insert into public.cms_singletons(key,status,data) values('site','draft','{"id":"virsapur-site","name":"Virsapur","defaultTourOrigin":"Lahore","tagline":"Pakistan’s heritage, made accessible.","purpose":"We aim to revive our diverse cultural heritage through spreading awareness and advocating for its preservation.","email":"virsapur@gmail.com","phone":"+92-315-4354899","address":null,"defaultSiteOrigin":"http://127.0.0.1:4173/production","defaultSeoImage":{"src":"assets/hero-badshahi.jpg","optimizedStem":"hero-badshahi","width":1918,"height":1080,"alt":"Badshahi Mosque and Lahore"},"navigation":[{"id":"home","label":"Home","route":"/","visible":true,"required":true},{"id":"map","label":"Explore","route":"/heritage-map","visible":true,"required":false},{"id":"programmes","label":"Experiences","route":"/programmes","visible":true,"required":false},{"id":"archives","label":"Stories","route":"/archives","visible":true,"required":false},{"id":"whats-on","label":"What’s On","route":"/whats-on","visible":true,"required":false},{"id":"work","label":"Our work","route":"/our-work","visible":true,"required":false},{"id":"about","label":"About","route":"/why-virsapur","visible":true,"required":false}],"footer":{"explore":["map","programmes","archives","work","about"],"connect":[{"label":"Contact","route":"/contact"}],"legal":[]},"social":[],"integrations":{"contact":{"connected":false,"endpoint":null,"method":"POST"},"newsletter":{"connected":false,"endpoint":null},"authentication":{"enabled":false}},"mission":"Bridge historical knowledge and public engagement through research, interpretation and shared experience.","vision":"A future in which Pakistan’s diverse heritage is visible, understood and carried forward with care.","productionDomain":"http://127.0.0.1:4173/production","commerce":{"enabled":false,"mode":"enquiry","currency":"PKR","amount":null,"label":""},"paymentMode":"disabled"}'::jsonb) on conflict(key) do nothing;
insert into public.cms_singletons(key,status,data) values('homepage','draft','{"id":"homepage","status":"published","seo":{"title":"Virsapur | Pakistan’s heritage, made accessible","description":"Discover Pakistan through Virsapur heritage experiences, the interactive Heritage Map, cultural stories and research-led programmes."},"modules":[{"id":"hero","type":"hero","enabled":true},{"id":"quick-discovery","type":"quickDiscovery","enabled":true},{"id":"map","type":"map","enabled":true},{"id":"current","type":"current","enabled":true},{"id":"experiences","type":"experiences","enabled":true},{"id":"stories","type":"stories","enabled":true},{"id":"projects","type":"projects","enabled":true},{"id":"themes","type":"themes","enabled":true},{"id":"mission","type":"mission","enabled":true},{"id":"about","type":"about","enabled":true},{"id":"collaborators","type":"collaborators","enabled":true},{"id":"final-action","type":"finalAction","enabled":true}],"hero":{"eyebrow":"Discover Pakistan through Virsapur","title":"Pakistan’s heritage, made accessible.","summary":"Explore remarkable places, experience living culture and connect with the stories that shape Pakistan.","image":{"src":"assets/hero-badshahi.jpg","optimizedStem":"hero-badshahi","width":1918,"height":1080,"alt":"Aerial view of Badshahi Mosque and Lahore","caption":"Badshahi Mosque · Lahore","credit":""},"actions":[{"label":"Explore Pakistan","route":"/heritage-map","style":"primary"},{"label":"Find an experience","route":"/programmes","style":"secondary"}]},"quickDiscovery":[{"id":"place","eyebrow":"Explore by place","title":"Heritage Map","route":"/heritage-map"},{"id":"experiences","eyebrow":"Experiences","title":"Tours & heritage walks","route":"/service/heritage-tours"},{"id":"learn","eyebrow":"Learn","title":"Workshops & programmes","route":"/service/cultural-and-educational-workshops"},{"id":"stories","eyebrow":"Stories","title":"Explore the Archives","route":"/archives"}],"map":{"eyebrow":"Explore by place","title":"Explore Pakistan","summary":"Discover heritage through its provinces, regions and districts.","cta":{"label":"Explore the full map","route":"/heritage-map"}},"current":{"eyebrow":"What’s happening","title":"See what’s happening with Virsapur.","featuredEventId":"","eventIds":[]},"experiences":{"eyebrow":"Ways to take part","title":"Experiences with Virsapur","summary":"Walk through history, learn with cultural practitioners and build thoughtful heritage work together.","featuredProgrammeId":"programme-heritage-tours","programmeIds":["programme-heritage-tours","programme-cultural-educational-workshops","programme-research-restoration","programme-cultural-events-collaborations"],"categoryLabels":{"programme-heritage-tours":"Experience","programme-cultural-educational-workshops":"Learn","programme-research-restoration":"Our work","programme-cultural-events-collaborations":"Events & collaboration"},"cta":{"label":"Explore all programmes","route":"/programmes"}},"stories":{"eyebrow":"Archives","title":"Stories from our land","summary":"Places, objects and cultural memory—researched and connected to the landscapes they come from.","featuredStoryId":"story-wells-mohenjodaro","storyIds":["story-wells-mohenjodaro","story-priest-king"],"cta":{"label":"Explore all stories","route":"/archives"}},"projects":{"eyebrow":"Research & preservation","title":"Our work","featuredProjectId":"project-walled-city-revitalization","projectIds":["project-walled-city-revitalization","project-heritage-documentation"],"cta":{"label":"Explore our work","route":"/programmes"}},"about":{"eyebrow":"About Virsapur","title":"Heritage is lived, shared and carried forward.","summary":"Virsapur connects research, education and cultural experience so more people can encounter Pakistan’s heritage—and help protect it.","images":[{"src":"assets/fresco_room.jpg","optimizedStem":"fresco-room","width":1153,"height":2048,"alt":"Painted architectural detail"},{"src":"assets/temple_distant.jpg","optimizedStem":"temple-distant","width":1153,"height":2048,"alt":"Historic temple architecture in the landscape"},{"src":"assets/archive-wells.jpg","optimizedStem":"archive-wells","width":640,"height":404,"alt":"Archaeological remains at Mohenjo-daro"}],"testimonialId":"testimonial-burnt-brains","cta":{"label":"Why Virsapur","route":"/why-virsapur"}},"finalAction":{"eyebrow":"Start your journey","title":"Explore with us.","summary":"Plan a heritage experience or begin a cultural collaboration with Virsapur.","image":{"src":"assets/temple_shadow.jpg","optimizedStem":"temple-shadow","width":1153,"height":2048,"alt":"Sunlight and shadow across historic stone architecture"},"actions":[{"label":"Find an experience","route":"/programmes","style":"primary"},{"label":"Work with Virsapur","route":"/contact","style":"secondary"}]},"mission":{"eyebrow":"Our purpose","title":"We aim to revive our diverse cultural heritage through spreading awareness and advocating for its preservation.","mission":"Bridge historical knowledge and public engagement through research, interpretation and shared experience.","vision":"A future in which Pakistan’s diverse heritage is visible, understood and carried forward with care."},"themes":{"eyebrow":"Explore by theme","title":"Follow the threads that connect people and place."}}'::jsonb) on conflict(key) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('archiveCategories','archive-category-archaeology-ancient-civilisations','archaeology-and-ancient-civilisations','published','{"id":"archive-category-archaeology-ancient-civilisations","slug":"archaeology-and-ancient-civilisations","status":"published","title":"Archaeology & Ancient Civilisations","shortTitle":"Archaeology","summary":"Material traces of early settlements, cities and the civilisations that shaped the region.","description":"Explore archaeological places, excavated structures and research-led stories that connect present-day Pakistan with its ancient civilisations.","featuredImage":{"src":"assets/temporary/temp-archive-archaeology.png","optimizedStem":"temp-archive-archaeology","width":1448,"height":1086,"alt":"Excavated ancient brick architecture and a historic well","focalX":63,"focalY":48},"sortOrder":1,"homepageOrder":2,"featured":true,"showOnHomepage":true,"seo":{"title":"Archaeology & Ancient Civilisations | Virsapur Archives","description":"Explore Virsapur stories about archaeology and ancient civilisations across Pakistan."}}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('archiveCategories','archive-category-architecture-built-heritage','architecture-and-built-heritage','published','{"id":"archive-category-architecture-built-heritage","slug":"architecture-and-built-heritage","status":"published","title":"Architecture & Built Heritage","shortTitle":"Architecture","summary":"Buildings, streets and designed places understood through detail, use and change.","description":"Discover architectural histories, urban fabric and the many ways Pakistan’s built heritage has been made, inhabited and adapted.","featuredImage":{"src":"assets/temporary/temp-archive-interior.png","optimizedStem":"temp-archive-interior","width":1122,"height":1402,"alt":"A painted historic interior with a carved timber doorway","focalX":58,"focalY":43},"sortOrder":2,"homepageOrder":1,"featured":true,"showOnHomepage":true,"seo":{"title":"Architecture & Built Heritage | Virsapur Archives","description":"Explore Virsapur stories about architecture, streets and built heritage across Pakistan."}}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('archiveCategories','archive-category-sacred-heritage','sacred-heritage','published','{"id":"archive-category-sacred-heritage","slug":"sacred-heritage","status":"published","title":"Sacred Heritage","shortTitle":"Sacred Heritage","summary":"Places of belief, memory and devotion across Pakistan’s many religious traditions.","description":"Encounter sacred buildings, landscapes and practices through careful stories grounded in place, memory and continuing meaning.","featuredImage":{"src":"assets/temporary/temp-project-preservation.png","optimizedStem":"temp-project-preservation","width":1448,"height":1086,"alt":"A restored historic civic building and shaded arcade","focalX":39,"focalY":48},"sortOrder":3,"homepageOrder":4,"featured":true,"showOnHomepage":true,"seo":{"title":"Sacred Heritage | Virsapur Archives","description":"Explore Virsapur stories about sacred places, traditions and cultural memory in Pakistan."}}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('archiveCategories','archive-category-living-traditions','living-traditions','published','{"id":"archive-category-living-traditions","slug":"living-traditions","status":"published","title":"Living Traditions","shortTitle":"Living Traditions","summary":"Skills, ceremonies and knowledge carried forward through practice and community.","description":"Explore living cultural practices through the people, materials and shared knowledge that keep traditions in motion.","featuredImage":{"src":"assets/temporary/temp-programme-workshops.png","optimizedStem":"temp-programme-workshops","width":1122,"height":1402,"alt":"Artisan hands painting a traditional geometric floral panel","focalX":51,"focalY":48},"sortOrder":4,"homepageOrder":3,"featured":true,"showOnHomepage":true,"seo":{"title":"Living Traditions | Virsapur Archives","description":"Explore Virsapur stories about living traditions, material practice and cultural knowledge."}}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('archiveCategories','archive-category-objects-material-culture','objects-and-material-culture','published','{"id":"archive-category-objects-material-culture","slug":"objects-and-material-culture","status":"published","title":"Objects & Material Culture","shortTitle":"Objects & Material Culture","summary":"Objects understood through their making, use, movement and cultural meaning.","description":"Read object biographies and material histories that connect collections, archaeological evidence and everyday cultural life.","featuredImage":{"src":"assets/temporary/temp-archive-object.png","optimizedStem":"temp-archive-object","width":1122,"height":1402,"alt":"A carved archaeological object under museum light","focalX":50,"focalY":48},"sortOrder":5,"homepageOrder":5,"featured":false,"showOnHomepage":false,"seo":{"title":"Objects & Material Culture | Virsapur Archives","description":"Explore Virsapur stories about objects, collections and material culture in Pakistan."}}'::jsonb) on conflict(collection,id) do nothing;
