insert into public.cms_records(collection,id,slug,status,data) values('programmes','programme-heritage-tours','heritage-tours','published','{"id":"programme-heritage-tours","tour":{"enabled":true,"startLocation":"","duration":"By itinerary","bookingMode":"quote"},"relatedHeritageIds":[],"type":"programme","slug":"heritage-tours","legacySlug":"heritageTours","status":"published","title":"Heritage Tours","summary":"Guided encounters with ancient landmarks, living neighbourhoods and the stories that shaped them.","body":"Heritage tours offer travelers a chance to explore ancient landmarks, vibrant cultures, and timeless traditions that reflect the rich history and identity of diverse civilizations. These journeys go beyond typical sightseeing, guiding visitors through historical monuments, traditional settings, museums and sacred sites that hold deep significance.","featured":true,"sortOrder":1,"featuredImage":{"src":"assets/archive-katas.jpg","optimizedStem":"archive-katas","width":640,"height":379,"alt":"Historic temple architecture at Katas Raj","caption":"","credit":""},"practical":{"audience":"","format":"","duration":"","location":"","availability":"","price":""},"cta":{"type":"enquiry","label":"Build a custom itinerary","target":"/tours/custom"},"relatedStoryIds":[],"seo":{"title":"Heritage Tours in Pakistan | Virsapur","description":"Explore Virsapur’s approach to guided heritage tours and enquire about a cultural experience.","image":"assets/archive-katas.jpg"},"kind":"experience","commerce":{"enabled":false,"mode":"enquiry","currency":"PKR","amount":null,"label":"Enquire about heritage tours"},"scheduleNotes":""}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('programmes','programme-cultural-educational-workshops','cultural-and-educational-workshops','published','{"id":"programme-cultural-educational-workshops","type":"programme","slug":"cultural-and-educational-workshops","legacySlug":"culturalAndEducationalWorkshops","status":"published","title":"Cultural & Educational Workshops","summary":"Immersive learning that connects history, material culture and community knowledge.","body":"Cultural and educational workshops combine learning with immersive experiences through hands-on activities, interactive discussion and practical exposure beyond conventional classroom learning.","featured":true,"sortOrder":2,"featuredImage":{"src":"assets/fresco_strip.jpg","optimizedStem":"fresco-strip","width":1035,"height":320,"alt":"Historic painted architectural detail","caption":"","credit":""},"practical":{"audience":"","format":"","duration":"","location":"","availability":"","price":""},"cta":{"type":"enquiry","label":"Discuss a workshop","target":"/contact?type=workshops"},"relatedStoryIds":[],"seo":{"title":"Cultural and Educational Workshops | Virsapur","description":"Explore Virsapur’s cultural and educational workshop approach and discuss a learning programme.","image":"assets/fresco_strip.jpg"},"kind":"workshop","commerce":{"enabled":false,"mode":"enquiry","currency":"PKR","amount":null,"label":"Discuss a workshop"},"scheduleNotes":""}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('programmes','programme-research-restoration','research-and-restoration-projects','published','{"id":"programme-research-restoration","type":"programme","slug":"research-and-restoration-projects","legacySlug":"researchAndRestorationProjects","status":"published","title":"Research & Restoration Projects","summary":"Research, documentation and interpretation supporting the preservation of cultural heritage.","body":"Research and restoration work supports the careful documentation, conservation and interpretation of cultural heritage through planned collaboration and specialist knowledge.","featured":true,"sortOrder":3,"featuredImage":{"src":"assets/archive-wells.jpg","optimizedStem":"archive-wells","width":640,"height":404,"alt":"Archaeological remains and historic wells at Mohenjo-daro","caption":"","credit":""},"practical":{"audience":"","format":"","duration":"","location":"","availability":"","price":""},"cta":{"type":"enquiry","label":"Discuss research or restoration","target":"/contact?type=research"},"relatedStoryIds":[],"seo":{"title":"Heritage Research and Restoration Projects | Virsapur","description":"Learn about Virsapur’s research, documentation and heritage-preservation approach.","image":"assets/archive-wells.jpg"},"kind":"project programme","commerce":{"enabled":false,"mode":"enquiry","currency":"PKR","amount":null,"label":"Discuss research or restoration"},"scheduleNotes":""}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('programmes','programme-cultural-events-collaborations','cultural-events-and-collaborations','published','{"id":"programme-cultural-events-collaborations","type":"programme","slug":"cultural-events-and-collaborations","legacySlug":"culturalEventsAndCollaborations","status":"published","title":"Cultural Events & Collaborations","summary":"Public programmes and partnerships that foster creativity, dialogue and cultural participation.","body":"Cultural events and collaborations create platforms where people can celebrate, share and learn from different traditions and artistic expressions through thoughtful partnerships.","featured":true,"sortOrder":4,"featuredImage":{"src":"assets/archive-gurdwara.jpg","optimizedStem":"archive-gurdwara","width":639,"height":426,"alt":"Historic gurdwara architecture in Punjab","caption":"","credit":""},"practical":{"audience":"","format":"","duration":"","location":"","availability":"","price":""},"cta":{"type":"enquiry","label":"Propose a collaboration","target":"/contact?type=collaboration"},"relatedStoryIds":[],"seo":{"title":"Cultural Events and Collaborations | Virsapur","description":"Explore Virsapur’s approach to cultural programming and institutional collaboration.","image":"assets/archive-gurdwara.jpg"},"kind":"experience","commerce":{"enabled":false,"mode":"enquiry","currency":"PKR","amount":null,"label":"Propose a collaboration"},"scheduleNotes":""}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('programmes','programme-lahore-gates-mosques','lahore-gates-mosques-and-city','review','{"id":"programme-lahore-gates-mosques","slug":"lahore-gates-mosques-and-city","title":"Lahore: Gates, Mosques & City","summary":"A proposed route through Delhi Gate, Shahi Hammam and Wazir Khan Mosque, connecting an urban threshold, a historic bathhouse and a living sacred landmark.","relatedHeritageIds":["major-doam-6449","major-doam-9778","major-doam-6466"],"body":"This curated planning route approaches Lahore through the relationship between streets and institutions. Delhi Gate introduces the historic city''s edge and the passage into its commercial fabric. The nearby Shahi Hammam provides a different setting for considering water, service and architectural conservation. Wazir Khan Mosque then brings the route into a major sacred and urban ensemble. These are three separate Heritage records, not interchangeable examples of a single monument type. The sequence is a starting point for discussion, not a confirmed guided departure. Virsapur will review current opening arrangements, worship requirements, walking conditions, group access and available interpretation before agreeing the final programme. Select the places below to examine their records, or start a custom itinerary and change the order to suit your group''s interests.","type":"programme","status":"review","featured":false,"kind":"curated tour proposal","sortOrder":20,"tour":{"enabled":true,"startLocation":"","duration":"Day itinerary proposal; timings confirmed with the quote","bookingMode":"quote"},"featuredImage":null,"practical":{"audience":"Small groups; requirements discussed individually","format":"Curated itinerary proposal","availability":"By enquiry. No scheduled departure is confirmed."},"cta":{"type":"enquiry","label":"Build a custom itinerary","target":"/tours/custom"},"relatedStoryIds":[],"seo":{"title":"Lahore: Gates, Mosques & City | Virsapur Tours","description":"A proposed route through Delhi Gate, Shahi Hammam and Wazir Khan Mosque, connecting an urban threshold, a historic bathhouse and a living sacred landmark.","primaryKeyword":"Lahore: Gates, Mosques & City","noindex":false},"commerce":{"enabled":false,"mode":"enquiry","currency":"PKR","amount":null,"label":"Request a custom quote"},"internalNotes":"New editorial route proposal for owner review, not a confirmed operational departure. Preserve review state until access, travel logistics and delivery are approved."}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('programmes','programme-rohtas-taxila-route','rohtas-and-taxila-heritage-route','review','{"id":"programme-rohtas-taxila-route","slug":"rohtas-and-taxila-heritage-route","title":"Rohtas & Taxila: Landscapes of Power and Learning","summary":"A multi-day planning route linking Rohtas Fort with Taxila’s archaeological landscape, starting from Lahore and shaped through a personal quote.","relatedHeritageIds":["unesco-586","unesco-139"],"body":"Rohtas Fort and Taxila support different ways of understanding the northern Punjab landscape. The fort invites close attention to walls, gateways and the organisation of a defensible place. Taxila is a serial archaeological property whose settlements and religious sites should be understood together, not reduced to a single map pin or monument. This route therefore treats Taxila as one canonical Heritage Place with multiple documented components. A proposed visit would identify which components suit the available time and access conditions; adding Taxila does not promise entry to every component. Travel begins from the configured Virsapur origin in Lahore. Transport, overnight arrangements, daily travel distances and site permissions must be assessed before the itinerary is agreed. The page does not advertise a fixed departure, package price or guaranteed opening hours. Use the Heritage records below as a research starting point, then request a custom quote for the places and pace your group prefers.","type":"programme","status":"review","featured":false,"kind":"curated tour proposal","sortOrder":21,"tour":{"enabled":true,"startLocation":"","duration":"Multi-day proposal; duration agreed after route review","bookingMode":"quote"},"featuredImage":{"mediaId":"release-rohtas","alt":"Rohtas Fort"},"practical":{"audience":"Small groups; requirements discussed individually","format":"Curated itinerary proposal","availability":"By enquiry. No scheduled departure is confirmed."},"cta":{"type":"enquiry","label":"Build a custom itinerary","target":"/tours/custom"},"relatedStoryIds":[],"seo":{"title":"Rohtas & Taxila: Landscapes of Power and Learning | Virsapur Tours","description":"A multi-day planning route linking Rohtas Fort with Taxila’s archaeological landscape, starting from Lahore and shaped through a personal quote.","primaryKeyword":"Rohtas & Taxila: Landscapes of Power and Learning","noindex":false},"commerce":{"enabled":false,"mode":"enquiry","currency":"PKR","amount":null,"label":"Request a custom quote"},"internalNotes":"New editorial route proposal for owner review, not a confirmed operational departure. Preserve review state until access, travel logistics and delivery are approved."}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('programmes','programme-indus-thatta-route','indus-cities-and-thatta-heritage-route','review','{"id":"programme-indus-thatta-route","slug":"indus-cities-and-thatta-heritage-route","title":"Indus Cities & Thatta: Archaeology, Memory and Craft","summary":"A proposed journey connecting Moenjodaro, Makli and Shah Jahan Mosque, with travel from Lahore and practical arrangements reviewed individually.","relatedHeritageIds":["unesco-138","unesco-143","major-doam-5625"],"body":"This planning route brings together an archaeological city, a major funerary landscape and a living mosque without presenting them as one continuous historical episode. Moenjodaro asks questions about urban organisation and the interpretation of excavated remains. Makli offers a different encounter with monuments, burial traditions and remembered political communities around Thatta. Shah Jahan Mosque introduces another architectural and devotional setting. Each Place has its own source record and designation; the mosque is not described here as an inscribed World Heritage property. The proposed sequence is an editorial framework for a conversation, not a bookable scheduled departure. Starting from Lahore, the final route depends on transport options, seasonal conditions, access permissions, group needs and the time available. No price is calculated on this page. A custom quote should identify the selected places and practical requirements so Virsapur can review feasibility before making any commitment. The related records below provide context while keeping the three places distinct.","type":"programme","status":"review","featured":false,"kind":"curated tour proposal","sortOrder":22,"tour":{"enabled":true,"startLocation":"","duration":"Multi-day proposal; duration and transport require review","bookingMode":"quote"},"featuredImage":null,"practical":{"audience":"Small groups; requirements discussed individually","format":"Curated itinerary proposal","availability":"By enquiry. No scheduled departure is confirmed."},"cta":{"type":"enquiry","label":"Build a custom itinerary","target":"/tours/custom"},"relatedStoryIds":[],"seo":{"title":"Indus Cities & Thatta: Archaeology, Memory and Craft | Virsapur Tours","description":"A proposed journey connecting Moenjodaro, Makli and Shah Jahan Mosque, with travel from Lahore and practical arrangements reviewed individually.","primaryKeyword":"Indus Cities & Thatta: Archaeology, Memory and Craft","noindex":false},"commerce":{"enabled":false,"mode":"enquiry","currency":"PKR","amount":null,"label":"Request a custom quote"},"internalNotes":"New editorial route proposal for owner review, not a confirmed operational departure. Preserve review state until access, travel logistics and delivery are approved."}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-wells-mohenjodaro','the-wells-of-mohenjodaro','review','{"id":"story-wells-mohenjodaro","type":"story","slug":"the-wells-of-mohenjodaro","status":"review","title":"The wells of Mohenjodaro","summary":"Brick-lined wells bring Mohenjodaro into focus as a city of repeated daily tasks, specialised construction and carefully arranged access to water.","category":"Archaeology","primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"location":"Mohenjo-daro · Sindh","province":"Sindh","district":"Larkana","author":"","publishedAt":"","updatedAt":"","body":[{"type":"paragraph","text":"A well is a modest-looking opening in the ground. At Mohenjodaro, it is also a way into the organisation of a city. The most revealing question is not simply how old a shaft is, but who could approach it, how water moved from it into neighbouring rooms, and what happened after that water had been used."},{"type":"paragraph","text":"Archaeologist Michael Jansen’s study of the city’s water system describes hundreds of wells alongside bathing facilities and drainage. His much-cited figure of more than 700 belongs to an archaeological account of urban provision, not a promise that a visitor can identify that many exposed shafts today. Estimates of an ancient system and the number of monuments visible on a walk are different kinds of information."},{"type":"heading","level":2,"text":"A circle made from bricks"},{"type":"paragraph","text":"Jonathan Mark Kenoyer’s photographic documentation draws attention to wedge-shaped bricks at a large well in the HR area. Their form allows a circular shaft to be assembled from small units. Some bricks also carry grooves associated with drawing ropes. These details shift attention from the well as a picturesque ruin to the practical work of building and using it."},{"type":"paragraph","text":"The same documentation distinguishes wells reached directly from a street from those within buildings. That distinction matters even without knowing the names or legal rights of their users. A doorway, passage or enclosing wall changes the route to water. An apparently simple circle therefore belongs to a larger architectural arrangement rather than standing alone as an isolated invention."},{"type":"heading","level":2,"text":"Supply is only half the story"},{"type":"paragraph","text":"Water brought into a house must also be handled after use. Jansen considers supply and disposal together, while a later engineering study by Nakamura and colleagues questions how the drainage evidence should be interpreted. Its abstract proposes that the drains primarily removed wastewater from paved rooms near wells. Calling every channel a sewer can conceal precisely this question about function."},{"type":"paragraph","text":"For a careful reading of the site, follow relationships rather than collecting superlatives: shaft to platform, platform to room, room to outlet, outlet to lane. Where a connection is not preserved, leave it as a question. A modern photograph can show a wall very clearly while revealing little about its relationship to a surface removed during excavation."},{"type":"paragraph","text":"The wells make Mohenjodaro compelling because they concern repeated actions: reaching, drawing, carrying, washing and maintaining. They suggest a city understood through use, not only through famous buildings. Their achievement is substantial without claiming that every resident enjoyed identical access, that every installation worked at once, or that an ancient system was equivalent to modern household plumbing."}],"references":[{"title":"Water Supply and Sewage Disposal at Mohenjo-Daro","url":"https://www.jstor.org/stable/124907","publisher":"Michael Jansen / World Archaeology","accessDate":"2026-10-22"},{"title":"Wells: archaeological captions","url":"https://www.harappa.com/category/slide-subject/wells?page=0","publisher":"Jonathan Mark Kenoyer / Harappa","accessDate":"2026-10-22"},{"title":"Reconsideration of water supply-drainage system","url":"https://www.jstage.jst.go.jp/article/journalhs1990/15/0/15_0_87/_article","publisher":"Nakamura and colleagues / Historical Studies in Civil Engineering","accessDate":"2026-10-22"}],"relatedProgrammeIds":[],"relatedProjectIds":[],"featured":false,"sortOrder":1,"featuredImage":null,"seo":{"title":"The wells of Mohenjodaro | Virsapur Archives","description":"Brick-lined wells bring Mohenjodaro into focus as a city of repeated daily tasks, specialised construction and carefully arranged access to water.","primaryKeyword":"The wells of Mohenjodaro","socialTitle":"The wells of Mohenjodaro","socialDescription":"Brick-lined wells bring Mohenjodaro into focus as a city of repeated daily tasks, specialised construction and carefully arranged access to water."},"relatedDistrictIds":["sindh-larkana"],"previousSlugs":[],"tags":["Archaeology","Sindh"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["unesco-138"],"relatedStoryIds":["story-mohenjodaro-lanes","story-mohenjodaro-architecture","story-priest-king","story-great-bath"],"contentType":"archaeology","imageStatus":"no-cleared-image","aiAssisted":true,"editorialReviewRequired":true,"internalNotes":"Jansen abstract supports scale, supply and drainage; Kenoyer captions support wedge bricks, rope grooves, access and well/platform associations. Nakamura abstract supports caution about wastewater function. No claim that every house had a well or that all drains carried sewage.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain the construction, distribution and archaeological evidence of wells, keeping estimates source-specific.","wordCount":412,"publicationHold":false}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-mohenjodaro-lanes','mohenjo-daro-residential-lanes','review','{"id":"story-mohenjodaro-lanes","type":"story","slug":"mohenjo-daro-residential-lanes","status":"review","title":"Mohenjo Daro Residential Lanes","summary":"Mohenjo Daro’s lanes reveal a city that was planned, used and altered. Thresholds and blocked drains tell a more intricate story than the familiar grid diagram.","category":"Urban history","primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage","archive-category-archaeology-ancient-civilisations"],"location":"Mohenjo-daro · Sindh","province":"Sindh","district":"Larkana","author":"","publishedAt":"","updatedAt":"","body":[{"type":"paragraph","text":"A city plan makes Mohenjo Daro look orderly from above. A lane introduces a different scale: a doorway only a few steps away, a wall that interrupts a view, a narrow passage between larger buildings. These spaces are not incidental gaps left over after monuments were built. They are the places where movement between buildings becomes visible in the archaeological record."},{"type":"paragraph","text":"Harappa’s documentation of the DK-G area describes streets and buildings aligned broadly north–south and east–west, but also notes adjustments as new construction appeared. In the photographed example, a corbelled covering over a drain was eventually obstructed as adjoining streets accumulated material. The grid was therefore not a timeless diagram. Its elements belonged to successive acts of construction, use and alteration."},{"type":"heading","level":2,"text":"Looking at the entrance"},{"type":"paragraph","text":"An educational reconstruction preserved in the Australian National University’s Basham Collection presents rooms around a courtyard and entrances facing a lane rather than the principal street. It is useful for imagining a relationship between outside movement and an interior household space. It is not a measured record of every house, and its sweeping description should not be mistaken for proof that all residents lived alike."},{"type":"paragraph","text":"Instead, treat the entrance as a question. Does it face a broad route or a smaller passage? Is the threshold at the same level as the surrounding surface? Can someone entering see directly into the next space? Such observations help explain how a building organised movement without requiring an invented account of the family who occupied it."},{"type":"heading","level":2,"text":"The missing vertical city"},{"type":"paragraph","text":"The low walls visible today can encourage an entirely horizontal reading. Documented stairways remind us that movement also ran upward. Kenoyer’s archaeological captions discuss access to upper courts or floors in particular buildings. That evidence adds height to the streetscape, but does not justify completing every missing roof or assigning each room a fixed purpose."},{"type":"paragraph","text":"The most useful mental reconstruction is consequently selective. Imagine an upward route where a stair supports it; recognise an entrance where an opening is documented; distinguish a surviving surface from a modern path. Leave the unsupported details unfilled rather than supplying a complete theatrical scene."},{"type":"paragraph","text":"Mohenjo Daro’s lanes offer an alternative to the image of a perfectly controlled ancient city. Their interest lies in the tension between a recognisable framework and local change. A blocked drain, a shifted wall or an altered approach can matter as much as a straight street. Read at walking pace, the city becomes a record of decisions made over time, not merely an early demonstration of the ruler and the right angle."}],"references":[{"title":"Mohenjo-daro: Narrow Streets and Lanes","url":"https://www.harappa.com/blog/mohenjo-daro-narrow-streets-and-lanes","publisher":"Harappa archaeological documentation","accessDate":"2026-10-22"},{"title":"Reconstruction of a house, Mohenjo-daro Museum","url":"https://openresearch-repository.anu.edu.au/entities/anuarchivesitem/18ecc16b-0291-4781-bdb0-75a30d71e9ed","publisher":"Australian National University Archives, Basham Collection","accessDate":"2026-10-22"},{"title":"Stairways of Mohenjo-daro II","url":"https://www.harappa.com/blog/stairways-mohenjo-daro-ii","publisher":"Harappa, archaeological captions and excavation-report discussion","accessDate":"2026-10-22"}],"relatedProgrammeIds":[],"relatedProjectIds":[],"featured":false,"sortOrder":2,"featuredImage":null,"seo":{"title":"Mohenjo Daro Residential Lanes | Virsapur Archives","description":"Mohenjo Daro’s lanes reveal a city that was planned, used and altered. Thresholds and blocked drains tell a more intricate story than the familiar grid diagram.","primaryKeyword":"Mohenjo Daro Residential Lanes","socialTitle":"Mohenjo Daro Residential Lanes","socialDescription":"Mohenjo Daro’s lanes reveal a city that was planned, used and altered. Thresholds and blocked drains tell a more intricate story than the familiar grid diagram."},"relatedDistrictIds":["sindh-larkana"],"previousSlugs":[],"tags":["Architecture","Sindh"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["unesco-138"],"relatedStoryIds":["story-wells-mohenjodaro","story-mohenjodaro-architecture","story-priest-king","story-great-bath"],"contentType":"architecture","imageStatus":"no-cleared-image","aiAssisted":true,"editorialReviewRequired":true,"internalNotes":"Lane alignment and blocked corbelled drain: Harappa lane caption. Courtyard/side entrance discussion: ANU historical reconstruction, explicitly qualified as interpretation. Stair evidence: Harappa stair captions. No household universality inferred from an educational model.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Read residential circulation, thresholds and street edges at human scale, distinct from the overall architecture overview.","wordCount":415,"publicationHold":false}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-mohenjodaro-architecture','mohenjo-daro-architecture','review','{"id":"story-mohenjodaro-architecture","type":"story","slug":"mohenjo-daro-architecture","status":"review","title":"Mohenjo Daro Architecture","summary":"Mohenjo Daro’s architecture is best read through materials, levels and connections—not through confident labels for buildings whose original names are unknown.","category":"Architecture","primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage","archive-category-archaeology-ancient-civilisations"],"location":"Mohenjo-daro · Sindh","province":"Sindh","district":"Larkana","author":"","publishedAt":"","updatedAt":"","body":[{"type":"paragraph","text":"The architecture of Mohenjo Daro is not confined to one monumental building. It lies in the repeated joining of wall, opening, platform, stair and drain. Looking at these relationships offers a more useful introduction than assigning every large room a grand title. A building can be carefully planned and socially important even when its original name and function are unknown."},{"type":"paragraph","text":"UNESCO identifies the site as a major surviving example of an early planned city, distinguished by brick construction and an extensive urban layout. This broad significance should not flatten the remains into a single moment. The visible city is an archaeological selection: excavated structures, surviving fragments and the interventions that allow them to remain exposed."},{"type":"heading","level":2,"text":"Reading height in low walls"},{"type":"paragraph","text":"Stairs are especially valuable because they point toward spaces that no longer survive in full. Harappa’s architectural documentation discusses upper courts and floors, while also showing how the interpretation of an impressive house can vary. A suggestion that a building was a palace or temple is not the same thing as an inscription identifying its occupants."},{"type":"paragraph","text":"Think of each stair as a surviving connection rather than a complete answer. It establishes movement between levels; it does not by itself recover the roofing system, the activity upstairs or the authority of the person who used it. This distinction keeps reconstruction anchored to the structure rather than to modern expectations about ancient power."},{"type":"heading","level":2,"text":"Buildings changed their surroundings"},{"type":"paragraph","text":"A digitised archaeological account held by IGNCA describes a building whose earlier entrance was blocked, another opened, and later work raised above older surfaces. Access to a well subsequently required descending from a higher lane. The example is a reminder that relative levels are historical evidence. What seems awkward in a ruin may record adaptation to an altered setting rather than poor original design."},{"type":"paragraph","text":"When looking at a plan, ask which elements actually belong together. A straight wall meeting another wall does not necessarily prove they were constructed simultaneously. An entrance can be cut after a room is built; a raised floor can change the experience of a doorway without moving its walls. Architecture includes such revisions, not just the first design."},{"type":"paragraph","text":"Mohenjo Daro rewards this patient attention. Its importance is not dependent on recognising a royal residence or imagining a single architect directing the entire city. Materials and connections show how built space was organised; alterations show that it continued to be negotiated. The ruins are most revealing when treated as evidence of construction and change, with uncertainty made visible rather than concealed behind familiar labels."}],"references":[{"title":"Archaeological Ruins at Moenjodaro","url":"https://whc.unesco.org/en/list/138/","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Stairways of Mohenjo-daro II","url":"https://www.harappa.com/blog/stairways-mohenjo-daro-ii","publisher":"Harappa archaeological documentation","accessDate":"2026-10-22"},{"title":"Mohenjo-Daro, architectural discussion","url":"https://ignca.gov.in/Asi_data/14733.pdf","publisher":"Indira Gandhi National Centre for the Arts, digitised archaeological publication","accessDate":"2026-10-22"}],"relatedProgrammeIds":[],"relatedProjectIds":[],"featured":false,"sortOrder":3,"featuredImage":null,"seo":{"title":"Mohenjo Daro Architecture | Virsapur Archives","description":"Mohenjo Daro’s architecture is best read through materials, levels and connections—not through confident labels for buildings whose original names are unknown.","primaryKeyword":"Mohenjo Daro Architecture","socialTitle":"Mohenjo Daro Architecture","socialDescription":"Mohenjo Daro’s architecture is best read through materials, levels and connections—not through confident labels for buildings whose original names are unknown."},"relatedDistrictIds":["sindh-larkana"],"previousSlugs":[],"tags":["Architecture","Sindh"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["unesco-138"],"relatedStoryIds":["story-wells-mohenjodaro","story-mohenjodaro-lanes","story-priest-king","story-great-bath"],"contentType":"architecture","imageStatus":"no-cleared-image","aiAssisted":true,"editorialReviewRequired":true,"internalNotes":"UNESCO source checked with supplementary close-read before compilation; keep UNESCO-derived account under 200 words across this set. IGNCA indexed passage supports changed entrances, raised surfaces and wells below later levels. Stair source reused sparingly, factual attribution about building A1 remains qualified.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Introduce building materials, spatial organisation and evidential limits across the city, not a repeated lane or bath profile.","wordCount":413,"publicationHold":false}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-priest-king','priest-king','review','{"id":"story-priest-king","type":"story","slug":"priest-king","status":"review","title":"Priest-King","summary":"The small steatite figure known as the Priest-King is an extraordinary sculpture, but its familiar name remains an interpretation rather than an identified office.","category":"Object story","primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture","archive-category-archaeology-ancient-civilisations"],"location":"Mohenjo-daro · Sindh","province":"Sindh","district":"Larkana","author":"","publishedAt":"","updatedAt":"","body":[{"type":"paragraph","text":"The name seems to settle the matter before we have looked: Priest-King. It suggests a ruler whose political and religious authority were combined. Yet the sculpture from Mohenjo Daro does not come with a surviving inscription identifying its subject in those terms. The familiar label is part of its later interpretation, not a recovered personal name or a securely established title."},{"type":"paragraph","text":"Jonathan Mark Kenoyer’s object record identifies a small figure made from low-fired white steatite, measuring about 17.5 centimetres high. A decorated garment crosses the left shoulder; a headband and carefully treated beard give the face an immediately recognisable character. The record associates it with the National Museum in Karachi, whose own institutional description includes the sculpture among its Indus collections."},{"type":"heading","level":2,"text":"A close view changes the scale"},{"type":"paragraph","text":"The object’s fame can make it seem monumental. Its actual dimensions invite a different kind of attention. Small carved details carry much of the visual effect: the treatment of the eyes, the repeated motifs on the garment, the relationship between exposed skin and patterned cloth. These are observations about an object, not evidence that a particular institution of kingship existed."},{"type":"paragraph","text":"Kenoyer notes traces and features that suggest additional colour or attached elements, while carefully qualifying what may once have been present. A damaged or incomplete sculpture asks us to separate what survives from what is reconstructed. An imagined headdress or lost lower body can dramatically alter how the figure is understood, which is precisely why such additions should remain explicit hypotheses."},{"type":"heading","level":2,"text":"What a face cannot tell us"},{"type":"paragraph","text":"A scholarly study preserved by IGNCA cautions that the iconographic form alone cannot establish whether such figures represent priests, rulers or deities. That does not make interpretation pointless. It changes the task from naming a person with certainty to examining what the figure permits us to ask about representation, dress and social distinction."},{"type":"paragraph","text":"Nor should a single sculpture be asked to stand for every inhabitant of a large and varied urban world. Its survival, excavation and repeated reproduction have made it unusually visible. That visibility is not a measurement of how often similar objects were encountered in daily life, or of how people across the Indus region understood them."},{"type":"paragraph","text":"The Priest-King is therefore most interesting when its two histories remain in view: an ancient crafted object whose original significance is only partly recoverable, and a modern emblem repeatedly used to picture an entire civilisation. Looking beyond the nickname does not diminish its presence. It gives the sculpture room to be more than an answer to a question the evidence has not yet resolved."}],"references":[{"title":"“Priest King” side view","url":"https://www.harappa.com/slide/priest-king-side-view","publisher":"Jonathan Mark Kenoyer / Harappa","accessDate":"2026-10-22"},{"title":"National Museum of Pakistan, Karachi","url":"https://doam.gov.pk/public/heritage-sites/792","publisher":"Department of Archaeology & Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Study of Indus stone sculpture, digitised publication","url":"https://ignca.gov.in/Asi_data/74331.pdf","publisher":"Indira Gandhi National Centre for the Arts","accessDate":"2026-10-22"}],"relatedProgrammeIds":[],"relatedProjectIds":[],"featured":false,"sortOrder":4,"featuredImage":null,"seo":{"title":"Priest-King | Virsapur Archives","description":"The small steatite figure known as the Priest-King is an extraordinary sculpture, but its familiar name remains an interpretation rather than an identified office.","primaryKeyword":"Priest-King","socialTitle":"Priest-King","socialDescription":"The small steatite figure known as the Priest-King is an extraordinary sculpture, but its familiar name remains an interpretation rather than an identified office."},"relatedDistrictIds":["sindh-larkana"],"previousSlugs":[],"tags":["Sindh","Material Culture"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["unesco-138"],"relatedStoryIds":["story-wells-mohenjodaro","story-mohenjodaro-lanes","story-mohenjodaro-architecture","story-great-bath"],"contentType":"objects-material","imageStatus":"no-cleared-image","aiAssisted":true,"editorialReviewRequired":true,"internalNotes":"Kenoyer object record supports steatite, dimensions, decoration, inventory and uncertainties about inlay. DOAM supports collection association. IGNCA publication explicitly rejects deducing priest/ruler/god from iconography alone. No claim about current display or diplomatic transfer.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain the excavated sculpture and the speculative nature of its familiar name; require an identified collection record.","wordCount":415,"publicationHold":false}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-tomb-anarkali','tomb-of-anarkali','review','{"id":"story-tomb-anarkali","type":"story","slug":"tomb-of-anarkali","status":"review","title":"Tomb of Anarkali","summary":"Lahore’s Anarkali tomb holds more than a celebrated romance: its architecture and successive uses reveal the making, adaptation and preservation of public memory.","category":"Built heritage","primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"location":"Lahore · Punjab","province":"Punjab","district":"Lahore","author":"","publishedAt":"","updatedAt":"","body":[{"type":"paragraph","text":"Anarkali’s name carries a story that can overwhelm the building associated with it. The Lahore tomb is often introduced through the romance of Prince Salim and a woman said to have suffered for their attachment. For an architectural visit, it is more useful to begin with a distinction: the monument is tangible evidence; the celebrated personal narrative requires its own historical proof."},{"type":"paragraph","text":"The federal archaeological catalogue describes an octagonal building with unequal alternating sides and a central dome raised on a cylindrical neck. It also records a marble cenotaph decorated with floral work and calligraphy. These details give us something concrete to examine without assuming that every element of the popular story has been established."},{"type":"heading","level":2,"text":"A building with successive lives"},{"type":"paragraph","text":"The account published by the Punjab Walled Cities & Heritage Areas Authority follows a later history that is easier to connect to institutional change. After the annexation of Punjab, the building accommodated administrative staff. It was converted into a church in 1851 and continued in that role until 1886, before becoming a record office in 1891."},{"type":"paragraph","text":"Each change asks a practical question. How did a funerary space become a place for a congregation? How were circulation, seating and storage accommodated within an inherited form? The authority’s account mentions additions associated with the church, demonstrating that reuse was not simply a matter of changing a sign at the entrance."},{"type":"heading","level":2,"text":"A monument that kept documents"},{"type":"paragraph","text":"The historical description of Punjab Archives published by Sindh Archives identifies the tomb with the Historical Record Office. It discusses Persian and English records, including administrative material connected with the Lahore Darbar and the subsequent colonial administration. This is a history of the repository, not a current promise about which documents can be consulted inside the monument today."},{"type":"paragraph","text":"The association is nevertheless striking. A building remembered through an elusive personal story became a setting for documentary evidence about government and society. These two forms of memory do not cancel one another. They show how a monument can acquire meanings that its original builders could not have anticipated."},{"type":"paragraph","text":"The heritage authority also reports a 2024 handover and investigation of painted decoration concealed beneath later finishes. That work illustrates the delicate problem of deciding what to reveal and what to retain. Removing a later layer may disclose earlier fabric while also changing evidence of subsequent use."},{"type":"paragraph","text":"Anarkali’s tomb deserves attention beyond a choice between believing or rejecting a romance. Its plan, cenotaph, adaptations and institutional associations provide a substantial history in their own right. Keeping the legend distinct from that evidence allows both the building and the questions surrounding its name to remain visible."}],"references":[{"title":"Tomb of Anarkali","url":"https://doam.gov.pk/public/sites/6469","publisher":"Department of Archaeology & Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Tomb of Anarkali","url":"https://walledcitylahore.gop.pk/tomb-of-anarkali/","publisher":"Punjab Walled Cities & Heritage Areas Authority","accessDate":"2026-10-22"},{"title":"Punjab Archive","url":"https://archives.sindhculture.gov.pk/punjab_archive/","publisher":"Sindh Archives institutional directory","accessDate":"2026-10-22"}],"relatedProgrammeIds":[],"relatedProjectIds":[],"featured":false,"sortOrder":5,"featuredImage":null,"seo":{"title":"Tomb of Anarkali | Virsapur Archives","description":"Lahore’s Anarkali tomb holds more than a celebrated romance: its architecture and successive uses reveal the making, adaptation and preservation of public memory.","primaryKeyword":"Tomb of Anarkali","socialTitle":"Tomb of Anarkali","socialDescription":"Lahore’s Anarkali tomb holds more than a celebrated romance: its architecture and successive uses reveal the making, adaptation and preservation of public memory."},"relatedDistrictIds":[],"previousSlugs":[],"tags":["Punjab","Architecture"],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"heritage-place","imageStatus":"no-cleared-image","aiAssisted":true,"editorialReviewRequired":true,"internalNotes":"DOAM architectural details only; its romantic biography and erroneous coordinate not adopted. PWCA supports church1851–1886, record office1891 and2024 conservation handover. Sindh Archives supports historical repository uses; not asserted current holdings/access.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Separate the documented building, later archive use and contested personal attribution; do not repeat the source’s disputed coordinate.","wordCount":425,"publicationHold":false}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-gurdwara-lahura','gurdwara-lahura-sahib','review','{"id":"story-gurdwara-lahura","type":"story","slug":"gurdwara-lahura-sahib","status":"review","title":"Gurdwara Lahura Sahib","summary":"This retained Virsapur story is awaiting reliable identification of Lahura Sahib and must not be published as a verified monument history.","category":"Sacred heritage","primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage","archive-category-architecture-built-heritage"],"location":"Punjab","province":"Punjab","district":"","author":"","publishedAt":"","updatedAt":"","body":[{"type":"paragraph","text":"This story is retained in the review collection because it belongs to Virsapur’s existing archive. Its subject has not yet been identified to the standard required for a factual public article."},{"type":"paragraph","text":"Searches for Lahura Sahib and related spellings produced public references to a gurdwara near Lahore, but the research did not establish a matching institutional site record or an authenticated historical account. Those leads are not sufficient to assign a foundation date, a precise location, a present custodian or a particular episode in the life of Guru Nanak."},{"type":"paragraph","text":"Before publication, an editor should match the name to a documented building and obtain an authoritative local or community source. Any account of a sacred association should distinguish the tradition as remembered by devotees from independently dated architectural evidence. Current access also needs direct confirmation rather than an assumption drawn from older images."},{"type":"paragraph","text":"No replacement history has been invented to fill this gap. The existing story identity remains available for completion once that evidence is secured."}],"references":[{"title":"Shrines Branch","url":"https://etpb.gov.pk/shrines/shrines-branch/","publisher":"Evacuee Trust Property Board","accessDate":"2026-10-22"}],"relatedProgrammeIds":[],"relatedProjectIds":[],"featured":false,"sortOrder":6,"featuredImage":null,"seo":{"title":"Gurdwara Lahura Sahib | Virsapur Archives","description":"This retained Virsapur story is awaiting reliable identification of Lahura Sahib and must not be published as a verified monument history.","primaryKeyword":"Gurdwara Lahura Sahib","socialTitle":"Gurdwara Lahura Sahib","socialDescription":"This retained Virsapur story is awaiting reliable identification of Lahura Sahib and must not be published as a verified monument history."},"relatedDistrictIds":[],"previousSlugs":[],"tags":["Punjab","Architecture"],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"heritage-place","imageStatus":"no-cleared-image","aiAssisted":true,"editorialReviewRequired":true,"internalNotes":"Exact-name searches returned public video/social references to Ghawindi/Ghavindi near Lahore, but no matched institutional record or authenticated historical text. No founding date, ownership, coordinates or Guru Nanak visit asserted. Parent explicitly authorised retaining unresolved flag.\nHOLD — Identity unresolved. An internal hold is deliberately shorter than an article; do not count this record as a completed publication-ready article.","editorialReason":"Retain the existing story identity while first establishing the precise gurdwara name, location and institutional record.","wordCount":164,"publicationHold":true}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-shaheed-ganj','gurudwara-shaheed-ganj-singh-singhnian','review','{"id":"story-shaheed-ganj","type":"story","slug":"gurudwara-shaheed-ganj-singh-singhnian","status":"review","title":"Gurudwara Shaheed Ganj Singh Singhnian","summary":"Shaheed Ganj Singh Singhnian is a place of Sikh remembrance whose name, neighbouring shrines and custodial history should be understood without collapsing them into one story.","category":"Sacred heritage","primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage","archive-category-architecture-built-heritage"],"location":"Lahore · Punjab","province":"Punjab","district":"Lahore","author":"","publishedAt":"","updatedAt":"","body":[{"type":"paragraph","text":"The name Shaheed Ganj carries the weight of remembrance. At Gurdwara Shaheed Ganj Singh Singhnian in Lahore, that remembrance includes Sikh men, women and children who suffered persecution. The place should be approached as a community’s sacred memorial, not reduced to an arresting tale of violence or treated as interchangeable with every nearby site bearing a similar name."},{"type":"paragraph","text":"The Shiromani Gurdwara Parbandhak Committee’s account places this shrine opposite Shahid Ganj Bhai Taru Singh. It gives particular importance to the memory of women, reflected in the name Singhnian. This distinction is essential: proximity and shared commemorative language do not make separate shrines the same building, nor allow the history of one to be transferred automatically to another."},{"type":"heading","level":2,"text":"Remembering without inflating"},{"type":"paragraph","text":"Accounts of suffering at Shahid Ganj often include very large numerical claims. The sources consulted do not establish a reliable basis for repeating a precise total here. A memorial’s importance does not depend on selecting the largest circulating figure. The significance of the remembered lives, and of the community that continues to honour them, remains without an unsupported calculation."},{"type":"paragraph","text":"This also requires care with chronology. A community account can be a primary source for the way a place is remembered while still containing dates that need independent checking. Reading it respectfully does not require treating every sentence as a settled historical finding."},{"type":"heading","level":2,"text":"Custodianship is part of the history"},{"type":"paragraph","text":"Historian Sana Haroon’s research on Shahidganj examines administration and control between 1850 and 1936. Her published abstract describes evidence concerning land, custodians and competing uses of the site. That approach moves beyond a story of two unchanging religious communities: access and management were also shaped by particular people, institutions and administrative arrangements."},{"type":"paragraph","text":"The government’s 2017–2018 yearbook lists Gurdwara Shaheed Ganj Singh Singhnian among functional shrines in Lahore under ETPB management. It is useful evidence for that reporting period, not a substitute for checking today’s arrangements. Nor does a management listing convey the full meaning of the place to worshippers."},{"type":"paragraph","text":"For a visitor or reader, the starting point is therefore accurate identification. Keep this shrine distinct from Bhai Taru Singh’s memorial and distinguish devotional memory, architectural history and custodial records. Each contributes something different. Together they offer a more substantial understanding than a sensational summary: a place where remembrance has been maintained, interpreted and administered across profound changes in Lahore’s religious and political landscape."}],"references":[{"title":"Gurdwara Shahid Ganj Singhnian Lahore","url":"https://sgpc.net/gurdwara-shahid-ganj-singhnian-lahore/","publisher":"Shiromani Gurdwara Parbandhak Committee","accessDate":"2026-10-22"},{"title":"Year Book 2017–2018, page 33","url":"https://www.mora.gov.pk/SiteImage/Publication/YearBook2017-18.pdf","publisher":"Ministry of Religious Affairs and Interfaith Harmony, Pakistan","accessDate":"2026-10-22"},{"title":"Custodianship of Shahidganj in colonial Lahore, abstract","url":"https://journals.sagepub.com/doi/10.1177/0019464617695678","publisher":"Sana Haroon / The Indian Economic and Social History Review","accessDate":"2026-10-22"}],"relatedProgrammeIds":[],"relatedProjectIds":[],"featured":false,"sortOrder":7,"featuredImage":null,"seo":{"title":"Gurudwara Shaheed Ganj Singh Singhnian | Virsapur Archives","description":"Shaheed Ganj Singh Singhnian is a place of Sikh remembrance whose name, neighbouring shrines and custodial history should be understood without collapsing them into one story.","primaryKeyword":"Gurudwara Shaheed Ganj Singh Singhnian","socialTitle":"Gurudwara Shaheed Ganj Singh Singhnian","socialDescription":"Shaheed Ganj Singh Singhnian is a place of Sikh remembrance whose name, neighbouring shrines and custodial history should be understood without collapsing them into one story."},"relatedDistrictIds":[],"previousSlugs":[],"tags":["Punjab","Architecture"],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"heritage-place","imageStatus":"no-cleared-image","aiAssisted":true,"editorialReviewRequired":true,"internalNotes":"SGPC supports distinct shrine opposite Bhai Taru Singh, Sikh commemorative framing, women’s memory and1934management claim. Implausible1764MirMannu date and numerical casualty claims excluded. Government2017–18registry supports historical functional listing, not2026access. Haroon abstract read; article beyond abstract not claimed accessed.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Use the official registry to identify the gurdwara, then source its built history without sensational or unverified casualty claims.","wordCount":381,"publicationHold":false}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-katas-raj','katas-raj','review','{"id":"story-katas-raj","type":"story","slug":"katas-raj","status":"review","title":"Katas Raj","summary":"Katas Raj is an ensemble organised around sacred water, with temples and other structures that belong to different histories—not a single building with one date.","category":"Sacred heritage","primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage","archive-category-cultural-landscapes-historic-places"],"location":"Chakwal · Punjab","province":"Punjab","district":"Chakwal","author":"","publishedAt":"","updatedAt":"","body":[{"type":"paragraph","text":"Katas Raj is easiest to misread when it is treated as the name of one temple. The complex in Chakwal brings together sacred water, several temples and other historic structures. Its significance comes partly from that grouping: different buildings and memories meet around a place that remains important to Hindu devotees."},{"type":"paragraph","text":"The federal archaeological catalogue identifies temples, a holy pool, stupa remains, havelis and memorial structures within the ensemble. Punjab’s tourism documentation likewise describes a complex rather than a solitary monument. These sources make a useful first distinction, even where their compressed chronologies require more careful checking: the things visible together today were not necessarily built together."},{"type":"heading","level":2,"text":"The water at the centre"},{"type":"paragraph","text":"The pool is associated in Hindu tradition with Shiva’s grief and tears. This is a sacred account of the landscape, not a geological explanation or a construction inscription. Describing it as a tradition allows its religious meaning to be recognised without confusing different kinds of evidence."},{"type":"paragraph","text":"The relationship between pool and buildings also changes how the site is experienced. A distant photograph can turn the water into a reflective foreground. For worshippers, it belongs to a place of devotion. Reading Katas Raj only as a pleasing arrangement of stone and water misses that difference in purpose."},{"type":"heading","level":2,"text":"An ensemble with internal distinctions"},{"type":"paragraph","text":"The Satgraha group deserves its own close architectural attention; it is not a convenient label for everything at Katas. Likewise, a haveli should not be assigned the same function or date as a temple merely because both appear in one view. Names, plans and documented relationships help keep the complex intelligible."},{"type":"paragraph","text":"Rather than trying to memorise a single foundation story, begin by noticing changes in scale and form. Which structures stand on raised platforms? How do passages connect them? Where does an individual building address the pool, and where does it turn toward another part of the settlement? These are questions for observation, not instructions to enter restricted spaces."},{"type":"paragraph","text":"Katas Raj is also more than an abandoned archaeological setting. ETPB lists it among functional mandirs, and a Pakistan High Commission announcement documents visas issued for a pilgrimage scheduled in February and March 2025. That dated event demonstrates continuing devotional connection; it does not establish the current calendar or unrestricted daily access."},{"type":"paragraph","text":"The most generous account of Katas Raj keeps these dimensions together without merging them. Its architecture invites close looking, its traditions require respectful attribution, and its living religious use calls for consideration of the people for whom it is sacred. The ensemble becomes clearer when each part is allowed its own history."}],"references":[{"title":"Katas Raj Temples","url":"https://doam.gov.pk/public/sites/6750","publisher":"Department of Archaeology & Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Katas Raj Temple Complex brochure","url":"https://webapi.tdcp.gop.pk/uploads/1769508488275-547027222.pdf","publisher":"Tourism Development Corporation of Punjab","accessDate":"2026-10-22"},{"title":"Functional mandirs","url":"https://etpb.gov.pk/shrines/mandirs/functional/","publisher":"Evacuee Trust Property Board","accessDate":"2026-10-22"},{"title":"Pilgrimage visas for Katas Raj, 21 February 2025","url":"https://pakhcnewdelhi.org.pk/pakistan-issues-visas-to-indian-pilgrims-for-visit-to-katas-raj-chakwal-2/","publisher":"Pakistan High Commission, New Delhi","accessDate":"2026-10-22"}],"relatedProgrammeIds":[],"relatedProjectIds":[],"featured":false,"sortOrder":8,"featuredImage":null,"seo":{"title":"Katas Raj | Virsapur Archives","description":"Katas Raj is an ensemble organised around sacred water, with temples and other structures that belong to different histories—not a single building with one date.","primaryKeyword":"Katas Raj","socialTitle":"Katas Raj","socialDescription":"Katas Raj is an ensemble organised around sacred water, with temples and other structures that belong to different histories—not a single building with one date."},"relatedDistrictIds":["punjab-chakwal"],"previousSlugs":[],"tags":["Punjab","Architecture"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6750"],"relatedStoryIds":["story-satgraha-temples","story-havan-kund","story-reading-a-shikhara-without-guessing-a-date","story-sacred-water-at-katas-traditions-and-material-settings"],"contentType":"heritage-place","imageStatus":"no-cleared-image","aiAssisted":true,"editorialReviewRequired":true,"internalNotes":"DOAM ensemble and mythology attribution <120words here; datescontradictory so omitted. TDCPensembleorientation only <80words; remaining architectureallocation nextarticle. ETPBfunctional list anddated2025pilgrimageprimaryrelease used, nofuturecalendarinference.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Orient readers to the ensemble, its setting and multiple periods, distinct from the Satgraha architectural close reading.","wordCount":416,"publicationHold":false}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-satgraha-temples','satgraha-temples','review','{"id":"story-satgraha-temples","type":"story","slug":"satgraha-temples","status":"review","title":"Satgraha Temples","summary":"The Satgraha temples invite a close architectural reading within Katas Raj, from platforms and carved openings to the caution needed when dating a building by its style.","category":"Architecture","primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage","archive-category-sacred-heritage"],"location":"Katas Raj · Punjab","province":"Punjab","district":"Chakwal","author":"","publishedAt":"","updatedAt":"","body":[{"type":"paragraph","text":"Within the larger Katas Raj ensemble, the Satgraha temples reward a slower kind of looking. The name is associated with a group of seven temples, but counting alone explains little about their architecture. A platform, a doorway and the way a roofline rises above a wall offer a more useful route into the buildings than a list of names."},{"type":"paragraph","text":"Punjab’s official tourism brochure describes features including fluted pillars, trefoil arches, dentils and pointed rooflines. These terms identify things to look for. Fluting gives a shaft repeated vertical grooves; a trefoil opening has a three-lobed outline; dentils form a small, tooth-like sequence beneath a projecting edge. Recognising the terms helps a visitor move from a general impression of ornament to specific architectural observation."},{"type":"heading","level":2,"text":"Looking from the base upward"},{"type":"paragraph","text":"The brochure describes temples raised on square platforms and elevations articulated by successive horizontal elements. A platform establishes a boundary and a level before a visitor reaches the shrine itself. Above it, projecting bands and shaped openings organise the face of the building. The effect comes from their relationship, not from ornament considered as an independent surface pattern."},{"type":"paragraph","text":"The federal archaeological catalogue associates the Satgarha group with an early medieval date and describes its architecture as Kashmiri in character. Such a label is a comparison of architectural features. It does not, by itself, identify the birthplace of a craftsperson, establish a direct journey of builders or recover a precise year of construction."},{"type":"heading","level":2,"text":"Style is evidence, but not a date stamp"},{"type":"paragraph","text":"Architectural historian Michael Meister’s study of Salt Range temples places the region within a broader history of temple forms. His discussion also makes clear that proposed sequences based on style need archaeological support. A resemblance can be significant while still leaving several explanations open: shared conventions, adaptation, exchange or later alteration."},{"type":"paragraph","text":"This is particularly important at Katas Raj, where different components appear together in a compact landscape. A date assigned to one group should not spread automatically across the whole complex. Equally, a restored edge should not be used uncritically to reconstruct an original silhouette. Photographs, plans and conservation records need to be compared rather than treated as interchangeable evidence."},{"type":"paragraph","text":"The Satgraha temples can therefore be read both closely and cautiously. Look at how a shaped opening sits within its wall, how a supporting element meets a projection, and how one building relates to the next. Their architectural interest does not require an entirely resolved chronology. It lies in the specificity of the surviving forms and in the historical questions those forms continue to make possible."}],"references":[{"title":"Katas Raj Temple Complex brochure","url":"https://webapi.tdcp.gop.pk/uploads/1769508488275-547027222.pdf","publisher":"Tourism Development Corporation of Punjab","accessDate":"2026-10-22"},{"title":"Katas Raj Temples","url":"https://doam.gov.pk/public/sites/6750","publisher":"Department of Archaeology & Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Temples Along the Indus","url":"https://www.penn.museum/sites/expedition/temples-along-the-indus/","publisher":"Michael W. Meister / Penn Museum Expedition, 1996","accessDate":"2026-10-22"}],"relatedProgrammeIds":[],"relatedProjectIds":[],"featured":false,"sortOrder":9,"featuredImage":null,"seo":{"title":"Satgraha Temples | Virsapur Archives","description":"The Satgraha temples invite a close architectural reading within Katas Raj, from platforms and carved openings to the caution needed when dating a building by its style.","primaryKeyword":"Satgraha Temples","socialTitle":"Satgraha Temples","socialDescription":"The Satgraha temples invite a close architectural reading within Katas Raj, from platforms and carved openings to the caution needed when dating a building by its style."},"relatedDistrictIds":["punjab-chakwal"],"previousSlugs":[],"tags":["Punjab","Architecture"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6750"],"relatedStoryIds":["story-katas-raj","story-havan-kund","story-reading-a-shikhara-without-guessing-a-date","story-sacred-water-at-katas-traditions-and-material-settings"],"contentType":"heritage-place","imageStatus":"no-cleared-image","aiAssisted":true,"editorialReviewRequired":true,"internalNotes":"TDCParchitecturalvocabulary <180words acrossarticles7&8; DOAMfeatures/dating <190across7&8; Meisterregionalcomparisonanddatingcaution <140 here leave~60forlaterarticles. Do not present Kashmiri-style label as origin-proof, noinventedconstructionphase.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Read a component grouping within Katas Raj without inventing a separate Place or presenting uncertain chronology as settled.","wordCount":410,"publicationHold":false}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-havan-kund','havan-kund','review','{"id":"story-havan-kund","type":"story","slug":"havan-kund","status":"review","title":"Havan Kund","summary":"Havan Kund names a ritual feature, not simply an architectural shape. At Katas Raj, interpreting it requires attention to both documented fabric and living practice.","category":"Living traditions","primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions","archive-category-sacred-heritage"],"location":"Katas Raj · Punjab","province":"Punjab","district":"Chakwal","author":"","publishedAt":"","updatedAt":"","body":[{"type":"paragraph","text":"The phrase havan kund directs attention to a setting for ritual fire. It is not simply another name for any small basin or sunken architectural feature. At Katas Raj, a study held in the National University of Modern Languages repository identifies the baradari with this name. That association gives a starting point for interpretation, but it does not supply a complete account of every ceremony performed there."},{"type":"paragraph","text":"The distinction matters because photographs tend to privilege what remains still: an edge, a platform, an opening or a pavilion. A ritual also involves actions, participants, words and occasions. Those elements cannot all be reconstructed from the shape of a structure, however clearly it has been photographed."},{"type":"heading","level":2,"text":"More than a container"},{"type":"paragraph","text":"Institutional documentation of Hindu temple ritual, such as IGNCA’s study of the Brihadishvara Temple, distinguishes the kindling of fire, recitation and other ceremonial activities. It is evidence of the complexity of a documented ritual setting, not a script that can be imported wholesale into Katas Raj. Practices have particular communities and contexts; similarity of terminology does not make them identical."},{"type":"paragraph","text":"For that reason, describing the Havan Kund should begin with the local name and the source that records it. Questions about who officiated, what was offered, how often a ceremony occurred and how participants understood it need testimony or documentation specific to the place. A confident universal explanation can erase precisely the local detail that makes heritage meaningful."},{"type":"heading","level":2,"text":"Architecture and practice together"},{"type":"paragraph","text":"The baradari association also invites an architectural question. How does a covered or partly open setting accommodate people gathering around a focal activity? A plan can help establish the arrangement, while a dated account can explain how it was used. Neither should be made to do the work of the other. An architectural name does not date a ritual; a remembered ceremony does not prove that every visible element is original."},{"type":"paragraph","text":"ETPB’s listing of Katas Raj among functional mandirs is a further reason not to treat the complex purely as an archaeological stage. Living devotional use deserves respect even where a particular feature is quiet during a visit. The absence of a ceremony at one moment is not evidence that a tradition has disappeared."},{"type":"paragraph","text":"The Havan Kund is best understood at this meeting of material and living heritage. Its interpretation should make room for knowledgeable practitioners, acknowledge the limits of the available record and avoid turning a sacred activity into a visitor performance. A careful account can explain why the feature matters while leaving unverified details open for those with the appropriate evidence to clarify."}],"references":[{"title":"Archaeology and Cultural Heritage of Chakwal: A Case Study of Shri Katas Raj Temple","url":"https://norr.numl.edu.pk/repository/filedownload/1603","publisher":"National University of Modern Languages research repository","accessDate":"2026-10-22"},{"title":"Brihadishvara Temple: ritual documentation","url":"https://ignca.gov.in/brhadisvaratemple/VIMAN/RITUALS/Pages/entry.html","publisher":"Indira Gandhi National Centre for the Arts","accessDate":"2026-10-22"},{"title":"Functional mandirs","url":"https://etpb.gov.pk/shrines/mandirs/functional/","publisher":"Evacuee Trust Property Board","accessDate":"2026-10-22"}],"relatedProgrammeIds":[],"relatedProjectIds":[],"featured":false,"sortOrder":10,"featuredImage":null,"seo":{"title":"Havan Kund | Virsapur Archives","description":"Havan Kund names a ritual feature, not simply an architectural shape. At Katas Raj, interpreting it requires attention to both documented fabric and living practice.","primaryKeyword":"Havan Kund","socialTitle":"Havan Kund","socialDescription":"Havan Kund names a ritual feature, not simply an architectural shape. At Katas Raj, interpreting it requires attention to both documented fabric and living practice."},"relatedDistrictIds":["punjab-chakwal"],"previousSlugs":[],"tags":["Punjab","Languages"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6750"],"relatedStoryIds":["story-katas-raj","story-satgraha-temples","story-reading-a-shikhara-without-guessing-a-date","story-sacred-water-at-katas-traditions-and-material-settings"],"contentType":"languages-literature-living","imageStatus":"no-cleared-image","aiAssisted":true,"editorialReviewRequired":true,"internalNotes":"NUMLindexedpassageidentifiesBaradari/Havankund;fullPDFtimeoutmeans specificdimensions/dates omitted. IGNCAritualdocumentation supports distinctionfirekindling/recitation/ceremonialcontext, explicitly nottransferredtoKatas. Requires local practitioner review beforepublication; notinstructions.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain the named ritual feature and local context through practitioner-sensitive sources rather than infer practice from a photograph.","wordCount":417,"publicationHold":false}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-khewra-mines','khewra-salt-mines','review','{"id":"story-khewra-mines","type":"story","slug":"khewra-salt-mines","status":"review","title":"Khewra Salt Mines","summary":"Khewra is both a geological exposure and a working industrial landscape. Its underground rooms reveal extraction, structural judgement and the labour behind an everyday material.","category":"Cultural landscape","primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"location":"Jhelum · Punjab","province":"Punjab","district":"Jhelum","author":"","publishedAt":"","updatedAt":"","body":[{"type":"paragraph","text":"A visit to Khewra begins with salt, but the mine is also a place to think about work. The chambers are spaces made by removing a material that is ordinarily encountered in a packet, a kitchen or a market. Seeing that material still embedded in the earth changes its scale: an everyday commodity becomes a geological body, an industrial resource and an engineered interior."},{"type":"paragraph","text":"The Jhelum district administration locates the mine in Pind Dadan Khan tehsil, at Khewra in Punjab’s Salt Range. The Pakistan Mineral Development Corporation identifies it as one of its operating salt mines. These two facts are a useful foundation. Khewra is not simply a decorative underground attraction, nor is the accessible visitor area the whole of the working mine."},{"type":"heading","level":2,"text":"Leaving material behind"},{"type":"paragraph","text":"PMDC describes the extraction system as room and pillar. In this method, the space opened for extraction is understood alongside material deliberately left to support the workings. The apparently empty chamber and the surviving mass are parts of the same engineering decision. Removing more is not automatically better: the relationship between opening and support is central to reading the interior."},{"type":"paragraph","text":"The operator records several salt seams and colours ranging from pale and transparent material to pink and red. Those variations are part of the physical deposit, but colour alone does not establish a product’s purity, origin or health effects. The most useful on-site observation is how bands and masses appear in the exposed workings, not what a souvenir label promises."},{"type":"heading","level":2,"text":"A history larger than a discovery story"},{"type":"paragraph","text":"The district’s tourist account repeats the familiar story of Alexander’s horses licking salt-bearing stones. It is a memorable piece of local narration, but that page does not supply contemporary evidence establishing the event. The history of a resource should not depend on a single dramatic moment of supposed discovery. Knowledge held by local populations, changing extraction practices and commercial organisation are different questions requiring their own records."},{"type":"paragraph","text":"Khewra also belongs to a wider regional geography. PUNJMIN’s account of rock salt identifies other mining locations in the Salt Range, including Warcha and Kalabagh. This context prevents one famous mine from standing in for every deposit and every working practice in the region. Shared material does not imply identical industrial histories."},{"type":"heading","level":2,"text":"Reading an industrial interior"},{"type":"paragraph","text":"For the heritage observer, distinguish the exposed geology, the excavated workings and later visitor installations. A carved display may explain a material or celebrate a landmark without being an ancient feature. A tunnel’s scale may reflect extraction and transport requirements rather than the proportions of a public room."},{"type":"paragraph","text":"Most importantly, remember that the mine was made legible through human labour and continuing maintenance. Its heritage lies not only in attractive colours but in the relationship between material, judgement and work. That perspective gives Khewra a place in cultural history alongside forts and temples: it records how people have transformed the ground beneath them into a resource and a built environment."}],"references":[{"title":"Khewra Salt Mines","url":"https://jhelum.punjab.gov.pk/khewra_salt_mine","publisher":"Government of Punjab, Jhelum district","accessDate":"2026-10-22"},{"title":"Mines: Khewra Salt Mines","url":"https://www.pmdc.gov.pk/mines/","publisher":"Pakistan Mineral Development Corporation","accessDate":"2026-10-22"},{"title":"Rock Salt","url":"https://punjmin.punjab.gov.pk/rock-salt","publisher":"Punjab Mineral Development Corporation","accessDate":"2026-10-22"}],"relatedProgrammeIds":[],"relatedProjectIds":[],"featured":false,"sortOrder":11,"featuredImage":null,"seo":{"title":"Khewra Salt Mines | Virsapur Archives","description":"Khewra is both a geological exposure and a working industrial landscape. Its underground rooms reveal extraction, structural judgement and the labour behind an everyday material.","primaryKeyword":"Khewra Salt Mines","socialTitle":"Khewra Salt Mines","socialDescription":"Khewra is both a geological exposure and a working industrial landscape. Its underground rooms reveal extraction, structural judgement and the labour behind an everyday material."},"relatedDistrictIds":[],"previousSlugs":[],"tags":["Punjab","Architecture"],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"heritage-place","imageStatus":"no-cleared-image","aiAssisted":true,"editorialReviewRequired":true,"internalNotes":"PMDCroomandpillar,seams,colours,operatingmine;JhelumlocationandtoldAlexanderstorylabelledstorynotfact;PUNJMINregionalcontextindexedread. PMDCclaimsaboutage/ranknotadopted. No inventedlabourhistorynames or currenttouravailability.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Connect extraction, geology and industrial heritage using operator and district records, separating tourism folklore from evidence.","wordCount":472,"publicationHold":false}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-great-bath','great-bath-of-mohenjo-daro','review','{"id":"story-great-bath","type":"story","slug":"great-bath-of-mohenjo-daro","status":"review","title":"Great Bath of Mohenjo-Daro","summary":"The Great Bath combines precise masonry with an unresolved social purpose. Its steps, ledges and waterproofing explain more than an easy comparison with a modern swimming pool.","category":"Archaeology","primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"location":"Mohenjo-daro · Sindh","province":"Sindh","district":"Larkana","author":"","publishedAt":"","updatedAt":"","body":[{"type":"paragraph","text":"The Great Bath is one of Mohenjo Daro’s most recognisable spaces, yet recognition can be misleading. Its name encourages an immediate comparison with a swimming pool. The archaeological evidence offers something more particular: a carefully constructed tank, controlled approaches, surrounding spaces and a demanding effort to keep water where its builders wanted it."},{"type":"paragraph","text":"Harappa’s archaeological description gives approximate dimensions of twelve metres by seven, with a depth of about 2.4 metres. Staircases descend from opposite ends. A ledge beside the water allowed movement near the foot of the steps without immediately entering the deeper tank. These details make the structure intelligible as an arrangement for bodies and movement, not just a rectangle seen from above."},{"type":"heading","level":2,"text":"Keeping water in, letting it out"},{"type":"paragraph","text":"The construction used closely fitted brickwork with gypsum plaster and a bitumen layer for additional waterproofing. The distinction between ordinary masonry and a watertight enclosure is important. A wall can remain standing while leaking badly; containing water demands attention to joints and surfaces as well as strength."},{"type":"paragraph","text":"The published archaeological descriptions also identify an outlet connected to a substantial drain. Filling and emptying belong to the same problem of use. A tank that could only be filled would be a different kind of installation from one whose contents could be discharged. The material evidence for managing water is firmer than any reconstruction of the exact ceremony that may have taken place around it."},{"type":"paragraph","text":"A nearby well has been proposed as a supply source, but the Harappa account notes that no inlet drains have been found. It is therefore better to describe possible supply arrangements than to invent a complete hydraulic circuit. Even an exceptionally well-known monument can retain such basic uncertainties."},{"type":"heading","level":2,"text":"What happened around the tank?"},{"type":"paragraph","text":"Rooms and colonnaded areas formed a larger architectural setting. Their presence encourages questions about preparation, waiting, supervision and movement between spaces. Those questions are useful precisely because they are not already answered by the modern name. A plan shows where a doorway lies; it does not tell us who was permitted to cross it or what words were spoken there."},{"type":"paragraph","text":"Ritual bathing is a common scholarly interpretation of the Great Bath. It should remain an interpretation, rather than becoming a claim that a particular later religious practice has been identified in the third millennium BCE. Similar use of water in different periods does not by itself establish direct continuity of belief."},{"type":"paragraph","text":"Seen within the wider system studied by Michael Jansen, the tank also belongs to a city with many installations for obtaining, using and disposing of water. Its monumentality should not isolate it from those more ordinary provisions. The Great Bath brings technical skill and questions of collective life together. Its surviving fabric tells us a great deal about making a water-filled space, while leaving the social meaning of that space open to further evidence."}],"references":[{"title":"The Great Bath of Mohenjo-daro C","url":"https://www.harappa.com/content/great-bath-mohenjo-daro-c","publisher":"Harappa archaeological documentation","accessDate":"2026-10-22"},{"title":"The Great Bath and Indus public buildings","url":"https://chromeias.com/wp-content/uploads/2020/03/NCERT-Ancient-India-Makkham-Lal.pdf","publisher":"NCERT, Ancient India by Makkhan Lal, hosted reproduction","accessDate":"2026-10-22"},{"title":"Water Supply and Sewage Disposal at Mohenjo-Daro","url":"https://www.jstor.org/stable/124907","publisher":"Michael Jansen / World Archaeology","accessDate":"2026-10-22"}],"relatedProgrammeIds":[],"relatedProjectIds":[],"featured":false,"sortOrder":12,"featuredImage":null,"seo":{"title":"Great Bath of Mohenjo-Daro | Virsapur Archives","description":"The Great Bath combines precise masonry with an unresolved social purpose. Its steps, ledges and waterproofing explain more than an easy comparison with a modern swimming pool.","primaryKeyword":"Great Bath of Mohenjo-Daro","socialTitle":"Great Bath of Mohenjo-Daro","socialDescription":"The Great Bath combines precise masonry with an unresolved social purpose. Its steps, ledges and waterproofing explain more than an easy comparison with a modern swimming pool."},"relatedDistrictIds":["sindh-larkana"],"previousSlugs":[],"tags":["Archaeology","Sindh"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["unesco-138"],"relatedStoryIds":["story-wells-mohenjodaro","story-mohenjodaro-lanes","story-mohenjodaro-architecture","story-priest-king"],"contentType":"archaeology","imageStatus":"no-cleared-image","aiAssisted":true,"editorialReviewRequired":true,"internalNotes":"HarappaC account derived~180words;NCERTindexedpage69supportsoutletcorbelleddrainbitumen,samefactnotduplicatednewsourcebudget;Jansenbroadsystembriefunder50wordsadditional. Avoidabsoluteoldest, certainreligion, certainwaterinlet.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Study the structure, waterproofing and competing interpretations of the Great Bath without asserting an unproven ritual.","wordCount":461,"publicationHold":false}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-moenjodaro-beyond-the-postcard-view','moenjodaro-beyond-the-postcard-view','review','{"id":"story-moenjodaro-beyond-the-postcard-view","type":"story","slug":"moenjodaro-beyond-the-postcard-view","title":"Moenjodaro beyond the postcard view","summary":"A view beyond Moenjodaro’s famous monuments reveals a large, partly excavated urban landscape whose neighbourhoods, later remains and conservation needs deserve equal attention.","body":[{"type":"paragraph","text":"Moenjodaro is often compressed into two images: the Great Bath and the familiar silhouette of the mound behind it. Neither is an adequate picture of the city. A more revealing introduction begins by changing scale, moving from the famous structure to its surrounding buildings, from those buildings to a neighbourhood, and from the excavated neighbourhood to the wider archaeological landscape."},{"type":"paragraph","text":"UNESCO’s account distinguishes a western elevated sector from extensive lower-town remains to the east. It also makes clear that excavation has exposed only part of the protected area. The visible walls are therefore not the full outline of everything that once existed. A blank space on a visitor’s mental map may represent unexcavated deposits rather than an ancient absence of settlement."},{"type":"heading","level":2,"text":"A city seen in fragments"},{"type":"paragraph","text":"The archaeological photographs assembled by Harappa range across different excavation areas, showing streets, wells, rooms and large structures. Their area labels are helpful because they keep an image attached to a particular location. A photograph of one well is evidence about that installation; it should not silently become a picture of every household’s water supply."},{"type":"paragraph","text":"The same discipline applies to an itinerary. Choosing a few contrasting examples can be more illuminating than treating the visit as a race between celebrated monuments. Compare a substantial public-looking space with a smaller domestic arrangement. Notice how an entrance meets a lane, or how the level of a well relates to the surviving walls around it. Such comparisons reveal the different scales at which a city operates."},{"type":"heading","level":2,"text":"More than one time in the view"},{"type":"paragraph","text":"The Buddhist stupa on the western mound belongs to a much later period than the Indus city beneath it. Its visibility in panoramic photographs can make the two appear to belong to one architectural episode. They do not. The later structure is part of the place’s long history, while the urban remains require their own chronology."},{"type":"paragraph","text":"This is why a picturesque skyline needs interpretation. Height, proximity and prominence do not establish contemporaneity. The element most easily recognised at a distance may not be the one that best explains the period a visitor has come to understand."},{"type":"heading","level":2,"text":"The exposed city needs care"},{"type":"paragraph","text":"UNESCO’s conservation discussion identifies saline action associated with the water table as a threat to the remains. This introduces a final change of perspective: excavation is not simply the moment when a hidden city is revealed for everyone to enjoy. Once exposed, fragile fabric requires continuing decisions about protection and maintenance."},{"type":"paragraph","text":"The site is consequently neither a complete recovered city nor a static collection of ruins. It is a place where archaeological knowledge, surviving material and conservation choices meet. Moving beyond the postcard does not mean abandoning the Great Bath. It means giving the lesser-known walls, routes and unfinished questions enough attention that the celebrated monument becomes part of a city again."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"Larkana","relatedDistrictIds":["sindh-larkana"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["unesco-138"],"relatedStoryIds":["story-wells-mohenjodaro","story-mohenjodaro-lanes","story-mohenjodaro-architecture","story-priest-king"],"contentType":"heritage-place","seo":{"title":"Moenjodaro beyond the postcard view | Virsapur Archives","description":"A view beyond Moenjodaro’s famous monuments reveals a large, partly excavated urban landscape whose neighbourhoods, later remains and conservation needs deserve equal attention.","primaryKeyword":"Moenjodaro heritage","socialTitle":"Moenjodaro beyond the postcard view","socialDescription":"A view beyond Moenjodaro’s famous monuments reveals a large, partly excavated urban landscape whose neighbourhoods, later remains and conservation needs deserve equal attention."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Archaeological Ruins at Moenjodaro","url":"https://whc.unesco.org/en/list/138/","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Mohenjo-daro archaeological slideshow","url":"https://www.harappa.com/slideshows/mohenjo-daro","publisher":"Jonathan Mark Kenoyer / Harappa","accessDate":"2026-10-22"},{"title":"Lower Town in the mist","url":"https://www.harappa.com/indus6/mohenjodaromist1.html","publisher":"Harappa archaeological field photography","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"UNESCOspatialscope,excavatedfraction,buddhiststupalater,saltthreat~130words; earlierarchitectureused~60=>200sourcebudget. Slideshowrangesandcaptionnamesprimaryphotodoc. Originalinterpretationofscaledviewnotassertnewhistoricalfacts.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Orient readers to the extent and varied neighbourhoods of a city rather than a single photogenic ruin.","wordCount":452,"publicationHold":false,"sortOrder":13}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-taxila-is-eighteen-places-not-one-stop','taxila-is-eighteen-places-not-one-stop','review','{"id":"story-taxila-is-eighteen-places-not-one-stop","type":"story","slug":"taxila-is-eighteen-places-not-one-stop","title":"Taxila is eighteen places, not one stop","summary":"Taxila’s eighteen mapped components tell connected but different stories. Settlements, monasteries and later remains should be read together without turning them into one timeless city.","body":[{"type":"paragraph","text":"Taxila is a name large enough to hide several different places. A visitor may use it for the museum, a particular monastery, an ancient city or the modern town. In heritage terms, it is a serial property: separate archaeological components are recognised together because their combined evidence tells a larger history. Virsapur’s atlas keeps eighteen component locations within that single canonical property."},{"type":"paragraph","text":"UNESCO’s description includes a cave, early settlement sites, Buddhist religious complexes and later Muslim remains. The result is not one frozen moment of civilisation. It is a landscape in which settlement, patronage and religious use changed over a long period. Keeping the components distinct is the first step toward understanding their connections."},{"type":"heading","level":2,"text":"Different cities, different questions"},{"type":"paragraph","text":"Saraikala, Bhir, Sirkap and Sirsukh represent different parts of the settlement sequence. They should not be imagined as neighbourhoods constructed at the same time around a single centre. A comparison between them is historical: it concerns changing forms of settlement and the evidence preserved at each location."},{"type":"paragraph","text":"At Sirkap, the planned street arrangement and the placement of buildings along it offer questions about urban organisation. The museum’s dedicated account places the city within a sequence of political and cultural changes. That specificity matters more than assigning the entire Taxila landscape one adjective such as Greek, Buddhist or Kushan. Those labels refer to different kinds of connection and different periods."},{"type":"heading","level":2,"text":"Monasteries are not smaller cities"},{"type":"paragraph","text":"Mohra Moradu provides another scale of evidence. Its documented religious architecture belongs to the monastic landscape, with a different organisation and purpose from a settlement street. Comparing a monastery with a city can illuminate relationships between religious institutions and surrounding populations, but resemblance in masonry does not make their functions identical."},{"type":"paragraph","text":"The museum helps reconnect objects with these settings. A sculptural panel is more informative when its recorded provenance is retained than when it is presented simply as an example of Gandharan art. The object’s style, findspot and original architectural context are related questions, not substitutes for one another. Where a context is uncertain, that uncertainty should remain visible."},{"type":"heading","level":2,"text":"Reading the whole without losing the parts"},{"type":"paragraph","text":"A useful approach to Taxila is therefore to select contrasting components and ask what each contributes. One may clarify a settlement plan, another a religious arrangement, another a later phase of the valley’s occupation. The point is not to collect eighteen identical stops. It is to understand why a dispersed group can tell a story that no single monument could carry."},{"type":"paragraph","text":"On a map, the components remain separate points; in interpretation, they remain connected evidence. That balance prevents two common mistakes: reducing Taxila to one famous monastery, and dissolving the individual sites into an undifferentiated ancient city. The serial property is strongest when its diversity stays legible."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Architecture"],"province":"Khyber Pakhtunkhwa; Punjab","district":"Haripur; Rawalpindi","relatedDistrictIds":["khyber-pakhtunkhwa-haripur","punjab-rawalpindi"],"provinceRegionIds":["khyber-pakhtunkhwa","punjab"],"relatedHeritageIds":["unesco-139"],"relatedStoryIds":["story-gandhara-as-a-region-not-a-single-dynasty","story-how-a-site-plan-changes-what-visitors-see","story-old-excavation-reports-valuable-records-with-limits","story-the-circumambulation-path-as-a-designed-experience"],"contentType":"heritage-place","seo":{"title":"Taxila is eighteen places, not one stop | Virsapur Archives","description":"Taxila’s eighteen mapped components tell connected but different stories. Settlements, monasteries and later remains should be read together without turning them into one timeless city.","primaryKeyword":"Taxila heritage","socialTitle":"Taxila is eighteen places, not one stop","socialDescription":"Taxila’s eighteen mapped components tell connected but different stories. Settlements, monasteries and later remains should be read together without turning them into one timeless city."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Taxila: Outstanding Universal Value and component list","url":"https://whc.unesco.org/en/list/139/","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Sirkap","url":"https://taxilamuseum.punjab.gov.pk/node/79","publisher":"Taxila Museum, Government of Punjab","accessDate":"2026-10-22"},{"title":"Mohra Moradu","url":"https://taxilamuseum.punjab.gov.pk/node/76","publisher":"Taxila Museum, Government of Punjab","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"UNESCOserialproperty,cavefoursettlementsreligioussites~175words. MuseumSirkapandMohraM sourcesclose-readrequiredbeforecompile.18component count retainedcanonicalUNESCObaseline; noinventgeography/serialsplit.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain the serial property and distinguish settlements, monasteries and their separate evidence.","wordCount":439,"publicationHold":false,"sortOrder":14}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-takht-i-bahi-and-the-city-below','takht-i-bahi-and-the-city-below','review','{"id":"story-takht-i-bahi-and-the-city-below","type":"story","slug":"takht-i-bahi-and-the-city-below","title":"Takht-i-Bahi and the city below","summary":"Takht-i-Bahi’s hilltop monastery and Sahr-i-Bahlol’s town remains form one World Heritage property, but their distinct settings reveal different aspects of Gandharan life.","body":[{"type":"paragraph","text":"Takht-i-Bahi commands attention through its position. Stone courts and passages occupy a hilltop setting above the surrounding plain, making the monastery appear visually separate from everyday settlement. Yet its full World Heritage name includes another place: the neighbouring city remains at Sahr-i-Bahlol. The pairing encourages a broader view of Gandhara than an isolated religious monument can provide."},{"type":"paragraph","text":"UNESCO describes the property as two distinct components. Takht-i-Bahi is a monastic complex whose use extended from the early centuries CE into the seventh century. Sahr-i-Bahlol, about five kilometres away, preserves evidence of a fortified town on a lower mound. Their recognition together does not make them one continuous building complex, nor prove that every surviving element was in use simultaneously."},{"type":"heading","level":2,"text":"A monastery organised through courts"},{"type":"paragraph","text":"The federal archaeological description identifies a main stupa court, a court with numerous stupas, residential monastic spaces, an assembly hall and other facilities. These names help distinguish parts of the complex, but some functional labels remain interpretations. The department itself qualifies the description of underground spaces traditionally called meditation cells."},{"type":"paragraph","text":"The courts make a useful starting point for observation. Notice how a passage delivers someone into a defined space, how an arrangement of smaller monuments differs from a dominant central structure, and how a group of rooms relates to its shared open area. These relationships convey organisation even where roofing, furnishings and the details of daily activity are no longer preserved."},{"type":"paragraph","text":"Local stone construction is another part of the site’s character. UNESCO notes the distinctive masonry pattern associated with Gandharan buildings. Looking at the combination of larger and smaller pieces helps explain how a wall was assembled, while avoiding the assumption that every visible repair belongs to the original construction."},{"type":"heading","level":2,"text":"The less spectacular component"},{"type":"paragraph","text":"Sahr-i-Bahlol asks for a different kind of attention. Its archaeological remains are entangled with later settlement rather than presented as an isolated hilltop ruin. UNESCO’s account records pressures from encroachment and the limited survival of the old defensive perimeter. The contrast illustrates how very different preservation conditions can exist within one recognised property."},{"type":"paragraph","text":"A dramatic view of the monastery can therefore give an incomplete impression of the heritage challenge. Conserving an exposed complex and managing buried or occupied urban remains involve different practical questions. A single designation does not remove those differences."},{"type":"paragraph","text":"Reading the two components together restores a sense of scale to the religious landscape. Monasteries belonged to a world that also contained towns and ordinary settlement, even when the precise relationships between particular communities require further evidence. Takht-i-Bahi offers unusually legible architecture; Sahr-i-Bahlol reminds us that the less visible part of the record matters too. The property’s significance lies in allowing both kinds of evidence to remain part of the story."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Khyber Pakhtunkhwa","Architecture"],"province":"Khyber Pakhtunkhwa","district":"Mardan","relatedDistrictIds":["khyber-pakhtunkhwa-mardan"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["unesco-140"],"relatedStoryIds":["story-gandhara-as-a-region-not-a-single-dynasty","story-monasteries-and-towns-testing-an-economic-relationship","story-buddhist-pilgrimage-and-the-material-presence-of-relics","story-the-circumambulation-path-as-a-designed-experience"],"contentType":"heritage-place","seo":{"title":"Takht-i-Bahi and the city below | Virsapur Archives","description":"Takht-i-Bahi’s hilltop monastery and Sahr-i-Bahlol’s town remains form one World Heritage property, but their distinct settings reveal different aspects of Gandharan life.","primaryKeyword":"Takht-i-Bahi & Sahr-i-Bahlol heritage","socialTitle":"Takht-i-Bahi and the city below","socialDescription":"Takht-i-Bahi’s hilltop monastery and Sahr-i-Bahlol’s town remains form one World Heritage property, but their distinct settings reveal different aspects of Gandharan life."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Buddhist Ruins of Takht-i-Bahi and Neighbouring City Remains at Sahr-i-Bahlol","url":"https://whc.unesco.org/en/list/140/","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Takht-i-Bahi","url":"https://doam.gov.pk/public/heritage-sites/392","publisher":"Department of Archaeology & Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Physical Cultural Resources Management Plan: Takht-i-Bhai and Jamal Garhi","url":"https://old.kptourism.com/uploads/images/kite/1692866715873-final-pcrmp-for-illumination-of--of-takht-bhai-and-jamal-garhi--21-august-23.pdf","publisher":"Khyber Pakhtunkhwa tourism and archaeology project documentation","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"UNESCOtwocomponentsdistanceperiodassemblagemasonry~190words. DOAMroomfunctionterminology~70words;typo1978earlyexcavationdateexcluded. Managementplanreferenceusedforconservationplanningnotunreadspecificclaims. Bodydoesnotassertdonor/tradeconnectionbetweenexactsitesasproven.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Read the relationship between the hilltop monastery and Sahr-i-Bahlol without merging their functions.","wordCount":441,"publicationHold":false,"sortOrder":15}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-lahore-fort-and-shalamar-one-inscription-two-settings','lahore-fort-and-shalamar-one-inscription-two-settings','review','{"id":"story-lahore-fort-and-shalamar-one-inscription-two-settings","type":"story","slug":"lahore-fort-and-shalamar-one-inscription-two-settings","title":"Lahore Fort and Shalamar: one inscription, two settings","summary":"Lahore Fort and Shalamar Gardens share a World Heritage inscription, but their contrasting settings reveal different ways Mughal patronage organised movement, display and water.","body":[{"type":"paragraph","text":"A fortified royal enclosure and a terraced garden seem to ask for different kinds of attention. At Lahore Fort, walls, gateways and successive courts organise the experience. At Shalamar, the relationship between level ground, falling water and planted space becomes central. Their shared World Heritage inscription recognises connected achievements without making the two complexes interchangeable."},{"type":"paragraph","text":"UNESCO describes them as distinct royal settings several kilometres apart. Their surviving architecture reflects Mughal patronage during the sixteenth and seventeenth centuries. The fort contains buildings and decorative work associated with successive rulers, while Shalamar’s construction is associated with Shah Jahan in 1641–1642. Visiting both should therefore be understood as a comparison across the city, not a walk between adjacent parts of one palace."},{"type":"heading","level":2,"text":"Inside the fort’s layered enclosure"},{"type":"paragraph","text":"The fort’s variety is part of its historical value. Brick and sandstone, marble and inlay, painted surfaces and tile decoration contribute different textures and effects. It is useful to notice where a material belongs: on a structural wall, a screen, a floor, an image-bearing surface or an element designed to catch the light."},{"type":"paragraph","text":"The Picture Wall offers a particularly vivid example of display beyond a simple defensive exterior. AKDN’s conservation account identifies imagery including people, animals, birds, scenes of action and patterned ornament. The wall’s treatment brings representation into the experience of approaching the royal enclosure; it is not merely a neutral boundary around more important buildings."},{"type":"paragraph","text":"The same account documents structural stabilisation alongside conservation of decorated surfaces. This is a useful reminder that a mural at architectural scale depends on the condition of its support. Preserving its colour and imagery cannot be separated from understanding the wall that carries them."},{"type":"heading","level":2,"text":"Water gives the garden its structure"},{"type":"paragraph","text":"Shalamar’s three terraces produce a different sequence. UNESCO describes an enclosed, rectilinear garden with pavilions, basins and flowing-water features. Here, a change of level can become a visual and sensory event rather than merely a step between rooms. Water links separate parts of the composition while making the descent through the garden legible."},{"type":"paragraph","text":"A dry channel can still communicate this intended arrangement, though it cannot reproduce the complete historical experience. Likewise, a contemporary planting scheme should not automatically be assumed to match every earlier planting. A garden is maintained and altered through time; its living material does not survive in the same way as carved stone."},{"type":"heading","level":2,"text":"Compare relationships, not luxury alone"},{"type":"paragraph","text":"The pairing is most rewarding when attention moves beyond an inventory of precious materials. Ask how an approach frames a view, how a boundary controls entry, and how a pavilion or court establishes a place to pause. The fort and garden offer different answers to related questions about order and display."},{"type":"paragraph","text":"Their shared inscription does not erase the individuality of either setting. It allows them to illuminate one another: monumental enclosure beside designed landscape, decorated surface beside moving water. Together they show why Mughal architectural patronage cannot be understood through buildings alone, or through gardens detached from the courtly world that commissioned them."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Lahore","relatedDistrictIds":["punjab-lahore"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["unesco-171"],"relatedStoryIds":["story-how-a-mughal-charbagh-organises-movement"],"contentType":"heritage-place","seo":{"title":"Lahore Fort and Shalamar: one inscription, two settings | Virsapur Archives","description":"Lahore Fort and Shalamar Gardens share a World Heritage inscription, but their contrasting settings reveal different ways Mughal patronage organised movement, display and water.","primaryKeyword":"Fort & Shalamar Gardens heritage","socialTitle":"Lahore Fort and Shalamar: one inscription, two settings","socialDescription":"Lahore Fort and Shalamar Gardens share a World Heritage inscription, but their contrasting settings reveal different ways Mughal patronage organised movement, display and water."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Fort and Shalamar Gardens in Lahore","url":"https://whc.unesco.org/en/list/171/","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Picture Wall conservation inauguration, 2019","url":"https://the.akdn/en/resources-media/whats-new/news-release/prime-minister-imran-khan-inaugurates-400-year-old-historic-%E2%80%9Cpicture-wall%E2%80%9D-lahore-fort","publisher":"Aga Khan Development Network","accessDate":"2026-10-22"},{"title":"Monuments: Shalimar Gardens","url":"https://walledcitylahore.gop.pk/monuments/","publisher":"Punjab Walled Cities & Heritage Areas Authority","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"UNESCOtwocomplexes7kmthree terraces1641–42 materials~180words;AKDN2019wallmaterialsconservation~120words;comparisoninterpretiveclearly. UNESCO erroneous13th–15thearlyMughalsomitted. No claims currentfountainsoperational.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain why the paired property joins a courtly enclosure to a designed garden landscape.","wordCount":479,"publicationHold":false,"sortOrder":16}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-makli-as-a-landscape-of-generations','makli-as-a-landscape-of-generations','review','{"id":"story-makli-as-a-landscape-of-generations","type":"story","slug":"makli-as-a-landscape-of-generations","title":"Makli as a landscape of generations","summary":"Makli is not one monument repeated across a hillside. Its tombs preserve changing patronage, materials and forms across generations of Sindh’s history.","body":[{"type":"paragraph","text":"Makli resists the idea of a single landmark. Its importance lies in the accumulation of monuments across a large funerary landscape near Thatta: different patrons, generations, materials and architectural ambitions occupy the same plateau. A visitor who seeks only the largest tomb can miss the relationships that make the place historically exceptional."},{"type":"paragraph","text":"UNESCO places the principal monumental sequence between the fourteenth and eighteenth centuries, during the changing political history of Sindh. Rulers and governors are part of that story, but so are religious figures and other people commemorated in the cemetery. The landscape is not simply a catalogue of royal biographies. It also records the different ways authority, devotion and remembrance were given built form."},{"type":"heading","level":2,"text":"Stone does not tell the same story as tile"},{"type":"paragraph","text":"The variation in materials helps make the sequence visible. UNESCO describes stone and brick monuments, including structures with glazed-tile decoration. Carving, coloured surface and architectural mass create different effects. A relief cut into stone and a pattern assembled through glazed elements may share a visual rhythm while requiring different methods of production and repair."},{"type":"paragraph","text":"Rather than treating these techniques as a competition in richness, notice how each organises a surface. A band can lead the eye around a wall; a framed panel can interrupt that movement; an inscription can establish a different kind of attention. The monument is read through the arrangement of its parts as well as through the person named on it."},{"type":"heading","level":2,"text":"One tomb within a longer landscape"},{"type":"paragraph","text":"The Sindh Antiquities account of Jam Nizamuddin’s tomb provides a close example. It identifies relief-carved bands, floral forms, arched panels and finely worked inscriptions. Its description also connects the carving with architectural traditions beyond Thatta. These comparisons point toward a history of exchange, but they should not be used to assign a religion or birthplace to an unnamed individual craftsperson."},{"type":"paragraph","text":"Inside, the documented carved mihrab and inscription bands continue the relationship between orientation, text and worked stone. The building rewards attention at several distances: the overall mass, the organisation of the wall and the small changes within a carved sequence. A single frontal photograph rarely captures all three."},{"type":"paragraph","text":"Returning from that close view to the wider cemetery changes its meaning. This tomb is one contribution to a much longer history, not a model from which every other structure was copied. Contrasts between monuments can reveal changes in patronage and architectural preference, provided their identities and dates are established rather than guessed from appearance."},{"type":"paragraph","text":"Makli’s scale also makes conservation a landscape problem. Individual repairs matter, but so do the relationships between structures and the pressures affecting the wider site. Its heritage value lies in the continuing legibility of a varied assemblage. To understand it is to move between the particular and the collective: one inscription, one tomb, one group, and the generations that made the plateau a place of remembrance."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"Thatta","relatedDistrictIds":["sindh-thatta"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["unesco-143"],"relatedStoryIds":["story-funerary-landscapes-and-the-names-we-no-longer-know","story-thatta-across-political-and-cultural-changes","story-maklis-scale-walking-a-funerary-landscape"],"contentType":"heritage-place","seo":{"title":"Makli as a landscape of generations | Virsapur Archives","description":"Makli is not one monument repeated across a hillside. Its tombs preserve changing patronage, materials and forms across generations of Sindh’s history.","primaryKeyword":"Makli, Thatta heritage","socialTitle":"Makli as a landscape of generations","socialDescription":"Makli is not one monument repeated across a hillside. Its tombs preserve changing patronage, materials and forms across generations of Sindh’s history."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Historical Monuments at Makli, Thatta","url":"https://whc.unesco.org/en/list/143/","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Jam Nizamuddin’s Tomb, Makli–Thatta","url":"https://antiquities.sindhculture.gov.pk/tour/jam-nizamuddins-tomb-makli-thatta/","publisher":"Directorate General of Antiquities, Government of Sindh","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"UNESCOchronologydynasticvarietybuilttypes~185words;SindhJamNizamspecificcarvedbandsandmihrab~160words. No unverifiedgravecount orreductiondecorativemotiftoethnicmakeridentity. LaterMaklilandscapetopicneedsnewsourcebudget.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Organise a vast necropolis through chronology and patronage rather than a list of tombs.","wordCount":458,"publicationHold":false,"sortOrder":17}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-rohtas-fort-through-its-gateways','rohtas-fort-through-its-gateways','review','{"id":"story-rohtas-fort-through-its-gateways","type":"story","slug":"rohtas-fort-through-its-gateways","title":"Rohtas Fort through its gateways","summary":"Rohtas Fort’s gateways reveal the logic of a vast defensive enclosure: controlled entry, changing directions, internal divisions and the work of maintaining monumental masonry.","body":[{"type":"paragraph","text":"The walls of Rohtas are impressive at a distance, but a gateway reveals how the fort was meant to work. A continuous boundary excludes; a gate must admit someone while preserving control. Its size, depth, approach and connection to the spaces beyond are therefore more than ceremonial details. They belong to the practical problem at the centre of a fortification."},{"type":"paragraph","text":"UNESCO identifies Rohtas as a sixteenth-century complex begun under Sher Shah Suri in 1541. Its irregular enclosure follows the terrain rather than imposing a simple geometric outline. More than four kilometres of wall, bastions and monumental gateways form a system whose scale is difficult to grasp from a single viewpoint."},{"type":"heading","level":2,"text":"An opening with a name and a setting"},{"type":"paragraph","text":"Jhelum’s official account lists twelve gates, including Sohail, Shah Chandwali, Kabuli, Shishi, Langar Khani and Talaqi. Their names are useful anchors, but the more revealing comparison concerns how each opening sits within the surrounding fabric. Does a route approach directly or change direction? How does the passage relate to adjacent towers? What can be seen before and after crossing the threshold?"},{"type":"paragraph","text":"These questions do not require inventing a battle scene. They follow from the architecture itself. A gateway can slow movement, organise approach and make authority visible even without evidence of an assault at that precise point. Defensive potential and a documented historical event are different subjects."},{"type":"paragraph","text":"The district account places the Shahi mosque near Kabuli Gate. This juxtaposition reminds us that the fort was more than a perimeter. Religious provision, accommodation and movement had to fit within the fortified setting. The boundary protected a place of occupation, not an empty diagram of military engineering."},{"type":"heading","level":2,"text":"Inside another boundary"},{"type":"paragraph","text":"UNESCO also records an internal wall separating the citadel from the rest of the fort and stepped wells supplying water. These elements extend the logic of control inward. Entering the outer enclosure was not necessarily the end of a sequence, and sustaining people inside required infrastructure as well as strong masonry."},{"type":"paragraph","text":"Rohtas can consequently be read as nested relationships: approach to gate, gate to enclosure, enclosure to citadel, occupation to water supply. The gates make those relationships easier to perceive because they are points where one condition changes into another."},{"type":"heading","level":2,"text":"A massive building can still be vulnerable"},{"type":"paragraph","text":"The official district history records rain and seepage damage at Talaqi Gate in 2005 and deterioration affecting Gatali Gate’s supporting fabric. These are dated reports, not a current condition survey, but they undermine the idea that monumental thickness guarantees permanent survival. Foundations, water movement and maintenance remain consequential."},{"type":"paragraph","text":"The best introduction to Rohtas therefore combines scale with precision. Step back far enough to recognise the terrain-following enclosure, then return to a gateway and examine its relationships. Its grandeur comes not only from the quantity of stone but from the way that stone organised access, occupation and the assertion of power."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Jhelum","relatedDistrictIds":["punjab-jhelum"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["unesco-586"],"relatedStoryIds":["story-defensive-gates-bends-levels-and-lines-of-approach","story-world-heritage-is-not-the-same-as-the-tentative-list"],"contentType":"heritage-place","seo":{"title":"Rohtas Fort through its gateways | Virsapur Archives","description":"Rohtas Fort’s gateways reveal the logic of a vast defensive enclosure: controlled entry, changing directions, internal divisions and the work of maintaining monumental masonry.","primaryKeyword":"Rohtas Fort heritage","socialTitle":"Rohtas Fort through its gateways","socialDescription":"Rohtas Fort’s gateways reveal the logic of a vast defensive enclosure: controlled entry, changing directions, internal divisions and the work of maintaining monumental masonry."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Rohtas Fort","url":"https://whc.unesco.org/en/list/586/","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Rohtas Fort: gates and documented condition","url":"https://jhelum.punjab.gov.pk/rohtas_fort_pp","publisher":"Government of Punjab, Jhelum district","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"UNESCO16thcentury1541contourwallsbaolisinnercitadel~180words;Jhelum12gatesnamesmosqueand2005Talaqidamage~140words. Gatefunctiondiscussionarchitecturalinterpretation no claimparticularkillzone. No currentcondition inferredoldreport.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Use entry sequences and defensive thresholds to understand the fort’s organisation.","wordCount":455,"publicationHold":false,"sortOrder":18}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-baltit-fort-a-building-changed-by-its-inhabitants','baltit-fort-a-building-changed-by-its-inhabitants','review','{"id":"story-baltit-fort-a-building-changed-by-its-inhabitants","type":"story","slug":"baltit-fort-a-building-changed-by-its-inhabitants","title":"Baltit Fort: a building changed by its inhabitants","summary":"Baltit Fort’s commanding silhouette is the result of successive adaptations. Its conservation preserved a layered building rather than returning it to one imagined original moment.","body":[{"type":"paragraph","text":"Baltit Fort looks like a single commanding object above Karimabad. Its history is less uniform than that silhouette suggests. The building grew through additions and adjustments, responding to changing domestic, political and defensive needs. To read it as an unchanged medieval castle is to overlook the evidence that makes it particularly interesting."},{"type":"paragraph","text":"Pakistan’s UNESCO Tentative List description places the fort on an elevated spur overlooking the Hunza valley. It describes storage, halls, domestic rooms and spaces for reception within a multi-storey arrangement. Those different uses complicate the word fort: the structure was also a residence and a setting in which authority was received and displayed."},{"type":"heading","level":2,"text":"A building made through change"},{"type":"paragraph","text":"The conservation case study hosted by MIT’s Aga Khan Program reports that archaeological investigation distinguished more than seventy construction phases. The number conveys the complexity of the building rather than a visitor checklist. Walls, floors and openings were not all conceived as one design, and later work became part of the object conservators had to understand."},{"type":"paragraph","text":"The federal archaeological account likewise emphasises adaptation. It describes alterations to the upper floor under Muhammad Nazim Khan that gave the building a more palatial character. Such changes matter because domestic comfort and representation can transform a defensive structure without erasing every earlier element."},{"type":"paragraph","text":"Looking for junctions is therefore more useful than searching for a single founding date. A change in material, a room fitted against an older wall or a passage accommodating an irregular plan may preserve the story of adjustment. Not every visible difference can be dated by eye, but it can identify where a closer investigation would be valuable."},{"type":"heading","level":2,"text":"Conservation as a sequence of decisions"},{"type":"paragraph","text":"The MIT case study describes an approach that began with structural problems around foundations and load-bearing walls, before treating architectural fabric and introducing elements needed for reuse. This order is significant. The appearance of a room depends on a building’s ability to stand; decorative repair cannot substitute for understanding its support."},{"type":"paragraph","text":"Restoration and museum reuse were completed in the 1990s, with an opening in 1996. Local workers participated in the project, while its wider planning considered the relationship between the fort and Karimabad. The result should not be understood simply as an isolated monument rescued from its surroundings. The setting and the people able to care for it are part of its continuing life."},{"type":"heading","level":2,"text":"More than a view"},{"type":"paragraph","text":"Baltit’s position naturally draws the eye toward the mountains. Turning attention back to the interior reveals a different achievement: a layered arrangement of rooms made useful, repaired and adapted over time. The contrast between distant silhouette and intimate interior is central to its character."},{"type":"paragraph","text":"Baltit appears on Pakistan’s Tentative List, which is not the same status as an inscribed World Heritage property. Its significance does not depend on blurring that distinction. The building already offers a compelling account of architectural change, and of conservation that allows those changes to remain readable rather than replacing them with a polished fiction of an untouched past."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Gilgit-Baltistan","Architecture"],"province":"Gilgit-Baltistan","district":"Hunza","relatedDistrictIds":["gilgit-baltistan-hunza"],"provinceRegionIds":["gilgit-baltistan"],"relatedHeritageIds":["curated-baltit"],"relatedStoryIds":["story-reading-repairs-without-calling-everything-original","story-hunza-through-fort-and-settlement-relations","story-hunzas-fort-and-the-settlement-below-it"],"contentType":"heritage-place","seo":{"title":"Baltit Fort: a building changed by its inhabitants | Virsapur Archives","description":"Baltit Fort’s commanding silhouette is the result of successive adaptations. Its conservation preserved a layered building rather than returning it to one imagined original moment.","primaryKeyword":"Baltit Fort heritage","socialTitle":"Baltit Fort: a building changed by its inhabitants","socialDescription":"Baltit Fort’s commanding silhouette is the result of successive adaptations. Its conservation preserved a layered building rather than returning it to one imagined original moment."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Baltit Fort","url":"https://whc.unesco.org/en/tentativelists/1882/","publisher":"UNESCO World Heritage Centre / Pakistan Tentative List submission","accessDate":"2026-10-22"},{"title":"Baltit Fort: restoration and adaptive reuse","url":"https://web.mit.edu/akpia/www/AKPsite/4.239/baltit/baltit.html","publisher":"MIT Aga Khan Program for Islamic Architecture, Li Lian Tan case study","accessDate":"2026-10-22"},{"title":"Baltit Fort","url":"https://doam.gov.pk/public/heritage-sites/748","publisher":"Department of Archaeology & Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"MITconstructionphasesmethodrepairsequence1996opening <190words;DOAMpalatialalterationsmuseumandvillage~130words;UNtentativestatuslandscaperooms~100words. AvoidDOAM950stypo andMITincorrectIndusthroughHunza. No currenthours.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Trace adaptation and conservation rather than presenting an unchanging medieval castle.","wordCount":480,"publicationHold":false,"sortOrder":19}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-mehrgarh-before-the-indus-cities','mehrgarh-before-the-indus-cities','review','{"id":"story-mehrgarh-before-the-indus-cities","type":"story","slug":"mehrgarh-before-the-indus-cities","title":"Mehrgarh before the Indus cities","summary":"Mehrgarh opens a view onto settlement before the Indus cities. New dating research makes its chronology a live question rather than a fixed origin story.","body":[{"type":"paragraph","text":"Mehrgarh matters because it allows questions to be asked before the familiar skyline of the Indus cities appears. On the Kachi plain near the Bolan Pass, archaeological mounds preserve evidence of settlement, building and burial over successive periods. The place offers an account of changing ways of living, not simply an earlier version of Mohenjo Daro waiting to become a city."},{"type":"paragraph","text":"Pakistan’s Tentative List submission describes low mounds and substantial deposits, much of them beneath later alluvium. It records compartmented mud-brick structures whose functions are not always certain, as well as excavated cemeteries. The arrangement of small units may suggest storage in some cases, but an interpretation should remain attached to the specific structure and its evidence."},{"type":"heading","level":2,"text":"A mound is accumulated history"},{"type":"paragraph","text":"Mehrgarh is described as a tell: a mound built up through repeated occupation and the survival of earlier material beneath later construction. Its depth is therefore not a simple measure of age. Buildings can be rebuilt, abandoned, eroded or covered at different rates. Understanding the sequence requires the relationship between layers as well as measurements of when particular materials formed."},{"type":"paragraph","text":"Excavations opened by the French archaeological mission in collaboration with Pakistan’s archaeological department brought this evidence into sustained research. The resulting importance of Mehrgarh should not be confused with a claim that every stage of early farming across a vast region is represented at this one location. It is an unusually informative record, not the whole record."},{"type":"heading","level":2,"text":"Why the dates are being reconsidered"},{"type":"paragraph","text":"A 2025 study by Benjamin Mutin and colleagues analysed tooth enamel from twenty-three burials in the Period I cemetery and modelled the results alongside their stratigraphic positions. It proposed a beginning around 5200–4900 BCE for that cemetery sequence, substantially later than influential older chronologies. The paper also argued for a shorter duration than had often been assumed."},{"type":"paragraph","text":"The distinction between a dated sample, a cemetery phase and a regional historical claim is essential. A burial belongs to a particular context; the authors then use the pattern of dates to reconsider broader interpretations. Readers should be told both what was measured and how far the argument extends, rather than being given a newly simplified headline date for the invention of agriculture."},{"type":"paragraph","text":"This research also shows why an older heritage description and a recent scientific paper may disagree. The discrepancy is not resolved by silently selecting the more dramatic age. Dates belong to methods, samples and arguments that can be checked and revised."},{"type":"paragraph","text":"Mehrgarh’s value survives that revision. Its structures and burials still contribute to understanding settlement before the major Indus urban centres. Indeed, the ability to return to excavated material with new methods is part of its importance. The strongest introduction to the site leaves room for that ongoing enquiry: a history made more precise through evidence, rather than a contest to claim the earliest beginning."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Balochistan","Architecture"],"province":"Balochistan","district":"Kachhi","relatedDistrictIds":["balochistan-kachhi"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["curated-mehrgarh"],"relatedStoryIds":["story-early-farming-in-the-kachi-plain-evidence-rather-than-an-origin-myth","story-radiocarbon-dates-are-ranges-not-birthdays","story-animal-bones-and-the-limits-of-ancient-menus","story-terracotta-figurines-without-invented-identities"],"contentType":"heritage-place","seo":{"title":"Mehrgarh before the Indus cities | Virsapur Archives","description":"Mehrgarh opens a view onto settlement before the Indus cities. New dating research makes its chronology a live question rather than a fixed origin story.","primaryKeyword":"Mehrgarh heritage","socialTitle":"Mehrgarh before the Indus cities","socialDescription":"Mehrgarh opens a view onto settlement before the Indus cities. New dating research makes its chronology a live question rather than a fixed origin story."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Archaeological Site of Mehrgarh","url":"https://whc.unesco.org/en/tentativelists/1876/","publisher":"UNESCO World Heritage Centre / Pakistan Tentative List submission","accessDate":"2026-10-22"},{"title":"New radiocarbon dates of human tooth enamel reveal a late appearance of farming life in the Indus Valley","url":"https://www.nature.com/articles/s41598-025-92621-5.pdf","publisher":"Benjamin Mutin and colleagues / Scientific Reports, 2025","accessDate":"2026-10-22"},{"title":"Nouvelles recherches archéologiques au Baluchistan: les fouilles de Mehrgarh","url":"https://www.persee.fr/doc/paleo_0153-9345_1974_num_2_2_1075","publisher":"Jean-François Jarrige / Paléorient, 1974","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"2025PDFabstractmethods/resultsreadfullavailabletext;~180wordderivation(max200). UNESCOlandscapetellcompartmentwalls~135words. 1974sourceabstract supports excavationmission only. Do notconflatecemeterystart withfirsthumanpresenceorallSouthAsia.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain the settlement’s long archaeological sequence without making a simplistic first-civilisation claim.","wordCount":459,"publicationHold":false,"sortOrder":20}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-rehman-dheri-and-the-question-of-planned-settlement','rehman-dheri-and-the-question-of-planned-settlement','review','{"id":"story-rehman-dheri-and-the-question-of-planned-settlement","type":"story","slug":"rehman-dheri-and-the-question-of-planned-settlement","title":"Rehman Dheri and the question of planned settlement","summary":"Rehman Dheri makes early planning visible in streets and blocks, but its ground plan cannot by itself identify the people or institutions that organised the settlement.","body":[{"type":"paragraph","text":"A low mound can contain an unusually legible idea of a town. At Rehman Dheri in the Gomal plain, the arrangement of streets, lanes and blocks is central to the site''s importance. The settlement asks a question that is more useful than a contest over which city came first: how much can an ordered plan tell us about the society that made it?"},{"type":"paragraph","text":"Pakistan''s Tentative List description identifies a rectangular, walled settlement whose latest layout remains discernible on the surface and in aerial views. Streets divide the interior into regular blocks. Rain and dew can help reveal buried walls through differences in the ground. This is a plan partly exposed by the condition of the mound, rather than a complete town excavated room by room."},{"type":"heading","level":2,"text":"Order before the great cities"},{"type":"paragraph","text":"Archaeologist Jonathan Mark Kenoyer places Rehman Dheri among the important settlements preceding the mature Indus urban centres. His review of archaeological research highlights the University of Peshawar excavations directed by Farzand Ali Durrani, substantial mud-brick walls, planned streets and early evidence of seals and graffiti. The point is not that urban organisation suddenly appeared at one famous city. Its antecedents can be investigated in several settlements and regional traditions."},{"type":"paragraph","text":"A regular street grid implies coordination, but it does not reveal the form of government. The same surviving pattern cannot tell us whether a ruler, a council, neighbouring households or several changing institutions made each decision. Nor does an enclosing wall alone demonstrate a particular war. Planning, authority and defensive intention are related questions, not interchangeable answers."},{"type":"heading","level":2,"text":"The surface is only one moment"},{"type":"paragraph","text":"The Tentative List account also records evidence of craft activity, including kilns and slag, and notes the limitations imposed by comparatively restricted excavation. Surface visibility therefore has a double meaning. It helps make the last settlement arrangement intelligible, while erosion exposes material that once belonged within deposits. A clear photograph can be the result of a damaging process."},{"type":"paragraph","text":"Imagine two plans laid over one another: the visible pattern of the final occupation and the sequence of earlier building beneath it. They need not be identical. Establishing continuity requires dated layers, recorded wall relationships and associated finds. A neat aerial outline is an invitation to research, not a substitute for that work."},{"type":"heading","level":2,"text":"Making the site accessible without losing evidence"},{"type":"paragraph","text":"The introduction to Khyber Pakhtunkhwa''s January 2024 environmental and social management plan treats conservation and visitor development as activities requiring impact assessment and monitoring. It describes a proposed management framework, not proof that every intended intervention has been completed."},{"type":"paragraph","text":"That distinction matters for visitors and planners alike. Paths, drainage, signs and protective measures should help people understand the mound without confusing new facilities with ancient remains. Rehman Dheri''s strongest story is already in its ground: an early community organised a substantial settlement, and archaeology is still determining how that organisation changed. Respecting the unanswered questions makes the visible order more interesting, not less."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Khyber Pakhtunkhwa","Architecture"],"province":"Khyber Pakhtunkhwa","district":"D. I. Khan","relatedDistrictIds":["khyber-pakhtunkhwa-d-i-khan"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["curated-rehman-dheri"],"relatedStoryIds":[],"contentType":"heritage-place","seo":{"title":"Rehman Dheri and the question of planned settlement | Virsapur Archives","description":"Rehman Dheri makes early planning visible in streets and blocks, but its ground plan cannot by itself identify the people or institutions that organised the settlement.","primaryKeyword":"Rehman Dheri heritage","socialTitle":"Rehman Dheri and the question of planned settlement","socialDescription":"Rehman Dheri makes early planning visible in streets and blocks, but its ground plan cannot by itself identify the people or institutions that organised the settlement."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Rehman Dheri","url":"https://whc.unesco.org/en/tentativelists/1877/","publisher":"Pakistan submission to UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Fifty-Five Years of Archaeological Research in Pakistan","url":"https://www.harappa.com/sites/default/files/pdf/Kenoyer2004_Fifty-five%20years%20of%20Archaeological%20Research%20in%20P.pdf","publisher":"Jonathan Mark Kenoyer","accessDate":"2026-10-22"},{"title":"Environmental and Social Management Plan: Rehman Dheri, January 2024","url":"https://old.kptourism.com/uploads/images/kite/1706169526668-clean-version-of-esmp-for-rehman-dheri-site-di-khan---25-jan-2024.pdf","publisher":"Khyber Pakhtunkhwa Integrated Tourism Development Project","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"UNESCO description close-read; Kenoyer specific indexed research passage read; ESMP direct URL404, indexed introduction read only, not represented as full PDF inspection. UNESCO erroneous phase-I enddate omitted. Approximately180words UNESCO,110Kenoyer,70ESMP; remaining original interpretation.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Identify what the site plan can and cannot reveal about early urban organisation.","wordCount":465,"publicationHold":false,"sortOrder":21}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-badshahi-mosque-and-the-scale-of-congregation','badshahi-mosque-and-the-scale-of-congregation','review','{"id":"story-badshahi-mosque-and-the-scale-of-congregation","type":"story","slug":"badshahi-mosque-and-the-scale-of-congregation","title":"Badshahi Mosque and the scale of congregation","summary":"Badshahi Mosque turns scale into a sequence of thresholds, open court and covered prayer space. Its authority comes from relationships between these spaces, not dimensions alone.","body":[{"type":"paragraph","text":"Badshahi Mosque is often introduced through numbers: the size of its courtyard, the height of its minarets, the capacity of a congregation. Those measurements express magnitude, but the experience of the building is more precise. Its architecture transforms arrival into a sequence, moving from the surrounding city through an elevated entrance into an open field and finally towards the covered prayer space."},{"type":"paragraph","text":"Punjab''s Auqaf Department dates Aurangzeb''s commission to 1671 and completion to 1673. It places the mosque opposite Lahore Fort, across Hazuri Bagh, and identifies red sandstone and marble inlay among its defining materials. The setting matters as much as the individual façade: mosque, garden and fort can be understood together without treating them as one building or one construction campaign."},{"type":"heading","level":2,"text":"A courtyard with direction"},{"type":"paragraph","text":"The federal archaeological catalogue describes a raised platform, an eastern entrance and a large courtyard before the prayer hall. These elements establish a clear directional relationship. The gateway gathers movement into a threshold; the court releases it into a much wider space; the prayer front gives that openness a destination."},{"type":"paragraph","text":"Empty space here is architectural substance. It allows the principal elevations to be seen at a distance and accommodates changing patterns of gathering. An uncrowded photograph can make the court appear purely contemplative, while a large congregation reveals another capacity of the same design. Neither image alone describes its full purpose."},{"type":"paragraph","text":"Look at the relationship between the horizontal prayer front and the tall corner minarets. The towers frame the complex at the scale of the city, while repeated openings help the eye read the much longer elevation. Marble accents sharpen the edges and features of the red surface. Authority is produced by the agreement between these scales rather than by ornament applied everywhere with equal intensity."},{"type":"heading","level":2,"text":"The building beyond its front"},{"type":"paragraph","text":"The Department of Archaeology''s account describes the interior as a sequence of halls and a central vaulted space. This is a useful correction to the famous frontal view. A mosque is an arrangement of routes, sheltered areas and places of prayer, not merely a picture of domes. Even when access is limited, the exterior should be read as the boundary of inhabited spaces."},{"type":"paragraph","text":"Conservation introduces another scale of attention. In its account of work begun in December 2022, the Walled City of Lahore Authority discusses entrance-area and rear-chamber work and roof waterproofing. That dated project description should not be converted into a claim that all work is now finished. It does show why a monumental image depends on less conspicuous tasks, including controlling water at the roof."},{"type":"paragraph","text":"Badshahi Mosque remains a religious place as well as a celebrated monument. Observe prayer activity, follow local access instructions and avoid treating worshippers as photographic props. The most rewarding architectural reading combines the long view with the human one: a large composition made meaningful by people moving, pausing and gathering within it."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Lahore","relatedDistrictIds":["punjab-lahore"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6467"],"relatedStoryIds":[],"contentType":"heritage-place","seo":{"title":"Badshahi Mosque and the scale of congregation | Virsapur Archives","description":"Badshahi Mosque turns scale into a sequence of thresholds, open court and covered prayer space. Its authority comes from relationships between these spaces, not dimensions alone.","primaryKeyword":"Badshahi Mosque heritage","socialTitle":"Badshahi Mosque and the scale of congregation","socialDescription":"Badshahi Mosque turns scale into a sequence of thresholds, open court and covered prayer space. Its authority comes from relationships between these spaces, not dimensions alone."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Badshahi Mosque","url":"https://auqaf.punjab.gov.pk/index.php/badshahi-mosque","publisher":"Punjab Auqaf and Religious Affairs Department","accessDate":"2026-10-22"},{"title":"Badshahi Mosque","url":"https://doam.gov.pk/public/sites/6467","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Badshahi Mosque conservation","url":"https://walledcitylahore.gop.pk/badshahi-mosque/","publisher":"Walled City of Lahore Authority","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Auqaf commission1671/completion1673,materials/setting;DOAM platform/eastgateway/court/hall,minarets; corrupt court dimension49.2squaremetres omitted. WCLA dated conservation scope not claimedcompleted. Original spatial analysis distinguished from history.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain courtyard and prayer-hall relationships without repeating visitor rankings or capacity claims.","wordCount":467,"publicationHold":false,"sortOrder":22}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-wazir-khan-mosque-surfaces-that-reward-close-looking','wazir-khan-mosque-surfaces-that-reward-close-looking','review','{"id":"story-wazir-khan-mosque-surfaces-that-reward-close-looking","type":"story","slug":"wazir-khan-mosque-surfaces-that-reward-close-looking","title":"Wazir Khan Mosque: surfaces that reward close looking","summary":"Wazir Khan Mosque rewards attention at several distances: a civic presence in the old city, a finely patterned architectural surface and fragile painted work requiring careful documentation.","body":[{"type":"paragraph","text":"Wazir Khan Mosque changes as you approach it. From farther away, its mass and minarets establish a recognisable place in Lahore''s old city. Closer to the walls, broad coloured areas resolve into smaller units, inscriptions and floral patterns. Inside, painted surfaces call for a different kind of looking. The building rewards changes in distance rather than one definitive viewpoint."},{"type":"paragraph","text":"The Aga Khan Development Network dates its construction to 1634–35 under Hakim Ilmuddin, the governor of Punjab remembered as Wazir Khan. That patronage belongs to the mosque''s history, but the surroundings are equally important to its architectural identity. An urban mosque receives people through streets, shops and public space; its threshold is part of a larger inhabited fabric."},{"type":"heading","level":2,"text":"Two kinds of surface"},{"type":"paragraph","text":"The Walled City of Lahore Authority distinguishes the glazed ceramic decoration of the exterior from interior naqqashi wall painting. These should not be flattened into a single category of colourful ornament. Ceramic units and painted plaster have different material properties, assembly methods and conservation needs. Their appearance may be related, but the work that produces and preserves them is not identical."},{"type":"paragraph","text":"The Authority also identifies the Calligraphers'' Bazaar crossing the entrance axis. This detail complicates the idea of a monument separated from everyday activity. The route to prayer belongs to a setting of exchange and specialised work. Architecture can give public and devotional life adjacent spaces without making them the same activity."},{"type":"heading","level":2,"text":"The ground outside matters"},{"type":"paragraph","text":"AKDN''s conservation account explains that accumulated street levels had risen substantially beside the mosque, creating problems at its lower fabric. Its work on the northern façade, completed in 2016, included attention to the adjoining street and former shop spaces. Work around the chowk likewise addressed levels and the relationship between the mosque and its public foreground."},{"type":"paragraph","text":"This is a useful way to understand conservation: the decorated wall cannot be treated independently of what touches it. A raised surface can redirect water or conceal a plinth; a repaired façade can remain vulnerable if those conditions persist. The view admired by the visitor depends partly on decisions made at pavement level."},{"type":"heading","level":2,"text":"Looking with a record"},{"type":"paragraph","text":"CyArk documents a 2015 collaboration with Lahore University of Management Sciences that used digital recording and field training at the mosque. Its account describes attention to cracks, frescoes and minaret geometry. These are dated observations used to create a baseline, not a current engineering verdict on every feature."},{"type":"paragraph","text":"Documentation also changes the meaning of a detailed photograph. A decorative panel can be recorded for comparison, allowing later observers to distinguish stable variation from material loss. Repeated images from known positions become evidence rather than a succession of attractive impressions."},{"type":"paragraph","text":"For a visitor, the practical lesson is simple: look closely without touching, and allow more than one scale of attention. Follow the building from street to gateway, from court to prayer hall, and from overall pattern to individual material. Wazir Khan Mosque''s richness emerges through those relationships, not through colour alone."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Lahore","relatedDistrictIds":["punjab-lahore"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6466"],"relatedStoryIds":["story-tile-mosaic-and-glazed-brick-not-interchangeable-terms","story-calligraphy-as-part-of-an-architectural-facade","story-one-glazed-tile-many-conservation-questions","story-lahores-old-city-through-routes-rather-than-monuments"],"contentType":"heritage-place","seo":{"title":"Wazir Khan Mosque: surfaces that reward close looking | Virsapur Archives","description":"Wazir Khan Mosque rewards attention at several distances: a civic presence in the old city, a finely patterned architectural surface and fragile painted work requiring careful documentation.","primaryKeyword":"Wazir Khan Mosque heritage","socialTitle":"Wazir Khan Mosque: surfaces that reward close looking","socialDescription":"Wazir Khan Mosque rewards attention at several distances: a civic presence in the old city, a finely patterned architectural surface and fragile painted work requiring careful documentation."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Masjid Wazir Khan: In depth","url":"https://www.cyark.org/projects/masjid-wazir-khan/in-depth","publisher":"CyArk","accessDate":"2026-10-22"},{"title":"Walled City of Lahore conservation","url":"https://www-hetz2.the.akdn/en/where-we-work/south-asia/pakistan/walled-city-of-lahore-conservation-pakistan","publisher":"Aga Khan Development Network","accessDate":"2026-10-22"},{"title":"Historic monuments: Wazir Khan Mosque","url":"https://walledcitylahore.gop.pk/monuments2/","publisher":"Walled City of Lahore Authority","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"AKDN construction1634–35HakimIlmuddin,streetfill/northfacade/chowk under190derivedwords;CyArk2015survey under150;WCLA tile/naqqashi/bazaar under150. No current structuraldiagnosis from2015documentation.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Read the relation between architectural space, painting, tile and calligraphy.","wordCount":478,"publicationHold":false,"sortOrder":23}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-jahangirs-tomb-at-ground-level','jahangirs-tomb-at-ground-level','review','{"id":"story-jahangirs-tomb-at-ground-level","type":"story","slug":"jahangirs-tomb-at-ground-level","title":"Jahangir’s Tomb at ground level","summary":"Jahangir’s tomb is best understood through its low body, shaded circulation and concentrated stonework, with the surrounding Shahdara ensemble extending the story beyond one mausoleum.","body":[{"type":"paragraph","text":"At Jahangir''s tomb, it is worth resisting the instinct to look immediately upward. The corner towers draw attention, yet the main building is deliberately low. Its long elevations, sheltered verandah and repeated openings give the monument a strong horizontal character. Much of its architectural interest lies at the level of a person walking around it."},{"type":"paragraph","text":"The Walled City of Lahore Authority records Jahangir''s death in 1627 and the completion of the mausoleum under Shah Jahan in 1637. It identifies the burial setting as Dilkusha Bagh, associated with Nur Jahan, and describes a square garden organised in the chaharbagh manner. The garden is therefore not a decorative margin around the tomb. It establishes the framework within which the building is approached and understood."},{"type":"heading","level":2,"text":"Moving around, moving inward"},{"type":"paragraph","text":"The federal archaeological description identifies an arcaded verandah before a series of rooms, with vaulted approaches leading towards the central burial chamber. These successive spaces make the transition inward gradual. Open air, shade and enclosed chamber are distinct conditions, each shaping what can be seen and how the visitor moves."},{"type":"paragraph","text":"Try reading an elevation as both a surface and an inhabited edge. From the garden, the repeated arches create a measured rhythm. Within the verandah, the same openings become frames for views outward. A façade that appears flat in a photograph is also the boundary of a route."},{"type":"paragraph","text":"Red sandstone and light-coloured inlay give that route its visual structure. Pakistan''s UNESCO Tentative List description records panel decoration across the exterior and richly worked corner towers. Detail can be followed without assuming that every surviving surface is untouched seventeenth-century fabric. A material history includes repair as well as initial construction."},{"type":"heading","level":2,"text":"A small object within a large composition"},{"type":"paragraph","text":"Inside, the Walled City Authority describes a marble cenotaph marking the grave beneath and bearing floral stone inlay and the attributes of Allah. Distinguishing the memorial above from the burial below avoids a common confusion. The cenotaph concentrates skilled work and remembrance at the centre of a much larger spatial arrangement."},{"type":"paragraph","text":"The change in scale is important. Garden paths and building elevations organise movement over considerable distances, while stone joints, coloured inlay and inscriptions ask for slow, close attention. The tomb does not rely on one uninterrupted experience of grandeur; it brings different kinds of attention into sequence."},{"type":"heading","level":2,"text":"Shahdara as an ensemble"},{"type":"paragraph","text":"The Tentative List entry groups Jahangir''s tomb with Asif Khan''s tomb and Akbari Sarai. The sarai''s courtyard, cells and gateways and Asif Khan''s domed octagonal mausoleum broaden the architectural comparison. They should not be mistaken for parts of a single tomb, but neither should they disappear from its interpretation."},{"type":"paragraph","text":"Seeing these neighbouring structures together reveals differences in enclosure, silhouette and circulation. The low mass of Jahangir''s mausoleum becomes more distinctive when it is not treated as a generic Mughal tomb. Begin with the ground-level route, allow the detail to draw you closer, and then return to the larger garden and ensemble. Each scale clarifies the others."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Lahore","relatedDistrictIds":["punjab-lahore"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6479"],"relatedStoryIds":["story-how-a-mughal-charbagh-organises-movement","story-ghalibkari-and-the-shaping-of-a-decorated-ceiling","story-jali-screens-light-privacy-and-stonework","story-a-cenotaph-is-not-the-burial-itself"],"contentType":"heritage-place","seo":{"title":"Jahangir’s Tomb at ground level | Virsapur Archives","description":"Jahangir’s tomb is best understood through its low body, shaded circulation and concentrated stonework, with the surrounding Shahdara ensemble extending the story beyond one mausoleum.","primaryKeyword":"Jahangir''s Tomb heritage","socialTitle":"Jahangir’s Tomb at ground level","socialDescription":"Jahangir’s tomb is best understood through its low body, shaded circulation and concentrated stonework, with the surrounding Shahdara ensemble extending the story beyond one mausoleum."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Jahangir Tomb","url":"https://walledcitylahore.gop.pk/jahangir-tomb/","publisher":"Walled City of Lahore Authority","accessDate":"2026-10-22"},{"title":"Tombs of Jahangir, Asif Khan and Akbari Sarai","url":"https://whc.unesco.org/en/tentativelists/1279/","publisher":"Pakistan submission to UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Tomb of Jahangir","url":"https://doam.gov.pk/public/sites/6479","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"WCLA death1627completion1637gardens/verandahcenotaph~170;UNESCO ensemble/corner towers/redstone~145;DOAM chamber approaches/decoration~100. IncorrectUNESCOcoordinates and apparentShahJahanTombtypography not used; no lostdome claim.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain the low central monument and garden composition rather than another emperor biography.","wordCount":475,"publicationHold":false,"sortOrder":24}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-harappa-after-the-excavation-trench','harappa-after-the-excavation-trench','review','{"id":"story-harappa-after-the-excavation-trench","type":"story","slug":"harappa-after-the-excavation-trench","title":"Harappa after the excavation trench","summary":"Harappa’s archaeology continues after excavation through the study of objects, dates and recorded contexts. Small finds can reveal activities that monumental ruins alone cannot explain.","body":[{"type":"paragraph","text":"An excavation trench is the most visible symbol of archaeology, but it is not where all the important work happens. At Harappa, the interpretation of a small bone tool, a ceramic fragment or a dated deposit can change how an entire settlement is understood. The city survives not only in exposed architecture but also in records and collections that preserve relationships no longer visible on the ground."},{"type":"paragraph","text":"The federal archaeological catalogue recalls a damaging episode in the site''s modern history: ancient bricks were removed for railway construction in the nineteenth century. It also identifies the excavations begun in 1921. These are different kinds of intervention. One extracted building material; the other attempted to recover evidence. Neither can be understood simply by counting how much ground was disturbed."},{"type":"heading","level":2,"text":"A find needs a context"},{"type":"paragraph","text":"An object removed without a record loses part of its meaning. Its material and shape may remain available for study, but its relationship to a floor, wall, burial or sequence of deposits may be irretrievable. This is why archaeological documentation is not paperwork added after discovery. It is part of the evidence itself."},{"type":"paragraph","text":"Kenoyer and Meadow''s account of Harappa''s Ravi Phase explains how analysis of excavated materials and radiocarbon dates enabled a more detailed settlement chronology. A famous site name therefore covers a changing history, not one undifferentiated moment called the Indus civilisation. Separating phases makes it possible to ask when particular objects, practices and building traditions appeared."},{"type":"heading","level":2,"text":"Small tools, substantial questions"},{"type":"paragraph","text":"The authors illustrate bone points, an awl, polished rib fragments and a perforated piece. They suggest possible connections with basketry, spinning or weaving for some of these objects. The cautious wording matters. A shape can support a functional interpretation without proving one exclusive use."},{"type":"paragraph","text":"Such finds redirect attention towards activities that are easily lost in monumental accounts of the past. Producing thread or working fibres requires skill, repeated bodily movements and appropriate tools. The surviving object is only one part of that process. Archaeology must reconstruct the relationship between materials and actions while acknowledging where direct evidence is missing."},{"type":"paragraph","text":"A catalogue label should preserve that distinction. “Possible weaving tool” is not a weaker version of a confident but unsupported identification; it is a more accurate description of what is known. Uncertainty can indicate disciplined analysis rather than a failure to reach an answer."},{"type":"heading","level":2,"text":"The excavation has a history too"},{"type":"paragraph","text":"Gregory Possehl''s review of research at Harappa describes the multidisciplinary programme undertaken with Pakistan''s Department of Archaeology and Museums during the later twentieth century. Different specialists and institutions brought different questions to the same site. Published reports allow those questions, methods and conclusions to be revisited."},{"type":"paragraph","text":"For a visitor, the museum and excavation record therefore belong alongside the mounds. Ask where an object was found, how it was dated and which interpretation its evidence actually supports. Harappa becomes richer when it is seen not as a completed picture of an ancient city, but as a place where careful study continues to turn surviving traces into historically meaningful relationships."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Sahiwal","relatedDistrictIds":["punjab-sahiwal"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6579"],"relatedStoryIds":["story-how-archaeologists-build-an-indus-chronology","story-seeds-from-a-trench-what-archaeobotany-asks","story-what-changing-brick-sizes-can-and-cannot-prove","story-indus-exchange-without-a-modern-trade-map"],"contentType":"heritage-place","seo":{"title":"Harappa after the excavation trench | Virsapur Archives","description":"Harappa’s archaeology continues after excavation through the study of objects, dates and recorded contexts. Small finds can reveal activities that monumental ruins alone cannot explain.","primaryKeyword":"Harappa heritage","socialTitle":"Harappa after the excavation trench","socialDescription":"Harappa’s archaeology continues after excavation through the study of objects, dates and recorded contexts. Small finds can reveal activities that monumental ruins alone cannot explain."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Harappa","url":"https://doam.gov.pk/public/sites/6579","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"The Ravi Phase: A New Cultural Manifestation at Harappa","url":"https://www.harappa.com/content/ravi-phase-new-cultural-manifestation-harappa","publisher":"Jonathan Mark Kenoyer and Richard H. Meadow","accessDate":"2026-10-22"},{"title":"Harappa Excavations 1986–1990: history of archaeological research","url":"https://www.harappa.com/sites/default/files/pdf/Harappa1986-90_02_Possehl-History.pdf","publisher":"Gregory L. Possehl, Harappa excavation publication","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM railwaybrickloss1856/excavation1921~80;KenoyerMeadowRaviphaseobjects/radiocarbondates~175;Possehl indexedintro multidisciplinaryPakistanDOAMcollaboration~70. No certaingranary/workersquarterinterpretation; toolspossiblefunctionretained.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Follow how excavated material becomes an interpretation of everyday urban life.","wordCount":486,"publicationHold":false,"sortOrder":25}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-derawar-fort-and-the-need-for-water','derawar-fort-and-the-need-for-water','review','{"id":"story-derawar-fort-and-the-need-for-water","type":"story","slug":"derawar-fort-and-the-need-for-water","title":"Derawar Fort and the need for water","summary":"Derawar’s powerful walls belong to a desert network sustained by access to water. Reading wells, tanks and routes alongside bastions gives the fort a more complete geography.","body":[{"type":"paragraph","text":"Derawar Fort presents a powerful outline: repeated rounded bastions rising above the flat country of Cholistan. The first impression is defensive, but a fort cannot be understood through walls alone. People occupying it needed water, supplies and connections to routes beyond the enclosure. In this landscape, those less visible requirements are central to the story."},{"type":"paragraph","text":"Pakistan''s Tentative List submission places Derawar within a wider group of Cholistan forts, rather than presenting it as an isolated desert monument. It relates the network to caravan movement and suggests that access to water helps explain the distribution of fortifications. This is an interpretation of the landscape, not permission to invent a detailed account of every historic journey or garrison."},{"type":"heading","level":2,"text":"Looking past the skyline"},{"type":"paragraph","text":"The Department of Archaeology and Museums records forty bastions, a southern gateway, a well within the fort and a tank outside it. The water features alter the questions a visitor can ask. Where was water available? How did access relate to the enclosure? Which facilities lay inside a defended boundary and which required movement beyond it?"},{"type":"paragraph","text":"These questions do not require a dramatic siege story. Ordinary occupation would itself have created demands. A wall might control entry, but it could not remove the need for replenishment, maintenance and labour. The fort''s apparent self-sufficiency in a distant photograph is therefore misleading: an enclosed building remains connected to a wider environment."},{"type":"paragraph","text":"The repeated bastions should also be read as constructed surfaces. The Tentative List account draws attention to patterned brickwork and surviving interior decoration. Defence and visual expression were not necessarily separate concerns. A stronghold could communicate status through the treatment of its walls while accommodating a range of activities within them."},{"type":"heading","level":2,"text":"A network, not an empty desert"},{"type":"paragraph","text":"The UNESCO-hosted submission names other forts including Marotgarh, Maujgarh, Khairgarh and Islamgarh. Their inclusion encourages a regional view. A route has stages; access to resources varies; political boundaries and patterns of occupation change. The most prominent surviving structure cannot by itself stand for all those relationships."},{"type":"paragraph","text":"Calling the surroundings empty would also obscure the difference between a lightly built landscape and one without human knowledge. Water sources, paths and seasonal conditions can be significant even where they leave no monumental façade. The fort is a conspicuous element within that geography, not its only meaningful feature."},{"type":"heading","level":2,"text":"Keeping the chronology proportionate"},{"type":"paragraph","text":"The federal catalogue records Sadiq Muhammad Khan''s capture of the fort in 1733 while acknowledging uncertainty about earlier history. It is safer to distinguish documented episodes from repeated foundation traditions than to attach a precise ancient date to every visible wall. Repair and rebuilding can substantially change a structure that occupies an older location."},{"type":"paragraph","text":"Derawar''s value does not depend on settling every uncertain beginning. Its surviving mass, water features and position among other forts already support a compelling account of architecture in a demanding environment. Start with the bastions, but let the well, tank and routes expand the view. The most useful image of the fort includes what sustained it."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Bahawalpur","relatedDistrictIds":["punjab-bahawalpur"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6959"],"relatedStoryIds":["story-the-cholistan-fort-network-and-its-uneven-survival","story-cholistans-wells-forts-and-traces-of-water","story-world-heritage-is-not-the-same-as-the-tentative-list"],"contentType":"heritage-place","seo":{"title":"Derawar Fort and the need for water | Virsapur Archives","description":"Derawar’s powerful walls belong to a desert network sustained by access to water. Reading wells, tanks and routes alongside bastions gives the fort a more complete geography.","primaryKeyword":"Derawar Fort heritage","socialTitle":"Derawar Fort and the need for water","socialDescription":"Derawar’s powerful walls belong to a desert network sustained by access to water. Reading wells, tanks and routes alongside bastions gives the fort a more complete geography."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Derawar and the Desert Forts of Cholistan","url":"https://whc.unesco.org/en/tentativelists/6108/","publisher":"Pakistan submission to UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Derawar Fort","url":"https://doam.gov.pk/public/sites/6959","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"UNESCO route/water interpretation explicitlypresumed,fortnetwork~190derivedwords;DOAM40bastions,southgate,wellandtank,1733~120. Distinctoriginalsystemsreading not inventedhistoricoperations. Contradictorydimensionsandearlyfoundinglegendomitted.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Connect visible fortification to desert water and route systems, with tentative status explained.","wordCount":481,"publicationHold":false,"sortOrder":26}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-hiran-minar-a-memorial-in-a-water-landscape','hiran-minar-a-memorial-in-a-water-landscape','review','{"id":"story-hiran-minar-a-memorial-in-a-water-landscape","type":"story","slug":"hiran-minar-a-memorial-in-a-water-landscape","title":"Hiran Minar: a memorial in a water landscape","summary":"Hiran Minar combines an imperial animal memorial with a carefully arranged tank and pavilion. Its landscape is made through water collection, controlled movement and contrasting architectural forms.","body":[{"type":"paragraph","text":"Hiran Minar is more than a tower with a memorable origin story. Near Sheikhupura, the minar stands in relation to a large tank, a central pavilion and the route that connects the pavilion to the bank. Vertical monument, broad water surface and narrow crossing form a composition whose parts make most sense together."},{"type":"paragraph","text":"The federal archaeological catalogue associates the tower with Jahangir''s memorial to a favoured antelope named Mansraj. That association explains the monument''s name and commemorative purpose, but it should not consume the whole visit. The site also offers an unusually clear opportunity to examine the relationship between memory, pleasure architecture and water management."},{"type":"heading","level":2,"text":"A tower beside a horizontal landscape"},{"type":"paragraph","text":"The catalogue describes a tapering brick tower with lime-plastered surfaces and openings that admitted light. Its narrow, rising form contrasts with the tank''s broad enclosure. Seen together, the two make scale legible: the tower gives the eye a vertical measure, while the tank establishes distance across the ground."},{"type":"paragraph","text":"The UNESCO-hosted Tentative List description records an octagonal pavilion on a platform within the water and a causeway connecting it to a gateway. A crossing like this does more than provide access. It separates the experience of the pavilion from the surrounding bank, making arrival an extended movement through the composition."},{"type":"paragraph","text":"Consider the sequence rather than only its reflection in a photograph. A visitor approaches an edge, passes through an architectural threshold and follows a defined route towards a building surrounded by water. The pavilion''s position changes the relationship between near and far, centre and boundary. Its apparent simplicity depends on careful spatial decisions."},{"type":"heading","level":2,"text":"Water had to reach the tank"},{"type":"paragraph","text":"The Tentative List account describes a channel from the Aik rivulet and a system for collecting rainwater from the catchment. These features move the interpretation beyond the ornamental. A tank is an engineered receptacle within a larger hydrological setting; its surface does not explain its supply by itself."},{"type":"paragraph","text":"Water also makes the monument variable. The appearance of a pavilion, the visibility of edges and the extent of reflections depend on conditions. A particular photograph should not be treated as a permanent specification of the site. Understanding the intended arrangement requires distinguishing built form from a changing water level."},{"type":"heading","level":2,"text":"A historic landscape and a future plan"},{"type":"paragraph","text":"The Urban Unit''s published document is explicitly an eco-tourism and restoration master plan with a 2055 horizon. It brings the site into contemporary discussions about access and management, but a proposal is not evidence that every illustrated facility exists. Readers should keep intended interventions separate from the historic elements they are interpreting."},{"type":"paragraph","text":"That separation protects the clarity of Hiran Minar''s story. The memorial association, the tower''s fabric, the tank''s supply and the pavilion''s approach are connected but different subjects. Giving each its proper scale makes the site more than an anecdote about an emperor''s animal: it becomes a landscape in which remembrance and technical organisation were given a deliberate architectural form."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Sheikhupura","relatedDistrictIds":["punjab-sheikhupura"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6423"],"relatedStoryIds":["story-the-pavilion-a-small-building-with-several-jobs"],"contentType":"heritage-place","seo":{"title":"Hiran Minar: a memorial in a water landscape | Virsapur Archives","description":"Hiran Minar combines an imperial animal memorial with a carefully arranged tank and pavilion. Its landscape is made through water collection, controlled movement and contrasting architectural forms.","primaryKeyword":"Hiran Minar heritage","socialTitle":"Hiran Minar: a memorial in a water landscape","socialDescription":"Hiran Minar combines an imperial animal memorial with a carefully arranged tank and pavilion. Its landscape is made through water collection, controlled movement and contrasting architectural forms."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Hiran Minar","url":"https://doam.gov.pk/public/sites/6423","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Hiran Minar and Tank, Sheikhupura","url":"https://whc.unesco.org/en/tentativelists/1281/","publisher":"Pakistan submission to UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Hiran Minar Eco-Tourism and Restoration Master Plan, 2055","url":"https://urbanunit.gov.pk/Download/publications/Files/8/2025/Hiran%20Minar%20Master%20Plan_852025.pdf","publisher":"The Urban Unit, Government of Punjab","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMpetantelope/taperbrick/lime~95;UNESCOcatchment/Aikchannel/causeway/octagonalpavilion~185;UrbanUnitcover/disclaimer/contentsreadfuture2055masterplanonly~60. Conflictingtowerstoreys/paviliondates omitted. No implementationclaim.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Distinguish the commemorative tower from the later tank and pavilion ensemble.","wordCount":466,"publicationHold":false,"sortOrder":27}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-shah-rukn-e-alam-reading-a-monumental-silhouette','shah-rukn-e-alam-reading-a-monumental-silhouette','review','{"id":"story-shah-rukn-e-alam-reading-a-monumental-silhouette","type":"story","slug":"shah-rukn-e-alam-reading-a-monumental-silhouette","title":"Shah Rukn-e-Alam: reading a monumental silhouette","summary":"Shah Rukn-e-Alam’s mausoleum combines a powerful octagonal mass with detailed brick, timber and tile work. Its twentieth-century conservation also forms part of the building’s material history.","body":[{"type":"paragraph","text":"The mausoleum of Shah Rukn-e-Alam is immediately recognisable in Multan''s skyline, but its silhouette is only the beginning of its architectural character. From a distance, a substantial lower body supports progressively lighter forms and the dome. Close to the building, brickwork, timber and coloured tile divide that mass into a much more intricate construction."},{"type":"paragraph","text":"Pakistan''s Tentative List submission dates the tomb to the early fourteenth century and associates its construction with Ghiyasuddin Tughluq. The building''s significance is not confined to that dynastic attribution. It is also a devotional place and a major work of regional craftsmanship, with a material history that includes substantial modern conservation."},{"type":"heading","level":2,"text":"Making a large mass readable"},{"type":"paragraph","text":"The Department of Archaeology describes an octagonal base with projecting, tapering supports at its angles. Horizontal courses and changes in surface treatment help organise the exterior, while the upper stages lead towards the dome. These features prevent the building from reading as an undifferentiated block."},{"type":"paragraph","text":"The octagon is important at both scales. In the overall view, it provides a transition between a broad base and the rounded upper form. At ground level, each face and angle changes the view as a person moves around the building. The monument is not exhausted by a single frontal photograph."},{"type":"paragraph","text":"The catalogue also records the relationship of burnt brick and timber framing and the use of brick, tile and wood in the surface articulation. Materials that may appear decorative are part of a more complex assembly. A coloured band can be read visually while also prompting questions about how it was made, fixed and maintained."},{"type":"heading","level":2,"text":"Conservation as a chapter of construction"},{"type":"paragraph","text":"The Aga Khan Award for Architecture''s project account describes a major conservation campaign beginning in late 1971 and completed six years later. It included work on foundations and lower brick walls, replacement of lost tiles, repairs to damaged woodwork and treatment of the surrounding site. The surviving monument therefore should not be presented as entirely untouched medieval fabric."},{"type":"paragraph","text":"The same account places unusual emphasis on craft training. Experienced practitioners taught thirty-three novices in skills including Multan glazed tile work, wood carving and terracotta. This makes the project more than an episode of structural repair. It linked the care of an existing monument to the transmission of practical knowledge."},{"type":"paragraph","text":"That history changes how a visitor might look at a newly regular surface. Repair is not automatically a defect in authenticity, nor is every replacement beyond question. The useful enquiry is what was replaced, why, by whom and with what documentation. A conservation record helps distinguish informed intervention from an invented appearance of age."},{"type":"heading","level":2,"text":"From skyline to handwork"},{"type":"paragraph","text":"Move between the broad and the close view without allowing either to dominate. The dome and tapering body explain why the mausoleum carries such visual weight; joints, bands and worked surfaces reveal the many smaller acts through which that effect was achieved. Shah Rukn-e-Alam''s architectural presence belongs to this relationship between monumental form, devotional meaning and continuing skilled care."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Multan","relatedDistrictIds":["punjab-multan"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6431"],"relatedStoryIds":["story-brick-bonds-as-evidence-of-building-change","story-tile-mosaic-and-glazed-brick-not-interchangeable-terms","story-multani-kashikari-as-living-knowledge","story-multans-many-building-histories"],"contentType":"heritage-place","seo":{"title":"Shah Rukn-e-Alam: reading a monumental silhouette | Virsapur Archives","description":"Shah Rukn-e-Alam’s mausoleum combines a powerful octagonal mass with detailed brick, timber and tile work. Its twentieth-century conservation also forms part of the building’s material history.","primaryKeyword":"Shah Rukn-e-Alam heritage","socialTitle":"Shah Rukn-e-Alam: reading a monumental silhouette","socialDescription":"Shah Rukn-e-Alam’s mausoleum combines a powerful octagonal mass with detailed brick, timber and tile work. Its twentieth-century conservation also forms part of the building’s material history."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Tomb of Shah Rukn-e-Alam","url":"https://doam.gov.pk/public/sites/6431","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Tomb of Shah Rukn-i-Alam conservation project","url":"https://www-hetz2.the.akdn/en/how-we-work/our-agencies/aga-khan-trust-culture/akaa/tomb-shah-rukn-i-alam","publisher":"Aga Khan Development Network / Aga Khan Award for Architecture","accessDate":"2026-10-22"},{"title":"Tomb of Shah Rukn-e-Alam","url":"https://whc.unesco.org/en/tentativelists/1884/","publisher":"Pakistan submission to UNESCO World Heritage Centre","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMgeometry/timbers/stringcourses~180;AKDN1971–77repair/training33novices~180;UNESCOearly14c~25. Do notrepeatAuqafcontradictory1330burialbefore1335death. Originalscaleanalysis.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain how the building’s staged mass and materials create its recognisable form.","wordCount":477,"publicationHold":false,"sortOrder":28}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-bibi-jawindis-tomb-and-the-problem-of-survival','bibi-jawindis-tomb-and-the-problem-of-survival','review','{"id":"story-bibi-jawindis-tomb-and-the-problem-of-survival","type":"story","slug":"bibi-jawindis-tomb-and-the-problem-of-survival","title":"Bibi Jawindi’s Tomb and the problem of survival","summary":"Bibi Jawindi’s partially surviving tomb makes its construction unusually visible. The challenge is to understand and protect that evidence without romanticising loss or confusing repair with recovery.","body":[{"type":"paragraph","text":"The surviving portion of Bibi Jawindi''s tomb at Uch can be visually arresting because it is incomplete. The broken enclosure reveals surfaces and structural relationships that a fully intact building would conceal. Yet this visibility comes from loss. An architectural reading should acknowledge the power of the view without treating damage as the monument''s ideal condition."},{"type":"paragraph","text":"Pakistan''s Tentative List submission places the tomb within a group of five monuments at Uch and dates it to around 1494. It describes a broader architectural ensemble associated with religious scholarship and devotional life. Bibi Jawindi''s tomb is therefore not a solitary sculptural object in a vacant landscape, even when a tightly framed photograph makes it appear so."},{"type":"heading","level":2,"text":"A form assembled in stages"},{"type":"paragraph","text":"The federal catalogue describes an octagonal base, tapering corner supports and a rising sequence of architectural stages. Recessed arches and bands of glazed decoration articulate the brick surfaces. The large form is legible at a distance, while the tile patterns introduce a much smaller scale of work."},{"type":"paragraph","text":"The relationship between the octagon and the upper structure is especially useful to observe. A dome requires a transition from the supporting enclosure beneath it. Where fabric has been lost, the profile can expose something of that construction. This is evidence to study carefully, not an invitation to climb unstable remains for a clearer photograph."},{"type":"paragraph","text":"Tile also needs to be understood as material rather than colour alone. Individual pieces belong to a surface attached to a larger wall. If the support moves or moisture affects the assembly, the decorative layer is involved in a structural and environmental problem. A striking blue-and-white pattern does not exist independently of the masonry carrying it."},{"type":"heading","level":2,"text":"The history of repair matters"},{"type":"paragraph","text":"World Monuments Fund''s 2000 Watch catalogue discussed the Uch complex as a conservation concern. Its account identified brick laid in earth mortars and warned that some ad hoc cement-based repairs had created problems. That is a dated institutional assessment, not a claim that every condition described remains unchanged today."},{"type":"paragraph","text":"The report nevertheless illustrates an enduring question. A repair that looks stronger or more complete can behave differently from the surrounding historic fabric. Compatibility matters alongside appearance. Before judging an intervention by how neatly it fills a gap, ask how it affects the existing structure and whether its purpose and materials are recorded."},{"type":"heading","level":2,"text":"More than a picturesque fragment"},{"type":"paragraph","text":"The UNESCO-hosted description notes that erosion has made aspects of the tombs'' profiles and interiors visible. Seeing this clearly requires two ideas at once: a damaged structure can preserve valuable information, and continued damage can destroy that information. Documentation is essential, but it cannot replace the fabric it records."},{"type":"paragraph","text":"At Uch, the respectful visitor keeps the individual monument in relation to its neighbouring tombs, mosque and living religious setting. The strongest interpretation neither invents an intact past from imagination nor celebrates the ruin as merely beautiful. It follows the surviving evidence, recognises the work needed for its care and leaves room for the site''s continuing significance beyond the photograph."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Bahawalpur","relatedDistrictIds":["punjab-bahawalpur"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6552"],"relatedStoryIds":["story-women-remembered-in-monumental-tombs"],"contentType":"heritage-place","seo":{"title":"Bibi Jawindi’s Tomb and the problem of survival | Virsapur Archives","description":"Bibi Jawindi’s partially surviving tomb makes its construction unusually visible. The challenge is to understand and protect that evidence without romanticising loss or confusing repair with recovery.","primaryKeyword":"Bibi Jawindi''s Tomb heritage","socialTitle":"Bibi Jawindi’s Tomb and the problem of survival","socialDescription":"Bibi Jawindi’s partially surviving tomb makes its construction unusually visible. The challenge is to understand and protect that evidence without romanticising loss or confusing repair with recovery."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Tomb of Bibi Jawindi","url":"https://doam.gov.pk/public/sites/6552","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Uch monuments Tentative List entry","url":"https://whc.unesco.org/en/tentativelists/1883/","publisher":"Pakistan submission to UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"World Monuments Watch 2000: Uch Monument Complex","url":"https://www.wmf.org/sites/default/files/article/pdfs/Watch_Catalog_2000.pdf","publisher":"World Monuments Fund","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMform/tile/stair~135;UNESCOensemble/datecirca1494/erodedprofiles~145;WMF2000indexedUchentryearthmortars/incompatiblecement/trainingplanning~150. No unverifiedsinglefloodcause/date or currentconditionclaim; broadercommentaryoriginal.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Describe the surviving fragment and conservation issues without reconstructing missing fabric as fact.","wordCount":483,"publicationHold":false,"sortOrder":29}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-kot-diji-separating-the-fort-from-the-archaeological-site','kot-diji-separating-the-fort-from-the-archaeological-site','review','{"id":"story-kot-diji-separating-the-fort-from-the-archaeological-site","type":"story","slug":"kot-diji-separating-the-fort-from-the-archaeological-site","title":"Kot Diji: separating the fort from the archaeological site","summary":"Kot Diji names both a Talpur fort and an ancient archaeological settlement. Separating their dates and evidence reveals two different histories that share a landscape, not a single construction story.","body":[{"type":"paragraph","text":"Kot Diji is a place where one name can carry two very different dates. The dramatic hilltop fort belongs to the Talpur period, while the archaeological settlement associated with the same locality reaches back into the development of the Indus civilisation. Confusing them turns a rich landscape into an impossible claim that the standing fortress is thousands of years old."},{"type":"paragraph","text":"The distinction is straightforward but important. The federal archaeological catalogue records the fort as a stronghold associated with Mir Sohrab Khan. Sindh''s Directorate General of Antiquities separately describes Diji ji Takri, the archaeological mound, and the excavations that helped identify a pre-Harappan cultural phase. These are related through location, not interchangeable historical objects."},{"type":"heading","level":2,"text":"Reading the fort on its own terms"},{"type":"paragraph","text":"The Department of Archaeology describes a steep approach, successive gateways and terraces, stone construction and projecting bastions. Those features belong to a defensive architectural sequence. An entrance is not simply a hole in the outer wall: the approach itself can organise and constrain movement before a person reaches the interior."},{"type":"paragraph","text":"Pakistan''s March 2026 Tentative List submission places the fort in the late-eighteenth-century Talpur context. That is a nomination-stage record, not inscription on the World Heritage List. The document contains differing precise construction dates, so a broad period is more responsible here than false certainty about a single year."},{"type":"paragraph","text":"The fort''s height allows the surrounding landscape to become part of its interpretation. Visibility, approach and the placement of enclosure walls are useful observations. They do not require claims that the fort was literally impregnable or that its defences were never tested. Architectural capacity and documented military events are different kinds of evidence."},{"type":"heading","level":2,"text":"Reading the mound differently"},{"type":"paragraph","text":"At the archaeological site, the evidence works through deposits and objects rather than standing Talpur walls. Sindh''s Antiquities account explains that excavation recovered a sequence of occupation, mud-brick building and distinctive pottery. These findings contributed to understanding developments preceding the mature Harappan cities."},{"type":"paragraph","text":"An archaeological culture is a scholarly way of describing recurring material characteristics; it is not automatically the name an ancient population used for itself. Likewise, shared pottery forms do not prove that all people using them belonged to one political state. The value of the Kot Diji evidence lies in making comparisons and changes investigable, not in supplying an effortless identity label."},{"type":"heading","level":2,"text":"Two histories in one visit"},{"type":"paragraph","text":"The fort and the mound invite different questions. At the fort, examine approach, elevation, masonry and enclosure. At the archaeological settlement, ask how deposits were recorded, which materials distinguish phases and how conclusions depend on excavated context. Neither method can simply be transferred to the other."},{"type":"paragraph","text":"Keeping the two histories distinct does not make the landscape fragmented. It reveals how a locality can acquire significance at widely separated times and for different reasons. The strongest account of Kot Diji holds both stories together while preserving the distance between them: an ancient settlement important to archaeological research, and a much later fortress expressing Talpur power through the control of a prominent site."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"Khairpur","relatedDistrictIds":["sindh-khairpur"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5206"],"relatedStoryIds":[],"contentType":"heritage-place","seo":{"title":"Kot Diji: separating the fort from the archaeological site | Virsapur Archives","description":"Kot Diji names both a Talpur fort and an ancient archaeological settlement. Separating their dates and evidence reveals two different histories that share a landscape, not a single construction story.","primaryKeyword":"Kot Diji Fort heritage","socialTitle":"Kot Diji: separating the fort from the archaeological site","socialDescription":"Kot Diji names both a Talpur fort and an ancient archaeological settlement. Separating their dates and evidence reveals two different histories that share a landscape, not a single construction story."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Kot Diji Fort","url":"https://doam.gov.pk/public/sites/5206","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Diji ji Takri, Kotdiji","url":"https://antiquities.sindhculture.gov.pk/tour/diji-ji-takri-mound-kotdiji-khairpur/","publisher":"Directorate General of Antiquities, Government of Sindh","accessDate":"2026-10-22"},{"title":"Kot Diji Fort Tentative List submission","url":"https://whc.unesco.org/en/tentativelists/6968/","publisher":"Pakistan submission to UNESCO World Heritage Centre","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMfortapproach/gates/stone~120;Sindharchaeologicalmoundexcavationceramicsmudbrick~170;UNESCO2026submission/Talpur/status~75. Nomination internally1797vs1785–95notresolveduselate18c; claimfortatopprehistoricmoundnotadopted; archaeologynearbydistinct.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Prevent confusion between a later stronghold and the earlier settlement tradition sharing its name.","wordCount":480,"publicationHold":false,"sortOrder":30}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-ranikot-what-a-circuit-of-walls-does-not-tell-us','ranikot-what-a-circuit-of-walls-does-not-tell-us','review','{"id":"story-ranikot-what-a-circuit-of-walls-does-not-tell-us","type":"story","slug":"ranikot-what-a-circuit-of-walls-does-not-tell-us","title":"Ranikot: what a circuit of walls does not tell us","summary":"Ranikot’s walls make a landscape-scale enclosure, but their extent is not a ready-made explanation of its history. Terrain, inner fortresses and conflicting records deserve separate attention.","body":[{"type":"paragraph","text":"Ranikot is easy to recognise and difficult to reduce to a single explanation. Walls climb and descend through a hilly landscape, joining built defences to natural barriers. The effect is extraordinary, but a sweeping view does not answer who first organised the enclosure, how every section was used or whether all its visible parts belong to one period."},{"type":"paragraph","text":"The available official accounts do not provide a completely consistent chronology. Pakistan''s 1993 Tentative List submission assigns the fort to the early nineteenth century. The federal archaeological catalogue records an eighteenth-century classification while discussing other proposed attributions. These differences should remain visible. Choosing the oldest date for dramatic effect would conceal the actual state of the evidence."},{"type":"heading","level":2,"text":"What is being measured?"},{"type":"paragraph","text":"Published descriptions also offer different figures for Ranikot''s extent. One useful clarification appears in the Endowment Fund Trust''s conservation account: it distinguishes the perimeter of the enclosed landscape from the length of constructed wall. Those are not equivalent measurements. Where terrain itself forms a barrier, an enclosure can extend beyond its built masonry."},{"type":"paragraph","text":"This distinction makes the architecture more interesting than a claim to a world record. The design depends on selecting where construction is necessary and where the topography contributes to enclosure. A wall following a ridge cannot be interpreted in isolation from the slopes and passages around it."},{"type":"paragraph","text":"Look for changes in direction, the relationship of bastions to adjoining stretches and the way openings meet routes. These observations can establish how the surviving system works spatially. They cannot, without additional evidence, supply a detailed battle history or prove that a particular gate served the same purpose throughout its life."},{"type":"heading","level":2,"text":"Enclosures within the enclosure"},{"type":"paragraph","text":"The Endowment Fund Trust identifies Mirikot and Shergarh as smaller fortresses within Ranikot. Its account describes Mirikot''s indirect entrance and residential structures, and Shergarh''s higher position. This introduces hierarchy into what might otherwise seem like one continuous defensive line."},{"type":"paragraph","text":"An outer boundary and an inner stronghold answer different architectural questions. The first defines a broad territory; the second concentrates access and occupation. Their relationship invites enquiry into refuge, residence and control, but those possible functions need to be tested against records and physical evidence rather than accepted from appearance alone."},{"type":"paragraph","text":"The UNESCO-hosted description also notes stone and lime construction and carved details at an inner gateway. Ranikot therefore contains more than distant walls. Smaller architectural features can reveal choices in workmanship and representation that disappear in a landscape panorama."},{"type":"heading","level":2,"text":"A careful kind of discovery"},{"type":"paragraph","text":"The Trust''s conservation documentation forms another layer in the site''s history. A dated project page is evidence of recorded work, not a guarantee that every part of a vast enclosure has the same condition today."},{"type":"paragraph","text":"The strongest visit to Ranikot is not a race to claim its full circuit. It is an attentive reading of a selected stretch, a gateway and an inner fortress in relation to their terrain. The monument''s scale is real; the explanation of that scale remains a research question worth preserving."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"Jamshoro","relatedDistrictIds":["sindh-jamshoro"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5168"],"relatedStoryIds":["story-brick-bonds-as-evidence-of-building-change"],"contentType":"heritage-place","seo":{"title":"Ranikot: what a circuit of walls does not tell us | Virsapur Archives","description":"Ranikot’s walls make a landscape-scale enclosure, but their extent is not a ready-made explanation of its history. Terrain, inner fortresses and conflicting records deserve separate attention.","primaryKeyword":"Ranikot Fort heritage","socialTitle":"Ranikot: what a circuit of walls does not tell us","socialDescription":"Ranikot’s walls make a landscape-scale enclosure, but their extent is not a ready-made explanation of its history. Terrain, inner fortresses and conflicting records deserve separate attention."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Rani Kot Fort, Dadu","url":"https://whc.unesco.org/en/tentativelists/1284/","publisher":"Pakistan submission to UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Ranikot Fort","url":"https://doam.gov.pk/public/sites/5168","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Ranikot Fort, Jamshoro conservation project","url":"https://eftsindh.com/ranikot-fort-jamshoro/","publisher":"Endowment Fund Trust for Preservation of the Heritage of Sindh","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"ConflictingUNESCO19c/DOAM18c17cflagged;no inventedfounder;EFTdistinguishesperiphery32.115kmbuiltwalls7.25km but exactnumbersnotrequired. UNESCO~150,EFT~165,DOAM~60; originalquestionsnotassertions.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Separate documented fabric from disputed dates, builders and popular superlatives.","wordCount":480,"publicationHold":false,"sortOrder":31}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-naukot-fort-at-the-desert-edge','naukot-fort-at-the-desert-edge','review','{"id":"story-naukot-fort-at-the-desert-edge","type":"story","slug":"naukot-fort-at-the-desert-edge","title":"Naukot Fort at the desert edge","summary":"Naukot Fort’s gateway and earthen wall construction connect political control with everyday occupation. Its conservation history shows why rain can be as important as defence in understanding a fortress.","body":[{"type":"paragraph","text":"At Naukot, the gateway is a good place to begin. The entrance is not presented as a simple opening in a flat wall: projecting bastions and a constrained approach make arrival part of the defensive design. Beyond that threshold, the fort opens into an interior that once had to accommodate the practical needs of occupation as well as displays of authority."},{"type":"paragraph","text":"Sindh''s Directorate General of Antiquities attributes the fort to Mir Karam Ali Khan Talpur in 1814 and places it near the edge of the Thar desert. It describes baked brick laid in mud mortar and walls that taper as they rise. These materials are central to the fort''s character, not incidental alternatives to a supposedly superior stone construction."},{"type":"heading","level":2,"text":"More than a boundary"},{"type":"paragraph","text":"The Directorate identifies Naukot as both a stronghold and a residence. A study published through Archives Conservation Laboratories discusses residential rooms, storage features, guard spaces and evidence of a well. Together, these suggest how the interior supported people over time. A fort had to manage water, shelter, supplies and controlled movement; a perimeter alone could not provide those functions."},{"type":"paragraph","text":"The study describes interconnected rooms and traces of decorative plaster around storage and door features. Such details bring the scale down from bastions to inhabitation. The occupants encountered shelves, openings and passages, not only a military silhouette."},{"type":"paragraph","text":"Where room functions are uncertain, interpretation should remain proportionate. A small, enclosed space does not automatically prove a dungeon; an empty chamber does not identify its former contents. Labels should distinguish documented uses from plausible suggestions. The plan can guide questions without answering all of them."},{"type":"heading","level":2,"text":"A wall is an assembly"},{"type":"paragraph","text":"The Endowment Fund Trust''s conservation account provides a revealing modern episode. Heavy monsoon rain in August 2011 damaged the fort, eroding earthen material and threatening the wall structure. The first conservation campaign addressed collapsed portions of the inner brick masonry skin using traditional materials and techniques."},{"type":"paragraph","text":"This record explains why the visible brick face should be understood together with what lies behind it. The strength of a wall depends on the behaviour of its full assembly. If rain enters from above or removes supporting material, a substantial-looking surface can become vulnerable."},{"type":"paragraph","text":"The lesson is not that earthen construction is inherently defective. It is that materials need appropriate detailing and continuing care. A fort built to resist hostile entry can still depend on routine management of water. Defence and maintenance operate on different timescales, but both shape survival."},{"type":"heading","level":2,"text":"The desert edge as a setting"},{"type":"paragraph","text":"Naukot''s position encourages a reading of the fort as a point of connection rather than an isolated object. Approaches, nearby settlement and the transition into Thar belong in the view. Its architectural story combines the concentration of Talpur power with the everyday requirements of occupying this location."},{"type":"paragraph","text":"Walk the composition from entrance to interior, then return to the wall surface. The movement reveals three related scales: controlled access, inhabited enclosure and individual material. Naukot becomes more intelligible when all three remain in focus."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"Tharparkar","relatedDistrictIds":["sindh-tharparkar"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5504"],"relatedStoryIds":["story-defensive-gates-bends-levels-and-lines-of-approach","story-thars-sacred-and-fortified-places","story-thar-settlement-around-scarce-water"],"contentType":"heritage-place","seo":{"title":"Naukot Fort at the desert edge | Virsapur Archives","description":"Naukot Fort’s gateway and earthen wall construction connect political control with everyday occupation. Its conservation history shows why rain can be as important as defence in understanding a fortress.","primaryKeyword":"Naukot Fort heritage","socialTitle":"Naukot Fort at the desert edge","socialDescription":"Naukot Fort’s gateway and earthen wall construction connect political control with everyday occupation. Its conservation history shows why rain can be as important as defence in understanding a fortress."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Naukot Fort, Tharparkar","url":"https://antiquities.sindhculture.gov.pk/tour/naukot-fort-tharparkar/","publisher":"Directorate General of Antiquities, Government of Sindh","accessDate":"2026-10-22"},{"title":"Naukot Fort conservation project","url":"https://eftsindh.org.pk/project/naukot-fort-tharparkar/","publisher":"Endowment Fund Trust","accessDate":"2026-10-22"},{"title":"Naukot Fort, Mithi, Tharparkar","url":"https://ar-cl.com/naukot-fort-mithi-tharparkar/","publisher":"Archives Conservation Laboratories / Sindh Antiquities Journal research","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Sindh1814MirKaram/gateway/bakedbrickmud~130;EFT2011rain2012–14skinrepair~155;researchwell/residentialstorageguardrooms~145. No contradictorydimensions/certainprisonidentity;EFTlater2021phase notconflatedwithfirstcampaign.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Read a compact fortified entrance and enclosure in its regional setting.","wordCount":481,"publicationHold":false,"sortOrder":32}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-umerkot-fort-and-layered-public-memory','umerkot-fort-and-layered-public-memory','review','{"id":"story-umerkot-fort-and-layered-public-memory","type":"story","slug":"umerkot-fort-and-layered-public-memory","title":"Umerkot Fort and layered public memory","summary":"Umerkot Fort holds architecture, political history, literary association and museum collections in one setting. Separating these layers helps explain its significance without turning every tradition into a building date.","body":[{"type":"paragraph","text":"Umerkot Fort is a place where several kinds of memory meet. Its walls express a history of enclosure and political control; its name evokes the Sindhi story of Umar and Marvi; the wider town is associated with Akbar''s birth; and a museum brings objects from different periods into the visitor''s route. These layers enrich one another when they are distinguished, not compressed into a single origin story."},{"type":"paragraph","text":"Sindh''s Directorate General of Antiquities describes a roughly rectangular fort with tapering walls and semicircular corner bastions. An eastern gateway is flanked by further projections, while a central watchtower offers a different view of the enclosure and town. The construction account identifies brick facing in mud mortar around an earthen core."},{"type":"heading","level":2,"text":"Political history and surviving fabric"},{"type":"paragraph","text":"The Directorate''s historical outline moves through Sodha, Kalhora and Talpur possession before British occupation. This sequence is more useful than assigning every visible surface to the earliest ruler mentioned in a foundation tradition. Continued use commonly entails rebuilding, and a political succession is not itself a detailed construction chronology."},{"type":"paragraph","text":"The fort should therefore be read through both records and material relationships. Changes in masonry, the arrangement of access and the position of internal structures can support questions about successive use. They do not become dated phases merely because a familiar dynasty can be attached to them."},{"type":"heading","level":2,"text":"A literary association is not an excavation report"},{"type":"paragraph","text":"Pakistan''s 2026 Tentative List submission includes the story of Umar and Marvi among the fort''s cultural associations. The story''s importance in Sindhi memory does not depend on proving every episode as a literal event in a particular surviving room. Literature can give a place meaning while requiring a different kind of interpretation from measured architecture."},{"type":"paragraph","text":"Akbar''s birth in Umerkot in 1542 is another important association. The federal catalogue separately records a commemorative pavilion at the identified birthplace, built in 1898. This is a useful distinction between an event, the place associated with it and a later monument marking that association. A visitor should not assume that a pavilion commemorating a sixteenth-century birth is itself sixteenth-century fabric."},{"type":"heading","level":2,"text":"The museum adds objects to the landscape"},{"type":"paragraph","text":"The provincial Antiquities Department dates the museum''s inauguration to 1968 and its move into a new building to 2006. Its account describes Mughal coins, arms and armour, manuscripts, paintings, royal documents and calligraphy, alongside photographic material about Tharparkar."},{"type":"paragraph","text":"These collections allow the fort visit to expand beyond a military reading. A coin can introduce circulation and authority; a manuscript can redirect attention to writing and knowledge; regional photographs can connect the enclosure to lives beyond its walls. Their labels and provenance matter as much as their visual appeal."},{"type":"paragraph","text":"Umerkot''s value lies in this layered encounter. The architecture need not authenticate every story, and the museum need not reduce the region to warfare. Holding structure, historical episode, literary memory and collected object together creates a fuller account of a place whose significance exceeds any one of them."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"Umer Kot","relatedDistrictIds":["sindh-umer-kot"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5509"],"relatedStoryIds":["story-thars-sacred-and-fortified-places"],"contentType":"heritage-place","seo":{"title":"Umerkot Fort and layered public memory | Virsapur Archives","description":"Umerkot Fort holds architecture, political history, literary association and museum collections in one setting. Separating these layers helps explain its significance without turning every tradition into a building date.","primaryKeyword":"Umerkot Fort heritage","socialTitle":"Umerkot Fort and layered public memory","socialDescription":"Umerkot Fort holds architecture, political history, literary association and museum collections in one setting. Separating these layers helps explain its significance without turning every tradition into a building date."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Umerkot Fort","url":"https://antiquities.sindhculture.gov.pk/tour/umerkot-fort-umerkot/","publisher":"Directorate General of Antiquities, Government of Sindh","accessDate":"2026-10-22"},{"title":"Thar Museum Umerkot","url":"https://antiquities.sindhculture.gov.pk/tour/archaeological-museum-umerkot/","publisher":"Directorate General of Antiquities, Government of Sindh","accessDate":"2026-10-22"},{"title":"Umerkot Fort Tentative List submission","url":"https://whc.unesco.org/en/tentativelists/6970/","publisher":"Pakistan submission to UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Memorial of Birth Place of Akbar","url":"https://doam.gov.pk/public/sites/5508","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Fortmaterial/politicalsuccession~145;Museum1968/2006collections~145;UNESCOUmarMarvifolklore/new2026~60;DOAM1542separatememorial1898~70. Exactbirthroomnotasserted;foundationdateconflictavoided.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Distinguish surviving architecture, later museum interpretation and associated historical narratives.","wordCount":466,"publicationHold":false,"sortOrder":33}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-chaukhandi-tombs-stories-carved-into-stone','chaukhandi-tombs-stories-carved-into-stone','review','{"id":"story-chaukhandi-tombs-stories-carved-into-stone","type":"story","slug":"chaukhandi-tombs-stories-carved-into-stone","title":"Chaukhandi Tombs: stories carved into stone","summary":"Chaukhandi’s carved sandstone graves communicate through form, motifs and grouping. They invite close looking, but an image of a weapon or ornament is not a complete biography of the person remembered.","body":[{"type":"paragraph","text":"At Chaukhandi, the surface of a grave can be extraordinarily communicative. Carved slabs rise in stepped arrangements, carrying geometric patterns, weapons, figures and ornaments. The workmanship encourages close attention, yet the images should not be treated as a simple code that instantly supplies the name, profession and life story of every person commemorated."},{"type":"paragraph","text":"The federal archaeological catalogue identifies the cemetery with Baloch families and places its principal tombs in the seventeenth and eighteenth centuries. Pakistan''s Tentative List description adds an important caution: dated inscriptions are scarce, making precise dates difficult to assign. A broad historical setting is not the same as a verified year for each grave."},{"type":"heading","level":2,"text":"Stone assembled for remembrance"},{"type":"paragraph","text":"The monuments use carved sandstone slabs arranged on raised platforms, often narrowing upwards. Their form makes the grave visible as an individual construction while allowing groups of related monuments to create a larger composition. The Tentative List account describes family groupings and a smaller number of tombs sheltered by pillared canopies."},{"type":"paragraph","text":"This gives the visitor more than one scale of observation. Begin with the grouping, then examine the stacked form, and finally the carving. An isolated close-up can reveal technical skill while concealing how the monument relates to neighbouring graves. A distant view can preserve that relationship but lose the detail through which remembrance was expressed."},{"type":"heading","level":2,"text":"Motifs and the limits of identification"},{"type":"paragraph","text":"The archaeological catalogue records horsemen, shields, swords, bows and arrows, as well as jewellery forms such as necklaces and bracelets. It associates different motifs with male and female graves. Those established interpretations are useful guides, but they should not be expanded into invented individual biographies."},{"type":"paragraph","text":"A weapon may participate in a representation of status or identity without proving the exact circumstances of a person''s death. An ornament carved in stone is not evidence that the buried person owned that particular object. The distinction is between what a community chose to represent and what an observer can independently establish about a life."},{"type":"heading","level":2,"text":"A wider regional language"},{"type":"paragraph","text":"A study in Sindh Antiquities examines the social and political significance of tomb form and decoration across several regional examples. It treats height, arrangement and imagery as evidence of how communities represented identity. Its examples include cemeteries beyond Chaukhandi, which is a reminder that a shared architectural type can appear in different places."},{"type":"paragraph","text":"Comparative interpretation should preserve those differences. A documented identification at Makli or Oongar cannot automatically be transferred to a similarly carved grave near Karachi. Similarity helps frame a question; provenance and local evidence help answer it."},{"type":"paragraph","text":"Chaukhandi is also a cemetery, not an outdoor furniture collection. Avoid sitting or climbing on the monuments, and do not touch carving to make a photograph more dramatic. Looking with care allows the work to remain both legible and dignified. The stones carry remarkable evidence of craft and commemoration, even where the names and precise histories behind them remain uncertain."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"Malir Karachi","relatedDistrictIds":["sindh-malir-karachi"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5815"],"relatedStoryIds":["story-funerary-landscapes-and-the-names-we-no-longer-know"],"contentType":"heritage-place","seo":{"title":"Chaukhandi Tombs: stories carved into stone | Virsapur Archives","description":"Chaukhandi’s carved sandstone graves communicate through form, motifs and grouping. They invite close looking, but an image of a weapon or ornament is not a complete biography of the person remembered.","primaryKeyword":"Chaukhandi Tombs heritage","socialTitle":"Chaukhandi Tombs: stories carved into stone","socialDescription":"Chaukhandi’s carved sandstone graves communicate through form, motifs and grouping. They invite close looking, but an image of a weapon or ornament is not a complete biography of the person remembered."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Chaukhandi Tombs","url":"https://doam.gov.pk/public/sites/5815","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Chaukhandi Tombs, Karachi","url":"https://whc.unesco.org/en/tentativelists/1287/","publisher":"Pakistan submission to UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Declarations in Death","url":"https://saj.sindhculture.gov.pk/images/SAJ/Vol6No12020/04_Declarations_in_Death.pdf","publisher":"Sindh Antiquities, volume 6 number 1, 2020","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMmotifs~110;UNESCOdatinglimits/groupedgraves/canopies~145;articlep56–58comparativeinterpretation~150,doNOTtransferMakli/Oongarindividualidentities toKarachi. No gendercertaintiesfrommotif alone.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Introduce carved funerary forms while distinguishing motifs from unsupported identity claims.","wordCount":463,"publicationHold":false,"sortOrder":34}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-banbhore-and-the-evidence-for-a-port','banbhore-and-the-evidence-for-a-port','review','{"id":"story-banbhore-and-the-evidence-for-a-port","type":"story","slug":"banbhore-and-the-evidence-for-a-port","title":"Banbhore and the evidence for a port","summary":"Banbhore’s port history is supported by its creek-side position, urban remains and evidence of production and exchange. Recent ivory-workshop research adds labour and manufacturing to the familiar harbour story.","body":[{"type":"paragraph","text":"A port is more than a place where ships stop. It connects landing, storage, exchange, manufacture and movement inland. Banbhore''s importance emerges from this wider set of relationships: a fortified settlement beside Gharo Creek, internal streets and substantial buildings, activity beyond the walls, and finds that connect the site to networks across the Indian Ocean."},{"type":"paragraph","text":"Pakistan''s Tentative List submission locates the site on the creek''s northern bank and describes a long occupation sequence extending into the early thirteenth century. It identifies several urban zones and notes that earlier deposits are affected by waterlogging. The visible surface therefore does not provide an equally complete view of every period in the site''s history."},{"type":"heading","level":2,"text":"The port in the plan"},{"type":"paragraph","text":"The federal archaeological catalogue describes fortification walls, gateways, streets, a mosque and an industrial area beyond the defended settlement. The UNESCO-hosted account also emphasises imported ceramic and metal goods. Taken together, these are different kinds of evidence: architecture shows the arrangement of space, while objects help investigate production, circulation and contact."},{"type":"paragraph","text":"A creek-side position alone would not establish a complete trading history. The argument becomes stronger when location is considered alongside excavated material and the organisation of the settlement. Equally, an imported object does not by itself identify the nationality of its owner or the exact route by which it travelled."},{"type":"heading","level":2,"text":"What discarded ivory can reveal"},{"type":"paragraph","text":"Research reported by archaeologist Simone Mantellini through the Fondation Max van Berchem describes ivory-working evidence in Trench 9. Two workshops were associated with offcuts, small chips, powder and unfinished or broken objects. The report places this production in the twelfth century and distinguishes the abundant manufacturing waste from the much smaller number of complete pieces."},{"type":"paragraph","text":"Waste is especially informative because it records making rather than only possession. An attractive finished object might have arrived from elsewhere; a concentration of intermediate fragments and offcuts can reveal stages of work at the site itself. The workshop shifts attention from the harbour as a point of arrival to the town as a place of skilled labour."},{"type":"paragraph","text":"The same project sets out further questions about manufacturing techniques and the origin of raw material, including proposed scientific analysis. Those research aims should not be presented as already completed answers. Evidence that elephant ivory was worked at Banbhore does not, on its own, establish where every tusk originated."},{"type":"heading","level":2,"text":"Connecting scales of evidence"},{"type":"paragraph","text":"Banbhore becomes most intelligible when the large plan and the small fragment are read together. Walls and gates organise movement through the town; a workshop locates an activity; the waste from that activity helps reconstruct a sequence of actions. Each contributes something the others cannot provide."},{"type":"paragraph","text":"For visitors, this means allowing the museum, excavation records and landscape to complement one another. A monumental wall may provide the strongest photograph, but an unassuming fragment can explain how the settlement participated in a much wider economy. The port''s history includes both the routes across water and the hands at work on land."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"Thatta","relatedDistrictIds":["sindh-thatta"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5512"],"relatedStoryIds":["story-coastal-sites-and-a-moving-shoreline","story-the-indus-delta-and-the-changing-idea-of-a-port"],"contentType":"heritage-place","seo":{"title":"Banbhore and the evidence for a port | Virsapur Archives","description":"Banbhore’s port history is supported by its creek-side position, urban remains and evidence of production and exchange. Recent ivory-workshop research adds labour and manufacturing to the familiar harbour story.","primaryKeyword":"Banbhore heritage","socialTitle":"Banbhore and the evidence for a port","socialDescription":"Banbhore’s port history is supported by its creek-side position, urban remains and evidence of production and exchange. Recent ivory-workshop research adds labour and manufacturing to the familiar harbour story."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Port of Banbhore","url":"https://whc.unesco.org/en/tentativelists/1885/","publisher":"Pakistan submission to UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Banbhore","url":"https://doam.gov.pk/public/sites/5512","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Ivory manufacturing at Banbhore","url":"https://maxvanberchem.org/en/scientific-activities/projects/archeology/11-archeologie/201-ivory-industrial-scale-manufacturing-at-banbhore-pakistan-a-unique-archaeological-discovery-from-islamic-sindh-12th-13th-centuries","publisher":"Simone Mantellini / Fondation Max van Berchem","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"UNESCOlocation/zones/imports~165;DOAMfortification/industrialoutside~65;Mantellinireportworkshops/offcuts/semifinished12c/proposedDNA~190. No largest/earliestclaims;Debalassociationnotresolvedorasserted; no rawmaterialoriginwithoutresults.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Use excavated material and coastal setting to discuss trade without asserting debated city identifications.","wordCount":474,"publicationHold":false,"sortOrder":35}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-shah-jahan-mosque-thatta-brick-tile-and-repetition','shah-jahan-mosque-thatta-brick-tile-and-repetition','review','{"id":"story-shah-jahan-mosque-thatta-brick-tile-and-repetition","type":"story","slug":"shah-jahan-mosque-thatta-brick-tile-and-repetition","title":"Shah Jahan Mosque, Thatta: brick, tile and repetition","summary":"Shah Jahan Mosque in Thatta builds a rich visual language from repeated bays, brickwork and patterned tiles. Its spaces reveal how structural rhythm and surface design can reinforce one another.","body":[{"type":"paragraph","text":"The Shah Jahan Mosque in Thatta offers a lesson in repetition without monotony. Brick piers, arches and domed bays establish a recurring structure, while tile patterns change the way each surface is perceived. The building''s richness comes from the interaction of those systems: the rhythm of construction and the smaller rhythms of colour, line and geometry."},{"type":"paragraph","text":"Sindh''s Directorate General of Antiquities identifies it as Thatta''s seventeenth-century congregational mosque, built during Shah Jahan''s reign. Its extensive brickwork distinguishes the material experience from the red sandstone and marble commonly associated with major Mughal monuments farther north. An imperial-period building can belong strongly to a regional architectural language."},{"type":"heading","level":2,"text":"A court held by covered spaces"},{"type":"paragraph","text":"The federal archaeological account describes the prayer chamber on the west and a balancing eastern composition, with galleries along the other sides of the courtyard. The UNESCO-hosted Tentative List description emphasises substantial walls and square supports. These are the elements that make the repeated bays possible."},{"type":"paragraph","text":"The court provides a pause between covered spaces. From its openness, the surrounding arcades can be read as an ordered boundary. Within the galleries, the same repetition becomes a sequence of shorter views, framed by one opening after another. The building therefore changes from a composition seen across space to a rhythm experienced through movement."},{"type":"paragraph","text":"This is one reason a single wide-angle photograph is insufficient. It may capture the overall arrangement while compressing the depth of the galleries. A close view of tilework has the opposite limitation: it can lose the architectural framework that gives the pattern its position and scale."},{"type":"heading","level":2,"text":"Patterns that describe a surface"},{"type":"paragraph","text":"The Tentative List account distinguishes radiating blue-and-white tile arrangements in the principal domes, floral designs around arches and geometric panels elsewhere. These patterns do not all perform the same visual task. A radial design draws attention towards a dome''s centre; a border can clarify an edge; repeated panels organise a broader wall."},{"type":"paragraph","text":"The most useful looking is therefore comparative. Follow a pattern to its boundary. Notice where it changes direction, meets an arch or adjusts to a curved surface. The craft lies not simply in producing a decorative unit but in fitting units to a particular architectural situation."},{"type":"paragraph","text":"Brickwork deserves the same attention. Where it remains visually exposed, its scale and arrangement contribute to the composition. The contrast between brick and glazed surface helps explain how the mosque can be materially restrained and visually elaborate at the same time."},{"type":"heading","level":2,"text":"Listening without turning worship into a test"},{"type":"paragraph","text":"Many descriptions celebrate the mosque''s acoustics, sometimes with sweeping claims about what can be heard everywhere. Those claims need more than an anecdote to become a measured account of sound. Visitors need not call out to test them, especially during worship."},{"type":"paragraph","text":"Instead, allow the building''s ordinary use to shape the encounter. Observe the relationship between open court and covered prayer spaces, and give the craftsmanship time at both near and far distances. Thatta''s mosque is most rewarding when repetition is understood as a carefully varied architectural resource rather than a background to one spectacular ceiling."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"Thatta","relatedDistrictIds":["sindh-thatta"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5625"],"relatedStoryIds":["story-tile-mosaic-and-glazed-brick-not-interchangeable-terms","story-thatta-across-political-and-cultural-changes"],"contentType":"heritage-place","seo":{"title":"Shah Jahan Mosque, Thatta: brick, tile and repetition | Virsapur Archives","description":"Shah Jahan Mosque in Thatta builds a rich visual language from repeated bays, brickwork and patterned tiles. Its spaces reveal how structural rhythm and surface design can reinforce one another.","primaryKeyword":"Shah Jahan Mosque heritage","socialTitle":"Shah Jahan Mosque, Thatta: brick, tile and repetition","socialDescription":"Shah Jahan Mosque in Thatta builds a rich visual language from repeated bays, brickwork and patterned tiles. Its spaces reveal how structural rhythm and surface design can reinforce one another."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Shah Jahan Mosque, Thatta","url":"https://whc.unesco.org/en/tentativelists/1286/","publisher":"Pakistan submission to UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Shah Jahan Mosque","url":"https://doam.gov.pk/public/sites/5625","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Shah Jahan Mosque, Jamia Masjid, Thatta","url":"https://antiquities.sindhculture.gov.pk/tour/shah-jahan-mosque-jamia-masjid-thatta/","publisher":"Directorate General of Antiquities, Government of Sindh","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"UNESCOtilepatterns/courtarcades~170;DOAMwestprayer/eastbalance~90;Sindh17c/redbrickregionalcontext~80. Avoid inconsistent93/100domes, acousticguarantees,unsupportedtileimportfromHala. Originalvisualreading.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain the architectural rhythm of multiple bays rather than repeat acoustic folklore.","wordCount":486,"publicationHold":false,"sortOrder":36}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-gori-temple-and-the-evidence-in-its-painted-interior','gori-temple-and-the-evidence-in-its-painted-interior','review','{"id":"story-gori-temple-and-the-evidence-in-its-painted-interior","type":"story","slug":"gori-temple-and-the-evidence-in-its-painted-interior","title":"Gori Temple and the evidence in its painted interior","summary":"Gori Temple’s painted interior belongs to a wider Jain architectural landscape. Carved stone, hall sequence and surviving imagery offer different kinds of evidence that should be read together.","body":[{"type":"paragraph","text":"Gori Temple asks the visitor to look beyond the pale stone of its exterior. Its surviving painted interior is part of the building''s religious and artistic significance, not an incidental embellishment. The relationship between carved architecture and painted imagery offers a way into the Jain history of Tharparkar without reducing the temple to a picturesque ruin."},{"type":"paragraph","text":"Pakistan''s Nagarparkar Cultural Landscape submission places Gori alongside other Jain temples and associated remains at places including Viravah and Bhodesar. It identifies Jain religious imagery in Gori''s painted interior. That regional setting is important: the temple belongs to a network of religious buildings and communities, rather than an inexplicable exception in the landscape."},{"type":"heading","level":2,"text":"A sequence of spaces"},{"type":"paragraph","text":"The Department of Archaeology''s description distinguishes an outer hall, a further inner hall, subsidiary cells and the sanctuary. It also records carved pillars and corbelled construction. These features create an architectural sequence through which the visitor can understand changes in enclosure and emphasis."},{"type":"paragraph","text":"A corbelled form is made by successive projecting courses rather than by treating every curved ceiling as the same kind of arch or dome. Recognising that distinction helps connect visible shape to construction. It also encourages attention to joints and supports instead of judging the interior solely by its decorative effect."},{"type":"paragraph","text":"The Endowment Fund Trust''s inventory records the building within an enclosure with an open area in front. This foreground belongs to the experience of approach. The transition from exterior light to the more contained halls affects how carving and painted surfaces can be seen."},{"type":"heading","level":2,"text":"What a painted surface can tell us"},{"type":"paragraph","text":"Religious imagery requires informed identification. A figure, gesture or arrangement may carry meanings that are not apparent to an unfamiliar observer. It is better to describe a visible composition carefully and consult specialist scholarship than to assign every figure a name from a general internet search."},{"type":"paragraph","text":"The same caution applies to age. A temple can contain successive construction, repair and decoration campaigns. The federal catalogue records an inscription associated with repairs in 1715; this does not automatically date every painted fragment or establish that nothing changed afterwards. Architectural and artistic chronologies need to be considered together without being made identical."},{"type":"paragraph","text":"For documentation, position is as valuable as an attractive close-up. A record should show where an image sits in relation to a hall, ceiling or doorway, then examine its details. Without that context, a photograph risks turning part of a meaningful programme into a detached decorative sample."},{"type":"heading","level":2,"text":"Preserving relationships"},{"type":"paragraph","text":"The broader cultural-landscape approach helps keep Gori connected to water features, settlements and other religious places in the region. It also avoids presenting Jain heritage as merely a vanished aesthetic. The meanings of these traditions extend beyond the surviving buildings and require respectful engagement with knowledgeable communities and scholars."},{"type":"paragraph","text":"Do not touch painted or carved surfaces, and follow local guidance on photography and access. Gori''s importance is carried by the relationship between its plan, material and imagery. Protecting those relationships allows future interpretation to become more precise, rather than replacing uncertainty with an attractive but invented story."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"Tharparkar","relatedDistrictIds":["sindh-tharparkar"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5499"],"relatedStoryIds":["story-jain-heritage-in-pakistan-beyond-one-temple","story-religious-heritage-and-the-politics-of-naming","story-thars-sacred-and-fortified-places","story-thar-settlement-around-scarce-water"],"contentType":"heritage-place","seo":{"title":"Gori Temple and the evidence in its painted interior | Virsapur Archives","description":"Gori Temple’s painted interior belongs to a wider Jain architectural landscape. Carved stone, hall sequence and surviving imagery offer different kinds of evidence that should be read together.","primaryKeyword":"Gori Temple heritage","socialTitle":"Gori Temple and the evidence in its painted interior","socialDescription":"Gori Temple’s painted interior belongs to a wider Jain architectural landscape. Carved stone, hall sequence and surviving imagery offer different kinds of evidence that should be read together."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Gori Temple","url":"https://doam.gov.pk/public/sites/5499","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Nagarparkar Cultural Landscape","url":"https://whc.unesco.org/en/tentativelists/6111/","publisher":"Pakistan submission to UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Gori Temple, Tharparkar","url":"https://heritage.eftsindh.com/districts/tharparkar/gori-temple.php","publisher":"Endowment Fund Trust heritage inventory","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"UNESCOJainimagery/region~170;DOAMhalls/cells/corbelleddomerepair1715~160;EFTenclosureandstone~60. No unverifiedoldestmuralclaim/specificiconography/colonialfirestory. Specialistidentificationneededforindividualpaintings.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Connect a Jain sacred building with its surviving decoration and conservation questions.","wordCount":491,"publicationHold":false,"sortOrder":37}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-mohatta-palace-from-residence-to-cultural-institution','mohatta-palace-from-residence-to-cultural-institution','review','{"id":"story-mohatta-palace-from-residence-to-cultural-institution","type":"story","slug":"mohatta-palace-from-residence-to-cultural-institution","title":"Mohatta Palace: from residence to cultural institution","summary":"Mohatta Palace’s public identity grew through a succession of uses: private house, state premises, residence and museum. Its architecture and exhibition history show different ways a building can carry cultural value.","body":[{"type":"paragraph","text":"Mohatta Palace is not simply a grand house that happens to contain exhibitions. Its current identity is the result of several changes in ownership and use, followed by a deliberate decision to make it a public cultural institution. Reading the building through that sequence reveals how architecture can acquire new responsibilities without losing the evidence of its earlier life."},{"type":"paragraph","text":"The museum''s own history records that Shiv Rattan Mohatta commissioned the house in 1927 in Clifton, Karachi. It names Ahmed Hussein Agha as architect and describes a design combining local yellow Gizri stone with pink Jodhpur stone. The historical reference is a Mughal revival vocabulary adapted to a wealthy twentieth-century residence, not an original Mughal palace."},{"type":"heading","level":2,"text":"A building with successive lives"},{"type":"paragraph","text":"According to the museum, the Government of Pakistan acquired the property in 1947 for the Ministry of Foreign Affairs. It later became the residence of Fatima Jinnah. These uses introduce different histories into the same rooms: private wealth, the institutions of a new state and the life of a major public figure."},{"type":"paragraph","text":"The museum records acquisition by a public trust in 1995 and opening to visitors on 15 September 1999. Its account of the restoration explains that a board oversaw the programme before the museum opened. This was an institutional transformation as well as a physical repair project."},{"type":"heading","level":2,"text":"The house and the exhibition"},{"type":"paragraph","text":"A museum in a former residence presents two kinds of display simultaneously. Visitors encounter the building''s proportions, materials and decorative choices while also following the ideas assembled by curators. The relationship can be productive, but the objects in an exhibition should not automatically be assumed to have belonged to the original household."},{"type":"paragraph","text":"The museum''s exhibition history makes that distinction clear. Its inaugural show, Treasures of the Talpurs, brought material from the courts of Sindh to public audiences through borrowed collections. Later in 1999, Qalam examined calligraphy across a range of materials, including manuscripts and architectural elements. These were curatorial subjects extending well beyond a reconstruction of Mohatta family life."},{"type":"paragraph","text":"The borrowing of objects also brings documentation into focus. A display can create an illuminating comparison between works from separate collections, but their individual histories still matter. Provenance, date, medium and ownership should remain visible rather than disappearing into the atmosphere of a historic room."},{"type":"heading","level":2,"text":"Public value through continued use"},{"type":"paragraph","text":"The museum describes its governing body as an autonomous public trust with a purpose of encouraging appreciation of Pakistan''s and the region''s cultural heritage. That mission helps explain why preserving the building and developing exhibitions are connected activities. The architecture provides a setting, while programming gives people reasons to return and encounter new questions."},{"type":"paragraph","text":"For a visit, pay attention to both layers. Notice how the coloured stone and historic forms frame arrival, then follow the evidence and argument of the exhibition rather than treating it as interior decoration. Mohatta Palace''s significance lies partly in this continuing exchange: a once-private architectural statement has become a place where many different histories and creative practices can enter public view."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"South Karachi","relatedDistrictIds":["sindh-south-karachi"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-6036"],"relatedStoryIds":["story-adaptive-reuse-what-should-stay-legible"],"contentType":"heritage-place","seo":{"title":"Mohatta Palace: from residence to cultural institution | Virsapur Archives","description":"Mohatta Palace’s public identity grew through a succession of uses: private house, state premises, residence and museum. Its architecture and exhibition history show different ways a building can carry cultural value.","primaryKeyword":"Mohatta Palace heritage","socialTitle":"Mohatta Palace: from residence to cultural institution","socialDescription":"Mohatta Palace’s public identity grew through a succession of uses: private house, state premises, residence and museum. Its architecture and exhibition history show different ways a building can carry cultural value."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"History of the Museum","url":"https://www.mohattapalacemuseum.org/public/history-of-the-museum","publisher":"Mohatta Palace Museum","accessDate":"2026-10-22"},{"title":"About the Museum","url":"https://mohattapalacemuseum.org/public/about-the-museum","publisher":"Mohatta Palace Museum","accessDate":"2026-10-22"},{"title":"Exhibitions through the years","url":"https://www.mohattapalacemuseum.org/events","publisher":"Mohatta Palace Museum","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Museumhistorydates/materials/architect~185;Abouttrust/restoration~100;Exhibition1999Talpurs/Qalam~120. Preserve sourceownShivRattanname; nohauntinglegend/tunnel orcurrentexhibitioncount.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Trace changing uses of the building without treating exhibition content as permanent.","wordCount":483,"publicationHold":false,"sortOrder":38}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-bhittais-shrine-as-an-architectural-setting-for-memory','bhittais-shrine-as-an-architectural-setting-for-memory','review','{"id":"story-bhittais-shrine-as-an-architectural-setting-for-memory","type":"story","slug":"bhittais-shrine-as-an-architectural-setting-for-memory","title":"Bhittai’s shrine as an architectural setting for memory","summary":"At Bhit Shah, the shrine of Shah Abdul Latif Bhittai is both an architectural complex and a setting for performed poetry. Courts, thresholds and spaces for listening connect built and living heritage.","body":[{"type":"paragraph","text":"A photograph of the shrine at Bhit Shah can describe a dome, a courtyard and a decorated façade. It cannot fully convey what happens when poetry is sung and people gather to listen. The mausoleum of Shah Abdul Latif Bhittai is best understood through this relationship between built space and continuing cultural practice, rather than as an architectural shell around a famous name."},{"type":"paragraph","text":"The federal archaeological catalogue describes a complex organised around the tomb, with successive courts, a mosque, service spaces and a porch associated with music. This arrangement matters because a shrine accommodates more than one activity. Approach, prayer, remembrance, gathering and practical support require spaces with different degrees of enclosure and access."},{"type":"heading","level":2,"text":"Architecture for arrival and attention"},{"type":"paragraph","text":"The movement from the town towards the central tomb creates a sequence of thresholds. A court can receive people and allow them to pause; a more enclosed space can concentrate attention. The catalogue''s descriptions of screens, painted surfaces and tile decoration add further layers to that sequence."},{"type":"paragraph","text":"These elements should not be reduced to a competition in ornament. A screen shapes a relationship between spaces; a doorway directs movement; an open court allows different groups to gather without making every activity identical. Architecture supports a changing social setting, not a single frozen scene."},{"type":"heading","level":2,"text":"Poetry as performed knowledge"},{"type":"paragraph","text":"Zulfiqar Qureshi''s study of Vaaee, published through Sindh''s Culture Department, examines singing traditions associated with Bhittai. It distinguishes forms of performance and discusses the ordering of baits and vaaees. Its account of shrine practice includes rounds drawing on named surs, including Bilawal, Sri Raga, Samoondi and Soorath."},{"type":"paragraph","text":"This is evidence of structure and transmitted knowledge, not merely spontaneous atmosphere. The performers carry an understanding of sequence, melody and text that is as important to the encounter as the visible architecture. A visitor who does not understand Sindhi can still recognise that listening respectfully is different from treating the sound as a background effect."},{"type":"paragraph","text":"The study describes practice at the time of its research; it should not be converted into an unverified promise that a particular performance will occur at a stated hour today. Living traditions continue through people and institutions, and their circumstances can change."},{"type":"heading","level":2,"text":"A wider cultural setting"},{"type":"paragraph","text":"The Culture Department''s public record of a July 2026 raag programme identifies the Shah Abdul Latif Bhittai Auditorium in Bhit Shah as its venue. The auditorium is not the shrine itself. Keeping those locations distinct helps show how remembrance and performance extend across a town''s cultural institutions rather than occupying one undifferentiated sacred space."},{"type":"paragraph","text":"At the shrine, follow local guidance, give worshippers and musicians room, and ask before recording identifiable people. The most rewarding architectural interpretation leaves room for the people who make the place meaningful. Courts and thresholds provide a setting, but the heritage of Bhit Shah also lives in trained voices, shared attention and the continuing relationship between poetry and memory."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"Matiari","relatedDistrictIds":["sindh-matiari"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-10375"],"relatedStoryIds":["story-the-poets-tomb-and-the-readers-memory","story-shah-abdul-latif-as-a-reader-of-landscapes"],"contentType":"heritage-place","seo":{"title":"Bhittai’s shrine as an architectural setting for memory | Virsapur Archives","description":"At Bhit Shah, the shrine of Shah Abdul Latif Bhittai is both an architectural complex and a setting for performed poetry. Courts, thresholds and spaces for listening connect built and living heritage.","primaryKeyword":"Shah Abdul Latif Bhittai heritage","socialTitle":"Bhittai’s shrine as an architectural setting for memory","socialDescription":"At Bhit Shah, the shrine of Shah Abdul Latif Bhittai is both an architectural complex and a setting for performed poetry. Courts, thresholds and spaces for listening connect built and living heritage."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Shrine of Shah Abdul Latif Bhittai","url":"https://doam.gov.pk/public/sites/10375","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Vaaee of Shah Abdul Latif Bhittai: origin and evolution","url":"https://el.sindhculture.gov.pk/read/13","publisher":"Zulfiqar Qureshi / Culture Department, Government of Sindh","accessDate":"2026-10-22"},{"title":"Raag programme at Bhit Shah, 29 July 2026","url":"https://www.youtube.com/watch?v=3VIQmtjBtXA","publisher":"Culture Department, Government of Sindh","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMlayoutcourtsmosquekitchenmusicporch~180;Qureshispecificperformancepattern~155;official2026programmeindexeddescription~40 explicitlyauditoriumnotshrine. No lyrics quoted; noexactcurrentlydailyguarantee, dubious1772constructionomitted.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Keep the tangible shrine story distinct from a separate article on the poet’s texts.","wordCount":465,"publicationHold":false,"sortOrder":39}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-mansehras-rock-edicts-as-a-public-text','mansehras-rock-edicts-as-a-public-text','review','{"id":"story-mansehras-rock-edicts-as-a-public-text","type":"story","slug":"mansehras-rock-edicts-as-a-public-text","title":"Mansehra’s rock edicts as a public text","summary":"Mansehra’s rock edicts turn an existing landscape into a medium for imperial communication. Their script, placement and comparison with other versions reveal more than a general claim to ancient writing.","body":[{"type":"paragraph","text":"At Mansehra, three large boulders carry a form of architecture without a building. Their surfaces were made into a medium for the edicts of the Mauryan emperor Ashoka. The result joins text, rock and route: a political message placed in a landscape rather than confined to a manuscript that could be moved elsewhere."},{"type":"paragraph","text":"Pakistan''s Tentative List description dates the inscriptions to the middle of the third century BCE and identifies fourteen major edicts written in Kharoshthi, from right to left. The federal archaeological catalogue likewise treats the boulders as a related group. The physical carrier is therefore essential to the site''s identity; a printed translation explains the words but cannot replace their setting."},{"type":"heading","level":2,"text":"A message beside movement"},{"type":"paragraph","text":"The UNESCO-hosted submission places the edicts beside an old route connecting the Peshawar region with northern areas and Taxila. This location invites questions about intended audiences. People moving through a route encountered a marked place; the inscription did not have to travel to them in the same way as a document."},{"type":"paragraph","text":"That does not prove universal literacy or that every passer-by read the text directly. Public communication can involve readers, listeners, interpreters and repeated explanation. The surviving words establish that a message was inscribed, but the full history of its reception requires evidence beyond the stone itself."},{"type":"paragraph","text":"The edicts concern Ashoka''s understanding of dharma, described in the Tentative List account as righteous conduct or law. A careful interpretation distinguishes the ruler''s declared principles from independent evidence about how society actually behaved. An official statement is a source for political intention and representation, not a transparent description of everyday life."},{"type":"heading","level":2,"text":"Script, language and comparison"},{"type":"paragraph","text":"Kharoshthi is the script: the system of signs in which the text was written. Identifying a script is not the same task as translating the language or explaining a historical term. Keeping those stages separate makes the work of reading ancient inscriptions more intelligible."},{"type":"paragraph","text":"The University of Oslo''s Bibliotheca Polyglotta places Mansehra within a comparative set of Ashokan rock-edict records, alongside locations such as Girnar, Kalsi and Shahbazgarhi. Such a framework allows versions to be studied in relation to one another rather than assuming every inscription is an identical copy. Its record for the thirteenth edict explicitly identifies the Mansehra version."},{"type":"heading","level":2,"text":"Recording a vulnerable surface"},{"type":"paragraph","text":"The British Library''s catalogue includes a historical image record for Mansehra''s edicts IX–XI. A photograph can preserve information about a surface at a particular moment, but its usefulness depends on knowing what it shows, when it was made and how it relates to the actual rock."},{"type":"paragraph","text":"Visitors should never trace, rub or wet an inscription to make its letters easier to see. The desire to read must not damage the evidence being read. Mansehra rewards a slower encounter: first the boulder in its setting, then the marked surface, and finally the scholarly work that makes the text accessible. Together, those scales reveal an ancient act of communication still open to careful study."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Khyber Pakhtunkhwa","Architecture"],"province":"Khyber Pakhtunkhwa","district":"Mansehra","relatedDistrictIds":["khyber-pakhtunkhwa-mansehra"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-doam-136"],"relatedStoryIds":["story-reading-ashokas-edicts-as-material-objects","story-kharoshthi-and-brahmi-in-the-north-west","story-reading-a-bilingual-inscription"],"contentType":"heritage-place","seo":{"title":"Mansehra’s rock edicts as a public text | Virsapur Archives","description":"Mansehra’s rock edicts turn an existing landscape into a medium for imperial communication. Their script, placement and comparison with other versions reveal more than a general claim to ancient writing.","primaryKeyword":"Mansehra Rock Edicts heritage","socialTitle":"Mansehra’s rock edicts as a public text","socialDescription":"Mansehra’s rock edicts turn an existing landscape into a medium for imperial communication. Their script, placement and comparison with other versions reveal more than a general claim to ancient writing."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Mansehra Rock Edicts","url":"https://whc.unesco.org/en/tentativelists/1881/","publisher":"Pakistan submission to UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Mansehra Rock Edicts","url":"https://doam.gov.pk/public/sites/136","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Rock edicts: synoptic text records","url":"https://www2.hf.uio.no/polyglotta/index.php?mid=635067&page=record&vid=365&view=record","publisher":"Bibliotheca Polyglotta, University of Oslo","accessDate":"2026-10-22"},{"title":"Rocks with Asoka inscriptions, Edicts IX–XI, Mansehra","url":"https://searcharchives.bl.uk/catalog/040-003137370","publisher":"British Library Archives and Manuscripts catalogue","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"UNESCO3boulders14edictsKharoshthi3BCEroutes~170;DOAMsupportsamefactsnotdoublebudget;Oslo actualnavigationrecordreadnotfulltranslation used~70;BLindexedcataloguedescriptoronly~40. No verbatimroyaltranslation invented, earliestwritingabsoluteavoided; interpretationoriginal.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Examine surface, script and audience, distinguishing inscriptions from later interpretations.","wordCount":475,"publicationHold":false,"sortOrder":40}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-bhamala-and-the-shape-of-a-buddhist-complex','bhamala-and-the-shape-of-a-buddhist-complex','review','{"id":"story-bhamala-and-the-shape-of-a-buddhist-complex","type":"story","slug":"bhamala-and-the-shape-of-a-buddhist-complex","title":"Bhamala and the shape of a Buddhist complex","summary":"Bhamala’s cruciform stupa is the centre of a larger Buddhist complex. Excavation evidence connects its distinctive plan to chapels, monastic spaces and a history of continued use.","body":[{"type":"paragraph","text":"Bhamala''s main stupa is memorable for its cruciform plan, but its shape becomes more meaningful when the surrounding complex is allowed into the picture. Smaller stupas, image chapels, monastic spaces and later excavation discoveries show that this was not one isolated monument. It was an organised setting for a Buddhist community whose use of the place developed over time."},{"type":"paragraph","text":"The Department of Archaeology and Museums locates Bhamala in the hills near Khanpur and describes a square-based stupa with projecting stairways on four sides. The projections produce the characteristic cross-shaped plan. That geometry is more informative than comparisons with distant monuments that merely happen to look similar from above."},{"type":"heading","level":2,"text":"A centre with surrounding activities"},{"type":"paragraph","text":"The federal catalogue records smaller votive stupas and image chapels around the main court, with a monastic complex to the south. These elements establish relationships between a principal devotional focus and other spaces. Their distribution can help explain movement, proximity and differences in scale within the sacred precinct."},{"type":"paragraph","text":"The plan should not be imagined as fully visible in one historical instant. Archaeological sites often contain structures from successive phases, and an exposed arrangement can bring those phases together in a way that no original visitor experienced. Establishing which walls and floors belong together requires recorded excavation, not visual symmetry alone."},{"type":"heading","level":2,"text":"What renewed excavation changed"},{"type":"paragraph","text":"Abdul Samad''s report on the January–March 2013 field season describes work in the western part of the complex and an extension that drew attention to another phase of occupation. The team used systematic recording of deposits and relationships to begin refining the chronology. Training students and staff formed part of the programme alongside the recovery of objects."},{"type":"paragraph","text":"The report records terracotta and stucco sculpture and copper coins provisionally associated with the fourth and fifth centuries CE. It uses these findings to argue for activity extending beyond an earlier, narrowly framed understanding of the site. The important point is not simply that more objects were found; the relationship of finds to deposits changed the historical questions that could be asked."},{"type":"heading","level":2,"text":"Form is evidence, not a complete explanation"},{"type":"paragraph","text":"A cruciform stupa can be compared with other Buddhist architectural forms, but shape alone does not identify every ritual performed there. Likewise, an image chapel provides evidence of a devotional setting without preserving all the words, gestures and people that animated it."},{"type":"paragraph","text":"Pakistan submitted Bhamala as a separate Tentative List property in 2026. That nomination-stage recognition should be distinguished from World Heritage inscription, and geographical association with Taxila should not be used casually to redraw another property''s boundaries."},{"type":"paragraph","text":"For the visitor, a rewarding sequence is to understand the principal stupa''s outline, then trace how the surrounding spaces relate to it. Finally, consider the excavation record that places those relationships in time. Bhamala''s distinctive form is the beginning of discovery; the wider complex and its stratified evidence make that discovery historically substantial."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Khyber Pakhtunkhwa","Architecture"],"province":"Khyber Pakhtunkhwa","district":"Haripur","relatedDistrictIds":["khyber-pakhtunkhwa-haripur"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-doam-823"],"relatedStoryIds":["story-why-stupas-were-rebuilt-around-older-stupas","story-buddhist-pilgrimage-and-the-material-presence-of-relics"],"contentType":"heritage-place","seo":{"title":"Bhamala and the shape of a Buddhist complex | Virsapur Archives","description":"Bhamala’s cruciform stupa is the centre of a larger Buddhist complex. Excavation evidence connects its distinctive plan to chapels, monastic spaces and a history of continued use.","primaryKeyword":"Bhamala Buddhist Complex heritage","socialTitle":"Bhamala and the shape of a Buddhist complex","socialDescription":"Bhamala’s cruciform stupa is the centre of a larger Buddhist complex. Excavation evidence connects its distinctive plan to chapels, monastic spaces and a history of continued use."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Bhamala Stupa","url":"https://doam.gov.pk/public/sites/823","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"First-season excavation report, January–March 2013","url":"https://southasia.wisc.edu/wp-content/uploads/sites/499/2025/02/First-Season-Report.pdf","publisher":"Abdul Samad / Hazara University, hosted by University of Wisconsin–Madison","accessDate":"2026-10-22"},{"title":"Bhamala Buddhist Complex","url":"https://whc.unesco.org/en/tentativelists/7037/","publisher":"Pakistan submission to UNESCO World Heritage Centre","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMplanmonastery/votives~175;Samad2013reportreadall7pages,westernextension/training/coinsdated4–5c~175;UNESCO2026listednewstatusonly~35. Excluded unsupportedworldlargest/Azteccomparisons/allegations of excavationmishandling. NoTaxilaboundaryclaim.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Read the archaeological plan and sculptural discoveries through excavation evidence.","wordCount":458,"publicationHold":false,"sortOrder":41}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-butkara-i-a-stupa-built-through-successive-phases','butkara-i-a-stupa-built-through-successive-phases','review','{"id":"story-butkara-i-a-stupa-built-through-successive-phases","type":"story","slug":"butkara-i-a-stupa-built-through-successive-phases","title":"Butkara I: a stupa built through successive phases","summary":"Butkara I preserves repeated enlargement around a continuing sacred centre. Its successive stupa phases show why the history of a monument is not always a story of demolition and replacement.","body":[{"type":"paragraph","text":"At Butkara I in Swat, rebuilding did not simply erase what came before. The great stupa developed through successive enlargements that enclosed earlier forms. Its history is therefore nested within its fabric: a continuing sacred focus received new architectural bodies rather than being repeatedly abandoned for an unrelated monument elsewhere."},{"type":"paragraph","text":"Research published in Problems of Chronology in Gandharan Art describes five main building periods, corresponding to the original construction and four subsequent reconstructions of the great stupa. It credits Domenico Faccenna''s carefully recorded excavations of 1956–62 with establishing the long sequence. Counting those periods accurately matters; five phases do not mean an original building followed by five additional enlargements."},{"type":"heading","level":2,"text":"Continuity made through change"},{"type":"paragraph","text":"An enlargement can preserve the location and meaning of a monument while changing its size, surface and relationship to nearby structures. This is a different model of continuity from leaving every stone untouched. At Butkara, the earlier centre remained important even as later work transformed its appearance."},{"type":"paragraph","text":"The surrounding precinct developed too. The federal archaeological catalogue describes the great stupa among smaller votive stupas, columns and other religious structures, with schist paving and a rectangular water tank on the eastern side. The main monument was part of an accumulating environment rather than a solitary object on an empty platform."},{"type":"paragraph","text":"For someone reading the site, this creates a challenge. Features visible beside one another today may belong to different episodes of building. A complete-looking plan can conceal chronological complexity. The excavated relationships between foundations, surfaces and additions are what allow a sequence to be reconstructed."},{"type":"heading","level":2,"text":"Materials also changed"},{"type":"paragraph","text":"The specialist chronology study discusses a shift towards plastic materials and associated techniques during later phases, including the use of stucco in architectural and sculptural work. This should not be reduced to a simple story of artistic decline from stone to something less valuable. Different materials support different processes of modelling, repair and alteration."},{"type":"paragraph","text":"The study of a material change asks what was replaced, what was retained and how new work related to existing images. Those questions can reveal practical decisions and changing artistic habits without assuming that every phase had the same resources or intentions."},{"type":"heading","level":2,"text":"The image of a stupa"},{"type":"paragraph","text":"A separate study by Luca Maria Olivieri examines an incised slab from Butkara I showing a tall, towered stupa. Such an object adds another kind of evidence: architecture represented in an image. It should not automatically be treated as an exact portrait of the surviving great stupa, but it can contribute to comparisons across Buddhist visual traditions."},{"type":"paragraph","text":"The Department of Archaeology notes that sculptures from Butkara are held in Swat Museum. Moving between site and museum helps reconnect architectural setting with displaced objects. The strongest interpretation keeps the phases visible rather than compressing them into a single construction date. Butkara''s enduring identity was made through repeated acts of building, donation, adaptation and care."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Khyber Pakhtunkhwa","Architecture"],"province":"Khyber Pakhtunkhwa","district":"Swat","relatedDistrictIds":["khyber-pakhtunkhwa-swat"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-doam-3304"],"relatedStoryIds":["story-why-stupas-were-rebuilt-around-older-stupas","story-what-is-a-stupa-for","story-swat-beyond-a-single-buddhist-period","story-swats-terraces-and-archaeological-visibility"],"contentType":"heritage-place","seo":{"title":"Butkara I: a stupa built through successive phases | Virsapur Archives","description":"Butkara I preserves repeated enlargement around a continuing sacred centre. Its successive stupa phases show why the history of a monument is not always a story of demolition and replacement.","primaryKeyword":"Butkara I heritage","socialTitle":"Butkara I: a stupa built through successive phases","socialDescription":"Butkara I preserves repeated enlargement around a continuing sacred centre. Its successive stupa phases show why the history of a monument is not always a story of demolition and replacement."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Butkara-I","url":"https://doam.gov.pk/public/sites/3304","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Problems of Chronology in Gandharan Art","url":"https://www.archaeopress.com/Archaeopress/download/9781784918552","publisher":"Archaeopress, specialist Gandharan archaeology research","accessDate":"2026-10-22"},{"title":"Incised slab BI 3818 from Butkara I","url":"https://iris.unive.it/handle/10278/3722734","publisher":"Luca Maria Olivieri / Ca’ Foscari University research repository","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMcourt/tank/schistmuseum~110;ArchaeopressindexedButkara passagefiveperiods1956–62Faccenna/plasticmaterials~185;Olivieriabstractincisedslab~70. No simplefiveenlargements error: initial+foursubsequent. DatesbroadavoidconflictingGSt4subphases.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain stratified rebuilding rather than compress the site into a single construction date.","wordCount":462,"publicationHold":false,"sortOrder":42}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-mahabat-khan-mosque-above-the-bazaar','mahabat-khan-mosque-above-the-bazaar','review','{"id":"story-mahabat-khan-mosque-above-the-bazaar","type":"story","slug":"mahabat-khan-mosque-above-the-bazaar","title":"Mahabat Khan Mosque above the bazaar","summary":"Mahabat Khan Mosque belongs to Peshawar’s dense market fabric. Its raised setting, entrances and courtyard explain how a religious complex can create a distinct interior without becoming detached from the city.","body":[{"type":"paragraph","text":"Mahabat Khan Mosque is part of Peshawar''s old city rather than a monument placed outside its daily life. Approaching through the market setting, the visitor encounters a change in level and enclosure before reaching the courtyard. That transition is central to the building''s character: a distinct religious space remains closely connected to streets, trade and neighbouring structures."},{"type":"paragraph","text":"The mosque belongs to the seventeenth-century Mughal period. Its precise construction date is not consistently given in the sources: the federal catalogue supplies one date, while historical research has argued for a later foundation associated with Mahabat Khan''s governorship. A broad period is more useful here than presenting a disputed year as settled fact."},{"type":"heading","level":2,"text":"An urban complex, not only a prayer hall"},{"type":"paragraph","text":"Samra Khan''s architectural research describes the mosque together with an attached teaching establishment and a sarai. It identifies shops facing the bazaar as part of the historical relationship between the complex and its support. This setting complicates a familiar distinction between sacred monument and commercial city. The two could be spatially and economically connected."},{"type":"paragraph","text":"The study describes entrances with vaulted porches on several sides and small rooms around the court used for teaching and accommodation. Different users therefore encountered the complex through different activities. The prayer hall was the principal architectural focus, but it did not exhaust the site''s functions."},{"type":"heading","level":2,"text":"The courtyard as a clearing"},{"type":"paragraph","text":"The federal catalogue describes an open courtyard with a central ablution pool and a prayer hall on the west, framed by tall minarets. The arrangement gives the interior a clear orientation. Coming from tighter streets, the court offers a larger field of vision and a pause before the sheltered hall."},{"type":"paragraph","text":"This openness should not be mistaken for leftover space. It joins the entrances to the prayer front, accommodates movement and allows surrounding rooms to address a common centre. The tank adds a practical religious function to the composition rather than serving solely as a reflective feature for photographs."},{"type":"paragraph","text":"Inside the hall, the catalogue records three low domes and painted floral and geometric decoration. The change from an open court to a covered, decorated interior alters both light and attention. Large forms organise the room; smaller painted elements reward a slower inspection."},{"type":"heading","level":2,"text":"Surfaces with a repair history"},{"type":"paragraph","text":"Khan''s study discusses damage associated with the 1898 Peshawar fire and subsequent repair and repainting. The decoration seen today must therefore be understood through a history of maintenance, not described indiscriminately as untouched Mughal work. A repaired surface can still be historically significant, but its date and treatment belong in the interpretation."},{"type":"paragraph","text":"For visitors, the surrounding bazaar is part of the experience without making the mosque a stage for street photography. Respect worship, leave entrances clear and follow local guidance. The building''s achievement is its ability to create a composed religious interior within a dense urban setting. Its authority comes from that relationship as much as from the familiar silhouette of domes and minarets."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Khyber Pakhtunkhwa","Architecture"],"province":"Khyber Pakhtunkhwa","district":"Peshawar","relatedDistrictIds":["khyber-pakhtunkhwa-peshawar"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-doam-4399"],"relatedStoryIds":[],"contentType":"heritage-place","seo":{"title":"Mahabat Khan Mosque above the bazaar | Virsapur Archives","description":"Mahabat Khan Mosque belongs to Peshawar’s dense market fabric. Its raised setting, entrances and courtyard explain how a religious complex can create a distinct interior without becoming detached from the city.","primaryKeyword":"Mahabat Khan Mosque heritage","socialTitle":"Mahabat Khan Mosque above the bazaar","socialDescription":"Mahabat Khan Mosque belongs to Peshawar’s dense market fabric. Its raised setting, entrances and courtyard explain how a religious complex can create a distinct interior without becoming detached from the city."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Mahabat Khan Mosque","url":"https://doam.gov.pk/public/sites/4399","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"The Sethi merchants’ havelis in Peshawar, 1800–1910: form, identity and status","url":"https://westminsterresearch.westminster.ac.uk/download/45d37bbc99ca7a5c19bfb78f60d03ca4c6a3d027e174dccd6b9ee5b9a7b6a7ce/47291054/Khan_Samra_thesis.pdf","publisher":"Samra Khan / University of Westminster","accessDate":"2026-10-22"},{"title":"Mahabat Khan Mosque study","url":"https://pjhc.nihcr.edu.pk/wp-content/uploads/2020/08/4.pdf","publisher":"Pakistan Journal of History and Culture / NIHCR","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMcourt/tank/westhall3domespaint~160;Khanthesisindexedpp44–45accessmadrassasaraishops1898fire~170;NIHCRdateargumentindexedonly~50. PDFrenderfailedreported; nofullPDFclaim. Avoidhangingprisonersunsupportedstory; constructionbroad17c.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Relate the mosque’s access and spatial arrangement to Peshawar’s dense urban fabric.","wordCount":466,"publicationHold":false,"sortOrder":43}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-gor-khatri-a-place-with-more-than-one-past','gor-khatri-a-place-with-more-than-one-past','review','{"id":"story-gor-khatri-a-place-with-more-than-one-past","type":"story","slug":"gor-khatri-a-place-with-more-than-one-past","title":"Gor Khatri: a place with more than one past","summary":"Gor Khatri brings deep archaeological deposits together with a Mughal sarai, religious structures and later civic uses. Its value lies in the coexistence of these layers rather than the recovery of one supposedly pure period.","body":[{"type":"paragraph","text":"Gor Khatri resists the usual habit of giving a monument one dynasty, one function and one date. In Peshawar''s old city, a substantial enclosure contains standing architecture while archaeological deposits preserve evidence of earlier occupation below it. Religious associations, travel infrastructure and civic uses have each contributed to the place that survives."},{"type":"paragraph","text":"The Department of Archaeology describes a sarai established under Princess Jahan Ara Begum in 1640, known as Jahanabad. Its account identifies major eastern and western gateways, an internal quadrangle and ranges of cells. These features make the enclosure legible as an organised institution for movement and accommodation, not simply an empty court surrounded by walls."},{"type":"heading","level":2,"text":"Above ground and below ground"},{"type":"paragraph","text":"Pakistan''s 2026 Tentative List submission emphasises the combination of deep archaeological deposits and a standing architectural complex. The two require different forms of reading. Gateways and room ranges can be examined as built spaces; buried deposits depend on controlled excavation and recorded relationships."},{"type":"paragraph","text":"A date assigned to an excavated layer does not automatically date the wall standing above it. Conversely, a later building does not make the earlier occupation beneath it irrelevant. Gor Khatri''s significance depends on preserving the connection between these different kinds of evidence without merging them into one undifferentiated claim of antiquity."},{"type":"paragraph","text":"The nomination discusses possible earlier religious associations, but possibility should remain distinct from a securely identified structure. A name in a historical account, a tradition of pilgrimage and an excavated foundation do not carry identical evidential weight."},{"type":"heading","level":2,"text":"A courtyard with changing purposes"},{"type":"paragraph","text":"The federal catalogue records religious transformations during the Sikh period, while the newer nomination includes colonial civic reuse and the early-twentieth-century fire brigade building. These later elements are not merely clutter obscuring the Mughal sarai. They form part of the history through which the complex remained connected to the city."},{"type":"paragraph","text":"This does not mean every alteration must be valued equally or that conservation requires retaining every recent addition. It means decisions should begin with documentation and an understanding of significance. Restoring an imagined single-period appearance can erase evidence that helps explain how an urban place survived."},{"type":"heading","level":2,"text":"A place where heritage work happens"},{"type":"paragraph","text":"The Heritage Foundation of Pakistan records establishing a documentation centre at Gor Khatri in 2010 for work on Peshawar''s historic buildings. That is a modest but revealing continuation of institutional use: the complex became a setting for recording and understanding other parts of the city''s heritage."},{"type":"paragraph","text":"For a visitor, begin by reading the enclosure''s organisation, then ask which elements belong to which uses and periods. The gateway, cell, religious structure and civic building need not compete for attention. Each answers a different question about travel, authority, devotion or administration."},{"type":"paragraph","text":"Gor Khatri is most compelling when its layers remain intelligible together. Its story is not the replacement of one authentic past by a series of distractions. It is the repeated adaptation of a prominent urban place, with archaeology and architecture preserving different parts of that continuing history."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Khyber Pakhtunkhwa","Architecture"],"province":"Khyber Pakhtunkhwa","district":"Peshawar","relatedDistrictIds":["khyber-pakhtunkhwa-peshawar"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-doam-1810"],"relatedStoryIds":["story-peshawar-at-the-meeting-of-regional-routes"],"contentType":"heritage-place","seo":{"title":"Gor Khatri: a place with more than one past | Virsapur Archives","description":"Gor Khatri brings deep archaeological deposits together with a Mughal sarai, religious structures and later civic uses. Its value lies in the coexistence of these layers rather than the recovery of one supposedly pure period.","primaryKeyword":"Gor Khatri heritage","socialTitle":"Gor Khatri: a place with more than one past","socialDescription":"Gor Khatri brings deep archaeological deposits together with a Mughal sarai, religious structures and later civic uses. Its value lies in the coexistence of these layers rather than the recovery of one supposedly pure period."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Gor Khuttree","url":"https://doam.gov.pk/public/sites/1810","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Archaeological Complex of Gor Khatri","url":"https://whc.unesco.org/en/tentativelists/7035/","publisher":"Pakistan submission to UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Peshawar Heritage conservation account","url":"https://www.heritagefoundationpak.org/mi/3/peshawar-heritage","publisher":"Heritage Foundation of Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMJahanAra1640sarai/gates/cells~165;UNESCOsubsurface/firebrigade/religiouslayers~185;HeritageFoundation2010documentationcentreatGorKhatri~35. No unsupportedcontinuous2300yearproof norassertBuddhiststupacertain; no datedtempleclaim.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Compare archaeological layers and later occupations without erasing any period.","wordCount":471,"publicationHold":false,"sortOrder":44}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-sethi-house-and-the-merchant-courtyard','sethi-house-and-the-merchant-courtyard','review','{"id":"story-sethi-house-and-the-merchant-courtyard","type":"story","slug":"sethi-house-and-the-merchant-courtyard","title":"Sethi House and the merchant courtyard","summary":"Sethi House connects the display of merchant wealth with the practical organisation of privacy, business and climate. Its courtyard is the hinge between those different demands.","body":[{"type":"paragraph","text":"The courtyard at Sethi House is more than a pleasant opening within a richly decorated building. It helps organise the relationship between reception, business, domestic life and movement through the house. In the dense fabric of old Peshawar, the residence turns inward without becoming disconnected from the commercial world that made it possible."},{"type":"paragraph","text":"The federal archaeological catalogue associates the house with Seth Karim Bakhsh and records completion in 1884 after a long building campaign. Pakistan''s 2026 Tentative List submission places it within Mohallah Sethian, close to major market routes, and describes it as both a family residence and a place of business. Those functions explain why its architecture must be read through access as well as ornament."},{"type":"heading","level":2,"text":"Who can move where?"},{"type":"paragraph","text":"The nomination describes stairways, screened corridors and service spaces that organised circulation while maintaining household privacy. A visitor entering today may follow a museum-style route that differs from historic patterns of movement. Doors and passages once helped distinguish the spaces available to a business visitor from those used by household members."},{"type":"paragraph","text":"The courtyard provided a shared point of orientation without making all adjoining rooms equally public. This is an important distinction. An inward-facing plan can connect spaces visually while still controlling how they are reached. The arrangement allows proximity and separation to exist together."},{"type":"paragraph","text":"The same submission identifies ventilated lower spaces and terraces among the house''s responses to climate. Such features belong to the practical intelligence of the design. They should be studied alongside the decorative finish rather than treated as a less interesting technical background."},{"type":"heading","level":2,"text":"Light shaped by craft"},{"type":"paragraph","text":"The federal catalogue records carved entrance work, coloured glass in openings and decorated ceilings. These features change the experience of light and attention. A window is both an opening and a worked surface; a ceiling can become a field of pattern rather than a neutral cover above the room."},{"type":"paragraph","text":"Look at how ornament is positioned. Does it emphasise a doorway, frame a view or concentrate attention in a reception space? Questions of placement help explain why craftsmanship matters architecturally. The value is not simply that expensive materials appear in large quantities, but that they participate in the organisation of a room."},{"type":"heading","level":2,"text":"One house in a larger merchant quarter"},{"type":"paragraph","text":"The Heritage Foundation''s account of Peshawar conservation describes the Sethi neighbourhood as a wider group of merchant residences, some altered or lost. Its discussion of work on another property, Qadri Manzil, should not be silently transferred to Karim Bakhsh''s house. Distinct buildings can share a neighbourhood history without sharing every date or repair campaign."},{"type":"paragraph","text":"That wider context gives the surviving house added significance. A single carefully preserved interior cannot replace an entire historic residential fabric, but it can make the relationships between trade, family life and skilled work easier to understand."},{"type":"paragraph","text":"At Sethi House, let the courtyard guide the visit. Follow the thresholds, notice changes in light and compare public-facing display with more contained spaces. The richness of the building lies in the way these practical and expressive decisions are brought together."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Khyber Pakhtunkhwa","Architecture"],"province":"Khyber Pakhtunkhwa","district":"Peshawar","relatedDistrictIds":["khyber-pakhtunkhwa-peshawar"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-doam-3485"],"relatedStoryIds":["story-a-courtyard-is-more-than-empty-space","story-peshawar-at-the-meeting-of-regional-routes"],"contentType":"heritage-place","seo":{"title":"Sethi House and the merchant courtyard | Virsapur Archives","description":"Sethi House connects the display of merchant wealth with the practical organisation of privacy, business and climate. Its courtyard is the hinge between those different demands.","primaryKeyword":"Sethi House heritage","socialTitle":"Sethi House and the merchant courtyard","socialDescription":"Sethi House connects the display of merchant wealth with the practical organisation of privacy, business and climate. Its courtyard is the hinge between those different demands."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Sethi House","url":"https://doam.gov.pk/public/sites/3485","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Sethi House Tentative List submission","url":"https://whc.unesco.org/en/tentativelists/7036/","publisher":"Pakistan submission to UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Peshawar Heritage","url":"https://www.heritagefoundationpak.org/mi/3/peshawar-heritage","publisher":"Heritage Foundation of Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMcourtyardcutglassceilings1884~145;UNESCOmerchantusecirculationbasements~175;HFbroaderSethimohallahconservation~65. ImportantHFspecificprojectQadriManzilnotassumedsameKarimBukshhouse; no exactroomcount/multicourtconflict.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Investigate how reception, domestic life and craftsmanship shape a merchant residence.","wordCount":486,"publicationHold":false,"sortOrder":45}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-shahbazgarhi-an-inscription-encountered-in-the-landscape','shahbazgarhi-an-inscription-encountered-in-the-landscape','review','{"id":"story-shahbazgarhi-an-inscription-encountered-in-the-landscape","type":"story","slug":"shahbazgarhi-an-inscription-encountered-in-the-landscape","title":"Shahbazgarhi: an inscription encountered in the landscape","summary":"Shahbazgarhi’s two inscribed boulders show why a text’s physical arrangement matters. The separately carved twelfth edict also has a revealing history of nineteenth-century documentation.","body":[{"type":"paragraph","text":"At Shahbazgarhi, the arrangement of the text is part of the evidence. Ashoka''s fourteen major edicts are distributed across two boulders rather than contained on one continuous surface. That physical separation once complicated their documentation and still invites a useful question: how does the placement of words affect the way a public message is encountered?"},{"type":"paragraph","text":"Pakistan''s Tentative List description locates the inscriptions beside an old route connecting the Peshawar valley with northern valleys and Taxila. It dates them to the middle of the third century BCE and identifies Kharoshthi writing, read from right to left. The route, the rock and the script belong together in the interpretation."},{"type":"heading","level":2,"text":"The missing section that was nearby"},{"type":"paragraph","text":"Classicist Llewelyn Morgan, drawing on research undertaken with archaeologist Luca Olivieri, recounts a revealing episode in nineteenth-century scholarship. Charles Masson documented the principal inscription in 1838. Comparison with other versions showed that the twelfth edict was missing from the record. Harold Deane subsequently identified it on a separate nearby rock in 1888."},{"type":"paragraph","text":"This was a change in scholarly documentation, not proof that local people had been unaware of the second boulder. The distinction matters whenever an archaeological account uses the language of discovery. What was new to a visiting recorder or a learned society was not necessarily new to the community around the site."},{"type":"paragraph","text":"Morgan notes the separate treatment of the twelfth edict and discusses its emphasis on respect between religious groups. He offers the interpretation that this message may have had particular importance in the region. That is a historically informed reading of placement, not a fact explicitly explained by the rock''s location alone."},{"type":"heading","level":2,"text":"Reading words and reading space"},{"type":"paragraph","text":"An edition that prints all fourteen edicts in sequence makes comparison easier, but it can conceal the physical experience of the originals. At Shahbazgarhi, moving between surfaces is part of encountering the text. Letter size, carving and separation can carry information that a plain transcription does not preserve."},{"type":"paragraph","text":"The same principle applies to photographs. A tightly cropped image may help specialists examine letters while removing the inscription from its landscape. A wider record can show relationships between boulders and approaches but make the text illegible. Both forms of documentation have value because they answer different questions."},{"type":"heading","level":2,"text":"An imperial message, not a simple mirror of society"},{"type":"paragraph","text":"The edicts express a ruler''s declared principles. They should not be treated as automatic proof that every subject followed those principles or that all religious relations were harmonious. The gap between a statement of intent and lived practice is itself a historical question."},{"type":"paragraph","text":"For visitors, the most meaningful approach is to preserve the connection between text and place. Observe the boulders without touching or marking them, consult a reliable translation and notice how the words have been arranged. Shahbazgarhi''s importance is not exhausted by its age. It also shows how political ideas were given a durable physical presence, and how careful documentation can recover details that a seemingly complete record once missed."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Khyber Pakhtunkhwa","Architecture"],"province":"Khyber Pakhtunkhwa","district":"Mardan","relatedDistrictIds":["khyber-pakhtunkhwa-mardan"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-doam-4621"],"relatedStoryIds":["story-reading-ashokas-edicts-as-material-objects","story-kharoshthi-and-brahmi-in-the-north-west","story-reading-a-bilingual-inscription"],"contentType":"heritage-place","seo":{"title":"Shahbazgarhi: an inscription encountered in the landscape | Virsapur Archives","description":"Shahbazgarhi’s two inscribed boulders show why a text’s physical arrangement matters. The separately carved twelfth edict also has a revealing history of nineteenth-century documentation.","primaryKeyword":"Shahbazgarhi Rock Edicts heritage","socialTitle":"Shahbazgarhi: an inscription encountered in the landscape","socialDescription":"Shahbazgarhi’s two inscribed boulders show why a text’s physical arrangement matters. The separately carved twelfth edict also has a revealing history of nineteenth-century documentation."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Shahbazgarhi Rock Edicts","url":"https://whc.unesco.org/en/tentativelists/1880/","publisher":"Pakistan submission to UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Ashoka Rock Edicts, Mardan","url":"https://doam.gov.pk/public/sites/4621","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Edict XII, lost and found","url":"https://llewelynmorgan.com/2021/11/07/edict-xii-lost-found/","publisher":"Llewelyn Morgan, Oxford classicist and co-editor of Harold Deane research","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"UNESCOscript2rocks/routes~155;MorganoriginalresearchMasson1838Deane1888separateXII/toleration~190; DOAMonlycorroboration notadditionalbudget. No quotedtranslation/copyingmethods instructions. Colonialdocumentingnotfirstlocaldiscovery; interpretationofplacementqualified.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain why the placement and language of rock texts matter to interpretation.","wordCount":470,"publicationHold":false,"sortOrder":46}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-bala-hisar-fort-and-peshawars-changing-skyline','bala-hisar-fort-and-peshawars-changing-skyline','review','{"id":"story-bala-hisar-fort-and-peshawars-changing-skyline","type":"story","slug":"bala-hisar-fort-and-peshawars-changing-skyline","title":"Bala Hisar Fort and Peshawar’s changing skyline","summary":"Peshawar’s Bala Hisar is a repeatedly rebuilt fort whose prominence outlasts any one ruling period. Historical descriptions, surviving masonry and present institutional use need to be read separately.","body":[{"type":"paragraph","text":"Bala Hisar''s position in Peshawar makes it a landmark even for people who never enter it. Its mass contributes to the city''s skyline and provides a visible reminder that political authority has repeatedly occupied and reshaped prominent ground. The fort''s history, however, cannot be reduced to a single surviving building from one ruling dynasty."},{"type":"paragraph","text":"The federal archaeological catalogue describes repeated destruction and rebuilding through Mughal, Durrani, Sikh and British periods. It also preserves a historical description of Shah Shuja''s residence, with an oblong court, water features and a raised setting for royal appearance. That account concerns an earlier arrangement; it should not be used as a literal description of every space visible today."},{"type":"heading","level":2,"text":"A place can outlast its architecture"},{"type":"paragraph","text":"The persistence of a fortified location does not mean its walls have remained unchanged. The catalogue records replacement of earthen walls with brick masonry under British rule. Such changes alter material, profile and construction while allowing the site''s political and symbolic prominence to continue."},{"type":"paragraph","text":"This is why an origin story and a building date are not the same thing. A reference to a fort in an early text may establish the importance of a location without dating a particular parapet or gateway. A careful architectural history asks which evidence belongs to the place, which to a structure and which to an episode of reconstruction."},{"type":"paragraph","text":"The distinction is especially important because Bala Hisar is also the name of an archaeological mound at Charsadda. That is a separate site. Excavation accounts for the Charsadda mound should not be imported into the story of Peshawar''s standing fortress simply because the names match."},{"type":"heading","level":2,"text":"A continuing institutional setting"},{"type":"paragraph","text":"Radio Pakistan''s August 2026 report describes an organised university-student visit to Peshawar''s fort, including its museum and a briefing by Frontier Corps Khyber Pakhtunkhwa North. A February 2025 report likewise records a planned educational tour. These establish documented visits, not a general guarantee of unrestricted public entry."},{"type":"paragraph","text":"For anyone planning a visit, current access and photography arrangements require direct confirmation through the relevant local authorities. A photograph from an event, a social-media account or an old visitor schedule is not a reliable substitute. The fort remains part of a contemporary institutional setting rather than a neutral open-air ruin."},{"type":"heading","level":2,"text":"Seeing the fort from the city"},{"type":"paragraph","text":"The Peshawar Development Authority uses Bala Hisar as an identifiable city landmark. Its visibility is therefore part of the public experience even when internal access is limited. From permitted public viewpoints, the relationship between elevated enclosure and surrounding urban movement can be considered without intruding on controlled areas."},{"type":"paragraph","text":"The strongest interpretation holds three histories apart but connected: the long importance of the location, the successive remaking of its architecture and its present use. Bala Hisar''s authority in the skyline comes partly from that continuity of prominence, while its actual fabric reminds us that continuity is often produced through change."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Khyber Pakhtunkhwa","Architecture"],"province":"Khyber Pakhtunkhwa","district":"Peshawar","relatedDistrictIds":["khyber-pakhtunkhwa-peshawar"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-doam-4607"],"relatedStoryIds":["story-peshawar-at-the-meeting-of-regional-routes"],"contentType":"heritage-place","seo":{"title":"Bala Hisar Fort and Peshawar’s changing skyline | Virsapur Archives","description":"Peshawar’s Bala Hisar is a repeatedly rebuilt fort whose prominence outlasts any one ruling period. Historical descriptions, surviving masonry and present institutional use need to be read separately.","primaryKeyword":"Bala Hisar Fort heritage","socialTitle":"Bala Hisar Fort and Peshawar’s changing skyline","socialDescription":"Peshawar’s Bala Hisar is a repeatedly rebuilt fort whose prominence outlasts any one ruling period. Historical descriptions, surviving masonry and present institutional use need to be read separately."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Bala Hisar Fort","url":"https://doam.gov.pk/public/sites/4607","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Students visit Bala Hisar Fort, 21 August 2026","url":"https://new.radio.gov.pk/21-08-2026/students-from-kp-universities-visit-bala-hisar-fort-in-peshawar","publisher":"Radio Pakistan","accessDate":"2026-10-22"},{"title":"Educational tour for students, 28 February 2025","url":"https://www.radio.gov.pk/28-02-2025/fc-kp-north-organizes-educational-tour-for-students-of-tribal-districts","publisher":"Radio Pakistan","accessDate":"2026-10-22"},{"title":"Peshawar Development Authority","url":"https://pda.kp.gov.pk/","publisher":"Peshawar Development Authority","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMrebuildhistoryShahShujacourt/Britishbrick~190;Radio2026organisedvisitmuseum~85;2025~30;PDAlandmarkimagecaption~15. ExplicitdoNOTconfuseCharsaddaBalaHisarmounds; currentaccessnotverifieddoNOTpublishhours. Exteriorinterpretationoriginal.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Distinguish successive fort histories and contemporary access restrictions from promotional claims.","wordCount":459,"publicationHold":false,"sortOrder":47}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-damb-sadaat-and-the-archaeology-of-the-quetta-valley','damb-sadaat-and-the-archaeology-of-the-quetta-valley','review','{"id":"story-damb-sadaat-and-the-archaeology-of-the-quetta-valley","type":"story","slug":"damb-sadaat-and-the-archaeology-of-the-quetta-valley","title":"Damb Sadaat and the archaeology of the Quetta valley","summary":"Damb Sadaat places the Quetta valley within the archaeology of early regional communities. Its pottery, recorded excavations and wider comparisons help challenge a history focused only on the largest Indus cities.","body":[{"type":"paragraph","text":"The archaeology of early Pakistan is often narrated through a small number of great cities. Damb Sadaat, in the Quetta valley, invites a wider view. Its importance lies in the evidence of a regional settlement and in the comparisons that connect pottery, objects and building remains across a landscape larger than any one urban centre."},{"type":"paragraph","text":"The Department of Archaeology''s catalogue records a long history of investigation, including visits by Aurel Stein, later researchers and Walter Fairservis. It describes excavated pottery assemblages and structural evidence used to establish a sequence. The entry''s chronological labels are not fully consistent, so they should not be compressed into a precise foundation date without returning to the excavation publications."},{"type":"heading","level":2,"text":"A regional research programme"},{"type":"paragraph","text":"The Penn Museum Archives'' biographical account places Fairservis''s work in the Quetta–Pishin valley in 1950–51 and identifies Damb Sadaat and Kili Ghul Mohammad among the sites he investigated. The American Museum of Natural History''s publication record dates Excavations in the Quetta Valley to 1956. These records establish the history of research; they do not replace the detailed evidence in the excavation volume."},{"type":"paragraph","text":"Thinking regionally changes the questions. Instead of asking only whether a settlement resembles Mohenjo Daro, we can ask how communities in the valley made objects, organised space and participated in exchange. Differences become evidence rather than deficiencies measured against a larger city."},{"type":"heading","level":2,"text":"Pottery as a relationship"},{"type":"paragraph","text":"A pottery assemblage is more than a collection of attractive painted fragments. Shape, fabric, decoration and manufacturing traces can be compared, while the deposits in which pieces occur establish their sequence. The relationship between these kinds of information matters: visual similarity alone does not prove that two sites were occupied at exactly the same moment."},{"type":"paragraph","text":"Nor does a shared style automatically identify a single population. Vessels, skills and decorative ideas can move in different ways. A careful interpretation distinguishes the observation of resemblance from explanations involving trade, learning or migration. Those explanations require additional evidence."},{"type":"heading","level":2,"text":"Beyond one city-centred story"},{"type":"paragraph","text":"Jonathan Mark Kenoyer''s account of the Indus tradition includes Damb Sadaat among regional sites yielding seals before the fully developed urban phase. He discusses such objects in relation to economic and social differentiation, while acknowledging the difficulty of measuring those differences archaeologically. This places the settlement within a broader discussion without making every seal proof of the same political system."},{"type":"paragraph","text":"The contribution of a smaller site is therefore not limited to supplying a preliminary chapter before the famous cities appear. It can show local combinations of practices and materials that a city-centred narrative would miss."},{"type":"paragraph","text":"For readers encountering Damb Sadaat through museum objects or excavation drawings rather than a visit, provenance is especially valuable. Ask which trench or phase an object belongs to and which comparisons support its interpretation. The site''s significance grows through those recorded relationships: a regional community becomes part of a larger history without losing the particular evidence through which it is known."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Balochistan","Architecture"],"province":"Balochistan","district":"Quetta","relatedDistrictIds":["balochistan-quetta"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["major-doam-8773"],"relatedStoryIds":["story-quetta-valley-before-the-modern-city"],"contentType":"heritage-place","seo":{"title":"Damb Sadaat and the archaeology of the Quetta valley | Virsapur Archives","description":"Damb Sadaat places the Quetta valley within the archaeology of early regional communities. Its pottery, recorded excavations and wider comparisons help challenge a history focused only on the largest Indus cities.","primaryKeyword":"Damb Sadaat heritage","socialTitle":"Damb Sadaat and the archaeology of the Quetta valley","socialDescription":"Damb Sadaat places the Quetta valley within the archaeology of early regional communities. Its pottery, recorded excavations and wider comparisons help challenge a history focused only on the largest Indus cities."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Damb Sadaat","url":"https://doam.gov.pk/public/sites/8773","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Walter A. Fairservis papers: biographical finding aid","url":"https://findingaids.library.upenn.edu/records/UPENN_MUSEUM_PU-MU.2012","publisher":"Penn Museum Archives","accessDate":"2026-10-22"},{"title":"The Indus Valley Tradition of Pakistan and western India","url":"https://www.harappa.com/sites/default/files/pdf/Kenoyer1991%20Indus%20Valley%20Tradition.pdf","publisher":"Jonathan Mark Kenoyer","accessDate":"2026-10-22"},{"title":"Excavations in the Quetta Valley: publication record","url":"https://field.biodiversitylibrary.org/bibliography/88274","publisher":"American Museum of Natural History Library / Biodiversity Heritage Library","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMresearchvisitsassemblages~140;Penn1950–51regionalwork~75(sharedbudget48another60);Kenoyerregionalisationseals~110;AMNH1956catalogueonly~30. ConflictingDOAM4millenniumvs3000–1millenniumavoided. No claimfullFairservisvolumeclose-read.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Use a local sequence to widen the narrative beyond the great Indus cities.","wordCount":469,"publicationHold":false,"sortOrder":48}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-killi-gul-mohammad-what-small-excavations-can-reveal','killi-gul-mohammad-what-small-excavations-can-reveal','review','{"id":"story-killi-gul-mohammad-what-small-excavations-can-reveal","type":"story","slug":"killi-gul-mohammad-what-small-excavations-can-reveal","title":"Killi Gul Mohammad: what small excavations can reveal","summary":"Killi Gul Mohammad demonstrates both the value and the limits of a small excavation sample. Its early settlement sequence is important, but absence from a narrow trench cannot establish absence from an entire community.","body":[{"type":"paragraph","text":"Killi Gul Mohammad is important not because every aspect of its early community has been recovered, but because a limited excavation revealed a sequence that helped frame larger questions. Near Quetta, the mound became part of twentieth-century research into settlement before the mature Indus cities. Its evidence also offers a clear lesson in archaeological sampling."},{"type":"paragraph","text":"The federal catalogue places the site in the northern part of the Quetta valley, near the Quetta–Chaman route, and records excavation by Walter Fairservis in 1950–51. The Penn Museum Archives'' account situates this work within his broader survey of the Quetta–Pishin region. A single trench belonged to a larger effort to understand how settlements related across the valley."},{"type":"heading","level":2,"text":"A deep view is not a wide view"},{"type":"paragraph","text":"In a discussion of early shell use, archaeologist Jonathan Mark Kenoyer describes Fairservis''s excavation at Killi Gul Mohammad as a deep sondage: a restricted intervention designed to investigate the sequence below the surface. It revealed occupation extending from a phase without pottery into later periods with ceramics."},{"type":"paragraph","text":"Such a trench can be highly informative about succession. It may show one deposit above another and allow changes in material to be studied through depth. Its limitation is spatial: the sampled area cannot reveal every activity that took place across the settlement."},{"type":"paragraph","text":"Imagine investigating a modern neighbourhood through one narrow slice of ground. The sequence might be clear, but whether that slice crossed a kitchen, workshop, yard or passage would strongly affect the objects recovered. The same principle applies to an ancient mound, even when its surviving deposits are much more complex."},{"type":"heading","level":2,"text":"An absence that needs interpretation"},{"type":"paragraph","text":"Kenoyer notes that shell was not reported from the lower levels and was also absent from the published account of succeeding deposits. He cautions that the sample may not adequately represent the region''s material culture. The observation is not a licence to invent missing objects; it is a reason to avoid an overly broad conclusion from a restricted sample."},{"type":"paragraph","text":"“No shell was reported in this excavation” and “this community had no contact with shell materials” are different statements. The first describes an evidence base. The second proposes a historical explanation that would need wider support. Preserving the difference is one of archaeology''s most useful habits."},{"type":"heading","level":2,"text":"Pottery and changing practice"},{"type":"paragraph","text":"The federal catalogue emphasises changes in pottery manufacture across the site''s sequence. Those changes can be investigated through fabrics, forming methods, firing and decoration. They should not be turned into a simplistic ladder from primitive to advanced people. Different techniques answer different needs and may coexist."},{"type":"paragraph","text":"Killi Gul Mohammad therefore contributes both substantive evidence and a lesson in how to use it. Its early sequence matters, while the limits of excavation remain part of every responsible account. For the reader, the most valuable question is not merely how old the mound is, but what was actually sampled and how that sample supports the story being told."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Balochistan","Architecture"],"province":"Balochistan","district":"Quetta","relatedDistrictIds":["balochistan-quetta"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["major-doam-8867"],"relatedStoryIds":["story-quetta-valley-before-the-modern-city"],"contentType":"heritage-place","seo":{"title":"Killi Gul Mohammad: what small excavations can reveal | Virsapur Archives","description":"Killi Gul Mohammad demonstrates both the value and the limits of a small excavation sample. Its early settlement sequence is important, but absence from a narrow trench cannot establish absence from an entire community.","primaryKeyword":"Killi Gul Mohammad heritage","socialTitle":"Killi Gul Mohammad: what small excavations can reveal","socialDescription":"Killi Gul Mohammad demonstrates both the value and the limits of a small excavation sample. Its early settlement sequence is important, but absence from a narrow trench cannot establish absence from an entire community."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Kili Gul Mohammad","url":"https://doam.gov.pk/public/sites/8867","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Shell Trade and Shell Working during the Neolithic and Early Chalcolithic at Mehrgarh","url":"https://www.harappa.com/sites/default/files/pdf/Kenoyer1995_Shell%20Trade%20and%20Shell%20Working%20during%20the%20Neolith.pdf","publisher":"Jonathan Mark Kenoyer","accessDate":"2026-10-22"},{"title":"Walter A. Fairservis papers: biographical finding aid","url":"https://findingaids.library.upenn.edu/records/UPENN_MUSEUM_PU-MU.2012","publisher":"Penn Museum Archives","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMlocationpotterysequence~105;Kenoyerp571limitedsondageaceramic/shellabsence~185;PennFairservis1950–51~55. No obsoleteabsoluteearlydates; DOAMStein1094typoomitted. Distinctmethodfocusvsarticle47.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain the evidence and limits of an early village sequence.","wordCount":464,"publicationHold":false,"sortOrder":49}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-nausharo-between-village-and-urban-worlds','nausharo-between-village-and-urban-worlds','review','{"id":"story-nausharo-between-village-and-urban-worlds","type":"story","slug":"nausharo-between-village-and-urban-worlds","title":"Nausharo between village and urban worlds","summary":"Nausharo links regional Balochistan traditions with the Indus urban world through a sequence of buildings and objects. Its pottery and figurines reveal both connections and differences across time.","body":[{"type":"paragraph","text":"Nausharo is valuable because it complicates a clean dividing line between regional village traditions and an Indus urban world. The site preserves a sequence through which changes in architecture and material culture can be examined. Its significance is not that every phase looks the same, but that related and changing practices can be studied in their archaeological order."},{"type":"paragraph","text":"The Department of Archaeology locates Nausharo in the Bolan plain of Kachhi and records four principal cultural periods. Its catalogue includes dwelling structures, painted pottery, human and animal figurines and Harappan seals among the evidence. This range allows questions about everyday activity and representation to sit beside those about wider cultural connections."},{"type":"heading","level":2,"text":"Sequence before labels"},{"type":"paragraph","text":"Jarrige, Didier and Quivron compare Nausharo''s Harappan periods II, III and IV with sequences at other excavated sites. Such comparison is not simply a matter of matching famous names. It depends on relating material characteristics to stratigraphy and, where available, independent dating evidence."},{"type":"paragraph","text":"A period label is a tool for organising evidence, not an event that every household experienced on the same day. Changes in vessels, buildings and other objects need not all occur together. A useful account therefore asks which practices continued, which changed and how securely those changes can be placed in time."},{"type":"paragraph","text":"The authors also identify a minority component of material associated with the Oxus world in Nausharo''s later Harappan period. That observation broadens the geographical discussion without requiring the whole settlement to be assigned a new identity. An assemblage can contain objects with different connections."},{"type":"heading","level":2,"text":"Figurines and local choices"},{"type":"paragraph","text":"Jonathan Mark Kenoyer''s comparison of early art draws attention to greater variety among human figurines from Mehrgarh and Nausharo than in the Harappa material he discusses. He identifies applied clay decoration as an important technique at the Balochistan sites, contrasting it with other approaches visible at Harappa."},{"type":"paragraph","text":"This comparison shows why resemblance and difference deserve equal attention. Shared participation in a wider tradition does not require identical visual habits. How a figure was formed or ornamented can carry evidence about learned practices and choices in making, even where the object''s exact social or religious use remains uncertain."},{"type":"paragraph","text":"Kenoyer presents further comparative study as a research opportunity. That phrasing should be retained rather than converted into a settled explanation of social identity. A human figurine is not automatically a goddess, a toy or a portrait; interpretation depends on context and a defensible argument."},{"type":"heading","level":2,"text":"A connected place with its own evidence"},{"type":"paragraph","text":"Nausharo helps replace a simple centre-and-periphery picture with a more demanding one. Regional communities could participate in broad networks while retaining particular techniques and histories. The task is to demonstrate those relationships through objects and deposits, not assume them from a map."},{"type":"paragraph","text":"For readers, the best route into the site is to follow one class of evidence through its recorded sequence, then compare it with another. Pottery, figurines and architecture may tell overlapping but different stories. Together they make Nausharo an important place for understanding how cultural integration can occur alongside local continuity and change."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Balochistan","Architecture"],"province":"Balochistan","district":"Kachhi","relatedDistrictIds":["balochistan-kachhi"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["major-doam-8927"],"relatedStoryIds":["story-kachi-plain-the-landscape-around-early-villages"],"contentType":"heritage-place","seo":{"title":"Nausharo between village and urban worlds | Virsapur Archives","description":"Nausharo links regional Balochistan traditions with the Indus urban world through a sequence of buildings and objects. Its pottery and figurines reveal both connections and differences across time.","primaryKeyword":"Nausharo heritage","socialTitle":"Nausharo between village and urban worlds","socialDescription":"Nausharo links regional Balochistan traditions with the Indus urban world through a sequence of buildings and objects. Its pottery and figurines reveal both connections and differences across time."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Nausharo","url":"https://doam.gov.pk/public/sites/8927","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Shahr-i Sokhta and the chronology of the Indo-Iranian regions","url":"https://www.persee.fr/doc/paleo_0153-9345_2011_num_37_2_5420?pageId=T2_9","publisher":"Jean-François Jarrige, Aurore Didier and Gonzague Quivron / Paléorient","accessDate":"2026-10-22"},{"title":"Early Developments of Art, Symbol, Technology in the Indus Valley Tradition","url":"https://www.harappa.com/content/early-developments-art-symbol-technology-indus-valley-tradition-0","publisher":"Jonathan Mark Kenoyer","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMlocation4periodsdwellingspaintedpotteryseals~90;JarrigeetalsequenceIIIIIIVcomparisonandminorityOxus~165;Kenoyerfigurineappliquedifferences/researchquestion~130. No obsoleteMehrgarhchronology reused; no certainmigrations inferredfromobjects;DOAMmixedsurfacePiraklistomitted.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Follow material changes through the site’s sequence without assuming a single abrupt transition.","wordCount":486,"publicationHold":false,"sortOrder":50}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-nindowari-and-the-kulli-cultural-landscape','nindowari-and-the-kulli-cultural-landscape','review','{"id":"story-nindowari-and-the-kulli-cultural-landscape","type":"story","slug":"nindowari-and-the-kulli-cultural-landscape","title":"Nindowari and the Kulli cultural landscape","summary":"Nindowari connects a substantial settlement in the Ornach valley with the distinctive animal imagery of the Kulli cultural world.","body":[{"type":"paragraph","text":"Nindowari offers an important correction to a map of ancient Pakistan dominated by Harappa and Moenjodaro. The Department of Archaeology and Museums locates the settlement in the agricultural Ornach valley, south of Khuzdar, and describes a group of four mounds. This was a place with its own substantial archaeological footprint, not simply a point on a route between better-known cities. Its significance becomes clearer when settlement evidence is considered alongside the distinctive visual language associated with the Kulli culture."},{"type":"paragraph","text":"The official catalogue records four excavation seasons directed by Jean-Marie Casal between 1962 and 1966. That history matters: a mound seen today is not the same thing as a complete picture of its former settlement. Excavation exposes selected areas and generates records, while much of the evidence may remain below ground. The visible outline alone cannot establish how every part of Nindowari functioned or how its occupation changed."},{"type":"heading","level":2,"text":"An animal-shaped vessel and a larger world"},{"type":"paragraph","text":"A painted ceramic drinking vessel in the Musée Guimet provides a particularly vivid introduction to Kulli workmanship. Modelled as a humped bull, it combines the volume of an animal with the practical idea of a container. The museum attributes this rare piece and a matching example to Nindowari and dates them to approximately 2300–2000 BCE. Its catalogue places Kulli alongside, rather than after, the urban Indus civilisation."},{"type":"paragraph","text":"The museum emphasises the modelling of the animal’s body and suggests a possible ritual setting. Possible is the important word. An arresting shape does not by itself disclose a ceremony, the person who used it, or a belief shared by an entire population. Nor should the object’s museum attribution be silently upgraded into a detailed excavation history: the public catalogue records acquisition in 2014, but does not supply a complete chain from an excavated context to the collection."},{"type":"heading","level":2,"text":"Read connection without erasing difference"},{"type":"paragraph","text":"Looking at the vessel beside the settlement invites a productive question: how can a community participate in a wider world while retaining a recognisable way of making things? Comparison need not reduce Kulli to a provincial imitation of the Indus cities. An animal model, a painted surface and a settlement plan are different kinds of evidence; each may illuminate a different relationship."},{"type":"paragraph","text":"For a heritage atlas, the strongest presentation is therefore a connection rather than a claim of equivalence. Nindowari’s place record can lead to the history of excavation, then to a carefully identified museum object, while keeping the evidence for each separate. The museum photograph cannot stand in for the appearance of the archaeological site, and the site pin cannot establish the provenance of every object labelled Kulli."},{"type":"paragraph","text":"Nindowari rewards this slower approach. Its importance lies not in competing for an oldest or largest superlative, but in making the cultural variety of the third millennium BCE visible. A regional settlement and a finely modelled vessel together open questions about making, exchange and identity that a single civilisational label would conceal."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Balochistan","Architecture"],"province":"Balochistan","district":"Khuzdar","relatedDistrictIds":["balochistan-khuzdar"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["major-doam-8933"],"relatedStoryIds":["story-reading-kulli-material-culture-without-inventing-a-kingdom"],"contentType":"heritage-place","seo":{"title":"Nindowari and the Kulli cultural landscape | Virsapur Archives","description":"Nindowari connects a substantial settlement in the Ornach valley with the distinctive animal imagery of the Kulli cultural world.","primaryKeyword":"Nindowari heritage","socialTitle":"Nindowari and the Kulli cultural landscape","socialDescription":"Nindowari connects a substantial settlement in the Ornach valley with the distinctive animal imagery of the Kulli cultural world."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Nindowari","url":"https://doam.gov.pk/public/sites/8933","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Vase à boire (rython) en forme de zébu","url":"https://www.guimet.fr/fr/nos-collections/afghanistan-pakistan/vase-boire-rython-en-forme-de-zebu","publisher":"Musée Guimet","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM supports location, four mounds and Casal excavations, approximately 110 derived words. Guimet supports attributed object, dates and interpretation, approximately 175 words. Museum attribution is not represented as a documented excavation provenance. Remaining prose is explicitly comparative interpretation.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explore settlement and material connections while keeping archaeological labels distinct from ethnic identities.","wordCount":473,"publicationHold":false,"sortOrder":51}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-sutkagen-dor-an-indus-place-far-from-the-core-cities','sutkagen-dor-an-indus-place-far-from-the-core-cities','review','{"id":"story-sutkagen-dor-an-indus-place-far-from-the-core-cities","type":"story","slug":"sutkagen-dor-an-indus-place-far-from-the-core-cities","title":"Sutkagen-Dor: an Indus place far from the core cities","summary":"Sutkagen-Dor invites a careful reading of stone walls, river geography and the limits of the familiar “Harappan port” description.","body":[{"type":"paragraph","text":"Sutkagen-Dor sits far from the Indus cities that usually dominate accounts of the civilisation. Its position in western Balochistan makes it tempting to explain the site immediately as a port or trading outpost. Those labels may help frame a question, but they should not replace the evidence. The Department of Archaeology and Museums describes a settlement west of Suntsar, beside the Dasht river plain, partly constructed on a sandstone outcrop. Rock, river and built enclosure all belong in the story."},{"type":"paragraph","text":"The first useful distinction is between present geography and ancient geography. A modern map shows where a river, coast or road lies now. It does not automatically show the conditions under which a settlement operated several thousand years ago. Calling a place maritime requires more than drawing a line to the sea; it requires evidence for waterways, shorelines, movement and chronology."},{"type":"heading","level":2,"text":"What the investigations recorded"},{"type":"paragraph","text":"An illustrated account published by Harappa.com brings together earlier investigations and photographs from Randall Law’s visit. It discusses George Dales’s 1960 work, including limited trenches, substantial stone walls, a narrow southwestern entrance and evidence of successive building phases. The photographs are especially useful because they distinguish surviving fabric from a reconstructed plan. A wall foundation is visible evidence; a fully imagined fortified town is an interpretation."},{"type":"paragraph","text":"The article also records the mixture of mud-brick construction, rock outcrops and pottery evidence used to understand the site. Its proposed explanations for exchange and coastal connections remain arguments, not inscriptions left by the inhabitants. Even the customary terms citadel and lower town should be read as archaeological descriptions that organise the evidence, rather than ancient place names or proof of a particular government."},{"type":"paragraph","text":"Dales’s investigations were published as a dedicated volume by the University of California’s Archaeological Research Facility in 1992. That publication history offers a route into the excavation record beyond the attractive certainty of a short tourist caption."},{"type":"heading","level":2,"text":"A frontier on whose map?"},{"type":"paragraph","text":"The word remote depends on where the observer starts. From a map centred on Harappa, Sutkagen-Dor looks peripheral. From a map concerned with Makran, river corridors and connections westward, the same location prompts different questions. This is an interpretive shift, not proof that any single route or trading function has been established."},{"type":"paragraph","text":"A useful reading of the site holds several scales together: the passage through an enclosure, the relationship between building and rocky ground, and the much wider problem of regional exchange. None should erase the others. Monumental walls do not tell us everything about the daily work of a settlement, while a trade-route diagram cannot substitute for objects recovered in documented contexts."},{"type":"paragraph","text":"Sutkagen-Dor’s value lies partly in that unresolved relationship. It extends the geographical imagination of Indus archaeology without requiring an invented harbour, a named merchant community or a complete explanation of its abandonment. The most compelling discovery is not a ready-made answer, but the opportunity to see how a difficult archaeological question is assembled from modest, specific pieces of evidence."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Balochistan","Architecture"],"province":"Balochistan","district":"Gwadar","relatedDistrictIds":["balochistan-gwadar"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["major-doam-8639"],"relatedStoryIds":["story-indus-exchange-without-a-modern-trade-map","story-coastal-sites-and-a-moving-shoreline","story-makran-through-settlement-and-maritime-connections","story-makrans-inland-routes-and-coastal-horizons"],"contentType":"heritage-place","seo":{"title":"Sutkagen-Dor: an Indus place far from the core cities | Virsapur Archives","description":"Sutkagen-Dor invites a careful reading of stone walls, river geography and the limits of the familiar “Harappan port” description.","primaryKeyword":"Sutkagen-Dor heritage","socialTitle":"Sutkagen-Dor: an Indus place far from the core cities","socialDescription":"Sutkagen-Dor invites a careful reading of stone walls, river geography and the limits of the familiar “Harappan port” description."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Sutkagen Dor","url":"https://doam.gov.pk/public/sites/8639","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Sutkagen Dor: An Investigation of the Western-most Harappan Trading Post","url":"https://www.harappa.com/content/sutkagen-dor-investigation-western-most-harappan-trading-post","publisher":"Harappa.com, Kaiser Tufail with photographs by Randall Law","accessDate":"2026-10-22"},{"title":"Explorations on the Makran Coast, Pakistan: A Search for Paradise","url":"https://arf.berkeley.edu/publications/explorations-makran-coast-pakistan-search-paradise","publisher":"Archaeological Research Facility, University of California, Berkeley","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM location and sandstone outcrop approximately 60 words. Harappa essay read closely, approximately 185 derived words; speculative coastal reconstruction and definite port/garrison/brick-kiln identifications excluded. Berkeley publication metadata checked; book not claimed fully read. Analytical paragraphs distinguish observed evidence from hypotheses.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Assess frontier and exchange interpretations against the actual site evidence.","wordCount":480,"publicationHold":false,"sortOrder":52}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-ziarat-residency-memory-reconstruction-and-a-timber-building','ziarat-residency-memory-reconstruction-and-a-timber-building','review','{"id":"story-ziarat-residency-memory-reconstruction-and-a-timber-building","type":"story","slug":"ziarat-residency-memory-reconstruction-and-a-timber-building","title":"Ziarat Residency: memory, reconstruction and a timber building","summary":"Ziarat Residency is both a place associated with Jinnah and a reconstructed monument whose material history should remain visible.","body":[{"type":"paragraph","text":"Ziarat Residency asks visitors to hold two histories together. One concerns a building associated with Muhammad Ali Jinnah’s final year. The other concerns the destruction and reconstruction of that building long after his death. Both are necessary to understand what stands in Ziarat today. Treating the monument as an untouched capsule of 1948 would obscure an important part of its significance."},{"type":"paragraph","text":"The Department of Archaeology and Museums describes the Residency’s earlier role as a British administrative summer residence. Its account identifies stone construction with wooden floors and balconies, arranged over two storeys. Timber strongly shapes its appearance, but describing the whole building simply as a wooden house misses that material combination. The same catalogue connects Jinnah’s stay to the period following his inauguration of the State Bank in July 1948."},{"type":"paragraph","text":"Association is not the same as burial. The Residency is a place of residence and remembrance; it should not be described as Jinnah’s tomb. Keeping that distinction clear gives the building a more precise role within Pakistan’s commemorative geography."},{"type":"heading","level":2,"text":"Reconstruction is part of the history"},{"type":"paragraph","text":"The Residency was attacked in June 2013. An Associated Press of Pakistan report carried by The Express Tribune records the inauguration of the rehabilitated building in August 2014 and identifies architect Nayyar Ali Dada with the project. Those dates make reconstruction a major chapter, not a minor maintenance footnote."},{"type":"paragraph","text":"Sanam Maher’s contemporary reporting explores a difficult question behind the work: whether restoring the character of a cherished place is equivalent to conserving all of its surviving material. Her account describes the architect’s concern with retaining the spirit of the building, while also acknowledging earlier interventions. This is not evidence that every component visible today is original. It is evidence that the project involved choices about what continuity should mean after severe loss."},{"type":"heading","level":2,"text":"What a visitor should be able to distinguish"},{"type":"paragraph","text":"A clear interpretation could separate three layers: the building’s administrative origins, Jinnah’s association with it, and the later destruction and recovery. Each layer has its own documents, photographs and material questions. An old exterior photograph may help explain a reconstructed balcony, but it cannot establish the history of an object displayed inside. A room’s commemorative purpose does not automatically authenticate every furnishing."},{"type":"paragraph","text":"This distinction need not diminish the emotional force of the place. On the contrary, explaining what was lost, what survived and what was rebuilt allows remembrance to be more honest. Reconstruction can itself become an important public act, provided it is not confused with an uninterrupted survival of historic fabric."},{"type":"paragraph","text":"Ziarat Residency is therefore best encountered as a national memory site with a layered architectural biography. Its familiar outline carries meaning, but the story should extend beyond the outline. The building asks how a society cares for a place after damage, how it records absence, and how it makes a restored landmark intelligible to people who never saw the earlier structure."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Balochistan","Architecture"],"province":"Balochistan","district":"Ziarat","relatedDistrictIds":["balochistan-ziarat"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["major-doam-9686"],"relatedStoryIds":["story-architecture-after-damage-reconstruction-and-honesty"],"contentType":"heritage-place","seo":{"title":"Ziarat Residency: memory, reconstruction and a timber building | Virsapur Archives","description":"Ziarat Residency is both a place associated with Jinnah and a reconstructed monument whose material history should remain visible.","primaryKeyword":"Ziarat Residency heritage","socialTitle":"Ziarat Residency: memory, reconstruction and a timber building","socialDescription":"Ziarat Residency is both a place associated with Jinnah and a reconstructed monument whose material history should remain visible."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Quaid-e-Azam Residency, Ziarat","url":"https://doam.gov.pk/public/sites/9686","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Ziarat Residency: Restoring the house that Mr Jinnah called home","url":"https://tribune.com.pk/story/748568/ziarat-residency-restoring-the-house-that-mr-jinnah-called-home","publisher":"The Express Tribune, Sanam Maher","accessDate":"2026-10-22"},{"title":"Ziarat Residency restored: Negative politics should end says PM","url":"https://tribune.com.pk/story/749008/ziarat-residency-restored-negative-politics-should-end-says-pm","publisher":"The Express Tribune / Associated Press of Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM approximately 125 words on colonial use, stone and timber fabric, Jinnah association. Maher indexed article passages read, approximately 90 words, direct open returned403. APP report approximately 60 words verifies inauguration August2014 and June2013 attack. No surviving personal objects, precise construction date, or unchanged original fabric asserted.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Separate historic fabric, reconstructed elements and commemorative meaning.","wordCount":464,"publicationHold":false,"sortOrder":53}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-babra-tombs-and-a-regional-funerary-tradition','babra-tombs-and-a-regional-funerary-tradition','review','{"id":"story-babra-tombs-and-a-regional-funerary-tradition","type":"story","slug":"babra-tombs-and-a-regional-funerary-tradition","title":"Babra Tombs and a regional funerary tradition","summary":"The Babra graveyard near Bela contains several funerary forms, inviting a reading of a monument group rather than one uniform “Chaukhandi” type.","body":[{"type":"paragraph","text":"A cemetery is rarely a single architectural statement. At Babra, north of Bela, the official archaeological inventory describes a group of funerary structures with different materials and forms. Reading these differences is more rewarding than assigning the whole place one convenient label. The graveyard is associated with the Jams of Lasbela, but that association does not by itself identify every person commemorated there or establish when each monument was made."},{"type":"paragraph","text":"The Department of Archaeology and Museums records a brick-built tomb, stepped graves, a pillared sandstone canopy, lime-plastered graves and another group within an enclosing wall. It also records the local name Tharle. These details suggest an ensemble that deserves to be understood through its parts: an enclosure, a roofed space, a grave marker and a tomb are not interchangeable objects."},{"type":"heading","level":2,"text":"A regional family, not a single design"},{"type":"paragraph","text":"The catalogue compares some of Babra’s monuments with the Chaukhandi-type funerary architecture of Sindh and Balochistan. It places the comparison broadly in the seventeenth and eighteenth centuries. That is a useful starting point, but it is not a securely established construction date for every element of the cemetery."},{"type":"paragraph","text":"Scholarship on Chaukhandi tombs shows how a name associated with a particular cemetery became a wider classificatory term. Such terminology helps researchers recognise relationships across sites. It can also encourage a misleading impression that all related monuments were made at the same time, by the same workshop, or for the same community. The comparison should lead to closer observation, not end it."},{"type":"paragraph","text":"At Babra, the contrast between a brick tomb and a sandstone canopy is already enough to open questions. Does a change in material correspond to a different construction period, a different patron, or another practical choice? The inventory alone cannot decide. A documented inscription, a measured survey or a carefully established building sequence would be needed before one explanation became a historical claim."},{"type":"heading","level":2,"text":"See the group before the detail"},{"type":"paragraph","text":"A thoughtful record would begin with the arrangement of the cemetery, then move to individual structures. The relationship between a canopy and the graves it shelters matters as much as the profile of a carved stone. Likewise, an enclosing wall may organise access or distinguish a group, but its meaning should not be inferred solely from an aerial photograph."},{"type":"paragraph","text":"For visitors, this approach encourages respectful attention without turning the burial ground into a decorative backdrop. Looking closely does not require climbing a marker, touching a fragile surface or moving loose material for a better image. A photograph should preserve the relationship between an object and its setting wherever possible."},{"type":"paragraph","text":"Babra’s interest lies in its variety and in the questions that variety makes possible. It belongs to the heritage of Lasbela as a specific place, not merely as an outlying example of a better-known cemetery near Karachi. Keeping its different forms, local associations and evidential limits visible allows that regional identity to emerge without inventing a complete dynastic narrative."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Balochistan","Architecture"],"province":"Balochistan","district":"Lasbela","relatedDistrictIds":["balochistan-lasbela"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["major-doam-9678"],"relatedStoryIds":[],"contentType":"heritage-place","seo":{"title":"Babra Tombs and a regional funerary tradition | Virsapur Archives","description":"The Babra graveyard near Bela contains several funerary forms, inviting a reading of a monument group rather than one uniform “Chaukhandi” type.","primaryKeyword":"Babra Tombs heritage","socialTitle":"Babra Tombs and a regional funerary tradition","socialDescription":"The Babra graveyard near Bela contains several funerary forms, inviting a reading of a monument group rather than one uniform “Chaukhandi” type."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Ancestral Graveyard of Jam of Lasbela (Babra)","url":"https://doam.gov.pk/public/sites/9678","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Chaukhandi Tombs, Sindhological Studies Summer 1981","url":"https://library-sindhi-sp-2020.s3.us-east-2.amazonaws.com/files/Sindhological_Studies_%28Summer_1981%29-Mazhar_Yusuf-1981-cs.pdf","publisher":"Institute of Sindhology, Salome Zajadacz-Hastenrath","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM approximately185 derived words. Sindhological Studies indexed passage close-read previously, direct PDF403; approximately55 words on regional category/terminology only. No current condition, exact individual grave dates, genealogy or carvings invented. Comparative looking questions explicitly not assertions.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Introduce the documented tomb group with attention to stonework rather than speculative genealogy.","wordCount":471,"publicationHold":false,"sortOrder":54}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-hinidan-tombs-recording-a-vulnerable-monument-group','hinidan-tombs-recording-a-vulnerable-monument-group','review','{"id":"story-hinidan-tombs-recording-a-vulnerable-monument-group","type":"story","slug":"hinidan-tombs-recording-a-vulnerable-monument-group","title":"Hinidan Tombs: recording a vulnerable monument group","summary":"Hinidan’s carved tombs show why an old inventory, a stylistic comparison and a current condition record must be kept separate.","body":[{"type":"paragraph","text":"Hinidan is a useful place to learn how heritage knowledge is made—and how easily old observations can be mistaken for current facts. Its decorated funerary monuments have appeared in archaeological writing for more than a century. Yet the existence of a long bibliography does not mean that the date, identity and present condition of every tomb have been settled."},{"type":"paragraph","text":"The Department of Archaeology and Museums describes numerous carved graves and a varied vocabulary of headstones and raised forms. Some details are especially distinctive, including projecting elements compared in the catalogue to the handles of a bier and floral motifs on the stonework. These are features worth documenting carefully. They are not, on their own, proof of how a burial was conducted beneath the monument."},{"type":"heading","level":2,"text":"The dates do not neatly agree"},{"type":"paragraph","text":"The official listing assigns a broad medieval chronology, while older scholarship and subsequent discussion place particular Hinidan examples later. J. Ph. Vogel examined the cemetery for the Archaeological Survey of India in the early twentieth century. Later research preserved in the Ca’ Foscari University repository discusses examples attributed to the late sixteenth and seventeenth centuries, including carved weapons and riders."},{"type":"paragraph","text":"These differences should remain visible rather than being silently resolved into one confident date. A style can persist; parts can be replaced; a cemetery can grow over generations. None of those possibilities should be asserted for a particular tomb without evidence, but all explain why a single site-wide date may be inadequate. A securely read inscription tied to a specific monument would carry a different evidential weight from a general comparison of form."},{"type":"paragraph","text":"The historical accounts also preserve names attached to graves through local tradition. Such traditions belong in the record with their attribution intact. They should not be converted into verified genealogies merely because an early survey printed them."},{"type":"heading","level":2,"text":"Recording vulnerability without inventing a condition survey"},{"type":"paragraph","text":"An old description of good preservation cannot certify how the cemetery looks today. Conversely, the fact that a monument is exposed outdoors does not justify a claim that it is currently collapsing. A useful modern record would pair dated overall photographs with details of the same identifiable stones, allowing change to be assessed rather than guessed."},{"type":"paragraph","text":"For a carved group such as Hinidan, the sequence of stones and their relationships are crucial. A detached panel photographed alone may preserve a motif but lose the evidence of where it belonged. Recording a tomb’s orientation, dimensions, inscriptions and position within the cemetery would make future comparisons much more reliable than collecting isolated close-ups."},{"type":"paragraph","text":"Hinidan’s appeal is not simply its ornament. It reveals the distance between recognising a beautiful object and understanding a funerary landscape. An atlas can help bridge that distance by linking the place to its survey history, showing where dates remain contested and refusing to present an old inventory as a live inspection. That kind of precision gives the monuments more substance, not less mystery."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Balochistan","Architecture"],"province":"Balochistan","district":"Lasbela","relatedDistrictIds":["balochistan-lasbela"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["major-doam-9683"],"relatedStoryIds":[],"contentType":"heritage-place","seo":{"title":"Hinidan Tombs: recording a vulnerable monument group | Virsapur Archives","description":"Hinidan’s carved tombs show why an old inventory, a stylistic comparison and a current condition record must be kept separate.","primaryKeyword":"Hinidan Tombs heritage","socialTitle":"Hinidan Tombs: recording a vulnerable monument group","socialDescription":"Hinidan’s carved tombs show why an old inventory, a stylistic comparison and a current condition record must be kept separate."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Hinidan Tombs","url":"https://doam.gov.pk/public/sites/9683","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Tombs at Hinidan in Las Bela, Archaeological Survey of India Annual Report 1902–03","url":"https://ignca.gov.in/Asi_data/13956.pdf","publisher":"Archaeological Survey of India, J. Ph. Vogel","accessDate":"2026-10-22"},{"title":"Chaukhandi Tombs doctoral research","url":"https://iris.unive.it/retrieve/f615d88f-413c-4c9a-a397-9bfd7147e4eb/Chaukhandi.Tombs.Matricola955338.Ciclo22.pdf","publisher":"Ca’ Foscari University of Venice repository","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM approximately130 words; Vogel indexed sections approximately60; university thesis indexed Hinidan discussion approximately90. Competing chronologies expressly unresolved. Excluded contradictory road distances, above-ground burial inference and modern condition extrapolation.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain the value of survey documentation when chronology and attribution remain limited.","wordCount":469,"publicationHold":false,"sortOrder":55}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-shigar-fort-palace-rooms-repair-and-new-use','shigar-fort-palace-rooms-repair-and-new-use','review','{"id":"story-shigar-fort-palace-rooms-repair-and-new-use","type":"story","slug":"shigar-fort-palace-rooms-repair-and-new-use","title":"Shigar Fort Palace: rooms, repair and new use","summary":"Shigar Fort Palace demonstrates how a historic residence can acquire a new use while its architecture and conservation choices remain part of the experience.","body":[{"type":"paragraph","text":"Shigar Fort Palace is not best understood as a single symmetrical block. The Department of Archaeology and Museums describes adjoining structures of different periods and architectural character, containing residential, service and religious spaces. Its local name, Fong Khar, points to the rock beneath it. The relationship between building, boulder and surrounding settlement is central to its identity."},{"type":"paragraph","text":"The catalogue’s account includes timber framing, carved details, gardens and a pavilion associated with water. It also distinguishes the palace from an older stronghold on the cliff above. That distinction helps prevent a common visual shortcut: treating every defensive ruin and every inhabited room in the landscape as one unchanged fort. What visitors encounter is a layered residential complex, not a complete military diagram."},{"type":"heading","level":2,"text":"A new use is a conservation decision"},{"type":"paragraph","text":"The Aga Khan Trust for Culture’s project converted the palace into a heritage residence with guest accommodation. Its contemporary account explains the intention to connect cultural conservation with income for operation and maintenance. This was not merely a question of furnishing old rooms attractively. A new use had to be made compatible with a building whose value lay partly in its historic spaces and materials."},{"type":"paragraph","text":"That project received the Award of Excellence in the 2006 UNESCO Asia-Pacific Heritage Awards. The recognition concerns conservation and reuse; it does not make Shigar a separately inscribed UNESCO World Heritage property. Keeping those two forms of recognition distinct is especially important on a heritage platform, where a familiar logo can otherwise imply the wrong status."},{"type":"paragraph","text":"The project’s account sets out ambitions for local economic benefit and cultural tourism. Those ambitions should be read as the conservation organisation’s rationale, not as a substitute for a current independent evaluation of employment, access or revenue. A successful opening is one moment in a building’s much longer maintenance life."},{"type":"heading","level":2,"text":"Rooms, routes and what survives"},{"type":"paragraph","text":"A useful way to look at Shigar is to follow transitions: from outside to an entrance, from circulation space to a room, and from enclosed interiors to the gardens. These changes of scale can communicate the palace more clearly than a checklist of decorative details. Carving becomes legible in relation to a doorway or structural member, rather than as a detached pattern."},{"type":"paragraph","text":"Adaptive reuse also raises practical questions a polished photograph may conceal. Which spaces retain their earlier character? Where were new services introduced? How are visitors told about repaired or reconstructed elements? These are questions to ask of interpretation and conservation records, not defects to presume without inspection."},{"type":"paragraph","text":"Shigar’s strongest lesson is that preservation and use need not be opposites, but neither are they automatically compatible. Their relationship must be designed, explained and maintained. The palace offers an opportunity to appreciate timber craft and spatial complexity while thinking critically about the work that allows an old residence to remain occupied. Its contemporary life is most compelling when the history of that transformation is visible alongside the historic architecture."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Gilgit-Baltistan","Architecture"],"province":"Gilgit-Baltistan","district":"Shigar","relatedDistrictIds":["gilgit-baltistan-shigar"],"provinceRegionIds":["gilgit-baltistan"],"relatedHeritageIds":["major-doam-7998"],"relatedStoryIds":["story-why-timber-matters-in-mountain-architecture","story-adaptive-reuse-what-should-stay-legible","story-what-measured-drawings-can-preserve","story-baltistans-courts-mosques-and-shared-building-skills"],"contentType":"heritage-place","seo":{"title":"Shigar Fort Palace: rooms, repair and new use | Virsapur Archives","description":"Shigar Fort Palace demonstrates how a historic residence can acquire a new use while its architecture and conservation choices remain part of the experience.","primaryKeyword":"Shigar Fort Palace heritage","socialTitle":"Shigar Fort Palace: rooms, repair and new use","socialDescription":"Shigar Fort Palace demonstrates how a historic residence can acquire a new use while its architecture and conservation choices remain part of the experience."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Shigar Fort Palace","url":"https://doam.gov.pk/public/sites/7998","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Shigar Fort: a new model of conservation combines economic and cultural objectives","url":"https://prod.the.akdn/en/resources-media/whats-new/news-release/shigar-fort-new-model-conservation-combines-economic-and-cultural-objectives","publisher":"Aga Khan Development Network","accessDate":"2026-10-22"},{"title":"Shigar Fort awarded top prize in the 2006 UNESCO Asia-Pacific Heritage Awards","url":"https://the.akdn/en/news-release/shigar-fort-awarded-top-prize-2006-unesco-asia-pacific-heritage-awards-pakistan","publisher":"Aga Khan Development Network","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM approximately165 words; project news approximately140; award release approximately40. Avoided consuming shared2005AKTCbook budget reserved Amburiq. Historical project aims not claimed as independently measured current economic outcomes. Award not World Heritage status.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Read the relationship between historic spatial organisation and conservation-led adaptation.","wordCount":471,"publicationHold":false,"sortOrder":56}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-khaplu-palace-and-the-scale-of-a-mountain-court','khaplu-palace-and-the-scale-of-a-mountain-court','review','{"id":"story-khaplu-palace-and-the-scale-of-a-mountain-court","type":"story","slug":"khaplu-palace-and-the-scale-of-a-mountain-court","title":"Khaplu Palace and the scale of a mountain court","summary":"Khaplu Palace can be read through the relationship between household rooms, ceremonial spaces and the conservation work that gave the building a new life.","body":[{"type":"paragraph","text":"Khaplu Palace brings the scale of a mountain court into view without requiring the spectacle of a vast imperial complex. Its interest lies in the arrangement of a residence: rooms for a ruling household, spaces for receiving people, service areas and the timber elements that mediate between inside and outside. Reading it as a working household makes the architecture more intelligible than treating it only as an ornamental façade."},{"type":"paragraph","text":"The Department of Archaeology and Museums describes stone and timber construction, lime-finished walls, a courtyard and garden, and rooms associated with the ruler’s extended family. Storage, cooking and animal accommodation also appear in its account. These functions remind us that a palace depended on practical work as well as ceremony. The building’s history cannot be reduced to the most photogenic balcony."},{"type":"paragraph","text":"The catalogue also notes carved posts, doors, windows and screened projecting spaces. Their value is not only decorative. Openings, screens and circulation routes shape how a building is experienced: what can be seen, where people move and how enclosed rooms relate to the exterior."},{"type":"heading","level":2,"text":"Repair and a changed purpose"},{"type":"paragraph","text":"The Aga Khan Development Network dates the palace to 1840 and describes considerable deterioration when restoration began in 2005. Its account records the opening of the restored palace and residence in July 2011, with guest accommodation forming part of the new use. The same organisation places the work within a wider programme involving settlements and other historic buildings around Khaplu."},{"type":"paragraph","text":"This wider context matters. A palace can become a highly visible destination while nearby houses and communal spaces remain less visible in publicity. The programme’s emphasis on local labour, traditional construction and improving existing settlements offers a different way to frame conservation: not simply as rescuing an exceptional object, but as sustaining knowledge and places around it."},{"type":"paragraph","text":"Those are the organisation’s stated project approaches. They should not be turned into unqualified claims about present-day benefits for every household. Understanding the long-term effects would require evidence beyond an architectural description or an opening announcement."},{"type":"heading","level":2,"text":"Look for relationships rather than a royal legend"},{"type":"paragraph","text":"A careful visit can begin with the relationship between court, room and balcony. Which spaces feel public or enclosed? How do the carved openings frame a view? Where does the scale become intimate? These questions do not require inventing the precise activities of a named ruler in an undocumented room."},{"type":"paragraph","text":"The same restraint applies to restoration. A coherent historic appearance does not mean that every visible timber or finish is untouched. Good interpretation should help distinguish retained material, repair and adaptation, so that the building’s recent life is not hidden behind a claim of timelessness."},{"type":"paragraph","text":"Khaplu Palace rewards attention to this middle scale: larger than an individual craft detail, smaller than a dramatic mountain panorama. Its architecture makes authority, domestic life and skilled construction tangible. Its conservation history adds another layer, asking how an inherited residence can remain useful while preserving enough evidence for visitors to understand what it once was."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Gilgit-Baltistan","Architecture"],"province":"Gilgit-Baltistan","district":"Ghanche","relatedDistrictIds":["gilgit-baltistan-ghanche"],"provinceRegionIds":["gilgit-baltistan"],"relatedHeritageIds":["major-doam-7974"],"relatedStoryIds":["story-why-timber-matters-in-mountain-architecture","story-princely-palaces-and-imported-design-vocabularies","story-what-measured-drawings-can-preserve","story-baltistans-courts-mosques-and-shared-building-skills"],"contentType":"heritage-place","seo":{"title":"Khaplu Palace and the scale of a mountain court | Virsapur Archives","description":"Khaplu Palace can be read through the relationship between household rooms, ceremonial spaces and the conservation work that gave the building a new life.","primaryKeyword":"Khaplu Fort Palace heritage","socialTitle":"Khaplu Palace and the scale of a mountain court","socialDescription":"Khaplu Palace can be read through the relationship between household rooms, ceremonial spaces and the conservation work that gave the building a new life."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Khaplu Palace","url":"https://doam.gov.pk/public/sites/7974","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Conservation and development in Gilgit-Baltistan: Khaplu Village and Palace","url":"https://www-hetz2.the.akdn/en/where-we-work/south-asia/pakistan/conservation-and-development-in-gilgit-baltistan-pakistan","publisher":"Aga Khan Development Network","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM approximately175 derived words; AKDN online regionalpage approximately175 words reserved entirely article56; no other article draws thispage. 1840 and2005–2011 project chronology attributed. Current access/room prices excluded. Architectural interpretation original.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Examine its layered domestic and administrative architecture without merging it with nearby mosques.","wordCount":478,"publicationHold":false,"sortOrder":57}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-chaqchan-mosque-understanding-a-timber-sacred-building','chaqchan-mosque-understanding-a-timber-sacred-building','review','{"id":"story-chaqchan-mosque-understanding-a-timber-sacred-building","type":"story","slug":"chaqchan-mosque-understanding-a-timber-sacred-building","title":"Chaqchan Mosque: understanding a timber sacred building","summary":"Chaqchan Mosque’s timber structure, verandahs and layered ornament offer a precise way to understand a living sacred building in Khaplu.","body":[{"type":"paragraph","text":"Chaqchan Mosque challenges the assumption that a mosque must announce itself through a large dome or a tall minaret. In Khaplu, timber construction, a raised setting and a layered roofline create a different architectural presence. The building is also a place of worship, not simply a surviving specimen of a regional style. Its religious life and its material construction need to be understood together."},{"type":"paragraph","text":"The Department of Archaeology and Museums describes a two-storey arrangement, with winter prayer rooms below the principal hall and verandahs around the upper level. It identifies a structural combination of timber, stone and earth. These are not incidental background materials: they help explain why the building has the form it does."},{"type":"heading","level":2,"text":"Structure before ornament"},{"type":"paragraph","text":"A 2025 descriptive study by Anwar Ali, Muhammad Nazir and Naveed Iqbal documents the mosque’s plan, woodwork and decorative vocabulary. It discusses interlocking timber construction and the relationship of the prayer hall to surrounding verandahs. The study also draws attention to carved floral and geometric motifs, calligraphy and the elaborate treatment of interior surfaces."},{"type":"paragraph","text":"For a non-specialist, the distinction between a beam, a post and a decorative panel is a useful beginning. A carved element can contribute to a structure while also carrying ornament; it need not belong exclusively to one category. Looking first at how the pieces meet can make the pattern easier to understand, rather than allowing decoration to turn the building into a flat visual surface."},{"type":"paragraph","text":"The research connects aspects of the architecture with Kashmir and the wider regional tradition. Such comparison is useful when it points to particular forms. A long list of cultural influences, by contrast, tells us little unless it explains what is being compared and on what evidence."},{"type":"heading","level":2,"text":"Tradition is evidence of memory"},{"type":"paragraph","text":"Accounts associate the mosque with Mir Sayyid Ali Hamdani, and local narratives describe an earlier Buddhist place at the site. These traditions are important to the building’s remembered history. They should nevertheless be identified as traditions, rather than presented as if an excavated foundation sequence had established every detail. A sacred association and an archaeological demonstration answer different questions."},{"type":"paragraph","text":"The official tourism account describes Chaqchan as an active place of worship. That fact changes the visitor’s priorities. Observation, photography and architectural curiosity should accommodate worshippers and local guidance, rather than assuming that a publicly known landmark is available at all times for unrestricted exploration."},{"type":"paragraph","text":"Chaqchan is most compelling when it is allowed to remain specific. Its verandahs are not merely scenic viewing platforms; its interior is not just a collection of motifs; its history is not a competition for the oldest building. Together, its spatial arrangement, skilled timber work and continuing religious role show how a sacred institution can be expressed through a regional building language. Understanding that language begins with patient looking and a willingness to keep different kinds of evidence distinct."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Gilgit-Baltistan","Architecture"],"province":"Gilgit-Baltistan","district":"Ghanche","relatedDistrictIds":["gilgit-baltistan-ghanche"],"provinceRegionIds":["gilgit-baltistan"],"relatedHeritageIds":["major-doam-7969"],"relatedStoryIds":["story-why-timber-matters-in-mountain-architecture","story-wooden-mosques-and-regional-building-knowledge","story-baltistans-courts-mosques-and-shared-building-skills"],"contentType":"heritage-place","seo":{"title":"Chaqchan Mosque: understanding a timber sacred building | Virsapur Archives","description":"Chaqchan Mosque’s timber structure, verandahs and layered ornament offer a precise way to understand a living sacred building in Khaplu.","primaryKeyword":"Chaqchan Mosque heritage","socialTitle":"Chaqchan Mosque: understanding a timber sacred building","socialDescription":"Chaqchan Mosque’s timber structure, verandahs and layered ornament offer a precise way to understand a living sacred building in Khaplu."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Chaqchan Mosque","url":"https://doam.gov.pk/public/sites/7969","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Descriptive Study of Chaqchan Mosque Khaplu, Gilgit Baltistan, Pakistan","url":"https://tjcp.aec.org.pk/index.php/tjcpdata/article/download/32/32","publisher":"The Journal of Cultural Perspectives, Anwar Ali, Muhammad Nazir and Naveed Iqbal","accessDate":"2026-10-22"},{"title":"Chaqchan Mosque","url":"https://e-tourism.visitgilgitbaltistan.gov.pk/tourist-destinations/chaqchan-mosque","publisher":"Tourism Department, Gilgit-Baltistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM approximately120 words;2025 research article approximately180;tourismportal approximately35(active worship). Avoided uncritical mass conversion, unique/oldest, Mughal14c conflation and undocumentedBuddhistfoundation certainty. Architectural explanation not engineering safety advice.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Focus on construction and surviving form while treating foundation narratives cautiously.","wordCount":463,"publicationHold":false,"sortOrder":58}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-amburiq-mosque-and-a-small-buildings-conservation-story','amburiq-mosque-and-a-small-buildings-conservation-story','review','{"id":"story-amburiq-mosque-and-a-small-buildings-conservation-story","type":"story","slug":"amburiq-mosque-and-a-small-buildings-conservation-story","title":"Amburiq Mosque and a small building’s conservation story","summary":"Amburiq Mosque shows how repairing a small, tilted timber building can involve structural skill, local participation and a renewed public role.","body":[{"type":"paragraph","text":"Amburiq Mosque offers a conservation story at the scale of a single room. That smallness is part of its importance. A modest building can contain complex structural knowledge, valued craftwork and a powerful place in community memory; it does not need palace dimensions to justify careful repair. In Shigar, Amburiq makes those relationships unusually clear."},{"type":"paragraph","text":"The Department of Archaeology and Museums describes a main hall with an eastern entrance verandah, a central column and a western mihrab. Timber framing, stone infill, carved details and a layered roof create a compact but richly articulated building. Its association with Mir Sayyid Ali Hamdani belongs to the remembered history of Islam in the region, while an exact foundation date should not be treated as settled solely by that association."},{"type":"heading","level":2,"text":"The problem was not merely cosmetic"},{"type":"paragraph","text":"The Aga Khan Trust for Culture’s published project account explains that water reaching the foundations had contributed to a substantial tilt. Roof and foundation repairs were urgent. The work required specialist structural intervention, including lifting at one corner, rather than simply renewing an attractive surface. The report records completion of the restoration in 1999."},{"type":"paragraph","text":"It also describes local support through labour and contributions of land and timber. This detail matters because conservation is often narrated as the achievement of a single organisation or expert. Here, the project account makes community participation part of the process. The building’s value was not discovered only when it entered an award programme; local attachment helped make repair possible."},{"type":"paragraph","text":"In 2005, Amburiq received an Award of Merit in UNESCO’s Asia-Pacific Heritage Conservation Awards. UNESCO’s announcement praised the conservation and described a renewed community-museum role for the building and courtyard. That historical recognition is not the same as inscription on the World Heritage List, nor does it establish today’s opening arrangements."},{"type":"heading","level":2,"text":"What a small building can teach"},{"type":"paragraph","text":"Amburiq encourages a change in how we look at repair. A straightened wall or a stable roof may appear quiet after completion, yet that apparent normality can conceal difficult decisions. Which pieces could remain? How could loads be transferred without losing historic fabric? How should water be kept away from a vulnerable foundation? The published account identifies the problem and intervention, but a casual photograph cannot answer every technical question."},{"type":"paragraph","text":"The central column, verandah and roof also make the building legible without a grand overview. A visitor can appreciate how a few elements organise space, shelter and attention. That intimacy should not become a reason to touch carved surfaces or treat the structure as an unrestricted exhibit; its care and local meaning remain important."},{"type":"paragraph","text":"Amburiq’s larger lesson is proportionate care. The significance of a monument is not measured by the size of its footprint, and a successful conservation project is not necessarily one that produces a spectacular new silhouette. Sometimes the achievement is that a vulnerable building can continue to stand, be understood and remain meaningful, with the history of its repair honestly explained."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Gilgit-Baltistan","Architecture"],"province":"Gilgit-Baltistan","district":"Shigar","relatedDistrictIds":["gilgit-baltistan-shigar"],"provinceRegionIds":["gilgit-baltistan"],"relatedHeritageIds":["major-doam-8229"],"relatedStoryIds":["story-wooden-mosques-and-regional-building-knowledge","story-conserving-a-sacred-building-with-its-community"],"contentType":"heritage-place","seo":{"title":"Amburiq Mosque and a small building’s conservation story | Virsapur Archives","description":"Amburiq Mosque shows how repairing a small, tilted timber building can involve structural skill, local participation and a renewed public role.","primaryKeyword":"Amburiq Mosque heritage","socialTitle":"Amburiq Mosque and a small building’s conservation story","socialDescription":"Amburiq Mosque shows how repairing a small, tilted timber building can involve structural skill, local participation and a renewed public role."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Amburiq Mosque","url":"https://doam.gov.pk/public/sites/8229","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Conservation and Development in Hunza and Baltistan, pages57–59","url":"https://static.the.akdn/53832/1641873948-2005_hcsp_hunza.pdf","publisher":"Aga Khan Trust for Culture","accessDate":"2026-10-22"},{"title":"2005 Asia-Pacific Heritage Conservation Award Winners Announced","url":"https://articles.unesco.org/sites/default/files/medias/fichiers/2023/06/2005-winners.pdf","publisher":"UNESCO","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM approximately130words;AKTC2005book approximately180words total usage reserved here(55doesnotcitebook);UNESCOaward indexed passage approximately45. Fourteenthcentury expressly traditional/alleged. Historical museum/use not asserted current schedule. Technical lifting described as expert intervention not DIY.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Show why modest scale does not mean minor architectural significance.","wordCount":475,"publicationHold":false,"sortOrder":59}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-manthals-buddha-relief-in-its-rock-setting','manthals-buddha-relief-in-its-rock-setting','review','{"id":"story-manthals-buddha-relief-in-its-rock-setting","type":"story","slug":"manthals-buddha-relief-in-its-rock-setting","title":"Manthal’s Buddha relief in its rock setting","summary":"Manthal’s carved boulder brings Buddhist imagery, Tibetan inscriptions and a stream-side landscape into a single archaeological encounter.","body":[{"type":"paragraph","text":"At Manthal, the image and the rock cannot be separated without losing part of the monument. A large carved face of a boulder presents a central Buddha, surrounding seated figures and two standing bodhisattvas. Below and around the composition are Tibetan inscriptions. The setting near the Sadpara stream, south of Skardu, makes this an encounter with a worked landscape rather than a sculpture displayed in a museum room."},{"type":"paragraph","text":"The Department of Archaeology and Museums records twenty-three figures in the principal composition. It also describes a vase motif, inscriptions and traces of red colour. These details encourage a more attentive reading than the familiar wide photograph: the monument includes writing and subsidiary imagery, not just the central figure that first catches the eye."},{"type":"heading","level":2,"text":"Image, inscription and sequence"},{"type":"paragraph","text":"An inscription is not simply a caption whose meaning can be guessed from the sculpture beside it. Reading damaged historical writing requires linguistic expertise, careful documentation and attention to which marks belong together. Popular translations repeated without an identifiable scholarly basis should therefore not be used to explain Manthal’s entire history."},{"type":"paragraph","text":"The official catalogue assigns the monument to the ninth or tenth century. Karl Jettmar’s discussion of exploration in Baltistan places Manthal within a broader account of later Buddhist religious expression and regional recovery. These are different interpretive frames, not a reason to manufacture a single exact construction year. The carving, the inscriptions and later interventions may raise questions that a short atlas entry cannot settle."},{"type":"paragraph","text":"Jettmar also discusses the importance of reliefs in relation to other forms of rock imagery. This helps distinguish Manthal from a surface bearing many small, independently accumulated engravings. Its organised composition deserves to be read as a whole, even while individual details require specialist study."},{"type":"heading","level":2,"text":"Let the rock remain part of the story"},{"type":"paragraph","text":"The natural surface sets limits and possibilities for the carving. Looking at the edges of the composition, the relationship between figures and inscriptions, and the orientation of the worked face can reveal more than isolating a single head in a photograph. The surrounding ground and stream-side context are likewise part of understanding where the monument was made."},{"type":"paragraph","text":"The catalogue records historical damage and surviving colour, but that description is not a fresh condition assessment. A current record should identify when photographs were taken and avoid interpreting every worn area as the result of one cause. Weathering, breakage and deliberate alteration require evidence if they are to be distinguished responsibly."},{"type":"paragraph","text":"For visitors, the safest way to appreciate the detail is without rubbing, wetting, chalking or climbing the carved surface. Those actions can change the evidence that future study depends on. A carefully framed photograph and an accurately attributed interpretation are more valuable than making a faint letter temporarily easier to see."},{"type":"paragraph","text":"Manthal’s significance extends beyond its striking appearance. It connects artistic composition with writing, regional religious history and the physical character of a particular boulder. Preserving those connections allows the monument to remain a source of inquiry, rather than reducing it to an uncomplicated symbol of a vanished past."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Gilgit-Baltistan","Architecture"],"province":"Gilgit-Baltistan","district":"Skardu","relatedDistrictIds":["gilgit-baltistan-skardu"],"provinceRegionIds":["gilgit-baltistan"],"relatedHeritageIds":["major-doam-7705"],"relatedStoryIds":[],"contentType":"heritage-place","seo":{"title":"Manthal’s Buddha relief in its rock setting | Virsapur Archives","description":"Manthal’s carved boulder brings Buddhist imagery, Tibetan inscriptions and a stream-side landscape into a single archaeological encounter.","primaryKeyword":"Manthal Rock Buddha heritage","socialTitle":"Manthal’s Buddha relief in its rock setting","socialDescription":"Manthal’s carved boulder brings Buddhist imagery, Tibetan inscriptions and a stream-side landscape into a single archaeological encounter."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Manthal Rock Buddha","url":"https://doam.gov.pk/public/sites/7705","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Exploration in Baltistan","url":"https://archiv.ub.uni-heidelberg.de/propylaeumdok/2135/1/Jettmar_Exploration_in_Baltistan_1990.pdf","publisher":"Karl Jettmar, East and West / Heidelberg University repository","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM approximately185derivedwords;Jettmarindexedprimarypassage approximately80. Catalogue9–10c and JettmarlaterBuddhistrecovery context not forcedintooneprecisedate. No folk inscription translation, unverifiedgranitetype or presentconditionclaim. New2025Chinese reinterpretation lead not treated read/validated.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain the relief as an archaeological surface rather than an isolated museum-like image.","wordCount":491,"publicationHold":false,"sortOrder":60}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-kharpocho-fort-and-the-view-over-skardu','kharpocho-fort-and-the-view-over-skardu','review','{"id":"story-kharpocho-fort-and-the-view-over-skardu","type":"story","slug":"kharpocho-fort-and-the-view-over-skardu","title":"Kharpocho Fort and the view over Skardu","summary":"Kharpocho’s elevated position explains part of its power, but the fort’s surviving fabric also records rebuilding and changing political control.","body":[{"type":"paragraph","text":"A view from a fort is more than a scenic reward. At Kharpocho, the relationship between elevated rock, Skardu and the Indus helps explain why this location mattered as a seat of power. The building occupies the rocky divide between town and river. Seen in that setting, its walls become part of a larger arrangement of visibility, movement and control rather than a picturesque silhouette against the mountains."},{"type":"paragraph","text":"The Department of Archaeology and Museums associates the fort with Ali Sher Khan Anchan, while also recording substantial later rebuilding under the Dogra ruler Ranbir Singh. Its description refers to an inscription dated to 1884. That later evidence complicates any caption that assigns the entire surviving structure to a single early ruler. A place can retain an older identity while much of its fabric belongs to subsequent work."},{"type":"heading","level":2,"text":"The hill is not an empty pedestal"},{"type":"paragraph","text":"The official inventory distinguishes the main fort, the remains of a hilltop watchtower and graves at the foot of the hill. It also notes a water reservoir and other structures on the slopes. These details make the complex larger than its best-known viewpoint. Defence, water, memory and residence all need space in the interpretation."},{"type":"paragraph","text":"The tourism department likewise places Kharpocho within a history of Maqpoon rule and later Dogra conflict. Exact foundation dates vary between public accounts, so the broad historical associations are more reliable here than an unsupported claim that a particular wall was completed in a particular year. A dated inscription can anchor one intervention without settling the whole sequence."},{"type":"heading","level":2,"text":"Reading a commanding position"},{"type":"paragraph","text":"Looking outward raises specific questions. What terrain is visible from a wall? Which approaches are hidden by the slope? How does the river separate one part of the landscape from another? These are ways to examine the site, not proof that every visible route was controlled by its occupants. A modern street grid should not be projected unchanged into an earlier period."},{"type":"paragraph","text":"Looking inward is equally important. A reservoir is a reminder that holding an elevated position required practical provision, not only thick walls. A watchtower and a residential space would have served different purposes. The distinction prevents the word fort from flattening a complex into a single military function."},{"type":"paragraph","text":"Present-day appreciation should also leave room for the building’s vulnerability. An old catalogue description cannot certify a current path, barrier or wall as safe, and this historical account is not a walking-route guide. Current local instructions should determine where visitors go and which areas remain accessible."},{"type":"paragraph","text":"Kharpocho’s strongest story joins geography with time. The broad panorama explains why the site was valued; the record of rebuilding explains why its appearance cannot be treated as frozen. To look carefully is to see both a place from which a landscape was observed and a structure repeatedly changed by the people who sought to occupy it."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Gilgit-Baltistan","Architecture"],"province":"Gilgit-Baltistan","district":"Skardu","relatedDistrictIds":["gilgit-baltistan-skardu"],"provinceRegionIds":["gilgit-baltistan"],"relatedHeritageIds":["major-doam-7818"],"relatedStoryIds":[],"contentType":"heritage-place","seo":{"title":"Kharpocho Fort and the view over Skardu | Virsapur Archives","description":"Kharpocho’s elevated position explains part of its power, but the fort’s surviving fabric also records rebuilding and changing political control.","primaryKeyword":"Kharpocho Fort heritage","socialTitle":"Kharpocho Fort and the view over Skardu","socialDescription":"Kharpocho’s elevated position explains part of its power, but the fort’s surviving fabric also records rebuilding and changing political control."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Kharpocho Fort Complex","url":"https://doam.gov.pk/public/sites/7818","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Kharpocho Fort","url":"https://e-tourism.visitgilgitbaltistan.gov.pk/tourist-destinations/kharpocho-fort","publisher":"Tourism Department, Gilgit-Baltistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM approximately185 derivedwords;tourismportal approximately70. Excluded contradictory1490–1505 attribution to AliSherKhan in older official page, unverified305m relativeheight,accesspromises. 1884inscription attributed catalogue not independently read.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Connect elevated siting with settlement geography without turning the article into a trekking guide.","wordCount":461,"publicationHold":false,"sortOrder":61}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-hodar-learning-to-read-a-rock-art-field','hodar-learning-to-read-a-rock-art-field','review','{"id":"story-hodar-learning-to-read-a-rock-art-field","type":"story","slug":"hodar-learning-to-read-a-rock-art-field","title":"Hodar: learning to read a rock-art field","summary":"At Hodar, individual boulders, overlapping marks and scholarly catalogue numbers reveal a rock-art landscape made over time.","body":[{"type":"paragraph","text":"Hodar is not one carving with one date. It is a field of marked rock surfaces near the Indus, where images and inscriptions accumulated through different acts of making. The Department of Archaeology and Museums describes clusters across hundreds of boulders around the mouth of the Hodar stream and nearby slopes. A single map pin is useful for finding the area, but it cannot represent the complexity of the evidence spread across it."},{"type":"paragraph","text":"The catalogue records animal and human figures, religious imagery and inscriptions, including Sogdian writing. These categories are not interchangeable. A recognisable animal may tell us something different from a personal name, while an architectural image can invite comparison without yielding an exact date. The site’s broad chronology must not become a claim that every mark is equally ancient."},{"type":"heading","level":2,"text":"A catalogue makes uncertainty visible"},{"type":"paragraph","text":"The detailed scholarly volume Die Felsbildstation Hodar, published in 1999, records individual stones and engravings with identifiers. One entry, 65:10, describes a stupa image whose upper part may have been constrained by an inscription above it. The authors suggest a possible sequence: the image might have followed the writing. They do not present that possibility as a certainty."},{"type":"paragraph","text":"Nearby inscription entries distinguish clear readings from uncertain ones. One name is difficult to establish even when examined at the rock; another is differentiated from related examples by the hand that wrote it. Such observations make the catalogue more valuable than a collection of confident translations. They show the reader what the scholar could see, what could be compared and where doubt remains."},{"type":"paragraph","text":"This is a practical lesson in archaeological literacy. An identifier lets another researcher return to the same mark. A measurement and orientation make a description testable. A question mark preserves a limitation that may otherwise disappear when the result is shortened for a visitor panel."},{"type":"heading","level":2,"text":"Surface colour is not a clock"},{"type":"paragraph","text":"The official overview discusses differences in repatination, the darkening of previously worked surfaces. These can contribute to a relative reading of marks, but colour alone should not be converted into a precise age. Exposure, surface condition and the relationship between engravings must also be considered. A dark animal figure is not automatically evidence for a named prehistoric community."},{"type":"paragraph","text":"For visitors, the first task is therefore to keep the boulder in view as well as the image. Where is the mark on the surface? Is there writing nearby? Does another line cross it? A photograph that includes context can preserve these relationships better than a tightly cropped motif."},{"type":"paragraph","text":"Hodar’s significance lies in this plurality. It is a place where movement, devotion and other forms of marking left material traces, without all those traces belonging to one moment or one explanation. Learning to read the field means resisting the urge to make every image instantly legible. Its uncertainties are part of the record, not gaps to fill with an attractive story."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Gilgit-Baltistan","Architecture"],"province":"Gilgit-Baltistan","district":"Diamir","relatedDistrictIds":["gilgit-baltistan-diamir"],"provinceRegionIds":["gilgit-baltistan"],"relatedHeritageIds":["major-doam-8249"],"relatedStoryIds":["story-rock-art-motif-is-not-a-secure-date","story-rock-art-corridors-of-the-upper-indus"],"contentType":"heritage-place","seo":{"title":"Hodar: learning to read a rock-art field | Virsapur Archives","description":"At Hodar, individual boulders, overlapping marks and scholarly catalogue numbers reveal a rock-art landscape made over time.","primaryKeyword":"Hodar Rock Art heritage","socialTitle":"Hodar: learning to read a rock-art field","socialDescription":"At Hodar, individual boulders, overlapping marks and scholarly catalogue numbers reveal a rock-art landscape made over time."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Hodar","url":"https://doam.gov.pk/public/sites/8249","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Die Felsbildstation Hodar, catalogue page297, stone65","url":"https://digi.hadw-bw.de/view/manp3/0319","publisher":"Heidelberg Academy of Sciences and Humanities, Ditte Bandini and Gérard Fussman, editors","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM approximately150words;Hodar1999volume approximately185 including metadata and close-readindexedstone65 entries. No absolute date from patina, population identity from script, or guessedtranslation. Source fullURLopencachemiss but indexedpage read.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Distinguish motif, inscription, patina and interpretive uncertainty across a group of surfaces.","wordCount":466,"publicationHold":false,"sortOrder":62}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-thalpan-and-the-meeting-of-image-and-inscription','thalpan-and-the-meeting-of-image-and-inscription','review','{"id":"story-thalpan-and-the-meeting-of-image-and-inscription","type":"story","slug":"thalpan-and-the-meeting-of-image-and-inscription","title":"Thalpan and the meeting of image and inscription","summary":"Thalpan’s rock images become more specific when read alongside carefully documented inscriptions, including a named religious offering.","body":[{"type":"paragraph","text":"At Thalpan, images and writing share rock surfaces along the upper Indus. That proximity can be illuminating, but it must be examined rather than assumed. A line of text beside a stupa may refer to it; another mark on the same boulder may belong to a different visit or period. The difference matters because it changes a generic picture of ancient travellers into a record of particular acts."},{"type":"paragraph","text":"The Department of Archaeology and Museums places the site on the river’s right bank near Chilas. Its overview describes a wide range of carvings, from animal imagery to Buddhist scenes and later material. The boulder often called the altar rock is a modern scholarly designation, not a name supplied by its makers. Even an evocative label should remain separate from the evidence it helps organise."},{"type":"heading","level":2,"text":"A named offering on stone142"},{"type":"paragraph","text":"The detailed Thalpan catalogue offers a more precise example. Entry 142:5 describes a carefully executed stupa image. Beside it, inscription 142:6 is interpreted as recording a religious offering by Varunapriya. The catalogue considers at least this inscription to be a caption associated with the image. Here, writing gives the visual mark a dimension that appearance alone could not supply: a named act of dedication."},{"type":"paragraph","text":"The record also notes uncertainties nearby, including a faint engraving whose interpretation remains unclear and an apparently unfinished inscription. These are not peripheral inconveniences. They show that one surface can preserve completed work, hesitant beginnings and marks that no longer yield an answer. A clean modern tracing should not make them appear more certain than the rock allows."},{"type":"paragraph","text":"The name does not provide a full biography. It cannot, by itself, tell us the donor’s profession, itinerary, language at home or reason for travelling. Its value is narrower and more concrete: it connects a particular inscription with a documented religious image."},{"type":"heading","level":2,"text":"More than illustrations of a route"},{"type":"paragraph","text":"The official overview also identifies narrative Buddhist imagery, including scenes understood through stories of the Buddha and his earlier lives. Such identifications depend on comparing figures and actions with established visual and textual traditions. Not every animal scene on the same site should therefore be treated as Buddhist, and not every inscription necessarily explains the nearest image."},{"type":"paragraph","text":"Thalpan is often approached through the idea of movement along the Indus. That is a useful framework, but the individual surfaces deserve attention on their own terms. A route map tells us where connections were possible; a documented offering tells us something about what someone chose to do at a particular place."},{"type":"paragraph","text":"For a heritage platform, the strongest presentation would connect the landscape view to one clearly identified catalogue entry, allowing a reader to move from setting to detail. Thalpan then becomes more than an impressive concentration of rock art. It becomes a place where the limits and possibilities of historical knowledge are visible in the meeting of an image, a name and a carefully recorded surface."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Gilgit-Baltistan","Architecture"],"province":"Gilgit-Baltistan","district":"Diamir","relatedDistrictIds":["gilgit-baltistan-diamir"],"provinceRegionIds":["gilgit-baltistan"],"relatedHeritageIds":["major-doam-8278"],"relatedStoryIds":["story-rock-art-motif-is-not-a-secure-date","story-an-inscription-and-a-carving-may-have-different-histories","story-rock-art-corridors-of-the-upper-indus"],"contentType":"heritage-place","seo":{"title":"Thalpan and the meeting of image and inscription | Virsapur Archives","description":"Thalpan’s rock images become more specific when read alongside carefully documented inscriptions, including a named religious offering.","primaryKeyword":"Thalpan Rock Art heritage","socialTitle":"Thalpan and the meeting of image and inscription","socialDescription":"Thalpan’s rock images become more specific when read alongside carefully documented inscriptions, including a named religious offering."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Thalpan","url":"https://doam.gov.pk/public/sites/8278","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Die Felsbildstation Thalpan, volume2, catalogue page116, stone142","url":"https://digi.hadw-bw.de/view/manp7/0134","publisher":"Heidelberg Academy of Sciences and Humanities, Oskar von Hinüber","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM approximately155words;MANP7stone142 approximately180words. DonorVarunapriya paraphrased fromGermantranslation;no biography/ethnicityinference. Singleheader9–8millennium notusedasentirefielddate. Indexedcataloguefullpagecloseread;directopencachemiss.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explore multiple periods of marking and movement without assigning every image one origin.","wordCount":471,"publicationHold":false,"sortOrder":63}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-thagas-khanqah-and-communal-sacred-space','thagas-khanqah-and-communal-sacred-space','review','{"id":"story-thagas-khanqah-and-communal-sacred-space","type":"story","slug":"thagas-khanqah-and-communal-sacred-space","title":"Thagas Khanqah and communal sacred space","summary":"Thagas Khanqah’s hall, side chambers and verandah express a communal sacred institution through the timber architecture of Baltistan.","body":[{"type":"paragraph","text":"Thagas Khanqah is best approached as an institution expressed through space. A large hall, rooms along its sides and a broad entrance zone suggest more than a building designed for a single brief encounter. The Department of Archaeology and Museums describes timber, stone and mud construction, with substantial wooden posts and capitals. The scale and arrangement make the communal interior the central architectural event."},{"type":"paragraph","text":"The official account places the entrance verandah to the east and meditation chambers along the northern and southern sides. It records an upper level associated with women’s prayer. These details explain how a building can bring collective gathering and more secluded activity into one structure. They are historical descriptive evidence, not a guarantee of current access arrangements or a complete account of contemporary practice."},{"type":"paragraph","text":"Nearby are the astanas of Mir Arif and Mir Ishaq. The khanqah should not be collapsed into either tomb simply because all belong to a sacred setting. Distinguishing hall, chamber and commemorative structure allows the relationship between them to become clearer."},{"type":"heading","level":2,"text":"A regional building type"},{"type":"paragraph","text":"In his study of traditional architecture in Baltistan, Max Klimburg describes large khanqahs with columned halls, frontal verandahs and side cells used for retreat or accommodation. He distinguishes this regional development from the generally smaller mosque forms discussed elsewhere in the study. He also identifies the adjacent astanas at Tagas, a spelling variant of Thagas, within the wider architectural landscape."},{"type":"paragraph","text":"This comparison helps explain the building without making it a copy of a single distant model. The meaningful connection is a family of spatial arrangements: gathering space, sheltered threshold, subsidiary rooms and the structural work of timber. Individual buildings can share those features while differing in date, scale, decoration and local significance."},{"type":"paragraph","text":"Klimburg’s account also makes clear that relationships between Baltistan and neighbouring traditions are questions for research, not a licence to assign every carved form an uncomplicated foreign origin. A familiar motif can travel, be reworked or acquire another meaning."},{"type":"heading","level":2,"text":"The threshold deserves attention"},{"type":"paragraph","text":"At Thagas, the verandah is an important interpretive starting point. It is neither wholly outside nor identical to the main hall. Thinking about that transition helps a visitor understand how a communal building can organise arrival, shelter and entry before its interior is reached. The side chambers then introduce another change of scale within the larger composition."},{"type":"paragraph","text":"The large posts should likewise be seen as members carrying a roof, not only as decorated objects. Their capitals mediate between vertical support and horizontal structure. Appreciating that relationship makes the craftsmanship more intelligible than isolating a carved detail from its architectural role."},{"type":"paragraph","text":"Thagas offers a reminder that sacred heritage includes institutions and patterns of shared space, not only spectacular façades. Its value emerges from the relationship of a community to a particular arrangement of rooms, thresholds and neighbouring memorials. Respectful interpretation preserves those relationships while leaving living custodians room to explain the building in their own terms."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Gilgit-Baltistan","Architecture"],"province":"Gilgit-Baltistan","district":"Ghanche","relatedDistrictIds":["gilgit-baltistan-ghanche"],"provinceRegionIds":["gilgit-baltistan"],"relatedHeritageIds":["major-doam-7966"],"relatedStoryIds":["story-shrine-mosque-and-khanqah-different-institutional-spaces","story-sacred-sound-is-not-always-music-for-an-audience"],"contentType":"heritage-place","seo":{"title":"Thagas Khanqah and communal sacred space | Virsapur Archives","description":"Thagas Khanqah’s hall, side chambers and verandah express a communal sacred institution through the timber architecture of Baltistan.","primaryKeyword":"Thagas Khanqah heritage","socialTitle":"Thagas Khanqah and communal sacred space","socialDescription":"Thagas Khanqah’s hall, side chambers and verandah express a communal sacred institution through the timber architecture of Baltistan."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Khanqah e Moallah Thagas","url":"https://doam.gov.pk/public/sites/7966","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Traditional Art and Architecture in Baltistan","url":"https://s3.amazonaws.com/media.archnet.org/system/publications/contents/4874/original/DPC1587.pdf?1384787082=","publisher":"Max Klimburg, Archnet / Aga Khan Trust for Culture","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMapproximately145words;Klimburgapproximately180words totalarticle63,regionalcomparisonsidentifiednotallThagasfacts. Thagas/Tagasspellingvariant matchedneighbouringMirArif/MirIshaqastanas. No exactfoundationyearorcurrentwomenaccessscheduleasserted.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Read a distinct institutional building in the architectural traditions of Baltistan.","wordCount":475,"publicationHold":false,"sortOrder":64}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-khaplu-polo-ground-as-a-historic-public-place','khaplu-polo-ground-as-a-historic-public-place','review','{"id":"story-khaplu-polo-ground-as-a-historic-public-place","type":"story","slug":"khaplu-polo-ground-as-a-historic-public-place","title":"Khaplu Polo Ground as a historic public place","summary":"Khaplu’s polo ground shows how an open space can carry architectural, sporting and communal heritage without a monumental roof or façade.","body":[{"type":"paragraph","text":"An open ground can be as culturally specific as a palace. At Khaplu, the polo ground belongs in a heritage account because it is a defined place for gathering and performance, not simply an unbuilt gap beside an important building. Its meaning depends on the relationship between the playing surface, its edges, the surrounding town and the people who use it."},{"type":"paragraph","text":"The Department of Archaeology and Museums records the ground south of Khaplu town, near the palace, and attributes its construction in 1890 to Raja Ali Sher Khan. Its account also distinguishes an older ground near the Hachi settlement, describing a shift in community use after 1972. That distinction is important: a tradition can continue while its principal venue changes."},{"type":"paragraph","text":"These catalogue dates should be understood as the record’s historical account, not evidence that every boundary or surface visible today has remained unchanged since the nineteenth century. Open spaces are maintained, adapted and sometimes reorganised, just as buildings are."},{"type":"heading","level":2,"text":"A ground becomes a gathering"},{"type":"paragraph","text":"Abdul Hameed’s illustrated account of the 2017 Jashn-e-Ghanche describes polo alongside other sports, music and dance at Khaplu’s festival. His report places the ground beside the former royal palace and records participation by teams from different parts of Baltistan. It provides a dated example of the space in use, rather than an abstract assertion that culture happens there."},{"type":"paragraph","text":"The account’s value lies in that specificity. It shows how one event brought competition and performance together. It should not be turned into a promise that the same programme, teams or dates recur every year. A historical description of a festival is not a current events calendar."},{"type":"paragraph","text":"A government development programme later listed improvement of the boundary wall at Khaplu’s Shahi Polo Ground. The budget entry is evidence of an identified maintenance project, not proof that every proposed work was completed. It nevertheless reminds us that the edges of an open place require care too."},{"type":"heading","level":2,"text":"Tangible space, living practice"},{"type":"paragraph","text":"Polo itself cannot be preserved by conserving a wall alone. Equally, the activity needs somewhere to take place. This makes the ground a useful example of the relationship between tangible heritage and living practice: neither is adequately represented if the other disappears from the account."},{"type":"paragraph","text":"For interpretation, a photograph of an empty field and a photograph of a match answer different questions. The first can show boundaries and relation to neighbouring buildings; the second can show how people occupy the space. Neither should stand alone as a complete history, and images of participants deserve the same care over context and permission as other cultural documentation."},{"type":"paragraph","text":"Khaplu’s polo ground expands what a visitor might recognise as heritage. The palace may draw attention first, but the neighbouring open space introduces another scale of social life. It is a place where architecture includes the arrangement of an absence: room left for movement, spectatorship and shared occasions that cannot fit inside a monument."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Gilgit-Baltistan","Architecture"],"province":"Gilgit-Baltistan","district":"Ghanche","relatedDistrictIds":["gilgit-baltistan-ghanche"],"provinceRegionIds":["gilgit-baltistan"],"relatedHeritageIds":["major-doam-7973"],"relatedStoryIds":["story-polo-in-baltistan-rules-memory-and-public-space"],"contentType":"heritage-place","seo":{"title":"Khaplu Polo Ground as a historic public place | Virsapur Archives","description":"Khaplu’s polo ground shows how an open space can carry architectural, sporting and communal heritage without a monumental roof or façade.","primaryKeyword":"Khaplu Polo Ground heritage","socialTitle":"Khaplu Polo Ground as a historic public place","socialDescription":"Khaplu’s polo ground shows how an open space can carry architectural, sporting and communal heritage without a monumental roof or façade."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Khaplu Polo Ground","url":"https://doam.gov.pk/public/sites/7973","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"From this year’s Jashn-e-Ghanche","url":"https://blogs.arynews.tv/blog/12855","publisher":"ARY Blogs, Abdul Hameed","accessDate":"2026-10-22"},{"title":"Annual Development Programme2024–25, boundary wall improvement at Shahi Polo Ground Khaplu","url":"https://gilgitbaltistan.gov.pk/storage/downloads/7mHWgRfQQPlmIabvIrVJrv7D6d9Tv2-metaQURQIDIwMjQtMjUgLnBkZg%3D%3D-.pdf","publisher":"Government of Gilgit-Baltistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMdirectfetch200evidence7973saved approximately100words;2018firstpersonfestivalreport approximately130words;ADPindexedbudgetline approximately25words(notcompletionclaim). Dates1890/1972 attributedcatalogue, no weeklyeventpromiseorunchangedboundaries.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain how a bounded open space belongs in tangible cultural landscape interpretation.","wordCount":471,"publicationHold":false,"sortOrder":65}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-muzaffarabads-red-fort-beside-the-river','muzaffarabads-red-fort-beside-the-river','review','{"id":"story-muzaffarabads-red-fort-beside-the-river","type":"story","slug":"muzaffarabads-red-fort-beside-the-river","title":"Muzaffarabad’s Red Fort beside the river","summary":"Muzaffarabad’s Red Fort links a river-defined defensive position with terraces, rebuilding and the continuing challenge of conservation after earthquake damage.","body":[{"type":"paragraph","text":"Muzaffarabad’s Red Fort is inseparable from the bend of the Neelum River around its rocky setting. The river does not merely provide a backdrop. Together with the raised ground, it helps explain the choice of a defensive position within what is now the city. Known also as Rutta Qila, the fort invites a reading that begins with terrain before moving to walls and rooms."},{"type":"paragraph","text":"The Department of Archaeology and Museums describes three terraces, with the principal entrance associated with the upper level. This stepped arrangement matters: the fort is not a flat enclosure placed on a uniform platform. Movement through it involved changes of level, and those changes belong to the architectural story as much as the outline seen from across the water."},{"type":"heading","level":2,"text":"More than one building campaign"},{"type":"paragraph","text":"The Walled City of Lahore Authority’s account traces the fort’s beginnings to the Chak period, its completion and repair under Sultan Muzaffar Khan in the seventeenth century, and further nineteenth-century work under Dogra rulers. The sequence is more useful than assigning all surviving fabric to one founder. A defensive place can retain strategic value while its buildings are repeatedly altered."},{"type":"paragraph","text":"Both the archaeological inventory and the conservation authority record major damage in the 2005 earthquake. This later event is part of the monument’s history, not an interruption that can be omitted in pursuit of a picturesque past. The surviving structure must be understood through what remained, what was lost and what subsequent work sought to stabilise."},{"type":"paragraph","text":"The authority’s project description includes historical and architectural analysis, conservation of original structures, interpretation and visitor facilities. It also lists later-phase commercial proposals. Those descriptions establish a programme of intentions; they do not, by themselves, confirm that every museum, facility or proposed business is complete and operating."},{"type":"heading","level":2,"text":"Reading the river edge"},{"type":"paragraph","text":"An exterior view can explain the fort’s broad siting, but it cannot show the full relationship between terraces, access and interior spaces. Conversely, a photograph taken inside may conceal how strongly the river defines the setting. Holding those two views together makes the building more intelligible than a sequence of isolated scenic details."},{"type":"paragraph","text":"Conservation adds another layer to that reading. A repaired section and an older surviving wall may look similar from a distance, yet they answer different historical questions. Clear interpretation should identify significant interventions without making visitors decode them from surface colour alone. It should also separate evidence for an earlier layout from features introduced for present-day use."},{"type":"paragraph","text":"The Red Fort’s cultural value does not depend on appearing untouched. Its repeated occupation, damage and repair are precisely what connect it to Muzaffarabad’s changing history. The challenge is to preserve enough of the material record that those changes remain understandable."},{"type":"paragraph","text":"Seen this way, the fort is both a river landmark and a layered urban monument. Its silhouette draws the eye; its terraces, building campaigns and conservation history reward the closer attention that follows."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Azad Kashmir","Architecture"],"province":"Azad Jammu and Kashmir","district":"Muzaffarabad","relatedDistrictIds":["azad-kashmir-muzaffarabad"],"provinceRegionIds":["azad-kashmir"],"relatedHeritageIds":["major-doam-6663"],"relatedStoryIds":["story-muzaffarabad-two-forts-and-changing-river-edges"],"contentType":"heritage-place","seo":{"title":"Muzaffarabad’s Red Fort beside the river | Virsapur Archives","description":"Muzaffarabad’s Red Fort links a river-defined defensive position with terraces, rebuilding and the continuing challenge of conservation after earthquake damage.","primaryKeyword":"Red Fort, Muzaffarabad heritage","socialTitle":"Muzaffarabad’s Red Fort beside the river","socialDescription":"Muzaffarabad’s Red Fort links a river-defined defensive position with terraces, rebuilding and the continuing challenge of conservation after earthquake damage."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Red Fort","url":"https://doam.gov.pk/public/sites/6663","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Muzaffarabad: Red Fort conservation project","url":"https://walledcitylahore.gop.pk/muzaffarabad/","publisher":"Walled City of Lahore Authority","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMapproximately145words;WCLAindexedfullprojecttextapproximately185words.1559/1646/19c attributedauthority;futurehotel/restaurant notclaimedoperational. No completedrestoration/accessassertions.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Examine its defensive location and surviving fabric through documented evidence.","wordCount":470,"publicationHold":false,"sortOrder":66}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-sharda-temple-architecture-and-the-limits-of-attribution','sharda-temple-architecture-and-the-limits-of-attribution','review','{"id":"story-sharda-temple-architecture-and-the-limits-of-attribution","type":"story","slug":"sharda-temple-architecture-and-the-limits-of-attribution","title":"Sharda Temple: architecture and the limits of attribution","summary":"Sharda Temple’s stone architecture deserves a precise account that separates the standing sanctuary from expansive claims about an ancient university.","body":[{"type":"paragraph","text":"Sharda Temple carries a name associated with sacred learning, but its standing remains should first be allowed to speak as architecture. In the Neelum Valley, a raised stone sanctuary, enclosing walls and a monumental approach form a specific archaeological place. Understanding those elements does not diminish the wider traditions attached to Sharda. It gives them a material setting against which different claims can be examined."},{"type":"paragraph","text":"The Department of Archaeology and Museums describes a sanctuary on a high platform, large stone components, trefoil-shaped details and a relatively plain interior. Its entry compares the building with the stone-temple tradition of Kashmir. The comparison concerns architectural form; it is not proof that one named ruler built every element or that all parts of the enclosure belong to one campaign."},{"type":"heading","level":2,"text":"What does “university” establish?"},{"type":"paragraph","text":"A 2022 study by Junaid Ahmad, Anas Mahmud Arif and Adnan Anwar directly examines the popular identification of the place as an ancient university. Drawing on field observation, architectural comparison and local accounts, the authors argue that the surviving structure is best understood as a temple dedicated to Sharada. They distinguish that identification from claims about a Buddhist monastic establishment, for which their study did not establish the expected structural evidence."},{"type":"paragraph","text":"This is a narrower argument than saying learning never occurred at Sharda. A religious place can have intellectual associations without the surviving building constituting a documented campus. The task is to specify what the walls demonstrate, what historical texts say and what later memory adds. Those forms of evidence can enrich one another without becoming interchangeable."},{"type":"paragraph","text":"The study’s discussion of local narratives also reminds us that memory has its own value. A tradition need not be treated as an excavation report to deserve respectful attention."},{"type":"heading","level":2,"text":"Look at how the stone works"},{"type":"paragraph","text":"The sanctuary’s raised position and surrounding enclosure establish a sequence from approach to court to interior. The shaped recesses and trefoil forms articulate the exterior, while large horizontal and vertical stones organise the openings. Looking at these relationships is more informative than applying a broad label such as Greek influence without explaining the specific comparison."},{"type":"paragraph","text":"Dating remains an exercise in evidence rather than visual impression. The official entry offers a tentative early-medieval attribution; comparative scholarship discusses a wider architectural tradition. Neither justifies turning an approximate range into an exact foundation anniversary."},{"type":"paragraph","text":"The absence of a complete historic roof also matters to how the monument is perceived. A ruin exposes spaces in ways its earlier occupants may never have experienced. The present silhouette should therefore not be mistaken for the original design, and a digital reconstruction would need to distinguish supported elements from conjecture."},{"type":"paragraph","text":"Sharda Temple is compelling without inflated certainty. Its scale, stonework and sacred associations already make it a significant place. A precise account can honour that significance while leaving room for unresolved chronology, changing interpretations and the difference between a remembered centre of learning and the architecture that survives."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Azad Kashmir","Architecture"],"province":"Azad Jammu and Kashmir","district":"Neelum","relatedDistrictIds":["azad-kashmir-neelum"],"provinceRegionIds":["azad-kashmir"],"relatedHeritageIds":["major-doam-6633"],"relatedStoryIds":["story-shared-sacred-landscapes-without-a-myth-of-seamless-harmony","story-neelum-valley-sacred-remains-and-a-river-corridor"],"contentType":"heritage-place","seo":{"title":"Sharda Temple: architecture and the limits of attribution | Virsapur Archives","description":"Sharda Temple’s stone architecture deserves a precise account that separates the standing sanctuary from expansive claims about an ancient university.","primaryKeyword":"Sharda Temple heritage","socialTitle":"Sharda Temple: architecture and the limits of attribution","socialDescription":"Sharda Temple’s stone architecture deserves a precise account that separates the standing sanctuary from expansive claims about an ancient university."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Sharda Temple","url":"https://doam.gov.pk/public/sites/6633","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"History, Architecture and Tourism Prospects of the Sharda Temple in Neelum Valley, Pakistan: An Appraisal","url":"https://grrjournal.com/article/history-architecture-and-tourism-prospects-of-the-sharda-temple-in-neelum-valley-pakistan-an-appraisal","publisher":"Global Regional Review, Junaid Ahmad, Anas Mahmud Arif and Adnan Anwar","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMapproximately150words;2022fieldstudyapproximately185words. Criticaluniversityidentificationattributedstudy, notdenialalllearningtradition. Cataloguecontradictoryorientation/exactstairsnotrepeated. Avoidscriptoriginclaimandunverifiedroyalfounder.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Separate the standing temple remains from broad literary and educational traditions attached to the name.","wordCount":473,"publicationHold":false,"sortOrder":67}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-sharda-fort-distinguishing-neighbouring-monuments','sharda-fort-distinguishing-neighbouring-monuments','review','{"id":"story-sharda-fort-distinguishing-neighbouring-monuments","type":"story","slug":"sharda-fort-distinguishing-neighbouring-monuments","title":"Sharda Fort: distinguishing neighbouring monuments","summary":"Sharda Fort is a separate nineteenth-century defensive place whose timber-and-rubble fabric should not be confused with the nearby stone temple.","body":[{"type":"paragraph","text":"Two monuments can share a place name without sharing a history. At Sharda, the fort and the better-known temple need separate records, photographs and explanations. The Department of Archaeology and Museums identifies a nineteenth-century fort near the meeting of the Madhumati stream and the Neelum River, within the village landscape. Its defensive architecture belongs to a different story from the large stone sanctuary nearby."},{"type":"paragraph","text":"The catalogue associates the fort with the Dogra period. It describes a roughly square enclosure with corner towers and identifies one more substantially surviving bastion as octagonal. Openings in the tower walls served observation and firing. These details establish a recognisable defensive building, rather than an alternative name for the temple compound."},{"type":"heading","level":2,"text":"Materials make the distinction clearer"},{"type":"paragraph","text":"The fort’s construction combines river stones, timber framing and earth. The survey describes deodar roof members and a layered roof incorporating birch bark and mud. This material account differs markedly from a description centred on the temple’s large dressed stone elements and shaped architectural recesses. Even before a visitor asks who built each place, the fabric provides a way to distinguish them."},{"type":"paragraph","text":"The catalogue also connects the fort with routes through the valley and towards Chilas. That gives a context for its military role, but it does not allow every road visible today to be treated as an unchanged historical route. A defensive position must be read against the terrain and the period being discussed."},{"type":"paragraph","text":"Government tourism lists sometimes group the Sharda name with several kinds of heritage. Such broad inventories are useful for recognising an area’s significance, but they are not a substitute for identifying individual structures. On a map, a misplaced label can turn that administrative shorthand into a false architectural claim."},{"type":"heading","level":2,"text":"Why separate identities matter"},{"type":"paragraph","text":"Imagine a photograph of the fort’s remaining tower captioned as part of an ancient university. The image would still look impressive, but the reader would have learned the wrong thing. The error could then travel into a tour description, a school presentation or another map. Accurate naming is therefore a form of care: it preserves the relationships between evidence and place."},{"type":"paragraph","text":"The same care applies to fragments found on the ground. The official description mentions pottery, but loose surface material alone does not establish the full chronology of an earlier settlement beneath the fort. That would require a documented archaeological investigation. A compelling possibility should remain a research question until the evidence supports more."},{"type":"paragraph","text":"Sharda Fort does not need the temple’s antiquity to be worth understanding. Its surviving construction speaks to another phase of the valley’s history, when a small defensive installation watched routes and occupied a strategic location. Keeping the two monuments distinct allows a richer account of Sharda: not one legendary complex stretched across centuries, but a landscape in which different buildings served different purposes over time."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Azad Kashmir","Architecture"],"province":"Azad Jammu and Kashmir","district":"Neelum","relatedDistrictIds":["azad-kashmir-neelum"],"provinceRegionIds":["azad-kashmir"],"relatedHeritageIds":["major-doam-6666"],"relatedStoryIds":["story-neelum-valley-sacred-remains-and-a-river-corridor"],"contentType":"heritage-place","seo":{"title":"Sharda Fort: distinguishing neighbouring monuments | Virsapur Archives","description":"Sharda Fort is a separate nineteenth-century defensive place whose timber-and-rubble fabric should not be confused with the nearby stone temple.","primaryKeyword":"Sharda Fort heritage","socialTitle":"Sharda Fort: distinguishing neighbouring monuments","socialDescription":"Sharda Fort is a separate nineteenth-century defensive place whose timber-and-rubble fabric should not be confused with the nearby stone temple."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Sharda Fort","url":"https://doam.gov.pk/public/sites/6666","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Tourism, Annual Development Programme2013–14: cultural heritage assets","url":"https://pndajk.gov.pk/ADP/2013-2014/Tourism.pdf","publisher":"Planning and Development Department, Azad Jammu and Kashmir","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMapproximately190words;governmenttourismlistapproximately20words demonstrates broadclassificationnotnewhistory. Sparseindependentfortstudy; no potterysurfaceprovesancientsettlement, precisegarrisoncount or geographyconflict. Article analytical focusidentityandmaterials, not paddedbiography.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Give the fort its own architectural identity rather than folding it into the temple story.","wordCount":459,"publicationHold":false,"sortOrder":68}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-mangla-fort-after-the-landscape-changed','mangla-fort-after-the-landscape-changed','review','{"id":"story-mangla-fort-after-the-landscape-changed","type":"story","slug":"mangla-fort-after-the-landscape-changed","title":"Mangla Fort after the landscape changed","summary":"Mangla Fort belongs to an older river landscape now experienced beside major water infrastructure; the two histories should be connected without being conflated.","body":[{"type":"paragraph","text":"Mangla Fort and Mangla Dam share a name and a landscape, but they are not one historical project. The fort belongs to an earlier pattern of occupation along the Jhelum; the dam transformed the wider setting in the twentieth century. Reading them together can reveal change, provided the modern water landscape is not projected backwards into the fort’s origins."},{"type":"paragraph","text":"The Department of Archaeology and Museums describes the fort beside the river, with an irregular enclosure formed from adjoining polygonal sections. Dressed sandstone, substantial walls and numerous narrow openings are prominent in its account. The main entrance is placed in the eastern wall and associated stylistically with the Sikh period. The record does not establish a single exact year in which every surviving part was built."},{"type":"paragraph","text":"The catalogue also preserves local accounts of religious occupants and temples within the enclosure. These should remain attributed traditions. Without independently identified structures or inscriptions, the recollections cannot be converted into a confident plan of four named temples."},{"type":"heading","level":2,"text":"A later infrastructure landscape"},{"type":"paragraph","text":"WAPDA records that construction of Mangla Dam began in 1962 and was completed in 1967. It describes the project as a major water and power undertaking on the Jhelum and records later raising work. These are separate historical layers from the fort. The reservoir’s presence in a contemporary photograph does not prove that the earlier builders designed their position beside an identical body of water."},{"type":"paragraph","text":"This distinction is especially important when a place is photographed primarily for its views. Water can make a ruin appear timeless, yet the apparent natural setting may itself be the result of a comparatively recent engineering intervention. A heritage interpretation should help the viewer recognise that change rather than conceal it."},{"type":"heading","level":2,"text":"Read the enclosure at its own scale"},{"type":"paragraph","text":"The fort’s irregular shape raises questions about how walls respond to terrain. Its openings and entrance invite a closer look at movement and observation. Those are architectural questions that can be asked without inventing a siege narrative or assigning a function to every damaged room."},{"type":"paragraph","text":"Comparing an older plan or photograph with a current one would be particularly valuable here. The comparison should identify its dates and viewpoints, because a change in camera position can look like a change in the building. Likewise, a survey’s description of missing roofs or damaged masonry should be presented as a dated observation, not silently updated to the present."},{"type":"paragraph","text":"Mangla also encourages a distinction between shared geography and shared identity. The fort, dam, reservoir and nearby settlements each have their own histories. Linking them on an atlas can make their relationships visible, but combining them into one catch-all attraction would lose the specificity that makes those relationships meaningful."},{"type":"paragraph","text":"The result is a more layered way to see the place. The fort remains an architectural subject in its own right, while the modern water infrastructure explains why its surroundings are encountered differently today. Neither history needs to erase the other."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Azad Kashmir","Architecture"],"province":"Azad Jammu and Kashmir","district":"Mirpur","relatedDistrictIds":["azad-kashmir-mirpur"],"provinceRegionIds":["azad-kashmir"],"relatedHeritageIds":["major-doam-6675"],"relatedStoryIds":[],"contentType":"heritage-place","seo":{"title":"Mangla Fort after the landscape changed | Virsapur Archives","description":"Mangla Fort belongs to an older river landscape now experienced beside major water infrastructure; the two histories should be connected without being conflated.","primaryKeyword":"Mangla Fort heritage","socialTitle":"Mangla Fort after the landscape changed","socialDescription":"Mangla Fort belongs to an older river landscape now experienced beside major water infrastructure; the two histories should be connected without being conflated."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Mangla Fort","url":"https://doam.gov.pk/public/sites/6675","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Mangla Dam","url":"https://wapda.gov.pk/mangla-dam/","publisher":"Water and Power Development Authority","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMapproximately165words;WAPDAapproximately75sharedbudgetwith69remaining125. No ancientQueenManglalegend;templesreportedlocaltraditionnotfact; no submergedstructureclaims or damengineeringnumbers.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Relate the surviving fort to later water infrastructure without inventing submerged histories.","wordCount":474,"publicationHold":false,"sortOrder":69}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-ramkot-fort-and-its-water-bound-setting','ramkot-fort-and-its-water-bound-setting','review','{"id":"story-ramkot-fort-and-its-water-bound-setting","type":"story","slug":"ramkot-fort-and-its-water-bound-setting","title":"Ramkot Fort and its water-bound setting","summary":"Ramkot’s enclosure, tanks and masonry can be read against a reservoir setting that is much younger than the fort itself.","body":[{"type":"paragraph","text":"Ramkot’s dramatic relationship with water can make it appear to have been conceived as a reservoir fortress. That impression needs a historical correction. The fort is older than the modern Mangla reservoir. Its hilltop position and surviving enclosure belong to an earlier landscape, while the surrounding water changes how the place is approached and photographed today."},{"type":"paragraph","text":"The Department of Archaeology and Museums describes an irregular, many-sided plan, with dressed stone, river pebbles, mortar and plaster. Its account identifies two water tanks, residential spaces, a watchtower and defensive openings. Those internal features matter as much as the exterior view: they show that occupying a fortified place required storage, shelter and controlled movement, not simply a striking perimeter wall."},{"type":"paragraph","text":"The catalogue associates the fort with earlier Kashmiri rulers and later Sikh strengthening. Precise patronage should remain qualified where the evidence is not secure. A broad sequence of occupation and alteration is more defensible than assigning all visible work to one ruler on the strength of a popular legend."},{"type":"heading","level":2,"text":"The water has its own date"},{"type":"paragraph","text":"WAPDA places the construction of Mangla Dam between 1962 and 1967. That chronology makes it clear why the present reservoir cannot be treated as an unchanged feature of Ramkot’s early history. The older hill and river system, the fort’s defensive arrangements and the later impounded water need to be interpreted as related but distinct layers."},{"type":"paragraph","text":"The tanks inside the fort sharpen this distinction. Stored water within an enclosure answers a different practical question from the large body of water outside it today. Their presence invites investigation of the fort’s provisioning, but does not by itself reveal capacity, seasonal reliability or how long a garrison could resist a siege."},{"type":"heading","level":2,"text":"A changing conservation setting"},{"type":"paragraph","text":"An October 2026 Associated Press of Pakistan report describes officials reviewing restoration and tourism development at Ramkot, including access improvements, fencing, landscaping and facilities. The report also records concern that development preserve the fort’s historic character. This is evidence of an active programme and review, not confirmation that all work is finished or that a particular visitor service is available."},{"type":"paragraph","text":"It also means older descriptions of abandonment should not be copied as if nothing had changed. A useful account dates its observations and distinguishes historic fabric from new infrastructure. Visitors should rely on current local arrangements for access rather than treating an old description of a boat approach as an unconditional instruction."},{"type":"paragraph","text":"Ramkot is most interesting when the picturesque view leads inward to the plan and outward to the changed landscape. The walls, tanks and openings offer questions about earlier occupation; the reservoir and contemporary works raise questions about how the monument is encountered now. Keeping both in view produces a richer story than either an isolated ruin or a simple leisure destination. It allows the fort to remain a historical place while acknowledging that its surroundings and public use continue to evolve."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Azad Kashmir","Architecture"],"province":"Azad Jammu and Kashmir","district":"Mirpur","relatedDistrictIds":["azad-kashmir-mirpur"],"provinceRegionIds":["azad-kashmir"],"relatedHeritageIds":["major-doam-6676"],"relatedStoryIds":[],"contentType":"heritage-place","seo":{"title":"Ramkot Fort and its water-bound setting | Virsapur Archives","description":"Ramkot’s enclosure, tanks and masonry can be read against a reservoir setting that is much younger than the fort itself.","primaryKeyword":"Ramkot Fort heritage","socialTitle":"Ramkot Fort and its water-bound setting","socialDescription":"Ramkot’s enclosure, tanks and masonry can be read against a reservoir setting that is much younger than the fort itself."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Ramkot Fort","url":"https://doam.gov.pk/public/sites/6676","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Mangla Dam","url":"https://wapda.gov.pk/mangla-dam/","publisher":"Water and Power Development Authority","accessDate":"2026-10-22"},{"title":"Restoration, Tourism Development Of Centuries-old Ramkot Fort Reviewed","url":"https://www.urdupoint.com/en/pakistan/restoration-tourism-development-of-centuries-2264554.html","publisher":"Associated Press of Pakistan, syndicated by UrduPoint","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMapproximately185words;WAPDAapproximately35words cumulative110with68;APPindexedOct2reportapproximately75words. No currentboat/safetypromise, templeidentificationunsupportedexcluded;earlierpatronattributionqualified.2020conditionnotclaimedcurrent.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Read the relationship between enclosure and terrain while leaving current access to verified advice.","wordCount":467,"publicationHold":false,"sortOrder":70}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-baghsar-fort-walls-courts-and-regional-power','baghsar-fort-walls-courts-and-regional-power','review','{"id":"story-baghsar-fort-walls-courts-and-regional-power","type":"story","slug":"baghsar-fort-walls-courts-and-regional-power","title":"Baghsar Fort: walls, courts and regional power","summary":"Baghsar Fort is most securely understood through its enclosures, circulation and provision for occupation, rather than a legendary royal death.","body":[{"type":"paragraph","text":"Baghsar Fort is often introduced through a royal association: the story that Emperor Jahangir died there while returning from Kashmir. The official archaeological catalogue itself presents this as something said, not as an established conclusion. The fort does not need that uncertain episode to justify attention. Its enclosures, rooms and water provision offer a substantial architectural subject in their own right."},{"type":"paragraph","text":"Located in the Samahni area of Bhimber, Baghsar occupies an elevated setting near the Line of Control. A 2023 heritage survey describes an outer enclosure and an inner fortified area, with entrances, bastions and rooms arranged along the walls. The same survey records a hall and a stepped water pond. These elements suggest a place organised for occupation as well as defence."},{"type":"heading","level":2,"text":"An enclosure within an enclosure"},{"type":"paragraph","text":"The relationship between outer and inner boundaries is a useful starting point. Crossing one gate does not necessarily bring a visitor directly to the most protected part of a fort. Successive thresholds can divide circulation, visibility and access. At Baghsar, the recorded arrangement invites examination of how entrances and internal spaces relate, rather than treating the perimeter as the whole monument."},{"type":"paragraph","text":"Published descriptions also identify narrow openings and defensive details along the walls. Their shape and position need careful recording before a specific weapon or tactical function is assigned to each. A slit is evidence of an opening; a detailed account of a battle requires other sources. Architecture can reveal possibilities without supplying a complete military narrative."},{"type":"paragraph","text":"The architectural inventory published by Naqoosh-e-Javidan acknowledges that the fort’s early history is poorly known. Its description emphasises multiple entrances, perimeter rooms and internal facilities. Accounts differ over some dimensions and building details, which makes a reliable measured survey more valuable than repeating the most dramatic figures."},{"type":"heading","level":2,"text":"Water, rooms and everyday occupation"},{"type":"paragraph","text":"The stepped pond changes the scale of the story. A fort required people to remain within it, and water was part of that practical problem. The feature should be documented as a physical structure before its capacity or exact use is inferred. Its presence alone cannot tell us how many people lived there or how long supplies lasted."},{"type":"paragraph","text":"Rooms around an enclosure raise related questions about sleeping, storage, administration and service. Those uses should not be allocated to individual chambers without evidence, but they remind us that defensive architecture was inhabited architecture. The experience of holding a position depended on daily provision as well as walls."},{"type":"paragraph","text":"Baghsar’s proximity to a sensitive boundary also means that a historical account is not an access guide. A heritage listing does not establish permission to enter, and current arrangements require separate confirmation from the relevant authorities."},{"type":"paragraph","text":"The most rewarding interpretation therefore begins with what can be examined: boundaries, thresholds, rooms, water and terrain. Royal traditions can be included with their uncertainty intact. They should enrich the record without displacing the material evidence that makes Baghsar a distinctive part of the region’s history."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Azad Kashmir","Architecture"],"province":"Azad Jammu and Kashmir","district":"Bhimber","relatedDistrictIds":["azad-kashmir-bhimber"],"provinceRegionIds":["azad-kashmir"],"relatedHeritageIds":["major-doam-6665"],"relatedStoryIds":[],"contentType":"heritage-place","seo":{"title":"Baghsar Fort: walls, courts and regional power | Virsapur Archives","description":"Baghsar Fort is most securely understood through its enclosures, circulation and provision for occupation, rather than a legendary royal death.","primaryKeyword":"Baghsar Fort heritage","socialTitle":"Baghsar Fort: walls, courts and regional power","socialDescription":"Baghsar Fort is most securely understood through its enclosures, circulation and provision for occupation, rather than a legendary royal death."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Baghsar Fort","url":"https://doam.gov.pk/public/sites/6665","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Bhimber heritage survey, Baghsar Fort and Sarai Saad Abad, page673","url":"https://www.ojs.ahss.org.pk/journal/article/download/278/280/401","publisher":"Annals of Human and Social Sciences, volume4 number2,2023","accessDate":"2026-10-22"},{"title":"Baghsar Fort","url":"https://pakheritage.org/baghsar-fort/","publisher":"Naqoosh-e-Javidan, Architecture History and Heritage of Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMapproximately65words;2023surveyapproximately120words(sharedbudget71<=75);architectureinventoryapproximately85words. Inventory conflicts on storeys/materials avoided. Jahangir death notasserted;currentrestrictedaccessnotadvised. No precise counts fromweakrecord.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Use the fort’s plan to discuss a local defensive ensemble rather than legendary rulers.","wordCount":475,"publicationHold":false,"sortOrder":71}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-saadabad-caravan-sarai-and-the-architecture-of-stopping','saadabad-caravan-sarai-and-the-architecture-of-stopping','review','{"id":"story-saadabad-caravan-sarai-and-the-architecture-of-stopping","type":"story","slug":"saadabad-caravan-sarai-and-the-architecture-of-stopping","title":"Saadabad Caravan Sarai and the architecture of stopping","summary":"Saadabad Caravan Sarai turns the history of movement into an architectural story of gateways, repeated rooms and a shared court.","body":[{"type":"paragraph","text":"Routes leave more than roads behind. They also leave places where movement paused: enclosed courts, rooms, water arrangements and guarded entrances. Saadabad Caravan Sarai, near Samahni in Bhimber, makes that architecture of stopping visible. Its interest lies in how a repeated set of modest spaces was organised around a shared centre."},{"type":"paragraph","text":"The Department of Archaeology and Museums describes a single-storey enclosure with gateways in the eastern and western walls. Rooms line the courtyard, and guardrooms accompany the entrances. The catalogue also records corner bastions, roof access and recessed arches. Together, these elements give the sarai a dual character: an accommodating interior within a clearly bounded exterior."},{"type":"paragraph","text":"The building is associated with the Mughal period, but the reviewed evidence does not establish an exact foundation date or a securely identified patron. It is better to preserve that broad attribution than to supply a particular emperor simply because the structure stands in a landscape of imperial travel."},{"type":"heading","level":2,"text":"Repetition is the design"},{"type":"paragraph","text":"At a palace, a visitor may look for the exceptional room. At a sarai, repetition can be the more revealing feature. Comparable chambers facing a common court create an arrangement that can be understood without every occupant being known. The shared space and the individual cell belong to one system, allowing a place to gather people without making every activity public."},{"type":"paragraph","text":"The gates change that experience again. They concentrate movement through the perimeter, while adjacent rooms give the threshold an architectural presence. The catalogue’s account of battlements and openings should not make the sarai indistinguishable from a battlefield fortress. Security and accommodation can coexist without proving that a particular siege occurred there."},{"type":"paragraph","text":"A 2023 heritage survey also records a mosque associated with the enclosure and later domestic construction within the courtyard. That observation adds another historical layer: the sarai is not only a surviving plan from an earlier age, but a place subsequently used and altered. The survey is a dated record, not a current count of residents or buildings."},{"type":"heading","level":2,"text":"The courtyard is not empty space"},{"type":"paragraph","text":"It is tempting to regard later use as visual clutter and imagine that conservation simply means returning the court to an ideal photograph. Such a response would overlook the people connected to the place. Any future interpretation or intervention should distinguish architectural evidence from assumptions about who belongs there and should treat current occupants as participants, not obstacles in a view."},{"type":"paragraph","text":"For the historical reader, the same courtyard offers a different lesson. An open centre can be the organising element of a building rather than leftover land. Its proportions, access and relationship to the surrounding rooms are essential to understanding how the complex worked."},{"type":"paragraph","text":"Saadabad’s story is therefore not a list of famous travellers who might have passed through. It is a material account of provision along a route. Gates, cells and court make the act of stopping visible, while later use reminds us that buildings can outlive the systems of movement for which they were first made."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Azad Kashmir","Architecture"],"province":"Azad Jammu and Kashmir","district":"Bhimber","relatedDistrictIds":["azad-kashmir-bhimber"],"provinceRegionIds":["azad-kashmir"],"relatedHeritageIds":["major-doam-6680"],"relatedStoryIds":["story-sarai-architecture-and-the-logistics-of-travel","story-bhimber-and-the-architecture-of-a-route"],"contentType":"heritage-place","seo":{"title":"Saadabad Caravan Sarai and the architecture of stopping | Virsapur Archives","description":"Saadabad Caravan Sarai turns the history of movement into an architectural story of gateways, repeated rooms and a shared court.","primaryKeyword":"Saadabad Caravan Sarai heritage","socialTitle":"Saadabad Caravan Sarai and the architecture of stopping","socialDescription":"Saadabad Caravan Sarai turns the history of movement into an architectural story of gateways, repeated rooms and a shared court."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Saadabad Caravan Sarai","url":"https://doam.gov.pk/public/sites/6680","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Bhimber heritage survey, Sarai Saad Abad, page673","url":"https://www.ojs.ahss.org.pk/journal/article/download/278/280/401","publisher":"Annals of Human and Social Sciences, volume4 number2,2023","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMapproximately185words;AHSSapproximately70words cumulative190with70. Bothsourcesspecificcloseread. No exactfounder or continuouslyoccupiedclaim. Moderninhabitationreported2023notcurrentcensus;relocationplansnotinvented.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain roadside accommodation as a material record of movement and exchange.","wordCount":483,"publicationHold":false,"sortOrder":72}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-rawat-fort-the-enclosure-and-the-tombs','rawat-fort-the-enclosure-and-the-tombs','review','{"id":"story-rawat-fort-the-enclosure-and-the-tombs","type":"story","slug":"rawat-fort-the-enclosure-and-the-tombs","title":"Rawat Fort: the enclosure and the tombs","summary":"Rawat combines the regular cells of a fortified sarai with a mosque, mausoleum and graves, making it a precinct of several overlapping functions.","body":[{"type":"paragraph","text":"Rawat is called a fort, but the arrangement inside its walls suggests a more layered identity. The Department of Archaeology and Museums describes regular rows of living cells around a quadrangular court and considers the complex to have originated as a sarai. Within that enclosure are a mosque, a mausoleum and scattered graves. Accommodation, defence, worship and remembrance occupy the same precinct."},{"type":"paragraph","text":"The catalogue tentatively places the early structure in the Sultanate period. It identifies two gateways, a three-domed mosque in the western range and an octagonal mausoleum near the northwestern corner. The mausoleum partly overlaps the mosque’s frontage in the recorded arrangement. That relationship is worth noticing because it suggests that the precinct should be read through its parts, not assumed to be one perfectly coordinated original composition."},{"type":"heading","level":2,"text":"A regular edge and a less regular centre"},{"type":"paragraph","text":"The repeated cells make the perimeter legible. They face inward, connecting individual enclosed spaces with the shared court. The funerary structures introduce another kind of use into that spatial order. A visitor’s eye moves from repetition to singular monuments, then to the graves that occupy the open area."},{"type":"paragraph","text":"This contrast provides a useful way to ask about change. Were particular structures added later? Did circulation shift as the precinct acquired new uses? The visible relationship can prompt those questions, but a complete sequence would require building analysis and documentary evidence. The word fort alone cannot answer them."},{"type":"paragraph","text":"Rawat’s association with Gakhar history is important, yet popular accounts sometimes repeat precise battle dates and named burials without resolving contradictions. The safest introduction begins with the documented architecture and treats individual historical attributions as claims requiring their own evidence. A grave’s position within a famous precinct is not enough to identify its occupant."},{"type":"heading","level":2,"text":"Conservation is another chapter"},{"type":"paragraph","text":"The National Heritage and Culture Division’s 2022–23 yearbook records a preservation and development project for Rawat. In January 2024, Radio Pakistan reported ministerial directions to speed up conservation work. These sources establish a modern conservation effort at particular dates. They do not certify that every element is now complete, nor that the condition described in an older inventory remains unchanged."},{"type":"paragraph","text":"For interpretation, this creates an opportunity to distinguish surviving fabric from repair. A renewed surface may help protect a structure, but visitors should still be able to understand the evidence for its earlier form. Similarly, improving the grounds should not obscure the relationships between cells, mosque, mausoleum and graves that make the precinct distinctive."},{"type":"paragraph","text":"Rawat rewards a circuit of attention rather than a search for one iconic façade. Its regular perimeter explains one aspect of the place; its sacred and funerary structures explain another. Seen together, they show how a bounded compound can gather different functions over time. The result is a more compelling history than a single label or a heroic episode detached from the building itself."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Islamabad","Architecture"],"province":"Islamabad Capital Territory","district":"Islamabad","relatedDistrictIds":["islamabad-islamabad"],"provinceRegionIds":["islamabad"],"relatedHeritageIds":["major-doam-6232"],"relatedStoryIds":[],"contentType":"heritage-place","seo":{"title":"Rawat Fort: the enclosure and the tombs | Virsapur Archives","description":"Rawat combines the regular cells of a fortified sarai with a mosque, mausoleum and graves, making it a precinct of several overlapping functions.","primaryKeyword":"Rawat Fort heritage","socialTitle":"Rawat Fort: the enclosure and the tombs","socialDescription":"Rawat combines the regular cells of a fortified sarai with a mosque, mausoleum and graves, making it a precinct of several overlapping functions."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Rawat Fort","url":"https://doam.gov.pk/public/sites/6232","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Jamal Shah directs for speedy completion of Rawat Fort","url":"https://www.radio.gov.pk/06-01-2024/jamal-shah-directs-for-speedy-completion-of-rawat-fort","publisher":"Radio Pakistan","accessDate":"2026-10-22"},{"title":"National Heritage and Culture Division Year Book2022–23, page45","url":"https://www.heritage.pakistan.gov.pk/SiteImage/Misc/files/Year%20Book%202022-23%2004-11-2024.pdf","publisher":"National Heritage and Culture Division, Government of Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMapproximately180words;RadioPakistanreadindexedapproximately30;yearbookapproximately40(sharedremainder160). Excluded impossible1546SherShahbattleclaim inAPP2016; no assertionpreciseSarangsonsidentities. Designanalysisoriginal.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain how the defensive and funerary elements occupy one historic precinct.","wordCount":458,"publicationHold":false,"sortOrder":73}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-pharwala-fort-and-the-gakhar-landscape','pharwala-fort-and-the-gakhar-landscape','review','{"id":"story-pharwala-fort-and-the-gakhar-landscape","type":"story","slug":"pharwala-fort-and-the-gakhar-landscape","title":"Pharwala Fort and the Gakhar landscape","summary":"Pharwala connects Gakhar political history with the Soan landscape, differentiated gateways and a foundation tradition that still requires care.","body":[{"type":"paragraph","text":"Pharwala is a place where regional power becomes legible through terrain. Set beside the Soan in the Potohar landscape, the fort is closely associated with the Gakhars. Its history is not simply a smaller version of an imperial capital’s story. It concerns local authority, control of approaches and the changing relationship between regional rulers and larger powers."},{"type":"paragraph","text":"Pakistan’s 2026 submission to UNESCO’s Tentative List describes the fort on the left bank of the river and identifies it as a principal Gakhar centre. The same text presents the early foundation under Sultan Kaigohar as a traditional attribution. That qualification matters. A remembered origin around the early eleventh century is not equivalent to a securely dated surviving wall."},{"type":"paragraph","text":"The submission also recounts Babur’s capture of the fort in 1519 and the Gakhars’ later relationship with the Mughals. These historical associations give the site context, but they should not be used to assign every gateway or ruin to the moment of a particular campaign."},{"type":"heading","level":2,"text":"Gateways are not interchangeable"},{"type":"paragraph","text":"The Tentative List description differentiates entrances by name, scale and architectural treatment. Hathi Gate is described with substantial flanking towers and carved rosettes; other entrances relate to different approaches and internal areas. The older archaeological catalogue also records named gates, but gives a different total. That discrepancy should be resolved through a clear site inventory rather than hidden behind an exact-sounding number."},{"type":"paragraph","text":"The material account is more secure at a broad level: stone construction, mortar and surviving portions of fortification. The Department of Archaeology and Museums notes that the earlier residential buildings were not preserved in the condition it recorded. A visitor should therefore resist filling the enclosure with an imagined palace plan merely because a historic account mentions a ruler’s residence."},{"type":"heading","level":2,"text":"A landscape, not an isolated object"},{"type":"paragraph","text":"The relationship between river, slope and gateway helps explain the fort’s position. It also reminds us that protection involves more than a single entrance façade. Approaches, views and neighbouring remains can carry information that disappears if the fort is treated as a decorative object cut out from its setting."},{"type":"paragraph","text":"The government’s 2022–23 heritage yearbook records a feasibility study for conservation and preservation. This is evidence of a planning stage, not a completion certificate. Likewise, Tentative List inclusion is a proposal within a longer heritage process; it is not inscription as a UNESCO World Heritage property."},{"type":"paragraph","text":"Pharwala is strongest as a story when these distinctions remain intact. Its Gakhar associations deserve attention without inflated foundation certainty. Its gateways deserve individual description without assuming every name maps cleanly onto a surviving structure. Its landscape deserves to remain part of the record, not merely the background of a photograph."},{"type":"paragraph","text":"Together, those elements show why the fort matters: it preserves a material point of entry into Potohar’s regional political history, while also revealing how much careful survey and interpretation still contribute to understanding a well-known name."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":"Punjab; Islamabad Capital Territory","district":"Rawalpindi; Islamabad","relatedDistrictIds":["punjab-rawalpindi","islamabad-islamabad"],"provinceRegionIds":["punjab","islamabad"],"relatedHeritageIds":["major-doam-6224"],"relatedStoryIds":[],"contentType":"heritage-place","seo":{"title":"Pharwala Fort and the Gakhar landscape | Virsapur Archives","description":"Pharwala connects Gakhar political history with the Soan landscape, differentiated gateways and a foundation tradition that still requires care.","primaryKeyword":"Pharwala Fort heritage","socialTitle":"Pharwala Fort and the Gakhar landscape","socialDescription":"Pharwala connects Gakhar political history with the Soan landscape, differentiated gateways and a foundation tradition that still requires care."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Pharwala Fort","url":"https://doam.gov.pk/public/sites/6224","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Pharwala Fort, Tentative List submission7027","url":"https://whc.unesco.org/en/tentativelists/7027/","publisher":"UNESCO World Heritage Centre, submission by Pakistan","accessDate":"2026-10-22"},{"title":"National Heritage and Culture Division Year Book2022–23, page45","url":"https://www.heritage.pakistan.gov.pk/SiteImage/Misc/files/Year%20Book%202022-23%2004-11-2024.pdf","publisher":"National Heritage and Culture Division, Government of Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMapproximately85words;UNESCOsubmissionapproximately190;yearbookapproximately25 cumulative65with72. Explicit6vs7gatediscrepancy. DOAM54sqkm/garrisonfigures excluded. Traditional1008foundationqualified,notnewcanonicaldata.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Investigate documented political associations through terrain and surviving architecture.","wordCount":465,"publicationHold":false,"sortOrder":74}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-shah-allah-ditta-caves-separating-layers-of-use','shah-allah-ditta-caves-separating-layers-of-use','review','{"id":"story-shah-allah-ditta-caves-separating-layers-of-use","type":"story","slug":"shah-allah-ditta-caves-separating-layers-of-use","title":"Shah Allah Ditta Caves: separating layers of use","summary":"Shah Allah Ditta’s shelters, painted surfaces and spring-side structures should be read as separate layers of use, not one uninterrupted ancient story.","body":[{"type":"paragraph","text":"Shah Allah Ditta is often introduced through a sweeping succession of religions and rulers. The physical site offers a more precise starting point: two natural rock shelters near a spring, altered by walls, plaster, painted surfaces and water-related construction. These are different kinds of evidence, and they need not all belong to the same period."},{"type":"paragraph","text":"The Department of Archaeology and Museums describes shelters in kanjur stone on opposite sides of the spring. Its account notes an enclosing wall at one entrance, plaster with red coatings, a small internal platform and smoke-darkened surfaces. In front are remains of a paved channel and a stone-built tank. The natural formation and the constructed additions should therefore be distinguished rather than described as if the entire complex had been made at once."},{"type":"heading","level":2,"text":"Painted surfaces need careful attribution"},{"type":"paragraph","text":"A government press release issued for the conservation project in January 2024 describes paintings beneath later whitewash and suggests a Hindu identification, possibly Vishnu. Other public accounts have described the imagery as Buddhist. Those labels should not be reconciled by guesswork. A properly documented examination of the surviving pigments, imagery and layers is needed before a specific identification can be presented confidently."},{"type":"paragraph","text":"Smoke staining likewise shows use involving fire, but does not independently identify the occupants or date their activity. A surface can be altered repeatedly. The most informative account would record where each layer occurs and how it relates to adjoining plaster or masonry, rather than turning colour into a simple chronology."},{"type":"paragraph","text":"The 2024 release also records worship by Hindu families before Partition. That is a distinct historical claim about later use, not proof of an unbroken sequence reaching back thousands of years."},{"type":"heading","level":2,"text":"Conservation should preserve the questions"},{"type":"paragraph","text":"The announced project included archaeological excavation, documentation, study of binding materials and drainage work. These tasks are significant because they address the evidence and its physical setting, not only the appearance of the visitor area. A spring-side site cannot be understood solely through the cave openings; water movement and built channels belong to its material history too."},{"type":"paragraph","text":"In September 2026, Associated Press of Pakistan reported an intended October opening. An intended date is not confirmation that opening occurred, so current access should be checked separately. The history of the site should not be made dependent on a promotional timetable."},{"type":"paragraph","text":"For a visitor, the strongest questions are close and concrete. Which parts are natural rock? Where was masonry added? Which surfaces carry plaster, and which remain exposed? How do the channel and tank relate to the shelters? Answers to these questions can be observed or investigated without inventing a continuous chain of named occupants."},{"type":"paragraph","text":"Shah Allah Ditta’s appeal lies in those layers. A natural refuge became a place shaped by people, water and religious practice. Preserving the distinctions between them makes the site more intelligible than an impressive age claim that the surviving evidence cannot yet securely support."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Islamabad","Architecture"],"province":"Islamabad Capital Territory","district":"Islamabad","relatedDistrictIds":["islamabad-islamabad"],"provinceRegionIds":["islamabad"],"relatedHeritageIds":["major-doam-6344"],"relatedStoryIds":["story-a-cave-is-not-automatically-a-prehistoric-home","story-the-capitals-older-places","story-the-margalla-foothills-before-the-planned-capital"],"contentType":"heritage-place","seo":{"title":"Shah Allah Ditta Caves: separating layers of use | Virsapur Archives","description":"Shah Allah Ditta’s shelters, painted surfaces and spring-side structures should be read as separate layers of use, not one uninterrupted ancient story.","primaryKeyword":"Shah Allah Ditta Caves heritage","socialTitle":"Shah Allah Ditta Caves: separating layers of use","socialDescription":"Shah Allah Ditta’s shelters, painted surfaces and spring-side structures should be read as separate layers of use, not one uninterrupted ancient story."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Shah Allah Ditta Caves","url":"https://doam.gov.pk/public/sites/6344","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Minister lays foundation stone of Shah Alla Ditta Caves preservation and development project,1January2024","url":"https://pid.gov.pk/site/press_detail/24286","publisher":"Press Information Department, Government of Pakistan","accessDate":"2026-10-22"},{"title":"Shah Allah Ditta Caves to be opened for visitors in first half of October,8September2026","url":"https://www.app.com.pk/national/shah-allah-ditta-caves-to-be-opened-for-visitors-in-first-half-of-october-minister/","publisher":"Associated Press of Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMapproximately155words;PIDapproximately180;APPapproximately30. SourceidentificationconflictBuddha/Vishnukeptuncertain;2,400yearmuralsclaimnotrepeated. Announcementnotactualopening. No continuousoccupationorAlexanderrouteassertions.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Distinguish rock shelter, religious interpretation and later occupation without assigning an unsupported continuous history.","wordCount":469,"publicationHold":false,"sortOrder":75}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-ban-faqiran-stupa-above-the-capital','ban-faqiran-stupa-above-the-capital','review','{"id":"story-ban-faqiran-stupa-above-the-capital","type":"story","slug":"ban-faqiran-stupa-above-the-capital","title":"Ban Faqiran Stupa above the capital","summary":"Ban Faqiran’s excavated stupa brings the archaeological landscape around Islamabad into focus through masonry, recorded finds and later structures.","body":[{"type":"paragraph","text":"Ban Faqiran introduces a history older than Islamabad’s planned streets without requiring the city to be described as an ancient capital. The archaeological site lies on a Margalla spur between the Taxila and Soan landscapes. Its principal excavated feature is a Buddhist stupa, while other remains belong to later activity. The distinction between the age of a modern city and the age of occupation in its territory is essential."},{"type":"paragraph","text":"The Department of Archaeology and Museums describes a square stupa base with diaper masonry, shaped kanjur stone and surviving traces of lime plaster. Its upper structure is missing. These details make the building an archaeological remnant, not a complete monument whose original height can be read from what stands today."},{"type":"heading","level":2,"text":"What excavation adds"},{"type":"paragraph","text":"Abdul Ghafoor Lone’s preliminary report identifies the Buddhist monument broadly within the early centuries CE and discusses the wider complex, including a later mosque and substantial water reservoir. The report provides a research framework that is more precise than treating every structure on the ridge as one Buddhist establishment."},{"type":"paragraph","text":"Contemporary reporting of the department’s work records the start of excavation in 2015 under Lone’s field direction. The finds included coins, pottery and iron arrowheads. Such objects are valuable because they can help establish sequences when their contexts are recorded. Their mere presence does not mean that every coin dates the construction of the stupa."},{"type":"paragraph","text":"The excavation report itself distinguishes finds from different layers and notes a surface coin that could not be securely connected with the structures. This is a particularly useful example of archaeological caution. An old object found at a site may have moved, been retained for a long time or come from an uncertain context. Its date and the date of a wall are separate propositions."},{"type":"heading","level":2,"text":"A monument in a wider terrain"},{"type":"paragraph","text":"Ban Faqiran’s position allows it to be considered alongside the region’s better-known Buddhist remains. That geographical relationship does not automatically place it within the boundaries of the UNESCO World Heritage property at Taxila. Cultural connection, proximity and formal designation answer different questions and should not be collapsed into one label."},{"type":"paragraph","text":"The surviving masonry also invites close observation. Diaper work combines larger stones with smaller filling material; moulded elements articulate the base; traces of plaster indicate that the visible stone was not necessarily intended to remain exposed. These features help a reader imagine construction and finish without requiring a speculative reconstruction of the missing superstructure."},{"type":"paragraph","text":"A visit or photograph should preserve the distinction between excavated evidence and later repair. Exposure creates a need for maintenance, and a current condition assessment should be dated rather than inferred from an old discovery announcement."},{"type":"paragraph","text":"Ban Faqiran matters because it brings archaeological method into the story of the capital’s surroundings. A hilltop remnant becomes intelligible through masonry, stratigraphy and carefully recorded objects. The reward is not an inflated claim to the oldest anything, but a more grounded understanding of how different periods left evidence in the same landscape."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Islamabad","Architecture"],"province":"Islamabad Capital Territory","district":"Islamabad","relatedDistrictIds":["islamabad-islamabad"],"provinceRegionIds":["islamabad"],"relatedHeritageIds":["major-doam-6315"],"relatedStoryIds":["story-the-margalla-foothills-before-the-planned-capital"],"contentType":"heritage-place","seo":{"title":"Ban Faqiran Stupa above the capital | Virsapur Archives","description":"Ban Faqiran’s excavated stupa brings the archaeological landscape around Islamabad into focus through masonry, recorded finds and later structures.","primaryKeyword":"Ban Faqiran Stupa heritage","socialTitle":"Ban Faqiran Stupa above the capital","socialDescription":"Ban Faqiran’s excavated stupa brings the archaeological landscape around Islamabad into focus through masonry, recorded finds and later structures."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Ban Faqiran Stupa","url":"https://doam.gov.pk/public/sites/6315","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Preliminary Report: Excavation of the Buddhist Stupa at Ban Faqiran-Islamabad","url":"https://iris.unive.it/retrieve/e4239ddd-bd16-7180-e053-3705fe0a3322/Archaeology%20New%202019%20%20%2025-06-2020.pdf","publisher":"Pakistan Archaeology, Abdul Ghafoor Lone","accessDate":"2026-10-22"},{"title":"Conservation of Ban Faqiran Heritage Site to Enhance Beauty, Attraction of Capital","url":"https://www.urdupoint.com/en/pakistan/conservation-of-ban-faqiran-heritage-site-t-381097.html","publisher":"Associated Press of Pakistan, syndicated by UrduPoint","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMapproximately90words;Loneprimaryindexedintro andartifactpages~185words;APP2018approximately90. FullprimaryPDF403; indexed passagescloseread plusmirroredextractnotclaimedwholebook. Findsstratificationavoidsoldcoin=stupadate;noTaxilaUNESCOboundaryclaim.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Introduce excavation evidence near Islamabad beyond the better-known Taxila itinerary.","wordCount":481,"publicationHold":false,"sortOrder":76}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-saidpurs-temple-complex-in-a-changing-village','saidpurs-temple-complex-in-a-changing-village','review','{"id":"story-saidpurs-temple-complex-in-a-changing-village","type":"story","slug":"saidpurs-temple-complex-in-a-changing-village","title":"Saidpur’s temple complex in a changing village","summary":"Saidpur’s temple precinct reveals how conservation, village life and tourism can give historic religious buildings new—and sometimes contested—roles.","body":[{"type":"paragraph","text":"Saidpur’s religious precinct is part of a village that has been remade for visitors. That transformation makes the temple complex more than an architectural curiosity near Islamabad. It raises a question that applies to many heritage places: what happens when buildings once connected with worship and everyday community life are presented primarily as attractions?"},{"type":"paragraph","text":"The Department of Archaeology and Museums describes a complex with temples and a dharamshala. Its architectural account identifies brick construction, a square principal shrine, a domed superstructure and recessed exterior panels. Those details provide a useful starting point, but a description of forms alone cannot explain how the precinct’s role changed."},{"type":"heading","level":2,"text":"A village, not a vacant stage"},{"type":"paragraph","text":"A case study published by NED University’s Journal of Research in Architecture and Planning examines Saidpur’s revitalisation through visits, interviews and photographic documentation covering 2006–2011. It identifies the mandir, a Sikh religious building and the dharamshala as major historic elements, arranged on a raised platform with an entrance connecting to the village street."},{"type":"paragraph","text":"The study also records the dharamshala’s later use as a girls’ school. This is an important reminder that buildings can acquire practical roles after the communities that established them change or leave. Such reuse is part of a building’s biography, even when it does not preserve the original function."},{"type":"paragraph","text":"Looking at the precinct only as a restored façade would miss those relationships with education, streets and residents. A conservation account should ask who used a building at different times, not only which surfaces were repaired."},{"type":"heading","level":2,"text":"Heritage status and religious meaning"},{"type":"paragraph","text":"In a 2016 parliamentary answer, the government described Saidpur’s tourist-village programme and stated that the preserved religious buildings were not intended to function for worship under that arrangement. This records an administrative position at a particular time. It should not be treated as a neutral statement that religious meaning had disappeared, nor as proof of the current rules."},{"type":"paragraph","text":"The distinction matters because a monument can remain significant to a faith community even when it is managed as a heritage exhibit. Interpretation should acknowledge the original religious identities rather than reducing them to evidence of picturesque diversity. Equally, current practice should be verified rather than assumed from an old policy answer."},{"type":"paragraph","text":"For the visitor, a respectful reading begins by recognising that these are not interchangeable ornamental buildings. The temple, Sikh structure and dharamshala had different purposes. Their proximity makes a shared precinct, not a single undifferentiated religious history."},{"type":"paragraph","text":"Saidpur offers a particularly clear view of the choices embedded in heritage tourism. Repair can make a place visible, but visibility is not the same as a complete account of its people and uses. The strongest presentation would hold architecture, village change and continuing religious associations together. That would allow the precinct to be understood as a layered cultural place, rather than simply an attractive stop between restaurants and mountain views."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Islamabad","Architecture"],"province":"Islamabad Capital Territory","district":"Islamabad","relatedDistrictIds":["islamabad-islamabad"],"provinceRegionIds":["islamabad"],"relatedHeritageIds":["major-doam-6230"],"relatedStoryIds":["story-changing-custodianship-of-a-religious-building","story-the-capitals-older-places"],"contentType":"heritage-place","seo":{"title":"Saidpur’s temple complex in a changing village | Virsapur Archives","description":"Saidpur’s temple precinct reveals how conservation, village life and tourism can give historic religious buildings new—and sometimes contested—roles.","primaryKeyword":"Saidpur Temple Complex heritage","socialTitle":"Saidpur’s temple complex in a changing village","socialDescription":"Saidpur’s temple precinct reveals how conservation, village life and tourism can give historic religious buildings new—and sometimes contested—roles."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Said Pur Temple Complex","url":"https://doam.gov.pk/public/sites/6230","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Saidpur Village revitalisation case study,JRAP2015firstissue","url":"https://jrap.neduet.edu.pk/arch-journal/JRAP_2015(FirstIssue)/JRAP-2015(1stIssue).pdf","publisher":"NED University of Engineering and Technology, Journal of Research in Architecture and Planning","accessDate":"2026-10-22"},{"title":"National Assembly questions and answers,22February2016, question on Saidpur temple","url":"https://www.na.gov.pk/uploads/documents/questions/1456146034_129.pdf","publisher":"National Assembly of Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMapproximately105words;NEDfieldstudyindexedpassageapproximately155words (PDFfontunreadablebutsearchparsed);NAprimaryanswerapproximately90words datedandcriticallyattributednotendorsed. No ancientage/founderattributionorcurrentworshiprestrictionsstatedasfact.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Examine the relationship between sacred buildings and later village adaptation.","wordCount":461,"publicationHold":false,"sortOrder":77}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-golra-railway-station-objects-within-a-working-railway-setting','golra-railway-station-objects-within-a-working-railway-setting','review','{"id":"story-golra-railway-station-objects-within-a-working-railway-setting","type":"story","slug":"golra-railway-station-objects-within-a-working-railway-setting","title":"Golra Railway Station: objects within a working railway setting","summary":"Golra’s railway museum makes sense through the working systems behind its objects: communication, maintenance, staff and the movement of trains.","body":[{"type":"paragraph","text":"A railway museum can easily become a row of impressive machines. At Golra, the more revealing story is how objects worked together. A clock, a signal, a telephone and a maintenance tool belong to different tasks, but all helped make coordinated movement possible. The station setting gives those relationships a physical context that a detached display case cannot fully reproduce."},{"type":"paragraph","text":"The Department of Archaeology and Museums describes Golra’s stone-built station and its collection of railway equipment, photographs, staff clothing and everyday objects. These smaller items deserve attention alongside locomotives. They connect the railway to people who operated, maintained and travelled on it, rather than presenting technology as if it moved by itself."},{"type":"heading","level":2,"text":"Communication was infrastructure"},{"type":"paragraph","text":"In a 2026 Associated Press of Pakistan feature, museum curator Arsalan Shahid discusses exhibits including telegraph equipment, mechanical signals, maintenance tools and a control-room telephone. The report describes two galleries and dates the museum’s establishment to 2003. This is a useful distinction: the collection’s institutional history is much more recent than many of the objects it preserves."},{"type":"paragraph","text":"Communication equipment offers a particularly accessible way into railway work. A train’s movement depends not only on an engine and track but on information reaching the right people. An obsolete telephone or telegraph therefore represents more than an early version of a modern device. It belongs to a system of instructions, responsibility and coordination."},{"type":"paragraph","text":"The same approach can be applied to staff clothing and tools. A uniform can communicate a role within an organisation; a specialised tool points to work that passengers might never see. Their significance grows when labels explain use and provenance rather than merely celebrating age."},{"type":"heading","level":2,"text":"A collection inside a railway place"},{"type":"paragraph","text":"Reporting from Golra in 2024 also places the museum within the railway-station environment. That setting helps visitors connect preserved objects with platforms, tracks and the scale of transport infrastructure. It should not, however, blur the distinction between a museum exhibit and equipment still used for operations. A historic signal on display is not an instruction to a present-day train."},{"type":"paragraph","text":"This distinction has practical consequences for visitors. Railway heritage is not permission to enter tracks or operational areas for photographs. The museum and station should be experienced within the boundaries and guidance provided by their custodians, with current opening arrangements checked separately."},{"type":"paragraph","text":"A strong visit can move between scales: first the station building, then the large rolling stock, then an object small enough to fit in a hand. Each scale asks a different question. Where did people wait? How was motion produced? How did workers communicate or record a task?"},{"type":"paragraph","text":"Golra’s value lies in bringing those questions together. It is not simply a nostalgic escape into an age of steam. It is a place to understand a railway as a social and technical system, assembled from buildings, machines, documents and human work. The objects become more memorable when the connections between them are made visible."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Islamabad","Architecture"],"province":"Islamabad Capital Territory","district":"Islamabad","relatedDistrictIds":["islamabad-islamabad"],"provinceRegionIds":["islamabad"],"relatedHeritageIds":["major-doam-6310"],"relatedStoryIds":["story-colonial-railway-stations-beyond-a-single-style","story-a-railway-ticket-as-an-archive-of-movement"],"contentType":"heritage-place","seo":{"title":"Golra Railway Station: objects within a working railway setting | Virsapur Archives","description":"Golra’s railway museum makes sense through the working systems behind its objects: communication, maintenance, staff and the movement of trains.","primaryKeyword":"Golra Railway Station heritage","socialTitle":"Golra Railway Station: objects within a working railway setting","socialDescription":"Golra’s railway museum makes sense through the working systems behind its objects: communication, maintenance, staff and the movement of trains."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Golra Railway Station","url":"https://doam.gov.pk/public/sites/6310","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Golra Railway Museum: A living archive of Pakistan’s railway heritage","url":"https://www.app.com.pk/features/golra-railway-museum-a-living-archive-of-pakistans-railway-heritage/","publisher":"Associated Press of Pakistan","accessDate":"2026-10-22"},{"title":"Museum documents150-year history of Pakistan Railways, rumbling through modern times","url":"https://www.arabnews.pk/pakistan/museum-documents-150-year-history-of-pakistan-railways-rumbling-through-modern-times-2477126","publisher":"Arab News, reporting from Golra","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMapproximately100words;APP2026curatorinterviewapproximately180;ArabNews2024approximately45museumsettingonly. Erroneous1826locomotivecaptionnotused, no presenttrains/ticketsclaim. Institutionalcollectionandoperatingrailwaydistinguished.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Keep station architecture, railway collections and operational transport distinct.","wordCount":472,"publicationHold":false,"sortOrder":78}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-bazira-barikot-and-the-evidence-of-a-long-lived-town','bazira-barikot-and-the-evidence-of-a-long-lived-town','review','{"id":"story-bazira-barikot-and-the-evidence-of-a-long-lived-town","type":"story","slug":"bazira-barikot-and-the-evidence-of-a-long-lived-town","title":"Bazira-Barikot and the evidence of a long-lived town","summary":"Barikot’s excavated streets, religious buildings and acropolis show a town repeatedly reorganised rather than one ancient city preserved at a single moment.","body":[{"type":"paragraph","text":"Barikot is compelling because excavation reveals change within a town, not simply the outline of a town. Known in historical discussion as Bazira or Vajirasthana, the site combines an elevated acropolis with settlement on the adjoining plain in the Swat Valley. Streets, houses, religious structures and defensive works belong to a long sequence of occupation. They should not be imagined as if all stood together in one timeless cityscape."},{"type":"paragraph","text":"Pakistan’s 2026 Tentative List submission describes the relationship between hill, terraces and lower urban area. It also identifies craft evidence, storage and religious precincts within and around the defended settlement. This range of material makes the site useful for asking how urban life was organised, rather than focusing only on a famous encounter with an invading ruler."},{"type":"heading","level":2,"text":"Excavation changes the scale of the story"},{"type":"paragraph","text":"Ca’ Foscari University’s account of the Italian Archaeological Mission describes work at Barikot beginning in 1984. It distinguishes the lower town, investigated over many seasons, from later work on the acropolis. In its account, the lower settlement includes an Indo-Greek defensive phase, while the hill preserves later religious and defensive structures."},{"type":"paragraph","text":"The university describes a substantial temple podium associated with the Shahi period, decorated architectural remains and a later guardtower. These features make the acropolis a sequence of transformations rather than a single monument. Earlier deposits may also be disturbed or reused by later construction, so an object’s presence in fill must be interpreted through its archaeological context."},{"type":"paragraph","text":"The Tentative List submission separately highlights an early apsidal Buddhist shrine and its successive remodelling. The importance is not merely an early date. It is the opportunity to examine how a religious building developed within an urban setting, alongside other activities and structures."},{"type":"heading","level":2,"text":"A town is more than its most celebrated building"},{"type":"paragraph","text":"Pottery, tools, production debris and small objects help explain activities that monumental architecture alone cannot reveal. Their value depends on recorded provenance: where they were found, in which layer and in relation to which structures. A beautiful object without context may be harder to connect with urban life than an ordinary fragment carefully documented during excavation."},{"type":"paragraph","text":"This is why an archaeological plan needs a time dimension. Two adjacent walls can belong to different phases; an open space can acquire a building; a residential area can take on another function. Colour-coded phases or clearly dated plans can communicate these changes more honestly than a single reconstructed panorama."},{"type":"paragraph","text":"Barikot’s inclusion on Pakistan’s Tentative List in 2026 should also be described accurately. It is part of a proposal process, not inscription as a World Heritage property. The significance of the excavated evidence does not depend on confusing those statuses."},{"type":"paragraph","text":"The site offers a powerful way to think about continuity: not as an absence of change, but as repeated occupation, adaptation and rebuilding. Its streets and acropolis make a long-lived town visible precisely because archaeology can separate the different moments that now share the same ground."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Khyber Pakhtunkhwa","Architecture"],"province":"Khyber Pakhtunkhwa","district":"Swat","relatedDistrictIds":["khyber-pakhtunkhwa-swat"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-bazira"],"relatedStoryIds":["story-layers-cuts-and-fills-a-first-guide-to-stratigraphy","story-monasteries-and-towns-testing-an-economic-relationship","story-coins-in-context-a-date-is-not-the-whole-story","story-swat-beyond-a-single-buddhist-period"],"contentType":"heritage-place","seo":{"title":"Bazira-Barikot and the evidence of a long-lived town | Virsapur Archives","description":"Barikot’s excavated streets, religious buildings and acropolis show a town repeatedly reorganised rather than one ancient city preserved at a single moment.","primaryKeyword":"Bazira-Barikot heritage","socialTitle":"Bazira-Barikot and the evidence of a long-lived town","socialDescription":"Barikot’s excavated streets, religious buildings and acropolis show a town repeatedly reorganised rather than one ancient city preserved at a single moment."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Bazira-Barikot, Tentative List submission7034","url":"https://whc.unesco.org/en/tentativelists/7034/","publisher":"UNESCO World Heritage Centre, submission by Pakistan","accessDate":"2026-10-22"},{"title":"Excavations: Archaeology at Ca’ Foscari, Italian Archaeological Mission in Pakistan","url":"https://www.unive.it/pag/44639/","publisher":"Ca’ Foscari University of Venice","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"UNESCOsubmissionapproximately180words;universityexcavationaccountapproximately190. AvoidconfusingearlyapsidalShrineHwithlateTempleHdifferentnomenclature. Nofirst/oldestworldclaim. TentativeListnotinscription. Datesprojectsummarynotcurrentcampaignstatus.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Use excavation phases to explain urban continuity and change in Swat.","wordCount":469,"publicationHold":false,"sortOrder":79}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-attock-khurd-station-at-the-indus-crossing','attock-khurd-station-at-the-indus-crossing','review','{"id":"story-attock-khurd-station-at-the-indus-crossing","type":"story","slug":"attock-khurd-station-at-the-indus-crossing","title":"Attock Khurd Station at the Indus crossing","summary":"Attock Khurd Station belongs to a larger railway landscape at the Indus, where a modest stone building and a major bridge tell connected but distinct stories.","body":[{"type":"paragraph","text":"Attock Khurd Station is modest in scale compared with the engineering problem that brought the railway to this landscape. Nearby, the line crosses the Indus. The station building, bridge and river passage are connected, but each has a distinct history. Understanding that relationship gives the stone station more substance than a description of it as merely picturesque or colonial."},{"type":"paragraph","text":"The Department of Archaeology and Museums records a compact masonry building, a platform setting and a small collection of railway-related objects. Its entry places the station in the late nineteenth-century railway landscape. The same catalogue gives inconsistent exact construction years, so a precise anniversary should not be asserted from that entry alone."},{"type":"heading","level":2,"text":"A crossing built for a network"},{"type":"paragraph","text":"The National Army Museum’s record of a 1907 photograph provides a more secure account of the nearby bridge. It explains that ferries and a seasonal bridge of boats preceded the permanent girder structure. Construction took place between 1880 and 1883, with railway traffic on the upper level and other movement below. The museum also records substantial redevelopment between 1926 and 1929."},{"type":"paragraph","text":"These dates belong to the bridge, not automatically to the station. The distinction is simple but important: infrastructure develops in connected projects that do not necessarily begin or finish together. A station photograph cannot establish the date of a bridge alteration, and a bridge opening cannot by itself date every nearby building."},{"type":"paragraph","text":"The museum notes fortified ends to the crossing, making its strategic significance visible in the design. The bridge was not only a neutral line between two points. It formed part of a network through which people, goods and state power moved."},{"type":"heading","level":2,"text":"From infrastructure to heritage experience"},{"type":"paragraph","text":"An Associated Press of Pakistan report in 2024 described a tourist-train initiative from Peshawar to Attock Khurd, crossing the old bridge. That is a dated example of railway heritage being experienced through a journey. It does not establish a current timetable or guarantee that the same service is available today."},{"type":"paragraph","text":"The station itself offers another scale of understanding. A platform marks the place where moving trains and waiting passengers meet. Communication and operational objects can explain the work behind that encounter, provided they are labelled with their actual histories rather than treated as generic antiques."},{"type":"paragraph","text":"The river setting also encourages comparison between the permanent crossing and the changing technologies around it. A bridge strengthened for later traffic is not a failure of the original story; it is evidence that infrastructure must respond to new loads and demands. Its history includes adaptation as well as first construction."},{"type":"paragraph","text":"Attock Khurd is therefore best read as part of a railway landscape, not an isolated architectural jewel. The small station gives human scale to a major crossing, while the bridge explains why the location mattered. Together, they make the movement of the railway tangible—without confusing historic appreciation with permission to enter tracks, structures or operational areas beyond the public route."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Attock","relatedDistrictIds":["punjab-attock"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-10358"],"relatedStoryIds":["story-colonial-railway-stations-beyond-a-single-style"],"contentType":"heritage-place","seo":{"title":"Attock Khurd Station at the Indus crossing | Virsapur Archives","description":"Attock Khurd Station belongs to a larger railway landscape at the Indus, where a modest stone building and a major bridge tell connected but distinct stories.","primaryKeyword":"Attock Khurd Railway Station heritage","socialTitle":"Attock Khurd Station at the Indus crossing","socialDescription":"Attock Khurd Station belongs to a larger railway landscape at the Indus, where a modest stone building and a major bridge tell connected but distinct stories."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Attock Khurd Railway Station","url":"https://doam.gov.pk/public/sites/10358","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Attock Railway Bridge,13February1907, accession1985-09-17-93","url":"https://collection.nam.ac.uk/detail.php?acc=1985-09-17-93","publisher":"National Army Museum, London","accessDate":"2026-10-22"},{"title":"Railways lauded for excellent initiative for families in KP","url":"https://www.app.com.pk/domestic/railways-lauded-for-excellent-initiative-for-families-in-kp/","publisher":"Associated Press of Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMapproximately120words;NAMprimarycollectionapproximately180;APPdated2024tourreportapproximately40. DOAMinternally1880/1883stationdatesandwrongSindhlegalstatus excluded. NAMcorrectOCallaghanoriginalengineer,not1929designer. No trainbookingpromise.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Connect railway engineering, stone architecture and the river passage.","wordCount":471,"publicationHold":false,"sortOrder":80}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-noor-mahal-and-bahawalpurs-princely-architectural-choices','noor-mahal-and-bahawalpurs-princely-architectural-choices','review','{"id":"story-noor-mahal-and-bahawalpurs-princely-architectural-choices","type":"story","slug":"noor-mahal-and-bahawalpurs-princely-architectural-choices","title":"Noor Mahal and Bahawalpur’s princely architectural choices","summary":"Noor Mahal brings European architectural references into the setting of Bahawalpur’s princely court. Its details reward a closer look than the familiar palace silhouette.","body":[{"type":"paragraph","text":"Noor Mahal is one of the buildings through which Bahawalpur’s former princely state made an architectural statement. Its appeal lies partly in an unexpected combination: the outline of a European palace, domed accents, and a setting tied to a South Asian court. Looking at the building as a collection of choices is more revealing than simply describing it as luxurious. What did its designers choose to make prominent, and how did those choices frame a visitor’s approach?"},{"type":"paragraph","text":"The Bahawalpur district administration dates the laying of its foundations to 1872 and completion to 1875. It identifies the state engineer, Heennan, as its designer. Its account also records imported materials and furniture. These details place the palace within networks of design and acquisition extending beyond Bahawalpur. They do not make it an imported building: its meaning came from the particular court and city in which those materials were assembled."},{"type":"heading","level":2,"text":"A building read from the centre outward"},{"type":"paragraph","text":"The district description identifies Corinthian and Islamic architectural elements. Columns, pediments and balustrades provide one vocabulary; the domes provide another. The useful question is how these elements are composed, rather than whether the palace belongs exclusively to either tradition. A dome can reinforce a centre or mark a subsidiary part. A colonnade can turn an otherwise solid wall into a sequence of shadows. Repetition gives the eye a rhythm through which to read the whole elevation."},{"type":"paragraph","text":"For a photograph, the main axis makes the symmetry immediately legible. An oblique view asks different questions. It reveals how the front connects to the side, how deeply openings are recessed, and whether a projecting feature is a room, porch or decorative emphasis. Neither photograph replaces the other. Together they show why a building can appear almost diagrammatically ordered from one position and much more layered from another."},{"type":"heading","level":2,"text":"Additions and changing custodianship"},{"type":"paragraph","text":"The official district account records a mosque added in 1906. It also describes later army occupation and ownership, and protection as a monument in 2001. These are separate chapters, not one uninterrupted original arrangement. An architectural history should allow an addition to retain its own date and purpose rather than folding every visible element into the first construction campaign."},{"type":"paragraph","text":"Stories about a palace being built for someone who barely occupied it circulate readily because they offer an intimate explanation for an imposing place. Noor Mahal has such traditions, acknowledged as legends by the district page. They belong in a discussion of memory, not as substitutes for documented construction history."},{"type":"paragraph","text":"The strongest way to encounter Noor Mahal is therefore both close and wide: close enough to notice the meeting of column, opening and cornice, wide enough to recognise a princely architectural programme. Access arrangements should be checked separately with its custodians. The historical account explains why the palace matters; it does not establish today’s visiting hours, permissions or interior availability."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Bahawalpur","relatedDistrictIds":["punjab-bahawalpur"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-9874"],"relatedStoryIds":["story-princely-palaces-and-imported-design-vocabularies","story-bahawalpurs-princely-building-programme"],"contentType":"heritage-place","seo":{"title":"Noor Mahal and Bahawalpur’s princely architectural choices | Virsapur Archives","description":"Noor Mahal brings European architectural references into the setting of Bahawalpur’s princely court. Its details reward a closer look than the familiar palace silhouette.","primaryKeyword":"Noor Mahal heritage","socialTitle":"Noor Mahal and Bahawalpur’s princely architectural choices","socialDescription":"Noor Mahal brings European architectural references into the setting of Bahawalpur’s princely court. Its details reward a closer look than the familiar palace silhouette."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Noor Mehal","url":"https://bahawalpur.punjab.gov.pk/node/71","publisher":"District Bahawalpur, Government of Punjab","accessDate":"2026-10-22"},{"title":"Noor Mahal catalogue record","url":"https://doam.gov.pk/public/sites/9874","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"District page close-read for 1872–1875 construction, state engineer Heennan, architectural vocabulary, mosque addition and later ownership. Approximately 190 source-derived words; remainder original visual interpretation. DOAM used for identity only. Do not repeat the district page’s inconsistent patron name, modern currency conversion or wife legend as established fact.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Describe the building’s documented design vocabulary rather than inventing a court romance.","wordCount":460,"publicationHold":false,"sortOrder":81}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-ganweriwala-a-major-site-still-demanding-research','ganweriwala-a-major-site-still-demanding-research','review','{"id":"story-ganweriwala-a-major-site-still-demanding-research","type":"story","slug":"ganweriwala-a-major-site-still-demanding-research","title":"Ganweriwala: a major site still demanding research","summary":"Ganweriwala is not simply an unexplored name on an Indus map. Recent fieldwork changes the questions that can responsibly be asked about this major Cholistan settlement.","body":[{"type":"paragraph","text":"Ganweriwala belongs to the archaeological landscape of Cholistan, where a mound can be both a conspicuous landmark and a largely unread historical archive. The Department of Archaeology and Museums identifies two principal mounds and places the settlement within the Mature Harappan world. Those broad facts explain its importance without requiring a league table of the largest Indus cities. Size is a useful starting point, but it cannot by itself explain how a settlement functioned."},{"type":"paragraph","text":"The familiar description of Ganweriwala as a place awaiting excavation now needs qualification. The University of Lahore reports fieldwork in 2024, coordinated through THAAP, and describes its own involvement in documentation and scientific research. A responsible account must distinguish an older picture of limited investigation from this newer phase. It must also distinguish the beginning of a project from the completion of its analysis."},{"type":"heading","level":2,"text":"What a new excavation can change"},{"type":"paragraph","text":"The university describes audio-visual recording alongside archaeological work, and planned or developing investigations involving biological and soil evidence. Its first-season account mentions terracotta figurines and copper objects. These are preliminary institutional reports, not a published inventory of every find. Nor does the announcement establish a genetic history of Ganweriwala’s population. Research intentions are not results, however promising the techniques sound."},{"type":"paragraph","text":"The more useful questions begin with relationships. Was an object recovered from a room floor, an accumulation of rubbish or disturbed ground? Did two walls belong to the same building episode? Was a sample taken from a securely identified deposit? These questions are not obstacles to telling a compelling story. They are what let a story become more than a list of attractive objects."},{"type":"paragraph","text":"A small excavated area can produce detailed evidence without representing the entire settlement. Conversely, a broad surface survey can reveal the spread of occupation without establishing the sequence beneath each patch. Ganweriwala therefore offers an opportunity to explain archaeology at different scales: the settlement, the excavation trench, the deposit and the individual find. Each provides a different kind of answer."},{"type":"heading","level":2,"text":"Cholistan beyond the isolated mound"},{"type":"paragraph","text":"The site should also be considered in its wider landscape. A settlement map raises questions about neighbouring occupation, possible routes and access to resources. Those questions need landscape research; they cannot be answered by drawing a line between two famous places and calling it a trade route. A heritage atlas can make the connections visible while leaving their historical interpretation open to evidence."},{"type":"paragraph","text":"Ganweriwala’s interest is not diminished by unfinished research. It lies partly in the possibility of learning something genuinely new about urban life in the Indus world. For readers following the project, the most valuable future updates will be those that connect a claim to a recorded context, explain how it was analysed and say what remains uncertain. That is a richer prospect than another confident account of a city whose full history has supposedly already been recovered."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Bahawalpur","relatedDistrictIds":["punjab-bahawalpur"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-7243"],"relatedStoryIds":["story-why-an-unexcavated-mound-is-still-evidence","story-archaeological-survey-versus-excavation"],"contentType":"heritage-place","seo":{"title":"Ganweriwala: a major site still demanding research | Virsapur Archives","description":"Ganweriwala is not simply an unexplored name on an Indus map. Recent fieldwork changes the questions that can responsibly be asked about this major Cholistan settlement.","primaryKeyword":"Ganweriwala heritage","socialTitle":"Ganweriwala: a major site still demanding research","socialDescription":"Ganweriwala is not simply an unexplored name on an Indus map. Recent fieldwork changes the questions that can responsibly be asked about this major Cholistan settlement."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Ganweriwala catalogue record","url":"https://doam.gov.pk/public/sites/7243","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"UOL’s SoCA and IMBB lead the audio-visual documentation and genetic analysis of Ganweriwala excavation","url":"https://uol.edu.pk/uols-soca-and-imbb-lead-the-audio-visual-documentation-and-genetic-analysis-of-ganweriwala-excavation/","publisher":"University of Lahore","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM two-mound Mature Harappan identification, not inconsistent dimensions. UOL institutional account close-read: 2024 fieldwork, THAAP coordination, documentation and proposed laboratory work, first-season object classes. Under 190 words derived from UOL; no DNA result, exact city rank or never-excavated claim. Remaining paragraphs original explanation of research questions, not asserted discoveries.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain scale, survey and unanswered questions without promising an excavated city plan.","wordCount":462,"publicationHold":false,"sortOrder":82}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-malot-temple-and-the-language-of-carved-stone','malot-temple-and-the-language-of-carved-stone','review','{"id":"story-malot-temple-and-the-language-of-carved-stone","type":"story","slug":"malot-temple-and-the-language-of-carved-stone","title":"Malot Temple and the language of carved stone","summary":"At Malot, carved stone connects a Salt Range temple to wider architectural traditions. Its forms are more secure evidence than confident stories about a particular royal founder.","body":[{"type":"paragraph","text":"Malot’s temple is particularly rewarding at the scale of a carved opening. The eye moves from a column to a recessed bay, then upward to a trefoil form whose outline breaks into three lobes. This is not decoration placed casually on an otherwise anonymous wall. The carving helps the wall behave as a structured composition, giving depth and emphasis to a building whose upper parts no longer survive complete."},{"type":"paragraph","text":"The official archaeological catalogue describes fluted columns and recessed bays, identifying strong connections with Kashmiri architectural forms. Architectural historian Adam Hardy discusses Malot within a more precise vocabulary of shrine forms, including the interaction of Kashmiri elements and miniature Nagara temple representations. For a general reader, the important point is that a temple can carry images of architecture within its own architecture. A small carved shrine is not merely a reduced copy of the whole building."},{"type":"heading","level":2,"text":"Reading the carved surface"},{"type":"paragraph","text":"Start with the major divisions rather than the smallest motif. Where does a wall project? Where does it retreat? Which element carries the strongest shadow? Only then turn to the fluting, mouldings and smaller shrine-like forms. This order of looking helps distinguish the organising structure from the details that enrich it. It also prevents a close-up photograph from giving the impression that an entire elevation is uniformly dense."},{"type":"paragraph","text":"The missing roof is an equally important part of the encounter. A reconstructed outline may help a specialist test an architectural hypothesis, but it remains a reconstruction. The present ruin does not show the exact original silhouette. Any illustrated restoration should therefore separate surviving masonry from proposed completion, especially when a lost upper portion would substantially change the building’s proportions."},{"type":"heading","level":2,"text":"Connections are not conquests"},{"type":"paragraph","text":"Older accounts sometimes move directly from a perceived Kashmiri style to a named Kashmiri ruler. That leap deserves caution. Similar architectural features can travel through craftsmen, patrons, drawings, memory or adaptation. A stylistic relationship alone does not establish the political control of a territory. Michael Meister’s work places Malot within a regional history in which local architectural invention matters alongside wider connections."},{"type":"paragraph","text":"Dating also requires more than an attractive founding story. Comparative architectural analysis can suggest a period and a relationship to other buildings, but a precise year needs evidence of a different order. Malot is better introduced through the forms that can actually be examined than through a certainty its surviving documentation may not support."},{"type":"paragraph","text":"This approach makes the temple more, not less, interesting. Its stonework becomes an active part of the argument: evidence that can be compared, photographed and reconsidered. A thoughtful visit or image sequence should include a full elevation, the relationship between openings and wall planes, and selected close details. Those views allow readers to see why Malot has a distinctive place in the Salt Range’s architectural history without reducing it to a label borrowed from somewhere else."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Chakwal","relatedDistrictIds":["punjab-chakwal"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6535"],"relatedStoryIds":["story-reading-a-shikhara-without-guessing-a-date","story-stone-temples-of-the-salt-range-a-regional-comparison","story-temple-sculpture-removed-from-its-original-setting","story-the-salt-range-as-a-corridor-of-different-periods"],"contentType":"heritage-place","seo":{"title":"Malot Temple and the language of carved stone | Virsapur Archives","description":"At Malot, carved stone connects a Salt Range temple to wider architectural traditions. Its forms are more secure evidence than confident stories about a particular royal founder.","primaryKeyword":"Malot Temple heritage","socialTitle":"Malot Temple and the language of carved stone","socialDescription":"At Malot, carved stone connects a Salt Range temple to wider architectural traditions. Its forms are more secure evidence than confident stories about a particular royal founder."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Malot temple catalogue record","url":"https://doam.gov.pk/public/sites/6535","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Kashmiri Temples: a Typological and Aedicular Analysis","url":"https://orca.cardiff.ac.uk/130814/1/Adam%20Hardy_Kashmiri%20Temples%2C%20a%20Typological%20and%20Aedicular%20Analysis.pdf","publisher":"Adam Hardy / Cardiff University","accessDate":"2026-10-22"},{"title":"Temples of the Indus","url":"https://sanipanhwar.com/uploads/books/2024-08-29_12-18-03_5528902827c80436b7ae2755e25d27d6.pdf","publisher":"Michael W. Meister","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM observed recessed bays, fluted columns, trefoil forms and missing roof ~100 words; founder attribution withheld. Hardy Kashmiri analysis ~115 words; reserve remainder for later reuse. Meister book ~50 words for dating debate and local adaptation, not political hegemony. No absolute ruler attribution.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Read columns and arches as evidence of regional architectural connections.","wordCount":465,"publicationHold":false,"sortOrder":83}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-shahi-masjid-chiniot-architecture-through-local-craft','shahi-masjid-chiniot-architecture-through-local-craft','review','{"id":"story-shahi-masjid-chiniot-architecture-through-local-craft","type":"story","slug":"shahi-masjid-chiniot-architecture-through-local-craft","title":"Shahi Masjid, Chiniot: architecture through local craft","summary":"Chiniot’s Shahi Masjid brings brick, stone, painted surfaces and urban setting into one composition. Its craft is best understood through how these materials work together.","body":[{"type":"paragraph","text":"Chiniot’s Shahi Masjid offers an architectural story rooted in material rather than scale alone. The three-domed prayer building, courtyard and ablution tank form a recognisable mosque composition, but the details make the place particular. Brick, streaked stone and surviving traces of painted ornament ask to be read together. A photograph of the domes supplies an outline; it does not yet explain the building’s craft."},{"type":"paragraph","text":"The Chiniot district administration associates the mosque with Saadullah Khan, the minister of Shah Jahan. That connection gives the building a place in Mughal patronage, while its location gives it a place in the life of Chiniot. These are complementary histories. A monument can express elite ambition and still depend on the skills, materials and everyday setting of a regional town."},{"type":"heading","level":2,"text":"Stone where the eye and body meet"},{"type":"paragraph","text":"The archaeological catalogue identifies dark-streaked stone at entrance steps and in architectural details, including pilaster bases on the western exterior. It also records floral and geometric painted traces inside. These distinctions are worth preserving in an account. The building is not simply a stone mosque or a painted mosque. Different materials perform different roles, and some become most noticeable at points of arrival, movement or close attention."},{"type":"paragraph","text":"Steps are especially revealing because they join architecture to bodily experience. Their edges, proportions and material change the act of entering. A pilaster, by contrast, shapes the reading of a wall without necessarily creating a freestanding passage. Looking at both prevents architectural description from becoming a catalogue of ornament detached from use."},{"type":"paragraph","text":"The older Jhang district gazetteer linked the mosque’s stonework to local hills and remarked on its western pillars. It also criticised repairs made in its own period. That historical judgement should not be adopted as a verdict on the mosque today. Its value is different: it shows that questions about alteration and architectural character were already part of the building’s recorded history."},{"type":"heading","level":2,"text":"Seeing a working composition"},{"type":"paragraph","text":"A useful visual sequence begins with the relationship of courtyard and prayer hall. It then moves to the openings and supports, before examining a painted or carved detail. This progression explains where a detail belongs. Without it, a beautiful fragment can appear interchangeable with ornament from any other mosque."},{"type":"paragraph","text":"The distinction between surviving paint, later repainting and exposed substrate also matters. Colour should not be digitally intensified until it looks like an imagined original scheme. Where the date of a surface treatment is uncertain, a caption should say so. The same caution applies to a newly repaired edge photographed as though it were untouched historic work."},{"type":"paragraph","text":"Shahi Masjid’s significance lies in the meeting of an intelligible overall plan and carefully placed material richness. It invites a slower appreciation than the hunt for the most elaborate facade. Respectful observation, particularly around prayer and circulation, allows its architecture to remain what it is: a religious place with a substantial craft history, not simply a decorative backdrop."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Chiniot","relatedDistrictIds":["punjab-chiniot"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6540"],"relatedStoryIds":["story-chiniot-and-the-relationship-between-craft-and-patronage"],"contentType":"heritage-place","seo":{"title":"Shahi Masjid, Chiniot: architecture through local craft | Virsapur Archives","description":"Chiniot’s Shahi Masjid brings brick, stone, painted surfaces and urban setting into one composition. Its craft is best understood through how these materials work together.","primaryKeyword":"Shahi Masjid, Chiniot heritage","socialTitle":"Shahi Masjid, Chiniot: architecture through local craft","socialDescription":"Chiniot’s Shahi Masjid brings brick, stone, painted surfaces and urban setting into one composition. Its craft is best understood through how these materials work together."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Shahi Masjid catalogue record","url":"https://doam.gov.pk/public/sites/6540","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Our History","url":"https://chiniot.punjab.gov.pk/our-history","publisher":"District Chiniot, Government of Punjab","accessDate":"2026-10-22"},{"title":"Jhang District Gazetteer","url":"https://ignca.gov.in/Asi_data/30636.pdf","publisher":"Punjab district administration / IGNCA digital archive","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM material and plan description ~150 words; district official patron association ~35; historical gazetteer observation on local stone and restoration criticism ~90. No unsupported claim that Chiniot workers built Taj Mahal. Historical condition explicitly separated from current.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Connect the mosque’s material details with Chiniot’s building traditions.","wordCount":470,"publicationHold":false,"sortOrder":84}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-gulzar-mahal-and-the-craft-of-a-domestic-interior','gulzar-mahal-and-the-craft-of-a-domestic-interior','review','{"id":"story-gulzar-mahal-and-the-craft-of-a-domestic-interior","type":"story","slug":"gulzar-mahal-and-the-craft-of-a-domestic-interior","title":"Gulzar Mahal and the craft of a domestic interior","summary":"Chiniot’s Umar Hayat Mahal, also called Gulzar Mahal, brings the work of woodcarvers, painters and builders into an unusually expressive domestic setting.","body":[{"type":"paragraph","text":"The Gulzar Mahal discussed here is the building in Chiniot also known as Umar Hayat or Omar Hayat Mahal. It should not be confused with the palace of the same name in Bahawalpur. That distinction matters because the Chiniot building belongs to a different story: a richly worked domestic interior, a merchant family and a concentration of specialist craft."},{"type":"paragraph","text":"The archaeological catalogue connects the house with Sheikh Umar Hayat and his son Gulzar. Its account places completion in 1935 after a prolonged building campaign. More unusually, it names people associated with the work, including the woodcarvers Rahim Bakhsh and Elahi Bakhsh. It also distinguishes brickwork, stucco and fresco painting as contributions of different specialists. This is a valuable corrective to the habit of assigning every artistic decision to the owner alone."},{"type":"heading","level":2,"text":"An interior made by several hands"},{"type":"paragraph","text":"Wood carving can be appreciated as pattern, but it is also a way of shaping thresholds and surfaces. A carved panel changes under oblique light; a projecting element casts a shadow that a flat painted motif cannot. Where several materials meet, the interest lies in the junction: how one border ends, how another begins, and whether their rhythms reinforce or interrupt one another."},{"type":"paragraph","text":"These are questions to ask of photographs as well as a visit. A tightly cropped image may show extraordinary workmanship while concealing whether the object is a door, a balcony element or part of a ceiling. Including a wider view helps a reader understand the scale of the labour. It also makes the interior legible as a home with connected spaces rather than an unlimited accumulation of decorative details."},{"type":"paragraph","text":"The term palace can encourage expectations of royal occupation. In this case, the domestic and mercantile context is essential. The account of a wealthy patron commissioning skilled work does not require a royal court to make the building important. It opens another route into architectural history: the ambitions and resources of people whose homes became exceptional local landmarks."},{"type":"heading","level":2,"text":"Survival is part of the design story"},{"type":"paragraph","text":"The official catalogue records losses to upper portions and later intervention, including a library use. The Urban Unit’s regional heritage assessment also draws attention to conservation concerns. Such records should be dated when cited; they are not substitutes for a current condition survey. They do, however, explain why an interior cannot be treated as an untouched snapshot of its completion year."},{"type":"paragraph","text":"Any account should separate documented building history from dramatic family legends. Stories of death or haunting may have become attached to the house, but repetition does not verify them. The material record already offers a substantial subject without those embellishments."},{"type":"paragraph","text":"Umar Hayat Mahal is most rewarding when attention shifts from the adjective ornate to the question of making. Who carved, who painted, how were the parts joined, and what has survived? That approach restores visibility to skilled labour and gives Chiniot’s craft heritage a human scale."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Chiniot","relatedDistrictIds":["punjab-chiniot"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-10101"],"relatedStoryIds":["story-chiniot-woodcarving-learning-by-making","story-chiniot-and-the-relationship-between-craft-and-patronage"],"contentType":"heritage-place","seo":{"title":"Gulzar Mahal and the craft of a domestic interior | Virsapur Archives","description":"Chiniot’s Umar Hayat Mahal, also called Gulzar Mahal, brings the work of woodcarvers, painters and builders into an unusually expressive domestic setting.","primaryKeyword":"Gulzar Mahal, Chiniot heritage","socialTitle":"Gulzar Mahal and the craft of a domestic interior","socialDescription":"Chiniot’s Umar Hayat Mahal, also called Gulzar Mahal, brings the work of woodcarvers, painters and builders into an unusually expressive domestic setting."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Gulzar Mahal, Chiniot catalogue record","url":"https://doam.gov.pk/public/sites/10101","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Faisalabad Regional Development Plan: Archaeology and Cultural Heritage Sector","url":"https://urbanunit.gov.pk/Download/publications/Files/17/2023/Faisalabad%20Regional%20Development%20Plan%20-%20Archaeology%20%26%20Cultural%20Heritage%20Sector_compressed.pdf","publisher":"The Urban Unit, Government of Punjab","accessDate":"2026-10-22"},{"title":"Chiniot gallery: Omar Hayat Mahal","url":"https://chiniot.punjab.gov.pk/pictures_gallery","publisher":"District Chiniot, Government of Punjab","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Identity critical: this is Chiniot Umar/Omar Hayat Mahal, also Gulzar Mahal, not Bahawalpur palace. DOAM account ~190 source-derived words including named carvers and craft specialisms; Urban Unit condition/conservation ~90, not present condition claim. Exclude death/ghost anecdotes and speculative family motives.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Focus on carved timber and ceiling decoration rather than another general Chiniot overview.","wordCount":468,"publicationHold":false,"sortOrder":85}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-hafiz-hayat-reading-a-shrine-as-an-ensemble','hafiz-hayat-reading-a-shrine-as-an-ensemble','review','{"id":"story-hafiz-hayat-reading-a-shrine-as-an-ensemble","type":"story","slug":"hafiz-hayat-reading-a-shrine-as-an-ensemble","title":"Hafiz Hayat: reading a shrine as an ensemble","summary":"Hafiz Hayat’s shrine near the University of Gujrat is an ensemble of religious, residential and gathering spaces. Its significance extends beyond a single tomb.","body":[{"type":"paragraph","text":"A shrine is often introduced by the name of the person buried there. At Hafiz Hayat, near the University of Gujrat, that introduction is necessary but incomplete. The place is an ensemble: tombs, a mosque, a baradari and other buildings occupy a historic mound. The relationship between these elements offers a fuller subject than an isolated photograph of the principal grave."},{"type":"paragraph","text":"The Department of Archaeology and Museums records several tombs and water-related features as well as religious and residential structures. The architectural heritage project Naqoosh-e-Javidan describes brickwork, lime plaster and fresco painting, and provides a plan of the complex. Its interpretation associates the site with the Jahangir period. That is a broad attribution rather than a secure date for every surviving wall."},{"type":"heading","level":2,"text":"Reading across the spaces"},{"type":"paragraph","text":"The first useful act is to locate the buildings in relation to one another. Which space opens toward another? Where is movement channelled through a doorway, and where is it dispersed across open ground? A plan can reveal these relationships more clearly than a sequence of picturesque close-ups. Photographs then add the qualities that a plan cannot: height, surface, shadow and the experience of approaching."},{"type":"paragraph","text":"The baradari is important within this reading because it should not disappear behind the more immediately recognisable mosque and tomb. Likewise, a structure interpreted as a residence or sarai raises questions about the activities that accompanied religious devotion. The alternative labels should remain visible where the evidence is uncertain. Calling a room a school, guesthouse or kitchen without supporting evidence would create a false impression of a completely understood institution."},{"type":"paragraph","text":"Painted plaster also deserves attention as part of a building rather than a separate artwork. A fragment may help explain the visual character of a room, but it does not necessarily recover its entire decorative scheme. Recording its position, scale and relationship to an opening makes it more informative than an isolated image of colour."},{"type":"heading","level":2,"text":"A layered place beside a modern institution"},{"type":"paragraph","text":"The proximity of the university creates a particularly useful opportunity for architectural learning. The site can be approached through measured observation, material study and archival research, with each discipline addressing a different question. A building survey, for example, could distinguish changes in masonry without pretending that every change can immediately be dated."},{"type":"paragraph","text":"The heritage project recommends careful archaeological investigation before conservation. That sequence is important. Repair decisions can erase evidence if an uncertain arrangement is made to look confidently complete. An intervention should therefore be judged not only by how tidy the result appears, but by what historical information it retains and how clearly new work is identified."},{"type":"paragraph","text":"Hafiz Hayat rewards an account that moves between the individual building and the whole setting. The tomb gives the complex a focus; the surrounding structures explain that the place had a wider spatial life. Preserving that relationship is the difference between conserving a collection of objects and understanding an ensemble."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Gujrat","relatedDistrictIds":["punjab-gujrat"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-10113"],"relatedStoryIds":[],"contentType":"heritage-place","seo":{"title":"Hafiz Hayat: reading a shrine as an ensemble | Virsapur Archives","description":"Hafiz Hayat’s shrine near the University of Gujrat is an ensemble of religious, residential and gathering spaces. Its significance extends beyond a single tomb.","primaryKeyword":"Hafiz Muhammad Hayat Shrine Complex heritage","socialTitle":"Hafiz Hayat: reading a shrine as an ensemble","socialDescription":"Hafiz Hayat’s shrine near the University of Gujrat is an ensemble of religious, residential and gathering spaces. Its significance extends beyond a single tomb."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Hafiz Hayat catalogue record","url":"https://doam.gov.pk/public/sites/10113","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Khanqah of Hafiz Hayat","url":"https://pakheritage.org/khanqah-of-hafiz-hayat/","publisher":"Naqoosh-e-Javidan architectural heritage project","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM ensemble identity and multiple tombs/water structures ~100 words; architectural project plan and brick/lime/fresco, tentative Jahangir attribution, residential/sarai uncertainty ~140. No precise mound height, sanctified biography or construction year. Original interpretation framed as questions rather than additional undocumented functions.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain linked tombs, mosque and pavilion without turning components into duplicate places.","wordCount":470,"publicationHold":false,"sortOrder":86}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-akbari-baoli-gujrat-descending-through-architecture','akbari-baoli-gujrat-descending-through-architecture','review','{"id":"story-akbari-baoli-gujrat-descending-through-architecture","type":"story","slug":"akbari-baoli-gujrat-descending-through-architecture","title":"Akbari Baoli, Gujrat: descending through architecture","summary":"Gujrat’s Akbari Baoli makes access to water an architectural sequence of steps, arches and landings. It should be distinguished from other historic wells in the district.","body":[{"type":"paragraph","text":"The Akbari Baoli in Gujrat is an example of architecture designed around descent. Instead of approaching a monumental room above ground, a person followed steps toward water. Arches and intermediate platforms gave that movement a built framework. The result can be understood as a passage through changing levels rather than simply a well with an unusually elaborate entrance."},{"type":"paragraph","text":"The Department of Archaeology and Museums places the structure near the remains of the fort associated with Akbar. Its description identifies brick construction, descending stairs, four-centred arches and platforms at intervals. An older archaeological inventory also records the Gujrat baoli. These references establish the monument’s identity, but they should not be stretched into an exact construction history that they do not supply."},{"type":"heading","level":2,"text":"The importance of the landing"},{"type":"paragraph","text":"A landing interrupts a staircase without necessarily interrupting its direction. It creates a level place from which the next part of the descent can be seen. In an architectural reading, this matters as much as the arch overhead. The experience is sequential: stair, platform, opening and another change of level. A single view down the axis compresses these parts; an oblique photograph can show their actual depth."},{"type":"paragraph","text":"The four-centred arch is another element worth noticing carefully. Its outline is not a semicircle. The changing curvature gives it a different relationship to the space beneath and the wall around it. Describing that shape is more useful than applying the word Mughal to every visible feature and leaving the reader to imagine the rest."},{"type":"paragraph","text":"Brickwork, too, should be read at more than one scale. The overall vault or arch establishes the form, while joints and local changes can reveal repairs or disruptions. Such variations do not date themselves. They are evidence to record and compare, not an invitation to assign each patch to a different ruler."},{"type":"heading","level":2,"text":"Keeping nearby histories separate"},{"type":"paragraph","text":"The association with Akbar and a neighbouring fort has encouraged a compact historical label. Yet a date attached to the fort cannot automatically become the construction date of the baoli. The same care is needed when comparing wells elsewhere in Gujrat district. A regional grouping is helpful; combining their descriptions, photographs or restoration histories into one monument is not."},{"type":"paragraph","text":"This distinction has practical consequences for a heritage archive. The title, location and image must refer to the same structure. A photograph of another well may illustrate the general building type, but it should be labelled as a comparison rather than presented as evidence for this site."},{"type":"paragraph","text":"Akbari Baoli is interesting because it makes an everyday requirement spatially legible. Access to water required movement, and movement produced a sequence of built thresholds. Its present water condition, accessibility and structural safety need separate current verification. The architectural story can be told without implying that visitors should descend into a historic structure whose condition has not been checked."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Gujrat","relatedDistrictIds":["punjab-gujrat"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6544"],"relatedStoryIds":["story-stepwells-as-designed-journeys-to-water"],"contentType":"heritage-place","seo":{"title":"Akbari Baoli, Gujrat: descending through architecture | Virsapur Archives","description":"Gujrat’s Akbari Baoli makes access to water an architectural sequence of steps, arches and landings. It should be distinguished from other historic wells in the district.","primaryKeyword":"Akbari Baoli, Gujrat heritage","socialTitle":"Akbari Baoli, Gujrat: descending through architecture","socialDescription":"Gujrat’s Akbari Baoli makes access to water an architectural sequence of steps, arches and landings. It should be distinguished from other historic wells in the district."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Akbari Baoli, Gujrat catalogue record","url":"https://doam.gov.pk/public/sites/6544","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Revised List of Objects of Archaeological Interest in the Punjab","url":"https://upload.wikimedia.org/wikipedia/commons/1/17/Revised_list_of_objects_of_archaeological_interest_in_the_Punjab_%28IA_dli.csl.7708%29.pdf","publisher":"Archaeological Survey of India historical inventory","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM close-read brick stair, four-centred arches, platforms and location near Akbar fort. Historical inventory used for corroborating identity, not present condition. 1580 pertains fort, not asserted construction date of baoli. Original spatial analysis ~300 words; no water quality, safe access or unverified original patron.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Use the changing experience of steps and arches to explain historic water access.","wordCount":459,"publicationHold":false,"sortOrder":87}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-tilla-jogian-buildings-tanks-and-a-sacred-hill','tilla-jogian-buildings-tanks-and-a-sacred-hill','review','{"id":"story-tilla-jogian-buildings-tanks-and-a-sacred-hill","type":"story","slug":"tilla-jogian-buildings-tanks-and-a-sacred-hill","title":"Tilla Jogian: buildings, tanks and a sacred hill","summary":"Tilla Jogian combines religious buildings with a substantial water landscape. Reading tanks, steps and gathering spaces together reveals more than a hilltop silhouette.","body":[{"type":"paragraph","text":"Tilla Jogian rises in the Jhelum part of the Salt Range, but the hill is more than the setting for a group of religious buildings. Its tanks, steps and waterworks form an essential part of the place. A shrine complex on high ground has to be understood through the means of sustaining activity there, not only through the appearance of its most visible roof or dome."},{"type":"paragraph","text":"The Department of Archaeology and Museums describes a temple complex with baths and water-management features. The National Institute of Historical and Cultural Research’s study of ancient Hindu temples and shrines provides a more specific account of tanks, including a masonry tank with a formal entrance and steps descending toward its bottom. It also describes spring-fed water features. These observations make water a central architectural subject rather than a picturesque accessory."},{"type":"heading","level":2,"text":"A sacred landscape at several scales"},{"type":"paragraph","text":"The hilltop view establishes the broad setting, but it cannot explain how the complex worked. For that, the scale must change. The relationship between a tank and a nearby building, the direction of a stair and the placement of an entrance all matter. Each can suggest a question about use and movement without requiring an invented reconstruction of daily life."},{"type":"paragraph","text":"Tanks also complicate the distinction between practical and ceremonial architecture. A water structure may be necessary infrastructure while receiving a carefully composed entrance. Its functional role does not make the design less significant. Conversely, a formal gateway does not prove that every use of the water was ritual. Those interpretations need documentary or archaeological support."},{"type":"paragraph","text":"The official catalogue records a major change after Partition, when the Hindu community associated with the complex departed. This is not simply the last date in a sequence of rulers. It marks a disruption in the people and practices through which the place had been maintained. An architectural account should acknowledge that human history without claiming to speak for communities whose experiences require their own testimony."},{"type":"heading","level":2,"text":"Conservation begins with the whole ensemble"},{"type":"paragraph","text":"Punjab’s 2025–26 development programme lists a proposed, then unapproved scheme including Tilla Jogian. A budget entry is evidence of a planning intention, not proof that restoration has been completed. It should not be converted into an assurance about the site’s present condition or visitor facilities."},{"type":"paragraph","text":"For conservation, the key question is whether buildings and water features are documented together. Repairing a prominent structure while overlooking the paths of water or the ground around a tank would leave part of the site’s history unread. A measured survey could help connect these elements and distinguish surviving construction from later alteration."},{"type":"paragraph","text":"Tilla Jogian is best approached as a layered religious landscape. Its buildings invite attention, but so do the less spectacular systems that supported them. The combination gives the site its particular character. Any actual visit requires current local advice about access and conditions; an old description of a path is not a safety assessment for the present day."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Jhelum","relatedDistrictIds":["punjab-jhelum"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-10363"],"relatedStoryIds":[],"contentType":"heritage-place","seo":{"title":"Tilla Jogian: buildings, tanks and a sacred hill | Virsapur Archives","description":"Tilla Jogian combines religious buildings with a substantial water landscape. Reading tanks, steps and gathering spaces together reveals more than a hilltop silhouette.","primaryKeyword":"Tilla Jogian heritage","socialTitle":"Tilla Jogian: buildings, tanks and a sacred hill","socialDescription":"Tilla Jogian combines religious buildings with a substantial water landscape. Reading tanks, steps and gathering spaces together reveals more than a hilltop silhouette."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Tilla Jogian catalogue record","url":"https://doam.gov.pk/public/sites/10363","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Pakistan: Its Ancient Hindu Temples and Shrines","url":"https://www.nihcr.edu.pk/Downloads/PDF%20Books/Pakistan%20Its%20Ancient%20Hindu%20Temples%20and%20Shrines.pdf","publisher":"National Institute of Historical and Cultural Research","accessDate":"2026-10-22"},{"title":"Archaeology development programme 2025–26","url":"https://pnd.punjab.gov.pk/system/files/Archaeology_3.pdf","publisher":"Planning and Development Board, Punjab","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"NIHCR Tilla section close-read tank, spring-fed network, minar-flanked entrance, steps ~150 words. DOAM broad ensemble/post1947 change ~100; no unsupported 2000-year foundation or safe trail claim. P&D unapproved scheme ~35 words does not establish completed restoration. No reuse of UNESCO6118 budget.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Read the tangible complex separately from unverified legends about every visitor.","wordCount":473,"publicationHold":false,"sortOrder":88}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-amb-temples-and-their-fortified-setting','amb-temples-and-their-fortified-setting','review','{"id":"story-amb-temples-and-their-fortified-setting","type":"story","slug":"amb-temples-and-their-fortified-setting","title":"Amb Temples and their fortified setting","summary":"Amb’s surviving temples belong to a fortified architectural landscape. Their plans and elevations show why the Salt Range is a major field for studying early medieval temple design.","body":[{"type":"paragraph","text":"At Amb, the surviving temples are part of a larger fortified setting rather than isolated objects placed on a scenic hill. That relationship changes how they should be viewed. The religious buildings, defensive enclosure and terrain belong in the same frame, even where the exact history of their development remains unresolved. A close-up of a carved surface is valuable, but it cannot tell this whole story."},{"type":"paragraph","text":"The Department of Archaeology and Museums records two surviving temples of different sizes and notes an earlier account of a third. Architectural studies place Amb within the Salt Range’s early medieval temple traditions. The surviving evidence is therefore both substantial and incomplete: enough to support detailed comparison, not enough to reconstruct every building or identify every patron with confidence."},{"type":"heading","level":2,"text":"Looking beyond the facade"},{"type":"paragraph","text":"Adam Hardy’s analysis treats the larger Amb temple as an unusually informative composition. Its projecting wall divisions, upper chamber and circulation within the structure complicate the impression of a simple solid tower. Michael Meister’s work likewise draws attention to the relationship between its plan and elevation. These are not details that a frontal photograph can fully explain."},{"type":"paragraph","text":"A plan and a section would reveal different aspects of the same building. The plan shows how spaces and wall masses meet horizontally. A section can explain the movement between levels and the position of an upper room. The elevation then shows how that internal arrangement is expressed, or concealed, on the exterior. Together these views turn an impressive ruin into an intelligible architectural proposition."},{"type":"paragraph","text":"The smaller temple deserves attention on its own terms. It is not merely a scale marker beside its larger neighbour. Differences in composition may help establish relationships within the group, but such comparisons must be argued from evidence. The assumption that the larger structure is automatically later, more important or more sophisticated would be a poor substitute for architectural analysis."},{"type":"heading","level":2,"text":"Why the fortified setting matters"},{"type":"paragraph","text":"Hardy discusses Amb alongside other temple sites associated with fortified elite settlements. The relationship suggests a close connection between monumental religion and centres of authority. It does not, by itself, identify the exact ruler who commissioned a particular building. Nor does a presumed religious affiliation establish the identity of an image that has not survived."},{"type":"paragraph","text":"Dating remains an area of scholarly discussion. Relative sequences based on architectural form can be persuasive even when proposed calendar dates differ. A public account should preserve that distinction: agreement that one form belongs before another is not necessarily agreement on the precise century or decade of construction."},{"type":"paragraph","text":"Amb’s importance lies in the questions its surviving fabric makes possible. How did a temple organise vertical space? How did it address a fortified settlement? Which features were shared across the region, and which were particular to this site? These questions offer a more durable encounter than a single dramatic label. They also explain why careful recording of walls, openings and surrounding remains matters as much as preserving the best-known silhouette."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Khushab","relatedDistrictIds":["punjab-khushab"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6897"],"relatedStoryIds":["story-stone-temples-of-the-salt-range-a-regional-comparison"],"contentType":"heritage-place","seo":{"title":"Amb Temples and their fortified setting | Virsapur Archives","description":"Amb’s surviving temples belong to a fortified architectural landscape. Their plans and elevations show why the Salt Range is a major field for studying early medieval temple design.","primaryKeyword":"Amb Temples heritage","socialTitle":"Amb Temples and their fortified setting","socialDescription":"Amb’s surviving temples belong to a fortified architectural landscape. Their plans and elevations show why the Salt Range is a major field for studying early medieval temple design."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Amb Temples catalogue record","url":"https://doam.gov.pk/public/sites/6897","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"The Salt Range Temples of the Shahi Period","url":"https://shahi.pubpub.org/pub/the-salt-range-temples-of-the-shahi-period/release/1","publisher":"Adam Hardy / University of Vienna Shahi research project","accessDate":"2026-10-22"},{"title":"Temples of the Indus","url":"https://sanipanhwar.com/uploads/books/2024-08-29_12-18-03_5528902827c80436b7ae2755e25d27d6.pdf","publisher":"Michael W. Meister","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Hardy2026 chapter close-read on fort/citadel context and Amb plan/upper cell/stair ~185 words; same work olderPDF not additional allowance. DOAM two surviving temples, historical third report ~60. Meister2010 total with article82 ~160 words, here ~110. Dates debated; no definitive deity or named royal builder.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain the relationship of the temple group to its enclosing landscape and ruins.","wordCount":481,"publicationHold":false,"sortOrder":89}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-wah-bhachrans-baoli-and-its-unusual-entrance','wah-bhachrans-baoli-and-its-unusual-entrance','review','{"id":"story-wah-bhachrans-baoli-and-its-unusual-entrance","type":"story","slug":"wah-bhachrans-baoli-and-its-unusual-entrance","title":"Wah Bhachran’s baoli and its unusual entrance","summary":"Wan Bhachran’s stepwell combines a long descent with a conspicuous entrance. Historical inspection records help separate its architecture from the certainty of popular founding stories.","body":[{"type":"paragraph","text":"The stepwell at Wan Bhachran, also rendered Wah Bhachran or Wah Buchhran, is marked above ground by a conspicuous paired entrance. Its principal architectural experience, however, runs downward. A long flight of steps connects the surface with the well, passing from an open portion into covered spaces. The building therefore presents two different faces: a landmark seen from outside and a descending sequence experienced within."},{"type":"paragraph","text":"A historical inspection by archaeologist Maulvi Zafar Hasan provides an unusually useful description. He recorded a brick structure running east to west, with an initially uncovered stair followed by domed and arched roofing toward the well at the western end. His report also identified the association with Sher Shah as local tradition. That wording matters: the name by which a monument is known does not automatically constitute a documented foundation inscription."},{"type":"heading","level":2,"text":"An entrance and a changing interior"},{"type":"paragraph","text":"The official archaeological catalogue draws attention to the two minaret-like elements at the entrance. Their visual role differs from that of the underground passage. They announce a place whose most important space is otherwise concealed below the surface. This contrast is a useful subject for photography: the entrance explains where the descent begins, while a view along the stairs explains the structure’s depth."},{"type":"paragraph","text":"The transition from open sky to a roofed passage deserves particular attention. It changes the light and the sense of enclosure. An arch seen repeatedly down an axis can make the passage appear rhythmically ordered, yet the actual sequence needs to be documented rather than reconstructed from one surviving view. Missing or repaired portions are part of that record."},{"type":"paragraph","text":"Hasan’s inspection described damage near the well while considering much of the structure to be in good condition at that time. This is historical evidence, not a report on the present day. The distinction is essential when old descriptions are republished online without their original context. A century-old judgement cannot establish whether a staircase is now safe to use."},{"type":"heading","level":2,"text":"Restoration is a dated chapter"},{"type":"paragraph","text":"An Associated Press of Pakistan report in 2021 described restoration work and quoted a local archaeology official about the well. The report is evidence of a conservation initiative at that date. It does not by itself establish the finished scope, later maintenance or current access arrangements. Those require newer documentation from the responsible authorities."},{"type":"paragraph","text":"The stepwell should also be understood without claims that it is the only example of its kind. Its combination of entrance markers, descending stairs and covered sections is distinctive enough to warrant attention. Inflated uniqueness claims do not improve the architectural account."},{"type":"paragraph","text":"Wan Bhachran’s baoli makes a compelling subject because it gives a practical destination a carefully staged approach. The visitor’s route, the management of light and the visibility of the entrance all belong to its design. Keeping those observations separate from unverified founding stories allows both the architecture and the local tradition to be represented honestly."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Mianwali","relatedDistrictIds":["punjab-mianwali"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6582"],"relatedStoryIds":["story-stepwells-as-designed-journeys-to-water"],"contentType":"heritage-place","seo":{"title":"Wah Bhachran’s baoli and its unusual entrance | Virsapur Archives","description":"Wan Bhachran’s stepwell combines a long descent with a conspicuous entrance. Historical inspection records help separate its architecture from the certainty of popular founding stories.","primaryKeyword":"Sher Shah Baoli, Wah Bhachran heritage","socialTitle":"Wah Bhachran’s baoli and its unusual entrance","socialDescription":"Wan Bhachran’s stepwell combines a long descent with a conspicuous entrance. Historical inspection records help separate its architecture from the certainty of popular founding stories."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Sher Shah Suri’s Baoli at Wah Buchhran catalogue record","url":"https://doam.gov.pk/public/sites/6582","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Sher Shah’s Baoli at Wan Bhachran","url":"https://ir.nbu.ac.in/bitstreams/c173363c-2f0f-4fef-aaf9-baeff0e46af2/download","publisher":"Maulvi Zafar Hasan / Archaeological Survey of India","accessDate":"2026-10-22"},{"title":"Sher Shah Suri-era step well to be restored in Mianwali","url":"https://tribune.com.pk/story/2327242/sher-shah-suri-era-step-well-to-be-restored-in-mianwali?amp=1","publisher":"Associated Press of Pakistan via The Express Tribune","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Primary historical inspection ~175 words: east-west brick structure, open then roofed stairs, attribution explicitly local tradition. DOAM entrance minarets ~45. APP2021 ~70 for then restoration project and named archaeology official, no completion claim or questionable210ftdepth. No unverified global uniqueness.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Investigate a distinctive water structure through plan and construction details.","wordCount":468,"publicationHold":false,"sortOrder":90}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-bhong-mosque-a-modern-work-of-many-crafts','bhong-mosque-a-modern-work-of-many-crafts','review','{"id":"story-bhong-mosque-a-modern-work-of-many-crafts","type":"story","slug":"bhong-mosque-a-modern-work-of-many-crafts","title":"Bhong Mosque: a modern work of many crafts","summary":"Bhong Mosque is a twentieth-century work of collective craftsmanship. Its architectural importance lies in the inventive meeting of materials, references and skilled labour.","body":[{"type":"paragraph","text":"Bhong Mosque can look older than it is to a viewer who equates dense ornament with a distant past. It is, instead, a major twentieth-century architectural project. Work began in 1932 under Rais Ghazi Mohammad, and the Aga Khan Award for Architecture records completion in 1982. Its recognition in the 1986 award cycle makes it part of the history of modern architecture as well as the history of mosque building."},{"type":"paragraph","text":"The award record credits local master masons and craftsmen rather than a single professional architect. It describes specialists drawn from several places, including Rajasthan and Karachi. This is an important starting point. The building emerged from coordinated skills developed over decades, not simply from a finished design translated mechanically into stone and plaster."},{"type":"heading","level":2,"text":"Many materials, one demanding composition"},{"type":"paragraph","text":"The project brought together carving, inlay, tilework, mirror work, painting and calligraphy. The wider compound also employed industrially produced materials alongside traditional ones. The award account distinguishes these from the traditional materials of the mosque interior. That distinction helps explain why the building should not be reduced to either an untouched craft tradition or a modern imitation of an older style."},{"type":"paragraph","text":"A study of its ornamentation discusses the involvement of skilled workers and their apprentices. Such a working relationship makes craft transmission part of the architectural story. A finished pattern is the visible outcome; the ability to set it out, cut it, fit it and repair it is another form of knowledge. The latter is less easily photographed but equally important."},{"type":"paragraph","text":"The mosque’s intensity can initially make individual decisions hard to see. One useful approach is to follow a single material across a surface. Where does tile give way to paint? Where does reflective work concentrate light? How does a calligraphic band establish a boundary? These questions reveal organisation within abundance, rather than treating ornament as an undifferentiated covering."},{"type":"heading","level":2,"text":"Modern does not have to mean unadorned"},{"type":"paragraph","text":"Bhong challenges a narrow definition of modern architecture as necessarily plain, industrial or detached from inherited forms. Its eclectic references were part of the award discussion, not an embarrassment concealed behind the prize. The building asks whether invention can occur through combination and elaboration as well as through reduction."},{"type":"paragraph","text":"That does not require every viewer to find the composition harmonious. A considered response can acknowledge tension, density and differences of taste. Architectural significance is not the same as universal agreement about beauty. The mosque provides a particularly clear opportunity to discuss that distinction without dismissing the makers or the community for whom it was built."},{"type":"paragraph","text":"For an archive, the best presentation would pair an overall view with a small number of carefully explained details. Each detail should identify its material and position rather than simply celebrate intricacy. Bhong’s achievement becomes more legible when the work of making is visible: a sustained collaboration in which contemporary patronage, inherited skills and new materials all had a part."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Rahim Yar Khan","relatedDistrictIds":["punjab-rahim-yar-khan"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-10370"],"relatedStoryIds":["story-new-sacred-architecture-can-also-be-heritage"],"contentType":"heritage-place","seo":{"title":"Bhong Mosque: a modern work of many crafts | Virsapur Archives","description":"Bhong Mosque is a twentieth-century work of collective craftsmanship. Its architectural importance lies in the inventive meeting of materials, references and skilled labour.","primaryKeyword":"Bhong Mosque heritage","socialTitle":"Bhong Mosque: a modern work of many crafts","socialDescription":"Bhong Mosque is a twentieth-century work of collective craftsmanship. Its architectural importance lies in the inventive meeting of materials, references and skilled labour."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Bhong Mosque","url":"https://the.akdn/da/en/how-we-work/our-agencies/aga-khan-trust-culture/akaa/bhong-mosque","publisher":"Aga Khan Development Network","accessDate":"2026-10-22"},{"title":"Study of the ornamentation of Bhong Mosque for the survival of decorative patterns in Islamic architecture","url":"https://mosqpedia.org/wp-content/uploads/2024/09/CwMz38W9ymol6jyJ1QtwtWxDBoq7erKdgUSKP1NA.pdf","publisher":"Frontiers of Architectural Research","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"AKDN award page ~190 words, including1932–1982project,1986award, patron, specialists and material range. DOAM10370 repeats same text and is not independent allowance. Research paper ~60 words for master/student craft transmission. Exclude dream legend and unsupported current access.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain the award-recognised project as twentieth-century architecture, not a medieval survival.","wordCount":467,"publicationHold":false,"sortOrder":91}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-harrand-fort-and-the-southern-punjab-frontier','harrand-fort-and-the-southern-punjab-frontier','review','{"id":"story-harrand-fort-and-the-southern-punjab-frontier","type":"story","slug":"harrand-fort-and-the-southern-punjab-frontier","title":"Harrand Fort and the southern Punjab frontier","summary":"Harrand Fort’s enclosure and gateways are firmer evidence than its many origin stories. Reading the surviving structure reveals a frontier place with several historical lives.","body":[{"type":"paragraph","text":"Harrand Fort is a place where the surviving enclosure offers a more reliable beginning than the most dramatic story about its origins. The official archaeological catalogue describes an approximately circular fort built with small bricks and mud mortar, strengthened by repeated bastions and entered from the east and west. These are concrete features that can be examined, measured and compared."},{"type":"paragraph","text":"The Rajanpur district administration presents a much longer historical narrative, but also admits uncertainty about the fort’s foundation. Its page combines early legends with accounts of Sikh rebuilding and later British military use; elsewhere on the same page it labels the fort British-period. These statements do not establish a single construction date. They demonstrate why the age of a place and the date of its surviving masonry must be treated as separate questions."},{"type":"heading","level":2,"text":"Following the enclosure"},{"type":"paragraph","text":"The catalogue records sixteen bastions, with octagonal forms. Their repetition gives the perimeter a recognisable rhythm. On a plan, the relationship between bastion and connecting wall would be more informative than the number alone. It would show how the enclosure responds to its ground and how the entrances interrupt the defensive line."},{"type":"paragraph","text":"An east–west pair of gateways also raises questions about movement. Were both used in the same way? How did internal paths connect them? Which buildings stood close to the entrances? The surviving arrangement can guide those questions, but an answer requires more than assuming that every fort followed an identical military plan."},{"type":"paragraph","text":"Brick size and mortar are another part of the evidence. A change in either may indicate a repair or a separate construction episode, although it does not automatically supply a date. Recording such changes would be particularly valuable at a place with a long reputation for repeated occupation. A neat dynasty-by-dynasty narrative can otherwise hide the very evidence that might test it."},{"type":"heading","level":2,"text":"A frontier history without invented certainty"},{"type":"paragraph","text":"The district account places Harrand within a history of military posts and changing control. Its regional setting makes routes, settlement and terrain appropriate subjects for further study. Yet a line drawn on a modern map cannot prove the itinerary of an ancient army. Nor can a coin reportedly found somewhere in a fort establish the date of the entire enclosure without a documented context."},{"type":"paragraph","text":"This is not an argument for ignoring local traditions. They can reveal how people have understood Harrand and connected it to larger histories. They should be identified as traditions, with the storyteller and circumstances recorded where possible, rather than converted into anonymous facts."},{"type":"paragraph","text":"Harrand’s strongest public story brings these forms of evidence into dialogue. The walls show a built defensive place; administrative accounts record later military uses; oral narratives give it a longer remembered past. Keeping those strands distinct allows the fort to remain historically rich without claiming that its most uncertain chapters have already been solved. Current access and custodianship should be confirmed locally before any visit."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Rajanpur","relatedDistrictIds":["punjab-rajanpur"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6193"],"relatedStoryIds":["story-bastion-curtain-wall-and-parapet-reading-a-fort"],"contentType":"heritage-place","seo":{"title":"Harrand Fort and the southern Punjab frontier | Virsapur Archives","description":"Harrand Fort’s enclosure and gateways are firmer evidence than its many origin stories. Reading the surviving structure reveals a frontier place with several historical lives.","primaryKeyword":"Harrand Fort heritage","socialTitle":"Harrand Fort and the southern Punjab frontier","socialDescription":"Harrand Fort’s enclosure and gateways are firmer evidence than its many origin stories. Reading the surviving structure reveals a frontier place with several historical lives."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Harrand Fort catalogue record","url":"https://doam.gov.pk/public/sites/6193","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Important Places: Harrand Fort","url":"https://rajanpur.punjab.gov.pk/important-places","publisher":"District Rajanpur, Government of Punjab","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM form/material/gates ~140 words. District page ~170 words, explicitly internally inconsistent foundation claims; no Harappan/Alexander/Arab founder assertion. Sikh rebuilding and British military use qualified as district account; current police occupation not assured. Descriptive architectural reading original.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Connect the documented enclosure to regional terrain without simplifying disputed foundation stories.","wordCount":471,"publicationHold":false,"sortOrder":92}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-haveli-sujan-singh-the-courtyard-as-an-urban-refuge','haveli-sujan-singh-the-courtyard-as-an-urban-refuge','review','{"id":"story-haveli-sujan-singh-the-courtyard-as-an-urban-refuge","type":"story","slug":"haveli-sujan-singh-the-courtyard-as-an-urban-refuge","title":"Haveli Sujan Singh: the courtyard as an urban refuge","summary":"Sujan Singh Haveli’s courtyard and sequence of thresholds reveal an urban house beyond its ornate doorway. Its changing surroundings are part of the architectural story.","body":[{"type":"paragraph","text":"Sujan Singh Haveli is often encountered through its ornate entrance, but the doorway is only the beginning of its architecture. The house is organised around an open courtyard, reached through a sequence of entrance spaces. That movement from street to interior is central to its character. A facade photograph can celebrate workmanship while leaving the actual experience of the building almost unexplained."},{"type":"paragraph","text":"The archaeological catalogue describes a recessed entrance porch, a substantial main door and routes leading toward the courtyard. Rooms flank parts of the court, while a larger hall occupies another side. Stairs connect levels. Rather than treating these as a list of components, imagine them as a series of choices about access, visibility and the relationship between shared and enclosed spaces."},{"type":"heading","level":2,"text":"The courtyard as an organising space"},{"type":"paragraph","text":"An open court gives a house an interior centre that is not itself a room. Doors and verandas can address it, and changes in light can make its edges more prominent than its middle. In reading Sujan Singh Haveli, the useful question is not simply whether the courtyard is attractive. It is how the surrounding spaces depend on it to form a coherent domestic arrangement."},{"type":"paragraph","text":"The idea of an urban refuge is therefore architectural rather than a claim that the house was always secluded or silent. A threshold can delay a view; a change of direction can separate an entrance from a principal space. These effects can be investigated from a plan and photographs without inventing the household’s daily routines."},{"type":"paragraph","text":"The catalogue’s description also recalls a former garden setting and a more dispersed surrounding landscape. That reminder complicates the present association with dense Rawalpindi streets. A building does not retain the same urban meaning when its surroundings change. Its former relationship to open ground deserves to be studied alongside its later place in the city."},{"type":"heading","level":2,"text":"Repairing a house, not just a front"},{"type":"paragraph","text":"Reports of conservation activity provide another layer. The National College of Arts’ involvement was reported in 2015, and an official statement carried by APP in 2021 described a restoration planning exercise. The latter noted surviving doors, iron elements and tiles. These are dated accounts of work and intentions, not evidence that every proposed intervention has since been completed."},{"type":"paragraph","text":"They nevertheless identify an important principle: the building’s character rests in a combination of materials. Replacing a door, altering a roof or removing a floor finish can change more than a decorative detail. Each may affect the way rooms connect and the way the interior is understood."},{"type":"paragraph","text":"An archive presentation should therefore follow the house inward. Begin at the street, pass through the entrance, establish the courtyard and then examine selected details in their positions. That sequence makes the haveli legible as a place of habitation and changing urban circumstances. It also gives its craftsmanship a purpose beyond the production of an impressive image."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Rawalpindi","relatedDistrictIds":["punjab-rawalpindi"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-9419"],"relatedStoryIds":["story-a-courtyard-is-more-than-empty-space","story-carved-doors-and-the-architecture-of-thresholds","story-shading-before-air-conditioning","story-carved-wooden-panels-after-their-removal"],"contentType":"heritage-place","seo":{"title":"Haveli Sujan Singh: the courtyard as an urban refuge | Virsapur Archives","description":"Sujan Singh Haveli’s courtyard and sequence of thresholds reveal an urban house beyond its ornate doorway. Its changing surroundings are part of the architectural story.","primaryKeyword":"Haveli Sujan Singh heritage","socialTitle":"Haveli Sujan Singh: the courtyard as an urban refuge","socialDescription":"Sujan Singh Haveli’s courtyard and sequence of thresholds reveal an urban house beyond its ornate doorway. Its changing surroundings are part of the architectural story."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Haveli Sujan Singh catalogue record","url":"https://doam.gov.pk/public/sites/9419","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"PC-1 of Haveli Preservation, Restoration project finalised","url":"https://www.brecorder.com/news/40068808","publisher":"Associated Press of Pakistan via Business Recorder","accessDate":"2026-10-22"},{"title":"Architectural preservation: NCA students, teachers step up to save Sujan Singh Haveli","url":"https://tribune.com.pk/story/993354/architectural-preservation-nca-students-teachers-step-up-to-save-sujan-singh-haveli","publisher":"The Express Tribune","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM courtyard/entrance/rooms and formergarden setting ~180 words. APP2021 materials/planning ~70, no completion inference. Reporter2015 directNCAstatement ~50. Avoid conflicting floor/room totals and woodspecies. Interpret courtyard as spatial refuge not measured climate claim.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Read domestic scale and craftsmanship in the dense streets of Rawalpindi.","wordCount":460,"publicationHold":false,"sortOrder":93}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-khem-singh-bedi-haveli-painted-rooms-and-public-memory','khem-singh-bedi-haveli-painted-rooms-and-public-memory','review','{"id":"story-khem-singh-bedi-haveli-painted-rooms-and-public-memory","type":"story","slug":"khem-singh-bedi-haveli-painted-rooms-and-public-memory","title":"Khem Singh Bedi Haveli: painted rooms and public memory","summary":"The painted rooms of Khem Singh Bedi Haveli bring architectural space and religious imagery together. Their interpretation requires care about both subject matter and changing condition.","body":[{"type":"paragraph","text":"Khem Singh Bedi Haveli at Kallar Syedan is distinguished by painted surfaces that belong to an architectural setting, not a detached gallery collection. The archaeological catalogue records frescoes across the facade, veranda pillars and interior rooms. It also describes courtyards, projecting windows and several levels. The paintings and the spaces that hold them need to be read together."},{"type":"paragraph","text":"The house is associated with Khem Singh Bedi, the nineteenth-century Sikh religious and social figure. In a 2021 study, art historian Muhammad Asghar examined its paintings through field research and the interpretation of religious imagery. His published abstract identifies subjects connected with Sikh, Hindu and Islamic traditions. That is a more useful starting point than assuming that a house associated with one community contains only one visual tradition."},{"type":"heading","level":2,"text":"Images in domestic space"},{"type":"paragraph","text":"The position of a painting affects how it is encountered. A figure above an opening is seen differently from one at eye level, and a sequence across a veranda differs from an isolated panel in an enclosed room. An adequate record should therefore include the wall, the opening and the surrounding decoration, not only a tightly cropped figure."},{"type":"paragraph","text":"Asghar interprets the imagery in terms of cultural syncretism and the patron’s religious outlook. That interpretation should be attributed to the researcher. It is not the same as a surviving statement by the patron explaining every painted subject. The distinction allows an engaging argument to remain open to discussion rather than hardening into a claim about someone’s private intentions."},{"type":"paragraph","text":"Individual identifications also require care. Clothing, attributes, inscriptions and comparison may support a reading, but a confident social-media caption is not sufficient evidence. Where a figure has not been securely identified, describing what is visible can be more honest and more useful than naming a deity or ruler prematurely."},{"type":"heading","level":2,"text":"A record of condition has a date"},{"type":"paragraph","text":"The catalogue’s positive description of the paintings’ condition cannot be treated as a timeless assessment. The 2021 study’s abstract, by contrast, expresses concern about deterioration. These sources belong to different moments and may have assessed different aspects of the building. Their contrast is a reason to seek dated photographs and surveys, not to choose whichever description produces the more dramatic story."},{"type":"paragraph","text":"Documentation can preserve information about a painting without physically preserving the painting itself. Both are needed. A photograph records a surface at one moment; conservation requires an understanding of the material, its support and the causes of change. Digital colour correction should not be mistaken for recovery of the original scheme."},{"type":"paragraph","text":"The haveli’s public value lies partly in this encounter between image, room and historical interpretation. Its paintings offer evidence of a varied visual world, while its architecture shows how that world was placed within a home. Keeping the two together gives the site a depth that the label colourful mansion cannot convey, and makes careful, contextual recording an essential part of its future."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Rawalpindi","relatedDistrictIds":["punjab-rawalpindi"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-7053"],"relatedStoryIds":["story-a-jharokha-looking-out-and-being-seen","story-fresco-painted-plaster-and-later-repainting","story-carved-wooden-panels-after-their-removal","story-rawalpindis-merchant-neighbourhoods-and-transport-links"],"contentType":"heritage-place","seo":{"title":"Khem Singh Bedi Haveli: painted rooms and public memory | Virsapur Archives","description":"The painted rooms of Khem Singh Bedi Haveli bring architectural space and religious imagery together. Their interpretation requires care about both subject matter and changing condition.","primaryKeyword":"Khem Singh Bedi Haveli heritage","socialTitle":"Khem Singh Bedi Haveli: painted rooms and public memory","socialDescription":"The painted rooms of Khem Singh Bedi Haveli bring architectural space and religious imagery together. Their interpretation requires care about both subject matter and changing condition."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Khem Singh Bedi Haveli catalogue record","url":"https://doam.gov.pk/public/sites/7053","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Cultural syncretism: an investigative study of nineteenth century Sikh Fresco paintings in Baba Sir Khem Singh Bedi’s Haveli in Punjab/Pakistan","url":"https://www.tandfonline.com/doi/abs/10.1080/17460654.2021.1956986","publisher":"Muhammad Asghar / Early Popular Visual Culture","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Primary research abstract close-read, not full paywalled paper. ~170 words from abstract on fieldwork, three traditions and author interpretation; no specific panelidentification notread. DOAM architectural components ~100words; cataloguegoodcondition not current. Avoidclaimedpatronintent asfact; noexactroomtotals.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explore the building’s interiors and changing use without reducing them to decoration alone.","wordCount":467,"publicationHold":false,"sortOrder":94}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-historic-bhera-beyond-a-single-gate','historic-bhera-beyond-a-single-gate','review','{"id":"story-historic-bhera-beyond-a-single-gate","type":"story","slug":"historic-bhera-beyond-a-single-gate","title":"Historic Bhera beyond a single gate","summary":"Bhera’s heritage is an urban network of gates, streets and reused buildings. Understanding that network is more useful than reducing the town to one landmark or a disputed gate count.","body":[{"type":"paragraph","text":"Bhera is best understood as an urban ensemble rather than a collection of unrelated monuments. Gates, streets, houses and religious buildings form a network, and the meaning of any one element depends partly on the others. A gate photographed without the street behind it becomes a facade. Seen in its urban setting, it is also an entrance, a route marker and a point where the town’s edges have changed."},{"type":"paragraph","text":"The Department of Archaeology and Museums places Bhera on the left bank of the Jhelum and describes its association with routes toward Lahore and Multan. Its account also notes substantial rebuilding of gates in the nineteenth century. That matters because the historical foundation of a walled town cannot be used as the date of every structure visible there today."},{"type":"heading","level":2,"text":"Why counting gates is not enough"},{"type":"paragraph","text":"Different inventories do not always count the same things. The national catalogue refers to eight gates, while the Urban Unit’s 2022 heritage plan lists nine, including an Inner Lahore Gate. The difference should be explained through the scope and naming of each inventory rather than silently converted into a single unquestioned total. An inner gateway and an outer entrance may belong to different levels of an urban system."},{"type":"paragraph","text":"The Urban Unit records several nineteenth-century dates and distinguishes surviving, altered and lost gateways. Those categories are more informative than a simple checklist. A missing gate can remain significant in a street name or route, while a standing gate may contain substantial later work. Neither is adequately described by the binary labels original and destroyed."},{"type":"paragraph","text":"The same report records a former gurdwara used as an imambargah, with local testimony about its condition around Partition. This is evidence of changing use, not permission to assume that every feature belongs to the building’s first function. The account should retain the difference between the physical record and what a caretaker recalled hearing from earlier generations."},{"type":"heading","level":2,"text":"The city between the monuments"},{"type":"paragraph","text":"Urban heritage includes the connections between celebrated buildings. Street width, the alignment of an entrance and the scale of adjoining construction influence how a place is experienced. A conservation project focused only on isolated fronts can miss these relationships. Equally, a plan that treats present residents and businesses as visual clutter misses the fact that the town continues to function."},{"type":"paragraph","text":"Punjab’s 2025–26 tourism programme listed an unapproved proposal for heritage conservation in Bhera. That planning record signals institutional interest, but it does not establish a completed transformation. Any account of subsequent work needs its own dated evidence."},{"type":"paragraph","text":"For an archive or a careful walk, Bhera suggests a sequence rather than a single destination: establish an entrance, follow a street, notice a change of use and return to the wider plan. Its appeal lies in the accumulated relationships of a living town. A decisive photograph of one gate can introduce that story, but it should not be allowed to stand in for the whole."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Sargodha","relatedDistrictIds":["punjab-sargodha"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6576"],"relatedStoryIds":["story-historic-streets-are-made-of-edges","story-bhera-and-the-memory-of-a-river-town"],"contentType":"heritage-place","seo":{"title":"Historic Bhera beyond a single gate | Virsapur Archives","description":"Bhera’s heritage is an urban network of gates, streets and reused buildings. Understanding that network is more useful than reducing the town to one landmark or a disputed gate count.","primaryKeyword":"Historic Bhera heritage","socialTitle":"Historic Bhera beyond a single gate","socialDescription":"Bhera’s heritage is an urban network of gates, streets and reused buildings. Understanding that network is more useful than reducing the town to one landmark or a disputed gate count."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Site of Ancient City, Bhera catalogue record","url":"https://doam.gov.pk/public/sites/6576","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Sargodha Archaeology and Heritage Plan","url":"https://urbanunit.gov.pk/Download/publications/Files/16/2022/12%20Sargodha%20Archaeology%20and%20Heritage%20Plan.pdf","publisher":"The Urban Unit, Government of Punjab","accessDate":"2026-10-22"},{"title":"Tourism development programme2025–26","url":"https://pnd.punjab.gov.pk/system/files/Tourism_1.pdf","publisher":"Planning and Development Board, Punjab","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMroutes/location/gate reconstruction~120; UrbanUnit2022gateinventorynine includingInnerLahore and formergurdwara reuse~185; P&Dunapprovedproposal~30. Explicitcountdiscrepancy, no claimAlexanderSophytus identification proved, no1540dates for survivinggates.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Introduce the urban ensemble while reserving the Jamia Mosque for a separate architectural study.","wordCount":471,"publicationHold":false,"sortOrder":95}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-sheikhupura-fort-and-the-evidence-of-later-occupation','sheikhupura-fort-and-the-evidence-of-later-occupation','review','{"id":"story-sheikhupura-fort-and-the-evidence-of-later-occupation","type":"story","slug":"sheikhupura-fort-and-the-evidence-of-later-occupation","title":"Sheikhupura Fort and the evidence of later occupation","summary":"Sheikhupura Fort contains more than a Mughal origin story. Later residences, painted interiors and political imprisonment are integral to its architectural history.","body":[{"type":"paragraph","text":"Sheikhupura Fort is often introduced through Jahangir, but its architecture cannot be understood by stopping at a Mughal foundation. Later residential buildings, painted rooms and changes in political use are part of the site’s substance. To remove those chapters from the account would be to make the fort historically simpler than the surviving evidence allows."},{"type":"paragraph","text":"The archaeological catalogue associates the main gateway and enclosure with the Mughal period while assigning much of the internal construction to later Sikh occupation. It records a residence associated with one of Ranjit Singh’s queens and floral frescoes within an upper room. The exact attribution of that room is presented cautiously in the source and should remain so. A plausible identification is not the same as an inscribed one."},{"type":"heading","level":2,"text":"An enclosure with several interiors"},{"type":"paragraph","text":"The fort’s outer wall establishes a strong boundary, but the buildings inside were not necessarily conceived as a single project. A useful architectural reading asks how one structure meets another. Does a wall continue uninterrupted? Has an opening been blocked? Does a staircase serve one building or link several? Such relationships can help reconstruct change without assigning every surface to a dynasty on appearance alone."},{"type":"paragraph","text":"Conservation architect Saba Samee’s presentation for the Commonwealth Heritage Forum emphasises the site’s range of architectural and decorative material, including frescoes and carved timber. Her account treats the fort as a layered place spanning several periods. This is an important alternative to selecting one imagined golden moment and making all later work disappear from view."},{"type":"paragraph","text":"Painted interiors are especially vulnerable to being detached from their context in public presentation. A floral panel may be beautiful, but its position within a residence helps explain how it was experienced. The room’s scale, its openings and its relation to neighbouring spaces should accompany the detail whenever possible."},{"type":"heading","level":2,"text":"Residence and confinement"},{"type":"paragraph","text":"The fort is also associated with the imprisonment of Maharani Jind Kaur during the nineteenth-century struggle over power in Punjab. This chapter changes the emotional register of the place. A royal building could serve as a setting for residence and later as an instrument of confinement. Those uses should not be collapsed into a picturesque story of courtly life."},{"type":"paragraph","text":"It is equally important not to assign a particular surviving room as her prison without specific evidence. Historical association can be secure at the scale of a site while remaining uncertain at the scale of an individual doorway or chamber. Good interpretation explains that difference instead of manufacturing a more dramatic visitor route."},{"type":"paragraph","text":"Sheikhupura Fort therefore calls for a form of conservation that preserves evidence of change. Its value is not only in the oldest masonry or the finest painted surface, but in the relationships between them. A public account that follows those relationships can show how architecture outlives its first patrons, acquires new meanings and carries histories that are not all celebratory."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Sheikhupura","relatedDistrictIds":["punjab-sheikhupura"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-9164"],"relatedStoryIds":[],"contentType":"heritage-place","seo":{"title":"Sheikhupura Fort and the evidence of later occupation | Virsapur Archives","description":"Sheikhupura Fort contains more than a Mughal origin story. Later residences, painted interiors and political imprisonment are integral to its architectural history.","primaryKeyword":"Sheikhupura Fort heritage","socialTitle":"Sheikhupura Fort and the evidence of later occupation","socialDescription":"Sheikhupura Fort contains more than a Mughal origin story. Later residences, painted interiors and political imprisonment are integral to its architectural history."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Sheikhupura Fort catalogue record","url":"https://doam.gov.pk/public/sites/9164","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Unfolding the Story of the abandoned Sheikhupura Fort","url":"https://www.commonwealthheritage.org/unfolding-the-story-of-the-abandoned-sheikhupura-fort-from-a-haveli-and-a-royal-hunting-palace-of-the-mughals-to-a-british-prison-for-the-sikh-maharani/","publisher":"Saba Samee / Commonwealth Heritage Forum","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM~180words on enclosure, Sikhresidence, frescoes, JindKaur; CHFprofessionallecture description~140words. Do not repeat source chronological error imprisonment after1849annexation, or RanjitSinghlastSikhruler. No exactbuildingdates absent evidence; potentialroomattributionkeptqualified.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Trace changes within a Mughal enclosure rather than freezing the site in one dynasty.","wordCount":465,"publicationHold":false,"sortOrder":96}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-old-murree-brewery-identifying-the-right-ruins','the-old-murree-brewery-identifying-the-right-ruins','review','{"id":"story-the-old-murree-brewery-identifying-the-right-ruins","type":"story","slug":"the-old-murree-brewery-identifying-the-right-ruins","title":"The old Murree brewery: identifying the right ruins","summary":"The old brewery ruins at Ghora Galli are not the operating Rawalpindi brewery. Keeping those sites distinct opens a clearer history of industry, water and changing production.","body":[{"type":"paragraph","text":"The name Murree Brewery can point to a company, an operating industrial site in Rawalpindi or the remains of an earlier hill complex. These are related histories, but they are not interchangeable places. The heritage record considered here concerns the old buildings at Ghora Galli. A photograph of those ruins should not be captioned as though it showed the present Rawalpindi production facilities."},{"type":"paragraph","text":"The company’s own history dates establishment to 1860 and incorporation to the following year at Ghora Galli. Its environmental brochure describes later expansion into Rawalpindi and Quetta, and explains that water scarcity at the hill site contributed to a shift in brewing. By the 1920s, much of that work had moved to Rawalpindi, while malting continued at Ghora Galli into the 1940s before the property was sold."},{"type":"heading","level":2,"text":"Industry leaves more than a name"},{"type":"paragraph","text":"This sequence gives the ruins an industrial explanation rather than merely a colonial atmosphere. Water, production and the distribution of activities between sites matter to the story. A factory can lose one function while retaining another; the movement of brewing did not necessarily mean that every building became unused on the same day."},{"type":"paragraph","text":"The Department of Archaeology and Museums describes several buildings made with dressed stone blocks and identifies extensive use of true arches. Those features provide a starting point for architectural recording. The relationship of opening, wall and roof would help explain the organisation of the complex, although the function of each surviving room cannot be assumed from appearance alone."},{"type":"paragraph","text":"An industrial building is especially easy to misread once equipment has gone. A large opening might have served movement, ventilation or a production requirement, but identifying its purpose requires plans, photographs or physical evidence. Calling every substantial chamber a brewing hall would replace investigation with a plausible-sounding label."},{"type":"heading","level":2,"text":"A company archive and a physical site"},{"type":"paragraph","text":"Corporate history is useful primary testimony about how a company presents its development. It is not necessarily a complete account of workers, land, labour relations or the surrounding settlement. Those subjects require additional records and voices. Keeping that distinction clear prevents an industrial heritage article from becoming either advertising or an unsupported counter-history."},{"type":"paragraph","text":"The company’s continuity also differs from the continuity of a particular building. A business can retain its name while changing locations, machinery and products. The hill ruins are evidence of one phase within that longer institutional history, not a frozen image of the entire enterprise."},{"type":"paragraph","text":"For a heritage atlas, precise identification is therefore the first interpretive act. Place the old complex correctly, name the source of the industrial chronology and separate surviving fabric from activities documented elsewhere. The result is a more useful story than an evocative but vague account of an abandoned brewery. Current ownership, access and structural safety need separate confirmation; a catalogue entry does not make a ruined industrial site an open visitor attraction."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Murree","relatedDistrictIds":["punjab-murree"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6373"],"relatedStoryIds":[],"contentType":"heritage-place","seo":{"title":"The old Murree brewery: identifying the right ruins | Virsapur Archives","description":"The old brewery ruins at Ghora Galli are not the operating Rawalpindi brewery. Keeping those sites distinct opens a clearer history of industry, water and changing production.","primaryKeyword":"Historic Murree Brewery Ruins heritage","socialTitle":"The old Murree brewery: identifying the right ruins","socialDescription":"The old brewery ruins at Ghora Galli are not the operating Rawalpindi brewery. Keeping those sites distinct opens a clearer history of industry, water and changing production."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Murree Brewery historic ruins catalogue record","url":"https://doam.gov.pk/public/sites/6373","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Our History","url":"https://murreebrewery.com/our-history/","publisher":"Murree Brewery Company","accessDate":"2026-10-22"},{"title":"Environmental brochure: company history","url":"https://murreebrewery.com/oldwebsite/envirmentalbrouchar.pdf","publisher":"Murree Brewery Company","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Companyhistorysameunderlyingwork acrosspagebrochure treatedaggregate~190words:1860/61,1885–90expansion,1920swaterproblem/transfer,malting1940s,sale. DOAMstonearchesruins~90. Nounsupported1947burningclaim, noinsideaccessadvice. Noalcoholpromotion or legalguidance.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Distinguish the abandoned hill complex from the operating Rawalpindi brewery.","wordCount":459,"publicationHold":false,"sortOrder":97}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-old-badin-an-archaeological-city-beneath-a-familiar-name','old-badin-an-archaeological-city-beneath-a-familiar-name','review','{"id":"story-old-badin-an-archaeological-city-beneath-a-familiar-name","type":"story","slug":"old-badin-an-archaeological-city-beneath-a-familiar-name","title":"Old Badin: an archaeological city beneath a familiar name","summary":"The ruins of Old Badin require a careful distinction between documented survey evidence and broad claims about antiquity. Their value does not depend on assigning them a Bronze Age origin.","body":[{"type":"paragraph","text":"Old Badin is an archaeological place-name within a district whose modern name can make the distinction easy to miss. The ruins should not be treated as a synonym for the entire present town or for every ancient site in the surrounding area. Identifying the specific recorded remains is the first step toward understanding what is known about them."},{"type":"paragraph","text":"The national archaeological catalogue describes an old town in ruins and notes pressure from modern construction. It also makes a broad claim connecting the place to the Mature Harappan period. That claim needs closer scrutiny. A primary survey summary published in Pakistan Archaeology records Old Badin as site 87 and assigns it to the medieval category. The table’s key defines that category as the eighth to eighteenth centuries."},{"type":"heading","level":2,"text":"What a survey actually establishes"},{"type":"paragraph","text":"The 1972 report summarises a southern Sindh survey carried out by the Department of Archaeology. Its classification is evidence about the material or historical assessment available to that survey. It is not a complete excavation sequence. A medieval surface classification cannot prove that no earlier deposits exist, but neither can an unsupported statement of great antiquity establish those deposits."},{"type":"paragraph","text":"This distinction gives Old Badin a useful place in a public discussion of archaeology. A settlement can be important without belonging to the earliest period a writer can name. Later towns have their own histories of occupation, production, movement and change. Adding thousands of years to an account does not make it more meaningful if the evidence has not been demonstrated."},{"type":"paragraph","text":"The ruins also appear in a protected-site list reproduced in a Sindh development project’s environmental documentation. That listing confirms their recognition as a heritage concern. It does not supply a detailed plan, a foundation date or a complete account of their destruction. Different kinds of records answer different questions."},{"type":"heading","level":2,"text":"A city beneath a familiar label"},{"type":"paragraph","text":"For further research, the most productive starting points would be the original survey documentation, a clearly defined site boundary and dated records of visible remains. Where modern building has affected an archaeological area, knowing exactly what was observed and when becomes particularly important. A general photograph of Badin cannot substitute for that record."},{"type":"paragraph","text":"Historical names may also move between an older settlement and a later town. The persistence of a name is significant, but it does not guarantee that the occupied area remained unchanged. Establishing continuity requires a combination of maps, texts and material evidence rather than a shared label alone."},{"type":"paragraph","text":"Old Badin’s story is therefore still a research question, but not an empty one. There is a documented archaeological identity, a survey classification and a recognised need for protection. Presenting those securely allows future findings to refine the account. It also gives readers something valuable now: an example of how a heritage archive can distinguish evidence from repetition while taking a less celebrated urban site seriously on its own terms."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"Badin","relatedDistrictIds":["sindh-badin"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-4915"],"relatedStoryIds":[],"contentType":"heritage-place","seo":{"title":"Old Badin: an archaeological city beneath a familiar name | Virsapur Archives","description":"The ruins of Old Badin require a careful distinction between documented survey evidence and broad claims about antiquity. Their value does not depend on assigning them a Bronze Age origin.","primaryKeyword":"Old City of Badin heritage","socialTitle":"Old Badin: an archaeological city beneath a familiar name","socialDescription":"The ruins of Old Badin require a careful distinction between documented survey evidence and broad claims about antiquity. Their value does not depend on assigning them a Bronze Age origin."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Ruins of the Old City of Badin catalogue record","url":"https://doam.gov.pk/public/sites/4915","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Explorations in Southern Sind:1972 survey summary","url":"https://rafiquemughal.com/wp-content/uploads/2022/01/MUGHAL_1972_In-Pakistan-PakArch8.pdf","publisher":"Pakistan Archaeology8 / Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"AnnexL: Protected Archaeological Sites and Monuments","url":"https://documents1.worldbank.org/curated/en/919521487918832519/pdf/SFG3075-V1-REVISED-EA-P158769-Box405305B-PUBLIC-Disclosed-10-19-2017.pdf","publisher":"Government of Sindh / World Bank project documentation","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Importantchronologyconflict: DOAM4915MatureHarappan assertion withheld. Primary1972survey site87OldBadin markedM; tablelegendpp135,137 explicitlyMedieval8th–18th. ~175words from1972wholework, not proof noearlierdeposits. WorldBankannex~30identityonly; DOAM~60ruins/modernencroachment. Articleexplainsresearchlimits withoutinventedcityplan.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain the surveyed remains and avoid conflating them with the modern district town.","wordCount":466,"publicationHold":false,"sortOrder":98}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-mukhi-mahal-and-the-merchant-world-of-hyderabad','mukhi-mahal-and-the-merchant-world-of-hyderabad','review','{"id":"story-mukhi-mahal-and-the-merchant-world-of-hyderabad","type":"story","slug":"mukhi-mahal-and-the-merchant-world-of-hyderabad","title":"Mukhi Mahal and the merchant world of Hyderabad","summary":"Mukhi House links Hyderabad’s domestic architecture with a later museum role. The building and its interpretation together raise questions about family memory, urban history and public access.","body":[{"type":"paragraph","text":"Mukhi House, also known as Mukhi Mahal, brings a domestic building into the public cultural life of Hyderabad. Its later museum role does not erase its earlier identity as a family residence. Instead, the two uses sit together: visitors encounter both a historic interior and a curated account of people, objects and the city around it."},{"type":"paragraph","text":"The house was built around 1920–21 and is associated with Mukhi Jethanand and his family. The archaeological catalogue describes stone masonry, multiple entrances and a prominent domed element. Reporting on the museum’s opening in 2021 places the building near Pucca Qila and records displays relating to Hyderabad’s history. The small variation in published construction dates is better acknowledged than concealed behind an unjustifiably exact anniversary."},{"type":"heading","level":2,"text":"A house becomes an exhibit"},{"type":"paragraph","text":"In a house museum, the building is not simply a neutral container. A doorway, veranda or stair can communicate scale and hierarchy before a visitor reads a label. The route through rooms also shapes the story. An exhibition that recognises these qualities can explain domestic architecture alongside the lives represented in photographs and objects."},{"type":"paragraph","text":"But the presence of an object in a historic room does not prove that it originally stood there. Interpretation should distinguish family possessions, later acquisitions and reconstructed arrangements. This makes the museum more informative, not less atmospheric. A clearly explained display allows visitors to understand which connections are documented and which are curatorial choices."},{"type":"paragraph","text":"The wider story of Hyderabad’s prominent families likewise needs evidence beyond a handsome house. Architecture can demonstrate investment and ambition, but it cannot alone reconstruct a merchant’s business network or every aspect of household life. Those subjects call for correspondence, accounts, family testimony and other records, each identified for what it can contribute."},{"type":"heading","level":2,"text":"Interpretation is part of conservation"},{"type":"paragraph","text":"A Sindh Culture Department field report from September 2024 records instructions to provide descriptions of exhibits in Sindhi, Urdu and English. It also notes the need to coordinate major repairs to wooden structures. The two concerns belong together. A museum needs material care, but it also needs interpretation that lets different readers understand what they are seeing."},{"type":"paragraph","text":"Multilingual labels should do more than translate an object’s name. A useful label can explain its date, source and relationship to the building. Where an attribution is uncertain, that uncertainty should survive translation rather than disappearing into a confident caption in one language."},{"type":"paragraph","text":"Mukhi House’s significance lies in the possibility of connecting a particular home with a larger urban history without dissolving the family into an anonymous decorative past. Its architecture offers a setting; its records and collections provide the evidence for a fuller account. The museum’s current displays and visiting arrangements should be checked independently, but the essential interpretive task remains clear: allow the house, the family and Hyderabad to be seen in relationship, while preserving the distinctions between them."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"Hyderabad","relatedDistrictIds":["sindh-hyderabad"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5700"],"relatedStoryIds":["story-adaptive-reuse-what-should-stay-legible","story-hyderabads-forts-houses-and-changing-institutions"],"contentType":"heritage-place","seo":{"title":"Mukhi Mahal and the merchant world of Hyderabad | Virsapur Archives","description":"Mukhi House links Hyderabad’s domestic architecture with a later museum role. The building and its interpretation together raise questions about family memory, urban history and public access.","primaryKeyword":"Mukhi Mahal heritage","socialTitle":"Mukhi Mahal and the merchant world of Hyderabad","socialDescription":"Mukhi House links Hyderabad’s domestic architecture with a later museum role. The building and its interpretation together raise questions about family memory, urban history and public access."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Mukhi Mahal catalogue record","url":"https://doam.gov.pk/public/sites/5700","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Museum opened at heritage home in Hyderabad","url":"https://tribune.com.pk/story/2310574/museum-opened-at-heritage-home-in-hyderabad?amp=1","publisher":"The Express Tribune","accessDate":"2026-10-22"},{"title":"Field Visit Report: Hyderabad and Jamshoro,26September2024","url":"https://pdmi.sindhculture.gov.pk/news-and-updates/field-visit-report-cultural-heritage-and-development-initiatives-in-hyderabad-jamshoro-by-secretary-culture","publisher":"Sindh Culture Department, PDM&I Cell","accessDate":"2026-10-22"},{"title":"Mukhi House Museum, Hyderabad","url":"https://antiquities.sindhculture.gov.pk/tour/mukhi-house-museum-hyderabad/","publisher":"Directorate General of Antiquities, Sindh","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMform~60; Tribune2021opening/patron~90; official2024reporttrilinguallabels/woodrepairs~115. c1920–21datequalified sourcesdifferent. Noinventedarchitect,merchanttransactionnetwork,originalfurnitureauthenticity. Officialmuseumlistingidentityonly.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Use a domestic building to investigate urban patronage and later museum interpretation.","wordCount":460,"publicationHold":false,"sortOrder":99}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-pucca-qila-surviving-walls-in-an-inhabited-city','pucca-qila-surviving-walls-in-an-inhabited-city','review','{"id":"story-pucca-qila-surviving-walls-in-an-inhabited-city","type":"story","slug":"pucca-qila-surviving-walls-in-an-inhabited-city","title":"Pucca Qila: surviving walls in an inhabited city","summary":"Pucca Qila’s walls are the surviving edge of a much-altered Hyderabad fort. Its history includes royal residence, military reuse and the difficult work of conserving an inhabited urban place.","body":[{"type":"paragraph","text":"Pucca Qila is not simply a complete fort waiting to be viewed from outside. Its surviving walls enclose a place whose buildings, uses and urban relationships have changed substantially. The heritage record’s emphasis on the boundary wall is therefore meaningful: the perimeter is a major surviving part of a much more complicated historical interior."},{"type":"paragraph","text":"Sindh’s Directorate General of Antiquities dates the founding of Hyderabad’s fort under Mian Ghulam Shah Kalhora to 1768. It records a further phase under Mir Fateh Ali Khan Talpur from 1789, when buildings were added for the ruling household. The same account describes extensive clearance of internal structures by the British in 1857 and subsequent military uses. These episodes explain why the enclosure cannot be read as an intact snapshot of one court."},{"type":"heading","level":2,"text":"The wall as an architectural document"},{"type":"paragraph","text":"The fortification’s crest carries distinctive merlons, the raised elements along the top of a defensive wall. They give the skyline a recognisable pattern, but the wall should also be examined below that outline. Changes in masonry, repaired openings and the relationship between wall and ground can reveal a different kind of history from the silhouette alone."},{"type":"paragraph","text":"The provincial account identifies surviving domestic fabric associated with the Talpur period, including painted elements. Its older language judges the paintings’ taste, a judgement that need not be inherited by a modern archive. Description, attribution and condition are useful information; an unexplained dismissal of aesthetic quality is not a substitute for them."},{"type":"paragraph","text":"The contrast between the strong outer boundary and the loss or alteration of internal buildings is central to the visitor’s understanding. A plan showing known historical structures and present conditions would be more informative than a reconstruction presented without explanation. It would allow absence to be understood as evidence of change rather than as an invitation to fill every gap with an imagined palace."},{"type":"heading","level":2,"text":"An urban place, not an empty stage"},{"type":"paragraph","text":"Conserving a fort within a living city requires attention to more than historic masonry. The surrounding streets and the people using the area are part of the present context in which any intervention occurs. A heritage account should not treat inhabitants as anonymous obstacles or imply that an attractive photograph is a sufficient measure of success."},{"type":"paragraph","text":"Equally, present use does not remove the need to document and protect historic fabric. The useful discussion concerns specific conditions and responsibilities: what survives, what is vulnerable, who maintains it and how proposed work affects both buildings and people. Such questions require current evidence, not assumptions derived from the word encroachment."},{"type":"paragraph","text":"A Sindh Culture Department report records a visit to Pacca Qila in September 2024, confirming continuing institutional attention without establishing the outcome of every conservation issue. The fort’s public story should maintain that same distinction between attention and completion. Pucca Qila matters because its walls frame several histories at once, and because their survival asks how an inhabited city can care for the material record within it."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"Hyderabad","relatedDistrictIds":["sindh-hyderabad"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5712"],"relatedStoryIds":["story-hyderabads-forts-houses-and-changing-institutions"],"contentType":"heritage-place","seo":{"title":"Pucca Qila: surviving walls in an inhabited city | Virsapur Archives","description":"Pucca Qila’s walls are the surviving edge of a much-altered Hyderabad fort. Its history includes royal residence, military reuse and the difficult work of conserving an inhabited urban place.","primaryKeyword":"Pucca Qila Fortifications heritage","socialTitle":"Pucca Qila: surviving walls in an inhabited city","socialDescription":"Pucca Qila’s walls are the surviving edge of a much-altered Hyderabad fort. Its history includes royal residence, military reuse and the difficult work of conserving an inhabited urban place."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Pucca Fort Boundary Wall catalogue record","url":"https://doam.gov.pk/public/sites/5712","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Boundary wall of Pucca Fort Hyderabad","url":"https://antiquities.sindhculture.gov.pk/tour/boundary-wall-of-pucca-fort-hyderabad/","publisher":"Directorate General of Antiquities, Sindh","accessDate":"2026-10-22"},{"title":"Field Visit Report: Hyderabad and Jamshoro,26September2024","url":"https://pdmi.sindhculture.gov.pk/news-and-updates/field-visit-report-cultural-heritage-and-development-initiatives-in-hyderabad-jamshoro-by-secretary-culture","publisher":"Sindh Culture Department, PDM&I Cell","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"OfficialSindhpage~190words foundation1768/Talpur1789/1857clearance/militaryreuse/merlons/remainingdomesticfabric. DOAMsameunderlyingtextnotindependentallowance.2024report~15wordsvisitonly; cumulativewith98~130. Nojudgementadoptedaboutpaintinggoodtaste, no residentnumbers/eviction recommendations.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Discuss the tension between fortification, later neighbourhoods and conservation evidence.","wordCount":473,"publicationHold":false,"sortOrder":100}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-jacobabads-clock-tower-and-public-time','jacobabads-clock-tower-and-public-time','review','{"id":"story-jacobabads-clock-tower-and-public-time","type":"story","slug":"jacobabads-clock-tower-and-public-time","title":"Jacobabad’s clock tower and public time","summary":"Jacobabad’s Victoria Tower placed a clock on four public faces. Its late-nineteenth-century commemoration and civic presence offer two ways of reading the same landmark.","body":[{"type":"paragraph","text":"Jacobabad’s Victoria Tower is a monument that can be read in two directions. Its name and commemorative purpose point toward imperial history; its clock faces point outward into the town. A civic clock makes time visible beyond the possession of an individual watch. The tower therefore belongs to a history of public space as well as to the history of the ruler it commemorated."},{"type":"paragraph","text":"The Endowment Fund Trust associates it with Queen Victoria’s jubilee and dates it to 1887, while the government’s cultural-property inventory records 1888. The safest concise description is a late-nineteenth-century monument of the 1887–88 period, pending a closer reconciliation of foundation and opening records. Both accounts connect the design with Colonel S. S. Jacob. The difference of a year should not obscure the building’s identity, but it should not be silently erased either."},{"type":"heading","level":2,"text":"Four faces toward the town"},{"type":"paragraph","text":"The 2015 inventory describes clocks on four sides of the tower and records brick-and-lime construction. It also identifies internal rooms and an iron stair. This is a building with an interior arrangement, not merely a tall support for a dial. The relation between the lower accommodation, vertical circulation and clock stage is part of its architectural interest."},{"type":"paragraph","text":"Four clock faces imply several directions of address. A single dial privileges one approach; several can make the timepiece legible from different streets or positions. That observation does not prove the original traffic pattern around Jacobabad’s tower, but it suggests a productive way to study it. Historic plans and photographs could show how the surrounding routes and open space changed."},{"type":"paragraph","text":"The distinction between seeing a clock and hearing a bell is also worth preserving. A tower should not be assigned an elaborate ringing history simply because it carries a clock. The mechanism, its operation and its maintenance require their own documentation. Nor does a historical inventory establish whether the clock is functioning today."},{"type":"heading","level":2,"text":"Commemoration and everyday use"},{"type":"paragraph","text":"Imperial monuments can acquire familiar local identities without losing their original political associations. Residents may use a tower as a meeting point or direction marker even when they have little interest in the event it commemorates. Such uses would be valuable subjects for local testimony, rather than assumptions imposed by an outside account."},{"type":"paragraph","text":"The inventory also records contributions from local groups toward the tower. This complicates a simple picture of an object placed in the town by a distant authority. The funding and social circumstances deserve research alongside the designer’s name, with care not to turn participation into proof of unanimous enthusiasm."},{"type":"paragraph","text":"Victoria Tower’s value lies in these overlapping scales: the mechanism, the building, the streets and the politics of commemoration. A good archive record should let the reader move among them. The result is more revealing than treating the tower as a picturesque leftover or as a symbol whose meaning has remained unchanged since its construction."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"Jacobabad","relatedDistrictIds":["sindh-jacobabad"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-4365"],"relatedStoryIds":["story-a-minaret-is-not-a-clock-tower","story-the-clock-tower-and-the-making-of-civic-space"],"contentType":"heritage-place","seo":{"title":"Jacobabad’s clock tower and public time | Virsapur Archives","description":"Jacobabad’s Victoria Tower placed a clock on four public faces. Its late-nineteenth-century commemoration and civic presence offer two ways of reading the same landmark.","primaryKeyword":"Victoria Clock Tower, Jacobabad heritage","socialTitle":"Jacobabad’s clock tower and public time","socialDescription":"Jacobabad’s Victoria Tower placed a clock on four public faces. Its late-nineteenth-century commemoration and civic presence offer two ways of reading the same landmark."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Victoria Clock Tower catalogue record","url":"https://doam.gov.pk/public/sites/4365","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Inventory of Cultural Property in Sindh,VolumeI:Victoria Tower","url":"https://rio-heritage.org/wp-content/uploads/2016/10/volume-i-inventory-of-cultural-property-in-the-province-of-sindh.pdf","publisher":"Government of Sindh","accessDate":"2026-10-22"},{"title":"Victoria Tower,Jacobabad","url":"https://heritage.eftsindh.com/districts/jacobabad/victoria-tower.php","publisher":"Endowment Fund Trust for Preservation of the Heritage of Sindh","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM and2015inventorysameunderlyingworkaggregate~185words:1888,SSJacob,clockfaces,bricklime/interiorstairs. EFT~75words Jubilee/1887; use1887–88ratherthanresolveconstruction/openingbyguess. Nofunctioningclock/bellclaims,currentaccessorunverifiedheight.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Read a civic landmark as part of the organisation of a colonial town.","wordCount":463,"publicationHold":false,"sortOrder":101}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-sehwan-fort-beyond-the-shrine-itinerary','sehwan-fort-beyond-the-shrine-itinerary','review','{"id":"story-sehwan-fort-beyond-the-shrine-itinerary","type":"story","slug":"sehwan-fort-beyond-the-shrine-itinerary","title":"Sehwan Fort beyond the shrine itinerary","summary":"Sehwan Fort is a large archaeological mound with a research history distinct from the city’s shrine. Its layers deserve attention beyond legends of a famous conqueror.","body":[{"type":"paragraph","text":"Sehwan’s religious importance can easily overshadow another substantial part of its heritage: the fort mound. The Department of Archaeology and Museums describes an extensive mass of accumulated earth with surviving structures and surface material including pottery and brick fragments. This is an archaeological landscape, not simply a standing fortress whose rooms can be assigned familiar names."},{"type":"paragraph","text":"Its scale makes the distinction important. A mound is formed through episodes of occupation, construction, collapse and other changes. The visible upper surface is only one part of that history. The fort’s name and its association with older political traditions do not make every deposit contemporary, nor do they establish that its entire sequence has been excavated."},{"type":"heading","level":2,"text":"What excavation adds to a landmark"},{"type":"paragraph","text":"In an interview published by the French Interdisciplinary Mission in Sindh, archaeologist Monik Kervran discusses the reference sequence developed through work at Sehwan between 1996 and 2002. She distinguishes a garrison context from occupation by local people and notes the value further work in the town could have for understanding earlier urbanisation. That distinction between the excavated fort area and the wider town is fundamental."},{"type":"paragraph","text":"A trench can establish relationships between deposits in the area it exposes. It does not automatically explain the whole city. Equally, a large mound visible from a distance may conceal a sequence that only a small, carefully recorded excavation can clarify. The scale of the view and the scale of the evidence are different."},{"type":"paragraph","text":"The fort is frequently connected in popular accounts with Alexander. Such associations should be treated as historical questions rather than as a guaranteed explanation of the visible masonry. A famous name can draw attention to a place, but it should not displace the less spectacular work of dating walls and understanding deposits."},{"type":"heading","level":2,"text":"Documentation after the excavation"},{"type":"paragraph","text":"A 2023 Sindhi Studies Group newsletter describes the Endowment Fund Trust’s involvement in conservation and the recording of artefacts through its regional documentation centre. It also discusses engagement with local stakeholders. This adds an important chapter: archaeological work does not end when a field season closes. Objects, records and the physical site continue to require care."},{"type":"paragraph","text":"The relationship with the surrounding city also needs to be understood in specific terms. Changes close to an archaeological mound may affect drainage, stability or access, but those effects should be documented rather than asserted as a general complaint about urban growth. People living and working nearby are part of the context in which preservation must occur."},{"type":"paragraph","text":"Sehwan Fort offers a different encounter from the shrine itinerary, without competing with it. One concerns a highly visible religious centre; the other invites a patient reading of occupation and change through material evidence. Bringing both into a heritage atlas gives the city greater historical depth. The fort becomes not an appendix to a famous destination, but a place where the history of Sehwan itself can be investigated."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"Jamshoro","relatedDistrictIds":["sindh-jamshoro"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5180"],"relatedStoryIds":["story-sehwan-as-both-archaeological-and-sacred-city"],"contentType":"heritage-place","seo":{"title":"Sehwan Fort beyond the shrine itinerary | Virsapur Archives","description":"Sehwan Fort is a large archaeological mound with a research history distinct from the city’s shrine. Its layers deserve attention beyond legends of a famous conqueror.","primaryKeyword":"Sehwan Fort heritage","socialTitle":"Sehwan Fort beyond the shrine itinerary","socialDescription":"Sehwan Fort is a large archaeological mound with a research history distinct from the city’s shrine. Its layers deserve attention beyond legends of a famous conqueror."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Fort at Sehwan catalogue record","url":"https://doam.gov.pk/public/sites/5180","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Interview with Monik Kervran:Archaeology and the Indus valley","url":"https://sindh.hypotheses.org/files/2011/06/MIFS-Newsletter-n%C2%B02-2009.pdf","publisher":"French Interdisciplinary Mission in Sindh,Newsletter2,2009","accessDate":"2026-10-22"},{"title":"Sindhi Studies Group newsletter,2023","url":"https://sindh.hypotheses.org/files/2023/12/MIFSEN-1221.pdf","publisher":"French Interdisciplinary Mission in Sindh / Sindhi Studies Group","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMmound/materials~95words. Kervranprimaryinterviewindexedpassagesread~125words; directopenbotchallenge recorded, no inventedfullread. Newsletter2023EFTdocumentation/stakeholderwork~100. Do not assert Alexanderfounder, allstrataRai, or cityentirelyexcavated.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Distinguish the archaeological mound and fort remains from the city’s sacred centre.","wordCount":465,"publicationHold":false,"sortOrder":102}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-chottori-tombs-and-carved-funerary-architecture','chottori-tombs-and-carved-funerary-architecture','review','{"id":"story-chottori-tombs-and-carved-funerary-architecture","type":"story","slug":"chottori-tombs-and-carved-funerary-architecture","title":"Chottori Tombs and carved funerary architecture","summary":"Chottori’s tombs combine carved sandstone, brick and different forms of enclosure. The cemetery should be read through its own Talpur associations rather than borrowed descriptions of Makli.","body":[{"type":"paragraph","text":"Chottori, also written Chittori or Chitorri, is a cemetery near Mirpur Khas whose architectural character comes from a group of tombs rather than one dominant monument. Carved sandstone, brick construction, enclosed chambers and open canopies create different ways of marking a burial. The differences are essential to understanding the place; they should not be smoothed into a generic description of Sindh’s funerary architecture."},{"type":"paragraph","text":"The national catalogue associates the cemetery with Talpur figures who held positions during Kalhora rule. A field survey by the Endowment Fund Trust in July 2017 distinguishes carved stone canopies, stone tombs and brick tombs. These are complementary kinds of information: one identifies historical associations, while the other describes visible building types."},{"type":"heading","level":2,"text":"A canopy is not a closed room"},{"type":"paragraph","text":"An open canopy frames a grave while allowing views through it. An enclosed tomb chamber creates a different relationship between inside and outside. This elementary distinction is more useful than treating every domed structure as the same architectural form. The supports, openings and roof must be considered together."},{"type":"paragraph","text":"An architectural account published by the Talpur heritage project draws attention to carved yellow sandstone on pillars, entrances, ceilings and tombstones. It describes domed compositions and relationships between supporting elements. These observations invite a close reading of how carving works across a structure: whether it emphasises an edge, fills a field or changes at the point where one element meets another."},{"type":"paragraph","text":"The cemetery’s visual richness does not mean every grave can be identified securely. An inscription may supply a name or date, while an uninscribed structure may depend on another form of attribution. Those kinds of evidence should be distinguished. A family association for the cemetery as a whole cannot identify every individual burial within it."},{"type":"heading","level":2,"text":"Comparison without substitution"},{"type":"paragraph","text":"Makli is a useful point of comparison for readers familiar with Sindh’s more celebrated funerary sites, but its history cannot simply be transferred to Chottori. Similar materials or architectural devices do not establish identical dates, patrons or workshop connections. Comparison should begin with a specific feature and then ask what the evidence supports."},{"type":"paragraph","text":"Published inventories also vary in the number of structures they count. A survey may count standing monuments differently from an earlier list that includes ruined or subsidiary elements. Until the inventories are reconciled on a plan, the difference should remain visible rather than becoming an unexplained claim that the cemetery contains one exact total."},{"type":"paragraph","text":"Chottori’s significance is strongest when the individual monuments remain part of a larger burial landscape. Their spacing, orientation and relation to neighbouring graves matter alongside the carved details. A respectful photographic record would include both the ensemble and selected close views, while avoiding contact with vulnerable surfaces. The result can reveal a distinctive regional history of commemoration without turning the cemetery into a catalogue of interchangeable ornamental objects."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"Mirpur Khas","relatedDistrictIds":["sindh-mirpur-khas"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5231"],"relatedStoryIds":[],"contentType":"heritage-place","seo":{"title":"Chottori Tombs and carved funerary architecture | Virsapur Archives","description":"Chottori’s tombs combine carved sandstone, brick and different forms of enclosure. The cemetery should be read through its own Talpur associations rather than borrowed descriptions of Makli.","primaryKeyword":"Chottori Tombs heritage","socialTitle":"Chottori Tombs and carved funerary architecture","socialDescription":"Chottori’s tombs combine carved sandstone, brick and different forms of enclosure. The cemetery should be read through its own Talpur associations rather than borrowed descriptions of Makli."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Chottori Tombs catalogue record","url":"https://doam.gov.pk/public/sites/5231","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Chittori Graveyard,Mirpurkhas:CDC-EFT survey26July2017","url":"https://heritage.eftsindh.com/districts/mirpurkhas/chittori-graveyard.php","publisher":"Endowment Fund Trust for Preservation of the Heritage of Sindh","accessDate":"2026-10-22"},{"title":"Talpurs and their tomb architecture","url":"https://talpur.org/talpurs-and-their-tomb-architecture/","publisher":"The Royal Talpurs and the Heritage of Sindh","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMTalpurKalhoraspecificburials~65. EFTprimarysurveytypes~90. Talpurheritagearchitecturalessay~160forcarvedsandstone/forms, attributionasaccount notverifiedgenealogy. Do not harmonisecontradictory12/14counts orcollapseall18c; noborrowedMakli chronology.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Compare documented tomb forms without applying Makli’s history indiscriminately.","wordCount":454,"publicationHold":false,"sortOrder":103}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-brahmanabad-mansurah-names-ruins-and-historical-identification','brahmanabad-mansurah-names-ruins-and-historical-identification','review','{"id":"story-brahmanabad-mansurah-names-ruins-and-historical-identification","type":"story","slug":"brahmanabad-mansurah-names-ruins-and-historical-identification","title":"Brahmanabad–Mansurah: names, ruins and historical identification","summary":"Mansurah’s archaeological remains raise questions about urban naming and early Islamic government. The mosque and adjoining monumental complex offer a firmer focus than a seamless story built from names alone.","body":[{"type":"paragraph","text":"The paired name Brahmanabad–Mansurah is convenient for locating an archaeological site, but it should not conceal the questions behind historical identification. Place-names in texts, names used by local communities and labels attached to excavated remains do not always coincide neatly. A heritage account has to explain which evidence it is using rather than presenting a familiar compound name as a complete solution."},{"type":"paragraph","text":"The Department of Archaeology and Museums describes Mansurah as a fortified early Islamic city founded in the eighth century. It records extensive remains, brick construction and a major mosque. These features give the site a substantial archaeological identity. They do not, on their own, settle every relationship between Mansurah and the other urban names appearing in the region’s history."},{"type":"heading","level":2,"text":"A mosque and the architecture of government"},{"type":"paragraph","text":"A Sapienza University research project takes a particularly focused approach: the relationship between the congregational mosque and a complex interpreted as the dar al-imara, or government palace. The project asks how their arrangement developed and what it can reveal about early Islamic political architecture. Its proposal stresses that published archaeological documentation is incomplete and requires critical reassessment."},{"type":"paragraph","text":"That qualification is important. A research aim should not be reported as an achieved result. The project’s interest lies precisely in testing a chronological and architectural interpretation through the surviving evidence. It offers a more productive question than simply declaring that the city followed a standard plan shared by all early Islamic capitals."},{"type":"paragraph","text":"The relationship of two major buildings can be studied in several ways. Their entrances may face one another, their walls may meet, or a later construction may interrupt an earlier arrangement. These physical relationships can help distinguish stages of development. They must then be compared with written evidence, rather than making the buildings illustrate a narrative decided in advance."},{"type":"heading","level":2,"text":"The value of excavation records"},{"type":"paragraph","text":"Sindh’s Exploration and Excavation Branch makes available a catalogue entry for a 1977 Mansura field diary by Irfan Hussain Siddiqi. The existence of such records reminds readers that an archaeological site is also an archive of observations. Field notes, plans and photographs can preserve relationships that are no longer obvious on the ground."},{"type":"paragraph","text":"A brief online description is therefore not the final form of the evidence. Re-examining earlier records can change an interpretation without a new discovery being made. It may also reveal where a confident statement rests on an uncertain identification or an incompletely published trench."},{"type":"paragraph","text":"Mansurah is compelling because it connects urban archaeology with the material expression of government and religion. Its value does not depend on smoothing all names and dates into a single uninterrupted story. A careful account can identify the fortified city, introduce the mosque and adjoining complex, and explain why their sequence remains a serious research problem. That gives readers a clearer understanding of both the importance of the ruins and the work still required to interpret them."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"Sanghar","relatedDistrictIds":["sindh-sanghar"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5267"],"relatedStoryIds":["story-historic-archaeology-after-the-ancient-period"],"contentType":"heritage-place","seo":{"title":"Brahmanabad–Mansurah: names, ruins and historical identification | Virsapur Archives","description":"Mansurah’s archaeological remains raise questions about urban naming and early Islamic government. The mosque and adjoining monumental complex offer a firmer focus than a seamless story built from names alone.","primaryKeyword":"Brahmanabad–Mansurah heritage","socialTitle":"Brahmanabad–Mansurah: names, ruins and historical identification","socialDescription":"Mansurah’s archaeological remains raise questions about urban naming and early Islamic government. The mosque and adjoining monumental complex offer a firmer focus than a seamless story built from names alone."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Brahmanabad(Mansurah) catalogue record","url":"https://doam.gov.pk/public/sites/5267","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Mansura:investigation of the congregational mosque–dar al-imara complex","url":"https://research.uniroma1.it/en/mansura-capitale-abbaside-del-sindh-indagine-del-complesso-monumentale-moschea-congregazionale-dar","publisher":"Sapienza University of Rome","accessDate":"2026-10-22"},{"title":"Mansura field diary162(14),1977","url":"https://ene.sindhculture.gov.pk/field-diaries/mansura-sindh-162-14-irfan-hussain-siddiqi-1977/","publisher":"Exploration and Excavation Branch,Sindh Culture Department","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM~100words fortifiedbrickcity8c; no13cendpointcertitude. Sapienza2019researchproposal~185words aims notachievedresults, mosque/palaceassociation andpatchydocumentation. Official1977diarymetadata~35words existenceonly, not full diary excavationclaims. Namesequivalenceexplicitnotproven; noZenodouploadinstitutionclaim.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain the relationship between archaeological evidence and the debated naming of an urban site.","wordCount":464,"publicationHold":false,"sortOrder":104}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-chanhudaro-an-archaeological-story-of-making','chanhudaro-an-archaeological-story-of-making','review','{"id":"story-chanhudaro-an-archaeological-story-of-making","type":"story","slug":"chanhudaro-an-archaeological-story-of-making","title":"Chanhudaro: an archaeological story of making","summary":"Chanhudaro’s workshop evidence reveals the Indus world through making. Bead drills, unfinished pieces and furnace-related fragments can be more informative than a finished ornament alone.","body":[{"type":"paragraph","text":"Chanhudaro offers a way into Indus archaeology through the evidence of work. Its importance is not confined to complete objects that might look impressive in a display case. Drills, unfinished beads, fragments and production debris can reveal decisions that disappear in the polished result. A workshop is understood through the relationship among those materials, not through one attractive find."},{"type":"paragraph","text":"The national archaeological catalogue records Ernest Mackay’s excavations of 1935–36 and identifies brick houses, drainage and a range of objects. The settlement therefore provides a domestic and urban setting for craft activity. It should not be imagined as an isolated factory detached from the other requirements of life."},{"type":"heading","level":2,"text":"The hole inside the bead"},{"type":"paragraph","text":"Jonathan Mark Kenoyer’s study of Indus trade and technology discusses a Chanhudaro carnelian-bead workshop with numerous drills and drill-making waste. The specialised material known as ernestite takes its name from Mackay. The association of tools, waste and products allows a more detailed account of manufacture than the finished beads could provide alone."},{"type":"paragraph","text":"A bead’s perforation is particularly informative because it records a process that the outer polish may obscure. Tool marks can be compared, and unfinished pieces can show where work stopped. Such evidence supports questions about technique and specialisation. It does not automatically tell us the name, status or personal identity of the person who used the drill."},{"type":"paragraph","text":"Production debris also changes the meaning of an apparently insignificant fragment. An abandoned blank may reveal an intermediate stage; a broken tool may indicate a technical problem. Their value lies in context and association. Removing them as souvenirs would destroy precisely the relationships that make them useful."},{"type":"heading","level":2,"text":"Reconsidering an old interpretation"},{"type":"paragraph","text":"Massimo Vidale’s 1987 study returned to another class of Chanhudaro material: the so-called paste plaques and cylinders. Mackay had connected them with raw material for faience. Vidale proposed instead that some were components of small high-temperature installations, potentially associated with glazing processes. He treated traces of glaze and the composition of the fragments as evidence for testing that interpretation."},{"type":"paragraph","text":"The study also discusses an unfinished steatite bead fragment that helps illuminate a manufacturing sequence. This is a good example of how renewed examination can extract information from material already known. Archaeological progress is not limited to opening a fresh trench; it can come from asking a better question of an old collection."},{"type":"paragraph","text":"Chanhudaro’s workshop evidence should therefore be presented as an argument, not a romantic scene of craftsmen reconstructed without qualification. What was found together? Which stage of production does it represent? Which interpretation remains a proposal? Those questions allow readers to follow the reasoning."},{"type":"paragraph","text":"The result is a human-scale view of the Indus world. Large cities and long-distance exchange remain important, but here they can be approached through the precision of a hole, the shape of a blank and the discarded remains of making. Small things become evidence of substantial technical knowledge."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"Shaheed Benazir Abad","relatedDistrictIds":["sindh-shaheed-benazir-abad"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-6464"],"relatedStoryIds":["story-seals-and-sealings-an-archaeological-distinction","story-households-and-workshops-in-an-indus-settlement","story-a-carnelian-beads-long-production-journey","story-shell-bangles-and-connections-to-the-coast"],"contentType":"heritage-place","seo":{"title":"Chanhudaro: an archaeological story of making | Virsapur Archives","description":"Chanhudaro’s workshop evidence reveals the Indus world through making. Bead drills, unfinished pieces and furnace-related fragments can be more informative than a finished ornament alone.","primaryKeyword":"Chanhudaro heritage","socialTitle":"Chanhudaro: an archaeological story of making","socialDescription":"Chanhudaro’s workshop evidence reveals the Indus world through making. Bead drills, unfinished pieces and furnace-related fragments can be more informative than a finished ornament alone."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Chanhu Jo Daro catalogue record","url":"https://doam.gov.pk/public/sites/6464","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Trade and Technology of the Indus Valley:New Insights from Harappa,Pakistan","url":"https://www.harappa.com/sites/default/files/pdf/kenoyer1997Trade%20and%20Technology%20of%20The%20Indus%20Valley.pdf","publisher":"Jonathan Mark Kenoyer / World Archaeology","accessDate":"2026-10-22"},{"title":"The Paste Plaques and Cylinders of Chanhudaro:A Descriptive Report","url":"https://www.harappa.com/sites/default/files/pdf/5_Annali_1987_47_%28f1%29_M._Vidale.pdf","publisher":"Massimo Vidale / Annali47.1,1987","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM1935–36/bricksdrains~65. Kenoyer1997~150wordsdrillsworkshopandmanufacture, no speculative migrantsecrecy claim. Vidale1987~185includingreinterpretationofplaques aspossiblefurnacecomponents notcertainty, steatiteblanksequence. Distinct from earlierInduscraftrawmaterialarticles.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Use published workshop evidence to explain craft production at a smaller Indus settlement.","wordCount":466,"publicationHold":false,"sortOrder":105}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-thul-mir-rukan-and-the-survival-of-a-brick-monument','thul-mir-rukan-and-the-survival-of-a-brick-monument','review','{"id":"story-thul-mir-rukan-and-the-survival-of-a-brick-monument","type":"story","slug":"thul-mir-rukan-and-the-survival-of-a-brick-monument","title":"Thul Mir Rukan and the survival of a brick monument","summary":"Thul Mir Rukan’s brick tiers and Buddhist associations make it an important monument in Sindh. Its visible form is clearer evidence than a precise founding story.","body":[{"type":"paragraph","text":"Thul Mir Rukan presents a substantial brick mass whose tapering profile is immediately recognisable. The monument is identified by Sindh’s antiquities department as a Buddhist stupa. Its form, decorative divisions and reported archaeological finds provide a firmer introduction than the stories sometimes used to explain why a nameless ruler supposedly built it."},{"type":"paragraph","text":"The provincial description records a square base supporting a cylindrical structure arranged in diminishing tiers. Moulded bands separate the levels, and pilasters divide their faces. It also notes terracotta Buddhist images recovered through excavation. The national catalogue, meanwhile, offers only a tentative chronological attribution. A precise foundation year or securely named patron is not established by these summaries."},{"type":"heading","level":2,"text":"Brickwork that shapes the whole"},{"type":"paragraph","text":"The monument’s interest lies partly in how brick creates an architectural profile at several scales. From a distance, the eye registers the reduction in diameter toward the top. Closer views reveal the bands and vertical divisions that organise the surface. These two readings belong together: the detail makes sense as part of a mass, and the mass gains character through its details."},{"type":"paragraph","text":"Pilasters are especially useful to notice because they can make a curved surface appear rhythmically divided. A moulding, by contrast, carries the eye horizontally. Their meeting produces a structured exterior rather than a plain cylinder. A photograph taken only from far away loses that articulation; one taken only close up loses the overall form that gives it meaning."},{"type":"paragraph","text":"The surviving outline should not be confused with a complete original state. Where an upper portion is lost or altered, a reconstruction must identify its basis. An apparently plausible dome can change the whole visual interpretation of a monument. It should not be added to an illustration without making the distinction between surviving and proposed form clear."},{"type":"heading","level":2,"text":"Buddhist identity and chronological caution"},{"type":"paragraph","text":"The reported terracotta images support the discussion of a Buddhist context, but objects need their own records. Their find locations, subjects and later custody matter. A photograph of a Buddhist plaque from another site cannot be used as an unlabelled substitute for an object from Thul Mir Rukan, however similar it appears."},{"type":"paragraph","text":"Likewise, a broad historical attribution should not be sharpened into certainty through repetition. Architectural comparison may help establish a period, while a securely recorded inscription or excavated sequence would answer different questions. The available public summaries do not provide all of those forms of evidence."},{"type":"paragraph","text":"Thul Mir Rukan deserves attention as a substantial surviving brick monument in its own regional setting. A strong public record would pair an overall view with details of tiers, mouldings and surface condition, and connect those images to dated documentation. That approach makes the stupa’s architecture accessible while leaving room for further scholarship. Its value does not depend on a dramatic legend or on claiming that every part of its history is already known."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"Shaheed Benazir Abad","relatedDistrictIds":["sindh-shaheed-benazir-abad"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5094"],"relatedStoryIds":["story-what-is-a-stupa-for"],"contentType":"heritage-place","seo":{"title":"Thul Mir Rukan and the survival of a brick monument | Virsapur Archives","description":"Thul Mir Rukan’s brick tiers and Buddhist associations make it an important monument in Sindh. Its visible form is clearer evidence than a precise founding story.","primaryKeyword":"Thul Mir Rukan heritage","socialTitle":"Thul Mir Rukan and the survival of a brick monument","socialDescription":"Thul Mir Rukan’s brick tiers and Buddhist associations make it an important monument in Sindh. Its visible form is clearer evidence than a precise founding story."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Thulh Mir Rukan catalogue record","url":"https://doam.gov.pk/public/sites/5094","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Buddhist Stupa,Village Thul Mir Rukan,Shaheed Benazir Abad","url":"https://antiquities.sindhculture.gov.pk/tour/buddhist-stupa-village-thul-mir-rukan-shaheed-benazir-abad/","publisher":"Directorate General of Antiquities,Sindh","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Officialprovincialform/tier/pilaster/imagesaccount~185words; DOAMchronologytentativeandlegend~60. Differentmeasurementsnotused. NoexactRai5–6cdateassertion, noinventedrelicchamber or assignunprovenmuseumobjects. Remainingoriginalformalreading andmethoddiscussion.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Examine the stupa’s fabric and conservation needs with cautious chronology.","wordCount":458,"publicationHold":false,"sortOrder":106}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-frere-hall-civic-space-and-changing-cultural-uses','frere-hall-civic-space-and-changing-cultural-uses','review','{"id":"story-frere-hall-civic-space-and-changing-cultural-uses","type":"story","slug":"frere-hall-civic-space-and-changing-cultural-uses","title":"Frere Hall: civic space and changing cultural uses","summary":"Frere Hall’s colonial architecture has acquired later cultural meanings. Its hall, verandas and association with Sadequain should be understood as related but distinct chapters.","body":[{"type":"paragraph","text":"Frere Hall is a colonial-era building whose later cultural associations are now inseparable from the way Karachi encounters it. Its name commemorates a British administrator, while its interior is also associated with the work of Sadequain. These histories do not cancel one another. They show how a civic building can acquire meanings beyond the political circumstances of its construction."},{"type":"paragraph","text":"The archaeological catalogue places the building in the 1860s and describes a Venetian Gothic vocabulary, yellowish limestone from Jungshahi, verandas and an upper hall approached by a double staircase. These features establish more than a recognisable skyline. They organise the movement from grounds to porch, from porch to stair and from stair to a substantial interior space."},{"type":"heading","level":2,"text":"A hall is more than its tower"},{"type":"paragraph","text":"The tower makes Frere Hall identifiable at a distance, but the verandas give the building another scale. Repeated openings and columns create a boundary that is neither an entirely solid wall nor an entirely open edge. The depth of that boundary is important to the architecture. It is best shown by a view that allows the reader to see both the outer line and the space behind it."},{"type":"paragraph","text":"The upper hall shifts attention again. A large interior is experienced through proportion, light and the relationship between floor, wall and ceiling. Its value cannot be conveyed by a close-up of one ornamental feature. A sequence of views should explain how a visitor arrives in the room before concentrating on its artistic contents."},{"type":"paragraph","text":"Sadequain’s ceiling work introduces a different visual language into this historic setting. The artist’s foundation identifies Frere Hall among the public locations of his murals and describes the ceiling work as unfinished at his death. That incompletion is part of its history, not a defect to be silently corrected in a retouched photograph or an imaginative reconstruction."},{"type":"heading","level":2,"text":"Later culture in an inherited building"},{"type":"paragraph","text":"The SADEQUAIN Foundation records establishing a gallery initiative at Frere Hall in February 2017. That institutional statement concerns a particular phase of activity; it should not be mistaken for the first moment the building was associated with the artist. Separating those dates allows the longer cultural history to remain legible."},{"type":"paragraph","text":"The relationship between art and architecture also raises a practical interpretive question. Is a ceiling painting shown as an independent composition, or is its position within the hall explained? Both kinds of image can be useful, but they answer different questions. The setting affects how the work is seen and how a viewer moves beneath it."},{"type":"paragraph","text":"Frere Hall’s significance therefore lies in more than colonial style or a famous artist’s name. It is a place where an inherited civic structure has accommodated subsequent cultural expression. A thoughtful account can acknowledge the original commemoration, explain the building’s spatial character and give later work its own history. Current exhibitions and access should be checked separately rather than assumed from an undated description of a public landmark."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"South Karachi","relatedDistrictIds":["sindh-south-karachi"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5858"],"relatedStoryIds":["story-karachis-civic-buildings-before-the-megacity"],"contentType":"heritage-place","seo":{"title":"Frere Hall: civic space and changing cultural uses | Virsapur Archives","description":"Frere Hall’s colonial architecture has acquired later cultural meanings. Its hall, verandas and association with Sadequain should be understood as related but distinct chapters.","primaryKeyword":"Frere Hall heritage","socialTitle":"Frere Hall: civic space and changing cultural uses","socialDescription":"Frere Hall’s colonial architecture has acquired later cultural meanings. Its hall, verandas and association with Sadequain should be understood as related but distinct chapters."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Frere Hall catalogue record","url":"https://doam.gov.pk/public/sites/5858","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"About SADEQUAIN Foundation","url":"https://sadequainfoundation.com/about-sadequain-foundation/","publisher":"SADEQUAIN Foundation","accessDate":"2026-10-22"},{"title":"Trails of the Lost Art of SADEQUAIN","url":"https://sadequainfoundation.com/product/trails-of-the-lost-art-of-sadequain/","publisher":"SADEQUAIN Foundation","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMstyle/material/upperhallstair~175words; no1863ascompletion claim. Foundationabout~35gallery2017, Trails~85ceilingunfinished but noassertionstolenworks. Distinguish2017foundationgalleryinitiative from originalgallerynaming; avoidunsupportedbookmarketcurrenthours.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Connect the hall, grounds and later artistic associations while checking dates and access separately.","wordCount":468,"publicationHold":false,"sortOrder":107}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-empress-market-a-building-still-used-as-a-market','empress-market-a-building-still-used-as-a-market','review','{"id":"story-empress-market-a-building-still-used-as-a-market","type":"story","slug":"empress-market-a-building-still-used-as-a-market","title":"Empress Market: a building still used as a market","summary":"Empress Market’s architecture and commercial life cannot be separated. Its history includes the building’s colonial origins and the consequences of later changes around it.","body":[{"type":"paragraph","text":"Empress Market is a historic building whose purpose is still legible in its name. It was designed for exchange, not simply for viewing. Its architectural form, the movement of goods and the people who buy and sell are therefore parts of the same subject. An account that removes commercial life from the picture risks preserving an image of the market while losing the reason it exists."},{"type":"paragraph","text":"The archaeological catalogue dates construction to 1884–89 and records four galleries arranged to accommodate shops and stalls. The Endowment Fund Trust identifies the market within Saddar and describes a varied range of everyday commodities. These details establish a working urban place rather than a monument whose only legitimate activity is tourism."},{"type":"heading","level":2,"text":"Architecture organised around transactions"},{"type":"paragraph","text":"A market building has to be understood through circulation. People need to enter, compare goods, stop, turn and leave, while sellers need access to their stock. The relationship between passage and stall is therefore as important as the outer facade. A photograph taken when a space is empty may clarify its geometry but conceal the patterns through which it normally operates."},{"type":"paragraph","text":"This does not mean congestion or poor maintenance should be romanticised. It means that improvements should be assessed against the building’s function as well as its appearance. A clearer view of a wall is only one possible outcome of an intervention; the effects on livelihoods, access and the distribution of activity also matter."},{"type":"paragraph","text":"The Urban Resource Centre documented demolitions around Empress Market in 2018 as part of a wider record of evictions in Karachi. Its material makes it impossible to describe the subsequent visual opening around the building as a purely aesthetic event. Shops and working spaces were involved, and the people affected belong in the history of the place."},{"type":"heading","level":2,"text":"A different way to imagine conservation"},{"type":"paragraph","text":"Urban planner Arif Hasan proposed ways to combine restoration with continued commerce, including organised low-height shops, improved pedestrian connections and space for changing public activities. These were proposals, not a description of a completed scheme. Their importance lies in demonstrating that the debate was not limited to a choice between an obscured building and an empty foreground."},{"type":"paragraph","text":"For a heritage archive, the same principle applies to images. Before-and-after photographs should be dated and explained. A newly exposed facade can appear to tell a simple story of rescue, while the caption may need to explain a much more complicated social change. The photograph is evidence of appearance, not a complete evaluation of policy."},{"type":"paragraph","text":"Empress Market’s heritage value is strongest when its architecture and its use remain in conversation. The colonial building, the later commercial networks and the disputes over public space are all parts of its history. Understanding them together does not require agreement on every intervention. It requires asking a fuller question: how can a market retain significant fabric while continuing to serve the city that gives it life?"}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"South Karachi","relatedDistrictIds":["sindh-south-karachi"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5846"],"relatedStoryIds":["story-a-markets-building-and-a-markets-life","story-karachis-civic-buildings-before-the-megacity"],"contentType":"heritage-place","seo":{"title":"Empress Market: a building still used as a market | Virsapur Archives","description":"Empress Market’s architecture and commercial life cannot be separated. Its history includes the building’s colonial origins and the consequences of later changes around it.","primaryKeyword":"Empress Market heritage","socialTitle":"Empress Market: a building still used as a market","socialDescription":"Empress Market’s architecture and commercial life cannot be separated. Its history includes the building’s colonial origins and the consequences of later changes around it."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Empress Market catalogue record","url":"https://doam.gov.pk/public/sites/5846","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Empress Market,Karachi","url":"https://heritage.eftsindh.com/districts/karachi/empress-market.php","publisher":"Endowment Fund Trust for Preservation of the Heritage of Sindh","accessDate":"2026-10-22"},{"title":"List of Recent Eviction2018:Demolished Units and Markets","url":"https://urckarachi.org/wp-content/uploads/2020/07/List-of-Recent-Eviction-2018-Demolished-Markets.pdf","publisher":"Urban Resource Centre,Karachi","accessDate":"2026-10-22"},{"title":"News articles by Arif Hasan:Empress Market proposals","url":"https://urckarachi.org/wp-content/uploads/2020/07/News-aricles-by-Arif-Hasan-2.pdf","publisher":"Arif Hasan / Urban Resource Centre","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMdates/galleries~65; EFTcommerce~40; URCprimaryinventory~55 (numberomitted toavoidcountscopeissue); ArifHasanplan~150 originaladvocacyproposalnotimplementedfact. Nolegaladvice or claimstallsallillegal; noDawnsyndicationreusewithoutbudget.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explore architectural form alongside living commercial use without romanticising displacement.","wordCount":467,"publicationHold":false,"sortOrder":108}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-sindh-madrassatul-islam-and-an-institutional-cityscape','sindh-madrassatul-islam-and-an-institutional-cityscape','review','{"id":"story-sindh-madrassatul-islam-and-an-institutional-cityscape","type":"story","slug":"sindh-madrassatul-islam-and-an-institutional-cityscape","title":"Sindh Madrassatul Islam and an institutional cityscape","summary":"Sindh Madrassatul Islam connects educational reform with Karachi’s historic architecture. Its institutional continuity is as important as its association with celebrated alumni.","body":[{"type":"paragraph","text":"Sindh Madrassatul Islam is an institution whose architectural setting and educational history have developed together. Founded in 1885 under the leadership of Hassanally Effendi, it began as a school and later became a college and university. Its historic buildings are therefore not simply memorials to an activity that has vanished. They belong to a continuing educational institution within Karachi’s commercial centre."},{"type":"paragraph","text":"The university’s own history presents the foundation as part of a programme of educational reform. It notes that, although the institution was established principally to advance Muslim education, students and teachers from other communities also participated. This is a more substantial starting point than reducing the school’s history to a list of famous names."},{"type":"heading","level":2,"text":"Buildings and institutional ambition"},{"type":"paragraph","text":"The university identifies James Strachan with the design of its historic buildings. An Endowment Fund Trust account distinguishes the shapes of arches at different levels and records a former principal’s residence with an inscription dating it to 1898. These details suggest a campus assembled through particular building campaigns and gifts, not one completed object with a single date."},{"type":"paragraph","text":"The distinction between an institution’s founding and the completion of a building is especially important here. September 1885 marks the opening of the school. It should not automatically become the date of every wall, veranda or later addition on the campus. A building history needs its own evidence, including inscriptions, plans and records of construction."},{"type":"paragraph","text":"The architectural setting also provides a way to think about educational life. Openings, circulation and the relationship between enclosed rooms and shared grounds influence how an institution is experienced. These qualities can be studied without inventing a precise account of a nineteenth-century pupil’s daily movements."},{"type":"heading","level":2,"text":"A famous association and a larger community"},{"type":"paragraph","text":"Muhammad Ali Jinnah studied at the institution from 1887 to 1892, according to its official history, and returned to inaugurate its college phase in 1943. This association is important, but it should not make other students and teachers disappear. The school’s broader significance lies in the sustained provision of education and in the changing society from which its community was drawn."},{"type":"paragraph","text":"The university’s annual report records the transition to university status in 2012. Such institutional changes do not necessarily erase earlier architectural meanings. They can create new pressures and possibilities: adapting rooms, accommodating more users and deciding how historic fabric remains useful without losing its character."},{"type":"paragraph","text":"An archive presentation should therefore hold several scales together. A plaque can identify a donor and a date; a building can reveal an architectural programme; institutional records can explain the evolution from school to university. None replaces the others. Seen this way, Sindh Madrassatul Islam is more than a picturesque campus or a famous alumnus’s backdrop. It is an enduring piece of Karachi’s educational cityscape, where historical buildings continue to participate in a living institutional purpose."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"South Karachi","relatedDistrictIds":["sindh-south-karachi"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-6234"],"relatedStoryIds":["story-school-and-library-buildings-as-heritage","story-karachis-civic-buildings-before-the-megacity"],"contentType":"heritage-place","seo":{"title":"Sindh Madrassatul Islam and an institutional cityscape | Virsapur Archives","description":"Sindh Madrassatul Islam connects educational reform with Karachi’s historic architecture. Its institutional continuity is as important as its association with celebrated alumni.","primaryKeyword":"Sindh Madrassatul Islam heritage","socialTitle":"Sindh Madrassatul Islam and an institutional cityscape","socialDescription":"Sindh Madrassatul Islam connects educational reform with Karachi’s historic architecture. Its institutional continuity is as important as its association with celebrated alumni."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"History of SMI","url":"https://www.smiu.edu.pk/about/history","publisher":"Sindh Madressatul Islam University","accessDate":"2026-10-22"},{"title":"About SMIU","url":"https://www.smiu.edu.pk/about/about","publisher":"Sindh Madressatul Islam University","accessDate":"2026-10-22"},{"title":"Sindh Madressahtul Islam College,Karachi","url":"https://heritage.eftsindh.com/districts/karachi/sindh-madressahtul-islam-college.php","publisher":"Endowment Fund Trust for Preservation of the Heritage of Sindh","accessDate":"2026-10-22"},{"title":"Annual Report2022–23","url":"https://aqec.smiu.edu.pk/PDF/Annual-Report-SMIU-2022-23.pdf","publisher":"Sindh Madressatul Islam University","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Officialhistory~170words foundation/openadmissions/Jinnah1887–92and1943; aboutpage~45Strachanlocation; annualreport~20university2012; EFT~140archesand1898principalresidenceplaque (derivedfromKarachiLegacieswork reservebudgetiflater). Do notconflate1885institutionfoundationwithexactmainbuildingcompletion, no1892matriculationassertion.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Read the historic educational building and its role within Karachi’s urban history.","wordCount":455,"publicationHold":false,"sortOrder":109}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-mir-masums-minaret-seeing-and-being-seen-in-sukkur','mir-masums-minaret-seeing-and-being-seen-in-sukkur','review','{"id":"story-mir-masums-minaret-seeing-and-being-seen-in-sukkur","type":"story","slug":"mir-masums-minaret-seeing-and-being-seen-in-sukkur","title":"Mir Masum’s minaret: seeing and being seen in Sukkur","summary":"Mir Masum’s tower in Sukkur belongs to an ensemble of inscriptions and family tombs. Its vertical presence is only one part of a monument shaped by writing and remembrance.","body":[{"type":"paragraph","text":"Mir Masum’s minaret is a conspicuous vertical landmark in Sukkur, but it should not be separated from the tombs and inscriptions around it. The tower, stone canopies and family graves form an ensemble. Its story concerns visibility from a distance and close reading at the scale of a carved surface: two very different ways in which a monument addresses its audience."},{"type":"paragraph","text":"Sindh’s antiquities department records the beginning of construction in 1595 and associates the work with Mir Muhammad Masum, the scholar, poet and author of the Tarikh-e-Masumi. The tower is built of brick and contains an internal staircase leading upward beneath a domed summit. These facts establish its architectural and personal associations without requiring an uncertain account of its original practical purpose."},{"type":"heading","level":2,"text":"Seeing and being seen"},{"type":"paragraph","text":"A tower can be prominent in a city even for people who never climb it. Its height and outline help establish a point of reference. Looking outward from its upper level is a different experience from seeing it from surrounding streets. Both are relevant to its visual role, but neither by itself proves that it was designed as a military lookout or signalling station."},{"type":"paragraph","text":"The published official descriptions give differing dimensions. An archive should therefore resist using a precise height as a headline unless a reliable measurement has been established. The building’s significance does not depend on winning a comparison with other towers. Its relationship to Sukkur and to the adjacent funerary structures is more informative than an uncertain superlative."},{"type":"paragraph","text":"Photographs can explain that relationship by moving from a wider view to the base and then toward the canopies. If the tower is shown alone in every image, readers may never realise that the site includes a substantial ensemble of remembrance."},{"type":"heading","level":2,"text":"Writing in the monument"},{"type":"paragraph","text":"The provincial description records Persian inscriptions and Quranic verses on the canopies, with the graves of Mir Masum and members of his family beneath them. It also notes an inscribed slab at the tower entrance. Writing is therefore part of the material experience of the place, not merely a source consulted elsewhere to supply dates."},{"type":"paragraph","text":"An inscription needs more than a decorative photograph. Its position, script, transcription and translation should be connected, and damaged or uncertain readings should be marked. A date on a grave may identify a death rather than the completion of the surrounding canopy. A date at an entrance may refer to a particular building event. Treating every inscription as interchangeable chronological evidence would miss these distinctions."},{"type":"paragraph","text":"Mir Masum’s role as a historical writer makes this especially resonant. The site can be approached through texts about the past and through texts physically placed within architecture. The resulting encounter is richer than a climb to a viewpoint. It joins urban visibility, personal commemoration and the durable act of writing on stone, while leaving current access and safety arrangements to be verified separately with the site’s custodians."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"Sukkur","relatedDistrictIds":["sindh-sukkur"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5135"],"relatedStoryIds":["story-a-minaret-is-not-a-clock-tower","story-sukkur-and-rohri-as-linked-river-settlements","story-the-sukkur-crossing-as-a-landscape-of-engineering"],"contentType":"heritage-place","seo":{"title":"Mir Masum’s minaret: seeing and being seen in Sukkur | Virsapur Archives","description":"Mir Masum’s tower in Sukkur belongs to an ensemble of inscriptions and family tombs. Its vertical presence is only one part of a monument shaped by writing and remembrance.","primaryKeyword":"Mir Masum’s Minaret and Tomb heritage","socialTitle":"Mir Masum’s minaret: seeing and being seen in Sukkur","socialDescription":"Mir Masum’s tower in Sukkur belongs to an ensemble of inscriptions and family tombs. Its vertical presence is only one part of a monument shaped by writing and remembrance."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Mir Masum’s Minar and Tomb catalogue record","url":"https://doam.gov.pk/public/sites/5135","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Mir Masum’s Minar,Sukkur","url":"https://antiquities.sindhculture.gov.pk/tour/mir-masums-minar-sukkur/","publisher":"Directorate General of Antiquities,Sindh","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Sharedofficialunderlyingtextaggregate~195words:1595start,writerTarikhMasumi,brick/internalstair/domedsummit,stonecanopies/Persianinscriptions/familygraves. Avoidconflicting30/34mheight,19.5/28circumference, erroneous1618AHcompletion andDOAMAkbar1606title. Originalanalysisvisibility/writing notclaimprovenwatchtowerfunction.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Connect tower, tomb and visibility as a documented monument ensemble.","wordCount":471,"publicationHold":false,"sortOrder":110}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-lansdowne-bridge-and-the-challenge-of-spanning-the-indus','lansdowne-bridge-and-the-challenge-of-spanning-the-indus','review','{"id":"story-lansdowne-bridge-and-the-challenge-of-spanning-the-indus","type":"story","slug":"lansdowne-bridge-and-the-challenge-of-spanning-the-indus","title":"Lansdowne Bridge and the challenge of spanning the Indus","summary":"The Lansdowne Bridge joined a railway across a difficult Indus channel. Construction photographs make its engineering decisions and labour visible alongside its celebrated outline.","body":[{"type":"paragraph","text":"The Lansdowne Bridge is often recognised before its engineering problem is understood. Its projecting steelwork has become a familiar outline above the Indus at Sukkur and Rohri. But its unusual shape was not an arbitrary flourish. It answered a particular difficulty: how to carry a railway across a channel where supports could not be placed as easily as on the other side of Bukkur island."},{"type":"paragraph","text":"Cambridge University Library’s account of its construction album explains that the smaller Sukkur channel had rock suitable for piers, while the Rohri channel presented a deep silty bed. Alexander Meadows Rendel’s design used great anchored cantilevers reaching out from the banks, with a suspended section between them. The bridge’s silhouette makes that structural decision unusually legible."},{"type":"heading","level":2,"text":"A crossing assembled in stages"},{"type":"paragraph","text":"The library’s album contains sixty-five photographs associated with engineer F. E. Robertson. They record work between 1885 and 1889, including the progressive assembly of the metal structure. Westwood, Baillie and Company manufactured the ironwork in London. Looking through construction photographs changes the experience of the finished bridge: pieces that appear continuous today emerge as components lifted, positioned and joined."},{"type":"paragraph","text":"An opening photograph in the British Library dates the inauguration to 25 March 1889. That documented occasion is preferable to treating every year attached to the bridge in a modern catalogue as its opening date. Design, fabrication, assembly and inauguration are different events. A reliable account should make room for each without forcing them into one anniversary."},{"type":"heading","level":2,"text":"Engineering has a labour history"},{"type":"paragraph","text":"The Cambridge account records six worker deaths during construction. It also identifies the sub-overseer Faiz Mahomed in the album. Such details interrupt a history told solely through the designer and the viceroy commemorated by the bridge’s name. Engineering depended on people whose responsibilities and risks were very unevenly recorded."},{"type":"paragraph","text":"A photograph can show where someone stood without explaining the terms of their employment. Payrolls, contractors’ records and local testimony would add other kinds of evidence. The absence of a name from a caption should not be mistaken for the absence of skill. Equally, an attractive story about a named worker should not be accepted without checking where it first appeared."},{"type":"heading","level":2,"text":"Two bridges, two moments"},{"type":"paragraph","text":"The later Ayub Bridge carried the railway from 1962. In some views the two structures overlap, making their relationship difficult to untangle. Identifying them separately helps the eye distinguish the earlier cantilever solution from its neighbour rather than reading the river crossing as one enormous object."},{"type":"paragraph","text":"Lansdowne’s significance is therefore more than its age or dramatic appearance. It brings geography, industrial fabrication, construction labour and changing transport requirements into the same frame. A careful photograph should reveal those relationships: bank, island, channel and structure, with enough context to show what the bridge was required to do."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Sindh","Architecture"],"province":"Sindh","district":"Sukkur","relatedDistrictIds":["sindh-sukkur"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5119"],"relatedStoryIds":["story-sukkur-and-rohri-as-linked-river-settlements","story-the-indus-as-a-cultural-landscape-not-a-single-itinerary","story-the-sukkur-crossing-as-a-landscape-of-engineering"],"contentType":"heritage-place","seo":{"title":"Lansdowne Bridge and the challenge of spanning the Indus | Virsapur Archives","description":"The Lansdowne Bridge joined a railway across a difficult Indus channel. Construction photographs make its engineering decisions and labour visible alongside its celebrated outline.","primaryKeyword":"Lansdowne Bridge heritage","socialTitle":"Lansdowne Bridge and the challenge of spanning the Indus","socialDescription":"The Lansdowne Bridge joined a railway across a difficult Indus channel. Construction photographs make its engineering decisions and labour visible alongside its celebrated outline."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Bridging the mighty Indus: the Lansdowne Bridge at Sukkur","url":"https://specialcollections-blog.lib.cam.ac.uk/?p=14253","publisher":"Cambridge University Library, Royal Commonwealth Society collections","accessDate":"2026-10-22"},{"title":"Lansdowne Bridge catalogue record","url":"https://doam.gov.pk/public/sites/5119","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Opening of the Lansdowne Bridge","url":"https://searcharchives.bl.uk/catalog/041-003093946","publisher":"British Library","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Cambridge collection essay closely read; approximately190 derived words including site constraint, cantilevers, album, deaths and later bridge. British Library opening catalogue about30. DOAM1887 is not opening date; use1889 confirmed by primary photograph. No Jamalo legend presented as fact.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Introduce engineering choices through the crossing rather than unsupported world-first claims.","wordCount":443,"publicationHold":false,"sortOrder":111}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-akra-archaeology-in-the-bannu-basin','akra-archaeology-in-the-bannu-basin','review','{"id":"story-akra-archaeology-in-the-bannu-basin","type":"story","slug":"akra-archaeology-in-the-bannu-basin","title":"Akra: archaeology in the Bannu basin","summary":"Research at Akra places early settlement growth in the Bannu basin before Achaemenid expansion. Its mounds complicate histories that explain change only through outside empires.","body":[{"type":"paragraph","text":"Akra invites a change of starting point. Instead of asking first which empire reached the Bannu basin, we can ask what was happening there before imperial expansion. Archaeological research makes that question possible. The settlement is not merely a backdrop for a political history written elsewhere; its own sequence can test that history."},{"type":"paragraph","text":"The Department of Archaeology and Museums describes a group of four mounds near Bharat village, southwest of Bannu. A group of mounds should not automatically be imagined as a single town occupied in exactly the same way throughout its existence. Differences between areas may matter as much as the outline of the whole site."},{"type":"heading","level":2,"text":"Growth before the imperial explanation"},{"type":"paragraph","text":"Peter Magee and his colleagues’ 2005 study reports results from three seasons of fieldwork ending in 2001. Their central conclusion is that settlement growth at Akra began early in the first millennium BCE, several centuries before Achaemenid expansion into the region. They also identify material connections extending toward Central Asia and peninsular India."},{"type":"paragraph","text":"This does not mean that later imperial connections were irrelevant. It means that an empire cannot simply be assigned responsibility for processes already under way. The order of events matters. If settlement expansion precedes a proposed cause, the explanation needs revision rather than a more dramatic retelling."},{"type":"paragraph","text":"The Bannu Archaeological Project’s later synthesis places Akra within a wider programme of fieldwork undertaken between 1985 and 2001. Its published description presents a long but discontinuous sequence extending from the first millennium BCE into the early second millennium CE. Discontinuous is an important qualification: a long overall date range is not evidence of uninterrupted occupation in every excavated area."},{"type":"heading","level":2,"text":"Reading connections without drawing an empire"},{"type":"paragraph","text":"An object resembling material from another region can raise several possibilities. It might have travelled, been copied locally or belong to a wider shared technical tradition. Determining which explanation fits requires attention to manufacture, composition and context. A line drawn between two points on a map is a useful question, not a complete account of exchange."},{"type":"paragraph","text":"Akra’s value lies partly in this tension between regional development and long-distance relationships. Neither isolation nor total dependence is a satisfactory default. The basin can be understood as a setting where people made choices, adapted techniques and participated in connections whose significance changed over time."},{"type":"heading","level":2,"text":"A mound is more than a label"},{"type":"paragraph","text":"For an atlas reader, the most useful introduction is therefore not a single dynasty attached to a pin. It is a sequence of research questions: which part of the settlement was investigated, how was it dated, and what supports the interpretation of its material?"},{"type":"paragraph","text":"Those questions make Akra more interesting, not less accessible. They reveal a place capable of correcting an inherited story. Preserving the distinctions between surveyed ground, excavated deposits and historical interpretation allows the Bannu basin to emerge as an active part of South Asian history rather than an empty space between better-known centres."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Khyber Pakhtunkhwa","Architecture"],"province":"Khyber Pakhtunkhwa","district":"Bannu","relatedDistrictIds":["khyber-pakhtunkhwa-bannu"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-doam-3184"],"relatedStoryIds":["story-the-bannu-basin-in-regional-archaeology"],"contentType":"heritage-place","seo":{"title":"Akra: archaeology in the Bannu basin | Virsapur Archives","description":"Research at Akra places early settlement growth in the Bannu basin before Achaemenid expansion. Its mounds complicate histories that explain change only through outside empires.","primaryKeyword":"Akra Archaeological Mounds heritage","socialTitle":"Akra: archaeology in the Bannu basin","socialDescription":"Research at Akra places early settlement growth in the Bannu basin before Achaemenid expansion. Its mounds complicate histories that explain change only through outside empires."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Akra catalogue record","url":"https://doam.gov.pk/public/sites/3184","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"The Achaemenid Empire in South Asia and Recent Excavations in Akra in Northwest Pakistan","url":"https://repository.brynmawr.edu/arch_pubs/82/","publisher":"Bryn Mawr College repository; American Journal of Archaeology","accessDate":"2026-10-22"},{"title":"The Archaeology of the Bannu Basin","url":"https://www.jstor.org/stable/j.ctv13pk77m","publisher":"Oxbow Books, Bannu Archaeological Project","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Magee et al2005abstract fully read approximately120 derived words. Bannu project synthesis description approximately75; DOAM approximately45. Do not claim entire book read, uninterrupted sequence or imperial attribution for every mound.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Show the basin’s place in regional settlement history through a documented mound complex.","wordCount":464,"publicationHold":false,"sortOrder":112}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-charsaddas-bala-hisar-the-mound-not-peshawars-fort','charsaddas-bala-hisar-the-mound-not-peshawars-fort','review','{"id":"story-charsaddas-bala-hisar-the-mound-not-peshawars-fort","type":"story","slug":"charsaddas-bala-hisar-the-mound-not-peshawars-fort","title":"Charsadda’s Bala Hisar: the mound, not Peshawar’s fort","summary":"Charsadda’s Bala Hisar is an archaeological mound associated with ancient Pushkalavati, not Peshawar’s standing fort. Its research history shows why preliminary interpretations need revisiting.","body":[{"type":"paragraph","text":"Two places can share a name without sharing a history. Bala Hisar at Charsadda is an archaeological mound associated with ancient Pushkalavati. It must not be confused with the conspicuous fort in Peshawar. That distinction is more than a navigation detail: the kinds of evidence available at the two places are different."},{"type":"paragraph","text":"At Charsadda, buried deposits and excavated material are central to interpretation. A photograph of the mound cannot supply the sequence beneath it. Nor does the expression high fort establish that every part was a fortress, or that the visible earthwork belongs to one construction episode. Place names are evidence to investigate, not substitutes for excavation."},{"type":"heading","level":2,"text":"How a provisional sequence became influential"},{"type":"paragraph","text":"The University of Cambridge’s account of earlier research explains the importance of Mortimer Wheeler’s 1958 investigation. It also makes a revealing qualification: Wheeler regarded the work as a preliminary reconnaissance, and the published pottery represented a selection. That initial framework subsequently acquired more authority than its limited basis necessarily justified."},{"type":"paragraph","text":"This is a useful lesson in how archaeological knowledge travels. A diagram or period table can be copied into later works until the original caution disappears. Repetition makes a claim familiar; it does not enlarge the excavation on which the claim rests. Returning to the first report can therefore be as important as obtaining a new date."},{"type":"paragraph","text":"The Cambridge account also describes the historical identification of Pushkalavati, including an inscription referring to the district of Pushkala. Such evidence helps establish a geographical argument, but it should be kept distinct from the dating of an individual occupation layer. A name and a deposit answer different questions."},{"type":"heading","level":2,"text":"Returning to the ground"},{"type":"paragraph","text":"A collaboration between the University of Peshawar and Cambridge began renewed investigation in 2006, led by Muhammad Nasim Khan and Cameron Petrie. The project situated Charsadda near the meeting of the Swat and Kabul river systems and within wider routes through the region. Its purpose was to improve understanding rather than merely repeat an established label."},{"type":"paragraph","text":"That setting encourages questions about movement and settlement. Rivers can support connections while also altering land and access. Yet an attractive regional map cannot determine which route was used in a particular century. Material from securely recorded contexts is needed to connect a broad geographical possibility to a historical claim."},{"type":"heading","level":2,"text":"What a visitor should take away"},{"type":"paragraph","text":"The mound deserves attention even where its architecture is not immediately spectacular. Its significance lies partly in the information that remains beneath an apparently simple surface. Surface disturbance can sever relationships that no later photograph will restore."},{"type":"paragraph","text":"Charsadda’s Bala Hisar is best introduced through this combination of place and inquiry. Identify the correct site, explain the evidence for Pushkalavati, and show how the chronology has been questioned. The result is a stronger history than a single confident foundation date: one that makes clear both what researchers have learned and why the work continues."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Khyber Pakhtunkhwa","Architecture"],"province":"Khyber Pakhtunkhwa","district":"Charsadda","relatedDistrictIds":["khyber-pakhtunkhwa-charsadda"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-doam-2160"],"relatedStoryIds":["story-the-peshawar-valley-as-a-network-of-places"],"contentType":"heritage-place","seo":{"title":"Charsadda’s Bala Hisar: the mound, not Peshawar’s fort | Virsapur Archives","description":"Charsadda’s Bala Hisar is an archaeological mound associated with ancient Pushkalavati, not Peshawar’s standing fort. Its research history shows why preliminary interpretations need revisiting.","primaryKeyword":"Bala Hisar Mound, Charsadda heritage","socialTitle":"Charsadda’s Bala Hisar: the mound, not Peshawar’s fort","socialDescription":"Charsadda’s Bala Hisar is an archaeological mound associated with ancient Pushkalavati, not Peshawar’s standing fort. Its research history shows why preliminary interpretations need revisiting."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Bala Hisar,Charsadda","url":"https://doam.gov.pk/public/sites/2160","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Investigating Ancient Pushkalavati: previous research","url":"https://www.arch.cam.ac.uk/research/projects/archived-projects/investigating-ancient-pushkalavati/previous-research","publisher":"University of Cambridge Department of Archaeology","accessDate":"2026-10-22"},{"title":"Investigating Ancient Pushkalavati: introduction","url":"https://www.arch.cam.ac.uk/research/projects/archived-projects/investigating-ancient-pushkalavati/introduction","publisher":"University of Cambridge Department of Archaeology","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Cambridge project pages treated as same work, approximately185 derived words total. DOAM identity and mound approximately45. Wheeler1958representative pottery preliminary not definitive. Avoid Peshawarfortconflation or accepted Achaemenidfoundationclaim.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Resolve a common naming confusion and explain the archaeological landscape.","wordCount":461,"publicationHold":false,"sortOrder":113}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-mustuj-fort-and-movement-through-upper-chitral','mustuj-fort-and-movement-through-upper-chitral','review','{"id":"story-mustuj-fort-and-movement-through-upper-chitral","type":"story","slug":"mustuj-fort-and-movement-through-upper-chitral","title":"Mustuj Fort and movement through upper Chitral","summary":"Mustuj, also written Mastuj, links a strategic valley junction with a living conservation problem. Its stone, earth and timber construction deserves as much attention as accounts of military movement.","body":[{"type":"paragraph","text":"Mustuj Fort, frequently written Mastuj, is a useful place to connect the history of movement with the history of building. Its position near the meeting of the Laspur and Yarkhun valleys helps explain why accounts of Upper Chitral repeatedly return to it. But describing a fort as strategic should be the beginning of an explanation, not its conclusion."},{"type":"paragraph","text":"The 1928 Chitral Gazetteer described the position in relation to routes toward Gilgit, Wakhan and Chitral, and recorded rebuilding in 1917. The property’s present stewardship account associates an earlier fort with the Katoor rulers and the late eighteenth century. These are different episodes, not necessarily rival answers to a single question about the building’s age."},{"type":"heading","level":2,"text":"A fort is a sequence of repairs"},{"type":"paragraph","text":"The 2025 condition survey prepared by Wadaan Consultants for the Commonwealth Heritage Forum provides a more immediate way to understand the surviving fabric. It records stone masonry, mud mortar and horizontal timber ties in the traditional construction system known as grin. The walls enclose an open interior rather than a surviving arrangement of roofed rooms."},{"type":"paragraph","text":"The survey identifies damaged wall sections, weakened timber connections and serious distress at the northeastern bastion. It also explains the importance of projecting protective copings and the consequences of their deterioration. Water management is not a minor finishing detail: the top and base of a wall belong to the same conservation problem."},{"type":"paragraph","text":"Those observations resist the idea that restoration means making an old fort look newly complete. A replacement surface can conceal a failing structural connection. Equally, leaving every damaged element untouched can allow avoidable loss. The appropriate response depends on understanding how the original materials worked together and where that relationship has broken down."},{"type":"heading","level":2,"text":"Knowledge held beyond the monument"},{"type":"paragraph","text":"The survey combined measurements, photographs and drone documentation with consultation involving craftspeople and local residents. This is especially valuable where maintenance knowledge concerns earth plaster, stone and timber. A measured drawing records dimensions; a craftsperson may explain how a vulnerable junction was traditionally protected or repaired."},{"type":"paragraph","text":"Neither source should be treated as infallible. An oral account can preserve an important practice without establishing the date of every wall. A technical survey can accurately describe a crack without explaining every historical alteration. Reading them together produces a more useful record than expecting either to supply the entire history."},{"type":"heading","level":2,"text":"Seeing the junction and the fabric"},{"type":"paragraph","text":"Good interpretation should therefore work at two scales. A wider view explains the relationship between the fort and the valleys. A closer view reveals joints, ties, copings and repairs. The landscape image alone can make the fort seem timeless; the material evidence shows that its survival has required repeated intervention."},{"type":"paragraph","text":"Mustuj is not simply an illustration for a military episode. It is a structure whose construction logic, changes and present vulnerabilities can be studied. Conservation begins when those particulars become visible, before a picturesque appearance is mistaken for a complete understanding of the place."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Khyber Pakhtunkhwa","Architecture"],"province":"Khyber Pakhtunkhwa","district":"Chitral Upper","relatedDistrictIds":["khyber-pakhtunkhwa-chitral-upper"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-doam-1238"],"relatedStoryIds":["story-chitrals-forts-and-multilingual-communities"],"contentType":"heritage-place","seo":{"title":"Mustuj Fort and movement through upper Chitral | Virsapur Archives","description":"Mustuj, also written Mastuj, links a strategic valley junction with a living conservation problem. Its stone, earth and timber construction deserves as much attention as accounts of military movement.","primaryKeyword":"Mustuj Fort heritage","socialTitle":"Mustuj Fort and movement through upper Chitral","socialDescription":"Mustuj, also written Mastuj, links a strategic valley junction with a living conservation problem. Its stone, earth and timber construction deserves as much attention as accounts of military movement."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Mustuj Fort catalogue record","url":"https://doam.gov.pk/public/sites/1238","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Mastuj Fort condition survey,2025","url":"https://www.commonwealthheritage.org/wp-content/uploads/2025/09/Mastuj-Fort-Condition-Survey-Report-1st-Stage-12.08.2025.pdf","publisher":"Wadaan Consultants / Commonwealth Heritage Forum","accessDate":"2026-10-22"},{"title":"Chitral Gazetteer,1928","url":"https://www.mahraka.com/pdf/chitralGazetteer-1928.pdf","publisher":"Government of India, historical gazetteer","accessDate":"2026-10-22"},{"title":"Mastuj Fort","url":"https://hindukushheights.com/mastuj-fort-chalets-glamping/","publisher":"Hindukush Heights, property stewardship account","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"2025conditionreport methods/construction/damage pages14–28 closely read, approximately190 derived words. Gazetteerp33~45; propertyhistoricalaccount~30explicitlyattributed. No definitive10ccreationclaim; no presentvisitoraccessguarantee.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Read the stronghold’s setting without treating modern political boundaries as ancient ones.","wordCount":464,"publicationHold":false,"sortOrder":114}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-bilot-sharif-temples-and-the-stone-building-tradition','bilot-sharif-temples-and-the-stone-building-tradition','review','{"id":"story-bilot-sharif-temples-and-the-stone-building-tradition","type":"story","slug":"bilot-sharif-temples-and-the-stone-building-tradition","title":"Bilot Sharif Temples and the stone-building tradition","summary":"Bilot Sharif’s temples belong to a regional stone-building tradition whose chronology cannot be reduced to one dynasty. Their materials, arrangements and changing scholarly labels reward careful comparison.","body":[{"type":"paragraph","text":"Bilot Sharif’s stone temples invite a closer look than the familiar label ancient ruins allows. The Department of Archaeology and Museums records temple groups within a fortified setting and describes the use of dressed stone and kanjur, a comparatively workable sedimentary material. Material and arrangement offer a route into the buildings even when a complete historical narrative is unavailable."},{"type":"paragraph","text":"A visitor can begin with straightforward questions. How does the entrance relate to the chamber? Which surfaces carry architectural mouldings? Where does one kind of masonry meet another? These observations are more useful than assigning every visible element to the same ruler simply because a regional dynasty is well known."},{"type":"heading","level":2,"text":"A regional tradition, not one repeated design"},{"type":"paragraph","text":"Michael Meister’s work on temples along the Indus places Bilot within a broader architectural discussion. The recurring forms matter, but so do differences between buildings. Comparison is most productive when it identifies a particular feature rather than treating all temples in the region as interchangeable examples."},{"type":"paragraph","text":"A separate excavation report by Meister, Abdur Rehman and Farid Khan provides an instructive comparison from north Kafirkot. There, investigation distinguished earlier temple construction from later enlargement. The authors describe changes from kanjur elements to limestone additions, modifications around an entrance and evidence for more than one building phase. They also argue against assigning the entire regional tradition exclusively to the Hindu Shahi period."},{"type":"paragraph","text":"Those findings belong to the excavated northern site. They should not be copied into Bilot’s record as if the same trench had been opened here. Their value is methodological: they demonstrate why standing appearance and a single dynastic label may conceal a more complicated sequence."},{"type":"heading","level":2,"text":"Reading stone without overreading it"},{"type":"paragraph","text":"A change in masonry can indicate an alteration, but it does not identify the person who ordered it. A blocked opening may reflect repair or changed use; its purpose requires contextual evidence. Architectural interpretation becomes stronger when it keeps these steps separate: observation, comparison, proposed explanation and supporting evidence."},{"type":"paragraph","text":"The names and letters applied to individual structures also require care. An archaeological catalogue may group a selection of buildings without providing a complete inventory of every surviving feature. Before comparing plans from different publications, the reader should check that their labels refer to the same structure. Otherwise, an apparent disagreement may simply be a mismatch in naming."},{"type":"heading","level":2,"text":"More than a skyline of towers"},{"type":"paragraph","text":"Photography can help make these distinctions visible. A distant view establishes the ensemble, while an oblique view may reveal an entrance or a change in wall treatment. Close details should remain connected to the building they belong to. An isolated ornamental fragment is visually appealing but tells little about spatial organisation on its own."},{"type":"paragraph","text":"Bilot’s importance lies in the opportunity to read architecture as evidence of making and remaking. The temples deserve individual identities within a shared tradition. That approach preserves their complexity and makes comparison with other Indus monuments meaningful, without turning a regional resemblance into an invented common history."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Khyber Pakhtunkhwa","Architecture"],"province":"Khyber Pakhtunkhwa","district":"D. I. Khan","relatedDistrictIds":["khyber-pakhtunkhwa-d-i-khan"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-doam-1012"],"relatedStoryIds":[],"contentType":"heritage-place","seo":{"title":"Bilot Sharif Temples and the stone-building tradition | Virsapur Archives","description":"Bilot Sharif’s temples belong to a regional stone-building tradition whose chronology cannot be reduced to one dynasty. Their materials, arrangements and changing scholarly labels reward careful comparison.","primaryKeyword":"Bilot Sharif Temples heritage","socialTitle":"Bilot Sharif Temples and the stone-building tradition","socialDescription":"Bilot Sharif’s temples belong to a regional stone-building tradition whose chronology cannot be reduced to one dynasty. Their materials, arrangements and changing scholarly labels reward careful comparison."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Bilot Sharif Temples","url":"https://doam.gov.pk/public/sites/1012","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Discovery of a New Temple on the Indus","url":"https://www.penn.museum/sites/expedition/discovery-of-a-new-temple-on-the-indus/","publisher":"Penn Museum; Michael W.Meister,Abdur Rehman,Farid Khan","accessDate":"2026-10-22"},{"title":"Temples Along the Indus","url":"https://www.penn.museum/sites/expedition/temples-along-the-indus/","publisher":"Penn Museum; Michael W.Meister","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"New2000primary excavation paper~175derived words for explicitly comparative NORTHKafirkot evidence, not imported into Bilot. 1996paper~35 additional,cumulative~175. DOAMBilot~75. Avoid treating DOAMthreecataloguegroups as total survivingtemplecount; no unsupportedpreciseBilotdates.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Examine the temple group as distinct from the similarly named Kafir Kot complex.","wordCount":472,"publicationHold":false,"sortOrder":115}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-peshawar-museum-how-a-collection-frames-gandhara','peshawar-museum-how-a-collection-frames-gandhara','review','{"id":"story-peshawar-museum-how-a-collection-frames-gandhara","type":"story","slug":"peshawar-museum-how-a-collection-frames-gandhara","title":"Peshawar Museum: how a collection frames Gandhara","summary":"Peshawar Museum’s Gandhara collections are more than a sequence of beautiful sculptures. Their acquisition histories, reserve holdings and scholarly study shape what visitors can learn from them.","body":[{"type":"paragraph","text":"A museum does not simply gather objects; it gives them relationships. Placing sculptures together can make gestures, materials and narrative scenes easier to compare. It can also separate those objects from the buildings and deposits in which they were found. Peshawar Museum offers a useful setting in which to think about both possibilities."},{"type":"paragraph","text":"The Department of Archaeology and Museums records the museum’s opening in 1907 in the Victoria Memorial building. Its holdings extend beyond Gandhara sculpture to other categories including coins, manuscripts, weapons and dress. Gandhara is central to the museum’s public identity, but it should not erase the range of historical material held there."},{"type":"heading","level":2,"text":"The collection behind the display"},{"type":"paragraph","text":"Tahir Saeed’s 2023 study focuses on a preaching Buddha image in the reserve collection associated with the former Sub-Regional Office at Peshawar. The article explains that this collection includes material received through several routes, including excavations, exploration, gifts, acquisitions and confiscations. These are not equivalent forms of provenance."},{"type":"paragraph","text":"An excavated sculpture may be connected to a recorded architectural context. An object seized from illicit circulation can retain artistic and historical importance while lacking that context. The distinction is not a ranking of beauty. It affects the questions a researcher can answer securely and the uncertainties a label should communicate."},{"type":"paragraph","text":"Saeed also traces changes in institutional custody, including the transfer of relevant federal holdings to the provincial directorate after the Eighteenth Amendment. The history of an object does not stop when it enters a museum. Registration, custody, storage and renewed study become further parts of its documented life."},{"type":"heading","level":2,"text":"Looking at a gesture"},{"type":"paragraph","text":"The article examines the Buddha’s preaching gesture, known as dharmacakra mudra, and uses formal comparison to discuss the sculpture. Such close study gives the viewer something more precise to notice than a general impression of serenity. The position of hands, treatment of clothing and relation of figure to support can become evidence."},{"type":"paragraph","text":"Comparison nevertheless has limits. Similar appearance does not by itself prove a shared workshop or findspot. An interpretation should distinguish what is visible on the object from what is inferred through comparison. That distinction becomes especially important where excavation information is missing."},{"type":"heading","level":2,"text":"What the gallery cannot show all at once"},{"type":"paragraph","text":"A published study of a reserve object also reminds us that the visible gallery is not the complete collection. Storage is not necessarily a sign that an object is unimportant; research, conservation and display planning involve different requirements. Conversely, publication does not establish that a particular sculpture is currently on public view."},{"type":"paragraph","text":"The most rewarding museum visit can therefore combine attentive looking with attention to the label. What is the object called? Where was it found? How certain is its date, and how did it enter the collection? Peshawar Museum’s significance grows when these questions accompany admiration. They restore some of the relationships that a case or pedestal cannot communicate by appearance alone."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Khyber Pakhtunkhwa","Architecture"],"province":"Khyber Pakhtunkhwa","district":"Peshawar","relatedDistrictIds":["khyber-pakhtunkhwa-peshawar"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-doam-4549"],"relatedStoryIds":["story-recognising-a-bodhisattva-through-attributes"],"contentType":"heritage-place","seo":{"title":"Peshawar Museum: how a collection frames Gandhara | Virsapur Archives","description":"Peshawar Museum’s Gandhara collections are more than a sequence of beautiful sculptures. Their acquisition histories, reserve holdings and scholarly study shape what visitors can learn from them.","primaryKeyword":"Peshawar Museum heritage","socialTitle":"Peshawar Museum: how a collection frames Gandhara","socialDescription":"Peshawar Museum’s Gandhara collections are more than a sequence of beautiful sculptures. Their acquisition histories, reserve holdings and scholarly study shape what visitors can learn from them."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Peshawar Museum","url":"https://doam.gov.pk/public/sites/4549","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"A Marvelous Buddha Sculpture in the Reserve Collection of Peshawar Museum","url":"https://www.esijournals.com/image/catalog/Journal%20Paper/SAHCA/2023/No%202%20%282023%29/12_Tahir.pdf","publisher":"Tahir Saeed, South Asian History,Culture and Archaeology,2023","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMmuseumhistory/collectionrange~100words. Saeed2023primarycollectionstudy sections collectionhistory/iconographypages289–293closelyread~190derivedwords. No claim reserveobjectpubliclydisplayed; no universalGreekoriginclaim; avoid sweeping chronology of Buddhaimage.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain gallery interpretation and collection history without claiming every object’s provenance is settled.","wordCount":459,"publicationHold":false,"sortOrder":116}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-gwadars-omani-fort-and-an-indian-ocean-history','gwadars-omani-fort-and-an-indian-ocean-history','review','{"id":"story-gwadars-omani-fort-and-an-indian-ocean-history","type":"story","slug":"gwadars-omani-fort-and-an-indian-ocean-history","title":"Gwadar’s Omani Fort and an Indian Ocean history","summary":"Gwadar’s Omani Fort connects a surviving building with the town’s Indian Ocean history. Its interpretation should distinguish political chronology, architectural evidence and current conservation proposals.","body":[{"type":"paragraph","text":"Gwadar’s Omani Fort offers a different starting point from the contemporary port projects that often dominate descriptions of the town. Its name points across the sea, toward a history in which political authority and movement connected Makran with Oman. The building deserves to be read within that history without becoming a convenient symbol for every overseas connection."},{"type":"paragraph","text":"The Department of Archaeology and Museums identifies a rectangular fort with substantial walls and windows and associates it with Omani rule. That description establishes a particular heritage asset. It does not make every older tower or coastal structure in Gwadar part of the same fort, or establish the date of each surviving wall."},{"type":"heading","level":2,"text":"An enclave and its documentary history"},{"type":"paragraph","text":"The Qatar Digital Library’s historical account describes repeated discussions about Gwadar’s status before its transfer from Oman to Pakistan in 1958. Digitised India Office records include a file from 1949–50 concerning a possible sale or lease, with British officials acting as intermediaries. The surviving paperwork makes clear that the eventual transfer followed a longer history of negotiation."},{"type":"paragraph","text":"Such records are valuable, but their perspective is specific. Officials discussing territory are not necessarily describing everyday life within it. Their categories and priorities should not stand in for the experiences of all residents. Local family histories, commercial records and material evidence would answer other questions about the same period."},{"type":"paragraph","text":"The distinction also matters architecturally. A document about sovereignty does not automatically date a staircase, roof or opening. Connecting political chronology to a building requires plans, inscriptions, photographs or a careful study of the fabric. The fort’s Omani association is a starting point for that work, not permission to assign every detail an identical origin."},{"type":"heading","level":2,"text":"Reuse without erasing the evidence"},{"type":"paragraph","text":"A Gwadar Development Authority newsletter describes adaptive-reuse work involving several historic sites, including the Omani Fort. It discusses cultural, educational and literary uses and distinguishes progress at the Telegraph Office from work continuing at other properties. An announcement of a programme should not be rewritten as proof that every restoration has been completed."},{"type":"paragraph","text":"Adaptive reuse raises practical interpretive questions. Which spaces can accommodate new activity? How will new services be introduced? Will visitors be able to distinguish repairs from surviving fabric? A successful cultural use should make the building more understandable, rather than turning it into a backdrop whose historical evidence is hidden by a uniform new finish."},{"type":"heading","level":2,"text":"A coastal history at human scale"},{"type":"paragraph","text":"The fort can help widen Gwadar’s story beyond a simple before-and-after narrative of development. It connects the town to maritime political history while remaining a specific place with its own construction and conservation questions."},{"type":"paragraph","text":"That combination is its strength. The sea supplies a broad horizon; the building brings attention back to walls, openings, rooms and the people responsible for their care. Interpretation should allow both scales to remain visible without claiming that a single monument contains the whole history of the coast."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Balochistan","Architecture"],"province":"Balochistan","district":"Gwadar","relatedDistrictIds":["balochistan-gwadar"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["major-doam-10390"],"relatedStoryIds":["story-makran-through-settlement-and-maritime-connections"],"contentType":"heritage-place","seo":{"title":"Gwadar’s Omani Fort and an Indian Ocean history | Virsapur Archives","description":"Gwadar’s Omani Fort connects a surviving building with the town’s Indian Ocean history. Its interpretation should distinguish political chronology, architectural evidence and current conservation proposals.","primaryKeyword":"Omani Fort, Gwadar heritage","socialTitle":"Gwadar’s Omani Fort and an Indian Ocean history","socialDescription":"Gwadar’s Omani Fort connects a surviving building with the town’s Indian Ocean history. Its interpretation should distinguish political chronology, architectural evidence and current conservation proposals."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Omani Fort","url":"https://doam.gov.pk/public/sites/10390","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Gwadar:The Omani Enclave in Pakistan","url":"https://qdl.qa/en/gwadar-omani-enclave-pakistan","publisher":"Qatar Digital Library / British Library","accessDate":"2026-10-22"},{"title":"Gwadar Development Authority newsletter","url":"https://gda.gov.pk/Documents/Document_1740223504.pdf","publisher":"Gwadar Development Authority","accessDate":"2026-10-22"},{"title":"File8/78II:Sale of Gwadur","url":"https://www.qdl.qa/archive/81055/vdc_100057741739.0x000013","publisher":"British Library India Office Records, Qatar Digital Library","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMbuildingdescription~65. QDLhistoricalessay~100anddistinct1949–50filecatalogue~45. GDAnewsletterp15adaptive-reuseproposal~90. Transfergiven1958onlyavoidsday/monthofficialdiscrepancy. No totalrestorationcompletionclaim,no mergedwatchtower/fortidentity.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Connect the documented building with maritime political change, not a generic beach itinerary.","wordCount":462,"publicationHold":false,"sortOrder":117}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-khojak-tunnel-and-the-landscape-of-railway-engineering','khojak-tunnel-and-the-landscape-of-railway-engineering','review','{"id":"story-khojak-tunnel-and-the-landscape-of-railway-engineering","type":"story","slug":"khojak-tunnel-and-the-landscape-of-railway-engineering","title":"Khojak Tunnel and the landscape of railway engineering","summary":"Khojak Tunnel is a railway monument best understood through the mountain it crosses and the work required to create its approaches. Its significance does not depend on an unverified modern length ranking.","body":[{"type":"paragraph","text":"A tunnel can be difficult to appreciate as a heritage place because most of its engineering is hidden. At Khojak, the visible portals represent only the ends of a much larger intervention through a mountain barrier. Understanding the site requires attention to the railway alignment and its approaches, not simply a photograph of the entrance."},{"type":"paragraph","text":"The Department of Archaeology and Museums places the tunnel on the Quetta–Chaman railway near Shelabagh. The Pakistan Bureau of Statistics’ provincial account dates its construction to 1888–91 and describes a passage approximately four kilometres long. A contemporary railway administration report records completion in 1891. These sources provide a more stable introduction than claims that it remains the longest tunnel of a particular kind."},{"type":"heading","level":2,"text":"The mountain defines the problem"},{"type":"paragraph","text":"A railway cannot respond to terrain in the same way as a footpath. Its alignment has to accommodate the movement of heavy vehicles along continuous rails. Cutting through a barrier therefore involves decisions about the approaches as well as the underground passage. The entrance makes sense only when connected to the track leading toward it."},{"type":"paragraph","text":"The official catalogue describes gradients, construction demands and the movement of materials required for the project. These details place Khojak within a history of coordinated engineering work. Excavation, removal of spoil, lining and track formation are connected tasks; success in one does not make the others unnecessary."},{"type":"paragraph","text":"The distinction between the finished structure and the worksite is particularly important here. A completed tunnel appears as a continuous passage. During construction it was a changing series of working faces, temporary arrangements and logistical problems. Historical photographs and engineering records can recover parts of that process that the finished object conceals."},{"type":"heading","level":2,"text":"Infrastructure and political purpose"},{"type":"paragraph","text":"The tunnel belongs to the railway history of British India’s northwestern frontier. That context should be discussed without treating infrastructure as a politically neutral gift or assuming that every person involved shared its official purpose. Strategic objectives, engineering achievement and the experience of labour are related but separate subjects."},{"type":"paragraph","text":"A heritage account can acknowledge the technical accomplishment while asking who supplied materials, who performed the work and how the railway affected surrounding places. Where documentary answers are incomplete, the questions should remain visible. A famous engineer’s name cannot substitute for a workforce history."},{"type":"heading","level":2,"text":"What a responsible record should preserve"},{"type":"paragraph","text":"The most useful record would connect portal details, dated engineering drawings, railway alignment and historical images. Length should be stated with an appropriate degree of approximation where sources differ. A construction date should not be confused with the date of later repair or alteration."},{"type":"paragraph","text":"Nor should historical interest be turned into an invitation to enter railway infrastructure. The monument’s significance can be explained without making assumptions about public access or operational conditions. Khojak rewards an account of how a landscape was crossed, rather than a contest over superlatives. Its importance lies in the relationship between terrain, technique, labour and the ambitions that brought them together."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Balochistan","Architecture"],"province":"Balochistan","district":"Chaman","relatedDistrictIds":["balochistan-chaman"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["major-doam-10388"],"relatedStoryIds":["story-khojak-a-pass-transformed-by-a-tunnel"],"contentType":"heritage-place","seo":{"title":"Khojak Tunnel and the landscape of railway engineering | Virsapur Archives","description":"Khojak Tunnel is a railway monument best understood through the mountain it crosses and the work required to create its approaches. Its significance does not depend on an unverified modern length ranking.","primaryKeyword":"Khojak Railway Tunnel heritage","socialTitle":"Khojak Tunnel and the landscape of railway engineering","socialDescription":"Khojak Tunnel is a railway monument best understood through the mountain it crosses and the work required to create its approaches. Its significance does not depend on an unverified modern length ranking."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Khojak Tunnel","url":"https://doam.gov.pk/public/sites/10388","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Balochistan provincial census report,2017","url":"https://www.pbs.gov.pk/sites/default/files/population/census_reports/pcr_balochistan.pdf","publisher":"Pakistan Bureau of Statistics","accessDate":"2026-10-22"},{"title":"Administration report on the railways in India,1891–92","url":"https://southasiacommons.net/artifacts/2358879/administration-report-on-the-railways-in-india-for-1891-92/3349880/","publisher":"Government of India railway administration report, digitised by South Asia Commons","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM~150wordsavoidingstale115years,longestrankandprecisefatalityclaim; PBS~50construction1888–91; contemporaryrailreportindexedcompletionpassage~35, not claimedwholevolumeclose-read. No entryaccess/safety claim.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain the tunnel as infrastructure in a difficult pass, with dates and dimensions verified before drafting.","wordCount":470,"publicationHold":false,"sortOrder":118}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-shahi-tump-and-the-archaeological-sequence-of-makran','shahi-tump-and-the-archaeological-sequence-of-makran','review','{"id":"story-shahi-tump-and-the-archaeological-sequence-of-makran","type":"story","slug":"shahi-tump-and-the-archaeological-sequence-of-makran","title":"Shahi Tump and the archaeological sequence of Makran","summary":"Shahi Tump preserves evidence of settlement and later burial in the Kech valley. The French mission’s work shows why those episodes must be separated rather than flattened into a single ancient date.","body":[{"type":"paragraph","text":"Shahi Tump lies in the Kech valley near Turbat, in a landscape whose archaeology cannot be reduced to a distant reflection of the Indus cities. The Department of Archaeology and Museums records settlement remains and later graves at the mound. That sequence is the essential starting point: a place used for living can subsequently become a place used for burial."},{"type":"paragraph","text":"The French archaeological mission in Makran investigated Shahi Tump between 1997 and 2006. Its institutional account locates the site across the Kech river from Miri Qalat and describes the investigation as a way to study an early village sequence. The two sites belong to the same research landscape, but their names and discoveries should not be exchanged."},{"type":"heading","level":2,"text":"One place, different uses"},{"type":"paragraph","text":"The mission reports buildings using stone and earth construction, followed by evidence from two fourth-millennium BCE burial grounds. It places the later cemetery within its regional phase IIIa, approximately 3400–2800 BCE. Pottery, metal objects and ornaments contributed to comparisons with southeastern Iran."},{"type":"paragraph","text":"These finds matter partly because they occur in recorded relationships. A vessel from a burial does not necessarily represent the equipment of an earlier house beneath it. Combining everything from a mound into a single list of ancient objects would destroy the distinction between different uses of the place."},{"type":"paragraph","text":"The relationship between settlement and burial also raises questions that cannot be answered from the mound’s outline alone. Did the later community remember the earlier buildings? Was the location chosen for its prominence, its associations or some other reason? Such possibilities should be identified as questions unless the excavated evidence supports a more definite explanation."},{"type":"heading","level":2,"text":"Connections across Makran"},{"type":"paragraph","text":"Comparisons with material farther west help place Shahi Tump within a wider regional history. They do not automatically establish the identity or language of the people buried there. Similar objects can travel through exchange, shared production practices or imitation; the particular explanation requires additional evidence."},{"type":"paragraph","text":"This is why regional phase names are useful but limited. They organise differences in material and chronology. They are not necessarily the names that ancient communities used for themselves, and they should not be converted into a map of fixed ethnic territories."},{"type":"heading","level":2,"text":"The archive behind the excavation"},{"type":"paragraph","text":"The CNRS-associated archive catalogue lists mission documents including campaign reports, burial inventories and stratigraphic records. Even at the level of catalogue descriptions, it reveals that excavation produces much more than a selection of display objects. The records connect finds to observations made during fieldwork."},{"type":"paragraph","text":"That documentary work is crucial because excavation changes the deposits it investigates. Later researchers depend on the surviving plans, photographs, registers and samples to reconsider an interpretation. Preserving the archive is therefore part of preserving the site’s knowledge."},{"type":"paragraph","text":"Shahi Tump offers a particularly clear introduction to this layered understanding of heritage. Its significance lies not in assigning the mound one spectacular age, but in separating episodes, recording their relationships and asking what those relationships reveal about life and remembrance in ancient Makran."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Balochistan","Architecture"],"province":"Balochistan","district":"Kech","relatedDistrictIds":["balochistan-kech"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["major-doam-10398"],"relatedStoryIds":["story-makran-through-settlement-and-maritime-connections","story-makrans-inland-routes-and-coastal-horizons"],"contentType":"heritage-place","seo":{"title":"Shahi Tump and the archaeological sequence of Makran | Virsapur Archives","description":"Shahi Tump preserves evidence of settlement and later burial in the Kech valley. The French mission’s work shows why those episodes must be separated rather than flattened into a single ancient date.","primaryKeyword":"Shahi Tump heritage","socialTitle":"Shahi Tump and the archaeological sequence of Makran","socialDescription":"Shahi Tump preserves evidence of settlement and later burial in the Kech valley. The French mission’s work shows why those episodes must be separated rather than flattened into a single ancient date."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Shahi Tump","url":"https://doam.gov.pk/public/sites/10398","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Mission archéologique française au Makran","url":"https://arscan.parisnanterre.fr/umr-7041/equipes/equipe-archeologie-de-lasie-centrale/activites-de-lequipe-archeologie-de-lasie-centrale/mission-archeologique-francaise-au-makran-mafm/","publisher":"ArScAn, Université Paris Nanterre / CNRS","accessDate":"2026-10-22"},{"title":"French mission in Makran archival descriptions","url":"https://archives.mshmondes.cnrs.fr/index.php/informationobject/browse?collection=157053&limit=10&media=print&sort=alphabetic&sortDir=desc&topLod=0","publisher":"Maison des Sciences de l’Homme Mondes, CNRS archives","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"ArScAnprimarymissionaccount~190derivedwords; no priorreusefound. DOAM~55. CNRSarchivecatalogue~70metadataonly. DistinctShahiTump/MiriQalat,temporalrelationbetweenvillage/cemeteries. No exactpopulation/ethnicityclaims.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Use published evidence to place a coastal-region settlement beyond the Indus-city story.","wordCount":476,"publicationHold":false,"sortOrder":119}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-hinglaj-a-sacred-place-within-a-difficult-landscape','hinglaj-a-sacred-place-within-a-difficult-landscape','review','{"id":"story-hinglaj-a-sacred-place-within-a-difficult-landscape","type":"story","slug":"hinglaj-a-sacred-place-within-a-difficult-landscape","title":"Hinglaj: a sacred place within a difficult landscape","summary":"Hinglaj is a living sacred place whose meaning cannot be reduced to scenery or a single uniform tradition. Research on pilgrimage shows how access, organisation and community interpretations change over time.","body":[{"type":"paragraph","text":"Hinglaj is not simply an arresting place in a dramatic landscape. It is a living sacred destination, and an account that treats worshippers as background to the scenery misses its central significance. The Department of Archaeology and Museums identifies the shrine within the Hingol landscape of Balochistan. Its location matters, but geography alone does not explain why people travel there."},{"type":"paragraph","text":"Jürgen Schaflechner’s ethnographic study, published by Oxford University Press in 2018, examines how the shrine’s meanings and organisation have changed. The book’s published overview connects the expansion of an annual pilgrimage festival from the mid-1980s with later changes in access associated with the coastal highway. It also explores differences among the people and organisations connected to the shrine."},{"type":"heading","level":2,"text":"A tradition with more than one voice"},{"type":"paragraph","text":"The study places Hinglaj within Hindu sacred narratives while also discussing regional and community-specific associations. Its chapter overview notes the name Nani in relation to Zikri Muslim traditions. Such connections deserve careful description, not a quick claim that everyone understands or uses the place in exactly the same way."},{"type":"paragraph","text":"The book also examines the role of the Hinglaj Sheva Mandali and questions of authority, community and interpretation. This makes the shrine visible as an organised social setting rather than a tradition that exists without people making decisions. Who coordinates a pilgrimage, explains its meaning or manages a sacred space can affect how it is experienced."},{"type":"paragraph","text":"Those observations should not be turned into a verdict about which community’s understanding is authentic. An archive article can introduce differences respectfully and identify whose account it is presenting. It should avoid using one interview, institution or academic interpretation to speak on behalf of every devotee."},{"type":"heading","level":2,"text":"What easier access changes"},{"type":"paragraph","text":"A change in the journey can alter a pilgrimage without making it less meaningful. Travel time, transport and the number of people arriving together may affect organisation and expectations. The important question is not whether a modern road has destroyed an untouched past, but how participants understand and adapt to changed circumstances."},{"type":"paragraph","text":"That question requires listening. Hardship can carry religious significance, but an outside observer should not romanticise danger or assume that greater difficulty produces greater devotion. Practical access and spiritual meaning are related in ways that differ between people and periods."},{"type":"heading","level":2,"text":"Looking with permission and context"},{"type":"paragraph","text":"Photography at a living shrine carries responsibilities that differ from photographing an unoccupied monument. Worship is not a performance staged for an archive. Consent, local guidance and sensitivity around ritual moments should shape what is recorded and how images are captioned."},{"type":"paragraph","text":"Hinglaj’s heritage value lies in the meeting of place, practice, memory and changing institutions. A useful introduction makes room for all four. It explains why the landscape matters while refusing to let landscape imagery replace the people for whom the shrine is sacred. That approach produces a richer account than either a scenic travel description or a supposedly timeless summary of belief."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Balochistan","Architecture"],"province":"Balochistan","district":"Lasbela","relatedDistrictIds":["balochistan-lasbela"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["major-doam-9186"],"relatedStoryIds":["story-hinglaj-pilgrimage-listening-before-describing","story-pilgrimage-paths-and-the-places-between-monuments"],"contentType":"heritage-place","seo":{"title":"Hinglaj: a sacred place within a difficult landscape | Virsapur Archives","description":"Hinglaj is a living sacred place whose meaning cannot be reduced to scenery or a single uniform tradition. Research on pilgrimage shows how access, organisation and community interpretations change over time.","primaryKeyword":"Hinglaj Mata Temple heritage","socialTitle":"Hinglaj: a sacred place within a difficult landscape","socialDescription":"Hinglaj is a living sacred place whose meaning cannot be reduced to scenery or a single uniform tradition. Research on pilgrimage shows how access, organisation and community interpretations change over time."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Hinglaj Mata Temple","url":"https://doam.gov.pk/public/sites/9186","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Hinglaj Devi:Identity,Change,and Solidification at a Hindu Temple in Pakistan","url":"https://academic.oup.com/book/5901","publisher":"Jürgen Schaflechner,Oxford University Press,2018","accessDate":"2026-10-22"},{"title":"Hinglaj in perspective,chapter abstract","url":"https://academic.oup.com/book/5901/chapter-abstract/149201192","publisher":"Oxford University Press","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"OUPbookandchapterabstractsread,notclaimingfullbookaccess; aggregate~190derivedwords. DOAMidentitylocation~25. No currentfestivaldate/accessclaims,nouniversalcommunityagreement,no sacredritualinstructions. Remainderoriginalethical/interpretiveanalysis.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Treat shrine setting, community meaning and travel limitations separately and respectfully.","wordCount":464,"publicationHold":false,"sortOrder":120}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-kharmang-fort-and-the-remains-of-a-mountain-seat','kharmang-fort-and-the-remains-of-a-mountain-seat','review','{"id":"story-kharmang-fort-and-the-remains-of-a-mountain-seat","type":"story","slug":"kharmang-fort-and-the-remains-of-a-mountain-seat","title":"Kharmang Fort and the remains of a mountain seat","summary":"Kharmang’s old fort, Boti Khar, should be distinguished from the palace recorded nearby. Keeping those identities separate is the first step toward understanding the surviving mountain seat.","body":[{"type":"paragraph","text":"The name Kharmang Fort can appear beside photographs of an impressive residence, creating the impression that every description refers to the same building. The official archaeological catalogue makes a distinction that should be preserved. It records an old fort called Boti Khar separately from Kharmang Palace. Before interpreting the architecture, an archive needs to establish which asset a photograph or account actually describes."},{"type":"paragraph","text":"The fort entry characterises Boti Khar as a two-storey structure and attributes its construction to a Kharpon ruler before 1565. It also mentions another fort, Soma Khar, which it says no longer survives. These statements come from a built-heritage inventory rather than a dated building inscription presented with the entry, so their attribution should remain visible."},{"type":"heading","level":2,"text":"A fort is not automatically the palace"},{"type":"paragraph","text":"The separate palace record describes a three-level building associated with Raja Jaffer Ali Khan. It records a rectangular arrangement, a courtyard and verandah on the upper level, and different seasonal and storage uses across the floors. These details should not be transferred to Boti Khar merely because the places are close together or their names are used loosely."},{"type":"paragraph","text":"This is a practical problem in heritage documentation. A photograph may be correctly located in Kharmang yet incorrectly captioned as a particular fort. An architectural feature may then be repeated in later descriptions until it seems to establish the fort’s form. Careful identification interrupts that chain before an error becomes familiar."},{"type":"paragraph","text":"The district tourism account explains the name Kharmang through the Balti terms for fort and abundance. That regional association helps explain why several fortified places can enter local histories. It does not mean that one surviving structure represents all of them, or that a regional name can supply a construction date."},{"type":"heading","level":2,"text":"What a measured record would clarify"},{"type":"paragraph","text":"Plans and dated photographs could help separate the surviving assets and document their relationship. Useful questions include where one enclosure ends, how entrances connect to surrounding ground and which wall junctions indicate alteration. Family records and local testimony could add histories of ownership and use, provided those accounts remain attributed."},{"type":"paragraph","text":"None of this requires turning a private building into an unrestricted visitor attraction. The catalogue records private ownership. Documentation and interpretation should respect the people responsible for the property, and an online description should not imply permission to enter rooms or enclosed ground."},{"type":"heading","level":2,"text":"Preserving the right story"},{"type":"paragraph","text":"The immediate value of Boti Khar is not diminished by uncertainty over individual historical details. On the contrary, the need to distinguish it from neighbouring buildings shows why a precise record matters. Conservation decisions depend on knowing what survives and which history belongs to it."},{"type":"paragraph","text":"Kharmang deserves an account in which the old fort, the later palace and the memory of other strongholds retain separate identities. Together they can illuminate a mountain seat over time. Merging them into one picturesque monument would make that history simpler, but much less informative."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Gilgit-Baltistan","Architecture"],"province":"Gilgit-Baltistan","district":"Kharmang","relatedDistrictIds":["gilgit-baltistan-kharmang"],"provinceRegionIds":["gilgit-baltistan"],"relatedHeritageIds":["major-doam-7978"],"relatedStoryIds":[],"contentType":"heritage-place","seo":{"title":"Kharmang Fort and the remains of a mountain seat | Virsapur Archives","description":"Kharmang’s old fort, Boti Khar, should be distinguished from the palace recorded nearby. Keeping those identities separate is the first step toward understanding the surviving mountain seat.","primaryKeyword":"Kharmang Fort (Boti Khar) heritage","socialTitle":"Kharmang Fort and the remains of a mountain seat","socialDescription":"Kharmang’s old fort, Boti Khar, should be distinguished from the palace recorded nearby. Keeping those identities separate is the first step toward understanding the surviving mountain seat."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Kharmang Fort","url":"https://doam.gov.pk/public/sites/7978","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Kharmang Palace","url":"https://doam.gov.pk/public/sites/8228","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Kharmang district","url":"https://e-tourism.visitgilgitbaltistan.gov.pk/districts/kharmang","publisher":"Government of Gilgit-Baltistan Tourism Department","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Fort andpalacecatalogue derived fromsameunpublishedBuiltHeritageGBinventory:aggregate~185derivedwords. GBdistrict~35. Sixteenthcenturydateattributednotindependentlyconfirmed; nearidenticalsourcecoordinates do not prove identicalasset. No canonicalgeometrychange.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Present the documented structure without reconstructing vanished palace life as fact.","wordCount":462,"publicationHold":false,"sortOrder":121}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-yasins-mudoori-fort-and-contested-remembrance','yasins-mudoori-fort-and-contested-remembrance','review','{"id":"story-yasins-mudoori-fort-and-contested-remembrance","type":"story","slug":"yasins-mudoori-fort-and-contested-remembrance","title":"Yasin’s Mudoori Fort and contested remembrance","summary":"Mudoori in Yasin is a place of remembrance as well as a recorded fort. Conflicting dates and casualty figures require explicit source criticism, not a dramatic narrative assembled from repetition.","body":[{"type":"paragraph","text":"Mudoori Fort at Sandi in the Yasin valley is not an uncomplicated scenic ruin. Accounts connect it with nineteenth-century violence and the deaths of people who sought protection there. A responsible introduction must acknowledge that association while being careful about the dates, numbers and political explanations attached to it."},{"type":"paragraph","text":"The Department of Archaeology and Museums’ short catalogue entry gives 1862 for an attack and includes a casualty estimate. Nineteenth-century accounts associated with George Hayward and G. W. Leitner instead place the massacre in 1863. This discrepancy should not be resolved by silently choosing the most frequently repeated version of an online story."},{"type":"heading","level":2,"text":"Reading a source and its argument"},{"type":"paragraph","text":"Leitner’s published historical chronology records violence against women and children at Yasin in 1863. An earlier volume reproduces Hayward’s forceful criticism of the Kashmir authorities and British policy. Editorial notes in the same material qualify some of Hayward’s political assertions, including claims about hereditary rights in Gilgit."},{"type":"paragraph","text":"That combination is revealing. The text preserves an accusation of serious violence, but it is also part of a dispute about political authority and intervention. Reading the charge and the editorial qualifications together is more informative than extracting a dramatic sentence and treating it as a complete, neutral account."},{"type":"paragraph","text":"The existence of disagreement does not justify dismissing the suffering being described. It does require separating several questions: what happened, when it happened, who was affected, how many people were involved and what political conclusions a writer wanted readers to draw. Evidence may be stronger for one question than for another."},{"type":"heading","level":2,"text":"Remembrance is not a casualty competition"},{"type":"paragraph","text":"An exact death toll should not be presented merely because precision feels authoritative. Estimates may derive from different witnesses, categories or later retellings. Without reconciliation, a range of incompatible numbers can obscure rather than honour the people remembered."},{"type":"paragraph","text":"Likewise, a contemporary community’s relationship to the place deserves its own documentation. Oral history can explain how an event is recalled, where commemoration occurs and which family or local narratives remain important. It should not be mined only for colourful details to decorate an account written elsewhere."},{"type":"heading","level":2,"text":"What the fort can contribute"},{"type":"paragraph","text":"The surviving place and the documentary history are related but not identical evidence. A wall or defensible position may help explain the physical setting, yet it cannot independently establish a particular sequence of killings. Archaeological work would need clearly defined questions and sensitivity toward the community’s understanding of the site."},{"type":"paragraph","text":"Mudoori therefore calls for an interpretation that combines acknowledgement with restraint. Its record should preserve source dates, identify disagreements and avoid converting uncertainty into either spectacle or denial. The most useful first account is one that makes the evidence traceable and leaves space for local testimony. That approach recognises the place’s seriousness while refusing to manufacture a certainty the sources do not support."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Gilgit-Baltistan","Architecture"],"province":"Gilgit-Baltistan","district":"Gupis-Yasin","relatedDistrictIds":["gilgit-baltistan-gupis-yasin"],"provinceRegionIds":["gilgit-baltistan"],"relatedHeritageIds":["major-doam-8030"],"relatedStoryIds":[],"contentType":"heritage-place","seo":{"title":"Yasin’s Mudoori Fort and contested remembrance | Virsapur Archives","description":"Mudoori in Yasin is a place of remembrance as well as a recorded fort. Conflicting dates and casualty figures require explicit source criticism, not a dramatic narrative assembled from repetition.","primaryKeyword":"Mudoori Fort, Yasin heritage","socialTitle":"Yasin’s Mudoori Fort and contested remembrance","socialDescription":"Mudoori in Yasin is a place of remembrance as well as a recorded fort. Conflicting dates and casualty figures require explicit source criticism, not a dramatic narrative assembled from repetition."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Mudoori Fort Sandi Yasin","url":"https://doam.gov.pk/public/sites/8030","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Dardistan in1866,1886and1893","url":"https://pahar.in/pahar/Books%20and%20Articles/Afghanistan/1893%20Dardistan%20in%201866%2C%201886%20and%201893%20by%20Leitner%20s.pdf","publisher":"G.W.Leitner, historical account","accessDate":"2026-10-22"},{"title":"The Languages and Races of Dardistan,1878","url":"https://pahar.in/pahar/Books%20and%20Articles/Afghanistan/1878%20Languages%20and%20Races%20of%20Dardistan%20by%20Leitner%20s.pdf","publisher":"G.W.Leitner,including George Hayward correspondence","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMshortentry~65. Leitner1893chronology indexedp73read~55; 1878Haywardappendix indexedpassageandeditorialfootnotesread~100; directPDF403notclaimingfullread. Underlyingoverlappingaccountsaggregate~155. Catalogue1862vsHayward1863explicit; casualtynumberomitted. Historicalsourcecolonialviewpointacknowledged.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Distinguish physical remains, historical documentation and later memory with attributed accounts.","wordCount":447,"publicationHold":false,"sortOrder":122}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-qalamdarchi-fort-at-a-northern-passage','qalamdarchi-fort-at-a-northern-passage','review','{"id":"story-qalamdarchi-fort-at-a-northern-passage","type":"story","slug":"qalamdarchi-fort-at-a-northern-passage","title":"Qalamdarchi Fort at a northern passage","summary":"Qalamdarchi Fort looks toward the northern approaches of Hunza. Its twentieth-century military purpose is clearer when the route network, water supply and surviving enclosure are considered together.","body":[{"type":"paragraph","text":"Qalamdarchi Fort belongs to the northern approaches of Hunza, above Misgar and in relation to routes toward the Kilik and Mintaka passes. Its location makes a wide landscape relevant to a comparatively compact structure. The fort was not intended to dominate a great urban square; its purpose is better understood through movement along mountain corridors."},{"type":"paragraph","text":"The Gilgit-Baltistan Tourism Department dates its construction to 1932–33 during British rule. The Department of Archaeology and Museums classifies it as a twentieth-century military building. These records offer a more precise framework than describing it simply as an ancient frontier fort, a phrase that can conceal a very recent historical context."},{"type":"heading","level":2,"text":"An enclosure with practical requirements"},{"type":"paragraph","text":"The archaeological catalogue describes an oblong plan, a defensive wall and a watchtower at one corner. It also records a well within the enclosure. Together these features shift attention from the distant view to the requirements of the people stationed there: observation, protected space and water."},{"type":"paragraph","text":"A well is not an incidental detail in such an account. A position chosen for visibility also has to support occupation. The relationship between supply and defensibility is therefore worth examining alongside the direction in which a watchtower faces. An imposing location alone does not explain how a post functioned."},{"type":"paragraph","text":"The tourism department notes use by successive military formations and changes during that use. This means that the present appearance should not be assumed to reproduce the original building without alteration. Dated plans or photographs would help distinguish construction, adaptation and repair."},{"type":"heading","level":2,"text":"Routes are not empty lines"},{"type":"paragraph","text":"A map showing the passes can explain the fort’s broader setting, but it should not make the valleys appear empty before the arrival of a military post. A route is experienced by people with different purposes, obligations and local knowledge. Trade, residence and political control are related dimensions, not interchangeable descriptions."},{"type":"paragraph","text":"The term frontier also deserves a date. Boundaries and institutions change, and a twentieth-century surveillance position should not be projected unchanged into every earlier period of movement through the region. Historical maps can be especially useful when their dates and intended purposes are stated clearly."},{"type":"heading","level":2,"text":"A careful visual record"},{"type":"paragraph","text":"The most informative presentation would pair a contextual landscape image with an accurately identified view of the enclosure. A caption should explain the connection between the fort and the northern approaches without turning every visible valley into a documented historic itinerary."},{"type":"paragraph","text":"Military association also means that heritage interest should not be confused with access permission. A catalogue description is not an invitation to enter controlled ground or photograph restricted activity. Public interpretation can remain useful without supplying operational details."},{"type":"paragraph","text":"Qalamdarchi’s significance lies in the relationship between a particular building and the geography it was meant to observe. Its restrained architecture can be read through that relationship. Giving it a clear twentieth-century history makes the place more distinctive than a vague claim of timeless strategic importance."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Gilgit-Baltistan","Architecture"],"province":"Gilgit-Baltistan","district":"Hunza","relatedDistrictIds":["gilgit-baltistan-hunza"],"provinceRegionIds":["gilgit-baltistan"],"relatedHeritageIds":["major-doam-7809"],"relatedStoryIds":[],"contentType":"heritage-place","seo":{"title":"Qalamdarchi Fort at a northern passage | Virsapur Archives","description":"Qalamdarchi Fort looks toward the northern approaches of Hunza. Its twentieth-century military purpose is clearer when the route network, water supply and surviving enclosure are considered together.","primaryKeyword":"Qalamdarchi Fort heritage","socialTitle":"Qalamdarchi Fort at a northern passage","socialDescription":"Qalamdarchi Fort looks toward the northern approaches of Hunza. Its twentieth-century military purpose is clearer when the route network, water supply and surviving enclosure are considered together."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Qalamdarchi Fort","url":"https://doam.gov.pk/public/sites/7809","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Kalamdarchi Fort","url":"https://www.visitgilgitbaltistan.gov.pk/tour/id/43","publisher":"Government of Gilgit-Baltistan Tourism Department","accessDate":"2026-10-22"},{"title":"Kalam Darchi Fort destination record","url":"https://e-tourism.visitgilgitbaltistan.gov.pk/tourist-destinations/kalamdarchi-fort","publisher":"Government of Gilgit-Baltistan Tourism Department","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM~135. Tourismtwoentriesaggregate~85date1932–33/locationonly; newerentrybroadpreborderclaimnotadopted. Avoid exoticising saintetymology; no currentmilitaryschedule/accessinstructions.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain the fort’s strategic setting without using a modern adventure-travel frame.","wordCount":465,"publicationHold":false,"sortOrder":123}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-rani-baoli-and-hammams-water-architecture-in-bhimber','rani-baoli-and-hammams-water-architecture-in-bhimber','review','{"id":"story-rani-baoli-and-hammams-water-architecture-in-bhimber","type":"story","slug":"rani-baoli-and-hammams-water-architecture-in-bhimber","title":"Rani Baoli and Hammams: water architecture in Sudhnoti","summary":"Rani Baoli stands at Palandri in Sudhnoti, not Bhimber. Its stepped tanks, courtyard and adjoining cells reveal a carefully organised water building whose precise chronology remains uncertain.","body":[{"type":"paragraph","text":"Rani Baoli and its adjoining cells belong to Palandri in Sudhnoti. The location needs stating at the outset because a mistaken association with Bhimber can send the building into the wrong regional story. The official archaeological record places it near Palandri’s administrative centre, and the AJK archaeology department includes it among Sudhanoti’s heritage sites."},{"type":"paragraph","text":"The building offers a compact lesson in how water can organise architecture. It is not simply a well with an ornamental surround. The Department of Archaeology and Museums describes a rectangular enclosure entered from the south, with an octagonal stepped tank in the courtyard and rooms arranged along its northern and western sides."},{"type":"heading","level":2,"text":"Water, enclosure and privacy"},{"type":"paragraph","text":"The catalogue records another stepped tank within the larger central cell, together with smaller troughs outside the enclosure. It also notes pointed-arched entrances, surviving wooden doors and perforated projections associated with curtains. These details suggest that access, privacy and different points of water use were considered within the design."},{"type":"paragraph","text":"The rooms are described as possible hammams rather than every function being conclusively established. That qualification matters. The presence of a tank or enclosed chamber is not enough to reconstruct a complete bathing routine, heating system or division of users. Those interpretations require additional evidence from the fabric and documentary record."},{"type":"paragraph","text":"The distinction between the central courtyard and individual cells is nevertheless observable in the published description. Water is encountered at more than one scale: in a shared open area, within a room and at the exterior edge. A plan can make those relationships clearer than a photograph concerned only with a picturesque arch."},{"type":"heading","level":2,"text":"A name and an unsettled chronology"},{"type":"paragraph","text":"The AJK archaeology department also calls the site Balaspuri Baoli and associates its construction with a rani of Balaspur in the Dogra period. The federal catalogue gives a broad relative chronology of 1799–1849. These attributions do not establish an exact construction year, and they should not be combined into an invented inscription or foundation event."},{"type":"paragraph","text":"Names can preserve patronage traditions even where documentary details remain incomplete. Recording the tradition is worthwhile, provided readers can distinguish it from a date demonstrated by a contemporary source. A measured survey, archival search and study of repairs could help refine the sequence."},{"type":"heading","level":2,"text":"The building as a connected system"},{"type":"paragraph","text":"Conservation should consider the tanks, walls, doors and external ground together. Repairing an attractive façade while overlooking drainage or structural movement would address only part of the building. Equally, a newly uniform surface could hide evidence of different construction episodes."},{"type":"paragraph","text":"Rani Baoli rewards close attention precisely because its scale is manageable. A reader can follow the movement from entrance to courtyard to chamber and consider how water structured that movement. Keeping the location correct and the uncertain functions qualified allows the architecture to speak more clearly, without relying on a romantic story that the available evidence cannot securely sustain."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Azad Kashmir","Architecture"],"province":"Azad Jammu and Kashmir","district":"Sudhnoti","relatedDistrictIds":["azad-kashmir-sudhnoti"],"provinceRegionIds":["azad-kashmir"],"relatedHeritageIds":["major-doam-10366"],"relatedStoryIds":["story-stepwells-as-designed-journeys-to-water","story-bhimber-and-the-architecture-of-a-route"],"contentType":"heritage-place","seo":{"title":"Rani Baoli and Hammams: water architecture in Sudhnoti | Virsapur Archives","description":"Rani Baoli stands at Palandri in Sudhnoti, not Bhimber. Its stepped tanks, courtyard and adjoining cells reveal a carefully organised water building whose precise chronology remains uncertain.","primaryKeyword":"Rani Baoli and Hammams heritage","socialTitle":"Rani Baoli and Hammams: water architecture in Sudhnoti","socialDescription":"Rani Baoli stands at Palandri in Sudhnoti, not Bhimber. Its stepped tanks, courtyard and adjoining cells reveal a carefully organised water building whose precise chronology remains uncertain."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Rani Baoli & Hammams","url":"https://doam.gov.pk/public/sites/10366","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Sudhanoti heritage sites","url":"https://archaeology.ajk.gov.pk/sudhanoti/","publisher":"AJK Tourism and Archaeology Department","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"PLAN CORRECTION:index123titleBhimber->Sudhnoti; stableID/slugretained perroot; plandistrictandrelateddistrictalreadySudhnoti. DOAMarchitecture~185derivedwords; AJK~60. DOAM1799–1849relativechronologyvsAJKDogra attribution notresolved. Hammamfunctionqualifiedasofficialcataloguepossibility.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Read the linked stepped-well and bath structures as one ensemble.","wordCount":457,"publicationHold":false,"sortOrder":124}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-throachi-fort-a-local-stronghold-in-its-terrain','throachi-fort-a-local-stronghold-in-its-terrain','review','{"id":"story-throachi-fort-a-local-stronghold-in-its-terrain","type":"story","slug":"throachi-fort-a-local-stronghold-in-its-terrain","title":"Throachi Fort: a local stronghold in its terrain","summary":"Throachi Fort follows the rock on which it stands. Its irregular enclosure, water storage and surviving bastions explain more about the stronghold than an unsupported account of a famous siege.","body":[{"type":"paragraph","text":"Throachi Fort is a useful reminder that a defensive building need not begin with a regular geometric plan. The published archaeological survey describes a fort near Gulpur in Kotli whose enclosure follows a rock outcrop. Its irregular form is therefore part of the relationship between construction and terrain, not a failure to achieve symmetry."},{"type":"paragraph","text":"The record identifies limestone blocks set in lime mortar and two water-storage pits cut into the softer bedrock within the enclosure. These details bring together two aspects of occupation: controlling a defensible position and sustaining people within it. A strong wall and a water supply address different needs, but neither can be understood entirely in isolation."},{"type":"heading","level":2,"text":"Following the ground"},{"type":"paragraph","text":"An irregular plan encourages a different kind of looking. Instead of searching for a central axis, the reader can ask where the rock changes level, where access is possible and how the walls respond. A measured plan would make those decisions easier to follow than a frontal photograph alone."},{"type":"paragraph","text":"This is also a reason to resist judging the fort primarily by size. A compact stronghold can exploit a difficult approach, while a larger enclosure may face other constraints. The relevant question is how a particular position was organised, not whether it resembles a more famous fort elsewhere."},{"type":"heading","level":2,"text":"Reading what is no longer present"},{"type":"paragraph","text":"The survey records bastions at the ends of the entrance wall and evidence of an upper storey whose timber floor no longer survives. It describes stairs and defensive wall features. These observations allow an interpretation of vertical movement without pretending that every lost room can be reconstructed confidently."},{"type":"paragraph","text":"An absent floor changes the way a ruin is perceived. Spaces that were once separated may now appear continuous, and a view through the structure may be a result of loss rather than original design. Interpretive drawings should identify reconstructed portions clearly so that possibility does not become apparent fact."},{"type":"paragraph","text":"The same care applies to the water pits. Their presence is recorded, but a complete account of supply, cleaning and distribution would require further investigation. A visible feature can establish a useful question without answering every aspect of operation."},{"type":"heading","level":2,"text":"Later meanings within an older place"},{"type":"paragraph","text":"The catalogue mentions a shrine associated with a local holy man, while explicitly acknowledging that its history could not be established. That caution should remain in any retelling. The shrine may be important to understanding later relationships with the ruins, but the record does not justify an invented ancient sacred lineage."},{"type":"paragraph","text":"Throachi’s strongest introduction is therefore architectural and spatial. Rock, masonry, storage and circulation provide enough evidence for a thoughtful account without attaching an unsupported siege narrative. The place can be appreciated for the decisions visible in its surviving fabric and for the questions that remain."},{"type":"paragraph","text":"Preserving those distinctions is itself a form of care. It lets future documentation add to the story rather than first having to undo a confident but untraceable history."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Azad Kashmir","Architecture"],"province":"Azad Jammu and Kashmir","district":"Kotli","relatedDistrictIds":["azad-kashmir-kotli"],"provinceRegionIds":["azad-kashmir"],"relatedHeritageIds":["major-doam-6671"],"relatedStoryIds":[],"contentType":"heritage-place","seo":{"title":"Throachi Fort: a local stronghold in its terrain | Virsapur Archives","description":"Throachi Fort follows the rock on which it stands. Its irregular enclosure, water storage and surviving bastions explain more about the stronghold than an unsupported account of a famous siege.","primaryKeyword":"Throachi Fort heritage","socialTitle":"Throachi Fort: a local stronghold in its terrain","socialDescription":"Throachi Fort follows the rock on which it stands. Its irregular enclosure, water storage and surviving bastions explain more about the stronghold than an unsupported account of a famous siege."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Throachi Fort,2020survey record","url":"https://doam.gov.pk/public/sites/6671","publisher":"Department of Archaeology and Museums; Taxila Institute of Asian Civilizations survey","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Official2020survey entry closely read. Approximately190derivedwords factualarchitecture/location/shrineuncertainty; remainderexplicitoriginalinterpretivequestions. Sparseevidence acknowledged; noinventedfounder/siegeexactdate. Single-source factual scope intentionallybounded.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Examine documented surviving fabric and landscape rather than an unsourced siege narrative.","wordCount":468,"publicationHold":false,"sortOrder":125}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-sarai-kharbuza-a-roadside-stop-within-the-modern-capital','sarai-kharbuza-a-roadside-stop-within-the-modern-capital','review','{"id":"story-sarai-kharbuza-a-roadside-stop-within-the-modern-capital","type":"story","slug":"sarai-kharbuza-a-roadside-stop-within-the-modern-capital","title":"Sarai Kharbuza: a roadside stop within the modern capital","summary":"Sarai Kharbuza preserves the logic of a roadside enclosure within Islamabad’s wider landscape. Jahangir’s account and the surviving fabric answer different questions about its history.","body":[{"type":"paragraph","text":"Islamabad’s modern identity can make older roadside settlements seem like exceptions to the capital’s history. Sarai Kharbuza suggests a different approach: the present city occupies a landscape through which people were already travelling, stopping and building. The sarai belongs to that longer geography of movement."},{"type":"paragraph","text":"The Department of Archaeology and Museums describes a square enclosure with arched gateways in the northern and southern walls. Living cells and a verandah run along the perimeter. This arrangement makes the building intelligible as a place that combined an inward-facing protected space with access from a route outside it."},{"type":"heading","level":2,"text":"A name in an emperor’s journey"},{"type":"paragraph","text":"Jahangir’s memoir records a stop at Kharbuza during his journey toward Kabul in 1607. He associates the name with a melon-shaped dome built earlier by the Gakhars, who collected tolls from travellers. The passage is valuable evidence for how the place was described at that time."},{"type":"paragraph","text":"It is not, however, a measured survey of all the surviving sarai. The emperor’s mention of a dome does not date every wall now identified with the complex. Nor should a brief account of a stop be expanded into a detailed description of accommodation that the text does not provide."},{"type":"paragraph","text":"This distinction is especially important where an evocative name attracts repeated retelling. A place-name explanation may be historically recorded while the relationship between the named feature and later buildings remains a separate question. Keeping both points clear produces a more reliable narrative than assigning the whole site to one celebrated visit."},{"type":"heading","level":2,"text":"Materials reveal different episodes"},{"type":"paragraph","text":"The archaeological catalogue records small-brick masonry with lime-surkhi plaster. It also describes a mosque at the northwestern corner that has been repaired and covered with cement mortar, with painted decoration inside. These observations indicate why a uniform date should not be assumed from the appearance of the complex today."},{"type":"paragraph","text":"The record additionally reports remains of a baoli associated with an earlier period beneath the mosque area. Because that information is presented as a reported identification, it should not be turned into a fully reconstructed water system without further investigation."},{"type":"heading","level":2,"text":"A roadside building within a living settlement"},{"type":"paragraph","text":"The most useful questions concern relationships: how the gateways connect to the surrounding streets, how cells relate to the enclosure and which parts preserve earlier materials. Answering them requires documentation that respects current occupants and users rather than treating a living place as an empty archaeological diagram."},{"type":"paragraph","text":"A sarai also invites reflection on the infrastructure of travel. Routes depend on places where people can pause, organise goods and obtain necessities. Such support is easy to overlook when history is told only through journeys between major cities."},{"type":"paragraph","text":"Sarai Kharbuza makes that intermediate scale visible. Its value lies in the meeting of a documented stopping place, surviving architectural arrangements and later adaptation. The modern capital becomes historically richer when those layers are recognised rather than forced into a single, picturesque origin story."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Islamabad","Architecture"],"province":"Islamabad Capital Territory","district":"Islamabad","relatedDistrictIds":["islamabad-islamabad"],"provinceRegionIds":["islamabad"],"relatedHeritageIds":["major-doam-6227"],"relatedStoryIds":["story-sarai-architecture-and-the-logistics-of-travel","story-the-capitals-older-places"],"contentType":"heritage-place","seo":{"title":"Sarai Kharbuza: a roadside stop within the modern capital | Virsapur Archives","description":"Sarai Kharbuza preserves the logic of a roadside enclosure within Islamabad’s wider landscape. Jahangir’s account and the surviving fabric answer different questions about its history.","primaryKeyword":"Sarai Kharbuza heritage","socialTitle":"Sarai Kharbuza: a roadside stop within the modern capital","socialDescription":"Sarai Kharbuza preserves the logic of a roadside enclosure within Islamabad’s wider landscape. Jahangir’s account and the surviving fabric answer different questions about its history."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Sarai Kharbuza","url":"https://doam.gov.pk/public/sites/6227","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"The Tuzuk-i-Jahangiri,volumeI,p98","url":"https://www.gutenberg.org/files/53674/53674-h/53674-h.htm","publisher":"Jahangir; translation Alexander Rogers,edited Henry Beveridge","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMlivefetchsuccessfulafterwebtimeout; approximately175derivedwords. JahangirmemoirKharbuza passagep98read~80derivedwords, noverbatimquotation. Use1607journeycontextnotfrequentlymisstated1605. Nooriginalfoundingyearorfreeaccommodationclaim.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Recover the architectural logic of a sarai without claiming that every surviving wall shares one date.","wordCount":461,"publicationHold":false,"sortOrder":126}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-early-farming-in-the-kachi-plain-evidence-rather-than-an-origin-myth','early-farming-in-the-kachi-plain-evidence-rather-than-an-origin-myth','review','{"id":"story-early-farming-in-the-kachi-plain-evidence-rather-than-an-origin-myth","type":"story","slug":"early-farming-in-the-kachi-plain-evidence-rather-than-an-origin-myth","title":"Early farming in the Kachi plain: evidence rather than an origin myth","summary":"Mehrgarh is central to understanding early farming in the Kachi plain, but evidence for crops and livestock is not the same as proof of a single isolated invention. The important story is a process, not an origin slogan.","body":[{"type":"paragraph","text":"Mehrgarh’s importance is often compressed into a declaration that farming began here. That statement is too blunt for the evidence. The site in the Kachi plain is central to the study of early food production in northwestern South Asia, but the questions it raises are more interesting than a competition to identify one first place."},{"type":"paragraph","text":"The published field reports bring together architecture, burials, tools, plants and animals. Yale’s archaeological index of those reports describes evidence relating to early cereals and livestock, including sheep, goats and cattle. Farming is therefore studied through several connected categories of material, not inferred from a single object that looks agricultural."},{"type":"heading","level":2,"text":"Cultivation and domestication are different questions"},{"type":"paragraph","text":"Cultivation concerns what people do with plants: tending, sowing or managing them. Domestication concerns changes in populations of plants or animals through their relationship with people. The two processes are connected, but evidence for one does not automatically demonstrate the timing or location of the other."},{"type":"paragraph","text":"Archaeobotanist Dorian Fuller’s review emphasises the need to study the physical changes associated with domestication and the gaps in evidence for earlier foraging and initial cultivation. In its discussion of Balochistan, the review notes the importance of introduced crops and livestock alongside unresolved questions about local developments and connections farther west."},{"type":"paragraph","text":"This approach avoids a false choice between complete isolation and passive borrowing. A community can adopt a crop from elsewhere while developing distinctive ways of growing, storing or combining it with other resources. Movement of a plant does not mean that the whole social system travelled unchanged with it."},{"type":"heading","level":2,"text":"What the assemblage can establish"},{"type":"paragraph","text":"The field-report description identifies cereal evidence including barley, with variation in the degree to which domesticated characteristics are apparent. That qualification matters. A grain is not merely a token in a list of foods; its identification, condition and archaeological context affect the conclusions drawn from it."},{"type":"paragraph","text":"The same applies to animal remains. Species identification alone does not tell us whether an animal was hunted, herded or obtained through exchange. Researchers have to examine additional patterns rather than treating every familiar domestic species as proof of a fully developed farming economy."},{"type":"heading","level":2,"text":"A history of decisions and connections"},{"type":"paragraph","text":"An origin myth makes change appear instantaneous. Archaeological evidence instead encourages questions about repeated choices: how people obtained food, managed risk, organised storage and responded to local conditions. Different parts of that process may have changed at different speeds."},{"type":"paragraph","text":"Chronology also needs to remain open to revision as better samples and methods become available. An early date repeated in textbooks should not substitute for checking which deposit was dated and how the result was obtained."},{"type":"paragraph","text":"Mehrgarh is most valuable when it is allowed to complicate the story. It reveals early communities making livelihoods through a combination of practices and relationships. Understanding that process gives the Kachi plain a substantial place in the history of farming without asking the site to prove a simplified claim of exclusive invention."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology","Balochistan"],"province":"Balochistan","district":"Kachhi","relatedDistrictIds":["balochistan-kachhi"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["curated-mehrgarh"],"relatedStoryIds":["story-mehrgarh-before-the-indus-cities","story-radiocarbon-dates-are-ranges-not-birthdays","story-animal-bones-and-the-limits-of-ancient-menus","story-terracotta-figurines-without-invented-identities"],"contentType":"archaeology","seo":{"title":"Early farming in the Kachi plain: evidence rather than an origin myth | Virsapur Archives","description":"Mehrgarh is central to understanding early farming in the Kachi plain, but evidence for crops and livestock is not the same as proof of a single isolated invention. The important story is a process, not an origin slogan.","primaryKeyword":"Mehrgarh early farming","socialTitle":"Early farming in the Kachi plain: evidence rather than an origin myth","socialDescription":"Mehrgarh is central to understanding early farming in the Kachi plain, but evidence for crops and livestock is not the same as proof of a single isolated invention. The important story is a process, not an origin slogan."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Finding Plant Domestication in the Indian Subcontinent","url":"https://www.journals.uchicago.edu/doi/abs/10.1086/658900","publisher":"Dorian Q.Fuller,Current Anthropology,2011","accessDate":"2026-10-22"},{"title":"Mehrgarh Field Reports1975–1985,publication description","url":"https://ehrafarchaeology.yale.edu/traditions/aq40/documents/002","publisher":"Yale eHRAF Archaeology","accessDate":"2026-10-22"},{"title":"Archaeological Site of Mehrgarh","url":"https://whc.unesco.org/en/tentativelists/1876/","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"FullerabstractandindexedBaluchistansectionread~175derivedwords; fulltext403notclaimedread. Yaleindexedprimaryfieldreportdescription~100. UNESCOlocation~12,cumulativeunder200. Avoidold7000BCEpresentedsettled; revisedchronologyhandledinarticle19,notreusedMutinbudget. Cultivation/domesticationdistinctionnotclaimallmorphologiesdocumented.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Separate plant, animal and settlement evidence from claims that one place invented agriculture.","wordCount":468,"publicationHold":false,"sortOrder":127}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-how-archaeologists-build-an-indus-chronology','how-archaeologists-build-an-indus-chronology','review','{"id":"story-how-archaeologists-build-an-indus-chronology","type":"story","slug":"how-archaeologists-build-an-indus-chronology","title":"How archaeologists build an Indus chronology","summary":"An Indus chronology is built by connecting stratigraphy, artefact comparison and scientific dating. Period names organise the evidence, but they should not be mistaken for events that happened everywhere at once.","body":[{"type":"paragraph","text":"A timeline of the Indus civilisation can look deceptively simple: an early phase, an urban phase and a later phase arranged in neat blocks. The archaeological work behind those blocks is less tidy. Researchers have to establish relationships between deposits, compare material and evaluate dates before deciding how a sequence should be described."},{"type":"paragraph","text":"A particularly revealing example appears in Dales and Kenoyer’s report on the Harappa Project’s 1986–89 seasons. The authors explain the need for a secure internal relative chronology supported by radiocarbon dates. They also warn that broad labels can obscure regional and temporal variation. Their numbered periods were analytical tools, not natural divisions waiting to be discovered intact."},{"type":"heading","level":2,"text":"First establish the order"},{"type":"paragraph","text":"Relative chronology asks which event or deposit came before another. A floor covered by later material, a wall cut by a pit or a sequence of rebuilding can provide such relationships. The result is an order of events even before any calendar date has been attached."},{"type":"paragraph","text":"That order is not always a simple vertical stack. Later activity can cut into earlier deposits, while older material can be moved into a newer fill. The location and character of a find matter as much as the depth at which it appears."},{"type":"paragraph","text":"The Harappa report’s caution about terminology is important here. If material is assigned to a phase solely because it resembles another assemblage, the classification should not then be used uncritically as independent proof that the two deposits are exactly contemporary."},{"type":"heading","level":2,"text":"Bringing dates into a recorded sequence"},{"type":"paragraph","text":"The Beas Landscape and Settlement Survey provides a concrete example from a test trench. Its authors distinguish cultural fills, hearths, burnt floors, water-related deposits and mudbrick structures. Radiocarbon results from different positions in that sequence were considered alongside the pottery rather than replacing the stratigraphic observations."},{"type":"paragraph","text":"The published discussion also treats a possible early occupation as something that further study could resolve. That wording is part of the result, not an inconvenience to remove from a public account. A small number of diagnostic-looking sherds can support a hypothesis without making it final."},{"type":"heading","level":2,"text":"From one settlement to a region"},{"type":"paragraph","text":"Connecting a local sequence to an Indus-wide chronology requires another step. Similar changes need not occur in every settlement at precisely the same moment. A regional phase is a useful framework for comparison, but it should not erase differences in the evidence from particular places."},{"type":"paragraph","text":"This is why a good timeline should identify approximate ranges, the source of its dates and the meaning of its period labels. It should also distinguish an older published framework from a later revision rather than mixing their dates without explanation."},{"type":"paragraph","text":"Chronology is not merely a preliminary list of numbers attached to a finished history. It is an argument about relationships in the evidence. Understanding how that argument is built makes the Indus past more accessible, because readers can see why an interpretation changes and what new work would be needed to improve it."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":"","district":"","relatedDistrictIds":["punjab-sahiwal","sindh-larkana"],"provinceRegionIds":["punjab","sindh"],"relatedHeritageIds":["major-doam-6579","unesco-138"],"relatedStoryIds":["story-wells-mohenjodaro","story-mohenjodaro-lanes","story-mohenjodaro-architecture","story-priest-king"],"contentType":"archaeology","seo":{"title":"How archaeologists build an Indus chronology | Virsapur Archives","description":"An Indus chronology is built by connecting stratigraphy, artefact comparison and scientific dating. Period names organise the evidence, but they should not be mistaken for events that happened everywhere at once.","primaryKeyword":"Indus civilisation chronology","socialTitle":"How archaeologists build an Indus chronology","socialDescription":"An Indus chronology is built by connecting stratigraphy, artefact comparison and scientific dating. Period names organise the evidence, but they should not be mistaken for events that happened everywhere at once."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"The Harappa Project1986–1989:New Investigation at an Ancient Indus City","url":"https://www.harappa.com/sites/default/files/pdf/Kenoyer1993_The%20Harappa%20Project%201986-1989%20New%20Investigations.pdf","publisher":"George F.Dales and J.Mark Kenoyer,1993","accessDate":"2026-10-22"},{"title":"Test Trench and Chronology,Beas survey","url":"https://www.harappa.com/beas/test-trench-chronology","publisher":"Rita P.Wright,Joseph Shuldenrein,M.Rafique Mughal; Harappa.com","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DalesKenoyer1993pp471–472~185derivedwords; historical1993provisionalperiodnumbersnotpresentedcurrent. Beasprimarytesttrench~150derivedwords avoidingoverprecisesinglepointdatesreproducedasbirthday. Remainingmethodologicalanalysisoriginal.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain how stratigraphy and material comparisons establish phases, not a memorised timeline.","wordCount":470,"publicationHold":false,"sortOrder":128}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-what-a-pottery-assemblage-can-say-about-a-settlement','what-a-pottery-assemblage-can-say-about-a-settlement','review','{"id":"story-what-a-pottery-assemblage-can-say-about-a-settlement","type":"story","slug":"what-a-pottery-assemblage-can-say-about-a-settlement","title":"What a pottery assemblage can say about a settlement","summary":"A pottery assemblage reveals patterns that an isolated decorated vessel cannot. Recording fabric, form, quantity and context helps distinguish evidence of making, use and deposition from attractive speculation.","body":[{"type":"paragraph","text":"A decorated pot can make a striking museum object, but an assemblage asks a different question: what can a group of pottery fragments reveal when their relationships are recorded? The answer depends on keeping ordinary material in view. Plain body sherds, damaged rims and undecorated bases can be as important as the pieces selected for display."},{"type":"paragraph","text":"The Chartered Institute for Archaeologists’ pottery guidance separates attributes such as fabric, form, surface treatment and decoration. It also emphasises quantities, including fragment count and weight. These records allow patterns to be examined rather than leaving interpretation dependent on the most memorable examples."},{"type":"heading","level":2,"text":"Counting fragments is not counting pots"},{"type":"paragraph","text":"One vessel may break into many pieces, while another is represented by a single rim. A hundred sherds therefore do not necessarily mean a hundred pots. The method used to estimate vessel numbers needs to be stated, and different measures may answer different questions."},{"type":"paragraph","text":"The guidance also recommends retaining the relationship between pottery and its contextual unit. That connection makes it possible to compare material from different deposits or structural areas. A spreadsheet of attractive vessel types without context would lose much of the archaeological value of the collection."},{"type":"paragraph","text":"Official catalogue descriptions of surface finds illustrate the range that may be present: pitchers, cooking vessels, dishes, bowls, lids and different surface treatments. Such lists can identify a promising assemblage, but surface collection does not provide the same chronological control as material recovered from recorded layers."},{"type":"heading","level":2,"text":"A settlement sequence through ceramics"},{"type":"paragraph","text":"George Dales’s first excavation report on Balakot offers a comparative example. The published abstract distinguishes an earlier occupation sequence from a later Harappan period and notes relationships between its pottery and ceramic traditions in Balochistan and the southern Indus region. The point was not simply that painted pottery existed there, but that excavation could place comparisons within a sequence."},{"type":"paragraph","text":"That distinction remains useful. Similar decoration may suggest a connection, yet it does not automatically show that a vessel was imported. Clay composition, manufacturing traces and the wider assemblage can support or challenge that interpretation. Appearance is evidence, but it is only one category of evidence."},{"type":"heading","level":2,"text":"The journey into the ground"},{"type":"paragraph","text":"A pottery group also reflects what happened after use. Material can be discarded, moved, broken again or incorporated into later construction. An assemblage from a fill may contain objects older than the event that created the fill. Its significance depends partly on understanding that history of deposition."},{"type":"paragraph","text":"For a public archive, the best explanation makes these relationships visible without overwhelming the reader with codes. A few carefully chosen examples can show the difference between a fabric group, a vessel form and a decorative treatment."},{"type":"paragraph","text":"The result is a richer picture of a settlement. Pottery becomes evidence for practices and connections rather than a collection of isolated motifs. The ordinary fragments matter because together, and in context, they allow questions that no single beautiful vessel can answer."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":"","district":"","relatedDistrictIds":["punjab-khanewal","punjab-lodhran"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-8671","major-doam-8669"],"relatedStoryIds":["story-from-sherd-to-published-argument","story-a-cooking-pot-and-its-traces-of-use","story-the-perforated-vessel-as-an-archaeological-puzzle"],"contentType":"archaeology","seo":{"title":"What a pottery assemblage can say about a settlement | Virsapur Archives","description":"A pottery assemblage reveals patterns that an isolated decorated vessel cannot. Recording fabric, form, quantity and context helps distinguish evidence of making, use and deposition from attractive speculation.","primaryKeyword":"archaeological pottery assemblages","socialTitle":"What a pottery assemblage can say about a settlement","socialDescription":"A pottery assemblage reveals patterns that an isolated decorated vessel cannot. Recording fabric, form, quantity and context helps distinguish evidence of making, use and deposition from attractive speculation."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Approaches to recording pottery","url":"https://www.archaeologists.net/work/toolkits/pottery/approaches-recording","publisher":"Chartered Institute for Archaeologists","accessDate":"2026-10-22"},{"title":"Excavations at Balakot,Pakistan,1973","url":"https://architexturez.net/doc/doi-10-1179/jfa-1974-1-1-2-3","publisher":"George F.Dales,Journal of Field Archaeology1974; abstract reproduced by Aζ South Asia","accessDate":"2026-10-22"},{"title":"Archaeological catalogue record8671","url":"https://doam.gov.pk/public/sites/8671","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Archaeological catalogue record8669","url":"https://doam.gov.pk/public/sites/8669","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"CIfAprofessionalmethodsrecording~185derivedwords noUKtypologytransferred. Dales1974abstract~95,fullpublisher403honest. DOAMsurfaceassemblageexamplesaggregate~75. RelatedDOAMsitesnotclaimedBalakot; Balakotexplicitcomparativeexcavatedcase.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Show why fragments, contexts and proportions matter more than a single attractive pot.","wordCount":465,"publicationHold":false,"sortOrder":129}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-hakra-phase-a-research-label-explained','the-hakra-phase-a-research-label-explained','review','{"id":"story-the-hakra-phase-a-research-label-explained","type":"story","slug":"the-hakra-phase-a-research-label-explained","title":"The Hakra phase: a research label explained","summary":"Hakra is an archaeological classification built from material evidence, not the securely known name of an ancient people. Its varied pottery and uneven dating require careful use of the label.","body":[{"type":"paragraph","text":"The expression Hakra phase can sound like the name of a clearly bounded period ruled by a known people. In archaeological use, it is a research classification derived from material evidence, especially pottery. It helps organise comparisons, but it should not be mistaken for a name recovered from an ancient community’s own written records."},{"type":"paragraph","text":"The distinction matters because labels travel easily from specialist reports into maps and popular histories. Once printed beside a coloured territory, a ceramic classification can begin to look like a political state. That visual certainty may be much stronger than the evidence on which the original term depended."},{"type":"heading","level":2,"text":"What is being grouped together?"},{"type":"paragraph","text":"Alessandro Ceccarelli and Cameron Petrie discuss the varied shapes, surface treatments and manufacturing techniques included within Hakra assemblages. Their review identifies major limitations: many defining collections came from surveyed, unexcavated sites, while secure stratigraphic evidence and absolute chronology remained uneven."},{"type":"paragraph","text":"The authors also caution that roughened or slurry-treated surfaces occur in several ceramic traditions. Such a treatment cannot reliably date a deposit by itself. This is a useful corrective to the idea that a single visually distinctive sherd always supplies an unambiguous cultural identity."},{"type":"paragraph","text":"Official archaeological catalogue entries from the wider Punjab record appliqué pottery assigned to the Hakra phase, sometimes alongside grey wares or burnished surfaces. These observations are valuable as records of what surveyors encountered. They do not by themselves establish a complete occupation sequence beneath the collected material."},{"type":"heading","level":2,"text":"From resemblance to a stronger argument"},{"type":"paragraph","text":"A stronger classification compares several attributes together. Form, fabric, decoration and manufacturing traces may support one another, while the excavated context helps establish their chronological relationship. One resemblance should not outweigh contradictory evidence from the rest of the assemblage."},{"type":"paragraph","text":"Ceccarelli and Petrie point to material from excavated early levels at Harappa and Jalilpur as useful for refining the discussion, while retaining questions about diversity and dating. The implication is not that the Hakra label should be discarded. It is that its meaning needs to remain connected to the evidence and purpose of a particular study."},{"type":"heading","level":2,"text":"A phase is not a person"},{"type":"paragraph","text":"People can share ways of making vessels without sharing a single government, language or identity. Conversely, a community can use more than one ceramic tradition. The passage from a pottery group to a social explanation therefore requires additional argument, not merely a change in terminology."},{"type":"paragraph","text":"For an atlas, this means that a Hakra attribution should be accompanied by a short explanation of its basis. Was the material collected on the surface or excavated? Which features were considered diagnostic? Is the date independently supported or inferred through comparison?"},{"type":"paragraph","text":"Those questions do not make the label unusable. They make it informative. Hakra becomes a way to explore patterns and unresolved relationships in early material culture, rather than a deceptively simple answer to who lived everywhere a particular kind of pottery has been found."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology","Punjab"],"province":"Punjab","district":"Leiah","relatedDistrictIds":["punjab-leiah"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-7980","major-doam-8159"],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"The Hakra phase: a research label explained | Virsapur Archives","description":"Hakra is an archaeological classification built from material evidence, not the securely known name of an ancient people. Its varied pottery and uneven dating require careful use of the label.","primaryKeyword":"Hakra phase archaeology","socialTitle":"The Hakra phase: a research label explained","socialDescription":"Hakra is an archaeological classification built from material evidence, not the securely known name of an ancient people. Its varied pottery and uneven dating require careful use of the label."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Cultural Evolutionary Paradigms and Technological Transformations","url":"https://easaa.org/wp-content/uploads/2023/01/Alessandro-Ceccarelli-1.pdf","publisher":"Alessandro Ceccarelli and Cameron A.Petrie","accessDate":"2026-10-22"},{"title":"Hakra-phase surface collection record7980","url":"https://doam.gov.pk/public/sites/7980","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Hakra-phase surface collection record8159","url":"https://doam.gov.pk/public/sites/8159","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"CeccarelliPetriepp10–11specificHakraargument~190derivedwords; avoidreuseelsewhereexcept<=10. DOAMtwoentries~75aggregate. Nofixedethnicity/dynasty/dateorallappliquereliablediagnostic. Surfaceobservationversussecurestratigraphyexplicit.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Clarify the term and limits of attribution rather than imply a bounded ethnic people.","wordCount":459,"publicationHold":false,"sortOrder":130}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-reading-kulli-material-culture-without-inventing-a-kingdom','reading-kulli-material-culture-without-inventing-a-kingdom','review','{"id":"story-reading-kulli-material-culture-without-inventing-a-kingdom","type":"story","slug":"reading-kulli-material-culture-without-inventing-a-kingdom","title":"Reading Kulli material culture without inventing a kingdom","summary":"Kulli describes a recognisable archaeological complex, not a kingdom whose borders and rulers are known. Settlement surveys reveal both shared forms and significant local differences.","body":[{"type":"paragraph","text":"Kulli is a useful archaeological term, but it can become misleading when treated as the name of a known kingdom. Recognisable objects and settlement patterns do not automatically supply a ruler, a capital or a political boundary. The term allows researchers to discuss relationships within material culture while leaving those larger social questions open."},{"type":"paragraph","text":"Ute Franke-Vogt’s account of fieldwork in southeastern Balochistan explains that the complex takes its name from the site of Kulli in Kolwa, investigated by Aurel Stein. Her team’s surveys found a substantial range of settlements associated with this material. Some occupied elevated positions; others formed compact groups on open ground."},{"type":"heading","level":2,"text":"Shared forms, different settlements"},{"type":"paragraph","text":"The survey describes arrangements of houses, lanes and terraces, with stone used in substantial construction. It also records dams associated with many settlements. This evidence widens the discussion beyond painted pots and animal imagery. Kulli-related communities were making places as well as objects."},{"type":"paragraph","text":"Variation within those places is important. A hilltop settlement and an open hamlet may participate in related practices without serving identical functions. Size, setting and internal arrangement should be considered before drawing conclusions about their relationship. A shared ceramic label is not a complete settlement hierarchy."},{"type":"paragraph","text":"Nindowari provides one substantial archaeological point of reference. The official catalogue records excavation under Jean-Marie Casal. Its place in a researched landscape should not, however, turn it automatically into the capital of an imagined Kulli state. That would require a different kind of argument."},{"type":"heading","level":2,"text":"Where categories overlap"},{"type":"paragraph","text":"Franke-Vogt’s discussion of Bakkar Buthi is particularly instructive. The site’s assemblage is predominantly Harappan in character but also includes Kulli elements. Excavated building phases and pottery-production waste add further context. The combination does not fit a simple map divided into mutually exclusive cultural territories."},{"type":"paragraph","text":"An assemblage can contain objects made through different traditions. Those objects might reflect exchange, local production, learning or several processes together. Choosing between these explanations requires attention to manufacture and context rather than treating the presence of a motif as a passport stamp."},{"type":"heading","level":2,"text":"What would demonstrate political organisation?"},{"type":"paragraph","text":"Questions about power remain legitimate. Differences in settlement scale, access to resources and investment in buildings may contribute to an interpretation. But each observation needs to be related to the others, and alternative explanations should be considered. Architectural prominence alone does not reveal a king’s name or the extent of his authority."},{"type":"paragraph","text":"The same restraint should shape visual presentation. A map can show known sites and the distribution of material without drawing a hard border around a hypothetical kingdom. A caption can identify a Kulli-associated vessel without assigning its maker a language that has not been established."},{"type":"paragraph","text":"Kulli’s importance does not depend on becoming a smaller version of a better-known civilisation. Its settlements and objects reveal a varied regional world with connections beyond it. Keeping the category flexible enough to accommodate that evidence makes the history more substantial, not less impressive."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology","Balochistan"],"province":"Balochistan","district":"","relatedDistrictIds":["balochistan-khuzdar"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["major-doam-8933"],"relatedStoryIds":["story-nindowari-and-the-kulli-cultural-landscape"],"contentType":"archaeology","seo":{"title":"Reading Kulli material culture without inventing a kingdom | Virsapur Archives","description":"Kulli describes a recognisable archaeological complex, not a kingdom whose borders and rulers are known. Settlement surveys reveal both shared forms and significant local differences.","primaryKeyword":"Kulli culture archaeology","socialTitle":"Reading Kulli material culture without inventing a kingdom","socialDescription":"Kulli describes a recognisable archaeological complex, not a kingdom whose borders and rulers are known. Settlement surveys reveal both shared forms and significant local differences."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Later Third Millennium BCE Sites","url":"https://www.harappa.com/content/6-later-third-millenium-bce-sites","publisher":"Ute Franke-Vogt,Archaeology of Southeastern Balochistan","accessDate":"2026-10-22"},{"title":"Nindowari","url":"https://doam.gov.pk/public/sites/8933","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Frankeprimarysurveyaccount~190derivedwords,selectsettlementdiversityandBakkarButhi,nogeneralabandonmentclaim. DOAM~35additional,cumulativewitharticle50~145. Guimetsourcearticle50notreused. Explicitlynoinventedkingdom/ruler/ethnicity.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Distinguish a material-culture grouping from unsupported political identities.","wordCount":465,"publicationHold":false,"sortOrder":131}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-togau-pottery-and-the-challenge-of-dating-regional-change','togau-pottery-and-the-challenge-of-dating-regional-change','review','{"id":"story-togau-pottery-and-the-challenge-of-dating-regional-change","type":"story","slug":"togau-pottery-and-the-challenge-of-dating-regional-change","title":"Togau pottery and the challenge of dating regional change","summary":"Togau pottery is recognised through a history of classification and comparison. Its decorative groups are useful research tools, but uncertain contexts prevent them from functioning as a simple universal clock.","body":[{"type":"paragraph","text":"Togau pottery is often introduced through recognisable painted designs, but its real archaeological interest lies in how those designs have been classified and dated. A sequence of motifs can look like a ready-made clock. It only becomes a reliable chronological tool, however, when the material has been connected to secure archaeological contexts."},{"type":"paragraph","text":"The official catalogue identifies Togau as a site in the Kalat region, named after a nearby hamlet. The relationship between a type-site and the pottery category named after it should be kept clear. The category can occur at many places; it is not confined to the settlement whose name it carries."},{"type":"heading","level":2,"text":"How the categories were built"},{"type":"paragraph","text":"Zahir Hussain and Kiran Shahid Siddiqui’s analytical study explains the importance of Beatrice de Cardi’s work at Anjira and Siah Damb in defining Togau groups. Decorative differences were used to distinguish stages conventionally labelled A, B, C and D. The authors also note difficulties caused by erosion and the need to combine evidence from different excavations."},{"type":"paragraph","text":"Their own survey observations in Panjgur found an uneven distribution of these types: some were prominent, others scarce or not clearly identified. Such variation matters. A group missing from a surface collection does not necessarily prove that the corresponding period was absent from the settlement."},{"type":"paragraph","text":"Surface visibility, sample size and the locations examined can all shape what enters a collection. A classification is strongest when its limits are stated alongside its diagnostic features. Otherwise, a useful comparison can harden into an assumption that every region followed the same sequence at the same pace."},{"type":"heading","level":2,"text":"Context is part of the object"},{"type":"paragraph","text":"The study also discusses Togau-type vessels in a private collection and acknowledges their likely illicit excavation. Attractive, relatively complete vessels may preserve decoration while losing the information needed to date their deposition. Recovering an object from the market cannot recover the layer from which it was removed."},{"type":"paragraph","text":"A contrasting example of documentation appears in Cambridge’s Museum of Archaeology and Anthropology. Its record for worked stone from Siah Damb includes an accession number, excavation information and a period attribution linked to de Cardi’s work. The object is not pottery, but the record shows how different kinds of finds can remain connected to an investigated sequence."},{"type":"heading","level":2,"text":"A chronology open to testing"},{"type":"paragraph","text":"For Togau, the productive question is therefore not which motif looks oldest in isolation. It is how decorative groups relate to manufacturing methods, associated finds and independently dated deposits. New evidence may confirm parts of an established sequence while requiring other parts to be revised."},{"type":"paragraph","text":"This makes the pottery more than a set of pleasing designs. It becomes evidence for how researchers construct regional histories from incomplete material. A careful public account should show the beauty of the vessels while making clear that their chronological value depends on relationships that an unprovenanced object, however impressive, cannot supply on its own."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology","Balochistan"],"province":"Balochistan","district":"Kalat","relatedDistrictIds":["balochistan-kalat"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["major-doam-9032"],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"Togau pottery and the challenge of dating regional change | Virsapur Archives","description":"Togau pottery is recognised through a history of classification and comparison. Its decorative groups are useful research tools, but uncertain contexts prevent them from functioning as a simple universal clock.","primaryKeyword":"Togau pottery chronology","socialTitle":"Togau pottery and the challenge of dating regional change","socialDescription":"Togau pottery is recognised through a history of classification and comparison. Its decorative groups are useful research tools, but uncertain contexts prevent them from functioning as a simple universal clock."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"The Case of Togau Ware:An Analytical Study","url":"https://ph.hu.edu.pk/public/uploads/vol-13/A%204.%20Zahir%20Hussain%20and%20Kiran%20Shahid%20Siddiqui.pdf","publisher":"Zahir Hussain and Kiran Shahid Siddiqui,Pakistan Heritage13","accessDate":"2026-10-22"},{"title":"Togau","url":"https://doam.gov.pk/public/sites/9032","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Siah Damb object1966.259B","url":"https://collections.maa.cam.ac.uk/objects/593890/","publisher":"Museum of Archaeology and Anthropology,University of Cambridge","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"HussainSiddiquiprimaryPanjgursurveyandcollectionreviewindexedfirstpagecloselyread~190derivedwords; directPDF502recorded. DOAM~45. Cambridgeexcavatedstoneobjectmetadata~45illustratescontextdocumentation,notTogaupotteryobject. Nochronologypresentedasuncontestedorunprovenancedcollectingendorsed.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Use a ceramic tradition to explain chronological comparison across settlements.","wordCount":456,"publicationHold":false,"sortOrder":132}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-why-an-unexcavated-mound-is-still-evidence','why-an-unexcavated-mound-is-still-evidence','review','{"id":"story-why-an-unexcavated-mound-is-still-evidence","type":"story","slug":"why-an-unexcavated-mound-is-still-evidence","title":"Why an unexcavated mound is still evidence","summary":"A mound can preserve valuable evidence before excavation. Surface survey and geophysics ask different questions, and their results should guide careful research rather than turn an archaeological place into a treasure target.","body":[{"type":"paragraph","text":"An unexcavated mound is not an empty page. Its shape, surface material and relationship to the surrounding landscape can already provide evidence. What it does not provide is unrestricted permission to imagine the buildings, people or events beneath it. The challenge is to ask questions that the available methods can answer without pretending that investigation has already revealed everything."},{"type":"paragraph","text":"Surface survey offers one starting point. Sidra Gulzar’s study of Ganweriwala explains how systematic examination of a site can record landscape, settlement form and the distribution of material. Such work can help researchers plan later investigation. Ganweriwala has now been excavated; its earlier survey remains a useful example of knowledge produced before trenches were opened."},{"type":"heading","level":2,"text":"Seeing a pattern without removing a layer"},{"type":"paragraph","text":"A concentration of pottery or building material can identify an area worth closer study. It does not automatically mark the precise boundary of an ancient house or workshop. Material may have moved through erosion, cultivation or later activity, and different parts of a surface may be unequally visible."},{"type":"paragraph","text":"Recording those conditions is therefore part of the evidence. A map of finds without information about how the survey was conducted can suggest a precision it does not possess. Repeated observations and a documented collection strategy make comparison more meaningful."},{"type":"heading","level":2,"text":"What geophysics measures"},{"type":"paragraph","text":"Historic England explains that the choice of geophysical technique depends on the expected target, its depth, the area to be covered and local conditions such as soils, geology and vegetation. There is no single instrument that reveals every kind of archaeological feature equally well."},{"type":"paragraph","text":"Oxford’s introduction makes another essential point: geophysical plots represent measured physical properties, such as electrical resistance or magnetism. They are not direct photographs of the past. A striking pattern may suggest a wall, ditch or other feature, but interpretation has to consider alternative explanations and the limits of the survey."},{"type":"paragraph","text":"An apparently blank result is equally easy to overread. Failure to detect a feature with one method does not establish that no archaeology exists. The question is whether the chosen technique and conditions were suitable for the kinds of remains being sought."},{"type":"heading","level":2,"text":"Preservation is an active decision"},{"type":"paragraph","text":"Leaving deposits in place can preserve relationships that future research may examine with better methods or different questions. Excavation is not the only meaningful sign that a site matters. Documentation, monitoring and protection from disturbance can be substantial forms of archaeological work."},{"type":"paragraph","text":"For a heritage atlas, the term unexcavated should therefore describe a dated research status, not a promise of hidden treasure. It should never encourage casual digging or collecting. Related sites may illustrate different stages of investigation rather than all sharing the same status."},{"type":"paragraph","text":"A mound’s value lies in the information it contains and the questions it can help answer. Recognising that value before excavation is one of the clearest ways to move from curiosity about ancient objects toward care for archaeological evidence."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":"","district":"","relatedDistrictIds":["punjab-bahawalpur","punjab-sheikhupura"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-7243","major-doam-6585"],"relatedStoryIds":["story-ganweriwala-a-major-site-still-demanding-research","story-archaeological-survey-versus-excavation","story-historic-archaeology-after-the-ancient-period"],"contentType":"archaeology","seo":{"title":"Why an unexcavated mound is still evidence | Virsapur Archives","description":"A mound can preserve valuable evidence before excavation. Surface survey and geophysics ask different questions, and their results should guide careful research rather than turn an archaeological place into a treasure target.","primaryKeyword":"archaeological mound significance","socialTitle":"Why an unexcavated mound is still evidence","socialDescription":"A mound can preserve valuable evidence before excavation. Surface survey and geophysics ask different questions, and their results should guide careful research rather than turn an archaeological place into a treasure target."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Harappan Cities:Landscape and Surface Survey at Ganweriwala","url":"https://easaa.org/wp-content/uploads/2023/01/Sidra-Gulzar-3.pdf","publisher":"Sidra Gulzar","accessDate":"2026-10-22"},{"title":"Geophysical Survey:Plotting Buried Traces of Human Activity","url":"https://historicengland.org.uk/research/methods/terrestrial-remote-sensing/geophysical-survey/","publisher":"Historic England","accessDate":"2026-10-22"},{"title":"Geophysics","url":"https://archeox.conted.ox.ac.uk/fact-sheets/pre-excavation-techniques/geophysics.html","publisher":"University of Oxford,Archaeology of East Oxford","accessDate":"2026-10-22"},{"title":"Ganweriwala excavation documentation","url":"https://uol.edu.pk/uols-soca-and-imbb-lead-the-audio-visual-documentation-and-genetic-analysis-of-ganweriwala-excavation/","publisher":"University of Lahore","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Gulzarprimarysurveymethodspassage~100derivedwords; HE~100; Oxford~100. UOLexact6wordsadditionalGanweriwalaexcavated,cumulativearticle81<=200. RelationshipGanweriwalaexplicitcomparisonofearlierpreexcavationknowledge,NOTassertcurrentlyunexcavated. NeitherrelatedPlaceassignednewstatus.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain survey evidence and uncertainty without pretending every mound has a known city plan.","wordCount":462,"publicationHold":false,"sortOrder":133}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-layers-cuts-and-fills-a-first-guide-to-stratigraphy','layers-cuts-and-fills-a-first-guide-to-stratigraphy','review','{"id":"story-layers-cuts-and-fills-a-first-guide-to-stratigraphy","type":"story","slug":"layers-cuts-and-fills-a-first-guide-to-stratigraphy","title":"Layers, cuts and fills: a first guide to stratigraphy","summary":"Stratigraphy reconstructs the order of archaeological events, including material added and ground removed. A simple hypothetical pit shows why depth alone cannot date a find.","body":[{"type":"paragraph","text":"Imagine a courtyard floor, a pit dug through it and soil later placed inside the pit. The floor came first, the digging happened next and the filling followed. All three belong to the archaeological sequence, but only two involve material added to the ground. The pit cut records removal. This simple example explains why stratigraphy is more than a stack of coloured layers."},{"type":"paragraph","text":"Archaeologists study the relationships between deposits, structures and cuts to reconstruct an order of events. A context is an individually recorded unit within that work. The terminology may sound technical, but its purpose is practical: to preserve observations clearly enough that another researcher can examine the argument."},{"type":"heading","level":2,"text":"A cut and its fill are not the same event"},{"type":"paragraph","text":"Historic England’s recording manual distinguishes a cut from the deposits that fill it. The shape of a pit belongs to the event that created the hollow; material inside may have accumulated through one or several later episodes. Treating both as a single undifferentiated feature would conceal that sequence."},{"type":"paragraph","text":"Return to the hypothetical courtyard. An old pottery fragment could be included in the soil used to fill the later pit. Its age would not make the pit older than the floor it cuts. The object’s manufacture and its final deposition are different moments."},{"type":"paragraph","text":"This is why depth alone is unreliable. The bottom of a later pit can lie below an earlier floor. Without recording the cut, a deep find may appear older simply because it lies lower. The physical relationship corrects that misleading impression."},{"type":"heading","level":2,"text":"Turning observations into an ordered argument"},{"type":"paragraph","text":"A Harris matrix represents earlier and later relationships in a diagram. Historic England’s guidance emphasises direct stratigraphic relationships and warns against adding connections that the evidence does not establish. The diagram is not a picture of the trench; it is an account of sequence."},{"type":"paragraph","text":"Two deposits at similar heights need not be contemporary. Conversely, parts of one deposit may be exposed in separate areas. Connecting them requires evidence and a stated basis, not just a convenient line on a chart. Where a relationship cannot be established, leaving the question open is more accurate than forcing an uninterrupted sequence."},{"type":"heading","level":2,"text":"Why the paperwork matters"},{"type":"paragraph","text":"The Museum of London’s field manual explains that excavation removes the contexts being investigated. Written descriptions, drawings, photographs and records of finds and samples therefore become essential evidence after the deposits are gone. Recording is not an administrative task added after discovery; it is part of the research itself."},{"type":"paragraph","text":"The hypothetical courtyard could support several later questions about rebuilding, use or abandonment. Those questions would be impossible to revisit if the pit and floor had simply been cleared without recording their relationship."},{"type":"paragraph","text":"Stratigraphy gives archaeological stories their sequence. It does not supply every date or explain every motive, but it establishes constraints that interpretations must respect. Learning to distinguish a layer, a cut and a fill is a first step toward understanding why careful excavation produces knowledge rather than merely exposing old things."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":"","district":"","relatedDistrictIds":["khyber-pakhtunkhwa-swat"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-bazira"],"relatedStoryIds":["story-bazira-barikot-and-the-evidence-of-a-long-lived-town","story-monasteries-and-towns-testing-an-economic-relationship","story-coins-in-context-a-date-is-not-the-whole-story","story-swat-beyond-a-single-buddhist-period"],"contentType":"archaeology","seo":{"title":"Layers, cuts and fills: a first guide to stratigraphy | Virsapur Archives","description":"Stratigraphy reconstructs the order of archaeological events, including material added and ground removed. A simple hypothetical pit shows why depth alone cannot date a find.","primaryKeyword":"archaeological stratigraphy","socialTitle":"Layers, cuts and fills: a first guide to stratigraphy","socialDescription":"Stratigraphy reconstructs the order of archaeological events, including material added and ground removed. A simple hypothetical pit shows why depth alone cannot date a find."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Excavation Recording Manual2018,modules2–3","url":"https://historicengland.org.uk/content/docs/research/historic-england-archaeological-recording-manual-2018","publisher":"Historic England","accessDate":"2026-10-22"},{"title":"Archaeological Site Manual,third edition1994,section3.1","url":"https://colat.org.uk/wp-content/uploads/2023/08/mol-site-manual-3rd-edition.pdf","publisher":"Museum of London Archaeology Service","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"HEmanual~185derivedwords cutfill/matrix/directrelationships; MOLAS~145recordinganddestructiveexcavation. Workedcourtyard/pitexampleoriginalhypotheticalnotassertedBarikottrench. RelatedBarikotislearningconnectiononly,noinventedlocalstratigraphy.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Teach the relationship between deposits and events using site-specific examples to be verified.","wordCount":474,"publicationHold":false,"sortOrder":134}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-radiocarbon-dates-are-ranges-not-birthdays','radiocarbon-dates-are-ranges-not-birthdays','review','{"id":"story-radiocarbon-dates-are-ranges-not-birthdays","type":"story","slug":"radiocarbon-dates-are-ranges-not-birthdays","title":"Radiocarbon dates are ranges, not birthdays","summary":"Radiocarbon dating estimates the age of a sampled organism, not automatically the founding year of a settlement. Calibration, context and reported uncertainty are essential parts of the result.","body":[{"type":"paragraph","text":"A radiocarbon result is sometimes turned into a headline announcing the exact age of a building or civilisation. That shortcut loses two essential distinctions. The laboratory measures a sample, and the result has uncertainty. Connecting it to a historical event requires an archaeological argument as well as a measurement."},{"type":"paragraph","text":"Oxford’s radiocarbon guidance explains that the method concerns carbon incorporated while an organism was alive. After death, radioactive decay changes the amount remaining. The resulting measurement is conventionally expressed in radiocarbon years before 1950, with an uncertainty. In this terminology, present does not move forward with the date on today’s calendar."},{"type":"heading","level":2,"text":"Why calibration is necessary"},{"type":"paragraph","text":"The amount of radiocarbon in the atmosphere has not remained constant. A radiocarbon age is therefore not simply a calendar year waiting to be subtracted from 1950. Calibration compares the result with material of known age to estimate possible calendar dates."},{"type":"paragraph","text":"Oxford’s explanation shows why this can produce more than one likely calendar interval. The shape of the calibration curve matters, as does measurement uncertainty. Reporting only a midpoint can hide the actual distribution and create an impression of precision that the analysis does not support."},{"type":"paragraph","text":"Historic England’s guidance recommends stating the calibration method and curve, together with the probability associated with the reported range. A range without its probability is incomplete information. The uncertainty is not an embarrassing weakness to remove; it is part of what the result means."},{"type":"heading","level":2,"text":"Which event has been dated?"},{"type":"paragraph","text":"Consider a hypothetical timber reused in a later structure. Dating its carbon would not automatically date the rebuilding. The relationship between the tree’s growth, the cutting of the timber and its eventual deposition would have to be considered. The same general question applies whenever sampled material may be older than the context in which it was found."},{"type":"paragraph","text":"A short-lived sample securely associated with an event can answer a different question from unidentified charcoal in mixed soil. Neither should be described simply as the date of the site. Sample identification and context belong beside the number in any serious interpretation."},{"type":"heading","level":2,"text":"Results that can be checked again"},{"type":"paragraph","text":"Historic England also stresses retaining the laboratory identifier, the uncalibrated result and its uncertainty. Calibration curves are refined over time, so a future researcher may need to revisit the calculation. A polished timeline that preserves only a rounded calendar year makes that work harder."},{"type":"paragraph","text":"For readers encountering early settlements such as Mehrgarh, the practical lesson is to ask what was sampled, where it came from and how the published date is expressed. A revised estimate need not mean that the site’s importance has disappeared; it may mean that the evidence has become better understood."},{"type":"paragraph","text":"Radiocarbon dating is powerful precisely because its assumptions and uncertainties can be examined. Treating dates as supported ranges rather than birthdays allows scientific evidence to strengthen history without pretending that it offers a certainty beyond its reach."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":"","district":"","relatedDistrictIds":["balochistan-kachhi"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["curated-mehrgarh"],"relatedStoryIds":["story-mehrgarh-before-the-indus-cities","story-early-farming-in-the-kachi-plain-evidence-rather-than-an-origin-myth","story-animal-bones-and-the-limits-of-ancient-menus","story-terracotta-figurines-without-invented-identities"],"contentType":"archaeology","seo":{"title":"Radiocarbon dates are ranges, not birthdays | Virsapur Archives","description":"Radiocarbon dating estimates the age of a sampled organism, not automatically the founding year of a settlement. Calibration, context and reported uncertainty are essential parts of the result.","primaryKeyword":"radiocarbon dating archaeology","socialTitle":"Radiocarbon dates are ranges, not birthdays","socialDescription":"Radiocarbon dating estimates the age of a sampled organism, not automatically the founding year of a settlement. Calibration, context and reported uncertainty are essential parts of the result."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Explanation of radiocarbon results","url":"https://c14new.arch.ox.ac.uk/explanation.php","publisher":"Oxford Radiocarbon Accelerator Unit","accessDate":"2026-10-22"},{"title":"Radiocarbon Dating","url":"https://c14.arch.ox.ac.uk/dating","publisher":"Oxford Radiocarbon Accelerator Unit","accessDate":"2026-10-22"},{"title":"Radiocarbon Dating and Chronological Modelling:Radiocarbon Dating","url":"https://historicengland.org.uk/images-books/publications/radiocarbon-dating-chronological-modelling/radiocarbon-dating/","publisher":"Historic England","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Oxfordtwoexplanatorypagesaggregate~185derivedwords includingorganismversususe,1950,calibrationmultipleranges. HE2022guidance~180reportingcalibrationprobabilitylabdata. No Mehrgarh new numericaldate/no counterfeitcalculation. Hypotheticaltimberexampleoriginal.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain calibration, sample context and uncertainty without a false precision narrative.","wordCount":460,"publicationHold":false,"sortOrder":135}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-seeds-from-a-trench-what-archaeobotany-asks','seeds-from-a-trench-what-archaeobotany-asks','review','{"id":"story-seeds-from-a-trench-what-archaeobotany-asks","type":"story","slug":"seeds-from-a-trench-what-archaeobotany-asks","title":"Seeds from a trench: what archaeobotany asks","summary":"Plant remains can reveal crop processing, fuel use and labour as well as food. Research at Harappa shows why seeds in a deposit should not be read as a straightforward ancient menu.","body":[{"type":"paragraph","text":"A charred seed from an excavation can seem like a direct message from an ancient meal. It may be evidence of food, but its route into the deposit needs investigation. A seed could arrive with processing waste, spilled grain, stored material or fuel. Archaeobotany asks how plants were used and how their remains survived, not merely which familiar foods can be named."},{"type":"paragraph","text":"A recent study of Harappa makes that distinction especially clear. The researchers examined relationships between grain and weed seeds in the assemblage. Their analysis suggests that crops often reached the city in an already well-processed condition, while burning animal dung introduced many small weed seeds into archaeological deposits."},{"type":"heading","level":2,"text":"The route from field to sample"},{"type":"paragraph","text":"That interpretation changes what a collection of seeds can mean. Small weeds need not represent plants deliberately gathered for human consumption. They may have passed through animals and entered a fire as part of fuel. The material still reveals human activity, but the activity is different from the one suggested by a simple food list."},{"type":"paragraph","text":"The Harappa study also records analytical limitations, including the difficulty of distinguishing some modern and ancient seeds without breaking them. Such decisions affect which material enters the final analysis. A published result is therefore inseparable from the procedures used to select and identify the evidence."},{"type":"paragraph","text":"This makes the sample record important. Where was the material found? How much sediment was examined? What was preserved and what was excluded? These questions help prevent a very small or unusual group of remains from being treated as representative of an entire city."},{"type":"heading","level":2,"text":"Looking beyond visible seeds"},{"type":"paragraph","text":"Kashyap and Weber’s pilot study at Farmana in Haryana explored a complementary form of evidence: microscopic starch grains. They examined surfaces including pottery, stone tools and dental calculus. Their report argues that reliance on larger charred remains alone can overlook plants whose useful parts do not readily survive that process."},{"type":"paragraph","text":"The Farmana work identified starches associated with several plant groups and linked observations to particular sampled surfaces. Those findings belong to Farmana; they should not be moved into Harappa’s record merely because both sites are associated with the Indus civilisation. The methodological comparison is valuable without inventing an identical diet."},{"type":"heading","level":2,"text":"From ingredients to work"},{"type":"paragraph","text":"Plant remains can also raise questions about where labour took place. If crops arrived at a settlement after substantial processing, some work may have occurred elsewhere. Establishing that possibility does not identify every worker or the terms of their labour, but it gives the investigation a more social dimension than a list of crops alone."},{"type":"paragraph","text":"The strongest public account therefore follows evidence through a chain of reasoning. Identification comes first, then consideration of preservation and deposition, and only then an interpretation of practice. Seeds can reveal a great deal, but they do not speak in complete recipes. Their value lies in the careful questions that make ordinary fragments informative about ancient lives."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":"","district":"","relatedDistrictIds":["punjab-sahiwal"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6579"],"relatedStoryIds":["story-harappa-after-the-excavation-trench","story-how-archaeologists-build-an-indus-chronology","story-what-changing-brick-sizes-can-and-cannot-prove","story-indus-exchange-without-a-modern-trade-map"],"contentType":"archaeology","seo":{"title":"Seeds from a trench: what archaeobotany asks | Virsapur Archives","description":"Plant remains can reveal crop processing, fuel use and labour as well as food. Research at Harappa shows why seeds in a deposit should not be read as a straightforward ancient menu.","primaryKeyword":"archaeobotany Indus","socialTitle":"Seeds from a trench: what archaeobotany asks","socialDescription":"Plant remains can reveal crop processing, fuel use and labour as well as food. Research at Harappa shows why seeds in a deposit should not be read as a straightforward ancient menu."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Taphonomy and labour at the Indus Valley site of Harappa3700–1300BC","url":"https://www.cambridge.org/core/journals/antiquity/article/taphonomy-and-labour-at-the-indus-valley-site-of-harappa-37001300-bc/55810416F25148D686092A0968D5AD6F","publisher":"Antiquity,primary archaeobotanical study","accessDate":"2026-10-22"},{"title":"Harappan plant use revealed by starch grains from Farmana,India","url":"https://antiquity.ac.uk/projgall/kashyap326","publisher":"Arunima Kashyap and Steve Weber,Antiquity Project Gallery","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Harappastudyresults/dungdiscussion~190derivedwords includingconditionalcropsarriveprocessed. Farmanaprimarypilot~155derivedwords,carefulnottransferplants/findstoHarappa. Noancientrecipeclaim or completefoodspectrum.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Distinguish crop remains, sampling and interpretation from assumptions about ancient diets.","wordCount":466,"publicationHold":false,"sortOrder":136}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-animal-bones-and-the-limits-of-ancient-menus','animal-bones-and-the-limits-of-ancient-menus','review','{"id":"story-animal-bones-and-the-limits-of-ancient-menus","type":"story","slug":"animal-bones-and-the-limits-of-ancient-menus","title":"Animal bones and the limits of ancient menus","summary":"Animal bones record more than meals. Species, skeletal parts, modification and deposition must be considered together before reconstructing husbandry, hunting or food consumption.","body":[{"type":"paragraph","text":"A pile of animal bones is not an ancient menu preserved in shorthand. Some remains may come from food preparation, but others can reflect craftwork, natural death, deliberate burial or later disturbance. Zooarchaeology begins by identifying the material and its context before deciding which human activities it represents."},{"type":"paragraph","text":"Historic England’s animal-bone handbook sets out the importance of recording species, skeletal parts, age indicators and modifications. Cut marks can contribute evidence for carcass processing, while weathering and scavenger damage help reconstruct what happened before burial. These observations need to be considered together rather than allowing one dramatic mark to determine the whole interpretation."},{"type":"heading","level":2,"text":"What is being counted?"},{"type":"paragraph","text":"Fragment numbers are affected by breakage. One bone can produce many pieces, and different parts of a skeleton preserve differently. A count of fragments therefore cannot be converted directly into the number of animals eaten, still less into portions served to a population."},{"type":"paragraph","text":"The handbook also emphasises that some processing activities leave more visible traces than others. An absence of cut marks is not automatically evidence that a carcass was untouched. Recording methods, preservation and the parts recovered all influence the result."},{"type":"paragraph","text":"This is one reason that recovery procedures matter. If small bones are missed, the apparent balance between large animals and smaller species can change. The assemblage is not simply what once existed; it is what survived, was recovered and could be identified."},{"type":"heading","level":2,"text":"Availability is not the same as use"},{"type":"paragraph","text":"Richard Meadow’s discussion of regional subsistence offers a useful comparison from Balakot. He notes that fish bones and mollusc shells were uncommon in earlier levels but much more abundant in the later Harappan phase. Proximity to coastal resources did not produce an identical pattern of exploitation throughout the site’s history."},{"type":"paragraph","text":"Meadow also stresses variation between settlements and phases, even where a broad agricultural foundation appears similar. Landscape creates possibilities and constraints, but people’s knowledge and decisions shape how those resources are used. An environmental map cannot by itself reconstruct a community’s diet."},{"type":"heading","level":2,"text":"Animals had lives before they became remains"},{"type":"paragraph","text":"Food is only one dimension of human-animal relationships. A study may also ask about management, movement, working lives or the use of non-food products. Those questions require evidence appropriate to them. Naming cattle in an assemblage does not, on its own, establish a particular dairy system or method of traction."},{"type":"paragraph","text":"For early farming places such as Mehrgarh, this distinction helps keep the discussion grounded. The aim is not to project modern menus or identities backward, but to understand the relationships supported by the material."},{"type":"paragraph","text":"An accessible archive article can explain the difference between identification and interpretation through a few well-recorded examples. The bones become more informative when their limitations are visible. Rather than offering a supposedly complete dinner table, they can reveal changing practices, selective survival and the work required to turn fragments into a history of human and animal lives."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":"","district":"","relatedDistrictIds":["balochistan-kachhi"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["curated-mehrgarh"],"relatedStoryIds":["story-mehrgarh-before-the-indus-cities","story-early-farming-in-the-kachi-plain-evidence-rather-than-an-origin-myth","story-radiocarbon-dates-are-ranges-not-birthdays","story-terracotta-figurines-without-invented-identities"],"contentType":"archaeology","seo":{"title":"Animal bones and the limits of ancient menus | Virsapur Archives","description":"Animal bones record more than meals. Species, skeletal parts, modification and deposition must be considered together before reconstructing husbandry, hunting or food consumption.","primaryKeyword":"zooarchaeology Pakistan","socialTitle":"Animal bones and the limits of ancient menus","socialDescription":"Animal bones record more than meals. Species, skeletal parts, modification and deposition must be considered together before reconstructing husbandry, hunting or food consumption."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Animal Bones and Archaeology:Recovery to Archive","url":"https://historicengland.org.uk/images-books/publications/animal-bones-and-archaeology/animal-bones-archaeology-handbook/","publisher":"Polydora Baker and Fay Worley,Historic England2019","accessDate":"2026-10-22"},{"title":"The use of animal remains at Harappa and related regional evidence","url":"https://www.harappa.com/sites/default/files/pdf/Harappa1986-90_07_Meadow-Fauna_0_1.pdf","publisher":"Richard H.Meadow,Harappa Excavations1986–1990","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"HEhandbookpp2–5,44–46,53–55read~190derivedwords. Meadowprimarychapterindexedpp89–90read~170derivedwords; PDFtoolsizeblocked,noentirechapterclaim. Mehrgarhrelationconceptualnoinventedmenu; Balakotcomparisonexplicitlysameauthorreported. No moderndiet/religionretrojection.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Explain identification and depositional bias rather than list foods without evidence.","wordCount":459,"publicationHold":false,"sortOrder":137}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-what-changing-brick-sizes-can-and-cannot-prove','what-changing-brick-sizes-can-and-cannot-prove','review','{"id":"story-what-changing-brick-sizes-can-and-cannot-prove","type":"story","slug":"what-changing-brick-sizes-can-and-cannot-prove","title":"What changing brick sizes can and cannot prove","summary":"Indus brick proportions reveal shared building practices, but they do not by themselves prove a central building authority. Dimensions, reuse and construction context all affect the interpretation.","body":[{"type":"paragraph","text":"A brick is an unusually modest object on which to build a large historical claim. Yet the proportions of Indus bricks are frequently used to discuss standardisation, urban organisation and political authority. The evidence is important, but the steps between a measured object and a model of government need to remain visible."},{"type":"paragraph","text":"The CSMVS museum’s record for a fired-clay brick from Moenjodaro introduces the familiar relationship of four to two to one in length, width and thickness. It also distinguishes examples of different absolute sizes. This is the first essential point: a ratio can remain similar while the dimensions change."},{"type":"heading","level":2,"text":"Proportion is not a single size"},{"type":"paragraph","text":"A small and a large rectangle can share the same proportions without being interchangeable building units. Recording only a ratio therefore loses information. Measurements, material, condition and architectural context should be retained so that comparisons can be checked."},{"type":"paragraph","text":"J. Mark Kenoyer’s study of Harappan measurement discusses variation in brick sizes and the difficulties created by reuse. Fired bricks could be incorporated into later structures, separating their manufacture from the date of the wall in which they were found. A wall containing old bricks is not necessarily an old wall."},{"type":"paragraph","text":"Kenoyer also cautions against treating uniform proportions as straightforward proof of a powerful central government enforcing building codes. Shared technical practices can spread through mechanisms other than a single administrative command. The existence of a pattern and the explanation for that pattern are separate propositions."},{"type":"heading","level":2,"text":"What a change might mean"},{"type":"paragraph","text":"A change in dimensions could relate to production, building requirements, repair or the reuse of available material. It might also form part of a broader social change. The point is not that political interpretation is impossible, but that a measurement alone cannot choose among all these explanations."},{"type":"paragraph","text":"The strongest argument would examine a securely dated sequence of structures and compare evidence from more than one area. If measurements are taken from loose rubble or mixed deposits, the uncertainty should be stated. A graph can look precise while combining bricks that never belonged to the same building episode."},{"type":"heading","level":2,"text":"Looking at the work of building"},{"type":"paragraph","text":"The museum record draws attention to the interlocking arrangement of bricks in walls. This reminds us that a unit was designed to work with others. Proportion has practical consequences for joining courses and negotiating corners; it is not only an abstract symbol of order."},{"type":"paragraph","text":"Specialised shapes raise further questions about particular construction tasks. Rather than forcing every brick into one ideal standard, a useful study asks what a builder needed the unit to do. Material choices and placement can be as informative as dimensions."},{"type":"paragraph","text":"Indus brickwork remains impressive when these qualifications are retained. Its value is not weakened by abandoning an automatic equation between standardisation and central power. Careful measurement can reveal shared knowledge, variation and repeated rebuilding, allowing a commonplace object to illuminate urban life without making it carry more historical certainty than it can support."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":"","district":"","relatedDistrictIds":["punjab-sahiwal","sindh-larkana"],"provinceRegionIds":["punjab","sindh"],"relatedHeritageIds":["major-doam-6579","unesco-138"],"relatedStoryIds":["story-wells-mohenjodaro","story-mohenjodaro-lanes","story-mohenjodaro-architecture","story-priest-king"],"contentType":"archaeology","seo":{"title":"What changing brick sizes can and cannot prove | Virsapur Archives","description":"Indus brick proportions reveal shared building practices, but they do not by themselves prove a central building authority. Dimensions, reuse and construction context all affect the interpretation.","primaryKeyword":"Indus brick proportions","socialTitle":"What changing brick sizes can and cannot prove","socialDescription":"Indus brick proportions reveal shared building practices, but they do not by themselves prove a central building authority. Dimensions, reuse and construction context all affect the interpretation."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Measuring the Harappan world:Insights into the Indus order and cosmology","url":"https://www.harappa.com/sites/default/files/pdf/Kenoyer%202010%20Measuring%20the%20Harappan%20World.pdf","publisher":"J.Mark Kenoyer,Cambridge University Press2010","accessDate":"2026-10-22"},{"title":"Harappan Brick,accessionIV10","url":"https://networksofthepast.csmvs.in/object/harappan-brick/","publisher":"Chhatrapati Shivaji Maharaj Vastu Sangrahalaya","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Kenoyer2010pp118–119~190derivedwords includingratio/absolutes/reuse/centralisedgovernmentcaution. CSMVSrecord~80derivedwords object/material/dateanddimensions. Noexactcitywidepoliticalcollapseinference. Do notreuseKenoyer2010forotherdraftswithoutbudget.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Assess standardisation as archaeological evidence without treating every ratio as a political code.","wordCount":468,"publicationHold":false,"sortOrder":138}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-indus-exchange-without-a-modern-trade-map','indus-exchange-without-a-modern-trade-map','review','{"id":"story-indus-exchange-without-a-modern-trade-map","type":"story","slug":"indus-exchange-without-a-modern-trade-map","title":"Indus exchange without a modern trade map","summary":"Evidence for Indus exchange can connect materials to sources without revealing the exact route or terms of a transaction. Geological and isotope studies help distinguish different kinds of movement.","body":[{"type":"paragraph","text":"A map of ancient exchange often uses arrows that resemble modern shipping routes. The arrows are easy to understand, but they can imply more than the evidence establishes. An object may connect a settlement with a raw-material source without telling us which path it followed, how many hands it passed through or what was exchanged for it."},{"type":"paragraph","text":"Randall Law’s study of Harappa’s rock and mineral assemblage provides a useful alternative. It compares archaeological material with samples from potential geological sources. The resulting connections are not all presented with the same confidence. His summary distinguishes firm analytical assignments from reasonable but less directly tested inferences."},{"type":"heading","level":2,"text":"A line is an argument"},{"type":"paragraph","text":"Law explicitly explains that the pathways drawn on his maps are conjectural. A solid line can indicate strong evidence for a material-source relationship without documenting the exact road, river journey or coastal passage. This is a small cartographic distinction with large consequences for interpretation."},{"type":"paragraph","text":"The study of steatite illustrates why source research is necessary. Potential deposits occur in several regions, and appearance alone cannot securely choose among them. Comparing the archaeological objects with geological samples supplies a more disciplined basis for an acquisition argument."},{"type":"paragraph","text":"Even a strong match does not reveal the complete transaction. Material might move directly, through intermediaries or after being partly worked. Those possibilities require other evidence. A map should not silently turn a source attribution into proof that a named city controlled a distant quarry."},{"type":"heading","level":2,"text":"Objects and people leave different traces"},{"type":"paragraph","text":"A 2013 study by Kenoyer, Price and Burton explored another approach: isotope analysis of tooth enamel from individuals buried at Harappa and Ur. Its published abstract presents the work as a preliminary investigation of whether non-local people and movement could be identified more directly."},{"type":"paragraph","text":"That is a different question from the geological origin of a bead. The movement of an object does not require its maker to travel with it, and the movement of a person does not identify their occupation. An isotope result should not be converted into a biography of a merchant without further support."},{"type":"heading","level":2,"text":"What exchange evidence can make visible"},{"type":"paragraph","text":"Taken together, these approaches widen the history beyond a list of exotic goods. They can illuminate changing access to materials, connections between regions and the mobility of people. They also reveal how much remains unknown about the institutions and everyday arrangements through which those connections operated."},{"type":"paragraph","text":"For an atlas reader, a useful exchange map would identify the kind of evidence behind each connection and the period to which it belongs. It would separate a confirmed material source from a suggested route and avoid combining many centuries into one supposedly simultaneous network."},{"type":"paragraph","text":"The Indus world does not need a modern-looking trade diagram to appear connected. Its relationships become more compelling when the evidence is allowed to retain different levels of certainty. A carefully explained line can then open a question about movement instead of closing it with an invented itinerary."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":"","district":"","relatedDistrictIds":["punjab-sahiwal","balochistan-gwadar"],"provinceRegionIds":["punjab","balochistan"],"relatedHeritageIds":["major-doam-6579","major-doam-8639"],"relatedStoryIds":["story-harappa-after-the-excavation-trench","story-sutkagen-dor-an-indus-place-far-from-the-core-cities","story-how-archaeologists-build-an-indus-chronology","story-seeds-from-a-trench-what-archaeobotany-asks"],"contentType":"archaeology","seo":{"title":"Indus exchange without a modern trade map | Virsapur Archives","description":"Evidence for Indus exchange can connect materials to sources without revealing the exact route or terms of a transaction. Geological and isotope studies help distinguish different kinds of movement.","primaryKeyword":"Indus trade evidence","socialTitle":"Indus exchange without a modern trade map","socialDescription":"Evidence for Indus exchange can connect materials to sources without revealing the exact route or terms of a transaction. Geological and isotope studies help distinguish different kinds of movement."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Summary and Discussion,Inter-Regional Interaction and Urbanism","url":"https://www.harappa.com/content/summary-and-discussion-concluding-remarks","publisher":"Randall Law","accessDate":"2026-10-22"},{"title":"Steatite Acquisition Networks","url":"https://www.harappa.com/content/steatite-acquisition-networks","publisher":"Randall Law","accessDate":"2026-10-22"},{"title":"A new approach to tracking connections between the Indus Valley and Mesopotamia","url":"https://architexturez.net/doc/az-cf-176037","publisher":"J.Mark Kenoyer,T.Douglas Price,James H.Burton,Journal of Archaeological Science2013","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Law2011bookand2024introductionsconservativelysameworkaggregate~190derivedwords:analyticalsourcecomparison,solid/dashedlines,conjecturalpathways,steatite. Isotopeprimaryabstract~110,nofullpaperclaimorconfirmedindividualHarappanmerchantinUr. Distinctmovementobjects/people explanatoryanalysis.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Separate sourced objects and routes from speculative lines joining ancient cities.","wordCount":469,"publicationHold":false,"sortOrder":139}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-meluhha-reading-a-name-across-different-kinds-of-evidence','meluhha-reading-a-name-across-different-kinds-of-evidence','review','{"id":"story-meluhha-reading-a-name-across-different-kinds-of-evidence","type":"story","slug":"meluhha-reading-a-name-across-different-kinds-of-evidence","title":"Meluhha: reading a name across different kinds of evidence","summary":"Meluhha connects Mesopotamian texts with arguments about the Indus world. The name, a translator’s seal and traded objects are complementary evidence, not a decipherment of the Indus script.","body":[{"type":"paragraph","text":"Meluhha is a name encountered in Mesopotamian written evidence, not a word securely read from an Indus inscription. That distinction is essential. The name is widely associated with the Indus region in discussions of third-millennium BCE connections, but the association rests on an argument combining texts, geography and material evidence."},{"type":"paragraph","text":"Gregory Possehl’s discussion of the Middle Asian interaction sphere places Meluhha alongside Dilmun and Magan in cuneiform accounts of maritime connections. He notes Sargon’s claim that ships from these places reached Akkad. Such references establish that Mesopotamian writers imagined and described a wider world, but they do not provide a modern map with surveyed boundaries."},{"type":"heading","level":2,"text":"The translator and the seal"},{"type":"paragraph","text":"One particularly evocative object is the cylinder seal of Shu-ilishu, identified in its inscription as an interpreter associated with Meluhha. Possehl’s separate account explains how the reading was checked again with a fresh impression. The episode makes scholarly verification visible: even a familiar object can benefit from returning to the original evidence."},{"type":"paragraph","text":"The same account retains an important limitation. The seal came through a nineteenth-century collection with little archaeological findspot information. Its inscription is meaningful, but the missing excavation context restricts what can be said about precisely where it was used or deposited."},{"type":"paragraph","text":"An interpreter’s existence suggests communication across a linguistic difference. It does not tell us everything about the language involved, the interpreter’s origins or the range of situations in which he worked. Those are tempting biographical questions, but the object does not answer them all."},{"type":"heading","level":2,"text":"Reading different evidence together"},{"type":"paragraph","text":"Objects found beyond the Indus region strengthen the broader discussion of contact. Possehl also describes how early classifications of seals required revision as archaeology in the Persian Gulf became better understood. Some pieces once grouped together because they looked Indian belonged to more complicated regional traditions."},{"type":"paragraph","text":"This is why a resemblance and a written place-name should not simply be added together as if they were identical kinds of proof. An inscription can name a place; an object can preserve materials, techniques and imagery. Their relationship has to be demonstrated, with attention to date and archaeological context."},{"type":"paragraph","text":"The electronic Sumerian dictionary’s entry for Meluhha provides a further reminder that the name belongs to a textual corpus. Its written occurrences can be studied without assuming that every use across all periods carried exactly the same geographical meaning."},{"type":"heading","level":2,"text":"Not a shortcut to decipherment"},{"type":"paragraph","text":"Possehl’s seal study explicitly distinguishes the readable cuneiform inscription from the undeciphered Indus writing system. The possibility that future bilingual evidence might help is not the same as possessing such a text. A translator mentioned in one script does not supply translations for signs in another."},{"type":"paragraph","text":"Meluhha is therefore best approached as a productive meeting point between evidence types. It opens questions about travel, language and how distant societies named one another. Keeping those distinctions visible allows the connection with the Indus world to remain compelling without turning a strong historical argument into an unsupported claim of complete certainty."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":"","district":"","relatedDistrictIds":["sindh-larkana"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["unesco-138"],"relatedStoryIds":["story-wells-mohenjodaro","story-mohenjodaro-lanes","story-mohenjodaro-architecture","story-priest-king"],"contentType":"archaeology","seo":{"title":"Meluhha: reading a name across different kinds of evidence | Virsapur Archives","description":"Meluhha connects Mesopotamian texts with arguments about the Indus world. The name, a translator’s seal and traded objects are complementary evidence, not a decipherment of the Indus script.","primaryKeyword":"Meluhha Indus identification","socialTitle":"Meluhha: reading a name across different kinds of evidence","socialDescription":"Meluhha connects Mesopotamian texts with arguments about the Indus world. The name, a translator’s seal and traded objects are complementary evidence, not a decipherment of the Indus script."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Shu-ilishu’s Cylinder Seal","url":"https://www.penn.museum/sites/expedition/shu-ilishus-cylinder-seal/","publisher":"Gregory L.Possehl,Penn Museum,2006","accessDate":"2026-10-22"},{"title":"The Middle Asian Interaction Sphere","url":"https://www.penn.museum/sites/expedition/the-middle-asian-interaction-sphere/","publisher":"Gregory L.Possehl,Penn Museum,2007","accessDate":"2026-10-22"},{"title":"Meluhha geographical-name entry","url":"https://oracc.museum.upenn.edu/epsd2/cbd/sux/o0046355.html","publisher":"Electronic Pennsylvania Sumerian Dictionary,ORACC","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Possehl2006fullread~185derivedwords sealreading/provenance/rechecking/undecipheredscript;2007distinctstudy~165Sargon/geography/sealclassification, overlappingtranslatorfactsnotdoublecounted. ORACClexicalentry~15. No definitiveancientselfname/bilingualtextclaim, no universalMeluhhaidentificationacrossallperiods.\nSource-led draft; factual and cultural editorial review required before publication.","editorialReason":"Compare textual and material arguments while keeping identification and certainty distinct.","wordCount":476,"publicationHold":false,"sortOrder":140}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-indus-script-why-short-texts-resist-easy-answers','the-indus-script-why-short-texts-resist-easy-answers','review','{"id":"story-the-indus-script-why-short-texts-resist-easy-answers","type":"story","slug":"the-indus-script-why-short-texts-resist-easy-answers","title":"The Indus script: why short texts resist easy answers","summary":"Short inscriptions offer patterns without an agreed translation. Reading Indus signs responsibly means separating what an object shows from what a proposed decipherment claims.","body":[{"type":"paragraph","text":"An Indus inscription can be immediately recognisable without being readable. Its signs invite comparison: an angular shape returns, a sequence resembles another, or an animal appears beneath a line of marks. Recognition, however, is not translation. A convincing account must explain how a proposed meaning was reached and whether the same method works beyond the example chosen to illustrate it."},{"type":"heading","level":2,"text":"Three different questions"},{"type":"paragraph","text":"What signs occur together? What kind of communication did they perform? What language, if any, did a particular sequence record? These are related questions, but answering the first does not automatically settle the others. In their 2009 study, Rajesh Rao and colleagues examined sequential patterns using a Markov model. Their work investigated statistical structure; it did not supply a generally accepted reading of individual inscriptions."},{"type":"paragraph","text":"The difficulty is partly the material available. The study identifies brevity, the absence of a known bilingual and uncertainty about the underlying language as obstacles. A very short sequence offers few opportunities to test a proposed grammar. Assigning a familiar word to one sign may feel persuasive, yet several incompatible explanations can fit an isolated example."},{"type":"heading","level":2,"text":"The object still speaks"},{"type":"paragraph","text":"This does not make an inscribed object archaeologically silent. Kenoyer and Meadow''s study of material excavated at Harappa between 1986 and 2007 places inscriptions within documented find contexts. Their approach demonstrates the value of asking where an object was recovered and what kind of object carried the marks, even when the marks cannot be translated."},{"type":"paragraph","text":"For an archive reader, the practical distinction is between an observation and its interpretation. “This sign appears twice” reports something checkable. “This sign names a king” introduces a linguistic and historical claim. The second needs additional evidence, not simply confidence or a visually attractive diagram."},{"type":"paragraph","text":"A useful decipherment proposal should therefore explain its sign readings consistently, identify exceptions and test previously unexamined inscriptions. A claim that changes its rules whenever a new object appears cannot be assessed in the same way as one that makes clear, repeatable predictions."},{"type":"paragraph","text":"At Harappa or Moenjodaro, uncertainty should sharpen attention rather than end it. Examine the relationship between inscription, image and surface. Ask whether a photograph shows an original object or a reproduced impression. Then keep the unresolved language question visible. The achievement of Indus communication does not depend on supplying a modern sentence where the evidence does not yet support one."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":null,"district":null,"relatedDistrictIds":["punjab-sahiwal","sindh-larkana"],"provinceRegionIds":["punjab","sindh"],"relatedHeritageIds":["major-doam-6579","unesco-138"],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"The Indus script: why short texts resist easy answers | Virsapur","description":"Short inscriptions offer patterns without an agreed translation. Reading Indus signs responsibly means separating what an object shows from what a proposed decipherment claims.","primaryKeyword":"Indus script undeciphered","socialTitle":"The Indus script: why short texts resist easy answers","socialDescription":"Short inscriptions offer patterns without an agreed translation. Reading Indus signs responsibly means separating what an object shows from what a proposed decipherment claims."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"A Markov model of the Indus script","url":"https://homes.cs.washington.edu/~rao/PNASIndus.pdf","publisher":"Rao and colleagues, University of Washington / PNAS","accessDate":"2026-10-22"},{"title":"Inscribed Objects from Harappa Excavations 1986–2007","url":"https://www.harappa.com/content/inscribed-objects-harappa-excavations-1986-2007","publisher":"Jonathan Mark Kenoyer and Richard H. Meadow / Harappa.com","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Explain the evidence problem and identify unsupported decipherment claims without endorsing one.","internalNotes":"Original review draft. Source-backed observations are distinguished from interpretive questions and hypothetical examples. Specialist editorial review required; no photography cleared. Sources include full-text pages and indexed primary-research abstracts; do not imply all referenced volumes were read in full.","sortOrder":141}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-seals-and-sealings-an-archaeological-distinction','seals-and-sealings-an-archaeological-distinction','review','{"id":"story-seals-and-sealings-an-archaeological-distinction","type":"story","slug":"seals-and-sealings-an-archaeological-distinction","title":"Seals and sealings: an archaeological distinction","summary":"A seal makes an impression; a sealing preserves one. That difference changes what each object can tell us about handling, authority and archaeological context.","body":[{"type":"paragraph","text":"A museum photograph can place an engraved seal beside a crisp impression and make them appear to be a single ancient discovery. They are not necessarily the same kind of evidence. The seal is the object used to create a mark. A sealing is material bearing that mark. Before interpreting either, establish what the catalogue actually describes."},{"type":"heading","level":2,"text":"Read the label before the image"},{"type":"paragraph","text":"The Metropolitan Museum of Art labels its Indus example as a stamp seal with a modern impression. The seal is catalogued as burnt steatite and assigned to the Mature Harappan period. The accompanying impression helps a viewer see the design, but its modern manufacture means it cannot independently demonstrate an ancient act of sealing."},{"type":"paragraph","text":"That distinction also affects orientation. A recessed design and the raised impression it produces are counterparts, not identical views. A reader comparing photographs needs to know which surface is shown before treating differences in direction as evidence about an inscription. Good documentation should make this clear rather than rely on visual familiarity."},{"type":"heading","level":2,"text":"Tool, action and surviving trace"},{"type":"paragraph","text":"The museum discusses stamp seals in relation to ownership and status. Those broad possibilities do not identify the owner of this particular object or reconstruct every occasion on which it was used. A seal could survive without the material it once marked. Conversely, an impression might survive when the tool that made it has disappeared."},{"type":"paragraph","text":"A simple analytical exercise helps. Imagine two otherwise similar discoveries: a seal found among accumulated settlement debris, and an impression recovered on material still associated with a container. The second situation would offer an additional connection between mark and use. This is a hypothetical comparison, not a report of a specific find at Chanhudaro. Its purpose is to show why archaeological association matters."},{"type":"paragraph","text":"Mackay''s account of the Chanhudaro excavations discusses different kinds of seal-like objects across occupation levels. It should be read as an early excavation report, not as a timeless explanation of every object''s purpose. Its classifications and historical language require critical assessment alongside the recorded material."},{"type":"paragraph","text":"The useful question is consequently not just “What does this symbol mean?” It is “What happened to this object, and which part of that history survives?” A catalogue that separates ancient tool, ancient trace and modern demonstration gives readers a firmer starting point. It also protects an attractive reconstruction from quietly becoming evidence for an event that has not actually been documented."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":null,"district":null,"relatedDistrictIds":["sindh-shaheed-benazir-abad"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-6464"],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"Seals and sealings: an archaeological distinction | Virsapur","description":"A seal makes an impression; a sealing preserves one. That difference changes what each object can tell us about handling, authority and archaeological context.","primaryKeyword":"Indus seals sealings","socialTitle":"Seals and sealings: an archaeological distinction","socialDescription":"A seal makes an impression; a sealing preserves one. That difference changes what each object can tell us about handling, authority and archaeological context."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Stamp seal and modern impression: unicorn and incense burner (?)","url":"https://www.metmuseum.org/art/collection/search/324062","publisher":"The Metropolitan Museum of Art","accessDate":"2026-10-22"},{"title":"Excavations at Chanhu-daro 1935–36","url":"https://www.harappa.com/content/excavations-chanhu-daro-1935-36","publisher":"Ernest Mackay / Smithsonian Institution, reproduced by Harappa.com","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Distinguish the tool from its impression and explain why find context changes interpretation.","internalNotes":"Original review draft. Source-backed observations are distinguished from interpretive questions and hypothetical examples. Specialist editorial review required; no photography cleared. Sources include full-text pages and indexed primary-research abstracts; do not imply all referenced volumes were read in full.","sortOrder":142}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-households-and-workshops-in-an-indus-settlement','households-and-workshops-in-an-indus-settlement','review','{"id":"story-households-and-workshops-in-an-indus-settlement","type":"story","slug":"households-and-workshops-in-an-indus-settlement","title":"Households and workshops in an Indus settlement","summary":"Craft debris helps identify production, but it does not automatically reveal a factory. Chanhudaro offers a starting point for distinguishing work processes from assumptions about labour.","body":[{"type":"paragraph","text":"A finished bead is evidence of an accomplished object. A partly worked stone, a drill or a scatter of production waste can answer a different question: how was the object made? For an Indus settlement, distinguishing those questions is essential before a cluster of finds is confidently labelled a workshop."},{"type":"heading","level":2,"text":"Reconstruct a process, not a modern workplace"},{"type":"paragraph","text":"Jonathan Mark Kenoyer''s study of Indus stone beads places Chanhudaro''s bead workshop within the history of archaeological research. It also explains why recording should consider material, shaping, drilling, surface treatment, wear and later alteration. Classification by appearance alone can conceal differences in how an object reached its surviving state."},{"type":"paragraph","text":"The implications extend beyond beads. A production sequence has stages, and different stages leave different traces. Finding material from one stage does not establish that every other stage occurred in the same room. Nor does a concentration of finished products necessarily identify a place of manufacture; it could prompt questions about storage, exchange or later disposal."},{"type":"paragraph","text":"Consider the distinction between a room''s last contents and its full history. A space used for work might later be cleared or filled with rubbish. A household might undertake a specialised task alongside other activities. These are analytical alternatives to investigate, not descriptions that can be assigned to every Indus house."},{"type":"heading","level":2,"text":"Why comparison needs restraint"},{"type":"paragraph","text":"Ethnoarchaeological work on bead-making at Khambhat provides a way to study the relationship between activities and the traces they leave. Such comparison is useful because it asks what waste, tools and working arrangements look like together. It does not establish that ancient workers had identical households, employment relationships or social identities."},{"type":"paragraph","text":"Calling a site a factory can import assumptions about permanent employees, central management and separated domestic space. Each assumption needs its own evidence. A more careful account can identify specialised production while leaving the organisation of labour open where the archaeological record does not decide it."},{"type":"paragraph","text":"For visitors reading a plan of Harappa or Chanhudaro, this changes the emphasis. Instead of looking only for an impressive room, ask how the excavation linked particular finds with particular surfaces and phases. Were objects recorded together, or assembled later under a broad site name? Does the interpretation concern making, using or discarding?"},{"type":"paragraph","text":"The most informative workshop story is not necessarily the grandest. It may describe a single operation clearly, distinguish debris from finished goods and explain why the relationship with neighbouring domestic space remains uncertain. That is a richer account of skilled labour than turning every concentration of craft material into the same modern industrial scene."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":null,"district":null,"relatedDistrictIds":["sindh-shaheed-benazir-abad","punjab-sahiwal"],"provinceRegionIds":["sindh","punjab"],"relatedHeritageIds":["major-doam-6464","major-doam-6579"],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"Households and workshops in an Indus settlement | Virsapur","description":"Craft debris helps identify production, but it does not automatically reveal a factory. Chanhudaro offers a starting point for distinguishing work processes from assumptions about labour.","primaryKeyword":"Indus craft workshops","socialTitle":"Households and workshops in an Indus settlement","socialDescription":"Craft debris helps identify production, but it does not automatically reveal a factory. Chanhudaro offers a starting point for distinguishing work processes from assumptions about labour."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Stone Beads of the Indus Tradition: New Perspectives on Harappan Bead Typology, Technology and Documentation","url":"https://www.harappa.com/sites/default/files/pdf/Kenoyer2017%20Stone%20Beads_Chapter%2007.pdf","publisher":"Jonathan Mark Kenoyer","accessDate":"2026-10-22"},{"title":"Ethnoarchaeological Excavations of the Bead Making Workshops of Khambhat","url":"https://www.harappa.com/sites/default/files/pdf/Kenoyer1991_Ethnoarchaeological%20Excavations%20of%20the%20Bead%20Maki.pdf","publisher":"Jonathan Mark Kenoyer and colleagues","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Investigate the evidence for production spaces rather than assume modern factory organisation.","internalNotes":"Original review draft. Source-backed observations are distinguished from interpretive questions and hypothetical examples. Specialist editorial review required; no photography cleared. Sources include full-text pages and indexed primary-research abstracts; do not imply all referenced volumes were read in full.","sortOrder":143}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-disputed-granaries-of-indus-archaeology','the-disputed-granaries-of-indus-archaeology','review','{"id":"story-the-disputed-granaries-of-indus-archaeology","type":"story","slug":"the-disputed-granaries-of-indus-archaeology","title":"The disputed granaries of Indus archaeology","summary":"Harappa''s so-called granary shows how a familiar building name can outlive the evidence for its function. The monument remains important even when its interpretation changes.","body":[{"type":"paragraph","text":"A name can become the most durable part of a ruin. Once a building appears on maps and in schoolbooks as a granary, visitors begin to see its walls as proof of grain storage. At Harappa, the question should run in the opposite direction: what evidence supports the name?"},{"type":"heading","level":2,"text":"A building and an interpretation"},{"type":"paragraph","text":"Jonathan Mark Kenoyer''s account identifies the so-called granary on Mound F as a substantial brick structure organised in two rows of rooms beside a passage. He also notes the absence of the concentrations of burnt grain or storage vessels that would help establish the proposed function. The granary interpretation relied on comparisons with buildings elsewhere, rather than a decisive local assemblage."},{"type":"paragraph","text":"This does not mean the surviving architecture is unimportant. It means that scale, construction and arrangement are observations, while “granary” is an interpretation placed upon them. The difference should remain visible in a caption, a tour or a digital reconstruction. Quotation marks can be useful when a conventional name is retained for recognition."},{"type":"heading","level":2,"text":"What would strengthen a functional argument?"},{"type":"paragraph","text":"A building''s function is more persuasive when several kinds of evidence agree. An architectural arrangement may suggest one activity, but contents, residues, access patterns and the sequence of alterations can support or complicate that suggestion. The absence of one expected feature is not automatically conclusive; preservation and the extent of excavation also matter."},{"type":"paragraph","text":"The appropriate response is therefore not to replace one confident name with another equally confident guess. Calling the structure a palace, temple or administrative centre without the necessary evidence would repeat the same mistake. A description can remain exact about the surviving walls while being cautious about the activities once performed above or between them."},{"type":"paragraph","text":"Harappa.com''s account of renewed excavation reports further investigation of this area without the discovery of grain that might settle the old label. That is a reminder that archaeological interpretation is revisable. New excavation can question an inherited explanation even when the outline of a building has long been familiar."},{"type":"paragraph","text":"For a visitor, a productive exercise is to separate three layers of information: what survives, what excavators reconstructed and what later interpreters proposed. A plan may show all three with similar visual authority unless its conventions are explained."},{"type":"paragraph","text":"The disputed granary is consequently not an embarrassment to archaeology. It is an example of its corrective work. The most responsible account does not promise certainty that the evidence cannot supply. It lets a major public structure remain a major public structure, while keeping the question of its precise use open to further investigation."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":null,"district":null,"relatedDistrictIds":["punjab-sahiwal","sindh-larkana"],"provinceRegionIds":["punjab","sindh"],"relatedHeritageIds":["major-doam-6579","unesco-138"],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"The disputed granaries of Indus archaeology | Virsapur","description":"Harappa''s so-called granary shows how a familiar building name can outlive the evidence for its function. The monument remains important even when its interpretation changes.","primaryKeyword":"Indus granary interpretation","socialTitle":"The disputed granaries of Indus archaeology","socialDescription":"Harappa''s so-called granary shows how a familiar building name can outlive the evidence for its function. The monument remains important even when its interpretation changes."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"“Granary,” Harappa","url":"https://www.harappa.com/indus/15.html","publisher":"Jonathan Mark Kenoyer / Harappa.com","accessDate":"2026-10-22"},{"title":"Granary Excavations Reveal New Facts","url":"https://www.harappa.com/blog/granary-excavations-reveal-new-facts","publisher":"Harappa.com","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Use changing interpretations to show why old building names need scrutiny.","internalNotes":"Original review draft. Source-backed observations are distinguished from interpretive questions and hypothetical examples. Specialist editorial review required; no photography cleared. Sources include full-text pages and indexed primary-research abstracts; do not imply all referenced volumes were read in full.","sortOrder":144}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-urban-change-after-the-mature-harappan-period','urban-change-after-the-mature-harappan-period','review','{"id":"story-urban-change-after-the-mature-harappan-period","type":"story","slug":"urban-change-after-the-mature-harappan-period","title":"Urban change after the Mature Harappan period","summary":"Changes after the Mature Harappan period need regional chronologies, not one dramatic ending. Environmental research helps explain pressures without reducing every settlement to the same story.","body":[{"type":"paragraph","text":"The end of a familiar urban pattern is not the same event as the disappearance of a population. When discussing change after the Mature Harappan period, that distinction prevents a sequence of regional developments from being compressed into one catastrophe."},{"type":"heading","level":2,"text":"Ask what changed, and where"},{"type":"paragraph","text":"A city can become smaller while nearby settlement continues. A craft tradition can change while some skills persist. A building can be abandoned without proving that its surrounding region became empty. These are different historical questions, and each requires evidence at an appropriate scale."},{"type":"paragraph","text":"Giosan and colleagues'' study of river landscapes offers one important line of investigation. Their analysis relates settlement distribution to changing environmental conditions and argues for a gradual process involving reduced flood intensity and an eastward shift of settlement. It challenges explanations that depend on a single abrupt arid event affecting every place in the same way."},{"type":"paragraph","text":"That argument should be presented as a research interpretation, not converted into a universal timetable. A regional model is valuable precisely because it can be tested against individual settlements. It does not eliminate the need to establish when particular buildings, activities or neighbourhoods changed."},{"type":"heading","level":2,"text":"Several clocks are running"},{"type":"paragraph","text":"Climate evidence, river history and archaeological phases are not interchangeable dates. A broad environmental trend may extend over a period much longer than the occupation of a single building. Before joining the two into a causal story, ask whether their dating is sufficiently close and whether the proposed mechanism fits the local evidence."},{"type":"paragraph","text":"The word “collapse” can obscure those intermediate steps. Does it describe changes in settlement size, political organisation, trade, construction or material culture? If the term remains undefined, almost any alteration can be made to support it. More specific language makes disagreement easier to understand and research easier to evaluate."},{"type":"paragraph","text":"For Harappa, the useful editorial task is therefore to assemble a sequence rather than invent a final day. A responsible site account should distinguish a regional historical framework from the evidence recovered at Harappa itself. It should also avoid treating every later object as either a complete survival of the urban past or proof of an entirely new population."},{"type":"paragraph","text":"This approach leaves room for difficult questions about livelihood, movement and adaptation. It does not romanticise change as effortless resilience, nor assume that every change was disastrous. It asks who or what continued, what became less viable and which aspects of the story are still unresolved."},{"type":"paragraph","text":"An archaeological landscape is rarely explained by a single falling curtain. Reading its transitions carefully can reveal more than the search for one spectacular ending."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":null,"district":null,"relatedDistrictIds":["punjab-sahiwal"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6579"],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"Urban change after the Mature Harappan period | Virsapur","description":"Changes after the Mature Harappan period need regional chronologies, not one dramatic ending. Environmental research helps explain pressures without reducing every settlement to the same story.","primaryKeyword":"Late Harappan transformation","socialTitle":"Urban change after the Mature Harappan period","socialDescription":"Changes after the Mature Harappan period need regional chronologies, not one dramatic ending. Environmental research helps explain pressures without reducing every settlement to the same story."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Fluvial landscapes of the Harappan civilization","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3387054/","publisher":"Liviu Giosan and colleagues / PNAS","accessDate":"2026-10-22"},{"title":"Fluvial landscapes of the Harappan civilization — bibliographic record","url":"https://pubmed.ncbi.nlm.nih.gov/22645375/","publisher":"US National Library of Medicine","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Replace a single-catastrophe collapse story with regional and chronological questions.","internalNotes":"Original review draft. Source-backed observations are distinguished from interpretive questions and hypothetical examples. Specialist editorial review required; no photography cleared. Sources include full-text pages and indexed primary-research abstracts; do not imply all referenced volumes were read in full.","sortOrder":145}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-coastal-sites-and-a-moving-shoreline','coastal-sites-and-a-moving-shoreline','review','{"id":"story-coastal-sites-and-a-moving-shoreline","type":"story","slug":"coastal-sites-and-a-moving-shoreline","title":"Coastal sites and a moving shoreline","summary":"Today''s distance from the sea is not an ancient harbour measurement. Coastal archaeology has to connect settlement evidence with a changing landscape.","body":[{"type":"paragraph","text":"A coastal site can lie inland today without having been equally distant from water in every earlier period. The reverse assumption is also unsafe: proximity to the present shoreline does not establish that a settlement was an ancient port. Maritime geography has to be reconstructed, not borrowed unchanged from a modern map."},{"type":"heading","level":2,"text":"Sutkagen Dor and the problem of distance"},{"type":"paragraph","text":"The University of California''s Archaeological Research Facility lists the 1992 volume Explorations on the Makran Coast, Pakistan: A Search for Paradise, edited by George Dales and Carl Lipo. That catalogue entry identifies a research route, not proof of an ancient harbour. A reader investigating Sutkagen Dor''s distance from water still needs to examine the underlying survey, mapped reconstruction and dating evidence before accepting a proposed shoreline."},{"type":"paragraph","text":"A harbour argument involves more than drawing a line between a ruin and the sea. It needs evidence about water access, the character of channels or landing places and the date of those conditions. A navigable route at one moment might not remain usable at another. A coastal exchange network also need not imply that every participating settlement possessed a monumental dock."},{"type":"heading","level":2,"text":"Do not make the map answer everything"},{"type":"paragraph","text":"Imagine a reconstruction showing an earlier shore nearer an archaeological site. That would make a maritime relationship more plausible, but it would not by itself identify the cargo, the people involved or the settlement''s administrative role. Those questions require additional archaeological evidence."},{"type":"paragraph","text":"Likewise, material arriving from elsewhere can demonstrate a connection without proving the exact route travelled. A destination and an origin do not fill in every intermediate journey. This distinction matters when attractive maps turn possible paths into solid, authoritative lines."},{"type":"paragraph","text":"The wider river-landscape research associated with Giosan and colleagues reinforces the importance of reading settlements within changing physical systems. Coastal sites and inland river sites present different problems, however; evidence from one cannot simply be transferred to the other."},{"type":"paragraph","text":"Sutkagen Dor and Banbhore should also not be blended into one undated maritime story. A comparative account needs to establish each site''s period and evidence independently before discussing similarities. Their presence in the same heritage itinerary does not make them contemporary."},{"type":"paragraph","text":"For an archive reader, the most useful map has a date, a stated basis and a visible distinction between observed features and reconstructed possibilities. A dotted route may be more honest than a confident arrow. The shoreline is part of the historical question, not a stable frame outside it."},{"type":"paragraph","text":"That perspective makes coastal archaeology more interesting: it treats settlement, water and movement as relationships that had to be maintained in a landscape that could change."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":null,"district":null,"relatedDistrictIds":["balochistan-gwadar","sindh-thatta"],"provinceRegionIds":["balochistan","sindh"],"relatedHeritageIds":["major-doam-8639","major-doam-5512"],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"Coastal sites and a moving shoreline | Virsapur","description":"Today''s distance from the sea is not an ancient harbour measurement. Coastal archaeology has to connect settlement evidence with a changing landscape.","primaryKeyword":"Indus coastal archaeology","socialTitle":"Coastal sites and a moving shoreline","socialDescription":"Today''s distance from the sea is not an ancient harbour measurement. Coastal archaeology has to connect settlement evidence with a changing landscape."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Explorations on the Makran Coast, Pakistan: A Search for Paradise — publication catalogue","url":"https://arf.berkeley.edu/publications/explorations-makran-coast-pakistan-search-paradise","publisher":"Archaeological Research Facility, University of California, Berkeley","accessDate":"2026-10-22"},{"title":"Fluvial landscapes of the Harappan civilization","url":"https://landscapepartnership.org/maps-data/climate-context/cc-resources/ClimateSciPDFs/PNASGiosanetalsmall.pdf/app-download-file/file/PNASGiosanetalsmall.pdf","publisher":"Liviu Giosan and colleagues / PNAS","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Explain why ancient maritime geography cannot be read directly from today’s coastline.","internalNotes":"Original review draft. Source-backed observations are distinguished from interpretive questions and hypothetical examples. Specialist editorial review required; no photography cleared. Sources include full-text pages and indexed primary-research abstracts; do not imply all referenced volumes were read in full.","sortOrder":146}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-gandhara-as-a-region-not-a-single-dynasty','gandhara-as-a-region-not-a-single-dynasty','review','{"id":"story-gandhara-as-a-region-not-a-single-dynasty","type":"story","slug":"gandhara-as-a-region-not-a-single-dynasty","title":"Gandhara as a region, not a single dynasty","summary":"Gandhara names a regional world that crossed political changes. Separating region, dynasty and artistic attribution makes its heritage easier to understand.","body":[{"type":"paragraph","text":"“Gandharan” and “Kushan” often appear together on museum labels, but they do not answer the same question. One can describe a regional cultural or artistic context; the other identifies a ruling dynasty and a historical period associated with it. Treating the words as synonyms makes a complicated history look simpler than it was."},{"type":"heading","level":2,"text":"Region is not ruler"},{"type":"paragraph","text":"The Metropolitan Museum of Art describes Gandhara within areas of present-day Pakistan and Afghanistan and places it within a succession of political formations. Its account discusses the Kushans'' importance alongside earlier rulers and wider commercial connections. The region''s history therefore cannot be reduced to the lifespan of one dynasty."},{"type":"paragraph","text":"The distinction is practical. A sculpture attributed to Gandhara is not, solely for that reason, securely dated to a particular king. A monument in the region may contain phases created under different political conditions. Place, date and patronage need to be established separately before they are joined into a narrative."},{"type":"paragraph","text":"Modern borders add another layer. They are useful for locating heritage institutions and planning an itinerary, but they should not be projected backwards as the boundaries of every ancient cultural network. Equally, calling a region interconnected does not mean its local differences disappeared."},{"type":"heading","level":2,"text":"What an attribution actually says"},{"type":"paragraph","text":"A catalogue may use “Gandhara” for a find location, a cultural attribution or an artistic classification. Those categories should not be silently exchanged. An object excavated at a named site carries a different kind of locational evidence from an unprovenanced object assigned to a region through stylistic comparison."},{"type":"paragraph","text":"A reader can test a label by asking three questions: where was the object found, when is it thought to have been made, and what supports that date? If one answer is uncertain, the uncertainty should remain attached to that answer rather than spreading into invented precision elsewhere."},{"type":"paragraph","text":"The same discipline helps when visiting Taxila or Takht-i-Bahi. Their place in a Gandharan heritage itinerary is an invitation to compare architecture, institutions and material evidence. It is not a claim that every visible wall was built in one uniform “Gandhara age”."},{"type":"paragraph","text":"Regional language remains useful when it illuminates relationships. It becomes misleading when it replaces chronology. A better account can acknowledge connections across the north-west while still distinguishing individual sites and phases."},{"type":"paragraph","text":"Gandhara is therefore best approached as a historical geography to investigate, not a single dynasty to memorise. That change in perspective allows both the shared visual vocabulary and the differences between places to remain visible."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":null,"district":null,"relatedDistrictIds":["khyber-pakhtunkhwa-haripur","punjab-rawalpindi","khyber-pakhtunkhwa-mardan"],"provinceRegionIds":["khyber-pakhtunkhwa","punjab"],"relatedHeritageIds":["unesco-139","unesco-140"],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"Gandhara as a region, not a single dynasty | Virsapur","description":"Gandhara names a regional world that crossed political changes. Separating region, dynasty and artistic attribution makes its heritage easier to understand.","primaryKeyword":"Gandhara historical region","socialTitle":"Gandhara as a region, not a single dynasty","socialDescription":"Gandhara names a regional world that crossed political changes. Separating region, dynasty and artistic attribution makes its heritage easier to understand."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Kushan Empire (ca. Second Century B.C.–Third Century A.D.)","url":"https://www.metmuseum.org/essays/kushan-empire-ca-second-century-b-c-third-century-a-d","publisher":"The Metropolitan Museum of Art","accessDate":"2026-10-22"},{"title":"Gandhara — collection terminology","url":"https://www.britishmuseum.org/collection/term/x21989","publisher":"The British Museum","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Separate a regional cultural label from changing rulers and modern borders.","internalNotes":"Original review draft. Source-backed observations are distinguished from interpretive questions and hypothetical examples. Specialist editorial review required; no photography cleared. Sources include full-text pages and indexed primary-research abstracts; do not imply all referenced volumes were read in full.","sortOrder":147}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-monasteries-and-towns-testing-an-economic-relationship','monasteries-and-towns-testing-an-economic-relationship','review','{"id":"story-monasteries-and-towns-testing-an-economic-relationship","type":"story","slug":"monasteries-and-towns-testing-an-economic-relationship","title":"Monasteries and towns: testing an economic relationship","summary":"A monastery and a nearby town can be closely connected without having identical histories. Their economic relationship has to be demonstrated through evidence, not inferred from proximity alone.","body":[{"type":"paragraph","text":"A hilltop monastery can look detached from ordinary economic life. That appearance is partly a consequence of where a visitor stands. Moving the question from a single ruin to its surrounding settlement landscape can reveal a more demanding subject: how religious institutions and towns were connected."},{"type":"heading","level":2,"text":"Two places, not one interchangeable site"},{"type":"paragraph","text":"UNESCO''s account of Takht-i-Bahi and Sahr-i-Bahlol distinguishes the monastic complex from the neighbouring fortified town. It identifies both as components of one World Heritage property. Their joint listing is significant, but it does not mean that every building belongs to the same moment or that the town''s entire economy can be reconstructed from the monastery."},{"type":"paragraph","text":"The paired sites encourage questions about movement, supplies, labour and patronage. Those are research questions, not conclusions supplied by distance alone. A nearby settlement might support several institutions; a religious establishment might draw resources from more than its closest neighbour."},{"type":"heading","level":2,"text":"What would demonstrate a relationship?"},{"type":"paragraph","text":"A donor inscription can provide a named act of patronage. A securely documented find distribution might suggest movement of objects. Evidence for production or storage can support an argument about activities. None should automatically be made to stand for a complete financial system."},{"type":"paragraph","text":"Pakistan''s Tentative List submission for Bazira-Barikot describes religious buildings within an urban setting alongside houses and production areas. It is a state-party nomination document, not an inscription decision. Its value here is the specific spatial question it raises: what changes when a sanctuary is studied as part of a town rather than pictured as an isolated retreat?"},{"type":"paragraph","text":"A plan can show that two activities occupied neighbouring spaces. Establishing that they operated together requires chronology as well. Otherwise, buildings from different periods may be assembled into an imaginary simultaneous city."},{"type":"heading","level":2,"text":"Reading the economic story carefully"},{"type":"paragraph","text":"The word “wealth” needs similar care. Elaborate construction can indicate substantial resources, but it does not identify everyone who supplied them or describe how benefits were distributed. A patron''s visibility in an inscription is not a complete census of the people whose labour sustained a place."},{"type":"paragraph","text":"For a heritage visitor, the most useful comparison is therefore between different kinds of evidence. Look at the institutional layout, then ask what the excavated settlement adds. Notice where a source records an activity and where an interpretation proposes a relationship."},{"type":"paragraph","text":"This approach does not make monasteries less spiritual. It places religious practice within the material conditions that made buildings, gatherings and maintenance possible. The relationship between town and monastery becomes a historical investigation, rather than a choice between sacred isolation and an equally simplistic picture of commercial enterprise."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Khyber Pakhtunkhwa","Archaeology"],"province":"Khyber Pakhtunkhwa","district":null,"relatedDistrictIds":["khyber-pakhtunkhwa-mardan","khyber-pakhtunkhwa-swat"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["unesco-140","major-bazira"],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"Monasteries and towns: testing an economic relationship | Virsapur","description":"A monastery and a nearby town can be closely connected without having identical histories. Their economic relationship has to be demonstrated through evidence, not inferred from proximity alone.","primaryKeyword":"Gandhara monastery economy","socialTitle":"Monasteries and towns: testing an economic relationship","socialDescription":"A monastery and a nearby town can be closely connected without having identical histories. Their economic relationship has to be demonstrated through evidence, not inferred from proximity alone."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Buddhist Ruins of Takht-i-Bahi and Neighbouring City Remains at Sahr-i-Bahlol","url":"https://whc.unesco.org/en/list/140/","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Bazira-Barikot — Tentative List submission","url":"https://whc.unesco.org/en/tentativelists/7034/","publisher":"Pakistan''s Permanent Delegation to UNESCO / UNESCO World Heritage Centre","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Investigate donations and settlement links rather than assume monasteries were isolated retreats.","internalNotes":"Original review draft. Source-backed observations are distinguished from interpretive questions and hypothetical examples. Specialist editorial review required; no photography cleared. Sources include full-text pages and indexed primary-research abstracts; do not imply all referenced volumes were read in full.","sortOrder":148}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-why-stupas-were-rebuilt-around-older-stupas','why-stupas-were-rebuilt-around-older-stupas','review','{"id":"story-why-stupas-were-rebuilt-around-older-stupas","type":"story","slug":"why-stupas-were-rebuilt-around-older-stupas","title":"Why stupas were rebuilt around older stupas","summary":"An enlarged stupa can preserve an older monument inside it. At Butkara I, successive building phases make sacred architecture a sequence rather than a single finished object.","body":[{"type":"paragraph","text":"A larger monument does not always replace a smaller one by clearing it away. Sometimes new construction encloses an earlier structure. For the archaeology of stupas, that relationship can turn an apparently unified form into evidence of successive decisions, repairs and acts of patronage."},{"type":"heading","level":2,"text":"The monument has a sequence"},{"type":"paragraph","text":"Research on Butkara I distinguishes several structural phases of its main stupa. Olivieri and Filigenzi discuss the site''s chronology through successive building periods rather than treating all surviving material as one commission. This is the essential point for a visitor: the form visible at the end of a sequence is not necessarily the form that began it."},{"type":"paragraph","text":"Enlargement can preserve an older core while changing the exterior and the experience of approaching it. A new surrounding surface or addition may belong to a different phase from the structure it touches. The relationship has to be read through archaeological evidence, not assumed from how neatly the surviving pieces appear to fit together."},{"type":"heading","level":2,"text":"Continuity without a single motive"},{"type":"paragraph","text":"Why enlarge rather than begin elsewhere? Continued investment in an established sacred focus is one possible interpretation. But the precise intention behind a particular rebuilding must not be supplied merely because that explanation sounds plausible. Construction can involve several motives, and the surviving evidence may not identify them all."},{"type":"paragraph","text":"The distinction between sequence and motive is important. A masonry relationship may demonstrate that one phase followed another. It does not by itself reveal the donor''s thoughts, the size of a congregation or the ceremony accompanying the work. Those claims need independent support."},{"type":"paragraph","text":"Dating presents a related challenge. Sculpture recovered near a monument is not automatically contemporary with its earliest core. An object may belong to an addition, a repair, a later deposit or material displaced during subsequent activity. A good interpretation explains the association instead of giving the whole complex one undifferentiated date."},{"type":"heading","level":2,"text":"What to look for in a reconstruction"},{"type":"paragraph","text":"A reconstruction should show which stage it represents. Combining the earliest plan with decoration or surrounding buildings from later phases can produce an attractive image of a moment that never existed. Colour-coded phases or separate drawings can make the argument more legible without pretending every detail is certain."},{"type":"paragraph","text":"Butkara I is therefore more than an illustration of a stupa''s shape. It offers a way to think about sacred architecture through time. The structure''s significance includes what communities retained, what they covered and what they added."},{"type":"paragraph","text":"Reading those changes carefully preserves the monument''s accumulated history. It avoids reducing a long-lived place to either an untouched original or a succession of meaningless alterations."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Khyber Pakhtunkhwa","Archaeology"],"province":"Khyber Pakhtunkhwa","district":null,"relatedDistrictIds":["khyber-pakhtunkhwa-swat","khyber-pakhtunkhwa-haripur"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-doam-3304","major-doam-823"],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"Why stupas were rebuilt around older stupas | Virsapur","description":"An enlarged stupa can preserve an older monument inside it. At Butkara I, successive building phases make sacred architecture a sequence rather than a single finished object.","primaryKeyword":"stupa building phases","socialTitle":"Why stupas were rebuilt around older stupas","socialDescription":"An enlarged stupa can preserve an older monument inside it. At Butkara I, successive building phases make sacred architecture a sequence rather than a single finished object."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Problems of Chronology in Gandhāran Art — Olivieri and Filigenzi","url":"https://iris.unive.it/retrieve/e4239ddd-70be-7180-e053-3705fe0a3322/4%2C%20Olivieri%20and%20Filigenzi%20Offprint.pdf","publisher":"Luca Maria Olivieri and Anna Filigenzi / Ca'' Foscari University repository","accessDate":"2026-10-22"},{"title":"The Geography of Gandharan Art","url":"https://iris.unive.it/retrieve/e4239ddd-6ce0-7180-e053-3705fe0a3322/The%20Geography%20of%20Gandharan%20Art.pdf","publisher":"Ca'' Foscari University repository","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Explain accumulated sacred construction through excavated phases.","internalNotes":"Original review draft. Source-backed observations are distinguished from interpretive questions and hypothetical examples. Specialist editorial review required; no photography cleared. Sources include full-text pages and indexed primary-research abstracts; do not imply all referenced volumes were read in full.","sortOrder":149}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-coins-in-context-a-date-is-not-the-whole-story','coins-in-context-a-date-is-not-the-whole-story','review','{"id":"story-coins-in-context-a-date-is-not-the-whole-story","type":"story","slug":"coins-in-context-a-date-is-not-the-whole-story","title":"Coins in context: a date is not the whole story","summary":"A coin''s issue date is not automatically a building''s construction date. Archaeological context determines which chronological question a coin can help answer.","body":[{"type":"paragraph","text":"A coin appears to offer the archaeologist an unusually precise object: a recognisable ruler, an issue or a date range. The temptation is to transfer that precision directly to the room in which it was found. The missing step is the history between the coin''s manufacture and its final deposition."},{"type":"heading","level":2,"text":"Three dates, three different events"},{"type":"paragraph","text":"A coin was made, used and eventually deposited. Those events need not be close together. A worn or retained object can enter a context later than its issue date; material from an older deposit can also be moved into a newer one. A date on an object therefore does not automatically date every surrounding feature."},{"type":"paragraph","text":"The chronological principle often described as a terminus post quem is a lower boundary: a secure deposit containing an object cannot predate that object''s manufacture. It is not a statement that deposition happened immediately afterwards. Research on residual coins in other archaeological settings makes this distinction explicit and demonstrates why context cannot be omitted from interpretation."},{"type":"heading","level":2,"text":"Barikot''s chronological framework"},{"type":"paragraph","text":"The numismatic study of Barikot emphasises recorded find locations and stratigraphic contexts. Research on the site''s revised cultural sequence also draws on radiocarbon dating. Together, these sources illustrate a stronger approach than asking one coin to carry the entire chronology: different evidence is assessed within the excavation''s sequence."},{"type":"paragraph","text":"This does not mean radiocarbon dates and coin dates can simply be averaged. Each concerns different material and has its own relationship to the event being studied. The analytical task is to explain why a sample or object belongs to a particular phase and how its date constrains that phase."},{"type":"paragraph","text":"Consider a hypothetical coin in the fill beneath a later floor. It might help establish that the fill was deposited after a certain point. It would not, without further evidence, identify the exact year the floor was laid or prove who commissioned the building. A coin found loose on an exposed surface presents a different evidential situation again."},{"type":"heading","level":2,"text":"What a useful label should tell you"},{"type":"paragraph","text":"A museum or site label becomes more informative when it separates identification from archaeological association. “Coin of this ruler” is one statement. “Recovered in this documented context” is another. The argument linking that context with a building phase should remain visible."},{"type":"paragraph","text":"For visitors to Swat''s archaeological sites, coins are consequently best read as participants in a chronology rather than miniature calendars attached to walls. Their value grows when the excavation records survive with them."},{"type":"paragraph","text":"The most precise historical account is not always the one with the most exact-looking year. It is the one that explains which event is dated and why."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":null,"district":null,"relatedDistrictIds":["khyber-pakhtunkhwa-swat"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-bazira"],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"Coins in context: a date is not the whole story | Virsapur","description":"A coin''s issue date is not automatically a building''s construction date. Archaeological context determines which chronological question a coin can help answer.","primaryKeyword":"archaeological coin context","socialTitle":"Coins in context: a date is not the whole story","socialDescription":"A coin''s issue date is not automatically a building''s construction date. Archaeological context determines which chronological question a coin can help answer."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"A Numismatic History of Barikot: Catalogue and Analysis of the Coin Finds from the Excavations at Bīr-koṭ-ghwaṇḍai","url":"https://doi.org/10.2307/jj.30599548.27","publisher":"Scholarly numismatic catalogue / JSTOR","accessDate":"2026-10-22"},{"title":"A new revised chronology and cultural sequence of the Swat valley in the light of current excavations at Barikot","url":"https://www.sciencedirect.com/science/article/pii/S0168583X19303866","publisher":"Research article, Nuclear Instruments and Methods in Physics Research B","accessDate":"2026-10-22"},{"title":"Questions concerning the residuality of brooches and coins in Romano-British contexts","url":"https://onlinelibrary.wiley.com/doi/10.1111/ojoa.12205","publisher":"Oxford Journal of Archaeology","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Distinguish mint date, circulation and deposition before using a coin to date a building.","internalNotes":"Original review draft. Source-backed observations are distinguished from interpretive questions and hypothetical examples. Specialist editorial review required; no photography cleared. Sources include full-text pages and indexed primary-research abstracts; do not imply all referenced volumes were read in full.","sortOrder":150}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-reading-ashokas-edicts-as-material-objects','reading-ashokas-edicts-as-material-objects','review','{"id":"story-reading-ashokas-edicts-as-material-objects","type":"story","slug":"reading-ashokas-edicts-as-material-objects","title":"Reading Ashoka’s edicts as material objects","summary":"Ashoka''s edicts are carved surfaces in particular landscapes, not disembodied quotations. Their script, setting and physical arrangement matter alongside translation.","body":[{"type":"paragraph","text":"Reading an edict in translation can make its physical setting disappear. The words seem to arrive as a finished statement on a page, detached from the rock, the arrangement of lines and the landscape in which they were encountered. At Shahbazgarhi and Mansehra, an inscription is also a material intervention in a particular place."},{"type":"heading","level":2,"text":"The surface is part of the evidence"},{"type":"paragraph","text":"Pakistan''s Tentative List description of Shahbazgarhi identifies fourteen edicts on two boulders, written in Kharoshthi from right to left. It places them beside an ancient route connecting the Peshawar valley with other parts of the north-west. These details matter because an imperial text was not simply copied into an abstract literary space."},{"type":"paragraph","text":"The description is a state-party submission hosted by UNESCO, not proof that the site has been inscribed on the World Heritage List. That administrative distinction should remain separate from the historical importance of the monument."},{"type":"paragraph","text":"An inscription''s distribution across a rock raises questions about preparation, available surface and the practical work of carving. A transcription rearranged into printed paragraphs can assist reading while concealing those relationships. An edition and a photograph therefore perform different jobs; neither should be mistaken for a complete substitute for the object."},{"type":"heading","level":2,"text":"Address, audience and access"},{"type":"paragraph","text":"The presence of writing along a route does not establish that every passer-by could read it. It also does not tell us, without additional evidence, precisely how a text was explained, repeated or understood. Those questions are more interesting when they remain questions rather than becoming an imagined scene of universal literacy."},{"type":"paragraph","text":"The same caution applies to translation. A modern equivalent for an important term may help a reader, but it can also make a historical argument sound more familiar than it was. Comparing an edition''s notes with its translated text reveals where choices have been made."},{"type":"paragraph","text":"A careful heritage account should therefore identify the inscription being discussed, the edition or catalogue used and the limits of what is visible. It should distinguish missing letters from uncertain readings and avoid quietly completing damaged text as though every word survives."},{"type":"paragraph","text":"Visitors need not touch or trace a surface to appreciate these relationships. A respectful view of the rock, combined with a documented transcription, can show why line placement and physical condition matter."},{"type":"paragraph","text":"The edicts become richer when approached through both language and material. Ashoka''s historical significance remains important, but the site is not merely a stop in an emperor''s biography. It preserves evidence of how a message was made present in the landscape."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Khyber Pakhtunkhwa","Archaeology"],"province":"Khyber Pakhtunkhwa","district":null,"relatedDistrictIds":["khyber-pakhtunkhwa-mansehra","khyber-pakhtunkhwa-mardan"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-doam-136","major-doam-4621"],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"Reading Ashoka’s edicts as material objects | Virsapur","description":"Ashoka''s edicts are carved surfaces in particular landscapes, not disembodied quotations. Their script, setting and physical arrangement matter alongside translation.","primaryKeyword":"Ashokan rock edicts Pakistan","socialTitle":"Reading Ashoka’s edicts as material objects","socialDescription":"Ashoka''s edicts are carved surfaces in particular landscapes, not disembodied quotations. Their script, setting and physical arrangement matter alongside translation."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Shahbazgarhi Rock Edicts — Tentative List submission","url":"https://whc.unesco.org/en/tentativelists/1880","publisher":"Department of Archaeology and Museums / UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Mānsehrā Rock Edict 1","url":"https://gandhari.org/catalog/CKI0015","publisher":"Gandhari.org scholarly catalogue","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Connect text, script, carving and landscape rather than offer an emperor biography.","internalNotes":"Review draft; source-backed observations distinguished from analysis and hypothetical examples. Foreign methodological guidance is not represented as Pakistani law. No excavation, access, treatment or publicity claims inferred from general sources. Specialist editorial review and reference verification required.","sortOrder":151}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-kharoshthi-and-brahmi-in-the-north-west','kharoshthi-and-brahmi-in-the-north-west','review','{"id":"story-kharoshthi-and-brahmi-in-the-north-west","type":"story","slug":"kharoshthi-and-brahmi-in-the-north-west","title":"Kharoshthi and Brahmi in the north-west","summary":"Kharoshthi and Brahmi are writing systems, not interchangeable names for languages. Manuscripts and inscriptions help separate script, language and find context.","body":[{"type":"paragraph","text":"A script is a system for writing; a language is what is being written. The distinction sounds straightforward, yet heritage labels can blur it when unfamiliar names appear together. Kharoshthi, Brahmi and Gandhari should not be treated as three equivalent categories."},{"type":"heading","level":2,"text":"Begin with the catalogue''s separate fields"},{"type":"paragraph","text":"The University of Washington describes the British Library fragments as texts in the Gandhari language written in Kharoshthi script on birch bark. Each part of that description answers a different question: language, writing system and support. Keeping them separate makes the evidence easier to compare with an inscription carved on stone."},{"type":"paragraph","text":"The university also identifies uncertainty about the manuscripts'' exact findspot. That caution matters. A probable regional association is not the same as a documented excavation location, and the physical survival of a manuscript does not repair a gap in its archaeological provenance."},{"type":"paragraph","text":"Stefan Baums''s outline of Gandhari grammar explains the writing system within a linguistic study. It offers a reminder that identifying letter forms and understanding grammar are related but distinct scholarly tasks. Recognising a script in a photograph does not mean that the text has been read."},{"type":"heading","level":2,"text":"The north-west was not a single-script landscape"},{"type":"paragraph","text":"Research on an inscribed sherd from Barikot discusses an Aramaic-script object alongside other evidence of writing at the site, including Greek and Brahmi inscriptions. The point is not to assemble a decorative list of scripts. It is to recognise that a settlement''s writing practices can vary with period, object and purpose."},{"type":"paragraph","text":"A site label that says only “ancient inscription” loses those distinctions. A better description asks which script has been identified, which language is proposed, what dates the object and whether the reading is complete. Where a scholar is uncertain, the catalogue should retain that uncertainty."},{"type":"paragraph","text":"The coexistence of writing systems also does not prove that every inhabitant was multilingual or literate. A surviving inscription records a particular act of writing. Establishing who commissioned, produced or read it requires evidence beyond the existence of the marks themselves."},{"type":"paragraph","text":"For readers comparing the edicts at Mansehra with later manuscript traditions, this framework prevents an attractive but misleading straight line. Similar regional settings do not erase differences in chronology, medium or audience."},{"type":"paragraph","text":"The useful habit is to slow down at the label. Ask what each name denotes before turning it into a historical claim. Script, language and place can illuminate one another, but they should first be allowed to remain distinct."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":null,"district":null,"relatedDistrictIds":["khyber-pakhtunkhwa-mansehra","khyber-pakhtunkhwa-mardan"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-doam-136","major-doam-4621"],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"Kharoshthi and Brahmi in the north-west | Virsapur","description":"Kharoshthi and Brahmi are writing systems, not interchangeable names for languages. Manuscripts and inscriptions help separate script, language and find context.","primaryKeyword":"Kharoshthi Brahmi inscriptions","socialTitle":"Kharoshthi and Brahmi in the north-west","socialDescription":"Kharoshthi and Brahmi are writing systems, not interchangeable names for languages. Manuscripts and inscriptions help separate script, language and find context."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"The British Library Kharoṣṭhī Fragments","url":"https://asian.washington.edu/british-library-kharosthi-fragments","publisher":"University of Washington","accessDate":"2026-10-22"},{"title":"Outline of Gāndhārī Grammar","url":"https://gandhari.org/grammar","publisher":"Stefan Baums / Gandhari.org","accessDate":"2026-10-22"},{"title":"An Inscribed Sherd in Aramaic Script from Barikot, Pakistan","url":"https://www.journals.uchicago.edu/doi/10.1086/703097","publisher":"Michael Zellmann-Rohrer and Luca Maria Olivieri","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Compare writing systems and archaeological contexts without implying a single language per script.","internalNotes":"Review draft; source-backed observations distinguished from analysis and hypothetical examples. Foreign methodological guidance is not represented as Pakistani law. No excavation, access, treatment or publicity claims inferred from general sources. Specialist editorial review and reference verification required.","sortOrder":152}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-rock-art-motif-is-not-a-secure-date','rock-art-motif-is-not-a-secure-date','review','{"id":"story-rock-art-motif-is-not-a-secure-date","type":"story","slug":"rock-art-motif-is-not-a-secure-date","title":"Rock art: motif is not a secure date","summary":"A familiar animal or stupa shape does not supply a secure date for every rock carving. Rock-art interpretation depends on relationships, documentation and qualified comparisons.","body":[{"type":"paragraph","text":"A carved animal may look immediately recognisable while remaining difficult to date. The temptation is to identify the motif and attach a period to it, as though a familiar outline were a chronological label. Rock art along the Upper Indus calls for a more patient approach."},{"type":"heading","level":2,"text":"Similarity is a starting point"},{"type":"paragraph","text":"The Heidelberg Academy''s project describes a large and varied corpus of drawings and inscriptions distributed through the mountain region. Its scope spans very different periods and writing traditions. That breadth is precisely why the age assigned to one securely studied example cannot be transferred automatically to every similar mark."},{"type":"paragraph","text":"A visual resemblance can suggest a comparison. It does not establish that two carvings were made together, by the same community or for the same purpose. A simple shape may remain useful for a long time; a later maker may also encounter and respond to older imagery."},{"type":"paragraph","text":"The useful question is consequently not just “What does it resemble?” but “What additional relationship supports the proposed date?” An associated inscription, an overlap or a documented comparison may each contribute, but they do not all provide the same kind of information."},{"type":"heading","level":2,"text":"Relative order is not a calendar year"},{"type":"paragraph","text":"Where one marking demonstrably crosses another, it may help establish an order of making. The later mark must follow the earlier one at that intersection. This does not necessarily tell us whether the interval was brief or very long."},{"type":"paragraph","text":"A published study should make that relationship inspectable. If a sequence depends on an overlap, the photograph or drawing needs to show the relevant junction. If the dating depends on comparison, readers should be told what is being compared and why it is considered appropriate."},{"type":"paragraph","text":"Surface appearance should likewise not become an improvised clock for visitors. Colour, weathering and visibility require specialist assessment; they are not a licence to assign ages from a casual photograph. Nor should a carving be rubbed, wetted or traced to make it easier to see."},{"type":"paragraph","text":"For Hodar, Thalpan and other Upper Indus sites, the archive''s task is to preserve the distinction between an identified subject and an established date. A record may know the first more confidently than the second."},{"type":"paragraph","text":"This restraint does not make a carving less compelling. It allows the rock to retain a layered history rather than forcing every image into one convenient period. An honest date range, or an explicit unresolved date, can be the most informative part of the label."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Gilgit-Baltistan","Archaeology"],"province":"Gilgit-Baltistan","district":null,"relatedDistrictIds":["gilgit-baltistan-diamir","gilgit-baltistan-darel"],"provinceRegionIds":["gilgit-baltistan"],"relatedHeritageIds":["major-doam-8249","major-doam-8278","major-doam-8292"],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"Rock art: motif is not a secure date | Virsapur","description":"A familiar animal or stupa shape does not supply a secure date for every rock carving. Rock-art interpretation depends on relationships, documentation and qualified comparisons.","primaryKeyword":"rock art dating Pakistan","socialTitle":"Rock art: motif is not a secure date","socialDescription":"A familiar animal or stupa shape does not supply a secure date for every rock carving. Rock-art interpretation depends on relationships, documentation and qualified comparisons."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Rock Art and Inscriptions Along the Karakoram Highway","url":"https://www.hadw-bw.de/en/research/academy-program-projects/rock-paintings-and-inscriptions-along-the-karakorum-highway","publisher":"Heidelberg Academy of Sciences and Humanities","accessDate":"2026-10-22"},{"title":"Rock Art and Inscriptions in the Upper Indus","url":"https://storymaps.arcgis.com/stories/d5018abb97d34ac7ba3a3a84d0267e72","publisher":"Scholarly Upper Indus research presentation","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Explain stylistic dating and superimposition while avoiding confident dates for every carving.","internalNotes":"Review draft; source-backed observations distinguished from analysis and hypothetical examples. Foreign methodological guidance is not represented as Pakistani law. No excavation, access, treatment or publicity claims inferred from general sources. Specialist editorial review and reference verification required.","sortOrder":153}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-an-inscription-and-a-carving-may-have-different-histories','an-inscription-and-a-carving-may-have-different-histories','review','{"id":"story-an-inscription-and-a-carving-may-have-different-histories","type":"story","slug":"an-inscription-and-a-carving-may-have-different-histories","title":"An inscription and a carving may have different histories","summary":"An inscription beside an image may be a later addition rather than its original caption. The relationship has to be demonstrated on the rock itself.","body":[{"type":"paragraph","text":"An image with writing beside it resembles a captioned illustration. That familiar modern arrangement can mislead us when the surface is a rock visited and marked at different times. Physical proximity is an observation; contemporaneity is a separate claim."},{"type":"heading","level":2,"text":"A surface can accumulate"},{"type":"paragraph","text":"The Upper Indus research presentation discusses cases in which inscriptions and drawings overlap, helping establish relative sequence. It also raises the possibility that a later addition can engage with an earlier image. Such a relationship is more complex than an artist signing a newly completed picture."},{"type":"paragraph","text":"The Heidelberg Academy''s wider documentation identifies several writing traditions within the region''s rock-art corpus. Their presence demonstrates the breadth of the material under study, but a regional list cannot determine the relationship between two particular marks. That relationship must be established at the scale of the individual surface."},{"type":"paragraph","text":"One inscription might refer to a place, a visitor or a religious act without naming the adjacent image. Another might deliberately respond to something already present. These are alternatives to test against a reading and its physical context, not stories to assign on the strength of a pleasing composition."},{"type":"heading","level":2,"text":"How to read an illustrated record"},{"type":"paragraph","text":"Begin by checking whether a published drawing distinguishes separate markings or presents them as one unit. Does the photograph preserve the same spatial relationships? Are the scale, orientation and identifying numbers supplied? A cropped image can accidentally turn a complex surface into an apparently self-contained scene."},{"type":"paragraph","text":"Then examine the argument. If a scholar treats a text as a dedication, what in the reading supports that interpretation? If the carving is dated through the inscription, what establishes their association? The answer should involve more than “they are close together”."},{"type":"paragraph","text":"Damage creates another difficulty. A broken or obscured relationship should not be reconstructed silently in a caption. Readers need to know whether the relevant intersection survives, whether the transcription is partial and which elements remain uncertain."},{"type":"paragraph","text":"This is particularly useful when exploring places such as Thalpan through a digital archive. A record can connect related evidence without collapsing all of it into a single event. Separate identifiers and explanatory notes may preserve historical complexity better than one dramatic title."},{"type":"paragraph","text":"The result is not a less coherent story, but a different kind of coherence: a place repeatedly encountered and reinterpreted. The rock may record several histories of attention. Respecting their order allows later participants to remain visible without making them the original makers of everything beside their words."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Gilgit-Baltistan","Archaeology"],"province":"Gilgit-Baltistan","district":null,"relatedDistrictIds":["gilgit-baltistan-gilgit","gilgit-baltistan-diamir"],"provinceRegionIds":["gilgit-baltistan"],"relatedHeritageIds":["major-doam-7664","major-doam-8278"],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"An inscription and a carving may have different histories | Virsapur","description":"An inscription beside an image may be a later addition rather than its original caption. The relationship has to be demonstrated on the rock itself.","primaryKeyword":"rock inscriptions context","socialTitle":"An inscription and a carving may have different histories","socialDescription":"An inscription beside an image may be a later addition rather than its original caption. The relationship has to be demonstrated on the rock itself."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Rock Art and Inscriptions in the Upper Indus","url":"https://storymaps.arcgis.com/stories/d5018abb97d34ac7ba3a3a84d0267e72","publisher":"Scholarly Upper Indus research presentation","accessDate":"2026-10-22"},{"title":"Rock Art and Inscriptions Along the Karakoram Highway","url":"https://www.hadw-bw.de/en/research/academy-program-projects/rock-paintings-and-inscriptions-along-the-karakorum-highway","publisher":"Heidelberg Academy of Sciences and Humanities","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Show why nearby markings are not automatically contemporary.","internalNotes":"Review draft; source-backed observations distinguished from analysis and hypothetical examples. Foreign methodological guidance is not represented as Pakistani law. No excavation, access, treatment or publicity claims inferred from general sources. Specialist editorial review and reference verification required.","sortOrder":154}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-archaeological-survey-versus-excavation','archaeological-survey-versus-excavation','review','{"id":"story-archaeological-survey-versus-excavation","type":"story","slug":"archaeological-survey-versus-excavation","title":"Archaeological survey versus excavation","summary":"Survey and excavation answer different questions. Understanding their methods prevents a mapped site from being mistaken for a fully excavated settlement.","body":[{"type":"paragraph","text":"A site can be archaeologically known without having been extensively excavated. It may have been identified through a systematic surface survey, mapped through visible features or investigated by a limited programme of testing. Those distinctions should survive when research is condensed into a heritage description."},{"type":"heading","level":2,"text":"Different questions, different evidence"},{"type":"paragraph","text":"The US National Park Service''s explanation of site discovery distinguishes surface inspection, remote sensing, archival work and forms of testing. These methods can reveal where evidence is concentrated and help define the questions a later investigation might address. Excavation is not the automatic final step for every place identified."},{"type":"paragraph","text":"Survey often concerns relationships across an area. Excavation investigates deposits and features in the portion of ground actually opened. Neither method supplies an unrestricted view of the past. A surface pattern may be affected by visibility and later disturbance, while a trench offers detail from a necessarily limited location."},{"type":"paragraph","text":"Imagine a mound surveyed through scattered pottery and visible walls. That evidence may justify recording a settlement, but it does not establish the plan of every buried building. Conversely, a carefully excavated room cannot by itself describe the entire settlement around it. These are examples of scale, not claims about a particular Pakistani site."},{"type":"heading","level":2,"text":"Why excavation creates an archive"},{"type":"paragraph","text":"Oxford''s recording guidance stresses that excavation removes the deposits it investigates. Information missed during that process cannot simply be recovered by returning the soil to its earlier position. Recording is therefore part of the investigation itself, not an administrative task added afterwards."},{"type":"paragraph","text":"A useful report tells readers what was surveyed, what was excavated and how much remains unexamined. It should identify the methods used and the limitations of the resulting coverage. A map filled with confident outlines is not a substitute for that explanation."},{"type":"paragraph","text":"For heritage discovery, this matters when comparing sites with very different research histories. One may have many published trenches; another may be represented by survey observations. The difference in documentation should not be mistaken for a difference in historical importance."},{"type":"paragraph","text":"Nor should incomplete excavation be treated as an invitation for visitors to investigate independently. The point of understanding methods is to appreciate why controlled research and preservation matter, not to encourage collecting or digging."},{"type":"paragraph","text":"A good atlas can make these distinctions visible through clear notes. “Surveyed”, “tested” and “excavated” describe different kinds of knowledge. Retaining those words gives readers a more accurate account of both what archaeology has established and what a landscape still holds beyond the available record."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":null,"district":null,"relatedDistrictIds":["punjab-sheikhupura","punjab-bahawalpur"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6585","major-doam-7243"],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"Archaeological survey versus excavation | Virsapur","description":"Survey and excavation answer different questions. Understanding their methods prevents a mapped site from being mistaken for a fully excavated settlement.","primaryKeyword":"survey excavation difference","socialTitle":"Archaeological survey versus excavation","socialDescription":"Survey and excavation answer different questions. Understanding their methods prevents a mapped site from being mistaken for a fully excavated settlement."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"How Do Archeologists Find Sites?","url":"https://www.nps.gov/articles/000/how-do-archeologists-find-sites.htm","publisher":"US National Park Service","accessDate":"2026-10-22"},{"title":"Recording Guide","url":"https://archeox.conted.ox.ac.uk/www.archeox.net/sites/www.archeox.net/files/reports/Recording%20guide%20NEW.pdf","publisher":"University of Oxford, Archaeox","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Explain two distinct ways of producing evidence and their complementary limitations.","internalNotes":"Review draft; source-backed observations distinguished from analysis and hypothetical examples. Foreign methodological guidance is not represented as Pakistani law. No excavation, access, treatment or publicity claims inferred from general sources. Specialist editorial review and reference verification required.","sortOrder":155}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-how-a-site-plan-changes-what-visitors-see','how-a-site-plan-changes-what-visitors-see','review','{"id":"story-how-a-site-plan-changes-what-visitors-see","type":"story","slug":"how-a-site-plan-changes-what-visitors-see","title":"How a site plan changes what visitors see","summary":"A site plan is a selective argument in lines, not a transparent view of the past. Its key, phases and purpose determine how it should be read.","body":[{"type":"paragraph","text":"From above, a ruin can become wonderfully legible. Rooms connect, passages acquire direction and scattered walls form an apparent whole. Yet a site plan is not a window through time. It is a drawing made for a purpose, using conventions that decide what a reader can see."},{"type":"heading","level":2,"text":"Find the key before finding the building"},{"type":"paragraph","text":"The Archaeology Data Service asks deposited maps and plans to document their layers and drawing conventions. Historic England''s recording manual likewise treats conventions as part of archaeological documentation. Without that information, a broken line can be mistaken for a surviving wall, or an inferred continuation for an observed one."},{"type":"paragraph","text":"A useful first reading therefore begins outside the monument''s outline. Check the scale, orientation, date and legend. Ask whether the plan records exposed remains, reconstructs a phase or guides visitors through a modern site. These purposes can overlap, but they are not identical."},{"type":"paragraph","text":"A visitor route, for example, may cross an area differently from an ancient passage. A path included for access should not silently become evidence about historical circulation. The drawing needs to distinguish what it explains about the past from what it provides for the present."},{"type":"heading","level":2,"text":"More than one time on one sheet"},{"type":"paragraph","text":"Plans often bring together remains from several phases. Unless those phases are separated, a reader may imagine all the structures functioning at once. An apparently straightforward doorway might belong to an alteration, while a nearby wall predates the room it now appears to enclose."},{"type":"paragraph","text":"This is an interpretive problem, not a reason to distrust drawings. A well-labelled composite plan can be extremely useful. It becomes misleading only when its composite character disappears from the explanation."},{"type":"paragraph","text":"At complex sites such as Taxila or Moenjodaro, the best question is not “Where is the one correct plan?” but “Which part of the site, and which question, does this plan address?” Different scales can legitimately show different information. A regional map cannot carry every masonry junction; a detailed trench plan cannot substitute for a wider landscape."},{"type":"paragraph","text":"Digital presentation adds another responsibility. Cropping away a legend or shrinking labels until they cannot be read removes part of the argument while leaving the lines apparently authoritative. An attractive reproduction should retain the information needed to interpret it."},{"type":"paragraph","text":"Reading a plan carefully changes the experience of a site. Empty areas become unrecorded, unexcavated or intentionally omitted spaces rather than proof of ancient emptiness. The drawing becomes a companion to observation, not an instruction to see more certainty than the evidence contains."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":null,"district":null,"relatedDistrictIds":["khyber-pakhtunkhwa-haripur","punjab-rawalpindi","sindh-larkana"],"provinceRegionIds":["khyber-pakhtunkhwa","punjab","sindh"],"relatedHeritageIds":["unesco-139","unesco-138"],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"How a site plan changes what visitors see | Virsapur","description":"A site plan is a selective argument in lines, not a transparent view of the past. Its key, phases and purpose determine how it should be read.","primaryKeyword":"archaeological site plans","socialTitle":"How a site plan changes what visitors see","socialDescription":"A site plan is a selective argument in lines, not a transparent view of the past. Its key, phases and purpose determine how it should be read."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Maps and plans","url":"https://archaeologydataservice.ac.uk/help-guidance/ads-easy-guidance/step-3-edit-metadata/maps-and-plans/","publisher":"Archaeology Data Service","accessDate":"2026-10-22"},{"title":"Historic England Archaeology Recording Manual 2018","url":"https://historicengland.org.uk/content/docs/research/historic-england-archaeological-recording-manual-2018","publisher":"Historic England","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Teach readers to distinguish exposed remains, inferred walls and modern paths on plans.","internalNotes":"Review draft; source-backed observations distinguished from analysis and hypothetical examples. Foreign methodological guidance is not represented as Pakistani law. No excavation, access, treatment or publicity claims inferred from general sources. Specialist editorial review and reference verification required.","sortOrder":156}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-water-damage-in-an-archaeological-record','water-damage-in-an-archaeological-record','review','{"id":"story-water-damage-in-an-archaeological-record","type":"story","slug":"water-damage-in-an-archaeological-record","title":"Water damage in an archaeological record","summary":"Water threatens both archaeological fabric and the evidence held within it. Moenjodaro shows why conservation has to address a system of conditions rather than one visible symptom.","body":[{"type":"paragraph","text":"Water damage at an archaeological site is not confined to a dramatic flood photograph. Moisture, salts, rainfall and the behaviour of the ground can affect material over time. The difficulty is to understand how those processes interact before deciding what a damaged surface is telling us."},{"type":"heading","level":2,"text":"Fabric and information"},{"type":"paragraph","text":"UNESCO identifies salinity, humidity and climate-related risks among Moenjodaro''s conservation challenges. Its World Heritage description also connects threats to the site''s foundations with saline action and the water table. These are linked conditions, not merely stains to remove from a wall."},{"type":"paragraph","text":"A brick surface is part of a structure, but it can also preserve evidence about construction, repair and use. When material deteriorates, the loss is therefore both physical and informational. A wall may remain recognisable while some of the details needed to understand its history become harder to distinguish."},{"type":"paragraph","text":"The conservation report prepared by the Japan Consortium stresses investigation, appropriate measures and continued monitoring. That sequence is important. A treatment should respond to an identified process, and its performance needs assessment rather than being assumed successful because it initially looks tidy."},{"type":"heading","level":2,"text":"Avoid the instant repair story"},{"type":"paragraph","text":"A photograph can show an effect without explaining its cause. Similar-looking damage may arise under different conditions, and an intervention suitable for one location may be inappropriate elsewhere. This article is consequently not a repair guide. Site fabric requires qualified assessment and authorised conservation work."},{"type":"paragraph","text":"For a visitor, the useful response is to respect barriers and management instructions, including temporary restrictions that may protect fragile areas. A newly protected or covered section is not necessarily less authentic as an experience; it may be part of the work required to keep the underlying evidence from being lost."},{"type":"paragraph","text":"The same care should inform reporting. A claim that a site has been “saved” by one project can obscure the ongoing labour of maintenance. Conversely, a photograph of deterioration should not be used to assume that no technical work is taking place."},{"type":"paragraph","text":"UNESCO''s conservation programme explicitly combines technical capacity with disaster-risk reduction. The connection encourages a wider view of responsibility: preparation, monitoring and institutional knowledge matter alongside work on individual walls."},{"type":"paragraph","text":"Moenjodaro''s significance includes the challenge of caring for an exposed archaeological city. Understanding water damage makes that challenge more visible without turning the site into a spectacle of inevitable loss. The aim is to preserve both material and the possibility of future study, with decisions informed by evidence rather than the demand for a quick visual improvement."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Sindh","Archaeology"],"province":"Sindh","district":"Larkana","relatedDistrictIds":["sindh-larkana"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["unesco-138"],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"Water damage in an archaeological record | Virsapur","description":"Water threatens both archaeological fabric and the evidence held within it. Moenjodaro shows why conservation has to address a system of conditions rather than one visible symptom.","primaryKeyword":"archaeological erosion Pakistan","socialTitle":"Water damage in an archaeological record","socialDescription":"Water threatens both archaeological fabric and the evidence held within it. Moenjodaro shows why conservation has to address a system of conditions rather than one visible symptom."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Conservation of the Archaeological Ruins of Moenjodaro and Reinforcement of the Disaster Risk Reduction Mechanism","url":"https://core.unesco.org/en/project/537PAK4000","publisher":"UNESCO","accessDate":"2026-10-22"},{"title":"Archaeological Ruins at Moenjodaro","url":"https://whc.unesco.org/en/list/138","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Report on Damage to Cultural Properties in Sindh Province","url":"https://www.jcic-heritage.jp/wp-content/uploads/2024/04/ReportOnDamageToCulturalPropertiesInSindhProvince_JCIC-Heritage.pdf","publisher":"Japan Consortium for International Cooperation in Cultural Heritage","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Explain effects on fabric and evidence without presenting conservation instructions for untrained intervention.","internalNotes":"Review draft; source-backed observations distinguished from analysis and hypothetical examples. Foreign methodological guidance is not represented as Pakistani law. No excavation, access, treatment or publicity claims inferred from general sources. Specialist editorial review and reference verification required.","sortOrder":157}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-recording-a-find-before-naming-it','recording-a-find-before-naming-it','review','{"id":"story-recording-a-find-before-naming-it","type":"story","slug":"recording-a-find-before-naming-it","title":"Recording a find before naming it","summary":"An attractive name is not the first piece of information a find needs. Position, association and an honest description allow later interpretations to be tested.","body":[{"type":"paragraph","text":"“Royal”, “ritual” and “ceremonial” are powerful words. Attached too quickly to an archaeological find, they can make an object memorable while hiding how little is known about its use. The first task is less glamorous and more valuable: preserve the information that will allow an interpretation to be tested."},{"type":"heading","level":2,"text":"Description before identification"},{"type":"paragraph","text":"An observation should be distinguishable from a proposed explanation. Material, shape, dimensions and visible traces can be described without first deciding that an object was an amulet or a tool. An interpretation can then be added with its supporting argument and its degree of confidence."},{"type":"paragraph","text":"The National Park Service''s explanation of archaeological context includes an object''s relationships in space, time and association with other evidence. A find''s importance therefore does not reside solely in its appearance. The place and circumstances of recovery can change the questions it is capable of answering."},{"type":"paragraph","text":"Imagine a small perforated object. Without context, its opening might suggest suspension, attachment or another function. Recorded beside related material in a secure deposit, it may support a more specific argument. This is a hypothetical example of interpretation, not an identification of a particular Harappan artefact."},{"type":"heading","level":2,"text":"The record should survive a change of mind"},{"type":"paragraph","text":"Oxford''s field guidance emphasises consistent identifiers and thorough documentation. The practical reason is that an object, its bag, its drawing and its written description need to remain connected. If a later specialist revises the identification, those connections should not be lost."},{"type":"paragraph","text":"A good archive can therefore preserve both the earlier label and the revised one. The change becomes part of the research history. Quietly replacing a name without recording the basis of the revision makes it harder to understand why two publications describe the same object differently."},{"type":"paragraph","text":"For readers, the most useful catalogue entry answers modest questions clearly: what was observed, where was it recovered, what is inferred and who made that inference? An elaborate title is less informative if those elements are absent."},{"type":"paragraph","text":"This also explains why an object should not be removed by a visitor who thinks they have recognised something important. Moving it can destroy relationships that are difficult or impossible to reconstruct from memory. Recording and reporting concerns through the responsible site authority is different from collecting."},{"type":"paragraph","text":"At Harappa and other archaeological places, the ordinary-looking fragment may be informative precisely because its context survives. The discipline of recording before naming does not diminish discovery. It gives discovery a lasting evidential value, beyond the excitement of the first attractive interpretation."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":null,"district":null,"relatedDistrictIds":["punjab-sahiwal"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6579"],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"Recording a find before naming it | Virsapur","description":"An attractive name is not the first piece of information a find needs. Position, association and an honest description allow later interpretations to be tested.","primaryKeyword":"archaeological recording context","socialTitle":"Recording a find before naming it","socialDescription":"An attractive name is not the first piece of information a find needs. Position, association and an honest description allow later interpretations to be tested."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"What Is Archeological Context?","url":"https://www.nps.gov/articles/000/what-is-archeological-context.htm","publisher":"US National Park Service","accessDate":"2026-10-22"},{"title":"Recording Guide","url":"https://archeox.conted.ox.ac.uk/www.archeox.net/sites/www.archeox.net/files/reports/Recording%20guide%20NEW.pdf","publisher":"University of Oxford, Archaeox","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Show why location, layer and associations precede interpretation or attractive labels.","internalNotes":"Review draft; source-backed observations distinguished from analysis and hypothetical examples. Foreign methodological guidance is not represented as Pakistani law. No excavation, access, treatment or publicity claims inferred from general sources. Specialist editorial review and reference verification required.","sortOrder":158}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-a-cave-is-not-automatically-a-prehistoric-home','a-cave-is-not-automatically-a-prehistoric-home','review','{"id":"story-a-cave-is-not-automatically-a-prehistoric-home","type":"story","slug":"a-cave-is-not-automatically-a-prehistoric-home","title":"A cave is not automatically a prehistoric home","summary":"The age of a cave''s rock is not the date of human occupation. Shah Allah Ditta invites a distinction between geological shelter, material evidence and later associations.","body":[{"type":"paragraph","text":"A cave feels old before anyone has explained it. The rock, shade and enclosed space can suggest an immediate connection with remote human origins. That atmosphere is not archaeological proof. The formation of a shelter and its use by people are separate histories."},{"type":"heading","level":2,"text":"Separate the dates"},{"type":"paragraph","text":"A geological cavity can exist long before any documented human activity within it. Later people may alter its entrances, surfaces or surrounding ground. Still later visitors may attach religious or historical associations to the place. A responsible account needs evidence for each proposed episode rather than one age assigned to the entire setting."},{"type":"paragraph","text":"The National Heritage and Culture Division locates Shah Allah Ditta''s caves in the Margalla setting near Islamabad and identifies them as a protected heritage place. That institutional recognition establishes the site''s significance within heritage administration. It does not, by itself, settle every popular claim about the earliest people who occupied the caves."},{"type":"paragraph","text":"A claim of prehistoric habitation would need archaeological support tied to the place: documented deposits, securely associated material and a reasoned chronology. The existence of a shelter is not enough. Nor does a later sacred association automatically tell us what happened in an earlier period."},{"type":"heading","level":2,"text":"Ask what has actually been investigated"},{"type":"paragraph","text":"The National Park Service''s methodological guidance distinguishes several ways of identifying and investigating sites. Its general lesson applies here without importing American legal rules: different methods produce different evidence. A surface observation is not equivalent to a controlled sequence of excavated deposits."},{"type":"paragraph","text":"When reading a description, ask whether it refers to a formal investigation, a historical account, an oral tradition or an inference based on appearance. These categories can all contribute to understanding a place, but they should be named rather than merged."},{"type":"paragraph","text":"This distinction also protects living memory. A community''s account should not be dismissed because it is not an excavation report, but neither should it be presented as a laboratory date. Respect involves representing the nature of the evidence accurately."},{"type":"paragraph","text":"For a visitor, the cave''s interest does not depend on claiming the oldest possible origin. Its form, setting and documented associations can be explored without inventing a continuous occupation stretching across every era."},{"type":"paragraph","text":"A careful archive entry can therefore be both engaging and restrained. It can explain what is recognised, identify which historical claims remain under review and avoid turning uncertainty into either sensational antiquity or a declaration that nothing happened there. The cave becomes a place with several questions, rather than a ready-made picture of prehistoric life."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":null,"district":null,"relatedDistrictIds":["islamabad-islamabad"],"provinceRegionIds":["islamabad"],"relatedHeritageIds":["major-doam-6344"],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"A cave is not automatically a prehistoric home | Virsapur","description":"The age of a cave''s rock is not the date of human occupation. Shah Allah Ditta invites a distinction between geological shelter, material evidence and later associations.","primaryKeyword":"cave archaeology interpretation","socialTitle":"A cave is not automatically a prehistoric home","socialDescription":"The age of a cave''s rock is not the date of human occupation. Shah Allah Ditta invites a distinction between geological shelter, material evidence and later associations."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Shah Allah Ditta caves — heritage notice","url":"https://www.heritage.pakistan.gov.pk/NewsDetail/OTZlNTg3NDQtMzAxYS00ZDBmLTlmNTgtNmY4NTQ3MTEwNzFj","publisher":"National Heritage and Culture Division, Government of Pakistan","accessDate":"2026-10-22"},{"title":"How Do Archeologists Find Sites?","url":"https://www.nps.gov/articles/000/how-do-archeologists-find-sites.htm","publisher":"US National Park Service","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Separate geological shelter, material evidence and later sacred use.","internalNotes":"Review draft; source-backed observations distinguished from analysis and hypothetical examples. Foreign methodological guidance is not represented as Pakistani law. No excavation, access, treatment or publicity claims inferred from general sources. Specialist editorial review and reference verification required.","sortOrder":159}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-what-archaeological-absence-does-not-prove','what-archaeological-absence-does-not-prove','review','{"id":"story-what-archaeological-absence-does-not-prove","type":"story","slug":"what-archaeological-absence-does-not-prove","title":"What archaeological absence does not prove","summary":"A missing object is not automatically evidence that a practice never existed. Preservation, sampling and recovery determine what an archaeological collection can represent.","body":[{"type":"paragraph","text":"The sentence “archaeologists found none” sounds decisive until its boundaries are examined. None of what, recovered by which method, from how much ground and under what preservation conditions? Without those questions, an absence in a collection can become an unsupported claim about an entire society."},{"type":"heading","level":2,"text":"The collection is not the original world"},{"type":"paragraph","text":"Historic England''s environmental archaeology guidance treats sampling, recovery, processing and preservation as connected parts of research. Its supporting material distinguishes the kinds of biological evidence that can be studied and the conditions affecting their survival. The methodological point is that evidence reaches a researcher through several filters."},{"type":"paragraph","text":"An activity may have left material that did not survive. Surviving material may lie outside the area investigated. A recovered fragment may not have been recognised or retained under an earlier research strategy. These possibilities do not prove that the activity occurred; they explain why a simple absence may be less conclusive than it first appears."},{"type":"paragraph","text":"The opposite mistake is equally important to avoid. Saying that evidence could have disappeared cannot establish any preferred story. An unfalsifiable explanation that invokes loss whenever support is missing is not strengthened by the language of preservation."},{"type":"heading","level":2,"text":"Make the negative claim specific"},{"type":"paragraph","text":"A more useful statement identifies the investigation''s scope. “No example was identified in the examined assemblage” is narrower than “this community never used it”. The narrower formulation is not timid. It accurately describes the result that another researcher can assess."},{"type":"paragraph","text":"Imagine two surveys of the same landscape conducted under different visibility conditions. Their finds may differ without either team having encountered a different ancient population. This hypothetical comparison shows why method and conditions should accompany a distribution map."},{"type":"paragraph","text":"The same principle applies to the material selected for a museum display. A case of durable objects is not a complete inventory of everything once used by the people represented. Its apparent gaps may reflect preservation, collecting history and curatorial choices as well as ancient practice."},{"type":"paragraph","text":"For readers exploring the Indus or Gandharan past, the discipline is to ask what kind of absence is being discussed. Is it an observed gap within a well-defined sample, a limitation of current research or a much broader historical inference?"},{"type":"paragraph","text":"Absence can contribute to an argument when the expectation and the opportunity for detection are explained. It should neither be treated as automatically decisive nor dismissed as meaningless. The strongest account makes clear what ought to have been found, why it might survive and how thoroughly the relevant evidence was sought."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"What archaeological absence does not prove | Virsapur","description":"A missing object is not automatically evidence that a practice never existed. Preservation, sampling and recovery determine what an archaeological collection can represent.","primaryKeyword":"absence archaeological evidence","socialTitle":"What archaeological absence does not prove","socialDescription":"A missing object is not automatically evidence that a practice never existed. Preservation, sampling and recovery determine what an archaeological collection can represent."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Environmental Archaeology: A Guide to the Theory and Practice of Methods, third edition","url":"https://historicengland.org.uk/images-books/publications/environmental-archaeology-3rd/","publisher":"Historic England","accessDate":"2026-10-22"},{"title":"Environmental Archaeology","url":"https://historicengland.org.uk/advice/technical-advice/archaeological-science/environmental-archaeology/","publisher":"Historic England","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Explain preservation and sampling bias using bounded examples, not arguments from missing objects.","internalNotes":"Review draft; source-backed observations distinguished from analysis and hypothetical examples. Foreign methodological guidance is not represented as Pakistani law. No excavation, access, treatment or publicity claims inferred from general sources. Specialist editorial review and reference verification required.","sortOrder":160}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-burial-archaeology-and-respectful-interpretation','burial-archaeology-and-respectful-interpretation','review','{"id":"story-burial-archaeology-and-respectful-interpretation","type":"story","slug":"burial-archaeology-and-respectful-interpretation","title":"Burial archaeology and respectful interpretation","summary":"Burial evidence can illuminate health and mortuary practice without reducing people to specimens or spectacle. Harappa''s cemetery research requires both analytical precision and ethical care.","body":[{"type":"paragraph","text":"A burial is evidence of a person and of the actions taken around that person after death. Archaeological interpretation needs to hold those two dimensions together. Questions about health, burial position or associated objects do not remove the responsibility to describe human remains with care."},{"type":"heading","level":2,"text":"What a study''s sample can tell us"},{"type":"paragraph","text":"Nancy Lovell''s research on material excavated at Harappa''s Cemetery R37 in 1987 and 1988 distinguishes the minimum number of individuals represented from the much smaller number of complete skeletons in primary contexts. That distinction is important before any reported condition is treated as a statement about the whole population."},{"type":"paragraph","text":"The study examines several categories of skeletal change, including joint disease and trauma. A finding belongs to a particular examined sample. It should not be inflated into a complete biography for an individual or a sweeping diagnosis of everyone who lived at Harappa. The surviving material and the questions asked of it define the limits of the account."},{"type":"paragraph","text":"Burial arrangements require similar restraint. The presence of objects in a grave can be documented, but their relationship with status, belief or personal identity needs an argument. A richer-looking burial is not automatically evidence of a named social rank. The actions of those arranging a burial also need not reproduce every aspect of the deceased person''s life."},{"type":"heading","level":2,"text":"Respect changes presentation"},{"type":"paragraph","text":"The Metropolitan Museum''s stewardship policy treats human remains as those of once-living people and recognises responsibilities towards living communities. UCL''s policy likewise emphasises practical and ethical preparation for people handling such material. These are institutional approaches, not a substitute for Pakistani law or a universal answer to every local question."},{"type":"paragraph","text":"Their relevance to a public archive is nevertheless direct. An article can explain a research result without using a sensational photograph. It can distinguish an observation from an emotionally charged reconstruction. It can also acknowledge that display, research access and cultural expectations may require different decisions in different contexts."},{"type":"paragraph","text":"Terminology matters. Describing a burial as “mysterious” may attract attention while obscuring the actual problem: incomplete preservation, uncertain association or an unresolved interpretation. Naming the evidential limitation is usually more useful than making the person an object of intrigue."},{"type":"heading","level":2,"text":"Keep the research history visible"},{"type":"paragraph","text":"A cemetery may be excavated in several campaigns, with material subsequently studied using different methods. An account should identify which campaign and sample a conclusion concerns. Changes in classification or interpretation can then be understood as part of continuing research rather than contradictions to conceal."},{"type":"paragraph","text":"At Harappa, burial archaeology contributes to understanding lived experience as well as funerary practice. Its value does not depend on reconstructing intimate stories that the evidence cannot support. Careful language, sample-specific claims and respectful presentation allow readers to encounter the research without forgetting that the material belongs to human lives."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":null,"district":null,"relatedDistrictIds":["punjab-sahiwal"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6579"],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"Burial archaeology and respectful interpretation | Virsapur","description":"Burial evidence can illuminate health and mortuary practice without reducing people to specimens or spectacle. Harappa''s cemetery research requires both analytical precision and ethical care.","primaryKeyword":"burial archaeology ethics","socialTitle":"Burial archaeology and respectful interpretation","socialDescription":"Burial evidence can illuminate health and mortuary practice without reducing people to specimens or spectacle. Harappa''s cemetery research requires both analytical precision and ethical care."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Skeletal Paleopathology of Human Remains From Cemetery R37 at Harappa, excavated in 1987 and 1988","url":"https://www.harappa.com/content/skeletal-paleopathology-human-remains-cemetery-r37-harappa-excavated-1987-and-1988","publisher":"Nancy Lovell","accessDate":"2026-10-22"},{"title":"Stewardship of Human Remains","url":"https://www.metmuseum.org/policies/human-remains-guidelines","publisher":"The Metropolitan Museum of Art","accessDate":"2026-10-22"},{"title":"Human Remains Policy","url":"https://www.ucl.ac.uk/social-historical-sciences/archaeology/research/human-remains-policy","publisher":"UCL Institute of Archaeology","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Discuss the kinds of evidence available while avoiding sensational treatment of human remains.","internalNotes":"Original review draft. Specific scholarly observations distinguished from original architectural/archaeological analysis. Related Place links are comparative context, not unsupported claims that every linked structure exhibits the discussed feature. Verify specialist terminology, bibliography and local technical documentation before publication.","sortOrder":161}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-historic-archaeology-after-the-ancient-period','historic-archaeology-after-the-ancient-period','review','{"id":"story-historic-archaeology-after-the-ancient-period","type":"story","slug":"historic-archaeology-after-the-ancient-period","title":"Historic archaeology after the ancient period","summary":"Archaeology does not stop when written records begin. Medieval settlements and later buildings can reveal histories that documents record differently or leave unmentioned.","body":[{"type":"paragraph","text":"Archaeology is often imagined as the study of periods before writing. Once chronicles, inscriptions or administrative records appear, it may seem that historians can take over and the ground has little more to add. That division misunderstands what material evidence can do."},{"type":"heading","level":2,"text":"Documents do not describe everything"},{"type":"paragraph","text":"The Society for Historical Archaeology defines its field through the study of material remains alongside other historical evidence. Written and physical records can illuminate the same setting, but they do not necessarily preserve the same people, activities or priorities."},{"type":"paragraph","text":"A text might describe a foundation, a patron or a political event. Surviving fabric can raise questions about subsequent alteration, everyday use or an arrangement omitted from the written account. Neither source should automatically be treated as a transparent account of the other."},{"type":"paragraph","text":"Brahmanabad-Mansurah provides a Pakistani point of entry into this discussion. The Department of Archaeology and Museums records the remains of a fortified city. A fortification is not only an illustration for a historical name: its construction, changes and relationship with the surrounding settlement are material questions that require investigation."},{"type":"paragraph","text":"This article does not assign a new chronology to that site. Its purpose is to explain why a known historical setting still needs archaeological analysis rather than being considered fully understood once it has been linked with a text."},{"type":"heading","level":2,"text":"Agreement is not the only useful result"},{"type":"paragraph","text":"Suppose a written description presents a building as a single foundation, while its fabric contains several identifiable phases. That difference might reflect later rebuilding, a text''s selective purpose or an error in the assumed association. It should prompt research rather than an immediate choice that one entire source must be discarded."},{"type":"paragraph","text":"The same applies to ordinary material. A small domestic assemblage may address eating, repair or disposal practices that a political chronicle does not discuss. Its historical value is not reduced because the objects are less visually impressive than a monument or because the society also produced writing."},{"type":"paragraph","text":"Studies that establish context and chronology, including research on later phases in Swat, demonstrate why period labels alone are insufficient. “Medieval” covers questions, places and times that have to be specified. A shared label does not make all deposits contemporary."},{"type":"heading","level":2,"text":"An archive wider than antiquity"},{"type":"paragraph","text":"For heritage discovery, this perspective broadens what deserves attention. A later settlement, industrial feature or altered urban building can be archaeologically informative without pretending to be prehistoric. Age is not the only measure of evidential value."},{"type":"paragraph","text":"It also changes how repair and clearance are understood. Later layers are not automatically obstructions covering a more important ancient story. They may contain the evidence needed to explain how a place continued, changed or was remembered."},{"type":"paragraph","text":"Historical archaeology therefore works through a conversation between records rather than a competition between disciplines. The strongest account states what each source can establish, where they agree and where the difference itself becomes a question worth investigating."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":null,"district":null,"relatedDistrictIds":["sindh-sanghar","punjab-sheikhupura"],"provinceRegionIds":["sindh","punjab"],"relatedHeritageIds":["major-doam-5267","major-doam-6585"],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"Historic archaeology after the ancient period | Virsapur","description":"Archaeology does not stop when written records begin. Medieval settlements and later buildings can reveal histories that documents record differently or leave unmentioned.","primaryKeyword":"Islamic period archaeology Pakistan","socialTitle":"Historic archaeology after the ancient period","socialDescription":"Archaeology does not stop when written records begin. Medieval settlements and later buildings can reveal histories that documents record differently or leave unmentioned."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"What is Historical Archaeology?","url":"https://sha.org/what-is-historical-archaeology/","publisher":"Society for Historical Archaeology","accessDate":"2026-10-22"},{"title":"Brahmanabad (Mansurah)","url":"https://doam.gov.pk/public/heritage-sites/447","publisher":"Department of Archaeology and Museums, Government of Pakistan","accessDate":"2026-10-22"},{"title":"A short note on contexts and chronology of the materials from Saidu Sharif, Amluk-dara, Gumbat and Barikot","url":"https://oaj.fupress.net/index.php/ra/article/view/7357","publisher":"Luca Maria Olivieri / Restauro Archeologico","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Explain why archaeology also investigates medieval and later settlements.","internalNotes":"Original review draft. Specific scholarly observations distinguished from original architectural/archaeological analysis. Related Place links are comparative context, not unsupported claims that every linked structure exhibits the discussed feature. Verify specialist terminology, bibliography and local technical documentation before publication.","sortOrder":162}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-old-excavation-reports-valuable-records-with-limits','old-excavation-reports-valuable-records-with-limits','review','{"id":"story-old-excavation-reports-valuable-records-with-limits","type":"story","slug":"old-excavation-reports-valuable-records-with-limits","title":"Old excavation reports: valuable records with limits","summary":"Early excavation reports preserve observations that may no longer be recoverable. Reading them critically means separating documentation from inherited terminology and historical assumptions.","body":[{"type":"paragraph","text":"An old excavation report can be indispensable without being the last word. It may preserve a plan, a find location or a photograph of material that has since changed. At the same time, its classifications and explanations belong to the research habits of its period."},{"type":"heading","level":2,"text":"Preserve the observation, examine the claim"},{"type":"paragraph","text":"Ernest Mackay''s report on Chanhudaro describes excavation levels, buildings and objects, but also makes broad claims about peoples and cultural change. A present-day reader should not reproduce its racial or evolutionary language as neutral description. The task is to distinguish what the excavator recorded from the historical explanation attached to it."},{"type":"paragraph","text":"That distinction need not diminish the report''s value. A documented association can remain important even when an interpretation is revised. A drawing can preserve useful detail while its caption uses a name no longer accepted. Critical reading allows those different parts of the record to be assessed separately."},{"type":"paragraph","text":"Begin with the publication''s identity. Is it a preliminary account, a final excavation report, a catalogue or a later synthesis? A preliminary statement may reflect incomplete analysis. Quoting it without its status can make a provisional suggestion appear more settled than the author intended."},{"type":"heading","level":2,"text":"Classifications also have histories"},{"type":"paragraph","text":"Kenoyer''s discussion of Indus beads explains how influential early typologies shaped later research and why additional technological observations can refine them. The point is not simply that newer work is better. It is that a familiar classification may contain assumptions that have become difficult to see through repeated use."},{"type":"paragraph","text":"When comparing publications, check whether the same term means the same thing. A category defined by appearance in one study may be defined through manufacturing technique in another. Counting both together without examining those definitions can create an artificial pattern."},{"type":"paragraph","text":"Modern reporting guidance from the Chartered Institute for Archaeologists stresses explicit attributes and explained codes. That principle helps readers approach older documentation too: abbreviations, catalogue numbers and figure references are part of the evidence trail, not disposable clutter."},{"type":"heading","level":2,"text":"Revisions should be traceable"},{"type":"paragraph","text":"If a later researcher changes a date or identification, the archive should show the basis for that revision. Was new material excavated? Was an existing object re-examined? Did the chronological framework change? These are different reasons and should not disappear into the phrase “now believed”."},{"type":"paragraph","text":"A digital archive can support this by keeping the early report linked to later work. It should neither delete the earlier interpretation nor repeat it without qualification. Readers can then see how knowledge developed rather than encountering a collection of apparently incompatible facts."},{"type":"paragraph","text":"Old reports deserve particular care because some observations cannot be repeated. Excavation changes the ground, collections can become dispersed and landscapes can be altered. Preserving the report''s information while questioning its assumptions is therefore not disloyal to earlier scholarship. It is how the record remains useful for questions its first authors may never have imagined."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":null,"district":null,"relatedDistrictIds":["khyber-pakhtunkhwa-haripur","punjab-rawalpindi","sindh-larkana"],"provinceRegionIds":["khyber-pakhtunkhwa","punjab","sindh"],"relatedHeritageIds":["unesco-139","unesco-138"],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"Old excavation reports: valuable records with limits | Virsapur","description":"Early excavation reports preserve observations that may no longer be recoverable. Reading them critically means separating documentation from inherited terminology and historical assumptions.","primaryKeyword":"historic excavation reports","socialTitle":"Old excavation reports: valuable records with limits","socialDescription":"Early excavation reports preserve observations that may no longer be recoverable. Reading them critically means separating documentation from inherited terminology and historical assumptions."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Excavations at Chanhu-daro 1935–36","url":"https://www.harappa.com/content/excavations-chanhu-daro-1935-36","publisher":"Ernest Mackay / Smithsonian Institution","accessDate":"2026-10-22"},{"title":"Stone Beads of the Indus Tradition: New Perspectives on Harappan Bead Typology, Technology and Documentation","url":"https://www.harappa.com/sites/default/files/pdf/Kenoyer2017%20Stone%20Beads_Chapter%2007.pdf","publisher":"Jonathan Mark Kenoyer","accessDate":"2026-10-22"},{"title":"Approaches to reporting","url":"https://www.archaeologists.net/work/toolkits/pottery/approaches-reporting","publisher":"Chartered Institute for Archaeologists","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Teach critical reading of terminology, recording methods and later revisions.","internalNotes":"Original review draft. Specific scholarly observations distinguished from original architectural/archaeological analysis. Related Place links are comparative context, not unsupported claims that every linked structure exhibits the discussed feature. Verify specialist terminology, bibliography and local technical documentation before publication.","sortOrder":163}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-from-sherd-to-published-argument','from-sherd-to-published-argument','review','{"id":"story-from-sherd-to-published-argument","type":"story","slug":"from-sherd-to-published-argument","title":"From sherd to published argument","summary":"A pottery fragment becomes evidence through a chain of recording, classification and comparison. Each step should remain visible when a published argument moves from a sherd to a wider historical claim.","body":[{"type":"paragraph","text":"A sherd is a fragment, not a miniature complete pot. It may preserve a rim, a base, part of a handle or an otherwise unremarkable piece of wall. Its contribution to a historical argument depends on what survives and on the information recorded with it."},{"type":"heading","level":2,"text":"Begin with attributes"},{"type":"paragraph","text":"Pottery recording guidance from the Chartered Institute for Archaeologists distinguishes contextual unit, fabric, form, decoration and other attributes. “Fabric” concerns the material body of the pottery, including its clay and inclusions; it does not mean a textile. This vocabulary allows researchers to describe comparable features rather than rely on an overall impression."},{"type":"paragraph","text":"A fragment with a recognisable rim can offer different information from a plain body sherd. Decoration may support comparison, but it is not the only relevant feature. Material and manufacturing observations can complicate an identification that initially seemed obvious from colour or pattern."},{"type":"paragraph","text":"The analytical advantage is that a description can be checked. Another specialist may disagree with the classification while still working from the recorded attributes. If the entry contains only a culture name, the reasoning that led to it becomes much harder to assess."},{"type":"heading","level":2,"text":"A fragment is not a vessel count"},{"type":"paragraph","text":"Several sherds may come from one vessel, while a small assemblage can also contain fragments of many different vessels. Counting pieces is therefore not identical to counting pots. The chosen measure needs to be stated before quantities are used to compare deposits or settlements."},{"type":"paragraph","text":"This matters when an argument moves from pottery to behaviour. A higher fragment count does not automatically mean more people, more consumption or a longer occupation. Breakage, disposal and the composition of the investigated deposit all need consideration."},{"type":"paragraph","text":"Reporting guidance also asks researchers to address condition and fragmentation when discussing how an assemblage formed. The published table and the interpretation should therefore belong to the same argument, rather than the table serving merely as a technical appendix no one is expected to read."},{"type":"heading","level":2,"text":"From comparison to historical explanation"},{"type":"paragraph","text":"A resemblance between two pottery groups may support a chronological or technological comparison. It does not independently prove migration, trade or shared identity. Those explanations require additional evidence and an account of why alternative mechanisms are less convincing."},{"type":"paragraph","text":"For an archive reader encountering a sherd from a Pakistani mound, useful questions are modest and precise. Which part of the vessel survives? How securely is its context known? Is the proposed comparison based on form, fabric, decoration or several features together? What uncertainty remains?"},{"type":"paragraph","text":"The fragment''s value is not diminished if the answer stops short of a dramatic story. A carefully documented sherd can refine a sequence or reveal a problem in an existing classification."},{"type":"paragraph","text":"The route from fragment to argument should remain inspectable at every stage. Description, grouping, comparison and interpretation are connected operations, but they should not collapse into one confident label that hides how much work the conclusion actually requires."}],"primaryCategoryId":"archive-category-archaeology-ancient-civilisations","categoryIds":["archive-category-archaeology-ancient-civilisations"],"tags":["Archaeology"],"province":null,"district":null,"relatedDistrictIds":["punjab-khanewal"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-8671"],"relatedStoryIds":[],"contentType":"archaeology","seo":{"title":"From sherd to published argument | Virsapur","description":"A pottery fragment becomes evidence through a chain of recording, classification and comparison. Each step should remain visible when a published argument moves from a sherd to a wider historical claim.","primaryKeyword":"archaeological interpretation process","socialTitle":"From sherd to published argument","socialDescription":"A pottery fragment becomes evidence through a chain of recording, classification and comparison. Each step should remain visible when a published argument moves from a sherd to a wider historical claim."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Approaches to recording","url":"https://www.archaeologists.net/work/toolkits/pottery/approaches-recording","publisher":"Chartered Institute for Archaeologists","accessDate":"2026-10-22"},{"title":"Reporting","url":"https://www.archaeologists.net/work/toolkits/pottery/reporting","publisher":"Chartered Institute for Archaeologists","accessDate":"2026-10-22"},{"title":"Fabric Analysis — Pottery in Archaeology","url":"https://www.cambridge.org/core/books/abs/pottery-in-archaeology/fabric-analysis/CC3FB0EED69E6F196A3CA77B64DB355E","publisher":"Clive Orton and Michael Hughes / Cambridge University Press","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Follow the chain from observation to classification to a qualified research claim.","internalNotes":"Original review draft. Specific scholarly observations distinguished from original architectural/archaeological analysis. Related Place links are comparative context, not unsupported claims that every linked structure exhibits the discussed feature. Verify specialist terminology, bibliography and local technical documentation before publication.","sortOrder":164}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-how-a-mughal-charbagh-organises-movement','how-a-mughal-charbagh-organises-movement','review','{"id":"story-how-a-mughal-charbagh-organises-movement","type":"story","slug":"how-a-mughal-charbagh-organises-movement","title":"How a Mughal charbagh organises movement","summary":"A charbagh is experienced through routes, thresholds and changing views as well as symmetry. Lahore''s Shalamar Gardens show why water and levels belong to the same architectural reading.","body":[{"type":"paragraph","text":"From a plan, a Mughal garden can appear to be an exercise in symmetry. On foot, the experience is less static: an entrance frames a view, a channel establishes direction and a change of level alters the relationship between water and architecture. The garden is organised through movement as well as geometry."},{"type":"heading","level":2,"text":"Axes are routes and sightlines"},{"type":"paragraph","text":"A charbagh is associated with a divided garden layout, but the term should not replace attention to a particular site. UNESCO describes Shalamar''s upper and lower terraces through square arrangements and its intermediate terrace through a narrower configuration. The three levels do not offer an identical experience."},{"type":"paragraph","text":"An axis can guide the eye without functioning everywhere as an unrestricted path. A basin, platform or threshold may interrupt movement while extending a visual line. Reading the garden therefore involves asking where a visitor could walk, where a view continued and where access was mediated by architecture."},{"type":"paragraph","text":"The distinction is especially useful when a photograph presents a long, apparently continuous perspective. The image may compress changes of level or conceal a crossing. A plan and a view should be read together rather than allowing either to supply the whole experience."},{"type":"heading","level":2,"text":"Water is part of the arrangement"},{"type":"paragraph","text":"Water features establish relationships among channels, basins, platforms and pavilions. Their historical significance is not limited to decoration or symbolism. Their position also helps structure the route through the garden and the places from which it is seen."},{"type":"paragraph","text":"The Mughal Gardens research project presents Shalamar within a broader architectural landscape. ICOMOS''s conservation discussion, meanwhile, treats the garden as a historic entity requiring care. Together they encourage a reading in which buildings, planting and waterworks are interdependent rather than separate attractions."},{"type":"paragraph","text":"That interdependence is also a caution about reconstruction. A dry channel today is evidence of a surviving feature, not an adequate demonstration of every effect it once produced. Conversely, a functioning modern water display should not be assumed to reproduce an original hydraulic arrangement without documentation."},{"type":"heading","level":2,"text":"Thresholds make distinctions"},{"type":"paragraph","text":"A gateway or terrace boundary can change the scale and character of the space beyond it. Such transitions invite questions about ceremony, access and the relationship between different parts of a royal setting. Specific historical claims about who used each area still need documentary support."},{"type":"paragraph","text":"For visitors, an attentive walk can begin with simple observations: where does a path turn, what becomes visible at a crossing, and which building anchors the view? These observations do not require assigning a symbolic meaning to every tree or pool."},{"type":"paragraph","text":"The premium quality of the garden lies partly in these carefully composed relationships. A charbagh is not merely a diagram reproduced on the ground. At Shalamar, levels, routes and water create a sequence that has to be experienced through time. Understanding that sequence makes the garden''s architectural intelligence visible beyond its most familiar postcard view."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Punjab","Architecture"],"province":"Punjab","district":"Lahore","relatedDistrictIds":["punjab-lahore"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["unesco-171","major-doam-6479"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"How a Mughal charbagh organises movement | Virsapur","description":"A charbagh is experienced through routes, thresholds and changing views as well as symmetry. Lahore''s Shalamar Gardens show why water and levels belong to the same architectural reading.","primaryKeyword":"Mughal charbagh design","socialTitle":"How a Mughal charbagh organises movement","socialDescription":"A charbagh is experienced through routes, thresholds and changing views as well as symmetry. Lahore''s Shalamar Gardens show why water and levels belong to the same architectural reading."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Fort and Shalamar Gardens in Lahore","url":"https://whc.unesco.org/en/list/171","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Gardens of the Mughal Empire — Shalamar Garden","url":"https://www.mughalgardens.org/html/shalamar.html","publisher":"Mughal Gardens research project","accessDate":"2026-10-22"},{"title":"Shalamar Garden — Preservation and Restoration","url":"https://www.icomos.org/public/publications/93garden20.pdf","publisher":"ICOMOS","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Explain axes, thresholds and water as a design system rather than garden symbolism alone.","internalNotes":"Original review draft. Specific scholarly observations distinguished from original architectural/archaeological analysis. Related Place links are comparative context, not unsupported claims that every linked structure exhibits the discussed feature. Verify specialist terminology, bibliography and local technical documentation before publication.","sortOrder":165}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-pavilion-a-small-building-with-several-jobs','the-pavilion-a-small-building-with-several-jobs','review','{"id":"story-the-pavilion-a-small-building-with-several-jobs","type":"story","slug":"the-pavilion-a-small-building-with-several-jobs","title":"The pavilion: a small building with several jobs","summary":"A pavilion can mark a destination, frame a view or organise an approach. Hiran Minar''s tank setting shows why a small building must be read through its wider composition.","body":[{"type":"paragraph","text":"A pavilion may occupy little ground while organising a much larger setting. Its significance can depend on how it is approached, what it overlooks and how its openings connect interior and exterior. Describing it simply as a small decorative building misses those relationships."},{"type":"heading","level":2,"text":"Hiran Minar''s building in the water"},{"type":"paragraph","text":"Pakistan''s Tentative List description of Hiran Minar and Tank identifies an octagonal pavilion in the tank, reached by a causeway. It also records square pavilions at the corners. The central and corner structures belong to one composition, but they occupy different positions within it."},{"type":"paragraph","text":"That arrangement gives the approach architectural importance. The central pavilion is not reached in the same way as a roadside room. Its relationship with the water and the causeway makes movement towards it part of the experience. A photograph of the building alone can hide precisely what makes its setting distinctive."},{"type":"paragraph","text":"The official description uses the term baradari for the central pavilion. It does not follow that every open-sided building in every heritage garden should receive the same name. A recorded local or historical designation is preferable to a label supplied solely because the structure looks picturesque."},{"type":"heading","level":2,"text":"Position can change the job"},{"type":"paragraph","text":"A comparison outside Pakistan helps clarify the point without merging the sites. The government description of Humayun''s tomb places a pavilion along the eastern enclosure of the garden complex. A building positioned on a boundary relates to routes and views differently from one standing within a tank."},{"type":"paragraph","text":"This does not establish that the two structures had identical uses or patrons'' intentions. It shows why “pavilion” describes a broad architectural category rather than a complete functional history. To understand a particular example, the reader needs its plan, access and documented context."},{"type":"paragraph","text":"Some functions may be visible in the arrangement; others require historical evidence. A platform can provide a place to pause, but an account of a specific ceremony cannot be inferred from that possibility. Shelter, display and viewing may overlap, yet their balance should not be invented for an unnamed occasion."},{"type":"heading","level":2,"text":"Read the openings, not just the roof"},{"type":"paragraph","text":"The number and position of openings determine which directions are visually connected. Steps, railings and changes of level can shape how a person occupies the space. These details are often more informative than assigning a style name after a quick glance at the roofline."},{"type":"paragraph","text":"Conservation and later alteration may change those relationships. An opening that is blocked today or a route that has been redirected should not be silently projected into the building''s earliest phase. A heritage account can identify the current condition while explaining what is historically documented."},{"type":"paragraph","text":"Hiran Minar''s pavilion is consequently best understood with its tank and approach, not extracted from them. Its scale may be modest compared with the landscape it commands, but that is exactly the architectural achievement: a small structure giving focus to a much larger experience."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-sheikhupura","punjab-rawalpindi","azad-kashmir-muzaffarabad"],"provinceRegionIds":["punjab","azad-kashmir"],"relatedHeritageIds":["major-doam-6423","major-doam-6397","major-doam-6710"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"The pavilion: a small building with several jobs | Virsapur","description":"A pavilion can mark a destination, frame a view or organise an approach. Hiran Minar''s tank setting shows why a small building must be read through its wider composition.","primaryKeyword":"baradari architecture Pakistan","socialTitle":"The pavilion: a small building with several jobs","socialDescription":"A pavilion can mark a destination, frame a view or organise an approach. Hiran Minar''s tank setting shows why a small building must be read through its wider composition."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Hiran Minar and Tank, Sheikhupura — Tentative List submission","url":"https://whc.unesco.org/en/tentativelists/1281/","publisher":"Pakistan National Commission for UNESCO","accessDate":"2026-10-22"},{"title":"Humayun Tomb","url":"https://srdc.delhi.gov.in/en/srdc/humayun-tomb","publisher":"Shahjahanabad Redevelopment Corporation, Government of NCT of Delhi","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Compare documented pavilion uses without treating every open building as a baradari.","internalNotes":"Original review draft. Specific scholarly observations distinguished from original architectural/archaeological analysis. Related Place links are comparative context, not unsupported claims that every linked structure exhibits the discussed feature. Verify specialist terminology, bibliography and local technical documentation before publication.","sortOrder":166}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-a-courtyard-is-more-than-empty-space','a-courtyard-is-more-than-empty-space','review','{"id":"story-a-courtyard-is-more-than-empty-space","type":"story","slug":"a-courtyard-is-more-than-empty-space","title":"A courtyard is more than empty space","summary":"A courtyard connects rooms through light, routes and views. Reading domestic architecture requires attention to how the open centre works, not just to the ornament around it.","body":[{"type":"paragraph","text":"The centre of a courtyard house can seem to be the part where nothing has been built. In architectural terms, that apparent emptiness is active. Rooms face it, routes pass through or around it, and openings connect spaces that would otherwise be separated by walls."},{"type":"heading","level":2,"text":"The centre belongs to the plan"},{"type":"paragraph","text":"Sethi House in Peshawar is documented in official heritage material, including the Khyber Pakhtunkhwa archaeology report''s courtyard view. The image offers a useful starting point for looking at the relationship between an open centre and its surrounding elevations. It does not, on its own, explain every room''s historical use."},{"type":"paragraph","text":"The first question is how the house is entered. Does the approach reveal the court immediately, or does a threshold interrupt the view? Then consider how rooms connect with the centre and with one another. A court can distribute movement without every room needing to open directly onto a street."},{"type":"paragraph","text":"Vertical relationships matter as well. An upper-level opening may overlook the same court from a different position. That shared visual space does not mean that access to every level was identical. A photograph can show architectural connections while leaving the social arrangements unresolved."},{"type":"heading","level":2,"text":"Light, shade and daily activity"},{"type":"paragraph","text":"An open court admits daylight, but its effect depends on the height and orientation of the surrounding building. A narrow, tall enclosure and a broad, low one cannot be assumed to behave in the same way. The word “courtyard” identifies a spatial relationship, not a universal environmental formula."},{"type":"paragraph","text":"Claims about cooling require similar care. Shade, airflow, materials and water can interact, but a general statement that all old houses were naturally comfortable conceals variation. The useful approach is to study the particular arrangement rather than turn the courtyard into an effortless answer to every climatic problem."},{"type":"paragraph","text":"Daily uses may also change over time. A space might accommodate several activities at different hours, yet assigning those activities to a named historic family requires evidence. Architecture can suggest possibilities without giving us permission to script domestic scenes."},{"type":"heading","level":2,"text":"Ornament does not replace circulation"},{"type":"paragraph","text":"Carved wood, painted surfaces and decorative openings often dominate photographs of historic houses. They deserve attention, but their relationship with the plan matters. An elaborately treated opening may also frame a route or mediate a view. Seeing only its ornament removes part of its architectural work."},{"type":"paragraph","text":"WCLA''s presentation of Lahore''s historic environment offers another route into domestic and urban settings, but individual houses should not be treated as interchangeable examples of one timeless way of life. Sethi House, Haveli Sujan Singh and Haveli Nau Nihal Singh each require their own documented history."},{"type":"paragraph","text":"A good courtyard account therefore begins with relationships that can be observed and identifies the evidence behind broader social claims. The open centre becomes more than a photogenic void: it is the space through which much of the building''s organisation can be understood, while the lives once arranged around it remain a subject for careful historical inquiry."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["khyber-pakhtunkhwa-peshawar","punjab-rawalpindi","punjab-lahore"],"provinceRegionIds":["khyber-pakhtunkhwa","punjab"],"relatedHeritageIds":["major-doam-3485","major-doam-9419","major-doam-6446"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"A courtyard is more than empty space | Virsapur","description":"A courtyard connects rooms through light, routes and views. Reading domestic architecture requires attention to how the open centre works, not just to the ornament around it.","primaryKeyword":"courtyard architecture Pakistan","socialTitle":"A courtyard is more than empty space","socialDescription":"A courtyard connects rooms through light, routes and views. Reading domestic architecture requires attention to how the open centre works, not just to the ornament around it."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Archaeology Task Force Report","url":"https://dost.kp.gov.pk/wp-content/uploads/2026/01/Archeology_TF-Report.pdf","publisher":"Directorate of Science and Technology, Government of Khyber Pakhtunkhwa","accessDate":"2026-10-22"},{"title":"The Royal Trail","url":"https://artsandculture.google.com/story/the-royal-trail-walled-city-of-lahore-authority-wcla/bwWBgVXIrhEA8A?hl=en","publisher":"Walled City of Lahore Authority","accessDate":"2026-10-22"},{"title":"Sethi House","url":"https://doam.gov.pk/public/sites/3485","publisher":"Department of Archaeology and Museums, Government of Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Compare light, circulation and social divisions through specific domestic examples.","internalNotes":"Original review draft. Specific scholarly observations distinguished from original architectural/archaeological analysis. Related Place links are comparative context, not unsupported claims that every linked structure exhibits the discussed feature. Verify specialist terminology, bibliography and local technical documentation before publication.","sortOrder":167}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-from-square-room-to-dome-squinches-and-pendentives','from-square-room-to-dome-squinches-and-pendentives','review','{"id":"story-from-square-room-to-dome-squinches-and-pendentives","type":"story","slug":"from-square-room-to-dome-squinches-and-pendentives","title":"From square room to dome: squinches and pendentives","summary":"Squinches and pendentives address the transition between a chamber and a dome. Learning the distinction helps readers describe what they see without turning one feature into an unsupported date.","body":[{"type":"paragraph","text":"Look up inside a domed chamber and the most revealing part may not be the dome''s centre. It can be the zone where the room''s corners meet the structure above. A square plan and a circular dome do not share the same outline, so their relationship has to be resolved architecturally."},{"type":"heading","level":2,"text":"Two terms for a transition"},{"type":"paragraph","text":"A squinch bridges or occupies a corner, helping transform the support above a square space into a form that can carry the dome. A pendentive is a curved triangular transition associated with the space between supporting arches. Architectural teaching material distinguishes these approaches because their geometry is not the same."},{"type":"paragraph","text":"Patricia Blessing''s Khamseen presentation treats squinch and pendentive together as terms in Islamic architectural history. The comparison is useful for looking, but it should not become a competition in which every building must be placed in one simple box after a single photograph."},{"type":"paragraph","text":"Decoration can complicate recognition. A surface may be richly articulated, while the structural relationship beneath it is less obvious. An ornate corner should not automatically be identified as one device simply because it resembles an illustration seen elsewhere."},{"type":"heading","level":2,"text":"Follow the room upwards"},{"type":"paragraph","text":"Begin with the plan. Where are the main supports, and what happens at the corners? Does the transition appear as a distinct feature across a corner, or as part of a continuous curved surface between arches? Then ask how the zone above changes before the dome begins."},{"type":"paragraph","text":"These questions can be explored through measured sections and clear photographs. A low-angle interior image may hide the junction, while an exterior view can reveal little about the internal transition. If the evidence is insufficient, an honest description can identify the problem without forcing a label."},{"type":"paragraph","text":"The distinction also warns against dating a building from one feature. A constructional solution can be used in different regions and periods. Identifying it is one step in analysis, not a complete chronology or proof of a direct line of influence between two monuments."},{"type":"heading","level":2,"text":"Compare without importing an answer"},{"type":"paragraph","text":"For Pakistani mosques and tombs, the terms are useful when supported by documentation of the specific building. A related place in an atlas is an invitation to examine evidence, not a claim that its interior has already been structurally classified."},{"type":"paragraph","text":"A reliable account should separate the visible surface from the interpretation of how it carries loads. This article offers vocabulary for understanding published drawings, not an engineering assessment or permission to enter restricted structural spaces."},{"type":"paragraph","text":"Once the transition is noticed, the chamber becomes easier to read as a three-dimensional composition. The dome is no longer a shape placed mysteriously above four walls. It belongs to a sequence of supports, surfaces and spatial adjustments."},{"type":"paragraph","text":"That sequence is the real value of the vocabulary. Naming a squinch or pendentive should sharpen attention to the building, not end the investigation with a term that sounds more certain than the available view."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-gujranwala","punjab-chiniot"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-10107","major-doam-6211"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"From square room to dome: squinches and pendentives | Virsapur","description":"Squinches and pendentives address the transition between a chamber and a dome. Learning the distinction helps readers describe what they see without turning one feature into an unsupported date.","primaryKeyword":"squinch pendentive difference","socialTitle":"From square room to dome: squinches and pendentives","socialDescription":"Squinches and pendentives address the transition between a chamber and a dome. Learning the distinction helps readers describe what they see without turning one feature into an unsupported date."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Squinch and Pendentive","url":"https://sites.lsa.umich.edu/khamseen/terms/2022/squinch-and-pendentive/","publisher":"Patricia Blessing / University of Michigan Khamseen","accessDate":"2026-10-22"},{"title":"Byzantine Architecture — architectural technology teaching material","url":"https://openlab.citytech.cuny.edu/arch-1121-history-of-architectural-technology/files/2014/01/Lecture-07-Byzantine-Architecture.pdf","publisher":"New York City College of Technology, CUNY","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Make a structural transition intelligible through documented buildings.","internalNotes":"Original review draft. Specific scholarly observations distinguished from original architectural/archaeological analysis. Related Place links are comparative context, not unsupported claims that every linked structure exhibits the discussed feature. Verify specialist terminology, bibliography and local technical documentation before publication.","sortOrder":168}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-dome-and-the-roof-are-not-always-the-same-shell','the-dome-and-the-roof-are-not-always-the-same-shell','review','{"id":"story-the-dome-and-the-roof-are-not-always-the-same-shell","type":"story","slug":"the-dome-and-the-roof-are-not-always-the-same-shell","title":"The dome and the roof are not always the same shell","summary":"An exterior dome need not reproduce the ceiling seen inside. Double-shell construction separates two architectural profiles, but a particular building needs documented evidence before receiving that label.","body":[{"type":"paragraph","text":"A dome seen across a skyline can appear taller or differently shaped than the ceiling experienced inside the chamber below it. That difference does not necessarily mean one view is misleading. In double-shell construction, the interior and exterior profiles can belong to distinct shells rather than opposite faces of one continuous thickness."},{"type":"heading","level":2,"text":"Two profiles, different experiences"},{"type":"paragraph","text":"The Government of Delhi''s description of Humayun''s tomb identifies its prominent double dome. It provides a documented comparative example for understanding the term. It does not establish that every visually similar dome in Pakistan has the same construction."},{"type":"paragraph","text":"The architectural distinction is useful because the interior and exterior answer different spatial demands. A chamber is experienced from within, through its proportions and surfaces. A roof or dome also contributes to the building''s distant silhouette. Separate shells can allow those profiles to differ rather than requiring one shape to serve both experiences identically."},{"type":"paragraph","text":"That is an explanation of the principle, not a reconstruction of the engineering of every double dome. Materials, connections and construction histories need building-specific evidence. An elegant diagram is not a substitute for a documented section."},{"type":"heading","level":2,"text":"What a photograph cannot establish"},{"type":"paragraph","text":"A bulbous outline alone is not proof of double-shell construction. Nor does a difference between an interior photograph and an exterior photograph necessarily settle the matter: the views may be difficult to compare, and later alterations may complicate the relationship."},{"type":"paragraph","text":"Measured drawings can clarify what a casual view cannot. Historic England''s recording guidance distinguishes levels and methods of documentation for understanding buildings. The wider methodological lesson is relevant here: a description should state the evidence behind a structural identification."},{"type":"paragraph","text":"A useful section needs to show which surfaces were measured and which were inferred. If a cavity was inaccessible, that limitation should be recorded. The most visually complete drawing is not automatically the most reliable unless its conventions and basis are clear."},{"type":"heading","level":2,"text":"Keep the local question open"},{"type":"paragraph","text":"Attock Tomb and Marhi Baba Dhyghana Singh may appear in a comparative heritage route concerned with domed architecture. Their inclusion should not be read as an unsupported assertion that both have a particular shell arrangement. Each requires its own technical documentation and chronology."},{"type":"paragraph","text":"The distinction is also important in conservation. A crack or moisture stain on an interior surface does not, by itself, diagnose the condition of every part above it. Assessment belongs to qualified professionals with access to the relevant structure, not to an improvised interpretation from a visitor photograph."},{"type":"paragraph","text":"For the interested reader, the reward is a more exact question: which surface am I looking at, and how does it relate to the building''s other profile? That question turns a familiar silhouette into an investigation of architectural depth."},{"type":"paragraph","text":"The dome is not always a single object with one shape. Learning to distinguish appearance from documented construction makes both the skyline and the room beneath it more intelligible."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-attock","punjab-nankana-sahib"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6559","major-doam-6213"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"The dome and the roof are not always the same shell | Virsapur","description":"An exterior dome need not reproduce the ceiling seen inside. Double-shell construction separates two architectural profiles, but a particular building needs documented evidence before receiving that label.","primaryKeyword":"double dome architecture","socialTitle":"The dome and the roof are not always the same shell","socialDescription":"An exterior dome need not reproduce the ceiling seen inside. Double-shell construction separates two architectural profiles, but a particular building needs documented evidence before receiving that label."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Humayun Tomb","url":"https://srdc.delhi.gov.in/en/srdc/humayun-tomb","publisher":"Shahjahanabad Redevelopment Corporation, Government of NCT of Delhi","accessDate":"2026-10-22"},{"title":"Understanding Historic Buildings and Landscapes","url":"https://historicengland.org.uk/advice/technical-advice/recording-heritage/recording-buildings/","publisher":"Historic England","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Explain double-shell construction and the evidence needed to identify it.","internalNotes":"Original review draft. Specific scholarly observations distinguished from original architectural/archaeological analysis. Related Place links are comparative context, not unsupported claims that every linked structure exhibits the discussed feature. Verify specialist terminology, bibliography and local technical documentation before publication.","sortOrder":169}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-reading-a-shikhara-without-guessing-a-date','reading-a-shikhara-without-guessing-a-date','review','{"id":"story-reading-a-shikhara-without-guessing-a-date","type":"story","slug":"reading-a-shikhara-without-guessing-a-date","title":"Reading a shikhara without guessing a date","summary":"A shikhara belongs to an architectural composition, not a ready-made date label. Salt Range temple research shows the value of regional comparison and careful attention to surviving fabric.","body":[{"type":"paragraph","text":"The rising superstructure of a temple can dominate its appearance so completely that the rest of the building becomes a supporting detail. The term shikhara helps describe an important part of temple architecture, but it should not become a shortcut that assigns a date or dynasty from a silhouette alone."},{"type":"heading","level":2,"text":"A regional sequence, not an isolated shape"},{"type":"paragraph","text":"Michael W. Meister''s study of temples along the Indus presents the Salt Range material through an integrated architectural and archaeological investigation. He identifies a distinctive regional tradition and examines its relationship with wider architectural forms. The argument depends on a corpus of buildings, not one tower recognised from a distance."},{"type":"paragraph","text":"His discussion of Malot is especially useful for understanding comparison. The temple''s relationship with architectural traditions in Kashmir is considered through specific formal features and historical context. That is more precise than treating every temple in the region as an interchangeable instance of a broad style."},{"type":"paragraph","text":"Later scholarship on the Salt Range also discusses how earlier surveys and classifications shaped the field. Architectural terms have research histories. A label can be useful while still needing explanation about which features it groups together and which differences it leaves visible."},{"type":"heading","level":2,"text":"Read from the base to the top"},{"type":"paragraph","text":"A temple''s plan, wall articulation, projections, mouldings and surviving superstructure contribute to its interpretation. Looking only at the highest element can conceal the evidence offered by lower parts of the building. A damaged top may also distort the impression of the original profile."},{"type":"paragraph","text":"A careful description should identify what survives. Does the account concern intact masonry, fragments, an early photograph or a scholarly reconstruction? These sources can be combined, but their different status should not disappear when a drawing is reproduced."},{"type":"paragraph","text":"Chronology requires a further step. A formal resemblance may support a comparison, yet resemblance alone does not establish the exact date of construction. Inscriptions, archaeological context and a reasoned regional sequence can strengthen or revise an attribution."},{"type":"heading","level":2,"text":"Avoid the timeless temple image"},{"type":"paragraph","text":"Sites such as Katas Raj, Malot and Harnoli should not be collapsed into one undated visual tradition simply because they are all described as temples. Their individual histories, conditions and available documentation differ. A heritage category is a starting point for discovery, not a conclusion about chronology."},{"type":"paragraph","text":"The same care applies to religious continuity. A surviving form does not automatically establish that use was uninterrupted, nor does damage prove that all associations with the place ended. Architectural and community histories need their own evidence."},{"type":"paragraph","text":"For a visitor, a useful exercise is to move attention away from the summit. Notice how the entrance, walls and base organise the building before returning to the tower. Then compare those observations with a published plan or study."},{"type":"paragraph","text":"The shikhara becomes more informative when it is restored to the composition around it. Vocabulary should help readers see relationships and ask better questions, not supply an instant date that the building itself has not been shown to support."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-chakwal","punjab-mianwali"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6750","major-doam-6535","major-doam-9934"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"Reading a shikhara without guessing a date | Virsapur","description":"A shikhara belongs to an architectural composition, not a ready-made date label. Salt Range temple research shows the value of regional comparison and careful attention to surviving fabric.","primaryKeyword":"shikhara temple architecture","socialTitle":"Reading a shikhara without guessing a date","socialDescription":"A shikhara belongs to an architectural composition, not a ready-made date label. Salt Range temple research shows the value of regional comparison and careful attention to surviving fabric."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Temples Along the Indus","url":"https://www.penn.museum/sites/expedition/temples-along-the-indus/","publisher":"Michael W. Meister / Penn Museum","accessDate":"2026-10-22"},{"title":"The Salt Range Temples of the Shahi Period","url":"https://shahi.pubpub.org/pub/the-salt-range-temples-of-the-shahi-period/release/1","publisher":"Shahi research publication","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"editorialReason":"Introduce architectural vocabulary while warning against dating a temple from one shape alone.","internalNotes":"Original review draft. Specific scholarly observations distinguished from original architectural/archaeological analysis. Related Place links are comparative context, not unsupported claims that every linked structure exhibits the discussed feature. Verify specialist terminology, bibliography and local technical documentation before publication.","sortOrder":170}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-brick-bonds-as-evidence-of-building-change','brick-bonds-as-evidence-of-building-change','review','{"id":"story-brick-bonds-as-evidence-of-building-change","type":"story","slug":"brick-bonds-as-evidence-of-building-change","title":"Brick bonds as evidence of building change","summary":"Brickwork can reveal blocked openings and successive repairs, but a bond is evidence to interpret, not a date stamp.","body":[{"type":"paragraph","text":"A brick wall records decisions at several scales. There is the size of each brick, the direction of its exposed face, the thickness of its joint and the larger arrangement around openings. A bond is the pattern in which bricks are laid. Recognising that pattern can make an apparently uniform elevation much easier to read, especially where a doorway has been filled or a damaged corner rebuilt."},{"type":"paragraph","text":"A stretcher presents the brick''s long face; a header presents its shorter end. Alternating these faces can help connect the outer appearance to the wall''s construction, although a photograph of the surface cannot reveal every internal connection. Decorative brickwork, thin facing layers and later repairs complicate the relationship between the visible pattern and the wall behind it."},{"type":"heading","level":2,"text":"Start with the interruption"},{"type":"paragraph","text":"Imagine a wall whose regular courses stop at a vertical seam. On one side, joints continue across an arch; on the other, smaller units fill its opening. This is a useful hypothetical observation: the opening and its infill may represent different episodes. It does not establish who blocked it, why, or in which year. Those questions require other evidence, including construction joints, documents and earlier photographs."},{"type":"paragraph","text":"A change in colour alone is weaker evidence. Firing, weather exposure, moisture and cleaning can alter appearance. Conversely, a skilful repair may reproduce an earlier bond very closely. The SPAB''s brick-repair guidance explicitly recommends matching replacement units and their laying pattern to existing work. A convincing visual match therefore cannot guarantee that all the bricks are contemporary."},{"type":"heading","level":2,"text":"Compare relationships, not isolated samples"},{"type":"paragraph","text":"At large masonry sites such as Ranikot or Shah Rukn-e-Alam''s tomb, a useful enquiry would compare a particular wall segment with adjacent corners, openings and repaired areas. These are suggested questions for documented investigation, not a claim that one published photograph has established either monument''s sequence. The unit of observation should be a mapped area, rather than an attractive brick collected from somewhere nearby."},{"type":"paragraph","text":"Record which course meets which feature. Does a joint pass continuously behind an added support? Does an opening cut through earlier work? Are reused bricks distributed randomly or confined to a patch? A measured sketch can separate these observations from the chronological interpretation written alongside them. If access is restricted, retain that uncertainty instead of completing hidden masonry from imagination."},{"type":"heading","level":2,"text":"A wall does not need to look uniform"},{"type":"paragraph","text":"The public value of brickwork includes its evidence of maintenance. Rebuilding every irregular patch into one flawless pattern may remove the very relationships that explain the building''s life. Equally, a damaged wall needs assessment rather than romantic neglect. Material identification, structural judgement and conservation decisions belong to qualified specialists."},{"type":"paragraph","text":"For the visitor, the rewarding habit is simpler: follow a course, notice where it changes, then ask what evidence could explain the interruption. Bond names begin that conversation. They do not finish it."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["sindh-jamshoro","punjab-multan"],"provinceRegionIds":["sindh","punjab"],"relatedHeritageIds":["major-doam-5168","major-doam-6431"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"Brick bonds as evidence of building change | Virsapur","description":"Brickwork can reveal blocked openings and successive repairs, but a bond is evidence to interpret, not a date stamp.","primaryKeyword":"historic brick bonds Pakistan","socialTitle":"Brick bonds as evidence of building change","socialDescription":"Brickwork can reveal blocked openings and successive repairs, but a bond is evidence to interpret, not a date stamp."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"A guide to the repair of old brick walls","url":"https://www.spab.org.uk/advice/guide-repair-old-brick-walls","publisher":"Society for the Protection of Ancient Buildings","accessDate":"2026-10-22"},{"title":"Brick","url":"https://www.engineshed.scot/building-advice/building-materials/brick/","publisher":"Historic Environment Scotland","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original sourced review draft. Comparative examples and hypothetical observations are marked; linked places do not imply unverified technical findings. Editorial fact and terminology review required before publication.","editorialReason":"Distinguish repair phases and masonry observations from unsupported chronological certainty.","sortOrder":171}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-lime-mortar-and-the-problem-with-incompatible-repair','lime-mortar-and-the-problem-with-incompatible-repair','review','{"id":"story-lime-mortar-and-the-problem-with-incompatible-repair","type":"story","slug":"lime-mortar-and-the-problem-with-incompatible-repair","title":"Lime mortar and the problem with incompatible repair","summary":"A compatible mortar must work with the existing masonry and its environment. Choosing a repair is more demanding than choosing a colour.","body":[{"type":"paragraph","text":"Mortar is easily overlooked because it occupies the space between more conspicuous materials. Yet those joints influence how a wall responds to water, movement and repair. A neat new joint can be physically unsuitable; a weathered old joint can still contain valuable evidence. Conservation therefore asks how materials work together, not whether the latest intervention looks unusually clean."},{"type":"paragraph","text":"Lime is not one uniform product. The SPAB distinguishes types with different setting behaviour and explains the trade-off between greater hydraulic strength and reduced permeability and flexibility. That distinction matters because the word lime on a bag does not, by itself, establish compatibility with a particular historic wall. Aggregate, proportions, exposure and workmanship also require assessment."},{"type":"heading","level":2,"text":"Stronger is not automatically better"},{"type":"paragraph","text":"A repair material is part of a system that includes bricks or stone, earlier mortar, plaster, ground moisture and rainwater disposal. Judging one ingredient in isolation misses that system. If an intervention changes where moisture escapes, the problem can migrate rather than disappear. A sound conservation proposal must explain the mechanism of deterioration before presenting its chosen material as a solution."},{"type":"paragraph","text":"Lahore provides a concrete reason to investigate water as well as surfaces. AKDN''s account of Wazir Khan Mosque identifies leaking water and accumulated street deposits among threats to the building. The important lesson is not a transferable recipe from one monument. It is that a decorative or masonry repair cannot be separated from the conditions affecting its foundations and surroundings."},{"type":"heading","level":2,"text":"What a useful assessment should establish"},{"type":"paragraph","text":"Before work, a specialist needs to distinguish original material from previous interventions, understand where deterioration is active and document any proposed sampling. A fragment of mortar without a recorded location may reveal a composition but lose the relationship that makes the result useful. Samples from sheltered and exposed areas may answer different questions."},{"type":"paragraph","text":"A repair specification should then connect diagnosis to a limited intervention: what will be retained, what must be repaired, how compatibility will be assessed, and how performance will be monitored. The published Pakistan Journal of Science study on lime mortar places this question within conservation work on Pakistani historic buildings. It is a field of analysis, not an invitation to improvise a mixture beside a monument."},{"type":"heading","level":2,"text":"Maintenance belongs in the story"},{"type":"paragraph","text":"Shahi Hammam and Chauburji are useful starting points for exploring Lahore''s conservation history, but neither should become a universal demonstration of a treatment without a project-specific report. Photographs cannot establish mortar composition, hidden moisture paths or the safety of removing an earlier repair."},{"type":"paragraph","text":"For owners and visitors, the practical first step is documentation and professional advice, not scraping out joints or applying a stronger coating. Record the location and progression of visible damage without touching it. A responsible outcome may look modest: retained fabric, corrected water problems and carefully specified repairs. Its success lies in continued performance, rather than an immediate impression of newness."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-lahore"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-9778","major-doam-6495"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"Lime mortar and the problem with incompatible repair | Virsapur","description":"A compatible mortar must work with the existing masonry and its environment. Choosing a repair is more demanding than choosing a colour.","primaryKeyword":"lime mortar heritage repair","socialTitle":"Lime mortar and the problem with incompatible repair","socialDescription":"A compatible mortar must work with the existing masonry and its environment. Choosing a repair is more demanding than choosing a colour."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Lime","url":"https://www.spab.org.uk/advice/lime","publisher":"Society for the Protection of Ancient Buildings","accessDate":"2026-10-22"},{"title":"Lime mortar in conservation for historic buildings of Pakistan","url":"https://nja.pastic.gov.pk/journals/index.php/PJS/article/view/4458","publisher":"Pakistan Journal of Science","accessDate":"2026-10-22"},{"title":"Walled city of Lahore conservation","url":"https://www-hetz2.the.akdn/en/where-we-work/south-asia/pakistan/walled-city-of-lahore-conservation-pakistan","publisher":"Aga Khan Development Network","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original sourced review draft. Comparative examples and hypothetical observations are marked; linked places do not imply unverified technical findings. Editorial fact and terminology review required before publication.","editorialReason":"Explain compatibility and specialist assessment without offering unsafe do-it-yourself conservation advice.","sortOrder":172}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-why-timber-matters-in-mountain-architecture','why-timber-matters-in-mountain-architecture','review','{"id":"story-why-timber-matters-in-mountain-architecture","type":"story","slug":"why-timber-matters-in-mountain-architecture","title":"Why timber matters in mountain architecture","summary":"In Baltistan, timber is structure, joinery and skilled knowledge—not merely a decorative mountain motif.","body":[{"type":"paragraph","text":"A carved balcony is often the first timber element a visitor notices in a mountain palace. The less conspicuous connections may matter just as much: the way a beam meets a post, how a frame accommodates an opening, or how wood and masonry share a wall. Looking only at the carving reduces a building technology to a decorative style."},{"type":"paragraph","text":"The Department of Archaeology and Museums describes Shigar Fort as several adjoining structures from different phases, not a single construction event. Its account also draws attention to decorated timber-framed elements. That combination is important. A visitor should ask how each phase was built and joined, rather than assume that everything inside a visually unified palace follows one structural system."},{"type":"heading","level":2,"text":"A material and a network of skills"},{"type":"paragraph","text":"AKDN reports that conservation in Shigar helped revive carpentry and woodcarving and encouraged renewed use of traditional construction knowledge. Such skills cannot be preserved by keeping one attractive doorway behind glass alone. They involve selecting and working material, understanding joints, recognising deterioration and making decisions about repair within a larger building."},{"type":"paragraph","text":"This is also why the identity and contribution of craftspeople belong in interpretation. A label naming only a royal patron tells readers who commissioned a palace, but leaves its making almost anonymous. Where project records permit, a fuller account can identify the people responsible for survey, joinery, conservation and continuing maintenance without treating them as interchangeable carriers of an unchanging tradition."},{"type":"heading","level":2,"text":"Timber is not a promise of invulnerability"},{"type":"paragraph","text":"It is tempting to describe every timber-laced mountain building as earthquake-proof. That claim goes much further than a photograph or a general description can support. Performance depends on configuration, connections, condition, foundations and the particular forces acting on the building. A responsible description identifies documented construction features without promising universal safety."},{"type":"paragraph","text":"The conservation account for Khaplu Palace records serious decay associated with water ingress and timber deterioration. The project responded through documentation, structural analysis and interventions tailored to different conditions. This is evidence against the fantasy of a maintenance-free vernacular structure: skilled original construction and careful modern conservation both require attention to the building''s vulnerabilities."},{"type":"heading","level":2,"text":"Read the whole assembly"},{"type":"paragraph","text":"When viewing an accessible room, compare posts, beams, wall panels and the roof above them. Which elements appear continuous? Which are replaced? Is an ornamental surface attached to a structural member, or is it a separate component? A guide or conservation drawing may answer questions that cannot be resolved by sight."},{"type":"paragraph","text":"Shigar, Khaplu and Chaqchan offer different settings for this enquiry; their histories should not be collapsed into one generic mountain house. Permission, structural restrictions and present religious or residential use still govern access."},{"type":"paragraph","text":"Timber''s importance becomes clearer when the visitor moves from a catalogue of motifs to a record of relationships. The building is not simply wood beside stone. It is a negotiated assembly of materials, labour, environment and successive decisions about keeping a place in use."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Gilgit-Baltistan","Architecture"],"province":"Gilgit-Baltistan","district":null,"relatedDistrictIds":["gilgit-baltistan-shigar","gilgit-baltistan-ghanche"],"provinceRegionIds":["gilgit-baltistan"],"relatedHeritageIds":["major-doam-7998","major-doam-7974","major-doam-7969"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"Why timber matters in mountain architecture | Virsapur","description":"In Baltistan, timber is structure, joinery and skilled knowledge—not merely a decorative mountain motif.","primaryKeyword":"timber mountain architecture Pakistan","socialTitle":"Why timber matters in mountain architecture","socialDescription":"In Baltistan, timber is structure, joinery and skilled knowledge—not merely a decorative mountain motif."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Shigar Fort Palace","url":"https://doam.gov.pk/public/sites/7998","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Conservation of Khaplu Palace Complex, Pakistan","url":"https://www.whitr-ap.org/index.php?classid=1490&newsid=2013&t=show","publisher":"World Heritage Institute of Training and Research for Asia and the Pacific","accessDate":"2026-10-22"},{"title":"Conservation and development in Gilgit-Baltistan","url":"https://www-hetz2.the.akdn/en/where-we-work/south-asia/pakistan/conservation-and-development-in-gilgit-baltistan-pakistan","publisher":"Aga Khan Development Network","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original sourced review draft. Comparative examples and hypothetical observations are marked; linked places do not imply unverified technical findings. Editorial fact and terminology review required before publication.","editorialReason":"Connect joinery and local building knowledge while avoiding universal earthquake-proof claims.","sortOrder":173}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-a-jharokha-looking-out-and-being-seen','a-jharokha-looking-out-and-being-seen','review','{"id":"story-a-jharokha-looking-out-and-being-seen","type":"story","slug":"a-jharokha-looking-out-and-being-seen","title":"A jharokha: looking out and being seen","summary":"A projecting window connects room and street. Its meaning depends on access, visibility and the building around it.","body":[{"type":"paragraph","text":"A jharokha projects beyond the main face of a building, making an opening into a small spatial event. It can enlarge a view, create shade below and give a facade a point of emphasis. Calling it an ornamental window is therefore incomplete. It changes the relationship between a person inside a room and the space outside."},{"type":"paragraph","text":"That relationship has at least two directions. Someone may look outward through an opening, while the projecting structure makes the building—and sometimes its occupants—more visible from the street. Screening, height, depth and the route into the room modify these possibilities. The same outward form does not establish one identical social practice wherever it appears."},{"type":"heading","level":2,"text":"Follow the projection back inside"},{"type":"paragraph","text":"The official Gilgit-Baltistan description of Khaplu Palace offers a useful example of spatial continuity: its timber entrance develops into a balcony and then an upper room. The Department of Archaeology and Museums similarly identifies a prominent, multi-storey projecting timber feature. Here, the facade cannot be fully understood as a flat decorative composition. It belongs to a vertical arrangement of spaces."},{"type":"paragraph","text":"A careful architectural reading would connect the exterior to a plan or section. Is the projection accessible from one private room, a hall or a circulation passage? Can someone pause there without blocking movement? Is its floor level aligned with the space behind it? These questions are more revealing than assigning a purpose from carving alone."},{"type":"heading","level":2,"text":"Avoid a ready-made social story"},{"type":"paragraph","text":"A screen does not automatically prove that every person behind it was a secluded woman. A prominent balcony does not prove that a ruler addressed crowds from that exact position. Such interpretations may be correct in particular documented settings, but they need testimony, plans, paintings or records tied to the building under discussion."},{"type":"paragraph","text":"For Lahore''s Nau Nihal Singh Haveli, the official catalogue records spacious rooms, halls and balconies within a private residence. It provides a secure starting point for thinking about the relationship of interior space to a richly worked exterior. It does not license an invented account of a specific ceremony seen through every projecting opening."},{"type":"heading","level":2,"text":"Photograph the relationship, not only the detail"},{"type":"paragraph","text":"A useful set of permitted photographs would include the whole elevation, the feature''s connection to neighbouring openings and a closer view of its support and screening. Cropping out the street or courtyard can conceal the very relationship that makes a jharokha interesting. Where the interior is private or access is restricted, a missing view should remain missing."},{"type":"paragraph","text":"The havelis at Hazro and Khem Singh Bedi''s Rawalpindi district setting invite comparison through their own records, not through a single borrowed explanation. Variation is the subject, rather than an obstacle to a tidy definition."},{"type":"paragraph","text":"A jharokha rewards the visitor who asks two questions together: what can be seen from here, and what does this projection make visible to others? The answer begins with architecture but may lead toward a carefully evidenced social history."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-lahore","punjab-attock","punjab-rawalpindi"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6446","major-doam-7659","major-doam-7053"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"A jharokha: looking out and being seen | Virsapur","description":"A projecting window connects room and street. Its meaning depends on access, visibility and the building around it.","primaryKeyword":"jharokha architectural meaning","socialTitle":"A jharokha: looking out and being seen","socialDescription":"A projecting window connects room and street. Its meaning depends on access, visibility and the building around it."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Haveli Nau Nihal Singh, including garden and quarters","url":"https://doam.gov.pk/public/sites/6446","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Khaplu Fort","url":"https://www.visitgilgitbaltistan.gov.pk/tour/id/65","publisher":"Government of Gilgit-Baltistan","accessDate":"2026-10-22"},{"title":"Khaplu Palace, Yabgo Khar","url":"https://doam.gov.pk/public/sites/7841","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original sourced review draft. Comparative examples and hypothetical observations are marked; linked places do not imply unverified technical findings. Editorial fact and terminology review required before publication.","editorialReason":"Read a projecting window as space and social interface, not merely ornament.","sortOrder":174}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-carved-doors-and-the-architecture-of-thresholds','carved-doors-and-the-architecture-of-thresholds','review','{"id":"story-carved-doors-and-the-architecture-of-thresholds","type":"story","slug":"carved-doors-and-the-architecture-of-thresholds","title":"Carved doors and the architecture of thresholds","summary":"A historic door is a working boundary. Carving, hinges and the route beyond it all contribute to its meaning.","body":[{"type":"paragraph","text":"An elaborate door invites a close photograph, but its carving is only part of the architecture. A threshold organises entry. It separates spaces, accommodates movement and establishes the moment at which a visitor must pause, turn or seek permission. To understand a door, look at what approaches it and what lies immediately beyond."},{"type":"paragraph","text":"The official record of Haveli Sujan Singh in Rawalpindi describes a recessed entrance porch, an ornate main door and circulation towards stairs, entrance rooms and the courtyard. These relationships prevent the doorway from becoming a detached work of decorative art. It belonged to an arrangement of access, with different possible routes through the building."},{"type":"heading","level":2,"text":"The frame is part of the evidence"},{"type":"paragraph","text":"Distinguish the moving leaf from its frame and surrounding masonry. Carving may continue across one component but stop at another. Hinges, sockets, locks and worn edges can raise questions about operation and alteration. A mismatched frame may indicate modification, although identifying its date or original location requires more than visual suspicion."},{"type":"paragraph","text":"Consider a hypothetical door whose decorated upper panel fits awkwardly inside a later frame. One possibility is reuse; another is repair or adjustment in place. The visible mismatch is an observation. The story explaining it remains a hypothesis until measurements, joinery evidence or records support it. This separation protects a compelling detail from becoming a confident but invented biography."},{"type":"heading","level":2,"text":"Entering is a sequence"},{"type":"paragraph","text":"At the historic haveli catalogued in Lawa, the Department of Archaeology and Museums describes steps, a series of arches and a veranda leading to a wooden door. It also records niches beside the entrance. The important effect is cumulative: a threshold can begin well before the actual door leaf. A facade photograph that excludes the steps and approach loses that sequence."},{"type":"paragraph","text":"The decoration may direct attention towards the main entrance, but a larger doorway is not automatically evidence of unrestricted public access. Visitors, residents, service workers and animals may have used different routes in a building''s history. Plans and testimony are needed before assigning these movements to particular people."},{"type":"heading","level":2,"text":"Keep the door attached to its place"},{"type":"paragraph","text":"Architectural woodwork is especially vulnerable to being appreciated as a collectible fragment. Once removed, a door may retain its carving while losing information about height, orientation, adjacent rooms and later use. A museum or collection record should therefore distinguish a documented original location from a broad stylistic attribution."},{"type":"paragraph","text":"At an occupied or supervised heritage property, do not open a door simply to test its mechanism, lean against a fragile leaf or move fittings for a photograph. Permission to visit a courtyard is not permission to enter every room."},{"type":"paragraph","text":"The most rewarding doorway description combines craft with movement: material and carving, frame and fastening, approach and destination. That account lets a threshold remain what it was architecturally—a relationship between spaces—rather than reducing it to a beautiful rectangle."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-rawalpindi","punjab-talagang"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-9419","major-doam-6806"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"Carved doors and the architecture of thresholds | Virsapur","description":"A historic door is a working boundary. Carving, hinges and the route beyond it all contribute to its meaning.","primaryKeyword":"carved wooden doors Pakistan","socialTitle":"Carved doors and the architecture of thresholds","socialDescription":"A historic door is a working boundary. Carving, hinges and the route beyond it all contribute to its meaning."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Haveli Sujan Singh","url":"https://doam.gov.pk/public/sites/9419","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Haveli-I, Tehsil Talagang","url":"https://doam.gov.pk/public/sites/6806","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original sourced review draft. Comparative examples and hypothetical observations are marked; linked places do not imply unverified technical findings. Editorial fact and terminology review required before publication.","editorialReason":"Use entrances to discuss movement, craft and later alteration.","sortOrder":175}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-tile-mosaic-and-glazed-brick-not-interchangeable-terms','tile-mosaic-and-glazed-brick-not-interchangeable-terms','review','{"id":"story-tile-mosaic-and-glazed-brick-not-interchangeable-terms","type":"story","slug":"tile-mosaic-and-glazed-brick-not-interchangeable-terms","title":"Tile mosaic and glazed brick: not interchangeable terms","summary":"A blue surface may be painted tile, cut-tile mosaic or glazed masonry. Technique should be identified before style.","body":[{"type":"paragraph","text":"Blue-and-white architectural decoration is often described with a handful of interchangeable words: tile, mosaic, glazed brick. They may refer to related materials, but they do not describe the same process. A useful account begins by asking how a pattern was made and assembled, rather than treating colour as a complete technical identification."},{"type":"paragraph","text":"In cut-tile mosaic, individual pieces are shaped and combined into a larger design. The Metropolitan Museum''s study of Persian tiles explains this construction through a surviving mihrab from Isfahan: pieces cut from differently coloured glazed tiles form the composition. This is a comparative example, not proof that every patterned surface in Pakistan was manufactured in the same way."},{"type":"heading","level":2,"text":"Find the boundaries of the units"},{"type":"paragraph","text":"A painted tile can carry more than one colour or part of a design on a single unit. In a mosaic, changes in colour may coincide with joins between shaped pieces. Glazed brick introduces another relationship between a ceramic surface and masonry. These distinctions affect how curves, lettering and repeated patterns are produced, and how damaged areas can be understood."},{"type":"paragraph","text":"From an appropriate viewing distance, look for seams and repeated modules. Does a flower continue across rectangular tile joints? Are small pieces fitted around the curves of a letter? Does the glazed face follow the dimensions and bond of masonry units? A clear answer may require technical photography or conservation documentation; a distant image can conceal the relevant joins."},{"type":"heading","level":2,"text":"Compare without flattening regional difference"},{"type":"paragraph","text":"The Shah Jahan Mosque at Thatta, Wazir Khan Mosque in Lahore and Shah Rukn-e-Alam''s tomb in Multan are valuable starting points for comparison. Their decorative programmes should not be collapsed into one generic blue-tile tradition. Materials, geometry, placement and repair histories deserve individual description."},{"type":"paragraph","text":"AKDN''s Lahore conservation account distinguishes glazed tile mosaics from painted surface decoration at Wazir Khan Mosque. That vocabulary is useful because a single building can contain several techniques. Calling every coloured surface a fresco, or every repeated design a mosaic, obscures the work of different crafts and the different conservation problems they present."},{"type":"heading","level":2,"text":"Repairs can complicate what we see"},{"type":"paragraph","text":"A replaced area may imitate the colour and geometry of an earlier surface while using a different method. Conversely, an irregular colour can result from weathering rather than a different construction phase. The Met''s published discussion of its Isfahan mihrab records extensive restoration, a reminder that even a museum masterpiece has a material history after its initial making."},{"type":"paragraph","text":"A responsible caption can therefore say patterned glazed ceramic decoration when a closer technical identification has not been established. Precision includes knowing when to remain general."},{"type":"paragraph","text":"The visual reward is substantial. Once the eye begins to follow unit boundaries, a wall becomes a record of cutting, arranging, fitting and repair. The pattern is still beautiful, but its beauty is connected to decisions made by skilled people rather than explained by colour alone."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-lahore","sindh-thatta","punjab-multan"],"provinceRegionIds":["punjab","sindh"],"relatedHeritageIds":["major-doam-6466","major-doam-5625","major-doam-6431"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"Tile mosaic and glazed brick: not interchangeable terms | Virsapur","description":"A blue surface may be painted tile, cut-tile mosaic or glazed masonry. Technique should be identified before style.","primaryKeyword":"tile mosaic glazed brick","socialTitle":"Tile mosaic and glazed brick: not interchangeable terms","socialDescription":"A blue surface may be painted tile, cut-tile mosaic or glazed masonry. Technique should be identified before style."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Persian Tiles","url":"https://resources.metmuseum.org/resources/metpublications/pdf/Persian_Tiles.pdf","publisher":"The Metropolitan Museum of Art","accessDate":"2026-10-22"},{"title":"Shahjahani Mosque / Jamia Mosque, Thatta","url":"https://doam.gov.pk/public/sites/5625","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Walled city of Lahore conservation","url":"https://www-hetz2.the.akdn/en/where-we-work/south-asia/pakistan/walled-city-of-lahore-conservation-pakistan","publisher":"Aga Khan Development Network","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original sourced review draft. Comparative examples and hypothetical observations are marked; linked places do not imply unverified technical findings. Editorial fact and terminology review required before publication.","editorialReason":"Distinguish techniques before discussing colour or regional style.","sortOrder":176}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-fresco-painted-plaster-and-later-repainting','fresco-painted-plaster-and-later-repainting','review','{"id":"story-fresco-painted-plaster-and-later-repainting","type":"story","slug":"fresco-painted-plaster-and-later-repainting","title":"Fresco, painted plaster and later repainting","summary":"Historic wall painting may combine wet-plaster work, dry-applied details and later coatings. Appearance alone cannot separate them.","body":[{"type":"paragraph","text":"Fresco is often used casually to mean any old painting on a wall. In technical discussion, however, the way pigment meets plaster matters. Paint applied while lime plaster is wet behaves differently from paint held on a dry surface by a binder. A wall may contain more than one technique, as well as later retouching and coatings."},{"type":"paragraph","text":"Getty''s technical study of its Peacock wall painting makes this distinction unusually clear. Although the familiar name calls it a fresco, examination identified painting applied over a dried surface. The museum retains the convenient title while explaining the material evidence. That is a useful model for heritage writing: a customary name need not be discarded, but its technical limits should be visible."},{"type":"heading","level":2,"text":"A surface can contain several histories"},{"type":"paragraph","text":"Imagine a painted border with a small area of different sheen. It might be a later coating, a repair, a change of material or simply a lighting effect. A photograph cannot settle those alternatives. A conservator may need magnification, examination under different illumination and carefully justified analysis before distinguishing original paint from later intervention."},{"type":"paragraph","text":"The Getty Conservation Institute''s research on organic materials also warns against overly rigid categories. Historic painters sometimes combined techniques or worked at intermediate stages of plaster setting. It is therefore safer to describe a documented painting process than to force every surviving surface into an ideal textbook category."},{"type":"heading","level":2,"text":"Lahore''s paintings are part of buildings"},{"type":"paragraph","text":"The Punjab heritage authority identifies fresco decoration within Lal Burj and records its conservation alongside roof, floor and structural work. That combination matters: a painted interior is not an isolated canvas. Its survival depends on the roof, masonry and environmental conditions around it. A treatment focused only on brighter colour would miss the larger system."},{"type":"paragraph","text":"Shahi Hammam and Khem Singh Bedi Haveli are further places from which to investigate painted architectural surfaces through their own documentation. Their inclusion in a discovery route does not establish that every visible painting is original or executed with the same binding medium. Those are questions for specific records."},{"type":"heading","level":2,"text":"Newness is not a measure of authenticity"},{"type":"paragraph","text":"A vivid panel may be well preserved, recently conserved or heavily repainted. A muted panel may be old, dirty, altered by a coating or affected by pigment change. None of these possibilities can be ranked from saturation alone. Before praising a restoration for making a wall look new, ask what was retained and how additions were documented."},{"type":"paragraph","text":"Useful interpretation can distinguish surviving early work, later historic layers, modern conservation fills and areas where evidence is incomplete. A diagram or paired photograph may communicate this more honestly than a seamless reconstruction."},{"type":"paragraph","text":"For visitors, the restraint is straightforward: no touching, wetting, rubbing or improvised cleaning to reveal a design. The reward of careful looking is not merely discovering a hidden picture. It is understanding a layered surface whose history includes making, use, alteration and the decisions involved in keeping it visible."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-lahore","punjab-rawalpindi"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-9778","major-doam-7053"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"Fresco, painted plaster and later repainting | Virsapur","description":"Historic wall painting may combine wet-plaster work, dry-applied details and later coatings. Appearance alone cannot separate them.","primaryKeyword":"historic fresco Pakistan","socialTitle":"Fresco, painted plaster and later repainting","socialDescription":"Historic wall painting may combine wet-plaster work, dry-applied details and later coatings. Appearance alone cannot separate them."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"The Getty Peacock Fresco","url":"https://www.getty.edu/publications/getty-research-journal/21/the-getty-peacock-fresco/","publisher":"Getty Research Journal","accessDate":"2026-10-22"},{"title":"Organic Materials in Wall Paintings","url":"https://www.getty.edu/conservation/publications_resources/pdf_publications/pdf/omwp_report.pdf","publisher":"Getty Conservation Institute","accessDate":"2026-10-22"},{"title":"Lal Burj","url":"https://walledcitylahore.gop.pk/lal-burj/","publisher":"Punjab Walled Cities and Heritage Areas Authority","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original sourced review draft. Comparative examples and hypothetical observations are marked; linked places do not imply unverified technical findings. Editorial fact and terminology review required before publication.","editorialReason":"Explain how descriptions and conservation records distinguish painted surfaces.","sortOrder":177}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-ghalibkari-and-the-shaping-of-a-decorated-ceiling','ghalibkari-and-the-shaping-of-a-decorated-ceiling','review','{"id":"story-ghalibkari-and-the-shaping-of-a-decorated-ceiling","type":"story","slug":"ghalibkari-and-the-shaping-of-a-decorated-ceiling","title":"Ghalibkari and the shaping of a decorated ceiling","summary":"Ghalibkari gives patterned relief to curved surfaces. Reading its ribs and setting is more useful than treating every decorated vault alike.","body":[{"type":"paragraph","text":"A decorated vault can be difficult to describe because several kinds of work occupy the same field of vision. Ribs cast shadows; paint gives them colour; adjoining panels carry floral or geometric designs. Ghalibkari is useful vocabulary for one part of that composition, but it should not become a general label for every elaborate ceiling."},{"type":"paragraph","text":"The Punjab heritage authority describes ghalib kari at the gateway associated with Jahangir''s tomb as a network of stucco or plaster ribs applied to curved surfaces. Its account distinguishes that work from the muqarnas of the central space. The distinction provides a concrete starting point: related ornamental effects can coexist without being technically identical."},{"type":"heading","level":2,"text":"Look for a system of lines"},{"type":"paragraph","text":"From the permitted viewing area, trace how a rib begins, divides and meets another. Does the pattern respond to the centre of the vault, repeat along its length or change at the edge of an opening? The shape of the supporting surface matters. A flat photograph can make a pattern look like a drawing when it is actually organised across depth."},{"type":"paragraph","text":"Shadow can help reveal relief, but lighting also deceives. Painted lines may imitate raised work, while heavy coatings may soften the edges of actual ribs. A visual description should therefore identify what is observable and leave material attribution to records or close examination where necessary."},{"type":"heading","level":2,"text":"Ornament is not automatically structure"},{"type":"paragraph","text":"A rib-like feature may organise the eye without carrying the building''s principal load. Conversely, an architectural member can be both structural and ornamented. It is unsafe to infer the hidden construction of a vault simply because its surface resembles a diagram of forces. Sections, surveys and technical reports are needed for that judgement."},{"type":"paragraph","text":"This distinction also changes interpretation. Instead of calling the ceiling ingenious engineering on appearance alone, a writer can explain how relief establishes scale, concentrates attention or subdivides a large curved surface. Those observations describe the visitor''s encounter without inventing a structural explanation."},{"type":"heading","level":2,"text":"Keep the terminology tied to a place"},{"type":"paragraph","text":"Jahangir''s tomb complex supplies a documented example for this introduction. Nadira Begum''s tomb is another linked monument for further architectural exploration, not an automatic second example of the same technique. A place association in a catalogue must not become a technical claim that the source has not made."},{"type":"paragraph","text":"Condition matters too. Cracks, missing sections, later paint and repairs may interrupt a design. Reconstructing the missing pattern in a graphic should be explicitly identified as an interpretation, rather than presented as an unbroken survival. Even a repeated motif may have changed at a corner or transition."},{"type":"paragraph","text":"The visitor''s task is not to memorise an exotic label and move on. It is to use that label to notice the relationship between surface, relief, light and architectural setting. A carefully described ceiling can then reveal a precise craft tradition without dissolving into a vague celebration of decoration."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-lahore"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6479","major-doam-6485"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"Ghalibkari and the shaping of a decorated ceiling | Virsapur","description":"Ghalibkari gives patterned relief to curved surfaces. Reading its ribs and setting is more useful than treating every decorated vault alike.","primaryKeyword":"ghalibkari decoration","socialTitle":"Ghalibkari and the shaping of a decorated ceiling","socialDescription":"Ghalibkari gives patterned relief to curved surfaces. Reading its ribs and setting is more useful than treating every decorated vault alike."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Monuments: Tomb of Jahangir and Akbari Sarai","url":"https://walledcitylahore.gop.pk/monuments/","publisher":"Punjab Walled Cities and Heritage Areas Authority","accessDate":"2026-10-22"},{"title":"Jahangir''s Tomb and Compound","url":"https://doam.gov.pk/public/sites/6479","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Organic Materials in Wall Paintings","url":"https://www.getty.edu/projects/organic-materials-wall-paintings/","publisher":"Getty Conservation Institute","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original sourced review draft. Comparative examples and hypothetical observations are marked; linked places do not imply unverified technical findings. Editorial fact and terminology review required before publication.","editorialReason":"Introduce a specific ornamental technique with verified examples and careful terminology.","sortOrder":178}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-calligraphy-as-part-of-an-architectural-facade','calligraphy-as-part-of-an-architectural-facade','review','{"id":"story-calligraphy-as-part-of-an-architectural-facade","type":"story","slug":"calligraphy-as-part-of-an-architectural-facade","title":"Calligraphy as part of an architectural facade","summary":"Architectural calligraphy is simultaneously text, scale and spatial organisation. Reading its position is not a substitute for translating it.","body":[{"type":"paragraph","text":"An inscription can organise a facade before a visitor has read a single word. A band may frame an entrance, establish a horizontal line or draw the eye towards a central opening. That visual effect is real, but it is only one part of calligraphy''s work. The writing carries language, and its meaning should not disappear into a description of elegant decoration."},{"type":"paragraph","text":"The Metropolitan Museum''s account of calligraphy stresses both its textual function and its varied relationship with ornament. Some compositions give lettering visual priority; others combine it with geometric or vegetal patterns. Architectural interpretation becomes richer when it asks how those relationships operate at the scale of a doorway, wall or dome."},{"type":"heading","level":2,"text":"Separate three kinds of reading"},{"type":"paragraph","text":"The first reading is spatial. Where is the inscription, how large is it and from what position is it legible? The second is material: was it cut, painted, assembled from ceramic pieces or worked by another process? The third is linguistic and historical: what does it say, in which language and script, and how securely is its date or authorship known?"},{"type":"paragraph","text":"A confident answer to one question does not settle the others. Someone may identify a repeated geometric frame without being qualified to transcribe the text inside it. Conversely, a translation may tell us little about the placement or subsequent repair of the physical inscription."},{"type":"heading","level":2,"text":"The order of the words matters"},{"type":"paragraph","text":"A museum tile panel from Kashan illustrates why text and material must be studied together. The Met explains that gaps in its Qur''anic passage help scholars reconstruct how individual tiles were positioned in a larger frame. This is a comparison from Iran, not a claim about a particular Pakistani monument. It shows how writing can supply evidence for an architectural arrangement."},{"type":"paragraph","text":"The reverse is also important. A displaced panel or an incorrectly assembled repair may disturb a sequence. Treating calligraphy as pattern alone can conceal that problem, especially when photographs crop individual letters away from their neighbours."},{"type":"heading","level":2,"text":"Read Lahore with appropriate caution"},{"type":"paragraph","text":"Wazir Khan Mosque offers a particularly strong setting for exploring the relationship between writing, architectural surfaces and the surrounding city. The Punjab heritage authority also identifies the Calligraphers'' Bazaar within the entrance arrangement. This connection should prompt questions about spatial setting and craft, without suggesting that every surviving inscription can be assigned to a named workshop."},{"type":"paragraph","text":"At Chauburji or another decorated gateway, a responsible caption should use a reliable transcription and translation, identify the source and mark damaged or uncertain passages. Decorative resemblance alone is not sufficient to name a calligrapher or attribute the work to a ruler."},{"type":"paragraph","text":"A useful photograph preserves the whole inscription and enough architecture to locate it. A useful description preserves both what the words communicate and how the building presents them. Together, these forms of attention allow calligraphy to remain language in a place, rather than a beautiful surface stripped of its voice."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-lahore"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6466","major-doam-6495"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"Calligraphy as part of an architectural facade | Virsapur","description":"Architectural calligraphy is simultaneously text, scale and spatial organisation. Reading its position is not a substitute for translating it.","primaryKeyword":"architectural calligraphy Pakistan","socialTitle":"Calligraphy as part of an architectural facade","socialDescription":"Architectural calligraphy is simultaneously text, scale and spatial organisation. Reading its position is not a substitute for translating it."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Calligraphy in Islamic Art","url":"https://www.metmuseum.org/es/essays/calligraphy-in-islamic-art","publisher":"The Metropolitan Museum of Art","accessDate":"2026-10-22"},{"title":"Tile Panel, object 12.34.3","url":"https://www.metmuseum.org/art/collection/search/446200","publisher":"The Metropolitan Museum of Art","accessDate":"2026-10-22"},{"title":"Monuments: Wazir Khan Mosque","url":"https://walledcitylahore.gop.pk/monuments/","publisher":"Punjab Walled Cities and Heritage Areas Authority","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original sourced review draft. Comparative examples and hypothetical observations are marked; linked places do not imply unverified technical findings. Editorial fact and terminology review required before publication.","editorialReason":"Explain placement and visual hierarchy without inventing translations or attribution.","sortOrder":179}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-mihrab-and-the-organisation-of-a-prayer-hall','the-mihrab-and-the-organisation-of-a-prayer-hall','review','{"id":"story-the-mihrab-and-the-organisation-of-a-prayer-hall","type":"story","slug":"the-mihrab-and-the-organisation-of-a-prayer-hall","title":"The mihrab and the organisation of a prayer hall","summary":"The mihrab identifies the direction of prayer; understanding it requires reading the hall and its use, not only the niche.","body":[{"type":"paragraph","text":"A mihrab is a directional focus within a mosque or another Muslim prayer setting. Often formed as a niche, it identifies the qibla, the direction towards Mecca. Its significance does not depend on exceptional size or decoration. A modest example can organise a room as clearly as one covered in elaborate tilework."},{"type":"paragraph","text":"The Metropolitan Museum''s educational account makes the directional function explicit through a surviving mihrab from an Iranian religious school. Smarthistory''s architectural introduction places the niche within the qibla wall and distinguishes it from other mosque elements. These comparative sources help establish vocabulary, while individual Pakistani buildings still require their own plans and histories."},{"type":"heading","level":2,"text":"Begin with the prayer space"},{"type":"paragraph","text":"A close photograph of a mihrab can conceal the hall''s organisation. Step back, where access and worship permit, and consider the width of the wall, the rhythm of supporting elements and the relationship between covered space and courtyard. The architectural question is not only where the niche is, but how the room enables people to orient themselves towards the same direction."},{"type":"paragraph","text":"An entrance need not stand directly opposite the mihrab. Circulation, site constraints and later alterations can produce more complicated approaches. A visitor should therefore avoid drawing a simple symmetrical plan from one frontal image. The route by which people reach the prayer area is part of the building''s evidence."},{"type":"heading","level":2,"text":"Do not confuse neighbouring elements"},{"type":"paragraph","text":"The minbar is associated with the delivery of a sermon; it is not another name for the mihrab. A minaret is a tower, not the niche. These distinctions sound elementary, yet they matter when captions describe a photograph or a catalogue connects an architectural detail to a place."},{"type":"paragraph","text":"Decoration is a further, separate layer. Tilework, carved material, plaster and inscriptions may emphasise the qibla wall, but colour does not determine function. Nor does a resemblance to a mihrab prove that every niche elsewhere in a building served the same purpose. Context and documented use remain essential."},{"type":"heading","level":2,"text":"Compare through evidence, not a fixed template"},{"type":"paragraph","text":"The Sawi Mosque in Multan and the Bari Mosque at Pasrur are linked starting points for looking at regional prayer architecture. Their inclusion here does not establish identical plans, dates or decorative programmes. A meaningful comparison would record each building''s orientation, surviving fabric, alterations and present use before considering shared features."},{"type":"paragraph","text":"Historic orientation itself deserves careful treatment. Surveyed alignment and the methods available to builders may not correspond perfectly with a modern digital bearing. A small discrepancy is not, by itself, evidence that a building was wrongly identified or that worship lacked a directional focus."},{"type":"paragraph","text":"Finally, an active mosque is not an empty architectural exhibit. Ask about permitted access and photography, avoid interrupting worship and do not enter a niche for a portrait. Understanding the mihrab means recognising the community and practice that give the architectural focus its purpose."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-multan","punjab-sialkot"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6433","major-doam-6217"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"The mihrab and the organisation of a prayer hall | Virsapur","description":"The mihrab identifies the direction of prayer; understanding it requires reading the hall and its use, not only the niche.","primaryKeyword":"mihrab mosque architecture","socialTitle":"The mihrab and the organisation of a prayer hall","socialDescription":"The mihrab identifies the direction of prayer; understanding it requires reading the hall and its use, not only the niche."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Mihrab, Image 4: Art of the Islamic World","url":"https://www.metmuseum.org/de/learn/educators/curriculum-resources/art-of-the-islamic-world/unit-one/featured-works-of-art/image-4","publisher":"The Metropolitan Museum of Art","accessDate":"2026-10-22"},{"title":"Mosque architecture, an introduction","url":"https://smarthistory.org/introduction-to-mosque-architecture/","publisher":"Smarthistory","accessDate":"2026-10-22"},{"title":"Common types of mosque architecture","url":"https://smarthistory.org/common-types-of-mosque-architecture/","publisher":"Smarthistory","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original sourced review draft. Comparative examples and hypothetical observations are marked; linked places do not imply unverified technical findings. Editorial fact and terminology review required before publication.","editorialReason":"Distinguish architectural function from decorative treatment across examples.","sortOrder":180}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-a-minaret-is-not-a-clock-tower','a-minaret-is-not-a-clock-tower','review','{"id":"story-a-minaret-is-not-a-clock-tower","type":"story","slug":"a-minaret-is-not-a-clock-tower","title":"A minaret is not a clock tower","summary":"Towers can announce prayer, display time or commemorate a patron. Height and silhouette do not make them the same building type.","body":[{"type":"paragraph","text":"Two tall structures may dominate a skyline while performing quite different tasks. One belongs to a mosque, another displays a clock, and a third commemorates a person or political claim. Similar height, a staircase and a small crowning pavilion do not make them interchangeable. Building type is a question of purpose and setting as well as shape."},{"type":"paragraph","text":"A minaret is associated with mosque architecture and the call to prayer, although its form and historical use vary. A clock tower makes time publicly visible or audible through a mechanism. The broader term minar can describe a tower without establishing that it functioned as a mosque minaret. These distinctions help prevent a familiar silhouette from becoming a misleading identification."},{"type":"heading","level":2,"text":"Names are a beginning"},{"type":"paragraph","text":"In Sukkur, the Department of Archaeology and Museums records Mir Masum''s Minar together with the adjoining family tombs. It describes a brick tower with an internal stair and a domed summit. The funerary and commemorative setting belongs in any account. Simply relabelling it a mosque tower would erase the context supplied by the record."},{"type":"paragraph","text":"Jacobabad''s Victoria Clock Tower belongs to a different institutional and architectural story. The official inventory describes its masonry construction, internal rooms and stair. Its clock-tower identity does not mean that every part of the building was only a container for the mechanism; rooms, circulation and public presentation deserve attention too."},{"type":"heading","level":2,"text":"Ask what makes the type work"},{"type":"paragraph","text":"For a clock tower, the useful questions concern the clock faces, their viewing distances, the mechanism and access for maintenance. Was sound also part of its operation? An answer requires evidence, not an assumption that every public clock had a bell. A stopped mechanism can leave the landmark recognisable while changing its practical relationship with the city."},{"type":"paragraph","text":"For a minaret, questions concern its relationship to the prayer building, access and documented use. Modern amplification may change how a call is transmitted without removing the tower''s architectural or symbolic significance. A present-day observation should not be projected unchanged onto every earlier period."},{"type":"heading","level":2,"text":"Comparison should retain the difference"},{"type":"paragraph","text":"A good comparative drawing could show each tower at the same scale, then add its surrounding complex. That second step is essential. Without context, the comparison rewards superficial resemblance; with context, it reveals different relationships between height, movement and public attention."},{"type":"paragraph","text":"Multan''s Ghanta Ghar offers another clock-tower setting to investigate, but its civic role should be considered through its own municipal history. It is not an interchangeable version of either Sukkur''s minar or Jacobabad''s monument."},{"type":"paragraph","text":"When writing a caption, use the established name and explain the documented function separately. If the function is uncertain, say so. Towers are powerful precisely because they can carry different meanings across a townscape. Keeping those meanings distinct makes the skyline more interesting, not less coherent."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["sindh-sukkur","sindh-jacobabad","punjab-multan"],"provinceRegionIds":["sindh","punjab"],"relatedHeritageIds":["major-doam-5135","major-doam-4365","major-doam-10385"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"A minaret is not a clock tower | Virsapur","description":"Towers can announce prayer, display time or commemorate a patron. Height and silhouette do not make them the same building type.","primaryKeyword":"minaret clock tower architecture","socialTitle":"A minaret is not a clock tower","socialDescription":"Towers can announce prayer, display time or commemorate a patron. Height and silhouette do not make them the same building type."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Mir Masum''s Minar and Tomb","url":"https://doam.gov.pk/public/sites/5135","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Victoria Clock Tower","url":"https://doam.gov.pk/public/sites/4365","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Mosque architecture, an introduction","url":"https://smarthistory.org/introduction-to-mosque-architecture/","publisher":"Smarthistory","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review draft. Material and spatial observations are separated from uncertain chronology and current access. Catalogue errors, dated conditions and colonial evaluative language are not reproduced as current objective fact. Editorial source review required.","editorialReason":"Compare distinct building types and avoid superficial tower-based classification.","sortOrder":181}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-stepwells-as-designed-journeys-to-water','stepwells-as-designed-journeys-to-water','review','{"id":"story-stepwells-as-designed-journeys-to-water","type":"story","slug":"stepwells-as-designed-journeys-to-water","title":"Stepwells as designed journeys to water","summary":"A baoli is understood in section: steps, landings, roofed passages and the changing relationship between people and water.","body":[{"type":"paragraph","text":"A well is often imagined as a shaft seen from above. A baoli makes the approach to water architectural: a person moves down through a sequence of steps and landings. Its most revealing drawing is therefore often a section, showing depth and changes of level, rather than a plan that records only the outline at ground level."},{"type":"paragraph","text":"The official description of Akbari Baoli in Gujrat identifies a brick stair descending towards the well, with intermediate platforms and arches. These are not incidental embellishments. They shape the route between the ground above and the water below, making the act of reaching water part of a built sequence."},{"type":"heading","level":2,"text":"Descent changes the experience"},{"type":"paragraph","text":"A stair controls pace. Landings interrupt it, allowing a turn, a pause or a change in direction. Walls frame the view; overhead construction changes the amount of light. The result cannot be understood fully from a photograph taken at the entrance, however dramatic its perspective."},{"type":"paragraph","text":"At Wah Buchhran, the Department of Archaeology and Museums describes an upper stretch of uncovered steps followed by roofed, arched space below. That distinction gives the visitor a specific relationship to investigate in documentation: an open descent becomes a covered passage. It is more informative than applying one atmospheric description to the whole structure."},{"type":"heading","level":2,"text":"Water infrastructure serves different users"},{"type":"paragraph","text":"Losar Baoli''s official record includes an animal-watering trough as well as its stair and entrance arrangement. This detail broadens the social picture. Water infrastructure could be connected to movement, work and animal care, rather than only to a solitary person lowering a vessel into a picturesque well."},{"type":"paragraph","text":"It does not follow that every baoli had identical users or management. The association of a structure with a ruler, a road or a settlement requires its own evidence. Naming traditions can be valuable, but they are not always equivalent to a securely dated foundation inscription."},{"type":"heading","level":2,"text":"A section also exposes uncertainty"},{"type":"paragraph","text":"A present water level is not necessarily the historical level. Silting, changes in use, drainage and groundwater conditions can alter what survives or remains visible. A measured record should identify the date of observation and distinguish an accessible surveyed depth from an inferred original depth. An attractive reconstruction must not silently fill missing parts."},{"type":"paragraph","text":"The Rani Baoli and hammam group offers another linked place for exploring water-related architecture, but a bath and a stepped well perform different tasks. Their relationship should be explained through the site''s own record rather than assumed from their proximity."},{"type":"paragraph","text":"For visitors, a descent is never automatically safe because historic steps survive. Follow access restrictions, stay away from unstable edges and do not test water for drinking or enter enclosed lower spaces without authorisation. The most useful encounter may be a supervised view, a section drawing and an account of how the water system was maintained. Together they reveal a designed journey, not merely a hole in the ground."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-gujrat","punjab-mianwali","azad-kashmir-sudhnoti"],"provinceRegionIds":["punjab","azad-kashmir"],"relatedHeritageIds":["major-doam-6544","major-doam-6582","major-doam-10366"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"Stepwells as designed journeys to water | Virsapur","description":"A baoli is understood in section: steps, landings, roofed passages and the changing relationship between people and water.","primaryKeyword":"baoli architecture Pakistan","socialTitle":"Stepwells as designed journeys to water","socialDescription":"A baoli is understood in section: steps, landings, roofed passages and the changing relationship between people and water."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Akbari Baoli, Gujrat Town","url":"https://doam.gov.pk/public/sites/6544","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Sher Shah Baoli, Wah Buchhran","url":"https://doam.gov.pk/public/sites/6582","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Losar Baoli, Wah Cantt","url":"https://doam.gov.pk/public/sites/6413","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review draft. Material and spatial observations are separated from uncertain chronology and current access. Catalogue errors, dated conditions and colonial evaluative language are not reproduced as current objective fact. Editorial source review required.","editorialReason":"Read section, stairs and changing light in historic water infrastructure.","sortOrder":182}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-sarai-architecture-and-the-logistics-of-travel','sarai-architecture-and-the-logistics-of-travel','review','{"id":"story-sarai-architecture-and-the-logistics-of-travel","type":"story","slug":"sarai-architecture-and-the-logistics-of-travel","title":"Sarai architecture and the logistics of travel","summary":"Sarai plans reveal the practical organisation of arrival, accommodation and circulation. Their surviving rooms need more than a romantic caravan story.","body":[{"type":"paragraph","text":"Travel requires more than a route. People need a place to stop, protect possessions, obtain water and organise the next stage. A sarai can be read as architecture responding to those practical needs, although the exact services and users differed between places and periods. Its walls and rooms are evidence of organisation, not a licence to invent a colourful crowd for every courtyard."},{"type":"paragraph","text":"Sarai Kharbuza''s official record describes a square enclosure with gateways to the north and south, rooms around its perimeter and a veranda in front. The arrangement establishes a relationship between a shared central space and smaller accommodation units. A plan makes that relationship clearer than a sequence of isolated room photographs."},{"type":"heading","level":2,"text":"Arrival is an architectural problem"},{"type":"paragraph","text":"Imagine approaching an enclosure with goods and companions. The gateway concentrates movement; the space beyond redistributes it. A veranda provides an intermediate zone between open court and enclosed room. These are spatial implications of the plan, not proof of a particular fee system, security procedure or division of guests."},{"type":"paragraph","text":"To go further, an historian would need records of management and use. A room near a gate might have served several purposes over time. Calling it a guardroom, office or merchant''s shop without supporting evidence turns a plausible possibility into a false certainty."},{"type":"heading","level":2,"text":"Similar outlines can conceal different histories"},{"type":"paragraph","text":"Begum Ki Sarai in Attock also has an enclosed plan, with compartments and a veranda. Its official account records substantial repairs using stone in areas originally built with small bricks. That material difference is a reminder that the surviving building is not a complete snapshot of one moment."},{"type":"paragraph","text":"A visitor comparing the two sarais should therefore ask which parts are early, altered, missing or reused. Gateways may have changed; rooms may have been subdivided; routes through the enclosure may have shifted. The comparison becomes more useful when it acknowledges these differences rather than presenting both as untouched examples of a single model."},{"type":"heading","level":2,"text":"Infrastructure before atmosphere"},{"type":"paragraph","text":"A serious interpretation should look for documented water provision, drainage, food preparation, animal accommodation and links to nearby routes. Where these features have not been identified, a public account can explain why they are questions worth investigating. It should not supply them merely because the word caravanserai evokes a familiar story."},{"type":"paragraph","text":"The Saadabad caravan sarai is another linked starting point for regional comparison. Its route and historical setting need their own sources, rather than an automatic assignment to a vaguely defined Silk Road. Long-distance movement was made from particular journeys, institutions and local services."},{"type":"paragraph","text":"Present communities also belong in the account. Surviving sarai spaces may be occupied, adapted or managed in ways that are not visible on an old plan. Permission and current use govern a visit. Reading the architecture through movement and maintenance brings the history closer to everyday life, without pretending that an empty courtyard can tell us everything about its former travellers."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["islamabad-islamabad","punjab-attock","azad-kashmir-bhimber"],"provinceRegionIds":["islamabad","punjab","azad-kashmir"],"relatedHeritageIds":["major-doam-6227","major-doam-6567","major-doam-6680"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"Sarai architecture and the logistics of travel | Virsapur","description":"Sarai plans reveal the practical organisation of arrival, accommodation and circulation. Their surviving rooms need more than a romantic caravan story.","primaryKeyword":"caravanserai architecture Pakistan","socialTitle":"Sarai architecture and the logistics of travel","socialDescription":"Sarai plans reveal the practical organisation of arrival, accommodation and circulation. Their surviving rooms need more than a romantic caravan story."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Sarai Kharbuza","url":"https://doam.gov.pk/public/sites/6227","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Begum Ki Sarai","url":"https://doam.gov.pk/public/sites/6567","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review draft. Material and spatial observations are separated from uncertain chronology and current access. Catalogue errors, dated conditions and colonial evaluative language are not reproduced as current objective fact. Editorial source review required.","editorialReason":"Explain enclosure and rooms through movement and accommodation, not a generic Silk Road romance.","sortOrder":183}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-defensive-gates-bends-levels-and-lines-of-approach','defensive-gates-bends-levels-and-lines-of-approach','review','{"id":"story-defensive-gates-bends-levels-and-lines-of-approach","type":"story","slug":"defensive-gates-bends-levels-and-lines-of-approach","title":"Defensive gates: bends, levels and lines of approach","summary":"A fort gateway is a route through a defensive boundary. Bends and level changes need to be read with terrain, chronology and documented purpose.","body":[{"type":"paragraph","text":"A monumental fort entrance often invites a frontal photograph: two flanking masses, a central opening and a skyline above. Yet the gateway''s architectural work happens through movement. A visitor approaches, passes a threshold, changes direction or level and emerges inside. Reading that sequence reveals more than treating the facade as an isolated emblem of strength."},{"type":"paragraph","text":"UNESCO''s account of Rohtas describes a fort whose irregular plan follows its hilltop terrain. It identifies gateways, bastions, an internal division and stepped wells within a larger defensive system. The gate therefore belongs to an arrangement of landscape, boundaries and resources, not simply to a collection of impressive stone openings."},{"type":"heading","level":2,"text":"Follow the actual route"},{"type":"paragraph","text":"Begin with a plan, or with permitted observation from a safe path. Where does the approach first become visible from the wall? How does its width change? Is there a turn before the entrance or within it? Does the route rise, descend or remain level? These questions establish the physical arrangement before assigning a tactical explanation."},{"type":"paragraph","text":"A bend may restrict a direct approach, but not every bend was designed for the same military reason. Terrain, an earlier route, drainage or later building can also influence movement. The popular explanation that every angled entrance stopped charging elephants is especially unsatisfactory when offered without evidence for the particular gate."},{"type":"heading","level":2,"text":"A gateway can communicate as well as control"},{"type":"paragraph","text":"Scale, carving and inscriptions can make an entrance a place of display. Defensive purpose and ceremonial presentation are not mutually exclusive. A gateway may regulate passage while making an architectural statement to those who approach it. Interpretation should examine both roles instead of assuming that ornament is irrelevant to military architecture."},{"type":"paragraph","text":"Rohtas''s decorated gateways provide a setting for this enquiry, while the Naukot Fort record offers a different regional comparison. Their construction histories and defensive arrangements must remain distinct. A feature observed at one cannot simply be transferred to the other because both sites are called forts."},{"type":"heading","level":2,"text":"The present path may be later"},{"type":"paragraph","text":"Modern road surfaces, filled ditches, repaired steps and openings made for contemporary access can change the route a visitor experiences. A current walk-through should be compared with surveys and earlier records before it becomes a reconstruction of historical movement. An entrance photographed after restoration also needs its intervention history."},{"type":"paragraph","text":"There is a useful difference between saying a turn interrupts a straight approach and claiming it successfully defeated a particular attack. The first may be visible in a plan; the second requires historical evidence. Architectural form can establish possibilities without proving events."},{"type":"paragraph","text":"The most informative gateway photograph includes the approach and an oblique view through the opening, where permitted. The most informative account explains how that route connects to the surrounding wall and terrain. A fort then becomes a working spatial system rather than a dramatic doorway awaiting a legend."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-jhelum","sindh-tharparkar"],"provinceRegionIds":["punjab","sindh"],"relatedHeritageIds":["unesco-586","major-doam-5504"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"Defensive gates: bends, levels and lines of approach | Virsapur","description":"A fort gateway is a route through a defensive boundary. Bends and level changes need to be read with terrain, chronology and documented purpose.","primaryKeyword":"fort gateway architecture","socialTitle":"Defensive gates: bends, levels and lines of approach","socialDescription":"A fort gateway is a route through a defensive boundary. Bends and level changes need to be read with terrain, chronology and documented purpose."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Rohtas Fort","url":"https://whc.unesco.org/en/list/586/","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Naukot Fort","url":"https://doam.gov.pk/public/sites/5504","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review draft. Material and spatial observations are separated from uncertain chronology and current access. Catalogue errors, dated conditions and colonial evaluative language are not reproduced as current objective fact. Editorial source review required.","editorialReason":"Explain documented defensive design without assigning every bend a military purpose.","sortOrder":184}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-bastion-curtain-wall-and-parapet-reading-a-fort','bastion-curtain-wall-and-parapet-reading-a-fort','review','{"id":"story-bastion-curtain-wall-and-parapet-reading-a-fort","type":"story","slug":"bastion-curtain-wall-and-parapet-reading-a-fort","title":"Bastion, curtain wall and parapet: reading a fort","summary":"A few precise terms make a fort easier to understand, provided they are attached to visible features rather than memorised as a checklist.","body":[{"type":"paragraph","text":"Fortification vocabulary is most useful when it describes relationships. A projecting element, a connecting wall and its protected upper edge work together. Learning their names allows a visitor to move from the statement that a fort has thick walls towards a more exact account of how its perimeter is organised."},{"type":"paragraph","text":"A curtain wall is the stretch connecting defensive towers or projecting works. A parapet is a protective wall along an elevated edge, often associated with a walkway or roof. Bastion can describe a projecting defensive feature, but its shape and technical meaning vary across periods and traditions. It should not automatically evoke the angular geometry of a European star fort."},{"type":"heading","level":2,"text":"Start with the plan"},{"type":"paragraph","text":"The official description of Harrand Fort records an approximately circular enclosure with repeated octagonal bastions and entrances on opposing sides. Sangni''s record describes a roughly square plan with projecting features and a gate flanked by bastions. These contrasting outlines immediately show why a fort cannot be understood from one wall segment."},{"type":"paragraph","text":"On a plan, mark where the boundary projects and where it runs between projections. Then compare the width and form of these features. Are they regularly spaced? Do they concentrate near an entrance? Does the ground outside rise or fall? The names begin a spatial enquiry; they do not supply the explanation in advance."},{"type":"heading","level":2,"text":"Read the wall vertically"},{"type":"paragraph","text":"An elevation or section adds a second dimension. A high wall, its walkway and its upper protection are different elements. The familiar alternating solid and open pattern of battlements is not the entire wall, and a parapet need not always have that profile. A missing upper edge can make a surviving wall look unlike its earlier appearance."},{"type":"paragraph","text":"Openings also need careful identification. A drainage outlet, a construction hole and an opening associated with defence may appear similar in a distant photograph. The shape, internal passage and documented context matter. It is better to record an unidentified opening than to label every hole an arrow slit."},{"type":"heading","level":2,"text":"Avoid a universal military diagram"},{"type":"paragraph","text":"UNESCO describes Rohtas as an integrated system of walls, bastions and gateways adapted to its terrain. That comparison helps readers recognise a broader vocabulary, but it does not establish that Harrand or Sangni used identical weapons, strategies or construction methods. Shared terms do not erase chronological and regional differences."},{"type":"paragraph","text":"Nor should the vocabulary imply that the whole surviving fort belongs to one campaign. Repairs, rebuilding and changed use can alter an enclosure. A bastion may retain its outline while containing later masonry; a parapet may be reconstructed."},{"type":"paragraph","text":"For a visit, use an authorised path and regard wall tops as restricted unless clearly opened and supervised. A low-looking parapet or broad projection is not evidence of safe access. The best result is a precise description made from plans and permitted viewpoints: what projects, what connects, what protects the edge, and which parts remain uncertain."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-rajanpur","punjab-rawalpindi"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6193","major-doam-6922"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"Bastion, curtain wall and parapet: reading a fort | Virsapur","description":"A few precise terms make a fort easier to understand, provided they are attached to visible features rather than memorised as a checklist.","primaryKeyword":"fortification architecture terms","socialTitle":"Bastion, curtain wall and parapet: reading a fort","socialDescription":"A few precise terms make a fort easier to understand, provided they are attached to visible features rather than memorised as a checklist."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Harrand Fort","url":"https://doam.gov.pk/public/sites/6193","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Sangni Fort","url":"https://doam.gov.pk/public/sites/6922","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Rohtas Fort","url":"https://whc.unesco.org/en/list/586/","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review draft. Material and spatial observations are separated from uncertain chronology and current access. Catalogue errors, dated conditions and colonial evaluative language are not reproduced as current objective fact. Editorial source review required.","editorialReason":"Give readers a precise vocabulary anchored in visible examples.","sortOrder":185}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-earthen-forts-and-the-labour-of-maintenance','earthen-forts-and-the-labour-of-maintenance','review','{"id":"story-earthen-forts-and-the-labour-of-maintenance","type":"story","slug":"earthen-forts-and-the-labour-of-maintenance","title":"Earthen forts and the labour of maintenance","summary":"Earthen architecture survives through knowledge and continuing care. Its maintenance is part of its history, not proof of an inferior building material.","body":[{"type":"paragraph","text":"An earthen fort can appear vulnerable when its surfaces are compared with hard stone. That contrast should not become a ranking of civilisations or an assumption that earth was merely a temporary substitute. Earth is a building material with many techniques, capabilities and maintenance requirements. Its history includes the labour that repeatedly kept walls, roofs and surfaces functioning."},{"type":"paragraph","text":"Getty''s discussion of earthen conservation emphasises how strongly materials, environment, scale and use affect each case. It also distinguishes occupied buildings from archaeological remains that are incomplete and no longer maintained in the same way. A ruined wall and a working settlement therefore cannot be approached as identical conservation problems."},{"type":"heading","level":2,"text":"Maintenance leaves history in the surface"},{"type":"paragraph","text":"Renewed plaster may protect an older wall while changing what the visitor sees. A visible surface can be much younger than the structure beneath it. That does not necessarily make the building inauthentic; it may reflect a continuing maintenance practice. The important questions are what was renewed, by whom, with which materials and under what conditions."},{"type":"paragraph","text":"A useful account would document the cycle of care rather than celebrate only a foundation date. Where did suitable material come from? Who knew how to prepare and apply it? How were vulnerable wall tops and drainage routes managed? These questions connect architectural survival with organisation and skilled labour."},{"type":"heading","level":2,"text":"Abandonment changes the system"},{"type":"paragraph","text":"When use stops, small defects may no longer be repaired promptly. Loss of roofs or protective surfaces exposes elements that were not intended to stand indefinitely in that condition. Conservation must then address a new situation rather than simply preserve the ruin''s present appearance as if it were the original design."},{"type":"paragraph","text":"Getty''s Taourirt project in Morocco combined concern for historic fabric with technical knowledge, appropriate reuse and local participation. It offers a comparative conservation approach, not a treatment prescription for Punjab. Ahmadpur Lamma and Kot Mahoi Wala require their own material assessment, history and management decisions before any intervention is proposed."},{"type":"heading","level":2,"text":"Hard coatings are not a simple answer"},{"type":"paragraph","text":"A surface that seems stronger can interact poorly with the wall behind it. Conversely, a traditional-looking repair is not automatically suitable merely because it contains earth. Composition, exposure, drainage and the surviving fabric need specialist investigation. This article deliberately offers no repair mixture or instruction for unsupervised work."},{"type":"paragraph","text":"The public story should also include resources. A maintenance programme needs time, training, access and a responsible organisation. Photographing a conservation ceremony once does not demonstrate that those conditions remain in place afterwards."},{"type":"paragraph","text":"Earthen forts become more understandable when survival is seen as an activity rather than a material miracle. Their significance lies in form and history, but also in the recurring work that made occupation possible. Respecting that work means neither romanticising deterioration nor replacing vulnerable fabric indiscriminately. It means asking how a place can continue to be cared for without losing the evidence it carries."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-rahim-yar-khan","punjab-taunsa"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-10307","major-doam-6199"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"Earthen forts and the labour of maintenance | Virsapur","description":"Earthen architecture survives through knowledge and continuing care. Its maintenance is part of its history, not proof of an inferior building material.","primaryKeyword":"mud fort conservation","socialTitle":"Earthen forts and the labour of maintenance","socialDescription":"Earthen architecture survives through knowledge and continuing care. Its maintenance is part of its history, not proof of an inferior building material."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"The Delicate Balance of Conserving Earthen Archaeological Sites","url":"https://www.getty.edu/news/the-delicate-balance-of-conserving-earthen-archaeological-sites/","publisher":"Getty Conservation Institute","accessDate":"2026-10-22"},{"title":"Conservation and Rehabilitation Plan for the Kasbah of Taourirt","url":"https://www.getty.edu/projects/conservation-rehabilitation-plan-kasbah-taourirt/","publisher":"Getty Conservation Institute","accessDate":"2026-10-22"},{"title":"Earthen Architecture Conservation: teaching resources","url":"https://www.getty.edu/research-conservation/teaching-learning-resources/earthen-architecture-conservation/","publisher":"Getty Conservation Institute","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review draft. Material and spatial observations are separated from uncertain chronology and current access. Catalogue errors, dated conditions and colonial evaluative language are not reproduced as current objective fact. Editorial source review required.","editorialReason":"Explain material vulnerability and continual care without treating earth as primitive construction.","sortOrder":186}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-stone-temples-of-the-salt-range-a-regional-comparison','stone-temples-of-the-salt-range-a-regional-comparison','review','{"id":"story-stone-temples-of-the-salt-range-a-regional-comparison","type":"story","slug":"stone-temples-of-the-salt-range-a-regional-comparison","title":"Stone temples of the Salt Range: a regional comparison","summary":"Malot, Amb and Nandana belong in a regional conversation, but their surviving forms and documentary histories resist a single temple template.","body":[{"type":"paragraph","text":"A regional group is a useful way to begin studying the Salt Range temples, but it should not become a claim that every building follows one plan or belongs to one moment. Comparison works best when the differences remain visible: the treatment of an entrance, the organisation of a shrine, the surrounding enclosure and the state of preservation."},{"type":"paragraph","text":"Malot''s official catalogue description draws attention to recessed faces, columns and trefoil arches. Amb''s entry instead foregrounds a group of temples within an enclosure, including structures of different sizes. Even these brief descriptions suggest different starting points. At Malot, the elevation invites close reading; at Amb, the relationship between buildings is immediately important."},{"type":"heading","level":2,"text":"Compare the same things"},{"type":"paragraph","text":"A productive comparison chooses a small set of features and records them consistently. How is the entrance framed? What remains of the upper structure? Is the building freestanding or part of a larger group? How does its platform meet the surrounding ground? The answers should come from measured records and documented observation, not from a checklist completed by analogy."},{"type":"paragraph","text":"Preservation can distort comparison. A missing roof may make two originally different buildings appear similar, while a surviving decorated doorway can make one site seem more elaborate than another whose corresponding element is lost. The absence of a feature in the present ruin is not necessarily evidence that it never existed."},{"type":"heading","level":2,"text":"Regional exchange is not a single recipe"},{"type":"paragraph","text":"Michael Meister''s research presentation for Penn Museum situates these monuments within a wider architectural conversation and notes distinctive relationships with Kashmir at Malot. This offers a more useful model than treating the region as an isolated school with an unchanging style. Architectural knowledge travelled, but each proposed connection needs to be demonstrated through specific forms and evidence."},{"type":"paragraph","text":"Political labels also need care. A broad association with the Shahi period is not a substitute for establishing the date of an individual building phase. Earlier catalogues and later scholarship can differ. A public account should explain a significant disagreement rather than silently combine incompatible dates into a precise-looking chronology."},{"type":"heading","level":2,"text":"Read the setting as well as the shrine"},{"type":"paragraph","text":"Nandana''s remains belong to a larger fortified and historically layered landscape. Its official record discusses several kinds of surviving structures and preserves older interpretations. This is a reason to consult specialist research, not to merge all the remains into a single temple complex or repeat every historical attribution without scrutiny."},{"type":"paragraph","text":"For visitors, photographs should retain the platform, slope and neighbouring remains whenever possible. A close view of carving is valuable, but it cannot explain the full arrangement. Access and stability restrictions take precedence over the desire to recreate a historic viewpoint."},{"type":"paragraph","text":"A regional comparison succeeds when it makes each place more distinct. The Salt Range temples are not interesting because they can be reduced to one formula. They are interesting because related architectural ideas were worked out in different buildings, landscapes and historical circumstances."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-chakwal","punjab-khushab","punjab-jhelum"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6535","major-doam-6897","major-doam-8267"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"Stone temples of the Salt Range: a regional comparison | Virsapur","description":"Malot, Amb and Nandana belong in a regional conversation, but their surviving forms and documentary histories resist a single temple template.","primaryKeyword":"Salt Range temple architecture","socialTitle":"Stone temples of the Salt Range: a regional comparison","socialDescription":"Malot, Amb and Nandana belong in a regional conversation, but their surviving forms and documentary histories resist a single temple template."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Malot Temple","url":"https://doam.gov.pk/public/sites/6535","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Amb Temple","url":"https://doam.gov.pk/public/sites/6897","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Temples Along the Indus","url":"https://www.penn.museum/sites/expedition/temples-along-the-indus/","publisher":"Penn Museum; Michael W. Meister","accessDate":"2026-10-22"},{"title":"Nandana Fort","url":"https://doam.gov.pk/public/sites/8267","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review draft. Material and spatial observations are separated from uncertain chronology and current access. Catalogue errors, dated conditions and colonial evaluative language are not reproduced as current objective fact. Editorial source review required.","editorialReason":"Compare documented forms while retaining distinctions between individual temple histories.","sortOrder":187}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-sikh-samadhis-and-regional-architectural-exchange','sikh-samadhis-and-regional-architectural-exchange','review','{"id":"story-sikh-samadhis-and-regional-architectural-exchange","type":"story","slug":"sikh-samadhis-and-regional-architectural-exchange","title":"Sikh samadhis and regional architectural exchange","summary":"Samadhis can combine familiar regional forms while retaining specific commemorative meanings. Architectural exchange is not the disappearance of difference.","body":[{"type":"paragraph","text":"A dome, a cusped arch or a pavilion does not belong exclusively to one community. Such forms can recur across buildings with different patrons and purposes. Sikh samadhis in Punjab offer a way to study that architectural exchange, provided their commemorative identity is not dissolved into a vague claim that all regional traditions are essentially the same."},{"type":"paragraph","text":"The Department of Archaeology and Museums identifies Ranjit Singh''s samadhi in Lahore with his cremation site and describes a central dome, surrounding roof features and decorated interiors. These physical observations are useful. The older catalogue''s evaluative language about a mixture of styles is less useful: it reveals an author''s judgement, not an objective architectural defect."},{"type":"heading","level":2,"text":"Begin with the monument''s own purpose"},{"type":"paragraph","text":"A samadhi should not automatically be described as a mosque, a gurdwara or an ordinary burial chamber because its external features resemble another building. Commemoration, devotional practice and the treatment of remains require precise, site-specific explanation. The established name should remain visible while that context is introduced."},{"type":"paragraph","text":"Nor should a discussion of elite monuments stand for all Sikh practice. A ruler''s memorial has a particular political and patronage history. Its scale and decoration cannot be assumed to represent the buildings or preferences of every community associated with the same tradition."},{"type":"heading","level":2,"text":"Compare forms without assigning ownership"},{"type":"paragraph","text":"Mahan Singh''s samadhi in Gujranwala is catalogued as an octagonal building with a tall central chamber and a fluted dome. The official description also notes architectural features shared with Mughal building traditions. Comparison can focus on those features—the arrangement of bays, projecting eaves or profiles of arches—without claiming that the whole monument is merely a copy."},{"type":"paragraph","text":"Shared forms might reflect available craft knowledge, patronal choice or the established architectural vocabulary of a region. Establishing which explanation applies requires records beyond resemblance. Where the names of builders are unknown, that gap should be acknowledged rather than filled by attributing all work to an anonymous communal style."},{"type":"heading","level":2,"text":"Decoration has a subject as well as a surface"},{"type":"paragraph","text":"Paintings and ornamental work may be discussed technically, but their iconography also matters. A description of painted narratives should identify what a reliable source recognises, distinguish surviving images from lost ones and avoid supplying identities from a blurred photograph. The same caution applies to stories about reused architectural fragments."},{"type":"paragraph","text":"Current condition must be dated. A catalogue''s report of damage describes the circumstances of that documentation, not automatically the building''s state today. Before directing visitors, obtain current access information from the responsible custodian."},{"type":"paragraph","text":"The strongest account of these samadhis holds several things together: the people commemorated, the architectural forms chosen, the labour that realised them and the later history of care. Exchange becomes a specific historical process. Difference remains legible, and the monuments are allowed to be more than illustrations of a simplified regional style."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-lahore","punjab-gujranwala"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6470","major-doam-10110"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"Sikh samadhis and regional architectural exchange | Virsapur","description":"Samadhis can combine familiar regional forms while retaining specific commemorative meanings. Architectural exchange is not the disappearance of difference.","primaryKeyword":"Sikh samadhi architecture","socialTitle":"Sikh samadhis and regional architectural exchange","socialDescription":"Samadhis can combine familiar regional forms while retaining specific commemorative meanings. Architectural exchange is not the disappearance of difference."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Samadh of Ranjit Singh","url":"https://doam.gov.pk/public/sites/6470","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Mahan Singh Samadhi","url":"https://doam.gov.pk/public/sites/10110","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review draft. Material and spatial observations are separated from uncertain chronology and current access. Catalogue errors, dated conditions and colonial evaluative language are not reproduced as current objective fact. Editorial source review required.","editorialReason":"Study building form without flattening different devotional traditions into one style.","sortOrder":188}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-colonial-railway-stations-beyond-a-single-style','colonial-railway-stations-beyond-a-single-style','review','{"id":"story-colonial-railway-stations-beyond-a-single-style","type":"story","slug":"colonial-railway-stations-beyond-a-single-style","title":"Colonial railway stations beyond a single style","summary":"Railway stations are systems of movement as well as facades. Lahore, Attock Khurd and Golra invite comparison beyond a generic colonial style.","body":[{"type":"paragraph","text":"A railway station must connect a town to a moving network. Its architecture handles arrival, waiting, tickets, baggage, staff work and access to trains. A decorative facade may be its most recognisable image, but the building''s history cannot be reduced to that image or to the broad label colonial."},{"type":"paragraph","text":"The official description of Lahore Railway Station emphasises its castle-like appearance and its post-1857 context. Attock Khurd''s record instead draws attention to a smaller stone-built station beside the Indus crossing. The contrast is useful even without assigning either building to a perfectly bounded style: scale, material and position within the network already differ."},{"type":"heading","level":2,"text":"Look from the track side too"},{"type":"paragraph","text":"The public entrance and the platform answer different requirements. An urban frontage addresses streets and arriving passengers. The platform edge must relate to railway operations. Roofs, canopies, waiting areas and circulation between these sides can tell a different story from the principal elevation."},{"type":"paragraph","text":"A comparison should therefore include plans and operational spaces where documentation permits. How does someone move from entrance to platform? Where are public and staff areas separated? Have additional platforms or buildings changed the original arrangement? These questions bring the station''s practical life into the architectural account."},{"type":"heading","level":2,"text":"A network gives a building its scale"},{"type":"paragraph","text":"A major junction and a smaller station near an important crossing are not simply large and small versions of the same object. Their roles can shape accommodation, circulation and relationships with surrounding infrastructure. Attock Khurd''s proximity to the bridge is especially important to its setting, but the station and successive bridge works should retain separate construction histories."},{"type":"paragraph","text":"The DOAM entry for Attock Khurd contains differing dates and some inconsistent classification fields. That is a reminder to check archival or railway records before publishing a precise chronology. An official catalogue is a valuable lead, not a guarantee that every field has been reconciled."},{"type":"heading","level":2,"text":"Preserve work, not only nostalgia"},{"type":"paragraph","text":"Signals, communication equipment, signs, benches and maintenance spaces can be as informative as an ornamental tower. When objects are displayed in a railway museum, their original operational context matters. A tool labelled merely old railway equipment tells visitors far less than a record explaining who used it and which task it performed."},{"type":"paragraph","text":"Golra provides another linked place for exploring that relationship between a station and railway memory. Its interpretation should be based on its own collection and building records, rather than borrowing Lahore''s monumental narrative."},{"type":"paragraph","text":"Active railway property also imposes clear limits. Photography permission does not authorise access to tracks, staff rooms or operational equipment. A heritage visit must not interfere with passengers or railway work."},{"type":"paragraph","text":"The architectural reward of this broader view is a more human history. Stations emerge as places built and adapted for organised movement, shaped by labour and infrastructure as well as political display. Colonial is a historical context; it is not a complete description of every roof, room and platform."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-attock","punjab-lahore","islamabad-islamabad"],"provinceRegionIds":["punjab","islamabad"],"relatedHeritageIds":["major-doam-10358","major-doam-10172","major-doam-6310"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"Colonial railway stations beyond a single style | Virsapur","description":"Railway stations are systems of movement as well as facades. Lahore, Attock Khurd and Golra invite comparison beyond a generic colonial style.","primaryKeyword":"Pakistan railway station architecture","socialTitle":"Colonial railway stations beyond a single style","socialDescription":"Railway stations are systems of movement as well as facades. Lahore, Attock Khurd and Golra invite comparison beyond a generic colonial style."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Lahore Railway Station","url":"https://doam.gov.pk/public/sites/10172","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Attock Khurd Railway Station","url":"https://doam.gov.pk/public/sites/10358","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Golra Railway Station","url":"https://doam.gov.pk/public/sites/6310","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review draft. Material and spatial observations are separated from uncertain chronology and current access. Catalogue errors, dated conditions and colonial evaluative language are not reproduced as current objective fact. Editorial source review required.","editorialReason":"Compare infrastructure, materials and scale rather than impose one uniform colonial aesthetic.","sortOrder":189}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-clock-tower-and-the-making-of-civic-space','the-clock-tower-and-the-making-of-civic-space','review','{"id":"story-the-clock-tower-and-the-making-of-civic-space","type":"story","slug":"the-clock-tower-and-the-making-of-civic-space","title":"The clock tower and the making of civic space","summary":"A civic clock tower makes a landmark out of public time. Its urban role depends on sightlines, movement and the institution around it.","body":[{"type":"paragraph","text":"A clock tower does more than lift a clock above the street. It makes a public claim about visibility and shared time. People can use it as a meeting point, orient themselves by its position or read it while moving through surrounding streets. The architecture becomes part of the town''s daily geography, even for someone who never enters the building."},{"type":"paragraph","text":"Multan''s Ghanta Ghar is particularly useful for thinking about this relationship. The official catalogue places it near the old fortress and a convergence of streets, and connects it with the former municipal building. The tower''s civic identity therefore belongs to both its mechanism and the institutional space around it."},{"type":"heading","level":2,"text":"Visibility is designed and negotiated"},{"type":"paragraph","text":"A clock face needs to be seen from somewhere. Its height, orientation and relation to neighbouring buildings affect who can read it and from what distance. Later traffic arrangements, signs, trees or construction may alter those sightlines. An old photograph and a present view can therefore show different urban roles even when the tower itself remains recognisable."},{"type":"paragraph","text":"This does not mean that every surrounding street was laid out for the clock. The order of development matters. A tower may occupy an existing junction, reshape attention within it or become a landmark after subsequent changes. Plans and dated photographs are needed to distinguish those possibilities."},{"type":"heading","level":2,"text":"The mechanism is part of the heritage"},{"type":"paragraph","text":"A facade can survive while a clock stops, changes mechanism or receives a new source of power. These are not merely technical footnotes. They affect the building''s ability to perform the public task that gives it its name. A conservation account should record such changes rather than treating the visible dial as the whole clock."},{"type":"paragraph","text":"The Multan catalogue describes past work on the clocks, but that report does not establish their operation today. A visitor''s account should date any observation of movement or sound. One working face also does not automatically prove that every dial shows the same time."},{"type":"heading","level":2,"text":"A landmark can outlive its original institution"},{"type":"paragraph","text":"Jacobabad''s Victoria Clock Tower offers a second setting for considering architecture, commemoration and public orientation. Its historic name carries a political context, while residents may attach other associations to the place. Those meanings should be documented rather than reduced either to colonial nostalgia or to a single official narrative."},{"type":"paragraph","text":"The public space around a tower may be more significant to everyday users than the interior. Vendors, pedestrians, transport and nearby institutions contribute to that setting, but their use should not be romanticised without listening to the people involved. A beautiful traffic-free photograph can conceal the place''s actual pressures."},{"type":"paragraph","text":"To describe a civic clock tower well, connect three scales: the mechanism, the building and the urban approach. The result is not just a biography of an object. It is an account of how a city makes time visible, changes the meaning of a landmark and decides which parts of that relationship to keep."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["sindh-jacobabad","punjab-multan"],"provinceRegionIds":["sindh","punjab"],"relatedHeritageIds":["major-doam-4365","major-doam-10385"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"The clock tower and the making of civic space | Virsapur","description":"A civic clock tower makes a landmark out of public time. Its urban role depends on sightlines, movement and the institution around it.","primaryKeyword":"civic clock towers Pakistan","socialTitle":"The clock tower and the making of civic space","socialDescription":"A civic clock tower makes a landmark out of public time. Its urban role depends on sightlines, movement and the institution around it."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Ghanta Ghar Multan","url":"https://doam.gov.pk/public/sites/10385","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Victoria Clock Tower","url":"https://doam.gov.pk/public/sites/4365","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review draft. Material and spatial observations are separated from uncertain chronology and current access. Catalogue errors, dated conditions and colonial evaluative language are not reproduced as current objective fact. Editorial source review required.","editorialReason":"Focus on urban organisation, visibility and public time rather than building biographies.","sortOrder":190}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-indo-saracenic-architecture-a-term-worth-unpacking','indo-saracenic-architecture-a-term-worth-unpacking','review','{"id":"story-indo-saracenic-architecture-a-term-worth-unpacking","type":"story","slug":"indo-saracenic-architecture-a-term-worth-unpacking","title":"Indo-Saracenic architecture: a term worth unpacking","summary":"Indo-Saracenic is a historical label for architectural combinations, not a timeless style or a substitute for naming the people who made a building.","body":[{"type":"paragraph","text":"Indo-Saracenic appears frequently in descriptions of public buildings from the colonial period. It usually points towards a combination of architectural forms associated with South Asia and European design traditions. The term can be useful, but it is not a complete explanation of a building. It carries the history of classification as well as the history of construction."},{"type":"paragraph","text":"The word Saracenic reflects an older European way of naming Islamic cultures and architecture. It should be treated as part of a historical label, not as the name of a single community or a precise description of every arch and dome. Using the term without explanation can make very different buildings seem members of one uniform family."},{"type":"heading","level":2,"text":"Move from the label to the building"},{"type":"paragraph","text":"At Multan''s Ghanta Ghar, the official catalogue uses Indo-Saracenic in describing a municipal building with a prominent clock tower. A useful architectural account would then identify the actual features: the organisation of openings, roof forms, projections and the relationship between the tower and the adjoining halls. Those observations allow readers to understand what the label is doing."},{"type":"paragraph","text":"The same approach applies to Lahore''s museum and art-school setting. Instead of stopping at a stylistic adjective, consider how the building accommodates galleries, circulation, light and public arrival. Institutional function and construction methods are not secondary details hidden behind an ornamental exterior."},{"type":"heading","level":2,"text":"Name the makers"},{"type":"paragraph","text":"Lahore Museum''s own history credits Bhai Ram Singh with the design of the museum and technical-institute complex, and Ganga Ram with supervising its execution. This is important evidence against a story in which architecture simply arrives from abroad and local people disappear into an anonymous workforce."},{"type":"paragraph","text":"Authorship itself can be distributed. A designer, engineer, patron, contractor and specialist craft workshop contribute different decisions. Where records identify those roles, interpretation should retain them. Where they do not, the absence should not be repaired by assigning the whole building to a broad national or imperial style."},{"type":"heading","level":2,"text":"Comparison can travel, but carefully"},{"type":"paragraph","text":"A V&A conservation account describes Mumbai''s former Prince of Wales Museum through the same stylistic vocabulary. This provides a comparative institutional example, not proof that the buildings in Lahore and Multan share one designer, construction process or political message. The category stretches across different commissions and places."},{"type":"paragraph","text":"Nor does the presence of a European-looking feature make every palace or civic building simply colonial in purpose. Patronage and use require separate historical investigation. A building may participate in imperial institutions, local ambition and regional craft practice at the same time."},{"type":"paragraph","text":"The best use of Indo-Saracenic is therefore provisional and explanatory: name the term, unpack the features and return to the particular building. Architecture becomes more legible when a classification opens questions rather than closes them. The label belongs in the account, but it should never replace the plan, materials, makers or people who used the rooms."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-multan","punjab-lahore"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-10385","major-doam-10162"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"Indo-Saracenic architecture: a term worth unpacking | Virsapur","description":"Indo-Saracenic is a historical label for architectural combinations, not a timeless style or a substitute for naming the people who made a building.","primaryKeyword":"Indo Saracenic architecture Pakistan","socialTitle":"Indo-Saracenic architecture: a term worth unpacking","socialDescription":"Indo-Saracenic is a historical label for architectural combinations, not a timeless style or a substitute for naming the people who made a building."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Background","url":"https://lahoremuseum.punjab.gov.pk/node/21","publisher":"Lahore Museum","accessDate":"2026-10-22"},{"title":"Ghanta Ghar Multan","url":"https://doam.gov.pk/public/sites/10385","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"V&A Conservation Journal: Prince of Wales Museum","url":"https://media.vam.ac.uk/media/documents/legacy_documents/file_upload/16752_file.pdf","publisher":"Victoria and Albert Museum","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review article; historical and institutional sources used for bounded claims. No unmeasured performance, current access, or unsupported origin claims. Rights-cleared photography absent. Editorial review required.","editorialReason":"Explain the label’s history and limits through specific institutional buildings.","sortOrder":191}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-princely-palaces-and-imported-design-vocabularies','princely-palaces-and-imported-design-vocabularies','review','{"id":"story-princely-palaces-and-imported-design-vocabularies","type":"story","slug":"princely-palaces-and-imported-design-vocabularies","title":"Princely palaces and imported design vocabularies","summary":"Palaces could borrow architectural ideas selectively. Comparing Noor Mahal and Khaplu asks who chose those ideas and how they were made local.","body":[{"type":"paragraph","text":"A palace can look outward in more than one sense. Its patron may choose forms associated with distant courts, new political relationships or admired buildings, while the structure remains rooted in local materials and work. Borrowing is therefore not simply copying. It involves selection, translation and decisions about what a building should communicate."},{"type":"paragraph","text":"Noor Mahal in Bahawalpur is described in the national heritage catalogue through a European and neoclassical vocabulary, within the patronage of the princely state. Khaplu Palace''s official descriptions instead emphasise a combination of regional architectural traditions and timber construction. Comparing them is useful because the differences are substantial, not because both can be reduced to the word eclectic."},{"type":"heading","level":2,"text":"Separate appearance from construction"},{"type":"paragraph","text":"A column or dome may suggest a visual reference, but the building''s structure, circulation and materials require their own description. An imported-looking facade does not establish that every component was imported, that foreign workers built it or that the interior follows a European domestic plan."},{"type":"paragraph","text":"At Khaplu, official documentation describes posts, beams, wall panels and timber reinforcement alongside the palace''s architectural character. These details return attention to the assembly of the building. A design vocabulary becomes concrete through material choices and skilled construction rather than remaining an abstract list of influences."},{"type":"heading","level":2,"text":"Patronage is an active process"},{"type":"paragraph","text":"A princely commission should not be narrated as if its patron had no choices. Forms could be selected to express status, establish a particular ceremonial setting or engage with a wider architectural world. These are possibilities to investigate, not motives that can be read automatically from an elevation."},{"type":"paragraph","text":"To establish a specific intention, look for correspondence, accounts, drawings or contemporary descriptions. A later legend about why a palace was built may be culturally significant without functioning as a reliable construction record. Its status as a remembered story should be made clear."},{"type":"heading","level":2,"text":"Compare rooms and routes"},{"type":"paragraph","text":"The strongest comparison would ask how each palace separates reception, domestic life, service work and circulation. Does the principal approach lead directly to a formal room? How are upper levels reached? Which spaces face gardens or public areas? These questions make the people and labour behind palace life visible without inventing a day in the ruler''s household."},{"type":"paragraph","text":"Present use adds another layer. A palace adapted for visitors or hospitality may have new services and circulation arrangements. A current room label or furnishing display does not necessarily reconstruct its original contents. Conservation and interpretation records should explain what survives and what has changed."},{"type":"paragraph","text":"Noor Mahal and Khaplu are not opposites labelled foreign and authentic. Both invite a more precise account of how architectural ideas were chosen, combined and built in particular circumstances. The rewarding question is not whether a palace is pure in style. It is how its different references became a coherent place, and what evidence allows us to understand that process."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-bahawalpur","gilgit-baltistan-ghanche"],"provinceRegionIds":["punjab","gilgit-baltistan"],"relatedHeritageIds":["major-doam-9874","major-doam-7974"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"Princely palaces and imported design vocabularies | Virsapur","description":"Palaces could borrow architectural ideas selectively. Comparing Noor Mahal and Khaplu asks who chose those ideas and how they were made local.","primaryKeyword":"Bahawalpur palace architecture","socialTitle":"Princely palaces and imported design vocabularies","socialDescription":"Palaces could borrow architectural ideas selectively. Comparing Noor Mahal and Khaplu asks who chose those ideas and how they were made local."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Noor Mahal","url":"https://doam.gov.pk/public/sites/9874","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Khaplu Fort","url":"https://www.visitgilgitbaltistan.gov.pk/tour/id/65","publisher":"Government of Gilgit-Baltistan","accessDate":"2026-10-22"},{"title":"Khaplu Palace, Yabgo Khar","url":"https://doam.gov.pk/public/sites/7841","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review article; historical and institutional sources used for bounded claims. No unmeasured performance, current access, or unsupported origin claims. Rights-cleared photography absent. Editorial review required.","editorialReason":"Compare patronage and selective architectural borrowing without calling every European detail colonial.","sortOrder":192}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-school-and-library-buildings-as-heritage','school-and-library-buildings-as-heritage','review','{"id":"story-school-and-library-buildings-as-heritage","type":"story","slug":"school-and-library-buildings-as-heritage","title":"School and library buildings as heritage","summary":"Schools and libraries preserve histories of learning through rooms, routes and continuing use—not only through famous alumni and grand facades.","body":[{"type":"paragraph","text":"A classroom can carry history without looking like a monument. Its proportions, windows, furniture and relation to a corridor shape how people learn together. A library similarly joins books with the spaces and rules that make reading possible. Educational heritage is therefore more than an impressive entrance photographed after everyone has gone home."},{"type":"paragraph","text":"Aitchison College''s own history links its Old Building to a move from dispersed teaching accommodation into a dedicated school building. Its later account describes the building''s reopening after renovation and continued educational use. The important continuity is not that nothing changed, but that conservation and a working institution remain connected."},{"type":"heading","level":2,"text":"Read the daily route"},{"type":"paragraph","text":"An architectural account can begin with the journey from entrance to classroom or reading room. Where do people gather? Which spaces support quiet work, discussion or assembly? How are daylight and circulation organised? These questions bring educational purpose into the description instead of treating the building as a palace with desks added."},{"type":"paragraph","text":"Changes in teaching can leave physical traces. A large room may be subdivided; new equipment may require wiring; access needs may call for alterations. Such changes should be assessed and documented, not automatically condemned as intrusions or accepted without regard to significant fabric."},{"type":"heading","level":2,"text":"Famous names are only one layer"},{"type":"paragraph","text":"Sindh Madressatul Islam''s association with Muhammad Ali Jinnah is central to its public memory, but the institution also contains a wider built and educational history. The university''s own reporting on historic buildings and Talpur House demonstrates that conservation extends beyond a single celebrated room or person."},{"type":"paragraph","text":"Teachers, librarians, caretakers, clerks and generations of students also shaped these places. Their experiences should be collected with consent and recorded alongside dates and architectural drawings. An alumni memory can illuminate how a room was used, while still requiring comparison with other testimony and physical evidence."},{"type":"heading","level":2,"text":"Reuse can change the meaning of a hall"},{"type":"paragraph","text":"The halls now associated with Quaid-e-Azam Library in Lahore have a history beyond their present library function. That makes them valuable for considering how an institutional interior can acquire new purposes. The building''s name, collection and use should not be assumed to share one foundation date."},{"type":"paragraph","text":"A public account should distinguish the chronology of the fabric from the chronology of the organisation. It should also resist describing an earlier elite institution as though access had always been universal. Who could enter, study or borrow is part of the history of learning."},{"type":"paragraph","text":"These are working places, not automatically open tourist attractions. Visits require institutional permission, and photographs must respect students, staff and readers. The quiet practicalities matter: a heritage tour should not interrupt a class or turn a reading room into a backdrop."},{"type":"paragraph","text":"Taking educational buildings seriously broadens architectural discovery. It allows heritage to include the environments where knowledge was organised, debated and passed on, and where those processes continue to change."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-lahore","sindh-south-karachi"],"provinceRegionIds":["punjab","sindh"],"relatedHeritageIds":["major-doam-10146","major-doam-10152","major-doam-6234"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"School and library buildings as heritage | Virsapur","description":"Schools and libraries preserve histories of learning through rooms, routes and continuing use—not only through famous alumni and grand facades.","primaryKeyword":"educational architecture heritage Pakistan","socialTitle":"School and library buildings as heritage","socialDescription":"Schools and libraries preserve histories of learning through rooms, routes and continuing use—not only through famous alumni and grand facades."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Aitchison''s History","url":"https://aitchison.edu.pk/school/history","publisher":"Aitchison College","accessDate":"2026-10-22"},{"title":"Old Building","url":"https://aitchison.edu.pk/school/old-building","publisher":"Aitchison College","accessDate":"2026-10-22"},{"title":"SMIU: Talpur House and historic buildings","url":"https://www.smiu.edu.pk/viewnews/vice-chancellor-dr-mujeeb-sahrai-inaugurates-coffee-house-at-smiu","publisher":"Sindh Madressatul Islam University","accessDate":"2026-10-22"},{"title":"Montgomery Hall, Quaid-i-Azam Library","url":"https://doam.gov.pk/public/sites/10152","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review article; historical and institutional sources used for bounded claims. No unmeasured performance, current access, or unsupported origin claims. Rights-cleared photography absent. Editorial review required.","editorialReason":"Show why everyday institutions deserve architectural reading beyond monumental tourism.","sortOrder":193}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-a-markets-building-and-a-markets-life','a-markets-building-and-a-markets-life','review','{"id":"story-a-markets-building-and-a-markets-life","type":"story","slug":"a-markets-building-and-a-markets-life","title":"A market’s building and a market’s life","summary":"A market survives through trade as well as masonry. Conserving its architecture requires understanding the people and routines that animate it.","body":[{"type":"paragraph","text":"A market can be photographed as a building or experienced as a pattern of exchange. The first view notices gates, roofs and galleries. The second includes deliveries, negotiations, storage, cleaning and the repeated journeys of traders and customers. Neither is sufficient alone. The architecture and its use have histories that overlap without being identical."},{"type":"paragraph","text":"Karachi''s Empress Market provides a clear architectural starting point. The national inventory records a late nineteenth-century building organised with galleries and accommodation for stalls. That description explains part of the formal arrangement. It does not tell us everything about who traded there at different times or how commerce extended into the surrounding streets."},{"type":"heading","level":2,"text":"Plans show capacity, not a complete social history"},{"type":"paragraph","text":"A row of stalls suggests a division of space, but a plan cannot establish the goods sold in every period, the terms of tenancy or the relationships between traders. Those questions need records and testimony. A historical capacity figure should not be presented as a current count of businesses without a new survey."},{"type":"paragraph","text":"Likewise, an open passage may have served customers, deliveries or both at different times of day. Understanding these rhythms requires observation with dates and consent, rather than a single crowded photograph treated as a timeless image of market life."},{"type":"heading","level":2,"text":"A bazaar need not be one monumental building"},{"type":"paragraph","text":"Tang Gali Bazaar in Kalabagh offers a different kind of enquiry. Its official record draws attention to verandas and wooden balconies along a trading setting. Here, the architectural interest lies partly in a sequence of edges and upper levels, rather than only in one designed market hall."},{"type":"paragraph","text":"The comparison should retain that difference. A purpose-built market and a street bazaar may both support trade while arranging access, shade, storage and display differently. Neither should be treated as a more authentic version of the other simply because it appears older or more picturesque."},{"type":"heading","level":2,"text":"Improvement has consequences"},{"type":"paragraph","text":"Historic England''s guidance on historic retail centres connects the condition of buildings and public space with the health of their uses. Its institutional context differs from Pakistan''s, but the underlying question is useful: what happens to a historic market if the architecture is repaired while the activities sustaining it are displaced?"},{"type":"paragraph","text":"Answering that question requires listening to traders, workers, residents and customers, including people whose contribution is not represented by a shopfront. Cleaner views and restored masonry are not, by themselves, a complete measure of success. Access for deliveries, sanitation, safe movement and viable livelihoods belong in the assessment."},{"type":"paragraph","text":"For a visitor, respectful attention means asking before close portraits, keeping routes clear and recognising that bargaining or handling goods is not a performance staged for heritage tourism. A purchase can be an exchange; it does not purchase unlimited access to someone''s story."},{"type":"paragraph","text":"The market''s building and its life should remain connected in interpretation. The goal is neither an empty architectural exhibit nor an uncritical celebration of congestion, but a place whose history and continuing work can both be understood."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["sindh-south-karachi","punjab-mianwali"],"provinceRegionIds":["sindh","punjab"],"relatedHeritageIds":["major-doam-5846","major-doam-9924"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"A market’s building and a market’s life | Virsapur","description":"A market survives through trade as well as masonry. Conserving its architecture requires understanding the people and routines that animate it.","primaryKeyword":"historic market architecture Pakistan","socialTitle":"A market’s building and a market’s life","socialDescription":"A market survives through trade as well as masonry. Conserving its architecture requires understanding the people and routines that animate it."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Empress Market","url":"https://doam.gov.pk/public/sites/5846","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Tang Gali Bazar, Kalabagh","url":"https://doam.gov.pk/public/sites/9924","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Historic Town Centres and High Streets","url":"https://historicengland.org.uk/advice/planning/historic-towns-and-high-streets/","publisher":"Historic England","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review article; historical and institutional sources used for bounded claims. No unmeasured performance, current access, or unsupported origin claims. Rights-cleared photography absent. Editorial review required.","editorialReason":"Separate formal design from the changing practices of traders and users.","sortOrder":194}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-reading-repairs-without-calling-everything-original','reading-repairs-without-calling-everything-original','review','{"id":"story-reading-repairs-without-calling-everything-original","type":"story","slug":"reading-repairs-without-calling-everything-original","title":"Reading repairs without calling everything original","summary":"A repaired building is not necessarily a false building. The crucial questions are what survives, what changed and whether the evidence remains readable.","body":[{"type":"paragraph","text":"The word original can hide several different claims. It might mean material surviving from a building''s first construction, a later historic addition still in place, or a modern repair intended to recover an earlier appearance. These are not equivalent. A useful heritage account explains which meaning it intends instead of applying the word to an entire monument."},{"type":"paragraph","text":"Buildings that remain standing have often been maintained. Roofs leak, timber decays and surfaces weather. Repair can preserve important fabric by addressing those problems. The presence of new material is therefore not enough to dismiss conservation as fake; the amount, purpose, compatibility and documentation of the intervention matter."},{"type":"heading","level":2,"text":"Retention is a decision supported by investigation"},{"type":"paragraph","text":"The published Baltit conservation account describes carefully recording timber elements and retaining more structural timber than early estimates had anticipated. That is a specific lesson about investigation: an initial expectation of replacement can change when the building is examined closely. It is not a percentage target that every other project should copy."},{"type":"paragraph","text":"A replaced member may be necessary, while an apparently sound surface may conceal a problem. Visitors cannot settle those questions by colour or age alone. The conservation report should explain what was found, which alternatives were considered and why the chosen action was taken."},{"type":"heading","level":2,"text":"Legible does not mean aggressively contrasting"},{"type":"paragraph","text":"Conservation discussions associated with the Venice Charter address the relationship between retained work and additions, including the need not to falsify historical evidence. This does not mean every repair must dominate the building visually. The challenge is to make intervention intelligible without allowing it to overwhelm the place."},{"type":"paragraph","text":"Legibility can be supported by close-range differences, dated records, drawings and interpretation. A discreet repair may be understandable in a well-documented account even when it does not announce itself from across a courtyard. Conversely, a highly visible modern insert is not automatically a good conservation decision merely because it is unmistakably new."},{"type":"heading","level":2,"text":"Later history may also deserve retention"},{"type":"paragraph","text":"Returning a building to an imagined first day can remove evidence of subsequent use. A later window, partition or painted layer may possess significance of its own. The question is not simply whether an element is early or late, but what it contributes to the place''s history and how intervention affects that evidence."},{"type":"paragraph","text":"Baltit Fort and Shahi Hammam offer different settings for examining conservation records. Their methods and objectives should not be merged into one universal approach. Each project requires its own account of retained fabric, discoveries, repairs and interpretation."},{"type":"paragraph","text":"A useful visitor panel can show a before photograph, a survey and the completed work, with uncertain reconstruction clearly identified. ICCROM''s presentation of its historic training projects demonstrates the value of keeping drawings, photographs and reports together."},{"type":"paragraph","text":"The honest question is not whether everything looks old. It is whether the building''s material history, including the work that helped it survive, can still be understood."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["gilgit-baltistan-hunza","punjab-lahore"],"provinceRegionIds":["gilgit-baltistan","punjab"],"relatedHeritageIds":["curated-baltit","major-doam-9778"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"Reading repairs without calling everything original | Virsapur","description":"A repaired building is not necessarily a false building. The crucial questions are what survives, what changed and whether the evidence remains readable.","primaryKeyword":"historic building repair phases","socialTitle":"Reading repairs without calling everything original","socialDescription":"A repaired building is not necessarily a false building. The crucial questions are what survives, what changed and whether the evidence remains readable."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Conservation and Development in Hunza and Baltistan","url":"https://static.the.akdn/53832/1641873948-2005_hcsp_hunza.pdf","publisher":"Aga Khan Historic Cities Programme","accessDate":"2026-10-22"},{"title":"Observations on Concepts in the Venice Charter","url":"https://www.iccrom.org/sites/default/files/publications/2023-02/en_es_lac_11_conversaciones_iccrom_2023_compressed.pdf","publisher":"ICCROM; Jukka Jokilehto","accessDate":"2026-10-22"},{"title":"ICCROM Architectural Conservation Course: Capua study project","url":"https://www.iccrom.org/resources/resources-of-the-month/iccrom-international-architectural-conservation-course-arc-study","publisher":"ICCROM","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review article; historical and institutional sources used for bounded claims. No unmeasured performance, current access, or unsupported origin claims. Rights-cleared photography absent. Editorial review required.","editorialReason":"Explain why visible replacement can be honest conservation when documented.","sortOrder":195}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-adaptive-reuse-what-should-stay-legible','adaptive-reuse-what-should-stay-legible','review','{"id":"story-adaptive-reuse-what-should-stay-legible","type":"story","slug":"adaptive-reuse-what-should-stay-legible","title":"Adaptive reuse: what should stay legible","summary":"A new use can sustain a historic building, but its success depends on whether important spaces, fabric and stories remain understandable.","body":[{"type":"paragraph","text":"Adaptive reuse gives a building a purpose different from the one for which it was made. A residence may become a museum; a palace may accommodate hospitality. The change can bring maintenance, public interest and income, but a new use is not automatically a successful conservation outcome. It must be assessed against what makes the place significant."},{"type":"paragraph","text":"Mohatta Palace Museum''s own history records successive residential, governmental and museum uses. Its account connects the present institution with restoration and an exhibition programme. This layered history is more informative than presenting the building as though it had always been a museum or as though its value ended when its first occupant left."},{"type":"heading","level":2,"text":"Keep the route through the building intelligible"},{"type":"paragraph","text":"A new function can alter how people enter and move. Reception desks, display walls, security arrangements and service areas may be necessary, yet they can obscure earlier relationships between rooms. Good interpretation helps a visitor distinguish the historic spatial arrangement from the route required by the present institution."},{"type":"paragraph","text":"The question is not whether every room must retain an old use. It is whether significant features and relationships remain legible. A large hall subdivided into small units creates a different experience from one whose scale remains visible. Which change is acceptable depends on evidence and significance, not a universal preference for open space."},{"type":"heading","level":2,"text":"Services are architectural interventions"},{"type":"paragraph","text":"Bathrooms, wiring, drainage, climate control and fire safety require careful planning. Their effects are not limited to visible equipment. Routes through walls and floors can affect historic fabric, and maintenance access influences what happens after the opening ceremony. A conservation proposal should explain these systems rather than hide them behind a claim of sympathetic design."},{"type":"paragraph","text":"At Shigar, AKDN describes a conservation model that combined restored fabric with a hospitality use. That project provides a documented example to examine, not a rule that every fort should become a hotel. Different buildings, communities and access expectations can support different choices."},{"type":"heading","level":2,"text":"Public benefit needs a practical definition"},{"type":"paragraph","text":"A museum may expand access to collections while imposing necessary restrictions on rooms, photography or events. A hospitality project may provide employment but limit access to private guest areas. These consequences should be stated clearly. The phrase open to the public should not conceal the actual conditions of entry."},{"type":"paragraph","text":"Mukhi Mahal is another linked place from which to investigate changed use through its own institutional record. Comparisons should consider interpretation, maintenance, accessibility and the treatment of former occupants'' histories, rather than ranking projects by the glamour of their new function."},{"type":"paragraph","text":"A successful reuse does not freeze a building, nor does it make the past disappear behind a commercial or cultural brand. It creates a workable present while allowing visitors to recognise what came before. The test is concrete: can the important fabric be maintained, can the building''s history be understood, and can the people responsible sustain that care beyond a single project?"}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["gilgit-baltistan-shigar","sindh-hyderabad","sindh-south-karachi"],"provinceRegionIds":["gilgit-baltistan","sindh"],"relatedHeritageIds":["major-doam-7998","major-doam-5700","major-doam-6036"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"Adaptive reuse: what should stay legible | Virsapur","description":"A new use can sustain a historic building, but its success depends on whether important spaces, fabric and stories remain understandable.","primaryKeyword":"adaptive reuse heritage Pakistan","socialTitle":"Adaptive reuse: what should stay legible","socialDescription":"A new use can sustain a historic building, but its success depends on whether important spaces, fabric and stories remain understandable."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"History of the Museum","url":"https://mohattapalacemuseum.org/public/history-of-the-museum","publisher":"Mohatta Palace Museum","accessDate":"2026-10-22"},{"title":"About the Museum","url":"https://www.mohattapalacemuseum.org/about-the-museum","publisher":"Mohatta Palace Museum","accessDate":"2026-10-22"},{"title":"Shigar Fort: a new model of conservation","url":"https://www-hetz2.the.akdn/en/resources-media/whats-new/news-release/shigar-fort-new-model-conservation-combines-economic-and-cultural-objectives","publisher":"Aga Khan Development Network","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review article; historical and institutional sources used for bounded claims. No unmeasured performance, current access, or unsupported origin claims. Rights-cleared photography absent. Editorial review required.","editorialReason":"Compare new functions and historic legibility without assuming every reuse is successful.","sortOrder":196}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-shading-before-air-conditioning','shading-before-air-conditioning','review','{"id":"story-shading-before-air-conditioning","type":"story","slug":"shading-before-air-conditioning","title":"Shading before air-conditioning","summary":"Verandas, screens and courtyards can moderate sun and air, but their performance depends on orientation, climate and the whole building.","body":[{"type":"paragraph","text":"Standing in a shaded veranda can make the difference between sun and shelter immediately apparent. It is tempting to turn that experience into a sweeping claim that historic buildings always remained cool without mechanical systems. The more interesting explanation is specific: which surfaces are shaded, where air can move, how the building is used and what the weather is doing."},{"type":"paragraph","text":"Shading can reduce direct solar exposure to openings and surfaces. It is not identical to lowering the temperature of the outside air. A roof projection, screen or deep opening changes the relationship between sun and building, while ventilation concerns the movement of air. These processes interact, but they should not be treated as one magical vernacular solution."},{"type":"heading","level":2,"text":"Orientation changes the result"},{"type":"paragraph","text":"An overhang''s effect depends on the direction of the opening and the sun''s position. A deep shaded zone at one time of day may receive low sunlight at another. A photograph taken at noon in one season cannot establish year-round performance."},{"type":"paragraph","text":"The US Department of Energy''s design guidance treats shading as one part of a wider cooling strategy and distinguishes it from ventilation and other measures. This is a technical framework for asking questions, not direct performance evidence for a Pakistani haveli. Local climate and the building''s actual configuration still need study."},{"type":"heading","level":2,"text":"Courtyards are not automatically cool"},{"type":"paragraph","text":"A courtyard may provide light, circulation and a relationship between rooms, but its thermal behaviour depends on proportions, surface exposure, vegetation, openings and use. A broad sunlit court differs from a narrow shaded one. Adding the word traditional does not make those differences disappear."},{"type":"paragraph","text":"Haveli Sujan Singh''s documented courtyard and entrance arrangement offers a starting point for spatial investigation. It does not supply measured temperatures or prove a particular air-flow pattern. A careful account can describe the architecture and identify a possible environmental role while leaving performance claims open."},{"type":"heading","level":2,"text":"Heating and cooling histories can coexist"},{"type":"paragraph","text":"Shahi Hammam is a useful reminder that historic environmental design also involved deliberately producing and managing heat. A public bath should not be recruited into a generic story about cooling simply because it has thick walls or shaded rooms. Its particular services and room functions require their own explanation."},{"type":"paragraph","text":"Likewise, occupants may have changed rooms, opened and closed shutters or adjusted daily routines with the season. Those practices belong to environmental history, but they must be documented rather than imagined for every house."},{"type":"heading","level":2,"text":"Learn without promising a shortcut"},{"type":"paragraph","text":"Modern reuse can change occupancy, internal heat gains and ventilation paths. Blocking a veranda or sealing an opening may alter the original arrangement, yet removing modern equipment without assessment can also make a building unsuitable for present users."},{"type":"paragraph","text":"The useful lesson is attentive design, not a claim that one old feature solves every contemporary problem. Observe the shade, record the time and orientation, and distinguish measured evidence from a comfortable moment. Historic buildings can then inform environmental thinking without being burdened with performance guarantees their documentation cannot support."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-rawalpindi","punjab-lahore"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-9419","major-doam-9778"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"Shading before air-conditioning | Virsapur","description":"Verandas, screens and courtyards can moderate sun and air, but their performance depends on orientation, climate and the whole building.","primaryKeyword":"historic passive cooling Pakistan","socialTitle":"Shading before air-conditioning","socialDescription":"Verandas, screens and courtyards can moderate sun and air, but their performance depends on orientation, climate and the whole building."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"The Building Architectural Design: Passive Cooling Strategies","url":"https://www.energy.gov/sites/prod/files/2013/12/f5/sustainable_guide_ch4.pdf","publisher":"Los Alamos National Laboratory / US Department of Energy","accessDate":"2026-10-22"},{"title":"Home Cooling","url":"https://www.energy.gov/home-cooling","publisher":"US Department of Energy","accessDate":"2026-10-22"},{"title":"Haveli Sujan Singh","url":"https://doam.gov.pk/public/sites/9419","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review article; historical and institutional sources used for bounded claims. No unmeasured performance, current access, or unsupported origin claims. Rights-cleared photography absent. Editorial review required.","editorialReason":"Examine screens, verandas and courtyards without claiming measured performance absent research.","sortOrder":197}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-jali-screens-light-privacy-and-stonework','jali-screens-light-privacy-and-stonework','review','{"id":"story-jali-screens-light-privacy-and-stonework","type":"story","slug":"jali-screens-light-privacy-and-stonework","title":"Jali screens: light, privacy and stonework","summary":"A jali is a material screen and a changing field of light. Its geometry matters together with thickness, position and the space around it.","body":[{"type":"paragraph","text":"A jali makes a boundary without making it completely solid. Its openings allow a relationship between spaces while the remaining material establishes a pattern. Seen frontally, it may resemble a geometric drawing. Seen in place, it also has thickness, weight, changing shadows and a particular relationship to the people on either side."},{"type":"paragraph","text":"The Metropolitan Museum''s marble and sandstone screens illustrate that material difference. Its curatorial descriptions also distinguish the screen itself from the effects of light passing through it. These are comparative objects attributed to the subcontinent, not components to be reassigned to a Pakistani monument without provenance."},{"type":"heading","level":2,"text":"Geometry is made in material"},{"type":"paragraph","text":"A drawn pattern can be repeated indefinitely. A carved stone panel must hold together, fit an opening and survive handling and use. The widths of connecting elements, the treatment of the border and the transition between patterns therefore matter as much as the attractive shapes of the holes."},{"type":"paragraph","text":"Some screens are cut from a single piece; others use different assembly methods or materials. Do not assume that every perforated architectural panel demonstrates the same process. A technical record should identify the material and construction before a caption praises the supposed difficulty of making it."},{"type":"heading","level":2,"text":"The view changes with position"},{"type":"paragraph","text":"Move sideways within the permitted area and an opening''s apparent size can change. Thickness and angle influence what is visible through the screen. Light from outside and inside also affects the relationship between seeing and being seen. Privacy is therefore conditional, not an absolute property permanently guaranteed by a patterned surface."},{"type":"paragraph","text":"A screen may divide an interior, fill an external opening or protect an edge. Those positions create different spatial tasks. The presence of a jali does not, by itself, establish the gender, status or identity of everyone who used the room."},{"type":"heading","level":2,"text":"Shadow is part of the composition"},{"type":"paragraph","text":"The Met''s interpretation draws attention to the moving patterns projected into an interior. A useful architectural photograph can show both the panel and its effect on an adjoining floor or wall, provided the setting and permission allow it. Recording the time helps distinguish a momentary pattern from a permanent feature."},{"type":"paragraph","text":"At the tombs of Shah Burhan or Jahangir, the linked place records offer starting points for investigating screens in their own settings. Their materials, repairs and specific functions should be checked individually rather than inferred from the museum comparisons."},{"type":"paragraph","text":"A broken or replaced section also belongs in the history. A visually complete pattern may include conservation work, while weathering can alter the apparent sharpness of an opening. Touching fragile edges to test thickness is not an acceptable way to investigate."},{"type":"paragraph","text":"The pleasure of a jali lies in several relationships at once: solid and open, pattern and support, visibility and shelter, surface and shadow. Describing those relationships keeps the craft connected to architecture instead of reducing it to an ornamental motif that could be pasted anywhere."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-chiniot","punjab-lahore"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6211","major-doam-6479"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"Jali screens: light, privacy and stonework | Virsapur","description":"A jali is a material screen and a changing field of light. Its geometry matters together with thickness, position and the space around it.","primaryKeyword":"jali screen architecture","socialTitle":"Jali screens: light, privacy and stonework","socialDescription":"A jali is a material screen and a changing field of light. Its geometry matters together with thickness, position and the space around it."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Pierced Window Screen, object 1984.193","url":"https://www.metmuseum.org/art/collection/search/453241","publisher":"The Metropolitan Museum of Art","accessDate":"2026-10-22"},{"title":"Pierced Window Screen, object 1993.67.1","url":"https://www.metmuseum.org/art/collection/search/453343","publisher":"The Metropolitan Museum of Art","accessDate":"2026-10-22"},{"title":"Jali: educator resource","url":"https://www.metmuseum.org/learn/educators/curriculum-resources/art-of-the-islamic-world/unit-three/featured-works-of-art/image-15","publisher":"The Metropolitan Museum of Art","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review article; historical and institutional sources used for bounded claims. No unmeasured performance, current access, or unsupported origin claims. Rights-cleared photography absent. Editorial review required.","editorialReason":"Explain material and spatial effects rather than treat all perforated screens as identical.","sortOrder":198}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-plinth-why-a-building-begins-above-the-street','the-plinth-why-a-building-begins-above-the-street','review','{"id":"story-the-plinth-why-a-building-begins-above-the-street","type":"story","slug":"the-plinth-why-a-building-begins-above-the-street","title":"The plinth: why a building begins above the street","summary":"A raised base changes how a building meets the street. Its purpose may involve space, presentation or water—but those explanations need evidence.","body":[{"type":"paragraph","text":"The first architectural decision a visitor encounters may be underfoot. A building can begin at street level, rise by a few steps or stand on a substantial platform. That raised base, often described as a plinth, changes the approach and the relationship between the building and its surroundings. It should not be treated as a decorative strip at the bottom of an elevation."},{"type":"paragraph","text":"At Lahore''s Sunehri Mosque, the Punjab heritage authority describes an elevated arrangement accommodating shops beneath the prayer space. This is a specific urban relationship: different uses occupy different levels. It provides a stronger explanation than assuming that every raised religious building was elevated only to appear grand."},{"type":"heading","level":2,"text":"A platform can organise several functions"},{"type":"paragraph","text":"A plinth may establish a level surface on uneven ground, mark a transition or affect the relationship to water and surrounding activity. Which of these purposes mattered in a particular building must be demonstrated. A high base is not automatic proof of flood protection, and a broad platform is not automatic proof of ceremonial gathering."},{"type":"paragraph","text":"The Dalwal temple record identifies a square building on a raised platform. That observation is secure enough to begin a spatial description. It does not establish the platform''s original height, all its uses or the reason its builders selected that arrangement."},{"type":"heading","level":2,"text":"The street may have moved vertically"},{"type":"paragraph","text":"Road surfaces can be renewed, deposits can accumulate and adjacent land can be altered. Today''s relationship between doorway and street may therefore differ from an earlier one. A building that seems unusually low may once have stood higher relative to its surroundings; a newly cleared base may reveal a previously concealed level."},{"type":"paragraph","text":"Establishing this change requires surveys, dated photographs or archaeological evidence. It is not enough to compare two images taken from different angles. Measurements should state which surface and date they describe, especially where a restoration has altered the visible ground line."},{"type":"heading","level":2,"text":"The approach is part of the architecture"},{"type":"paragraph","text":"Steps, ramps and landings turn a difference in level into a route. Their position affects how visitors encounter the facade and where movement gathers. A central stair produces a different approach from a side entrance, even when both reach the same raised space."},{"type":"paragraph","text":"For current use, accessibility cannot be dismissed as an inconvenience to historical appearance. A thoughtful solution needs both conservation expertise and an understanding of users'' needs. The task is to improve access without casually damaging significant fabric or presenting a modern intervention as an original feature."},{"type":"paragraph","text":"A clear public description can separate three things: the surviving platform, the documented historical ground level and the present access arrangement. If one is unknown, the account should say so."},{"type":"paragraph","text":"Reading the plinth makes architecture feel less like an image floating above the city. The building begins somewhere, meets a changing ground and receives people through a designed sequence. That connection is often where its practical and symbolic roles become most visible."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-lahore","punjab-chakwal"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-10190","major-doam-6754"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"The plinth: why a building begins above the street | Virsapur","description":"A raised base changes how a building meets the street. Its purpose may involve space, presentation or water—but those explanations need evidence.","primaryKeyword":"historic building plinth","socialTitle":"The plinth: why a building begins above the street","socialDescription":"A raised base changes how a building meets the street. Its purpose may involve space, presentation or water—but those explanations need evidence."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Monuments: Sunehri Mosque","url":"https://walledcitylahore.gop.pk/monuments/","publisher":"Punjab Walled Cities and Heritage Areas Authority","accessDate":"2026-10-22"},{"title":"Dalwal Temple-I","url":"https://doam.gov.pk/public/sites/6754","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Sunehri Masjid, Lahore","url":"https://doam.gov.pk/public/sites/10190","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review article; historical and institutional sources used for bounded claims. No unmeasured performance, current access, or unsupported origin claims. Rights-cleared photography absent. Editorial review required.","editorialReason":"Compare flood, visibility and spatial explanations while marking hypotheses clearly.","sortOrder":199}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-historic-streets-are-made-of-edges','historic-streets-are-made-of-edges','review','{"id":"story-historic-streets-are-made-of-edges","type":"story","slug":"historic-streets-are-made-of-edges","title":"Historic streets are made of edges","summary":"Historic streets take shape through continuous edges, thresholds and everyday services. Their heritage is not limited to the landmark at the end.","body":[{"type":"paragraph","text":"A historic street is not simply the gap between important buildings. Its character emerges from the edges that define it: a repeated line of shopfronts, a recessed doorway, an upper balcony, a blank wall or a sudden opening into a courtyard. Walking through it is an encounter with changing enclosure and access."},{"type":"paragraph","text":"A landmark gate can help orient a route, but the spaces between landmarks often carry the everyday life of the place. Around Delhi Gate or Bhati Gate in Lahore, and in historic Bhera, an architectural enquiry should therefore look beyond a list of monuments. The width of a passage and the rhythm of entrances can be as revealing as an individual decorated facade."},{"type":"heading","level":2,"text":"Follow the ground floor"},{"type":"paragraph","text":"The street''s lower edge is where public movement meets buildings. Note where people enter, pause, exchange goods or turn into narrower routes. An upper facade may look continuous while the ground floor contains very different relationships: a private threshold, a shop, a service opening or a blocked entrance."},{"type":"paragraph","text":"These observations need time and context. A shuttered frontage early in the morning does not prove vacancy, and a busy doorway does not establish the use of every room above it. Recording the time and asking occupants about their space prevents a fleeting impression from becoming a fixed description."},{"type":"heading","level":2,"text":"Infrastructure belongs in the view"},{"type":"paragraph","text":"AKDN''s account of Lahore''s Royal Trail work joins improvements to utilities with rehabilitation of buildings and street fronts. This is a valuable reminder that a historic streetscape includes water, drainage and electricity, not only the surfaces tourists see. A clean facade cannot compensate for failing services behind or beneath it."},{"type":"paragraph","text":"Changes to paving, signs and street furniture also influence movement and visual continuity. A new object may solve one problem while creating another if it blocks a narrow route or obscures an entrance. The relevant question is how the whole street works for its users."},{"type":"heading","level":2,"text":"An audit should include people"},{"type":"paragraph","text":"Historic England''s street-audit guidance combines attention to heritage with access and safety. Used as a comparative method rather than imported regulation, it encourages a practical enquiry: which features are valued, which movements are obstructed and who experiences the street differently?"},{"type":"paragraph","text":"Residents, traders, delivery workers and people with mobility or sensory needs may identify issues a visitor overlooks. Consultation is not a decorative addition to a completed design. It can change the understanding of what should be retained or improved."},{"type":"paragraph","text":"The aim is not to remove every sign of present life until a street resembles an empty historical photograph. Nor is every alteration harmless because it supports an existing activity. Both heritage and use require careful judgement."},{"type":"paragraph","text":"A good walking account traces edges, transitions and services alongside memorable buildings. It allows the street to remain a connected place where people live and work, rather than a sequence of isolated photo stops linked by anonymous pavement."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["punjab-lahore","punjab-sargodha"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6449","major-doam-6458","major-doam-6576"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"Historic streets are made of edges | Virsapur","description":"Historic streets take shape through continuous edges, thresholds and everyday services. Their heritage is not limited to the landmark at the end.","primaryKeyword":"historic streetscape Pakistan","socialTitle":"Historic streets are made of edges","socialDescription":"Historic streets take shape through continuous edges, thresholds and everyday services. Their heritage is not limited to the landmark at the end."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Prepare a Street Audit","url":"https://historicengland.org.uk/advice/caring-for-heritage/streets-for-all/what-you-can-do/street-clutter-audit/","publisher":"Historic England","accessDate":"2026-10-22"},{"title":"Walled city of Lahore conservation","url":"https://the.akdn/en/where-we-work/south-asia/pakistan/walled-city-of-lahore-conservation-pakistan","publisher":"Aga Khan Development Network","accessDate":"2026-10-22"},{"title":"Work Towards Improvement Together","url":"https://historicengland.org.uk/advice/caring-for-heritage/streets-for-all/what-you-can-do/work-towards-improvement-together/","publisher":"Historic England","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review article; historical and institutional sources used for bounded claims. No unmeasured performance, current access, or unsupported origin claims. Rights-cleared photography absent. Editorial review required.","editorialReason":"Read frontage, entrances and route width rather than reduce a street to landmark buildings.","sortOrder":200}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-what-measured-drawings-can-preserve','what-measured-drawings-can-preserve','review','{"id":"story-what-measured-drawings-can-preserve","type":"story","slug":"what-measured-drawings-can-preserve","title":"What measured drawings can preserve","summary":"Plans, sections and elevations preserve different kinds of evidence. Reading them together makes a building’s construction and later changes easier to understand.","body":[{"type":"paragraph","text":"A measured drawing makes an argument about a building through lines, dimensions and conventions. Unlike a picturesque sketch, it offers relationships that another person can check: the width of an opening, the thickness of a wall, or the height between two floors. Its value is not that it replaces the building, but that it preserves a particular, dated understanding of it."},{"type":"paragraph","text":"A photograph can show the colour of timber and the texture of plaster exceptionally well. It may be much less useful for comparing rooms hidden behind one another. A drawing can expose those relationships, provided its author explains what was measured, what was inferred and which parts remained inaccessible."},{"type":"heading","level":2,"text":"Three views, three questions"},{"type":"paragraph","text":"A plan describes a horizontal slice. It helps readers follow passages, compare rooms and notice a wall that changes thickness. An elevation records a face of the building without the perspective of an ordinary photograph. A section cuts vertically through it, making floor levels, roof structures and connections between storeys intelligible. None is simply a more technical version of the other."},{"type":"paragraph","text":"Imagine documenting a timber balcony at a mountain palace. An elevation might establish the spacing of its posts, while a section explains how the projecting floor relates to the room behind it. A plan could locate a stair that is invisible from outside. This is an illustrative recording exercise, not a claim about a particular undocumented detail at Shigar or Khaplu."},{"type":"heading","level":2,"text":"Measurement and interpretation"},{"type":"paragraph","text":"Historic England’s Drawing for Understanding guidance treats hand measurement and analytical drawing as ways of investigating fabric closely. It recommends using drawings with photographs and written records rather than expecting one medium to carry everything. Its separate geospatial specification addresses the requirements of accurate survey datasets, including digital methods."},{"type":"paragraph","text":"That distinction matters. A highly precise scan does not itself explain why a doorway was blocked. Conversely, a persuasive phase diagram may contain conjecture even when drawn with immaculate lines. The useful record keeps these layers distinguishable: measured position, observed material, interpreted sequence and proposed reconstruction."},{"type":"paragraph","text":"Consider an uneven wall. Straightening it on paper might make a cleaner illustration, but erase evidence needed by a later investigator. The drawing’s purpose should determine the detail recorded, not an assumption that an old building must conform to an ideal geometry. Small irregularities may deserve annotation precisely because their significance is not yet understood."},{"type":"heading","level":2,"text":"What survives in the archive"},{"type":"paragraph","text":"A useful drawing needs a scale, orientation, date, author and a clear explanation of symbols. Its relationship to photographs should also be recoverable. A numbered timber joint that appears in the drawing becomes far more informative when its close-up photograph and inspection note can be found without guesswork."},{"type":"paragraph","text":"For readers exploring Pakistan’s palaces and houses, measured drawings open another route into architecture: not just what a facade resembles, but how spaces connect and how evidence supports an interpretation. They can preserve knowledge of fabric before repair changes its appearance. They cannot preserve the fabric itself, and their existence should never be mistaken for a reason that losing it does not matter."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["gilgit-baltistan-shigar","gilgit-baltistan-ghanche"],"provinceRegionIds":["gilgit-baltistan"],"relatedHeritageIds":["major-doam-7998","major-doam-7974"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"What measured drawings can preserve | Virsapur","description":"Plans, sections and elevations preserve different kinds of evidence. Reading them together makes a building’s construction and later changes easier to understand.","primaryKeyword":"measured drawings heritage documentation","socialTitle":"What measured drawings can preserve","socialDescription":"Plans, sections and elevations preserve different kinds of evidence. Reading them together makes a building’s construction and later changes easier to understand."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Drawing for Understanding","url":"https://historicengland.org.uk/images-books/publications/drawing-for-understanding/","publisher":"Historic England","accessDate":"2026-10-22"},{"title":"Geospatial Survey Specifications for Cultural Heritage","url":"https://historicengland.org.uk/images-books/publications/geospatial-survey-specifications-cultural-heritage/","publisher":"Historic England","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original source-based review draft. Comparative examples are labelled and must not be transferred to linked Pakistani sites. No live access promises. Article-specific sources read; limited paraphrase with original analytical explanation. ","editorialReason":"Explain the evidential role of plans, sections and elevations before intervention.","sortOrder":201}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-architecture-after-damage-reconstruction-and-honesty','architecture-after-damage-reconstruction-and-honesty','review','{"id":"story-architecture-after-damage-reconstruction-and-honesty","type":"story","slug":"architecture-after-damage-reconstruction-and-honesty","title":"Architecture after damage: reconstruction and honesty","summary":"The rebuilt Ziarat Residency raises a useful question: how can a damaged monument recover its public meaning while making its repairs and replacements intelligible?","body":[{"type":"paragraph","text":"After a historic building is damaged, the question is rarely just whether its familiar outline can be recovered. Which materials remain? What evidence records the missing parts? Whose memories and uses should the work sustain? A reconstructed building can have considerable public meaning without every visible element being old. Explaining that difference is part of caring for the place."},{"type":"paragraph","text":"Ziarat Residency is a particularly important Pakistani example because its association with Muhammad Ali Jinnah gives it a significance extending beyond architectural design. The federal heritage catalogue records his stay there in 1948. That historical association is not erased when fabric is lost, but neither does it make replacement material automatically original."},{"type":"heading","level":2,"text":"A documented disagreement"},{"type":"paragraph","text":"In a 2014 interview about work following the 2013 attack, architect Nayyar Ali Dada described using photographs and documentation from an earlier intervention. He also explained that previous alterations complicated decisions about what should be recreated. The same report recorded Yasmeen Lari’s preference for retaining damaged objects as visible witnesses. These were different responses to loss, not simply a dispute between caring and not caring."},{"type":"paragraph","text":"The interview is valuable as participant testimony, rather than a complete technical account of the project. It reveals choices and time pressures that a photograph of the finished building cannot show. It does not establish a room-by-room inventory of surviving fabric, and this article does not attempt to supply one."},{"type":"heading","level":2,"text":"Repair, reconstruction and commemoration"},{"type":"paragraph","text":"For an ordinary reader, it helps to separate three questions. Repair concerns making surviving fabric sound. Reconstruction introduces material to recover something missing. Commemoration concerns how the place communicates an event or a person. One project may do all three, but the evidence required for each is different."},{"type":"paragraph","text":"Suppose a lost balustrade is reproduced from a dated, detailed photograph. That provides a stronger basis for its visible arrangement than a distant view in which the railings cannot be counted. Neither photograph necessarily establishes concealed joints or the original timber species. A truthful account could identify the visible form as documented while explaining that other decisions used comparative evidence."},{"type":"heading","level":2,"text":"Honesty need not mean visual conflict"},{"type":"paragraph","text":"The ICCROM–ICOMOS recovery guidance places rebuilding within a wider process involving people and the consequences of disaster or conflict. This helps move discussion beyond a choice between leaving everything ruined and making damage disappear. A community’s recovery, the survival of evidence and the future use of a place all deserve attention."},{"type":"paragraph","text":"Visitors do not need every replacement to shout across a facade. They do need access to an intelligible explanation: what was retained, what was renewed, when the intervention happened, and where uncertainty remains. A concise timeline, carefully labelled objects and an accessible project record can support that understanding."},{"type":"paragraph","text":"The strongest question to ask of a recovered monument is therefore not merely whether it looks as it once did. It is whether the building and its interpretation allow people to recognise both its earlier history and the later act of reconstruction. At Ziarat, those histories belong together; reducing the place to either an untouched relic or a meaningless copy would obscure what makes it significant."}],"primaryCategoryId":"archive-category-architecture-built-heritage","categoryIds":["archive-category-architecture-built-heritage"],"tags":["Architecture"],"province":null,"district":null,"relatedDistrictIds":["balochistan-ziarat"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["major-doam-9686"],"relatedStoryIds":[],"contentType":"architecture","seo":{"title":"Architecture after damage: reconstruction and honesty | Virsapur","description":"The rebuilt Ziarat Residency raises a useful question: how can a damaged monument recover its public meaning while making its repairs and replacements intelligible?","primaryKeyword":"heritage reconstruction authenticity","socialTitle":"Architecture after damage: reconstruction and honesty","socialDescription":"The rebuilt Ziarat Residency raises a useful question: how can a damaged monument recover its public meaning while making its repairs and replacements intelligible?"},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Guidance on Post-Disaster and Post-Conflict Recovery and Reconstruction of Heritage Places","url":"https://www.iccrom.org/publication/guidance-post-disaster-and-post-conflict-recovery-and-reconstruction-heritage-places","publisher":"ICCROM and ICOMOS","accessDate":"2026-10-22"},{"title":"Ziarat Residency: Restoring the house that Mr Jinnah called home","url":"https://tribune.com.pk/story/748568/ziarat-residency-restoring-the-house-that-mr-jinnah-called-home","publisher":"The Express Tribune; interviews with project architects","accessDate":"2026-10-22"},{"title":"Quaid-e-Azam Residency, Ziarat","url":"https://doam.gov.pk/public/sites/9686","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original source-based review draft. Comparative examples are labelled and must not be transferred to linked Pakistani sites. No live access promises. Article-specific sources read; limited paraphrase with original analytical explanation. Architect testimony is attributed as a reported primary interview, not a comprehensive conservation record.","editorialReason":"Distinguish repair, reconstruction and commemoration using documented decisions rather than moral absolutes.","sortOrder":202}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-visiting-a-sacred-place-that-is-still-in-use','visiting-a-sacred-place-that-is-still-in-use','review','{"id":"story-visiting-a-sacred-place-that-is-still-in-use","type":"story","slug":"visiting-a-sacred-place-that-is-still-in-use","title":"Visiting a sacred place that is still in use","summary":"A living sacred place is not an empty monument waiting for visitors. Its worship, hospitality and boundaries should shape how a heritage visit unfolds.","body":[{"type":"paragraph","text":"A doorway can admit you to a historic building without admitting you to every activity taking place inside it. At a living sacred place, the congregation is not part of the display. Someone may be praying, preparing food, grieving or carrying out an ordinary responsibility. A worthwhile heritage visit begins by recognising those purposes as more important than completing a photographic itinerary."},{"type":"paragraph","text":"This does not require treating every unfamiliar practice as mysterious. It requires asking clear questions, accepting specific answers and leaving room for a visit to change. Permission to enter, permission to observe a ceremony and permission to publish an identifiable person’s image are separate matters."},{"type":"heading","level":2,"text":"Before crossing the threshold"},{"type":"paragraph","text":"Harvard’s Pluralism Project advises researchers visiting religious communities to prepare, communicate with hosts and take local guidance seriously. Its examples concern particular communities rather than a universal set of rules. That is a useful distinction for Pakistan: a visitor should not assume that instructions at one mosque, shrine, temple, church or gurdwara automatically apply at another."},{"type":"paragraph","text":"Contact the institution or a recognised caretaker where possible. Ask whether the intended time is suitable for an observational visit, whether an event limits access, and where a visitor can wait without obstructing others. Questions about clothing, footwear or head covering are best settled through that local conversation, not through a guessed rule based on the building’s appearance."},{"type":"paragraph","text":"Accessibility deserves the same practical approach. Ask about steps, seating and available routes without presuming that a visitor can use an entrance reserved for another purpose. If an arrangement cannot be confirmed, describe it as unconfirmed rather than offering a reassuring promise to someone who may depend on it."},{"type":"heading","level":2,"text":"During worship"},{"type":"paragraph","text":"There is a difference between being welcomed and being asked to participate. A visitor can listen attentively without performing a gesture they do not understand. If invited to join an activity, a quiet explanation of one’s uncertainty is usually more useful than imitating others for a photograph."},{"type":"paragraph","text":"Keep passages clear and avoid turning someone’s prayer into a foreground for architectural photography. A wide shot can still identify people. A camera set aside may make it possible to notice aspects of the building that are otherwise missed: how a room fills, where people pause, or which threshold marks a change in behaviour."},{"type":"heading","level":2,"text":"After the visit"},{"type":"paragraph","text":"ICCROM’s work on living religious heritage places religious use and community values within conservation discussion. The practical implication for an archive is that recording a place’s stonework is only one part of understanding it. Contemporary participants may explain meanings that cannot be recovered by measuring a wall."},{"type":"paragraph","text":"Those explanations need careful attribution. One caretaker’s account should not become an assertion that every worshipper believes the same thing. Distinguish a personal recollection, an institution’s published account and a historical claim supported by other evidence."},{"type":"paragraph","text":"If a photograph or interview is intended for publication, agree on that use explicitly. Record names and preferred descriptions accurately, and honour restrictions. The result may be a smaller collection of images or a shorter visit. It can also be a substantially better encounter: one that treats hospitality as a relationship rather than as unlimited access."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Visiting a sacred place that is still in use | Virsapur","description":"A living sacred place is not an empty monument waiting for visitors. Its worship, hospitality and boundaries should shape how a heritage visit unfolds.","primaryKeyword":"respectful sacred heritage visits","socialTitle":"Visiting a sacred place that is still in use","socialDescription":"A living sacred place is not an empty monument waiting for visitors. Its worship, hospitality and boundaries should shape how a heritage visit unfolds."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Research Guidelines","url":"https://pluralism.org/research-guidelines","publisher":"Harvard University Pluralism Project","accessDate":"2026-10-22"},{"title":"Conservation of Living Religious Heritage","url":"https://www.iccrom.org/publication/conservation-living-religious-heritage","publisher":"ICCROM","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original source-based review draft. Comparative examples are labelled and must not be transferred to linked Pakistani sites. No live access promises. Article-specific sources read; limited paraphrase with original analytical explanation. ","editorialReason":"Explain consent, worship and photography as considerations to verify locally, not universal rules.","sortOrder":203}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-shrine-mosque-and-khanqah-different-institutional-spaces','shrine-mosque-and-khanqah-different-institutional-spaces','review','{"id":"story-shrine-mosque-and-khanqah-different-institutional-spaces","type":"story","slug":"shrine-mosque-and-khanqah-different-institutional-spaces","title":"Shrine, mosque and khanqah: different institutional spaces","summary":"Mosque, shrine and khanqah describe different emphases within religious life. Their functions may overlap inside one precinct without making the terms interchangeable.","body":[{"type":"paragraph","text":"A religious precinct may contain a prayer hall, a revered burial, rooms associated with teaching and spaces for hospitality. Calling the entire place a mosque can conceal the tomb; calling everything a shrine can conceal congregational prayer. The terms are useful when they help us distinguish activities and histories, rather than when they force a complex institution into a single box."},{"type":"paragraph","text":"In broad usage, a mosque is a place of Muslim prayer. A shrine identifies a focus of reverence, often associated with a saint or a burial, but the word alone does not specify every building around it. A khanqah is associated with Sufi religious life and may involve assembly, teaching, residence or hospitality. The combination and institutional meaning vary by place and period."},{"type":"heading","level":2,"text":"A building with several kinds of room"},{"type":"paragraph","text":"The federal catalogue’s account of Thagas Khanqah in Ghanche describes a hall, an eastern entrance veranda and smaller meditation rooms on two sides. It also records nearby astanas associated with Mir Arif and Mir Ishaq. This is more informative than treating a photograph of its timberwork as a complete account of the institution."},{"type":"paragraph","text":"The recorded arrangement suggests useful questions for reading the site: which space accommodated gathering, which offered relative seclusion, and how did the adjacent sacred structures relate to the principal building? These are questions for investigation, not permission to assign a known ceremony to every room."},{"type":"paragraph","text":"A comparative Archnet account of Samarkand’s Registan describes an earlier khanqah serving alongside a madrasa. That example is outside Pakistan, but it illustrates why institutional relationships matter. Teaching, lodging and devotion can be linked without becoming identical activities. It would be misleading to infer the plan of Thagas from the Samarkand example."},{"type":"heading","level":2,"text":"Distinguish the precinct from its centre"},{"type":"paragraph","text":"At a saint’s shrine, the tomb may be the element that gives the larger place its name. The visible precinct, however, can include additions from different periods. A date associated with the saint’s life is not automatically the construction date of a courtyard wall, gateway or prayer space."},{"type":"paragraph","text":"This distinction matters when describing a complex such as the shrine of Bahauddin Zakariya in Multan. The subject of an architectural account might be the tomb structure; the subject of a devotional account might be the saint; the subject of a contemporary institutional account might be the people responsible for the precinct. A good article says which of these it is discussing."},{"type":"heading","level":2,"text":"Names should clarify, not settle belief"},{"type":"paragraph","text":"ICCROM’s discussion of living religious heritage is a reminder that conservation must engage with religious use as well as material fabric. For an archive, this means listening to how an institution names its own spaces while retaining the ability to explain historical changes and differing sources."},{"type":"paragraph","text":"A caption can be precise without becoming lengthy: identify the building, the larger complex and the activity actually documented. Avoid guessing from a dome, a courtyard or a group of visitors. Architectural forms travel between institutions, and the same structure can acquire new uses."},{"type":"paragraph","text":"The result is a richer reading of sacred heritage. A mosque, a shrine and a khanqah may be neighbours or parts of one compound. Their relationship is often the story worth telling, rather than a problem to remove through a single label."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["punjab-multan","gilgit-baltistan-ghanche"],"provinceRegionIds":["punjab","gilgit-baltistan"],"relatedHeritageIds":["major-doam-10273","major-doam-7966"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Shrine, mosque and khanqah: different institutional spaces | Virsapur","description":"Mosque, shrine and khanqah describe different emphases within religious life. Their functions may overlap inside one precinct without making the terms interchangeable.","primaryKeyword":"shrine mosque khanqah difference","socialTitle":"Shrine, mosque and khanqah: different institutional spaces","socialDescription":"Mosque, shrine and khanqah describe different emphases within religious life. Their functions may overlap inside one precinct without making the terms interchangeable."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Khanqah-e-Moallah Thagas","url":"https://doam.gov.pk/public/sites/7966","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Shir Dar Madrasa","url":"https://www.archnet.org/sites/2146","publisher":"Archnet","accessDate":"2026-10-22"},{"title":"Conservation of Living Religious Heritage","url":"https://www.iccrom.org/publication/conservation-living-religious-heritage","publisher":"ICCROM","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original source-based review draft. Comparative examples are labelled and must not be transferred to linked Pakistani sites. No live access promises. Article-specific sources read; limited paraphrase with original analytical explanation. ","editorialReason":"Clarify useful terms while recognising regional variation and overlapping precincts.","sortOrder":204}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-gurdwara-as-more-than-a-landmark','the-gurdwara-as-more-than-a-landmark','review','{"id":"story-the-gurdwara-as-more-than-a-landmark","type":"story","slug":"the-gurdwara-as-more-than-a-landmark","title":"The gurdwara as more than a landmark","summary":"Understanding a gurdwara means looking beyond its silhouette to the Guru Granth Sahib, the congregation and the everyday work that sustains a religious institution.","body":[{"type":"paragraph","text":"The outside of a gurdwara may be the first thing a visitor recognises: an entrance, a dome or a prominent flag. Yet its religious significance cannot be read from a skyline alone. A description that stops at architectural style can miss the congregation, scripture and service through which the place continues to matter."},{"type":"paragraph","text":"The Pluralism Project’s account places the Guru Granth Sahib at the centre of gurdwara life and describes the institution as a setting for worship and community activity. That is a better starting point than treating every gurdwara as an isolated memorial to a past event. A historic association can be important without exhausting the institution’s present purpose."},{"type":"heading","level":2,"text":"Reading a complex through use"},{"type":"paragraph","text":"Look at the relationship between spaces rather than assuming that the largest room is the whole institution. A route towards the prayer hall, an area for preparing food and a room used for teaching answer different needs. Their exact arrangement must be established at the particular gurdwara; a diagram from another country is not a universal floor plan."},{"type":"paragraph","text":"For a heritage reader, this changes the questions asked of a building. Where does a visitor first receive guidance? Which thresholds connect public hospitality and congregational activity? How are storage, cleaning and circulation accommodated? These ordinary matters may explain an extension or a change in use more effectively than a style label."},{"type":"paragraph","text":"An account of Panja Sahib should therefore distinguish its site-specific history from general information about gurdwaras. The name of the institution and a familiar photograph do not establish current opening arrangements, an event timetable or access to every part of the compound."},{"type":"heading","level":2,"text":"Service has a spatial history"},{"type":"paragraph","text":"The SGPC’s description of the langar at Harmandir Sahib explains its hospitality across religious and social distinctions. This is evidence from a practising Sikh institution, not simply an outsider’s interpretation of shared food. Its operating details belong to that site and should not be turned into promises about every gurdwara."},{"type":"paragraph","text":"The architectural implication is substantial. Food preparation, serving, washing and the movement of people require space and sustained work. An archive that photographs only a decorated facade may omit the areas where much of that work takes place. Those spaces should be documented with permission, not treated as accessible merely because they are less monumental."},{"type":"heading","level":2,"text":"Festivals and ordinary days"},{"type":"paragraph","text":"The SGPC’s account of gurpurbs describes commemorations involving scripture, devotional singing, prayer and langar. Such occasions make the relationship between religious calendar and institutional space especially visible. They also remind visitors that a gurdwara is not experienced in exactly the same way on every day."},{"type":"paragraph","text":"A crowded commemorative gathering and a quieter weekday can reveal different aspects of the same place. Neither is more authentic simply because it produces a more dramatic image. The appropriate account identifies the occasion and avoids presenting one observed arrangement as permanent."},{"type":"paragraph","text":"To understand a gurdwara as heritage is therefore to hold architecture and continuing practice together. Materials, repairs and patronage remain important. So do the people who read, listen, teach, cook and care for the building. The landmark becomes more intelligible when the institution is allowed to remain alive within the description."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["punjab-attock"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-7658"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"The gurdwara as more than a landmark | Virsapur","description":"Understanding a gurdwara means looking beyond its silhouette to the Guru Granth Sahib, the congregation and the everyday work that sustains a religious institution.","primaryKeyword":"gurdwara sacred space","socialTitle":"The gurdwara as more than a landmark","socialDescription":"Understanding a gurdwara means looking beyond its silhouette to the Guru Granth Sahib, the congregation and the everyday work that sustains a religious institution."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"The Gurdwara","url":"https://pluralism.org/the-gurdwara","publisher":"Harvard University Pluralism Project","accessDate":"2026-10-22"},{"title":"Around Sri Harmandir Sahib","url":"https://new.sgpc.net/around-harmandir-sahib/","publisher":"Shiromani Gurdwara Parbandhak Committee","accessDate":"2026-10-22"},{"title":"Gurpurbs","url":"https://new.sgpc.net/gurpurbs/","publisher":"Shiromani Gurdwara Parbandhak Committee","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original source-based review draft. Comparative examples are labelled and must not be transferred to linked Pakistani sites. No live access promises. Article-specific sources read; limited paraphrase with original analytical explanation. ","editorialReason":"Introduce worship, community space and institutional history through authoritative Sikh perspectives.","sortOrder":205}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-langar-and-the-spaces-of-shared-food','langar-and-the-spaces-of-shared-food','review','{"id":"story-langar-and-the-spaces-of-shared-food","type":"story","slug":"langar-and-the-spaces-of-shared-food","title":"Langar and the spaces of shared food","summary":"Langar brings religious service, shared eating and practical labour into one setting. Its kitchens and dining spaces deserve attention alongside monumental architecture.","body":[{"type":"paragraph","text":"A dining space can be as important to understanding a religious institution as its most photographed hall. Langar makes that especially clear. Food is not merely an extra amenity for people who have come to admire a building; the preparation and sharing of a meal belong to the institution’s religious and social life."},{"type":"paragraph","text":"A Sikh institutional account in the SGPC’s Gurdwara Gazette connects langar with equality and sewa, or service. The point is not simply that a large quantity of food is available. It is that preparing, offering and eating it express a relationship between people. That meaning should remain visible when the subject is translated into architectural description."},{"type":"heading","level":2,"text":"Follow the work, not only the meal"},{"type":"paragraph","text":"The Pluralism Project’s account of a langar in Fremont follows a family involved in preparing a meal for hundreds of people. Its value lies in the particular work it records. Shopping, preparation and coordination are part of the event, even though a visitor may see only the finished food."},{"type":"paragraph","text":"That field account concerns one American Sikh community. It should not supply invented details about the staffing or menu at Panja Sahib. It does, however, suggest an effective way to investigate a Pakistani site: ask who organises the work, how responsibilities are shared and which parts of the process may be observed or recorded."},{"type":"paragraph","text":"A dining room on a plan is only one link in that chain. Ingredients need somewhere to arrive and be kept. Preparation requires suitable working space. Used utensils must move away from served food. These are practical questions for documenting a particular kitchen, not a claim that every langar has an identical arrangement."},{"type":"heading","level":2,"text":"Equality and the visible room"},{"type":"paragraph","text":"Shared seating can communicate an institutional ideal, but a photograph cannot fully explain it. A useful caption might identify the occasion and the setting, then direct the reader towards the community’s own account. It should not infer the identity, caste or personal circumstances of people shown eating."},{"type":"paragraph","text":"The Pluralism Project’s Westborough field record places langar alongside other facilities and describes volunteer organisation. This offers another concrete example of a gurdwara functioning through recurring community commitments. The building is sustained not only by major donations or ceremonial moments but also by tasks that have to be done again."},{"type":"heading","level":2,"text":"A heritage record that includes labour"},{"type":"paragraph","text":"Documenting langar well means giving those tasks an appropriate place in the archive. With consent, a record could include the layout of a serving area, the names of people explaining their responsibilities and the date of the observed gathering. A historic photograph might then be compared with a later arrangement without claiming that one is the timeless original."},{"type":"paragraph","text":"Visitors should not obstruct service to obtain such a record. Nor should a person’s willingness to offer hospitality be treated as automatic agreement to an interview or publication. A simple explanation of the intended use makes participation more meaningful."},{"type":"paragraph","text":"Langar expands what counts as a heritage subject. It directs attention from exceptional objects to shared infrastructure and recurring acts of care. The kitchen, the dining space and the people maintaining them form a story that a facade alone cannot tell."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["punjab-attock"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-7658"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Langar and the spaces of shared food | Virsapur","description":"Langar brings religious service, shared eating and practical labour into one setting. Its kitchens and dining spaces deserve attention alongside monumental architecture.","primaryKeyword":"langar heritage","socialTitle":"Langar and the spaces of shared food","socialDescription":"Langar brings religious service, shared eating and practical labour into one setting. Its kitchens and dining spaces deserve attention alongside monumental architecture."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Langar: The Communal Meal","url":"https://pluralism.org/langar-the-communal-meal","publisher":"Harvard University Pluralism Project","accessDate":"2026-10-22"},{"title":"Westborough Gurdwara — New England Sikh Study Circle","url":"https://pluralism.org/westborough-gurdwara-new-england-sikh-study-circle-inc","publisher":"Harvard University Pluralism Project","accessDate":"2026-10-22"},{"title":"Gurdwara Gazette, September 2018","url":"https://sgpc.net/gazette/2018/September/September-English.pdf","publisher":"Shiromani Gurdwara Parbandhak Committee","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original source-based review draft. Comparative examples are labelled and must not be transferred to linked Pakistani sites. No live access promises. Article-specific sources read; limited paraphrase with original analytical explanation. ","editorialReason":"Study the spatial and community dimension with practising-community sources, not an invented universal history.","sortOrder":206}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-jain-heritage-in-pakistan-beyond-one-temple','jain-heritage-in-pakistan-beyond-one-temple','review','{"id":"story-jain-heritage-in-pakistan-beyond-one-temple","type":"story","slug":"jain-heritage-in-pakistan-beyond-one-temple","title":"Jain heritage in Pakistan beyond one temple","summary":"Pakistan’s Jain heritage includes temples, commemorative structures and former community institutions. Recognising those differences prevents a diverse history from being reduced to one monument.","body":[{"type":"paragraph","text":"Gori Temple is an important point of entry into Pakistan’s Jain heritage, but it cannot stand for the entire subject. A temple, a memorial to a religious teacher and a former school preserve different kinds of history. Bringing them into one conversation should reveal their relationships without flattening their distinctions."},{"type":"paragraph","text":"The SOAS exploratory survey was designed to document a much wider field than famous temple remains. Its research programme included built and funerary heritage, manuscripts, libraries and community institutions. That breadth matters because a religious community’s presence is not recorded only in the places where a visitor expects to find monumental worship."},{"type":"heading","level":2,"text":"Beyond the temple category"},{"type":"paragraph","text":"A published field report from the project distinguishes several forms, including temples, dadabaris, sthanakas and samadhis, alongside schools and other institutions. It also notes problems of identification. A building described casually as Hindu may require closer investigation before its Jain affiliation is recognised."},{"type":"paragraph","text":"This is not an invitation to relabel structures from appearance alone. Rather, it shows why inscriptions, documentary records, community histories and architectural evidence should be considered together. An unfamiliar image or a changed use can complicate recognition. A modern sign may preserve a useful name without settling every question about the building’s earlier function."},{"type":"paragraph","text":"At Gori, SOAS field documentation records the organisation of halls and surrounding cells, while the federal catalogue describes the mandapas and materials. These provide a more concrete starting point than a claim that all Jain temples share one appearance. The two accounts are evidence about this complex, not a template to impose on every site."},{"type":"heading","level":2,"text":"Commemoration is a different question"},{"type":"paragraph","text":"The archive also links readers to the Atmaramji Shrine record. Its inclusion alongside Gori should prompt a distinction between a temple complex and a place associated with religious commemoration. A full account requires secure identification of the person remembered and the institution’s history; similarity between names is not sufficient."},{"type":"paragraph","text":"That caution is particularly important in searchable archives. The same or similar personal name can belong to people of different periods and traditions. An attractive biography found online cannot be attached to a monument merely because the spellings match. Until the connection is demonstrated, the narrower description is the more informative one."},{"type":"heading","level":2,"text":"Institutions after displacement"},{"type":"paragraph","text":"The SOAS project situates its work in a history affected by Partition and migration. For a heritage reader, this raises questions about how records and memories travel when communities move. A building may remain in Pakistan while relevant photographs, family papers or institutional recollections are held elsewhere."},{"type":"paragraph","text":"Its later history also deserves attention. A change of use, a repair, or the work of a present caretaker can be documented without erasing the earlier affiliation. Equally, recognising that affiliation does not require inventing an uninterrupted ritual life."},{"type":"paragraph","text":"A useful Jain heritage archive would therefore connect places with kinds of evidence: inscriptions with readings, photographs with dates, and institutional names with corroborating records. Gori remains compelling, but the larger story becomes visible only when the less conspicuous structures and records are allowed to matter too."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["sindh-tharparkar","punjab-gujranwala"],"provinceRegionIds":["sindh","punjab"],"relatedHeritageIds":["major-doam-5499","major-doam-10109"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Jain heritage in Pakistan beyond one temple | Virsapur","description":"Pakistan’s Jain heritage includes temples, commemorative structures and former community institutions. Recognising those differences prevents a diverse history from being reduced to one monument.","primaryKeyword":"Jain heritage Pakistan","socialTitle":"Jain heritage in Pakistan beyond one temple","socialDescription":"Pakistan’s Jain heritage includes temples, commemorative structures and former community institutions. Recognising those differences prevents a diverse history from being reduced to one monument."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Exploratory Survey of Jaina Heritage in Pakistan","url":"https://www.soas.ac.uk/research/exploratory-survey-jaina-heritage-pakistan","publisher":"SOAS University of London","accessDate":"2026-10-22"},{"title":"Jaina Studies Newsletter, Issue 13: Survey of Jaina Heritage in Pakistan","url":"https://www.soas.ac.uk/sites/default/files/2022-11/Centre%20of%20Jaina%20Studies%20Issue%2013%20-%20March%202019.pdf","publisher":"SOAS Centre of Jaina Studies","accessDate":"2026-10-22"},{"title":"Gori Temple field documentation","url":"https://digital.soas.ac.uk/content/JH/P0/00/01/06/00001/JHP0000106_00001.pdf","publisher":"SOAS Digital Collections","accessDate":"2026-10-22"},{"title":"Gori Temple","url":"https://doam.gov.pk/public/sites/5499","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original source-based review draft. Comparative examples are labelled and must not be transferred to linked Pakistani sites. No live access promises. Article-specific sources read; limited paraphrase with original analytical explanation. Atmaramji person/site identity needs specialist review before a detailed biography is commissioned; no unsupported biography asserted.","editorialReason":"Distinguish temple and commemorative traditions without merging Jain and Hindu identities.","sortOrder":207}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-buddhist-pilgrimage-and-the-material-presence-of-relics','buddhist-pilgrimage-and-the-material-presence-of-relics','review','{"id":"story-buddhist-pilgrimage-and-the-material-presence-of-relics","type":"story","slug":"buddhist-pilgrimage-and-the-material-presence-of-relics","title":"Buddhist pilgrimage and the material presence of relics","summary":"Reliquaries show how small objects could give monumental Buddhist spaces religious significance. Their inscriptions and collection histories must be read as carefully as their decoration.","body":[{"type":"paragraph","text":"A monumental stupa and a small reliquary operate at very different scales, yet they can belong to the same sacred relationship. The building gives a deposit a place in the landscape. The deposit helps explain why that place mattered to worshippers. Looking at masonry alone can miss this connection; looking at a casket in isolation can lose the setting that gave it meaning."},{"type":"paragraph","text":"Relics are not simply another category of archaeological treasure. Their religious significance concerns an association with an honoured person or sacred presence. Archaeology can document a container, an inscription and the circumstances of a discovery without being able to verify every devotional identification attached to the contents."},{"type":"heading","level":2,"text":"Inscriptions connect objects and people"},{"type":"paragraph","text":"Kurt Behrendt’s Metropolitan Museum account of Gandhara discusses reliquaries within the relationship between stupas and monastic complexes. The Indravarman reliquary provides an example of an inscription connecting dedication with named people and religious merit. Such evidence brings donors into view rather than leaving the institution as an anonymous group of ruined walls."},{"type":"paragraph","text":"That does not mean every deposit has an equally informative inscription. An uninscribed casket may preserve evidence of materials and manufacture while leaving its donor unknown. The absence of a name is a limit of the surviving record, not proof that the object lacked an important religious role."},{"type":"heading","level":2,"text":"An original and a replica are different witnesses"},{"type":"paragraph","text":"The British Museum’s record for its Kanishka casket is especially instructive: the museum identifies the object as a replica, with the original in Peshawar Museum. A photograph circulated without that information can easily create a false impression about where the ancient object is held."},{"type":"paragraph","text":"The replica may be useful for studying or displaying the form. It is not evidence that the original material is in London. The catalogue also discusses difficulties in reading the inscription. A confident date copied from an old label should therefore be checked against the present scholarly record rather than repeated as settled fact."},{"type":"heading","level":2,"text":"What a find record can preserve"},{"type":"paragraph","text":"A separate British Museum entry for a rock-crystal reliquary from Sonala Pind records its relationship to a stupa discovery and to other containers. It also preserves uncertainty about the identification of material once associated with the deposit. This is a reminder that an excavation or collection history can be informative without being complete."},{"type":"paragraph","text":"For visitors to Buddhist sites in Pakistan, these objects suggest questions to bring to a site museum. Is a displayed item original, a cast or a modern reconstruction? Is its findspot known? Does the label distinguish an archaeological attribution from a religious tradition? Those questions deepen appreciation rather than diminishing the object’s sacred importance."},{"type":"heading","level":2,"text":"Pilgrimage cannot be reconstructed from stone alone"},{"type":"paragraph","text":"Sites such as Takht-i-Bahi and Bhamala belong within a wider exploration of Buddhist sacred space. Their architectural remains should not, however, be used to invent a single unchanged pilgrimage practice across centuries."},{"type":"paragraph","text":"A more defensible account connects specific deposits, inscriptions and excavated contexts where the evidence permits. It acknowledges living Buddhist interpretations without pretending that present testimony automatically supplies every missing ancient detail. The small reliquary and the monumental landscape then illuminate one another, while each retains its own history."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["khyber-pakhtunkhwa-mardan","khyber-pakhtunkhwa-haripur"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["unesco-140","major-doam-823"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Buddhist pilgrimage and the material presence of relics | Virsapur","description":"Reliquaries show how small objects could give monumental Buddhist spaces religious significance. Their inscriptions and collection histories must be read as carefully as their decoration.","primaryKeyword":"Buddhist relic veneration Gandhara","socialTitle":"Buddhist pilgrimage and the material presence of relics","socialDescription":"Reliquaries show how small objects could give monumental Buddhist spaces religious significance. Their inscriptions and collection histories must be read as carefully as their decoration."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Gandhara","url":"https://www.metmuseum.org/it/essays/gandhara","publisher":"The Metropolitan Museum of Art; Kurt Behrendt","accessDate":"2026-10-22"},{"title":"Replica of the Kanishka reliquary, 1880.270","url":"https://www.britishmuseum.org/collection/object/A_1880-270","publisher":"The British Museum","accessDate":"2026-10-22"},{"title":"Reliquary from Sonala Pind, 1887.0717.35","url":"https://www.britishmuseum.org/collection/object/A_1887-0717-35","publisher":"The British Museum","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original source-based review draft. Comparative examples are labelled and must not be transferred to linked Pakistani sites. No live access promises. Article-specific sources read; limited paraphrase with original analytical explanation. ","editorialReason":"Explain how documented relic deposits relate to sacred space rather than speculate on living ritual continuity.","sortOrder":208}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-what-is-a-stupa-for','what-is-a-stupa-for','review','{"id":"story-what-is-a-stupa-for","type":"story","slug":"what-is-a-stupa-for","title":"What is a stupa for?","summary":"A stupa can be a reliquary, a focus of devotion or a commemorative offering. Its purpose cannot be inferred from size alone, and not every example contains a known deposit.","body":[{"type":"paragraph","text":"A stupa is often first encountered as a distinctive shape: a raised base, a rounded or tiered mass and an upper element that draws the eye upwards. But asking what it was for produces a richer answer than identifying its profile. Stupas can organise devotion around relics, commemorate a sacred association and serve as offerings. Their scale ranges from major monuments to small objects."},{"type":"paragraph","text":"These roles should not be collapsed into the assumption that every stupa contains the bodily remains of the Buddha. The contents and dedication of a particular example require evidence. Some are known through excavated deposits or inscriptions; others survive without that information."},{"type":"heading","level":2,"text":"A monument does not need an interior hall"},{"type":"paragraph","text":"For a visitor accustomed to entering religious buildings, a stupa changes the relationship between architecture and worship. Its significance may be concentrated within a solid structure, while devotional activity takes place around it. The outside is therefore not merely an envelope hiding the building’s real purpose."},{"type":"paragraph","text":"The Metropolitan Museum’s Tree and Serpent exhibition guide discusses relics and the sacred importance of early Buddhist monuments alongside narrative imagery and patronage. This helps explain why a concealed deposit and a highly visible exterior are not contradictory. Presence can be understood religiously even when the material associated with it is not available for inspection."},{"type":"paragraph","text":"A visitor’s attention can accordingly shift to the surrounding space: the approach, adjacent offerings and the relationship between the principal monument and smaller structures. That is a way of asking how the setting worked, rather than searching only for a doorway."},{"type":"heading","level":2,"text":"Small stupas are not failed large ones"},{"type":"paragraph","text":"The Metropolitan Museum’s small Votive Stupa with Four Buddhas, attributed to Bihar in the tenth or eleventh century, is a useful comparison. Its scale is appropriate to a votive object. It should not be treated as an incomplete architectural model simply because it can be held or displayed in a case."},{"type":"paragraph","text":"This example is outside Pakistan and belongs to its own period. Its relevance is conceptual: monumentality is not the only measure of religious significance. A small offering can express devotion without reproducing the function or construction of a large excavated stupa."},{"type":"heading","level":2,"text":"Form and container can coincide"},{"type":"paragraph","text":"The British Museum records a tiny gold reliquary assembled in the form of a stupa, with separate base, dome and upper element. Here the shape and the function of holding something sacred are brought together in a portable object."},{"type":"paragraph","text":"Its collection history also limits what can be said. Acquisition through a market is not an excavated findspot. The object can support discussion of material and form without licensing a claim about the exact monastery or ritual in which it was used."},{"type":"paragraph","text":"For Pakistan’s heritage reader, Butkara I and Thul Mir Rukan offer starting points for exploring very different surviving monumental settings. Their histories must be established separately; one should not transfer a reliquary’s contents or a votive object’s date onto either site."},{"type":"paragraph","text":"The most useful answer to the opening question is therefore plural. A stupa gives form to a sacred relationship, but the particular relationship becomes clearer through inscriptions, objects, excavated arrangements and religious interpretation considered together."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["khyber-pakhtunkhwa-swat","sindh-shaheed-benazir-abad"],"provinceRegionIds":["khyber-pakhtunkhwa","sindh"],"relatedHeritageIds":["major-doam-3304","major-doam-5094"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"What is a stupa for? | Virsapur","description":"A stupa can be a reliquary, a focus of devotion or a commemorative offering. Its purpose cannot be inferred from size alone, and not every example contains a known deposit.","primaryKeyword":"stupa purpose Gandhara","socialTitle":"What is a stupa for?","socialDescription":"A stupa can be a reliquary, a focus of devotion or a commemorative offering. Its purpose cannot be inferred from size alone, and not every example contains a known deposit."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Votive Stupa with Four Buddhas, 1987.142.342","url":"https://www.metmuseum.org/art/collection/search/38411","publisher":"The Metropolitan Museum of Art","accessDate":"2026-10-22"},{"title":"Gold stupa-shaped reliquary, 2004.0331.1","url":"https://www.britishmuseum.org/collection/object/A_2004-0331-1","publisher":"The British Museum","accessDate":"2026-10-22"},{"title":"Tree and Serpent visiting guide","url":"https://www.metmuseum.org/ko/exhibitions/tree-and-serpent/visiting-guide","publisher":"The Metropolitan Museum of Art; John Guy","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original source-based review draft. Comparative examples are labelled and must not be transferred to linked Pakistani sites. No live access promises. Article-specific sources read; limited paraphrase with original analytical explanation. ","editorialReason":"Introduce ritual and commemorative functions separately from the technical construction article.","sortOrder":209}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-circumambulation-path-as-a-designed-experience','the-circumambulation-path-as-a-designed-experience','review','{"id":"story-the-circumambulation-path-as-a-designed-experience","type":"story","slug":"the-circumambulation-path-as-a-designed-experience","title":"The circumambulation path as a designed experience","summary":"Walking around a sacred focus makes architecture unfold through time. Excavated paths and thresholds can reveal how a Buddhist setting organised movement without preserving every ancient ritual.","body":[{"type":"paragraph","text":"An architectural plan is still; a person moving through it is not. Circumambulation, or movement around a sacred focus, makes that difference especially important. A stupa is encountered from changing positions, with one view giving way to another. The route is not simply leftover space between buildings. It can be integral to how a sacred setting is experienced."},{"type":"paragraph","text":"The Metropolitan Museum’s introduction to Buddhist art connects stupas with the devotional practice of walking around them. The general relationship is useful, but it does not provide a complete itinerary for every excavated monastery. A particular path still needs to be read through the site’s own evidence."},{"type":"heading","level":2,"text":"Start with the route that survives"},{"type":"paragraph","text":"On a plan, identify the principal monument, entrances, steps and any continuous space around it. Then ask where a route narrows, where a person changes level and whether neighbouring structures interrupt an apparently obvious circuit. These are architectural observations that can be checked before interpreting their religious meaning."},{"type":"paragraph","text":"An open strip beside a stupa is not automatically proof that every visitor followed it in the same way. A surviving plan may combine features from different building phases. A later addition could have changed an earlier route, while missing paving can make a former connection difficult to recognise."},{"type":"paragraph","text":"At Takht-i-Bahi or within Taxila’s multiple archaeological sites, this encourages a slower reading. Begin with the displayed plan and the remains it actually identifies. Do not use the fame of the location to fill in an undocumented procession, chant or sequence of gestures."},{"type":"heading","level":2,"text":"A comparative example, not a universal template"},{"type":"paragraph","text":"Karen Shelby’s discussion of Sanchi explains circumambulation as part of the relationship between a stupa and Buddhist practice. The gateways, railings and routes there make movement especially legible. Sanchi is in India, and its particular arrangement should not be copied mentally onto every Gandharan complex."},{"type":"paragraph","text":"Another comparison comes from Bamiyan, where spaces around the monumental Buddha figures permitted movement around parts of the images. This shows that circumambulation need not be discussed only in relation to a freestanding domed stupa. The sacred focus and its architectural setting can take different forms."},{"type":"paragraph","text":"The comparisons are useful because they sharpen questions rather than answer them in advance. Where could people move? What remained visible as they did so? How did the route bring them near to, or keep them apart from, the sacred focus?"},{"type":"heading","level":2,"text":"Space becomes a sequence"},{"type":"paragraph","text":"A photograph taken from the entrance can make a site look like a single composition. Walking reveals successive relationships: a wall conceals a view, a turn opens another, a stair changes the apparent scale of a monument. Recording that sequence can explain the architecture more effectively than selecting only the most symmetrical image."},{"type":"paragraph","text":"A responsible modern visit must still follow current conservation routes. An ancient path identified by archaeologists is not an invitation to step onto fragile masonry or cross a barrier."},{"type":"paragraph","text":"Circumambulation helps us recognise a broader architectural truth: some places were made to be understood through movement. Excavation can recover parts of that design. Religious texts, inscriptions and carefully situated comparisons can enrich it, while the gestures of individual ancient visitors often remain beyond reconstruction."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["khyber-pakhtunkhwa-mardan","khyber-pakhtunkhwa-haripur","punjab-rawalpindi"],"provinceRegionIds":["khyber-pakhtunkhwa","punjab"],"relatedHeritageIds":["unesco-140","unesco-139"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"The circumambulation path as a designed experience | Virsapur","description":"Walking around a sacred focus makes architecture unfold through time. Excavated paths and thresholds can reveal how a Buddhist setting organised movement without preserving every ancient ritual.","primaryKeyword":"Buddhist circumambulation architecture","socialTitle":"The circumambulation path as a designed experience","socialDescription":"Walking around a sacred focus makes architecture unfold through time. Excavated paths and thresholds can reveal how a Buddhist setting organised movement without preserving every ancient ritual."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Buddhism and Buddhist Art","url":"https://www.metmuseum.org/ko/essays/buddhism-and-buddhist-art","publisher":"The Metropolitan Museum of Art","accessDate":"2026-10-22"},{"title":"The stupa, an introduction","url":"https://smarthistory.org/the-stupa-sanchi/","publisher":"Smarthistory; Dr Karen Shelby","accessDate":"2026-10-22"},{"title":"Bamiyan Buddhas","url":"https://smarthistory.org/bamiyan-buddhas/","publisher":"Smarthistory","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original source-based review draft. Comparative examples are labelled and must not be transferred to linked Pakistani sites. No live access promises. Article-specific sources read; limited paraphrase with original analytical explanation. ","editorialReason":"Read circulation through excavated plans without claiming one unchanged practice everywhere.","sortOrder":210}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-sacred-water-at-katas-traditions-and-material-settings','sacred-water-at-katas-traditions-and-material-settings','review','{"id":"story-sacred-water-at-katas-traditions-and-material-settings","type":"story","slug":"sacred-water-at-katas-traditions-and-material-settings","title":"Sacred water at Katas: traditions and material settings","summary":"At Katas, sacred tradition and a physical water system meet. Understanding the pond requires attention to both, without treating either as a substitute for the other.","body":[{"type":"paragraph","text":"The pond at Katas Raj is not simply a reflective foreground for temple photographs. It belongs to the sacred significance of the complex. The federal heritage catalogue records a Hindu tradition connecting it with Shiva’s tears. Describing that association as a religious tradition respects its meaning without presenting it as a geological explanation of how water reaches the pool."},{"type":"paragraph","text":"The distinction is important because two different kinds of knowledge meet here. Devotees can explain why the water matters within worship and memory. Hydrological investigation can examine supply, groundwater levels and changes over time. Neither enquiry makes the other unnecessary."},{"type":"heading","level":2,"text":"A complex organised around water"},{"type":"paragraph","text":"The catalogue places the sacred pool within a larger group of temples, other structures and archaeological remains. That is a useful corrective to the idea that Katas is one building with one construction date. A visitor encounters a layered setting in which buildings and water have related histories."},{"type":"paragraph","text":"The pool also changes how the complex is seen. Its edge creates a boundary, an approach and a place from which several structures can be viewed together. These spatial relationships deserve documentation even where the precise chronology of a particular wall or flight of steps has not been established."},{"type":"paragraph","text":"A careful architectural record would distinguish the pool’s retaining structures, access points and surrounding buildings. Dating one component would not automatically date the others. Nor would a modern photograph showing water establish that its level or source had remained constant."},{"type":"heading","level":2,"text":"What testimony can tell us"},{"type":"paragraph","text":"Hifsa’s PIDE case study, completed in 2020, records local recollections of a formerly fuller pond and accounts from caretakers about artificial replenishment during the research period. These are significant observations about people’s experience of change. They are not a measurement of the present water level or a complete scientific allocation of responsibility for depletion."},{"type":"paragraph","text":"That distinction allows the testimony to remain useful. A remembered swimming place, a caretaker’s explanation of a pump and a measured groundwater record answer different questions. Combining them carefully can reveal how environmental change affects both everyday associations and sacred use."},{"type":"paragraph","text":"The thesis also contains broad judgements and historical claims that require separate checking. Its most valuable contribution here is the dated field testimony, not permission to repeat every conclusion as settled fact."},{"type":"heading","level":2,"text":"Conservation beyond the photograph"},{"type":"paragraph","text":"The ETPB identifies Katas Raj among the mandirs within its shrines work. For an institution responsible for such a setting, water is not merely part of landscaping. Questions about the pool affect the experience of the sacred place as well as its visual appearance."},{"type":"paragraph","text":"A conservation account should therefore explain what is being monitored, the period covered by the evidence and how worshippers are involved. A full pool on one day is not proof of long-term recovery; a low level in an old photograph is not a current visitor advisory."},{"type":"paragraph","text":"Katas rewards a way of looking that holds meaning and material conditions together. The tradition explains why the pond cannot be replaced in the story by any attractive body of water. Investigation of its physical system explains what must be understood if that meaningful place is to endure."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Punjab","Sacred Heritage"],"province":"Punjab","district":"Chakwal","relatedDistrictIds":["punjab-chakwal"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6750"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Sacred water at Katas: traditions and material settings | Virsapur","description":"At Katas, sacred tradition and a physical water system meet. Understanding the pond requires attention to both, without treating either as a substitute for the other.","primaryKeyword":"Katas sacred water","socialTitle":"Sacred water at Katas: traditions and material settings","socialDescription":"At Katas, sacred tradition and a physical water system meet. Understanding the pond requires attention to both, without treating either as a substitute for the other."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Katas Raj Temples","url":"https://doam.gov.pk/public/sites/6750","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Issues and Challenges in Marketing of Heritage Sites: A Case Study of Katas Raj","url":"https://file-thesis.pide.org.pk/pdf/mphil-development-studies-2017-hifsa--issues-and-challenges-in-marketing-of-heritage-sites-a-case-study-of-katas-raj.pdf","publisher":"Pakistan Institute of Development Economics; Hifsa, 2020","accessDate":"2026-10-22"},{"title":"Shrines Branch","url":"https://etpb.gov.pk/shrines/shrines-branch/","publisher":"Evacuee Trust Property Board","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review draft; traditions explicitly attributed, dated testimony not represented as current conditions. No invented interview or ritual participation. PIDE field testimony consulted at pp.59–60; broad thesis causal/religious judgements not adopted. No quantitative groundwater claim.","editorialReason":"Distinguish community narratives, physical water systems and present conservation questions.","sortOrder":211}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-hinglaj-pilgrimage-listening-before-describing','hinglaj-pilgrimage-listening-before-describing','review','{"id":"story-hinglaj-pilgrimage-listening-before-describing","type":"story","slug":"hinglaj-pilgrimage-listening-before-describing","title":"Hinglaj pilgrimage: listening before describing","summary":"Hinglaj is a pilgrimage landscape, not just a destination pin. Its changing journeys and diverse accounts make listening an essential part of describing it.","body":[{"type":"paragraph","text":"A map can locate Hinglaj in Balochistan, but it cannot by itself explain the pilgrimage. For a pilgrim, the shrine may be connected with an inherited story, a family obligation, a journey made with others or an experience of the goddess. A description that treats the trip as a scenic approach to a remarkable cave leaves much of the subject outside the frame."},{"type":"paragraph","text":"Listening matters because there is not necessarily one account shared in precisely the same form by every participant. Differences in language, community history and the circumstances of travel can shape what is remembered and emphasised."},{"type":"heading","level":2,"text":"The journey has a history"},{"type":"paragraph","text":"Jürgen Schaflechner’s research places changes in access at the centre of its account. His book describes the significance of the Makran Coastal Highway for a pilgrimage previously associated with a demanding desert journey. It also distinguishes the shrine’s longer history from the relatively recent development of its large annual festival."},{"type":"paragraph","text":"These points challenge the phrase “unchanged ancient tradition.” Continuity of devotion does not mean that transport, organisation or the scale of gathering has remained fixed. A bus journey and a remembered journey on foot can belong to the same sacred geography without being the same experience."},{"type":"paragraph","text":"The book’s chapter summaries also identify resting places and changes to the physical shrine as part of its investigation. Only those published summaries have been used here; this article does not reconstruct a complete ritual sequence from an inaccessible chapter."},{"type":"heading","level":2,"text":"Ask about a particular journey"},{"type":"paragraph","text":"A useful conversation might begin with when someone first travelled to Hinglaj, who accompanied them and which stages they remember most clearly. Those questions invite a situated account. Asking someone to explain “what all Hindus believe” would instead place an unreasonable burden on one speaker."},{"type":"paragraph","text":"The resulting record should retain the circumstances of the conversation. An account given by a person recalling childhood is different from instructions issued by organisers for a particular year. Both may matter, but they should not be merged into a single timeless itinerary."},{"type":"paragraph","text":"A named resting place can be recorded in the speaker’s preferred language alongside a transliteration. If two people identify it differently, the archive can preserve that difference rather than silently choosing the version that looks tidiest on a map."},{"type":"heading","level":2,"text":"Sacred narrative and physical evidence"},{"type":"paragraph","text":"A devotional account can explain why a rock, spring or passage matters. It does not need to be converted into archaeological proof to deserve serious attention. Conversely, the geological character of a feature does not exhaust its religious meaning."},{"type":"paragraph","text":"UNESCO’s ethical principles place communities at the centre of safeguarding and require meaningful, informed consent. Applied here, that means agreeing on how an interview, image or recorded explanation will be used, not merely obtaining access to the site."},{"type":"paragraph","text":"The best introduction to Hinglaj leaves room for people to explain their own relationships with it. It identifies documented changes without treating change as a loss of legitimacy. And it recognises that a pilgrimage is made through movement, memory and shared practice: the arrival matters, but it is not the whole story."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Balochistan","Sacred Heritage"],"province":"Balochistan","district":"Lasbela","relatedDistrictIds":["balochistan-lasbela"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["major-doam-9186"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Hinglaj pilgrimage: listening before describing | Virsapur","description":"Hinglaj is a pilgrimage landscape, not just a destination pin. Its changing journeys and diverse accounts make listening an essential part of describing it.","primaryKeyword":"Hinglaj pilgrimage traditions","socialTitle":"Hinglaj pilgrimage: listening before describing","socialDescription":"Hinglaj is a pilgrimage landscape, not just a destination pin. Its changing journeys and diverse accounts make listening an essential part of describing it."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Hinglaj Devi: Identity, Change, and Solidification at a Hindu Temple in Pakistan","url":"https://academic.oup.com/book/5901","publisher":"Oxford University Press; Jürgen Schaflechner","accessDate":"2026-10-22"},{"title":"Historical Representations and Recent Changes","url":"https://academic.oup.com/book/5901/chapter-abstract/149202495","publisher":"Oxford University Press; Jürgen Schaflechner","accessDate":"2026-10-22"},{"title":"Change and Perseverance","url":"https://academic.oup.com/book/5901/chapter-abstract/149205252","publisher":"Oxford University Press; Jürgen Schaflechner","accessDate":"2026-10-22"},{"title":"Ethics and Intangible Cultural Heritage","url":"https://ich.unesco.org/en/ethics-and-ich-00866","publisher":"UNESCO","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review draft; traditions explicitly attributed, dated testimony not represented as current conditions. No invented interview or ritual participation. OUP book/chapter abstracts read, not full paywalled chapters; total book-derived paraphrase kept under 200 words. Needs community review.","editorialReason":"Frame a community-informed account and avoid treating sacred narratives as archaeological proof.","sortOrder":212}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-panja-sahib-a-tradition-and-its-tangible-setting','panja-sahib-a-tradition-and-its-tangible-setting','review','{"id":"story-panja-sahib-a-tradition-and-its-tangible-setting","type":"story","slug":"panja-sahib-a-tradition-and-its-tangible-setting","title":"Panja Sahib: a tradition and its tangible setting","summary":"The handprint tradition gives Panja Sahib a distinctive sacred focus. Reading the gurdwara well means distinguishing that tradition, the building’s history and continuing pilgrimage.","body":[{"type":"paragraph","text":"Panja Sahib in Hasan Abdal is associated with a sacred account in which Guru Nanak stops a falling rock with his hand. The handprint is central to the place’s identity. Introducing the account as Sikh tradition is not a way of dismissing it; it identifies the kind of meaning being communicated and avoids pretending that a heritage description has independently tested a miracle."},{"type":"paragraph","text":"The SGPC’s account tells the story through Guru Nanak, Bhai Mardana and Wali Qandhari, with access to water and the overcoming of pride among its themes. The rock is therefore not an isolated curiosity. It belongs within a narrative about relationships, spiritual authority and transformation."},{"type":"heading","level":2,"text":"A material focus for memory"},{"type":"paragraph","text":"The federal catalogue likewise identifies the handprint-bearing boulder as the gurdwara’s distinctive sacred association. Its physical presence gives a particular location to a story that can also be carried through speech, text and family memory."},{"type":"paragraph","text":"This relationship helps explain why a close-up image is insufficient. The photograph may show a surface, but it cannot establish how the story is told, how the object relates to the surrounding complex or what the visit means to a pilgrim. A useful caption should connect the object to the institution and attribute the tradition clearly."},{"type":"paragraph","text":"It should also avoid making a visitor’s physical access into a promise. Permission to approach a sacred feature, photograph it or enter a particular area must be established through the institution’s current arrangements."},{"type":"heading","level":2,"text":"The building has more than one time"},{"type":"paragraph","text":"A narrative associated with Guru Nanak and the construction history of the present complex are different subjects. The SGPC account describes later building and changes in management, while the federal catalogue associates construction with Sikh-period patronage. Neither requires the entire visible ensemble to date from the event commemorated."},{"type":"paragraph","text":"This distinction prevents a common error in heritage writing: giving every wall the date of the sacred story. A precinct can grow because an association remains important. Later halls, accommodation and repairs can become part of that history rather than intrusions that must be edited out of the description."},{"type":"paragraph","text":"Detailed claims about individual construction phases would require a more extensive architectural record than the short institutional accounts consulted here."},{"type":"heading","level":2,"text":"An institution, not a frozen scene"},{"type":"paragraph","text":"The ETPB lists Panja Sahib among functional gurdwaras. That classification directs attention to continuing religious life, not only to architectural survival. Pilgrimage connects the place with people whose relationships to it may extend well beyond Hasan Abdal."},{"type":"paragraph","text":"A heritage archive can acknowledge that reach without inventing a representative pilgrim’s experience. It can pair the documented site history with consent-based accounts from visitors and caretakers, preserving the speaker’s name or requested anonymity and the date of the conversation."},{"type":"paragraph","text":"Panja Sahib is most intelligible when these layers remain distinct but connected: the sacred tradition, its tangible focus, the history of the built institution and the people who continue to visit it. Reducing the place to either a miraculous object or an attractive building would miss the relationship between them."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Punjab","Sacred Heritage"],"province":"Punjab","district":"Attock","relatedDistrictIds":["punjab-attock"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-7658"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Panja Sahib: a tradition and its tangible setting | Virsapur","description":"The handprint tradition gives Panja Sahib a distinctive sacred focus. Reading the gurdwara well means distinguishing that tradition, the building’s history and continuing pilgrimage.","primaryKeyword":"Panja Sahib handprint tradition","socialTitle":"Panja Sahib: a tradition and its tangible setting","socialDescription":"The handprint tradition gives Panja Sahib a distinctive sacred focus. Reading the gurdwara well means distinguishing that tradition, the building’s history and continuing pilgrimage."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Gurdwara Panja Sahib, Hasan Abdal","url":"https://new.sgpc.net/gurdwara-panja-sahib-hasan-abdal-pakistan/","publisher":"Shiromani Gurdwara Parbandhak Committee","accessDate":"2026-10-22"},{"title":"Gurdwara Panja Sahib, Hasan Abdal, Attock","url":"https://doam.gov.pk/public/sites/7658","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Functional Gurdwaras","url":"https://etpb.gov.pk/shrines/gurdwaras/functional/","publisher":"Evacuee Trust Property Board","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review draft; traditions explicitly attributed, dated testimony not represented as current conditions. No invented interview or ritual participation. ","editorialReason":"Attribute sacred narrative explicitly and explain how the complex embodies that memory.","sortOrder":213}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-poets-tomb-and-the-readers-memory','the-poets-tomb-and-the-readers-memory','review','{"id":"story-the-poets-tomb-and-the-readers-memory","type":"story","slug":"the-poets-tomb-and-the-readers-memory","title":"The poet’s tomb and the reader’s memory","summary":"A poet’s tomb can bring words, devotion and place together. The connection becomes richer when the text, the performance and the memorial each retain their own history.","body":[{"type":"paragraph","text":"A reader may arrive at a poet’s tomb already carrying a voice: a line heard at home, a school lesson, a recording or a remembered performance. The building gives that attachment a location. Yet the poem and the tomb are not the same kind of evidence. One has a history of wording, interpretation and circulation; the other has a history of construction, repair and use."},{"type":"paragraph","text":"This distinction is especially useful when exploring the memorial places associated with Bulleh Shah, Khawaja Ghulam Farid and Shah Abdul Latif Bhittai. Their names connect literary and devotional worlds, but they should not be combined into an interchangeable category of “Sufi tourist attractions.”"},{"type":"heading","level":2,"text":"A name on the map is only a beginning"},{"type":"paragraph","text":"The federal catalogue identifies Bulleh Shah’s shrine in Kasur and places the poet within a Punjabi literary and religious context. It does not provide a critical edition of his work or establish the authorship of every verse now circulated under his name."},{"type":"paragraph","text":"An archive should therefore resist the temptation to decorate a place page with the most familiar quotation found online. The wording, language, edition and attribution matter. A popular line may reach a visitor through a singer’s version or a modern translation; naming that route can be more illuminating than presenting an unexamined quotation as the poet’s exact voice."},{"type":"paragraph","text":"The same care applies to inscriptions at a memorial. A verse installed during a later repair can reveal how the poet was remembered at that moment. It is not automatically an autograph or a text selected by the poet."},{"type":"heading","level":2,"text":"The voice continues beyond the page"},{"type":"paragraph","text":"Zulfiqar Ali Qureshi’s study of Shah Latif’s vaaee examines singing styles and the role of mass media. Its discussion of the Bhit Shah shrine links poetry with recurring vocal practice, while its broader subject recognises that recordings and broadcasting create further settings for listening."},{"type":"paragraph","text":"This makes an important point about literary heritage: transmission is not confined to a book or a monument. A text may be learned through performance before it is read on a page. Variations in pacing, repetition and musical setting can shape how a listener encounters it without making the printed edition irrelevant."},{"type":"paragraph","text":"The presence of a Shah Abdul Latif library at Bhitshah offers another institutional connection between place and reading. A shrine visit and a library enquiry can answer different questions within the same larger exploration."},{"type":"heading","level":2,"text":"Two histories in conversation"},{"type":"paragraph","text":"Imagine comparing a dated photograph of a poet’s tomb with a dated recording of a poem. The photograph may document a changed entrance or surface. The recording may reveal a performer’s arrangement and pronunciation. Neither can stand in for the other, but together they widen the history of remembrance."},{"type":"paragraph","text":"For visitors, a productive approach is to carry one securely attributed text into the encounter, then notice what the place adds and what it leaves unresolved. The building need not illustrate every line. Nor must every reader experience it devotionally."},{"type":"paragraph","text":"The poet’s memorial becomes most meaningful when it opens further reading and listening. Its role is not to turn a complicated literary life into a fixed slogan, but to make room for continued engagement with words that people have carried across places and generations."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["punjab-kasur","punjab-rajanpur","sindh-matiari"],"provinceRegionIds":["punjab","sindh"],"relatedHeritageIds":["major-doam-10141","major-doam-6191","major-doam-10375"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"The poet’s tomb and the reader’s memory | Virsapur","description":"A poet’s tomb can bring words, devotion and place together. The connection becomes richer when the text, the performance and the memorial each retain their own history.","primaryKeyword":"poet shrines Pakistan","socialTitle":"The poet’s tomb and the reader’s memory","socialDescription":"A poet’s tomb can bring words, devotion and place together. The connection becomes richer when the text, the performance and the memorial each retain their own history."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Shrine of Hazrat Bulley Shah","url":"https://doam.gov.pk/public/sites/10141","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Vaaee of Shah Abdul Latif Bhitai: Origin, Evolution and Role of Mass Media","url":"https://www.el.sindhculture.gov.pk/read/13","publisher":"Sindh Culture Department; Zulfiqar Ali Qureshi","accessDate":"2026-10-22"},{"title":"Shah Abdul Latif Library, Bhitshah","url":"https://archives.sindhculture.gov.pk/shahlatif_library/","publisher":"Sindh Archives","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review draft; traditions explicitly attributed, dated testimony not represented as current conditions. No invented interview or ritual participation. ","editorialReason":"Compare memorial and literary relationships without reducing poets to tourism brands.","sortOrder":214}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-urs-as-a-changing-community-practice','urs-as-a-changing-community-practice','review','{"id":"story-urs-as-a-changing-community-practice","type":"story","slug":"urs-as-a-changing-community-practice","title":"Urs as a changing community practice","summary":"An urs is a commemoration with a local history, not a single festival format. Comparing documented gatherings reveals different calendars, participants and meanings.","body":[{"type":"paragraph","text":"The word urs often appears in visitor information as though it names a standard event. In practice, a commemoration belongs to a particular saint, institution, locality and calendar. Its activities may connect devotion with food, travel, music or social obligations, but the combination must be established rather than assumed."},{"type":"paragraph","text":"Richard K. Wolf’s study of the commemoration at Madho Lal Husain in Lahore explains the association of urs with a spiritual wedding or union. His ethnography also shows that a gathering can hold many meanings for different participants. A shared occasion does not require everyone present to experience it in the same way."},{"type":"heading","level":2,"text":"Local names carry local histories"},{"type":"paragraph","text":"Punjab Auqaf describes the commemoration associated with Sakhi Sarwar as Sang Mela and connects it with the Vaisakhi season. That institutional description offers a specific example; it should not become a rule that every urs follows the same calendar or lasts for the same period."},{"type":"paragraph","text":"The distinction matters for both historical interpretation and practical planning. A remembered seasonal association, a religious calendar date and an organiser’s announcement for a particular year are not interchangeable. An archive can preserve the first two without pretending to provide a confirmed timetable for the third."},{"type":"paragraph","text":"The name of a gathering can also travel. A celebration associated with a saint may occur beyond the principal shrine. The locality and source must be stated so that accounts of different events are not accidentally fused."},{"type":"heading","level":2,"text":"A crowd is not a single participant"},{"type":"paragraph","text":"Wolf’s fieldwork pays attention to drumming, dancing and the ways people describe their participation. It demonstrates the value of looking beyond a general label such as festival atmosphere. A performer, a family visiting a shrine and a person responsible for organising space may be involved in the same event through different commitments."},{"type":"paragraph","text":"A separate ethnographic study by Omar Kasmani examines fakir life in a graveyard at Sehwan Sharif. It draws attention to relationships with place and religious authority that exceed the duration of an annual gathering. The lesson for visitors is not to assume that the most crowded days contain the entirety of a shrine’s living history."},{"type":"paragraph","text":"These studies concern particular settings and research periods. They do not authorise a description of every contemporary participant at Sakhi Sarwar or Lal Shahbaz Qalandar."},{"type":"heading","level":2,"text":"Recording change without declaring decline"},{"type":"paragraph","text":"An old photograph may show a smaller gathering or a differently arranged entrance. A later recording may include amplification or a changed performance setting. Such differences invite questions about organisation, access and technology; they do not by themselves prove that devotion has become less authentic."},{"type":"paragraph","text":"A useful record identifies the year, place, occasion and source of its description. Where people explain a change, their explanation should remain attributed. If accounts differ, the difference may be historically significant."},{"type":"paragraph","text":"For a modern visit, current organisers must confirm access and any recording restrictions. For historical understanding, the more important task is to recognise the urs as a recurring practice made anew by participants, rather than a performance preserved outside time. Its continuity can include change, negotiation and more than one account of what the occasion means."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["punjab-dera-ghazi-khan","sindh-jamshoro"],"provinceRegionIds":["punjab","sindh"],"relatedHeritageIds":["major-doam-10103","major-doam-5179"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Urs as a changing community practice | Virsapur","description":"An urs is a commemoration with a local history, not a single festival format. Comparing documented gatherings reveals different calendars, participants and meanings.","primaryKeyword":"urs cultural heritage Pakistan","socialTitle":"Urs as a changing community practice","socialDescription":"An urs is a commemoration with a local history, not a single festival format. Comparing documented gatherings reveals different calendars, participants and meanings."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Hazrat Sakhi Sarwar, Dera Ghazi Khan","url":"https://auqaf.punjab.gov.pk/shrine-sakhi-sarwar","publisher":"Punjab Auqaf and Religious Affairs Department","accessDate":"2026-10-22"},{"title":"The poetics of Sufi practice: Drumming, dancing, and complex agency at Madho Lal Husain","url":"https://richardkwolf.com/wp-content/uploads/2016/12/poetics_of_sufi_practice.pdf","publisher":"American Ethnologist; Richard K. Wolf","accessDate":"2026-10-22"},{"title":"Grounds of becoming: fakirs among the dead in Sehwan Sharif, Pakistan","url":"https://www.tandfonline.com/doi/abs/10.1080/14755610.2017.1326959","publisher":"Culture and Religion; Omar Kasmani","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review draft; traditions explicitly attributed, dated testimony not represented as current conditions. No invented interview or ritual participation. ","editorialReason":"Plan a sourced account of commemoration, with local variation and contemporary permissions clearly marked.","sortOrder":215}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-qawwali-and-the-question-of-setting','qawwali-and-the-question-of-setting','review','{"id":"story-qawwali-and-the-question-of-setting","type":"story","slug":"qawwali-and-the-question-of-setting","title":"Qawwali and the question of setting","summary":"Qawwali changes when its setting changes. A shrine gathering, a commissioned mehfil and an album place different relationships around the same art of listening.","body":[{"type":"paragraph","text":"A recording can make qawwali available far from the gathering in which it was performed. That reach is valuable, but it also changes the listener’s relationship to the event. A track has a beginning, an ending and a place in a catalogue. A live gathering includes people, expectations and a setting that the recording may only partly preserve."},{"type":"paragraph","text":"Understanding qawwali as heritage therefore means asking where a performance happened, who was involved and how the surviving record was made. A shrine name alone cannot answer those questions, and a playlist is not a complete account of a devotional practice."},{"type":"heading","level":2,"text":"The setting affects the sequence"},{"type":"paragraph","text":"The Smithsonian Folkways record for Meraj Ahmed and his party distinguishes performances at a dargah from commissioned Sufi mehfils elsewhere. Its accompanying description notes that structure and order can vary with those contexts. The recording attempts to represent a sequence, rather than claiming to be a transparent substitute for every gathering."},{"type":"paragraph","text":"This is a useful comparison for approaching qawwali associated with Pakistani shrines such as Data Darbar. It encourages questions about the actual occasion: was the recording made during a shrine event, in a studio, at a concert or in another commissioned setting? Those circumstances should be stated before drawing conclusions about religious practice."},{"type":"paragraph","text":"The Meraj Ahmed material concerns an Indian performer linked with Nizamuddin Auliya. It is not a record of a performance at Data Darbar, and should not be labelled as one."},{"type":"heading","level":2,"text":"Musicians are not anonymous atmosphere"},{"type":"paragraph","text":"Folkways’ Pakistan: The Music of the Qawal identifies an ensemble led by Haji Ghulam Farid Sabri. Naming the musicians changes how the archive works. The recording becomes part of identifiable artistic labour and a recorded career, rather than a decorative soundtrack attached to a photograph of a shrine."},{"type":"paragraph","text":"Ethnomusicologist Shalini Ayyagari’s commentary on the release also questions aspects of its presentation, including the choice of photographs in the original notes. This is a useful reminder that even an institutional album can be examined critically. The authority of a collection does not mean every accompanying image precisely represents the performers heard."},{"type":"heading","level":2,"text":"Listen to what the record preserves"},{"type":"paragraph","text":"A listener can attend to the interaction between a principal voice and the ensemble, changes in intensity, and the return of a line or phrase. Those observations are more specific than describing the whole performance as ecstatic. They still do not reveal the private experience of an individual listener."},{"type":"paragraph","text":"Translations need their own attribution. A lyric’s poetic speaker should not automatically be treated as the singer’s autobiography, and a translated refrain may not carry every implication of its original language. A useful archive connects the recording with the available text and explanation without pretending that one caption resolves the entire poem."},{"type":"paragraph","text":"Qawwali’s movement into concerts and recordings is part of its history, not merely a departure from a supposedly untouched original. The task is to identify those settings honestly. When place, performers, occasion and recording history remain visible, listening can become an encounter with an art and its relationships rather than a search for a convenient cultural mood."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["punjab-lahore"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-10200"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Qawwali and the question of setting | Virsapur","description":"Qawwali changes when its setting changes. A shrine gathering, a commissioned mehfil and an album place different relationships around the same art of listening.","primaryKeyword":"qawwali shrine context","socialTitle":"Qawwali and the question of setting","socialDescription":"Qawwali changes when its setting changes. A shrine gathering, a commissioned mehfil and an album place different relationships around the same art of listening."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Qawwali by Meraj Ahmed and Party","url":"https://folkways.si.edu/meraj-ahmed-and-party/qawwali/india-world/music/album/smithsonian","publisher":"Smithsonian Folkways and Archives and Research Centre for Ethnomusicology","accessDate":"2026-10-22"},{"title":"Pakistan: The Music of the Qawal","url":"https://folkways.si.edu/pakistan-the-music-of-the-qawal/world/music/album/smithsonian","publisher":"Smithsonian Folkways","accessDate":"2026-10-22"},{"title":"UNESCO Collection Week 16: Lesser-known Music from North India and Pakistan","url":"https://folkways.si.edu/news-and-press/unesco-collection-week-16-lesser-known-music-from-north-india-and-pakistan","publisher":"Smithsonian Folkways; Shalini Ayyagari","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review draft; traditions explicitly attributed, dated testimony not represented as current conditions. No invented interview or ritual participation. ","editorialReason":"Explain performance context through practitioner and institutional records rather than a generic playlist.","sortOrder":216}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-dhamaal-representation-participation-and-consent','dhamaal-representation-participation-and-consent','review','{"id":"story-dhamaal-representation-participation-and-consent","type":"story","slug":"dhamaal-representation-participation-and-consent","title":"Dhamaal: representation, participation and consent","summary":"Dhamaal should not be reduced to a dramatic clip. Its documentation requires attention to participants’ meanings, the setting and consent for the uses an image may acquire.","body":[{"type":"paragraph","text":"Dhamaal is visually compelling, which makes it particularly vulnerable to being detached from its setting. A short clip can turn movement into a symbol of abandon, mystery or spectacle before a participant has said anything about what they are doing. The result may circulate widely while communicating very little about the practice."},{"type":"paragraph","text":"At Sehwan, the association with Lal Shahbaz Qalandar gives dhamaal a specific religious context. It should not be approached as a generic dance available for a visitor to reproduce, direct or interrupt. Observation and participation are different relationships, and neither automatically includes permission to publish."},{"type":"heading","level":2,"text":"Meaning is not visible in a facial expression"},{"type":"paragraph","text":"Delphine Ortis’s research summary treats dhamaal in Sehwan through love, authority and the recognition of practice within a community. It points towards learned relationships and local understandings rather than an absence of order. The short summary does not provide a complete account of every form of dhamaal, and it is used here only for that limited argument."},{"type":"paragraph","text":"Richard K. Wolf’s work on drumming and movement in Lahore likewise examines different accounts of participation. The comparison shows why a caption should not claim to know a person’s inner state from a photograph. The research sites are distinct; a Lahore observation is not direct evidence about a particular Sehwani participant."},{"type":"paragraph","text":"Words such as trance can become especially misleading when used as a visual diagnosis. If a participant uses a term to describe an experience, attribute it. If no such account exists, describe only what the recording actually shows."},{"type":"heading","level":2,"text":"Consent follows the image"},{"type":"paragraph","text":"UNESCO’s ethical principles emphasise the role of communities and sustained informed consent in safeguarding living heritage. For a photographer, this means explaining the proposed use: a personal record, an educational archive and a promotional campaign are not the same request."},{"type":"paragraph","text":"A person may agree to a photograph without anticipating that it will be cropped, captioned with a speculative claim or detached from the name of the occasion. Discussing those uses before publication is more meaningful than treating a quick gesture towards the camera as unlimited permission."},{"type":"paragraph","text":"Where obtaining individual consent is impractical, that limitation should influence what is recorded. A distant scene may still identify people; a sensitive moment does not become ethically uncomplicated because it occurs in an accessible space."},{"type":"heading","level":2,"text":"Preserve the relationship, not only the movement"},{"type":"paragraph","text":"A stronger archive would name the place and date, identify the occasion where known and include the participant’s own explanation when offered. It would distinguish a recording of an event from a later demonstration made for documentation. Neither should be passed off as the other."},{"type":"paragraph","text":"The sound also belongs to the record. Replacing it with unrelated music can sever the relationship between movement and the actual gathering. An edited clip should say that it is edited, and any interpretation should remain separate from the evidence."},{"type":"paragraph","text":"Dhamaal deserves the same precision given to an inscription or an architectural plan. Its participants are people with responsibilities, preferences and differing understandings, not visual material awaiting an outside explanation. A smaller, consent-based record may preserve more of that reality than an impressive collection of decontextualised images."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sindh","Sacred Heritage"],"province":"Sindh","district":"Jamshoro","relatedDistrictIds":["sindh-jamshoro"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5179"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Dhamaal: representation, participation and consent | Virsapur","description":"Dhamaal should not be reduced to a dramatic clip. Its documentation requires attention to participants’ meanings, the setting and consent for the uses an image may acquire.","primaryKeyword":"dhamaal heritage interpretation","socialTitle":"Dhamaal: representation, participation and consent","socialDescription":"Dhamaal should not be reduced to a dramatic clip. Its documentation requires attention to participants’ meanings, the setting and consent for the uses an image may acquire."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Dancing to Show Love, Practicing to Show Authority: The Practice of Dhamal in the Qalandari Sufi Order","url":"https://www.growkudos.com/publications/10.1163%25252F26670925-bja10017/reader","publisher":"Delphine Ortis; author summary of Journal of Sindhi Studies research","accessDate":"2026-10-22"},{"title":"The poetics of Sufi practice","url":"https://richardkwolf.com/wp-content/uploads/2016/12/poetics_of_sufi_practice.pdf","publisher":"American Ethnologist; Richard K. Wolf","accessDate":"2026-10-22"},{"title":"Ethics and Intangible Cultural Heritage","url":"https://ich.unesco.org/en/ethics-and-ich-00866","publisher":"UNESCO","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review draft; traditions explicitly attributed, dated testimony not represented as current conditions. No invented interview or ritual participation. Ortis author summary/abstract read, full DOI unavailable; no detailed ritual sequence inferred. Requires participant review before publication.","editorialReason":"Address ethical documentation and local meaning without prescribing ritual participation.","sortOrder":217}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-sacred-sound-is-not-always-music-for-an-audience','sacred-sound-is-not-always-music-for-an-audience','review','{"id":"story-sacred-sound-is-not-always-music-for-an-audience","type":"story","slug":"sacred-sound-is-not-always-music-for-an-audience","title":"Sacred sound is not always music for an audience","summary":"The same sound can be heard as worship, recitation or performance. Heritage listening begins by asking how participants understand it, not by assigning every voice to a concert category.","body":[{"type":"paragraph","text":"A visitor hears a trained voice, a repeated phrase or an organised melody and may immediately call it a performance. That description can be useful, but it may also place the visitor at the centre of an activity that is not being undertaken primarily for an audience. The people involved may understand the sound through worship, recitation, learning or service."},{"type":"paragraph","text":"This is not an argument against appreciating musical skill. It is an invitation to identify the purpose and terms of the particular practice before turning it into a heritage soundtrack."},{"type":"heading","level":2,"text":"The words are part of the action"},{"type":"paragraph","text":"The SGPC’s Sikh Rehat Maryada describes kirtan through the singing of scriptural compositions and sets out expectations for its congregational setting. That institutional account makes the relationship to scripture explicit. The melody cannot be understood fully as an independent decorative layer."},{"type":"paragraph","text":"For a visitor at a gurdwara such as Panja Sahib, this means that listening should not begin with a request for a favourite song or an assumption that the gathering operates like a concert. Current guidance from the institution determines how a visitor may observe or record. The code is a religious source, not a timetable for the site."},{"type":"paragraph","text":"The distinction also affects cataloguing. Identifying a recording only as “traditional music” can hide the text and the purpose that participants consider central. Where the composition can be reliably identified, that information belongs beside the performers and the occasion."},{"type":"heading","level":2,"text":"A recording changes the encounter"},{"type":"paragraph","text":"The Folkways description of Meraj Ahmed’s qawwali distinguishes shrine-related performance from commissioned gatherings. Even within one broad tradition, setting affects the organisation of the music. A commercially available recording may preserve significant artistry while offering only a partial view of the live relationship."},{"type":"paragraph","text":"Zulfiqar Ali Qureshi’s study of Shah Latif’s vaaee examines both shrine practice and mass media. The comparison suggests another question: what happens when a recurring devotional practice is presented to listeners who encounter it through broadcasting rather than participation at its established setting?"},{"type":"paragraph","text":"The answer need not be that one form is authentic and the other false. The useful account identifies the change in medium and the people responsible for the version being heard."},{"type":"heading","level":2,"text":"Listen without assigning a private experience"},{"type":"paragraph","text":"A listener can describe a response from the group, a change of pace or a return to particular words. They cannot know from sound alone whether an individual is experiencing consolation, concentration, grief or something else. Those meanings require testimony, and testimony remains the account of its speaker."},{"type":"paragraph","text":"At a khanqah, shrine or gurdwara, silence and waiting may also matter. A recording that removes every interval can make an activity seem more continuous or more theatrical than it was. Good documentation notes editing rather than presenting the result as an unaltered encounter."},{"type":"paragraph","text":"Sacred sound can be aesthetically powerful without existing for a visitor’s enjoyment. Respectful listening allows those facts to coexist. It attends to the text, the setting and the participants, and accepts that some moments are better understood by being present than by taking a recording away."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["gilgit-baltistan-ghanche","punjab-attock"],"provinceRegionIds":["gilgit-baltistan","punjab"],"relatedHeritageIds":["major-doam-7966","major-doam-7658"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Sacred sound is not always music for an audience | Virsapur","description":"The same sound can be heard as worship, recitation or performance. Heritage listening begins by asking how participants understand it, not by assigning every voice to a concert category.","primaryKeyword":"sacred sound heritage Pakistan","socialTitle":"Sacred sound is not always music for an audience","socialDescription":"The same sound can be heard as worship, recitation or performance. Heritage listening begins by asking how participants understand it, not by assigning every voice to a concert category."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Sikh Rehat Maryada, Article VI: Kirtan","url":"https://old.sgpc.net/CDN/Sikh_Rehat_Maryada_English.pdf","publisher":"Shiromani Gurdwara Parbandhak Committee","accessDate":"2026-10-22"},{"title":"Qawwali by Meraj Ahmed and Party","url":"https://folkways.si.edu/meraj-ahmed-and-party/qawwali/india-world/music/album/smithsonian","publisher":"Smithsonian Folkways","accessDate":"2026-10-22"},{"title":"Vaaee of Shah Abdul Latif Bhitai: Origin, Evolution and Role of Mass Media","url":"https://www.el.sindhculture.gov.pk/read/13","publisher":"Sindh Culture Department; Zulfiqar Ali Qureshi","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review draft; traditions explicitly attributed, dated testimony not represented as current conditions. No invented interview or ritual participation. SGPC PDF indexed Article VI/XIX text read; direct PDF host returned 502. Code distinguished from historical practice.","editorialReason":"Distinguish worship, performance and visitor listening through community-reviewed examples.","sortOrder":218}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-a-samadhi-and-a-grave-are-not-interchangeable','a-samadhi-and-a-grave-are-not-interchangeable','review','{"id":"story-a-samadhi-and-a-grave-are-not-interchangeable","type":"story","slug":"a-samadhi-and-a-grave-are-not-interchangeable","title":"A samadhi and a grave are not interchangeable","summary":"Funerary terms describe more than a building’s appearance. Samadhi, cremation memorial and grave should be distinguished through the history of the particular place.","body":[{"type":"paragraph","text":"A dome and a chamber do not tell us what happened to the body of the person commemorated there. Similar architectural forms can shelter a grave, mark a cremation place or serve a memorial purpose. Translating every funerary monument as a tomb may be convenient, but it can conceal distinctions that matter to its history."},{"type":"paragraph","text":"Samadhi is a particularly important term to retain and explain carefully. In a built-heritage record, its meaning should be established through the particular institution and source, rather than assumed from a dictionary definition or extended to every Hindu or Sikh funerary practice."},{"type":"heading","level":2,"text":"Two monuments, specific associations"},{"type":"paragraph","text":"The federal catalogue describes the Samadhi of Ranjit Singh in Lahore as occupying the place of his cremation. Its record for Mahan Singh’s samadhi in Gujranwala likewise connects the monument with a cremation site. Those descriptions are more precise than an unqualified statement that each ruler is buried beneath the building."},{"type":"paragraph","text":"They also show why the history of the memorial must be distinguished from the death commemorated. Construction may follow later. Patronage, subsequent additions and restoration can belong to different moments, even when the monument continues to bear one person’s name."},{"type":"paragraph","text":"The short catalogue entries are not sufficient to establish every detail about the handling or present location of remains. Where the evidence does not support that claim, an archive should use the narrower description of a commemorative association."},{"type":"heading","level":2,"text":"Historical practice and religious prescription"},{"type":"paragraph","text":"The SGPC’s Sikh Rehat Maryada discusses funeral ceremonies and cremation. It also rejects raising a monument at the place of cremation. This makes an important distinction visible: the existence of a historical royal samadhi should not be presented as proof that it represents the prescription for all Sikh funerals."},{"type":"paragraph","text":"A code and a surviving monument answer different historical questions. The code states an institutional religious position; the monument documents a particular act of commemoration. Their relationship requires historical context, not an attempt to erase either source."},{"type":"paragraph","text":"This is also why a visitor should not infer the beliefs of present-day Sikhs from a royal building alone. Monumental patronage, family memory and religious norms do not always produce a single uniform record."},{"type":"heading","level":2,"text":"Read the label before the silhouette"},{"type":"paragraph","text":"A useful description separates the site’s name, its commemorative subject and the physical evidence. It might state that a building is identified as a samadhi and that a cited record associates it with cremation, then describe its plan and decoration independently."},{"type":"paragraph","text":"The same approach helps with a grave. A visible marker is not necessarily the burial chamber itself, and a later inscription may replace an earlier one. Architectural observation should be paired with documentary evidence rather than made to carry an identification it cannot establish."},{"type":"paragraph","text":"For the visitor, this precision makes the buildings more interesting, not less. Ranjit Singh’s and Mahan Singh’s memorials become particular historical constructions instead of examples of an imagined universal custom. Keeping the original term visible allows the archive to explain the commemorative relationship on its own terms, while avoiding a misleading translation that makes every funerary place appear to be the same kind of burial."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["punjab-lahore","punjab-gujranwala"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6470","major-doam-10110"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"A samadhi and a grave are not interchangeable | Virsapur","description":"Funerary terms describe more than a building’s appearance. Samadhi, cremation memorial and grave should be distinguished through the history of the particular place.","primaryKeyword":"samadhi funerary heritage","socialTitle":"A samadhi and a grave are not interchangeable","socialDescription":"Funerary terms describe more than a building’s appearance. Samadhi, cremation memorial and grave should be distinguished through the history of the particular place."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Samadh of Ranjit Singh","url":"https://doam.gov.pk/public/sites/6470","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Mahan Singh Samadhi","url":"https://doam.gov.pk/public/sites/10110","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Sikh Rehat Maryada, Article XIX: Funeral Ceremonies","url":"https://old.sgpc.net/CDN/Sikh_Rehat_Maryada_English.pdf","publisher":"Shiromani Gurdwara Parbandhak Committee","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review draft; traditions explicitly attributed, dated testimony not represented as current conditions. No invented interview or ritual participation. SGPC PDF indexed Article VI/XIX text read; direct PDF host returned 502. Code distinguished from historical practice.","editorialReason":"Clarify commemorative terminology without making broad claims about all Sikh or Hindu traditions.","sortOrder":219}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-funerary-landscapes-and-the-names-we-no-longer-know','funerary-landscapes-and-the-names-we-no-longer-know','review','{"id":"story-funerary-landscapes-and-the-names-we-no-longer-know","type":"story","slug":"funerary-landscapes-and-the-names-we-no-longer-know","title":"Funerary landscapes and the names we no longer know","summary":"Unknown names do not make a cemetery historically empty. At Makli and Chaukhandi, materials, inscriptions and the relationships between monuments preserve different kinds of evidence.","body":[{"type":"paragraph","text":"A named royal tomb offers a convenient story: a ruler, a date and a monument. A grave whose occupant is unknown can seem less legible, but it is not without history. Its material, position, construction and relationship to neighbouring graves may preserve evidence even when the person’s name has been lost or has not yet been securely identified."},{"type":"paragraph","text":"This is a useful way to approach the funerary landscapes of Makli and Chaukhandi. They should not be treated as identical cemeteries, nor reduced to a collection of photogenic carvings. Each has its own setting and evidence."},{"type":"heading","level":2,"text":"A monument without a secure name"},{"type":"paragraph","text":"UNESCO’s account of conservation work at Makli in 2025 describes attention to the Shaikh Jyio Tomb and a nearby unknown tomb associated with the Samma period. The unidentified monument was documented, assessed and investigated before work proceeded. A missing personal name did not make its structure or conservation needs less significant."},{"type":"paragraph","text":"The example separates two kinds of knowledge. Researchers may have evidence for a broad period or building technique without knowing who was commemorated. Conversely, a traditional name may survive while the date of the visible fabric remains uncertain."},{"type":"paragraph","text":"An honest archive keeps those levels distinct. “Unknown” should identify the particular gap, not suggest that nothing can be said. Nor should a plausible name be inserted merely to make a place page feel complete."},{"type":"heading","level":2,"text":"Decoration is evidence, not a biography"},{"type":"paragraph","text":"The federal catalogue describes Chaukhandi’s carved stone graves and the motifs used in its interpretation of male and female commemorations. Such descriptions provide a starting point for studying how identity was represented. They do not automatically reveal the occupation, rank or life story of every individual."},{"type":"paragraph","text":"A horseman or weapon motif may have a commemorative role without proving that the person below performed a specific deed. Jewellery carved on stone is not an inventory of possessions recovered from a burial. To turn either into a personal biography would require further evidence."},{"type":"paragraph","text":"The carvings still deserve close attention. Recording their location, relationship to inscriptions and differences between monuments can support comparison without forcing a confident story onto each image."},{"type":"heading","level":2,"text":"The cemetery is more than its largest buildings"},{"type":"paragraph","text":"UNESCO’s Makli description connects the necropolis with the historical importance of Thatta and identifies monuments associated with several kinds of social figure. The better-known structures help orient a visit, but they should not make smaller markers disappear from the record."},{"type":"paragraph","text":"Paths, groups of graves and changes in construction can reveal relationships at a scale larger than an individual tomb. A survey can record those relationships even where a visitor cannot read an inscription. Such documentation must be undertaken without moving stones or treating fragile surfaces as seats or climbing points."},{"type":"paragraph","text":"A cemetery also concerns the dead and those who continue to care about them. Lack of a legible name does not remove the obligation to behave respectfully."},{"type":"paragraph","text":"The most revealing encounter may therefore begin with a modest question: what is actually preserved here, and what kind of evidence could answer the next question? That approach leaves uncertainty visible while recognising that unnamed people and monuments remain part of the historical landscape."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["sindh-thatta","sindh-malir-karachi"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["unesco-143","major-doam-5815"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Funerary landscapes and the names we no longer know | Virsapur","description":"Unknown names do not make a cemetery historically empty. At Makli and Chaukhandi, materials, inscriptions and the relationships between monuments preserve different kinds of evidence.","primaryKeyword":"historic cemetery interpretation","socialTitle":"Funerary landscapes and the names we no longer know","socialDescription":"Unknown names do not make a cemetery historically empty. At Makli and Chaukhandi, materials, inscriptions and the relationships between monuments preserve different kinds of evidence."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Historical Monuments at Makli, Thatta","url":"https://whc.unesco.org/en/list/143","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"UNESCO Strengthens Capacity of the Government of Sindh in Preserving the Historical Monuments at Makli","url":"https://whc.unesco.org/en/news/2771","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Chaukhandi Tombs","url":"https://doam.gov.pk/public/sites/5815","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Original review draft; traditions explicitly attributed, dated testimony not represented as current conditions. No invented interview or ritual participation. ","editorialReason":"Explore what architecture can reveal when individual identity remains uncertain.","sortOrder":220}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-reading-epitaphs-responsibly','reading-epitaphs-responsibly','review','{"id":"story-reading-epitaphs-responsibly","type":"story","slug":"reading-epitaphs-responsibly","title":"Reading epitaphs responsibly","summary":"An epitaph is a text on a material object, not a ready-made biography. Transcription, translation and historical interpretation should remain distinct and checkable.","body":[{"type":"paragraph","text":"A few legible words on a tomb can feel like direct contact with a person from the past. They can also tempt a reader into filling gaps too quickly. An epitaph may include names, titles, prayer, poetry and dates, but those elements need to be separated before they can support a historical account."},{"type":"paragraph","text":"Reading responsibly begins with the object. Where is the inscription? Is it part of a grave marker, a wall panel or a later plaque? Does it appear to belong to the surrounding fabric? A text moved or replaced during repair may have a different history from the monument beside it."},{"type":"heading","level":2,"text":"Record before translating"},{"type":"paragraph","text":"A transcription represents the writing that can be read. A translation attempts to convey its meaning in another language. Neither is the same as an explanation of the person’s life. Keeping the three stages separate makes it possible for another reader to identify where an interpretation entered the record."},{"type":"paragraph","text":"EpiDoc’s guidance distinguishes a diplomatic transcription, with minimal intervention, from editorial additions and other treatments of a text. Its conventions also allow lost or illegible material to remain visibly missing. The broader lesson is useful beyond any particular digital format: uncertainty should survive into the published record."},{"type":"paragraph","text":"If part of a name is damaged, supplying a familiar ruler’s name without marking the restoration creates false certainty. If a title has several possible meanings, a translation should not silently choose the one that makes the most dramatic biography."},{"type":"heading","level":2,"text":"Dates describe particular events"},{"type":"paragraph","text":"A date on a tomb may concern death, construction, repair or the installation of a panel. Identifying the event is as important as converting the numerals. Calendar conversions should also be checked, especially when a published equivalent offers more precision than the inscription supports."},{"type":"paragraph","text":"A prayer or scriptural passage is not automatically a personal statement by the deceased. Nor does a poem establish authorship merely because it appears on a monument associated with a poet. The text’s function has to be considered alongside its wording."},{"type":"paragraph","text":"The federal records for Tahir Khan Nahar’s tomb at Sitpur and Sheikh Sadan Shaheed’s tomb provide architectural descriptions, but they do not supply complete edited epitaphs. Their inclusion in the atlas is therefore not a licence to invent translated inscriptions for either place."},{"type":"heading","level":2,"text":"Make the reading recoverable"},{"type":"paragraph","text":"A useful record preserves a clear photograph, the location of the text, line divisions, the proposed reading and the translator’s name. Earlier published readings can be cited separately. If two readings differ, explain which letters or assumptions produce the disagreement."},{"type":"paragraph","text":"A photograph taken in poor light may conceal a stroke that is visible in another image. That is a reason to improve non-invasive documentation with permission, not to scratch, chalk or wet the surface to make it easier to read."},{"type":"paragraph","text":"The reward is more than an accurate caption. A carefully edited epitaph can connect a name with patronage, family relationships or a particular commemorative moment. Where it cannot, the gap remains part of the evidence. Preserving that distinction allows the inscription to speak as a historical source rather than as a prompt for a story we have already decided to tell."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["punjab-muzaffargarh"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6417","major-doam-6172"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Reading epitaphs responsibly | Virsapur","description":"An epitaph is a text on a material object, not a ready-made biography. Transcription, translation and historical interpretation should remain distinct and checkable.","primaryKeyword":"epitaph translation heritage","socialTitle":"Reading epitaphs responsibly","socialDescription":"An epitaph is a text on a material object, not a ready-made biography. Transcription, translation and historical interpretation should remain distinct and checkable."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"EpiDoc: Epigraphic Documents in TEI XML","url":"https://epidoc.stoa.org/","publisher":"EpiDoc Collaborative","accessDate":"2026-10-22"},{"title":"Diplomatic Transcriptions","url":"https://epidoc.stoa.org/gl/latest/trans-diplomatic.html","publisher":"EpiDoc Collaborative","accessDate":"2026-10-22"},{"title":"Lost characters, quantity known","url":"https://epidoc.stoa.org/gl/latest/trans-lostcharknown.html","publisher":"EpiDoc Collaborative","accessDate":"2026-10-22"},{"title":"Tomb of Tahir Khan Nahar, Sitpur","url":"https://doam.gov.pk/public/sites/6417","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Tomb of Hazrat Sheikh Sadan Shaheed","url":"https://doam.gov.pk/public/sites/6172","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft; evidence-specific comparisons and explicit limits. No new ownership/access determinations or speculative biographies. ","editorialReason":"Explain transcription, translation and attribution checks rather than provide unverified translations.","sortOrder":221}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-women-remembered-in-monumental-tombs','women-remembered-in-monumental-tombs','review','{"id":"story-women-remembered-in-monumental-tombs","type":"story","slug":"women-remembered-in-monumental-tombs","title":"Women remembered in monumental tombs","summary":"The tombs associated with Nur Jahan, Nadira Begum and Bibi Jawindi invite different questions about women, patronage and remembrance. Their histories should not be reduced to romantic biography.","body":[{"type":"paragraph","text":"A woman’s monumental tomb is often introduced through her relationship to a man: wife, daughter or mother. Those relationships may be historically relevant, but they should not become the entire description. Patronage, political presence, religious standing and the later work of remembrance can offer other routes into the subject."},{"type":"paragraph","text":"The tombs associated with Nur Jahan, Nadira Begum and Bibi Jawindi are not three versions of one story. Their forms and surviving records differ. Comparing them is useful precisely because it prevents a single familiar narrative of royal love from being imposed on every monument."},{"type":"heading","level":2,"text":"Patronage is a question of evidence"},{"type":"paragraph","text":"The federal catalogue attributes Nur Jahan’s tomb to construction during her own lifetime. That statement places patronage within the discussion rather than treating her only as the person commemorated. It deserves to be considered alongside other documentary and material evidence, not expanded into an imagined account of her private thoughts."},{"type":"paragraph","text":"A British Museum gold coin dated 1626 identifies both Jahangir and Nur Jahan in its catalogue authority fields. It is a different kind of object from the Lahore tomb, but it helps keep political presence within view. A funerary account need not sever the remembered person from the public world in which she acted."},{"type":"paragraph","text":"Neither source, on its own, explains every decision behind the tomb’s design. A responsible comparison identifies what each object can establish and resists using architectural beauty as evidence of a particular emotion."},{"type":"heading","level":2,"text":"Buildings are not interchangeable biographies"},{"type":"paragraph","text":"The catalogue describes Nadira Begum’s tomb as a two-storeyed, square pavilion with recessed openings and traces of painted geometric decoration. Bibi Jawindi’s tomb at Uch is described through an octagonal plan, brick construction and glazed tilework. These are materially different ways of making a commemorative structure."},{"type":"paragraph","text":"The contrast offers questions about setting, construction and architectural relationships. It does not establish that one woman preferred one form or personally selected its ornament. Such claims would need evidence of agency in the design process, not merely a named association with the completed building."},{"type":"paragraph","text":"The surviving fabric also has a history after the original commemoration. Loss, repair and replacement can shape what a visitor sees. A present appearance should not be treated as an untouched expression of a patron’s intention."},{"type":"heading","level":2,"text":"What the comparison can recover"},{"type":"paragraph","text":"A useful account asks who commissioned the monument, what identifies the person remembered, which parts survive and how the place has been interpreted over time. Sometimes the answers are uneven. A detailed building description may coexist with a comparatively sparse biography."},{"type":"paragraph","text":"That unevenness should remain visible. Inventing a personality to balance an article’s paragraphs does not recover a neglected woman’s history; it replaces the missing evidence with an author’s expectations."},{"type":"paragraph","text":"The monuments nevertheless make women’s remembrance materially present within Pakistan’s heritage landscape. They invite attention to authority, devotion, family and patronage without requiring every life to fit the same pattern. Reading them together can widen the questions asked of funerary architecture, while keeping each woman and each building distinct."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["punjab-lahore","punjab-bahawalpur"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6472","major-doam-6485","major-doam-6552"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Women remembered in monumental tombs | Virsapur","description":"The tombs associated with Nur Jahan, Nadira Begum and Bibi Jawindi invite different questions about women, patronage and remembrance. Their histories should not be reduced to romantic biography.","primaryKeyword":"women funerary monuments Pakistan","socialTitle":"Women remembered in monumental tombs","socialDescription":"The tombs associated with Nur Jahan, Nadira Begum and Bibi Jawindi invite different questions about women, patronage and remembrance. Their histories should not be reduced to romantic biography."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Tomb of Nur Jahan","url":"https://doam.gov.pk/public/sites/6472","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Nadira Begum’s Tomb and Tank","url":"https://doam.gov.pk/public/sites/6485","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Tomb of Bibi Jawindi","url":"https://doam.gov.pk/public/sites/6552","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Gold coin associated with Jahangir and Nur Jahan, 1939.0514.12","url":"https://www.britishmuseum.org/collection/object/C_1939-0514-12","publisher":"The British Museum","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft; evidence-specific comparisons and explicit limits. No new ownership/access determinations or speculative biographies. ","editorialReason":"Compare documented patronage and commemoration without inventing private biographies.","sortOrder":222}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-christian-church-heritage-beyond-metropolitan-centres','christian-church-heritage-beyond-metropolitan-centres','review','{"id":"story-christian-church-heritage-beyond-metropolitan-centres","type":"story","slug":"christian-church-heritage-beyond-metropolitan-centres","title":"Christian church heritage beyond metropolitan centres","summary":"Historic churches in Abbottabad, the Galiyat and Talagang widen the geography of Christian heritage. Their congregations and institutional histories matter as much as their colonial-period fabric.","body":[{"type":"paragraph","text":"Pakistan’s Christian built heritage is not confined to the major cathedrals of its largest cities. Churches in smaller urban centres and hill settings broaden the picture. They also challenge a habit of describing every such building as a picturesque remnant of British rule, as though its history stopped when the colonial period ended."},{"type":"paragraph","text":"The materials and dates of construction remain important. So do the institutions and communities that have used, maintained or adapted the buildings. A church can be an architectural record and a place of continuing worship at the same time."},{"type":"heading","level":2,"text":"Abbottabad: fabric and institution"},{"type":"paragraph","text":"The federal survey record for St Luke’s Church in Abbottabad describes dressed stonework and a pointed entrance arch. These observations provide an architectural starting point, but the survey’s assessment of condition belongs to its research period. It is not a current inspection report."},{"type":"paragraph","text":"The Peshawar Diocese’s own parish listing identifies St Luke’s within the Church of Pakistan’s institutional life. The same listing connects the Abbottabad area with worship places in the Galiyat. That primary community source is important because it keeps the account from presenting the buildings merely as objects inherited from absent Europeans."},{"type":"paragraph","text":"A parish listing does not provide a complete architectural history. It does, however, show where a heritage enquiry should seek a community perspective and confirmation of present arrangements."},{"type":"heading","level":2,"text":"A smaller record in Talagang"},{"type":"paragraph","text":"The federal catalogue also records a church in Talagang through a local archaeological study. Its description notes a square plan, a pediment and later renovation. The entry’s generic title is itself a limit: it does not establish the dedication, denomination or full history of the congregation."},{"type":"paragraph","text":"Those gaps should not be filled by transferring details from a better-known church elsewhere. A cross or a round-arched opening cannot determine an institution’s denominational history. A more complete account would bring the building record into conversation with parish documents and people authorised to speak about its use."},{"type":"paragraph","text":"The atlas’s linked St Matthew’s record in Nathia Gali offers another starting point for enquiry. It should not be assumed to be the St Matthew’s congregation in Peshawar simply because the dedication matches."},{"type":"heading","level":2,"text":"Beyond the colonial label"},{"type":"paragraph","text":"An archival photograph may document an early arrangement of pews, a roof or a memorial tablet. Later photographs and community records can reveal repairs and changes in use. Both belong to the building’s history. Treating only the earliest layer as valuable can make decades of local care disappear."},{"type":"paragraph","text":"The people who clean, repair, teach or gather in a church are not secondary to its heritage. Their accounts may explain why a room changed or which memorials continue to matter. Any oral history should be recorded with consent and attributed rather than turned into a statement about all Christians in Pakistan."},{"type":"paragraph","text":"Visiting requires an invitation or confirmed access arrangements, especially during worship. The aim is not to collect interiors as visual curiosities. It is to understand how particular buildings belong to particular communities, and how those relationships have continued beyond the period in which the first stones were laid."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["khyber-pakhtunkhwa-abbottabad","punjab-talagang"],"provinceRegionIds":["khyber-pakhtunkhwa","punjab"],"relatedHeritageIds":["major-doam-664","major-doam-623","major-doam-6744"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Christian church heritage beyond metropolitan centres | Virsapur","description":"Historic churches in Abbottabad, the Galiyat and Talagang widen the geography of Christian heritage. Their congregations and institutional histories matter as much as their colonial-period fabric.","primaryKeyword":"historic churches Pakistan","socialTitle":"Christian church heritage beyond metropolitan centres","socialDescription":"Historic churches in Abbottabad, the Galiyat and Talagang widen the geography of Christian heritage. Their congregations and institutional histories matter as much as their colonial-period fabric."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"St Luke’s Church","url":"https://doam.gov.pk/public/sites/664","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Church, Talagang","url":"https://doam.gov.pk/public/sites/6744","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Parishes and Clergy","url":"https://new.peshawardiocese.org/new-parishes-clergy/","publisher":"Peshawar Diocese, Church of Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft; evidence-specific comparisons and explicit limits. No new ownership/access determinations or speculative biographies. Denominational/current-use review required by relevant church communities; generic Talagang dedication unresolved. Nathia Gali mentioned only as linked enquiry, not conflated with Peshawar Saint Matthew.","editorialReason":"Widen the geographic story while requiring denominational and community review.","sortOrder":223}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-cemeteries-as-records-of-migration-and-service','cemeteries-as-records-of-migration-and-service','review','{"id":"story-cemeteries-as-records-of-migration-and-service","type":"story","slug":"cemeteries-as-records-of-migration-and-service","title":"Cemeteries as records of migration and service","summary":"A cemetery can connect places of birth, work and death, but inscriptions need to be read alongside archival records. A single named officer cannot represent everyone buried nearby.","body":[{"type":"paragraph","text":"A cemetery can bring distant places into a single landscape. A name, a recorded birthplace, a service title or a family relationship may suggest journeys that ended far from where they began. Yet the presence of a person in a burial ground does not by itself explain why they travelled, how they lived or how they understood their attachment to the place."},{"type":"paragraph","text":"This is especially important when reading cemeteries associated with colonial-period institutions. Soldiers, administrators, children, spouses and other residents should not be merged into one undifferentiated population simply because some graves share a language or a religious form."},{"type":"heading","level":2,"text":"Two scales of evidence"},{"type":"paragraph","text":"The federal catalogue describes Shahwala Graveyard through its terraced arrangement, compartments, stone enclosure and marble decoration. That record tells us about the cemetery’s physical organisation. It does not provide a full list of those buried there or their individual biographies."},{"type":"paragraph","text":"The catalogue entry for John Jacob’s grave in Jacobabad operates at another scale, identifying a particular monument and its marble enclosure. A famous name can orient a visitor, but it should not make every surrounding burial into an extension of the same person’s story."},{"type":"paragraph","text":"The difference between a cemetery record and a grave record matters in a digital archive. The former describes a landscape; the latter concerns a particular commemorative object. Linking them is useful, but merging them can obscure people who are less thoroughly documented."},{"type":"heading","level":2,"text":"Follow names into records carefully"},{"type":"paragraph","text":"The British Library’s India Office catalogue includes family and service-related records. One provident-fund register describes information about subscribers, spouses and children, while an ecclesiastical volume covers baptisms, marriages and burials in India and Pakistan after independence."},{"type":"paragraph","text":"These are examples of potentially relevant archival series, not proof that a person in Shahwala appears in them. Establishing a connection requires consulting the record and matching several details. A common surname or approximate age is not enough."},{"type":"paragraph","text":"The nature of the archive also shapes what survives. A pension record was created for an administrative purpose, not to provide a complete family history. People outside the relevant scheme may be absent. Absence from that register should not be mistaken for absence from the town."},{"type":"heading","level":2,"text":"Service is only one part of a life"},{"type":"paragraph","text":"An epitaph may emphasise rank or an employer because those were important to the people commissioning it. Other aspects of the person’s life may appear in a marriage register, a letter or a local account. The historian’s task is to connect evidence without pretending that every gap has been closed."},{"type":"paragraph","text":"For visitors, the most revealing detail may be a relationship rather than a title: a child’s age, a spouse named on the same marker, or a place mentioned far from the burial ground. Such details deserve accuracy and restraint, not invented scenes of grief."},{"type":"paragraph","text":"Cemeteries preserve movement through the people remembered in them, but they also preserve the choices of those who made the memorials. Reading both dimensions allows a landscape of graves to become a record of differentiated lives rather than a simplified monument to an institution or an empire."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["punjab-murree","sindh-jacobabad"],"provinceRegionIds":["punjab","sindh"],"relatedHeritageIds":["major-doam-6376","major-doam-4362"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Cemeteries as records of migration and service | Virsapur","description":"A cemetery can connect places of birth, work and death, but inscriptions need to be read alongside archival records. A single named officer cannot represent everyone buried nearby.","primaryKeyword":"cemetery migration history Pakistan","socialTitle":"Cemeteries as records of migration and service","socialDescription":"A cemetery can connect places of birth, work and death, but inscriptions need to be read alongside archival records. A single named officer cannot represent everyone buried nearby."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Shahwala Graveyard","url":"https://doam.gov.pk/public/sites/6376","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Grave of John Jacob","url":"https://doam.gov.pk/public/sites/4362","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"India Office Provident Fund: Complete Family Register of Subscribers","url":"https://searcharchives.bl.uk/catalog/040-000970788","publisher":"British Library, India Office Records","accessDate":"2026-10-22"},{"title":"India and Pakistan: Baptisms, Marriages, Burials, 1947–1950","url":"https://searcharchives.bl.uk/catalog/040-000116761","publisher":"British Library, India Office Records","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft; evidence-specific comparisons and explicit limits. No new ownership/access determinations or speculative biographies. ","editorialReason":"Examine inscriptions and archival records without treating all buried people as a homogeneous community.","sortOrder":224}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-shared-sacred-landscapes-without-a-myth-of-seamless-harmony','shared-sacred-landscapes-without-a-myth-of-seamless-harmony','review','{"id":"story-shared-sacred-landscapes-without-a-myth-of-seamless-harmony","type":"story","slug":"shared-sacred-landscapes-without-a-myth-of-seamless-harmony","title":"Shared sacred landscapes without a myth of seamless harmony","summary":"Different religious histories can occupy one landscape without proving uninterrupted harmony. A useful account distinguishes shared space, successive use and remembered attachment.","body":[{"type":"paragraph","text":"A landscape containing monuments associated with more than one religion can be described as shared, but the word needs explanation. Did communities use a place at the same time? Did one institution follow another? Do people living elsewhere retain an attachment to it? These are different relationships, and none is proved simply by placing several coloured pins on a map."},{"type":"paragraph","text":"Recognising coexistence matters. So does recognising change, unequal access and episodes of loss. An account that assumes either perfect harmony or permanent hostility before examining the evidence makes the landscape serve a conclusion rather than allowing it to complicate one."},{"type":"heading","level":2,"text":"Layers are not automatically encounters"},{"type":"paragraph","text":"The federal description of Katas Raj records temples, a sacred pool, other buildings and archaeological remains within the complex. Their presence creates a layered historical setting. It does not, by itself, establish that the people associated with every layer met there on equal terms."},{"type":"paragraph","text":"A construction sequence might show that one use followed another. A travel account might describe a particular encounter. An oral history might preserve an attachment maintained after migration. Each would add something different to the map."},{"type":"paragraph","text":"The distinction is practical as well as historical. A visitor route that passes several buildings is not necessarily a pilgrimage route shared by their religious communities. The itinerary belongs to the visitor unless evidence establishes another relationship."},{"type":"heading","level":2,"text":"A surviving structure and an absent journey"},{"type":"paragraph","text":"At Sharda in the Neelum Valley, the federal survey records a temple with a raised platform, substantial stonework and an enclosure. These material remains are a starting point for architectural study. They cannot alone explain every community’s relationship to the place or the changing possibilities of reaching it."},{"type":"paragraph","text":"A person can maintain a sacred attachment without being physically present. An archive should therefore not equate a small visible congregation, interrupted use or an empty photograph with a lack of significance. Equally, it should not invent contemporary access arrangements from historical descriptions of pilgrimage."},{"type":"paragraph","text":"The history of movement matters because a sacred landscape extends beyond the outline of a building. Paths, borders and the practical ability to travel can alter how people encounter a place."},{"type":"heading","level":2,"text":"Change can be part of the religious story"},{"type":"paragraph","text":"Schaflechner’s research on Hinglaj examines changing narratives and the making of religious space. Its relevance here is limited but important: a place’s identity need not be fixed once and for all. This is not a reason to transfer Hinglaj’s history onto Katas or Sharda; it is a reason to ask site-specific questions."},{"type":"paragraph","text":"A careful account identifies who is speaking, which period is being described and what kind of evidence supports the claim. If an older source uses a dismissive label for another community, that language should be examined rather than silently inherited."},{"type":"paragraph","text":"The aim is not to drain shared heritage of hope. It is to give that hope a credible foundation. Particular acts of care, hospitality or collaboration are more meaningful when documented precisely than when used to suggest that conflict never existed. A landscape can hold more than one attachment, and its history becomes richer when those attachments are allowed to remain distinct."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["punjab-chakwal","azad-kashmir-neelum"],"provinceRegionIds":["punjab","azad-kashmir"],"relatedHeritageIds":["major-doam-6750","major-doam-6633"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Shared sacred landscapes without a myth of seamless harmony | Virsapur","description":"Different religious histories can occupy one landscape without proving uninterrupted harmony. A useful account distinguishes shared space, successive use and remembered attachment.","primaryKeyword":"shared sacred landscapes Pakistan","socialTitle":"Shared sacred landscapes without a myth of seamless harmony","socialDescription":"Different religious histories can occupy one landscape without proving uninterrupted harmony. A useful account distinguishes shared space, successive use and remembered attachment."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Katas Raj Temples","url":"https://doam.gov.pk/public/sites/6750","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Sharda Temple","url":"https://doam.gov.pk/public/sites/6633","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Hinglaj Devi: Identity, Change, and Solidification at a Hindu Temple in Pakistan","url":"https://academic.oup.com/book/5901","publisher":"Oxford University Press; Jürgen Schaflechner","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft; evidence-specific comparisons and explicit limits. No new ownership/access determinations or speculative biographies. ","editorialReason":"Allow coexistence, change and conflict to be documented rather than romanticised.","sortOrder":225}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-changing-custodianship-of-a-religious-building','changing-custodianship-of-a-religious-building','review','{"id":"story-changing-custodianship-of-a-religious-building","type":"story","slug":"changing-custodianship-of-a-religious-building","title":"Changing custodianship of a religious building","summary":"Ownership, daily care and religious authority are different responsibilities. Understanding a building’s custodianship requires dated institutional evidence rather than assumptions based on who holds the key.","body":[{"type":"paragraph","text":"The person who opens a religious building for a visitor may know its daily needs better than anyone else. That does not mean the person is its legal owner, the authority responsible for structural conservation or the sole voice of a religious community. Custodianship is easier to understand when those responsibilities are separated."},{"type":"paragraph","text":"A building’s history can involve changes in all of them. Management may move between institutions; the people maintaining it may change; religious use may continue, stop or resume. The visible result can be a new sign, a repaired roof or a different use of a room, but the institutional history needs documentary evidence."},{"type":"heading","level":2,"text":"Several responsibilities can coexist"},{"type":"paragraph","text":"The ETPB’s published functions include maintaining property records, managing relevant trust property and supporting religious shrines and pilgrims. Its description of the Pakistan Sikh Gurdwara Parbandhak Committee sets out responsibilities concerning religious arrangements, care and pilgrimage."},{"type":"paragraph","text":"These institutional accounts illustrate a division of responsibilities. They should not be used to declare that every old temple or gurdwara belongs to one body, or that the same administrative relationship applies to every site. A particular claim requires the relevant record."},{"type":"paragraph","text":"For heritage interpretation, the distinction prevents a common shortcut: equating religious identity with a single modern owner. A building can have a clear historic affiliation while its present administrative position requires separate confirmation."},{"type":"heading","level":2,"text":"A catalogue is a dated source"},{"type":"paragraph","text":"The federal entries for Golra Sharif Temple and Said Pur Temple Complex draw on archaeological publications from the early 2010s. They describe architectural features and include ownership fields. Those fields are part of a catalogue record, not a current title investigation."},{"type":"paragraph","text":"The buildings also differ physically. The Said Pur entry describes a complex including temples and a dharamshala, whereas the Golra entry focuses on a temple and its sanctum. A change affecting one room or structure should not automatically be described as a transfer of the entire institution."},{"type":"paragraph","text":"Before writing that a building was “taken over,” an archive should ask what changed, when, through which documented action and according to whom. The phrase can otherwise merge a repair project, a temporary use and a formal administrative change into one misleading event."},{"type":"heading","level":2,"text":"Care has a history too"},{"type":"paragraph","text":"A maintenance ledger, a dated photograph or an account from a caretaker can preserve work that official summaries overlook. Who repaired a roof after rain? Who kept a room accessible? Who retained a key or preserved an inscription when a use changed?"},{"type":"paragraph","text":"These questions do not replace institutional records. They complement them by showing how responsibility was exercised in practice. An oral account should remain attributed, especially where it concerns contested decisions or another person’s actions."},{"type":"paragraph","text":"Visitors need the current institution’s guidance for access and recording. Researchers making ownership claims need appropriate documentary verification; this article is not advice on title or property rights."},{"type":"paragraph","text":"The most useful history of custodianship connects the formal and the everyday without confusing them. It explains not only who is named in a record, but how a building has been cared for, interpreted and made available to the people for whom it continues to matter."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["islamabad-islamabad"],"provinceRegionIds":["islamabad"],"relatedHeritageIds":["major-doam-6311","major-doam-6230"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Changing custodianship of a religious building | Virsapur","description":"Ownership, daily care and religious authority are different responsibilities. Understanding a building’s custodianship requires dated institutional evidence rather than assumptions based on who holds the key.","primaryKeyword":"religious heritage custodianship Pakistan","socialTitle":"Changing custodianship of a religious building","socialDescription":"Ownership, daily care and religious authority are different responsibilities. Understanding a building’s custodianship requires dated institutional evidence rather than assumptions based on who holds the key."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Functions of the Board","url":"https://etpb.gov.pk/functions/","publisher":"Evacuee Trust Property Board","accessDate":"2026-10-22"},{"title":"Pakistan Sikh Gurdwara Parbandhak Committee","url":"https://etpb.gov.pk/shrines/pakistan-sikh-gurdwara-parbandhak-committee-psgpc/","publisher":"Evacuee Trust Property Board","accessDate":"2026-10-22"},{"title":"Golra Sharif Temple","url":"https://doam.gov.pk/public/sites/6311","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Said Pur Temple Complex","url":"https://doam.gov.pk/public/sites/6230","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft; evidence-specific comparisons and explicit limits. No new ownership/access determinations or speculative biographies. ","editorialReason":"Explain institutional responsibility and historical change without offering legal advice.","sortOrder":226}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-abandoned-does-not-mean-ownerless','abandoned-does-not-mean-ownerless','review','{"id":"story-abandoned-does-not-mean-ownerless","type":"story","slug":"abandoned-does-not-mean-ownerless","title":"Abandoned does not mean ownerless","summary":"Disuse describes an activity, not the disappearance of rights or attachment. A quiet or damaged sacred building still requires permission, care and a precise account of its condition.","body":[{"type":"paragraph","text":"An empty doorway is not an invitation. A sacred building may appear unused during a brief visit, yet still have an owner, a caretaker, neighbours responsible for access or a community that remembers it from elsewhere. The word abandoned can conceal all of these relationships."},{"type":"paragraph","text":"It is also imprecise. Does it mean worship has stopped, the roof is damaged, no one lives nearby or a previous use has ended? Each describes a different condition. A heritage account becomes more useful when it names the observed situation rather than applying a dramatic label to the whole place."},{"type":"heading","level":2,"text":"Two records, different circumstances"},{"type":"paragraph","text":"The federal catalogue describes the temple at Harnoli through its brickwork, shikhara, paintings and inscriptions. It records private ownership. That does not establish present access arrangements, but it clearly gives no basis for treating the building as an unclaimed object."},{"type":"paragraph","text":"The Dalwal entry describes a temple and nearby samadhi and reports an altered use during the period documented by its source. It separately records government ownership. The two entries show why the visible state or religious affiliation of a building cannot be used to guess its administrative position."},{"type":"paragraph","text":"Both are dated records. Their condition descriptions should not be repeated as though someone inspected the buildings this morning. A current photograph can update part of the record, but it still cannot establish ownership from appearance."},{"type":"heading","level":2,"text":"Attachment can survive interrupted use"},{"type":"paragraph","text":"A family photograph, a remembered festival or an institution’s papers may connect people with a building they no longer regularly visit. That attachment is not disproved by a locked gate. Nor should the existence of a distant connection be used to ignore people currently responsible for the site."},{"type":"paragraph","text":"A useful enquiry asks about both. Who looks after the place now? Who has historical knowledge of it? What evidence explains a change of use? The answers may come from different people and may not agree completely."},{"type":"paragraph","text":"The ETPB’s published responsibilities include maintaining records and managing relevant trust property. This provides one example of why institutional enquiries matter. It does not establish that either of these particular temples falls within its control, and no such conclusion is made here."},{"type":"heading","level":2,"text":"Documentation is not salvage"},{"type":"paragraph","text":"A detached tile, carved fragment or broken fitting can seem vulnerable. Removing it as a keepsake or an improvised rescue destroys its relationship to the place and may prevent proper recording. The appropriate response is to report a concern to the responsible institution, not to appoint oneself custodian of the object."},{"type":"paragraph","text":"The same restraint applies to entry. A damaged stair, unfastened door or gap in a boundary is not confirmation that a visit is authorised or safe. Photographs taken from permitted positions can still contribute to a record without creating another risk."},{"type":"paragraph","text":"Better language changes the encounter. “No worship observed during this visit” is narrower than “abandoned forever.” “Roof missing in a dated survey” is more informative than “forgotten.” Such precision leaves room for people, rights and future care. It also prevents heritage discovery from becoming an excuse to treat vulnerable places as though no one has a claim on them."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["punjab-mianwali","punjab-chakwal"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-9934","major-doam-6754"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Abandoned does not mean ownerless | Virsapur","description":"Disuse describes an activity, not the disappearance of rights or attachment. A quiet or damaged sacred building still requires permission, care and a precise account of its condition.","primaryKeyword":"abandoned sacred buildings heritage","socialTitle":"Abandoned does not mean ownerless","socialDescription":"Disuse describes an activity, not the disappearance of rights or attachment. A quiet or damaged sacred building still requires permission, care and a precise account of its condition."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Hindu Temple, Harnoli","url":"https://doam.gov.pk/public/sites/9934","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Dalwal Temple-I","url":"https://doam.gov.pk/public/sites/6754","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Functions of the Board","url":"https://etpb.gov.pk/functions/","publisher":"Evacuee Trust Property Board","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft; evidence-specific comparisons and explicit limits. No new ownership/access determinations or speculative biographies. ","editorialReason":"Distinguish disuse, ownership and community attachment; avoid promoting unauthorised access.","sortOrder":227}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-religious-heritage-and-the-politics-of-naming','religious-heritage-and-the-politics-of-naming','review','{"id":"story-religious-heritage-and-the-politics-of-naming","type":"story","slug":"religious-heritage-and-the-politics-of-naming","title":"Religious heritage and the politics of naming","summary":"A sacred place can carry several names without having several identities. Recording aliases carefully can improve discovery while preserving religious affiliation and historical distinctions.","body":[{"type":"paragraph","text":"A place name is not merely a label attached after the history has been written. It can preserve a religious relationship, a personal name, a local pronunciation or the priorities of a later catalogue. Choosing one spelling for a map is useful; treating that choice as the only legitimate identity of the place is not."},{"type":"paragraph","text":"The problem becomes especially visible when a religious building is described through a broad category that obscures its affiliation. Calling every non-Muslim sacred structure a temple may make a list shorter, but it makes the history less precise."},{"type":"heading","level":2,"text":"One person, more than one name"},{"type":"paragraph","text":"The ASU Asian Art History record identifies the Gujranwala memorial associated with Atmaramji as a shrine of Acharya Vijayanandsuri. It explains that the two names refer to the same Jain religious figure. This is a useful case of an alias making a connection rather than creating a second monument."},{"type":"paragraph","text":"A searchable archive can retain Atmaramji as a familiar name while also recording Vijayanandsuri and the term samadhi. The relationship should be explained explicitly. Otherwise, readers may assume that a shrine, a samadhi and a memorial under another personal name are three different places."},{"type":"paragraph","text":"The ASU account also distinguishes the figure’s Jain institutional history. That specificity matters more than forcing the monument into a generic architectural category. Similarities with other memorial buildings do not make its religious affiliation interchangeable."},{"type":"heading","level":2,"text":"Names can outlive a use"},{"type":"paragraph","text":"A building may continue to be known by its former sacred name after another use begins. Conversely, a later administrative name can become more familiar locally than an older dedication. Neither circumstance permits the archive to erase the other period."},{"type":"paragraph","text":"The SOAS survey of Jain heritage demonstrates the importance of documenting institutions and funerary monuments as well as major temples. Its research scope provides a reason to look beyond familiar catalogue labels, not a licence to relabel a building without evidence."},{"type":"paragraph","text":"At Gori, the established temple name provides an entry point into a specific Jain complex. A transliteration variant should be linked as an alternative spelling where verified, not treated as a fresh place simply because a search engine returns it separately."},{"type":"heading","level":2,"text":"Preserve the source of each name"},{"type":"paragraph","text":"A practical record can distinguish a current institutional name, a historical name and a locally reported alias. It should state where each came from and avoid turning an unverified suggestion into the main title. Recording the original script, when securely read, can reduce confusion introduced by transliteration."},{"type":"paragraph","text":"Honorifics deserve similar care. They can be meaningful to a community without functioning as a separate personal name. Removing them everywhere may flatten the source; including every variant without explanation may make the record difficult to understand."},{"type":"paragraph","text":"Naming also affects whose history becomes discoverable. A reader searching for Jain heritage should be able to find a Jain memorial even if an older inventory used an imprecise category. The solution is a transparent correction with retained provenance, not a silent replacement that makes the earlier description impossible to trace."},{"type":"paragraph","text":"Good names do two things at once: they help people find the place and help them understand why it has been known in different ways."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["punjab-gujranwala","sindh-tharparkar"],"provinceRegionIds":["punjab","sindh"],"relatedHeritageIds":["major-doam-10109","major-doam-5499"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Religious heritage and the politics of naming | Virsapur","description":"A sacred place can carry several names without having several identities. Recording aliases carefully can improve discovery while preserving religious affiliation and historical distinctions.","primaryKeyword":"sacred place names Pakistan","socialTitle":"Religious heritage and the politics of naming","socialDescription":"A sacred place can carry several names without having several identities. Recording aliases carefully can improve discovery while preserving religious affiliation and historical distinctions."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Memorial shrine of Vijayanandsuri, late nineteenth–early twentieth century","url":"https://www.artworkarchive.com/profile/asu-asian-art-history/artwork/90-memorial-shrine-of-vijayanandsuri-late-19th-early-20th-c","publisher":"ASU Asian Art History","accessDate":"2026-10-22"},{"title":"Exploratory Survey of Jaina Heritage in Pakistan","url":"https://www.soas.ac.uk/research/exploratory-survey-jaina-heritage-pakistan","publisher":"SOAS University of London","accessDate":"2026-10-22"},{"title":"Gori Temple","url":"https://doam.gov.pk/public/sites/5499","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft; evidence-specific comparisons and explicit limits. No new ownership/access determinations or speculative biographies. ASU institutional collection confirms Atmaramji/Vijayanandsuri identity; former-use statement deliberately not treated as current.","editorialReason":"Explain aliases and respectful naming through documented cases without erasing community terminology.","sortOrder":228}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-what-a-saints-biography-can-and-cannot-date','what-a-saints-biography-can-and-cannot-date','review','{"id":"story-what-a-saints-biography-can-and-cannot-date","type":"story","slug":"what-a-saints-biography-can-and-cannot-date","title":"What a saint’s biography can and cannot date","summary":"A saint’s dates and a shrine’s construction dates answer different questions. Keeping separate timelines makes rebuilding, patronage and continuing devotion easier to understand.","body":[{"type":"paragraph","text":"A shrine page often begins with the life of the saint and then moves directly to a photograph of the present building. The transition can quietly imply that everything in the image belongs to the saint’s lifetime. That is rarely a conclusion the biography alone can support."},{"type":"paragraph","text":"A revered figure, an early burial or sacred association, the construction of a tomb and later additions are different events. Some may be well dated; others may be known only approximately. Keeping them separate produces a more informative history than forcing the whole place into one year."},{"type":"heading","level":2,"text":"Read what the source actually dates"},{"type":"paragraph","text":"The federal entry for Madhu Lal Hussain is primarily biographical: it identifies Shah Hussain as a Punjabi Sufi poet and locates the tomb in Lahore. Its broad period field does not supply a phase-by-phase date for the shrine’s fabric."},{"type":"paragraph","text":"The Auqaf account of Sakhi Sarwar, by contrast, describes a tomb and a later expansion. Even a short institutional summary can therefore distinguish the remembered person from subsequent building activity. The dates and attributions still need checking against fuller historical evidence before they are used to reconstruct an exact architectural sequence."},{"type":"paragraph","text":"The key question is grammatical as much as historical: what is the date attached to? A person’s death, an inscription, a donation, an opening ceremony and a repair campaign are not interchangeable events."},{"type":"heading","level":2,"text":"Build two timelines before combining them"},{"type":"paragraph","text":"One timeline can follow the figure and the development of the commemorative tradition. Another can follow the building: first documented structure, additions, repairs, losses and changes in use. Where the evidence securely connects them, the timelines can meet."},{"type":"paragraph","text":"For example, a donor’s inscription might establish that a gateway was built at a particular time. It would not automatically date the tomb chamber beyond it. A later account might describe an earlier shrine, but the date when that account was written must remain visible too."},{"type":"paragraph","text":"This method also prevents a modern restoration from disappearing. A renewed surface can retain an older design while being recent material. Both facts belong in the record."},{"type":"heading","level":2,"text":"Fabric can ask questions that biography cannot"},{"type":"paragraph","text":"Historic England’s analytical drawing guidance treats close observation and measurement as tools for understanding a building. Applied as a general method, it suggests looking for changes in masonry, blocked openings and relationships between walls. Such observations can support an investigation of sequence."},{"type":"paragraph","text":"They do not automatically provide calendar dates. A joint may show that one wall was built against another; it does not reveal the year without further evidence. Architectural comparison can suggest a period while remaining less precise than a securely read construction inscription."},{"type":"paragraph","text":"The reward for this care is a fuller account of the shrine. Later patronage becomes visible instead of being absorbed into the saint’s biography. Craftspeople, donors and communities who maintained the institution can enter the history."},{"type":"paragraph","text":"A shrine’s importance does not depend on every visible stone having witnessed the saint’s life. Continuing care, rebuilding and renewed devotion may be central to its significance. Accurate chronology allows that continuity to be described without confusing it with uninterrupted survival of the original fabric."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["punjab-dera-ghazi-khan","punjab-lahore"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-10103","major-doam-10203"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"What a saint’s biography can and cannot date | Virsapur","description":"A saint’s dates and a shrine’s construction dates answer different questions. Keeping separate timelines makes rebuilding, patronage and continuing devotion easier to understand.","primaryKeyword":"shrine chronology evidence","socialTitle":"What a saint’s biography can and cannot date","socialDescription":"A saint’s dates and a shrine’s construction dates answer different questions. Keeping separate timelines makes rebuilding, patronage and continuing devotion easier to understand."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Shrine of Hazrat Madhu Lal Hussain","url":"https://doam.gov.pk/public/sites/10203","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Hazrat Sakhi Sarwar, Dera Ghazi Khan","url":"https://auqaf.punjab.gov.pk/shrine-sakhi-sarwar","publisher":"Punjab Auqaf and Religious Affairs Department","accessDate":"2026-10-22"},{"title":"Drawing for Understanding","url":"https://historicengland.org.uk/images-books/publications/drawing-for-understanding/","publisher":"Historic England","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft; evidence-specific comparisons and explicit limits. No new ownership/access determinations or speculative biographies. DOAM Shah Hussain entry contains conflicting chronology (death before Jahangir reign); do not repeat that claim. Biography only used to demonstrate source scope.","editorialReason":"Separate the life of a revered figure from construction and rebuilding of the monument.","sortOrder":229}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-new-sacred-architecture-can-also-be-heritage','new-sacred-architecture-can-also-be-heritage','review','{"id":"story-new-sacred-architecture-can-also-be-heritage","type":"story","slug":"new-sacred-architecture-can-also-be-heritage","title":"New sacred architecture can also be heritage","summary":"Bhong Mosque shows why heritage value is not reserved for ancient buildings. Its twentieth-century construction brings patronage, craft and changing materials into the same architectural story.","body":[{"type":"paragraph","text":"A building does not have to be medieval to raise important heritage questions. Bhong Mosque in Rahim Yar Khan District is a twentieth-century work, yet its construction connects patronage, specialised craft and religious use in ways that deserve serious historical attention. Its relative youth makes some kinds of evidence more accessible, not its significance automatically smaller."},{"type":"paragraph","text":"The Aga Khan Award for Architecture records the project as beginning in 1932 under Rais Ghazi Mohammad and completed in 1982. The district’s official account also identifies its 1986 award. Those dates locate the mosque within modern history rather than requiring it to borrow the prestige of an imagined ancient origin."},{"type":"heading","level":2,"text":"Craft can continue through new work"},{"type":"paragraph","text":"The award record credits local master masons and craftspeople and describes specialists drawn from different places, including Rajasthan and Karachi. It also identifies a combination of traditional and modern materials across the compound. This is evidence of active making, not merely the conservation of an older structure."},{"type":"paragraph","text":"For a visitor, that changes the questions worth asking. Which work required specialist knowledge? How were different surfaces and techniques brought together? What records name the people responsible? The mosque can be approached as a history of labour and collaboration as well as patronage."},{"type":"paragraph","text":"A publication record held by the Chinese University of Hong Kong lists named master craftspeople in the award documentation. Their presence is a reminder that the phrase “local craftsmanship” should not erase individual makers when the archive can identify them."},{"type":"heading","level":2,"text":"Modern does not mean visually minimalist"},{"type":"paragraph","text":"Bhong’s elaborate appearance complicates the assumption that twentieth-century architecture must reject ornament. The award description recognises eclectic sources and a varied material vocabulary. The building therefore belongs to modern architectural history even where it draws on forms associated with earlier periods."},{"type":"paragraph","text":"That distinction is useful beyond this mosque. A newly made arch or decorative panel is not necessarily an unsuccessful imitation simply because it recalls an older example. The historical question concerns how and why it was selected, made and combined with other elements."},{"type":"paragraph","text":"Personal taste still has a place in the encounter. A viewer may find the density of ornament exhilarating or overwhelming. Neither reaction settles the building’s cultural significance. Understanding the work requires more than deciding whether it matches a preferred visual style."},{"type":"heading","level":2,"text":"Document before the evidence becomes distant"},{"type":"paragraph","text":"For comparatively recent religious buildings, construction photographs, correspondence and memories of the work may still be recoverable. Recording them can prevent later accounts from reducing a complex project to a single patron’s name or an award date."},{"type":"paragraph","text":"The distinction between the initial design and later alteration also matters. Maintenance, replacement and continued religious use will add further history. A material introduced during the original project should not be mistaken for a later repair merely because it appears modern."},{"type":"paragraph","text":"Bhong Mosque makes a strong case for treating heritage as an enquiry into significance rather than a competition in age. Its craftsmanship, patronage and place within twentieth-century architectural debate are substantial subjects in their own right. Taking those subjects seriously allows newer sacred architecture to enter the archive without pretending that it is older than it is."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["punjab-rahim-yar-khan"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-10370"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"New sacred architecture can also be heritage | Virsapur","description":"Bhong Mosque shows why heritage value is not reserved for ancient buildings. Its twentieth-century construction brings patronage, craft and changing materials into the same architectural story.","primaryKeyword":"modern sacred heritage Pakistan","socialTitle":"New sacred architecture can also be heritage","socialDescription":"Bhong Mosque shows why heritage value is not reserved for ancient buildings. Its twentieth-century construction brings patronage, craft and changing materials into the same architectural story."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Bhong Mosque","url":"https://the.akdn/en/how-we-work/our-agencies/aga-khan-trust-culture/akaa/bhong-mosque","publisher":"Aga Khan Award for Architecture","accessDate":"2026-10-22"},{"title":"Important Places: Bhong Mosque","url":"https://rykhan.punjab.gov.pk/important_places","publisher":"Government of Punjab, District Rahim Yar Khan","accessDate":"2026-10-22"},{"title":"1986 Aga Khan Award for Architecture publication record","url":"https://hkapi.lib.cuhk.edu.hk/items/d7c73c01-c59c-4811-b08c-392844acecf8","publisher":"Chinese University of Hong Kong Architecture Library","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft; evidence-specific comparisons and explicit limits. No new ownership/access determinations or speculative biographies. ","editorialReason":"Use documented modern craft patronage to challenge the assumption that age alone creates significance.","sortOrder":230}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-wooden-mosques-and-regional-building-knowledge','wooden-mosques-and-regional-building-knowledge','review','{"id":"story-wooden-mosques-and-regional-building-knowledge","type":"story","slug":"wooden-mosques-and-regional-building-knowledge","title":"Wooden mosques and regional building knowledge","summary":"Timber mosques reveal structural and craft knowledge, but shared materials do not make their histories or religious institutions interchangeable.","body":[{"type":"paragraph","text":"A timber column can carry a roof, organise a room and hold a carver’s decisions within the same piece of wood. Looking at a mosque through its construction therefore adds something that a list of founders and dates cannot. It brings the building into focus as a working assembly, made and maintained by people with particular skills."},{"type":"paragraph","text":"“Wooden mosque” is a useful starting description, not a complete architectural category. Timber may form posts and beams while stone or earth completes the walls. Carved surfaces need to be distinguished from the load-bearing system beneath them. A roof profile alone does not explain either the building’s structure or the religious life it accommodates."},{"type":"heading","level":2,"text":"Reading Chaqchan from the section"},{"type":"paragraph","text":"The Gilgit-Baltistan government’s account of Chaqchan Mosque in Khaplu describes lower winter prayer rooms, an upper main prayer hall and a surrounding verandah. It identifies a construction system combining timber with stone, adobe and mud. These details make the vertical arrangement particularly revealing: different enclosed and open spaces occur within one building, rather than everything being contained in a single monumental hall."},{"type":"paragraph","text":"An architectural section would show that arrangement more clearly than a frontal photograph. It would connect floor levels, supports, roof and verandah while leaving room to distinguish original fabric from repairs. This is also why a decorative close-up should be accompanied by a wider view. A beautifully carved member may otherwise appear to be a free-standing artwork rather than part of a spatial and structural sequence."},{"type":"heading","level":2,"text":"A shared material is not a shared biography"},{"type":"paragraph","text":"Amburiq in Shigar offers another perspective. UNESCO’s 2005 conservation award account described its building and courtyard being brought into use as a community museum following work by Aga Khan Cultural Services Pakistan. That dated description concerns a particular conservation outcome; it is not evidence that every historic mosque with timber construction has the same institutional role."},{"type":"paragraph","text":"Nor does timber architecture belong only to Baltistan. The federal archaeology catalogue records a wooden mosque at Maina Kalay in Bajaur, describing substantial columns in its verandah and a wooden screen. This provides a concrete comparison outside the linked Baltistan sites. Similar questions about support, enclosure and workmanship can be asked there without claiming that its craftsmen came from Khaplu or followed an identical building tradition."},{"type":"paragraph","text":"The productive comparison is between decisions: how a roof is supported, how light enters, how a threshold is shaped, where carving is concentrated. A claim about the transmission of skills would require further evidence, such as named makers, dated repairs or closely documented connections between workshops."},{"type":"heading","level":2,"text":"Keeping repair visible"},{"type":"paragraph","text":"For a heritage record, timber should be described as carefully as masonry. A replacement post is not necessarily a failure of authenticity; its meaning depends on why and how it was introduced. Equally, an attractive new carving should not silently acquire the age of the building around it."},{"type":"paragraph","text":"The result is a richer way of seeing northern mosques: not as interchangeable “mountain-style” monuments, but as buildings whose materials, seasonal spaces, custodians and repair histories deserve to be understood together."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["gilgit-baltistan-ghanche","gilgit-baltistan-shigar","khyber-pakhtunkhwa-swat"],"provinceRegionIds":["gilgit-baltistan","khyber-pakhtunkhwa"],"relatedHeritageIds":["major-doam-7969","major-doam-8229","major-doam-10332"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Wooden mosques and regional building knowledge | Virsapur","description":"Timber mosques reveal structural and craft knowledge, but shared materials do not make their histories or religious institutions interchangeable.","primaryKeyword":"wooden mosques Baltistan","socialTitle":"Wooden mosques and regional building knowledge","socialDescription":"Timber mosques reveal structural and craft knowledge, but shared materials do not make their histories or religious institutions interchangeable."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Chaqchan Mosque","url":"https://visitgilgitbaltistan.gov.pk/tour/id/67","publisher":"Government of Gilgit-Baltistan","accessDate":"2026-10-22"},{"title":"2005 Asia-Pacific Heritage Conservation Award winners","url":"https://articles.unesco.org/sites/default/files/medias/fichiers/2023/06/2005-winners.pdf","publisher":"UNESCO","accessDate":"2026-10-22"},{"title":"Maina Kalay Wooden Mosque","url":"https://doam.gov.pk/public/sites/1730","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM Kalam live fetch failed; do not invent construction or institutional specifics. Amburiq museum use is explicitly the 2005 award account, not current access advice. Chaqchan founder traditions and broad style labels not adopted as established facts.","editorialReason":"Explore shared construction knowledge while retaining each mosque’s institutional context.","sortOrder":231}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-temple-sculpture-removed-from-its-original-setting','temple-sculpture-removed-from-its-original-setting','review','{"id":"story-temple-sculpture-removed-from-its-original-setting","type":"story","slug":"temple-sculpture-removed-from-its-original-setting","title":"Temple sculpture removed from its original setting","summary":"A carved fragment can preserve exceptional workmanship while losing the architectural relationships that once made it legible.","body":[{"type":"paragraph","text":"A temple fragment displayed at eye level offers an intimacy its original setting may never have allowed. Tool marks, a small figure or the turn of a carved leaf become easier to examine. Yet the same move can conceal its purpose. Was the stone above a doorway, beneath a roof, beside a deity or part of a procession of images? Close visibility does not automatically restore context."},{"type":"paragraph","text":"Murti Hill in the Salt Range makes this problem unusually tangible. The federal archaeology catalogue describes carved red-sandstone architectural pieces, including elements identified as columns, brackets and architraves. It also records earlier removal of sculptural material for reuse at Katas and Choa Saidan Shah. The history is therefore not simply a movement from an intact temple into a modern museum."},{"type":"heading","level":2,"text":"Several histories inhabit one stone"},{"type":"paragraph","text":"A fragment has at least three histories to investigate: its manufacture and first installation, any later reuse, and its collection or documentation. These histories may have different levels of certainty. A stylistic date for carving does not establish when a piece left its building, while a museum inventory date does not necessarily reveal when it entered the collection."},{"type":"paragraph","text":"The American Institute of Indian Studies’ photographic archive provides another kind of evidence. Its documentation of Chandigarh Museum includes works catalogued under Murti, Salt Range: architectural fragments, pillar elements, a doorjamb and figural pieces. The catalogue assigns different date ranges to different objects. That variety is a reason to examine individual records, not to compress the entire group into a single neatly dated structure."},{"type":"paragraph","text":"A museum photograph establishes that a particular object was documented in that setting. It does not, by itself, establish a complete chain of ownership. Nor does a shared place-name prove that every fragment came from the same doorway or building phase."},{"type":"heading","level":2,"text":"What a useful fragment record preserves"},{"type":"paragraph","text":"Getty’s Object ID guidance separates identification fields such as material, measurements, inscriptions and distinguishing features, and recommends recording origin or discovery information and related documentation. Those distinctions are valuable here. “From Murti” should be accompanied by the source of that attribution, rather than appearing as an unexplained certainty."},{"type":"paragraph","text":"A broken edge can be informative without becoming an invitation to speculative reconstruction. Dimensions, surviving joints and old photographs may support a proposed relationship between pieces. Decorative resemblance alone is weaker evidence: workshops can repeat motifs, and fragments from separate structures can look persuasive when arranged together."},{"type":"paragraph","text":"For an online display, a detail image should therefore sit beside an overall view and a caption identifying the holding institution, inventory information where available, and the limits of the attribution. A reconstruction should be visibly labelled as a hypothesis, with the evidence supporting each join made accessible."},{"type":"heading","level":2,"text":"Looking without possessing"},{"type":"paragraph","text":"The linked Murti and Malot records offer entry points into the Salt Range’s architectural heritage, not opportunities to search for portable souvenirs. A displaced stone can still illuminate a building tradition, but removing another piece would erase relationships that future research might recover."},{"type":"paragraph","text":"The strongest encounter is consequently double: appreciate the carving, then ask what the display cannot show. That question turns an isolated object back toward its architectural and documentary world."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["punjab-chakwal"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-9766","major-doam-6535"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Temple sculpture removed from its original setting | Virsapur","description":"A carved fragment can preserve exceptional workmanship while losing the architectural relationships that once made it legible.","primaryKeyword":"displaced temple sculpture","socialTitle":"Temple sculpture removed from its original setting","socialDescription":"A carved fragment can preserve exceptional workmanship while losing the architectural relationships that once made it legible."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Murti Hill","url":"https://doam.gov.pk/public/sites/9766","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Chandigarh Museum: Murti, Salt Range photographs","url":"https://vmis.in/ArchiveCategories/collection_gallery_parent?count=24&id=1366&maxrange=0&minrange=0&siteid=7365","publisher":"American Institute of Indian Studies, Center for Art and Archaeology","accessDate":"2026-10-22"},{"title":"Introduction to Object ID","url":"https://www.getty.edu/publications/resources/virtuallibrary/0892365722.pdf","publisher":"Getty Information Institute","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAM classification/chronology and VMIS date ranges differ; no harmonised foundation date or universal religious identity invented. VMIS is documentation of objects, not proof of their legal transfer. No collection encouragement.","editorialReason":"Discuss architectural fragments and provenance without encouraging collecting or speculative reconstruction.","sortOrder":232}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-pilgrimage-paths-and-the-places-between-monuments','pilgrimage-paths-and-the-places-between-monuments','review','{"id":"story-pilgrimage-paths-and-the-places-between-monuments","type":"story","slug":"pilgrimage-paths-and-the-places-between-monuments","title":"Pilgrimage paths and the places between monuments","summary":"Pilgrimage is made through stops, supplies and organised movement as well as the destination monument; different journeys require different evidence.","body":[{"type":"paragraph","text":"A map pin makes a pilgrimage destination look self-contained. The journey that gives it meaning is rarely so compact. Departure, waiting, food, rest and the order of visits can matter alongside arrival. To interpret those relationships, a heritage map needs evidence for movement rather than a decorative line joining famous sacred places."},{"type":"paragraph","text":"Panja Sahib and Hinglaj illustrate different kinds of documentation. They should not be combined into one historical route, nor treated as equivalent experiences merely because both involve pilgrimage. Their records instead show how carefully bounded accounts can reveal the places between monuments."},{"type":"heading","level":2,"text":"An itinerary is a document, not an eternal route"},{"type":"paragraph","text":"An SGPC departure notice for a Khalsa Sajna Diwas jatha names a sequence including Nankana Sahib, Sacha Sauda, Panja Sahib and later visits associated with Lahore and other gurdwaras. It records planned stays and the main congregation, as well as supplies sent with the group. This is evidence of an organised journey with an institutional framework, not simply individual movement towards one shrine."},{"type":"paragraph","text":"The distinction matters when reading a map. A planned visit is not proof that every participant completed it. A listed overnight location is not a guarantee of accommodation for an independent visitor. Most importantly, an archived programme cannot be used as a current timetable merely because the festival recurs."},{"type":"paragraph","text":"The notice makes another point visible: religious travel includes coordination and provisioning. Supplies are not an incidental backdrop to devotion. They help a group undertake the journey together, connecting the departure institution with the sites at which its members will gather."},{"type":"heading","level":2,"text":"At Hinglaj, movement exceeds the road"},{"type":"paragraph","text":"Associated Press’s reporting from the April 2024 Hinglaj festival describes pilgrims arriving by bus, continuing on foot where vehicles could not take them, and encountering temporary food and drink stalls. It also records ritual activity at a mud volcano and the Hingol River. This dated observation places the cave shrine within a wider landscape of movement and worship."},{"type":"paragraph","text":"The report should not become a universal checklist of compulsory acts. Individuals may travel for different reasons and participate differently. Nor does an observed walking segment establish an ancient path unchanged over centuries. Its value is more precise: it shows that a modern road journey can still contain other kinds of movement, waiting and bodily effort."},{"type":"heading","level":2,"text":"The infrastructure between destinations"},{"type":"paragraph","text":"Historical resting places deserve attention in their own right. Sarai Kharbuza, documented in the federal archaeology catalogue, provides a comparative example of roadside accommodation heritage. That does not establish it as a stop on either pilgrimage discussed here. Connecting it to a particular group would require an itinerary, inscription, account or other evidence linking the two."},{"type":"paragraph","text":"Water points, kitchens and lodging become historical evidence when such connections can be demonstrated. Without them, a plausible-looking route risks presenting modern assumptions as inherited geography."},{"type":"paragraph","text":"A more honest discovery experience allows several layers to remain distinct: the shrine, a documented journey, an observed festival and the infrastructure of travel. Their intersections can be meaningful without being forced into a single continuous line."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["balochistan-lasbela","punjab-attock"],"provinceRegionIds":["balochistan","punjab"],"relatedHeritageIds":["major-doam-9186","major-doam-7658"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Pilgrimage paths and the places between monuments | Virsapur","description":"Pilgrimage is made through stops, supplies and organised movement as well as the destination monument; different journeys require different evidence.","primaryKeyword":"pilgrimage route heritage Pakistan","socialTitle":"Pilgrimage paths and the places between monuments","socialDescription":"Pilgrimage is made through stops, supplies and organised movement as well as the destination monument; different journeys require different evidence."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"SGPC jatha departs for Khalsa Sajna Diwas at Panja Sahib","url":"https://sgpc.net/sgpc-jatha-departs-for-celebrating-khalsa-sajna-diwas-at-gurdwara-sri-panja-sahib-pakistan/","publisher":"Shiromani Gurdwara Parbandhak Committee","accessDate":"2026-10-22"},{"title":"A Hindu festival in southwestern Pakistan brings a mountainous region to life","url":"https://apnews.com/article/bbebc541b403875a15c675bab353821c","publisher":"Associated Press, firsthand reporting, 28 April 2024","accessDate":"2026-10-22"},{"title":"Sarai Kharbuza","url":"https://doam.gov.pk/public/sites/6227","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"AP contribution kept under100 words; SGPC extracted page lacks year, so no year/current itinerary supplied. Sarai is explicitly comparative, not claimed as a documented stop for either linked pilgrimage. No cross-country route generated.","editorialReason":"Study rest, water and movement with verified historical evidence rather than inventing a continuous route.","sortOrder":233}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-conserving-a-sacred-building-with-its-community','conserving-a-sacred-building-with-its-community','review','{"id":"story-conserving-a-sacred-building-with-its-community","type":"story","slug":"conserving-a-sacred-building-with-its-community","title":"Conserving a sacred building with its community","summary":"Conservation must decide how a building will continue to matter, not simply how its repaired surfaces will look.","body":[{"type":"paragraph","text":"Conserving a sacred building begins with a difficult question: what, exactly, needs to continue? The answer may include historic fabric, worship, a community’s relationship with a place, or the knowledge needed to maintain it. These aims can support one another, but they are not identical. A technically excellent repair cannot alone decide how a room should be used."},{"type":"paragraph","text":"Amburiq Mosque in Shigar is useful because its conservation record does not fit a simple story of returning an old monument to an unchanged past. UNESCO’s 2005 award announcement described the restored building and courtyard as a community museum. That is a specific account of renewed use at the time of recognition, rather than a general claim that museum conversion is appropriate for sacred buildings."},{"type":"heading","level":2,"text":"Start with the people who use and care for it"},{"type":"paragraph","text":"A practical conservation brief should identify who holds responsibility for the building and who experiences its daily operation. Custodians, worshippers, neighbours, craftspeople and visitors may ask different questions. Consultation becomes meaningful when those questions can affect decisions about access, materials, interpretation and future care."},{"type":"paragraph","text":"Consider a doorway. A conservation team may focus on its damaged frame; a caretaker may be concerned about closing it securely; a regular user may need assistance crossing its threshold. None of these concerns is answered by a photograph of the finished entrance. They need to be discussed together, with a record of the choices and their consequences."},{"type":"paragraph","text":"This is an approach to planning, not a claim about undocumented meetings at Amburiq. The award account establishes a conservation outcome; reconstructing the full decision-making process would require project records and testimony from participants."},{"type":"heading","level":2,"text":"What a bathhouse can—and cannot—teach a mosque"},{"type":"paragraph","text":"Lahore’s Shahi Hammam provides a deliberately different comparison. It is a historic public bathhouse, not a mosque. UNESCO’s 2016 award profile records structural conservation, the treatment of frescoes and interpretation of excavated underground features. Its presentation helps visitors understand how the bathhouse functioned."},{"type":"paragraph","text":"The comparison is valuable because conservation involves both fabric and explanation. A visitor can see a repaired surface without understanding a building’s former use. At the hammam, interpretation connects the visible rooms with systems that would otherwise remain obscure. At a sacred site, the equivalent task might involve explaining a space without interrupting or reducing its religious significance."},{"type":"paragraph","text":"The difference is equally important. A method for presenting archaeological bathhouse features cannot simply be transferred to a room still required for worship. An exhibit, barrier or visitor route needs to be assessed against the particular use of the space."},{"type":"heading","level":2,"text":"The project continues after the award"},{"type":"paragraph","text":"A repaired roof creates future obligations: inspection, maintenance, documentation and decisions about the next intervention. A display creates others, including updating its account and ensuring that local knowledge is not frozen at the date of opening."},{"type":"paragraph","text":"For readers, the most useful conservation story therefore includes more than a dramatic before-and-after image. It explains the building’s purpose, what changed, who was involved where that is documented, and what remains uncertain. The ambition is not to make a sacred building look untouched. It is to make care legible while allowing the place to retain a meaningful life."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["gilgit-baltistan-shigar","punjab-lahore"],"provinceRegionIds":["gilgit-baltistan","punjab"],"relatedHeritageIds":["major-doam-8229","major-doam-9778"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Conserving a sacred building with its community | Virsapur","description":"Conservation must decide how a building will continue to matter, not simply how its repaired surfaces will look.","primaryKeyword":"community sacred heritage conservation","socialTitle":"Conserving a sacred building with its community","socialDescription":"Conservation must decide how a building will continue to matter, not simply how its repaired surfaces will look."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"2005 Asia-Pacific Heritage Conservation Award winners","url":"https://articles.unesco.org/sites/default/files/medias/fichiers/2023/06/2005-winners.pdf","publisher":"UNESCO","accessDate":"2026-10-22"},{"title":"Project profiles for 2016 UNESCO Heritage Award winners","url":"https://articles.unesco.org/sites/default/files/medias/fichiers/2023/06/2016-winners_1.pdf","publisher":"UNESCO","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Amburiq 2005 account used under100 words cumulatively with230. Shahi Hammam expressly a bathhouse comparator, not relabelled sacred. Consultation framework is editorial analysis, not a claimed project participation history. No current access/use promise.","editorialReason":"Focus on consultation and continued use rather than treating a living site as an empty monument.","sortOrder":234}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-shrine-courtyard-as-social-space','the-shrine-courtyard-as-social-space','review','{"id":"story-the-shrine-courtyard-as-social-space","type":"story","slug":"the-shrine-courtyard-as-social-space","title":"The shrine courtyard as social space","summary":"A shrine courtyard holds movement, waiting and practical services as well as ceremonial attention; its social life cannot be read from a plan alone.","body":[{"type":"paragraph","text":"A shrine courtyard can look empty in an architectural photograph and crowded in a festival image. Neither view is a complete account of the place. A courtyard is a setting in which people move, wait, meet and orient themselves towards a sacred centre. Its significance depends partly on activities that a plan can locate but cannot fully explain."},{"type":"paragraph","text":"Data Darbar in Lahore and Baba Farid’s shrine in Pakpattan offer different scales of inquiry. They are not interchangeable examples of an undifferentiated “Sufi atmosphere.” Their entrances, administrative arrangements and relationships with surrounding spaces require separate attention."},{"type":"heading","level":2,"text":"The practical life of an open space"},{"type":"paragraph","text":"A Punjab government planning document for Data Darbar lists courtyard and covered prayer spaces alongside water supply, drainage, ablution facilities, shoe storage and food distribution. It is a brief for evaluating and improving infrastructure, not a certificate that every proposed improvement was completed. Even so, the list reveals how many systems support the apparent simplicity of a gathering space."},{"type":"paragraph","text":"Shoe storage, for example, sits at the intersection of movement and a change in bodily practice. A queue there can affect the experience of arrival even when it lies outside the photograph’s central frame. Drainage and cleaning similarly influence whether an open surface remains usable. These are not lesser subjects than the ornament of a gateway; they help explain how the complex works."},{"type":"paragraph","text":"The planning record does not tell us how each visitor feels. A person waiting may be resting, accompanying someone, seeking assistance or preparing to enter. Assigning one motive to everybody in a crowd would turn an observable arrangement into an invented collective experience."},{"type":"heading","level":2,"text":"Thresholds organise attention"},{"type":"paragraph","text":"Auqaf’s description of Baba Farid’s shrine identifies two named doors, Nuri Darwaza and Bahishti Darwaza. Such names show that an entrance can carry a significance beyond its position in a wall. The physical opening and its religious associations belong to related but different kinds of description."},{"type":"paragraph","text":"A careful account would connect the doorway to documented practice while avoiding the assumption that a historic name guarantees unrestricted access. It would also show the surrounding spaces through which people approach, rather than reducing the shrine to the tomb chamber alone."},{"type":"paragraph","text":"At Data Darbar, an APP report of the Auqaf secretary’s Ramadan 2026 briefing described application-based arrangements for Itikaf, space constraints during construction and separate provision for women. This is a dated administrative account, not a permanent rule for all visitors. It nevertheless demonstrates that shared sacred space is actively organised rather than socially uniform."},{"type":"heading","level":2,"text":"Observe relationships, not just crowds"},{"type":"paragraph","text":"To study a courtyard, it helps to follow relationships: entrance to shoe storage, shade to waiting area, food distribution to circulation, open space to covered prayer hall. Those connections explain why even a modest change can affect more than the square metres it occupies."},{"type":"paragraph","text":"The courtyard’s heritage is consequently neither an empty architectural void nor a picturesque mass of people. It lies in the meeting of built form, care, devotion and ordinary practical needs. Recognising those layers makes room for individual experiences instead of treating everyone present as scenery."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":["punjab-lahore","punjab-pakpattan"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-10200","major-doam-9694"],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"The shrine courtyard as social space | Virsapur","description":"A shrine courtyard holds movement, waiting and practical services as well as ceremonial attention; its social life cannot be read from a plan alone.","primaryKeyword":"shrine courtyard heritage","socialTitle":"The shrine courtyard as social space","socialDescription":"A shrine courtyard holds movement, waiting and practical services as well as ceremonial attention; its social life cannot be read from a plan alone."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Integrated Development Planning and Revamping of Data Darbar Complex, Lahore: PC-II","url":"https://pnd.punjab.gov.pk/system/files/Auqaf%29%20Integrated%20Development%20Planning%20%26%20Revamping%20of%20Data%20Darbar%20Complex%2C%20Lahore%20%28PC-II%29.pdf","publisher":"Planning and Development Board, Government of Punjab","accessDate":"2026-10-22"},{"title":"Hazrat Baba Fariduddin Masud Gunj Shakar, Pakpattan","url":"https://auqaf.punjab.gov.pk/shrine-baba-farid","publisher":"Auqaf and Religious Affairs Department, Punjab","accessDate":"2026-10-22"},{"title":"Itikaf arrangements at Data Darbar","url":"https://www.app.com.pk/punjab/2600-apply-for-itikaf-at-data-darbar-1200-selected-auqaf-secretary/","publisher":"Associated Press of Pakistan, reporting the Auqaf secretary","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"PC-II indexed substantive scope read; direct PDF403, explicitly planning not completion. APP dated Ramadan2026 report treated as attributed administrative statement. Auqaf Baba Farid page contains problematic biography (Ibn Battuta meeting); only physical doors/location used.","editorialReason":"Distinguish documented social uses from assumptions about a single shared experience.","sortOrder":235}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-sacred-calendars-and-administrative-calendars','sacred-calendars-and-administrative-calendars','review','{"id":"story-sacred-calendars-and-administrative-calendars","type":"story","slug":"sacred-calendars-and-administrative-calendars","title":"Sacred calendars and administrative calendars","summary":"An anniversary, a moon-sighting notice and a travel application deadline answer different questions; a useful heritage calendar keeps them separate.","body":[{"type":"paragraph","text":"A historical account may explain why a community marks an anniversary without telling a visitor when this year’s gathering will take place. A calendar adds another layer: it translates an observance into dates. Organisers then add their own arrangements, including start times, application deadlines and access conditions. Treating these as one kind of information is a common source of confusion."},{"type":"paragraph","text":"For heritage readers, the essential distinction is between meaning and scheduling. A festival’s historical significance may remain relevant for many years. The practical details attached to one edition can expire almost immediately."},{"type":"heading","level":2,"text":"Observation is not the same as a forecast"},{"type":"paragraph","text":"Pakistan’s Ministry of Religious Affairs publishes notices about arrangements for moon sighting. The Meteorological Department also issues documents describing coordinates and the chance of seeing a new moon. The titles themselves identify different tasks: organising an observation process and supplying astronomical or visibility information."},{"type":"paragraph","text":"A predicted possibility should not silently become a confirmed religious date in a public calendar. Nor should a notice from one year be copied into another because the month-name is unchanged. The original calendar designation and the corresponding civil date should remain connected to the issuing source."},{"type":"paragraph","text":"This does not mean that every religious tradition uses the same calendar or the same method of confirmation. A heritage platform should describe the specific observance being discussed, rather than assume that one rule governs every shrine, gurdwara, temple or church."},{"type":"heading","level":2,"text":"The administrative clock can start much earlier"},{"type":"paragraph","text":"An archived SGPC announcement extended a January 2023 passport-submission deadline for a pilgrimage associated with Khalsa Sajna Diwas later that year. The deadline was not the festival date. It belonged to the preparation of an organised journey."},{"type":"paragraph","text":"That difference is easy to lose when a search result shows a sacred occasion beside a prominent date. A reader may mistake an application notice for an event listing, or a departure date for the day of the main congregation. Retaining the action attached to each date—apply, depart, gather, return—makes the record much clearer."},{"type":"paragraph","text":"Auqaf’s website likewise separates dated news announcements from general descriptions of shrines. Its notices identify particular Urs ceremonies and years. A historical profile and a practical announcement can complement one another without either being made to carry information it does not contain."},{"type":"heading","level":2,"text":"A calendar needs a history of its own"},{"type":"paragraph","text":"A useful event record should retain the source, the date it was checked, the year of the observance and whether the information is proposed or confirmed. If organisers change a schedule, the previous entry should be recognisable as superseded rather than quietly reused."},{"type":"paragraph","text":"For an archive, an expired event is not worthless. It can document how a gathering was organised at a particular moment. Its value simply changes from planning information to historical evidence."},{"type":"paragraph","text":"The reader’s final question should therefore be precise: am I learning about an observance, consulting a past programme, or checking an announcement for an upcoming visit? Those are all worthwhile activities. Keeping them distinct respects both the religious occasion and the practical realities of attending it."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Sacred calendars and administrative calendars | Virsapur","description":"An anniversary, a moon-sighting notice and a travel application deadline answer different questions; a useful heritage calendar keeps them separate.","primaryKeyword":"religious festival dates Pakistan heritage","socialTitle":"Sacred calendars and administrative calendars","socialDescription":"An anniversary, a moon-sighting notice and a travel application deadline answer different questions; a useful heritage calendar keeps them separate."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Arrangements for sighting the moon of Ramadan 1447 AH / 2026","url":"https://www.mora.gov.pk/NewsDetail/ZTk4OGVhOGMtMjYzNi00M2ZiLTg1ZTYtODJiYWNiYTI2Y2Ji","publisher":"Ministry of Religious Affairs and Interfaith Harmony, Pakistan","accessDate":"2026-10-22"},{"title":"Coordinates and chance for sighting the new moon of Safar1447 AH","url":"https://cdpc.pmd.gov.pk/SAFAR_1447_AH.pdf","publisher":"Pakistan Meteorological Department","accessDate":"2026-10-22"},{"title":"Pilgrims can deposit passports up to January11 for Khalsa Sajna Diwas pilgrimage","url":"https://new.sgpc.net/pilgrims-willing-to-visit-sikh-shrines-in-pakistan-on-khalsa-sajna-diwas-can-now-deposit-passports-up-to-january-11/","publisher":"Shiromani Gurdwara Parbandhak Committee","accessDate":"2026-10-22"},{"title":"Auqaf highlights and dated Urs announcements","url":"https://auqaf.punjab.gov.pk/index.php/","publisher":"Auqaf and Religious Affairs Department, Punjab","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Some direct pages fail but indexed titles/text support bounded examples; no current event date provided. SGPC example explicitly January2023 not thisyear. Administrative framework original explanatory analysis, not legal/travel advice.","editorialReason":"Explain why historical accounts do not establish this year’s event dates or visitor access.","sortOrder":236}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-photographing-sacred-art-without-losing-its-context','photographing-sacred-art-without-losing-its-context','review','{"id":"story-photographing-sacred-art-without-losing-its-context","type":"story","slug":"photographing-sacred-art-without-losing-its-context","title":"Photographing sacred art without losing its context","summary":"A responsible photograph records more than an attractive surface: it preserves context, respects restrictions and distinguishes permission from attribution.","body":[{"type":"paragraph","text":"A photograph can make sacred art visible while making its setting disappear. A carved panel becomes a pattern; an inscription becomes a texture; a ritual object becomes an attractive shape. The problem is not that close-up photography is inherently disrespectful. It is that a photograph needs enough information around it to explain what has been selected and what has been left out."},{"type":"paragraph","text":"The first decision happens before framing the image: should this object or activity be photographed for the intended use? Permission to enter a building is not automatically permission to photograph everything inside it, and a permitted personal photograph is not necessarily cleared for a public website."},{"type":"heading","level":2,"text":"Ask about the intended use"},{"type":"paragraph","text":"An institution’s rules and a community’s expectations may concern different things. A caretaker may explain where photography is allowed. A person appearing prominently in the image may have a separate view about publication. A collection record may specify a photographer’s credit without supplying unrestricted reuse rights."},{"type":"paragraph","text":"For a heritage publication, the request should therefore name the intended context: an educational article, a promotional banner, a social post or an archive. The answer should be recorded with the image. That is more useful than an ambiguous note saying only “permission obtained.”"},{"type":"paragraph","text":"The 2004 edition of ICOM’s museum ethics code, published in 2017, provides a relevant historical benchmark. Its sections on sacred material and interpretation call for respect for originating communities and careful presentation. ICOM has since revised its code, so this older edition should be identified rather than presented as the latest text. The underlying issue remains concrete: visibility is a decision with consequences."},{"type":"heading","level":2,"text":"Make a sequence, not only a hero image"},{"type":"paragraph","text":"Getty’s Object ID guidance emphasises both overall photographs and identifying details, alongside written information about the object. Applied to sacred art, that suggests a useful sequence: an authorised contextual view, an overall view of the work and a detail that answers a particular question."},{"type":"paragraph","text":"A close-up of an inscription, for example, should not be captioned as a complete translation if part of the text lies outside the frame. A detail of painted decoration should identify the room or surface to which it belongs. The image sequence can preserve this relationship without publishing every part of the site."},{"type":"paragraph","text":"Scale also matters. A tiny ornament photographed to fill the screen can look like a monumental relief. Measurements or a carefully worded caption can correct the impression without placing an intrusive object next to the artwork."},{"type":"heading","level":2,"text":"Keep the caption accountable"},{"type":"paragraph","text":"A useful caption distinguishes the work, its location, its attribution and the photograph’s date and maker. If an identification is uncertain, that uncertainty belongs in the caption rather than disappearing behind a confident title. If the photograph records a restoration state, it should not be used to imply that the same surface survives unchanged."},{"type":"paragraph","text":"The finished image should invite attention, not pretend to exhaust the object’s meaning. Sometimes the most responsible result is a photograph with a narrower crop, a restricted audience or no public image at all. Context and restraint are part of visual quality, not obstacles to it."}],"primaryCategoryId":"archive-category-sacred-heritage","categoryIds":["archive-category-sacred-heritage"],"tags":["Sacred Heritage"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"sacred","seo":{"title":"Photographing sacred art without losing its context | Virsapur","description":"A responsible photograph records more than an attractive surface: it preserves context, respects restrictions and distinguishes permission from attribution.","primaryKeyword":"sacred art photography ethics","socialTitle":"Photographing sacred art without losing its context","socialDescription":"A responsible photograph records more than an attractive surface: it preserves context, respects restrictions and distinguishes permission from attribution."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"ICOM Code of Ethics for Museums,2004 revision/2017 publication","url":"https://icom.museum/wp-content/uploads/2018/07/ICOM-code-En-web.pdf","publisher":"International Council of Museums","accessDate":"2026-10-22"},{"title":"Introduction to Object ID","url":"https://www.getty.edu/publications/resources/virtuallibrary/0892365722.pdf","publisher":"Getty Information Institute","accessDate":"2026-10-22"},{"title":"ICOM Code of Ethics: revision status","url":"https://icom.museum/en/resources/standards-guidelines/code-of-ethics/","publisher":"International Council of Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Historical2004 code edition identified rather than falsely current (2026 revisionexists). ICOM-derivedcontent under150, Gettycumulative231+236under180. Practical photo workflow editorialframework; not legaladvice. No newphotos or permissionclaim.","editorialReason":"Develop an institution- and community-informed framework for consent, captioning and attribution.","sortOrder":237}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-punjabi-across-more-than-one-script','punjabi-across-more-than-one-script','review','{"id":"story-punjabi-across-more-than-one-script","type":"story","slug":"punjabi-across-more-than-one-script","title":"Punjabi across more than one script","summary":"Shahmukhi and Gurmukhi make Punjabi visible through different writing systems; reading across them involves more than changing a font.","body":[{"type":"paragraph","text":"Two readers may understand the same spoken Punjabi sentence yet find each other’s books difficult to read. Language and script answer different questions. The language concerns vocabulary, grammar and ways of speaking; the script supplies a visible system for writing them. Punjabi’s association with both Shahmukhi and Gurmukhi makes that distinction especially important."},{"type":"paragraph","text":"A change of script is therefore not necessarily a translation into another language. At the same time, reading across scripts is not merely a matter of replacing a typeface. The characters, conventions and decisions about representing sound have to be understood."},{"type":"heading","level":2,"text":"A small letter can reveal a large problem"},{"type":"paragraph","text":"A 2019 Unicode proposal by Lorna Priest Evans and M.G.Abbas Malik addressed the representation of a Punjabi retroflex lateral sound in Arabic-script writing. It compared the relevant Gurmukhi character with proposed Shahmukhi representation and discussed a publisher’s workaround. The proposal also presented historical manuscript evidence rather than relying only on a newly designed symbol."},{"type":"paragraph","text":"The example is useful because it shows several kinds of work meeting on a printed page: a speaker distinguishes a sound; an editor decides how to write it; a font must display the chosen character; and software must preserve it as text. A page may look correct to a casual observer while still failing one of those requirements."},{"type":"paragraph","text":"It would be misleading to turn this single proposal into a claim that Punjabi had no writing tradition before digital standardisation. The problem concerns particular representation and technical support, not the existence or legitimacy of the language."},{"type":"heading","level":2,"text":"Crossing the script barrier"},{"type":"paragraph","text":"Research by Saini, Lehal and Kalra on Shahmukhi-to-Gurmukhi conversion describes the use of a language corpus and statistical information to address text without diacritical marks. That is an important clue: conversion can require informed choices, not a simple one-to-one character substitution."},{"type":"paragraph","text":"Punjabi University’s 2007–2008 report also lists work on transliteration tools and a Gurmukhi/Shahmukhi presentation of the Puratan Janam Sakhi. These are documented attempts to widen access across writing systems. They do not establish that every automated conversion is accurate, or that readers using either script necessarily share identical literary interests."},{"type":"paragraph","text":"For an archive, the practical implication is to retain the source text alongside a clearly identified converted version. If an editor resolves an ambiguous word, that decision should not be hidden inside an apparently mechanical output. A competent reader of the destination script needs to review the result."},{"type":"heading","level":2,"text":"More than a choice between two labels"},{"type":"paragraph","text":"A script field can help a reader find material, but it should not substitute for information about the work itself. Author, edition, place of publication and language variety remain relevant. Two books in the same script can differ profoundly, while versions in different scripts may preserve a close textual relationship."},{"type":"paragraph","text":"The reward of reading across Punjabi’s scripts is not the elimination of difference. It is access to a wider literary conversation. Treating both systems as serious ways of writing, while making the process of conversion transparent, allows that conversation to expand without pretending that typography alone can do all the work."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Punjab","Languages"],"province":"Punjab","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Punjabi across more than one script | Virsapur","description":"Shahmukhi and Gurmukhi make Punjabi visible through different writing systems; reading across them involves more than changing a font.","primaryKeyword":"Punjabi Shahmukhi Gurmukhi","socialTitle":"Punjabi across more than one script","socialDescription":"Shahmukhi and Gurmukhi make Punjabi visible through different writing systems; reading across them involves more than changing a font."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Proposal to encode Arabic letter lam with small Arabic letter tah above","url":"https://unicode.org/wg2/docs/n5048-19111r-punjabi-lam.pdf","publisher":"Lorna Priest Evans and M.G.Abbas Malik, Unicode proposal","accessDate":"2026-10-22"},{"title":"Shahmukhi to Gurmukhi Transliteration System","url":"https://learnpunjabi.org/pdf/gslehal-pap15.pdf","publisher":"Tejinder Singh Saini, Gurpreet Singh Lehal and VirinderS.Kalra, Punjabi University research","accessDate":"2026-10-22"},{"title":"Annual Quality Assurance Report2007–2008","url":"https://www.punjabiuniversity.ac.in/pages/Images/IQAC/AQAR2007-2008.pdf","publisher":"Punjabi University, Patiala","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"No obsolete speaker counts or unqualified scriptstandardisationclaims adopted. Technical proposaltreatedhistorically not allUnicodecurrentstatus. NativePunjabi/scriptreview required; no invented bilingualexamples.","editorialReason":"Explain script and language as different questions, avoiding a single-script identity claim.","sortOrder":238}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-sindhis-writing-traditions-and-the-making-of-print','sindhis-writing-traditions-and-the-making-of-print','review','{"id":"story-sindhis-writing-traditions-and-the-making-of-print","type":"story","slug":"sindhis-writing-traditions-and-the-making-of-print","title":"Sindhi’s writing traditions and the making of print","summary":"Sindhi print history includes several scripts, production methods and editorial decisions; an individual edition is a better starting point than a single invention date.","body":[{"type":"paragraph","text":"A printed Sindhi book carries more than words. Its script, letterforms, page arrangement and method of production tell us how a text was prepared for particular readers. Asking when “Sindhi printing began” can be useful, but a single date cannot explain all those decisions or the writing traditions that preceded them."},{"type":"paragraph","text":"The history becomes more tangible when approached through an edition. What script does it use? Does the page preserve handwritten forms through lithography, or show characters assembled from movable type? Who prepared the text, and what does the title page actually claim?"},{"type":"heading","level":2,"text":"Khudawadi in the record of print"},{"type":"paragraph","text":"Anshuman Pandey’s 2011 proposal for encoding Khudawadi documents a Sindhi writing system associated with mercantile use and later adapted for education and administration. It presents examples of lithographed texts, including Dodo Chanesar, and records the use of metal type in the 1870s. Its illustrations also include later religious publications."},{"type":"paragraph","text":"These examples are valuable because they connect script history to surviving printed evidence. The same language could be written for an account, a classroom or a literary audience, but those uses did not necessarily produce the same page. A commercial writing practice and a standard prepared for printing should not be assumed to have identical character repertoires."},{"type":"paragraph","text":"The proposal is a technical document with a historical argument. It is not a complete survey of Sindhi publishing. Its particular strength here lies in the reproduced specimens and the questions they allow us to ask about how letters became repeatable printed forms."},{"type":"heading","level":2,"text":"Why the script’s name matters"},{"type":"paragraph","text":"A related 2010 submission argued for changing the proposed Unicode name from “Sindhi” to “Khudawadi.” It explained that Sindhi names a language and can also appear in broad descriptions of several writing systems; the generic label risked confusion with the Arabic-based script commonly used for Sindhi."},{"type":"paragraph","text":"That naming problem extends beyond software. A catalogue entry that records only “Sindhi script” may leave a reader uncertain about what is actually on the page. Identifying the writing system more precisely helps connect an edition with suitable readers and tools without claiming that one script owns the language."},{"type":"paragraph","text":"It also prevents a false historical sequence in which each new standard is imagined to erase everything that came before. Documents can preserve older forms, while different audiences and institutions make different choices."},{"type":"heading","level":2,"text":"Read the edition as an object"},{"type":"paragraph","text":"A useful description should separate the date of a work from the date of the copy or printed edition being examined. A familiar poem in a nineteenth-century book is not automatically a nineteenth-century composition. Conversely, the age of a story does not make every spelling or arrangement in a later edition ancient."},{"type":"paragraph","text":"Printer, editor and translator also deserve separate credit where the publication supplies their names. Each may have shaped what the reader encounters. A digitised cover alone may not reveal all these roles; the title page, preface and colophon can be crucial."},{"type":"paragraph","text":"Sindhi’s print heritage is consequently a history of making texts available through particular material and linguistic choices. Attending to those choices gives a richer account than declaring one moment when an entire literary culture supposedly entered print."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Sindh","Languages"],"province":"Sindh","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Sindhi’s writing traditions and the making of print | Virsapur","description":"Sindhi print history includes several scripts, production methods and editorial decisions; an individual edition is a better starting point than a single invention date.","primaryKeyword":"Sindhi script print history","socialTitle":"Sindhi’s writing traditions and the making of print","socialDescription":"Sindhi print history includes several scripts, production methods and editorial decisions; an individual edition is a better starting point than a single invention date."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Final Proposal to Encode the Khudawadi Script","url":"https://www.unicode.org/L2/L2011/11022-khudawadi.pdf","publisher":"Anshuman Pandey, University of Michigan / Unicode","accessDate":"2026-10-22"},{"title":"Request to Rename Sindhi to Khudawadi","url":"https://www.unicode.org/L2/L2010/10420-sindhi-name-change.pdf","publisher":"Anshuman Pandey, Script Encoding Initiative","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Eachsourceunder200words;2011proposal~155facts/2010~65,restoriginaledition-readinganalysis. No broadclaims late19c officialscript or obsoletecommunityusage; no claim entireSindhiliteratureinventedcolonially. Nativeeditorreview required.","editorialReason":"Use documented editions and script debates rather than a simplified invention date.","sortOrder":239}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-pashto-literary-forms-beyond-a-single-poet','pashto-literary-forms-beyond-a-single-poet','review','{"id":"story-pashto-literary-forms-beyond-a-single-poet","type":"story","slug":"pashto-literary-forms-beyond-a-single-poet","title":"Pashto literary forms beyond a single poet","summary":"Pashto literature includes translated romances, instructional verse and changing manuscript networks—not only the biography of a celebrated poet.","body":[{"type":"paragraph","text":"A literary tradition can become smaller in the telling when it is represented by one famous name. Pashto offers a more interesting picture when the question changes from “Who is its greatest poet?” to “What kinds of writing did people make, copy and read?” The answers lead through romance, instruction, translation and the movement of manuscripts."},{"type":"paragraph","text":"This is not a complete history of Pashto literature. It is a way into several documented examples that resist the idea of a single poet, genre or territory standing for the whole."},{"type":"heading","level":2,"text":"Romance through translation"},{"type":"paragraph","text":"C.Ryan Perkins’s research presentation at UCLA examined Abdul Qadir Khan’s Pashto rendering of Jami’s Persian Yusuf va Zulaikha. The abstract locates the work around the turn of the seventeenth and eighteenth centuries and discusses later manuscript copies associated with Kashmir and Shahjahanabad. It places translation within a broader moment of literary production rather than treating it as a secondary activity."},{"type":"paragraph","text":"That distinction matters. A translated romance is not simply evidence that readers lacked an original literature. It can show writers choosing to participate in a wider narrative world while making the work available in another language. The manuscript’s place and date of copying then add a further history of readers and circulation."},{"type":"paragraph","text":"A reader should keep those stages separate: the Persian work, the Pashto rendering and a particular surviving copy are related but not identical objects. Their dates answer different questions."},{"type":"heading","level":2,"text":"Verse can instruct as well as celebrate"},{"type":"paragraph","text":"The British Library’s record for IO Islamic 4820 describes a copy of Fazl namah attributed to Khushhal Khan as an instructional work in verse. The manuscript is dated 1795, much later than the author’s lifetime. Its catalogue therefore offers a concrete reminder that an old author continued to be transmitted through later material copies."},{"type":"paragraph","text":"Instructional verse also complicates the modern assumption that poetry is primarily a brief expression of private feeling. Form can organise teaching and make a text memorable. To understand how this particular work does so would require reading its Pashto text, not merely repeating its catalogue label."},{"type":"paragraph","text":"A responsible introduction can identify the genre and manuscript without pretending to have translated the work. That leaves a clear path for a specialist edition or a native-language reading to add depth."},{"type":"heading","level":2,"text":"Literary geography is wider than a modern boundary"},{"type":"paragraph","text":"Mikhail Pelevin’s 2018 UCLA lecture abstract traces Pashto writing in North India from Roshani poetry to later literary activity in Rohilkhand. His research framing asks readers to consider writers and manuscripts beyond the territory most immediately associated with the language today."},{"type":"paragraph","text":"The implication is not that Pashto belongs somewhere else. It is that a literary map needs to accommodate movement. Where a text was composed, where a copy was made and where it is held now may all differ."},{"type":"paragraph","text":"Together, these examples suggest an archive organised around forms and textual relationships as well as authors. Romance, instruction and manuscript circulation each open a different door. Reading through more than one of them makes room for a tradition that is neither reducible to a heroic biography nor confined to a single kind of poem."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Khyber Pakhtunkhwa","Languages"],"province":"Khyber Pakhtunkhwa","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Pashto literary forms beyond a single poet | Virsapur","description":"Pashto literature includes translated romances, instructional verse and changing manuscript networks—not only the biography of a celebrated poet.","primaryKeyword":"Pashto literary forms","socialTitle":"Pashto literary forms beyond a single poet","socialDescription":"Pashto literature includes translated romances, instructional verse and changing manuscript networks—not only the biography of a celebrated poet."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Afghanistan, Pashto and the Creation of a Literary Language","url":"https://international.ucla.edu/asia/event/10161","publisher":"C.Ryan Perkins, research lecture abstract hosted by UCLA","accessDate":"2026-10-22"},{"title":"Pashto Literature in North India in the16th–18thCenturies","url":"https://www.international.ucla.edu/apc/event/13112","publisher":"Mikhail Pelevin, research lecture abstract hosted by UCLA","accessDate":"2026-10-22"},{"title":"IO Islamic4820: Fazl namah","url":"https://searcharchives.bl.uk/catalog/032-004342266","publisher":"British Library","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Abstracts attributed as researcharguments notfullpaperread. BritishLibrarycodex1795 date notauthorlife/compositiondate. No quotedverse. Wideroralgenresnotclaimedexhaustive; specialistPashtoedition/native-reviewgate remains.","editorialReason":"Commission examples across genres, requiring a specialist edition and native-language review.","sortOrder":240}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-balochi-oral-poetry-and-the-work-of-transmission','balochi-oral-poetry-and-the-work-of-transmission','review','{"id":"story-balochi-oral-poetry-and-the-work-of-transmission","type":"story","slug":"balochi-oral-poetry-and-the-work-of-transmission","title":"Balochi oral poetry and the work of transmission","summary":"Balochi oral poetry reaches us through performers, collectors and changing versions; transmission is part of the work, not a gap before writing.","body":[{"type":"paragraph","text":"A poem remembered and performed is not an unfinished book waiting for someone to write it down. Its delivery, audience and occasions can be part of its meaning. Balochi oral poetry becomes more legible when we keep those relationships in view instead of treating transmission as a chain of anonymous repetitions."},{"type":"paragraph","text":"The first question is consequently not only “Who composed this?” It is also “Who performed this version, for whom, and how did this recording or transcription reach us?” The answers may belong to different people and different moments."},{"type":"heading","level":2,"text":"Several kinds of literary labour"},{"type":"paragraph","text":"Sabir Badalkhan and Carina Jahani’s introduction to Balochi literature distinguishes performers associated with heroic deeds and love lyrics, alongside professional and non-professional storytellers. It also notes written registers kept by some poets in Makran by the late nineteenth and early twentieth centuries. The relationship between memory and writing was therefore more complicated than an abrupt switch from one medium to another."},{"type":"paragraph","text":"Their account describes tribal poems as potentially competing versions of events. That observation changes how a historical ballad should be read. Its loyalties and rhetorical force are not defects to be removed before it becomes evidence; they are part of what the work can reveal about the circumstances in which history was narrated."},{"type":"paragraph","text":"A poem can illuminate an argument about honour or an admired figure without serving as an independently verified chronology. The date of a later performance does not settle the date of its first composition."},{"type":"heading","level":2,"text":"The collector is also in the frame"},{"type":"paragraph","text":"Josef Elfenbein’s account identifies Mansell Longworth Dames among the important early collectors who put Balochi oral poetry into print. A collection makes material available to readers who were not present at a performance, but it also introduces choices: selection, transcription, ordering and translation."},{"type":"paragraph","text":"A published title such as “traditional song” can hide those choices. If a collector recorded the performer’s name, location or explanation, that information deserves to travel with the text. If it was omitted, the omission should remain visible rather than being filled with an invented communal voice."},{"type":"paragraph","text":"Comparing two versions is especially valuable when the differences can be described precisely. A changed episode, a different sequence or an altered address to the audience may reveal adaptation. It should not automatically be dismissed as faulty memory simply because one version appeared in print first."},{"type":"heading","level":2,"text":"What a listening archive can preserve"},{"type":"paragraph","text":"A useful record would connect the sound with its transcription and translation while keeping the performer, composer where known, recorder and translator distinct. It would also note whether the performance was requested for documentation or arose within another occasion. Those situations may produce different material."},{"type":"paragraph","text":"Permission belongs to this record too. A recording preserved for research should not automatically become unrestricted promotional audio."},{"type":"paragraph","text":"Balochi oral poetry does not need to be made timeless to deserve attention. Its endurance is more compelling when the people doing the work of remembering, performing, revising and publishing remain present in the account. Transmission is not merely how a poem survives; it is one of the places where its history happens."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Balochistan","Languages"],"province":"Balochistan","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Balochi oral poetry and the work of transmission | Virsapur","description":"Balochi oral poetry reaches us through performers, collectors and changing versions; transmission is part of the work, not a gap before writing.","primaryKeyword":"Balochi oral poetry","socialTitle":"Balochi oral poetry and the work of transmission","socialDescription":"Balochi oral poetry reaches us through performers, collectors and changing versions; transmission is part of the work, not a gap before writing."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"A Brief Introduction to Balochi Literature","url":"https://www2.lingfil.uu.se/arkiv/old_site/digitalAssets/562/c_562186-l_3-k_jahanibadalkhanlastversionnov15.pdf","publisher":"Sabir Badalkhan and Carina Jahani, Uppsala University repository","accessDate":"2026-10-22"},{"title":"BaluchistanIIIa: Baluchi Poetry","url":"https://www.iranicaonline.org/articles/baluchistan-iiia/","publisher":"Josef Elfenbein, Encyclopaedia Iranica","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Badalkhan/Jahani specialist primary synthesis approximately160 words; Elfenbein approximately55. No verse quoted, no universal extinction claim.","editorialReason":"Distinguish performers, versions and collectors rather than present a fixed anonymous tradition.","sortOrder":241}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-brahui-a-language-not-a-historical-shortcut','brahui-a-language-not-a-historical-shortcut','review','{"id":"story-brahui-a-language-not-a-historical-shortcut","type":"story","slug":"brahui-a-language-not-a-historical-shortcut","title":"Brahui: a language, not a historical shortcut","summary":"Brahui’s Dravidian classification concerns linguistic relationships; it does not by itself identify an ancient population or settle a migration history.","body":[{"type":"paragraph","text":"Brahui is often introduced through an apparent geographical surprise: a Dravidian language in Balochistan, far from the southern Indian languages that many readers first associate with that family. The classification is important. It is also the beginning of an inquiry, not a shortcut to a complete history of its speakers."},{"type":"paragraph","text":"Glottolog places Brahui within Dravidian. That statement concerns a linguistic relationship. It does not automatically tell us when the language reached its present distribution, whether a particular archaeological community spoke it, or how every present-day speaker understands their identity."},{"type":"heading","level":2,"text":"A family tree is not a migration itinerary"},{"type":"paragraph","text":"Historical linguistics compares patterns across languages rather than relying on a few similar-sounding words. A relationship needs to account for inherited forms and systematic changes. Borrowing, by contrast, can connect languages whose speakers interact without making them members of the same family."},{"type":"paragraph","text":"A 2018 study by Kolipakam and colleagues analysed Dravidian lexical data through a Bayesian model. It recovered major groupings while reporting uncertainty about relationships between the principal branches. The researchers explicitly noted that the family’s geographical homeland and exact dispersal were not known."},{"type":"paragraph","text":"Those limits matter more than a striking headline about age. A model of linguistic divergence is not a dated map of people walking from one location to another. Its results depend on data, classifications and chronological assumptions that readers should be able to inspect."},{"type":"heading","level":2,"text":"Contact does not cancel inheritance"},{"type":"paragraph","text":"Elfenbein’s specialist account discusses Brahui’s extensive contact with Balochi and other regional languages. This makes it a useful reminder that a language can retain a genealogical classification while incorporating vocabulary and other influences through interaction."},{"type":"paragraph","text":"There is no need to choose between “truly Dravidian” and “shaped by its neighbours.” The two descriptions address different aspects of linguistic history. A borrowed word does not make a speaker less authentic, just as an inherited grammatical pattern does not dictate a person’s present cultural affiliations."},{"type":"paragraph","text":"The same caution applies to names. The label used for a language, a community’s preferred self-description and an administrative category may overlap without being identical. A heritage profile should not infer one automatically from another."},{"type":"heading","level":2,"text":"Give the living language room"},{"type":"paragraph","text":"An article devoted only to remote origins can make current speakers disappear. Useful documentation also asks what people write, tell, teach and translate in Brahui, and which varieties a particular recording or publication represents. A grammatical description and a literary performance are different records, each worth keeping on its own terms."},{"type":"paragraph","text":"Claims connecting Brahui directly to the Indus civilisation require evidence beyond its modern location and family membership. Without a securely demonstrated link, such a claim would turn a living language into an answer to a separate unsolved historical question."},{"type":"paragraph","text":"Brahui’s significance does not depend on supplying that answer. It offers a rich case for thinking about inheritance, contact and linguistic knowledge in Balochistan. The more carefully those questions are separated, the less temptation there is to replace its documented complexity with a dramatic origin story."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Balochistan","Languages"],"province":"Balochistan","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Brahui: a language, not a historical shortcut | Virsapur","description":"Brahui’s Dravidian classification concerns linguistic relationships; it does not by itself identify an ancient population or settle a migration history.","primaryKeyword":"Brahui language heritage","socialTitle":"Brahui: a language, not a historical shortcut","socialDescription":"Brahui’s Dravidian classification concerns linguistic relationships; it does not by itself identify an ancient population or settle a migration history."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Brahui classification","url":"https://glottolog.org/glottolog?iso=brh","publisher":"Glottolog","accessDate":"2026-10-22"},{"title":"A Bayesian phylogenetic study of the Dravidian language family","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5882685/","publisher":"Vishnupriya Kolipakam and colleagues, Royal Society Open Science","accessDate":"2026-10-22"},{"title":"Brahui","url":"https://www.iranicaonline.org/articles/brahui/","publisher":"Josef Elfenbein, Encyclopaedia Iranica","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"No genetics/Indus civilisation identity claim.2018 model uncertainty retained, no date asserted for Brahui arrival. Elfenbein language contact only, no lexicon percentages.","editorialReason":"Explain present linguistic identity while separating classification from speculative population history.","sortOrder":242}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-saraiki-poetry-and-the-vocabulary-of-the-river-plain','saraiki-poetry-and-the-vocabulary-of-the-river-plain','review','{"id":"story-saraiki-poetry-and-the-vocabulary-of-the-river-plain","type":"story","slug":"saraiki-poetry-and-the-vocabulary-of-the-river-plain","title":"Saraiki poetry and the vocabulary of landscape","summary":"Khwaja Ghulam Farid’s landscape vocabulary rewards close reading, but poetic places are not a literal map of a linguistically uniform region.","body":[{"type":"paragraph","text":"A landscape in poetry is made from selected words. A riverbank, desert grass or the sound of an animal can establish a place while also carrying an emotional charge. Reading Saraiki poetry for landscape therefore requires attention to both geography and literary purpose."},{"type":"paragraph","text":"Khwaja Ghulam Farid is an important starting point, but not a substitute for the whole language. His tomb at Kot Mithan is a tangible place through which readers can approach his legacy. The poems themselves create a different kind of space, one that cannot be reduced to the location of the shrine."},{"type":"heading","level":2,"text":"Listen for the particular, not only the picturesque"},{"type":"paragraph","text":"Christopher Shackle’s study of Farid’s Urdu poetry sets it alongside his better-known Saraiki work. In discussing the latter, he identifies the force of local poetic resources and includes a passage whose landscape is populated by grasses, animals, sand and rain. The effect is more precise than a generic description of a beautiful desert."},{"type":"paragraph","text":"The vocabulary matters because it selects what a reader is asked to notice. A translation that replaces every specific plant or creature with a broad English category may preserve the outline while thinning the texture. Conversely, an unexplained local word may preserve its sound but leave a new reader unable to understand its role."},{"type":"paragraph","text":"A useful edition can hold those needs together: retain the original text, supply a readable translation and explain difficult words in notes. This is not an invitation to invent an English equivalent from a photograph or a dictionary entry detached from the poem."},{"type":"heading","level":2,"text":"The river plain is not one landscape"},{"type":"paragraph","text":"The title of a regional literary article can tempt us to imagine a uniform setting. Farid’s association with Rohi and the desert complicates an account focused only on the river plain. These environments can be connected within a poet’s world without becoming interchangeable."},{"type":"paragraph","text":"Nor should a metaphor be treated as a field observation. Rain in a poem may be an event, an image of relief or part of a larger structure of longing. Establishing which meanings are active requires reading the surrounding lines and, where relevant, the work’s devotional and performance contexts."},{"type":"paragraph","text":"Shackle’s comparison also reminds us that Farid wrote in more than one language. A writer’s linguistic choices can produce different effects within the same broad literary life. An archive should identify the actual language of the cited text rather than infer it from the poet’s reputation."},{"type":"heading","level":2,"text":"Follow the edition and the later conversation"},{"type":"paragraph","text":"A poem’s number is useful only when the edition is named. Editors can arrange a body of work differently, and a translation may follow a particular selection. Recording the editor and source allows another reader to return to the same passage."},{"type":"paragraph","text":"Later writers may engage with Farid’s legacy without merely repeating him. That conversation deserves separate study rather than being folded into an unchanged regional essence."},{"type":"paragraph","text":"The reward of close reading is a more attentive encounter with place. The landscape becomes neither tourist scenery nor proof that everybody in a district speaks alike. It is a worked vocabulary through which a particular poem makes feeling, memory and environment speak to one another."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Punjab","Languages"],"province":"Punjab","district":null,"relatedDistrictIds":["punjab-rajanpur"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6191"],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Saraiki poetry and the vocabulary of landscape | Virsapur","description":"Khwaja Ghulam Farid’s landscape vocabulary rewards close reading, but poetic places are not a literal map of a linguistically uniform region.","primaryKeyword":"Saraiki poetry heritage","socialTitle":"Saraiki poetry and the vocabulary of landscape","socialDescription":"Khwaja Ghulam Farid’s landscape vocabulary rewards close reading, but poetic places are not a literal map of a linguistically uniform region."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Urdu as a sideline: the poetry of Khwaja Ghulam Farid","url":"https://siraiki.com/wp-content/uploads/2025/07/Urdu-as-a-sideline_-the-poetry-of-Khawja-Ghulam-Farid.pdf","publisher":"Christopher Shackle, originally in Urdu and Muslim South Asia, SOAS","accessDate":"2026-10-22"},{"title":"Tomb of Khawaja Ghulam Farid","url":"https://doam.gov.pk/public/sites/6191","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Shackle article read via author-credited scan; no lyric quoted, approximately150 words derived. Native Saraiki edition review before original words/translations published. Riverplain title qualified by Rohi diversity.","editorialReason":"Read selected authorised texts for landscape vocabulary without treating a region as linguistically uniform.","sortOrder":243}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-shina-storytelling-and-community-documentation','shina-storytelling-and-community-documentation','review','{"id":"story-shina-storytelling-and-community-documentation","type":"story","slug":"shina-storytelling-and-community-documentation","title":"Shina storytelling and community documentation","summary":"A Shina story or recollection is most useful when the record keeps its speaker, setting and permissions visible alongside the words.","body":[{"type":"paragraph","text":"A story recorded in Shina is not simply a sample of a language. It is an event in which someone chooses what to tell, how to tell it and what a listener is expected to understand. Community documentation becomes stronger when those choices remain attached to the recording."},{"type":"paragraph","text":"This changes the emphasis from collecting “vanishing customs” to sustaining useful relationships. The storyteller is not merely a source from whom an archive extracts words. They may be a performer, interpreter, family historian or critic of the version someone else remembers."},{"type":"heading","level":2,"text":"A recollection with a name and a setting"},{"type":"paragraph","text":"Mountain Heritage Archives’ description of an interview with Khalifa Durr-e-Maknun identifies the recording as made at his home in Sher Qila in the summer of 2016. It describes his recollections of the Shina poet Khalifa Rehmat Malang Jan and the poetry associated with the poet’s love for Yourmas. The publicly posted account thus distinguishes the remembered poet from the person recounting his memory."},{"type":"paragraph","text":"That distinction is essential. A recollection about a poem is not necessarily a contemporary record of its composition. The interview date is not the date of the events described. Both can be valuable, but their value depends on knowing which kind of evidence is being heard."},{"type":"paragraph","text":"The recording’s public description also does not grant permission to extract and reuse its audio. Access to an archive and clearance for a new publication are separate matters."},{"type":"heading","level":2,"text":"A language contains more than one storytelling setting"},{"type":"paragraph","text":"Ruth Laila Schmidt’s study of a Naga-prince tale concerns a version recorded in the Shina of Indus Kohistan. Its abstract highlights a resourceful female protagonist and compares the tale with versions elsewhere. This is a different regional and documentary setting from the Sher Qila interview."},{"type":"paragraph","text":"The comparison should not erase that difference. A shared language label cannot make every story a representative voice for all Shina speakers. Nor does resemblance between tales prove that one storyteller copied another. The form of the comparison must remain tied to the versions actually studied."},{"type":"paragraph","text":"For a reader, this is an opportunity to ask better questions. Who drives the action in this telling? Which explanations does the narrator offer? What does a translation need to explain because the expected audience has changed?"},{"type":"heading","level":2,"text":"Documentation that returns something"},{"type":"paragraph","text":"A community-led project should agree how recordings will be named, stored, accessed and reused before treating public upload as the default outcome. Speakers should be able to identify the language variety and decide whether personal names or sensitive parts of a narrative should appear."},{"type":"paragraph","text":"The useful outputs need not all be scholarly. A family copy, an accessible transcription or material chosen for local teaching may matter as much as a searchable catalogue. Where translation is made, its maker and reviewer should receive credit alongside the recorder."},{"type":"paragraph","text":"The aim is not to preserve one supposedly final version of Shina storytelling. It is to keep an accountable record of particular tellings, with room for other speakers to respond, differ and add. An archive becomes a conversation when its contributors can still recognise themselves within it."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Gilgit-Baltistan","Languages"],"province":"Gilgit-Baltistan","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Shina storytelling and community documentation | Virsapur","description":"A Shina story or recollection is most useful when the record keeps its speaker, setting and permissions visible alongside the words.","primaryKeyword":"Shina oral literature","socialTitle":"Shina storytelling and community documentation","socialDescription":"A Shina story or recollection is most useful when the record keeps its speaker, setting and permissions visible alongside the words."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Khalifa Rehmat Malang Jan’s Memories Recounted","url":"https://soundcloud.com/mountainheritagearchives/khalifa-rehmat-malang-jans-memories-recounted","publisher":"Mountain Heritage Archives, original recording description","accessDate":"2026-10-22"},{"title":"The Transformation of a Naga Prince Tale, abstract","url":"https://www1.columbia.edu/sec/cu/lso/tocdata/765425/CU02681463/081-Vol_81.pdf","publisher":"Ruth Laila Schmidt, Oriental Archive81,2013; contents hosted by Columbia University","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Recording description read; no claim audio audited/transcribed. Schmidt scoped to KohistaniShina, not Gilgit variety. Community-led framework proposed, not completed. All-rights-reserved audio not reused.","editorialReason":"Plan a community-led documentation account rather than a list of supposedly vanishing customs.","sortOrder":244}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-balti-language-in-manuscripts-and-new-media','balti-language-in-manuscripts-and-new-media','review','{"id":"story-balti-language-in-manuscripts-and-new-media","type":"story","slug":"balti-language-in-manuscripts-and-new-media","title":"Balti language in manuscripts and new media","summary":"Balti’s writing history includes distinct manuscript systems and contemporary digital needs; a script’s encoding status is not the status of the language.","body":[{"type":"paragraph","text":"A language can remain vigorously spoken while one of its historical writing systems becomes difficult to read or reproduce. Balti makes the distinction important. “Balti language,” “a script used for Balti” and “a digital font” are not interchangeable descriptions."},{"type":"paragraph","text":"The history is more varied than a simple passage from an old manuscript to a modern screen. Different writing systems may record the same language, and a technical description may give a provisional name to a script whose own historical name is uncertain."},{"type":"heading","level":2,"text":"Two manuscript labels, not two languages"},{"type":"paragraph","text":"Anshuman Pandey’s 2010 Unicode contribution distinguishes systems he provisionally calls Balti A and Balti B. He stresses that evidence is limited and that their relationship is unknown. For Balti B, he discusses a manuscript of Wazir Ahmad’s account of the creation of Shigar, drawing on published photographs and script charts."},{"type":"paragraph","text":"The document also shows why copied descriptions need scrutiny. Earlier accounts disagreed over writing direction and the relationship of the characters to other scripts. Pandey separates the systems rather than forcing every reference into one alphabet. The labels are tools for research, not names for separate Balti-speaking peoples."},{"type":"paragraph","text":"This is an edition-level problem as much as a linguistic one. A chart reproduced from another publication may look like new evidence while actually descending from the same original specimen. Several appearances on different websites do not necessarily mean that several independent manuscripts have survived."},{"type":"heading","level":2,"text":"What the screen can conceal"},{"type":"paragraph","text":"Unicode’s unsupported-scripts page lists Balti A and Balti B among historical systems not yet supported. That does not mean that Balti cannot be written digitally. The Consortium’s language-and-script data also records Balti in connection with Arabic script."},{"type":"paragraph","text":"These technical records answer a narrow question about representation. They do not establish how many people prefer a particular script, which literary works circulate most widely, or what a community regards as the best spelling practice."},{"type":"paragraph","text":"A photograph of a manuscript can be displayed even when its script is not encoded, but the words in the photograph are not automatically searchable text. A transcription adds another layer of interpretation. An editor must decide which marks are letters, which are variants and how uncertain readings will be shown."},{"type":"heading","level":2,"text":"Keep versions connected"},{"type":"paragraph","text":"For a digital edition, the strongest arrangement would preserve a connection between the page image, a transcription, any transliteration and a translation. A reader could then see where an interpretation comes from instead of encountering a clean paragraph detached from its evidence."},{"type":"paragraph","text":"Modern writing should receive equal attention. A historical script does not become more culturally authentic merely because it is rare, and a writer using a widely supported script is not abandoning the language by choosing practical tools."},{"type":"paragraph","text":"Balti’s manuscript and digital worlds therefore invite a question about continuity without demanding sameness. What can a new medium carry forward, and what choices does it introduce? Keeping those choices visible allows old texts to gain new readers without turning a complex writing history into a single romantic story of loss and revival."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Gilgit-Baltistan","Languages"],"province":"Gilgit-Baltistan","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Balti language in manuscripts and new media | Virsapur","description":"Balti’s writing history includes distinct manuscript systems and contemporary digital needs; a script’s encoding status is not the status of the language.","primaryKeyword":"Balti language writing","socialTitle":"Balti language in manuscripts and new media","socialDescription":"Balti’s writing history includes distinct manuscript systems and contemporary digital needs; a script’s encoding status is not the status of the language."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Introducing Another Script for Writing Balti","url":"https://www.unicode.org/L2/L2010/10231-n3842-balti.pdf","publisher":"Anshuman Pandey, Unicode technical contribution","accessDate":"2026-10-22"},{"title":"As Yet Unsupported Scripts","url":"https://www.unicode.org/standard/unsupported.html","publisher":"Unicode Consortium","accessDate":"2026-10-22"},{"title":"Languages and Scripts, CLDR49","url":"https://www.unicode.org/cldr/charts/49/supplemental/languages_and_scripts.html","publisher":"Unicode Consortium","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Pandey approximately170 words derived; historical A/B labels tentative retained; no claim all Balti unencoded/dead. CLDR not literary census. No manuscript images reused.","editorialReason":"Examine continuity and adaptation across writing contexts with edition-level verification.","sortOrder":245}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-burushaski-and-the-meaning-of-a-language-isolate','burushaski-and-the-meaning-of-a-language-isolate','review','{"id":"story-burushaski-and-the-meaning-of-a-language-isolate","type":"story","slug":"burushaski-and-the-meaning-of-a-language-isolate","title":"Burushaski and the meaning of a language isolate","summary":"Calling Burushaski a language isolate describes the limits of demonstrated linguistic kinship, not the isolation of its speakers.","body":[{"type":"paragraph","text":"“Language isolate” sounds like a description of a community cut off from the world. In linguistics it means something narrower: a language has no demonstrated genealogical relationship with another language or family. Applied to Burushaski, the term concerns evidence of inherited linguistic kinship, not the absence of contact, travel or multilingual lives."},{"type":"paragraph","text":"This distinction matters because exotic accounts can turn an ordinary technical classification into a mystery about people. Burushaski speakers do not need an extraordinary origin story for their language to deserve careful study."},{"type":"heading","level":2,"text":"A claim about relationships"},{"type":"paragraph","text":"There have been proposals connecting Burushaski with other languages. Their existence does not itself establish those relationships. Luca Alfieri’s 2020 review of an Indo-European affiliation argument concludes that contact and borrowed material offer a better explanation than the proposed genealogical classification. That is a scholarly assessment of evidence, not a claim that future research is impossible."},{"type":"paragraph","text":"The useful question is what a proposed relationship explains systematically. Similar words can arise through borrowing, chance or shared inheritance. A persuasive historical argument must distinguish these possibilities rather than assemble a list of resemblances."},{"type":"paragraph","text":"Conversely, “isolate” does not mean that every word must be unique or that the language has never changed. Those would be much stronger—and quite different—claims."},{"type":"heading","level":2,"text":"Grammar is more revealing than a mystery headline"},{"type":"paragraph","text":"Anderson and Eggert’s study of Burushaski verb agreement examines how grammatical information is distributed within verbal forms. It describes noun classes and patterns of agreement, working through particular constructions rather than searching for a dramatic ancestral identity."},{"type":"paragraph","text":"For a general reader, the important point is methodological. A language can be studied in depth through the way its parts work together. Classification is only one question among many: how a speaker refers to participants, forms a sentence or distinguishes events can be equally revealing."},{"type":"paragraph","text":"A short English explanation cannot replace those analyses, but it can direct attention towards them. The language then appears as an organised means of expression rather than a collection of supposedly inexplicable words."},{"type":"heading","level":2,"text":"Hear the range of things people say"},{"type":"paragraph","text":"The Burushaski Language Resource at the University of North Texas provides another route in. Directed by Sadaf Munshi, the project includes material from Hunza, Nagar, Yasin and Srinagar. Its collection description lists conversations, personal accounts, stories, songs, recipes and teaching materials, together with transcriptions and research notes."},{"type":"paragraph","text":"That variety challenges the expectation that a heritage language should appear only in ceremonial performance. A recipe or a discussion can reveal forms of knowledge and interaction that a spectacular legend does not."},{"type":"paragraph","text":"The regional labels also matter. A recording should retain its particular speaker and variety instead of being treated as a definitive sample of all Burushaski. Access to the collection does not erase its individual permissions or conditions."},{"type":"paragraph","text":"Understanding “isolate” correctly therefore makes room for a less isolated view of the language. We can recognise uncertainty about deep relationships while attending closely to the documented grammar, voices and social worlds that are already available to study."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Gilgit-Baltistan","Languages"],"province":"Gilgit-Baltistan","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Burushaski and the meaning of a language isolate | Virsapur","description":"Calling Burushaski a language isolate describes the limits of demonstrated linguistic kinship, not the isolation of its speakers.","primaryKeyword":"Burushaski language isolate","socialTitle":"Burushaski and the meaning of a language isolate","socialDescription":"Calling Burushaski a language isolate describes the limits of demonstrated linguistic kinship, not the isolation of its speakers."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Burushaski Language Resource","url":"https://digital.library.unt.edu/explore/collections/BURUS/","publisher":"University of North Texas Libraries; Sadaf Munshi project","accessDate":"2026-10-22"},{"title":"Is Burushaski an Indo-European Language?","url":"https://iris.unimarconi.it/handle/20.500.14241/5413","publisher":"Luca Alfieri,2020 research abstract, Università Guglielmo Marconi repository","accessDate":"2026-10-22"},{"title":"A Typology of Verb Agreement in Burushaski","url":"https://sealang.net/sala/archives/pdf4/anderson2001typology.pdf","publisher":"GregoryD.S.Anderson and Randall Eggert, Linguistics of the Tibeto-Burman Area","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"No population/ancientoriginclaim; Alfieri attributed critique fromabstract. Grammar example described notnew invented sentence. UNTproject~95words; no audio reused.","editorialReason":"Clarify a linguistic term without exoticising speakers or inventing origins.","sortOrder":246}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-khowar-in-a-multilingual-chitral','khowar-in-a-multilingual-chitral','review','{"id":"story-khowar-in-a-multilingual-chitral","type":"story","slug":"khowar-in-a-multilingual-chitral","title":"Khowar in a multilingual Chitral","summary":"Khowar is a major language of wider communication in Chitral, but the region’s linguistic life cannot be reduced to one language per valley or district.","body":[{"type":"paragraph","text":"A person may use one language at home, another in a market and a third in education. A map that assigns a single language to Chitral cannot show this movement between settings. Khowar’s regional importance is best understood within those relationships, rather than as evidence that every resident shares the same first language."},{"type":"paragraph","text":"The distinction is between a language’s reach and its exclusivity. A language of wider communication allows people with different linguistic backgrounds to interact. That function does not make their other languages disappear from the social landscape."},{"type":"heading","level":2,"text":"Different scales of communication"},{"type":"paragraph","text":"Research on Hindukush multilingualism published in Multiethnica in 2017 describes Khowar and Pashto as languages of wider communication with different geographical reach in Chitral. Its discussion of Palula speakers shows that language choice can vary with interlocutors and destinations. The study thus presents a network of relationships, not a set of sealed language territories."},{"type":"paragraph","text":"This makes a market town an important linguistic place. It is not simply where several languages happen to be present. It is where speakers negotiate how to communicate, sometimes using a language that is not their first."},{"type":"paragraph","text":"Such patterns should remain dated and locally specific. A field study records practices under particular circumstances; it does not establish an immutable rule for every conversation in the region."},{"type":"heading","level":2,"text":"Regional strength can create local pressure"},{"type":"paragraph","text":"Fakhruddin Akhunzada’s report for the Forum for Language Initiatives discusses Yidgha-speaking communities in Lutkoh and their use of Khowar in wider social settings. It identifies education, employment, migration and family relationships among factors associated with language shift."},{"type":"paragraph","text":"This is a useful change of scale. Khowar may need support in some national or institutional contexts while exerting pressure on a smaller neighbouring language in another. Neither observation cancels the other."},{"type":"paragraph","text":"The report’s concerns should not be turned into a claim that every Yidgha-speaking household has made the same choice. Language maintenance is lived through particular families, opportunities and preferences. A regional overview needs room for those differences."},{"type":"heading","level":2,"text":"Writing creates further connections"},{"type":"paragraph","text":"FLI’s account of Khowar’s development as a literacy language describes collaboration involving researchers, writers and community intellectuals. Among its concrete examples are booklets of children’s stories and sayings accompanied by Urdu versions. These publications show another kind of multilingual relationship: one language helping readers approach material in another."},{"type":"paragraph","text":"A bilingual booklet is not proof that its two texts are interchangeable. Translation can widen access while leaving features of rhythm, wordplay or local reference to be explained. Crediting the writer, compiler and translator separately makes the collaboration visible."},{"type":"paragraph","text":"For heritage discovery, Khowar can therefore be approached through both its own literature and its role within a multilingual region. A story’s recording location, a speaker’s preferred language name and the languages of a publication all provide useful information."},{"type":"paragraph","text":"The resulting picture is more interesting than a one-colour language map. Chitral appears as a place of overlapping communication, where regional connections and smaller linguistic worlds need to be understood together."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Khyber Pakhtunkhwa","Languages"],"province":"Khyber Pakhtunkhwa","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Khowar in a multilingual Chitral | Virsapur","description":"Khowar is a major language of wider communication in Chitral, but the region’s linguistic life cannot be reduced to one language per valley or district.","primaryKeyword":"Khowar Chitral languages","socialTitle":"Khowar in a multilingual Chitral","socialDescription":"Khowar is a major language of wider communication in Chitral, but the region’s linguistic life cannot be reduced to one language per valley or district."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Multilingualism in the Hindukush, Multiethnica36–37,2017","url":"https://su.diva-portal.org/smash/get/diva2%3A1155268/FULLTEXT01.pdf","publisher":"Henrik Liljegren, Stockholm University repository","accessDate":"2026-10-22"},{"title":"Yidgha: an endangered language in Chitral","url":"https://www.fli-online.org/documents/languages/yidgha/yidgha-report.htm","publisher":"Fakhruddin Akhunzada, Forum for Language Initiatives","accessDate":"2026-10-22"},{"title":"Development of Khowar as a Literacy Language","url":"https://fli-online.org/site/wp-content/uploads/2017/10/Development-of-Khowar-as-a-Literacy-Language.pdf","publisher":"Forum for Language Initiatives","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"2017paperindexedfullrelevantsection; directfetchthrottled. Avoid outdated geography/counts/currentextinctionprediction and report''s suspectpassaltitude. FLI literacy historicalpublicationexamplesonly, notcurrentcounts.","editorialReason":"Distinguish regional language networks rather than equate one district with one language.","sortOrder":247}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-wakhi-oral-history-across-a-mountain-world','wakhi-oral-history-across-a-mountain-world','review','{"id":"story-wakhi-oral-history-across-a-mountain-world","type":"story","slug":"wakhi-oral-history-across-a-mountain-world","title":"Wakhi oral history across a mountain world","summary":"Wakhi oral histories connect mountain settlements with wider worlds, while also recording the restrictions and institutions that shaped movement.","body":[{"type":"paragraph","text":"A mountain landscape can look remote from the road while being densely connected through memory. Wakhi oral histories make such connections audible: family movements, work, education and remembered restrictions can place a village within a much wider world. The challenge is to preserve that reach without imagining a past in which borders and authority never mattered."},{"type":"paragraph","text":"An oral history is also more than an origin account. It may concern a first journey to a city, the person who provided a place to stay or a decision to pursue education. These details can explain how a network formed."},{"type":"heading","level":2,"text":"Following the first journeys"},{"type":"paragraph","text":"Andreas Benz’s 2013 study of migration from Gojal draws on fieldwork in 2011 and 2012, including interviews in village and urban settings. It examines experiences associated with military service, labour and education, and the support networks that helped later migrants follow earlier ones."},{"type":"paragraph","text":"The method matters. The researcher did not treat a village as a self-contained unit and then count everyone who left as permanently absent. He followed relationships between places. A person working elsewhere could remain connected to a household, a village and later migrants."},{"type":"paragraph","text":"For a heritage reader, this shifts attention from a line on a map to the arrangements that made travel possible. Who offered information? Where did newcomers find support? How did one person’s experience become useful to someone arriving later?"},{"type":"heading","level":2,"text":"Remembering constraints as well as connections"},{"type":"paragraph","text":"Benz also records recollections of permission requirements and controls on movement under Hunza’s former rulers. Those accounts complicate a romantic image of mountain communities moving freely across an open landscape. A pass is a geographical possibility, but access to it can be shaped by power and circumstance."},{"type":"paragraph","text":"Such testimony should retain its status as a remembered account. A researcher may compare it with administrative documents, but the comparison should not erase what the narrator understood or emphasised. Conversely, a memory of one period should not be presented as the rule for every earlier century."},{"type":"paragraph","text":"The same care applies to settlement histories. A UCL thesis records differing Wakhi accounts of migration into Gojal and notes tension with some published chronologies. The existence of several versions is itself significant; selecting the most vivid one as an unquestioned founding story would conceal the evidence."},{"type":"heading","level":2,"text":"Beyond the origin story"},{"type":"paragraph","text":"A strong oral-history collection can include the speaker’s circumstances, the language of the interview, the questions asked and the limits of publication permission. Translation should preserve uncertainty when a narrator is unsure, rather than smoothing the account into a falsely exact timeline."},{"type":"paragraph","text":"It should also recognise whose experiences are missing. A study centred on early male migrants cannot automatically describe the lives of those who remained, or stand for every woman’s experience of the same changes."},{"type":"paragraph","text":"Wakhi heritage becomes richer when movement and staying are considered together. Cross-border cultural connections may form part of that history, but so do local rules, national institutions and urban opportunities. The mountain world is neither sealed away nor borderless: it is made through relationships whose terms have changed over time."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Gilgit-Baltistan","Languages"],"province":"Gilgit-Baltistan","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Wakhi oral history across a mountain world | Virsapur","description":"Wakhi oral histories connect mountain settlements with wider worlds, while also recording the restrictions and institutions that shaped movement.","primaryKeyword":"Wakhi oral history","socialTitle":"Wakhi oral history across a mountain world","socialDescription":"Wakhi oral histories connect mountain settlements with wider worlds, while also recording the restrictions and institutions that shaped movement."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"How migrants made their way","url":"https://www.geo.fu-berlin.de/geog/fachrichtungen/anthrogeog/zelf/Medien/download/Benz/Benz_2013_-_How_Migrants_made_their_Way_-_CA_Working_Paper_No_11.pdf","publisher":"Andreas Benz, Crossroads Asia Working Paper11,2013","accessDate":"2026-10-22"},{"title":"Of moths and candle flames, doctoral thesis","url":"https://discovery.ucl.ac.uk/id/eprint/10106656/1/Of_moths_and_candle_flames_Th.pdf","publisher":"University College London research repository","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Benz paraphrase approximately170words; UCLexcerpt approximately50. Do notturncompetingoralsettlementchronologiesintofact. No contemporarybordercrossingadvice. Fullthesisauthor/titleverifybeforepublication; citeexactrepositorysource.","editorialReason":"Frame cross-border cultural connections without suggesting contemporary borders never matter.","sortOrder":248}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-hindko-and-the-languages-of-urban-encounter','hindko-and-the-languages-of-urban-encounter','review','{"id":"story-hindko-and-the-languages-of-urban-encounter","type":"story","slug":"hindko-and-the-languages-of-urban-encounter","title":"Hindko and the languages of urban encounter","summary":"Hindko’s urban life is visible in changing language choices and specialised workplace vocabulary, not only in a list of places where it is spoken.","body":[{"type":"paragraph","text":"A city’s linguistic heritage is not confined to its oldest inscriptions. It also lives in workplaces, family conversations and decisions about which language to use with whom. Hindko offers a way to examine that everyday urban texture without pretending that one language belongs exclusively to one city."},{"type":"paragraph","text":"Peshawar is an important setting for this inquiry, but a citywide label cannot reveal how different speakers navigate the same streets. Age, occupation, education and social relationships may all affect the language choices a person makes."},{"type":"heading","level":2,"text":"What a small study can show"},{"type":"paragraph","text":"A 2021 study of Hindko language maintenance in Peshawar used a questionnaire with 75 participants divided between two age groups. The authors reported a tendency among a substantial number of younger respondents to shift towards other dominant languages, linking this with social mobility."},{"type":"paragraph","text":"The study is evidence about its participants and research design, not a census of all Hindko speakers. Its value lies in the questions it raises about use and aspiration. Knowing that someone identifies with Hindko does not tell us which language they use at work, with children or in a formal setting."},{"type":"paragraph","text":"Language choice should not be reduced to personal loyalty. Opportunities and expectations can shape what people find useful or necessary. Equally, a person using several languages need not have abandoned the language they grew up with."},{"type":"heading","level":2,"text":"A workshop has its own vocabulary"},{"type":"paragraph","text":"Haroon-ur-Rashid and Raja Nasim Akhtar’s research on Hindko vehicle vocabulary offers a more focused view of contact. They interviewed motor mechanics and analysed how English loanwords were adapted to Hindko sound patterns, including adjustments to consonant clusters."},{"type":"paragraph","text":"This is not the same phenomenon as language shift. Borrowing can occur within continued use of Hindko. A technical term becomes part of a working conversation through the speech patterns of those using it, rather than remaining an untouched foreign object."},{"type":"paragraph","text":"The example also expands what counts as heritage knowledge. A workshop’s vocabulary records encounters with technologies, training and other languages. It may be less likely to appear in a ceremonial performance, but it belongs to the history of how people communicate and work."},{"type":"heading","level":2,"text":"Publications and recordings make another public"},{"type":"paragraph","text":"The Hindko Language and Culture Society presents publications and audiovisual material through its own platform. Such initiatives create places where language can be read and heard beyond a household or workplace. They should be understood as particular organisational efforts, not as a single institution speaking for every Hindko user."},{"type":"paragraph","text":"A useful archive would distinguish a literary reading, an interview and a conversation about a trade. Each has a different purpose and audience. Their variety is more informative than searching for one sample that supposedly captures an entire urban culture."},{"type":"paragraph","text":"Hindko’s heritage is consequently both literary and everyday. Following its use across settings makes urban encounter visible: languages meet, terms are adapted and speakers choose among possibilities. That living complexity deserves attention alongside the monuments and historic neighbourhoods with which the language is associated."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Khyber Pakhtunkhwa","Languages"],"province":"Khyber Pakhtunkhwa","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Hindko and the languages of urban encounter | Virsapur","description":"Hindko’s urban life is visible in changing language choices and specialised workplace vocabulary, not only in a list of places where it is spoken.","primaryKeyword":"Hindko language heritage","socialTitle":"Hindko and the languages of urban encounter","socialDescription":"Hindko’s urban life is visible in changing language choices and specialised workplace vocabulary, not only in a list of places where it is spoken."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Language shift and maintenance: Hindko community in Peshawar","url":"https://www.pjsel.jehanf.com/index.php/journal/article/view/450","publisher":"Pakistan Journal of Society, Education and Language7(2),2021","accessDate":"2026-10-22"},{"title":"English Loanword Adaptation in Hindko: Vehicle Vocabulary","url":"https://kjlr.pk/index.php/kjlr/article/view/431","publisher":"Haroon-ur-Rashid and Raja Nasim Akhtar, Kashmir Journal of Language Research18(1),2015","accessDate":"2026-10-22"},{"title":"Hindko Language and Culture Society","url":"https://hindko.org/en","publisher":"Hindko Language and Culture Society","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Researchabstractsread;75participantssampleboundednotpopulationclaim. Borrowingdistinctfromshift. No inventedHindkoforms. Societyhomepageestablishespublication/archiveactivitynotrepresentativeness.","editorialReason":"Explore documented multilingual settings rather than draw unsupported language boundaries.","sortOrder":249}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-pahari-and-pothwari-names-varieties-and-self-identification','pahari-and-pothwari-names-varieties-and-self-identification','review','{"id":"story-pahari-and-pothwari-names-varieties-and-self-identification","type":"story","slug":"pahari-and-pothwari-names-varieties-and-self-identification","title":"Pahari and Pothwari: names, varieties and self-identification","summary":"Pahari and Pothwari labels connect linguistic varieties, places and self-identification; careful description leaves room for those meanings to differ.","body":[{"type":"paragraph","text":"A language name can identify speech, place, ancestry or a relationship with other speakers. Sometimes it does several of these things at once. Pahari and Pothwari are therefore best approached through the people and varieties being described, rather than as labels whose meanings can be settled by choosing one spelling."},{"type":"paragraph","text":"This is not a reason to avoid description. It is a reason to make description more precise: who uses the name, for which variety, in what context?"},{"type":"heading","level":2,"text":"Naming is part of the evidence"},{"type":"paragraph","text":"Farah B. Nazir’s 2014 thesis on Potwari discusses the use of Pahari, Potwari and Mirpuri among speakers and in research. Her study focuses on a community in Leeds with migration connections to Mirpur. She explains the terminology chosen for that study while acknowledging the variety of names speakers themselves employ."},{"type":"paragraph","text":"The point is not that every label means exactly the same thing. Nor does one researcher’s choice settle the preferred name for every community. The account shows that language naming has a social history, including the circumstances of migration and the audiences to whom speakers explain themselves."},{"type":"paragraph","text":"An archive can preserve this complexity by recording a contributor’s own term alongside a broader catalogue category. The catalogue can then help people find related material without silently replacing the name used in the recording."},{"type":"heading","level":2,"text":"Study a variety closely"},{"type":"paragraph","text":"Awais Hussain’s 2024 research on negation identifies its principal data as the Chakswari variety and its migrant community. It examines how negative markers function within sentences. This is a tightly defined linguistic inquiry, not an attempt to make every speaker fit a single uniform standard."},{"type":"paragraph","text":"That local focus is a strength. A grammatical claim becomes more useful when readers know which speech it describes. The fact that a feature appears in one study does not establish that every related variety uses it in precisely the same way."},{"type":"paragraph","text":"It also illustrates why a discussion of language and dialect cannot be settled by prestige. A variety does not need a large publishing industry to possess systematic grammar. Conversely, similarity between neighbouring forms of speech does not determine how their speakers must identify politically or culturally."},{"type":"heading","level":2,"text":"Avoid making a map do too much"},{"type":"paragraph","text":"A place-name can help orient a reader, but it should not be converted automatically into an exclusive language boundary. People move, families maintain connections across places and speakers may use different names in different settings. A migration destination can become a significant site of literary or linguistic activity in its own right."},{"type":"paragraph","text":"For a public heritage record, uncertainty should be specific rather than evasive. “The speaker calls this variety Pahari” conveys useful information. “The terminology is disputed” is less useful unless the competing usages and their contexts are explained."},{"type":"paragraph","text":"The aim is not to invent a compromise label that everybody must accept. It is to make related materials discoverable while respecting the particular names, voices and research scopes they contain. Pahari and Pothwari then become openings into a complex linguistic world, rather than a naming argument that prevents readers from encountering it."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Languages"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Pahari and Pothwari: names, varieties and self-identification | Virsapur","description":"Pahari and Pothwari labels connect linguistic varieties, places and self-identification; careful description leaves room for those meanings to differ.","primaryKeyword":"Pahari Pothwari languages","socialTitle":"Pahari and Pothwari: names, varieties and self-identification","socialDescription":"Pahari and Pothwari labels connect linguistic varieties, places and self-identification; careful description leaves room for those meanings to differ."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Light Verb Constructions in Potwari","url":"https://pure.manchester.ac.uk/ws/files/54567249/FULL_TEXT.PDF","publisher":"FarahB.Nazir, University of Manchester doctoral thesis,2014","accessDate":"2026-10-22"},{"title":"Clausal negation in Pahari-Pothwari","url":"https://etheses.whiterose.ac.uk/id/eprint/34946/","publisher":"Awais Hussain, University of York research thesis,2024","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Nazir namingdiscussion140wordsmax; Hussain~90. No contestedclassificationdeclaredsettled; no inventedbordersorintelligibilitypercentages. Selfidentificationframeworkeditorialnotcensus.","editorialReason":"Require speaker-sensitive terminology and distinguish linguistic classification from political labels.","sortOrder":250}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-kashmiri-literary-memory-beyond-a-single-script','kashmiri-literary-memory-beyond-a-single-script','review','{"id":"story-kashmiri-literary-memory-beyond-a-single-script","type":"story","slug":"kashmiri-literary-memory-beyond-a-single-script","title":"Kashmiri literary memory beyond a single script","summary":"Kashmiri literary memory travels through scripts, voices and editorial hands. A script history and a recorded story collection reveal different kinds of evidence.","body":[{"type":"paragraph","text":"A language is not identical to the alphabet in which a reader first encounters it. That distinction matters especially for Kashmiri literary memory. A poem heard from a relative, a manuscript copied in a historic script and a printed translation can preserve related material while offering very different routes into it. None should be treated as the complete tradition."},{"type":"paragraph","text":"The Unicode Consortium’s account identifies Sharada as a historical script used for Kashmiri, Sanskrit and other languages of northern South Asia. It describes the expansion of Arabic-script writing for Kashmiri and of Devanagari as part of Sharada’s changing position, with specialized ritual uses continuing. This is a history of writing practices, not evidence that every work in Sharada is Kashmiri or that every Kashmiri reader shares one script."},{"type":"heading","level":2,"text":"A story passes through several hands"},{"type":"paragraph","text":"The British Library’s record for Hatim’s tales offers a more intimate example. It describes stories and songs recorded by Aurel Stein with the assistance of a Kashmiri pandit, then edited and translated by George Grierson. The archive also preserves an additional index comparing words in the pandit’s text with those in Stein’s. Even the existence of that comparison complicates the idea of a single transparent record."},{"type":"paragraph","text":"Who told a story, who wrote it down and who supplied its English wording are separate questions. A reader opening such a collection should identify those roles before quoting a line as the storyteller’s exact expression. The names on a title page can make collecting and editing visible while leaving the conditions of narration less clear. That imbalance is itself worth investigating rather than quietly repeating."},{"type":"heading","level":2,"text":"Compare the layers, not just the letters"},{"type":"paragraph","text":"A useful reading exercise begins with one short passage available in more than one form. First establish that the versions actually correspond. Then distinguish changes in script from altered wording, an editor’s punctuation and a translator’s interpretation. If a published text has no associated recording, its spelling cannot by itself establish how a particular narrator performed the passage."},{"type":"paragraph","text":"An English translation may help a new reader follow a story, yet it does not preserve every sound or every ambiguity. A transcription can keep the wording closer to its source without becoming easy for an unfamiliar reader. An image of the manuscript adds another dimension: corrections, spacing and the physical arrangement of a page can remain invisible in a clean modern edition."},{"type":"paragraph","text":"For a heritage archive, the practical response is to preserve these distinctions in the description. Identify the language, script, source edition and person responsible for each transformation. Keep a narrator’s role separate from that of a collector. Include community knowledge about pronunciation and use where permission allows. Kashmiri literary memory becomes more widely accessible when these layers are explained, not when they are compressed into a single authoritative-looking English paragraph."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Azad Kashmir","Languages"],"province":"Azad Jammu and Kashmir","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Kashmiri literary memory beyond a single script | Virsapur","description":"Kashmiri literary memory travels through scripts, voices and editorial hands. A script history and a recorded story collection reveal different kinds of evidence.","primaryKeyword":"Kashmiri literature scripts","socialTitle":"Kashmiri literary memory beyond a single script","socialDescription":"Kashmiri literary memory travels through scripts, voices and editorial hands. A script history and a recorded story collection reveal different kinds of evidence."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Unicode 17, Chapter 15: Sharada","url":"https://www.unicode.org/versions/Unicode17.0.0/core-spec/chapter-15/","publisher":"Unicode Consortium","accessDate":"2026-10-22"},{"title":"Mss Eur E223/8: Hatim’s tales and Grierson’s additional index","url":"https://searcharchives.bl.uk/catalog/040-002278888","publisher":"British Library","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Regional category is inherited from plan but subject spans Kashmir beyond AJK. Specialist/community review required. No literary quotations. Unicode-derived account about80words; BL about90.","editorialReason":"Map the research questions and require specialist review of script and regional claims.","sortOrder":251}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-gojri-songs-and-a-mobile-pastoral-vocabulary','gojri-songs-and-a-mobile-pastoral-vocabulary','review','{"id":"story-gojri-songs-and-a-mobile-pastoral-vocabulary","type":"story","slug":"gojri-songs-and-a-mobile-pastoral-vocabulary","title":"Gojri songs and a mobile pastoral vocabulary","summary":"Gojri songs can illuminate livelihood and movement, but language should not be reduced to a single nomadic identity.","body":[{"type":"paragraph","text":"A song about movement does not prove that every speaker of its language moves with livestock. Gojri offers a good reason to resist that shortcut. Language connects people whose work, residence and relationship to seasonal travel can differ considerably. Reading its oral literature only as the voice of an imagined, uniformly nomadic population would conceal the very diversity that makes it interesting."},{"type":"paragraph","text":"Wayne Losey’s 2002 study of Gojri writing distinguishes nomadic pastoralists, settled agricultural communities and people practising seasonal movement. Its discussion of Hazara also differentiates particular pastoral groups and patterns of contact. These are observations from a situated study, not a timeless classification of every Gojri-speaking household. Occupational labels and language names cannot simply stand in for one another."},{"type":"heading","level":2,"text":"What a pastoral word can carry"},{"type":"paragraph","text":"For a listener, vocabulary connected with animals or terrain is an invitation to ask precise questions. Does a term distinguish an animal’s age, a kind of pasture, a stage of a journey or a relationship between people? Does the singer use it literally, affectionately or as a comparison? An English gloss such as cattle or mountains might be convenient while removing the distinction that gives the verse its force."},{"type":"paragraph","text":"Those possibilities should be investigated through an actual recording and a knowledgeable speaker, not supplied from imagination. A useful annotation would connect a word to its place in the performance, retain the speaker’s explanation and distinguish that explanation from the editor’s inference. The same expression in conversation might do different work from its use in a refrain."},{"type":"paragraph","text":"Losey also describes Gojri literary activity around a circle established at Nawanshahr near Abbottabad in the 1960s. That evidence places writing and organized literary exchange alongside oral transmission. It challenges a false opposition between a mobile people who supposedly only sing and settled institutions that supposedly produce literature."},{"type":"heading","level":2,"text":"Listening as a shared research task"},{"type":"paragraph","text":"The Forum for Language Initiatives reports participation by Gojri community representatives in its 2023 ethnomusicology workshop alongside several other language communities. The event concerned the skills needed to document indigenous music. It is evidence of active work on representation, not proof that a single workshop exhaustively documented a repertoire."},{"type":"paragraph","text":"A strong song record needs more than a language label and an attractive landscape image. Ask who performed it, whether the words are their composition or an inherited version, what occasion shaped the performance and how the performer wishes to be credited. Record separately any restrictions on circulation. An accessible recording is not automatically an invitation to detach a singer’s voice for a tourism montage."},{"type":"paragraph","text":"The most revealing comparison may be between two performances rather than two dictionary entries. A change in emphasis, audience or location can alter what listeners recognize in familiar words. Following those differences keeps livelihood within the story without turning livelihood into a compulsory identity. Gojri then appears as a language used by people making choices, not as a decorative soundtrack assigned to a single way of life."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Languages"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Gojri songs and a mobile pastoral vocabulary | Virsapur","description":"Gojri songs can illuminate livelihood and movement, but language should not be reduced to a single nomadic identity.","primaryKeyword":"Gojri oral literature","socialTitle":"Gojri songs and a mobile pastoral vocabulary","socialDescription":"Gojri songs can illuminate livelihood and movement, but language should not be reduced to a single nomadic identity."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Writing Gojri: Linguistic and Sociolinguistic Constraints on a Standardized Orthography for the Gujars of South Asia","url":"https://www.fli-online.org/documents/languages/gojri/losey_thesis.pdf","publisher":"Wayne E. Losey / University of North Dakota","accessDate":"2026-10-22"},{"title":"Annual Report 2023: Understanding our Indigenous Music","url":"https://fli-online.org/wp-content/uploads/2024/05/FLI-Annual-Report.pdf","publisher":"Forum for Language Initiatives","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"No specific song text or invented pastoral lexicon. Losey historical2002fieldwork not current demographic census. About140derivedwordsLosey and45FLI(shared with254totalunder200). Community review needed.","editorialReason":"Examine language and livelihood without assuming every speaker shares a nomadic life.","sortOrder":252}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-kalasha-language-documentation-and-community-agency','kalasha-language-documentation-and-community-agency','review','{"id":"story-kalasha-language-documentation-and-community-agency","type":"story","slug":"kalasha-language-documentation-and-community-agency","title":"Kalasha language documentation and community agency","summary":"Kalasha documentation is strongest when speakers are collaborators, authors and decision-makers—not simply subjects of an outsider’s recording.","body":[{"type":"paragraph","text":"A microphone can preserve a voice without giving its speaker much control over the resulting archive. For Kalasha language documentation, the difference between being recorded and directing a record is therefore fundamental. The question is not only whether words survive in a repository, but whether speakers can decide how their language is described, taught and circulated."},{"type":"paragraph","text":"Qandeel Hussain and Jeff Mielke’s 2020 language snapshot describes a multilingual community in which Kalasha is used in everyday life and taught locally. It credits community members, working with Gregory and Elsa Cooper, in the development of a Roman writing system. That attribution matters: writing was not simply delivered to passive recipients by an outside expert."},{"type":"paragraph","text":"The same research identifies Ishpata News as a community-launched media outlet, producing material in Kalasha and Urdu. A language archive should therefore look beyond the familiar image of an elderly narrator preserving a disappearing past. Community news and contemporary communication also belong in the picture, even when they do not resemble the ceremonial material an outsider expects to see."},{"type":"heading","level":2,"text":"What the record is for"},{"type":"paragraph","text":"Different recordings answer different needs. A carefully elicited sound contrast can support phonetic research. A conversation can document how speakers manage an exchange. A story recorded for children can serve readers and listeners who are learning. None is automatically a substitute for the others, and a technically sophisticated research collection may still be difficult for a local teacher to use."},{"type":"paragraph","text":"Hussain and Mielke describe their own work on speech sounds and spontaneous narratives, including research across Birir, Bumburet and Rumbur. That scope is more precise than claiming to have captured the language in its entirety. A reader should similarly ask which speakers, places and speaking situations a particular recording represents before treating it as a model for everyone."},{"type":"heading","level":2,"text":"Agency after the recording"},{"type":"paragraph","text":"A useful project discussion would cover naming, access and future reuse before publication. Does the speaker want their name attached? Who can correct the transcript? Can a passage be withdrawn? Does permission for research include a public website, a commercial film or a machine-learning dataset? These are distinct choices; a general expression of enthusiasm for documentation cannot answer all of them."},{"type":"paragraph","text":"Practical access also matters. A repository identifier is valuable, but a community participant may need a copy that plays on their own phone, a readable transcript or material suitable for a class. A project can plan for those uses without assuming that everyone wants the same writing system, format or audience."},{"type":"paragraph","text":"For visitors, the corresponding discipline is simple but demanding: do not make cultural distinctiveness into a request for performance. A person speaking Kalasha is not obliged to supply a story, costume or ritual demonstration. Documentation gains depth when it follows the purposes speakers themselves identify. Its success should be measured not just in hours recorded, but in the continuing relationships and usable resources that those hours make possible."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Khyber Pakhtunkhwa","Languages"],"province":"Khyber Pakhtunkhwa","district":"Lower Chitral","relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Kalasha language documentation and community agency | Virsapur","description":"Kalasha documentation is strongest when speakers are collaborators, authors and decision-makers—not simply subjects of an outsider’s recording.","primaryKeyword":"Kalasha language documentation","socialTitle":"Kalasha language documentation and community agency","socialDescription":"Kalasha documentation is strongest when speakers are collaborators, authors and decision-makers—not simply subjects of an outsider’s recording."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Kalasha (Pakistan) – Language Snapshot","url":"https://www.elpublishing.org/sites/default/files/attachments/ldd17_04_0.pdf","publisher":"Qandeel Hussain and Jeff Mielke / Language Documentation and Description","accessDate":"2026-10-22"},{"title":"Ishpata News community media channel, identified in the language snapshot","url":"https://www.youtube.com/user/voiceofkalash/videos","publisher":"Ishpata News","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Second reference identification established from primary research, not independent viewing of all videos. No claims about current channel output. Snapshot-derivedfactsabout150words. No speculative origins/religious essentialism. Community-led review before release.","editorialReason":"Separate language documentation from outsider spectacle and require community-led sources.","sortOrder":253}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-making-a-keyboard-for-a-small-language','making-a-keyboard-for-a-small-language','review','{"id":"story-making-a-keyboard-for-a-small-language","type":"story","slug":"making-a-keyboard-for-a-small-language","title":"Making a keyboard for a small language","summary":"A keyboard turns a writing system into everyday digital action. Gawri offers a concrete example of the distinct work done by input, encoding and fonts.","body":[{"type":"paragraph","text":"A person can know exactly what they want to write and still be unable to enter it on a phone. The obstacle may be a missing letter, an inaccessible mark or a sequence that looks correct on one screen and fails on another. For a language with fewer ready-made digital resources, keyboard design is part of making ordinary correspondence possible."},{"type":"paragraph","text":"The Rachitrali-Gawri keyboard provides a specific example. Keyman’s record credits Rehmat Aziz Chitrali at the Khowar Academy with developing an Arabic-script keyboard for Gawri. It identifies Unicode encoding and support across desktop, mobile and web platforms. This establishes an available input tool; it does not establish that every Gawri speaker uses it or agrees on every spelling."},{"type":"heading","level":2,"text":"Three layers behind a visible word"},{"type":"paragraph","text":"A keyboard determines how an action produces text. A font determines how that text is drawn. Character encoding gives the underlying characters stable digital identities. These layers interact, but replacing one does not automatically repair the others. A beautiful font cannot supply a missing keyboard key, and an accessible key cannot ensure that every receiving device will display its character well."},{"type":"paragraph","text":"Unicode’s discussion of historic scripts makes the distinction concrete: it separates encoded characters from variations handled by fonts, such as certain scribal forms. The implication for a new keyboard is important. Designers need to know whether a desired shape represents a distinct character or a visual variant before deciding what a key should produce."},{"type":"paragraph","text":"Imagine testing a short message that includes ordinary words, a personal name, punctuation and numbers. Does it remain readable after being copied into another application? Can the recipient reply without reconstructing each character? Can the writer correct a mistake without deleting an entire cluster? These are useful tests precisely because they resemble everyday writing rather than a demonstration screen."},{"type":"heading","level":2,"text":"A layout has to be learnable"},{"type":"paragraph","text":"Design also involves choices about placement. Familiar letters may belong where experienced users expect them, while additional characters need discoverable positions. A desktop layout with several modifier keys may not translate comfortably into a small touch keyboard. The right solution depends on its users and their existing habits, not on how symmetrical the chart looks."},{"type":"paragraph","text":"Community testing should include actual writing tasks. Ask people to compose something they would normally send, then observe where they hesitate. If a character is available but repeatedly overlooked, the problem may be discoverability rather than missing technical support. If people disagree about the spelling, that is an orthographic discussion which the software should not pretend to settle alone."},{"type":"paragraph","text":"For a heritage platform, supporting the resulting text means preserving it as text. A screenshot may look correct but prevents searching, copying and many assistive uses. Keep the language name, keyboard documentation and relevant display requirements available to editors. Digital inclusion begins with the unglamorous success of a message that can be typed, sent, found again and read by the person for whom it was intended."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Languages"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Making a keyboard for a small language | Virsapur","description":"A keyboard turns a writing system into everyday digital action. Gawri offers a concrete example of the distinct work done by input, encoding and fonts.","primaryKeyword":"Pakistan indigenous language keyboards","socialTitle":"Making a keyboard for a small language","socialDescription":"A keyboard turns a writing system into everyday digital action. Gawri offers a concrete example of the distinct work done by input, encoding and fonts."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Rachitrali-Gawri keyboard","url":"https://keyman.com/en/keyboards/rac_gawri","publisher":"Keyman / Rehmat Aziz Chitrali","accessDate":"2026-10-22"},{"title":"Unicode 17, Chapter 15: character and rendering distinctions","url":"https://www.unicode.org/versions/Unicode17.0.0/core-spec/chapter-15/","publisher":"Unicode Consortium","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Keyboardfactsabout65words; technical explanation original synthesis. Unicodebudgetshared250+253under200. No installation claims or endorsement of sole community standard.","editorialReason":"Explain the practical work of digital writing systems through documented community projects.","sortOrder":254}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-what-an-orthography-workshop-actually-decides','what-an-orthography-workshop-actually-decides','review','{"id":"story-what-an-orthography-workshop-actually-decides","type":"story","slug":"what-an-orthography-workshop-actually-decides","title":"What an orthography workshop actually decides","summary":"Choosing how a language is written involves sound, learning, identity and practical use. A Bateri workshop shows why agreement extends beyond an alphabet chart.","body":[{"type":"paragraph","text":"An orthography workshop is not simply a meeting at which someone draws an alphabet. It concerns the conventions that let people recognize spoken words in writing: how sounds are represented, where words are divided and how unfamiliar forms are handled. A chart can display a decision without showing the discussions that made it workable—or the disagreements still unresolved."},{"type":"paragraph","text":"The Forum for Language Initiatives describes a concrete Bateri example in its 2023 annual report. Seventeen teachers, students and community researchers attended a three-day follow-up to an earlier workshop. Their work addressed characters for distinctive sounds, vowels, diphthongs and diacritics, along with borrowed words, compounds and infinitive forms. That range shows how quickly alphabet design becomes the practical work of writing sentences."},{"type":"heading","level":2,"text":"Sound analysis is only one part"},{"type":"paragraph","text":"A linguist may identify a contrast between two sounds, but deciding how readers should represent that contrast requires further choices. Should it receive a separate letter, a mark added to an existing letter or a sequence of letters? Which option can learners distinguish, remember and reproduce? A technically elegant distinction may still be awkward in handwriting or unfamiliar on a keyboard."},{"type":"paragraph","text":"SIL Australia’s community-based orthography training explicitly treats acceptance, identity and usability alongside technical considerations. Its programme includes designing, testing, documenting and evaluating proposals. This is a useful framework, not evidence that one outside organization can determine the correct system for another language community."},{"type":"paragraph","text":"Consider a proposed spelling for a frequently used word. Reading it aloud checks one kind of recognition. Asking several people to write the same word from speech tests another. Trying it in a sentence may reveal a problem with word boundaries that an isolated word list missed. These exercises investigate different aspects of usability; none alone is a vote establishing permanent correctness."},{"type":"heading","level":2,"text":"Whose agreement counts?"},{"type":"paragraph","text":"Participation needs to be described rather than assumed. Teachers may know classroom difficulties, experienced writers may know existing conventions, and younger users may recognize obstacles on phones. Speakers of different local varieties can identify where a proposal privileges one pronunciation. The purpose is not to make every spelling encode every possible difference, but to understand what a common convention includes and leaves visible."},{"type":"paragraph","text":"A workshop report should distinguish a suggestion from a tested decision and a decision from widespread adoption. Agreement among participants is meaningful, yet it does not automatically describe absent speakers. Recording the reasons for a choice makes later revision easier: a future editor can see whether the priority was pronunciation, familiarity, consistency or compatibility with existing books."},{"type":"paragraph","text":"For heritage readers, the outcome is best understood as social infrastructure. A usable writing convention can help produce correspondence, teaching materials and literature, but it remains connected to the people who use it. The workshop’s most important artifact may be an explanation of how choices were tested and who can revisit them, rather than a polished alphabet poster presented as the final word."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Languages"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"What an orthography workshop actually decides | Virsapur","description":"Choosing how a language is written involves sound, learning, identity and practical use. A Bateri workshop shows why agreement extends beyond an alphabet chart.","primaryKeyword":"language orthography Pakistan","socialTitle":"What an orthography workshop actually decides","socialDescription":"Choosing how a language is written involves sound, learning, identity and practical use. A Bateri workshop shows why agreement extends beyond an alphabet chart."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Annual Report 2023: Enhancing Bateri Language Writing","url":"https://fli-online.org/wp-content/uploads/2024/05/FLI-Annual-Report.pdf","publisher":"Forum for Language Initiatives","accessDate":"2026-10-22"},{"title":"Community-Based Orthography Design","url":"https://www.sila.org.au/event/orthography-workshop/","publisher":"SIL Australia","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"FLI2023facts~85words shared251~45=>130; SIL~50. Methodological recommendations original, not claim of attendance/outcomes beyond report.","editorialReason":"Distinguish sound analysis, community preference and technical encoding.","sortOrder":255}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-transliteration-is-not-translation','transliteration-is-not-translation','review','{"id":"story-transliteration-is-not-translation","type":"story","slug":"transliteration-is-not-translation","title":"Transliteration is not translation","summary":"Changing a script is not the same as conveying meaning in another language. Manuscript titles and catalogue records make the distinction visible.","body":[{"type":"paragraph","text":"A heritage label can show an unfamiliar name in familiar letters without explaining what the name means. That operation is transliteration: representing writing through another script. Translation addresses meaning in another language. The two often appear together, which makes them easy to confuse, but they solve different problems for a reader."},{"type":"paragraph","text":"The Library of Congress maintains ALA-LC romanization tables for numerous writing systems, including Urdu. These are structured conventions for rendering non-Roman writing in Roman letters. Their existence also explains why an academic catalogue may spell a name differently from a tourist sign: a particular system is doing specific work, rather than merely decorating the word with unusual marks."},{"type":"heading","level":2,"text":"One manuscript, several descriptions"},{"type":"paragraph","text":"Consider the Library of Congress record for a manuscript of Amir Khusraw Dihlavi’s Khamsah, held by the Walters Art Museum. The record identifies Persian as the language and nastaʿliq as the writing style. It also explains Khamsah as a quintet. The Roman-letter title and the English explanation perform different tasks; neither converts the manuscript itself into an English text."},{"type":"paragraph","text":"The catalogue cautiously associates this copy with late-sixteenth-century Lahore. Its description of a particular manuscript should not be confused with the date of the author’s composition. Here, too, preserving the distinctions between a work, a copy and an English catalogue entry prevents an apparently small label from carrying a large historical error."},{"type":"heading","level":2,"text":"Sound is a third question"},{"type":"paragraph","text":"Pronunciation introduces another layer. A system designed to represent letters consistently is not necessarily a pronunciation guide for an English-speaking visitor. The reader needs to know what its signs mean. Conversely, an informal spelling intended to help someone say a name may omit distinctions useful for finding the original written form."},{"type":"paragraph","text":"This matters when searching archives. If a catalogue uses a formal romanization and a family history uses an everyday spelling, the two may refer to the same person or work. A search aid can connect those forms without claiming that one is a translation of the other. Keeping the source spelling visible makes the connection inspectable."},{"type":"paragraph","text":"Translation requires additional decisions that an alphabet table cannot make. A title may carry a literal sense, a conventional English rendering and associations with a literary genre. A translator has to decide what an intended reader needs and where an explanation belongs. Replacing every culturally specific word with a short English equivalent can make a sentence fluent while obscuring the distinction the author wanted."},{"type":"paragraph","text":"A well-prepared heritage entry therefore separates the original form, its chosen transliteration, a translation where appropriate and any pronunciation assistance. It names the system or translator when that information is available. This is not an exercise in making labels cumbersome. It lets a visitor know whether they are seeing the name, an attempt to say it, or an interpretation of its meaning—and follow the record back to its source."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Languages"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Transliteration is not translation | Virsapur","description":"Changing a script is not the same as conveying meaning in another language. Manuscript titles and catalogue records make the distinction visible.","primaryKeyword":"transliteration translation heritage","socialTitle":"Transliteration is not translation","socialDescription":"Changing a script is not the same as conveying meaning in another language. Manuscript titles and catalogue records make the distinction visible."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"ALA-LC Romanization Tables","url":"https://www.loc.gov/catdir/cpso/roman","publisher":"Library of Congress","accessDate":"2026-10-22"},{"title":"The Khamsah of Amir Khusraw Dihlavi, Walters W.624","url":"https://www.loc.gov/item/2021667230/","publisher":"Library of Congress / Walters Art Museum","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"No invented transliteration examples or claims of reading Persian original. LOCromanabout55,manuscriptabout65; remaining original explanation. Specialist review for any future originalscript additions.","editorialReason":"Use heritage names and literary examples to clarify two different editorial tasks.","sortOrder":256}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-why-a-place-can-have-several-spellings','why-a-place-can-have-several-spellings','review','{"id":"story-why-a-place-can-have-several-spellings","type":"story","slug":"why-a-place-can-have-several-spellings","title":"Why a place can have several spellings","summary":"Different spellings can result from different languages, romanization systems and inherited records. The task is to connect names without erasing their histories.","body":[{"type":"paragraph","text":"A place-name can look inconsistent even when each writer has followed a deliberate convention. Moving a name between scripts requires choices about vowels, consonants and marks that may not have an obvious English equivalent. Local usage, earlier maps and the habits of particular institutions can leave several forms circulating at once."},{"type":"paragraph","text":"The United Kingdom’s Permanent Committee on Geographical Names publishes romanization systems developed with the United States Board on Geographic Names. Its guidance makes clear that systems are applied within policies for particular areas. This is not evidence for a universal rule compelling every resident, historian or cultural organization to spell a Pakistani name in the same way."},{"type":"paragraph","text":"A historical UN working-group account of Urdu romanization shows concrete differences between systems, including their treatment of long vowels and certain consonants. Such choices can produce visibly different Roman-letter forms from the same source writing. Removing diacritics for convenience can introduce another difference without implying that the place itself has changed."},{"type":"heading","level":2,"text":"Start with the record you are using"},{"type":"paragraph","text":"UNESCO’s World Heritage entry uses Moenjodaro in its official property title. A researcher citing that entry should retain its title accurately, even if another publication uses a different spelling. The citation identifies a source, not a ruling that every alternative is illegitimate. Search systems can recognize variants while a display label follows a consistent editorial policy."},{"type":"paragraph","text":"The reverse problem deserves equal attention: similar-looking names do not necessarily identify the same place. A district name, a settlement and an archaeological site may share a word without sharing boundaries or a precise location. Before merging records, compare the type of place, its location and the source’s date. Spelling similarity is a lead, not sufficient proof of identity."},{"type":"heading","level":2,"text":"Preserve names without manufacturing certainty"},{"type":"paragraph","text":"An effective place record can have a preferred display name and separately documented variants. Each variant should say where it was found, rather than becoming a list of plausible spellings generated by guesswork. If an older source describes a different administrative area, that temporal context belongs with the name."},{"type":"paragraph","text":"Local pronunciation also deserves a place in the discussion, but it should come from speakers rather than an editor’s intuition. A recording, with permission and appropriate attribution, can supplement written forms. It should not be presented as the only possible pronunciation if usage varies. Language affiliation and personal preference may matter as much as a standardized map label."},{"type":"paragraph","text":"For a visitor, these distinctions are practical. The name used to ask for directions may differ from the form that retrieves an academic excavation report. A heritage platform can help bridge those settings by making the connection explicit. It should not translate an uncertain etymology into an alluring story merely to explain a spelling difference."},{"type":"paragraph","text":"The goal is dependable recognition with an honest trail of evidence. A consistent interface need not pretend that historical writing was equally consistent. When variants are documented carefully, a name becomes a path between records rather than a barrier that makes the same place disappear from a search."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Languages"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Why a place can have several spellings | Virsapur","description":"Different spellings can result from different languages, romanization systems and inherited records. The task is to connect names without erasing their histories.","primaryKeyword":"Pakistani place name spellings","socialTitle":"Why a place can have several spellings","socialDescription":"Different spellings can result from different languages, romanization systems and inherited records. The task is to connect names without erasing their histories."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Romanization systems","url":"https://www.gov.uk/government/publications/romanization-systems","publisher":"Permanent Committee on Geographical Names","accessDate":"2026-10-22"},{"title":"Report on the current status of United Nations romanization systems: Urdu","url":"https://arhiiv.eki.ee/wgrs/rom1_ur.htm","publisher":"UNGEGN Working Group on Romanization Systems / Institute of the Estonian Language","accessDate":"2026-10-22"},{"title":"Archaeological Ruins at Moenjodaro","url":"https://whc.unesco.org/en/list/138/","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"UNESCOusedtitleonly~10words. UNreporthistoricalnotcurrentmandatoryPakpolicy. No invented aliases/etymology. PCGN~35UN~65.","editorialReason":"Explain transliteration, language variation and archival forms without inventing standardisation rules.","sortOrder":257}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-reading-a-bilingual-inscription','reading-a-bilingual-inscription','review','{"id":"story-reading-a-bilingual-inscription","type":"story","slug":"reading-a-bilingual-inscription","title":"Language, script and the evidence for a bilingual inscription","summary":"Two scripts do not automatically mean two languages. Ashokan rock edicts and a documented Indo-Greek coin show how to ask the right questions.","body":[{"type":"paragraph","text":"Before calling an inscription bilingual, ask two different questions: what language is being expressed, and what script is used to write it? A language can be written in more than one script, while a single script can serve more than one language. Counting visually different letter forms is therefore not enough to establish bilingual communication."},{"type":"paragraph","text":"The Ashokan rock edicts linked from this article offer a useful warning. Shahbazgarhi’s Tentative List description identifies a Prakrit text written in Kharosthi. Prakrit and Kharosthi are not the names of two languages in that description. One identifies the language, the other the writing system. A reader should not turn that pair of terms into a claim that the monument carries two parallel translations."},{"type":"heading","level":2,"text":"A small object offers a comparison"},{"type":"paragraph","text":"The British Museum’s coin IOC.104, attributed to Menander I, records a Greek inscription on one side and a Kharosthi legend on the other. Its catalogue describes a wheel and a palm frond among the designs. The object was collected at Begram in present-day Afghanistan; it is a comparative example from the wider region, not a newly identified Pakistani monument."},{"type":"paragraph","text":"Even here, the catalogue’s script description is a starting point. To compare the actual messages, a reader needs an edited reading and identification of the language represented by each legend. The presence of two writing systems does not, by itself, tell us whether their wording is equivalent, whether titles differ or how a contemporary viewer understood them."},{"type":"heading","level":2,"text":"Read the relationship between the texts"},{"type":"paragraph","text":"For a securely identified bilingual inscription, begin by locating the two texts on the object. Are they placed side by side, on opposing faces or in different parts of a building? Are they contemporary, or could one have been added later? Those questions connect linguistic interpretation with the object’s material history rather than treating words as detached statements."},{"type":"paragraph","text":"Next compare what an editor says is actually present. A readable letter, a restored gap and a disputed reading carry different levels of certainty. An English translation may smooth all three into a confident sentence unless its notes are consulted. Two fluent translations can also hide differences in titles, names or formulae that matter to the historical argument."},{"type":"paragraph","text":"A bilingual text can suggest an effort to address different readers, but it cannot establish that every inhabitant of a region knew both languages. Nor does the language of a ruler’s proclamation necessarily describe ordinary conversation. Claims about education, identity or administration require additional evidence beyond the inscription’s mere existence."},{"type":"paragraph","text":"The reward for this slower approach is a more interesting encounter. Instead of treating multilingual writing as a slogan about cultural fusion, we can examine a particular act of communication: who commissioned it, what was made legible and how its forms were arranged. The first step remains modest and precise—name the language and script separately, then show the evidence for calling a text bilingual."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Languages"],"province":null,"district":null,"relatedDistrictIds":["khyber-pakhtunkhwa-mansehra","khyber-pakhtunkhwa-mardan"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-doam-136","major-doam-4621"],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Language, script and the evidence for a bilingual inscription | Virsapur","description":"Two scripts do not automatically mean two languages. Ashokan rock edicts and a documented Indo-Greek coin show how to ask the right questions.","primaryKeyword":"language script bilingual inscriptions","socialTitle":"Language, script and the evidence for a bilingual inscription","socialDescription":"Two scripts do not automatically mean two languages. Ashokan rock edicts and a documented Indo-Greek coin show how to ask the right questions."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Shahbazgarhi Rock Edicts, Tentative List entry","url":"https://whc.unesco.org/en/tentativelists/1880/","publisher":"UNESCO World Heritage Centre / Pakistan submission","accessDate":"2026-10-22"},{"title":"Coin of Menander I, IOC.104","url":"https://www.britishmuseum.org/collection/object/C_IOC-104","publisher":"British Museum","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Plan257titleandSEOkeywordrefinedwithrootpermission; stableIDslug retained. Mansehra/Shahbazgarhi links are comparison not bilingual examples. UNESCO1880previous150~80+here45<=200. BM~100. CoinfoundBegramAfghanistan NOTPakistaniheritage-location claim. Museumreadthroughindexedcatalogue403direct.","editorialReason":"Teach how to identify languages and translations before claiming a monument’s message.","sortOrder":258}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-heer-as-a-changing-literary-work','heer-as-a-changing-literary-work','review','{"id":"story-heer-as-a-changing-literary-work","type":"story","slug":"heer-as-a-changing-literary-work","title":"Heer as a changing literary work","summary":"Heer survives through editions, performance and reinterpretation. Reading a particular version reveals more than treating the familiar plot as an unchanging text.","body":[{"type":"paragraph","text":"Knowing the story of Heer and Ranjha is not the same as knowing a particular text of Heer. A plot can be retold in a few sentences while its literary force depends on who speaks, how a scene unfolds and what a performance chooses to emphasize. The familiar names invite recognition; they should also invite a closer look at the version in front of us."},{"type":"paragraph","text":"Ankur Barua and Hina Khalid identify Waris Shah’s 1766 Heer as a celebrated qissa rendition within a longer history of the tale. Their theological reading attends to the interplay of love, separation and religious imagery. They draw comparisons with Yusuf and Zulaikha and with Krishna, without reducing the work to a single straightforward allegory."},{"type":"paragraph","text":"Those associations are interpretations of literary relationships, not evidence that all audiences experience the poem identically. A reader may notice an argument about desire, social authority or spiritual longing in a particular passage. The useful next step is to show how the words and dramatic setting sustain that reading, rather than announcing one hidden meaning for the entire work."},{"type":"heading","level":2,"text":"A tradition can argue with itself"},{"type":"paragraph","text":"Sara Kazmi’s doctoral research examines modern Punjabi writers who rework inherited forms, including the Heer qissa, across India, Pakistan and Britain. Her account emphasizes political and social contestation rather than a simple longing for an untouched past. This makes adaptation part of literary history, not merely a departure from it."},{"type":"paragraph","text":"The distinction helps when comparing an older edition with a contemporary performance. Ask what has been selected, reordered or brought into focus. If a production gives a character more room to speak, that choice may change the audience’s sympathies even when the recognizable plot remains. If a retelling removes a difficult passage, its fluency should not make the removal invisible."},{"type":"heading","level":2,"text":"Read with an edition in view"},{"type":"paragraph","text":"Start with the title page and editorial introduction. Who prepared the text, which sources are named and what is the relationship between the original wording and any translation? A claim about Waris Shah should be traceable to the edition being used. A popular quotation circulating without that information is a research lead, not a secure textual reference."},{"type":"paragraph","text":"During a close reading, mark the speaker as carefully as the words. A character’s accusation, a narrator’s aside and an editor’s heading do not have the same authority. When a passage is performed, listen for the ways a voice makes those boundaries clear or deliberately unsettles them. Printed punctuation alone may not capture that movement."},{"type":"paragraph","text":"The heritage value of Heer lies partly in this continuing capacity to be read anew. Preserving a text does not require freezing every interpretation around it. It requires enough bibliographic and performance context for readers to distinguish the inherited work, a specific editorial form and the new argument an artist makes through it. Familiarity then becomes the beginning of attention rather than its substitute."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Punjab","Languages"],"province":"Punjab","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Heer as a changing literary work | Virsapur","description":"Heer survives through editions, performance and reinterpretation. Reading a particular version reveals more than treating the familiar plot as an unchanging text.","primaryKeyword":"Heer Waris Shah versions","socialTitle":"Heer as a changing literary work","socialDescription":"Heer survives through editions, performance and reinterpretation. Reading a particular version reveals more than treating the familiar plot as an unchanging text."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Writing Resistance in the Three Punjabs: Critical Engagements with Literary Tradition","url":"https://www.repository.cam.ac.uk/items/68ca6c38-c0c1-401b-a206-3599eeda62cd","publisher":"Sara Kazmi / University of Cambridge","accessDate":"2026-10-22"},{"title":"The Feminization of Love and the Indwelling of God: Theological Investigations Across Indic Contexts","url":"https://api.repository.cam.ac.uk/server/api/core/bitstreams/1bdf8ce7-0d66-4e4c-9941-48f323b20c1c/content","publisher":"Ankur Barua and Hina Khalid / Religions","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Kazmithesisabstractandtopicsearchconsulted; no claim of full manuscriptcollation. about90derivedwordsKazmi80BaruaKhalid. No poetryquoted. Specificedition/textreview stillrequired.","editorialReason":"Require edition-specific reading and distinguish text history from popular retellings.","sortOrder":259}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-sassui-and-the-landscapes-of-a-story','sassui-and-the-landscapes-of-a-story','review','{"id":"story-sassui-and-the-landscapes-of-a-story","type":"story","slug":"sassui-and-the-landscapes-of-a-story","title":"Sassui and the landscapes of a story","summary":"Sassui’s journey connects literary landscapes with questions of longing, courage and interpretation. A story’s geography is not an archaeological itinerary.","body":[{"type":"paragraph","text":"A landscape in a story can be both recognisable and transformed. A town becomes the place of separation; a difficult journey becomes an argument about persistence; distance is measured through longing rather than a surveyor’s line. Sassui’s story is especially powerful when these literary functions remain visible instead of being reduced to a supposed route that visitors can simply retrace."},{"type":"paragraph","text":"A study published by Begum Nusrat Bhutto Women University’s research journal summarizes the narrative’s connection between Bhanbhor and Punhun’s home in the Kech-Makran region. Its authors, Rab Nawaz Mangi and Abdul Sattar Memon, read Sassui as a figure of courage. This is an interpretation of a literary heroine, not independent evidence that each narrated event occurred at an identifiable archaeological location."},{"type":"paragraph","text":"Another study, published through the University of Sindh, examines Sassui as a spiritual seeker in Shah Abdul Latif Bhittai’s poetry. It discusses her presence across several poetic groupings, including Dessi, Mazoori, Abri, Kohyari and Hussaini. The emphasis is on the meaning of the quest, not the reconstruction of an itinerary."},{"type":"heading","level":2,"text":"Follow what the journey does"},{"type":"paragraph","text":"These approaches open different questions. A reading centred on courage asks how Sassui acts, what confronts her and how she responds. A spiritual reading asks what the outward journey makes imaginable about an inward search. Neither requires the landscape to become meaningless scenery. Rather, terrain matters because difficulty, distance and exposure shape the experience of seeking."},{"type":"paragraph","text":"When reading a selected passage, notice where the voice is situated. Is the speaker describing a place, addressing someone absent, speaking to the landscape or reflecting on the journey itself? Those changes affect the role of a mountain or road. A feature that seems merely descriptive in a plot summary may become an interlocutor in the poem."},{"type":"paragraph","text":"Different translations may also distribute attention differently. One can foreground physical hardship, another the vocabulary of devotion. Comparing them is useful only when they correspond to the same passage and identify their source text. A modern paraphrase of the entire story cannot stand in for a particular verse by Bhittai."},{"type":"heading","level":2,"text":"Map associations without inventing events"},{"type":"paragraph","text":"For a heritage map, literary association deserves its own clear label. It is reasonable to explain that a place is associated with a narrative when a source supports that connection. It is a different claim to state that a named character lived in a particular excavated room or followed a precisely plotted path. Attractive storytelling does not bridge that evidentiary gap."},{"type":"paragraph","text":"The distinction also gives readers more, not less, to explore. An archaeological account can explain what material remains show, while a literary account can trace how a place has been imagined. Keeping them connected but separate lets Sassui’s landscapes retain their emotional and intellectual force. We encounter a story about movement and resolve without asking the ground to certify every episode as a historical fact."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Sindh","Languages"],"province":"Sindh","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Sassui and the landscapes of a story | Virsapur","description":"Sassui’s journey connects literary landscapes with questions of longing, courage and interpretation. A story’s geography is not an archaeological itinerary.","primaryKeyword":"Sassui Punhun literary landscape","socialTitle":"Sassui and the landscapes of a story","socialDescription":"Sassui’s journey connects literary landscapes with questions of longing, courage and interpretation. A story’s geography is not an archaeological itinerary."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"“Sassui” the True Seeker of God","url":"https://sujo.usindh.edu.pk/index.php/IRJAH/article/view/1037","publisher":"Abdul Ghani Shaikh, Zain-ul-Abdin Sodhar and Hashaam Faek Mo’Shashaa / University of Sindh","accessDate":"2026-10-22"},{"title":"Representation of Women as a Symbol of Courage in Shah Abdul Latif Bhittai’s Sur Sassue","url":"https://bjmr.bnbwu.edu.pk/index.php/bjmr/article/view/30","publisher":"Rab Nawaz Mangi and Abdul Sattar Memon / BNBWU Journal of Multidisciplinary Research","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Interpretationsattributednotuniversalbelief. ~85derivedwordseachpaper; narrativegeographyexplicitlynotarchaeologicalproof. ReviewSindh-onlymetadata becauseKechcrossregionstory. Noquotes.","editorialReason":"Explore narrative geography without claiming fictional episodes are verified historical events.","sortOrder":260}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-sohni-across-oral-and-written-versions','sohni-across-oral-and-written-versions','review','{"id":"story-sohni-across-oral-and-written-versions","type":"story","slug":"sohni-across-oral-and-written-versions","title":"Sohni across oral and written versions","summary":"Sohni’s story changes as it moves between painted scene, sung dialogue and literary interpretation. Comparing media reveals what a plot summary leaves out.","body":[{"type":"paragraph","text":"Sohni is often remembered through a single image: a woman in the river with a clay vessel. Yet the image does not tell us which version we are encountering, whose perspective it adopts or how much of the story its audience already knows. Comparing a painting, a song and a literary reading shows why a familiar plot is only the starting point."},{"type":"paragraph","text":"In a British Museum exhibition account, a miniature dated approximately 1700–1750 is placed beside a CD case. The curator connects its depiction of Sohni crossing the Chenab with a childhood memory of a song performed by Nusrat Fateh Ali Khan. The song imagines a dialogue between Sohni and her pot. The display thus makes a personal listening history part of the encounter with an older object."},{"type":"paragraph","text":"The museum’s summary describes the tragic substitution of an unbaked vessel for the pot that supports Sohni in the water. This narrative detail makes the vessel more than a convenient prop. It concentrates trust, danger and betrayal in an object that can be pictured at once but unfolds differently when made to speak in song."},{"type":"heading","level":2,"text":"What changes with the medium?"},{"type":"paragraph","text":"A painting can hold a moment in suspense. It may show the crossing without narrating every cause or consequence. A song can return repeatedly to an address or phrase, extending a moment that a short prose retelling passes over quickly. A written version can elaborate dialogue or explain relationships. None of these possibilities makes one medium inherently more faithful; each requires its own careful reading."},{"type":"paragraph","text":"A University of Sindh study of Sur Suhni in Shah Abdul Latif Bhittai’s poetry approaches the heroine through emotion, agency and social constraint. That literary perspective is not identical to the museum curator’s account of personal memory. Both are useful when their scope remains clear: one interprets a poetic text, the other explains a particular curatorial juxtaposition."},{"type":"paragraph","text":"To compare versions, choose a specific episode. Ask whether the vessel is silent or addressed, whether the river is a setting or an active presence, and how the narrator positions the listener in relation to Sohni. These questions can reveal differences without requiring a competition to identify the supposedly purest retelling."},{"type":"heading","level":2,"text":"Give each version its own identity"},{"type":"paragraph","text":"A responsible archive should name the painter where known, the collection record, the performer and recording, or the editor and translator of a text. A song title alone does not establish the authorship of every word sung. An image caption should not silently borrow details from an unrelated modern adaptation."},{"type":"paragraph","text":"Nor should a literary association become a claim that an exact episode has been archaeologically verified. The story’s importance does not depend on that conversion. Its continuing force lies in how artists and listeners make the river crossing speak to them. Keeping the versions distinct allows us to notice those choices while still recognizing the shared story that makes the comparison possible."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Punjab","Languages"],"province":"Punjab","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Sohni across oral and written versions | Virsapur","description":"Sohni’s story changes as it moves between painted scene, sung dialogue and literary interpretation. Comparing media reveals what a plot summary leaves out.","primaryKeyword":"Sohni Mahiwal versions","socialTitle":"Sohni across oral and written versions","socialDescription":"Sohni’s story changes as it moves between painted scene, sung dialogue and literary interpretation. Comparing media reveals what a plot summary leaves out."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"A Confluence of Stories","url":"https://www.britishmuseum.org/blog/confluence-stories","publisher":"British Museum","accessDate":"2026-10-22"},{"title":"Unveiling Emotions of Women: A Glimpse into Shah Latif’s Poetry","url":"https://sujo.usindh.edu.pk/index.php/THE-WOMEN/article/view/6936","publisher":"The Women / University of Sindh","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Museumaccount~130words,universityabstract~40; no songlyricsquoted. No assertion of historicalevents. PunjabfacetnotexclusiveSohni/Suhnicirculation.","editorialReason":"Compare transmission and adaptation rather than flatten regional variants into one plot.","sortOrder":261}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-marui-reading-homeland-through-a-literary-figure','marui-reading-homeland-through-a-literary-figure','review','{"id":"story-marui-reading-homeland-through-a-literary-figure","type":"story","slug":"marui-reading-homeland-through-a-literary-figure","title":"Marui: reading homeland through a literary figure","summary":"Marui’s remembered homeland is made through relationships and address. Reading her voice closely avoids turning a complex literary figure into a simple slogan.","body":[{"type":"paragraph","text":"What makes a place home in a poem? It may be less a list of geographical features than a network of people, obligations and remembered ways of living. Marui is a compelling figure through whom to ask that question. Her attachment should be read in the movement of a particular text, not reduced in advance to a ready-made slogan about belonging."},{"type":"paragraph","text":"A University of Sindh study examines Sur Marui from Shah jo Risalo through the framework of dramatic monologue. Muhammad Hassan Khoso and colleagues identify Marui as the speaker and distinguish the people she addresses, including Omar, relatives and messengers. Their account locates that speech within her captivity. The important point for a reader is that her voice has an occasion and an audience."},{"type":"paragraph","text":"The authors also note that lyrical elements complicate a straightforward classification as dramatic monologue. Their conclusion is an argument about poetic form, not a claim to have established a historical biography of Marui. Keeping that distinction visible gives us room to examine how the poem works."},{"type":"heading","level":2,"text":"Homeland is spoken to someone"},{"type":"paragraph","text":"An address to a captor does different work from an address to kin. Even when both concern home, one may be shaped by refusal, another by an appeal or remembered relationship. Before deciding what a passage means, identify who is speaking and who is being asked to listen. A generalized summary of homesickness can erase those differences."},{"type":"paragraph","text":"The same care applies to the vocabulary of place. A reference to familiar surroundings may establish contrast with the speaker’s present situation, evoke a shared practice or make an emotional claim. Rather than assuming that every place-word is a literal map instruction, ask how it participates in the argument of the passage."},{"type":"paragraph","text":"One useful reading exercise is to follow a change of addressee through a short, identified section. Note what remains constant and what changes in the speaker’s tone. Then compare a translation, if available, with an explanation by a reader of Sindhi. The aim is not to impose a single emotional response but to notice where the language permits more than one emphasis."},{"type":"heading","level":2,"text":"A figure should not replace living people"},{"type":"paragraph","text":"Marui can be important to discussions of homeland without representing the feelings of every person associated with Sindh. A literary heroine’s words are not a survey of contemporary opinion. Nor does admiration for her require turning displacement, captivity or hardship into attractive cultural scenery."},{"type":"paragraph","text":"For a heritage archive, the distinction leads to better captions and connections. Identify the particular work and edition, explain the interpretive approach and label any place association accurately. If a contemporary artist uses Marui’s figure to make a new argument, credit that intervention rather than presenting it as the only inherited meaning."},{"type":"paragraph","text":"The reward is a more demanding understanding of belonging. Home emerges not as a decorative backdrop but as something articulated under pressure, through relationships and choices. Reading Marui closely lets that complexity remain audible instead of replacing it with a sentence that could be attached to any landscape."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Sindh","Languages"],"province":"Sindh","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Marui: reading homeland through a literary figure | Virsapur","description":"Marui’s remembered homeland is made through relationships and address. Reading her voice closely avoids turning a complex literary figure into a simple slogan.","primaryKeyword":"Marui Shah jo Risalo","socialTitle":"Marui: reading homeland through a literary figure","socialDescription":"Marui’s remembered homeland is made through relationships and address. Reading her voice closely avoids turning a complex literary figure into a simple slogan."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Dramatic Monologue in Shah Jo Risalo: A Generic Study of Sur Marui","url":"https://sujo.usindh.edu.pk/index.php/ARIEL/article/view/3800","publisher":"Muhammad Hassan Khoso and colleagues / University of Sindh","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Singleprimarytextualstudy-deriveddetails~140words; restoriginalclose-readingmethod not claimsabout unconsultedverses. No quotation or invented scenes. NativeSindhireviewrequired.","editorialReason":"Use identified surs and translations to analyse themes without reproducing long copyrighted passages.","sortOrder":262}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-shah-jo-risalo-why-the-edition-matters','shah-jo-risalo-why-the-edition-matters','review','{"id":"story-shah-jo-risalo-why-the-edition-matters","type":"story","slug":"shah-jo-risalo-why-the-edition-matters","title":"Shah jo Risalo: why the edition matters","summary":"An edition of Shah jo Risalo is an editorial arrangement of a transmitted corpus. Manuscript order, selection and performance context affect the reader’s encounter.","body":[{"type":"paragraph","text":"A book titled Shah jo Risalo may look like a single stable object, but the title alone does not tell a reader how its text was assembled. Which verses are included, how sections are ordered and what editorial explanations accompany them can shape the experience of reading. The edition is therefore part of the evidence, not a wrapper that can be discarded."},{"type":"paragraph","text":"Pei-ling Huang’s research on Shah Abdul Latif’s musical legacy describes a transmitted repertoire whose organization has changed. Her discussion identifies the Ganj compilation of 1793, several decades after Latif’s death, and notes differences in the ordering of poetic chapters across manuscript traditions. This is a concrete reason not to assume that a modern contents page reproduces one unaltered original sequence."},{"type":"paragraph","text":"The Sindhi Language Authority’s account of literary development identifies Ernst Trumpp’s 1866 printed edition as another important moment in that transmission. Printing made a particular arrangement reproducible; it did not remove the need to ask how that arrangement was selected. A later edition may engage with a different range of manuscripts or editorial judgements."},{"type":"heading","level":2,"text":"Order creates a reading experience"},{"type":"paragraph","text":"A section placed at the beginning can establish expectations for everything that follows. Moving it elsewhere may alter the journey a reader feels they are taking, even when individual verses remain recognizable. To compare editions responsibly, begin with their contents and editorial introductions before claiming that one has added or lost a passage."},{"type":"paragraph","text":"Verse numbering can be especially deceptive. A number is an address within an edition, not necessarily a universal identifier across every version. A citation should therefore include enough information for another reader to find the same text. When comparing translations, confirm that they refer to the same passage rather than trusting a matching number alone."},{"type":"paragraph","text":"Huang also examines Shah jo Rag as a system in which poetry and melodic practice are closely connected. That perspective complicates a strict separation between a literary book and music added afterwards. A page can preserve words without fully conveying the knowledge involved in their performance."},{"type":"heading","level":2,"text":"What an editor should make visible"},{"type":"paragraph","text":"A useful edition explains its sources, its treatment of variant readings and the limits of its claims. If a reading is uncertain, the uncertainty should remain distinguishable from a typographical error. If a translation smooths a difficult expression, a note can reveal what was gained in accessibility and what became less visible."},{"type":"paragraph","text":"For a new reader, this need not make the Risalo inaccessible. Begin with a clearly identified edition and a short section. Read the introduction, listen to a documented performance where appropriate and ask how the two encounters differ. The purpose is to deepen attention, not to demand mastery of every manuscript before enjoying a poem."},{"type":"paragraph","text":"A heritage archive serves that process best by naming editors, translators and recordings precisely. It should not combine passages from different versions into a seamless text without explanation. The Risalo’s transmission is part of its cultural life; recognizing editorial choices allows that history to enrich rather than undermine the reading."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Sindh","Languages"],"province":"Sindh","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Shah jo Risalo: why the edition matters | Virsapur","description":"An edition of Shah jo Risalo is an editorial arrangement of a transmitted corpus. Manuscript order, selection and performance context affect the reader’s encounter.","primaryKeyword":"Shah jo Risalo editions","socialTitle":"Shah jo Risalo: why the edition matters","socialDescription":"An edition of Shah jo Risalo is an editorial arrangement of a transmitted corpus. Manuscript order, selection and performance context affect the reader’s encounter."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Ways of Love: Self-making and Repertoire Formation through the Musical Legacy of Shah Abdul Latif in Sindh, Pakistan","url":"https://dash.harvard.edu/entities/publication/4d8548be-ed3c-489d-b757-54251e1b1891","publisher":"Pei-ling Huang / Harvard University","accessDate":"2026-10-22"},{"title":"Linguistic Development, Sindhi Language and Literature","url":"https://www.library.sindhila.org/book/46/read/1328","publisher":"Sindhi Language Authority","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Huangabstract+indexedPDFp130consulted; fullPDFfetch405. Ganj1793/orderclaims~125 plusabstract35 under200. Sindhila1866~25. No assertion all editionssame30surs. Sourceeditioncomparisonnotperformedclaimed.","editorialReason":"Explain compilation, ordering and translation choices before offering a definitive reading.","sortOrder":263}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-kafi-as-a-poetic-and-performed-form','the-kafi-as-a-poetic-and-performed-form','review','{"id":"story-the-kafi-as-a-poetic-and-performed-form","type":"story","slug":"the-kafi-as-a-poetic-and-performed-form","title":"The kafi as a poetic and performed form","summary":"A kafi has a life as poetry and as performance. Attention to voice, repetition and attribution helps listeners hear more than a generic label of Sufi music.","body":[{"type":"paragraph","text":"Calling a recording a kafi tells us something important, but it does not tell us everything we need to hear. The term connects a poetic form with traditions of performance. A particular recording also has a poet, a singer, a language, an arrangement and an audience. Those details prevent a rich musical encounter from collapsing into the broad label Sufi music."},{"type":"paragraph","text":"Sara Kazmi’s study of Punjabi literary tradition discusses the kafi through its dramatic voices, everyday imagery and connections with other texts, including the Heer story. Her reading emphasizes how apparently simple language can carry sharp social criticism. This is an interpretive account of a literary corpus, not a rule that every kafi makes the same argument."},{"type":"paragraph","text":"A different kind of source, Asia Society’s programme for its 2010 Sufi music festival, identifies Abida Parveen’s singing of kafis in Sindhi, Seraiki and Punjabi. The programme documents a performer’s repertoire across languages. It does not make those languages interchangeable, nor does a celebrated singer’s rendition define every local practice."},{"type":"heading","level":2,"text":"A poem becomes an event"},{"type":"paragraph","text":"On a page, a reader can pause and return at will. In performance, the singer shapes those returns. A phrase may be sustained, repeated or approached through a changing melodic emphasis. For a listener, a useful question is not merely what words are present, but which words become prominent and when."},{"type":"paragraph","text":"That question can be explored without pretending to understand a language one has not learned. Begin with a reliable text and translation for the specific piece. Mark where the performance returns to a phrase, then ask a knowledgeable listener what that return brings into focus. A repetition that seems musically decorative may affect how an address or contrast is understood."},{"type":"paragraph","text":"Attribution needs similar care. The name attached to an online clip may identify the singer while leaving the poet unstated. An album may combine selected verses or shorten a longer text. Before quoting the recording as the complete poem, establish what version has been performed and what the published notes actually claim."},{"type":"heading","level":2,"text":"Do not let labels replace listening"},{"type":"paragraph","text":"Kafi as a poetic and performed form should not be confused simply with the musical name of a raga. A label shared across different descriptive systems can conceal rather than resolve the question of what is being classified. An archive entry should say whether it is naming a text, a performance form or a melodic framework."},{"type":"paragraph","text":"Nor is devotional importance a reason to erase musicians’ work. Vocal preparation, accompaniment, arrangement and the practical conditions of a concert shape the encounter. Crediting those contributions does not diminish the poem; it explains how this particular audience receives it."},{"type":"paragraph","text":"For an attentive listener, the best introduction is a small, documented comparison: the same identified text in two performances, with their differences left audible. The kafi then emerges neither as a frozen literary specimen nor as an anonymous atmosphere, but as a form through which words continue to be voiced, interpreted and shared."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Languages"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"The kafi as a poetic and performed form | Virsapur","description":"A kafi has a life as poetry and as performance. Attention to voice, repetition and attribution helps listeners hear more than a generic label of Sufi music.","primaryKeyword":"kafi poetry form","socialTitle":"The kafi as a poetic and performed form","socialDescription":"A kafi has a life as poetry and as performance. Attention to voice, repetition and attribution helps listeners hear more than a generic label of Sufi music."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Writing Resistance in the Three Punjabs: Critical Engagements with Literary Tradition","url":"https://www.repository.cam.ac.uk/items/68ca6c38-c0c1-401b-a206-3599eeda62cd","publisher":"Sara Kazmi / University of Cambridge","accessDate":"2026-10-22"},{"title":"Voices of Sufism programme notes, 22 July 2010","url":"https://www.asiasociety.org/files/pdf/100722_voiceofsufi_prognotesweb.pdf","publisher":"Asia Society","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Kazmiabout75words plus258about90=>165cumulative. Programmeabout50. Do notconfusepoeticformwithragaKafi. No lyricsquoted/noanalysisofunheard recording. Performancequestions framedguidance.","editorialReason":"Distinguish metre, textual tradition and performance through sourced examples.","sortOrder":264}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-qissa-a-genre-not-just-a-folk-tale','qissa-a-genre-not-just-a-folk-tale','review','{"id":"story-qissa-a-genre-not-just-a-folk-tale","type":"story","slug":"qissa-a-genre-not-just-a-folk-tale","title":"Qissa: a genre, not just a folk tale","summary":"Qissa connects storytelling, print and performance, but its scope changes across literary settings. Punjabi and Urdu sources warn against a single narrow definition.","body":[{"type":"paragraph","text":"Translating qissa simply as folk tale can make the term sound smaller and more uniform than the works it describes. A qissa may be encountered in writing, through performance or in a remembered retelling. Its form and cultural setting deserve attention before it is assigned to a familiar English shelf."},{"type":"paragraph","text":"Farina Mir’s study of colonial Punjab examines qisse as a lively literature of epics and romances, connecting print, performance and ideas of belonging. Her research asks how Punjabi literary practice flourished despite the limited official patronage available to it under British rule. The important contrast is between institutional marginalization and cultural activity—not between supposedly oral people and literate elites."},{"type":"paragraph","text":"Musharraf Ali Farooqi’s introduction to Fabulous Machinery for the Curious, a collection of translated Urdu qissas makes a different caution. It notes that qissa in Urdu can cover both short and long narratives, in prose as well as verse. A definition drawn from one Punjabi corpus should therefore not be imposed automatically on every Urdu work bearing the term."},{"type":"heading","level":2,"text":"Genre is a way of asking questions"},{"type":"paragraph","text":"A useful genre label helps readers notice conventions. Does the story announce a narrator? How are dialogue and description handled? What kind of attention does it ask from a listener or reader? Those questions are more productive than assuming that every qissa has the same length, metre or relationship to historical events."},{"type":"paragraph","text":"Print adds another set of clues. A title page, an illustration, an editor’s introduction or a publisher’s series can frame the work for an audience. A performance may frame it through an opening address or the occasion on which it is heard. Both are part of the story’s circulation, even when neither appears in a short plot summary."},{"type":"paragraph","text":"A familiar romance also makes it tempting to treat different tellings as copies of one ideal original. Comparison can instead ask what each version does with inherited material. A changed emphasis on a character, an expanded exchange or a new setting for performance may be central to the work’s purpose rather than evidence of decay."},{"type":"heading","level":2,"text":"Keep the archive specific"},{"type":"paragraph","text":"For a catalogue, record the author or attributed author where known, the language, the edition and the medium being described. If a performer retells a printed work, identify that relationship when the evidence supports it. If the connection is uncertain, uncertainty is more useful than an invented chain of transmission."},{"type":"paragraph","text":"The term folklore should not function as permission to omit individual makers. A story’s wide circulation does not mean that every performance or translation is anonymous, unowned or available for unrestricted reuse. Nor does an association with a place verify every narrated event as local history."},{"type":"paragraph","text":"Understanding qissa in this way enlarges the encounter. We can appreciate the pleasure of a story while also examining its language, social world and routes between listeners and readers. The label becomes an opening into those relationships, not a small box that removes the work from literature as soon as it is called traditional."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Languages"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Qissa: a genre, not just a folk tale | Virsapur","description":"Qissa connects storytelling, print and performance, but its scope changes across literary settings. Punjabi and Urdu sources warn against a single narrow definition.","primaryKeyword":"qissa literary genre","socialTitle":"Qissa: a genre, not just a folk tale","socialDescription":"Qissa connects storytelling, print and performance, but its scope changes across literary settings. Punjabi and Urdu sources warn against a single narrow definition."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"The Social Space of Language: Vernacular Culture in British Colonial Punjab","url":"https://www.ucpress.edu/book/9780520262690/the-social-space-of-language","publisher":"Farina Mir / University of California Press","accessDate":"2026-10-22"},{"title":"Fabulous Machinery for the Curious: The Garden of Urdu Classical Literature, introduction","url":"https://content.ucpress.edu/title/9780520388239/fabulousintro.pdf","publisher":"Musharraf Ali Farooqi / University of California Press","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Exact book identity verified against UC Press ISBN9780520388239. Mir about100 derived words; Farooqi about60. Genre flexibility explained. No exclusive Punjabi/Urdu claim.","editorialReason":"Explain narrative form and performance with specific editions and regional differences.","sortOrder":265}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-proverbs-as-records-of-use-not-timeless-wisdom','proverbs-as-records-of-use-not-timeless-wisdom','review','{"id":"story-proverbs-as-records-of-use-not-timeless-wisdom","type":"story","slug":"proverbs-as-records-of-use-not-timeless-wisdom","title":"Proverbs as records of use, not timeless wisdom","summary":"A proverb records an expression in circulation, not an unquestionable truth. Dictionaries and critical studies help separate wording, use and social judgement.","body":[{"type":"paragraph","text":"A proverb can sound persuasive partly because it arrives already shaped for repetition. Its brevity suggests experience condensed into a sentence. That effect deserves attention, but it is not a guarantee of truth. A saying may comfort, tease, warn, justify authority or express a prejudice, depending on who uses it and what happens around it."},{"type":"paragraph","text":"Rauf Parekh’s study of Urdu proverb dictionaries traces a substantial history of collecting these expressions. He notes their value for examining social settings and changes in language. A dictionary entry establishes that a form has been recorded; it does not tell us that every speaker agrees with it or uses it in the same way."},{"type":"paragraph","text":"A critical study by Tufail Chandio approaches Sindhi proverbs through their potential to reinforce social attitudes. Its broad account should itself be read critically rather than treated as proof that sayings determine an entire society’s behaviour. The useful question it raises is narrower: what work can a familiar expression do in a particular exchange?"},{"type":"heading","level":2,"text":"Record the moment of use"},{"type":"paragraph","text":"Imagine two people using the same saying, one earnestly and one with deliberate irony. A transcript that preserves only the words may make their positions look identical. Tone, timing, the audience’s response and the relationship between speakers can distinguish endorsement from criticism."},{"type":"paragraph","text":"A careful field note would therefore identify the occasion, the speaker’s intended meaning where they explain it, and the response. It should also distinguish a proverb offered because a researcher requested examples from one used spontaneously in conversation. Both are valuable records, but they answer different questions about everyday use."},{"type":"paragraph","text":"Older dictionaries introduce another layer. The compiler may provide a literal meaning, a conventional explanation or an illustrative anecdote. Those editorial choices are not necessarily statements made by the people who use the proverb today. A dated entry can be compared with contemporary testimony without requiring either to cancel the other."},{"type":"heading","level":2,"text":"Heritage does not require endorsement"},{"type":"paragraph","text":"Some expressions carry assumptions about gender, status or social groups that deserve examination rather than celebration. Preserving a record of such language can support historical understanding, but presenting it as charming collective wisdom may reproduce the injury it contains. Context and purpose should determine whether quotation is necessary at all."},{"type":"paragraph","text":"A useful educational comparison might place two explanations of a saying together, showing how readers disagree about its force. That is different from collecting contradictory proverbs as evidence that a language is confused. People draw on expressions selectively, and contradiction can reveal the range of arguments available to them."},{"type":"paragraph","text":"For a heritage archive, the strongest unit is therefore not an isolated line on an attractive background. It is a documented expression with its source, date where known, interpretation and conditions of use. Such a record leaves room for change, disagreement and humour. Proverbs become evidence of people speaking to one another, rather than anonymous commands handed down unchanged from an undifferentiated past."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Languages"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Proverbs as records of use, not timeless wisdom | Virsapur","description":"A proverb records an expression in circulation, not an unquestionable truth. Dictionaries and critical studies help separate wording, use and social judgement.","primaryKeyword":"Pakistani proverbs oral culture","socialTitle":"Proverbs as records of use, not timeless wisdom","socialDescription":"A proverb records an expression in circulation, not an unquestionable truth. Dictionaries and critical studies help separate wording, use and social judgement."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Proverbs and dictionaries of proverbs in Urdu","url":"https://sujo.usindh.edu.pk/index.php/TAHQIQ/article/view/2698","publisher":"Rauf Parekh / Tahqiq, University of Sindh","accessDate":"2026-10-22"},{"title":"Social Dynamics of Sindhi Society: An analysis of Proverbs and their impact on Mindset","url":"https://sujo.usindh.edu.pk/index.php/KALICH/article/view/434","publisher":"Tufail Chandio / Kalich Research Journal","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Parekh~65Chandio~45facts; explicitlycritiquebroadcausalclaimsnotendorse negativegroupstereotypes. No inventedproverbs. Discussionofmethodoriginal.","editorialReason":"Show how context and speakers change meaning and avoid generalising stereotypes.","sortOrder":266}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-womens-voices-in-regional-oral-literature','womens-voices-in-regional-oral-literature','review','{"id":"story-womens-voices-in-regional-oral-literature","type":"story","slug":"womens-voices-in-regional-oral-literature","title":"Women’s voices in regional oral literature","summary":"Women’s oral literature becomes clearer when performers, fictional voices and collectors are distinguished. Research in Bhakkar shows why familiarity does not remove the need for negotiation.","body":[{"type":"paragraph","text":"The phrase women’s voices can refer to several different things: women performing, women composing, a female character speaking in a text, or a collector describing women’s experiences. These categories can overlap, but they are not interchangeable. A heritage archive becomes more revealing when it identifies which kind of voice a record actually preserves."},{"type":"paragraph","text":"Atifa Nasir’s account of collecting wedding songs among Rajput women in Bhakkar offers a concrete example. She reports gathering eighty-four songs, many from relatives, and discusses the negotiation required in family-based research. Familiarity did not eliminate the need to maintain trust or adapt the process. Her account is valuable precisely because it makes the research relationship visible."},{"type":"paragraph","text":"The collection’s scale does not make it a portrait of all women in Bhakkar, still less of Pakistan. It documents a particular project with particular relationships and access. That boundary should accompany any claim made from the material, rather than disappearing when a song is placed beneath a broad regional heading."},{"type":"heading","level":2,"text":"Who is speaking, and in what role?"},{"type":"paragraph","text":"A literary study of Sur Marui identifies a female speaker within Shah Abdul Latif Bhittai’s poetic work. That is a different kind of evidence from a recording of a woman performing at a wedding. A fictional voice may illuminate literary representation; it cannot automatically be treated as an unmediated statement by historical women."},{"type":"paragraph","text":"Likewise, the person singing need not be the person who composed the words. A performer may inherit, select or adapt material. Asking how she learned a song can reveal a chain of transmission without forcing her into the role of a last surviving custodian. A repertoire may also include recently learned pieces, personal preferences and material she chooses not to perform."},{"type":"paragraph","text":"The occasion matters. A song shared among familiar participants may depend on relationships that an outside audience does not understand. A joke can become misleading when detached from its target and response. A translation may convey the literal words while missing why the room laughs, falls silent or joins in."},{"type":"heading","level":2,"text":"Let participation include refusal"},{"type":"paragraph","text":"Documentation should allow a singer to decide whether a recording is made, how it is credited and who may hear it. Permission to record within a research conversation is not automatically permission for unrestricted online circulation. The wishes of other identifiable participants may also matter when a group performance is involved."},{"type":"paragraph","text":"These choices should not be portrayed as obstacles to saving culture. They are part of respecting the people whose activity gives the record value. An archive can preserve a description or a restricted-access recording where a public clip would be inappropriate."},{"type":"paragraph","text":"Attending to women’s oral literature therefore requires more than adding a few recordings to a male-dominated collection. It means examining how access, authorship and interpretation shape the collection itself. The result is a more exact account of creative work and social exchange—one in which women are not simply symbolic voices but people able to define the terms of their contribution."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Languages"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Women’s voices in regional oral literature | Virsapur","description":"Women’s oral literature becomes clearer when performers, fictional voices and collectors are distinguished. Research in Bhakkar shows why familiarity does not remove the need for negotiation.","primaryKeyword":"women oral literature Pakistan","socialTitle":"Women’s voices in regional oral literature","socialDescription":"Women’s oral literature becomes clearer when performers, fictional voices and collectors are distinguished. Research in Bhakkar shows why familiarity does not remove the need for negotiation."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"In Search of Folk Wedding Songs: A Woman Researcher’s Challenges in Family Folkloric Studies","url":"https://www.humapub.com/admin/alljournals/gsr/papers/vteHey5lGf.pdf","publisher":"Atifa Nasir / Global Sociological Review","accessDate":"2026-10-22"},{"title":"Dramatic Monologue in Shah Jo Risalo: A Generic Study of Sur Marui","url":"https://sujo.usindh.edu.pk/index.php/ARIEL/article/view/3800","publisher":"Muhammad Hassan Khoso and colleagues / University of Sindh","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Nasirprimaryfieldwork~120words; Maruipaper~35+261~130total165. Distinguishfemalecharacter/performer/author. Noexplicitlyprivate material reproduced/no inventedparticipantvoices.","editorialReason":"Commission documented voices and attribution rather than repeat anonymous gender stereotypes.","sortOrder":267}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-translation-and-the-problem-of-a-beautiful-mistranslation','translation-and-the-problem-of-a-beautiful-mistranslation','review','{"id":"story-translation-and-the-problem-of-a-beautiful-mistranslation","type":"story","slug":"translation-and-the-problem-of-a-beautiful-mistranslation","title":"Translation and the problem of a beautiful mistranslation","summary":"A beautiful translation can still mislead if its choices are hidden. Comparing specific versions helps separate poetic transformation from unsupported attribution.","body":[{"type":"paragraph","text":"A line in English may be memorable, moving and entirely convincing as a poem while remaining a poor guide to the text it claims to translate. The problem is not beauty itself. It is the moment when a translator’s choices become invisible and the resulting words are attributed directly to an author who never wrote them in that form."},{"type":"paragraph","text":"Translation involves decisions about meaning, sound, rhythm and the needs of a new audience. Those priorities can pull in different directions. A version made for singing may solve a musical problem differently from one prepared for a scholarly edition. Neither purpose removes the obligation to explain what kind of version is being offered."},{"type":"paragraph","text":"Nasir Mehmood and Hazrat Umar’s study compares three English translations of a selected stanza from Iqbal’s Shikwah. They find differences in procedure and form while arguing that a core of theme and tone remains broadly shared. The study’s limited selection is important: its conclusion is not a verdict on every line of the poem or on translation in general."},{"type":"heading","level":2,"text":"Compare choices, not just fluency"},{"type":"paragraph","text":"Begin with a passage whose source can be identified. Establish which edition a translator used and whether the published wording is a translation, an adaptation or a quotation through another writer. A polished sentence copied from an unattributed image has not passed that first test, however plausible it sounds."},{"type":"paragraph","text":"Then ask specific questions. Has a concrete image become an abstract statement? Has an ambiguous pronoun been assigned a definite identity? Has a question become an assertion? These are points to investigate with a knowledgeable reader of the source language, not invitations to declare a translation wrong merely because another version differs."},{"type":"paragraph","text":"Research on creative translation of Bulleh Shah’s poetry, published in Kalich Research Journal, also treats the style of the English text as an object of analysis. That focus is useful: the translated poem has its own verbal construction. Its effects should be examined rather than mistaken for direct, transparent access to the original."},{"type":"heading","level":2,"text":"Give interpretation a visible place"},{"type":"paragraph","text":"An explanatory note can be more honest than forcing every nuance into the main line. It may identify an allusion, describe an alternative reading or explain why a literal rendering would mislead. Such notes need not overwhelm a general reader; they can reveal one consequential choice at the point where it matters."},{"type":"paragraph","text":"A heritage website should credit translators separately from poets and retain the edition or recording behind a quotation. If the wording is a new paraphrase, label it as such. If no dependable source can be found, an appealing line should remain out of the poet’s mouth until the attribution is resolved."},{"type":"paragraph","text":"The aim is not to make translated literature timid or graceless. It is to let readers appreciate artistry without losing track of responsibility. A beautiful version becomes a stronger bridge when its construction is visible: we can admire what the translator has made and still ask how it relates to the work that prompted it."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Languages"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Translation and the problem of a beautiful mistranslation | Virsapur","description":"A beautiful translation can still mislead if its choices are hidden. Comparing specific versions helps separate poetic transformation from unsupported attribution.","primaryKeyword":"regional poetry translation Pakistan","socialTitle":"Translation and the problem of a beautiful mistranslation","socialDescription":"A beautiful translation can still mislead if its choices are hidden. Comparing specific versions helps separate poetic transformation from unsupported attribution."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Exploring the Invariant Core: An Analysis of Multiple Translations of a Selection from Iqbal’s Shikwah","url":"https://pu.edu.pk/images/journal/bazyaft/PDF/07_v37_July-Dec_2020.pdf","publisher":"Nasir Mehmood and Hazrat Umar / Bazyāft, University of the Punjab","accessDate":"2026-10-22"},{"title":"Foregrounding and Creative Translation: Stylistic Deviation in the English Translation of Bulleh Shah’s Poetry","url":"https://sujo.usindh.edu.pk/index.php/KALICH/article/download/3904/2889/7290","publisher":"Mehvish Riaz / Kalich Research Journal","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Firstpaper~100derivedwords,second~25(topicnotfindingsunread). No accuseindividualmistranslation; noquotelyrics. Review any future translatedexampleswithsource-languageexpert.","editorialReason":"Compare short licensed examples and require bilingual review of interpretation.","sortOrder":268}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-suri-jagek-observing-the-sky-through-local-terrain','suri-jagek-observing-the-sky-through-local-terrain','review','{"id":"story-suri-jagek-observing-the-sky-through-local-terrain","type":"story","slug":"suri-jagek-observing-the-sky-through-local-terrain","title":"Suri Jagek: observing the sky through local terrain","summary":"Suri Jagek connects celestial observation with the local horizon. Its safeguarding concerns the transmission of situated knowledge, not simply the preservation of a picturesque viewpoint.","body":[{"type":"paragraph","text":"A mountain horizon is not an empty background to the sky. Where the sun appears in relation to a ridge, and how shadows move across familiar ground, can become part of a learned way of recognizing time. Suri Jagek draws attention to this relationship between observation and place."},{"type":"paragraph","text":"UNESCO describes Suri Jagek as a Kalasha knowledge system involving the sun, moon, stars and shadows in relation to local topography. Its account connects the practice with agricultural and livestock decisions, the Kalasha calendar and the timing of social and religious occasions. It was inscribed in 2018 on the List of Intangible Cultural Heritage in Need of Urgent Safeguarding."},{"type":"paragraph","text":"That recognition concerns a living body of knowledge and its transmission. It should not be mistaken for an independent scientific verification of every prediction attributed to the practice. Nor does it convert a local observational system into a universal calendar that can be copied accurately from any hillside."},{"type":"heading","level":2,"text":"Observation needs a place and a teacher"},{"type":"paragraph","text":"The reference to topography is crucial. A distant ridge or a familiar shadow can only function as a marker when an observer knows what relationship to look for. A photograph of a horizon may preserve its appearance without conveying the sequence of observations through which it becomes meaningful."},{"type":"paragraph","text":"For a visitor, the interesting questions are therefore practical and situated. Who teaches a learner where to stand? How is an observation compared with earlier ones? Which terms are used to describe the relevant feature? These questions should be asked through a community-led account rather than answered by an outsider inventing an elegant system from a single image."},{"type":"paragraph","text":"UNESCO’s description identifies stories, songs and proverbs among the means through which knowledge is passed on. This means that separating astronomy from oral tradition too neatly can obscure how people actually learn. A remembered expression may help organize an observation without functioning like a modern technical table."},{"type":"heading","level":2,"text":"Safeguarding is more than demonstration"},{"type":"paragraph","text":"THAAP’s account of its work describes community-based inventorying in the Kalasha valleys and collaboration in preparing the nomination. This gives an institutional context for the record, while the continued decisions of practitioners remain essential. A nomination file is not a substitute for their account of current use."},{"type":"paragraph","text":"A public demonstration may create interest, but regular transmission needs opportunities for learners to observe over time. An archive can support that process by documenting explanations with permission and retaining the circumstances in which they were given. It should not publish sensitive or restricted knowledge simply because a heritage label makes the material attractive."},{"type":"paragraph","text":"The strongest encounter with Suri Jagek is not a claim that modern tools and inherited observation must compete for exclusive legitimacy. It is attention to the ways people relate knowledge to a particular landscape and pass it between generations. The horizon then becomes legible as part of a cultural practice, not merely as scenery behind a festival photograph."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Khyber Pakhtunkhwa","Languages"],"province":"Khyber Pakhtunkhwa","district":"Lower Chitral","relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Suri Jagek: observing the sky through local terrain | Virsapur","description":"Suri Jagek connects celestial observation with the local horizon. Its safeguarding concerns the transmission of situated knowledge, not simply the preservation of a picturesque viewpoint.","primaryKeyword":"Suri Jagek Kalasha knowledge","socialTitle":"Suri Jagek: observing the sky through local terrain","socialDescription":"Suri Jagek connects celestial observation with the local horizon. Its safeguarding concerns the transmission of situated knowledge, not simply the preservation of a picturesque viewpoint."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Suri Jagek, nomination 01381","url":"https://ich.unesco.org/en/USL/suri-jagek-observing-the-sun-traditional-meteorological-and-astronomical-practice-based-on-the-observation-of-the-sun-moon-and-stars-in-reference-to-the-local-topography-01381","publisher":"UNESCO Intangible Cultural Heritage","accessDate":"2026-10-22"},{"title":"THAAP review of accreditation","url":"https://ich.unesco.org/doc/src/60958-EN.pdf","publisher":"THAAP / UNESCO Intangible Cultural Heritage","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"UNESCOdescription~155words;THAAP~40. Noforecastaccuracyendorsementorweatheradvice. No preciseobservationpointsinvented; noallKalashastandardization.","editorialReason":"Explain the documented knowledge system and community safeguarding, not an exotic astronomy claim.","sortOrder":269}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-nowruz-as-a-shared-festival-with-local-differences','nowruz-as-a-shared-festival-with-local-differences','review','{"id":"story-nowruz-as-a-shared-festival-with-local-differences","type":"story","slug":"nowruz-as-a-shared-festival-with-local-differences","title":"Nowruz as a shared festival with local differences","summary":"Nowruz connects communities across a wide region without making their celebrations identical. International recognition is a starting point for asking about local practice.","body":[{"type":"paragraph","text":"A shared festival does not require a single script for celebration. Nowruz is observed across a wide region, and its many spellings are an early reminder that language and local practice matter. The name connects communities; it does not make every household’s food, ceremony or understanding of the day identical."},{"type":"paragraph","text":"The United Nations marks International Nowruz Day on 21 March and connects the festival with renewal around the spring equinox. Its account identifies practices associated with particular settings, including the Haft Sin arrangement especially associated with Iran. That detail should remain situated. An Iranian example cannot automatically serve as a description of every Nowruz observance in Pakistan."},{"type":"paragraph","text":"UNESCO’s current multinational inscription includes Pakistan alongside countries across Central, South and Southwest Asia and beyond. The 2024 record is part of an extended history of recognition, not evidence that all the participating states began celebrating together or that every citizen participates."},{"type":"heading","level":2,"text":"Move from a broad label to a local account"},{"type":"paragraph","text":"To understand a particular celebration, ask who is organizing it and what its participants call it. A family gathering, a community event and a diplomatic programme may all use the festival’s name while doing different social work. Their relationship can be explored without treating one as authentic and the others as mere copies."},{"type":"paragraph","text":"Pakistan’s periodic report to UNESCO mentions programmes held in cooperation with Iran, Afghanistan and Central Asian states. That is evidence of organized cultural exchange. It does not describe every local practice within Pakistan or establish the meaning of the festival for each participating person."},{"type":"paragraph","text":"An event record should therefore be specific about place, year and purpose. Photographs can show a table, a performance or a public gathering, but the accompanying description needs participants’ explanations. A visually striking object should not acquire a universal symbolic meaning simply because that interpretation appears on an unrelated festival webpage."},{"type":"heading","level":2,"text":"Renewal can take different forms"},{"type":"paragraph","text":"For a heritage reader, comparison becomes more useful when it follows one feature across well-documented settings. How is the beginning of the celebration marked? Which activities are public and which belong within a household? What changes when a community celebrates away from the place where family members grew up? These questions invite detail without requiring every difference to become a dispute over ownership."},{"type":"paragraph","text":"Care is also needed with the calendar. A general annual observance is not a confirmed invitation to a particular local event. Dates, access and programme details should come from its organizers. An archive may describe a past celebration accurately while offering no evidence that the same arrangement will recur."},{"type":"paragraph","text":"Nowruz’s shared character is most meaningful when local distinctions remain visible. A cultural platform can connect records through the common festival while allowing participants to explain their own practices. The result is a richer account of continuity and exchange: not one standardized scene repeated across a map, but related celebrations through which different communities mark renewal on their own terms."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Languages"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Nowruz as a shared festival with local differences | Virsapur","description":"Nowruz connects communities across a wide region without making their celebrations identical. International recognition is a starting point for asking about local practice.","primaryKeyword":"Nowruz Pakistan heritage","socialTitle":"Nowruz as a shared festival with local differences","socialDescription":"Nowruz connects communities across a wide region without making their celebrations identical. International recognition is a starting point for asking about local practice."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Nowruz, multinational inscription 02097","url":"https://ich.unesco.org/en/RL/nowruz-02097","publisher":"UNESCO Intangible Cultural Heritage","accessDate":"2026-10-22"},{"title":"International Nowruz Day","url":"https://www.un.org/en/observances/international-nowruz-day","publisher":"United Nations","accessDate":"2026-10-22"},{"title":"Pakistan periodic report on implementation of the 2003 Convention","url":"https://ich.unesco.org/doc/src/Signed%20periodic%20report%20-%20Periodic%20report-67253.pdf","publisher":"Government of Pakistan / UNESCO","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"UNESCOrecord~60UN~65PKreport~25. DirectUNESCOchallenge; indexedofficialentryread. No claim allPakistancelebrates/no unverifiedlocalmenuorritual. Current2024multinationalextensionnotnewPakistan-onlyinscription.","editorialReason":"Distinguish multinational recognition from specific community practices and dates.","sortOrder":270}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-boreendo-a-small-instrument-and-a-large-safeguarding-task','boreendo-a-small-instrument-and-a-large-safeguarding-task','review','{"id":"story-boreendo-a-small-instrument-and-a-large-safeguarding-task","type":"story","slug":"boreendo-a-small-instrument-and-a-large-safeguarding-task","title":"Boreendo: a small instrument and a large safeguarding task","summary":"Safeguarding the boreendo means sustaining makers, players and opportunities to learn—not merely preserving a small clay instrument in a display.","body":[{"type":"paragraph","text":"The boreendo is small enough for its visual simplicity to conceal the work around it. A hollow clay body with sound holes may appear to be a modest object. Yet making it sound, shaping its musical possibilities and teaching someone else to use it involve knowledge that cannot be preserved by keeping the object alone."},{"type":"paragraph","text":"UNESCO’s boreendo record describes clay that is dried and fired, with sound produced by blowing and altered through the handling of the openings and mouthpiece. It also notes recent modifications that extend musical possibilities. This is evidence of an instrument being worked with and developed, not a form that must remain physically unchanged to count as heritage."},{"type":"paragraph","text":"The element was inscribed in 2025 on the List of Intangible Cultural Heritage in Need of Urgent Safeguarding. The decision records community participation in the nomination and calls for continued involvement in safeguarding, with particular attention to education. Recognition is therefore connected to a task, not a declaration that the task has been completed."},{"type":"heading","level":2,"text":"Follow the work beyond the finished object"},{"type":"paragraph","text":"A display can identify the material and shape of a boreendo. To understand the craft, a record also needs the maker’s explanation of decisions: how the body is formed, how openings are handled and how a finished piece is judged. Such documentation should distinguish what a particular maker demonstrates from a universal rule for every instrument."},{"type":"paragraph","text":"Playing introduces another kind of expertise. An object that produces a sound does not automatically reveal the repertoire or the control needed for performance. A short demonstration may attract attention while leaving the process of learning almost entirely invisible. Repeated lessons, feedback and opportunities to play can matter more than a single public appearance."},{"type":"paragraph","text":"UNESCO’s account describes transmission within families and newer teaching settings, including schools and cultural events. These settings raise practical questions. Who has time to teach? Can learners obtain suitable instruments? Is there a place to practise? Which forms of support do the people involved consider useful? A safeguarding plan becomes meaningful through such details."},{"type":"heading","level":2,"text":"Avoid the romance of disappearance"},{"type":"paragraph","text":"Calling an instrument the last trace of an ancient civilization may produce a dramatic caption, but it requires evidence that a contemporary performance cannot supply. Likewise, a dated statement about the number of expert practitioners should not be repeated indefinitely as a current census. Attention is more useful when it remains accurate."},{"type":"paragraph","text":"The people who make, decorate, teach and perform should be credited for their particular contributions. Roles recorded in one nomination should not become permanent restrictions on who may participate. The point of safeguarding is to support a living practice, including the choices its participants make about its future."},{"type":"paragraph","text":"The boreendo’s scale makes this lesson especially clear. A museum case can protect a clay object from damage. Sustaining the heritage around it requires relationships, learning and material support outside the case. The instrument deserves to be seen, but also understood as something people continue to make meaningful through use."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Sindh","Languages"],"province":"Sindh","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Boreendo: a small instrument and a large safeguarding task | Virsapur","description":"Safeguarding the boreendo means sustaining makers, players and opportunities to learn—not merely preserving a small clay instrument in a display.","primaryKeyword":"Boreendo Bhorindo heritage","socialTitle":"Boreendo: a small instrument and a large safeguarding task","socialDescription":"Safeguarding the boreendo means sustaining makers, players and opportunities to learn—not merely preserving a small clay instrument in a display."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Boreendo, Bhorindo, nomination 02328","url":"https://ich.unesco.org/en/USL/boreendo-bhorindo-ancient-dying-folk-musical-instrument-its-melodies-knowledge-and-skills-02328","publisher":"UNESCO Intangible Cultural Heritage","accessDate":"2026-10-22"},{"title":"Decision 20.COM 7.A.3","url":"https://ich.unesco.org/en/decisions/20.COM/7.A.3","publisher":"UNESCO Intergovernmental Committee","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"CombinedUNESCOnomination/decisionderivedfactsunder190; sourceSpanishversionreadwhenEnglishblocked. No unverifiedIndusantiquityclaim or currentlastmusicianclaim. Communityrolesdatedto nominationnotmandatorygenderboundaries.","editorialReason":"Use the current official listing and practitioner documentation; do not infer antiquity from its name.","sortOrder":271}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-rubab-as-an-instrument-made-and-maintained','the-rubab-as-an-instrument-made-and-maintained','review','{"id":"story-the-rubab-as-an-instrument-made-and-maintained","type":"story","slug":"the-rubab-as-an-instrument-made-and-maintained","title":"The rubab as an instrument made and maintained","summary":"The rubab’s sound depends on craft, setup and continuing care. A museum object and a regional safeguarding record reveal different parts of that work.","body":[{"type":"paragraph","text":"A rubab is not only a recognizable outline or a sound associated with a region. It is also a made object whose parts must work together. Looking at its materials and the knowledge required to maintain it changes the emphasis from a picturesque performance to the labour that makes performance possible."},{"type":"paragraph","text":"The Metropolitan Museum of Art holds a rubab catalogued as Pakistani, with Karachi given as its geographical association and a date in the late nineteenth or early twentieth century. Its recorded materials include wood, skin, gut, bone and mother-of-pearl. This is the description of one object, not a universal specification for every rubab made or played in Pakistan."},{"type":"paragraph","text":"The combination is instructive. Decorative inlay and sounding components belong to the same instrument but do different work. A collection photograph, where available, may make ornament easy to notice while giving little information about the condition of the strings, the setup or how the instrument was played."},{"type":"heading","level":2,"text":"Craft is a relationship with sound"},{"type":"paragraph","text":"UNESCO’s 2024 inscription on crafting and playing rubab/rabab describes skills including woodwork, carving and inlay, transmitted through practical learning. The participating states are Afghanistan, Iran, Tajikistan and Uzbekistan. Pakistan is not listed in that nomination; the record is a regional comparison, not a UNESCO designation for Pakistani rubab practice."},{"type":"paragraph","text":"For an individual instrument, a useful account would follow the maker’s decisions rather than replacing them with a generic list of materials. How is the intended use discussed with a player? What adjustments are made before the instrument is considered ready? Which parts are expected to be replaced through use? These questions connect craft with the experience of musicians."},{"type":"paragraph","text":"Maintenance belongs in the story too. An instrument can remain visually impressive while no longer being suitable to play. Conversely, a working instrument may show replacement parts and ordinary wear. Neither appearance alone tells us whether it has been well cared for or what a conservator or maker would recommend."},{"type":"heading","level":2,"text":"Museum care and musical use are different decisions"},{"type":"paragraph","text":"A historic collection object should not be made playable merely to satisfy curiosity. Its materials, condition and significance require specialist assessment. A musician’s working rubab has different needs, and decisions about repair should involve someone with appropriate expertise. An introductory heritage article cannot replace that judgement."},{"type":"paragraph","text":"An archive can still make maintenance visible by recording repairs, modifications and the names of craftspeople when those facts are known. It should distinguish a maker’s original work from later intervention. If an instrument has travelled between musicians or regions, that history can be as revealing as an assigned geographical label."},{"type":"paragraph","text":"The most complete account therefore connects an object record with testimony from makers and players, while respecting the limits of each source. Hearing the rubab then means hearing more than a regional emblem. It means recognizing the accumulated decisions, skilled hands and continuing care through which a piece of crafted material becomes a musical companion."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Khyber Pakhtunkhwa","Languages"],"province":"Khyber Pakhtunkhwa","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"The rubab as an instrument made and maintained | Virsapur","description":"The rubab’s sound depends on craft, setup and continuing care. A museum object and a regional safeguarding record reveal different parts of that work.","primaryKeyword":"rubab making Pakistan","socialTitle":"The rubab as an instrument made and maintained","socialDescription":"The rubab’s sound depends on craft, setup and continuing care. A museum object and a regional safeguarding record reveal different parts of that work."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Rubab, object 11.94","url":"https://www.metmuseum.org/art/collection/search/503001","publisher":"Metropolitan Museum of Art","accessDate":"2026-10-22"},{"title":"Art of crafting and playing rubab/rabab, nomination 02143","url":"https://ich.unesco.org/en/RL/art-of-crafting-and-playing-rubab-rabab-02143","publisher":"UNESCO Intangible Cultural Heritage","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Metabout70UNESCOabout100. Explicit2024countriesexcludesPakistan. InheritedKPfacet broaderbodycomparativeKarachiobject; localKPmakerinterviewwouldstrengthenpublication. No unsafeDIYrepairadvice.","editorialReason":"Focus on craft knowledge, materials and musicians rather than a generic origin story.","sortOrder":272}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-alghoza-and-the-coordination-of-breath','the-alghoza-and-the-coordination-of-breath','review','{"id":"story-the-alghoza-and-the-coordination-of-breath","type":"story","slug":"the-alghoza-and-the-coordination-of-breath","title":"The alghoza and the coordination of breath","summary":"The alghoza’s paired pipes ask a player to coordinate airflow and melody. Its sound is best understood through specific musicians rather than a single regional stereotype.","body":[{"type":"paragraph","text":"Two pipes held together can create an impression of effortless continuity. The alghoza’s effect is more interesting when we notice the coordination behind it: air, finger movement and the relationship between sustained and changing sound. The instrument is not simply a pair of flutes added together; it is a way of making their interaction musically useful."},{"type":"paragraph","text":"The American Institute of Pakistan Studies describes paired flutes under several names, including alghoza, pava and beenu in Sindh, and a related doneli form in Balochistan. It notes that the pipes can differ in length. These descriptions establish a family of practices, not proof that every named form is identical in construction, tuning or use."},{"type":"paragraph","text":"A comparative example comes from Jodhpur RIFF’s programme for Taga Ram Bhil in Rajasthan. Its account emphasizes circular breathing, with one pipe sustaining a note while the other carries melodic phrases, and identifies the musician as an instrument maker as well as a performer. This is a documented account of a particular artist’s practice across the border, not a template imposed on all Pakistani players."},{"type":"heading","level":2,"text":"Continuity is something to listen for"},{"type":"paragraph","text":"The phrase circular breathing refers to a technique for sustaining airflow while replenishing breath. A listener does not need to master it to appreciate what it makes possible. Begin by noticing whether the sound continues across a long phrase and how movement in the melody relates to the steadier tone beside it."},{"type":"paragraph","text":"Then attend to changes rather than continuity alone. Where does a phrase gather energy? When does a repeated figure return? Does the balance between the two pipes remain constant? These questions direct attention to musical choices rather than treating sustained sound as a physical trick performed for an audience."},{"type":"paragraph","text":"A recording can help repeated listening, but its conditions matter. A close microphone may emphasize breath or small attacks differently from an outdoor performance. Editing can alter the impression of duration. Unless the record documents a continuous take, a listener should not use its length as a measure of how long a musician played without interruption."},{"type":"heading","level":2,"text":"Credit the person behind the sound"},{"type":"paragraph","text":"Names, repertoire and learning histories make a stronger introduction than a broad caption such as desert music. A performer may identify teachers, describe how an instrument was made or explain why a particular tune suits an occasion. Those details need to be recorded with permission rather than inferred from clothing or scenery."},{"type":"paragraph","text":"Comparing instruments also requires restraint. A similar appearance does not establish a shared tuning, and a shared name does not settle the question of origin. Where sources disagree, an archive can preserve the competing descriptions without inventing a single migration story to make the map look tidy."},{"type":"paragraph","text":"The alghoza rewards a kind of listening that follows several things at once. The paired sound is immediately attractive; its deeper interest lies in the control that keeps those parts in conversation. Recognizing that work gives the musician room to be an artist and craftsperson, not merely the bearer of an atmospheric regional sound."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Languages"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"The alghoza and the coordination of breath | Virsapur","description":"The alghoza’s paired pipes ask a player to coordinate airflow and melody. Its sound is best understood through specific musicians rather than a single regional stereotype.","primaryKeyword":"alghoza folk instrument","socialTitle":"The alghoza and the coordination of breath","socialDescription":"The alghoza’s paired pipes ask a player to coordinate airflow and melody. Its sound is best understood through specific musicians rather than a single regional stereotype."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Instruments of Pakistan: Pava / Beenu / Alghoza / Doneli","url":"https://www.pakistanstudies.net/node/62","publisher":"American Institute of Pakistan Studies","accessDate":"2026-10-22"},{"title":"Living Legends: Taga Ram Bhil, 24 October 2026 programme","url":"https://jodhpurriff.org/day-3-2026/","publisher":"Jodhpur RIFF","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"AIPS~60shared273~50=>110; RIFFabout75. ProgrammeupcomingataccessOct22notclaimedattended; Rajasthancomparativeclearlylabelled. No exactoriginclaims or medicalbreathtraining.","editorialReason":"Commission an instrument-specific account with practitioner verification of technique.","sortOrder":273}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-surando-and-the-relationship-between-instrument-and-voice','surando-and-the-relationship-between-instrument-and-voice','review','{"id":"story-surando-and-the-relationship-between-instrument-and-voice","type":"story","slug":"surando-and-the-relationship-between-instrument-and-voice","title":"Surando and the relationship between instrument and voice","summary":"A surando record should explain both the instrument and its musical role. Bowed strings, regional names and relationships with singing need precise attribution.","body":[{"type":"paragraph","text":"A bowed instrument can seem to follow a voice closely enough that a listener describes it as singing. That resemblance is a useful starting point, but it should not replace attention to what an instrument actually does. In a surando performance, the relationship between sustained tone, melodic movement and any accompanying voice needs to be heard in a specific musical setting."},{"type":"paragraph","text":"The Hartenberger collection records a surando associated with Kutch, describing a wooden body, a skin-covered part of the soundbox and several kinds of strings. Its account distinguishes bowed, drone and sympathetic strings on the catalogued object. This is a comparative instrument record from India; it does not establish the construction of every surando used in Sindh."},{"type":"paragraph","text":"The American Institute of Pakistan Studies connects the name surando with Sindh and related names, including saro and saroz, with other regions of Pakistan. Such naming is a reason to ask more precise questions, not to collapse every similarly named instrument into one unchanging design."},{"type":"heading","level":2,"text":"What does accompaniment mean?"},{"type":"paragraph","text":"In his historical account of Balochistan’s music, Mohammad-Taqi Masudiya describes sung narrative with a bowed sorud and a plucked lute providing a rhythmic drone. The account identifies distinct musical roles. It should not be generalized into a claim that a surando always accompanies singing in exactly that combination."},{"type":"paragraph","text":"For a listener, accompaniment can be investigated at the scale of a phrase. Does the instrument move with the singer, answer after a line or sustain a sound while the voice pauses? Does a repeated figure connect sections? A performance may make more than one of these relationships audible. Describing the actual exchange is more informative than saying only that the instrument imitates the human voice."},{"type":"paragraph","text":"If there is no singer, the question changes rather than disappears. An instrumental performance may draw on a familiar vocal melody, but that connection needs identification by a performer or reliable record. A listener’s impression of speech-like phrasing is not by itself evidence of a particular song."},{"type":"heading","level":2,"text":"Keep construction and performance connected"},{"type":"paragraph","text":"A museum catalogue can describe strings and materials while leaving the intended tuning uncertain. A recording can reveal musical behaviour while showing little of the instrument’s construction. Combining the two types of evidence requires an identified connection, not merely a similar-looking photograph chosen to illustrate the sound."},{"type":"paragraph","text":"The same applies to regional labels. A musician’s location, the place an instrument was made and the origin attributed to a repertoire may differ. Recording those fields separately helps preserve a history of exchange. It also prevents an instrument from being assigned to a single modern boundary simply because that makes an archive easier to browse."},{"type":"paragraph","text":"A strong introduction to the surando therefore makes room for both the object and the encounter. It credits maker and player where known, explains the source of its names and follows the instrument’s role in a documented performance. The apparent closeness to the voice then becomes a question worth listening to, rather than an attractive description repeated without evidence."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Sindh","Languages"],"province":"Sindh","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Surando and the relationship between instrument and voice | Virsapur","description":"A surando record should explain both the instrument and its musical role. Bowed strings, regional names and relationships with singing need precise attribution.","primaryKeyword":"surando Sindh music","socialTitle":"Surando and the relationship between instrument and voice","socialDescription":"A surando record should explain both the instrument and its musical role. Bowed strings, regional names and relationships with singing need precise attribution."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"India ‘Surando’ (Sarinda), AS-CHLT-09-14","url":"https://wmic.net/india-surando-sarinda/","publisher":"Hartenberger World Musical Instrument Collection","accessDate":"2026-10-22"},{"title":"Instruments of Pakistan: Surando / Saro / Saroz","url":"https://www.pakistanstudies.net/node/62","publisher":"American Institute of Pakistan Studies","accessDate":"2026-10-22"},{"title":"Baluchistan iv. Music of Baluchistan","url":"https://www.iranicaonline.org/articles/baluchistan-iv/","publisher":"Mohammad-Taqi Masudiya / Encyclopaedia Iranica","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"HWMCobject~75 AIPS~40 Iranica~60shared274~65=>125. KutchcollectionobjectnotPakistanfindclaim. Avoid treatingallregionalnamesidentical. Iranica1988historicalnotcurrentcensus.","editorialReason":"Investigate documented performance relationships without treating one style as universal.","sortOrder":274}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-dambura-traditions-and-the-risk-of-a-single-regional-label','dambura-traditions-and-the-risk-of-a-single-regional-label','review','{"id":"story-dambura-traditions-and-the-risk-of-a-single-regional-label","type":"story","slug":"dambura-traditions-and-the-risk-of-a-single-regional-label","title":"Dambura traditions and the risk of a single regional label","summary":"Dambura and related names occur across different musical settings. Comparing Baloch and Afghan records shows why a single regional label can mislead.","body":[{"type":"paragraph","text":"An instrument name can travel farther than a single design or playing tradition. Dambura is a good example of why a heritage archive should resist assigning one label to one province and treating the matter as settled. Similar names may connect instruments while still leaving important differences in construction, repertoire and musical role."},{"type":"paragraph","text":"In his account of Balochistan’s music, Mohammad-Taqi Masudiya describes a long-necked plucked dambura providing a rhythmic drone alongside bowed accompaniment in sung narrative. The emphasis is on what the instrument contributes to that performance. The article, first published in 1988, should be read as a historically situated account rather than a current inventory of every Baloch musician."},{"type":"paragraph","text":"Smithsonian Folkways’ notes for recordings from Afghanistan describe a dambura as a two-stringed, fretless plucked lute associated particularly with the north of that country. This provides a useful comparison, but it would be a mistake to transfer that exact description automatically to every instrument bearing a related name in Balochistan."},{"type":"heading","level":2,"text":"Compare the object before merging the labels"},{"type":"paragraph","text":"Begin with visible and documented features. What is the shape of the body? How many strings are present on this instrument? Are there frets? What does its maker or player call it? If those answers are missing, a broad name is not enough to fill them in confidently."},{"type":"paragraph","text":"Next ask about musical function. An instrument that supplies a recurring rhythmic support in one setting may carry a melody or accompany a solo singer in another. Similar construction does not require identical use. Conversely, instruments with different forms can occupy comparable roles within different ensembles."},{"type":"paragraph","text":"The recording notes matter because they connect description with identifiable tracks and musicians. An isolated image labelled folk lute can show an object without telling us what was played on it. A sound file labelled Balochistan may tell us even less about the instrument if it lacks performer and recording information."},{"type":"heading","level":2,"text":"A region contains more than one community"},{"type":"paragraph","text":"Balochistan is not a synonym for a single language or musical practice. An archive should distinguish a geographical association from the language of a song and from the identity a performer gives to their work. Those distinctions are especially important when a familiar instrument name encourages a quick, overly broad classification."},{"type":"paragraph","text":"Claims about ancestry also need evidence. A resemblance between names or shapes is not a complete history of transmission. It may suggest a question for research, but it does not establish when an instrument arrived, who carried it or whether one community borrowed directly from another."},{"type":"paragraph","text":"The practical goal is not to abandon regional browsing. It is to make the label an entry point into a more exact record. A dambura article becomes stronger when it identifies the particular instrument and source, explains its musical role and leaves unsupported connections open. Listeners can then explore relationships across the region without losing the distinct practices that give those relationships substance."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Balochistan","Languages"],"province":"Balochistan","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Dambura traditions and the risk of a single regional label | Virsapur","description":"Dambura and related names occur across different musical settings. Comparing Baloch and Afghan records shows why a single regional label can mislead.","primaryKeyword":"dambura music Pakistan","socialTitle":"Dambura traditions and the risk of a single regional label","socialDescription":"Dambura and related names occur across different musical settings. Comparing Baloch and Afghan records shows why a single regional label can mislead."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Baluchistan iv. Music of Baluchistan","url":"https://www.iranicaonline.org/articles/baluchistan-iv/","publisher":"Mohammad-Taqi Masudiya / Encyclopaedia Iranica","accessDate":"2026-10-22"},{"title":"Afghanistan: Music During the Civil War (1979–2001), recording notes","url":"https://folkways-media.si.edu/docs/folkways/artwork/UNES08320.pdf","publisher":"Smithsonian Folkways / UNESCO Collection","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Iranica~65shared273~60=>125. Smithsoniannotes~70 indexedreadPDFlargefetchfailed. No Balochi/Brahui/Hazarascope conflation or universalstringcount. Native musicianreviewneeded.","editorialReason":"Compare named communities and instrument variants with sensitive attribution.","sortOrder":275}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-dhol-in-work-celebration-and-performance','the-dhol-in-work-celebration-and-performance','review','{"id":"story-the-dhol-in-work-celebration-and-performance","type":"story","slug":"the-dhol-in-work-celebration-and-performance","title":"The dhol in work, celebration and performance","summary":"The dhol’s force comes from musical choices and social occasions as well as volume. A player’s account shows tradition as something learned and continually reworked.","body":[{"type":"paragraph","text":"A dhol can announce its presence before the player comes into view. Yet describing it only as loud misses the musical decisions that make its sound meaningful: placement of strokes, changes in emphasis and the relationship between a drummer and the people moving or listening nearby. The drum belongs to an occasion, not just to a volume level."},{"type":"paragraph","text":"In an essay for the Smithsonian, musician Sunny Jain describes the dhol as a double-headed wooden drum associated with farming, dance and special events in Punjabi life. He also discusses his interest in Pakistani Sufi dhol players after joining Junoon. This is a musician’s account of learning and influence, with named artists rather than an anonymous picture of regional tradition."},{"type":"paragraph","text":"Jain’s own practice brings those influences into conversation with jazz and other music. He describes using electronic effects as well as acoustic sound. His account is useful not because it defines every dhol tradition, but because it shows a player making deliberate choices about what to inherit and how to work with it."},{"type":"heading","level":2,"text":"Listen for relationship, not just repetition"},{"type":"paragraph","text":"A repeated pattern can establish a framework in which a small change becomes significant. Notice when a player intensifies a phrase, leaves space or signals a return. The response of dancers or fellow musicians can help explain the effect, but it should not be assumed from an isolated audio clip."},{"type":"paragraph","text":"Different settings also change what is audible. A drum in a procession competes with movement and surrounding sound. A microphone on a stage can present a different balance. A studio recording may isolate details that a nearby listener at an outdoor gathering would hear as part of a larger event."},{"type":"paragraph","text":"An archival Smithsonian record from the 1976 Festival of American Folklife identifies a Pakistani programme that includes a Punjab folk tune with shehnai and dhol. That kind of entry offers a useful anchor: an occasion, a performance grouping and a record that can be investigated. It does not describe every use of the drum in Punjab."},{"type":"heading","level":2,"text":"Keep the work of the drummer visible"},{"type":"paragraph","text":"A cultural caption should credit the player and identify the setting whenever those facts are known. If a piece is associated with work, celebration or devotion, explain the basis of that association. Avoid turning a broad historical connection into an unsupported claim that the specific recording accompanied agricultural labour or a ritual."},{"type":"paragraph","text":"The same care applies to change. A contemporary arrangement is not automatically a loss of tradition, just as an old-looking performance is not automatically faithful to a single original form. The musician’s account of learning, repertoire and intention can reveal a more complex relationship."},{"type":"paragraph","text":"The dhol’s cultural power is not diminished by such precision. Its sound can bring people together while remaining the result of individual skill and shared expectations. Listening to those decisions allows a heritage archive to present a working musical practice—energetic, adaptable and situated—rather than a generic beat attached to every image of Punjabi celebration."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Languages"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"The dhol in work, celebration and performance | Virsapur","description":"The dhol’s force comes from musical choices and social occasions as well as volume. A player’s account shows tradition as something learned and continually reworked.","primaryKeyword":"dhol cultural contexts Pakistan","socialTitle":"The dhol in work, celebration and performance","socialDescription":"The dhol’s force comes from musical choices and social occasions as well as volume. A player’s account shows tradition as something learned and continually reworked."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"The Tradition of Now","url":"https://folklife.si.edu/magazine/tradition-of-now-sunny-jain","publisher":"Sunny Jain / Smithsonian Center for Folklife and Cultural Heritage","accessDate":"2026-10-22"},{"title":"Pakistani Stage, 1976 Festival of American Folklife archival recording","url":"https://www.si.edu/object/archives/components/sova-cfch-sff-1976-ref15913","publisher":"Smithsonian Institution","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"SunnyJain~165words;archive~25. SourcehistoricalmusicnotadoptfactuallywrongJainism3000BCEorPartitiondatesfromessay. No inventedparticularrhythms/nohomogenization.","editorialReason":"Distinguish event contexts and changing practice rather than publish a fixed cultural stereotype.","sortOrder":276}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-polo-in-baltistan-rules-memory-and-public-space','polo-in-baltistan-rules-memory-and-public-space','review','{"id":"story-polo-in-baltistan-rules-memory-and-public-space","type":"story","slug":"polo-in-baltistan-rules-memory-and-public-space","title":"Polo in Baltistan: rules, memory and public space","summary":"Polo grounds in Baltistan are spaces of activity and public memory. Historic places and current tournaments need to be connected without inventing one universal set of rules.","body":[{"type":"paragraph","text":"A polo ground may look like an open space when no match is underway. Its heritage value becomes clearer when that apparent emptiness is understood as room for activity: players crossing the field, spectators finding a place and a town gathering around an event. In Baltistan, the ground deserves attention alongside the dramatic images of horses and riders."},{"type":"paragraph","text":"Virsapur’s linked record identifies Khaplu Polo Ground through the Department of Archaeology and Museums catalogue. It places a sporting space within the heritage inventory rather than limiting that inventory to enclosed buildings. The record does not, by itself, establish a complete history of matches or the rules used at every period."},{"type":"paragraph","text":"Contemporary evidence offers another view. Gilgit-Baltistan’s tourism and culture department reports the conclusion of the 2026 Ali Sher Khan Anchan tournament at Maqpoon Polo Ground in Skardu. That is a different ground and a specific event. Keeping the two places distinct lets a reader connect historic sporting landscapes with continuing organized competition without inventing a direct event history for Khaplu."},{"type":"heading","level":2,"text":"Freestyle does not mean without expectations"},{"type":"paragraph","text":"Official tourism material describes freestyle polo as part of Gilgit-Baltistan’s sporting culture. Promotional phrases about minimal rules should not be read as proof that players recognize no conventions or responsibilities. A visitor needs the explanation of the particular organizers, not a generalized claim that the game is simply unregulated."},{"type":"paragraph","text":"Ask how teams are constituted, how play begins and resumes, and how disputed moments are handled at the event being watched. These questions make a match easier to follow without importing the regulations of an unrelated polo competition. An archive should identify the date and source of any rules it records, because practice can vary."},{"type":"paragraph","text":"The field itself is also evidence. Its entrances, edges and relationship to surrounding buildings can shape how people arrive and watch. Historical photographs may help trace changes, but an attractive image is not enough to establish a ground’s original dimensions or continuous use."},{"type":"heading","level":2,"text":"Preserve the capacity to gather"},{"type":"paragraph","text":"For a sporting landscape, conservation is not only about retaining an outline on a map. Questions about access, maintenance and competing uses affect whether the place can continue to support activity. A ground kept visually open but unavailable to players has a different relationship to living practice from one used regularly."},{"type":"paragraph","text":"Spectators also have responsibilities. Follow the organizers’ boundaries and do not enter a playing area for a closer photograph. Familiarity among local participants should not be mistaken for permission to stand wherever a visitor chooses. Horses and fast-moving play require attention beyond the view through a phone."},{"type":"paragraph","text":"Polo in Baltistan is therefore best approached through connected but distinct records: a place, a match, the people who organize it and the memories participants attach to it. Together they reveal a cultural landscape in use. None needs to be inflated into a claim that all mountain polo follows one timeless and identical tradition."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Gilgit-Baltistan","Languages"],"province":"Gilgit-Baltistan","district":"Ghanche","relatedDistrictIds":["gilgit-baltistan-ghanche"],"provinceRegionIds":["gilgit-baltistan"],"relatedHeritageIds":["major-doam-7973"],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Polo in Baltistan: rules, memory and public space | Virsapur","description":"Polo grounds in Baltistan are spaces of activity and public memory. Historic places and current tournaments need to be connected without inventing one universal set of rules.","primaryKeyword":"Baltistan polo heritage","socialTitle":"Polo in Baltistan: rules, memory and public space","socialDescription":"Polo grounds in Baltistan are spaces of activity and public memory. Historic places and current tournaments need to be connected without inventing one universal set of rules."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Khaplu Polo Ground, catalogue 7973","url":"https://doam.gov.pk/public/sites/7973","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Ali Sher Khan Anchan Polo Tournament Season 6, 2026","url":"https://www.visitgilgitbaltistan.gov.pk/public/pages/news/98","publisher":"Tourism, Sports, Culture, Archaeology and Museums Department, Gilgit-Baltistan","accessDate":"2026-10-22"},{"title":"Jashn-e-Baharan Polo Tournament","url":"https://e-tourism.visitgilgitbaltistan.gov.pk/festivals-and-events/jashn-e-baharan-polo-tournament","publisher":"Tourism Department Gilgit-Baltistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"DOAMidentityfromexistingverifiedcanonicalrecordlive timeout; detailedfoundingclaimswithheld. NewsindexedofficialSept28read,about50words. GBtourismdateconflictMarch7vsAprilnotrepeated; no no-rules/no-protectivegearendorsement. RelationKhapluvalid; no eventKhapluclaim.","editorialReason":"Separate a historic ground’s record from present sporting practice requiring fresh verification.","sortOrder":277}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-tent-pegging-as-a-performed-skill','tent-pegging-as-a-performed-skill','review','{"id":"story-tent-pegging-as-a-performed-skill","type":"story","slug":"tent-pegging-as-a-performed-skill","title":"Tent pegging as a performed skill","summary":"Tent pegging combines riding, timing and precision within organized competition. Understanding the skill means looking beyond the dramatic instant when a target is lifted.","body":[{"type":"paragraph","text":"The most photographed moment in tent pegging is brief: a rider reaches down, the weapon meets a small target and the target is carried away. That instant can make the event look like a feat of daring alone. A closer account sees coordination between horse and rider, preparation of the course and a competition structure that makes precision assessable."},{"type":"paragraph","text":"The International Tent Pegging Federation describes the sport as a mounted discipline using a lance or sword to lift and carry a ground target. This provides a practical definition without requiring an uncertain origin story to explain every present-day event. A sporting action can have a historical association while its current organization follows a distinct set of rules."},{"type":"paragraph","text":"The Equestrian Federation of Pakistan identifies the organization and promotion of tent pegging among its purposes. That institutional setting matters: local enthusiasm and international competition are connected through clubs, organizers and officials, not merely through the resemblance of one rider’s action to another’s."},{"type":"heading","level":2,"text":"Watch the run as a whole"},{"type":"paragraph","text":"For a spectator, the approach to the target is part of the performance. Notice the line of travel, the moment of reaching and what happens after contact. A successful-looking strike in a photograph does not show the full run or establish its official result. The score depends on the rules and judging of the competition being observed."},{"type":"paragraph","text":"The ITPF rulebook effective in January 2019 illustrates the range of organization involved. It separates individual and team events, equipment, course arrangements, timekeeping, judging and veterinary matters. It is a dated document, not a claim about the exact regulations governing every event in 2026. Its value here is to show that the sport extends well beyond a single target."},{"type":"paragraph","text":"A visitor who wants to follow a current competition should consult its published conditions or organizers. Weapon type, event format and scoring should not be guessed from clothing or a general festival description. Where commentary is available, it can help connect what is visible with the decisions officials make."},{"type":"heading","level":2,"text":"Horse care belongs inside the heritage account"},{"type":"paragraph","text":"The animal is not scenery around a human achievement. Preparation, handling and welfare are fundamental to the event. The presence of veterinary and horse-abuse provisions in formal rules makes that responsibility explicit. A cultural account should not celebrate a dramatic image while ignoring how the horse is treated."},{"type":"paragraph","text":"Nor should an introductory article offer instructions for attempting the skill without appropriate training and supervision. For an ordinary visitor, the relevant guidance is to respect barriers, keep clear of the course and follow event staff. Photographs should be made from permitted positions, not by stepping into the line of a run."},{"type":"paragraph","text":"Tent pegging becomes more impressive, not less, when its organization is visible. We can appreciate the precision of the rider while also recognizing the work of trainers, handlers, officials and course teams. The result is a portrait of a demanding contemporary sport with cultural associations, rather than a timeless spectacle reduced to a single spectacular second."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Languages"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Tent pegging as a performed skill | Virsapur","description":"Tent pegging combines riding, timing and precision within organized competition. Understanding the skill means looking beyond the dramatic instant when a target is lifted.","primaryKeyword":"tent pegging Pakistan heritage","socialTitle":"Tent pegging as a performed skill","socialDescription":"Tent pegging combines riding, timing and precision within organized competition. Understanding the skill means looking beyond the dramatic instant when a target is lifted."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"What is Tent Pegging","url":"https://itpf.net/en/","publisher":"International Tent Pegging Federation","accessDate":"2026-10-22"},{"title":"Rules for Tent Pegging, effective 1 January 2019","url":"https://demo.efp.com.pk/wp-content/uploads/2023/07/rulesen.pdf","publisher":"International Tent Pegging Federation / Equestrian Federation of Pakistan","accessDate":"2026-10-22"},{"title":"About the federation","url":"https://efp.com.pk/about-us/","publisher":"Equestrian Federation of Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"ITPFhomepage~55;2019rules~70,EFP~35. Historicalrulebooknot2026requirements; no numericalruleassertion,noequitationDIY,no uncertainoriginstoryasfact.","editorialReason":"Examine training and event history without declaring an unsupported ancient lineage.","sortOrder":278}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-traditional-wrestling-and-the-institution-of-the-akhara','traditional-wrestling-and-the-institution-of-the-akhara','review','{"id":"story-traditional-wrestling-and-the-institution-of-the-akhara","type":"story","slug":"traditional-wrestling-and-the-institution-of-the-akhara","title":"Traditional wrestling and the institution of the akhara","summary":"An akhara is sustained by space, teaching and support as well as physical skill. Institutional evidence helps move its history beyond nostalgia about famous wrestlers.","body":[{"type":"paragraph","text":"A wrestling bout displays strength and technique, but the institution that prepares wrestlers is less visible in the moment of competition. The akhara is a place of practice, instruction and repeated work. Understanding it as an institution shifts attention from a few celebrated champions to the conditions that allow people to learn and continue."},{"type":"paragraph","text":"A University of the Punjab press release records the opening of an akhara at its New Campus hostel grounds in May 2013. The ceremony included wrestlers and sports officials, followed by competitions. This is a specific example of institutional support: a place was provided and an activity organized. It does not establish that all traditional wrestling was flourishing or declining at the same rate."},{"type":"paragraph","text":"A historical study by Tayyab Butt examines akharas in Lahore and Gujranwala through patronage and changing economic conditions. Its argument links difficulties in sustaining the institution with changes in support and everyday livelihoods. This is more useful as a question to investigate than a blanket statement that modernity inevitably destroys tradition."},{"type":"heading","level":2,"text":"Training needs a durable setting"},{"type":"paragraph","text":"A heritage record of an akhara should ask who teaches, who can attend and how the space is maintained. These practical details can reveal more about continuity than a claim that the practice is centuries old. A name may remain well known while the arrangements that once supported regular training have changed."},{"type":"paragraph","text":"The relationship between teacher and learner also deserves careful documentation. How is a beginner introduced? What expectations accompany participation? Which aspects of the teaching are described as inherited, and which have been adapted? Answers should come from people involved rather than from assumptions imported from a different region’s wrestling literature."},{"type":"paragraph","text":"A public competition and a training ground are not interchangeable records. The event may draw a large audience while the institution works quietly through ordinary days. Photographs of a successful bout cannot establish the frequency of practice, the availability of instruction or the costs borne by participants."},{"type":"heading","level":2,"text":"Look beyond a story of inevitable loss"},{"type":"paragraph","text":"Accounts of decline can draw attention to real pressures, but they can also make current practitioners disappear behind nostalgia. The university example shows why evidence needs dates and locations. An arena can open in one setting while another closes elsewhere. Both events may belong to the same wider history."},{"type":"paragraph","text":"Likewise, supporting an akhara does not mean endorsing every practice attributed to it. Questions of access, safety and the treatment of learners remain relevant. A cultural description should not turn a wrestler’s diet or training routine into general health advice, and it should not assume that customs are identical across institutions."},{"type":"paragraph","text":"The strongest account connects space, instruction, competition and support without collapsing them into one romantic image. It credits the people who sustain ordinary practice as well as those who win public recognition. Seen this way, the akhara is neither merely a patch of earth nor a relic awaiting rescue. It is an organization whose continuing life depends on concrete relationships and choices."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Punjab","Languages"],"province":"Punjab","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Traditional wrestling and the institution of the akhara | Virsapur","description":"An akhara is sustained by space, teaching and support as well as physical skill. Institutional evidence helps move its history beyond nostalgia about famous wrestlers.","primaryKeyword":"akhara wrestling Pakistan","socialTitle":"Traditional wrestling and the institution of the akhara","socialDescription":"An akhara is sustained by space, teaching and support as well as physical skill. Institutional evidence helps move its history beyond nostalgia about famous wrestlers."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Inauguration of an akhara at New Campus, 13 May 2013","url":"https://pu.edu.pk/home/section/allpress/2605","publisher":"University of the Punjab","accessDate":"2026-10-22"},{"title":"The Slow Fade: State Patronage, Modernity, and the Decline of the Akhara in Lahore and Gujranwala (1900–2000)","url":"https://ighsjournals.com/index.php/Historian/article/view/25","publisher":"Tayyab Butt / The Historian","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"PUprimaryevent~85words. Buttargument~65attributednotempiricalcurrentcensus; journalissuedate2023vswebpublication2025flagneedsbibliographicreview. Nohealth/dietadvice/no assumedreligionorthisexclusion.","editorialReason":"Focus on documented training spaces and community practice, not romanticised masculinity.","sortOrder":279}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-childrens-games-as-a-changing-archive','childrens-games-as-a-changing-archive','review','{"id":"story-childrens-games-as-a-changing-archive","type":"story","slug":"childrens-games-as-a-changing-archive","title":"Children’s games as a changing archive","summary":"Children’s games are transmitted by playing and negotiating, not just by preserving rules. Research in Chitral shows how documentation can support use while allowing adaptation.","body":[{"type":"paragraph","text":"A children’s game can survive without a printed rulebook because players teach it to one another. They demonstrate a movement, argue over a boundary, change a rule to fit the available space and invite someone new to join. That activity makes games a changing archive rather than a collection of instructions waiting to be copied exactly."},{"type":"paragraph","text":"Rubina Nawab’s research at Aga Khan University offers a grounded example from Chitral. The project interviewed ten community elders, involved early-childhood education specialists in reviewing the material and selected seven games for classroom use. The choices considered age, inclusion and practicality rather than assuming that every remembered game would suit every group of children."},{"type":"paragraph","text":"The study was carried out in a particular early-years class and used observation, reflection and discussion through successive cycles. Its findings concern that educational setting; they should not be inflated into a universal claim that any traditional game automatically produces the same developmental benefits. The value of the project includes the careful process of selection and adaptation."},{"type":"heading","level":2,"text":"A rule is only part of the record"},{"type":"paragraph","text":"To document a game, record what players call it, what materials they use and how play begins and ends. Then ask how they learned it and whether they know other versions. A disagreement about a rule may be valuable evidence of variation rather than a problem that the researcher must resolve into one official form."},{"type":"paragraph","text":"Space matters too. A game played in a courtyard may be adjusted for a school ground or a narrow lane. The number and age of players can change what is practical. Describing those conditions helps a later reader understand the version recorded, instead of assuming that a short list of actions will reproduce the whole experience."},{"type":"paragraph","text":"The 2025 publication Echoes of Play, by Nawab and Fozia Parveen, identifies traditional outdoor games of Chitral’s mountain communities as its subject. Its existence shows documentation being made into an educational resource. A book can support transmission, but it cannot replace the social work children do when they actually play."},{"type":"heading","level":2,"text":"Let children contribute to the archive"},{"type":"paragraph","text":"Adults’ memories are important, yet they should not be the only authority. Children may know variants, new names or solutions that make a game workable now. Recording those contributions avoids presenting change as evidence that they have failed to preserve the past correctly."},{"type":"paragraph","text":"Ethical documentation is especially important here. Permission for research or a school activity is not automatically permission to publish identifiable photographs or recordings of children. A description of rules can often be shared without exposing names, faces or precise everyday locations. Participation should also allow a child to decline being recorded."},{"type":"paragraph","text":"The aim is a resource that makes play possible, not a museum of compulsory authenticity. A well-documented game can carry a history while remaining open to thoughtful adaptation. Its heritage continues when children find it worth playing together—and when an archive respects their role as present-day makers of that experience, rather than treating them only as recipients of adult memory."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Languages"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Children’s games as a changing archive | Virsapur","description":"Children’s games are transmitted by playing and negotiating, not just by preserving rules. Research in Chitral shows how documentation can support use while allowing adaptation.","primaryKeyword":"traditional games Pakistan","socialTitle":"Children’s games as a changing archive","socialDescription":"Children’s games are transmitted by playing and negotiating, not just by preserving rules. Research in Chitral shows how documentation can support use while allowing adaptation."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Documenting traditional outdoor play practices in mountain communities and implementing action research for enhanced learning experiences in early childhood education","url":"https://ecommons.aku.edu/etd_pk_ied_med/707/","publisher":"Rubina Nawab / Aga Khan University","accessDate":"2026-10-22"},{"title":"Echoes of play: Traditional outdoor games of Chitral’s mountain communities","url":"https://ecommons.aku.edu/ied_p_pub/9/","publisher":"Rubina Nawab and Fozia Parveen / Aga Khan University","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Thesis~140derivedwordsbook~30; no causaluniversalhealthclaims. BookmetadatareadPDF403no inventedgamenames/rules. Consent/privacyrecommendationsoriginal.","editorialReason":"Use named documented examples and address urban change without inventing national uniformity.","sortOrder":280}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-board-games-and-the-difference-between-play-and-evidence','board-games-and-the-difference-between-play-and-evidence','review','{"id":"story-board-games-and-the-difference-between-play-and-evidence","type":"story","slug":"board-games-and-the-difference-between-play-and-evidence","title":"Board games and the difference between play and evidence","summary":"Archaeological game pieces can establish possibilities for play without recovering the rules or proving direct continuity with a living game.","body":[{"type":"paragraph","text":"A marked board and a handful of pieces make us want to begin. Games are familiar social experiences, so archaeological objects associated with play can seem easier to understand than an inscription or ceremonial vessel. The familiarity is deceptive. Equipment may survive while rules, turns, penalties and the names of games disappear."},{"type":"paragraph","text":"Harappa.com''s presentation of a possible gameboard from Moenjodaro identifies it cautiously and notes that an accompanying pointed object is probably not a gaming piece. A second display explicitly places archaeological pieces on a modern wooden board. That distinction is fundamental: the modern arrangement is a way to show the objects, not a game set recovered intact from one ancient room."},{"type":"heading","level":2,"text":"Pieces do not supply their own rules"},{"type":"paragraph","text":"A counter can move between spaces in many different games. A die can determine a move, a score or a selection. Even when a gaming interpretation is persuasive, it does not follow that the exact game has been reconstructed. Mayank Vahia''s response to a question about Indus mancala emphasises the sparseness of the evidence and the uncertainty about what was played."},{"type":"paragraph","text":"This leaves useful work to do. The material, dimensions, markings and find context of the pieces can be compared. Objects recovered together may pose different questions from a display assembled across excavations. A proposed board should be examined as an individual artefact, including its broken edges and the possibility that only part of its layout survives."},{"type":"paragraph","text":"Living games can enrich that investigation. A demonstration makes the relationship between board, counters and movement understandable. But the explanation must identify it as a comparison. A resemblance between an ancient piece and a modern counter is not a complete chain of evidence connecting their rules across millennia."},{"type":"heading","level":2,"text":"Play without a continuity claim"},{"type":"paragraph","text":"An educational activity can invite participants to invent several games using the same replica equipment. The point would be to show why surviving pieces alone may underdetermine the rules. It should not be advertised as playing the exact game of an Indus household. The uncertainty is the lesson, not a defect to hide from visitors."},{"type":"paragraph","text":"Likewise, it is unwise to assign every small object to children. Adults also play, and some objects classified as gaming pieces may have other functions. Age, occasion and social meaning require evidence beyond size. A cheerful reconstruction of children in an ancient courtyard should be labelled as an imaginative scene rather than an excavated fact."},{"type":"paragraph","text":"The history of play can remain vivid under these constraints. It invites attention to ordinary interaction, anticipation and competition while acknowledging that their precise forms are difficult to recover. A good account brings the ancient objects close enough to provoke curiosity, but does not make them identical to games we already know simply because that would allow the story to end neatly."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Material Culture","Languages"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Board games and the difference between play and evidence","description":"Archaeological game pieces can establish possibilities for play without recovering the rules or proving direct continuity with a living game.","primaryKeyword":"historic board games Pakistan","socialTitle":"Board games and the difference between play and evidence","socialDescription":"Archaeological game pieces can establish possibilities for play without recovering the rules or proving direct continuity with a living game."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Gameboard","url":"https://www.harappa.com/slide/gameboard","publisher":"Harappa.com / Jonathan Mark Kenoyer","accessDate":"2026-10-22"},{"title":"Game Board","url":"https://www.harappa.com/slide/game-board","publisher":"Harappa.com / John Marshall excavation record","accessDate":"2026-10-22"},{"title":"Did they play mancala in the ancient Indus Valley?","url":"https://www.harappa.com/answers/did-they-play-mancala-ancient-indus-valley-if-so-what-did-their-game-boards-look","publisher":"Harappa.com / Mayank Vahia","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Compare excavated objects and living games without asserting direct continuity.","sortOrder":281}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-ajrak-makers-and-the-language-of-apprenticeship','ajrak-makers-and-the-language-of-apprenticeship','review','{"id":"story-ajrak-makers-and-the-language-of-apprenticeship","type":"story","slug":"ajrak-makers-and-the-language-of-apprenticeship","title":"Ajrak makers and the language of apprenticeship","summary":"Ajrak teaching moves between workshops and classrooms. Its continuity depends on recognising makers as teachers, with knowledge that exceeds a printed pattern.","body":[{"type":"paragraph","text":"An ajrak can be photographed in a moment; learning how to make one is a different undertaking. The finished cloth reveals pattern and colour, but not every decision that produced them. For an archive concerned with living heritage, the relationship between maker and learner deserves attention alongside the textile itself. A pattern catalogue cannot stand in for a teacher."},{"type":"heading","level":2,"text":"The maker as educator"},{"type":"paragraph","text":"In a small qualitative study published in 2021, education researcher Aruj Khaliq interviewed people involved in teaching craft heritage in Pakistan. One participant, Sindh artisan Muhammad Ghulam Abbas, described invitations to teach ajrak in educational institutions. The account places a practising maker in the role of an educator, rather than treating craft expertise merely as material for someone else’s lesson."},{"type":"paragraph","text":"Khaliq’s discussion also considers learning through sustained guidance and the connection between craft and other subjects. It is a study of selected perspectives, not a national survey demonstrating how every ajrak workshop trains its apprentices. That distinction leaves room for different teaching arrangements and for artisans who do not work with formal institutions."},{"type":"paragraph","text":"A British Council programme guide offers another specific example: it identifies Ghulam Abbas Soomro as a master block printer from Bhit Shah and describes engagement with textile and fashion education. This is evidence of a named practitioner’s educational work. It should not be expanded into a claim that every student encounter provides a full apprenticeship."},{"type":"heading","level":2,"text":"Demonstration is only a beginning"},{"type":"paragraph","text":"Consider the difference between watching a printed impression and learning to judge it. In a hypothetical teaching exercise, a learner might compare two attempts, explain where the repeat fails, and try again with feedback. The educational value lies partly in being able to recognise and discuss a mistake. A successful souvenir print, by itself, tells us much less about what was learned."},{"type":"paragraph","text":"An archive interview could therefore ask who taught a maker, which tasks a beginner is allowed to attempt, and how competence is recognised. These are proposed questions, not answers supplied on behalf of practitioners. Local terms should be recorded with their speaker and context instead of being presented as a universal vocabulary for all Sindh workshops."},{"type":"heading","level":2,"text":"Recording without replacing"},{"type":"paragraph","text":"Noorjehan Bilgrami’s documented work includes the book Sindh jo Ajrak and the film Sun, Fire, River, Ajrak. Their existence shows that recording the craft has taken several forms. Neither a book citation nor a film title, however, authorises an archive to reproduce a maker’s designs or disclose workshop knowledge without agreement."},{"type":"paragraph","text":"Good documentation should distinguish the teacher, the workshop, the person recording the lesson and the person making the object. It should also ask what may be shared publicly. A maker can welcome visitors while declining to reveal a technique or have a learner photographed. Respecting those choices keeps apprenticeship a relationship between people, not simply an attractive story attached to cloth."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Sindh","Languages"],"province":"Sindh","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Ajrak makers and the language of apprenticeship","description":"Ajrak teaching moves between workshops and classrooms. Its continuity depends on recognising makers as teachers, with knowledge that exceeds a printed pattern.","primaryKeyword":"ajrak apprenticeship","socialTitle":"Ajrak makers and the language of apprenticeship","socialDescription":"Ajrak teaching moves between workshops and classrooms. Its continuity depends on recognising makers as teachers, with knowledge that exceeds a printed pattern."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Approaches to Teaching Craft Heritage: Educator Perspectives from Pakistan","url":"https://globalinch.org/article/approaches-to-teaching-craft-heritage/","publisher":"Aruj Khaliq / Global InCH","accessDate":"2026-10-22"},{"title":"Maker programme guide","url":"https://www.britishcouncil.pk/sites/default/files/mtn_prog_guide_-_digital_full_guidepdf.pdf","publisher":"British Council Pakistan","accessDate":"2026-10-22"},{"title":"Noorjehan Bilgrami: contributor profile","url":"https://www.sahapedia.org/saha-user/noorjehan-bilgrami","publisher":"Sahapedia","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. Khaliq article read via publicly indexed journal archive, including Muhammad Ghulam Abbas educator example; do not conflate him with similarly named Hala ceramicist. British Council guide biography identifies Ghulam Abbas Soomro, Bhit Shah. No claim of first/only artisan, current course availability or ancient unbroken lineage. Bilgrami publication/film metadata only, not claim of watching film. Approximate source-derived allocations: Khaliq 130 words, Council 65, profile 30 (prior profile use approximately 50). Remaining text is original educational analysis, not reported observation.","editorialReason":"Focus on knowledge transmission, reserving dye chemistry and object analysis for a separate article.","sortOrder":282}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-chiniot-woodcarving-learning-by-making','chiniot-woodcarving-learning-by-making','review','{"id":"story-chiniot-woodcarving-learning-by-making","type":"story","slug":"chiniot-woodcarving-learning-by-making","title":"Chiniot woodcarving: learning by making","summary":"Chiniot’s woodworking knowledge is learned within a specialised production economy. Apprenticeship connects skill, responsibility and livelihoods beyond the finished furniture.","body":[{"type":"paragraph","text":"A carved panel can make Chiniot woodworking look like the accomplishment of one pair of hands. The learning behind it is less solitary. Skill is developed through correction, repetition and relationships with people who understand different parts of production. Looking at apprenticeship changes the question from how elaborate a finished object appears to how someone becomes able to make it."},{"type":"heading","level":2,"text":"A workshop economy, not one task"},{"type":"paragraph","text":"Martin Enzner’s study, published in 2013 after fieldwork in 2012, distinguishes fitters, jigsawers, turners, carvers and polishers within Chiniot’s furniture economy. Its interviewed workers generally remained specialists. A person skilled at carving was therefore not automatically responsible for every operation on a finished piece."},{"type":"paragraph","text":"Among the fully trained carpenters interviewed, learning with an ustad was the reported route into the occupation; the respondents had not received formal vocational training. Training periods differed. Apprentices did not necessarily belong to the same social group as their teachers. These findings describe that study’s participants, not every present-day workshop."},{"type":"paragraph","text":"This division of work matters when attributing an object. A shop name may identify its seller without identifying its carver. Likewise, the person who assembled furniture need not have designed or polished its ornament. An archive should leave room for several credits rather than choosing a single convenient author."},{"type":"heading","level":2,"text":"Learning also creates obligations"},{"type":"paragraph","text":"Enzner records the close involvement of teachers in trainees’ working lives, and the sale of work made during apprenticeship. The study also describes movement to other cities through skills and contacts acquired in Chiniot. Teaching was connected to earning, not isolated from it."},{"type":"paragraph","text":"That relationship should not be romanticised. Learning opportunities and unequal bargaining power can exist together. An account of apprenticeship needs to ask about hours, payment, education and the ability to leave, particularly when young people are involved. Admiration for intricate carving is not a substitute for those questions, and historical research does not establish current conditions."},{"type":"paragraph","text":"Imagine an interview organised around a practice piece rather than a showroom display. The maker could explain which cuts were difficult, what an instructor corrected and when the piece was considered acceptable. This is a proposed research method, not a scene observed in a named workshop. It would allow the learner’s judgement to enter the record instead of documenting only the master’s reputation."},{"type":"heading","level":2,"text":"From famous buildings to named makers"},{"type":"paragraph","text":"The official record for Gulzar Mahal associates its woodwork with Rahim Bakhsh and Elahi Bakhsh. Naming craftsmen changes the familiar palace narrative: patronage is important, but it does not exhaust authorship. Such names should be preserved without assuming that a present workshop descends directly from them."},{"type":"paragraph","text":"Chiniot’s craft history becomes richer when a visitor can move between a remarkable architectural interior and an account of how working knowledge is acquired. The connection is not that every chair repeats a palace. It is that both invite careful attention to decisions, specialisms and people whose labour may otherwise disappear behind the finished surface."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Punjab","Languages"],"province":"Punjab","district":"Chiniot","relatedDistrictIds":["punjab-chiniot"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-10101"],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Chiniot woodcarving: learning by making","description":"Chiniot’s woodworking knowledge is learned within a specialised production economy. Apprenticeship connects skill, responsibility and livelihoods beyond the finished furniture.","primaryKeyword":"Chiniot woodcarving tradition","socialTitle":"Chiniot woodcarving: learning by making","socialDescription":"Chiniot’s woodworking knowledge is learned within a specialised production economy. Apprenticeship connects skill, responsibility and livelihoods beyond the finished furniture."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Carpenters of Chiniot, Pakistan: The Social Economy of Woodcraft and Furniture Production","url":"https://www.geo.fu-berlin.de/geog/fachrichtungen/anthrogeog/zelf/_media_/download/Berlin_Geographical_Papers/BGP41_Carpenters-of-Chiniot.pdf","publisher":"Martin Enzner / Freie Universität Berlin","accessDate":"2026-10-22","section":"2013; sections 6.3–6.5"},{"title":"Gulzar Mahal, Chiniot","url":"https://doam.gov.pk/public/sites/10101","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. Enzner 2013 study based on 2012 fieldwork; relevant training and production passages close-read. Approximately 175 source-derived words, remaining original analysis. Do not universalise sample or reproduce dated wages as current. DOAM maker names only, approximately 25 words; combined with earlier331 remains within 200. Reject study romanticisation of very young labour; no legal claim.","editorialReason":"Document skill transmission and workshop voices rather than only finished luxury interiors.","sortOrder":283}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-multani-kashikari-as-living-knowledge','multani-kashikari-as-living-knowledge','review','{"id":"story-multani-kashikari-as-living-knowledge","type":"story","slug":"multani-kashikari-as-living-knowledge","title":"Multani kashikari as living knowledge","summary":"Multani kashikari survives through working knowledge, training and access to production resources—not through admiration for blue ornament alone.","body":[{"type":"paragraph","text":"The blue surface of a Multani ceramic object is easy to recognise before its maker is known. That visual familiarity can conceal a harder question: who is able to learn the work, practise it and sustain a livelihood from it? Kashikari is living knowledge because people continue making decisions with materials. A photograph of an old tiled building cannot answer how that knowledge circulates today."},{"type":"heading","level":2,"text":"Knowledge and access"},{"type":"paragraph","text":"Ayesha Aslam’s PIDE case study of Multan ceramics distinguishes workers’ vocational skills from owners’ access to physical capital. Its interviews describe learning within production settings and unequal opportunities to establish an independent business. Possessing a skill and possessing the resources to use it commercially are different conditions."},{"type":"paragraph","text":"The study also records respondents’ accounts of knowledge being retained within families, including reluctance to share particular stages of production. Those testimonies reveal tensions around teaching and competition. They do not establish that every Multani family behaves alike, or that inherited knowledge necessarily prevents new entrants."},{"type":"paragraph","text":"For an archive, the useful lesson is to ask more precise questions. Who taught a ceramicist to prepare a body, mix a material or judge a result? Which parts of the process are shared, and with whom? A general statement that the craft passes from father to son would erase the different answers that actual makers may give."},{"type":"heading","level":2,"text":"More than one setting for learning"},{"type":"paragraph","text":"The Skilling Pakistan directory lists a Government Institute Blue Pottery Development in Mumtazabad, Multan. That institutional entry establishes a named training setting, not a promise about current admissions, staffing or the availability of a particular course. Those details require a separate current enquiry."},{"type":"paragraph","text":"Another form of evidence comes from practitioner presentation. Ustad Wajid Art’s workshop description outlines teaching that connects clay preparation, pattern, pigment, glaze and kiln work. It is the workshop’s own account of its offer, not an independently assessed qualification. It nevertheless shows how a maker presents ceramic knowledge as an interconnected process rather than simply a decorative motif."},{"type":"paragraph","text":"These different settings need not be treated as rivals. A classroom can introduce vocabulary and observation; a production workshop can expose a learner to repeated decisions and consequences. Whether either arrangement is effective must be assessed with the people who teach and learn there, not inferred from the word traditional or modern."},{"type":"heading","level":2,"text":"Document the judgement, not only the result"},{"type":"paragraph","text":"A useful future interview might compare a successful object with a rejected one, if its maker agrees. Why was one retained and the other set aside? Which decision would the maker change? Such questions recognise practical judgement without publishing a technical recipe or appropriating protected workshop knowledge."},{"type":"paragraph","text":"The purpose is not to turn every ceramicist into an anonymous custodian of the past. Makers may teach, experiment, restrict access, change products or leave the occupation. A responsible account gives those choices space. Multani kashikari deserves appreciation as work carried out by living people, with expertise and constraints that cannot be read from blue glaze alone."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Punjab","Languages"],"province":"Punjab","district":"Multan","relatedDistrictIds":["punjab-multan"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6431","major-doam-6428"],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Multani kashikari as living knowledge","description":"Multani kashikari survives through working knowledge, training and access to production resources—not through admiration for blue ornament alone.","primaryKeyword":"Multan kashikari tradition","socialTitle":"Multani kashikari as living knowledge","socialDescription":"Multani kashikari survives through working knowledge, training and access to production resources—not through admiration for blue ornament alone."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Factors Affecting Ceramics Industry: A Case Study of Multan","url":"https://file-thesis.pide.org.pk/pdf/mphil-development-studies-2017-ayesha-aslam--factors-affecting-ceramics-industry-a-case-study-of-multan.pdf","publisher":"Ayesha Aslam / Pakistan Institute of Development Economics","accessDate":"2026-10-22","section":"Sections 5.6–5.8"},{"title":"Institutes directory: Government Institute Blue Pottery Development, Multan","url":"https://skillingpakistan.gov.pk/institutes?page=367","publisher":"Skilling Pakistan","accessDate":"2026-10-22"},{"title":"Workshops","url":"https://www.ustadwajidart.com/workshops","publisher":"Ustad Wajid Art","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. PIDE selected findings close-read, not all thesis; filename registration2017 is not assumed publication year. Avoid unreliable respondent genealogy back to Muhammad bin Qasim and unverified institutional allegations. Wajid self-published workshop curriculum indexed; full reader cache miss, verify before publication. Practitioner page is evidence of self-description, not independent genealogy/quality certification. PIDE derived allocation approximately170, directory35, workshop55.","editorialReason":"Separate current craft practice from historic tile descriptions through practitioner research.","sortOrder":284}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-truck-art-workshops-and-changing-commissions','truck-art-workshops-and-changing-commissions','review','{"id":"story-truck-art-workshops-and-changing-commissions","type":"story","slug":"truck-art-workshops-and-changing-commissions","title":"Truck-art workshops and changing commissions","summary":"Truck art changes through the relationship between skilled workshops and their commissioners, from transport owners to education campaigns and cultural exchanges.","body":[{"type":"paragraph","text":"A decorated truck is both a working vehicle and a commissioned surface. Its appearance is negotiated among people: the owner who pays, the workers who build and finish it, and the artist whose choices give it character. Thinking about these relationships explains change more usefully than searching for one permanent meaning behind every bird, flower or portrait."},{"type":"heading","level":2,"text":"The workshop behind the image"},{"type":"paragraph","text":"Associated Press reporting in May 2025 follows Rawalpindi painter Muhammad Ashfaq and describes a collaborative trade involving painters, welders, electricians and metalworkers. Clients’ preferences and budgets influence the result. This particular account reminds us that the finished vehicle combines several kinds of labour; it is not simply a large painting made independently of its structure."},{"type":"paragraph","text":"An archive caption should therefore distinguish what it knows. Naming the painter does not automatically credit the people responsible for metalwork, lettering or fittings. Naming the owner is not the same as naming the maker. Where those roles cannot be recovered, an explicit gap is more honest than a single sweeping attribution."},{"type":"heading","level":2,"text":"When the commissioner changes"},{"type":"paragraph","text":"UNESCO’s 2019 account of its girls’ education programme describes trucks carrying educational messages through Kohistan. The campaign used a familiar public visual form for a specified advocacy purpose. Its meaning came partly from the commission and the words selected for it, rather than from a timeless code assumed to govern all truck decoration."},{"type":"paragraph","text":"This example also calls for care with claims about impact. A programme report can establish what was commissioned and why. Demonstrating a change in school participation would require a different kind of evidence. An archive can explain the campaign without turning its aspirations into measured results."},{"type":"paragraph","text":"In 2023, Associated Press of Pakistan reported a truck-art exhibition and student engagement in Langfang, involving Pakistan’s embassy and Phool Patti. Here the work entered a cultural-exchange setting rather than a transport yard. The change of setting matters: a classroom demonstration has different audiences, constraints and purposes from decorating a vehicle that will carry freight."},{"type":"heading","level":2,"text":"Adaptation is part of authorship"},{"type":"paragraph","text":"The Karachi Art Directory profile of Haider Ali describes work extending beyond trucks to other surfaces. Such a practice should not be reduced to the anonymous export of a national pattern. It belongs to an artist with a career and decisions about where and how to work."},{"type":"paragraph","text":"These examples suggest useful questions for future workshop interviews. Who proposed a design? What changed during discussion? Which decisions belonged to the commissioner and which to the maker? A motif may hold a personal, devotional, humorous or commercial meaning in one commission without carrying the same significance elsewhere."},{"type":"paragraph","text":"Truck art’s continuing relevance is not measured by how little it changes. Its makers respond to new patrons and settings while negotiating material and visual demands. Recording those negotiations gives a fuller account than treating every brightly painted surface as an interchangeable emblem of Pakistan."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Languages"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Truck-art workshops and changing commissions","description":"Truck art changes through the relationship between skilled workshops and their commissioners, from transport owners to education campaigns and cultural exchanges.","primaryKeyword":"Pakistan truck art workshops","socialTitle":"Truck-art workshops and changing commissions","socialDescription":"Truck art changes through the relationship between skilled workshops and their commissioners, from transport owners to education campaigns and cultural exchanges."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Pakistan truck art photo essay","url":"https://apnews.com/article/0f79bf77f9cba321d5ec210dda23ff2b","publisher":"Associated Press","accessDate":"2026-10-22","section":"1 May 2025"},{"title":"Truck art: Advocating for girls’ education in Pakistan through local art","url":"https://www.unesco.org/en/articles/truck-art-advocating-girls-education-pakistan-through-local-art","publisher":"UNESCO","accessDate":"2026-10-22","section":"28 March 2019"},{"title":"Pakistani truck art exhibition attracts Chinese students","url":"https://www.app.com.pk/global/pakistani-truck-art-exhibition-attracts-chinese-students/","publisher":"Associated Press of Pakistan","accessDate":"2026-10-22","section":"2023"},{"title":"Haider Ali","url":"https://karachiartdirectory.com/art-professionals/haider-ali/","publisher":"Karachi Art Directory","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. AP original reportage has 100-word budget; article derives approximately65 words from it. UNESCO approximately90, APP55, artist directory40. No quotation or copied captions. Commissioned campaign impact claims not adopted as demonstrated outcome. Do not conflate Phool Patti organisers with Haider Ali; no universal symbol dictionary or current workshop booking promise.","editorialReason":"Investigate labour, patronage and adaptation without making every motif a fixed symbol.","sortOrder":285}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-embroidery-learned-at-home-and-sold-in-markets','embroidery-learned-at-home-and-sold-in-markets','review','{"id":"story-embroidery-learned-at-home-and-sold-in-markets","type":"story","slug":"embroidery-learned-at-home-and-sold-in-markets","title":"Embroidery learned at home and sold in markets","summary":"Embroidery can connect household learning to market income, but its value cannot be understood without the maker’s time, choices and position in the supply chain.","body":[{"type":"paragraph","text":"A piece of embroidery can move from a household to a market without carrying the name of the person who stitched it. Along that journey, an account of family skill can become a sales description while hours of work disappear from view. Understanding the craft requires attention to both learning and exchange: how someone acquires competence, and how that competence becomes income."},{"type":"heading","level":2,"text":"Learning does not happen in one way"},{"type":"paragraph","text":"World Bank research on low-income urban women’s work includes accounts of skills learned within families and the practical importance of work arrangements compatible with domestic responsibilities. Embroidery appears within a wider discussion of livelihoods, not as a single experience shared by every woman. Household learning can be valuable without making the household the only appropriate place for work."},{"type":"paragraph","text":"A 2017 Balochistan Review study of home-based embroidery workers similarly connects craft income to household circumstances and choices. Its participants should not become a composite imaginary artisan whose story supposedly represents an entire province. Their evidence is strongest when its setting and limits remain visible."},{"type":"paragraph","text":"For future documentation, asking who taught a stitch is only a beginning. A maker may also wish to discuss how she developed speed, learned to interpret an order, selected materials or decided which work to accept. These questions recognise judgement and experience, rather than reducing expertise to an inherited female instinct."},{"type":"heading","level":2,"text":"The route to the buyer"},{"type":"paragraph","text":"The ILO’s Pakistan’s Hidden Workers draws on research conducted in two Karachi locations in 2016. It examines home-based work within wider supply chains. Its local findings cannot serve as current national wage statistics, but they challenge the assumption that working at home means working outside an economic system."},{"type":"paragraph","text":"WIEGO’s research also records irregular orders and intermediary relationships in home-based production. The existence of an intermediary is not, by itself, an explanation of every outcome. A useful account asks who supplies materials, agrees a rate, checks the work and bears the cost when an order changes or is rejected."},{"type":"paragraph","text":"Consider a hypothetical embroidered panel sold for a known price. That figure alone does not reveal the maker’s earnings. Material costs, unpaid preparation, delivery arrangements and the division of payment would all need to be established. An attractive retail price tag cannot substitute for that information."},{"type":"heading","level":2,"text":"Make room for the maker’s account"},{"type":"paragraph","text":"A consent-based interview should let the maker decide whether to be named, photographed or represented through her work alone. It should also distinguish her words from a retailer’s description. A family connection may be part of her identity, but it need not be the headline of her professional story."},{"type":"paragraph","text":"The resulting account can recognise pleasure, ambition and resourcefulness without hiding difficult conditions. It can also acknowledge that someone may choose another livelihood. Preserving embroidery should not mean asking its makers to accept any terms offered in the name of tradition. The craft’s cultural value and the worker’s economic choices belong in the same conversation."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Languages"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Embroidery learned at home and sold in markets","description":"Embroidery can connect household learning to market income, but its value cannot be understood without the maker’s time, choices and position in the supply chain.","primaryKeyword":"Pakistan embroidery livelihoods","socialTitle":"Embroidery learned at home and sold in markets","socialDescription":"Embroidery can connect household learning to market income, but its value cannot be understood without the maker’s time, choices and position in the supply chain."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Pakistan’s hidden workers: Wages and conditions of home-based workers and the informal economy","url":"https://www.ilo.org/publications/pakistan%E2%80%99s-hidden-workers-wages-and-conditions-home-based-workers-and","publisher":"International Labour Organization","accessDate":"2026-10-22","section":"2017 study publication"},{"title":"Labor Force Experiences for Urban Low-Income Pakistani Women","url":"https://documents1.worldbank.org/curated/en/308381611611828453/pdf/Labor-Force-Experiences-for-Urban-Low-Income-Pakistani-Women.pdf","publisher":"World Bank","accessDate":"2026-10-22"},{"title":"Socio-economic Conditions of Women Home-based Balochi Embroidery Workers in Balochistan, Pakistan","url":"https://www.uob.ac.pk/Journals/Balochistan-Review/data/BR%2001%202017/187-202%20Socio-economic%20Conditions%20of%20Women%20Home-based%20Balochi%20Embroidery%20Workers%20in%20Balochistan%2C%20Pakistan%2C%20Mehwish%20Qudoos%20Alizai.pdf","publisher":"Mehwish Qudoos Alizai / Balochistan Review","accessDate":"2026-10-22","section":"2017"},{"title":"Home-based workers research, Working Paper 14","url":"https://www.wiego.org/sites/default/files/publications/files/Mumtaz_WIEGO_WP14.pdf","publisher":"WIEGO","accessDate":"2026-10-22","section":"2012"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. Selected primary research findings and publication metadata read; no interview conducted by Virsapur. Each source-derived allocation below100 words. ILO2016 Karachi study not national/current statistics. No legal wage/employment-right assertions. No identifying quotations or invented named maker; propose consent-based reporting rather than pretending fieldwork happened.","editorialReason":"Plan consent-based accounts of labour and valuation without reducing women to unnamed craft bearers.","sortOrder":286}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-an-oral-history-is-a-relationship-not-just-a-recording','an-oral-history-is-a-relationship-not-just-a-recording','review','{"id":"story-an-oral-history-is-a-relationship-not-just-a-recording","type":"story","slug":"an-oral-history-is-a-relationship-not-just-a-recording","title":"An oral history is a relationship, not just a recording","summary":"An oral-history interview depends on consent, interpretation, preservation and return—not merely on capturing a clear recording.","body":[{"type":"paragraph","text":"A recorder can capture a voice without capturing the relationship that made the conversation possible. Oral history begins before the first question and continues after the file is saved. The narrator needs to understand the project, the interviewer needs to explain the proposed uses, and both need a realistic account of what will happen to the recording."},{"type":"paragraph","text":"The Oral History Association’s best-practice guidance identifies preparation, interviewing, preservation and access as connected parts of the work. It calls for documented informed consent and, where possible, an opportunity for narrators to approve the oral history before public release. These are not merely administrative steps added after a compelling interview has been obtained."},{"type":"heading","level":2,"text":"Agree on the conversation’s future"},{"type":"paragraph","text":"An interview for a private research project and an interview intended for an unrestricted website create different expectations. A participant should not have to discover the difference after publication. Explaining where material may appear, who will hold it and what review is possible helps make the agreement meaningful."},{"type":"paragraph","text":"Language adds another layer. A narrator may choose expressions whose significance is not fully carried by a short English translation. Keeping the original recording and documenting translation decisions allows future listeners to understand what has been changed. A polished quotation should not silently merge the narrator’s words with the editor’s explanation."},{"type":"paragraph","text":"Memory also has its own character. An oral account can reveal how a person understands an experience, including emphasis, uncertainty and later reflection. It should not automatically be treated as a precise chronological register. Where a historical claim requires corroboration, other evidence can be consulted without dismissing the narrator’s perspective as worthless."},{"type":"heading","level":2,"text":"Returning something useful"},{"type":"paragraph","text":"The recording’s destination should be planned, not improvised once storage becomes inconvenient. The Oral History Association advises selecting a repository capable of preserving the material and respecting the agreed conditions. For a small local project, that principle raises practical questions about copies, file formats, contact details and who will manage access if the original interviewer leaves."},{"type":"paragraph","text":"Returning a recording or transcript can also allow participants to use the work themselves. A file that exists only in an inaccessible institutional account may preserve information while failing to serve the people who contributed it. The form of return should be discussed rather than assumed: a digital link is not useful to everyone in the same way."},{"type":"paragraph","text":"For heritage storytelling, the most valuable interview is not necessarily the one that produces the most dramatic extract. It is one conducted through a clear and respectful process, with its context and conditions retained. The resulting record can then support future understanding without reducing the person who spoke to a source of quotations."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Languages"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"An oral history is a relationship, not just a recording","description":"An oral-history interview depends on consent, interpretation, preservation and return—not merely on capturing a clear recording.","primaryKeyword":"oral history community consent","socialTitle":"An oral history is a relationship, not just a recording","socialDescription":"An oral-history interview depends on consent, interpretation, preservation and return—not merely on capturing a clear recording."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Oral History Best Practices","url":"https://oralhistory.org/best-practices/","publisher":"Oral History Association","accessDate":"2026-10-22","section":"Preparation, interviewing, preservation and access"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Explain consent, translation and return of recordings through institutional practice.","sortOrder":287}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-what-community-led-safeguarding-changes','what-community-led-safeguarding-changes','review','{"id":"story-what-community-led-safeguarding-changes","type":"story","slug":"what-community-led-safeguarding-changes","title":"What community-led safeguarding changes","summary":"Community-led safeguarding changes who defines the work, controls the record and judges whether it remains useful to the people concerned.","body":[{"type":"paragraph","text":"Documentation can produce a valuable archive without ensuring that a practice remains viable. A recording may preserve a performance, yet say little about whether younger practitioners have opportunities to learn. Community-led safeguarding starts from a different question: what do the people who recognise and maintain this heritage consider necessary for its continuation?"},{"type":"paragraph","text":"UNESCO’s guidance on involving tradition bearers gives practitioners an active role in identifying and inventorying their heritage. Its discussion of inventories also recognises that communities may limit the information they provide. An inventory is therefore not simply a collector’s attempt to gather everything that can be recorded. Its scope and access conditions are part of the work."},{"type":"heading","level":2,"text":"From subjects to decision-makers"},{"type":"paragraph","text":"Imagine a proposed archive of a craft practice. An externally designed project might prioritise photographs of finished objects because they display well. Practitioners might instead identify teaching time, access to tools or recognition of individual makers as the more urgent concern. Neither viewpoint should be invented in an article about a real community. The example shows why the project’s priorities need to emerge through discussion rather than be settled in advance."},{"type":"paragraph","text":"Control over description matters too. A label chosen by an outsider may flatten distinctions that practitioners consider important. Names of techniques, relationships between stages of work and the meaning of particular occasions can require explanation in the language used by the people involved. A database should be able to accommodate that knowledge instead of forcing every practice into an overly broad category."},{"type":"paragraph","text":"Community leadership does not require a claim that every person agrees. Different generations, households or practitioners may have different interests. A useful process makes those differences discussable and records how decisions were reached. It should not treat an institution’s preferred representative as automatically authorised to settle every question."},{"type":"heading","level":2,"text":"Measure the result differently"},{"type":"paragraph","text":"The number of files uploaded is an easy output to count. It is not the same as successful safeguarding. A more useful evaluation asks whether the agreed aims were met, whether participants can access and use the record, and whether the work creates burdens or risks that were not anticipated."},{"type":"paragraph","text":"For an editorial platform, this changes the language of achievement. Publishing a story should not be described as saving a tradition unless there is evidence for that much larger claim. It may be a contribution to documentation, an invitation to learn or part of a wider practitioner-led effort."},{"type":"paragraph","text":"The difference is not modesty for its own sake. It is accuracy about agency. A community-led approach recognises that a heritage practice has a life beyond its appearance in an archive, and that those who sustain it should help determine how the archive serves that life."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Languages"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"What community-led safeguarding changes","description":"Community-led safeguarding changes who defines the work, controls the record and judges whether it remains useful to the people concerned.","primaryKeyword":"community led intangible heritage","socialTitle":"What community-led safeguarding changes","socialDescription":"Community-led safeguarding changes who defines the work, controls the record and judges whether it remains useful to the people concerned."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Involvement of tradition bearers and practitioners","url":"https://ich.unesco.org/en/tradition-bearers-and-practitioners-00259","publisher":"UNESCO Intangible Cultural Heritage","accessDate":"2026-10-22"},{"title":"Drawing up inventories","url":"https://ich.unesco.org/en/drawing-up-inventories-00313","publisher":"UNESCO Intangible Cultural Heritage","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Distinguish documentation from control, access and community decision-making.","sortOrder":288}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-recording-a-song-without-erasing-its-performer','recording-a-song-without-erasing-its-performer','review','{"id":"story-recording-a-song-without-erasing-its-performer","type":"story","slug":"recording-a-song-without-erasing-its-performer","title":"Recording a song without erasing its performer","summary":"A song recording should retain the performer’s identity, context and agreed conditions of use instead of becoming anonymous cultural background.","body":[{"type":"paragraph","text":"A recorded song can travel far from the occasion on which it was performed. A short clip may circulate without the singer’s name, the language, the accompanying musicians or the reason for the gathering. The sound remains audible, but much of the work that gives it meaning disappears. Responsible documentation should resist that loss of context."},{"type":"paragraph","text":"The Smithsonian Center for Folklife and Cultural Heritage’s shared-stewardship statement invites knowledge about attribution, meaning, context and the identity of artists and performers in its collections. That approach treats an archive as something that can be corrected and enriched through relationships, rather than as a finished store of anonymous cultural material."},{"type":"heading","level":2,"text":"The performer is part of the record"},{"type":"paragraph","text":"A useful recording description should identify the people involved as accurately as the circumstances permit. It should distinguish a song title from a genre label and a performer’s account from an editor’s interpretation. If a name or language identification is uncertain, the uncertainty should remain visible instead of being replaced by a confident guess."},{"type":"paragraph","text":"Context includes the circumstances of recording. Was this a public concert, a demonstration arranged for a researcher, a rehearsal or a gathering with particular restrictions? Those situations may produce different performances and expectations. An excerpt should not be presented as an unmediated glimpse of everyday life if the event was organised specifically for documentation."},{"type":"paragraph","text":"Credit and permission also answer different questions. Naming a musician does not itself establish permission for every reuse of a recording. Even an openly licensed file needs its specific conditions checked. The Creative Commons BY deed, for example, requires attribution and disclosure of changes, while warning that other permissions may still be relevant. This is a general distinction, not a ruling on any particular recording’s legal status."},{"type":"heading","level":2,"text":"Editing should not erase relationships"},{"type":"paragraph","text":"Selecting a short extract can remove introductions, exchanges with an audience or contributions by accompanists. Sometimes an excerpt is appropriate, but its limits should be stated. A transcript or translation should identify who prepared it and should not imply certainty where words remain unclear. Keeping a connection to the fuller record lets listeners understand what the excerpt leaves out."},{"type":"paragraph","text":"An archive should also offer a practical route for corrections. A performer, family member or knowledgeable listener may recognise a person or identify an error that was not apparent to the original recorder. Such information should be reviewed carefully, with its source retained."},{"type":"paragraph","text":"The aim is not to burden every act of listening with a legal lecture. It is to recognise that music reaches us through people, labour and specific occasions. A heritage platform serves the song better when it keeps those relationships audible and visible, rather than using the recording as interchangeable atmosphere."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Languages"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Recording a song without erasing its performer","description":"A song recording should retain the performer’s identity, context and agreed conditions of use instead of becoming anonymous cultural background.","primaryKeyword":"folk song documentation ethics","socialTitle":"Recording a song without erasing its performer","socialDescription":"A song recording should retain the performer’s identity, context and agreed conditions of use instead of becoming anonymous cultural background."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Shared Stewardship and Ethical Returns","url":"https://folklife.si.edu/archives/shared-stewardship-ethical-returns","publisher":"Smithsonian Center for Folklife and Cultural Heritage","accessDate":"2026-10-22"},{"title":"CC BY 4.0 deed","url":"https://creativecommons.org/licenses/by/4.0/","publisher":"Creative Commons","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Smithsonian institutional search-index text read; direct page fetch returned500. No claim of an interview or performer consent. General editorial discussion, not legal advice; rights specialist review required.","editorialReason":"Address attribution and permissions instead of treating public performance as free content.","sortOrder":289}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-migration-and-the-new-settings-of-regional-culture','migration-and-the-new-settings-of-regional-culture','review','{"id":"story-migration-and-the-new-settings-of-regional-culture","type":"story","slug":"migration-and-the-new-settings-of-regional-culture","title":"Migration and the new settings of regional culture","summary":"Bradford’s museum and exhibition records show how migration can create new settings for memory, making and cultural interpretation—not only stories of loss.","body":[{"type":"paragraph","text":"Migration changes the settings in which culture is practised and remembered. A familiar language may be spoken in a new workplace; a family photograph may become part of a city archive; an artist may use inherited memories to make work for a public gallery. Describing these changes only as cultural loss misses the new relationships and forms of expression that can emerge."},{"type":"paragraph","text":"Bradford’s museum records provide a specific example connected to migration from Pakistan. In an account of redeveloping a 1970s domestic display, museum staff describe using recorded memories, photographs and consultation with women from the WomenZone Community Centre. The resulting interpretation addressed a home associated with a recently migrated Pakistani family rather than presenting migration solely through a journey or border crossing."},{"type":"heading","level":2,"text":"Everyday life as historical evidence"},{"type":"paragraph","text":"The institutional account notes the contribution of conversations in Urdu and recollections about domestic life and leisure. These details matter because they show interpretation being shaped by experiences that might not be recoverable from an architectural shell alone. A room’s furniture can suggest a period, but the meaning of its arrangement needs more than a designer’s assumption."},{"type":"paragraph","text":"The display is still a museum construction, not a transparent window into every Pakistani household in Bradford. Its value lies in a documented process and a particular set of perspectives. Reading it carefully means asking which memories and objects were selected, while avoiding the expectation that one domestic scene represents an entire migrant population."},{"type":"paragraph","text":"Another Bradford example takes a different form. The 2024 exhibition Where It Began presented Osman Yousefzada’s work through questions of migration, identity, class and belonging. The museum’s account links the exhibition’s title to several historical relationships, including the artist’s father’s arrival in Bradford during the 1960s. Here migration becomes a subject of contemporary artistic investigation, not simply a background explanation for an inherited tradition."},{"type":"heading","level":2,"text":"Continuity does not require sameness"},{"type":"paragraph","text":"Taken together, these examples suggest an editorial approach. A heritage story can examine what people carry, adapt, remember or question without demanding that culture remain unchanged to count as meaningful. A new setting may alter an audience, a material or a mode of presentation while preserving some relationships and creating others."},{"type":"paragraph","text":"The evidence should remain particular. A museum display and an artist’s exhibition cannot establish what all migrants experience, and neither should be recruited into a universal story of successful integration or inevitable loss. They offer documented ways in which memory and cultural work enter public life."},{"type":"paragraph","text":"For readers exploring Pakistan’s heritage, migration expands the field of enquiry beyond the places where practices originated. It asks how people make a home, sustain connections and contribute to new environments, while retaining the names, choices and circumstances that keep those histories from becoming anonymous."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Languages"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Migration and the new settings of regional culture","description":"Bradford’s museum and exhibition records show how migration can create new settings for memory, making and cultural interpretation—not only stories of loss.","primaryKeyword":"diaspora regional languages Pakistan","socialTitle":"Migration and the new settings of regional culture","socialDescription":"Bradford’s museum and exhibition records show how migration can create new settings for memory, making and cultural interpretation—not only stories of loss."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Redeveloping the 1970s Back to Back","url":"https://bradfordmuseums.org/redeveloping-the-1970s-back-to-back/","publisher":"Bradford District Museums & Galleries","accessDate":"2026-10-22"},{"title":"Where It Began — Osman Yousefzada","url":"https://bradfordmuseums.org/event/where-it-began-osman-yousefzada/","publisher":"Bradford District Museums & Galleries","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Use documented urban community events to examine continuity without a loss-only narrative.","sortOrder":290}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-museums-of-living-culture-who-gets-to-speak','museums-of-living-culture-who-gets-to-speak','review','{"id":"story-museums-of-living-culture-who-gets-to-speak","type":"story","slug":"museums-of-living-culture-who-gets-to-speak","title":"Museums of living culture: who gets to speak?","summary":"A museum of living culture selects voices as well as objects. Its displays are strongest when interpretation remains accountable to the people represented.","body":[{"type":"paragraph","text":"A display of living culture can make a visitor feel close to people they have never met. Music, objects, reconstructed interiors and scenes of work create an impression of familiarity. That impression is produced through choices: what to include, whose words to use and which moment to present. Asking who gets to speak helps make those choices visible."},{"type":"paragraph","text":"Lok Virsa describes its Heritage Museum in Islamabad as a museum of ethnology concerned with living traditions, using visual narratives, dioramas and ethnographic displays. This identifies a different emphasis from an exhibition organised only around excavated objects. It also raises a distinctive interpretive challenge: living communities continue to change after a display is installed."},{"type":"heading","level":2,"text":"A scene is not an entire community"},{"type":"paragraph","text":"A reconstructed workplace may be informative about tools and spatial relationships. It can also suggest a single timeless way of life if dates, regional variation and the identities of practitioners are absent. A visitor should be able to distinguish a documented example from a representative arrangement and a staged scene from an unaltered historical interior."},{"type":"paragraph","text":"Labels can acknowledge these differences without becoming unreadable. Naming a maker, identifying a recording date or explaining who contributed to a display gives the viewer a route back to the people and evidence involved. A broad regional label may still be useful, but it should not make individual labour disappear."},{"type":"paragraph","text":"Participation can affect more than the wording of a caption. Bradford Museums’ account of revising a domestic display describes consultation that influenced object choices and interpretation. The point is not to assume that one museum’s process can simply be copied elsewhere. It provides a documented example of people’s recollections changing what a museum presents, rather than merely endorsing a finished arrangement."},{"type":"heading","level":2,"text":"Keep interpretation open to correction"},{"type":"paragraph","text":"Living-culture displays need ways to receive new information. A practitioner may recognise an incorrectly named tool; a musician may identify a performer; a visitor may challenge an overgeneralisation. A responsible institution can assess such contributions while recording who supplied them and why a change was made. Updating a label need not be treated as an embarrassment."},{"type":"paragraph","text":"The question of voice also applies to absence. Some knowledge may not be appropriate for public display, and some people may not wish to participate. A museum should not fill every gap with an invented representative scene simply to maintain visual completeness."},{"type":"paragraph","text":"Looking critically at interpretation does not diminish the pleasure of visiting a museum. It deepens it. Instead of seeing a display as culture itself, readers can understand it as a carefully made account of culture—one that should reveal its evidence, recognise its collaborators and remain answerable to the people whose lives give it meaning."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Museums","Languages"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"languages-literature-living","seo":{"title":"Museums of living culture: who gets to speak?","description":"A museum of living culture selects voices as well as objects. Its displays are strongest when interpretation remains accountable to the people represented.","primaryKeyword":"Lok Virsa representation","socialTitle":"Museums of living culture: who gets to speak?","socialDescription":"A museum of living culture selects voices as well as objects. Its displays are strongest when interpretation remains accountable to the people represented."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Heritage Museum","url":"https://lokvirsa.org.pk/heritage-museum/","publisher":"Lok Virsa","accessDate":"2026-10-22"},{"title":"Redeveloping the 1970s Back to Back","url":"https://bradfordmuseums.org/redeveloping-the-1970s-back-to-back/","publisher":"Bradford District Museums & Galleries","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Examine interpretive choices and community participation rather than an uncritical museum promotion.","sortOrder":291}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-an-indus-seal-as-a-made-object','an-indus-seal-as-a-made-object','review','{"id":"story-an-indus-seal-as-a-made-object","type":"story","slug":"an-indus-seal-as-a-made-object","title":"An Indus seal as a made object","summary":"An Indus seal can be examined as a worked material before anyone attempts to explain its signs.","body":[{"type":"paragraph","text":"A seal is easily reduced to its picture: an animal, a row of signs, an intriguing composition. Yet its surface also belongs to a manufactured object. Before asking what an inscription means, we can ask what was cut, what was heated and which observations belong to this particular specimen. That change of attention brings an otherwise anonymous maker into view without inventing a name or translating an unread text."},{"type":"paragraph","text":"Harappa''s published photographic record includes an instructive contrast. Jonathan Mark Kenoyer identifies an unfired rectangular steatite seal beside a fired and glazed example, both assigned to the later Harappa Phase. The same commentary distinguishes another fired and glazed seal from the preceding phase. These are not interchangeable illustrations of one timeless technique: their material condition and archaeological dating are part of the evidence."},{"type":"heading","level":2,"text":"From soft stone to finished surface"},{"type":"paragraph","text":"Kenoyer''s workshop study explains that steatite could be shaped while relatively soft and subsequently transformed by high-temperature firing. This gives the finished object a history that its present hardness alone does not reveal. The study also concerns faience, a different manufactured material; a pale or glazed appearance therefore should not replace an actual material identification."},{"type":"paragraph","text":"Imagine documenting a seal for an exhibition. A face-on photograph records the composition, but a second view of its edge could help readers understand thickness and damage. A scale prevents a small carving from being mentally enlarged into a monumental relief. A material description tells us something that colour reproduction cannot. These are different kinds of information, and none needs to compete with the visual pleasure of the image."},{"type":"paragraph","text":"An individual button seal provides a useful anchor. The Harappa Archaeological Research Project records H2000-4432/2174-3 from the Trench 54 area as fired steatite bearing four concentric-circle designs. Keeping that identifier with the image allows an editor to distinguish this find from superficially similar pieces. A generic caption such as “ancient seal” would discard that connection."},{"type":"heading","level":2,"text":"Making, use and meaning are different questions"},{"type":"paragraph","text":"Manufacturing evidence does not automatically establish how long a seal was used, who controlled it or what every mark signified. A proposed sequence of carving and firing is a statement about production. A claim about an owner''s occupation requires another kind of support. An interpretation of the signs requires something different again. The confidence attached to one conclusion cannot simply be transferred to the others."},{"type":"paragraph","text":"For a visitor, the most rewarding exercise is to keep those questions alongside one another. What can the photograph show? What has an excavator recorded? What has a materials specialist established? What remains an interpretation? Looking this way does not make the object less evocative. It replaces an imagined certainty with a more tangible achievement: a person selected a material and made a small surface capable of carrying an exceptionally deliberate design."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Material Culture"],"province":null,"district":null,"relatedDistrictIds":["punjab-sahiwal"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6579"],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"An Indus seal as a made object","description":"An Indus seal can be examined as a worked material before anyone attempts to explain its signs.","primaryKeyword":"Indus seal manufacture","socialTitle":"An Indus seal as a made object","socialDescription":"An Indus seal can be examined as a worked material before anyone attempts to explain its signs."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Steatite and Faience Seals and Tablets","url":"https://www.harappa.com/slide/steatite-and-faience-seals-and-tablets","publisher":"Harappa.com / Jonathan Mark Kenoyer","accessDate":"2026-10-22"},{"title":"Steatite button seal","url":"https://www.harappa.com/slide/steatite-button-seal","publisher":"Harappa Archaeological Research Project","accessDate":"2026-10-22"},{"title":"Steatite and Faience Manufacturing at Harappa","url":"https://www.harappa.com/sites/default/files/pdf/Kenoyer%202005%20Faience%20Workshop.pdf","publisher":"National Museum of Pakistan / Jonathan Mark Kenoyer","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Examine cutting, firing and wear rather than repeat the undeciphered-script article.","sortOrder":292}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-standardised-weights-and-the-evidence-of-measurement','standardised-weights-and-the-evidence-of-measurement','review','{"id":"story-standardised-weights-and-the-evidence-of-measurement","type":"story","slug":"standardised-weights-and-the-evidence-of-measurement","title":"Standardised weights and the evidence of measurement","summary":"Indus weights reveal relationships between measured quantities, but they are not a deciphered price list or a known currency.","body":[{"type":"paragraph","text":"A group of stone cubes can look modest beside a sculpture or seal. Its importance emerges when the pieces are measured together. The question is not simply how heavy each one is, but whether their masses form a patterned relationship. That relationship is evidence of a practice shared by makers and users, even when the words they used for its units are unavailable."},{"type":"paragraph","text":"The published display of Indus weights on Harappa.com identifies banded chert among their materials and describes a sequence of smaller units increasing by doubling. The same page also corrects a misleading visual impression: a conical shell object included in the photograph is not a weight. Even a carefully arranged museum group must therefore be read with its catalogue rather than treated as a self-explanatory set."},{"type":"heading","level":2,"text":"A system is more than a neat row"},{"type":"paragraph","text":"Jonathan Mark Kenoyer''s study of Harappan measurement revisits older claims that apparent uniformity demonstrated unusually rigid civic control. Its investigation of measured objects instead asks about standardisation alongside variation. This is a productive distinction. Repeated proportions can show that people recognised a convention; they do not, by themselves, identify the institution that maintained it or explain how disagreements were settled."},{"type":"paragraph","text":"Consider a hypothetical group with masses close to one, two, four and eight units. The pattern would be more persuasive than a collection whose values have no evident relationship. But an honest presentation would also show actual measurements, missing pieces and departures from the pattern. Rounding every value until it fits the proposed sequence would conceal the very evidence being tested."},{"type":"paragraph","text":"There is a further difference between mass and value. A weight can help measure a material, but it does not tell us its price. A measured quantity of one substance need not exchange for the same quantity of another. Calling a stone weight a coin, or assigning it a modern currency equivalent, would introduce a financial system that the object has not established."},{"type":"heading","level":2,"text":"What a useful label should preserve"},{"type":"paragraph","text":"For an individual piece, readers need the material identification, recorded mass, dimensions, find context and collection number. For an assemblage, they also need to know whether the objects were excavated together or assembled for comparison. A display can bring pieces from different places into a visually convincing sequence; that arrangement is an editorial decision, not necessarily an ancient arrangement recovered intact."},{"type":"paragraph","text":"This makes weights particularly good objects for learning how archaeological reasoning works. A proposal becomes stronger when another reader can inspect the observations behind it. A tidy diagram is helpful only if it leaves that route open. The small stone cube then becomes more than a symbol of an “advanced civilisation.” It introduces a specific problem: how people made quantities comparable across transactions, work and distance, and how much of that agreement can still be reconstructed from surviving things."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Material Culture"],"province":null,"district":null,"relatedDistrictIds":["punjab-sahiwal","sindh-larkana"],"provinceRegionIds":["punjab","sindh"],"relatedHeritageIds":["major-doam-6579","unesco-138"],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Standardised weights and the evidence of measurement","description":"Indus weights reveal relationships between measured quantities, but they are not a deciphered price list or a known currency.","primaryKeyword":"Indus weights measurement","socialTitle":"Standardised weights and the evidence of measurement","socialDescription":"Indus weights reveal relationships between measured quantities, but they are not a deciphered price list or a known currency."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Measuring the Harappan world","url":"https://www.harappa.com/sites/default/files/pdf/Kenoyer%202010%20Measuring%20the%20Harappan%20World.pdf","publisher":"Cambridge University Press / Jonathan Mark Kenoyer","accessDate":"2026-10-22"},{"title":"Weights","url":"https://www.harappa.com/slide/weights","publisher":"Harappa.com / National Museum of Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Explain material and proportional evidence without claiming a known currency system.","sortOrder":293}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-a-carnelian-beads-long-production-journey','a-carnelian-beads-long-production-journey','review','{"id":"story-a-carnelian-beads-long-production-journey","type":"story","slug":"a-carnelian-beads-long-production-journey","title":"A carnelian bead’s long production journey","summary":"Carnelian beads preserve evidence of shaping, drilling and finishing, while workshop comparisons reveal choices rather than one uniform production line.","body":[{"type":"paragraph","text":"A carnelian bead is a small object with a demanding internal problem: a hole must pass through stone without destroying the form around it. Its outside is what a wearer displays, but the perforation can be equally important to an archaeologist. A complete account therefore considers both the attractive finished surface and the less visible labour that made the bead usable."},{"type":"paragraph","text":"Jonathan Mark Kenoyer''s study of Indus bead technology makes Chanhudaro in Sindh a particularly valuable example. The workshop assemblage included roughly finished short beads as well as carefully shaped and polished long carnelian examples made with specialised drills. Different levels of finishing occurred within one production setting. It would be misleading to turn every rough bead into evidence of an incompetent maker or an earlier stage of civilisation."},{"type":"heading","level":2,"text":"Following a sequence without inventing a worker"},{"type":"paragraph","text":"Raw material, shaping, perforation, finishing and use are separate questions. A proposed production sequence should explain which marks support each step. It should also allow for an object that left manufacture without being worn, or one whose comparatively rough finish was acceptable to its user. “Finished” is not necessarily a synonym for the smoothest object in a modern display case."},{"type":"paragraph","text":"Kenoyer discusses the significance of wear inside perforations and the absence of such wear in the Chanhudaro examples he examined. These observations help distinguish production history from later use. They do not supply an owner''s identity or the price paid for an ornament. The distinction matters because a beautifully made bead is often invited to carry a complete social biography that its surviving evidence cannot support."},{"type":"paragraph","text":"An ethnographic study of carnelian production at Khambhat in India offers a different kind of comparison. It documents connected tasks and specialised working arrangements in a living industry. Such research can help archaeologists ask better questions about manufacturing waste and the organisation of labour. It is not a licence to transfer a modern worker''s tools, contracts or family structure unchanged into an Indus workshop."},{"type":"heading","level":2,"text":"The journey is not a single arrow"},{"type":"paragraph","text":"An exhibition map might draw an elegant line from a stone source to a workshop and then to a distant settlement. Each connection nevertheless needs its own evidence. Finding a finished bead at the destination does not identify every stop along the way. Nor does a shared colour prove that two stones came from the same deposit. A responsible diagram can distinguish a demonstrated connection from a suggested route."},{"type":"paragraph","text":"The bead''s long journey is consequently best approached as a set of connected investigations. Where did its material originate? Which operations are visible? Was it used, repaired or restrung? Where was it finally deposited? These questions preserve the fascination of movement while resisting an invented travel story. They also restore attention to the maker''s practical choices: the alignment of a hole, the treatment of a surface and the decision that this particular piece was ready to leave the workshop."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Material Culture"],"province":null,"district":null,"relatedDistrictIds":["sindh-shaheed-benazir-abad"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-6464"],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"A carnelian bead’s long production journey","description":"Carnelian beads preserve evidence of shaping, drilling and finishing, while workshop comparisons reveal choices rather than one uniform production line.","primaryKeyword":"Indus carnelian beads","socialTitle":"A carnelian bead’s long production journey","socialDescription":"Carnelian beads preserve evidence of shaping, drilling and finishing, while workshop comparisons reveal choices rather than one uniform production line."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Stone Beads of the Indus Tradition","url":"https://www.harappa.com/sites/default/files/pdf/Kenoyer2017%20Stone%20Beads_Chapter%2007.pdf","publisher":"Jonathan Mark Kenoyer","accessDate":"2026-10-22"},{"title":"Carnelian Bead Production in Khambhat, India","url":"https://www.harappa.com/sites/default/files/pdf/Kenoyer1994_Carnelian%20Bead%20Production%20in%20Khambhat%20India%20An%20E.pdf","publisher":"Jonathan Mark Kenoyer and collaborators","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Follow material sourcing and manufacturing steps through published analysis.","sortOrder":294}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-faience-is-not-simply-blue-stone','faience-is-not-simply-blue-stone','review','{"id":"story-faience-is-not-simply-blue-stone","type":"story","slug":"faience-is-not-simply-blue-stone","title":"Faience is not simply blue stone","summary":"Indus faience was a deliberately manufactured material, not merely a blue stone. Workshop evidence makes its technical character visible.","body":[{"type":"paragraph","text":"Blue-green colour can make an ancient bead seem straightforward: an attractive stone, selected and polished. Faience asks us to reconsider that first impression. Its appearance results from making a material as well as shaping an object. Understanding the distinction changes the kind of skill we recognise and the questions we ask of a museum label."},{"type":"paragraph","text":"In his report on Harappa''s Mound E workshop, Jonathan Mark Kenoyer describes faience manufacture involving processed quartz, colouring materials and high-temperature firing. He distinguishes this from steatite, a stone that could be carved and subsequently fired. The workshop investigated in the 2000–2001 excavations contained evidence for both industries. Their association does not make the two materials identical."},{"type":"heading","level":2,"text":"Colour is an observation, not an identification"},{"type":"paragraph","text":"A visitor can describe a blue-green surface without knowing its composition. A catalogue''s material identification goes further, and ideally rests on specialist examination. Keeping those two statements separate is important when a photograph has altered the apparent colour, when a surface has changed in burial or when an old label uses terminology differently from a modern technical report."},{"type":"paragraph","text":"The practical consequence is simple. A story about faience should not illustrate itself with any blue object that happens to be available. The selected object needs a recorded identification. If the record says steatite, it cannot silently become faience because the layout would benefit from another photograph. A visually coherent display must remain a materially accurate one."},{"type":"paragraph","text":"The workshop study gives manufacturing debris and unfinished pieces a role alongside completed ornaments. For interpretation, this reverses a familiar hierarchy: the less spectacular fragment may help answer a question that the intact object leaves open. A finished surface presents a successful outcome. Material left during production can make the operations behind that outcome easier to investigate."},{"type":"heading","level":2,"text":"A workshop is an argument assembled from evidence"},{"type":"paragraph","text":"Calling an excavated area a workshop is more informative when the explanation identifies the relevant finds and their relationships. One isolated ornament would not, on its own, demonstrate local manufacture. A claim about production asks whether the assemblage includes convincing traces of making and whether the context supports their association. The reasoning should remain visible rather than being compressed into a colourful reconstruction of workers at a furnace."},{"type":"paragraph","text":"It is equally important not to make this a recipe. An archaeological account of a high-temperature process is not an instruction to reproduce it at home, and a modern demonstration should identify its own materials and adaptations. Replication can test a proposal, but a successful modern object does not prove that every ancient maker followed the same procedure."},{"type":"paragraph","text":"Faience rewards this slower attention because it complicates the boundary between “natural” material and crafted appearance. The object is not less accomplished once its colour is explained. Its beauty becomes connected to controlled transformations, accumulated knowledge and decisions whose material consequences survive even when the maker''s own explanation does not."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Material Culture"],"province":null,"district":null,"relatedDistrictIds":["punjab-sahiwal"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6579"],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Faience is not simply blue stone","description":"Indus faience was a deliberately manufactured material, not merely a blue stone. Workshop evidence makes its technical character visible.","primaryKeyword":"Indus faience technology","socialTitle":"Faience is not simply blue stone","socialDescription":"Indus faience was a deliberately manufactured material, not merely a blue stone. Workshop evidence makes its technical character visible."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Steatite and Faience Manufacturing at Harappa","url":"https://www.harappa.com/sites/default/files/pdf/Kenoyer%202005%20Faience%20Workshop.pdf","publisher":"National Museum of Pakistan / Jonathan Mark Kenoyer","accessDate":"2026-10-22"},{"title":"Steatite and Faience Seals and Tablets","url":"https://www.harappa.com/slide/steatite-and-faience-seals-and-tablets","publisher":"Harappa.com / Jonathan Mark Kenoyer","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Clarify a manufactured material and the evidence for its production.","sortOrder":295}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-shell-bangles-and-connections-to-the-coast','shell-bangles-and-connections-to-the-coast','review','{"id":"story-shell-bangles-and-connections-to-the-coast","type":"story","slug":"shell-bangles-and-connections-to-the-coast","title":"Shell bangles and connections to the coast","summary":"Shell bangles connect inland archaeological finds to marine materials, but workshop waste is needed to understand where and how they were made.","body":[{"type":"paragraph","text":"A pale curved fragment from an inland settlement may preserve a connection to the sea. Yet the connection is not a complete itinerary. A shell bangle can demonstrate the use of marine material without revealing whether a whole shell, a partly worked ring or a finished ornament travelled to the place where it was found. Those alternatives imply different distributions of labour."},{"type":"paragraph","text":"Jonathan Mark Kenoyer''s study of Indus shell industries identifies several species used in ornament production. It also explains a limitation that is easy to overlook: a small finished fragment may have lost the anatomical features needed for a confident species identification. The surviving object can therefore be recognisably shell while its more precise biological attribution remains uncertain."},{"type":"heading","level":2,"text":"Looking at what was cut away"},{"type":"paragraph","text":"The study reconstructs bangle manufacture using working traces and discarded pieces. Saw cuts, shell anatomy and unfinished forms help distinguish stages that a polished ring can conceal. Kenoyer''s research at Balakot adds a coastal production context to the broader comparison. Together these investigations encourage us to treat manufacturing waste as evidence, not merely as the unattractive remainder of a collection."},{"type":"paragraph","text":"Suppose a hypothetical inland excavation yields only finished bangles. It would be reasonable to ask how the ornaments arrived, but premature to announce a local bangle factory. If another context contains consistently related blanks and cutting waste, the production question changes. The importance lies in the combination of finds and their recorded setting, not in the simple number of attractive objects recovered."},{"type":"paragraph","text":"This distinction also changes how we imagine exchange. A map line from coast to city is a summary of a relationship, not necessarily a direct journey by one merchant. Material could have changed hands, form and value along the way. Unless a particular route is independently documented, an illustration should leave the intermediate stages open rather than give them invented certainty."},{"type":"heading","level":2,"text":"Ornament does not explain its wearer"},{"type":"paragraph","text":"A bangle''s shape invites comparison with objects worn today. Comparison can make an unfamiliar fragment intelligible, but it cannot by itself establish an ancient wearer''s marital status, community or ritual obligations. Contemporary meanings belong to particular people and settings. They should not be projected backwards simply because both objects encircle a wrist."},{"type":"paragraph","text":"For an exhibition, a useful arrangement might place an accurately identified finished fragment beside a documented working piece and a diagram of the relevant shell anatomy. The purpose would not be to reconstruct a universal Indus workshop, but to make one supported manufacturing argument understandable. Each object would retain its own location, period and collection identifier."},{"type":"paragraph","text":"Shell bangles thus open two different histories. One concerns the movement of material between marine environments and inland settlements. The other concerns skilled transformation: understanding an irregular natural form well enough to cut a desired object from it. Keeping both in view gives the fragment more depth than either an isolated jewellery label or a sweeping claim about ancient trade can provide."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Material Culture"],"province":null,"district":null,"relatedDistrictIds":["sindh-shaheed-benazir-abad"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-6464"],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Shell bangles and connections to the coast","description":"Shell bangles connect inland archaeological finds to marine materials, but workshop waste is needed to understand where and how they were made.","primaryKeyword":"Indus shell bangles","socialTitle":"Shell bangles and connections to the coast","socialDescription":"Shell bangles connect inland archaeological finds to marine materials, but workshop waste is needed to understand where and how they were made."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Shell Working Industries of the Indus Civilization","url":"https://www.harappa.com/sites/default/files/pdf/Kenoyer1984_Shell%20Working%20Industries%20of%20the%20Indus%20Civilizati.pdf","publisher":"Paléorient / Jonathan Mark Kenoyer","accessDate":"2026-10-22"},{"title":"Shell Working at Ancient Balakot, Pakistan","url":"https://www.harappa.com/sites/default/files/pdf/Kenoyer1977_Shell%20Working%20at%20Ancient%20Balakot%2C%20Pakistan.pdf","publisher":"Jonathan Mark Kenoyer","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Use material identification and manufacturing waste to connect craft and exchange.","sortOrder":296}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-copper-alloy-objects-why-composition-matters','copper-alloy-objects-why-composition-matters','review','{"id":"story-copper-alloy-objects-why-composition-matters","type":"story","slug":"copper-alloy-objects-why-composition-matters","title":"Copper alloy objects: why composition matters","summary":"A copper-coloured object is not a chemical analysis. Composition helps distinguish metal choices while leaving questions about intention and sourcing open.","body":[{"type":"paragraph","text":"“Bronze” can sound like a complete explanation of an ancient metal object. In fact, it may conceal several questions. What elements were measured? How was the object made? Did its composition result from a deliberate recipe, the character of the raw material, or the reuse of earlier metal? An artefact''s outline does not answer all of these at once."},{"type":"paragraph","text":"Jonathan Mark Kenoyer and Heather M.-L. Miller''s review of Indus metal technologies makes this uncertainty explicit. Their survey discusses differing thresholds used to classify copper alloys and cautions that low concentrations of additional elements do not necessarily demonstrate intentional alloying. It also notes that similarly shaped objects could have different compositions. Form and chemistry are related avenues of investigation, not substitutes for each other."},{"type":"heading","level":2,"text":"A description and a result"},{"type":"paragraph","text":"A catalogue should distinguish an identification supported by analysis from one inherited from an older description. “Copper alloy” can be a useful cautious term where the exact composition is not established. It is less dramatic than a specific metallurgical claim, but more informative than a precision the available record cannot justify."},{"type":"paragraph","text":"Imagine two objects of the same shape in adjacent cases. One has a published laboratory result; the other has only an early catalogue entry. Writing identical confident captions would erase that difference in knowledge. A better interpretation explains why the first identification is more specific and what would be required to investigate the second. Visitors can then understand uncertainty as a feature of the evidence, rather than as an omission to disguise."},{"type":"paragraph","text":"The review also points to weaknesses in the available sample and inconsistencies between earlier investigations. These qualifications matter when someone tries to turn a handful of analyses into a claim about an entire civilisation. A dataset may illuminate the objects examined without representing every workshop, region or period equally well."},{"type":"heading","level":2,"text":"Chemistry is not a biography"},{"type":"paragraph","text":"Even a reliable composition does not name a maker or identify every movement of the material. An explanation of sourcing needs comparisons and context beyond the finished object''s appearance. Likewise, a difference between two objects need not mean that one craftsperson was more capable. Before ranking the work, we would need to know what each maker or user was trying to achieve."},{"type":"paragraph","text":"This approach changes the way technological sophistication is discussed. Rather than placing objects on a simple ladder from crude to advanced, it asks which practical choices can be demonstrated. The result may be a more complicated history, but it is also more respectful of craft: it does not assume that every material decision was directed towards a single modern ideal."},{"type":"paragraph","text":"The most useful museum encounter therefore moves between scales. The whole object offers clues about shape and handling. Its catalogue establishes context and identity. A specialist report addresses questions that the eye alone cannot settle. Keeping those layers connected lets an apparently familiar metal object remain an active piece of evidence, rather than a label whose certainty exceeds what has actually been tested."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Material Culture"],"province":null,"district":null,"relatedDistrictIds":["punjab-sahiwal"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6579"],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Copper alloy objects: why composition matters","description":"A copper-coloured object is not a chemical analysis. Composition helps distinguish metal choices while leaving questions about intention and sourcing open.","primaryKeyword":"Indus copper bronze objects","socialTitle":"Copper alloy objects: why composition matters","socialDescription":"A copper-coloured object is not a chemical analysis. Composition helps distinguish metal choices while leaving questions about intention and sourcing open."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Metal Technologies of the Indus Valley Tradition in Pakistan and Western India","url":"https://www.harappa.com/sites/default/files/pdf/Kenoyer1999_Metal%20Technologies%20of%20the%20Indus%20Valley%20Tradition.pdf","publisher":"Jonathan Mark Kenoyer and Heather M.-L. Miller","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Distinguish copper from bronze and object form from laboratory identification.","sortOrder":297}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-terracotta-figurines-without-invented-identities','terracotta-figurines-without-invented-identities','review','{"id":"story-terracotta-figurines-without-invented-identities","type":"story","slug":"terracotta-figurines-without-invented-identities","title":"Terracotta figurines without invented identities","summary":"Terracotta figurines invite stories, but observation, archaeological context and changing interpretations should come before invented identities.","body":[{"type":"paragraph","text":"A small clay figure seems to ask for a name. Goddess, ruler, child, animal companion: familiar identities can make an object immediately memorable. They can also conceal how little is known about its original use. The first task is not to suppress imagination, but to prevent a plausible story from replacing the surviving evidence."},{"type":"paragraph","text":"Two early photographs from Harappa make the problem unusually visible. The archival images identified as ASI 416/86 and 423/86 show a terracotta human head and a humped bull. In one photograph the head was placed upside down; the other corrects its orientation. Before any larger interpretation, there was a basic problem of how to look at the fragment."},{"type":"heading","level":2,"text":"Begin with what can be checked"},{"type":"paragraph","text":"A description can record the surviving headgear, applied details, breaks and the relationship between separate parts. These observations are not trivial preliminaries to a more exciting religious explanation. They are the evidence against which an explanation must be tested. A missing feature should remain missing in the account rather than being supplied from an imagined complete figure."},{"type":"paragraph","text":"The Harappa archive also preserves Daya Ram Sahni''s report of figurines associated with smaller vessels inside a large jar. Such contextual information poses different questions from an isolated photograph. It can direct attention towards deposition and association without automatically explaining the ceremony, household activity or later disturbance that produced the arrangement."},{"type":"paragraph","text":"The archive''s discussion of Sharri R. Clark''s research notes her challenge to an automatic “Mother Goddess” interpretation. The important change is methodological: representation, variation and context must be investigated rather than reduced to a single reproductive or sacred identity. This does not prove that no figurine had a religious role. It means that a religious role requires an argument."},{"type":"heading","level":2,"text":"Several questions can remain open together"},{"type":"paragraph","text":"For a hypothetical exhibition, compare three captions. “Mother Goddess” states an identity as settled. “Female figurine” describes an attribution based on representation but still needs attention to the surviving features. “Terracotta fragment with applied ornaments” may be more cautious where the evidence is incomplete. The most appropriate wording depends on the individual record; caution should sharpen description, not erase useful information."},{"type":"paragraph","text":"Function is another question. A figure might have been handled, displayed or deposited in circumstances that are no longer recoverable. Size alone cannot decide whether it was a toy, a ritual object or something else. Nor can the presence of elaborate ornament establish a specific rank in an otherwise undocumented social hierarchy."},{"type":"paragraph","text":"The pleasure of looking survives these limits. Clay carries decisions about proportion, attachment and expression that can be discussed without inventing a personal biography. An accurate account lets a visitor notice those decisions and follow the history of their interpretation. The object remains compelling because it has resisted complete explanation, not because a confident modern label has finally made it say more than the record supports."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Material Culture"],"province":null,"district":null,"relatedDistrictIds":["balochistan-kachhi","punjab-sahiwal"],"provinceRegionIds":["balochistan","punjab"],"relatedHeritageIds":["curated-mehrgarh","major-doam-6579"],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Terracotta figurines without invented identities","description":"Terracotta figurines invite stories, but observation, archaeological context and changing interpretations should come before invented identities.","primaryKeyword":"Indus terracotta figurines","socialTitle":"Terracotta figurines without invented identities","socialDescription":"Terracotta figurines invite stories, but observation, archaeological context and changing interpretations should come before invented identities."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Terracotta Head and Bull","url":"https://www.harappa.com/slide/terracotta-head-and-bull","publisher":"Harappa.com / Archaeological Survey of India records","accessDate":"2026-10-22"},{"title":"The Social Lives of Figurines: Recontextualizing the Third-Millennium-BC Terracotta Figurines from Harappa","url":"https://www.harappa.com/content/social-lives-figurines-recontextualizing-third-millennium-bc-terracotta-figurines-harappa","publisher":"Harappa.com / discussion of Sharri R. Clark","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Separate observed form from unsupported mother-goddess or ruler labels.","sortOrder":298}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-toy-cart-or-ritual-model-reading-miniature-objects','toy-cart-or-ritual-model-reading-miniature-objects','review','{"id":"story-toy-cart-or-ritual-model-reading-miniature-objects","type":"story","slug":"toy-cart-or-ritual-model-reading-miniature-objects","title":"Toy cart or ritual model? Reading miniature objects","summary":"Miniature carts show how construction, context and revised identifications matter more than assuming that every small object was a toy.","body":[{"type":"paragraph","text":"A miniature cart immediately suggests movement. We imagine wheels turning and a hand pulling it across the ground. That response is understandable, but the imagination has already supplied a user and an activity. To study the object carefully, we need to return to its construction and the circumstances in which its parts were recovered."},{"type":"paragraph","text":"The published Nausharo example provides unusually concrete information. The terracotta frame has openings interpreted as fittings for wooden elements, and two wheels were found beside it. The catalogue places the assemblage in Period III at Nausharo in Balochistan. Its proposed reconstruction depends on the arrangement of those features, not simply on a resemblance to a cart seen today."},{"type":"heading","level":2,"text":"A small structure with missing parts"},{"type":"paragraph","text":"This is an object whose surviving material does not necessarily represent its entire original construction. When a reconstruction adds wooden bars or an axle, it should distinguish the surviving terracotta from the inferred components. Colour-coding the additions or explaining them in a caption can make that distinction legible without making the display visually confusing."},{"type":"paragraph","text":"The word “toy” in a catalogue is itself an interpretation worth understanding. A model capable of moving is compatible with play, but mechanical possibility and demonstrated use are not identical. Conversely, uncertainty should not prompt an equally unsupported ritual explanation. Calling a miniature sacred because its everyday use is unknown does not solve the evidential problem."},{"type":"paragraph","text":"A second Harappa example shows how identifications can change. Daya Ram Sahni initially discussed curved, perforated terracotta pieces as possible implements for making twine, while acknowledging uncertainty. Kenoyer''s later commentary identifies them as sides of miniature ox-carts. The archived record preserves both readings, allowing us to see that the present label emerged through comparison rather than appearing complete at excavation."},{"type":"heading","level":2,"text":"Reconstruction as a question"},{"type":"paragraph","text":"Imagine presenting a replica beside the documented fragments. Its usefulness would lie in showing how the proposed parts fit together. If the replica rolls, it demonstrates that this arrangement is mechanically possible. It does not prove who owned the ancient object, whether it was pulled often, or what stories accompanied its use. A demonstration tests one part of an interpretation, not an entire social history."},{"type":"paragraph","text":"This makes miniatures especially good teaching objects. They bring design down to a scale where a visitor can follow connections and ask why an opening sits where it does. At the same time, their smallness encourages assumptions about children, domestic life and intention. Keeping the construction argument visible helps those appealing assumptions remain questions."},{"type":"paragraph","text":"The best account therefore does not choose between a lifeless list of dimensions and an invented scene of ancient play. It connects the catalogue, the surviving parts and a clearly labelled reconstruction. The miniature becomes a record of making and a history of interpretation, while leaving its original users more room than a single confident story would allow."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Material Culture"],"province":null,"district":null,"relatedDistrictIds":["punjab-sahiwal"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6579"],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Toy cart or ritual model? Reading miniature objects","description":"Miniature carts show how construction, context and revised identifications matter more than assuming that every small object was a toy.","primaryKeyword":"Indus miniature carts","socialTitle":"Toy cart or ritual model? Reading miniature objects","socialDescription":"Miniature carts show how construction, context and revised identifications matter more than assuming that every small object was a toy."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Toy carts, Nausharo","url":"https://www.harappa.com/slide/toy-carts-nausharo","publisher":"Harappa.com / Jonathan Mark Kenoyer","accessDate":"2026-10-22"},{"title":"Two earthenware implements","url":"https://www.harappa.com/slide/two-earthenware-implements","publisher":"Harappa.com / Daya Ram Sahni and Jonathan Mark Kenoyer","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Compare interpretations and explain why scale alone does not establish use.","sortOrder":299}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-spindle-whorls-and-the-evidence-for-fibre-work','spindle-whorls-and-the-evidence-for-fibre-work','review','{"id":"story-spindle-whorls-and-the-evidence-for-fibre-work","type":"story","slug":"spindle-whorls-and-the-evidence-for-fibre-work","title":"Spindle whorls and the evidence for fibre work","summary":"Spindle whorls are evidence for fibre work, but identifying a tool, a fibre and an ancient textile requires different observations.","body":[{"type":"paragraph","text":"A spindle whorl is an unassuming route into a largely missing world of cloth. The object helps a spindle turn while fibres are formed into thread. Its survival can draw attention to work that is less immediately visible than stone carving or metal casting, but a perforated object should not be assigned to spinning merely because that identification would complete a familiar story."},{"type":"paragraph","text":"Rita Wright and colleagues'' study of a jute textile trace from Harappa demonstrates the importance of combining different evidence. Their identification concerns material preserved on a ceramic object dated to the later third millennium BCE. They also discuss the possibility that some finds previously classified as wheels, weights or beads might have served as whorls. That is a research proposal, not a blanket relabelling of every pierced clay disc."},{"type":"heading","level":2,"text":"Tools and fibres answer different questions"},{"type":"paragraph","text":"The physical characteristics of a possible whorl can be recorded and compared, but a tool''s presence does not automatically identify the fibre spun with it. The jute study relies on examination of the surviving textile structure for its material claim. A distinction between tool evidence and fibre evidence prevents a label from turning a plausible association into a demonstrated connection."},{"type":"paragraph","text":"Jonathan Mark Kenoyer''s survey of ancient Indus textiles describes the variety of indirect traces available, including impressions and fibres preserved in association with other materials. Such traces are fragmentary. A surviving scrap and a depiction of clothing do not offer identical information: one may preserve structure while the other presents a representation whose details require interpretation."},{"type":"paragraph","text":"For a visitor, this opens a useful sequence of questions. Is the exhibit an actual fibre, an impression, a representation or a tool? What feature permits its identification? Does the evidence concern spinning, weaving or the finished garment? These distinctions make the subject more accessible because they show exactly how a claim has been reached."},{"type":"heading","level":2,"text":"Restoring labour without inventing a household"},{"type":"paragraph","text":"It is tempting to turn a whorl into a scene of a woman spinning in a named kind of household. Unless the context provides further evidence, that image adds gender, social organisation and location beyond what the object alone establishes. Recognising labour does not require assigning an anonymous worker a biography borrowed from another period."},{"type":"paragraph","text":"A hypothetical display could instead place an accurately identified whorl beside a clearly labelled modern demonstration of spinning. The demonstration would explain the mechanism, while the ancient record would establish the find''s identity and context. Its modern fibre and technique should remain explicit, so that an educational comparison does not quietly become a claim of exact continuity."},{"type":"paragraph","text":"The whorl then tells a more demanding story than “people made cloth.” It introduces the difficulty of recovering ordinary work from uneven survival. It invites attention to the small traces through which skill becomes archaeologically visible, while reminding us that the absence of a complete textile is not permission to weave an unsupported one in words."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Textiles","Material Culture"],"province":null,"district":null,"relatedDistrictIds":["punjab-sahiwal"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6579"],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Spindle whorls and the evidence for fibre work","description":"Spindle whorls are evidence for fibre work, but identifying a tool, a fibre and an ancient textile requires different observations.","primaryKeyword":"archaeological spindle whorls","socialTitle":"Spindle whorls and the evidence for fibre work","socialDescription":"Spindle whorls are evidence for fibre work, but identifying a tool, a fibre and an ancient textile requires different observations."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"New evidence for jute in the Indus civilization","url":"https://www.harappa.com/sites/default/files/pdf/Jute.pdf","publisher":"Archaeological and Anthropological Sciences / Wright, Lentz, Beaubien and Kimbrough","accessDate":"2026-10-22"},{"title":"Ancient Textiles of the Indus Valley Region","url":"https://www.harappa.com/sites/default/files/pdf/Kenoyer2004%20IndusTextilesfinal.pdf","publisher":"Koel Publications / Jonathan Mark Kenoyer","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Connect small tools with textile production while acknowledging material preservation limits.","sortOrder":300}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-a-cooking-pot-and-its-traces-of-use','a-cooking-pot-and-its-traces-of-use','review','{"id":"story-a-cooking-pot-and-its-traces-of-use","type":"story","slug":"a-cooking-pot-and-its-traces-of-use","title":"A cooking pot and its traces of use","summary":"A pot’s form and its absorbed residues offer different evidence about food. Neither should be turned into a complete ancient recipe.","body":[{"type":"paragraph","text":"A vessel''s shape can suggest how it might have been handled, filled or heated. It cannot, by itself, tell us everything that went inside. Calling an archaeological vessel a cooking pot is therefore the beginning of an investigation rather than a recovered menu. Surface traces, absorbed material and excavation context can each contribute different evidence."},{"type":"paragraph","text":"Akshyeta Suryanarayan and collaborators analysed lipid residues in pottery from Indus settlements in present-day northwest India. Their study includes rural sites as well as larger settlements, rather than treating a single urban assemblage as representative of everyone. Its relevance to Pakistan''s Indus heritage is comparative: these are not chemical results from a pot excavated at Harappa or Moenjodaro."},{"type":"heading","level":2,"text":"What remains inside the clay"},{"type":"paragraph","text":"The researchers identified evidence consistent with animal products, while explaining uncertainties in interpreting some chemical signatures. Mixtures and the lack of suitable local reference materials complicated particular assignments. This is a more careful result than a headline claiming to have recovered one universal Indus diet. Laboratory evidence can narrow possibilities without turning every sample into a named dish."},{"type":"paragraph","text":"The distinction matters for public interpretation. A reference to dairy processing, for example, is not automatically evidence for a particular modern recipe. Nor does an ingredient category tell us the occasion, seasoning or social meaning of a meal. Those questions require additional evidence, and some may remain unanswered."},{"type":"paragraph","text":"Experimental research offers another caution. A year-long cooking study compared different forms of residue to investigate whether they reflected a final use or accumulated cooking events. The key question is temporal: what interval of a vessel''s history does a sample represent? A chemical trace need not be a direct snapshot of the last meal prepared before the pot was broken or abandoned."},{"type":"heading","level":2,"text":"Different clues, different scales"},{"type":"paragraph","text":"Imagine a museum display with a vessel drawing, a photograph of the sampled fragment and a summary of the analysis. Keeping them together would help visitors understand the chain from an excavated object to a scientific claim. The result should identify the actual sample, rather than illustrating an unrelated beautiful pot and allowing readers to assume it was tested."},{"type":"paragraph","text":"This is also why a single vessel cannot stand in for a whole settlement''s cuisine without qualification. People may have used different containers for different tasks, and the sampled material represents only what survived and was selected for analysis. A sensible account makes the limits of that selection part of the explanation instead of hiding them in technical notes."},{"type":"paragraph","text":"The cooking pot is compelling precisely because it sits between ordinary life and analytical difficulty. We recognise the act of preparing food, yet its ancient details are not automatically familiar. Reading the vessel carefully means combining what its form permits, what its context records and what its residues support. The result is not a reconstructed dinner served with false certainty, but a better-founded encounter with past habits of nourishment and work."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Material Culture"],"province":null,"district":null,"relatedDistrictIds":["punjab-khanewal"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-8671"],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"A cooking pot and its traces of use","description":"A pot’s form and its absorbed residues offer different evidence about food. Neither should be turned into a complete ancient recipe.","primaryKeyword":"archaeological pottery use wear","socialTitle":"A cooking pot and its traces of use","socialDescription":"A pot’s form and its absorbed residues offer different evidence about food. Neither should be turned into a complete ancient recipe."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Lipid residues in pottery from the Indus Civilisation in northwest India","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7829615/","publisher":"Journal of Archaeological Science / Suryanarayan and collaborators","accessDate":"2026-10-22"},{"title":"Interpreting ancient food practices: stable isotope and molecular analyses of visible and absorbed residues from a year-long cooking experiment","url":"https://pubmed.ncbi.nlm.nih.gov/32855436/","publisher":"Scientific Reports / experimental residue research","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Distinguish form-based interpretation from residues and wear evidence.","sortOrder":301}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-perforated-vessel-as-an-archaeological-puzzle','the-perforated-vessel-as-an-archaeological-puzzle','review','{"id":"story-the-perforated-vessel-as-an-archaeological-puzzle","type":"story","slug":"the-perforated-vessel-as-an-archaeological-puzzle","title":"The perforated vessel as an archaeological puzzle","summary":"Perforated Indus vessels have prompted several functional explanations. Their holes are clear evidence; a single universal purpose is not.","body":[{"type":"paragraph","text":"The holes are the first thing one notices. A perforated Indus vessel appears to announce that something was meant to pass through its walls. That observation is useful, but incomplete. What passed through, under which conditions, and in combination with what other equipment? A striking shape can generate a strong hypothesis without establishing a single answer."},{"type":"paragraph","text":"In commentary accompanying a National Museum of Pakistan example, Jonathan Mark Kenoyer discusses straining, the preparation of beverages and dairy processing among the possibilities considered for different perforated vessels. He also points to residue research suggesting varied uses. The careful reading is not that archaeologists have discovered three interchangeable names for the same function, but that the objects need to be studied individually and comparatively."},{"type":"heading","level":2,"text":"The vessel around the vessel"},{"type":"paragraph","text":"Some published examples were associated with larger containers. That relationship is essential to understanding proposals involving straining. An isolated perforated object may not represent the complete apparatus. A reconstruction should therefore show which components were found together, which are supplied by comparison and which remain hypothetical. Otherwise a persuasive illustration can hide the weakest part of the argument."},{"type":"paragraph","text":"Size also deserves attention. A small perforated form and a tall cylindrical jar may belong in the same broad visual family without performing exactly the same task. Grouping them for study is a starting point. It should not remove differences in their dimensions, openings, bases or recorded associations."},{"type":"paragraph","text":"The National Museum in New Delhi''s educational booklet invites readers to consider possible uses for a perforated jar. The wording preserves an important space for inquiry. A classroom can compare proposals without pretending that a successful guess has recovered the original owner''s intention. The exercise becomes stronger when pupils explain which feature supports their answer and what further evidence would change it."},{"type":"heading","level":2,"text":"Testing a suggestion"},{"type":"paragraph","text":"For example, a hypothetical filtering proposal should address more than the presence of holes. Would the proposed material escape through them? Does the explanation require a lining or another container? Is there evidence for those additions in the relevant context? These are practical questions, not proof that any particular ancient vessel was a filter."},{"type":"paragraph","text":"Likewise, a reconstruction that successfully performs a task demonstrates possibility rather than exclusivity. A container can work in more than one arrangement. Evidence of ancient use must come back into the discussion before a modern experiment is turned into a definitive label."},{"type":"paragraph","text":"This is why the perforated vessel deserves more than a caption calling it an archaeological mystery. That phrase can imply that nothing useful is known. In reality, manufacture, form and context offer specific information, while function remains open to investigation. A good account identifies both. The holes cease to be a puzzle awaiting one dramatic solution and become an invitation to follow how archaeologists compare explanations, reject weak ones and retain uncertainty where the evidence genuinely requires it."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Material Culture"],"province":null,"district":null,"relatedDistrictIds":["punjab-khanewal"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-8671"],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"The perforated vessel as an archaeological puzzle","description":"Perforated Indus vessels have prompted several functional explanations. Their holes are clear evidence; a single universal purpose is not.","primaryKeyword":"Indus perforated pottery","socialTitle":"The perforated vessel as an archaeological puzzle","socialDescription":"Perforated Indus vessels have prompted several functional explanations. Their holes are clear evidence; a single universal purpose is not."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Perforated Jar","url":"https://www.harappa.com/slide/perforated-jar","publisher":"Harappa.com / Jonathan Mark Kenoyer","accessDate":"2026-10-22"},{"title":"Life in Harappan Civilization","url":"https://nationalmuseumindia.gov.in/assets/pdf/Life-in-Harappan-Civilization-activity-booklet.pdf","publisher":"National Museum, New Delhi","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Present competing functional interpretations without selecting a convenient story.","sortOrder":302}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-terracotta-cakes-a-familiar-name-for-uncertain-objects','terracotta-cakes-a-familiar-name-for-uncertain-objects','review','{"id":"story-terracotta-cakes-a-familiar-name-for-uncertain-objects","type":"story","slug":"terracotta-cakes-a-familiar-name-for-uncertain-objects","title":"Terracotta cakes: a familiar name for uncertain objects","summary":"“Terracotta cake” is a modern descriptive label. Context and working traces, not the nickname, must guide explanations of these clay objects.","body":[{"type":"paragraph","text":"A name can make an unfamiliar object seem familiar too quickly. Archaeological “terracotta cakes” are not preserved food. The term groups clay objects whose appearance encouraged a convenient descriptive label. Before asking what a cake did, we need to remember that its name is not ancient testimony about its purpose."},{"type":"paragraph","text":"The Rediscovering Harappa catalogue includes triangular examples from Kot Diji and Cholistan, identified as P-341 and P-2057. It also records oval examples from Cholistan. Their inclusion under related names makes comparison possible, but the catalogue''s shapes, locations and object numbers should remain attached to them. A broad category is useful only while it preserves meaningful differences."},{"type":"heading","level":2,"text":"An explanation tied to a context"},{"type":"paragraph","text":"Cortesi and colleagues discuss these objects within research on connections between the Indus and the Helmand region. Their account considers uses involving heat and industrial or domestic activity, while recognising that marked examples and variation complicate interpretation. Their evidence includes Shahr-i Sokhta in present-day Iran; those observations should not be silently presented as excavations in Pakistan."},{"type":"paragraph","text":"This produces a more interesting question than simply choosing a dictionary definition. Could superficially similar objects have performed different roles in different settings? A proposed heat-related use needs to be considered alongside the material, condition and associated finds. A mark on one piece needs its own investigation rather than being treated as decoration with an obvious universal meaning."},{"type":"paragraph","text":"The published Beas survey provides another perspective. Its researchers counted and weighed surface materials systematically, including terracotta cakes and other fired-clay debris. The value here lies in recording ordinary finds as part of a spatial sample. A single attractive specimen cannot show the distribution that a consistent survey may reveal."},{"type":"heading","level":2,"text":"What an unglamorous find can contribute"},{"type":"paragraph","text":"For a public display, a complete example may establish shape, while a fragment demonstrates what much of the actual record looks like. A map of recorded concentrations could explain a research question, provided it does not convert surface distribution into a complete plan of ancient activity. The distinction between where something was recovered and where it was originally used must remain visible."},{"type":"paragraph","text":"There is no need to make the object more prestigious by attaching it to a dramatic ritual. Nor should a practical interpretation make it unworthy of attention. Ordinary equipment can be central to understanding how work was organised, particularly when repeated forms appear in substantial quantities."},{"type":"paragraph","text":"The careful label consequently does two jobs. It allows the established term “terracotta cake” to connect the object with research literature, and it explains that the term describes a class rather than settles a function. This modest clarification protects the reader from a false certainty. It also preserves a genuine archaeological opportunity: to investigate how repeated, apparently simple objects participated in processes whose finished products usually receive more of our attention."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Material Culture"],"province":null,"district":null,"relatedDistrictIds":["punjab-sahiwal"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6579"],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Terracotta cakes: a familiar name for uncertain objects","description":"“Terracotta cake” is a modern descriptive label. Context and working traces, not the nickname, must guide explanations of these clay objects.","primaryKeyword":"Indus terracotta cakes","socialTitle":"Terracotta cakes: a familiar name for uncertain objects","socialDescription":"“Terracotta cake” is a modern descriptive label. Context and working traces, not the nickname, must guide explanations of these clay objects."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Rediscovering Harappa","url":"https://www.harappa.com/sites/default/files/pdf/Rediscovering_Harappa.pdf","publisher":"Exhibition catalogue, Harappa.com repository","accessDate":"2026-10-22"},{"title":"Cultural Relationships Beyond the Iranian Plateau","url":"https://www.harappa.com/sites/default/files/pdf/Indus-helmand2.pdf","publisher":"Paléorient / Cortesi, Tosi, Lazzari and Vidale","accessDate":"2026-10-22"},{"title":"Sampling and Recording of Surface Materials","url":"https://www.harappa.com/beas/sampling-recording","publisher":"Rita P. Wright, Joseph Shuldenrein and M. Rafique Mughal","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Explain why an archaeological nickname does not settle an object’s function.","sortOrder":303}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-stone-tools-in-a-village-economy','stone-tools-in-a-village-economy','review','{"id":"story-stone-tools-in-a-village-economy","type":"story","slug":"stone-tools-in-a-village-economy","title":"Stone tools in a village economy","summary":"Stone tools remained part of Indus economies alongside other technologies. Their material and working traces deserve study without a hierarchy of “primitive” and “advanced.”","body":[{"type":"paragraph","text":"A stone blade in an agricultural settlement is not evidence that its users failed to discover better materials. That assumption turns a technological label into a judgement about people. The more useful questions concern what the blade was made to do, how it was produced and why this material remained part of the available toolkit."},{"type":"paragraph","text":"Research on Rohri Hills chert follows stone beyond the place where it occurs naturally. The published study of exploitation and circulation discusses tools found in a range of Indus settings and reviews evidence for specialised production and movement. Its subject is not merely a quarry on a map, but the connection between raw material, manufacturing choices and the places where implements were used."},{"type":"heading","level":2,"text":"Stone beside other technologies"},{"type":"paragraph","text":"A settlement''s tools need not belong to one material alone. The presence of metal does not make every stone implement obsolete. For interpretation, this means avoiding a display sequence in which stone disappears as soon as a supposedly superior technology enters the story. Different materials can form parts of the same working environment."},{"type":"paragraph","text":"A recent review of Indus lithic evidence also draws attention to uneven research. Published collections and functional studies do not cover every region equally. That qualification matters when the absence of a reported tool is used to claim the absence of an activity. An under-studied collection is not the same thing as a community that never performed the work."},{"type":"paragraph","text":"“Blade” describes an archaeological form, not a complete occupation. Without appropriate evidence, a blade should not become a farmer''s sickle, a butcher''s knife or a ritual implement solely because one interpretation would enliven the caption. A specific functional claim needs a specific argument, ideally connected to the object or closely relevant assemblage being discussed."},{"type":"heading","level":2,"text":"A village-scale question"},{"type":"paragraph","text":"Consider a hypothetical village display. One panel might address the source of the stone; another, traces of manufacture; a third, evidence for use. Those panels need not all reach the same level of certainty. A material attribution could be strong while the precise task remains unresolved. Combining them into one confident narrative would make the interpretation simpler at the expense of accuracy."},{"type":"paragraph","text":"Waste pieces deserve a place in this account. They can help distinguish the arrival of finished implements from the working of material locally, although the inference depends on the assemblage and its context. An isolated tool cannot supply the whole production history of the settlement in which it was found."},{"type":"paragraph","text":"The result is a less theatrical but richer picture of a village economy. Rather than illustrating an evolutionary stage, the stone implement becomes evidence of choices within a functioning community. It may connect everyday work to skilled production and distant materials. Its significance rests not on looking primitive or unexpectedly modern, but on the particular relationships that careful archaeological study can demonstrate."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Material Culture"],"province":null,"district":null,"relatedDistrictIds":["balochistan-kachhi"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["curated-mehrgarh"],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Stone tools in a village economy","description":"Stone tools remained part of Indus economies alongside other technologies. Their material and working traces deserve study without a hierarchy of “primitive” and “advanced.”","primaryKeyword":"Mehrgarh stone tools","socialTitle":"Stone tools in a village economy","socialDescription":"Stone tools remained part of Indus economies alongside other technologies. Their material and working traces deserve study without a hierarchy of “primitive” and “advanced.”"},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Exploitation, Transport, and Circulation of the Rohri Hills Chert during the Indus Period","url":"https://www.mdpi.com/2571-9408/7/8/200","publisher":"Heritage","accessDate":"2026-10-22"},{"title":"Where Are the “Lithics” of Chalcolithic Indus Civilization?","url":"https://www.tandfonline.com/doi/full/10.1080/01977261.2025.2523610","publisher":"Lithic Technology","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft based on accessible indexed primary article text; MDPI direct reader returned429. Recheck full papers and site-specific functional claims before publication. No individual blade is assigned an unverified function.","editorialReason":"Read making and use alongside farming rather than treat stone technology as a primitive stage.","sortOrder":304}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-gandharan-schist-and-the-work-of-the-sculptor','gandharan-schist-and-the-work-of-the-sculptor','review','{"id":"story-gandharan-schist-and-the-work-of-the-sculptor","type":"story","slug":"gandharan-schist-and-the-work-of-the-sculptor","title":"Gandharan schist and the work of the sculptor","summary":"Gandharan schist sculpture joins close carving to the possibilities and vulnerabilities of stone. Its material history is part of its artistic achievement.","body":[{"type":"paragraph","text":"The folds of a Gandharan robe invite the eye to follow lines across stone. They can seem almost independent of the material, as if a sculptor had simply translated cloth into a permanent surface. Yet the material was never passive. Its scale, structure and condition affected both the making of an image and the form in which that image survives."},{"type":"paragraph","text":"Kurt Behrendt''s Metropolitan Museum discussion draws attention to a monumental bodhisattva torso and the difficulty of producing large schist sculptures. The stone''s tendency to break along its internal planes contributes to understanding the extensive losses. The surviving torso is therefore not merely an incomplete version of a figure: its fragmentary state also belongs to a material history."},{"type":"heading","level":2,"text":"Looking beyond the front"},{"type":"paragraph","text":"The British Museum record for the seated Buddha numbered 1895,1026.1 includes details rarely carried into a general photograph caption. It describes crystalline inclusions, breaks, surface loss and rough working at the back, as well as a modern supporting arrangement. These observations connect the admired carved face to an object with sides, an underside and a history of display."},{"type":"paragraph","text":"That fuller record changes the questions a visitor can ask. Which surfaces were intended to receive close attention? Which preserve marks of working? What belongs to the ancient object and what to a modern mount? A front-facing image remains valuable, but should not be mistaken for complete access to the sculpture."},{"type":"paragraph","text":"Tool marks can introduce craft without requiring an invented sculptor. A signed object or documented workshop attribution would support one kind of account; an anonymous work permits another. Similar handling of drapery may invite comparison, but it does not automatically identify a single hand, family or migrant artisan. The attribution must be proportionate to the evidence."},{"type":"heading","level":2,"text":"Skill without a solitary genius story"},{"type":"paragraph","text":"It is tempting to explain an impressive sculpture through one exceptional individual. A more open account can consider carving, preparation, installation and later repair as separate questions, without claiming an undocumented division of labour. This leaves room for collective production where research supports it and avoids making anonymity a reason to neglect the practical intelligence visible in the work."},{"type":"paragraph","text":"Material description also prevents a common visual shortcut. Gandharan sculptures were made in more than one medium, and an example in stucco cannot stand in for a schist object when the topic is carving stone. A comparison is useful precisely when its differences are explicit."},{"type":"paragraph","text":"The encounter with schist becomes richer when beauty and condition are read together. A broken edge does not invalidate the figure''s achievement; it helps explain what time and the material have allowed us to see. The sculptor''s work is present in the surviving relationships of surface, depth and form, while the catalogue reminds us that the object before us is neither untouched nor completely recoverable."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Gandhara","Material Culture"],"province":null,"district":null,"relatedDistrictIds":["khyber-pakhtunkhwa-haripur","punjab-rawalpindi"],"provinceRegionIds":["khyber-pakhtunkhwa","punjab"],"relatedHeritageIds":["unesco-139"],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Gandharan schist and the work of the sculptor","description":"Gandharan schist sculpture joins close carving to the possibilities and vulnerabilities of stone. Its material history is part of its artistic achievement.","primaryKeyword":"Gandhara schist sculpture","socialTitle":"Gandharan schist and the work of the sculptor","socialDescription":"Gandharan schist sculpture joins close carving to the possibilities and vulnerabilities of stone. Its material history is part of its artistic achievement."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Gandhara","url":"https://www.metmuseum.org/essays/gandhara","publisher":"The Metropolitan Museum of Art / Kurt Behrendt","accessDate":"2026-10-22"},{"title":"Seated Buddha,1895,1026.1","url":"https://www.britishmuseum.org/collection/object/A_1895-1026-1","publisher":"British Museum","accessDate":"2026-10-22"},{"title":"Stoneyards and Artists in Gandhara","url":"https://edizionicafoscari.unive.it/media/pdf/books/978-88-6969-577-3/978-88-6969-577-3-ch-13_M12UHle.pdf","publisher":"Edizioni Ca’ Foscari","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Explain material choice and carving evidence without attributing anonymous works to invented artists.","sortOrder":305}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-recognising-a-bodhisattva-through-attributes','recognising-a-bodhisattva-through-attributes','review','{"id":"story-recognising-a-bodhisattva-through-attributes","type":"story","slug":"recognising-a-bodhisattva-through-attributes","title":"Recognising a bodhisattva through attributes","summary":"Identifying a bodhisattva depends on combinations of attributes and context, especially when hands or other diagnostic details are missing.","body":[{"type":"paragraph","text":"A halo alone does not give a sculpture its name. Neither does jewellery, an elaborate hairstyle or a serene expression. Identifying a bodhisattva involves a combination of features, the relationship to other figures and the scholarship attached to a particular work. The process is most revealing when the catalogue explains the reasoning rather than offering only a confident title."},{"type":"paragraph","text":"The University of Missouri''s Museum of Art and Archaeology presents a schist Maitreya from Gandhara, numbered 84.66. Its explanation draws attention to the flask held in the figure''s left hand as an identifying attribute. The museum associates Maitreya with the future appearance of a Buddha. Here the named identity is connected to a specific surviving feature, not to a general impression of spirituality."},{"type":"heading","level":2,"text":"When the attribute is missing"},{"type":"paragraph","text":"The University of Sydney''s study of the so-called year 5 schist Buddha triad presents a more qualified case. It identifies the figure to the Buddha''s right as most likely Maitreya, discussing the hairstyle and a missing hand that probably held a water pot. The difference between a surviving vessel and a reconstructed one is crucial. Both can participate in interpretation, but not with identical evidential force."},{"type":"paragraph","text":"The same study discusses the figure on the opposite side through another attribute: a small Buddha represented in the headdress. This illustrates why a careful description should preserve the actual arrangement. “Two attendants” may be adequate for an initial orientation, but it loses the details through which a more specific identification is argued."},{"type":"paragraph","text":"A reader does not need to memorise an entire iconographic dictionary before looking. Start by noticing what is visibly present and then compare the catalogue''s explanation. If the interpretation relies on a damaged area, ask whether it is supported by a surviving trace, a close comparison or an older record. These are productive questions rather than challenges to the value of specialist knowledge."},{"type":"heading","level":2,"text":"An identification is not a universal rule"},{"type":"paragraph","text":"A single example should not become an automatic recognition test applied to every sculpture. Regional traditions, periods and changing scholarly interpretations can complicate a seemingly simple association. A feature that supports an identification in one context may be insufficient in another. The relevant comparison is not merely any image with a similar silhouette."},{"type":"paragraph","text":"Digital presentation can help by pairing an overview with a clearly identified detail. Cropping to the hand or headdress should leave readers a route back to the complete composition. Otherwise the attribute becomes detached from the very context that gives it significance."},{"type":"paragraph","text":"Recognising a bodhisattva is consequently less like solving a visual password than following an argument. A strong account distinguishes observation, comparison and conclusion. It can name Maitreya where the evidence supports that identification, retain “probably” where it matters, and leave an unresolved figure unnamed. This makes the encounter more precise without reducing the work to a checklist of symbols."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Gandhara","Material Culture"],"province":null,"district":null,"relatedDistrictIds":["khyber-pakhtunkhwa-peshawar"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-doam-4549"],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Recognising a bodhisattva through attributes","description":"Identifying a bodhisattva depends on combinations of attributes and context, especially when hands or other diagnostic details are missing.","primaryKeyword":"Gandhara bodhisattva attributes","socialTitle":"Recognising a bodhisattva through attributes","socialDescription":"Identifying a bodhisattva depends on combinations of attributes and context, especially when hands or other diagnostic details are missing."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Bodhisattva Maitreya","url":"https://maa.missouri.edu/education/museum-in-30-objects/bodhisattva-maitreya","publisher":"University of Missouri Museum of Art and Archaeology","accessDate":"2026-10-22"},{"title":"Schist Buddha Triad,year5","url":"https://gandhari-texts.sydney.edu.au/edition/schist-buddha-triad/","publisher":"University of Sydney / Gandhāran Buddhist Texts","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Teach cautious iconographic identification through catalogued objects.","sortOrder":306}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-donor-figures-at-the-feet-of-a-sculpture','donor-figures-at-the-feet-of-a-sculpture','review','{"id":"story-donor-figures-at-the-feet-of-a-sculpture","type":"story","slug":"donor-figures-at-the-feet-of-a-sculpture","title":"Donor figures at the feet of a sculpture","summary":"Small donor figures help make patronage visible, but a represented devotee is not automatically an identifiable historical portrait.","body":[{"type":"paragraph","text":"The principal figure usually receives the first and longest look. Smaller people near a sculpture''s base or sides can disappear into the background of a museum photograph. Looking again restores a different subject: the representation of giving, worship and participation around a sacred image. Their scale should not make these figures historically invisible."},{"type":"paragraph","text":"The Asian Art Museum catalogues a small schist work from Swat as Standing Buddha flanked by donors, object B60S266. The title identifies a relationship within the composition rather than naming the people represented. That is an important distinction. A donor figure can make the idea of patronage visible without supplying a recoverable individual biography."},{"type":"heading","level":2,"text":"Images and inscriptions do not say the same thing"},{"type":"paragraph","text":"Ashwini Lakshminarayanan''s study of female donors in Gandharan art compares epigraphic and visual evidence. It explains that inscriptions can preserve names and social relationships while images follow conventions of representation. A direct identification between a named woman in an inscription and a particular carved figure cannot simply be assumed. The two bodies of evidence illuminate participation differently."},{"type":"paragraph","text":"This cautions against an appealing shortcut. A richly dressed small figure is not automatically the king who funded a monastery; a pair of figures is not automatically a married couple. Those suggestions require support beyond modern expectations about how patrons ought to appear. A label can discuss a proposed identification while making clear why it remains provisional."},{"type":"paragraph","text":"An isolated head presents an even sharper problem. The University of Michigan Museum of Art describes its stucco head 1948/1.102 as an unidentified male figure, possibly a donor or devotee from a larger group. Its careful title retains the missing relationship. Detached from its original composition, the head cannot provide the same contextual clues as a figure still positioned beside a Buddha."},{"type":"heading","level":2,"text":"Looking down changes the story"},{"type":"paragraph","text":"For a public interpretation, a detail image of the smaller figures can be paired with the whole sculpture. This allows viewers to examine gestures and placement without losing the hierarchy of the composition. The caption should identify whether “donor” is the catalogue''s classification, a scholarly proposal or an interpretation being tested."},{"type":"paragraph","text":"This approach also makes room for people who are not rulers. Patronage is too easily reduced to a succession of famous kings, while the evidence for donation can involve different kinds of participants. A responsible account follows the available record rather than inserting unnamed ordinary people merely to make a story feel inclusive."},{"type":"paragraph","text":"The smaller figures therefore deserve attention in their own right, but not at the cost of fictional identities. They invite us to examine how participation was made visible and how memory was organised around an image. Sometimes the most accurate conclusion remains a relationship—someone represented in an act of devotion—rather than a name. That is still a meaningful presence, and one that a quick glance at the principal figure alone would miss."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Gandhara","Material Culture"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Donor figures at the feet of a sculpture","description":"Small donor figures help make patronage visible, but a represented devotee is not automatically an identifiable historical portrait.","primaryKeyword":"Gandhara donor figures","socialTitle":"Donor figures at the feet of a sculpture","socialDescription":"Small donor figures help make patronage visible, but a represented devotee is not automatically an identifiable historical portrait."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Standing Buddha flanked by donors","url":"https://searchcollection.asianart.org/objects/10778/standing-buddha-flanked-by-donors","publisher":"Asian Art Museum","accessDate":"2026-10-22"},{"title":"Towards investigating the representation of Gandhāran female donors","url":"https://orca.cardiff.ac.uk/id/eprint/167812/","publisher":"Arts Asiatiques / Ashwini Lakshminarayanan","accessDate":"2026-10-22"},{"title":"Head of an unidentified male figure","url":"https://umma.umich.edu/objects/head-of-an-unidentified-male-figure-possibly-a-donor-figure-or-a-devotee-in-a-buddhist-sculpture-group-1948-1-102/","publisher":"University of Michigan Museum of Art","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Examine how donors appear in a specific catalogued work rather than assert their identities.","sortOrder":307}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-narrative-reliefs-and-the-order-of-scenes','narrative-reliefs-and-the-order-of-scenes','review','{"id":"story-narrative-reliefs-and-the-order-of-scenes","type":"story","slug":"narrative-reliefs-and-the-order-of-scenes","title":"Narrative reliefs and the order of scenes","summary":"A narrative relief is not always a surviving strip of events in chronological order. Fragments, registers and architectural placement affect how it is read.","body":[{"type":"paragraph","text":"A carved narrative panel invites us to read, but stone does not provide the same instructions as a printed page. The starting point may be uncertain, figures can recur, and only part of a larger arrangement may survive. Reading a relief therefore means attending to its physical organisation as well as identifying the story represented."},{"type":"paragraph","text":"Penn Museum''s Gandharan stupa fragment 29-64-223 preserves three vertically arranged scenes. Its catalogue describes standing and seated devotional images above a representation of the Buddha''s passing away. It also identifies the fragment as part of a stupa''s stone facing. The object thus combines a surviving internal arrangement with a larger architectural setting that is no longer present around it."},{"type":"heading","level":2,"text":"Sequence is something to establish"},{"type":"paragraph","text":"The order in which a modern viewer notices the scenes is not automatically the order in which they were intended to be understood. Top-to-bottom, left-to-right and chronological readings should not be treated as interchangeable. A composition can juxtapose moments or different kinds of image without functioning like consecutive frames in a film."},{"type":"paragraph","text":"The Carlos Museum''s account of Megha making an offering to a Buddha of the past introduces another narrative scale. The scene concerns a previous-life story rather than simply another episode placed along a modern biography of the historical Buddha. An interpreter who treats every relief as part of one continuous lifetime can therefore misread the relationship between separate panels."},{"type":"paragraph","text":"What matters first is the identification supplied by the relevant catalogue and the features on which it rests. A repeated figure, a gesture or an attribute may help distinguish a moment, but a fragmentary scene should retain uncertainty when its identifying details are absent. Familiarity with a story does not entitle us to insert its missing conclusion into the surviving stone."},{"type":"heading","level":2,"text":"The architecture has a role"},{"type":"paragraph","text":"An isolated museum panel is usually encountered face-on at a convenient height. Its original position may have shaped a different encounter. Where the mounting or architectural association is documented, a diagram can help explain that difference. Where it is unknown, a complete digital reconstruction should not quietly assign the object a place simply because it fits the proposed sequence attractively."},{"type":"paragraph","text":"Comparisons are most useful when they identify what is being compared. Two reliefs may represent the same episode while arranging figures differently. Two similar formats may contain different stories. Their resemblance should lead to closer description, not to an assumption that one is an interchangeable illustration of the other."},{"type":"paragraph","text":"Narrative reliefs reward a patient rhythm of looking: the whole fragment, the separate scenes, the relationships between figures, and then the missing architectural context. A good interpretation helps viewers move through those scales. It can convey the force of visual storytelling while keeping the surviving evidence distinct from the longer story we bring to it. The gaps are part of the encounter, not blank spaces an editor is obliged to fill."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Gandhara","Material Culture"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Narrative reliefs and the order of scenes","description":"A narrative relief is not always a surviving strip of events in chronological order. Fragments, registers and architectural placement affect how it is read.","primaryKeyword":"Gandhara narrative reliefs","socialTitle":"Narrative reliefs and the order of scenes","socialDescription":"A narrative relief is not always a surviving strip of events in chronological order. Fragments, registers and architectural placement affect how it is read."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Stupa Fragment29-64-223","url":"https://www.penn.museum/collections/object/213789","publisher":"Penn Museum","accessDate":"2026-10-22"},{"title":"Megha Makes an Offering to a Buddha of the Past","url":"https://collections.carlos.emory.edu/objects/39040/megha-makes-an-offering-to-a-buddha-of-the-past","publisher":"Michael C. Carlos Museum, Emory University","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Explain how separated fragments complicate the reconstruction of visual stories.","sortOrder":308}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-a-reliquary-its-inscription-and-its-contents','a-reliquary-its-inscription-and-its-contents','review','{"id":"story-a-reliquary-its-inscription-and-its-contents","type":"story","slug":"a-reliquary-its-inscription-and-its-contents","title":"A reliquary, its inscription and its contents","summary":"An inscribed reliquary connects a physical container with a historical act of donation, but its text, dating and surviving contents must be distinguished.","body":[{"type":"paragraph","text":"A reliquary brings several kinds of evidence into a small space. There is the container itself, any inscription associated with it, the account of its recovery and whatever contents were documented. These layers can support one another, but they should not be collapsed. A text declaring the installation of relics is not the same thing as a modern record of everything found inside."},{"type":"paragraph","text":"The Metropolitan Museum''s current record for an inscribed schist reliquary from Bajaur identifies a donation by Indravarman. Its translated inscription describes the establishment of bodily relics of Shakyamuni and relates the act to merit and named family relationships. This is unusually direct evidence for how a donor represented the purpose of a gift."},{"type":"heading","level":2,"text":"The inscription as an historical statement"},{"type":"paragraph","text":"The wording gives the object a voice, but not an unlimited one. It records a claim made in a particular religious and social setting. An interpretation should identify that claim as part of the inscription rather than converting it into an independent scientific determination of the relics'' identity. Respect for the devotional meaning and precision about the evidence are compatible."},{"type":"paragraph","text":"The container''s material, dimensions and collection number answer different questions. They connect the published account to an individual object that can be examined and compared. A general photograph of a similar vessel would not be an adequate substitute when the argument depends on a specific inscription."},{"type":"heading","level":2,"text":"A date that needs its source"},{"type":"paragraph","text":"This example also illustrates why catalogue versions matter. The current online record gives 15–16 CE, while the museum''s older publication discusses an Indravarman reliquary with an earlier converted date and a different numbering arrangement among adjacent entries. These details should not be combined into one apparently seamless record. The discrepancy requires specialist reconciliation before a definitive chronology or identifier is repeated."},{"type":"paragraph","text":"For a reader, acknowledging that problem is more useful than concealing it. Ancient dates can depend on identifying an era as well as reading a number, and a collection record can change as research develops. A responsible article should state which record it follows and preserve the route to the alternative rather than treating an older printed source as automatically final."},{"type":"paragraph","text":"The same discipline applies to contents. If an excavation or collection history does not establish a particular surviving assemblage, an attractive group of beads or fragments must not be presented as belonging to this vessel. A photograph of an open reliquary can otherwise imply an association that the record has never documented."},{"type":"paragraph","text":"The object''s significance does not depend on resolving every uncertainty. Its inscription already connects donation, kinship and sacred purpose in a way that an uninscribed container cannot. Keeping that achievement distinct from unsettled dating and collection details allows the reliquary to remain both a religious object and a precise historical source, rather than a convenient illustration assembled from incompatible information."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Gandhara","Material Culture"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"A reliquary, its inscription and its contents","description":"An inscribed reliquary connects a physical container with a historical act of donation, but its text, dating and surviving contents must be distinguished.","primaryKeyword":"Gandhara reliquary inscriptions","socialTitle":"A reliquary, its inscription and its contents","socialDescription":"An inscribed reliquary connects a physical container with a historical act of donation, but its text, dating and surviving contents must be distinguished."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Inscribed Reliquary, Donated by King Indravarman","url":"https://www.metmuseum.org/art/collection/search/38111","publisher":"The Metropolitan Museum of Art","accessDate":"2026-10-22"},{"title":"The Art of Gandhara in The Metropolitan Museum of Art","url":"https://resources.metmuseum.org/resources/metpublications/pdf/The_Art_of_Gandhara_in_The_Metropolitan_Museum_of_Art.pdf","publisher":"The Metropolitan Museum of Art / Kurt Behrendt","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Current Met record38111 assigns1987.142.70a,b to Indravarman and15–16CE. Older Met book assigns1987.142.71a,b to Indravarman at5–6 CE and1987.142.70a,b to Ramaka. Draft explicitly distinguishes source versions; specialist reconciliation required before publication. Do not silently merge IDs or assert extant contents.","editorialReason":"Distinguish container, inscription and excavated context with catalogue-level sources.","sortOrder":309}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-coins-as-images-of-authority','coins-as-images-of-authority','review','{"id":"story-coins-as-images-of-authority","type":"story","slug":"coins-as-images-of-authority","title":"Coins as images of authority","summary":"Kushan coins present authority through figures, gestures and legends. Comparing individual types reveals more than assigning one religious image to an entire reign.","body":[{"type":"paragraph","text":"A coin can compress an argument about authority into a very small surface. A ruler''s clothing, a gesture towards an altar, a divine figure and a legend all contribute to its presentation. Looking at the two sides together is essential: one side does not necessarily repeat or simply explain the other."},{"type":"paragraph","text":"The Metropolitan Museum''s gold coin of Kanishka, numbered 99.35.3024, provides one specific example. Its published discussion describes the standing ruler on the obverse and a four-armed deity identified with Oesho or Shiva on the reverse. The composition should be understood as the imagery of this coin type, not as an exhaustive account of everything the ruler supported or believed."},{"type":"paragraph","text":"The British Museum''s copper coin 1922,0424.3587 offers a contrasting pairing. Its record identifies Kanishka making an offering on one side and Shakyamuni, with a raised hand, on the other. Comparing the two objects immediately complicates any account that assigns one religious image to all of Kanishka''s coinage."},{"type":"heading","level":2,"text":"Read the object before the reputation"},{"type":"paragraph","text":"A famous ruler often arrives with a ready-made historical story. That story can lead a viewer to see what is expected rather than what is actually present. An accurate description starts with the catalogued type and its surviving details. A deity familiar from one issue should not be imported into another because the coins share a ruler''s name."},{"type":"paragraph","text":"Legends require the same care. The language of an inscription, the script in which it is written and a modern translation are different pieces of information. A public article should use a verified reading rather than copying letters from a low-resolution image and treating the result as a new translation. Where a legend is incomplete, the missing part should not vanish from the explanation."},{"type":"heading","level":2,"text":"A circulating image is not a personal confession"},{"type":"paragraph","text":"Coin imagery presents authority publicly, but it does not provide unmediated access to a ruler''s private convictions. A claim about political intention needs a broader argument. Equally, the presence of several divine figures across a coinage should not be converted immediately into a modern slogan about tolerance or identity. The historical setting deserves more specific treatment."},{"type":"paragraph","text":"For display, a paired image of both sides is more useful than an enlarged portrait alone. The enlargement should include a scale or diameter so that viewers understand how compressed the design originally was. Keeping the metal, collection number and type together prevents two visually similar objects from being mistaken for the same specimen."},{"type":"paragraph","text":"The reward is a richer reading of the coin as designed communication. Authority is expressed through relationships—between ruler and deity, figure and text, material and circulation. Those relationships can be examined without claiming that one small object explains an entire reign. The coin becomes a precise witness to a particular public image, not a miniature substitute for political history."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Material Culture"],"province":null,"district":null,"relatedDistrictIds":["khyber-pakhtunkhwa-haripur","punjab-rawalpindi"],"provinceRegionIds":["khyber-pakhtunkhwa","punjab"],"relatedHeritageIds":["unesco-139"],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Coins as images of authority","description":"Kushan coins present authority through figures, gestures and legends. Comparing individual types reveals more than assigning one religious image to an entire reign.","primaryKeyword":"Gandhara coin iconography","socialTitle":"Coins as images of authority","socialDescription":"Kushan coins present authority through figures, gestures and legends. Comparing individual types reveals more than assigning one religious image to an entire reign."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Coin of Kanishka99.35.3024","url":"https://www.metmuseum.org/art/collection/search/39385","publisher":"The Metropolitan Museum of Art","accessDate":"2026-10-22"},{"title":"Coin1922,0424.3587","url":"https://www.britishmuseum.org/collection/object/C_1922-0424-3587","publisher":"British Museum","accessDate":"2026-10-22"},{"title":"The Art of Gandhara in The Metropolitan Museum of Art","url":"https://resources.metmuseum.org/resources/metpublications/pdf/The_Art_of_Gandhara_in_The_Metropolitan_Museum_of_Art.pdf","publisher":"The Metropolitan Museum of Art / Kurt Behrendt","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Focus on imagery and legends, not the separate archaeological dating article.","sortOrder":310}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-carved-sandstone-fragments-and-lost-buildings','carved-sandstone-fragments-and-lost-buildings','review','{"id":"story-carved-sandstone-fragments-and-lost-buildings","type":"story","slug":"carved-sandstone-fragments-and-lost-buildings","title":"Carved sandstone fragments and lost buildings","summary":"A carved stone fragment can preserve a decorative vocabulary without proving the form of a lost building. Archival context is essential to reconstruction.","body":[{"type":"paragraph","text":"A fragment of carved sandstone can be more visually persuasive than its evidence warrants. An elephant, a border or a curved edge encourages us to imagine the complete object, then the building around it. The first reconstruction may be plausible; the second can introduce an entire architectural history that the fragment has not established."},{"type":"paragraph","text":"A British Library record of an Archaeological Survey of India photograph offers a useful restraint. It describes a circular sandstone fragment from Taxila''s Bhir Mound, numbered 829, with elephants and other relief decoration. The catalogue tentatively suggests a wheel and explicitly notes that the photograph has no scale. Both qualifications belong in any interpretation that uses this archival image."},{"type":"heading","level":2,"text":"A fragment is not automatically architectural"},{"type":"paragraph","text":"The example matters precisely because a decorated stone object should not be assigned to a lost temple merely because that would make an attractive story. Before discussing architectural placement, one must establish whether the piece was architectural at all. The catalogue''s question mark is evidence of uncertainty, not an inconvenience to remove from a cleaner caption."},{"type":"paragraph","text":"If a fragment is securely identified as part of a building, additional questions follow. Was it recovered in position or found displaced? Is there a recorded joint, matching piece or excavation context? Does the proposed reconstruction explain its dimensions and orientation? Similar decoration elsewhere can suggest comparisons, but cannot alone supply all the missing walls."},{"type":"paragraph","text":"The Penn Museum''s Salt Range Temple Project demonstrates a different scale of research, combining the study of standing remains with archaeological investigation. Its account describes a developing architectural chronology rather than a single form repeated unchanged. This is the kind of wider framework within which individual fragments may become informative, provided their own contexts are secure."},{"type":"heading","level":2,"text":"Materials must remain specific"},{"type":"paragraph","text":"Not every carved stone monument in the region is sandstone. The Department of Archaeology and Museums describes the Amb temples as constructed from kankar blocks and records an original plastered treatment. Calling every weathered carved surface “sandstone” would flatten a real material distinction. The same caution applies when a photograph''s colour suggests a stone identification that the catalogue does not support."},{"type":"paragraph","text":"An effective digital presentation can keep three things separate: the surviving piece, a comparison and a proposed reconstruction. A reconstruction should show which portions are directly evidenced and which are supplied hypothetically. Making that difference legible is more informative than producing a seamless image whose confidence cannot be inspected."},{"type":"paragraph","text":"The fragment''s value lies not in its ability to generate the grandest missing building, but in the questions it can genuinely help answer. It may preserve a motif, a carving method, a material choice or a documented relationship to a larger structure. Keeping those contributions precise allows the lost architecture to remain a subject of research rather than turning it into an illustration drawn mainly from expectation."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Material Culture"],"province":null,"district":null,"relatedDistrictIds":["punjab-chakwal"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-9766"],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Carved sandstone fragments and lost buildings","description":"A carved stone fragment can preserve a decorative vocabulary without proving the form of a lost building. Archival context is essential to reconstruction.","primaryKeyword":"architectural fragments Pakistan","socialTitle":"Carved sandstone fragments and lost buildings","socialDescription":"A carved stone fragment can preserve a decorative vocabulary without proving the form of a lost building. Archival context is essential to reconstruction."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Taxila,Bhir Mound.829,sandstone fragment","url":"https://searcharchives.bl.uk/catalog/041-003163994","publisher":"British Library / Archaeological Survey of India photograph","accessDate":"2026-10-22"},{"title":"Salt Range Temple Project","url":"https://www.penn.museum/research/project.php?pid=14","publisher":"Penn Museum","accessDate":"2026-10-22"},{"title":"Three temple inside fort,Amb","url":"https://doam.gov.pk/public/sites/6590","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Show how fragments can establish craft vocabulary without recreating an entire vanished temple.","sortOrder":311}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-a-cenotaph-is-not-the-burial-itself','a-cenotaph-is-not-the-burial-itself','review','{"id":"story-a-cenotaph-is-not-the-burial-itself","type":"story","slug":"a-cenotaph-is-not-the-burial-itself","title":"A cenotaph is not the burial itself","summary":"A cenotaph commemorates a burial but should not be confused with the bodily remains or the complete arrangement of a tomb.","body":[{"type":"paragraph","text":"At a tomb, the decorated stone that draws a visitor''s attention may not be the burial itself. A cenotaph serves a commemorative purpose; the relationship between that marker and the actual interment must be understood through the arrangement of the particular monument. Calling every visible monument a sarcophagus can give a misleading impression of what it contains."},{"type":"paragraph","text":"The official account of the Taj Mahal offers a clearly documented comparison. It distinguishes the commemorative forms in the principal chamber from the actual graves at a lower level. This is evidence for that building''s arrangement, not a universal plan that can be imposed on every Mughal tomb in Pakistan. A comparison should explain a concept while preserving the identity of the place being described."},{"type":"heading","level":2,"text":"One word, several scales"},{"type":"paragraph","text":"In ordinary speech, “tomb” can refer to an entire complex, a building, a chamber or an individual grave. The flexibility is convenient until a description moves between these scales without warning. A visitor reading that an emperor lies “in the marble tomb” may be imagining a container where the writer means a memorial structure above or around the burial."},{"type":"paragraph","text":"The Walled City of Lahore Authority''s account of Nur Jahan''s tomb describes two cenotaphs on a marble platform in the central chamber, commemorating Nur Jahan and Ladli Begum. Naming the objects carefully allows their commemorative relationship to be discussed without inventing the contents of the visible stone forms. It also encourages attention to the room and platform as parts of an architectural composition."},{"type":"paragraph","text":"An accurate illustrated explanation can use a plan or section when a reliable survey is available. The drawing should distinguish recorded spaces from inaccessible or uncertain ones. A dramatic cutaway that invents a hidden chamber is worse than a simpler explanation that admits the limits of the documentation."},{"type":"heading","level":2,"text":"Decoration and presence"},{"type":"paragraph","text":"Calligraphy, stonework and placement can make a cenotaph a powerful focus of remembrance. Its commemorative character does not make it merely ornamental or diminish the respect due to the site. The distinction between marker and burial is an architectural clarification, not a judgement about the significance of either."},{"type":"paragraph","text":"For this reason, public interpretation should avoid sensational language about “false graves.” Although that phrase sometimes appears in descriptions, it can suggest deception where there is an established commemorative arrangement. Explaining the function directly is clearer: a visible memorial marks and honours the deceased, while the burial has its own documented location."},{"type":"paragraph","text":"The same precision benefits photographs. A caption should identify whether it shows a cenotaph, a chamber or the exterior of a mausoleum. These are not interchangeable views. Once the terms are clear, the visitor can appreciate how an individual memorial relates to the spaces around it—how stone, text, light and approach bring remembrance into an architectural form without confusing that form with the remains it honours."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Mughal","Material Culture"],"province":null,"district":null,"relatedDistrictIds":["punjab-lahore"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6479","major-doam-6470"],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"A cenotaph is not the burial itself","description":"A cenotaph commemorates a burial but should not be confused with the bodily remains or the complete arrangement of a tomb.","primaryKeyword":"cenotaph tomb difference","socialTitle":"A cenotaph is not the burial itself","socialDescription":"A cenotaph commemorates a burial but should not be confused with the bodily remains or the complete arrangement of a tomb."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"The Taj Interiors","url":"https://www.tajmahal.gov.in/the-taj-interiors.aspx","publisher":"Government of Uttar Pradesh, Taj Mahal official site","accessDate":"2026-10-22"},{"title":"Monuments: Shahdara Complex","url":"https://walledcitylahore.gop.pk/monuments/","publisher":"Walled City of Lahore Authority","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Clarify the relationship between commemorative object and burial chamber.","sortOrder":312}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-marble-inlay-as-a-material-assembly','marble-inlay-as-a-material-assembly','review','{"id":"story-marble-inlay-as-a-material-assembly","type":"story","slug":"marble-inlay-as-a-material-assembly","title":"Marble inlay as a material assembly","summary":"Jahangir’s tomb demonstrates how stone inlay creates a surface through carefully fitted materials, rather than through colour alone.","body":[{"type":"paragraph","text":"From a distance, the ornament of Jahangir''s tomb can appear as a continuous drawing across a coloured wall. Closer attention reveals a material assembly. Contrasting pieces of stone participate in the pattern; the design depends on their meeting accurately, not only on an artist''s ability to draw a convincing outline."},{"type":"paragraph","text":"Lok Virsa''s account of traditional architectural crafts discusses white marble set into the tomb''s red sandstone surfaces and identifies vessel and floral motifs among the decoration. The Department of Archaeology and Museums likewise records inlaid geometric and floral designs in the complex. These descriptions locate the craft in a documented monument rather than treating inlay as a floating example of “Mughal luxury.”"},{"type":"heading","level":2,"text":"The line is also a joint"},{"type":"paragraph","text":"In a painted design, a boundary may be a change of pigment. In stone inlay, it can also be the meeting of separately prepared materials. This gives close looking a practical dimension: the edge belongs both to the image and to the way the surface has been made. A small detail photograph can reveal that relationship more effectively than an uninterrupted view of the whole façade."},{"type":"paragraph","text":"The distinction also helps prevent several decorative techniques from being collapsed into one. Inlay, mosaic, carving and painting may contribute to the same building, but they do not describe identical operations. The Walled City of Lahore Authority''s account mentions different treatments across Jahangir''s tomb. A photograph of one surface should not become evidence for the technique of every other surface in the complex."},{"type":"paragraph","text":"For a public interpretation, it is useful to move between the motif and the architectural bay. At close range, the fitted pieces command attention; from farther away, repetition and placement give them a larger rhythm. Neither view is sufficient alone. A detail without its location can lose scale, while a distant view can conceal the work entirely."},{"type":"heading","level":2,"text":"A surviving surface has a history"},{"type":"paragraph","text":"Present appearance does not automatically distinguish original material from later repair. Claims about an individual panel''s date or intervention history should follow documentation rather than assumptions based on whether it looks clean, worn or skilfully made. Newer work can be accomplished, and older work can survive unevenly. Visual freshness is not a reliable dating method."},{"type":"paragraph","text":"Nor should a writer assign every coloured stone a prestigious mineral name without a trustworthy identification. The appeal of the surface is not increased by an unsupported list of gems. A precise account of what is documented leaves a firmer basis for appreciating the craft."},{"type":"paragraph","text":"Stone inlay at Jahangir''s tomb can therefore be read as both image and construction. Its beauty lies in the coordination of pieces into a larger field, and in the movement between intimate detail and architectural scale. Looking at the joints as well as the flowers makes the material intelligence of that achievement easier to see."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Material Culture"],"province":null,"district":null,"relatedDistrictIds":["punjab-lahore"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6479"],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Marble inlay as a material assembly","description":"Jahangir’s tomb demonstrates how stone inlay creates a surface through carefully fitted materials, rather than through colour alone.","primaryKeyword":"pietra dura Pakistan","socialTitle":"Marble inlay as a material assembly","socialDescription":"Jahangir’s tomb demonstrates how stone inlay creates a surface through carefully fitted materials, rather than through colour alone."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Traditional Architectural Crafts of Pakistan","url":"https://lokvirsa.org.pk/wp-content/uploads/2023/12/Traditional-architectural-crafts-of-pakistan.pdf","publisher":"Lok Virsa","accessDate":"2026-10-22"},{"title":"Jahangir’s Tomb and Compound","url":"https://doam.gov.pk/public/heritage-sites/603","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Monuments: Tomb of Jahangir","url":"https://walledcitylahore.gop.pk/monuments/","publisher":"Walled City of Lahore Authority","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Explain joining and colour through the documented tomb rather than a broad style survey.","sortOrder":313}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-one-glazed-tile-many-conservation-questions','one-glazed-tile-many-conservation-questions','review','{"id":"story-one-glazed-tile-many-conservation-questions","type":"story","slug":"one-glazed-tile-many-conservation-questions","title":"One glazed tile, many conservation questions","summary":"A glazed tile is part of a layered architectural system. Conservation begins by distinguishing surface loss, attachment problems and the surrounding building.","body":[{"type":"paragraph","text":"A patch of missing blue on a historic wall can look like a straightforward colour problem. It is not necessarily one. The glaze, the body beneath it, the material attaching the tile and the surrounding masonry are different parts of the system. Treating all damage as a blemish to be covered would miss the relationships that conservation needs to understand."},{"type":"paragraph","text":"Salman Muhammad''s documentation paper on Wazir Khan Mosque distinguishes several conditions, including glaze separating from its terracotta body and loss of bond between tile and mortar. Its photographs and damage mapping turn a general impression of deterioration into specific recorded observations. That distinction is central: a visible loss does not, by itself, diagnose its cause or identify an appropriate treatment."},{"type":"heading","level":2,"text":"A pattern made of pieces"},{"type":"paragraph","text":"A field account published by Tokyo University of Foreign Studies describes the mosque''s cut-tile mosaic, in which coloured pieces are shaped and assembled into a design. This is not equivalent to one square tile carrying a complete painted motif. Understanding the construction affects how a missing element is documented and how the whole decorative field is interpreted."},{"type":"paragraph","text":"The documentation paper records deterioration piece by piece using measured drawings and photographic techniques. For a visitor, this painstaking work can be less immediately dramatic than a restored façade. Yet it is what allows condition to be described consistently and compared over time. An attractive before-and-after photograph cannot supply the same information on its own."},{"type":"heading","level":2,"text":"The questions precede the intervention"},{"type":"paragraph","text":"Where is the loss located? Which layer has changed? Is the observation isolated or repeated across the wall? What do earlier records show? These questions help explain why conservation cannot be reduced to finding a product that makes a surface look complete. Their answers depend on specialist examination and the circumstances of the building."},{"type":"paragraph","text":"A public article should not turn this explanation into a cleaning recipe. Historical glazed surfaces can be vulnerable in ways a photograph does not reveal, and an apparently gentle intervention can still be inappropriate. The useful public role is to understand the process, respect barriers and report concerns through the site''s custodians—not to test a household treatment on a monument."},{"type":"paragraph","text":"The same restraint applies to interpretation after work has been completed. A restored panel should retain a record of the decisions made. If additions reproduce a missing design, the explanation should say how that design was established. Documentation allows future investigators to distinguish historical fabric from the history of its care."},{"type":"paragraph","text":"Seen this way, a single tile becomes a meeting point between craft, architecture and conservation knowledge. Its colour remains important, but no longer stands alone. The most convincing conservation story is not that a wall has been made new. It is that its material relationships have been investigated and treated with enough precision for both the surviving work and the record of intervention to remain intelligible."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Material Culture"],"province":null,"district":null,"relatedDistrictIds":["punjab-lahore"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6466"],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"One glazed tile, many conservation questions","description":"A glazed tile is part of a layered architectural system. Conservation begins by distinguishing surface loss, attachment problems and the surrounding building.","primaryKeyword":"historic glazed tile conservation","socialTitle":"One glazed tile, many conservation questions","socialDescription":"A glazed tile is part of a layered architectural system. Conservation begins by distinguishing surface loss, attachment problems and the surrounding building."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Documentation and Conservation of Wazir Khan Mosque,Lahore,Pakistan","url":"https://www.cipaheritagedocumentation.org/wp-content/uploads/2018/12/Salman-Documentation-and-conservation-of-Wazir-Khan-mosque-Lahore-Pakistan.pdf","publisher":"CIPA / Salman Muhammad, Aga Khan Cultural Service Pakistan","accessDate":"2026-10-22"},{"title":"Deciphering the Construction Date of a Mosque Hidden in Its Mosaic Tiles","url":"https://www.aa.tufs.ac.jp/en/news/detail/12067-2/","publisher":"Tokyo University of Foreign Studies, ILCAA","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Follow substrate, glaze and context while avoiding treatment advice for untrained readers.","sortOrder":314}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-carved-wooden-panels-after-their-removal','carved-wooden-panels-after-their-removal','review','{"id":"story-carved-wooden-panels-after-their-removal","type":"story","slug":"carved-wooden-panels-after-their-removal","title":"Carved wooden panels after their removal","summary":"Carved wood retains evidence of making after it leaves a building, but a museum setting can obscure its original orientation, use and relationships.","body":[{"type":"paragraph","text":"A carved wooden surface mounted vertically in a gallery can be read as a self-contained picture. That presentation may make the pattern wonderfully clear while concealing how the object originally sat, moved or joined something else. Before interpreting a “panel,” it is worth asking whether it was a door, a piece of furniture, an architectural fitting or a portable object with another use."},{"type":"paragraph","text":"Powerhouse Museum''s prayer board from Swat, numbered 2000/114/2, makes the issue concrete. Its catalogue describes a shaped wooden surface supported on narrow pieces that form legs. It also records carving around a plain centre. A photograph that emphasised only the decorated face could encourage a mistaken reading of the object as a wall panel rather than a form intended for a different orientation."},{"type":"heading","level":2,"text":"Position belongs to the object"},{"type":"paragraph","text":"The Museum With No Frontiers account of a Swat chest with a sliding door provides another useful comparison. Its carved front participates in a piece of furniture; the relationship between decoration and opening matters. A crop of the front alone may reveal a pattern but cannot explain the operation of the chest."},{"type":"paragraph","text":"These are not reasons to reject detail photographs. They are reasons to pair them with an overview and a precise identification. A close view can show the depth of a cut or the meeting of forms. The complete object can show what that detail belonged to. Where an architectural fragment survives alone, an original-location photograph or measured record can supply context that the fragment no longer carries visibly."},{"type":"paragraph","text":"The Directorate of Archaeology''s account of Swat Museum includes carved wood within its ethnographic displays. This places woodwork alongside other aspects of regional material culture rather than treating it as an isolated decorative vocabulary. It also reminds us that a local museum can connect objects with the landscapes and communities from which they came."},{"type":"heading","level":2,"text":"Removal creates another history"},{"type":"paragraph","text":"Once an object enters a collection, its acquisition and display become part of its record. They do not erase the earlier use, but neither should the earlier setting be invented to fill a gap. A dealer''s or donor''s statement, a documented building location and a stylistic attribution are different forms of evidence and should be labelled accordingly."},{"type":"paragraph","text":"Motifs require similar care. A rosette or arch-shaped field can be described accurately without assigning it a timeless religious meaning. If a specific interpretation depends on testimony or scholarship, that source should remain visible. A decorative resemblance is not sufficient proof of unchanged belief over centuries."},{"type":"paragraph","text":"Carved wood rewards attention to these practical relationships. The work exists not only as a pattern but as an object with edges, supports, joins and a direction of use. Restoring those questions to the display does not reduce its beauty. It makes that beauty part of an inhabited world again, even where the exact original setting can no longer be recovered."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Material Culture"],"province":null,"district":null,"relatedDistrictIds":["punjab-rawalpindi"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-7053","major-doam-9419"],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Carved wooden panels after their removal","description":"Carved wood retains evidence of making after it leaves a building, but a museum setting can obscure its original orientation, use and relationships.","primaryKeyword":"architectural woodwork provenance","socialTitle":"Carved wooden panels after their removal","socialDescription":"Carved wood retains evidence of making after it leaves a building, but a museum setting can obscure its original orientation, use and relationships."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Prayer board,2000/114/2","url":"https://collection.powerhouse.com.au/object/8145","publisher":"Powerhouse Museum","accessDate":"2026-10-22"},{"title":"Chest with sliding door","url":"https://islamicart.museumwnf.org/database_item.php?id=object%3BEPM%3Bit%3BMus22%3B6%3Ben","publisher":"Museum With No Frontiers / Museum of Civilisations","accessDate":"2026-10-22"},{"title":"Swat Museum","url":"https://kparchaeology.gkp.pk/swat-museum/","publisher":"Directorate General of Archaeology and Museums, Khyber Pakhtunkhwa","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Discuss displaced architectural objects and the importance of recording their original setting.","sortOrder":315}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-an-ajrak-textile-under-close-examination','an-ajrak-textile-under-close-examination','review','{"id":"story-an-ajrak-textile-under-close-examination","type":"story","slug":"an-ajrak-textile-under-close-examination","title":"An ajrak textile under close examination","summary":"Reading ajrak through its repeat, borders and printed surfaces reveals a designed textile rather than a free-floating decorative pattern.","body":[{"type":"paragraph","text":"Begin with the whole cloth. Ajrak''s effect is not contained in a single star, flower or geometric unit. It emerges from the relationship between a repeating field and the borders that contain it. A tightly cropped image may make an attractive background while removing precisely the structure that makes the textile worth examining."},{"type":"paragraph","text":"The Crafts Museum in New Delhi describes a central field of repeated block prints followed by multiple borders. Its presentation also discusses printing on both sides and the sequence of resist and mordant processes used in particular examples. These observations provide a way of looking, but the museum''s Indian examples should not be relabelled as individual Sindh-made textiles. Ajrak connects regions without making their documented objects interchangeable."},{"type":"heading","level":2,"text":"Repeat and edge"},{"type":"paragraph","text":"At a distance, repetition can appear effortless. Close inspection invites different questions: where does a unit begin, how does it meet the next, and how is the field resolved at the edge? These are compositional questions that can be asked without claiming to identify a printer''s workshop from a photograph alone."},{"type":"paragraph","text":"The Rajasthan government''s craft account likewise locates ajrak in a wider geography that includes Sindh, Kutch and Barmer. Its account of a gridded design reinforces the importance of the overall structure. Geography should remain specific when discussing a maker or a piece, while the broader craft relationship can be acknowledged openly."},{"type":"paragraph","text":"Koel''s description of ajrak foregrounds staged work in Sindh, including preparation, printing and exposure to water and sun. The point for close looking is that the cloth''s surface results from a sequence, not from one instant application of a finished picture. The exact process of an individual textile should still come from its maker or a reliable technical record."},{"type":"heading","level":2,"text":"Looking at two surfaces"},{"type":"paragraph","text":"Where a cloth is documented as double-sided, both faces deserve attention. One photograph cannot establish the relationship between them. A digital display can show the full textile, a border detail and a corresponding view of the reverse, provided those photographs actually belong to the same object. Such an arrangement explains more than a collection of unrelated beautiful crops."},{"type":"paragraph","text":"The same care is needed with material claims. A familiar palette does not establish which dyes were used, and an ajrak-inspired printed surface is not automatically evidence of a particular hand process. Describing appearance and identifying manufacture are separate tasks. A maker''s documented account can connect them; visual expectation cannot replace it."},{"type":"paragraph","text":"Ajrak remains compelling without an unsupported claim that every motif has survived unchanged from an ancient civilisation. Its repeat, edges and surfaces already reveal substantial design intelligence. To look closely is to see how a pattern becomes a wearable or usable cloth, and how the decisions that organise the whole remain present in its smallest printed relationships."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Sindh","Material Culture"],"province":"Sindh","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"An ajrak textile under close examination","description":"Reading ajrak through its repeat, borders and printed surfaces reveals a designed textile rather than a free-floating decorative pattern.","primaryKeyword":"ajrak textile structure","socialTitle":"An ajrak textile under close examination","socialDescription":"Reading ajrak through its repeat, borders and printed surfaces reveals a designed textile rather than a free-floating decorative pattern."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Ajrakh: Rhythm of Blues","url":"https://artsandculture.google.com/story/ajrakh-rhythm-of-blues-crafts-museum-delhi/WAWhhiXYIwIA8A","publisher":"Crafts Museum, New Delhi","accessDate":"2026-10-22"},{"title":"Ajrakh Printing","url":"https://handmadeinrajasthan.rajasthan.gov.in/content/industries/handmadeinrajasthandepartment/artandcraft/textilework/ajrakhprinting.html","publisher":"Government of Rajasthan","accessDate":"2026-10-22"},{"title":"Ajrak","url":"https://koel.com.pk/ajrak/","publisher":"Koel","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Analyse borders, repeat and process, distinct from the apprenticeship article.","sortOrder":316}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-ralli-quilts-and-the-evidence-of-stitching','ralli-quilts-and-the-evidence-of-stitching','review','{"id":"story-ralli-quilts-and-the-evidence-of-stitching","type":"story","slug":"ralli-quilts-and-the-evidence-of-stitching","title":"Ralli quilts and the evidence of stitching","summary":"A ralli quilt’s seams, layers and stitches preserve construction choices, while its record may retain only part of the maker’s story.","body":[{"type":"paragraph","text":"A quilt is often photographed as a field of colour, flattened into a design. The stitches ask us to look differently. They join materials and hold an object together; their arrangement can make construction visible alongside pattern. Ralli is therefore not simply an image on cloth, but a relationship between pieces, layers and the work of assembling them."},{"type":"paragraph","text":"The International Quilt Museum records a ralli, numbered 2016.012.0062, probably made in Achra Thar in Sindh between 1950 and 1970. Its maker is unidentified. The catalogue distinguishes hand piecing from hand appliqué and records cotton as the primary fibre. Those details describe how this object was made more precisely than a general label such as “traditional quilt.”"},{"type":"heading","level":2,"text":"Do not smooth out the record"},{"type":"paragraph","text":"The word “probably” attached to its place of making matters. It should not disappear when the object is adapted into a shorter article. Nor should an unidentified maker become an imaginary grandmother whose life supplies emotional colour to the story. The skill is present in the object even when the archive has failed to preserve a name."},{"type":"paragraph","text":"A ralli in RISD Museum''s collection offers a comparison from Kutch in India. Its label discusses small groups of coloured stitches that may represent contributors'' signatures. The qualification is essential: an interpretation of particular stitches is not a universal rule for recognising makers across every quilt. It is an invitation to investigate a feature of that piece."},{"type":"paragraph","text":"The National Gallery of Victoria''s record introduces another material distinction. Its late-twentieth-century rilli quilt from the Thar region is catalogued as cotton and polyester. This is a useful corrective to descriptions that assume all textiles within a tradition must use one supposedly original material. A living practice can include change without ceasing to deserve careful attention."},{"type":"heading","level":2,"text":"Seams as evidence"},{"type":"paragraph","text":"For a close examination, the boundary between pieces is as important as the motif. Which forms are pieced together, and which are applied over a surface? What does the record say about layers, edges or later intervention? These questions should follow the actual textile rather than an imagined standard method."},{"type":"paragraph","text":"A display can make this accessible through a full view and a properly credited detail. The reverse may also be informative when it has been photographed, but a viewer should not be encouraged to handle a fragile object simply to satisfy curiosity. The collection''s documentation and access arrangements remain the appropriate route."},{"type":"paragraph","text":"Ralli becomes more than an emblem of regional colour when its construction is allowed to speak. A seam preserves a decision; a catalogue may connect that decision to a place and period, or acknowledge that the connection is incomplete. Respecting both the textile and those limits gives the maker''s work greater substance than a picturesque biography invented to fill the silence."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Sindh","Material Culture"],"province":"Sindh","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Ralli quilts and the evidence of stitching","description":"A ralli quilt’s seams, layers and stitches preserve construction choices, while its record may retain only part of the maker’s story.","primaryKeyword":"ralli quilts material culture","socialTitle":"Ralli quilts and the evidence of stitching","socialDescription":"A ralli quilt’s seams, layers and stitches preserve construction choices, while its record may retain only part of the maker’s story."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Ralli,2016.012.0062","url":"https://www.internationalquiltmuseum.org/quilt/20160120062","publisher":"International Quilt Museum","accessDate":"2026-10-22"},{"title":"Quilt,Ralli,2010.62.7","url":"https://risdmuseum.org/art-design/collection/quilt-ralli-2010627","publisher":"RISD Museum","accessDate":"2026-10-22"},{"title":"Rilli quilt,2003.682","url":"https://www.ngv.vic.gov.au/explore/collection/work/74529/","publisher":"National Gallery of Victoria","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Commission an object-focused account of construction and use with maker attribution.","sortOrder":317}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-phulkari-stitch-cloth-and-regional-variation','phulkari-stitch-cloth-and-regional-variation','review','{"id":"story-phulkari-stitch-cloth-and-regional-variation","type":"story","slug":"phulkari-stitch-cloth-and-regional-variation","title":"Phulkari: stitch, cloth and regional variation","summary":"Phulkari belongs to a shared regional textile history. Specific objects show how stitch, cloth and density vary within the tradition.","body":[{"type":"paragraph","text":"Phulkari is often introduced through a translation of its name, but “flower work” does not prepare us for the full range of its surfaces. The relationship between stitch and ground cloth is more informative than the expectation that every piece must look like a garden. A close examination begins with the individual textile rather than an ideal pattern assigned to the whole tradition."},{"type":"paragraph","text":"The Victoria and Albert Museum describes phulkari in relation to the wider Punjab region, spanning parts of present-day India and Pakistan. Its account explains work in darning stitch from the reverse of a cotton ground, using silk thread for a lustrous effect. It also distinguishes densely embroidered bagh pieces. These are useful technical and regional anchors, not a claim that every surviving example is identical."},{"type":"paragraph","text":"One illustrated object is a skirt attributed to Bannu, dated about 1867 and numbered 05668(IS). The record identifies yellow silk embroidery on indigo-dyed cotton. The named place and approximate date make this a particular object rather than a generic illustration of “Punjabi dress.” Its attribution also reminds readers that the historical geography of craft is not neatly contained by a single present-day administrative boundary."},{"type":"heading","level":2,"text":"Cloth remains part of the design"},{"type":"paragraph","text":"Embroidery does not replace the ground entirely in every piece. Where the cloth remains visible, its colour participates in the design. Where stitching becomes dense, another relationship emerges between coverage, reflected light and the surviving ground. Comparing these effects helps a viewer see variation without ranking one object simply by how little unworked cloth can be seen."},{"type":"paragraph","text":"The reverse-side technique is also worth explaining without turning the article into a tutorial. The finished face can conceal the order of work. A documented reverse photograph or a clearly labelled modern demonstration may help make that labour intelligible, while keeping the historical textile protected from unnecessary handling."},{"type":"heading","level":2,"text":"Shared history, specific attribution"},{"type":"paragraph","text":"Recognising a cross-border regional tradition does not make provenance unimportant. A maker, workshop, district or family history should be retained when documented. The wider category provides a connection between objects; it should not erase their differences or transfer one community''s account of use to everyone else."},{"type":"paragraph","text":"Likewise, an approximate nineteenth-century date cannot establish an unchanged practice stretching indefinitely into the past. It establishes what that catalogue attributes to that object. A stronger history grows by connecting securely recorded examples and testimony, not by treating visual resemblance as a complete chronological bridge."},{"type":"paragraph","text":"Phulkari can therefore be approached through a sequence of close observations: the ground, the stitch, the density, the full garment and its recorded history. This way of looking keeps regional belonging and individual variation together. It also gives an unnamed maker a more substantial presence through demonstrable choices, without claiming to recover a personal story that the surviving record does not contain."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Punjab","Material Culture"],"province":"Punjab","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Phulkari: stitch, cloth and regional variation","description":"Phulkari belongs to a shared regional textile history. Specific objects show how stitch, cloth and density vary within the tradition.","primaryKeyword":"phulkari embroidery technique","socialTitle":"Phulkari: stitch, cloth and regional variation","socialDescription":"Phulkari belongs to a shared regional textile history. Specific objects show how stitch, cloth and density vary within the tradition."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Indian embroidery: Phulkari","url":"https://www.vam.ac.uk/articles/indian-embroidery","publisher":"Victoria and Albert Museum","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Explain a documented technique without restricting the shared tradition to one modern country.","sortOrder":318}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-embroidery-motifs-are-not-a-universal-code','embroidery-motifs-are-not-a-universal-code','review','{"id":"story-embroidery-motifs-are-not-a-universal-code","type":"story","slug":"embroidery-motifs-are-not-a-universal-code","title":"Embroidery motifs are not a universal code","summary":"A familiar embroidered shape does not carry one fixed meaning everywhere. Interpretation depends on a particular textile and the people connected with it.","body":[{"type":"paragraph","text":"A triangle can be easy to recognise and difficult to interpret. So can a flower, a mirror or a repeated cross. The desire to translate every embroidered form into a fixed meaning is understandable: a symbolic dictionary promises quick access to a textile''s story. But recognition of a shape is not the same thing as knowing what it meant to its maker or wearer."},{"type":"paragraph","text":"The Victoria and Albert Museum illustrates mirrorwork with a boy''s tunic from Sindh, numbered IS.18-1981, dated to the early twentieth century. Its discussion notes protective associations for mirrorwork among some communities. The limiting phrase matters. It does not establish that every mirror on every garment, including this particular tunic, had an identical purpose or interpretation."},{"type":"heading","level":2,"text":"Description before translation"},{"type":"paragraph","text":"A careful description can identify where reflective elements appear and how they relate to the embroidery. A statement about belief requires another connection: testimony, a documented community context or relevant scholarship. Leaving that connection visible makes the interpretation stronger. Without it, a familiar explanation may simply be repeated until it begins to look like evidence."},{"type":"paragraph","text":"The problem is not restricted to religious meanings. A museum might identify a group of stitches as a possible signature, as RISD Museum does for particular details on a Kutch ralli quilt. “Possible” preserves an interpretive question. Removing it would turn a suggestion attached to one object into a confident rule about how all makers marked their work."},{"type":"paragraph","text":"Designs can also be named without the name exhausting their significance. A maker''s vocabulary may identify a shape, a remembered source, a technical arrangement or a use. An English translation should not force all of these into one category called symbolism. Where a term comes from an interview, the speaker, setting and permission to share it matter."},{"type":"heading","level":2,"text":"Ask a better question"},{"type":"paragraph","text":"Instead of asking only “What does this motif mean?”, try “Who identifies it this way?” and “What is known about this textile''s use?” These questions make room for more than one account without making every interpretation equally well supported. They also prevent an editor''s appealing visual association from quietly becoming a community''s voice."},{"type":"paragraph","text":"A public display can distinguish a maker''s explanation from a curator''s comparison and an older collector''s note. The distinctions need not overwhelm the design. A short attribution and a clear source can preserve them while keeping the textile at the centre of attention."},{"type":"paragraph","text":"The result is not a pattern emptied of meaning. It is a pattern returned to relationships: maker, user, occasion and later interpretation. Some of those relationships may be documented closely; others may be lost. Respecting the difference allows embroidery to remain culturally rich without turning its motifs into a universal code that no individual textile or community has actually supplied."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Material Culture"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Embroidery motifs are not a universal code","description":"A familiar embroidered shape does not carry one fixed meaning everywhere. Interpretation depends on a particular textile and the people connected with it.","primaryKeyword":"Pakistan embroidery motifs","socialTitle":"Embroidery motifs are not a universal code","socialDescription":"A familiar embroidered shape does not carry one fixed meaning everywhere. Interpretation depends on a particular textile and the people connected with it."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Indian embroidery: Shisha","url":"https://www.vam.ac.uk/articles/indian-embroidery","publisher":"Victoria and Albert Museum","accessDate":"2026-10-22"},{"title":"Quilt,Ralli,2010.62.7","url":"https://risdmuseum.org/art-design/collection/quilt-ralli-2010627","publisher":"RISD Museum","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Investigate named examples and avoid assigning one symbolic meaning to every pattern.","sortOrder":319}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-silver-ornaments-and-the-stories-a-museum-label-omits','silver-ornaments-and-the-stories-a-museum-label-omits','review','{"id":"story-silver-ornaments-and-the-stories-a-museum-label-omits","type":"story","slug":"silver-ornaments-and-the-stories-a-museum-label-omits","title":"Silver ornaments and the stories a museum label omits","summary":"A silver ornament’s material and catalogue attribution do not recover its maker, wearer or complete ownership history. Those absences should remain visible.","body":[{"type":"paragraph","text":"A jewellery label can be exceptionally precise about size and almost silent about a life. It may record metal, technique, weight and a regional name while leaving the maker and wearer unidentified. That imbalance is not a reason to ignore the ornament. It is a reason to read the record as carefully as the object."},{"type":"paragraph","text":"Bard Graduate Center''s checklist for India: A Jewelry Spectrum includes a silver and enamel necklace attributed to Multan, numbered 288 in the exhibition. It gives the name tin patrian har and records dimensions and weight. It also identifies the lender associated with the exhibition. These details establish a documented object and its presentation, but they do not amount to a complete account of who made or wore it."},{"type":"heading","level":2,"text":"Different names identify different relationships"},{"type":"paragraph","text":"A collection or lender''s name is not a maker''s credit. A regional attribution is not automatically a findspot. A local object name is not necessarily a complete explanation of its social use. Keeping these distinctions clear prevents the catalogue from appearing to say more than it actually records."},{"type":"paragraph","text":"The Multan necklace is especially useful for resisting a generic phrase such as “tribal silver.” That label can compress geography, technique and social identity into a picturesque category. The recorded combination of silver and enamel offers a more concrete starting point. It directs attention to a particular material relationship rather than requiring an imagined wearer to make the piece interesting."},{"type":"paragraph","text":"An account of use would need additional evidence. A portrait, family history or maker''s testimony might support specific claims, but only if the connection to this object or a clearly defined practice can be established. It would be inappropriate to invent a bride, inheritance or protective purpose merely because such stories are often attached to jewellery."},{"type":"heading","level":2,"text":"What the missing biography means"},{"type":"paragraph","text":"Acknowledging an unknown maker does not mean the work was anonymous in its original setting. It means that the available record has not preserved or supplied the name. Those are very different claims. The first would describe a historical condition; the second accurately describes our present knowledge."},{"type":"paragraph","text":"The same principle applies to collecting. An exhibition checklist documents an appearance in an exhibition. Unless it supplies a fuller ownership history, the reader should not assume that every earlier transfer is known. Further research might connect the object to correspondence, acquisition records or earlier photographs, but those connections must be found rather than implied."},{"type":"paragraph","text":"A rewarding display can therefore combine close attention to material with an honest account of what remains absent. The ornament does not have to become a symbol for all women of a region or a complete illustration of a community. It is already a specific crafted object whose surviving record can be examined, supplemented and questioned. The most responsible story leaves room for the maker and wearer without replacing them with attractive fiction."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Material Culture"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Silver ornaments and the stories a museum label omits","description":"A silver ornament’s material and catalogue attribution do not recover its maker, wearer or complete ownership history. Those absences should remain visible.","primaryKeyword":"Pakistan silver jewellery provenance","socialTitle":"Silver ornaments and the stories a museum label omits","socialDescription":"A silver ornament’s material and catalogue attribution do not recover its maker, wearer or complete ownership history. Those absences should remain visible."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"India: A Jewelry Spectrum,exhibition checklist","url":"https://www.bgc.bard.edu/files/Checklist_-_India_A_Jewelry_Spectrum_-_1998.pdf","publisher":"Bard Graduate Center","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Require an identified collection object and separate maker, wearer and collector histories.","sortOrder":320}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-brass-and-copper-water-vessels-in-everyday-life','brass-and-copper-water-vessels-in-everyday-life','review','{"id":"story-brass-and-copper-water-vessels-in-everyday-life","type":"story","slug":"brass-and-copper-water-vessels-in-everyday-life","title":"Brass and copper water vessels in everyday life","summary":"A catalogued brass water vessel links shape and ornament to use, while reminding us that a refined museum object cannot represent every household.","body":[{"type":"paragraph","text":"A water vessel brings the history of objects close to the body. It is made to contain, lift or pour, and its shape invites us to imagine those movements. But the invitation should not turn a museum piece into an invented scene of everyday life. A refined vessel may illuminate a particular craft tradition without representing the possessions of every household around it."},{"type":"paragraph","text":"A catalogued example in the Victoria and Albert Museum, numbered IS.21-1889, is described as a cast and engraved brass water vessel, dated about 1580–1600 and attributed probably to Lahore. The published entry records a height of 12.3 centimetres. These details give the discussion a particular scale, material and qualified location, rather than an undifferentiated category of “old metal pots.”"},{"type":"heading","level":2,"text":"Material and operation"},{"type":"paragraph","text":"Brass and copper should not be treated as interchangeable names. Nor can a photograph''s warm colour establish an exact composition. The catalogue''s identification is the appropriate starting point; a more detailed claim would need a technical source. This matters when an article discusses material choices rather than merely using the vessel as decoration."},{"type":"paragraph","text":"Casting and engraving also describe different aspects of making. One concerns forming the object, the other working its surface. Noting both allows the decoration to be considered as part of an operational object, rather than a pattern floating separately from the vessel beneath it."},{"type":"paragraph","text":"The recorded dimensions counter another distortion. An enlarged online photograph can make a compact vessel appear monumental. Keeping a measurement or scale alongside the image restores the relationship to a hand and body without claiming to know the gestures of a particular historical owner."},{"type":"heading","level":2,"text":"Everyday use is not a complete provenance"},{"type":"paragraph","text":"The label “water vessel” identifies a functional category, but it does not document every occasion on which this example was used. A writer should distinguish that category from evidence of ownership, setting or ceremony. A decorated surface cannot alone decide whether an object served a domestic, courtly or other environment."},{"type":"paragraph","text":"The qualified attribution to Lahore deserves equal care. “Probably” expresses the catalogue''s level of certainty and should remain in a shortened account. Removing it can turn a scholarly attribution into an apparently documented workshop location. If a later record improves that identification, the article can be updated with the new evidence."},{"type":"paragraph","text":"Water vessels are most informative when these ordinary-seeming distinctions are preserved. They connect the practical demands of a container with decisions about form, material and ornament. Looking at one carefully can open questions about handling and craft without making it stand for an entire society''s daily routine. Its value lies in the precision of that encounter: a particular object, made in particular ways, whose known history deserves as much attention as the imagined life its familiar function invites."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Material Culture"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Brass and copper water vessels in everyday life","description":"A catalogued brass water vessel links shape and ornament to use, while reminding us that a refined museum object cannot represent every household.","primaryKeyword":"Pakistan metal water vessels","socialTitle":"Brass and copper water vessels in everyday life","socialDescription":"A catalogued brass water vessel links shape and ornament to use, while reminding us that a refined museum object cannot represent every household."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Water vessel,IS.21-1889","url":"https://aaeportal.com/images/57811/water-vessel","publisher":"A&AePortal / Victoria and Albert Museum","accessDate":"2026-10-22"},{"title":"Water vessel,O154755","url":"https://collections.vam.ac.uk/item/O154755/water-vessel-unknown/","publisher":"Victoria and Albert Museum","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"The A&AePortal indexed institutional catalogue entry supplied object details; direct reader and V&A legacy page did not load. Recheck current V&A catalogue before publication. Attribution remains probably Lahore. No unsupported exact alloy composition or household biography.","editorialReason":"Plan a material-and-use biography anchored in a catalogued example rather than decorative nostalgia.","sortOrder":321}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-pottery-from-hala-clay-glaze-and-workshop-identity','pottery-from-hala-clay-glaze-and-workshop-identity','review','{"id":"story-pottery-from-hala-clay-glaze-and-workshop-identity","type":"story","slug":"pottery-from-hala-clay-glaze-and-workshop-identity","title":"Pottery from Hala: clay, glaze and workshop identity","summary":"Hala pottery is best understood through documented production and individual workshop records, not through colour alone or an assumed timeless style.","body":[{"type":"paragraph","text":"Hala''s name often arrives before the pot. It signals a recognised centre of making, encouraging a viewer to identify an object through its colour or pattern. Yet a place-name is not a complete workshop record. The history becomes more precise when the potter, production setting, material and date are considered separately rather than folded into one timeless “Hala style.”"},{"type":"paragraph","text":"The Trade Development Authority of Pakistan lists Hala among the country''s pottery production clusters. Its report connects regional design identities with an industry in which small-scale production matters. This is evidence for a production landscape, not a catalogue of every workshop''s methods. It should not be used to claim that all makers follow an identical recipe or serve the same market."},{"type":"heading","level":2,"text":"Clay, surface and attribution"},{"type":"paragraph","text":"A vessel has a body as well as a decorated surface. The visible design may attract attention first, but the material identification and manufacturing description should come from a reliable record. A blue or turquoise surface alone cannot establish a particular clay, glaze composition or firing practice. Nor can it prove that the object was made in Hala rather than inspired by work associated with the town."},{"type":"paragraph","text":"Farah Deeba Khan''s university research includes photographs of a Hala pottery shop and decorative work. Such situated documentation offers a useful counterpoint to a finished object photographed against a neutral background. It reminds us to ask when the observation was made and which workshop or practice it actually records, rather than presenting an older field image as an account of every present-day maker."},{"type":"paragraph","text":"The Mohatta Palace Museum''s Tale of the Tile exhibition placed historical ceramic traditions alongside contemporary practice. That chronological approach is valuable for Hala too. A historical collection and a living production centre can inform one another without being treated as an unchanged craft surviving outside time."},{"type":"heading","level":2,"text":"Giving a workshop an identity"},{"type":"paragraph","text":"For a new acquisition, a useful record would include the maker''s preferred name, workshop location, date of purchase and the account of manufacture the maker is willing to share. A photograph of the completed pot can then be connected to a real source rather than an anonymous regional label. This is a proposed documentation approach, not a claim that those details survive for every older object."},{"type":"paragraph","text":"Where the record is incomplete, the gap should remain visible. A shop location may be a place of sale rather than production; a family attribution may require confirmation. These distinctions prevent a story about craft from becoming an advertisement with historical assumptions attached."},{"type":"paragraph","text":"Hala pottery deserves attention as work made by people responding to particular materials, uses and markets. Its regional identity becomes more substantial, not less, when individual differences are retained. The most rewarding account connects the beauty of a surface to documented making while resisting the temptation to explain a whole town through one attractive pot."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Sindh","Material Culture"],"province":"Sindh","district":"Matiari","relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Pottery from Hala: clay, glaze and workshop identity","description":"Hala pottery is best understood through documented production and individual workshop records, not through colour alone or an assumed timeless style.","primaryKeyword":"Hala pottery material culture","socialTitle":"Pottery from Hala: clay, glaze and workshop identity","socialDescription":"Hala pottery is best understood through documented production and individual workshop records, not through colour alone or an assumed timeless style."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Pottery of Pakistan","url":"https://tdap.gov.pk/wp-content/uploads/2023/01/Pottery2022.pdf","publisher":"Trade Development Authority of Pakistan","accessDate":"2026-10-22"},{"title":"Tale of the Tile: The Ceramic Traditions of Pakistan","url":"https://mohattapalacemuseum.org/public/exhibitions/tale-of-the-tile-the-ceramic-traditions-of-pakistan","publisher":"Mohatta Palace Museum","accessDate":"2026-10-22"},{"title":"Hala fieldwork photographs in doctoral thesis","url":"https://iris.unive.it/retrieve/9bf5798d-23ad-4eb8-b65b-ed9be96746ca/Tesi.KHAN%20farah%20Deeba.%20Matricolo%20955339%20ciclo%2022.pdf","publisher":"Ca’ Foscari University / Farah Deeba Khan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"TDAP and thesis full fetch returned403; indexed primary excerpts support only explicitly limited claims. Publication review should add a documented Hala workshop interview and specific catalogued historical pot before expanding technical recipes or lineage claims.","editorialReason":"Separate current workshop practice and historic collection objects through named sources.","sortOrder":322}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-clay-body-of-a-boreendo','the-clay-body-of-a-boreendo','review','{"id":"story-the-clay-body-of-a-boreendo","type":"story","slug":"the-clay-body-of-a-boreendo","title":"The clay body of a boreendo","summary":"The boreendo’s clay body is part of its musical operation. Shape, holes and handling connect making to the sound of an individual instrument.","body":[{"type":"paragraph","text":"A boreendo can fit into a small display case and still be badly represented there. Its decorated clay surface is only part of the object. The hollow body, openings and relationship to a player''s breath make it an instrument. Without that connection, it risks becoming a miniature pot whose musical function is reduced to one line of a label."},{"type":"paragraph","text":"UNESCO''s account of the boreendo or bhorindo describes a hollow clay form that is dried and fired, with sound holes and a mouthpiece whose handling affects the tone. It also notes that size matters and that additional holes have been introduced to extend musical possibilities. The account therefore presents a made and adaptable object, not a single frozen form."},{"type":"heading","level":2,"text":"A body that participates in sound"},{"type":"paragraph","text":"For close interpretation, the useful question is how the physical object relates to performance. A photograph can establish the arrangement of visible openings, but it cannot demonstrate the sound of an instrument on its own. A recording should identify the performer and the particular instrument rather than pairing any attractive clay form with an unrelated audio track."},{"type":"paragraph","text":"The National Crafts Museum in New Delhi catalogues a small Borrindo from Gujarat, accession 94/1/D/NHHM. Its material, dimensions and painted appearance offer a documented comparison from a neighbouring region. It should be introduced as that comparison, not used as if it were an instrument collected in Sindh. Related practices deserve accurate geography."},{"type":"paragraph","text":"Nor should a writer reconstruct an exact acoustic formula from a photograph. The number of visible holes is an observation; a claim about pitch range or tuning requires a suitable technical or performer-based source. A label can explain that body and openings matter without pretending that their full relationship has been measured for an unexamined example."},{"type":"heading","level":2,"text":"The maker and player need not disappear"},{"type":"paragraph","text":"A useful documentation project would connect the object to its maker''s account and a credited performance, with consent for both. It might record the instrument''s dimensions and describe any changes the maker identifies. These details would allow a future reader to distinguish an individual example from a general account of the tradition."},{"type":"paragraph","text":"The same care applies to decoration. Its visual contribution deserves attention, but an unfamiliar pattern should not be assigned a symbolic meaning without supporting testimony. Manufacturing knowledge, decorative work and performance may involve different participants whose contributions should be identified where the evidence allows."},{"type":"paragraph","text":"The boreendo''s appeal lies in the meeting of material and breath. Clay does not simply provide a container for music; its worked form participates in making the sound possible. Presenting that relationship brings the object closer to a living practice while keeping the surviving instrument, documented comparison and modern recording distinct. It becomes possible to appreciate the craftsmanship without inventing a technical certainty or a continuous ancient biography that no individual object establishes."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Sindh","Material Culture"],"province":"Sindh","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"The clay body of a boreendo","description":"The boreendo’s clay body is part of its musical operation. Shape, holes and handling connect making to the sound of an individual instrument.","primaryKeyword":"boreendo instrument material","socialTitle":"The clay body of a boreendo","socialDescription":"The boreendo’s clay body is part of its musical operation. Shape, holes and handling connect making to the sound of an individual instrument."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Boreendo,Bhorindo: melodies,knowledge and skills","url":"https://ich.unesco.org/en/USL/boreendo-bhorindo-ancient-dying-folk-musical-instrument-its-melodies-knowledge-and-skills-02328","publisher":"UNESCO Intangible Cultural Heritage","accessDate":"2026-10-22"},{"title":"Borrindo,94/1/D/NHHM","url":"https://nationalcraftsmuseum.nic.in/artifacts-detail/31719","publisher":"National Crafts Museum and Hastkala Academy","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Study manufacture and acoustic design separately from the safeguarding-policy article.","sortOrder":323}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-manuscript-bindings-as-evidence-of-use','manuscript-bindings-as-evidence-of-use','review','{"id":"story-manuscript-bindings-as-evidence-of-use","type":"story","slug":"manuscript-bindings-as-evidence-of-use","title":"Manuscript bindings as evidence of use","summary":"A manuscript binding protects a text but also carries a history of alteration, repair and separation. Its date need not be the date of the writing inside.","body":[{"type":"paragraph","text":"A manuscript is often introduced by the date of its text, as though every visible part was made at the same moment. The binding complicates that assumption. Covers can be replaced, components separated and protective structures added. A book''s present appearance may bring several periods of work into one object."},{"type":"paragraph","text":"The Aga Khan Museum''s upper cover and front doublure numbered AKM386 provide a documented example from Iran. The record describes a surviving portion of a Qur''an binding rather than a complete manuscript. Its interpretation distinguishes the outer cover from the interior lining and considers the missing components. This is a comparative example for understanding book structures, not a manuscript attributed to Pakistan."},{"type":"heading","level":2,"text":"Cover and text have different histories"},{"type":"paragraph","text":"The University of Birmingham offers an equally useful distinction. Its account states that the Birmingham Qur''an leaves have been conserved and placed in an Islamic-style binding for protection. The protective binding is therefore part of modern conservation history; its style should not be used to date the writing it now houses. An attractive exterior and an ancient text do not automatically share an origin."},{"type":"paragraph","text":"This principle applies when examining manuscripts in any collection. A catalogue may record the date of copying, an attribution for the binding and later repairs separately. Those distinctions should survive a short public description. Compressing them into a single date may make a label easier to read while removing the most important evidence about the book''s changing life."},{"type":"heading","level":2,"text":"Wear is not a complete reading history"},{"type":"paragraph","text":"A damaged corner or repaired joint can prompt questions about use, but it does not reveal exactly who handled the volume or why. A worn binding should not become proof of a beloved household book unless a provenance or other record supports the account. Physical traces and ownership history can inform one another without being interchangeable."},{"type":"paragraph","text":"Yasmeen R. Khan''s discussion of manuscript conservation at the Library of Congress emphasises documentation before treatment. This matters because intervention itself changes the evidence future readers will encounter. A record of the earlier structure and condition helps preserve knowledge even when conservation is necessary to protect access to the text."},{"type":"paragraph","text":"For visitors, photographs of both exterior and interior components can make these relationships legible, provided the volume is supported and handled under the collection''s procedures. There is no need to force a fragile binding open to obtain a dramatic image. A partial view with an accurate explanation is preferable to damage undertaken in the name of interpretation."},{"type":"paragraph","text":"The binding is consequently more than a beautiful wrapper. It is evidence of protection, presentation and the successive decisions that allowed a text to remain usable. Reading it alongside the manuscript, rather than assuming the two have one uncomplicated history, gives the book a fuller material biography while leaving undocumented users unnamed."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Manuscripts","Conservation","Material Culture"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Manuscript bindings as evidence of use","description":"A manuscript binding protects a text but also carries a history of alteration, repair and separation. Its date need not be the date of the writing inside.","primaryKeyword":"Pakistan manuscript bindings","socialTitle":"Manuscript bindings as evidence of use","socialDescription":"A manuscript binding protects a text but also carries a history of alteration, repair and separation. Its date need not be the date of the writing inside."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Upper cover and front doublure of a Qur’an binding,AKM386","url":"https://collections.agakhanmuseum.org/collection/artifact/upper-cover-and-front-doublure-of-a-qur-an-binding-akm386","publisher":"Aga Khan Museum","accessDate":"2026-10-22"},{"title":"Conservation and research: Birmingham Qur’an","url":"https://www.birmingham.ac.uk/facilities/cadbury/birmingham-quran-mingana-collection/birmingham-quran/research-and-conservation","publisher":"University of Birmingham","accessDate":"2026-10-22"},{"title":"Conservation Treatment of Islamic Manuscripts at the Library of Congress","url":"https://www.conservation-wiki.com/w/images/1/1d/Conservation_of_Islamic_Manuscripts_at_LoC.pdf","publisher":"Library of Congress / Yasmeen R. Khan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Require an identified manuscript and examine repair and handling rather than summarise its literary text.","sortOrder":324}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-paper-ink-and-the-survival-of-a-written-page','paper-ink-and-the-survival-of-a-written-page','review','{"id":"story-paper-ink-and-the-survival-of-a-written-page","type":"story","slug":"paper-ink-and-the-survival-of-a-written-page","title":"Paper, ink and the survival of a written page","summary":"The survival of a written page depends on its paper, writing materials and environment. Age alone does not explain its condition.","body":[{"type":"paragraph","text":"An old page can remain flexible while a much newer sheet becomes brittle. That contrast is not a paradox. A document''s condition reflects its materials and the circumstances in which it has been kept, not simply the number of years since someone wrote on it. The words may be the reason we value the page, but their survival depends on a physical support."},{"type":"paragraph","text":"The Library of Congress explains paper deterioration through the interaction of composition and environment. Its account discusses cellulose fibres, acidity, moisture and light, distinguishing different manufacturing histories rather than treating paper as one uniform material. This provides a useful starting point for understanding vulnerability, but not a diagnosis of an individual document from its colour alone."},{"type":"heading","level":2,"text":"The page and the writing"},{"type":"paragraph","text":"A written sheet combines more than one material. The paper and the marks on it may raise different conservation questions. A treatment that appears suitable for the support cannot be assumed safe for every ink, pigment, annotation or later addition. This is why public guidance should not turn a general explanation of deterioration into a household recipe for making an old document look clean."},{"type":"paragraph","text":"The National Archives'' guidance for paper-based records also treats handling and housing as part of preservation. It recognises that tears, fasteners, inserts and different formats can require different arrangements. The aim is not simply to give every document an identical folder, but to reduce avoidable damage while preserving the relationships that make the record understandable."},{"type":"heading","level":2,"text":"Evidence includes more than the main text"},{"type":"paragraph","text":"A marginal note, folded insert or earlier enclosure may help explain how a document was used or stored. Removing such material for a tidier photograph can break a connection that later research needs. If an enclosure requires replacement, its information should be recorded and the decision made with appropriate archival guidance. Tidiness is not the same thing as preservation."},{"type":"paragraph","text":"Digitisation offers another kind of access, but the image and the original answer different questions. A clear scan may make writing easier to consult while leaving thickness, texture and some structural features unavailable. The digital record should identify the original and any image adjustments rather than presenting itself as a complete substitute for the physical object."},{"type":"paragraph","text":"A family or institution facing a damaged page can begin by documenting what is known and seeking qualified advice, especially where handling is already causing loss. The purpose of this article is to explain the questions, not prescribe chemical treatment, flattening or repair. A precious record does not become safer because an online technique looks simple."},{"type":"paragraph","text":"Preserving a written page therefore means caring for a material object and its context together. The text remains central, but the support, additions and history of custody can also carry information. Understanding that relationship encourages care that protects evidence rather than merely improving the page''s appearance for the next photograph."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Material Culture"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Paper, ink and the survival of a written page","description":"The survival of a written page depends on its paper, writing materials and environment. Age alone does not explain its condition.","primaryKeyword":"manuscript paper ink conservation","socialTitle":"Paper, ink and the survival of a written page","socialDescription":"The survival of a written page depends on its paper, writing materials and environment. Age alone does not explain its condition."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"The Deterioration and Preservation of Paper","url":"https://www.loc.gov/preservation/care/deterioratebrochure.html","publisher":"Library of Congress","accessDate":"2026-10-22"},{"title":"Paper-Based Records","url":"https://www.archives.gov/preservation/holdings-maintenance/paper","publisher":"United States National Archives","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Explain material evidence and specialist care without prescribing home conservation techniques.","sortOrder":325}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-printed-risalo-as-a-designed-object','the-printed-risalo-as-a-designed-object','review','{"id":"story-the-printed-risalo-as-a-designed-object","type":"story","slug":"the-printed-risalo-as-a-designed-object","title":"The printed Risalo as a designed object","summary":"A printed Risalo is an edited and manufactured book. Its publication record helps distinguish an edition from the poetry’s wider life.","body":[{"type":"paragraph","text":"A printed Risalo is not simply poetry placed between covers. It is an edition: a particular selection and arrangement presented through a particular book. Its title page, publication statement and pagination can help readers understand that distinction before they begin interpreting a verse. The physical and editorial form deserves attention alongside the literary work."},{"type":"paragraph","text":"The Bavarian State Library holds a digitised 1866 edition edited by Ernest Trumpp and published by Brockhaus in Leipzig. The catalogue identifies the work as Shaha Jo Risalo and records its government-supported publication statement. The library''s identifier, bsb10251280, connects the bibliographic description to a particular digitised copy. It does not stand for every version of Shah Abdul Latif''s poetry."},{"type":"heading","level":2,"text":"A book is an editorial encounter"},{"type":"paragraph","text":"The distinction matters whenever an article cites “the Risalo” as though the phrase named one unchanging set of pages. A reader needs to know which edition is being used and whether the passage comes from an original-language text, a translation or commentary. These are related but different encounters with the work."},{"type":"paragraph","text":"The 1866 imprint also makes a network of production visible: a named editor, publisher and place of printing. Those facts can be stated without assuming that the edition is complete, definitive or identical to a contemporary version. Evaluation of its literary decisions requires comparison and specialist knowledge, not a judgement based solely on its early date."},{"type":"heading","level":2,"text":"Design shapes navigation"},{"type":"paragraph","text":"To study a printed book as an object, an editor can examine how headings, page numbers and divisions help readers move through it. That examination must be based on the actual copy. It should not be inferred from a catalogue entry that supplies only bibliographic data. A digital article can state the questions while leaving unverified visual details for a documented follow-up."},{"type":"paragraph","text":"The distinction between the scanned copy and the printed edition is equally useful. A scan sequence may include covers, blank leaves or other material outside the numbered text. Referring to an image number as though it were a printed page can make a citation difficult to verify. A precise reference identifies the edition, page or folio where present, and the digital location used to consult it."},{"type":"paragraph","text":"This is not merely a technical concern for librarians. It affects whether a reader can find a passage, compare an alternative reading or recognise that a modern quotation has passed through an editor or translator. The book''s organisation participates in how the poetry is encountered."},{"type":"paragraph","text":"Looking at the printed Risalo in this way does not reduce it to publishing machinery. It makes one part of its transmission visible. A specific volume carries choices and institutional relationships as well as words. Recording those relationships accurately allows admiration for the poetry to coexist with critical attention to the edition through which a particular reader has received it."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Sindh","Material Culture"],"province":"Sindh","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"The printed Risalo as a designed object","description":"A printed Risalo is an edited and manufactured book. Its publication record helps distinguish an edition from the poetry’s wider life.","primaryKeyword":"Shah jo Risalo print editions","socialTitle":"The printed Risalo as a designed object","socialDescription":"A printed Risalo is an edited and manufactured book. Its publication record helps distinguish an edition from the poetry’s wider life."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Shaha Jo Risalo,1866 edition,bsb10251280","url":"https://digitale-sammlungen.de/de/details/bsb10251280","publisher":"Bavarian State Library / Munich Digitisation Centre","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Institutional bibliographic record and indexed metadata verified. Page viewer unavailable in web reader; draft deliberately makes no unverified claims about typography or individual page layout. Before publication add visual examination of title page and text openings, and Sindhi literary-editor review.","editorialReason":"Read layout and publication history separately from interpretation of the poetry.","sortOrder":326}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-a-railway-ticket-as-an-archive-of-movement','a-railway-ticket-as-an-archive-of-movement','review','{"id":"story-a-railway-ticket-as-an-archive-of-movement","type":"story","slug":"a-railway-ticket-as-an-archive-of-movement","title":"A railway ticket as an archive of movement","summary":"Tickets and timetables record different aspects of railway movement. A document of a possible journey is not proof that a particular person travelled.","body":[{"type":"paragraph","text":"A railway ticket is small enough to survive unnoticed in a book or family envelope. Its printed fields can connect two places through a date, class and fare, while later marks may record another stage of its use. Yet the ticket is not a complete travel diary. It does not automatically tell us why someone went, whom they met or whether the intended journey was completed."},{"type":"paragraph","text":"The distinction becomes clearer when a ticket is read beside a timetable. The IRFCA historical archive identifies an 1891 North Western Railway timetable extract for Lahore, Quetta and Karachi, reproduced from William Watson''s A guide to Karachi. The document offers a framework of advertised movement. It is not evidence that a named traveller followed that framework on a particular day."},{"type":"heading","level":2,"text":"An offer of movement and an individual record"},{"type":"paragraph","text":"A timetable concerns scheduled services; a ticket concerns an entitlement or transaction. Their information can be combined only with care. The timetable must be relevant to the ticket''s period, and the station names and railway administration need to be checked rather than normalised silently to their present forms."},{"type":"paragraph","text":"Pakistan Railways'' current guidance asks passengers to check fields including the train number, journey date and seat or berth details. Those examples show how a ticket can organise a journey, but they should not be projected unchanged onto every historical ticket format. The content and method of issuing travel documents can change. A modern electronic confirmation and an older printed ticket are not identical archival objects."},{"type":"heading","level":2,"text":"Keep the small marks"},{"type":"paragraph","text":"When documenting a surviving family ticket, an overview of both sides and a transcription of legible information can preserve details that a decorative crop would lose. Any handwritten or stamped addition should be distinguished from the original print. A doubtful reading should remain doubtful, especially where a damaged digit might alter the date or fare."},{"type":"paragraph","text":"Personal information requires another decision. A family may wish to preserve the complete document privately while sharing a redacted image publicly. That choice should be made before publication, not after a readable address or identifier has entered a searchable archive. The object can still support a historical account without exposing every detail it carries."},{"type":"paragraph","text":"The most interesting interpretation often lies in connecting modest evidence. A ticket might be compared with a relevant timetable, a dated letter or a photograph, but each connection needs to be documented. A family recollection is valuable when recorded as recollection rather than silently promoted into proof of every stage of a journey."},{"type":"paragraph","text":"Railway ephemera thus brings movement into an archive at several scales: the network advertised to passengers, the transaction recorded for an individual and the memory preserved later. Keeping those scales distinct allows a small piece of paper to tell a meaningful story without asking it to carry a complete journey that survives only in our imagination."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Material Culture"],"province":null,"district":null,"relatedDistrictIds":["islamabad-islamabad"],"provinceRegionIds":["islamabad"],"relatedHeritageIds":["major-doam-6310"],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"A railway ticket as an archive of movement","description":"Tickets and timetables record different aspects of railway movement. A document of a possible journey is not proof that a particular person travelled.","primaryKeyword":"Pakistan railway ephemera","socialTitle":"A railway ticket as an archive of movement","socialDescription":"Tickets and timetables record different aspects of railway movement. A document of a possible journey is not proof that a particular person travelled."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"North Western Railway Timetables","url":"https://irfca.org/gallery/Heritage/timetables/nwrtt/?g2_highlightId=579331","publisher":"Indian Railways Fan Club Association,primary timetable scans","accessDate":"2026-10-22"},{"title":"Pakistan Railways: Frequently Asked Questions","url":"https://pakrail.gov.pk/Faq.aspx","publisher":"Pakistan Railways","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Specific1891 timetable extract identified in IRFCA archive, originating in William Watson A guide to Karachi; scan close-reading still required before adding route/timing claims. No passenger ticket provenance invented. Current railwayFAQ used only for field examples, not travel advice/prices.","editorialReason":"Require a catalogued ticket or timetable and connect its printed information to transport systems.","sortOrder":327}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-postcards-and-the-framing-of-a-historic-city','postcards-and-the-framing-of-a-historic-city','review','{"id":"story-postcards-and-the-framing-of-a-historic-city","type":"story","slug":"postcards-and-the-framing-of-a-historic-city","title":"Postcards and the framing of a historic city","summary":"A historic postcard presents a selected city view. Its publisher, date range and rights record matter as much as its nostalgic appeal.","body":[{"type":"paragraph","text":"A postcard does not offer a neutral window onto an entire city. It offers a view selected for reproduction and circulation. That selection can make a gate, street or monument stand for a place while leaving much of urban life outside the frame. The resulting image is valuable historical evidence precisely when its choices remain visible."},{"type":"paragraph","text":"The Newberry Library catalogues a postcard titled Lahore, Delhi Gate, published by Raphael Tuck and Sons. It assigns a printing range between 1903 and 1959 and places the card in the Leonard A. Lauder collection of the publisher''s postcards. This is a defined object and collection history, not an undated “old Lahore” image found without attribution."},{"type":"heading","level":2,"text":"There is more than one date"},{"type":"paragraph","text":"The catalogue''s broad printing range should not be narrowed to an exact year without further evidence. The date a postcard was printed may also differ from the date of its source image or the date it was sent. If a postmark survives, it adds another observation rather than automatically resolving every aspect of production."},{"type":"paragraph","text":"This distinction matters in before-and-after comparisons. A modern photograph and an old card may seem to show change clearly, but differences in viewpoint, reproduction or editing can complicate the comparison. A historical claim should follow the actual image and its documentation, not the emotional contrast between a picturesque past and a crowded present."},{"type":"heading","level":2,"text":"The caption is part of the object"},{"type":"paragraph","text":"A publisher''s title directs attention. It identifies a place and proposes what the viewer is looking at. Transcribing it accurately is useful, but its wording should not become the only description. An editor can retain the historical title while distinguishing it from current identification or later corrections."},{"type":"paragraph","text":"The reverse, where available, may offer information about circulation, publication or a sender''s use. It should be documented separately from the image side. A postcard that was sold but never posted has a different surviving record from one carrying a dated message. Neither should be given an invented traveller to make its story more vivid."},{"type":"paragraph","text":"Reproduction also requires care. The Newberry record includes a no-copyright statement for the United States and asks for an institutional credit and link. That statement should be read for its stated scope rather than converted automatically into a worldwide permission claim. A reference to the record is useful even when no image is reproduced."},{"type":"paragraph","text":"The postcard''s value lies in the conjunction of view and object: what was selected, how it was named, who published it and what survives of its circulation. Reading those layers can deepen our understanding of how Lahore was presented to distant audiences. It does not require treating a commercial city image as a complete portrait of the people who lived beyond its edges."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Material Culture"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Postcards and the framing of a historic city","description":"A historic postcard presents a selected city view. Its publisher, date range and rights record matter as much as its nostalgic appeal.","primaryKeyword":"Pakistan historical postcards","socialTitle":"Postcards and the framing of a historic city","socialDescription":"A historic postcard presents a selected city view. Its publisher, date range and rights record matter as much as its nostalgic appeal."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Lahore,Delhi Gate","url":"https://collections.newberry.org/archive/-2KXJ8Z8XCX68C.html","publisher":"Newberry Library","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"IdentifiedNewberry postcard with No Copyright—United States statement. This is not global production clearance; featuredImage remainsnull. Catalogue text verified, but image not visually inspected, so draft avoids claims about specific visible buildings/people/colours. Human visual review and jurisdiction-specific reproduction check required.","editorialReason":"Examine selection and viewpoint, with an identified rights-cleared example required before drafting.","sortOrder":328}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-family-photographs-as-historical-evidence','family-photographs-as-historical-evidence','review','{"id":"story-family-photographs-as-historical-evidence","type":"story","slug":"family-photographs-as-historical-evidence","title":"Family photographs as historical evidence","summary":"Family photographs become stronger historical sources when identifications, uncertainty and permission to share are recorded alongside the image.","body":[{"type":"paragraph","text":"A family photograph can seem fully understood while the people who recognise it are still present. Someone knows the courtyard, the relative standing at the edge and the occasion that brought everyone together. Once that knowledge is separated from the print, the image may retain its emotional force while losing much of its historical specificity."},{"type":"paragraph","text":"The first task is therefore not to invent a polished caption. It is to record what is known, who supplied the identification and how certain they are. “My aunt thinks this was taken after the move” preserves a different kind of evidence from a dated inscription on the reverse. Both may be valuable, but they should not be merged into an apparently exact date."},{"type":"heading","level":2,"text":"Keep the conversation attached"},{"type":"paragraph","text":"Oral History Association guidance emphasises informed participation and clarity about how recorded material will be used. Applied to a family photograph project, that means discussing whether an account is intended for private preservation, a community archive or public publication. Agreement to identify a relative in conversation is not automatically agreement to place the image and story on an unrestricted website."},{"type":"paragraph","text":"Multiple memories should not be forced into premature agreement. If two relatives identify a location differently, the record can retain both accounts and the reasons given. A future researcher may find another photograph or document that clarifies the issue. Deleting the disagreement now would remove part of the evidence needed to resolve it."},{"type":"heading","level":2,"text":"The print has its own record"},{"type":"paragraph","text":"The National Archives advises preserving information associated with photographic enclosures and avoiding attempts to detach photographs from albums or mounts without suitable guidance. The surrounding material can establish relationships that a cropped scan loses. An album sequence, handwritten note or studio imprint may matter even when it is not the most visually attractive part of the object."},{"type":"paragraph","text":"Its guidance also distinguishes access copies from originals and recommends seeking specialist help when handling is causing damage. This is particularly relevant to curled, torn or unstable photographs. A digitisation project should not sacrifice the original in order to obtain a perfectly flat image."},{"type":"paragraph","text":"For a public version, it may be appropriate to omit private addresses or information about living people while keeping a fuller record under agreed access conditions. The decision should be explicit. Redaction need not destroy the private archive, and private preservation need not require public exposure."},{"type":"paragraph","text":"Family photographs become historical evidence through these relationships, not simply through age. The image, the physical print, remembered identifications and permission to use them form a connected record. Preserving that connection allows future readers to distinguish what the camera shows from what later testimony explains. It also gives the family a meaningful role in deciding how an intimate record enters a wider account of place and time."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Material Culture"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Family photographs as historical evidence","description":"Family photographs become stronger historical sources when identifications, uncertainty and permission to share are recorded alongside the image.","primaryKeyword":"Pakistan family photographs archives","socialTitle":"Family photographs as historical evidence","socialDescription":"Family photographs become stronger historical sources when identifications, uncertainty and permission to share are recorded alongside the image."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Preserving Family Photos","url":"https://www.archives.gov/publications/prologue/2015/fall/handling-photos.html","publisher":"United States National Archives","accessDate":"2026-10-22"},{"title":"Photographs: holdings maintenance","url":"https://www.archives.gov/preservation/holdings-maintenance/photographs","publisher":"United States National Archives","accessDate":"2026-10-22"},{"title":"Oral History Best Practices","url":"https://oralhistory.org/best-practices/","publisher":"Oral History Association","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Discuss metadata, consent and memory without presenting an image caption as complete truth.","sortOrder":329}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-museum-labels-small-texts-with-large-consequences','museum-labels-small-texts-with-large-consequences','review','{"id":"story-museum-labels-small-texts-with-large-consequences","type":"story","slug":"museum-labels-small-texts-with-large-consequences","title":"Museum labels: small texts with large consequences","summary":"Museum labels condense research into small texts. Their qualifiers, dates and collection histories can profoundly change what visitors think an object proves.","body":[{"type":"paragraph","text":"A museum label can alter an object''s apparent history with one small word. “Probably” distinguishes an attribution from a demonstrated fact; “about” preserves uncertainty in a date; “unidentified” acknowledges that a name has not survived in the available record. Removing these words to make prose more confident can make the object say something its evidence does not support."},{"type":"paragraph","text":"The International Quilt Museum''s record for ralli 2016.012.0062 offers a simple example. It identifies an unknown maker and a probable place of manufacture in Achra Thar, Sindh. A shortened caption that confidently names the location while dropping the unidentified maker would shift the balance of the record. The place would appear more certain, while the human absence would become invisible."},{"type":"heading","level":2,"text":"A current record is not outside history"},{"type":"paragraph","text":"Labels and online catalogues also change. The Metropolitan Museum''s current Indravarman reliquary record gives a date that differs from its older Gandhara publication, which also arranges neighbouring collection identifiers differently. An editor encountering both should not quietly choose details from each to create one seamless description. The inconsistency is a research issue requiring reconciliation."},{"type":"paragraph","text":"This does not mean that every label is unreliable. It means that interpretation is part of an ongoing scholarly process. A useful public record can identify its sources and revision date so that readers understand which account they are consulting. Updating a label is most responsible when it preserves an accessible explanation of important changes."},{"type":"heading","level":2,"text":"The credit line answers a particular question"},{"type":"paragraph","text":"An acquisition credit may identify a donor or fund rather than the historical maker. It may record how an institution received an object without supplying every earlier owner. Readers should not be expected to know these distinctions instinctively. Clear wording can prevent a modern collection name from being mistaken for an artistic attribution or complete provenance."},{"type":"paragraph","text":"The same applies to geography. A place of manufacture, findspot, purchase location and broad cultural attribution are not interchangeable. A short label may need to select among them, but it should not conceal which relationship is being stated. “Acquired in Lahore” does not necessarily mean “made in Lahore.”"},{"type":"paragraph","text":"An effective label consequently balances brevity with a route to fuller information. A visitor can receive the essential identification and one meaningful interpretation, while a linked catalogue preserves qualifications, references and collection history. The longer record should support the concise text rather than contradict its certainty."},{"type":"paragraph","text":"The aim is not to turn every gallery into a debate conducted in tiny print. It is to keep the most consequential distinctions legible. Small words can protect large historical differences. A label that respects them helps visitors appreciate an object while understanding how its identity has been established—and where the work of understanding it is still continuing."}],"primaryCategoryId":"archive-category-objects-material-culture","categoryIds":["archive-category-objects-material-culture"],"tags":["Material Culture"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"objects-material","seo":{"title":"Museum labels: small texts with large consequences","description":"Museum labels condense research into small texts. Their qualifiers, dates and collection histories can profoundly change what visitors think an object proves.","primaryKeyword":"museum object labels Pakistan","socialTitle":"Museum labels: small texts with large consequences","socialDescription":"Museum labels condense research into small texts. Their qualifiers, dates and collection histories can profoundly change what visitors think an object proves."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Inscribed Reliquary,Donated by King Indravarman","url":"https://www.metmuseum.org/art/collection/search/38111","publisher":"The Metropolitan Museum of Art","accessDate":"2026-10-22"},{"title":"The Art of Gandhara in The Metropolitan Museum of Art","url":"https://resources.metmuseum.org/resources/metpublications/pdf/The_Art_of_Gandhara_in_The_Metropolitan_Museum_of_Art.pdf","publisher":"The Metropolitan Museum of Art / Kurt Behrendt","accessDate":"2026-10-22"},{"title":"Ralli,2016.012.0062","url":"https://www.internationalquiltmuseum.org/quilt/20160120062","publisher":"International Quilt Museum","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Catalogue discrepancies are discussed as editorial examples, not resolved attributions. Shared-source use limited to brief factual identification; human reconciliation needed for Indravarman record beforepublication.","editorialReason":"Show how attribution, date ranges and provenance shape public understanding through specific examples.","sortOrder":330}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-lahores-old-city-through-routes-rather-than-monuments','lahores-old-city-through-routes-rather-than-monuments','review','{"id":"story-lahores-old-city-through-routes-rather-than-monuments","type":"story","slug":"lahores-old-city-through-routes-rather-than-monuments","title":"Lahore’s old city through routes rather than monuments","summary":"Read old Lahore through the spaces between landmarks: approaches, markets, thresholds and the infrastructure that makes an inhabited city work.","body":[{"type":"paragraph","text":"A list of Lahore’s monuments can make the old city seem like a collection of separate destinations. A route changes the emphasis. The interval between a gate, a bathhouse and a mosque becomes part of the story: how people approach, where streets widen, and how a public building meets the neighbourhood outside it. Architecture is no longer only something viewed from the front."},{"type":"paragraph","text":"The Walled City of Lahore Authority presents the Royal Trail as a connection between Delhi Gate and Lahore Fort. Its interpretation brings Shahi Hammam, Wazir Khan Mosque, Sonehri Mosque and market spaces into the same account. That is useful not because every building belongs to one reign, but because the route makes different histories legible together. The itinerary is a contemporary interpretive device as well as an account of an older passage."},{"type":"heading","level":2,"text":"Thresholds rather than isolated façades"},{"type":"paragraph","text":"At a city gate, ask what changes between outside and inside: direction, enclosure, the width of passage and the visibility of the next landmark. At a courtyard entrance, compare the compression of the approach with the space beyond. These are observational questions, not a claim that present traffic or paving reproduces Mughal experience. The city has been altered repeatedly, and its current rhythms deserve attention in their own right."},{"type":"paragraph","text":"The Authority’s account locates Sonehri Mosque above street level on a raised platform in Kashmiri Bazaar. That relationship is especially revealing. Elevation can distinguish a religious space without removing it from commercial life. Looking at stairs, edges and the street beneath gives a different understanding from looking only at domes. Shops and paths are not simply obstacles to a cleaner photograph; they help explain the setting in which the monument is encountered."},{"type":"heading","level":2,"text":"The route below the paving"},{"type":"paragraph","text":"AKDN’s 2022 project report describes work along a 383-metre stretch from Delhi Gate to Chowk Purani Kotwali. The programme included utilities, sewerage, paving and street furniture alongside architectural conservation. Its stated sequence placed safety and drainage before decorative finishing. These details make an important distinction: improving the appearance of a street and sustaining a usable neighbourhood are related, but they are not the same task."},{"type":"paragraph","text":"The same report describes community involvement and training within the rehabilitation programme. Those are project-reported activities, not proof that every resident experienced the work identically. A fuller social history would add residents’ accounts, including disagreements and changing livelihoods. A heritage walk should leave room for such voices rather than turning inhabited lanes into a theatrical background."},{"type":"paragraph","text":"Read the trail in both directions. Returning along an approach can reveal a doorway or change in scale that the outward journey concealed. Leave entrances clear, ask before photographing people, and distinguish a public route from permission to enter a private building. Lahore’s old city becomes richer when the connections between its landmarks receive as much attention as the landmarks themselves."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Punjab","Regional History"],"province":"Punjab","district":"Lahore","relatedDistrictIds":["punjab-lahore"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6449","major-doam-6458","major-doam-6466"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Lahore’s old city through routes rather than monuments","description":"Read old Lahore through the spaces between landmarks: approaches, markets, thresholds and the infrastructure that makes an inhabited city work.","primaryKeyword":"Lahore walled city routes","socialTitle":"Lahore’s old city through routes rather than monuments","socialDescription":"Read old Lahore through the spaces between landmarks: approaches, markets, thresholds and the infrastructure that makes an inhabited city work."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"The Royal Trail","url":"https://artsandculture.google.com/story/the-royal-trail-walled-city-of-lahore-authority-wcla/bwWBgVXIrhEA8A?hl=en","publisher":"Walled City of Lahore Authority","accessDate":"2026-10-22"},{"title":"The Walled City of Lahore: Preserving heritage and catalysing renewal","url":"https://the.akdn/Dari/project/walled-city-lahore-preserving-heritage-and-catalysing-renewal","publisher":"Aga Khan Development Network","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Build a relational urban history distinct from individual building profiles.","sortOrder":331}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-chiniot-and-the-relationship-between-craft-and-patronage','chiniot-and-the-relationship-between-craft-and-patronage','review','{"id":"story-chiniot-and-the-relationship-between-craft-and-patronage","type":"story","slug":"chiniot-and-the-relationship-between-craft-and-patronage","title":"Chiniot and the relationship between craft and patronage","summary":"Chiniot’s Shahi Masjid and Gulzar Mahal reveal different relationships between commissioning, skilled work and the survival of makers’ names.","body":[{"type":"paragraph","text":"Patronage is often reduced to a name on a building: the ruler, merchant or official who paid for it. Chiniot offers a more demanding question. How did a commission become a structure through the work of designers, masons, carvers and painters? Two official inventory entries—the Shahi Masjid and Gulzar Mahal—preserve very different kinds of evidence for answering it."},{"type":"paragraph","text":"The Department of Archaeology and Museums describes Shahi Masjid as a brick mosque with three domes and a courtyard ablution tank. Stone appears selectively at entrances and in the bases of architectural supports. The record also notes traces of painted floral and geometric ornament inside the prayer chamber. Rather than treating the mosque as an undifferentiated decorative object, these details identify distinct tasks: laying masonry, shaping durable thresholds and preparing painted surfaces."},{"type":"heading","level":2,"text":"A commission divided among skills"},{"type":"paragraph","text":"Gulzar Mahal’s inventory is unusually specific about people. It credits architect Syed Hassan Shah and names Rahim Bakhsh and Elahi Bakhsh for woodcarving, Ahmad Din for brickwork, Niaz Ahmad Jalandari for stucco, and Jan Muhammad for frescoes. These attributions are reported by the catalogue; they should not be mistaken for independently examined contracts. Nevertheless, they offer a valuable starting point for restoring makers to an account usually dominated by a mansion’s owner."},{"type":"paragraph","text":"The distinction between those trades matters. A carved ceiling must be supported and fitted; painted ornament depends on a prepared ground; stucco negotiates the junction between structure and surface. The finished room conceals much of this sequencing. Looking for joints, changes of material and the edges of panels helps reveal collaboration without inventing the words or working conditions of the people involved."},{"type":"paragraph","text":"The record places the mansion’s completion in 1935 and connects its commission with Sheikh Omar, a businessman returning to Chiniot. Its account also contains family stories and dramatic explanations for abandonment. Those narratives need a different evidential footing from the surviving fabric. They are not necessary to appreciate the documented range of skills, and they should not become the main explanation of the building’s significance."},{"type":"heading","level":2,"text":"Survival changes the commission"},{"type":"paragraph","text":"The catalogue describes the loss of upper levels and later conservation associated with conversion to a research centre and library. That history complicates any photograph presented as the original whole. What survives is both a record of ambitious making and a record of subsequent removal, repair and reuse. A description should identify which of those histories it is discussing."},{"type":"paragraph","text":"Comparing the mosque and mansion does not establish an unbroken workshop genealogy. Similar materials can be used centuries apart by different networks of workers. What the comparison does reveal is how commissioning becomes visible at several scales: the organisation of a courtyard, the selection of a stone threshold, or the fitting of an ornamental panel. Chiniot’s architectural history is strongest when it makes room for those different scales—and for the named and unnamed people whose labour connected them."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Craft","Punjab","Regional History"],"province":"Punjab","district":"Chiniot","relatedDistrictIds":["punjab-chiniot"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6540","major-doam-10101"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Chiniot and the relationship between craft and patronage","description":"Chiniot’s Shahi Masjid and Gulzar Mahal reveal different relationships between commissioning, skilled work and the survival of makers’ names.","primaryKeyword":"Chiniot craft patronage history","socialTitle":"Chiniot and the relationship between craft and patronage","socialDescription":"Chiniot’s Shahi Masjid and Gulzar Mahal reveal different relationships between commissioning, skilled work and the survival of makers’ names."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Shahi Masjid, Chiniot","url":"https://doam.gov.pk/public/sites/6540","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Gulzar Mahal, Chiniot","url":"https://doam.gov.pk/public/sites/10101","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Connect documented commissions and techniques without assigning all local craft one origin.","sortOrder":332}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-bahawalpurs-princely-building-programme','bahawalpurs-princely-building-programme','review','{"id":"story-bahawalpurs-princely-building-programme","type":"story","slug":"bahawalpurs-princely-building-programme","title":"Bahawalpur’s princely building programme","summary":"Bahawalpur’s princely architecture connects palace display, religious patronage and public institutions, rather than a single style or building campaign.","body":[{"type":"paragraph","text":"Bahawalpur’s princely building history is not a sequence of interchangeable palaces. It includes spaces for residence, ceremony, worship, education and administration. Reading these together changes the question from which building looks most impressive to how a ruling household presented authority and supported institutions across a city."},{"type":"paragraph","text":"Noor Mahal is a useful starting point because its dates require care. The federal inventory associates the palace with 1872. The district government’s fuller account identifies that as the foundation year and gives 1875 for completion. These statements need not be contradictory if construction is understood as a process. A single date beneath a photograph can conceal design, building, occupation and later additions."},{"type":"heading","level":2,"text":"Display and adaptation"},{"type":"paragraph","text":"The district account describes classical elements in Noor Mahal’s columns, pediments and balustrades alongside domed forms. It also records a mosque added in 1906. The building therefore resists a simple choice between imported and local architecture. Its surfaces and spaces were assembled for a particular princely setting, and later work extended that setting. Architectural comparison is most useful when it identifies an element precisely instead of assigning the entire palace to one cultural category."},{"type":"paragraph","text":"The account of Noor Mahal’s subsequent institutional custody adds another layer. A former princely building can retain its name while its users, access arrangements and responsibilities change. This is why an architectural history should not double as a promise of current opening hours. Nor should the familiar story of a reluctant royal resident be used as an established explanation of how the whole palace functioned."},{"type":"heading","level":2,"text":"Beyond the palace gate"},{"type":"paragraph","text":"Jame Masjid Al-Sadiq provides a different kind of evidence. Its inventory attributes a renovation in 1935 to Sir Sadiq Muhammad Khan Abbasi. The same entry contains an inconsistent broad chronology field, so it cannot establish an early-medieval date for the present building. The defensible point here is narrower: princely patronage included the renewal of a religious institution, not only the construction of residences."},{"type":"paragraph","text":"The district’s city history also records educational and civic milestones, including Sadiq Egerton College in 1886 and Jamia Abbasia in 1925. These institutions widen the frame beyond palace façades. A building programme can shape a city through teaching, administration and service as well as courtly display. The survival of an institution and the survival of its earliest fabric remain separate questions, requiring building-specific investigation."},{"type":"heading","level":2,"text":"A programme, not one blueprint"},{"type":"paragraph","text":"It is tempting to arrange these places as a smooth story of benevolent progress. A better account leaves room for different patrons, political relationships and users, and asks who could enter each space. Ceremony, education and congregational worship organise access differently. Comparing their entrances and public edges can make those distinctions tangible without pretending that architecture alone reveals every social relationship."},{"type":"paragraph","text":"Bahawalpur’s princely legacy is therefore best read as a changing network. Noor Mahal gives one view of display; Al-Sadiq another of religious renewal; educational institutions another of public ambition. None can stand for the entire city, but together they make its architectural history more substantial than a gallery of royal interiors."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Punjab","Regional History"],"province":"Punjab","district":"Bahawalpur","relatedDistrictIds":["punjab-bahawalpur"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-9874","major-doam-10087"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Bahawalpur’s princely building programme","description":"Bahawalpur’s princely architecture connects palace display, religious patronage and public institutions, rather than a single style or building campaign.","primaryKeyword":"Bahawalpur princely architecture history","socialTitle":"Bahawalpur’s princely building programme","socialDescription":"Bahawalpur’s princely architecture connects palace display, religious patronage and public institutions, rather than a single style or building campaign."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Noor Mahal","url":"https://doam.gov.pk/public/sites/9874","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Jame Masjid Al-Sadiq","url":"https://doam.gov.pk/public/sites/10087","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Noor Mehal","url":"https://bahawalpur.punjab.gov.pk/node/71","publisher":"District Government Bahawalpur","accessDate":"2026-10-22"},{"title":"Our History","url":"https://bahawalpur.punjab.gov.pk/our-history","publisher":"District Government Bahawalpur","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. Al-Sadiq catalogue chronology field conflicts with its narrative; no early-medieval date or unsupported capacity repeated. Noor Mahal 1872 is treated as foundation/start, 1875 completion per district account. Family legends omitted.","editorialReason":"Compare civic, domestic and sacred patronage beyond one palace narrative.","sortOrder":333}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-cholistan-fort-network-and-its-uneven-survival','the-cholistan-fort-network-and-its-uneven-survival','review','{"id":"story-the-cholistan-fort-network-and-its-uneven-survival","type":"story","slug":"the-cholistan-fort-network-and-its-uneven-survival","title":"The Cholistan fort network and its uneven survival","summary":"Derawar is only one part of Cholistan’s fort landscape. Smaller and damaged structures change how the network’s history should be understood.","body":[{"type":"paragraph","text":"Derawar’s recognisable outline can overshadow the other forts of Cholistan. Yet a network cannot be understood through its most photogenic member alone. Smaller enclosures, damaged walls and partly lost plans are evidence too. They help test whether the forts shared functions, how their forms differed, and why some survive more visibly than others."},{"type":"paragraph","text":"Pakistan’s Tentative List submission, published by UNESCO in 2016, proposes Derawar and the desert forts as a related landscape. Tentative listing is not World Heritage inscription. The submission links the structures with movement, water and political control, while acknowledging that the network’s precise extent and character need further exploration. This is an argument for research and comparison, not a licence to draw a fully proven route between every fort."},{"type":"heading","level":2,"text":"Different buildings within the landscape"},{"type":"paragraph","text":"The federal inventory’s Marot entry, drawing on Mohammad Rafique Mughal’s work, describes a rectangular enclosure and surviving corner bastions. It also reports that much of the layout had disappeared by the documented assessment. That description is a historical condition record, not a fresh survey. Its value lies partly in the features it recorded before further change, and partly in the questions it leaves for present documentation."},{"type":"paragraph","text":"Mirgarh’s entry gives a different picture: a compact square fort, an outer earthen rampart and wells inside and outside the enclosure. The catalogue associates its construction with Nur Muhammad Khan at the end of the eighteenth century. Even without accepting every measurement as a current field observation, the contrast with Marot is useful. Size, enclosure and water provision need to be compared individually rather than assumed from Derawar’s form."},{"type":"heading","level":2,"text":"Visibility is not importance"},{"type":"paragraph","text":"A tall standing wall offers a strong photograph. A low mound may preserve a more complex sequence underground. The difference is one of visibility, not automatically one of historical value. A damaged fort can still help establish building phases, access arrangements or the relationship between an enclosure and nearby water infrastructure. Removing loose material to make it more legible would destroy precisely the evidence needed to answer those questions."},{"type":"paragraph","text":"The Tentative List account presents continued occupation as one reason for Derawar’s comparatively strong survival. That explanation should not be generalised to every site. Different materials, repair histories and local circumstances can produce very different results. Nor should the apparent absence of a wall on a visitor photograph be treated as proof that a feature never existed."},{"type":"heading","level":2,"text":"Reading the network responsibly"},{"type":"paragraph","text":"An effective comparison begins with modest, consistent observations: the shape of the enclosure, the position of entrances, evidence for rebuilding and the relationship to documented wells. It then distinguishes measured features from proposed connections. The resulting map will have gaps, but those gaps are more useful than an elegant line that claims certainty it does not possess."},{"type":"paragraph","text":"Cholistan’s forts belong together without becoming identical. Derawar can introduce the landscape; it cannot replace it. Bringing Marot, Mirgarh and other recorded structures into the account shifts attention from a single monumental silhouette to the uneven survival of an entire historical system."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Punjab","Regional History"],"province":"Punjab","district":null,"relatedDistrictIds":["punjab-bahawalpur","punjab-bahawalnagar","punjab-rahim-yar-khan"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6959","major-doam-6999","major-doam-7002","major-doam-6978"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"The Cholistan fort network and its uneven survival","description":"Derawar is only one part of Cholistan’s fort landscape. Smaller and damaged structures change how the network’s history should be understood.","primaryKeyword":"Cholistan forts history","socialTitle":"The Cholistan fort network and its uneven survival","socialDescription":"Derawar is only one part of Cholistan’s fort landscape. Smaller and damaged structures change how the network’s history should be understood."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Derawar and the Desert Forts of Cholistan","url":"https://whc.unesco.org/en/tentativelists/6108/","publisher":"UNESCO World Heritage Centre / Government of Pakistan","accessDate":"2026-10-22"},{"title":"Marot Fort","url":"https://doam.gov.pk/public/sites/6999","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Mirgarh Fort","url":"https://doam.gov.pk/public/sites/7002","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Distinguish documented network relationships from a single continuous defensive line.","sortOrder":334}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-multans-many-building-histories','multans-many-building-histories','review','{"id":"story-multans-many-building-histories","type":"story","slug":"multans-many-building-histories","title":"Multan’s many building histories","summary":"Multan’s monumental tomb, tiled shrine and municipal clock tower reveal histories that cannot be reduced to a single architectural identity.","body":[{"type":"paragraph","text":"Multan is frequently introduced through its shrines, but even its religious architecture does not follow one formula. A comparison between Shah Rukn-i-Alam and Shah Yusuf Gardezi immediately reveals different approaches to mass, surface and enclosure. Adding the municipal clock tower makes the city’s changing institutional history visible as well. These are not three illustrations of one timeless style."},{"type":"paragraph","text":"The Department of Archaeology and Museums records Shah Rukn-i-Alam’s tomb as an octagonal structure articulated with buttresses, brickwork, tile and timber. The arrangement directs attention to the relationship between construction and ornament. Horizontal bands do more than colour a surface: they help a viewer read the mass in stages. The building’s scale and repeated angles create a very different encounter from a small rectangular shrine."},{"type":"heading","level":2,"text":"Two ways of making a sacred exterior"},{"type":"paragraph","text":"The official catalogue describes Shah Yusuf Gardezi’s tomb as a single-storey, flat-roofed rectangle with relatively unbroken walls and extensive coloured tile facing. Here, the surface becomes particularly important. A comparison should not rank one structure above the other by size. It should ask how each establishes an exterior, marks an entrance and distinguishes a sacred interior from its surroundings."},{"type":"paragraph","text":"Neither description permits every visible tile to be dated to the first construction. Repairs, replacements and later embellishment require their own evidence. A saint’s lifetime, the foundation of a shrine and the age of its present fabric are different historical questions. Keeping them separate makes a building history more informative, not less respectful of religious memory."},{"type":"heading","level":2,"text":"Municipal authority enters the picture"},{"type":"paragraph","text":"Multan’s Ghanta Ghar introduces another institutional language. The inventory dates the municipal complex to 1884–88 and places it beside the old fort area. It records the names Ripon Hall and Northbrook Tower, followed by Jinnah Hall after independence. These names are evidence of changing public commemoration as well as a way of identifying the building."},{"type":"paragraph","text":"A clock tower makes time visible in the street. A municipal hall places administration within an architectural setting. Their conjunction invites a different reading from that of a tomb: not only what the façade resembles, but how government represented itself to people moving through the city. This is interpretation of the building type, not proof of how every resident understood it."},{"type":"paragraph","text":"The catalogue also recounts reuse proposals and periods of disuse, but those observations belong to the dates of its sources. They should not be turned into an assertion about today’s museum provision. A historic building can remain an important landmark even while its institutional programme changes or remains unsettled."},{"type":"heading","level":2,"text":"A city with several architectural histories"},{"type":"paragraph","text":"The three buildings offer a compact way to resist a single-style portrait of Multan. Compare a buttressed octagon, a tile-clad rectangle and a civic tower. Then compare the kinds of records each needs: conservation evidence, religious histories, municipal archives and accounts from users. The city becomes more legible when those sources are allowed to differ. Its architectural richness lies in relationships between such histories, not in making them all tell the same story."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Punjab","Regional History"],"province":"Punjab","district":"Multan","relatedDistrictIds":["punjab-multan"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6431","major-doam-6428","major-doam-10385"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Multan’s many building histories","description":"Multan’s monumental tomb, tiled shrine and municipal clock tower reveal histories that cannot be reduced to a single architectural identity.","primaryKeyword":"Multan architectural history","socialTitle":"Multan’s many building histories","socialDescription":"Multan’s monumental tomb, tiled shrine and municipal clock tower reveal histories that cannot be reduced to a single architectural identity."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Tomb of Shah Rukhn-I-Alam","url":"https://doam.gov.pk/public/sites/6431","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Tomb of Shah Yusuf Gardezi","url":"https://doam.gov.pk/public/sites/6428","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Ghanta Ghar Multan","url":"https://doam.gov.pk/public/sites/10385","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. Yusuf Gardezi record close-read in official catalogue snapshot after individual web page timed out. Broad period fields not used to date every visible surface. Ghanta Ghar condition/museum claims in source stop at2019; not presented as current.","editorialReason":"Place sacred and civic architecture in a layered city rather than one saint-centred chronology.","sortOrder":335}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-rawalpindis-merchant-neighbourhoods-and-transport-links','rawalpindis-merchant-neighbourhoods-and-transport-links','review','{"id":"story-rawalpindis-merchant-neighbourhoods-and-transport-links","type":"story","slug":"rawalpindis-merchant-neighbourhoods-and-transport-links","title":"Rawalpindi’s merchant neighbourhoods and transport links","summary":"Rawalpindi’s domestic courtyards and transport infrastructure suggest an urban history larger than either a merchant mansion or a railway landmark alone.","body":[{"type":"paragraph","text":"A mansion and a railway station preserve different scales of urban life. One organises entry into a household; the other gathers movement across a wider territory. Rawalpindi’s history becomes more interesting when these scales are considered together, without assuming that every grand house was financed by railway commerce or that a transport line explains the whole city."},{"type":"paragraph","text":"The federal inventory describes Sujan Singh’s haveli through its entrance sequence: an ornate door, entrance rooms, a portico and an interior courtyard. Rooms and halls occupy different sides, while narrow stairs connect levels. These details suggest a way to read domestic architecture through controlled movement. The significance of the house is not exhausted by the richness of its front elevation."},{"type":"heading","level":2,"text":"The household within a changing neighbourhood"},{"type":"paragraph","text":"The entry draws on a 2014 condition assessment and describes a late-nineteenth-century building once associated with gardens. That historical setting matters. A house’s original relationship to open ground may differ from the dense urban context encountered later. Changes around a building can alter light, views and approaches without changing its name. A present-day street photograph cannot, on its own, reconstruct the earlier property boundary."},{"type":"paragraph","text":"Such a mansion is also an uneven source. It makes wealth and spatial organisation visible more readily than it makes domestic labour visible. Kitchens, stairs and service approaches may help formulate questions, but they cannot supply unnamed workers’ biographies. Reading a merchant neighbourhood responsibly means seeking commercial records and family or community histories alongside architectural description."},{"type":"paragraph","text":"The Urban Unit’s regional tourism report treats Rawalpindi Railway Station as a late-nineteenth-century transport landmark linking the city with a larger network. That connection provides context, not a complete explanation of urban change. To demonstrate how a particular business depended on rail, one would need records of goods, firms or journeys rather than the simple presence of both a station and a prosperous house."},{"type":"heading","level":2,"text":"A district is not a single town"},{"type":"paragraph","text":"Khem Singh Bedi’s haveli at Kallar Syedan offers a useful regional comparison. Its catalogue records courtyards, verandas, projecting windows and painted surfaces. But it is not a second stop in Rawalpindi’s old-city street system merely because an older inventory groups it under Rawalpindi District. Administrative labels can conceal considerable geographical distance and different settlement histories."},{"type":"paragraph","text":"Comparing the two houses can reveal different arrangements of rooms and display. It should not collapse their patrons, communities or settings into a generic description of a Sikh mansion. Nor should an older statement that paintings were well preserved be treated as a current condition report or permission to enter."},{"type":"paragraph","text":"Rawalpindi’s built history is therefore best approached as a set of relationships to investigate: house and street, neighbourhood and market, city and transport network. Begin with what each source actually records, then ask how the pieces connect. The result is less tidy than a single story of railway-driven prosperity, but much closer to the complexity of an inhabited city."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Punjab","Regional History"],"province":"Punjab","district":"Rawalpindi","relatedDistrictIds":["punjab-rawalpindi"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-9419","major-doam-7053"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Rawalpindi’s merchant neighbourhoods and transport links","description":"Rawalpindi’s domestic courtyards and transport infrastructure suggest an urban history larger than either a merchant mansion or a railway landmark alone.","primaryKeyword":"Rawalpindi merchant history","socialTitle":"Rawalpindi’s merchant neighbourhoods and transport links","socialDescription":"Rawalpindi’s domestic courtyards and transport infrastructure suggest an urban history larger than either a merchant mansion or a railway landmark alone."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Haveli Sujan Singh","url":"https://doam.gov.pk/public/sites/9419","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Khem Singh Bedi Haveli","url":"https://doam.gov.pk/public/sites/7053","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Rawalpindi Regional Development Plan: Tourism Sector Report","url":"https://urbanunit.gov.pk/Download/publications/Files/20/2024/tourism.pdf","publisher":"The Urban Unit","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. Urban Unit railway context verified from indexed official report passage; no exact railway opening date claimed. Khem Singh Bedi haveli is regional comparison at Kallar Syedan, not placed in Rawalpindi old-city street. Older condition descriptions not current access promises.","editorialReason":"Investigate urban commercial connections using buildings and archival evidence.","sortOrder":336}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-salt-range-as-a-corridor-of-different-periods','the-salt-range-as-a-corridor-of-different-periods','review','{"id":"story-the-salt-range-as-a-corridor-of-different-periods","type":"story","slug":"the-salt-range-as-a-corridor-of-different-periods","title":"The Salt Range as a corridor of different periods","summary":"The Salt Range’s temples reward comparison across form and time. A corridor is a framework for questions, not proof that every site belongs to one phase.","body":[{"type":"paragraph","text":"A regional map can make the Salt Range’s temples look like a unified group. Their proximity invites comparison, but it does not make them contemporary or architecturally identical. The most useful question is how a regional tradition accommodated different forms over time—and how confidently those differences can be dated."},{"type":"paragraph","text":"In his 1996 preliminary study for Penn Museum, architectural historian Michael W. Meister examined temples in the Salt Range and along the Indus. He argued against treating the whole group simply as an extension of Kashmiri architecture. His discussion of Malot was particularly important: a building with conspicuous affinities to Kashmir need not define every other temple in the region."},{"type":"heading","level":2,"text":"Compare a detail, not only a silhouette"},{"type":"paragraph","text":"Meister’s analysis draws attention to small representations of shrines on temple walls. These are architecture depicting architecture. Their towers, niches and roof forms can be compared with the larger structures that carry them. A small carved feature may therefore preserve evidence for architectural choices that a damaged superstructure no longer reveals directly."},{"type":"paragraph","text":"This is a useful lesson for looking. Begin with a bounded feature—a doorway, a cornice or a shrine model—and describe its shape before assigning it a period. A curved outline and a stepped outline are not interchangeable. Equally, a resemblance is the beginning of an argument, not proof that the same workshop, patron or community produced both objects."},{"type":"paragraph","text":"The official Malot inventory describes recessed faces, columns and trefoil arches, and reconstructs the lost roof cautiously. Its historical attribution differs from the framework developed in Meister’s later discussion. Presenting both sources as though they supplied one exact date would erase a real interpretive problem. The visible fabric, an older catalogue and a scholarly stylistic sequence are different kinds of evidence."},{"type":"heading","level":2,"text":"The limits of a corridor"},{"type":"paragraph","text":"A corridor is a helpful way to think about connections, but it should not become a conveyor belt carrying a single style in one direction. Materials, patrons and builders can move through networks while producing locally distinctive buildings. Similarities may indicate contact, shared conventions or later imitation; distinguishing those possibilities requires more than the line joining two map markers."},{"type":"paragraph","text":"Meister explicitly presented much of his chronology as a developing argument that further archaeological work could refine. That qualification belongs in the story. A date based mainly on architectural comparison has a different evidential status from an inscription or a securely excavated deposit. Neither should be silently substituted for the other."},{"type":"paragraph","text":"The Salt Range rewards a layered itinerary of attention rather than a race through monuments. Notice what survives, what is reconstructed in a drawing and what a source only proposes. Keep the temple’s setting in view without treating nearby remains as automatically part of the same foundation. Such distinctions do not diminish the landscape’s coherence. They allow its coherence to emerge from specific relationships rather than from a single broad label imposed in advance."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Punjab","Regional History"],"province":"Punjab","district":null,"relatedDistrictIds":["punjab-chakwal","punjab-jhelum"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6535","major-doam-6750","major-doam-8267"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"The Salt Range as a corridor of different periods","description":"The Salt Range’s temples reward comparison across form and time. A corridor is a framework for questions, not proof that every site belongs to one phase.","primaryKeyword":"Salt Range cultural history","socialTitle":"The Salt Range as a corridor of different periods","socialDescription":"The Salt Range’s temples reward comparison across form and time. A corridor is a framework for questions, not proof that every site belongs to one phase."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Temples Along the Indus","url":"https://www.penn.museum/sites/expedition/temples-along-the-indus/","publisher":"Michael W. Meister / Penn Museum","accessDate":"2026-10-22"},{"title":"Malot Temple","url":"https://doam.gov.pk/public/sites/6535","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. Meister1996 is preliminary stylistic argument; catalogue1987 differs on Malot attribution. No precise dynasty/date harmonised. Web transcription contains OCR errors, so no quotations or fine chronological dependence. Approximately170 words source-derived from Meister,65 from DOAM; remainder original comparison/method.","editorialReason":"Connect sites across terrain without making them all contemporaries.","sortOrder":337}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-gujranwala-before-and-after-the-sikh-court','gujranwala-before-and-after-the-sikh-court','review','{"id":"story-gujranwala-before-and-after-the-sikh-court","type":"story","slug":"gujranwala-before-and-after-the-sikh-court","title":"Gujranwala before and after the Sikh court","summary":"Gujranwala’s haveli, dynastic memorial and Jain shrine tell related but distinct stories of authority, commemoration and urban memory.","body":[{"type":"paragraph","text":"Gujranwala is closely associated with Ranjit Singh, but the city’s surviving architecture should not be reduced to an illustrated royal biography. A residence, a memorial to his father and a later Jain shrine preserve different relationships between a community and its past. Reading them separately also prevents similar architectural forms from producing mistaken identities."},{"type":"paragraph","text":"The Department of Archaeology and Museums catalogues a haveli as Ranjit Singh’s birthplace. Its description records a formal entrance front, a large reception space and a sequence of courtyards. Those features help explain how a substantial household organised approach and access. The attribution of a particular room as a birthplace is a narrower commemorative claim, not something the room’s architecture can independently prove."},{"type":"heading","level":2,"text":"Residence and remembrance"},{"type":"paragraph","text":"A residence accommodates changing daily uses. A memorial selects a life or event for public remembrance. Mahan Singh’s samadhi belongs to the second category. The official entry describes an octagonal structure with a domed upper chamber and painted interiors, and connects its commission with Ranjit Singh’s patronage. The building therefore tells us about remembrance after Mahan Singh’s life, not simply about the period in which he governed."},{"type":"paragraph","text":"The source’s chronological details are not entirely consistent, so an exact death date is not necessary to the present comparison. More securely, its architectural description identifies a symmetrical composition, projecting eaves and arched openings. These features offer a basis for comparison with other buildings without requiring a claim that one community exclusively owned a visual language."},{"type":"paragraph","text":"The record also contains condition observations inherited from earlier documentation. They explain why a surviving fragment of painting matters, but they are not a current survey. A damaged interior is not permission to enter, touch or retrieve loose material. The relationship between a memorial and neighbouring occupation deserves documentation rather than a picturesque description of neglect."},{"type":"heading","level":2,"text":"A Jain shrine is not another royal samadhi"},{"type":"paragraph","text":"Atmaramji Shrine commemorates the Jain teacher Acharya Vijayanand Suri. The catalogue places its construction around the turn of the twentieth century and notes formal similarities with nearby memorial architecture. It also cautions against an identification with Ranjit Singh’s grandfather that arose from those similarities. Here, naming is not a minor matter: a wrong label can erase the community and individual actually commemorated."},{"type":"paragraph","text":"The comparison provides a practical lesson. An octagonal chamber or dome can travel across different religious and patronage settings. Form alone cannot establish dedication. Inscriptions, institutional histories and community knowledge need to be read alongside architectural resemblance. Shared craftsmanship and shared identity are not equivalent claims."},{"type":"paragraph","text":"Together, these three places make a more complex Gujranwala visible. The haveli frames domestic authority; Mahan Singh’s samadhi frames dynastic memory; Atmaramji Shrine frames a Jain community’s commemoration. Their proximity creates opportunities for comparison, not reasons to merge their stories. The city’s heritage becomes clearer when the distinctions are maintained and the connections are explained with equal care."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Punjab","Regional History"],"province":"Punjab","district":"Gujranwala","relatedDistrictIds":["punjab-gujranwala"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-10111","major-doam-10110","major-doam-10109"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Gujranwala before and after the Sikh court","description":"Gujranwala’s haveli, dynastic memorial and Jain shrine tell related but distinct stories of authority, commemoration and urban memory.","primaryKeyword":"Gujranwala Sikh heritage history","socialTitle":"Gujranwala before and after the Sikh court","socialDescription":"Gujranwala’s haveli, dynastic memorial and Jain shrine tell related but distinct stories of authority, commemoration and urban memory."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Ranjit Singh Birthplace","url":"https://doam.gov.pk/public/sites/10111","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Mahan Singh Samadhi","url":"https://doam.gov.pk/public/sites/10110","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Atmaramji Shrine","url":"https://doam.gov.pk/public/sites/10109","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft.10111 and10109 close-read in official catalogue snapshot after livepage timeouts. Mahan Singh source internally conflicts on death/reign dates; dates omitted. Individual birthroom attribution qualified; no imagined servants/interiors copied. Atmaramji identification not overridden by visual resemblance.","editorialReason":"Separate political biography from urban and religious architectural change.","sortOrder":338}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-bhera-and-the-memory-of-a-river-town','bhera-and-the-memory-of-a-river-town','review','{"id":"story-bhera-and-the-memory-of-a-river-town","type":"story","slug":"bhera-and-the-memory-of-a-river-town","title":"Bhera and the memory of a river town","summary":"Bhera’s river setting, altered gates and repeatedly rebuilt mosque show why a town’s age cannot be read from a single origin story.","body":[{"type":"paragraph","text":"Bhera’s history is often compressed into a claim about exceptional antiquity. A more revealing starting point is its position beside the Jhelum and the different kinds of movement associated with it. Rivers, roads, gates and markets do not all preserve the same chronology. Their relationship can explain a town without requiring every visible building to belong to its earliest remembered phase."},{"type":"paragraph","text":"The federal inventory places Bhera on the river’s left bank and describes routes associated with salt traffic branching towards Lahore and Multan. It also repeats an identification with the capital of Sophytus, a contemporary of Alexander. The first is a geographical and route-history proposition; the second is a much more demanding ancient identification. It should not be treated as established merely because it appears beside a modern place name in a catalogue."},{"type":"heading","level":2,"text":"Gates that remember rebuilding"},{"type":"paragraph","text":"The same record describes an eight-gated walled town associated with Sher Shah Suri and notes substantial nineteenth-century reconstruction of gateways. That combination matters. A gate can preserve the memory and location of an older approach while containing later fabric. Calling it old does not answer which part is old, when it was repaired or how its surrounding street changed."},{"type":"paragraph","text":"Rather than seeking a completely untouched town, look for differences between the passage, its façade and the buildings that now meet it. A rebuilt arch may retain a route even where an earlier wall has disappeared. Conversely, an impressive façade does not prove the survival of a complete defensive system. These are questions to investigate through plans and dated photographs, not conclusions available from appearance alone."},{"type":"heading","level":2,"text":"A mosque with more than one date"},{"type":"paragraph","text":"Jame Masjid’s inventory associates its foundation with Sher Shah and reports a 1541 date on the entrance. It separately records rebuilding under Qazi Ahmed-ud-din Bugvi in 1858 and repair under Qazi Zahoor Ahmed Bugvi in 1926. The account also preserves the name of mason Muhammad Asif. These details turn a simple foundation story into a history of continued investment and skilled work."},{"type":"paragraph","text":"The present building therefore cannot be described responsibly as an unchanged sixteenth-century object. Its domes, halls, painted plaster and institutional spaces need to be understood through their individual phases. The association with an early patron remains meaningful, but it is not a date stamp applied to every wall. Later rebuilding is part of the monument’s significance rather than an embarrassment to be omitted."},{"type":"paragraph","text":"Bhera’s river-town identity emerges from this layering. Routes can persist while gateways change; a religious institution can endure through major reconstruction; an ancient name can remain debated while later history is well documented. These are not competing versions from which one must choose the most romantic. They describe different kinds of continuity. Keeping them distinct allows the town’s memory to remain expansive without making its evidence appear more certain than it is."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Punjab","Regional History"],"province":"Punjab","district":"Sargodha","relatedDistrictIds":["punjab-sargodha"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6576","major-doam-10314"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Bhera and the memory of a river town","description":"Bhera’s river setting, altered gates and repeatedly rebuilt mosque show why a town’s age cannot be read from a single origin story.","primaryKeyword":"Bhera urban history","socialTitle":"Bhera and the memory of a river town","socialDescription":"Bhera’s river setting, altered gates and repeatedly rebuilt mosque show why a town’s age cannot be read from a single origin story."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Site of Ancient City, Bhera","url":"https://doam.gov.pk/public/sites/6576","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Jame Masjid Bhera","url":"https://doam.gov.pk/public/sites/10314","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. Ancient Sophytus identification in catalogue is not adopted as established; mosqueSherShah association attributed, presentfabric distinguished from1541 inscription and1858/1926 phases. No currentgateconditionassurance.","editorialReason":"Use town fabric and documents while qualifying disputed ancient identifications.","sortOrder":339}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-faisalabad-a-planned-town-and-its-later-city','faisalabad-a-planned-town-and-its-later-city','review','{"id":"story-faisalabad-a-planned-town-and-its-later-city","type":"story","slug":"faisalabad-a-planned-town-and-its-later-city","title":"Faisalabad: a planned town and its later city","summary":"Faisalabad’s planned centre is only one chapter in a regional history that includes Sandal Bar, canal settlement, commerce and textile production.","body":[{"type":"paragraph","text":"Faisalabad’s clock tower and eight bazaars make a strong image of a planned city. Yet a plan is a beginning of inquiry, not a complete urban history. It shows how a centre was organised, but it does not explain every later business, journey or neighbourhood. Nor does the creation of a colonial town imply that its wider landscape previously lacked people or history."},{"type":"paragraph","text":"The district government dates the clock tower’s construction to 1903–05 and describes the eight-bazaar arrangement around it. The monument provides a common point of reference for several approaches. That is different from treating it as an isolated object in a square: its urban significance depends on the streets that bring people towards it and distribute them away again."},{"type":"heading","level":2,"text":"A plan encountered at street level"},{"type":"paragraph","text":"A diagram makes a radial arrangement look immediate and orderly. Walking through it is a different experience. A person sees one approach, a partial view of the tower and the changing frontage of a particular market. The distinction between a bird’s-eye plan and a ground-level journey helps explain why a designed centre can acquire many local identities without losing its overall geometry."},{"type":"paragraph","text":"The district account also identifies Kaiseri Gate and the Gumti with 1897, and places the gate at the entrance to Rail Bazaar. These smaller structures widen the reading beyond the tower. Commemorative architecture and commercial approaches can overlap, while later changes in use or symbolism alter what a place means. The presence of a colonial-era monument does not freeze the surrounding market in its original social setting."},{"type":"heading","level":2,"text":"The region before and beyond Lyallpur"},{"type":"paragraph","text":"Lyallpur Museum’s recorded gallery structure offers an important counterweight to a tower-centred account. Its subjects include Sandal Bar, regional archaeology, the Chenab Colony, Lyallpur and textiles. These categories connect a planned urban centre to a wider environmental, settlement and productive history. The museum’s use of the older city name also makes naming itself part of the historical conversation."},{"type":"paragraph","text":"The gallery list is not a substitute for inspecting individual objects and their labels. It does, however, show why the city cannot be explained solely through a colonial plan. A canal-colony history asks about land and settlement; a textile history asks about production and labour; an archaeological history reaches beyond the chronology of the modern centre. Each requires different sources and raises different questions about change."},{"type":"heading","level":2,"text":"A city outgrows its founding image"},{"type":"paragraph","text":"The useful contrast is not between a perfect old plan and a disorderly later city. It is between the intentions recorded in a plan and the many purposes that people subsequently bring to streets and buildings. A market is made through use as well as design. Its history includes adaptation, subdivision and changing forms of work."},{"type":"paragraph","text":"Faisalabad’s planned centre remains an excellent point of orientation. It becomes a richer heritage subject when the tower is read together with its bazaars and with the regional histories presented by the museum. The result is a city with a designed centre, not a city whose entire identity can be reduced to a design."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Punjab","Regional History"],"province":"Punjab","district":"Faisalabad","relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Faisalabad: a planned town and its later city","description":"Faisalabad’s planned centre is only one chapter in a regional history that includes Sandal Bar, canal settlement, commerce and textile production.","primaryKeyword":"Faisalabad Lyallpur history","socialTitle":"Faisalabad: a planned town and its later city","socialDescription":"Faisalabad’s planned centre is only one chapter in a regional history that includes Sandal Bar, canal settlement, commerce and textile production."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Important Places","url":"https://faisalabad.punjab.gov.pk/important-places","publisher":"District Government Faisalabad","accessDate":"2026-10-22"},{"title":"Lyallpur Museum, Faisalabad","url":"https://doam.gov.pk/public/heritage-sites/790","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Archaeology and Cultural Heritage Sectoral Report: Faisalabad Regional Development Plan","url":"https://urbanunit.gov.pk/Download/publications/Files/17/2023/Faisalabad%20Regional%20Development%20Plan%20-%20Archaeology%20%26%20Cultural%20Heritage%20Sector_compressed.pdf","publisher":"The Urban Unit","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. District page inconsistent1880Lyallgovernorstatement notused. Museumgalleryscope crosscheckedDOAM/UrbanUnitindexed report; no uninspectedobjectclaim. No claimcityplancreatedemptyland.","editorialReason":"Investigate planning, naming and lived growth without treating a plan as the complete city.","sortOrder":340}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-mandi-bahauddin-rail-river-and-market','mandi-bahauddin-rail-river-and-market','review','{"id":"story-mandi-bahauddin-rail-river-and-market","type":"story","slug":"mandi-bahauddin-rail-river-and-market","title":"Mandi Bahauddin: rail, river and market","summary":"Mandi Bahauddin’s modern growth connects a grain market with canal irrigation, rail transport and later river engineering.","body":[{"type":"paragraph","text":"The word mandi directs attention to exchange. In the district government’s account, Mandi Bahauddin’s name joins a grain market with the nearby settlement of Pindi Bahauddin. That is a useful beginning for a town history: not an isolated foundation ceremony, but a relationship between an existing place and a new concentration of commercial activity."},{"type":"paragraph","text":"The same account connects early-twentieth-century growth with the Lower Jhelum Canal, a railway station and the grain market. It records the canal’s opening in 1902, Pindi Bahauddin station in 1916 and the town’s notification as Mandi Bahauddin in 1920. Read together, these dates suggest successive investments rather than a city appearing fully formed in one year. They also leave space for the people already living and working in the surrounding countryside."},{"type":"heading","level":2,"text":"Water and movement do different work"},{"type":"paragraph","text":"Canal irrigation and railways are often presented as a single story of development. Their functions differ. A canal changes how water reaches land; a railway changes the movement of people and goods. A market concentrates transactions. Their intersection can create commercial opportunities, but it does not tell us how those opportunities were distributed. Land records, trading accounts and family histories would be needed to understand ownership, debt and labour alongside the infrastructure."},{"type":"paragraph","text":"Malakwal provides a second railway setting within the district. The government’s places guide dates its junction to 1901 and associates it with grain traffic and access towards Khewra’s salt and industrial activity. Malakwal Junction should not be confused with Pindi Bahauddin station. They belong to a related regional story, but are different places with different roles in the network."},{"type":"paragraph","text":"The distinction is easy to lose on a modern district map. A single administrative boundary may contain several town histories and transport nodes. The useful question is not which landmark best represents the entire district, but how each node connected to the others and to destinations beyond it."},{"type":"heading","level":2,"text":"A later engineering landscape"},{"type":"paragraph","text":"Rasul Barrage adds a post-independence chapter. The district guide identifies the present barrage on the Jhelum as a 1968 structure replacing an earlier installation. It describes regulation for irrigation and flood control. This is not a surviving colonial barrage simply carrying on unchanged: the site embodies replacement and a different stage of river engineering."},{"type":"paragraph","text":"For heritage interpretation, that distinction is important. An older location can contain newer infrastructure, while a newer structure can participate in a longer history of water management. Neither its age nor its scale alone explains its social effects. The settlement and labour associated with construction are also part of the story, even when they are less visible than gates, rails or concrete."},{"type":"paragraph","text":"Mandi Bahauddin’s history becomes clearer through these linked but distinct systems. Market, railway and barrage operate at different scales and follow different chronologies. Keeping those differences visible allows the town to be understood as a changing regional centre rather than a collection of disconnected historical attractions."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Punjab","Regional History"],"province":"Punjab","district":"Mandi Bahauddin","relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Mandi Bahauddin: rail, river and market","description":"Mandi Bahauddin’s modern growth connects a grain market with canal irrigation, rail transport and later river engineering.","primaryKeyword":"Mandi Bahauddin history","socialTitle":"Mandi Bahauddin: rail, river and market","socialDescription":"Mandi Bahauddin’s modern growth connects a grain market with canal irrigation, rail transport and later river engineering."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Our History","url":"https://mandibahauddin.punjab.gov.pk/our-history","publisher":"District Government Mandi Bahauddin","accessDate":"2026-10-22"},{"title":"Important Places","url":"https://mandibahauddin.punjab.gov.pk/important-places","publisher":"District Government Mandi Bahauddin","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. Ancient battle/city identifications and colonial empty-land claims in district history omitted. Malakwal1901 and PindiBahauddin1916 are distinct stations. Rasul1968 is present structure, not first intervention. Source-derived narrative below200 words per page; comparative interpretation original.","editorialReason":"Connect official railway and town evidence while leaving uncertain ancient claims aside.","sortOrder":341}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-thatta-across-political-and-cultural-changes','thatta-across-political-and-cultural-changes','review','{"id":"story-thatta-across-political-and-cultural-changes","type":"story","slug":"thatta-across-political-and-cultural-changes","title":"Thatta across political and cultural changes","summary":"Thatta’s city, congregational mosque and Makli necropolis preserve changing political and cultural histories, not a single frozen golden age.","body":[{"type":"paragraph","text":"Thatta’s history extends across changes of rule, patronage and architectural practice. The city’s relationship with Makli is essential, but the necropolis is not a substitute for the city. Nor does the Shah Jahan Mosque stand for every period of Thatta’s life. Together, these places reveal different ways in which political authority and religious commitment became architecture."},{"type":"paragraph","text":"UNESCO’s account of Makli places its major historical sequence between the fourteenth and eighteenth centuries. It identifies monuments associated with rulers, administrators, religious figures and scholars. The variety of patrons is matched by differences in material and form: stone structures, brick buildings and glazed-tile decoration occupy the same funerary landscape without becoming one architectural type."},{"type":"heading","level":2,"text":"Several histories within Makli"},{"type":"paragraph","text":"Among the monuments highlighted by UNESCO are those of Jam Nizamuddin II, Isa Khan Tarkhan the Younger and Diwan Shurfa Khan. These names locate different acts of commemoration within the wider landscape. They should not be treated as interchangeable examples of a generic royal tomb. A building’s plan, carved detail and inscription can illuminate a particular commission even when the larger political chronology remains in the background."},{"type":"paragraph","text":"The necropolis also creates an imbalance in what survives visibly. Monumental tombs make certain patrons easier to identify than the many people whose work and lives sustained the city. A history built only from the grandest mausoleums will inevitably favour commemorative wealth. Recognising that limit encourages attention to ordinary graves and to sources beyond architecture, without inventing biographies for those who remain unnamed."},{"type":"heading","level":2,"text":"The mosque and congregational space"},{"type":"paragraph","text":"The federal inventory describes Thatta’s Shah Jahan Mosque as a seventeenth-century courtyard complex with arcaded galleries and domed chambers. It records extensive tile decoration, including radiating patterns within the domes, and associates the commission with Shah Jahan. Here, ornament is encountered through a sequence of spaces rather than as a single façade."},{"type":"paragraph","text":"The distinction from Makli is functional as well as visual. A congregational building gathers people for worship; a funerary monument marks remembrance and burial. The two may share materials or patterns, but their circulation and social use differ. Comparing them illuminates a city’s cultural life more effectively than using one decorative motif to declare a uniform local style."},{"type":"paragraph","text":"The mosque and necropolis also have different international designation histories. Makli is the inscribed World Heritage property. Its status should not be extended casually to every monument in Thatta. A place can be important without sharing a neighbour’s designation, and accurate naming helps visitors understand what a particular listing actually covers."},{"type":"paragraph","text":"Thatta is therefore best read through overlapping histories rather than a single rise-and-fall account. Changes of rule did not make every building new at once, and surviving monuments do not preserve all aspects of urban life equally. Keeping the city, its sacred spaces and its necropolis in conversation allows their differences to become a source of understanding rather than an obstacle to a simple story."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Sindh","Regional History"],"province":"Sindh","district":"Thatta","relatedDistrictIds":["sindh-thatta"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["unesco-143","major-doam-5625"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Thatta across political and cultural changes","description":"Thatta’s city, congregational mosque and Makli necropolis preserve changing political and cultural histories, not a single frozen golden age.","primaryKeyword":"Thatta history heritage","socialTitle":"Thatta across political and cultural changes","socialDescription":"Thatta’s city, congregational mosque and Makli necropolis preserve changing political and cultural histories, not a single frozen golden age."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Historical Monuments at Makli, Thatta","url":"https://whc.unesco.org/en/list/143/","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Shahjahani Mosque / Jamia Mosque Thatta Town","url":"https://doam.gov.pk/public/sites/5625","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Relate urban, sacred and funerary histories without compressing centuries into one golden age.","sortOrder":342}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-sukkur-and-rohri-as-linked-river-settlements','sukkur-and-rohri-as-linked-river-settlements','review','{"id":"story-sukkur-and-rohri-as-linked-river-settlements","type":"story","slug":"sukkur-and-rohri-as-linked-river-settlements","title":"Sukkur and Rohri as linked river settlements","summary":"Sukkur and Rohri are connected by the Indus and its crossings, while their monuments preserve histories older than the celebrated steel bridge.","body":[{"type":"paragraph","text":"Sukkur and Rohri are often introduced through the bridge between them. It is a powerful image, but it can make the river appear to matter only as an obstacle overcome by engineering. The Indus also gives these settlements a shared setting while keeping their approaches and landmarks distinct. A crossing joins places; it does not make their histories identical."},{"type":"paragraph","text":"On the Sukkur side, Mir Masum’s minar and family tombs introduce a history older than the steel bridge. The federal inventory dates the start of the tower’s construction to 1595 and describes a brick structure with an internal stair. It also records inscribed canopies over the graves. The ensemble combines height, visibility and commemoration rather than serving simply as a decorative feature in a river panorama."},{"type":"heading","level":2,"text":"A monument and its associated record"},{"type":"paragraph","text":"The catalogue identifies Mir Masum as a scholar and historian associated with the Tarikh-e-Masumi. This connection is valuable because it brings a written historical tradition into the architectural landscape. A monument linked with a historian is not automatically a reliable illustration of everything in his text, but it offers a concrete point from which to ask about authorship, patronage and public memory."},{"type":"paragraph","text":"The tower and tombs should also be read together. A photograph concentrating only on the vertical landmark can exclude the lower structures that explain its commemorative setting. Conversely, a close view of an inscription may conceal the ensemble’s wider position. Different scales of looking answer different questions; neither the panorama nor the detail is sufficient alone."},{"type":"heading","level":2,"text":"A crossing documented in construction"},{"type":"paragraph","text":"Cambridge University Library holds a presentation album documenting construction of the Lansdowne Bridge. Its curatorial account identifies completion in 1889 and describes a sequence of 65 photographs covering stages of the project. The Institution of Civil Engineers also catalogues an 1889 photographic record. These dated records are more useful than a caption that leaves unclear whether its year refers to design, construction or opening."},{"type":"paragraph","text":"An album celebrating an engineering achievement is a selective historical object. It can preserve extraordinary information about assembly while directing attention towards the project’s official narrative. Reading it alongside a settlement history opens further questions: how approaches were organised, which journeys changed, and whose labour made the structure possible. Those questions should be investigated rather than answered by imagining unnamed workers’ experiences."},{"type":"paragraph","text":"Sukkur and Rohri are therefore linked at more than one scale. The bridge belongs to a transport network extending beyond either settlement. The minar and tombs belong to a local commemorative landscape. The river places both within a changing physical setting. Bringing these scales together avoids two familiar simplifications: treating the bridge as the beginning of regional connection, or treating the river towns as an unchanged backdrop to it. Their heritage lies in the interaction between long-established places and successive ways of moving through them."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Sindh","Regional History"],"province":"Sindh","district":null,"relatedDistrictIds":["sindh-sukkur"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5135","major-doam-5119"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Sukkur and Rohri as linked river settlements","description":"Sukkur and Rohri are connected by the Indus and its crossings, while their monuments preserve histories older than the celebrated steel bridge.","primaryKeyword":"Sukkur Rohri history","socialTitle":"Sukkur and Rohri as linked river settlements","socialDescription":"Sukkur and Rohri are connected by the Indus and its crossings, while their monuments preserve histories older than the celebrated steel bridge."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Mir Masum’s Minar and Tomb","url":"https://doam.gov.pk/public/sites/5135","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Digitisation of Sukkur Bridge photograph album","url":"https://specialcollections-blog.lib.cam.ac.uk/?p=16383","publisher":"Cambridge University Library","accessDate":"2026-10-22"},{"title":"The Sukkur (Lansdowne) Bridge, 1889","url":"https://www.ice-imagelibrary.com/image/960/the-sukkur-lansdowne-bridge","publisher":"Institution of Civil Engineers","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft.1889 completion follows Cambridge/ICE, notDOAM5119 shorthand1887. Album described fromcuratorial record, no claimall65imagesvisuallyinspected. ReserveCambridgepage sourcebudget for392:~85derivedwordshere.","editorialReason":"Investigate crossing, monument and settlement relations on both banks.","sortOrder":343}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-hyderabads-forts-houses-and-changing-institutions','hyderabads-forts-houses-and-changing-institutions','review','{"id":"story-hyderabads-forts-houses-and-changing-institutions","type":"story","slug":"hyderabads-forts-houses-and-changing-institutions","title":"Hyderabad’s forts, houses and changing institutions","summary":"Hyderabad’s fortification, dynastic tomb and Mukhi House show how authority, domestic life and public institutions occupy different layers of the city.","body":[{"type":"paragraph","text":"Hyderabad’s architectural history cannot be confined to one dynasty or one building type. A fort wall defines an enclosure; a tomb commemorates authority after death; a substantial house can later become a public institution. Comparing these forms reveals a city shaped by changing uses as well as successive rulers."},{"type":"paragraph","text":"The federal inventory records the decorated crest of Pucca Fort’s boundary wall and places the monument within the Kalhora and Talpur historical setting. A boundary wall is more than a dramatic edge. It distinguishes an inside from an outside, controls passage and frames the relationship between a stronghold and the settlement around it. The surviving line deserves attention even where the original internal arrangement is harder to recover."},{"type":"heading","level":2,"text":"Authority in more than one form"},{"type":"paragraph","text":"The tomb of Ghulam Shah Kalhoro presents a different architectural role. Its catalogue describes a raised brick structure finished with lime, a dome, painted interior details and exterior tile decoration. Here, authority is expressed through commemoration rather than through the control of a defended perimeter. Comparing the tomb with the fort can illuminate differences in function without assuming that every surviving element belongs to one uninterrupted building campaign."},{"type":"paragraph","text":"The materials also encourage a closer reading. Brick, plaster, paint and tile have different vulnerabilities and repair histories. A smooth surface can conceal substantial maintenance, while a missing decorative section may expose construction. The age of the institution or person commemorated does not, by itself, date every visible layer. That distinction is particularly important in buildings that continue to attract care and attention over generations."},{"type":"heading","level":2,"text":"A house becomes a public place"},{"type":"paragraph","text":"Mukhi House introduces the early twentieth century and a domestic setting. The inventory describes a two-storey stone building with a central domed feature. Official accounts place its construction in the early 1920s and associate it with Jethanand Mukhi. The Sindh Tourism Development Corporation records both its family-residence history and a period as Khadija Girls School. The Directorate of Antiquities now identifies it as Mukhi House Museum."},{"type":"paragraph","text":"These changes are not merely a footnote to the original architecture. A family home, a school and a museum organise access differently. Rooms once used within a household may acquire teaching or display functions; visitors move through spaces that previously had other thresholds. Reuse creates another layer of the building’s history, even where it also helps sustain older fabric."},{"type":"paragraph","text":"A museum setting should not erase the household associated with the building, just as a family narrative should not erase its later educational use. The strongest interpretation makes those transitions understandable and distinguishes preserved fabric from display arrangements. It need not pretend that each room has retained its original function."},{"type":"paragraph","text":"Hyderabad’s fort, tomb and house therefore offer three complementary approaches to the city: enclosure, remembrance and reuse. Their relationships are richer than a simple chronological procession from one ruler to the next. They show how architecture can continue to matter when its users, institutions and meanings change."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Sindh","Regional History"],"province":"Sindh","district":"Hyderabad","relatedDistrictIds":["sindh-hyderabad"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5712","major-doam-5700","major-doam-5659"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Hyderabad’s forts, houses and changing institutions","description":"Hyderabad’s fortification, dynastic tomb and Mukhi House show how authority, domestic life and public institutions occupy different layers of the city.","primaryKeyword":"Hyderabad Sindh heritage history","socialTitle":"Hyderabad’s forts, houses and changing institutions","socialDescription":"Hyderabad’s fortification, dynastic tomb and Mukhi House show how authority, domestic life and public institutions occupy different layers of the city."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Pucca Fort Boundary Wall","url":"https://doam.gov.pk/public/sites/5712","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Tomb of Ghulam Shah Kalhoro","url":"https://doam.gov.pk/public/sites/5659","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Mukhi Mahal, Fort Incline","url":"https://doam.gov.pk/public/sites/5700","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Mukhi House","url":"https://stdc.gos.pk/2024/10/15/mukhi-house/","publisher":"Sindh Tourism Development Corporation","accessDate":"2026-10-22"},{"title":"Mukhi House Museum, Hyderabad","url":"https://antiquities.sindhculture.gov.pk/tour/mukhi-house-museum-hyderabad/","publisher":"Directorate General of Antiquities, Government of Sindh","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. Mukhi date1920STDCversusaround1921inventory expressedearly1920s. Museumidentityverifiedcurrentofficialpage; templatehours/GMT8ignored. No obsoleteownership/protectionassertions.","editorialReason":"Build a comparative city narrative beyond a single ruling dynasty.","sortOrder":344}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-karachis-civic-buildings-before-the-megacity','karachis-civic-buildings-before-the-megacity','review','{"id":"story-karachis-civic-buildings-before-the-megacity","type":"story","slug":"karachis-civic-buildings-before-the-megacity","title":"Karachi’s civic buildings before the megacity","summary":"Karachi’s nineteenth-century hall, market and educational institution reveal different ambitions within the city before its metropolitan expansion.","body":[{"type":"paragraph","text":"Karachi’s older civic buildings are often photographed as fragments of a lost, quieter city. That nostalgic view can obscure their original differences. A commemorative hall, a regulated market and an educational institution were not interchangeable public amenities. They organised different activities and represented different forms of ambition within the nineteenth-century city."},{"type":"paragraph","text":"Frere Hall’s federal inventory describes a Gothic composition built in local Jungshahi limestone, with verandas, a tower and an upper hall reached by a substantial stair. Its name commemorated a colonial administrator. Material and dedication point in different directions: local stone and skilled construction served an institution associated with imperial authority. Recognising both avoids treating the building as either a purely imported object or an apolitical piece of craftsmanship."},{"type":"heading","level":2,"text":"Commerce within an architectural frame"},{"type":"paragraph","text":"Empress Market’s inventory dates its construction to 1884–89 and records a plan organised around four galleries accommodating shops and stalls. Its imperial name and everyday commercial function belong to the same building. The market’s significance is therefore not only the appearance of its exterior but the relationship between a formal structure and the many transactions it accommodated."},{"type":"paragraph","text":"A market building also raises questions that a façade cannot answer: how space was allocated, how goods arrived, and how regulation affected sellers. Those questions require municipal and commercial records as well as accounts from traders. The architecture provides a framework for inquiry, not evidence that all users experienced the institution in the same way. Its later history should not be reduced to whether a photograph looks more or less orderly."},{"type":"heading","level":2,"text":"Education as a civic project"},{"type":"paragraph","text":"Sindh Madressatul Islam offers a different institutional narrative. The university’s own history dates the school’s foundation to September 1885 under Hassanally Effendi’s leadership. It describes a project intended to expand educational opportunity for Muslims while admitting students of other religious backgrounds. This is an institutional account of reform, not simply another example of a government-sponsored colonial building."},{"type":"paragraph","text":"The university records Muhammad Ali Jinnah’s attendance between 1887 and 1892 and his return for the college inauguration in 1943. These associations matter, but a school’s heritage exceeds its most famous student. Teaching, boarding, administration and successive generations of pupils also belong to its history. An alumni narrative and a building history illuminate different aspects of the institution."},{"type":"heading","level":2,"text":"More than a surviving style"},{"type":"paragraph","text":"Placed beside one another, the hall, market and school show why a single architectural label cannot explain Karachi’s civic life. Commemoration, exchange and education produced different relationships between patronage and public use. They also connected the city to wider administrative, commercial and social networks."},{"type":"paragraph","text":"The useful comparison is therefore not between an elegant past and an inconvenient present. It is between the purposes for which buildings were made and the uses through which they continued to matter. Karachi’s earlier civic architecture becomes more compelling when people, institutions and contested meanings remain in the account, rather than disappearing behind a collection of attractive façades."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Sindh","Regional History"],"province":"Sindh","district":null,"relatedDistrictIds":["sindh-south-karachi"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5858","major-doam-5846","major-doam-6234"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Karachi’s civic buildings before the megacity","description":"Karachi’s nineteenth-century hall, market and educational institution reveal different ambitions within the city before its metropolitan expansion.","primaryKeyword":"Karachi civic heritage history","socialTitle":"Karachi’s civic buildings before the megacity","socialDescription":"Karachi’s nineteenth-century hall, market and educational institution reveal different ambitions within the city before its metropolitan expansion."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Frere Hall","url":"https://doam.gov.pk/public/sites/5858","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Empress Market","url":"https://doam.gov.pk/public/sites/5846","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"History of SMI","url":"https://www.smiu.edu.pk/about/history","publisher":"Sindh Madressatul Islam University","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Use institutions and urban records to explain change rather than nostalgia alone.","sortOrder":345}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-sehwan-as-both-archaeological-and-sacred-city','sehwan-as-both-archaeological-and-sacred-city','review','{"id":"story-sehwan-as-both-archaeological-and-sacred-city","type":"story","slug":"sehwan-as-both-archaeological-and-sacred-city","title":"Sehwan as both archaeological and sacred city","summary":"Sehwan’s archaeological mound and Lal Shahbaz Qalandar’s shrine belong to a connected urban history, but they preserve different kinds of evidence.","body":[{"type":"paragraph","text":"Sehwan is both an archaeological place and a living sacred city. The distinction matters because its mound and shrine answer different historical questions. Purana Qila preserves traces of occupation and rebuilding; Lal Shahbaz Qalandar’s shrine is sustained through remembrance, worship and institutions. Neither should be used to explain the other through a single founding legend."},{"type":"paragraph","text":"The federal inventory describes the fort site as a substantial mound containing fragments of pottery, brick and charcoal, with structures from different periods. Such a mound is not simply the remains of one fort built at one moment. Accumulated occupation can include houses, workshops, dumped material, defensive works and later disturbance. Its shape is the outcome of many processes rather than a straightforward ground plan."},{"type":"heading","level":2,"text":"A changing position within the town"},{"type":"paragraph","text":"Monique Kervran’s account of excavations, reproduced by the Endowment Fund Trust, distinguishes several major phases at Purana Qila. She describes a change in which a fortified garrison occupied the mound while civilian settlement developed to its south around the shrine. This offers a spatial relationship between the two histories without making them identical. A shift in where people lived can be as important as the construction of a prominent wall."},{"type":"paragraph","text":"Kervran’s account combines excavated sequences with written evidence and differentiates successive fortifications. The resulting picture is richer than attributing the entire mound to Alexander or to one later dynasty. A name used in local memory may be historically significant, but archaeological attribution requires material and chronological evidence. The city’s depth does not depend on winning a competition for the oldest continuously inhabited settlement."},{"type":"heading","level":2,"text":"The shrine has its own institutional history"},{"type":"paragraph","text":"The inventory identifies Lal Shahbaz Qalandar’s tomb and records an early shrine foundation. That is not a date for every part of the present complex. Religious institutions can undergo rebuilding while retaining their dedication and central place in a community. Continued significance and unchanged fabric are different forms of continuity."},{"type":"paragraph","text":"Researcher Delphine Ortis’s published presentation abstract identifies the shrine’s nationalisation in 1962 as an important change in its administration. This introduces a modern institutional history that a medieval foundation date alone cannot capture. Questions about management, ritual and authority remain part of the shrine’s life; they should not be concealed by presenting it as a survival outside history."},{"type":"paragraph","text":"Sehwan’s two forms of heritage also call for different kinds of respectful attention. Archaeological deposits should remain undisturbed, while a place of worship requires sensitivity to people using it. Neither is merely a setting for a visitor’s photograph. A fuller account would place excavation reports alongside locally grounded histories and accounts from participants, with consent and clear attribution."},{"type":"paragraph","text":"The most useful connection between mound and shrine is therefore a changing city. Buildings, settlement and sacred institutions shaped one another over time, but their records remain distinct. Keeping those distinctions visible allows Sehwan to be understood as more than either an ancient ruin or a timeless pilgrimage image."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Archaeology","Sindh","Regional History"],"province":"Sindh","district":"Jamshoro","relatedDistrictIds":["sindh-jamshoro"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5180","major-doam-5179"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Sehwan as both archaeological and sacred city","description":"Sehwan’s archaeological mound and Lal Shahbaz Qalandar’s shrine belong to a connected urban history, but they preserve different kinds of evidence.","primaryKeyword":"Sehwan history archaeology shrine","socialTitle":"Sehwan as both archaeological and sacred city","socialDescription":"Sehwan’s archaeological mound and Lal Shahbaz Qalandar’s shrine belong to a connected urban history, but they preserve different kinds of evidence."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Fort at Sehwan","url":"https://doam.gov.pk/public/sites/5180","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Shrine of Lal Shahbaz Qalandar","url":"https://doam.gov.pk/public/sites/5179","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Excavations on Sehwan, in International Conference: Alexander in the Indus Valley","url":"https://cdnc.heyzine.com/files/uploaded/v3/06c6f0d3a1e00ef2a3beb530f0373ae46e21936c.pdf","publisher":"Monique Kervran / Endowment Fund Trust for Preservation of the Heritage of Sindh","accessDate":"2026-10-22","section":"printed pages37–39"},{"title":"Universalisations et patrimonialisations du soufisme: Delphine Ortis presentation","url":"https://imaf.cnrs.fr/spip.php?article4272=&lang=fr","publisher":"Institut des mondes africains, CNRS","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. Kervranreporttextreadpp37–39; oldestcityrankingnotadopted. Ortisprimaryabstractreadindexedbecausefullfetchfailed; narrow1962administrationfactonly. No visualdiagramclaim or Alexanderfoundationclaim.","editorialReason":"Keep distinct forms of evidence visible within one local history.","sortOrder":346}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-thars-sacred-and-fortified-places','thars-sacred-and-fortified-places','review','{"id":"story-thars-sacred-and-fortified-places","type":"story","slug":"thars-sacred-and-fortified-places","title":"Thar’s sacred and fortified places","summary":"Gori’s Jain temple, Naukot and Umerkot reveal different sacred and fortified landscapes within Thar rather than one uniform desert culture.","body":[{"type":"paragraph","text":"Thar is often represented through a single visual vocabulary of sand, colour and remote monuments. Its built heritage is more varied. Gori’s Jain temple, Naukot Fort and Umerkot Fort differ in function, material and political setting. They can be compared within a wider region without being made to tell one uniform story about desert life."},{"type":"paragraph","text":"Pakistan’s Nagarparkar Cultural Landscape submission places Jain temples within a network of settlements, religious spaces and water features. It is on UNESCO’s Tentative List, not the World Heritage List. Its landscape approach is useful because a temple’s significance extends beyond an isolated carved doorway. Approaches, associated structures and relationships between settlements also matter."},{"type":"heading","level":2,"text":"A sacred interior organised in stages"},{"type":"paragraph","text":"Gori’s official inventory describes a sequence of pillared spaces leading towards the shrine, with stone construction and marble details. It also records an inscription associated with repair in 1715. The repair date is particularly revealing: the temple had a history of maintenance, not only an initial moment of construction. A surviving sacred building can preserve changes within a religious tradition as well as evidence of its original commission."},{"type":"paragraph","text":"Reading the temple through its successive spaces avoids reducing it to decoration. A threshold, a column and a covered chamber participate in the experience of approach. Their religious significance should be explained through appropriate Jain sources and community knowledge, rather than guessed from their resemblance to features in another tradition. Shared materials do not make dedications interchangeable."},{"type":"heading","level":2,"text":"Fortification and residence"},{"type":"paragraph","text":"Naukot’s catalogue presents a different architectural arrangement: a brick enclosure with a defended entrance, associated with the Talpur Mirs and used as both stronghold and residence. Its walls organise a protected interior, whereas the temple’s sequence organises a sacred approach. Both use enclosure, but enclosure serves different purposes in each setting."},{"type":"paragraph","text":"Umerkot’s record recounts successive political possession and describes a substantial rectangular fort with corner bastions. The important point for comparison is not that every surviving wall belongs to its earliest attributed ruler. Reoccupation and repair can change a fort while preserving its strategic or commemorative identity. A dynasty name alone cannot date all of its masonry."},{"type":"paragraph","text":"These forts should not automatically be included within the boundaries of the Nagarparkar Tentative List property. A regional article and an international designation have different scopes. The wider Thar context makes comparison possible; it does not create a single protected ensemble out of every place discussed."},{"type":"heading","level":2,"text":"Difference within a region"},{"type":"paragraph","text":"The contrast between temple and fort helps resist two simplifications: that the desert was empty except for a few monuments, or that all its communities shared one unchanged culture. Buildings imply different networks of devotion, authority, labour and settlement. Their histories also extend beyond the people whose names appear in catalogues."},{"type":"paragraph","text":"A thoughtful reading of Thar therefore preserves distinctions while exploring connections. Gori asks about sacred space and continuing care; Naukot about the relationship between residence and defence; Umerkot about successive claims to a stronghold. Together they offer a region with several histories, not a single picturesque desert past."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Sindh","Regional History"],"province":"Sindh","district":null,"relatedDistrictIds":["sindh-tharparkar","sindh-umer-kot"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5499","major-doam-5504","major-doam-5509"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Thar’s sacred and fortified places","description":"Gori’s Jain temple, Naukot and Umerkot reveal different sacred and fortified landscapes within Thar rather than one uniform desert culture.","primaryKeyword":"Thar heritage history","socialTitle":"Thar’s sacred and fortified places","socialDescription":"Gori’s Jain temple, Naukot and Umerkot reveal different sacred and fortified landscapes within Thar rather than one uniform desert culture."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Nagarparkar Cultural Landscape","url":"https://whc.unesco.org/en/tentativelists/6111/","publisher":"UNESCO World Heritage Centre / Government of Pakistan","accessDate":"2026-10-22"},{"title":"Gori Temple","url":"https://doam.gov.pk/public/sites/5499","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Naukot Fort","url":"https://doam.gov.pk/public/sites/5504","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Umerkot Fort","url":"https://doam.gov.pk/public/sites/5509","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. Gori/Naukotpagesclose-readsavedofficialcatalogueaftertimeouts. UNESCOtentativestatusretained; noentireTharserialpropertyclaim. Sea chronology/oldestfresco/vanishedcommunitytotalisationsnotadopted. NoexactfoundingdateforUmerkot.","editorialReason":"Compare built environments without portraying the desert as culturally uniform.","sortOrder":347}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-peshawar-at-the-meeting-of-regional-routes','peshawar-at-the-meeting-of-regional-routes','review','{"id":"story-peshawar-at-the-meeting-of-regional-routes","type":"story","slug":"peshawar-at-the-meeting-of-regional-routes","title":"Peshawar at the meeting of regional routes","summary":"Peshawar’s sarai, merchant house and fort show how movement became institutions, domestic space and political control within a city.","body":[{"type":"paragraph","text":"Calling Peshawar a crossroads is only a beginning. Routes become historically meaningful through places where people stop, transact, worship and govern. Gor Khatri, Sethi House and Bala Hisar reveal different ways in which a city accommodated movement. They also show why exchange should not be presented as a single, uninterrupted condition stretching across every period."},{"type":"paragraph","text":"The federal inventory describes Gor Khatri as a complex with a layered sacred and civic history. It associates a seventeenth-century sarai with Jahanara Begum and records monumental entrances opening into a large quadrangle lined with accommodation. A sarai gives physical form to stopping: a traveller passes through a controlled entrance into a shared interior before moving on again."},{"type":"heading","level":2,"text":"The architecture of staying"},{"type":"paragraph","text":"That arrangement differs from a road or pass. It places movement within an institution, with spaces for entry, supervision and temporary occupation. The catalogue also records later changes of religious use. Gor Khatri is consequently not an untouched example of a single Mughal programme. Its significance includes the ways later users altered an established place."},{"type":"paragraph","text":"The distinction between a traveller’s accommodation and a merchant household becomes clearer at Sethi House. The inventory records a courtyard reached through a carved entrance, coloured glass and decorated ceilings. It links the house with Seth Karim Bakhsh and places completion in 1884. The courtyard is described as a setting for hospitality and business, joining domestic space with exchange without making the building a public market."},{"type":"paragraph","text":"The richness of its interior points to concentrated resources and specialised work. It does not by itself identify where every material came from or which distant city inspired each motif. Those connections need trade records and comparative study. Describing coloured glass precisely is more informative than assigning the whole house to an exotic influence on the strength of resemblance alone."},{"type":"heading","level":2,"text":"A route also requires attention to power"},{"type":"paragraph","text":"Bala Hisar adds the question of control. Its inventory recounts repeated destruction and rebuilding under different authorities, including later replacement of earthen walls with brick masonry. The fort’s long history should therefore not be treated as the survival of one original structure. A prominent position can retain strategic importance while its architecture changes substantially."},{"type":"paragraph","text":"The three places complicate an exclusively celebratory story of cultural exchange. A sarai accommodates, a household negotiates access, and a fort asserts authority. Movement can support commerce and encounter while also being supervised, taxed or restricted. Which of these operated in a particular period requires evidence beyond the general description of Peshawar as a gateway."},{"type":"paragraph","text":"Read together, the buildings make the city itself central to the route story. Peshawar was not simply a space between more important destinations. It contained institutions and households that shaped what movement meant. Its heritage is most compelling when those local arrangements remain visible alongside the wider networks to which they belonged, and when later changes are treated as history rather than as distractions from an imagined original city."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Khyber Pakhtunkhwa","Regional History"],"province":"Khyber Pakhtunkhwa","district":"Peshawar","relatedDistrictIds":["khyber-pakhtunkhwa-peshawar"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-doam-1810","major-doam-3485","major-doam-4607"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Peshawar at the meeting of regional routes","description":"Peshawar’s sarai, merchant house and fort show how movement became institutions, domestic space and political control within a city.","primaryKeyword":"Peshawar urban history","socialTitle":"Peshawar at the meeting of regional routes","socialDescription":"Peshawar’s sarai, merchant house and fort show how movement became institutions, domestic space and political control within a city."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Gor Khuttree","url":"https://doam.gov.pk/public/sites/1810","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Sethi House","url":"https://doam.gov.pk/public/sites/3485","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Bala Hisar Fort","url":"https://doam.gov.pk/public/sites/4607","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Connect urban layers and exchange with carefully dated evidence.","sortOrder":348}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-swat-beyond-a-single-buddhist-period','swat-beyond-a-single-buddhist-period','review','{"id":"story-swat-beyond-a-single-buddhist-period","type":"story","slug":"swat-beyond-a-single-buddhist-period","title":"Swat beyond a single Buddhist period","summary":"Swat’s archaeology includes urban settlement, Buddhist precincts, early Islamic buildings and later timber architecture, with different chronologies at each site.","body":[{"type":"paragraph","text":"Swat’s Buddhist monuments are central to its archaeological importance, but they are not the whole of its history. Settlements, production areas, mosques and later timber buildings belong to the same valley without belonging to one period. A fuller picture emerges by comparing sites and phases rather than arranging the region around a single cultural high point followed by disappearance."},{"type":"paragraph","text":"The Khyber PATH research project at Ca’ Foscari describes Barikot through ten broad occupation phases extending from about 1200 BCE into the pre-modern period. Its account distinguishes the acropolis from the lower city and bases its sequence on archaeological contexts and radiocarbon evidence. This is a settlement history as well as a history of religious monuments."},{"type":"heading","level":2,"text":"Different parts of a town can change differently"},{"type":"paragraph","text":"At Barikot, the project describes changes in the use of defensive walls and the eventual abandonment of the ancient lower city. Such changes should not be converted into a claim that all life in Swat ended at the same moment. A hilltop, a town below it and neighbouring settlements can follow different trajectories. Regional history needs those differences rather than a single date imposed across the valley."},{"type":"paragraph","text":"Butkara-I offers a different archaeological focus. Its inventory describes a central stupa surrounded by smaller votive structures and associated buildings, with a paved setting and finds now represented in the Swat Museum. A religious precinct concentrates evidence for worship and patronage. It cannot by itself stand for every domestic activity or social group in the surrounding landscape."},{"type":"heading","level":2,"text":"Early Islamic evidence is archaeological too"},{"type":"paragraph","text":"The Swat Museum project’s account of Udegram discusses an inscription recording a mosque foundation in 1048–49 CE, associated with the Ghaznavid commander Nushtegin. Excavation revealed the mosque and neighbouring settlement. This is a material and epigraphic history of early Islamic occupation, not simply a later chapter added after the archaeological story has ended."},{"type":"paragraph","text":"The same account places the mosque on an earlier terrace with older masonry. Reuse of a location does not mean every earlier structure remained active, nor does it demonstrate that religious change happened uniformly across the valley. It shows why a site’s physical sequence is indispensable: a later building may occupy a landscape already shaped by centuries of construction."},{"type":"paragraph","text":"Kalam’s wooden mosque introduces another scale and material tradition. The official catalogue describes a timber structure with a central chamber, veranda and carved geometric and floral decoration. It belongs to a later inhabited setting, not to the same archaeological phase as Butkara or the same building campaign as Udegram."},{"type":"paragraph","text":"Swat is therefore not best understood as a succession of sealed cultural compartments. Places were occupied, altered, abandoned, revisited and maintained in different ways. Reading Barikot, Butkara, Udegram and Kalam together keeps both change and continued inhabitation in view. It also gives the valley’s later architectural traditions their own significance, rather than treating them merely as a background surrounding a more important ancient past."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Khyber Pakhtunkhwa","Regional History"],"province":"Khyber Pakhtunkhwa","district":"Swat","relatedDistrictIds":["khyber-pakhtunkhwa-swat"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-doam-3304","major-bazira","major-doam-10332"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Swat beyond a single Buddhist period","description":"Swat’s archaeology includes urban settlement, Buddhist precincts, early Islamic buildings and later timber architecture, with different chronologies at each site.","primaryKeyword":"Swat heritage chronology","socialTitle":"Swat beyond a single Buddhist period","socialDescription":"Swat’s archaeology includes urban settlement, Buddhist precincts, early Islamic buildings and later timber architecture, with different chronologies at each site."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Site 1: Barikot, Khyber PATH","url":"https://pric.unive.it/projects/khyberpath/research-and-excavations/site-1-barikot","publisher":"Ca’ Foscari University of Venice","accessDate":"2026-10-22"},{"title":"Butkara-I","url":"https://doam.gov.pk/public/sites/3304","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"The New Swat Archaeological Museum, Gallery8","url":"https://iris.unive.it/bitstream/10278/3722733/1/MUSEO_tnsam%201%2011-09-2013-l.pdf","publisher":"ACT Field School Project / Ca’ Foscari repository","accessDate":"2026-10-22","section":"Early Islam: the Ghaznavids, p119"},{"title":"Wooden Mosque, Kalam","url":"https://doam.gov.pk/public/sites/10332","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. MuseumbookUdegramsectionreadindexedprimarytextafter403; recheckfullbeforepublication. Butkara/Kalamofficialsnapshotread. Nooldestmosqueranking; noentirevalleyconversiondate. Barikotcontinuityqualifiedsitephase, notrepeatedUNESCOuninterruptedclaim.","editorialReason":"Show archaeological and later architectural layers without a disappearance narrative.","sortOrder":349}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-bannu-basin-in-regional-archaeology','the-bannu-basin-in-regional-archaeology','review','{"id":"story-the-bannu-basin-in-regional-archaeology","type":"story","slug":"the-bannu-basin-in-regional-archaeology","title":"The Bannu basin in regional archaeology","summary":"Research at Akra shows why Bannu’s growth and connections cannot be explained simply as the result of imperial annexation.","body":[{"type":"paragraph","text":"Bannu’s archaeology raises a question larger than the date of one mound: how did a region develop its own settlement and exchange patterns while interacting with expanding states? Akra is central to that inquiry. Its significance is not simply that it can be attached to the name of a famous empire, but that excavation complicates the relationship between local growth and imperial power."},{"type":"paragraph","text":"The federal inventory describes Akra as a group of mounds southwest of Bannu, with pottery, terracotta material and other remains. Its short chronology field emphasises the sixth to fourth centuries BCE. A catalogue field is useful for orientation, but it is not a complete account of a site’s occupation. Evidence discussed by the excavators reaches beyond that restricted period."},{"type":"heading","level":2,"text":"Growth before annexation"},{"type":"paragraph","text":"In their 2005 research article, Peter Magee, Cameron Petrie and colleagues reported that Akra expanded rapidly near the beginning of the first millennium BCE, before Achaemenid rule in the region. Their account also identified connections with Central Asia and peninsular India during that earlier phase. The result challenges a simple explanation in which imperial annexation created both urbanism and long-distance exchange."},{"type":"paragraph","text":"The distinction changes the historical question. Instead of asking only what an empire brought to a passive periphery, it becomes possible to ask how an established regional centre responded to new political circumstances. Existing networks may be redirected, maintained or selectively integrated. The evidence does not require every imported object to represent an official imperial presence."},{"type":"heading","level":2,"text":"Why the basin matters"},{"type":"paragraph","text":"The Bannu Archaeological Project’s later synthesis treats the basin across a long sequence from the first millennium BCE into the early second millennium CE. Its regional approach matters because a large settlement does not operate alone. Smaller sites, routes and productive landscapes help explain how a centre was sustained and how its importance changed."},{"type":"paragraph","text":"A basin is an analytical geographical unit, not a synonym for every archaeological site in western Pakistan. Discoveries in the Gomal or Kachi plains may offer valuable comparisons, but they must retain their own locations and histories. Adding a celebrated site from another basin to a Bannu itinerary would create a misleading impression of proximity and shared context."},{"type":"heading","level":2,"text":"Objects and political identity"},{"type":"paragraph","text":"Coins and pottery can reveal connections, but their interpretation depends on context. A coin may travel beyond the area directly governed by its issuer; a vessel type may be copied locally. Archaeological arguments become stronger when objects are associated with stratified deposits and compared with settlement evidence. A surface find alone cannot reconstruct a complete administrative system."},{"type":"paragraph","text":"Akra’s importance consequently lies in the questions it enables as much as in any single identification. It provides a way to examine regional initiative, exchange and changing relationships with larger powers. Bannu is not merely an edge on somebody else’s map. The research presents it as a historical landscape with its own patterns of growth—patterns that help explain why the borders of empires were often more complex than the outlines drawn for them."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Khyber Pakhtunkhwa","Regional History"],"province":"Khyber Pakhtunkhwa","district":"Bannu","relatedDistrictIds":["khyber-pakhtunkhwa-bannu"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-doam-3184"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"The Bannu basin in regional archaeology","description":"Research at Akra shows why Bannu’s growth and connections cannot be explained simply as the result of imperial annexation.","primaryKeyword":"Bannu archaeology history","socialTitle":"The Bannu basin in regional archaeology","socialDescription":"Research at Akra shows why Bannu’s growth and connections cannot be explained simply as the result of imperial annexation."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Akra (Akara) Mound","url":"https://doam.gov.pk/public/sites/3184","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"The Achaemenid Empire in South Asia and Recent Excavations in Akra in Northwest Pakistan","url":"https://repository.brynmawr.edu/arch_pubs/82/","publisher":"Peter Magee, Cameron Petrie and colleagues / American Journal of Archaeology","accessDate":"2026-10-22"},{"title":"Resistance at the Edge of Empires: The Archaeology and History of the Bannu Basin from1000BC toAD1200","url":"https://www.jstor.org/stable/j.ctv13pk77m","publisher":"Cameron A. Petrie and colleagues / Oxbow Books","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft.2005primaryarticleabstractclose-read;PDF403.2021bookdescriptionandchapterpreviewread, notfullbook. No specificunreadexcavationcontextasserted. Abstractcounterdatescataloguesixth-centuryfoundationassumption. Gomal/Kachi sitesnotimportedintoBannu.","editorialReason":"Explain basin-scale questions through Akra without absorbing archaeological sites from neighbouring basins.","sortOrder":350}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-chitrals-forts-and-multilingual-communities','chitrals-forts-and-multilingual-communities','review','{"id":"story-chitrals-forts-and-multilingual-communities","type":"story","slug":"chitrals-forts-and-multilingual-communities","title":"Chitral’s forts and multilingual communities","summary":"Chitral’s courtly buildings tell only part of a regional story whose living heritage includes many languages and community-led work.","body":[{"type":"paragraph","text":"Chitral’s forts and royal buildings offer a visible account of political authority. They do not contain the whole region’s cultural history. Languages, local names, songs and forms of knowledge are carried by communities whose presence cannot be read simply from a court’s architecture. A balanced introduction needs both the substantial building and the less monumental record."},{"type":"paragraph","text":"The federal inventory places Mustuj Fort within the Kathoor-period heritage of Chitral. Its short description records a roughly square enclosure. Shahi Masjid is also associated with that political setting, but has a different arrangement: a prayer hall, cloistered sides and a tomb connected with Shuja-ul-Mulk. These records establish different building functions without providing a complete social history of the people around them."},{"type":"heading","level":2,"text":"A court is not a cultural census"},{"type":"paragraph","text":"A fort can help explain the location and organisation of authority. A royal mosque can connect patronage, worship and remembrance. Neither proves that everyone within a ruler’s sphere spoke the same language or shared the same customs. The reach of political power and the distribution of languages are different geographical questions, and their boundaries need not coincide."},{"type":"paragraph","text":"The Forum for Language Initiatives’ introduction to the Palula makes that distinction concrete. It identifies Ashret and Biori as important Palula-speaking settings and describes multilingual communication involving other regional languages. The example challenges an account of Chitral reduced to Khowar and Kalasha alone. It also reminds readers that multilingual ability does not make a person’s mother tongue unimportant or interchangeable with another language."},{"type":"heading","level":2,"text":"Living heritage is being made now"},{"type":"paragraph","text":"FLI’s 2024 report describes a Chitral languages gathering involving researchers, writers, activists and performers. Its programme included discussion of writing and education, multilingual poetry and the launch of Yadgha songs. These are contemporary cultural activities, not the passive survival of an unchanged past. People are producing materials, choosing forms of expression and debating how their languages should be used."},{"type":"paragraph","text":"The report is evidence of an organised event, not a complete survey of every language community. Participation in a public programme should not be mistaken for a measure of a language’s health. Nor should a colourful performance be made to stand for all aspects of a community’s daily life. Education, migration and the settings in which children learn to speak require their own careful study."},{"type":"heading","level":2,"text":"Connecting buildings and voices"},{"type":"paragraph","text":"An interpretation of Mustuj or Chitral’s courtly heritage can make room for locally used place names and accounts from people connected with the surrounding settlements. Such material needs consent, attribution and appropriate language review. It should not be invented to make a building description sound more intimate."},{"type":"paragraph","text":"The resulting portrait of Chitral is neither a royal chronicle with a decorative cultural appendix nor a list of languages detached from place. Buildings record particular forms of power and patronage; living language work records communities actively shaping their futures. Holding those histories together makes the region more intelligible without pretending they are the same kind of evidence."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Khyber Pakhtunkhwa","Regional History"],"province":"Khyber Pakhtunkhwa","district":null,"relatedDistrictIds":["khyber-pakhtunkhwa-chitral-upper","khyber-pakhtunkhwa-chitral-lower"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-doam-1238","major-doam-1236"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Chitral’s forts and multilingual communities","description":"Chitral’s courtly buildings tell only part of a regional story whose living heritage includes many languages and community-led work.","primaryKeyword":"Chitral regional heritage history","socialTitle":"Chitral’s forts and multilingual communities","socialDescription":"Chitral’s courtly buildings tell only part of a regional story whose living heritage includes many languages and community-led work."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Mustuj Fort","url":"https://doam.gov.pk/public/sites/1238","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Shahi Masjid","url":"https://doam.gov.pk/public/sites/1236","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"The Land of the Palula","url":"https://fli-online.org/documents/languages/palula/land_of_palula.pdf","publisher":"Forum for Language Initiatives","accessDate":"2026-10-22"},{"title":"Annual Report2024: Gathering the Voices of Chitral","url":"https://fli-online.org/wp-content/uploads/2024/12/Annual-Report-2024.pdf","publisher":"Forum for Language Initiatives","accessDate":"2026-10-22","section":"p14"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. FLIprimarypassagesclose-readinindexedtextafterdirectfetchfailure; noestimatedspeakercountrepeated. FortandmosqueKathoorattributiononly, cataloguebroaddatefieldnotexactfoundation. Communityreviewrequiredforlanguageorthography.","editorialReason":"Balance built evidence and documented language diversity rather than one court narrative.","sortOrder":351}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-quetta-valley-before-the-modern-city','quetta-valley-before-the-modern-city','review','{"id":"story-quetta-valley-before-the-modern-city","type":"story","slug":"quetta-valley-before-the-modern-city","title":"Quetta valley before the modern city","summary":"Kili Gul Mohammad and Damb Sadaat show that the Quetta valley’s settlement history long predates the modern city, while precise early chronologies need care.","body":[{"type":"paragraph","text":"The modern city does not mark the beginning of habitation in the Quetta valley. Archaeological mounds such as Kili Gul Mohammad and Damb Sadaat preserve a much longer settlement history. They shift attention from streets and standing civic buildings to accumulated deposits, pottery and the traces of structures that may no longer be legible as complete buildings."},{"type":"paragraph","text":"Kili Gul Mohammad lies in the northern part of the valley. The federal inventory records excavation by Walter Fairservis in 1950–51 and describes a sequence important for the study of early pottery. Damb Sadaat, also known locally as Mian Ghundai, is another key settlement site. Its record connects architectural remains and ceramic assemblages with repeated archaeological investigation during the twentieth century."},{"type":"heading","level":2,"text":"Two sites, not one origin story"},{"type":"paragraph","text":"The sites are often grouped together because of their importance to research on the valley. That does not make them two parts of a single settlement or give them an identical chronological sequence. Each excavation samples a particular place. Similar pottery may help build a comparison, but the relationship must be demonstrated through contexts and dating rather than assumed from geographical proximity."},{"type":"paragraph","text":"Fairservis published his Quetta Valley investigations in the American Museum of Natural History’s Anthropological Papers in 1956. The museum’s bibliographic record provides a stable starting point for tracing this research history. It also separates the date of fieldwork from the date of publication—a small distinction that matters when assessing how archaeological interpretations developed."},{"type":"heading","level":2,"text":"Why exact dates need more than a catalogue"},{"type":"paragraph","text":"The current official entries contain broad early chronologies, but some fields and narrative dates do not agree. One also contains an obvious typographical error in the account of an early visit. Those problems are reasons to consult the excavation publication and later reassessments, not reasons to discard the sites’ importance or silently choose whichever date sounds most ancient."},{"type":"paragraph","text":"A settlement mound can contain many occupation phases. The date of an earliest sampled layer is not automatically the date on which a whole community was founded. Equally, the latest material recovered from one trench need not establish the end of activity everywhere on the site. The useful historical claim is that these places preserve long sequences requiring phase-by-phase study."},{"type":"heading","level":2,"text":"The valley as an inhabited landscape"},{"type":"paragraph","text":"Such evidence changes how the setting of Quetta is understood. The valley was not an empty geographical container awaiting the modern city. Its earlier inhabitants made, used and discarded objects, built structures and participated in patterns of settlement that archaeology can investigate. Those activities deserve an account in their own right rather than serving only as a preface to later urban history."},{"type":"paragraph","text":"For a visitor, a low or damaged mound may appear less immediately impressive than a standing monument. Its value lies in the relationships preserved within deposits. Removing a potsherd would detach it from that evidence. Quetta’s deeper history is therefore best approached through careful documentation and museum interpretation, with uncertainty about exact early dates kept visible until the underlying research can resolve it."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Balochistan","Regional History"],"province":"Balochistan","district":"Quetta","relatedDistrictIds":["balochistan-quetta"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["major-doam-8773","major-doam-8867"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Quetta valley before the modern city","description":"Kili Gul Mohammad and Damb Sadaat show that the Quetta valley’s settlement history long predates the modern city, while precise early chronologies need care.","primaryKeyword":"Quetta valley archaeology","socialTitle":"Quetta valley before the modern city","socialDescription":"Kili Gul Mohammad and Damb Sadaat show that the Quetta valley’s settlement history long predates the modern city, while precise early chronologies need care."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Kili Gul Mohammad","url":"https://doam.gov.pk/public/sites/8867","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Damb Sadaat","url":"https://doam.gov.pk/public/sites/8773","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Excavations in the Quetta Valley, West Pakistan: bibliographic record","url":"https://www.biodiversitylibrary.org/bibliography/88274","publisher":"American Museum of Natural History Library / Biodiversity Heritage Library","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. Fairservis1956bibliographyverifiedbutfullreportunavailable; no claimdirectread. DOAM8867has1094typo and inconsistentdates;8773field/narrativediffer. Exactearlydateswithheldratherthansynthesised. Source-limitedresearcharticle, editorialchronologyreviewrequired.","editorialReason":"Use settlement evidence to establish a long regional history with explicit chronological limits.","sortOrder":352}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-makran-through-settlement-and-maritime-connections','makran-through-settlement-and-maritime-connections','review','{"id":"story-makran-through-settlement-and-maritime-connections","type":"story","slug":"makran-through-settlement-and-maritime-connections","title":"Makran through settlement and maritime connections","summary":"Makran’s archaeology links inland oasis settlement with coastal resources and wider exchange, without requiring one continuous ancient sea route.","body":[{"type":"paragraph","text":"Makran’s heritage is often approached from the sea. Its archaeological history also depends on inland valleys and oases. Settlement near Turbat, sites in the Dasht landscape and later buildings at Gwadar belong to different periods and systems of connection. Bringing them into one regional account is useful only if those differences remain visible."},{"type":"paragraph","text":"The French Archaeological Mission in Makran investigated this relationship through survey and excavation in collaboration with Pakistan’s Department of Archaeology and Museums. Its published institutional overview places Miri Qalat and Shahi-Tump at the centre of a regional sequence reaching back into the fifth millennium BCE. The project combined settlement archaeology with studies of materials, environment and coastal resource use."},{"type":"heading","level":2,"text":"An oasis has its own history"},{"type":"paragraph","text":"At Shahi-Tump, the mission distinguishes built occupation from later cemetery phases. Its account discusses pottery, metalworking and ornaments in relation to wider regional connections. These are not simply exotic objects proving that traders passed through. Their archaeological contexts help reconstruct how people lived, made things and treated the dead within an inland setting."},{"type":"paragraph","text":"The difference between a settlement and a cemetery is crucial. Material from a grave belongs to a particular act of deposition; material in a floor or workshop has another relationship to activity. Combining everything under a single site date can conceal changes in use. Makran’s significance lies partly in the sequences that make such distinctions possible."},{"type":"heading","level":2,"text":"Coast and hinterland are related, not interchangeable"},{"type":"paragraph","text":"The federal inventory places Sutkagen-Dor beside the Dasht river plain on a sandstone outcrop. That location invites questions about approaches, water and regional movement. It does not, by itself, demonstrate where the shoreline lay during a particular occupation phase or prove that the site functioned as a harbour. Palaeoenvironmental evidence and excavated material are needed to establish those propositions."},{"type":"paragraph","text":"The mission’s wider research identifies connections with the Iranian plateau, the Indus region, Central Asia and Oman. Such connections need not represent one unchanging route. Objects, techniques and raw materials can move through several linked exchanges. A similarity between distant assemblages is evidence to investigate, not a complete itinerary for an individual traveller."},{"type":"heading","level":2,"text":"A much later maritime chapter"},{"type":"paragraph","text":"Gwadar’s Omani-period fort belongs to another historical framework. Its catalogue identifies a substantial rectangular building associated with Omani rule. It can introduce later political relationships across the sea, but it should not be used to imply direct continuity from a Bronze Age exchange network. The same coastal region can participate in very different systems centuries apart."},{"type":"paragraph","text":"Makran becomes more interesting when inland settlement is not treated merely as a supporting corridor to a port. Oases, river plains and coastal communities each contribute evidence with their own chronology. A regional narrative can connect them while remaining precise about what is known. That produces a history of changing relationships between land and sea, rather than a single ancient route drawn confidently across a modern map."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Balochistan","Regional History"],"province":"Balochistan","district":null,"relatedDistrictIds":["balochistan-kech","balochistan-gwadar"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["major-doam-10398","major-doam-8639","major-doam-10390"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Makran through settlement and maritime connections","description":"Makran’s archaeology links inland oasis settlement with coastal resources and wider exchange, without requiring one continuous ancient sea route.","primaryKeyword":"Makran cultural history","socialTitle":"Makran through settlement and maritime connections","socialDescription":"Makran’s archaeology links inland oasis settlement with coastal resources and wider exchange, without requiring one continuous ancient sea route."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Mission archéologique française au Makran","url":"https://arscan.parisnanterre.fr/umr-7041/equipes/equipe-archeologie-de-lasie-centrale/activites-de-lequipe-archeologie-de-lasie-centrale/mission-archeologique-francaise-au-makran-mafm/","publisher":"ArScAn / CNRS / Université Paris Nanterre","accessDate":"2026-10-22"},{"title":"Shahi Tump","url":"https://doam.gov.pk/public/sites/10398","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Sutkagen-Dor","url":"https://doam.gov.pk/public/sites/8639","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Omani Fort, Gwadar","url":"https://doam.gov.pk/public/sites/10390","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. ArScAnprimarymissionpageclose-read; use~165derivedwords, reservebudgetfor398. DOAMrecordsreadlocalsnapshot. SutkagenDor notassertedcoastalportbasedonmodernposition; GwadarfortnotBronzeAgecontinuity.","editorialReason":"Connect inland archaeology and coastal exchange without claiming one uninterrupted route.","sortOrder":353}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-sibis-forts-and-remembered-political-pasts','sibis-forts-and-remembered-political-pasts','review','{"id":"story-sibis-forts-and-remembered-political-pasts","type":"story","slug":"sibis-forts-and-remembered-political-pasts","title":"Sibi’s forts and remembered political pasts","summary":"Sibi’s Mir Chakar Fort combines a powerful remembered identity with earthen remains whose construction phases still require careful separation.","body":[{"type":"paragraph","text":"Sibi’s ruined fort is widely identified with Mir Chakar Khan. That name is an important part of its remembered identity, but it does not date every surviving wall. An earthen stronghold repeatedly occupied and repaired can preserve several histories within one enclosure. The task is to distinguish physical evidence from later attribution without treating either as irrelevant."},{"type":"paragraph","text":"The federal inventory describes the fort on the northern side of the town as a rectangular enclosure with circular bastions and corner watchtowers. Its walls and internal structures use earth, mud slabs and brick. The record also notes openings associated with defence and a western entrance whose full form is difficult to establish because of damage."},{"type":"heading","level":2,"text":"Earth records rebuilding differently"},{"type":"paragraph","text":"An earthen wall is not simply an unfinished stone wall. Its material affects how it weathers, how it can be repaired and what remains after collapse. Repeated maintenance may preserve a boundary while replacing much of its exposed fabric. A photograph of a surviving height cannot therefore establish the age of the entire structure beneath it."},{"type":"paragraph","text":"The inventory’s description of disturbed rooms is useful for the same reason. Incomplete walls can show that internal spaces existed without allowing their precise function to be named. Calling every chamber a barracks, prison or royal room would go beyond the evidence. A measured survey can establish dimensions and relationships; excavation or documentary sources are needed for more specific interpretations."},{"type":"heading","level":2,"text":"Names and political histories"},{"type":"paragraph","text":"The catalogue associates the fort with Mir Chakar while also repeating a much earlier origin tradition. A historical Sibi district gazetteer attributes forts in the region to Mughal use but allows that Sibi’s fort may have older origins. These differing statements need not be forced into one seamless foundation story. They may concern different structures, occupations or remembered episodes."},{"type":"paragraph","text":"Attribution is a historical question in its own right. A community may remember a fort through a prominent figure even when its walls were built or altered by several authorities. That association can be explained as remembrance without turning it into proof that the named person designed every feature. Conversely, uncertainty about a foundation does not make the place culturally unimportant."},{"type":"heading","level":2,"text":"Reading the surviving enclosure"},{"type":"paragraph","text":"The most productive account begins with the recorded plan, materials and visible defensive features, then asks which phases can be dated securely. It separates an observed opening from an inferred weapon use, a documented occupation from a legend, and an older condition report from the present state of the ruins."},{"type":"paragraph","text":"Sibi’s fort deserves that precision. Its significance does not depend on an exact early date repeated without checking, or on an imagined reconstruction of courtly life. The combination of substantial earthen remains and a strong place in regional memory is already compelling. Careful research can make the relationship between them clearer while preserving the questions the surviving structure cannot yet answer."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Balochistan","Regional History"],"province":"Balochistan","district":"Sibi","relatedDistrictIds":["balochistan-sibi"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["major-doam-8426"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Sibi’s forts and remembered political pasts","description":"Sibi’s Mir Chakar Fort combines a powerful remembered identity with earthen remains whose construction phases still require careful separation.","primaryKeyword":"Sibi heritage history","socialTitle":"Sibi’s forts and remembered political pasts","socialDescription":"Sibi’s Mir Chakar Fort combines a powerful remembered identity with earthen remains whose construction phases still require careful separation."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Mir Chakar Fort Sibi","url":"https://doam.gov.pk/public/sites/8426","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Balochistan District Gazetteer: Sibi District","url":"https://irrigation.sindh.gov.pk/files/Books/133.pdf","publisher":"Historical district gazetteer, hosted by Sindh Irrigation Department","accessDate":"2026-10-22","section":"History: fort attributions"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. Gazetteerrelevantpassagereadindexed; fullPDFtoolrejectedsize. Exact650CEclaimnotadopted; associationMirChakarqualified. Source-limitedscope focuses documentedfabric/remembrance, no fabricatedchronicleevents. Furtherhistorianreviewrequired.","editorialReason":"Separate historical documents, physical phases and later remembrance.","sortOrder":354}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-baltistans-courts-mosques-and-shared-building-skills','baltistans-courts-mosques-and-shared-building-skills','review','{"id":"story-baltistans-courts-mosques-and-shared-building-skills","type":"story","slug":"baltistans-courts-mosques-and-shared-building-skills","title":"Baltistan’s courts, mosques and shared building skills","summary":"Shigar, Khaplu Palace and Chaqchan Mosque show how shared materials and building skills served different courtly and religious purposes in Baltistan.","body":[{"type":"paragraph","text":"Baltistan’s historic buildings share a striking use of timber, masonry and carefully articulated openings. Shared materials do not make their purposes identical. A ruling household, a congregational mosque and a settlement around a palace require different arrangements of space. Comparing Shigar, Khaplu and Chaqchan reveals both a regional building vocabulary and the choices made within particular commissions."},{"type":"paragraph","text":"Shigar Fort Palace is an especially useful warning against treating a complex silhouette as one construction event. The federal inventory describes three adjoining structures from different phases, brought together into what appears to be an integrated mass. It records domestic and service spaces as well as a family mosque. A court was therefore a working household, not only an audience chamber."},{"type":"heading","level":2,"text":"Structure, screen and threshold"},{"type":"paragraph","text":"At Khaplu Palace, the catalogue describes timber-reinforced masonry, courtyards and rooms serving residence, storage and other needs. Carved frames and screened verandas articulate the edges between spaces. A screen is both a crafted object and part of a building’s organisation: it changes how an opening is perceived and how people see through it. Its significance is not exhausted by identifying a decorative pattern."},{"type":"paragraph","text":"The comparison with Shigar should remain specific. A similar carved detail might suggest shared conventions or the circulation of skills, but it cannot establish the identity of a maker without additional evidence. Nor does a broad label such as Tibetan or Kashmiri influence explain how a particular joint was made, a room used or a commission managed."},{"type":"heading","level":2,"text":"A mosque in the same material world"},{"type":"paragraph","text":"Chaqchan Jamia Mosque in Khaplu presents another relationship between timber, stone and earth. Its inventory describes a raised, two-level arrangement with an upper prayer hall and surrounding veranda, and lower winter prayer spaces. The building responds to use and seasonal conditions in ways that differ from a palace, even where construction traditions overlap."},{"type":"paragraph","text":"Its religious identity should not be inferred from a roof shape alone. Stories of earlier buildings on the site require their own evidence. What can be described securely is the recorded arrangement and the material techniques through which it was made. Comparison becomes more valuable when it respects the distinction between courtly and congregational space."},{"type":"heading","level":2,"text":"Conservation adds another chapter"},{"type":"paragraph","text":"AKDN reports conservation and reuse at Shigar and Khaplu alongside work in neighbouring settlements and on other historic buildings. The programme treats skills and infrastructure as part of conservation, not merely the finishing of interiors. These are the implementing organisation’s reported activities; their wider effects require independent and locally grounded assessment."},{"type":"paragraph","text":"The important interpretive point is that a conserved building is still part of a changing community. New uses, maintenance and training enter its history. Baltistan’s architecture is not a frozen catalogue of inherited motifs. It is a record of people arranging materials for particular lives and institutions, and of later people deciding how those structures can remain useful without losing the evidence of their earlier purposes."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Gilgit-Baltistan","Regional History"],"province":"Gilgit-Baltistan","district":null,"relatedDistrictIds":["gilgit-baltistan-shigar","gilgit-baltistan-ghanche"],"provinceRegionIds":["gilgit-baltistan"],"relatedHeritageIds":["major-doam-7998","major-doam-7974","major-doam-7969"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Baltistan’s courts, mosques and shared building skills","description":"Shigar, Khaplu Palace and Chaqchan Mosque show how shared materials and building skills served different courtly and religious purposes in Baltistan.","primaryKeyword":"Baltistan architecture history","socialTitle":"Baltistan’s courts, mosques and shared building skills","socialDescription":"Shigar, Khaplu Palace and Chaqchan Mosque show how shared materials and building skills served different courtly and religious purposes in Baltistan."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Shigar Fort Palace","url":"https://doam.gov.pk/public/sites/7998","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Khaplu Fort","url":"https://doam.gov.pk/public/sites/7974","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Chaqchan Jamia Mosque","url":"https://doam.gov.pk/public/sites/7969","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Conservation and Development in Gilgit-Baltistan","url":"https://www-hetz2.the.akdn/en/where-we-work/south-asia/pakistan/conservation-and-development-in-gilgit-baltistan-pakistan","publisher":"Aga Khan Development Network","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. Chaqchanreadsavedofficialcatalogueaftertimeout; Buddhistprecursorlocalaccountnotasserted. AKDNprogrammeclaimattributed, notindependentimpactevaluation. ~65wordsderivedAKDNpage; reservefor355/400/401.","editorialReason":"Explain regional connections without erasing local patronage or religious distinctions.","sortOrder":355}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-hunza-through-fort-and-settlement-relations','hunza-through-fort-and-settlement-relations','review','{"id":"story-hunza-through-fort-and-settlement-relations","type":"story","slug":"hunza-through-fort-and-settlement-relations","title":"Hunza through fort and settlement relations","summary":"Baltit Fort is best understood with the settlement below it: an architectural landmark within changing relationships of authority, housing and conservation.","body":[{"type":"paragraph","text":"Baltit Fort’s position above Karimabad makes it an obvious focal point. Yet the relationship with the settlement beneath it is more revealing than the silhouette alone. A fort is sustained through people, stores, routes and labour. Its prominence expresses a relationship to surrounding habitation, not separation from it."},{"type":"paragraph","text":"The UNESCO Tentative List account describes a building expanded through several phases, with storage areas, reception spaces and rooms associated with different seasons. It also notes timber reinforcement within masonry. These details complicate the image of a single defensive tower. The complex combined protection, household provision and the representation of authority, with additions changing how it functioned over time."},{"type":"heading","level":2,"text":"Looking below the landmark"},{"type":"paragraph","text":"AKTC’s account of Karimabad identifies the older clustered settlements of Diramishal and Khurukshal beneath the fort. It describes their historical dependence on the ruler rather than presenting the arrangement simply as a harmonious mountain village. That distinction matters. A visually coherent settlement can preserve unequal social relationships as well as shared building traditions."},{"type":"paragraph","text":"The fort’s reception rooms and the houses below belong to different scales of domestic life. Comparing them can suggest questions about storage, access and the organisation of work, but it cannot supply the experiences of particular households without other sources. A panoramic photograph may show spatial proximity while concealing social differences."},{"type":"heading","level":2,"text":"Change is not the opposite of heritage"},{"type":"paragraph","text":"The same programme literature discusses changing transport, employment and building patterns. Its conservation approach addressed the historic settlement as well as the fort. This is a significant shift from saving an isolated object: water, sanitation, housing and the pressure to build on agricultural land become part of the heritage discussion."},{"type":"paragraph","text":"AKDN records the completion of the Baltit conservation project in 1996 and its use as a local-history museum and cultural centre. Those changes create a new relationship between a former ruling residence and visitors. They do not return the building to a single original moment. Conservation itself becomes a documented phase in a longer history of alteration and use."},{"type":"paragraph","text":"The project’s own reports should be read as accounts from its implementing organisation, not as proof that every outcome was shared equally. A fuller evaluation would include residents’ experiences and the continuing costs of maintenance. The architectural achievement and the social process are connected but require different kinds of assessment."},{"type":"heading","level":2,"text":"Fort and settlement together"},{"type":"paragraph","text":"Baltit is on Pakistan’s Tentative List; this is distinct from World Heritage inscription. Its importance does not depend on confusing those statuses. The building offers a strong point of entry into Hunza’s history, especially when interpretation extends beyond its most spectacular rooms."},{"type":"paragraph","text":"Notice the approach, the transition between houses and fort, and the different uses of enclosure and outlook. Keep private homes distinct from public visitor spaces. The result is a less isolated image of Baltit: not a timeless castle above an equally timeless village, but a landmark within changing relationships between authority, household life and the care of an inhabited landscape."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Gilgit-Baltistan","Regional History"],"province":"Gilgit-Baltistan","district":"Hunza","relatedDistrictIds":["gilgit-baltistan-hunza"],"provinceRegionIds":["gilgit-baltistan"],"relatedHeritageIds":["curated-baltit"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Hunza through fort and settlement relations","description":"Baltit Fort is best understood with the settlement below it: an architectural landmark within changing relationships of authority, housing and conservation.","primaryKeyword":"Hunza historic settlements","socialTitle":"Hunza through fort and settlement relations","socialDescription":"Baltit Fort is best understood with the settlement below it: an architectural landmark within changing relationships of authority, housing and conservation."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Baltit Fort","url":"https://whc.unesco.org/en/tentativelists/1882/","publisher":"UNESCO World Heritage Centre / Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Steering the Transformation of the Physical Environment in Hunza","url":"https://static.the.akdn/53832/1641873948-2005_hcsp_hunza.pdf","publisher":"Aga Khan Trust for Culture","accessDate":"2026-10-22"},{"title":"Conservation and Development in Gilgit-Baltistan","url":"https://www-hetz2.the.akdn/en/where-we-work/south-asia/pakistan/conservation-and-development-in-gilgit-baltistan-pakistan","publisher":"Aga Khan Development Network","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. RemovedNiltfromtopicrelationshipbecauseNagar-sidecomparisonunnecessaryhere; rootnotified.2005Hunza reportrelevantKarimabadpassageclose-readindexed. Noeighth-centuryabsoluteclaimfrom2004TL; constructionphasesonly.2005reporthistoricaldescriptionnotpresentconditions. AKDNsharedwebpage~55derivedwords.","editorialReason":"Investigate building and community change rather than a timeless mountain kingdom.","sortOrder":356}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-gilgit-and-its-inscriptions-in-stone','gilgit-and-its-inscriptions-in-stone','review','{"id":"story-gilgit-and-its-inscriptions-in-stone","type":"story","slug":"gilgit-and-its-inscriptions-in-stone","title":"Gilgit and its inscriptions in stone","summary":"Danyor’s inscription and Kargah’s carved Buddha reveal different forms of evidence for Gilgit’s connections—and the care required to interpret stone records.","body":[{"type":"paragraph","text":"Stone can preserve writing and imagery in the same regional landscape without making them the same kind of document. Near Gilgit, Danyor’s inscription and the carved Buddha at Kargah offer a useful contrast. One requires the reading of a text and its script; the other requires the interpretation of an image, its setting and its formal details. Both need careful documentation before large historical claims are built upon them."},{"type":"paragraph","text":"The federal catalogue identifies Danyor as a royal inscription in a late Brahmi script tradition. That description is an orientation, not a translation. The distinction between a script and a language is important: naming the form of writing does not, on its own, explain what the record says or how it should be dated."},{"type":"heading","level":2,"text":"A difficult surface is part of the evidence"},{"type":"paragraph","text":"Gérard Fussman’s 1978 discussion records his examination of the Danyor inscription and explains why he postponed a full edition. He describes shallow lettering on an irregular, fissured surface and difficulties obtaining a complete photographic record. This is a valuable account of scholarly caution. The inscription’s existence was not in doubt, but secure reading required better documentation."},{"type":"paragraph","text":"The Collège de France archive also preserves a catalogued photographic record associated with Danyor. Such material allows the history of documentation to be traced alongside the history recorded on the stone. An older photograph can be evidence for what was visible at a particular time, although it must be assessed for lighting, framing and technical limits."},{"type":"heading","level":2,"text":"Image is not inscription"},{"type":"paragraph","text":"Kargah’s Buddha is described in the official inventory as a standing figure carved in low relief within a niche high on a rock face. Its raised hand and treatment of the robe are features through which specialists compare Buddhist imagery. It is not a written itinerary left by a traveller, and it should not be presented as though it supplied a named patron or exact date without further evidence."},{"type":"paragraph","text":"The comparison with Danyor clarifies what each source can do. A text may preserve names or titles, if securely read. An image can reveal iconographic choices and the significance of a particular location. Neither automatically proves how far a political authority extended or which route every traveller followed through the region."},{"type":"heading","level":2,"text":"Connections need precise claims"},{"type":"paragraph","text":"Gilgit’s position invites narratives of exchange across mountains, but a broad crossroads label should not replace analysis. The origin of a script, the language of a text, the affiliation of a ruler and the movement of an artist are separate questions. They may intersect, but one cannot simply stand in for the others."},{"type":"paragraph","text":"These stone records are most compelling when their limits remain visible. Do not trace letters, wet a surface or climb towards an image to improve a photograph. Specialist documentation should preserve the evidence rather than alter it. Danyor and Kargah offer access to different historical worlds; the task is to explain those worlds without making the stone say more than can securely be read."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Gilgit-Baltistan","Regional History"],"province":"Gilgit-Baltistan","district":"Gilgit","relatedDistrictIds":["gilgit-baltistan-gilgit"],"provinceRegionIds":["gilgit-baltistan"],"relatedHeritageIds":["major-doam-7664","major-doam-7638"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Gilgit and its inscriptions in stone","description":"Danyor’s inscription and Kargah’s carved Buddha reveal different forms of evidence for Gilgit’s connections—and the care required to interpret stone records.","primaryKeyword":"Gilgit historical inscriptions","socialTitle":"Gilgit and its inscriptions in stone","socialDescription":"Danyor’s inscription and Kargah’s carved Buddha reveal different forms of evidence for Gilgit’s connections—and the care required to interpret stone records."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Danyor Rock Inscription","url":"https://doam.gov.pk/public/sites/7664","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Kargah Buddha","url":"https://doam.gov.pk/public/sites/7638","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"I. Inscriptions de Gilgit","url":"https://www.persee.fr/doc/befeo_0336-1519_1978_num_65_1_3904?pageId=T1_4","publisher":"Gérard Fussman / Bulletin de l’École française d’Extrême-Orient","accessDate":"2026-10-22","section":"p4"},{"title":"Inscription de Danyor: photographic archive record","url":"https://francearchives.gouv.fr/facomponent/f2f22b2f09d799251ac8ff37075b91c0f6463b8d","publisher":"FranceArchives / Collège de France","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. Danyorexacttranslation/datewithheldpendingspecialistepigraphicreview; Fussmanp4readnotwhole64pp.1976photoarchiveverifiedmetadataonly. DOAMonlyprotectedsiteclaimoutdatednotrepeated. Kargahnotcalledinscription.","editorialReason":"Use dated or attributable records to frame regional connections cautiously.","sortOrder":357}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-bhimber-and-the-architecture-of-a-route','bhimber-and-the-architecture-of-a-route','review','{"id":"story-bhimber-and-the-architecture-of-a-route","type":"story","slug":"bhimber-and-the-architecture-of-a-route","title":"Bhimber and the architecture of a route","summary":"Bhimber’s mosque and Saadabad sarai reveal different needs along a regional route, while careful geography prevents unrelated structures being folded into one itinerary.","body":[{"type":"paragraph","text":"A route becomes visible through the places that support movement as well as through the road itself. Around Bhimber, the recorded sarai at Saadabad and the monument catalogued as the Mughal Mosque offer two different kinds of evidence. One organises temporary accommodation; the other provides a space for worship. Their relationship is regional, not proof that they were commissioned together."},{"type":"paragraph","text":"The federal inventory locates Saadabad Caravan Sarai near Samahni and describes a substantial enclosed courtyard with rooms around its perimeter. Gateways, guardrooms and corner bastions give the building a controlled edge. The repeated cells suggest provision for multiple occupants, while stairs and roof access add another dimension to its arrangement."},{"type":"heading","level":2,"text":"Movement includes stopping"},{"type":"paragraph","text":"Such a building makes sense only when a journey is understood as more than progress along a line. People require rest, shelter and places to organise onward movement. A sarai gives those needs an architectural form. Its entrance regulates the transition from the road outside to a shared interior, making accommodation and supervision part of the same spatial system."},{"type":"paragraph","text":"The physical arrangement does not tell us the identity of every traveller or what goods passed through. Those questions need accounts, inscriptions or other documentary evidence. An impressive gateway should not become an excuse to populate the courtyard with an imagined royal procession. The ordinary logistics of staying are already an important historical subject."},{"type":"heading","level":2,"text":"A different institution in Bhimber"},{"type":"paragraph","text":"The mosque’s official description records a compact square plan, local stone construction and a plastered exterior with arched features. This is a different scale and function from the sarai. Comparing the two can illuminate the range of institutions associated with settlement and movement without assuming that the mosque existed primarily for travellers."},{"type":"paragraph","text":"The catalogue’s Mughal-period classification is broad. It does not establish one exact building year or identify a patron whose name is absent from the record. Nor does proximity within a district establish that two monuments lay on an unchanged road alignment. Routes can shift while some institutions remain important locally."},{"type":"heading","level":2,"text":"Keep the geography honest"},{"type":"paragraph","text":"Regional heritage accounts sometimes accumulate attractive buildings until the resulting itinerary looks more complete than the evidence permits. A bath or stepped well in another district cannot be moved into Bhimber’s story merely because it belongs to a broadly similar historical tradition. Each place needs its own location, identity and evidence of connection."},{"type":"paragraph","text":"Saadabad and the mosque are sufficient to begin a meaningful comparison. Their plans show different responses to collective use: repeated accommodation around a courtyard and a concentrated space for prayer. A fuller route history would connect those observations with dated maps and travel records. Until then, the architecture can be explained clearly without claiming a complete sequence of royal stopping places or turning a regional connection into a precise historical itinerary."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Azad Kashmir","Regional History"],"province":"Azad Jammu and Kashmir","district":"Bhimber","relatedDistrictIds":["azad-kashmir-bhimber"],"provinceRegionIds":["azad-kashmir"],"relatedHeritageIds":["major-doam-6680","major-doam-9863"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Bhimber and the architecture of a route","description":"Bhimber’s mosque and Saadabad sarai reveal different needs along a regional route, while careful geography prevents unrelated structures being folded into one itinerary.","primaryKeyword":"Bhimber Mughal route heritage","socialTitle":"Bhimber and the architecture of a route","socialDescription":"Bhimber’s mosque and Saadabad sarai reveal different needs along a regional route, while careful geography prevents unrelated structures being folded into one itinerary."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Saadabad Caravan Sarai","url":"https://doam.gov.pk/public/sites/6680","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Mughal Mosque Bhimber","url":"https://doam.gov.pk/public/sites/9863","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Correctionapprovedbyroot: remove major-doam-10366RaniBaoli&Hammams,actuallyPalandri/Sudhnoti. Do not inventBhimberbathcomplex. Source-limitedcomparison; no exactpatron/date or guaranteedhistoricroutealignment. Allsourcedfacts<200perpage.","editorialReason":"Read mosque and sarai as related infrastructure without inventing a continuous itinerary.","sortOrder":358}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-muzaffarabad-two-forts-and-changing-river-edges','muzaffarabad-two-forts-and-changing-river-edges','review','{"id":"story-muzaffarabad-two-forts-and-changing-river-edges","type":"story","slug":"muzaffarabad-two-forts-and-changing-river-edges","title":"Muzaffarabad: two forts and changing river edges","summary":"Muzaffarabad’s Red and Black forts are separate monuments with different records; their river setting should not be used to merge their histories.","body":[{"type":"paragraph","text":"Muzaffarabad’s Red Fort and Black Fort are not alternative names for one monument. They occupy different locations and have different documentary records. Their shared association with the city makes comparison useful, but it does not justify combining their dates, functions or access arrangements into a single account."},{"type":"paragraph","text":"The federal inventory places Red Fort, also called Rutta Qila, on the western bank of the Neelum. It describes a terraced arrangement with the entrance at an upper level and associates the fort broadly with the sixteenth century. The topography is fundamental to the building: changes of level are part of its organisation, not merely a scenic backdrop."},{"type":"heading","level":2,"text":"Defence and a river setting"},{"type":"paragraph","text":"A raised riverside position can offer visibility and constrain approaches. It can also expose a structure to environmental forces and make access difficult. Those are general relationships to investigate through plans and field evidence, not a reason to assume that every wall served the same defensive purpose. A riverbank photograph cannot reveal the complete sequence of construction."},{"type":"paragraph","text":"The inventory records substantial damage in the 2005 earthquake. This provides a necessary caution when comparing older descriptions or photographs with later views. A missing stair or altered wall may reflect damage and subsequent work rather than an original design. The monument’s recent history belongs within its interpretation, not outside an account devoted only to its foundation."},{"type":"heading","level":2,"text":"A separate record for Black Fort"},{"type":"paragraph","text":"Black Fort, also identified as Gojra Fort, is catalogued on Police Line Road. Its entry associates it with the nineteenth-century historical period and reports military use with no public access. That is a different evidential and practical situation from a freely accessible visitor attraction. The catalogue should not be used to imply permission to enter or photograph restricted areas."},{"type":"paragraph","text":"The shortness of the record also limits comparison. It does not provide enough information to reconstruct the fort’s original rooms or assign a detailed sequence of alterations. The correct response is to keep that limit visible, rather than borrowing Red Fort’s history to fill the gap. Two sites can be important within the same city while being documented very unevenly."},{"type":"heading","level":2,"text":"The city around the monuments"},{"type":"paragraph","text":"Muzaffarabad’s archaeology department also records structures associated with the Jhelum and Domel, widening the view beyond the forts. River edges can contain crossings, ceremonial buildings and changing urban approaches as well as defences. A city history needs to distinguish these functions rather than reducing every riverside structure to military control."},{"type":"paragraph","text":"Reading the two forts separately is therefore the first step towards understanding their relationship. Establish the correct name and location; distinguish a historical phase from a current condition; and compare only features supported by records. The result is a more precise account of Muzaffarabad’s built landscape, in which rivers, changes of level and later urban life connect monuments without erasing the differences between them."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Azad Kashmir","Regional History"],"province":"Azad Jammu and Kashmir","district":"Muzaffarabad","relatedDistrictIds":["azad-kashmir-muzaffarabad"],"provinceRegionIds":["azad-kashmir"],"relatedHeritageIds":["major-doam-6663","major-doam-6730"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"Muzaffarabad: two forts and changing river edges","description":"Muzaffarabad’s Red and Black forts are separate monuments with different records; their river setting should not be used to merge their histories.","primaryKeyword":"Muzaffarabad forts history","socialTitle":"Muzaffarabad: two forts and changing river edges","socialDescription":"Muzaffarabad’s Red and Black forts are separate monuments with different records; their river setting should not be used to merge their histories."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Red Fort","url":"https://doam.gov.pk/public/sites/6663","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Black Fort / Gojra Fort","url":"https://doam.gov.pk/public/sites/6730","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Muzaffarabad monuments","url":"https://archaeology.ajk.gov.pk/muzaffarabad/","publisher":"AJK Tourism and Archaeology Department","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. AJKpageindexedcontextcontainschronologyerrorsnotrepeated. BlackFortcatalogueaccessrestrictionattributedandnointeriorclaims; RedFort1559narrativevsbroadtentative16c handledbroadly. No assertedbankmovement/erosionmeasurement.","editorialReason":"Distinguish separate monuments and landscape change instead of merging their histories.","sortOrder":359}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-capitals-older-places','the-capitals-older-places','review','{"id":"story-the-capitals-older-places","type":"story","slug":"the-capitals-older-places","title":"The capital’s older places","summary":"Saidpur, Sarai Kharbuza and Shah Allah Ditta reveal different histories within the capital’s landscape before and alongside the planned city.","body":[{"type":"paragraph","text":"Islamabad’s planned form can make its landscape seem to begin with the modern capital. Older settlements, religious buildings and route infrastructure show otherwise. Saidpur, Sarai Kharbuza and Shah Allah Ditta preserve different kinds of evidence for places that cannot be understood solely through the city’s sector plan."},{"type":"paragraph","text":"The federal inventory describes Saidpur’s religious complex as including temples and a dharamshala. Its architectural record identifies brick construction and a principal shrine with a domed superstructure. These are specific buildings within a settlement, not generic reminders of an undefined ancient past. Their religious identities and uses deserve to remain clear even when the surrounding village acquires new visitor-oriented functions."},{"type":"heading","level":2,"text":"A settlement is more than its oldest building"},{"type":"paragraph","text":"A temple can provide a focal point for understanding Saidpur, but it cannot stand for every household or period of village life. Buildings of worship, accommodation and ordinary residence organise different kinds of access. The relationship between them is part of the settlement’s history. Treating the entire place as a decorative heritage quarter risks obscuring those distinctions."},{"type":"paragraph","text":"Sarai Kharbuza introduces movement through the region. Its catalogue describes an enclosure with opposing gateways, accommodation cells and verandas, together with a mosque in one corner. It also records repairs and a reported older water feature. This is evidence of alteration within a route-related institution, rather than an intact single-period complex waiting outside modern history."},{"type":"heading","level":2,"text":"Natural shelter and human modification"},{"type":"paragraph","text":"At Shah Allah Ditta, the record describes two natural rock shelters beside a spring. Added walls, plaster, a platform and water-management features indicate human use and modification. The geological age of a shelter is not the age of its occupation, and the presence of a later wall does not date every activity within it. Those questions require archaeological context rather than a single impressive antiquity claim."},{"type":"paragraph","text":"The spring and associated channel and tank make water part of the interpretation. A shelter is not simply an isolated cavity in a hillside: its relationship with a dependable resource may help explain use. Yet the significance of water does not establish the identity of every group associated with the place or prove a continuous occupation sequence."},{"type":"heading","level":2,"text":"Several histories inside the capital’s landscape"},{"type":"paragraph","text":"Together, the three places show why pre-capital history cannot be reduced to one civilisation or one route. Saidpur contributes evidence of settlement and religious institutions; Sarai Kharbuza of accommodation and movement; Shah Allah Ditta of shelter and water. Their differences are precisely what makes the comparison useful."},{"type":"paragraph","text":"Accurate geography matters as well. Nearby places outside Islamabad’s administrative boundary retain their own districts and histories; they need not be absorbed into the capital to make its heritage richer. A planned city can coexist with older places without having created or exhausted their significance. Recognising those places allows Islamabad to be read as a contemporary urban project within an already inhabited landscape, rather than as an entirely new beginning."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Islamabad","Regional History"],"province":"Islamabad","district":null,"relatedDistrictIds":["islamabad-islamabad"],"provinceRegionIds":["islamabad"],"relatedHeritageIds":["major-doam-6230","major-doam-6227","major-doam-6344"],"relatedStoryIds":[],"contentType":"regional-history","seo":{"title":"The capital’s older places","description":"Saidpur, Sarai Kharbuza and Shah Allah Ditta reveal different histories within the capital’s landscape before and alongside the planned city.","primaryKeyword":"Islamabad heritage before capital","socialTitle":"The capital’s older places","socialDescription":"Saidpur, Sarai Kharbuza and Shah Allah Ditta reveal different histories within the capital’s landscape before and alongside the planned city."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Said Pur Temple Complex","url":"https://doam.gov.pk/public/sites/6230","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Sarai Kharbuza","url":"https://doam.gov.pk/public/sites/6227","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Shah Allah Ditta Caves","url":"https://doam.gov.pk/public/sites/6344","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. Saidpur/Sarai entriesclose-readsavedofficialcatalogueafterlive timeouts. Cavesnaturalagevsoccupationexplicit; no unsupportedBuddhistdating/Alexanderstory. AllthreeactualIslamabaddistrict; do not importTaxila intoICT.","editorialReason":"Show pre-capital buildings and settlements without claiming the area was empty before planning.","sortOrder":360}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-iqbal-between-house-manuscript-and-public-memory','iqbal-between-house-manuscript-and-public-memory','review','{"id":"story-iqbal-between-house-manuscript-and-public-memory","type":"story","slug":"iqbal-between-house-manuscript-and-public-memory","title":"Iqbal between house, manuscript and public memory","summary":"A Lahore house, a private notebook and a later tomb offer three different ways of encountering Muhammad Iqbal.","body":[{"type":"paragraph","text":"Iqbal’s presence in Lahore is not contained in a single monument. A house locates part of his daily life; a notebook preserves thinking that was not originally a public address; a tomb presents a later act of collective remembrance. Putting these records beside one another makes a more interesting encounter than treating every object associated with the poet as an illustration of an already completed legend."},{"type":"paragraph","text":"Javid Manzil belongs to the final years of his life. The federal archaeological catalogue records his move there in May 1935 and his death in the house in April 1938. It also preserves an unusually domestic detail: an agreement with his son Javed for the use of four front rooms. Such information places the celebrated writer within a household, property arrangements and a limited sequence of rooms, rather than an abstract national landscape."},{"type":"heading","level":2,"text":"A notebook is not a monument"},{"type":"paragraph","text":"Stray Reflections takes the reader into a different kind of space. In his account of the notebook, editor Khurram Ali Shafique explains that Iqbal entered thoughts during 1910, selected some for publication in 1917, and that the complete notebook appeared in 1961 under Javid Iqbal’s editorship. The Iqbal Academy’s catalogue identifies a later edition edited by Javid Iqbal and Shafique. Composition, selection and publication are therefore separate events."},{"type":"paragraph","text":"One entry discussed by Shafique concerns seeing Halley’s comet in May 1910. Its interest is not a prediction or an easily extracted motivational saying. It sets an immense astronomical cycle against the brevity of an individual life. Read in a notebook, that encounter allows hesitation and changing perspective. Detached from its date and surrounding entries, the same thought could become a misleading statement of a fixed philosophy."},{"type":"paragraph","text":"The manuscript question remains important even when reading a printed edition. Handwriting, corrections and page sequence can establish things that a typeset transcription cannot. This article has not inspected an original notebook, and the existence of a published edition should not be presented as proof that a particular manuscript is currently displayed in a particular museum room."},{"type":"heading","level":2,"text":"The work of commemoration"},{"type":"paragraph","text":"The tomb near Badshahi Mosque is a third record. The archaeological catalogue dates its red-sandstone building to 1951 and identifies the marble cenotaph as an Afghan government gift. These are facts about remembrance after Iqbal’s death, not the circumstances in which he wrote. Material, setting and inscription help explain how a public image of the poet was made visible."},{"type":"paragraph","text":"A useful reading route can therefore move between three questions: where did he live, how did a text take shape, and how was he subsequently remembered? None cancels the others. Keeping them distinct gives visitors room to encounter Iqbal as a working writer and thinker, while also recognising the institutions, family members and readers who have carried his memory forward."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Punjab","Cultural Figures"],"province":"Punjab","district":"Lahore","relatedDistrictIds":["punjab-lahore"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-9776","major-doam-6498"],"relatedStoryIds":[],"contentType":"personality","seo":{"title":"Iqbal between house, manuscript and public memory","description":"A Lahore house, a private notebook and a later tomb offer three different ways of encountering Muhammad Iqbal.","primaryKeyword":"Muhammad Iqbal heritage","socialTitle":"Iqbal between house, manuscript and public memory","socialDescription":"A Lahore house, a private notebook and a later tomb offer three different ways of encountering Muhammad Iqbal."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Javid Manzil","url":"https://doam.gov.pk/public/sites/9776","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Tomb of Dr. Muhammad Iqbal","url":"https://doam.gov.pk/public/sites/6498","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Stray Reflections: catalogue record","url":"https://iqbalcyberlibrary.net/en/844.html","publisher":"Iqbal Academy Pakistan","accessDate":"2026-10-22"},{"title":"Stray reflections","url":"https://marghdeen.com/2003/11/stray-reflections/","publisher":"Khurram Ali Shafique","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"No manuscript inspected. Bibliographical record and editor commentary distinguish notebook composition and later publication. House/tomb catalogue facts paraphrased; no quotations.","editorialReason":"Use tangible and textual records to distinguish a life from later commemoration.","sortOrder":361}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-sadequains-mural-as-a-public-commission','sadequains-mural-as-a-public-commission','review','{"id":"story-sadequains-mural-as-a-public-commission","type":"story","slug":"sadequains-mural-as-a-public-commission","title":"Sadequain’s mural as a public commission","summary":"Sadequain’s Lahore ceiling and State Bank mural show how institutions shape the making, viewing and afterlife of public art.","body":[{"type":"paragraph","text":"A public mural is more than a large painting. Its subject meets an institution, an architectural surface and an audience that may have arrived for another purpose. Sadequain’s work at Lahore Museum makes that relationship unusually clear: the museum’s own collection account identifies a ceiling mural made specifically for its building. Visitors encounter art not only at eye level, as a framed object, but overhead, as part of the place through which they move."},{"type":"paragraph","text":"The museum’s records do not agree in every detail. Its main website calls the work Evolution of Mankind and dates it to 1974; its contribution to Google Arts & Culture labels the ceiling work Quest for Knowledge and dates it to 1973. These descriptions support an early-1970s setting, but they should not be silently combined into a precise chronology. The differences deserve curatorial reconciliation before a definitive catalogue entry is published."},{"type":"heading","level":2,"text":"Knowledge as an institutional subject"},{"type":"paragraph","text":"The shared emphasis is the human pursuit of knowledge. In a museum, that theme speaks to the institution’s own task of collecting and interpreting objects. The ceiling also changes the practical experience of looking. A visitor must adjust position and distance, while the architecture determines what can be seen together. Those conditions distinguish a mural from a reproduction cropped to fit a screen."},{"type":"paragraph","text":"A second commission provides a useful comparison. The State Bank Museum’s annual report describes the mural commonly known as Treasures of Time as a work created for the bank’s Karachi library in 1961. It identifies a sequence of intellectual figures, including an image of the artist taking his own pulse to a physician. The setting was therefore not originally a conventional art gallery: a financial institution placed an expansive account of intellectual achievement in a space for reading."},{"type":"paragraph","text":"In 2015 the museum translated that mural into a colouring-book publication. This is another stage in the work’s public life. An image designed to surround or confront an adult viewer became material for closer, page-by-page educational engagement. The change of format is significant even without judging whether one experience is more authentic than another."},{"type":"heading","level":2,"text":"A commission has an afterlife"},{"type":"paragraph","text":"The State Bank’s collection page now situates Sadequain’s paintings alongside collages and other museum holdings. That institutional custody is part of the story, not merely a footnote to the artist’s biography. Display decisions, documentation and conservation determine whether a public work remains accessible and intelligible after its original room changes function."},{"type":"paragraph","text":"For visitors, the rewarding question is consequently not only who painted the mural. Ask what the building asked the painting to do, how its physical position directs attention, and what information accompanies it now. For editors, the corresponding responsibility is to keep titles, dates, original locations and later displays distinct. A celebrated signature does not remove the need for precise object histories; it makes that work more important."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Museums","Punjab","Cultural Figures"],"province":"Punjab","district":"Lahore","relatedDistrictIds":["punjab-lahore"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-10162"],"relatedStoryIds":[],"contentType":"personality","seo":{"title":"Sadequain’s mural as a public commission","description":"Sadequain’s Lahore ceiling and State Bank mural show how institutions shape the making, viewing and afterlife of public art.","primaryKeyword":"Sadequain Lahore Museum mural","socialTitle":"Sadequain’s mural as a public commission","socialDescription":"Sadequain’s Lahore ceiling and State Bank mural show how institutions shape the making, viewing and afterlife of public art."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Contemporary Paintings Gallery","url":"https://artsandculture.google.com/story/rQUhQmx0zB8A8A","publisher":"Lahore Museum","accessDate":"2026-10-22"},{"title":"Collection highlights: Evolution of Mankind","url":"https://lahoremuseum.punjab.gov.pk/","publisher":"Lahore Museum","accessDate":"2026-10-22"},{"title":"Annual Report 2014–2015: publication on the mural","url":"https://www.sbp.org.pk/museum/images/Annual_Report_2014-2015.pdf","publisher":"State Bank Museum","accessDate":"2026-10-22"},{"title":"Art Gallery collections","url":"https://www.sbp.org.pk/museum/the-collections","publisher":"State Bank of Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"PNCA-branded pnca.org.pk lead rejected as official evidence because footer disclaims PNCA affiliation. Lahore Museum official records disagree over 1973/1974, title and panel count: date described only as early 1970s, no panel total. SBP annual report read as indexed primary text after PDF 403. No image inspected; no invented visual details.","editorialReason":"Study a specific documented work and setting rather than write a generic artist biography.","sortOrder":362}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-anna-molka-ahmed-and-the-building-of-art-education','anna-molka-ahmed-and-the-building-of-art-education','review','{"id":"story-anna-molka-ahmed-and-the-building-of-art-education","type":"story","slug":"anna-molka-ahmed-and-the-building-of-art-education","title":"Anna Molka Ahmed and the building of art education","summary":"Anna Molka Ahmed’s contribution becomes clearer through the practical history of programmes, teaching and exhibitions at Punjab University.","body":[{"type":"paragraph","text":"Art education leaves a less obvious heritage than a monument. Its traces include a programme that continues after its founder, the habits students acquire, exhibition catalogues and the possibility of making a sustained living through art. Anna Molka Ahmed’s work at Punjab University should be understood through these structures as well as through her reputation as a painter."},{"type":"paragraph","text":"The university’s account places the founding of its Fine Arts Department in 1940. Its College of Art and Design prospectus adds a more detailed institutional sequence: enrolments began in June 1942, a master’s programme in Fine Arts followed in 1955, and postgraduate Graphic Design was established in 1964. Foundation and first enrolment are different milestones; treating the two dates as a contradiction would obscure how an institution actually develops."},{"type":"heading","level":2,"text":"Building a place to learn"},{"type":"paragraph","text":"These stages matter because an art department requires more than a talented teacher. A continuing course needs admissions, teaching time, assessment and resources. A postgraduate programme creates a different level of study from an introductory class, while Graphic Design places visual communication beside the fine arts within the institution. The recorded sequence suggests expansion through sustained administrative work, not a single ceremonial founding moment."},{"type":"paragraph","text":"Punjab University’s commemorative account also remembers Ahmed taking students outside the classroom to paint. Outdoor study changes the relationship between instruction and surroundings: light, scale and a changing scene cannot be arranged as readily as a studio exercise. This is a useful way to think about educational method without assuming that every former student painted alike or that one teacher single-handedly determined a national style."},{"type":"paragraph","text":"The Asian Art Resource Room records her organisation of exhibitions and publication of catalogues at the university during the 1950s. Exhibitions add another stage to education. Work moves from the private exchange between teacher and student into a setting where it can be compared, discussed and remembered. Catalogues may preserve that encounter after the display has closed, although the contents of an individual catalogue still need to be consulted before naming its participants."},{"type":"heading","level":2,"text":"The institution as an archive"},{"type":"paragraph","text":"The university subsequently named an art gallery for Ahmed. Such commemoration can introduce new audiences to a founder, but it should also lead back to less spectacular records: prospectuses, course changes, student work and teaching correspondence. These can show what opportunities existed, who could take them up and how programmes changed over time."},{"type":"paragraph","text":"An account centred only on awards risks making education appear to be the by-product of individual greatness. An institutional reading asks a harder question: what did Ahmed help make possible for people who came after her? The milestones recorded by Punjab University provide a starting answer in the growth of sustained study, specialist programmes and public presentation. Further work with its archives could turn that outline into a more detailed history of students, colleagues and the practical culture of the classroom."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Punjab","Cultural Figures"],"province":"Punjab","district":"Lahore","relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"personality","seo":{"title":"Anna Molka Ahmed and the building of art education","description":"Anna Molka Ahmed’s contribution becomes clearer through the practical history of programmes, teaching and exhibitions at Punjab University.","primaryKeyword":"Anna Molka Ahmed art education","socialTitle":"Anna Molka Ahmed and the building of art education","socialDescription":"Anna Molka Ahmed’s contribution becomes clearer through the practical history of programmes, teaching and exhibitions at Punjab University."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Google pays tribute to Anna Molka Ahmed","url":"https://pu.edu.pk/home/section/allpress/10687","publisher":"University of the Punjab","accessDate":"2026-10-22"},{"title":"College of Art and Design prospectus: The Founder","url":"https://pu.edu.pk/images/file/Prospectuses/Prospectus-CAD.pdf","publisher":"University of the Punjab","accessDate":"2026-10-22"},{"title":"Anna Molka Ahmed works at the University of Punjab","url":"https://asianart-gateway.jp/en/exploring/chronology/959/","publisher":"Asian Art Resource Room","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"University prospectus available as indexed primary pages; full PDF too large for reader. Dates 1940 foundation and 1942 enrolments deliberately distinguished. Unsupported university press-release superlatives about first-ever national exhibitions not repeated. No named painting formally analysed without catalogue evidence.","editorialReason":"Focus on an institutional contribution through university records and artworks.","sortOrder":363}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-yasmeen-lari-conservation-and-the-people-who-use-buildings','yasmeen-lari-conservation-and-the-people-who-use-buildings','review','{"id":"story-yasmeen-lari-conservation-and-the-people-who-use-buildings","type":"story","slug":"yasmeen-lari-conservation-and-the-people-who-use-buildings","title":"Yasmeen Lari: conservation and the people who use buildings","summary":"Yasmeen Lari’s work connects conservation with everyday building knowledge, while raising questions about evidence, maintenance and community agency.","body":[{"type":"paragraph","text":"Yasmeen Lari’s career makes it possible to discuss conservation without confining it to the repair of monumental buildings. The Architekturzentrum Wien’s 2023 exhibition placed her modernist practice, heritage work and later self-build projects within one account. That framing is valuable because it asks how knowledge moves between preserving an existing structure and helping people construct something they can use now."},{"type":"paragraph","text":"The exhibition drew on photographs, drawings and documents from Lari’s archive. It described the Heritage Foundation’s interest in both recognised monuments and ordinary buildings, and connected her later work with local construction techniques and materials such as bamboo, earth and lime. This is an institutional interpretation of a career, rather than a complete independent assessment of every project’s performance."},{"type":"heading","level":2,"text":"Two designs, different scales of use"},{"type":"paragraph","text":"The Lahore Biennale Foundation’s presentation identifies Lari Octagon Green as a design developed after the October 2015 earthquake. Its account explains a combination of a southern chaura-like roof form with the principle of a cross-braced northern frame, using bamboo and foldable parts. The significance is adaptation: inherited forms become resources for a new construction problem, rather than patterns reproduced merely to look traditional."},{"type":"paragraph","text":"The same presentation dates Pakistan Chulah to 2014 and describes a raised cooking platform using sun-dried mud and lime. Here the architectural unit is not a whole house. It is a place for an everyday activity, with bodily comfort, smoke, fuel and water exposure among the design concerns. Recognising a cooking place as architecture broadens what enters a heritage discussion and whose knowledge becomes relevant to it."},{"type":"paragraph","text":"Those descriptions establish intentions and methods. They do not, by themselves, demonstrate that every installed example performs identically, remains maintained or delivers a particular reduction in fuel use. Such claims require evidence about actual installations, testing conditions and the people using them. A material can be appropriate in one configuration without being a universal answer to every building risk."},{"type":"heading","level":2,"text":"Who retains the knowledge?"},{"type":"paragraph","text":"The most consequential question is what remains with a community after a project team leaves. Can residents repair a damaged element? Are replacement materials available? Who controls the decisions about layout and modification? These are useful tests of a self-build model, but this article has not interviewed users and should not supply invented answers on their behalf."},{"type":"paragraph","text":"Conservation also depends on comparable relationships. A documented technique is not sustained simply because it appears in a report; someone must have the skill, authority and resources to practise it. Lari’s work makes that connection visible across otherwise separate categories of monument, shelter and domestic infrastructure."},{"type":"paragraph","text":"The result is a richer subject than a sequence of prizes or heroic claims. It concerns how architectural expertise can be shared, revised and held accountable to use. Appreciating that ambition does not require suspending scrutiny. It requires taking residents’ experience, maintenance and long-term evidence as seriously as an architect’s original design."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Conservation","Cultural Figures"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"personality","seo":{"title":"Yasmeen Lari: conservation and the people who use buildings","description":"Yasmeen Lari’s work connects conservation with everyday building knowledge, while raising questions about evidence, maintenance and community agency.","primaryKeyword":"Yasmeen Lari heritage conservation","socialTitle":"Yasmeen Lari: conservation and the people who use buildings","socialDescription":"Yasmeen Lari’s work connects conservation with everyday building knowledge, while raising questions about evidence, maintenance and community agency."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Yasmeen Lari: Architecture for the Future","url":"https://www.azw.at/en/event/yasmeen-lari/","publisher":"Architekturzentrum Wien","accessDate":"2026-10-22"},{"title":"Lari Octagon Green and Pakistan Chulah","url":"https://lahorebiennale.org/lb03-artists/yasmeen-lari/","publisher":"Lahore Biennale Foundation","accessDate":"2026-10-22"},{"title":"Founders","url":"https://hw.heritagefoundationpak.org/founders","publisher":"Heritage Foundation of Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Institutional exhibition descriptions used for design intentions/materials, not as independent engineering or impact certification. No numerical beneficiary claims or guaranteed flood/fire/health performance. Users not interviewed; participation questions explicitly analytical.","editorialReason":"Examine documented practice and community agency without adopting promotional impact claims uncritically.","sortOrder":364}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-noorjehan-bilgrami-and-the-documentation-of-ajrak','noorjehan-bilgrami-and-the-documentation-of-ajrak','review','{"id":"story-noorjehan-bilgrami-and-the-documentation-of-ajrak","type":"story","slug":"noorjehan-bilgrami-and-the-documentation-of-ajrak","title":"Noorjehan Bilgrami and the documentation of ajrak","summary":"Noorjehan Bilgrami’s ajrak research shows how a craft can be documented through writing, film and attention to the sequence of making.","body":[{"type":"paragraph","text":"A finished piece of ajrak can be admired without revealing the decisions that produced it. Repeated patterns conceal repeated acts of judgement: aligning a block, preparing a resist, washing cloth and assessing colour. Noorjehan Bilgrami’s contribution to craft documentation is to direct attention from the attractive surface towards a process, and from a generic textile label towards knowledge held by makers."},{"type":"paragraph","text":"Sahapedia’s contributor record links her research to the book Sindh jo Ajrak and subsequently to the documentary Sun, Fire, River, Ajrak: Cloth from the Soil of Sindh. A related paper appears in the proceedings of the Textile Society of America’s 2000 symposium. These are different forms of record, intended for different kinds of encounter; they should not be treated as interchangeable evidence."},{"type":"heading","level":2,"text":"Recording a sequence"},{"type":"paragraph","text":"Bilgrami’s illustrated Sahapedia account identifies processes including steaming, preparation of a mud resist and resist printing. Its captions distinguish stages rather than presenting all visible activity as simply dyeing. That precision is important. A description that collapses the sequence into one colourful photograph loses the relationship between preparation, protected areas and later colour development."},{"type":"paragraph","text":"Film can potentially preserve movement and timing that a still image cannot. A book can place terms, diagrams or comparisons side by side. A conference paper can advance an argument and expose it to specialist discussion. This article has not viewed the documentary itself, so it does not claim that a particular action or named maker appears in it. The documented existence of the film is nevertheless part of the history of how ajrak has been communicated."},{"type":"paragraph","text":"The 2000 paper’s abstract also proposes connections between ajrak, ancient material culture and patterned textiles found farther west. Such comparisons are a research question, not automatic proof of an uninterrupted technique stretching across millennia. A similar motif may travel, recur or receive a new interpretation. Establishing continuity requires evidence of materials, methods and intervening examples, not resemblance alone."},{"type":"heading","level":2,"text":"Documentation is a relationship"},{"type":"paragraph","text":"The distinction matters because craft histories can unintentionally give an ancient object more authority than a living practitioner. A maker’s vocabulary and explanation deserve careful recording in their own right, even when a proposed archaeological connection remains uncertain. Conversely, an account of inherited practice is not a substitute for identifying the evidence behind a remote historical claim."},{"type":"paragraph","text":"For future documentation, useful questions include who names each stage, whether terms vary between workshops, and how makers want their contributions credited. Recording permission and the intended use of photographs should be agreed rather than assumed. These are recommendations for responsible research, not claims that this article has conducted new interviews."},{"type":"paragraph","text":"Bilgrami’s body of documentation offers a starting point for that work. It makes ajrak legible as accumulated practical knowledge while leaving room to examine how research itself selects, arranges and interprets. The next step is not merely to reproduce its most memorable images, but to retain the specificity of process and the agency of the people who continue to make the cloth."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Sindh","Cultural Figures"],"province":"Sindh","district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"personality","seo":{"title":"Noorjehan Bilgrami and the documentation of ajrak","description":"Noorjehan Bilgrami’s ajrak research shows how a craft can be documented through writing, film and attention to the sequence of making.","primaryKeyword":"Noorjehan Bilgrami ajrak research","socialTitle":"Noorjehan Bilgrami and the documentation of ajrak","socialDescription":"Noorjehan Bilgrami’s ajrak research shows how a craft can be documented through writing, film and attention to the sequence of making."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Ajrak: Cloth from the Soil of Sindh","url":"https://digitalcommons.unl.edu/tsaconf/771/","publisher":"Textile Society of America / University of Nebraska–Lincoln","accessDate":"2026-10-22"},{"title":"Noorjehan Bilgrami contributor profile","url":"https://www.sahapedia.org/saha-user/noorjehan-bilgrami","publisher":"Sahapedia","accessDate":"2026-10-22"},{"title":"Ajrak: The Sacred Cloth of Sindh","url":"https://www.sahapedia.org/ajrak-the-sacred-cloth-of-sindh","publisher":"Noorjehan Bilgrami / Sahapedia","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"2000 conference abstract and Sahapedia text/captions close-read; conference PDF inaccessible and documentary not watched. No claim of observing film sequences. Ancient unbroken lineage and priest-king motif identification treated as interpretive proposals, not established continuity. Source budget kept below 200 derived words per source.","editorialReason":"Read a maker-researcher’s published work as a contribution to craft documentation.","sortOrder":365}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-nusrat-fateh-ali-khan-across-recording-and-live-performance','nusrat-fateh-ali-khan-across-recording-and-live-performance','review','{"id":"story-nusrat-fateh-ali-khan-across-recording-and-live-performance","type":"story","slug":"nusrat-fateh-ali-khan-across-recording-and-live-performance","title":"Nusrat Fateh Ali Khan across recording and live performance","summary":"Three documented releases separate Nusrat Fateh Ali Khan’s live performance, studio collaboration and the later life of a recording archive.","body":[{"type":"paragraph","text":"The date printed on an album is not always the date of the performance it contains. Nusrat Fateh Ali Khan’s recording history makes that distinction especially useful. A live festival recording, a studio collaboration and a later archival release can reach listeners through similar streaming interfaces while preserving very different encounters with the musicians."},{"type":"paragraph","text":"Real World’s Live at WOMAD 1985 is a clear example. The label identifies the performance as taking place on 20 July 1985 at Mersea Island in Essex, but dates the album’s release to 2019. Its credits describe an eight-track analogue recording, followed much later by digitisation, restoration, mixing and mastering. The familiar word live therefore names the original performance setting, not an absence of subsequent technical work."},{"type":"heading","level":2,"text":"Performance and release are separate events"},{"type":"paragraph","text":"The credits also make a collective process visible. Nusrat appears with his party, while the surviving sound passes through the hands of recording and restoration specialists before reaching the listener. Naming those roles does not diminish the singer’s achievement. It identifies what kind of object the album is and avoids presenting a commercial release as an untouched window onto a night several decades earlier."},{"type":"paragraph","text":"Chain of Light supplies a different chronology. Real World’s announcement describes recordings made at its studios in April 1990 and scheduled for release in September 2024, after rediscovery in its tape archive. The label places these sessions alongside work on Mustt Mustt with producer Michael Brook. Traditional ensemble recording and a crossover collaboration were therefore being pursued in the same period, rather than occupying neatly separated stages of a career."},{"type":"paragraph","text":"This matters when accounts divide music into a supposedly pure early form and a compromised later one. The session history supports a more complicated picture of simultaneous approaches. It does not tell us that every listener experienced them in the same way, or that one release can stand for all the contexts in which qawwali was performed."},{"type":"heading","level":2,"text":"Listening with the record in view"},{"type":"paragraph","text":"A useful comparison begins with the documentation: when and where was the music recorded, which performers are credited, and what happened before publication? Only then should an account move to audible features. This article has checked release records rather than conducted a close listening session, so it does not invent claims about a particular improvisation, audience response or transition within a track."},{"type":"paragraph","text":"The archive has its own history as well. Tapes can remain unpublished, be rediscovered and acquire a new audience under a new title. A late release is evidence of continuing custodianship and editorial choice, not a new performance by an artist who has died."},{"type":"paragraph","text":"For heritage discovery, Nusrat’s recordings are consequently more than a playlist of famous titles. They invite attention to ensemble work, institutions of recording and the changing ways a performance survives. Keeping those layers visible allows admiration to become a more precise form of listening, with the people and processes around the voice remaining part of the story."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Cultural Figures"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"personality","seo":{"title":"Nusrat Fateh Ali Khan across recording and live performance","description":"Three documented releases separate Nusrat Fateh Ali Khan’s live performance, studio collaboration and the later life of a recording archive.","primaryKeyword":"Nusrat Fateh Ali Khan recordings","socialTitle":"Nusrat Fateh Ali Khan across recording and live performance","socialDescription":"Three documented releases separate Nusrat Fateh Ali Khan’s live performance, studio collaboration and the later life of a recording archive."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Live at WOMAD 1985","url":"https://realworldrecords.com/releases/live-at-womad-1985/","publisher":"Real World Records","accessDate":"2026-10-22"},{"title":"Real World Records to release lost album by Nusrat Fateh Ali Khan","url":"https://realworldrecords.com/news/real-world-records-to-release-lost-album-by-the-late-nusrat-fateh-ali-khan/","publisher":"Real World Records","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Release metadata/label account read, no audio listening claimed. Each label page under 200 derived words. Promotional first-ever audience claim and 600-year genealogy omitted. Analysis distinguishes recording, mastering and publication; no lyrics quoted.","editorialReason":"Distinguish recording history, collaborators and performance settings through primary label records.","sortOrder":366}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-shah-abdul-latif-as-a-reader-of-landscapes','shah-abdul-latif-as-a-reader-of-landscapes','review','{"id":"story-shah-abdul-latif-as-a-reader-of-landscapes","type":"story","slug":"shah-abdul-latif-as-a-reader-of-landscapes","title":"Shah Abdul Latif as a reader of landscapes","summary":"Shah Abdul Latif’s landscapes are built from work, movement and longing; selected translations show why they cannot be reduced to map pins.","body":[{"type":"paragraph","text":"A literary landscape is not simply a place mentioned in a poem. It is a setting made active by desire, work, memory and danger. In Shah Abdul Latif’s Risalo, water and dry ground, a working tool and a difficult journey can carry meanings that no map symbol can fully contain. Reading these relationships is more rewarding than assembling a list of places the poet supposedly visited."},{"type":"paragraph","text":"The Sindhi Language Authority’s discussion of Latif draws attention to vocabulary from occupations including pottery, metalwork, medicine, weaving and seafaring. This is an important corrective to a purely scenic reading. Landscape includes what people do and the words through which they understand it. A riverbank is not only a view; it may be a place of work, departure or uncertainty."},{"type":"heading","level":2,"text":"Looking through an identified edition"},{"type":"paragraph","text":"G. Allana’s Selections from the Risalo, republished by Sindh’s Culture Department in 2012, provides one accessible English route into this variety. Its arrangement includes sections concerned with seafarers, fishermen, wandering ascetics, spinning and rain, alongside familiar narrative figures. The selection itself shows that Latif’s imaginative geography is not confined to a single heroic journey or one kind of terrain."},{"type":"paragraph","text":"In the selected Susui verses, hardship and thirst turn a difficult journey into a test of longing. In the Noori material, the lake and fishing world remain part of the poem’s social setting rather than disappearing behind royal romance. These examples should be read as literary constructions, not field reports confirming the exact location of an event. Allana’s English also represents a translator’s choices, not a transparent substitute for every nuance of the Sindhi text."},{"type":"paragraph","text":"The occupational vocabulary discussed by the Language Authority suggests another reading exercise. Before converting an image into a general spiritual symbol, ask what practical knowledge makes it intelligible. A furnace, a tool or a vessel has a material operation. The poetic transformation gains force from that specificity; removing the working world can flatten the metaphor rather than deepen it."},{"type":"heading","level":2,"text":"A map needs room for interpretation"},{"type":"paragraph","text":"An atlas can connect a reader to Bhit Shah or to a regional landscape associated with the poetry. It should not draw a confident itinerary from every mention of a desert, mountain or harbour. Literary names, narrative geography and contemporary administrative boundaries answer different questions. A poem can preserve attachment to a place without providing survey evidence for a route."},{"type":"paragraph","text":"The most useful encounter therefore alternates between text and setting. Notice the concrete image, identify the edition and translator, and ask how the speaker’s situation changes its meaning. Where language is uncertain, a Sindhi reader’s explanation is more valuable than an invented universal gloss."},{"type":"paragraph","text":"Latif’s landscapes remain compelling because they are inhabited and felt. Work, waiting and movement give them depth. Keeping those human relations visible allows heritage interpretation to move beyond a scenic backdrop and towards the imaginative life through which places become meaningful."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Sindh","Cultural Figures"],"province":"Sindh","district":"Matiari","relatedDistrictIds":["sindh-matiari"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-10375"],"relatedStoryIds":[],"contentType":"personality","seo":{"title":"Shah Abdul Latif as a reader of landscapes","description":"Shah Abdul Latif’s landscapes are built from work, movement and longing; selected translations show why they cannot be reduced to map pins.","primaryKeyword":"Shah Abdul Latif literary landscapes","socialTitle":"Shah Abdul Latif as a reader of landscapes","socialDescription":"Shah Abdul Latif’s landscapes are built from work, movement and longing; selected translations show why they cannot be reduced to map pins."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Chapter Seven: The Period of Shah Latif","url":"https://library.sindhila.org/book/44/read/1305","publisher":"Sindhi Language Authority","accessDate":"2026-10-22"},{"title":"Selections from the Risalo, G. Allana, second edition 2012","url":"https://library-sindhi-sp-2020.s3.us-east-2.amazonaws.com/files/Selections_from_the_Risalo-G_Allana-2012-Cs.pdf","publisher":"Culture Department, Government of Sindh","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"SLA chapter occupational vocabulary and Allana selected sections/contents read; no verbatim verse. Allana-derived discussion under 200 words, SLA under 200. No literal route or travel biography inferred from poems. Full specialist Sindhi textual review required.","editorialReason":"Analyse selected literary geography with identified editions rather than retell the shrine profile.","sortOrder":367}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-bulleh-shah-reading-a-poet-beyond-famous-quotations','bulleh-shah-reading-a-poet-beyond-famous-quotations','review','{"id":"story-bulleh-shah-reading-a-poet-beyond-famous-quotations","type":"story","slug":"bulleh-shah-reading-a-poet-beyond-famous-quotations","title":"Bulleh Shah: reading a poet beyond famous quotations","summary":"An identified edition and a careful reading of poetic voice offer a better approach to Bulleh Shah than unattributed quotation cards.","body":[{"type":"paragraph","text":"A line attributed to Bulleh Shah can circulate far from the poem, edition or performance that gave it shape. Familiarity is not the same as authentication. The first useful question is therefore not whether a saying sounds sufficiently mystical, but whether it can be located in an identified text and understood within a larger poetic movement."},{"type":"paragraph","text":"Christopher Shackle’s Sufi Lyrics, published by the Murty Classical Library, offers one such point of reference. The publisher describes an edition prepared from modern Pakistani and Indian texts, with Punjabi in Gurmukhi beside an English translation. That arrangement makes editorial mediation visible: a reader encounters a poet through decisions about textual witnesses, script and translation, rather than through a supposedly self-evident quotation."},{"type":"heading","level":2,"text":"What the speaking voice is doing"},{"type":"paragraph","text":"In his chapter in Beyond Turk and Hindu, Shackle considers Bulleh Shah’s well-known poem of questioning identity. His discussion places its denials within a wider Sufi literary practice, while noting the particular force of social and religious categories in Punjabi writing. The poem’s movement cannot be reduced to a modern slogan that simply removes every distinction from the world."},{"type":"paragraph","text":"The tension is more demanding. Social identities remain recognisable enough for their limits to be challenged. Love becomes meaningful through that friction, not in a blank setting without history. This is a reading of poetic operation; it does not authorise an editor to turn the poet into the spokesperson for any present-day political position that happens to use similar language."},{"type":"paragraph","text":"A practical way to read is to follow the voice through a complete short poem. Who is addressed? Does a refrain change after the preceding lines? Does the speaker question, command, confess or mock? These features may disappear when a single translated sentence is detached from its setting. They are also reasons why two translations can emphasise different aspects without either being a simple word-for-word window onto the original."},{"type":"heading","level":2,"text":"Circulation is another history"},{"type":"paragraph","text":"The Murty publisher notes the continued presence of Bulleh Shah’s words in contemporary popular music. A performance is a further act of interpretation. Repetition, selection and musical pacing may change what an audience notices. An attribution to a singer, a lyric adaptation and an attribution to the historical poet should therefore be documented separately."},{"type":"paragraph","text":"When a circulating quotation cannot be found in a consulted edition, the responsible result is an unresolved attribution, not an assertion that the poet must have said it somewhere. Equally, failure to find a line in one selection does not prove that it is false; selections are incomplete by design."},{"type":"paragraph","text":"This approach does not make the poetry less accessible. It replaces vague reverence with a route back to the work. A named edition, an attentive reading and a clearly credited performance give readers something richer than a detached maxim: an encounter with a voice whose power depends on the language, tensions and forms in which it speaks."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Punjab","Cultural Figures"],"province":"Punjab","district":"Kasur","relatedDistrictIds":["punjab-kasur"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-10141"],"relatedStoryIds":[],"contentType":"personality","seo":{"title":"Bulleh Shah: reading a poet beyond famous quotations","description":"An identified edition and a careful reading of poetic voice offer a better approach to Bulleh Shah than unattributed quotation cards.","primaryKeyword":"Bulleh Shah poetry sources","socialTitle":"Bulleh Shah: reading a poet beyond famous quotations","socialDescription":"An identified edition and a careful reading of poetic voice offer a better approach to Bulleh Shah than unattributed quotation cards."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Sufi Lyrics, edited and translated by Christopher Shackle","url":"https://www.murtylibrary.com/books/sufi-lyrics","publisher":"Murty Classical Library of India","accessDate":"2026-10-22"},{"title":"Crossing the Boundaries in Indo-Muslim Romance","url":"https://ufdcimages.uflib.ufl.edu/AA/00/01/16/83/00001/Gilmartin_Lawrence_9781616101183.pdf","publisher":"Christopher Shackle / University Press of Florida","accessDate":"2026-10-22","section":"Chapter 2, especially printed pages 56–58"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Publisher edition description and Shackle chapter passages read. No online quote declared authentic merely by circulation, no verse quoted. Derived material per source below 200 words; original editorial reading method is not attributed research. Specialist Punjabi review remains required.","editorialReason":"Require authenticated texts and translations, checking misattributed circulating quotations.","sortOrder":368}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-khwaja-ghulam-farid-and-the-vocabulary-of-rohi','khwaja-ghulam-farid-and-the-vocabulary-of-rohi','review','{"id":"story-khwaja-ghulam-farid-and-the-vocabulary-of-rohi","type":"story","slug":"khwaja-ghulam-farid-and-the-vocabulary-of-rohi","title":"Khwaja Ghulam Farid and the vocabulary of Rohi","summary":"Rohi in Khwaja Ghulam Farid’s poetry is both a named landscape and a changing field of longing, weather and encounter.","body":[{"type":"paragraph","text":"Rohi is not an empty stage in Khwaja Ghulam Farid’s poetry. The name carries a landscape into the language of longing, but its emotional character changes. Dry ground can become a place of difficult wandering; rain can alter the scene; the same desert can be imagined as a meeting place. Reading those changes is more useful than assigning Rohi one fixed symbolic meaning."},{"type":"paragraph","text":"Shahzad Qaiser’s translation and commentary, Understanding Diwan-i-Farid, makes several such contrasts accessible to an English reader. In the selected passages considered here, separation appears through movement across desert and rocky ground, while a rainy season transforms dryness into growth. Elsewhere Rohi becomes the desired setting for an encounter with the beloved. These are brief examples from a much larger collection, not a claim to summarise its whole vocabulary."},{"type":"heading","level":2,"text":"A place name within a poem"},{"type":"paragraph","text":"The important feature is the relationship between surroundings and the speaker’s condition. Rain is not only weather information, and distance is not only a measurable interval. Yet the material setting is not disposable. The force of the image depends on knowing something of thirst, seasonal change and movement through difficult terrain."},{"type":"paragraph","text":"Qaiser places translation beside commentary and gives the passages a spiritual interpretation. Readers should keep those layers distinguishable. The English wording is a translation; the accompanying explanation is an interpreter’s account of meaning. Neither should be silently converted into a direct autobiographical statement about where Farid stood on a particular day or what route he followed."},{"type":"paragraph","text":"That distinction becomes especially important when literary material is linked to a heritage map. Kot Mithan and the physical landscape of Cholistan can provide orientation, but a poetic reference does not establish coordinates for an episode. The text may bring several forms of distance together: geographical separation, emotional absence and a spiritual search."},{"type":"heading","level":2,"text":"A vocabulary that continues to travel"},{"type":"paragraph","text":"The Poetry Translation Centre supplies a useful modern comparison. Its poem You Deserted Me in Rohi is by Shakir Shujaabadi, translated through a workshop involving Nukhbah Langah. The accompanying note identifies Rohi as an important symbol in Farid’s Saraiki mystical poetry. This is evidence of a continuing vocabulary, not permission to attribute the newer poem to Farid."},{"type":"paragraph","text":"The distinction is easy to lose when recordings, translation pages and social posts travel without their credits. Keeping the poet, translator and performer visible protects both the historical writer and the later artist. It also allows readers to notice continuity without pretending that all uses of a familiar image are identical."},{"type":"paragraph","text":"Farid’s Rohi is consequently best approached through a named edition and a small number of closely read passages. Follow how the landscape changes with the voice, and resist turning every image into a ready-made moral. The result is a more attentive literary geography: one in which a real region remains present, while poetry changes what distance, weather and belonging can mean."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Punjab","Cultural Figures"],"province":"Punjab","district":"Rajanpur","relatedDistrictIds":["punjab-rajanpur"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6191"],"relatedStoryIds":[],"contentType":"personality","seo":{"title":"Khwaja Ghulam Farid and the vocabulary of Rohi","description":"Rohi in Khwaja Ghulam Farid’s poetry is both a named landscape and a changing field of longing, weather and encounter.","primaryKeyword":"Khwaja Ghulam Farid Rohi poetry","socialTitle":"Khwaja Ghulam Farid and the vocabulary of Rohi","socialDescription":"Rohi in Khwaja Ghulam Farid’s poetry is both a named landscape and a changing field of longing, weather and encounter."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Understanding Diwan-i-Farid: translation and commentary","url":"https://apnaorg.com/books/english/divan-of-khawja-ghulam-farid-translation-and-explanation/divan-of-khawja-ghulam-farid-translation-and-explanation.pdf","publisher":"Shahzad Qaiser / Suhail Academy","accessDate":"2026-10-22","section":"Selected passages, PDF pages 269–270 and 380"},{"title":"You Deserted Me in Rohi: translation and notes","url":"https://www.poetrytranslation.org/poem/you-deserted-me-in-rohi/","publisher":"Poetry Translation Centre","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Qaiser selected translation/commentary passages read, not entire volume. PTC poem correctly attributed to Shakir Shujaabadi, not Ghulam Farid. No verse quotations. Qaiser-derived discussion under 200 words, PTC under 100. Source-limited literary analysis review draft, specialist Saraiki review required.","editorialReason":"Commission a text-led account, separate from the architecture of his shrine.","sortOrder":369}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-baba-farid-textual-memory-and-a-historic-place','baba-farid-textual-memory-and-a-historic-place','review','{"id":"story-baba-farid-textual-memory-and-a-historic-place","type":"story","slug":"baba-farid-textual-memory-and-a-historic-place","title":"Baba Farid: textual memory and a historic place","summary":"Baba Farid’s textual afterlife and the shrine at Pakpattan require related but separate histories of transmission, devotion and material change.","body":[{"type":"paragraph","text":"Baba Farid connects a historic place with a textual memory that extends beyond it. Pakpattan’s shrine is a focus of devotion and material care; verses associated with Farid have travelled through textual traditions, recitation and interpretation. These histories meet, but neither can simply authenticate every claim made about the other."},{"type":"paragraph","text":"The distinction is particularly important for the poetry preserved under Farid’s name in the Guru Granth. A 2022 study by Muhammad Tanveer Jamal and Abdul Zahoor Khan identifies questions of originality and thematic relationship as matters for historical investigation. Its abstract describes comparison with accounts of Farid’s life and teachings. That is evidence that attribution requires research, not a reason to announce that all questions have been settled without reading the full argument."},{"type":"heading","level":2,"text":"Transmission is part of the subject"},{"type":"paragraph","text":"A poem can remain meaningful through centuries of copying, recitation and interpretation. Those processes do not make it culturally less important, but they do create distinct questions. When was a text recorded? In which collection? Under what name? What language and script does a particular witness use? An English translation is another stage in that history rather than a substitute for the earlier witnesses."},{"type":"paragraph","text":"For this review draft, the scholarly article’s abstract and bibliography have been consulted, but its subscription full text has not. No disputed attribution is resolved here, and no verse is quoted as though it had been checked against a critical edition. A fuller literary treatment should involve a specialist able to assess Punjabi textual traditions and the relevant manuscript or printed evidence."},{"type":"heading","level":2,"text":"Reading the shrine as a building"},{"type":"paragraph","text":"The federal archaeological catalogue provides a different kind of record. Drawing on a study of Pakpattan’s religious architecture, it describes a small domed tomb chamber with an eastern entrance and a southern door known as the bihishti darwaza. It also distinguishes interior decorative work from older exterior inscriptions, whose dates it says cannot be assigned with certainty."},{"type":"paragraph","text":"That last qualification is valuable. An inscription on a revered building should not automatically be dated to the lifetime of the person commemorated. Repair, decoration and additions can belong to later phases. A shrine is not a sealed object left unchanged at the moment of a saint’s death; understanding its material history requires attention to the evidence for each element."},{"type":"paragraph","text":"For a visitor, these distinctions need not interrupt respect. They can deepen it by making room for the generations who have preserved the place and transmitted its associated words. A map can locate Pakpattan, but it cannot compress all those acts into one date or one authorship label."},{"type":"paragraph","text":"The strongest account therefore holds place and text together without collapsing them. It recognises devotional importance, records what the building survey actually supports, and leaves unresolved literary questions visible. That is a firmer basis for heritage interpretation than a smooth biography assembled from quotations and architectural claims whose origins have disappeared."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Punjab","Cultural Figures"],"province":"Punjab","district":"Pakpattan","relatedDistrictIds":["punjab-pakpattan"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-9694"],"relatedStoryIds":[],"contentType":"personality","seo":{"title":"Baba Farid: textual memory and a historic place","description":"Baba Farid’s textual afterlife and the shrine at Pakpattan require related but separate histories of transmission, devotion and material change.","primaryKeyword":"Baba Farid literary heritage","socialTitle":"Baba Farid: textual memory and a historic place","socialDescription":"Baba Farid’s textual afterlife and the shrine at Pakpattan require related but separate histories of transmission, devotion and material change."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Poetry of Baba Farid: A Historical and Thematic Analysis","url":"https://journals.iiu.edu.pk/index.php/islamicstudies/article/view/1393","publisher":"Muhammad Tanveer Jamal and Abdul Zahoor Khan / Islamic Studies","accessDate":"2026-10-22"},{"title":"Tomb of Baba Farid","url":"https://doam.gov.pk/public/sites/9694","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Islamic Studies abstract and bibliography read; full subscription article not available. No conclusion on disputed corpus authorship asserted. DOAM record based on Shaukat Mahmood 1995 explicitly uncertain inscriptions. No Punjabi verse or ritual rules invented. Specialist review required before release.","editorialReason":"Distinguish textual traditions and later commemoration with specialist review.","sortOrder":370}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-ranjit-singh-through-buildings-rather-than-a-heroic-portrait','ranjit-singh-through-buildings-rather-than-a-heroic-portrait','review','{"id":"story-ranjit-singh-through-buildings-rather-than-a-heroic-portrait","type":"story","slug":"ranjit-singh-through-buildings-rather-than-a-heroic-portrait","title":"Ranjit Singh through buildings rather than a heroic portrait","summary":"A residence, a birthplace and a later samadhi distinguish different kinds of architectural association with Ranjit Singh.","body":[{"type":"paragraph","text":"Buildings associated with Ranjit Singh do not all tell the same kind of story. A place remembered as his birthplace, a residence linked to his use, and a memorial built after his death belong to different historical relationships. Reading them together can move beyond the familiar heroic portrait without reducing architecture to a list of possessions."},{"type":"paragraph","text":"In Gujranwala, the birthplace haveli anchors a local memory of the ruler. Its association matters, but the survival of a named house does not mean every visible wall belongs to the moment of his birth. Identifying building phases is a separate task from recording the tradition attached to a room or address."},{"type":"heading","level":2,"text":"A residence away from the court"},{"type":"paragraph","text":"The federal catalogue describes a summer residence on the eastern side of the Chenab, away from central Gujranwala. Its account identifies masonry construction, teak elements, a tall central space, smaller rooms and long verandahs. These are useful architectural observations because they concern organisation and use rather than the ruler’s personality. The entry’s underlying source is a later architectural survey account, so its identification should not be mistaken for a contemporary royal building order."},{"type":"paragraph","text":"The arrangement suggests questions about seasonal occupation: how were enclosed rooms related to shaded edges, and how did a central volume connect the smaller spaces? Those are questions to pursue with measured plans and surviving fabric. They do not justify inventing an account of a particular summer gathering or claiming that the present river landscape is identical to its nineteenth-century setting."},{"type":"heading","level":2,"text":"A memorial made by successors"},{"type":"paragraph","text":"The Lahore samadhi is explicitly a later act of remembrance. The Walled City of Lahore Authority records that Kharak Singh began it at the cremation site and Duleep Singh completed it in 1848. It therefore represents decisions taken after Ranjit Singh’s death as well as memory of the ruler himself. The fluted dome, smaller roof pavilions and decorative interior belong to a commemorative building, not to a residence he inhabited."},{"type":"paragraph","text":"The federal catalogue also attributes a reused marble doorway to Shish Mahal. That is a claim about the movement of material and should remain attached to its source until supported by more detailed provenance. It opens a different perspective on royal building: new monuments may incorporate earlier fabric, while later histories can interpret those transfers in sharply different ways."},{"type":"paragraph","text":"These distinctions prevent one person’s name from flattening an architectural landscape. Birthplace, residence and samadhi can be compared without pretending that they were designed together, served the same audience or preserve the same moment."},{"type":"paragraph","text":"For heritage discovery, a productive visit asks what kind of relationship is being claimed at each place and which evidence supports it. A ruler becomes historically more interesting, not less, when commemoration, domestic space, succession and material reuse remain visible. The buildings then offer more than scenery for a biography: they reveal how power was inhabited and how its memory was subsequently constructed."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Punjab","Cultural Figures"],"province":"Punjab","district":null,"relatedDistrictIds":["punjab-gujranwala","punjab-lahore","punjab-wazirabad"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-10111","major-doam-6470","major-doam-10112"],"relatedStoryIds":[],"contentType":"personality","seo":{"title":"Ranjit Singh through buildings rather than a heroic portrait","description":"A residence, a birthplace and a later samadhi distinguish different kinds of architectural association with Ranjit Singh.","primaryKeyword":"Ranjit Singh architectural patronage","socialTitle":"Ranjit Singh through buildings rather than a heroic portrait","socialDescription":"A residence, a birthplace and a later samadhi distinguish different kinds of architectural association with Ranjit Singh."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Samadhi of Ranjit Singh","url":"https://artsandculture.google.com/asset/samadhi-of-ranjit-singh-walled-city-of-lahore-authority/qQFm3iXRRQJI9g","publisher":"Walled City of Lahore Authority","accessDate":"2026-10-22"},{"title":"Samadh of Ranjit Singh","url":"https://doam.gov.pk/public/sites/6470","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Ranjit Singh Summer Residence","url":"https://doam.gov.pk/public/sites/10112","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Ranjit Singh birthplace","url":"https://doam.gov.pk/public/sites/10111","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Residence entry checked against saved official catalogue as well as live identity. Its underlying source is Asian Historical Architecture, not a new field survey. Birthplace source previously used in article337: only brief association repeated. DOAM pejorative architectural judgement not adopted. No certainty asserted about reused doorframe beyond catalogue attribution.","editorialReason":"Use documented commissions and residences while allowing contradictory historical evidence.","sortOrder":371}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-nur-jahan-and-the-evidence-for-patronage','nur-jahan-and-the-evidence-for-patronage','review','{"id":"story-nur-jahan-and-the-evidence-for-patronage","type":"story","slug":"nur-jahan-and-the-evidence-for-patronage","title":"Nur Jahan and the evidence for patronage","summary":"A documented coin and the Shahdara tomb help separate Nur Jahan’s historical agency from later romantic attribution.","body":[{"type":"paragraph","text":"Nur Jahan is often introduced through romance, but material records offer a more precise starting point. A coin bearing her authority, a tomb attributed to her patronage and a later image carrying her name answer different questions. They should not be assembled into one seamless portrait without attending to their dates and purposes."},{"type":"paragraph","text":"The British Museum catalogues a gold coin minted at Surat in 1626 under both Jahangir and Nur Jahan. Its museum number, production date and mint make it an identifiable object rather than a general assertion that the empress was influential. The catalogue supports her appearance within the language of imperial authority. It does not by itself explain every administrative decision she made, and this article does not supply an unverified transcription of its legend."},{"type":"heading","level":2,"text":"Patronage and surviving fabric"},{"type":"paragraph","text":"At Shahdara, the federal archaeological catalogue attributes construction of Nur Jahan’s own tomb to her lifetime. It describes a platform setting and records traces of painted interior decoration, while also noting losses. Such an entry is a useful starting point for studying patronage, but the surviving building must still be understood through subsequent repair and alteration. A patron’s initiative is not a guarantee that all present material is original."},{"type":"paragraph","text":"The surrounding monuments are also distinct commissions. The UNESCO Tentative List entry is titled for the tombs of Jahangir and Asif Khan and Akbari Sarai. That title should not be casually expanded to give every nearby monument the same designation. Nor does proximity prove that one person commissioned the entire landscape. An ensemble can be historically connected while containing different agents, dates and functions."},{"type":"paragraph","text":"Together, coin and tomb broaden the evidence for Nur Jahan beyond a romantic anecdote. One is a portable official object; the other is a place of burial and remembrance. Their scales differ, but both make it possible to ask how a woman’s name and authority entered material public life."},{"type":"heading","level":2,"text":"A later portrait is another kind of evidence"},{"type":"paragraph","text":"The British Library’s record Add Or 1057 describes a drawing of a woman labelled Nur Jahan but dates it to around 1760. That is long after the empress’s lifetime. The record also preserves a later English inscription offering a dramatic story about her marriage. Such writing is evidence of how an image was interpreted and collected, not automatic proof of the events it alleges."},{"type":"paragraph","text":"This is why a familiar name beneath a picture requires the same scrutiny as an attribution on a building. When was the label added, by whom, and on what basis? The questions do not erase Nur Jahan’s agency; they help recover it from layers of later storytelling."},{"type":"paragraph","text":"A responsible account of patronage therefore distinguishes documented objects, catalogue attributions and subsequent memory. That approach gives the empress a more substantial historical presence than either idealised romance or an unsupported list of buildings ever could."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Punjab","Cultural Figures"],"province":"Punjab","district":"Lahore","relatedDistrictIds":["punjab-lahore"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6472"],"relatedStoryIds":[],"contentType":"personality","seo":{"title":"Nur Jahan and the evidence for patronage","description":"A documented coin and the Shahdara tomb help separate Nur Jahan’s historical agency from later romantic attribution.","primaryKeyword":"Nur Jahan architectural patronage","socialTitle":"Nur Jahan and the evidence for patronage","socialDescription":"A documented coin and the Shahdara tomb help separate Nur Jahan’s historical agency from later romantic attribution."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Tomb of Nur Jahan","url":"https://doam.gov.pk/public/sites/6472","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Gold coin, museum number 1939,0514.12","url":"https://www.britishmuseum.org/collection/object/C_1939-0514-12","publisher":"British Museum","accessDate":"2026-10-22"},{"title":"Add Or 1057: A lady","url":"https://searcharchives.bl.uk/catalog/040-003272080","publisher":"British Library","accessDate":"2026-10-22"},{"title":"Tombs of Jahangir, Asif Khan and Akbari Sarai","url":"https://whc.unesco.org/en/tentativelists/1279/","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"BM and BL primary indexed metadata read; BM full fetch403. No coin inscription transcribed. UNESCO1279 is contextual ensemble listing, not proof Nur Jahan tomb is itself included/inscribed. Tomb dimensions and speculative robbery claim omitted. Portrait dated c1760 not treated as lifetime likeness.","editorialReason":"Separate documented agency from romantic anecdotes and unsupported building attributions.","sortOrder":372}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-wazir-khan-a-patron-remembered-through-an-urban-ensemble','wazir-khan-a-patron-remembered-through-an-urban-ensemble','review','{"id":"story-wazir-khan-a-patron-remembered-through-an-urban-ensemble","type":"story","slug":"wazir-khan-a-patron-remembered-through-an-urban-ensemble","title":"Wazir Khan: a patron remembered through an urban ensemble","summary":"Wazir Khan’s mosque, bath and commercial spaces reveal patronage as an urban relationship rather than an isolated monument.","body":[{"type":"paragraph","text":"Wazir Khan’s name survives most visibly in a mosque, but the architectural story is larger than its prayer chamber. The patronage associated with Hakim Ilm ud Din, governor of Lahore under Shah Jahan, joined religious space to bathing, commerce and movement through the city. Looking at those relationships gives a more substantial account of patronage than a biography followed by a list of buildings."},{"type":"paragraph","text":"Punjab’s Auqaf Department identifies the mosque as part of an ensemble that included the nearby Shahi Hammam. Both belong to the seventeenth-century city around the route from Delhi Gate towards Lahore Fort. Their proximity is not merely convenient for a modern walking tour. It places them within a shared urban setting where residents, workers and travellers moved between different activities."},{"type":"heading","level":2,"text":"The threshold was not empty"},{"type":"paragraph","text":"The Aga Khan conservation account describes shops integrated with the mosque’s entrance and outer façades, including spaces associated with calligraphers and bookbinders. This matters because commerce was not simply an intrusion that arrived after a supposedly pure monument had been completed. Some commercial space formed part of the historic composition itself."},{"type":"paragraph","text":"The chowk, entrance sequence and prayer court therefore need to be read together. A visitor passes from a public urban space into a religious enclosure, but the boundary is articulated through rooms, openings and changes of scale. The patron’s presence was expressed not only in decoration but in the organisation of a place used by many people for different purposes."},{"type":"paragraph","text":"The hammam adds another dimension. Conservation work documented water supply, drainage, furnaces and underfloor heating. These systems remind us that patronage depended on technical labour and continued maintenance. A bathhouse was not sustained by its name alone: heat, water and circulation had to work. Painted surfaces are only one part of the surviving evidence."},{"type":"heading","level":2,"text":"Patronage and later urban change"},{"type":"paragraph","text":"The same conservation account records later adaptations of the hammam, including educational and administrative uses, and interventions to address water damage. Its subsequent presentation as a museum is another phase. A public bath, a reused building and a conserved visitor site are related but different institutions."},{"type":"paragraph","text":"The mosque’s surroundings similarly raise a distinction between historically integrated shops and later structures that obstructed or damaged parts of the complex. Calling all commerce an encroachment would obscure the original urban design; treating every later alteration as harmless continuity would ignore material consequences. Precise documentation is needed to distinguish them."},{"type":"paragraph","text":"Wazir Khan can thus be understood through the relationships his commissions helped establish, while acknowledging the many builders, craftspeople and users whose names are less securely recorded. The evidence does not require us to invent their biographies to recognise their work."},{"type":"paragraph","text":"The result is an urban history of patronage: a mosque connected to a market threshold, a bath connected to infrastructure, and both connected to a changing neighbourhood. That is a richer legacy than an isolated architectural masterpiece detached from the city that made it function."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Punjab","Cultural Figures"],"province":"Punjab","district":"Lahore","relatedDistrictIds":["punjab-lahore"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6466","major-doam-9778"],"relatedStoryIds":[],"contentType":"personality","seo":{"title":"Wazir Khan: a patron remembered through an urban ensemble","description":"Wazir Khan’s mosque, bath and commercial spaces reveal patronage as an urban relationship rather than an isolated monument.","primaryKeyword":"Wazir Khan Lahore patronage","socialTitle":"Wazir Khan: a patron remembered through an urban ensemble","socialDescription":"Wazir Khan’s mosque, bath and commercial spaces reveal patronage as an urban relationship rather than an isolated monument."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Wazir Khan Mosque","url":"https://auqaf.punjab.gov.pk/wazir-khan","publisher":"Punjab Auqaf and Religious Affairs Department","accessDate":"2026-10-22"},{"title":"Walled city of Lahore conservation","url":"https://the.akdn/en/where-we-work/south-asia/pakistan/walled-city-of-lahore-conservation-pakistan","publisher":"Aga Khan Development Network","accessDate":"2026-10-22"},{"title":"Documentation and conservation of Wazir Khan Mosque","url":"https://www.cipaheritagedocumentation.org/wp-content/uploads/2018/12/Salman-Documentation-and-conservation-of-Wazir-Khan-mosque-Lahore-Pakistan.pdf","publisher":"CIPA Heritage Documentation","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"AKDN page limited to under200 derived words combined mosque/bath. Earlier CIPA use~80 words: this article uses no new detailed source claims from it beyond documentation context. No claimed waqf income sum/deed inspected. Construction-date discrepancy 1634–35 versus1634–41 avoided by broad1630s formulation.","editorialReason":"Connect mosque and bath commission records without making the article another monument guide.","sortOrder":373}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-dyal-singh-majithia-and-the-idea-of-a-public-institution','dyal-singh-majithia-and-the-idea-of-a-public-institution','review','{"id":"story-dyal-singh-majithia-and-the-idea-of-a-public-institution","type":"story","slug":"dyal-singh-majithia-and-the-idea-of-a-public-institution","title":"Dyal Singh Majithia and the idea of a public institution","summary":"Dyal Singh Majithia’s bequest linked education, reading and public discussion; the institutions it supported have their own changing histories.","body":[{"type":"paragraph","text":"An endowment turns private resources towards a future the donor will not control in detail. Dyal Singh Majithia’s legacy is particularly interesting in this respect because it linked several kinds of public institution: a college, a library and a newspaper. Their common ground was access to knowledge, but each required a different form of organisation and a different relationship with its audience."},{"type":"paragraph","text":"Government Dyal Singh College’s institutional history describes his will as providing for these three ventures and assigning the largest part of the estate to the proposed college. The account presents education and public service as the organising purpose of the bequest. It is an institutional history of the will, not a substitute here for inspection of the original legal document or its complete financial schedules."},{"type":"heading","level":2,"text":"A library develops over time"},{"type":"paragraph","text":"The Evacuee Trust Property Board gives the Lahore library a chronology that is more useful than a single foundation date. It records establishment in 1908, initial operation in Dyal Singh’s residence and relocation to its present building in 1928. These dates describe different events: the institution began before it occupied the building now associated with it."},{"type":"paragraph","text":"The same account records closure following the migration of trustees in 1947 and resumption under ETPB administration in 1964. That interruption is part of the library’s history, not an awkward gap to be removed from a celebratory narrative. Books, buildings, legal responsibilities and readers do not necessarily move together when political boundaries and institutions change."},{"type":"paragraph","text":"New Delhi’s Dyal Singh Public Library identifies its own establishment in 1954 following Partition. The related name and founding inspiration should not lead us to merge two separate institutions into one unbroken address. Their subsequent histories belong to different communities of readers and different administrative settings."},{"type":"heading","level":2,"text":"What makes an institution public?"},{"type":"paragraph","text":"A benefactor’s name on a façade is only the beginning of that question. A college must sustain teaching; a library must organise collections and enable readers to use them; a newspaper needs editorial and production arrangements. Buildings can survive while access changes, and an institution can continue while moving to new premises."},{"type":"paragraph","text":"For heritage interpretation, the valuable evidence therefore includes catalogues, rules, staff records and accounts of use alongside architectural description. Such records can show how a bequest became a working service. They can also reveal whose access was limited and how the idea of a public audience changed, questions that a donor biography alone cannot answer."},{"type":"paragraph","text":"Dyal Singh’s legacy is consequently not just a story of generosity measured in property. It concerns the difficult work of making private wealth support collective intellectual life across generations. The documented changes in location, custody and operation show both the durability and the vulnerability of that ambition."},{"type":"paragraph","text":"Reading these institutions together preserves the connection established by the bequest without erasing their separate lives. It also shifts attention from commemoration alone towards the readers, students and workers who make a public institution real each day."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Punjab","Cultural Figures"],"province":"Punjab","district":"Lahore","relatedDistrictIds":["punjab-lahore"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-10187"],"relatedStoryIds":[],"contentType":"personality","seo":{"title":"Dyal Singh Majithia and the idea of a public institution","description":"Dyal Singh Majithia’s bequest linked education, reading and public discussion; the institutions it supported have their own changing histories.","primaryKeyword":"Dyal Singh Majithia legacy","socialTitle":"Dyal Singh Majithia and the idea of a public institution","socialDescription":"Dyal Singh Majithia’s bequest linked education, reading and public discussion; the institutions it supported have their own changing histories."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"History","url":"https://gdscl.edu.pk/history/","publisher":"Government Dyal Singh Graduate College Lahore","accessDate":"2026-10-22"},{"title":"Dyal Singh Trust Library","url":"https://etpb.gov.pk/dyal-singh-trust-library/","publisher":"Evacuee Trust Property Board","accessDate":"2026-10-22"},{"title":"Institutional history","url":"https://www.dspl.org.in/","publisher":"Dyal Singh Public Library, New Delhi","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"College/ETPB live institutional histories read. Delhi history distinguishes its1954 establishment from Lahore history; date1928 in Delhi shorthand not used as Lahore founding date. No will manuscript or specific financial amount claimed inspected.","editorialReason":"Use institutional histories and the bequest to discuss education and public reading.","sortOrder":374}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-sir-ganga-ram-civic-legacy-and-surviving-evidence','sir-ganga-ram-civic-legacy-and-surviving-evidence','review','{"id":"story-sir-ganga-ram-civic-legacy-and-surviving-evidence","type":"story","slug":"sir-ganga-ram-civic-legacy-and-surviving-evidence","title":"Sir Ganga Ram: civic legacy and surviving evidence","summary":"Sir Ganga Ram’s civic legacy is best followed through distinct records of engineering, philanthropy and later institutional growth.","body":[{"type":"paragraph","text":"Sir Ganga Ram’s name is attached to public buildings, charitable institutions and a memorial in Lahore. These associations are not interchangeable. Designing or supervising a building, providing money for a service, and being commemorated after death are different forms of civic presence. A careful account needs to establish the relationship separately for each place."},{"type":"paragraph","text":"The federal archaeological catalogue attributes Lahore’s General Post Office to Ganga Ram and links its construction to Queen Victoria’s Golden Jubilee in 1887. The same entry records a later conservation campaign and a stamp commemorating restoration in 1996. Even this brief chronology shows that the building has more than one authorial moment: original construction and subsequent care belong to different people and institutions."},{"type":"heading","level":2,"text":"A service is more than its first building"},{"type":"paragraph","text":"The Pakistan Society of Civil Engineers’ account places the beginnings of Sir Ganga Ram Hospital in Lahore in 1921 and describes its charitable facilities. That history establishes a philanthropic foundation, but it should not be used to date every block visible in today’s hospital complex. Medical institutions expand, replace spaces and change their relationship with teaching over time."},{"type":"paragraph","text":"Fatima Jinnah Medical University’s record of a new nephrology ward inaugurated in 2023 offers a concrete example of that continuing development. It names contemporary donors and staff and describes provision for treatment and training. The point here is not to assess clinical services, but to recognise that a historic institution is also the work of later contributors. Their labour should not disappear behind the founder’s name."},{"type":"paragraph","text":"The same distinction applies to architectural attribution. A familiar building is not securely a Ganga Ram project simply because it appears in a popular list. A responsible inventory should identify the evidence: a drawing, contract, institutional record or a clearly attributed historical study. Different roles in design, engineering and construction should be recorded rather than collapsed into a single credit."},{"type":"heading","level":2,"text":"Commemoration has its own material history"},{"type":"paragraph","text":"The catalogue places Ganga Ram’s samadhi near the old city on Ravi Road and records later renovation after damage in 1992. The memorial consequently tells a story of remembrance and subsequent repair. It is not an untouched expression of its initial construction, and a description based on an older account should not be treated as a current condition survey."},{"type":"paragraph","text":"Taken together, the post office, hospital and samadhi reveal three ways a civic legacy survives: through infrastructure still used, an institution that keeps developing, and a place where the individual is remembered. None needs an exaggerated claim that one person built an entire city."},{"type":"paragraph","text":"The stronger account is both more precise and more generous. It recognises a documented contribution while leaving room for colleagues, donors, staff, conservators and users. Following that evidence makes Lahore’s civic heritage intelligible as an accumulated public endeavour, rather than a collection of buildings assigned to a single celebrated name."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Punjab","Cultural Figures"],"province":"Punjab","district":"Lahore","relatedDistrictIds":["punjab-lahore"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-10240","major-doam-10157"],"relatedStoryIds":[],"contentType":"personality","seo":{"title":"Sir Ganga Ram: civic legacy and surviving evidence","description":"Sir Ganga Ram’s civic legacy is best followed through distinct records of engineering, philanthropy and later institutional growth.","primaryKeyword":"Sir Ganga Ram Lahore heritage","socialTitle":"Sir Ganga Ram: civic legacy and surviving evidence","socialDescription":"Sir Ganga Ram’s civic legacy is best followed through distinct records of engineering, philanthropy and later institutional growth."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"General Post Office Lahore","url":"https://doam.gov.pk/public/sites/10157","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Samadh of Sir Ganga Ram","url":"https://doam.gov.pk/public/sites/10240","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"The Pakistan Civil Engineer, December 2018","url":"https://psce.org.pk/wp-content/uploads/2022/04/The-Pakistan-Civil-Engineer-V02-I02-A-December-2018.pdf","publisher":"Pakistan Society of Civil Engineers","accessDate":"2026-10-22","section":"Sir Ganga Ram Hospital discussion"},{"title":"Inauguration of new Nephrology Department, 2023","url":"https://www.fjmu.edu.pk/event/inauguration-of-new-nephrology-department-sgrh/","publisher":"Fatima Jinnah Medical University","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Historical professional-society PDF indexed passage read; DOAM sources disclose secondary provenance. No unverified total building list, current hospital service claims, or claim all present hospital fabric dates1921. Samadhi page500, saved official catalogue used; present maintenance not asserted.","editorialReason":"Verify each attributed project rather than repeat a list of buildings credited by folklore.","sortOrder":375}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-ahmad-nabi-khan-and-the-work-of-a-monument-inventory','ahmad-nabi-khan-and-the-work-of-a-monument-inventory','review','{"id":"story-ahmad-nabi-khan-and-the-work-of-a-monument-inventory","type":"story","slug":"ahmad-nabi-khan-and-the-work-of-a-monument-inventory","title":"Ahmad Nabi Khan and the work of a monument inventory","summary":"Ahmad Nabi Khan’s documented publications show why inventory work matters, and why an older catalogue is a starting point rather than a final authority.","body":[{"type":"paragraph","text":"A heritage inventory can be easy to overlook because its entries are short and its labour is dispersed. Yet the ability to identify a modest tomb, find its bibliography or distinguish it from a similarly named building depends on such work. Ahmad Nabi Khan’s name appears repeatedly in Pakistan’s monument records, making his publications a useful route into the practice of documenting heritage."},{"type":"paragraph","text":"The federal catalogue entry for the tomb of Nawab Bahadur Khan in Lahore cites his 1987 publication Archaeological Sites and Historical Monuments Protected Under the Antiquities Act, 1975. The entry records an octagonal plan, brick construction and a later use as a theatre. These are different kinds of information: form and material describe a building, while a change of use opens a historical question."},{"type":"heading","level":2,"text":"What a short record makes possible"},{"type":"paragraph","text":"Even a concise description can direct attention towards evidence that a visitor might otherwise miss. An octagonal platform is a feature to locate and compare. A reported later use suggests documents to seek. A named publication gives the researcher a route beyond the current webpage. The value lies not only in the facts listed, but in making further checking possible."},{"type":"paragraph","text":"That does not mean every field on the digital page was supplied by Khan in 1987. Coordinates, administrative categories and website labels may have been added later. The publication date should therefore remain attached to the cited source, not transferred indiscriminately to all present metadata. Nor does a protected-monument inventory necessarily represent every place considered culturally important by local communities."},{"type":"paragraph","text":"The Sindh Exploration and Excavation Branch’s research-library catalogue documents a broader range of work under Khan’s name, including publications concerned with Multan, mosque architecture and archaeological meetings. Japan’s CiNii author record also connects the name to museum and art publications. These bibliographical records show the range of subjects available for study; they are not evidence that this article has read every listed volume."},{"type":"heading","level":2,"text":"An inventory remains open to revision"},{"type":"paragraph","text":"Older descriptions may preserve observations of features that have since changed. They can also contain uncertain dates, inherited interpretations or language that needs reconsideration. The appropriate response is neither unquestioning repetition nor dismissal. Compare the record with later studies, identify the source of a correction and retain the earlier account as part of the documentation history."},{"type":"paragraph","text":"For a digital atlas, that means keeping a stable identity for a place while allowing its description to improve. A revised name should not silently create a duplicate. A new coordinate should be supported by site evidence. A changed interpretation should be distinguishable from the simple correction of a typographical error."},{"type":"paragraph","text":"Khan’s contribution can therefore be approached through the continuing usefulness of documented work rather than an unsupported biographical tribute. An inventory gives future researchers something to question, compare and extend. Its legacy is strongest when the chain from physical place to description to publication remains visible, allowing each new generation to build on evidence rather than begin again from an unattributed paragraph."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Cultural Figures"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"personality","seo":{"title":"Ahmad Nabi Khan and the work of a monument inventory","description":"Ahmad Nabi Khan’s documented publications show why inventory work matters, and why an older catalogue is a starting point rather than a final authority.","primaryKeyword":"Ahmad Nabi Khan archaeology surveys","socialTitle":"Ahmad Nabi Khan and the work of a monument inventory","socialDescription":"Ahmad Nabi Khan’s documented publications show why inventory work matters, and why an older catalogue is a starting point rather than a final authority."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Tomb of Nawab Bahadur Khan","url":"https://doam.gov.pk/public/sites/6482","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Online catalogue of books","url":"https://ene.sindhculture.gov.pk/online-catalogue-of-books/","publisher":"Sindh Exploration and Excavation Branch","accessDate":"2026-10-22"},{"title":"Nabi Khan, Ahmad: author authority record","url":"https://ci.nii.ac.jp/author/DA0894264X","publisher":"National Institute of Informatics, Japan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Object-led bibliography profile, no invented biography/director tenure. CiNii indexed catalogue only; DOAM6482 and Sindh library catalogue read. Does not claim inspection of full1987 volume or attribute current website fields/coordinates to1987 author. This distinction is essential.","editorialReason":"Examine the documented survey publication’s methods and legacy; obtain a biographical source before drafting life details.","sortOrder":376}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-abdur-rahman-chughtai-the-line-between-painting-and-print','abdur-rahman-chughtai-the-line-between-painting-and-print','review','{"id":"story-abdur-rahman-chughtai-the-line-between-painting-and-print","type":"story","slug":"abdur-rahman-chughtai-the-line-between-painting-and-print","title":"Abdur Rahman Chughtai: the line between painting and print","summary":"An identified etching and illustrated book reveal Chughtai’s movement between a unique image, a printed impression and literary publication.","body":[{"type":"paragraph","text":"Chughtai’s work is often introduced through the elegance of his line, but the medium carrying that line matters. A drawing, a watercolour, an etched impression and an illustrated book are not simply different sizes of the same image. They involve different ways of making, reproducing and encountering art."},{"type":"paragraph","text":"The Asian Art Museum’s Old Musician provides an identifiable starting point. Its collection record describes an etching on paper, object number 2005.64.32, and dates it broadly to about 1940–1970. The museum notes Chughtai’s repeated variations on figures and motifs across different works. That is more precise than assuming a titled print depicts a particular historical musician whose biography is known."},{"type":"heading","level":2,"text":"A line made for printing"},{"type":"paragraph","text":"The museum’s account connects Chughtai’s printmaking with training in England and the establishment of a press after his return to Lahore. These details shift the discussion from visual style alone towards the practical means of circulation. A print can exist in multiple impressions, while the plate, paper and printing process all contribute to the resulting object."},{"type":"paragraph","text":"This does not mean every impression is identical or that an unsigned reproduction is equivalent to an artist’s print. For a particular sheet, the relevant evidence includes technique, inscriptions, paper, edition information and provenance. The museum’s broad date range should remain broad unless another document securely narrows it; apparent stylistic confidence is not a substitute for that evidence."},{"type":"paragraph","text":"Book production adds another relationship. The British Museum lists Poet of the East and Chughtai among its holdings, associated with Lahore’s Nisar Art Press. An object-specific auction description of a deluxe copy identifies colour plates, photogravures, calligraphic material and an etching, with English translations of Iqbal’s verses facing related images. The page thus brings reading and looking into a planned sequence."},{"type":"heading","level":2,"text":"The book is not merely a container"},{"type":"paragraph","text":"In such a publication, scale, facing pages and the order of images can affect interpretation. A reader turns pages and compares verse with picture, rather than encountering each work in isolation on a gallery wall. Illustration becomes a conversation with a literary text, not proof that the picture exhausts the poem’s meaning."},{"type":"paragraph","text":"The consulted catalogues also give differing publication dates for their records. That requires examination of the individual copies and editions before a single definitive date is assigned. A luxury edition, a later issue and a catalogue error are possibilities to investigate, not alternatives this draft can resolve by guesswork."},{"type":"paragraph","text":"Chughtai’s movement between painting and print is therefore a history of objects as well as style. The etching asks how a line becomes repeatable; the illustrated book asks how images travel with poetry. Keeping those formats distinct makes his achievement more intelligible and gives readers a practical way to approach the work: identify the object first, then consider what its medium allows the image to do."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Cultural Figures"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"personality","seo":{"title":"Abdur Rahman Chughtai: the line between painting and print","description":"An identified etching and illustrated book reveal Chughtai’s movement between a unique image, a printed impression and literary publication.","primaryKeyword":"Abdur Rahman Chughtai art","socialTitle":"Abdur Rahman Chughtai: the line between painting and print","socialDescription":"An identified etching and illustrated book reveal Chughtai’s movement between a unique image, a printed impression and literary publication."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Old Musician, object 2005.64.32","url":"https://searchcollection.asianart.org/objects/16183/old-musician","publisher":"Asian Art Museum, San Francisco","accessDate":"2026-10-22"},{"title":"Abdur Rahman Chughtai: collection records","url":"https://www.britishmuseum.org/collection/term/BIOG9076","publisher":"British Museum","accessDate":"2026-10-22"},{"title":"Poet of the East and Chughtai: deluxe copy, lot 20","url":"https://media.saffronart.com/auctions/2017/4033/files/assets/common/downloads/publication.pdf","publisher":"Saffronart","accessDate":"2026-10-22","section":"Object-specific auction catalogue, lot20"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Primary museum indexed records read after fetch restrictions; auction catalogue object description read as evidence for that copy, not generic edition authority. BM1962 versus deluxe1968 retained as unresolved edition-level distinction. No image visual inspection claimed, no biography dates used because catalogue sources differ.","editorialReason":"Commission an object-led profile from identified collection works and publication history.","sortOrder":377}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-zubeida-agha-and-the-language-of-modern-painting','zubeida-agha-and-the-language-of-modern-painting','review','{"id":"story-zubeida-agha-and-the-language-of-modern-painting","type":"story","slug":"zubeida-agha-and-the-language-of-modern-painting","title":"Zubeida Agha and the language of modern painting","summary":"A documented late painting and an archive of exhibition work place Zubeida Agha’s abstraction within a wider practice of making and organising art.","body":[{"type":"paragraph","text":"Zubeida Agha’s painting can be approached more closely by beginning with a particular work than by assigning her a rank among pioneers. Composition, dated 1988 and presented at the 2024 Venice Biennale, offers one such starting point. Its significance lies in the decisions within a painted surface, not simply in its position on a national timeline."},{"type":"paragraph","text":"In the Biennale’s catalogue text, curator Devika Singh describes a central grouping of asymmetrical geometric forms, with uneven rather than mechanically exact edges. She also draws attention to a band across the foreground that interrupts an easy resolution of the image. This is a named curator’s reading of a specific painting; it should not be presented as a fresh visual inspection undertaken for this article."},{"type":"heading","level":2,"text":"Abstraction as a set of decisions"},{"type":"paragraph","text":"The description points towards a useful question: how do shapes relate when they are not required to illustrate a recognisable scene? Edge, interval, colour and placement become active parts of the work. Geometric form does not necessarily mean impersonal regularity. An irregular boundary can make a shape feel made and contingent rather than simply calculated."},{"type":"paragraph","text":"The Jordan National Gallery of Fine Arts lists another work, Abstract Study, dated 1967. Its catalogue establishes a separate object and an earlier point in the practice. A title and date alone do not justify a detailed account of its appearance, but they provide a basis for future comparison with the later Composition. Such comparison should examine actual works or reliable reproductions rather than assume that all abstraction follows one continuous stylistic formula."},{"type":"heading","level":2,"text":"The painter also made institutions"},{"type":"paragraph","text":"Agha’s archive expands the subject beyond finished canvases. The Lahore Biennale Foundation records Saira Ansari’s research fellowship documenting the archive in collaboration with Asia Art Archive. A researcher-informed account of its photographic material discusses Agha’s public role in exhibitions, including a 1961 presentation of contemporary Pakistani painting in Milan."},{"type":"paragraph","text":"Those records matter because the work of arranging an exhibition is easily lost behind the image of the solitary painter. Selection, correspondence, installation and public discussion help determine which art becomes visible. An archive can preserve that labour alongside evidence of individual artistic practice."},{"type":"paragraph","text":"It also cautions against turning personality into explanation. Photographs of a public event cannot reveal every aspect of an artist’s private life, just as reports of privacy do not erase an active institutional role. The relevant question is what a particular document shows and what remains outside its frame."},{"type":"paragraph","text":"Seen together, the painting and archive offer two scales of agency: decisions within an image and decisions that create a setting for other images to be encountered. Agha’s contribution becomes more substantial when both are considered. Modern painting is then not only a story of imported styles or celebrated firsts, but of specific works, public platforms and the records through which their histories can be reconstructed."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Cultural Figures"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"personality","seo":{"title":"Zubeida Agha and the language of modern painting","description":"A documented late painting and an archive of exhibition work place Zubeida Agha’s abstraction within a wider practice of making and organising art.","primaryKeyword":"Zubeida Agha modern art","socialTitle":"Zubeida Agha and the language of modern painting","socialDescription":"A documented late painting and an archive of exhibition work place Zubeida Agha’s abstraction within a wider practice of making and organising art."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Zubeida Agha, Biennale Arte 2024","url":"https://www.labiennale.org/en/art/2024/abstraction/zubeida-agha","publisher":"La Biennale di Venezia / Devika Singh","accessDate":"2026-10-22"},{"title":"Zubeida Agha: Abstract Study, 1967","url":"https://nationalgallery.org/artist/zubeida-agha/","publisher":"Jordan National Gallery of Fine Arts","accessDate":"2026-10-22"},{"title":"Research fellowship: Zubeida Agha Archive","url":"https://lahorebiennale.org/research/lbf-research-fellowship-2015/","publisher":"Lahore Biennale Foundation","accessDate":"2026-10-22"},{"title":"A Public Presence: Selected Photo-Documentation in Zubeida Agha’s Archive","url":"https://www.asapconnect.in/post/205/singlestories/a-public-presence","publisher":"ASAP Art, with contributions from Saira Ansari","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"No image formally visually inspected; formal description explicitly attributed to Biennale curator. Direct AAA403 replaced with commissioning fellowship and researcher-contributed account. No first Pakistani abstract artist ranking or invented biographical psychology. Per-source summaries under200words.","editorialReason":"Use catalogued works and exhibition records rather than an unsupported pioneer ranking.","sortOrder":378}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-shakir-alis-studio-home-as-an-artistic-archive','shakir-alis-studio-home-as-an-artistic-archive','review','{"id":"story-shakir-alis-studio-home-as-an-artistic-archive","type":"story","slug":"shakir-alis-studio-home-as-an-artistic-archive","title":"Shakir Ali’s studio-home as an artistic archive","summary":"Shakir Ali’s former home brings architecture, artistic memory and museum-making together, but each layer needs its own evidence.","body":[{"type":"paragraph","text":"An artist’s house becomes an unusual kind of archive when it is turned into a museum. The building survives as a setting for work and daily life, but the later institution selects what to display, how to arrange it and what story to tell. Shakir Ali’s former home in Lahore invites attention to both layers: the place made for an artist and the public memory subsequently constructed within it."},{"type":"paragraph","text":"Nayyar Ali Dada and Associates includes Shakir Ali Museum in its project portfolio. MIT Libraries’ architectural photograph record independently attributes the building to Dada and identifies a photograph taken by Kazi Khaleed Ashraf in 1987. These records establish a documented architectural connection without requiring a romantic account of a conversation between architect and artist that has not been verified."},{"type":"heading","level":2,"text":"From a house to an institution"},{"type":"paragraph","text":"The museum’s formation also appears in near-contemporary records. Saifur Rahman Dar’s 1981 discussion of museum development states that the Pakistan National Council of the Arts converted Shakir Ali’s Lahore residence into a museum in 1976. The Planning Commission’s 1976–77 development programme lists an approved Shakir Ali Museum scheme. This administrative trace is useful precisely because it concerns the practical making of an institution rather than a later tribute."},{"type":"paragraph","text":"The MIT metadata uses 1975 for establishment as a museum, while Dar gives 1976 for conversion. Acquisition, formal organisation and public opening can be different events, but that explanation must be demonstrated rather than assumed. A definitive chronology should consult the acquisition and opening records. For now, the evidence places the transition in the mid-1970s and leaves the exact sequence open."},{"type":"heading","level":2,"text":"What can a studio-home preserve?"},{"type":"paragraph","text":"The house offers a spatial record: relationships between rooms, thresholds, light and places where work could occur. Museum collections may offer another record through paintings, correspondence and possessions. Yet a room arranged for visitors is not automatically an untouched studio left exactly as the artist used it. That claim would require inventories, dated photographs and documentation of later changes."},{"type":"paragraph","text":"The distinction affects interpretation. A painting’s present position may be a curator’s decision; a chair’s association may be well documented or only traditional. Both can have significance, but visitors deserve to know which kind of evidence they are encountering. This draft has not inspected a current interior inventory and does not assign particular objects to particular working habits."},{"type":"paragraph","text":"The surviving photograph record is similarly dated evidence. It identifies a view in 1987, not a current condition survey. Comparing such records with later documentation could reveal changes in the building and its presentation, provided the photographs themselves are examined and permissions respected."},{"type":"paragraph","text":"Shakir Ali’s studio-home is therefore valuable not as a frozen illustration of genius, but as a meeting point of architectural design, lived space and institutional care. Its strongest interpretation would keep those histories visible, allowing the artist’s memory to rest on documented relationships rather than an invented scene of work."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Cultural Figures"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"personality","seo":{"title":"Shakir Ali’s studio-home as an artistic archive","description":"Shakir Ali’s former home brings architecture, artistic memory and museum-making together, but each layer needs its own evidence.","primaryKeyword":"Shakir Ali Museum artist","socialTitle":"Shakir Ali’s studio-home as an artistic archive","socialDescription":"Shakir Ali’s former home brings architecture, artistic memory and museum-making together, but each layer needs its own evidence."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Shakir Ali Museum","url":"https://www.nayyaralidada.net/project-details/civic-cultural/shakir-ali-museum","publisher":"Nayyar Ali Dada and Associates","accessDate":"2026-10-22"},{"title":"Shakir Ali Museum: exterior photograph, 1987","url":"https://dome.mit.edu/entities/picture/01487805-326c-4be5-914f-1564a7aa9adf","publisher":"MIT Libraries / Kazi Khaleed Ashraf","accessDate":"2026-10-22"},{"title":"Museology and Museum Problems in Pakistan","url":"https://library-sindhi-sp-2020.s3.us-east-2.amazonaws.com/files/Muselogy_and_Museum_Problems_In_Pakistan_Dr_Saifur_Rahman_Dar_1981-cs.pdf","publisher":"Saifur Rahman Dar","accessDate":"2026-10-22","section":"Printed page16, indexed text"},{"title":"Annual Development Programme 1976–77","url":"https://pc.gov.pk/uploads/archives/1976-77FSDP.pdf","publisher":"Planning Commission, Government of Pakistan","accessDate":"2026-10-22","section":"Shakir Ali Museum scheme"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Current PNCA-branded domain rejected as official evidence. Architect project page, MIT photographic metadata, Dar indexed1981text and Planning Commission indexed scheme read. No current interior inventory, opening hours or uninspected photograph details claimed.1975MIT/1976Dar distinction acknowledged, not resolved. No reproduced image.","editorialReason":"Connect a preserved workspace with verified works and institutional documentation.","sortOrder":379}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-faiz-and-the-circulation-of-a-poem','faiz-and-the-circulation-of-a-poem','review','{"id":"story-faiz-and-the-circulation-of-a-poem","type":"story","slug":"faiz-and-the-circulation-of-a-poem","title":"Faiz and the circulation of a poem","summary":"Subh-e-Azadi shows why the date of a poem, the date of a translation and the date of an online repost must remain distinct.","body":[{"type":"paragraph","text":"Faiz’s Subh-e-Azadi travels through books, translations, recitation and online quotation. Each form can introduce the poem to a new audience, but it can also blur the record of what is being encountered. A date beside a digital item might identify publication of a translation rather than composition of the Urdu poem; a familiar voice might belong to a later performer rather than Faiz himself."},{"type":"paragraph","text":"The poem is identified with August 1947 in Rekhta’s text record. Penguin Random House’s publisher presentation places it in the anguish of Partition and supplies the Urdu text in transliteration. These are useful points of reference for identifying the work, but neither makes every circulated extract or recording an authenticated version."},{"type":"heading","level":2,"text":"The poem moves beyond its opening"},{"type":"paragraph","text":"The opening challenges the expected meaning of dawn. Arrival at a promised moment does not produce uncomplicated fulfilment. As the poem develops, the language of journey, desire and continuing darkness keeps the question of freedom unsettled. Reducing the work to its first memorable image loses the movement towards continuing effort that gives the poem its tension."},{"type":"paragraph","text":"That movement matters when the poem is presented as heritage. It is not merely an ornament for an anniversary page, nor a document that can be reduced to one fixed political caption. Readers need enough of the complete work to follow its changes of voice and direction. A short critical account can invite that reading without reproducing the poem or pretending to replace it."},{"type":"heading","level":2,"text":"Translation creates another publication history"},{"type":"paragraph","text":"The University of Wisconsin–Madison repository identifies The Dawn of Freedom, translated by Agha Shahid Ali, as an item in volume eleven of the Annual of Urdu Studies, issued in 1996. The repository also records later accession dates. None of those dates should be used to claim that Faiz first wrote the poem in 1996 or that it originated when the digital record was created."},{"type":"paragraph","text":"The Academy of American Poets documents Ali’s work as a translator of Faiz. Naming the translator is essential because an English poem is also a sequence of choices about rhythm, imagery and emphasis. Two translations can share an original without having identical wording or the same publication and reproduction permissions."},{"type":"paragraph","text":"Recitation adds a further layer. Tempo, pauses and emphasis can alter what listeners notice, while editing may remove lines or combine separate performances. A responsible archive should identify performer, recording source and date where known. It should not label an anonymous audio clip as the poet’s voice merely because that description has been widely repeated."},{"type":"paragraph","text":"Following Subh-e-Azadi through these layers reveals circulation as part of the cultural history. The Urdu work, a named translation, a journal publication and a later recording are connected but distinct objects. Keeping those connections explicit allows the poem to reach new readers without losing the people, editions and acts of interpretation through which it continues to live."}],"primaryCategoryId":"archive-category-living-traditions","categoryIds":["archive-category-living-traditions"],"tags":["Cultural Figures"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"personality","seo":{"title":"Faiz and the circulation of a poem","description":"Subh-e-Azadi shows why the date of a poem, the date of a translation and the date of an online repost must remain distinct.","primaryKeyword":"Faiz poetry publication performance","socialTitle":"Faiz and the circulation of a poem","socialDescription":"Subh-e-Azadi shows why the date of a poem, the date of a translation and the date of an online repost must remain distinct."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Subh-e-Azadi: publisher presentation","url":"https://www.penguin.co.in/subh-e-azadi-an-anguished-evocation-of-the-pain-of-partition/","publisher":"Penguin Random House India","accessDate":"2026-10-22"},{"title":"The Dawn of Freedom","url":"https://minds.wisconsin.edu/handle/1793/11923?show=full","publisher":"Annual of Urdu Studies / University of Wisconsin–Madison","accessDate":"2026-10-22"},{"title":"Agha Shahid Ali","url":"https://poets.org/poet/agha-shahid-ali","publisher":"Academy of American Poets","accessDate":"2026-10-22"},{"title":"Subh-e-Azadi, August 1947","url":"https://www.rekhta.org/nazms/subah-shayari/subh-e-aazaadii-august-47-ye-daag-daag-ujaalaa-ye-shab-gaziida-sahar-faiz-ahmad-faiz-nazms","publisher":"Rekhta","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"No verse reproduced; publisher Urdu transliteration read, Wisconsin primary bibliographic metadata indexed (full redirect inaccessible), Rekhta text/translator credit checked.1996is translation publication not original poem date. No claim any online recording is authenticated or licensed. Poetic discussion below200words derived from text.","editorialReason":"Require an authenticated edition and authorised translation to distinguish publication, recitation and later adaptation.","sortOrder":380}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-indus-as-a-cultural-landscape-not-a-single-itinerary','the-indus-as-a-cultural-landscape-not-a-single-itinerary','review','{"id":"story-the-indus-as-a-cultural-landscape-not-a-single-itinerary","type":"story","slug":"the-indus-as-a-cultural-landscape-not-a-single-itinerary","title":"The Indus as a cultural landscape, not a single itinerary","summary":"River terraces, rural settlement and engineering reveal several Indus landscapes rather than one uninterrupted cultural route.","body":[{"type":"paragraph","text":"The Indus can organise a map without organising every story on that map in the same way. A settlement mound, a cultivated floodplain and a railway bridge are connected to water through different technologies, institutions and timescales. Treating them as stops on one timeless route can obscure the very differences that make a river landscape worth exploring."},{"type":"paragraph","text":"The first useful distinction is between the river’s present line and the environments in which earlier communities lived. Archaeological sites do not become unrelated to a river merely because today’s channel lies elsewhere. Equally, proximity to water on a modern map cannot establish that a settlement was once a port."},{"type":"heading","level":2,"text":"Land beside a changing channel"},{"type":"paragraph","text":"Giosan and colleagues’ study of Harappan river landscapes describes important contrasts within the wider basin. In Punjab, incised river valleys and the higher land between them offered different combinations of flood exposure and agricultural opportunity. The researchers also discuss the possibility that later sediments conceal some earlier settlements in southwestern Sindh. Their argument is not that one environmental event mechanically explains every social change. Different local settings mattered."},{"type":"paragraph","text":"This distinction changes how a map should be read. An apparently empty patch may mean that evidence is buried, unrecorded or absent; those are three different propositions. A concentration of visible mounds is not automatically proof that one region supported more people than another throughout its history."},{"type":"heading","level":2,"text":"Beyond the famous city"},{"type":"paragraph","text":"The Beas Landscape and Settlement Survey makes the rural network particularly clear. Its researchers mapped and sampled settlements in the now-dry bed of the ancient Beas and examined their relationship with Harappa. They compared surface pottery with excavated sequences at the city and collected material for radiocarbon dating. Settlement history and the history of the floodplain were therefore investigated together, rather than treating villages as background scenery around an urban centre."},{"type":"paragraph","text":"For a reader, this offers an alternative to collecting only monumental highlights. The relationship between a small settlement and cultivable land can be as revealing as a major building. It also shows why a pottery scatter needs context: its location, date and association with other material are part of its meaning."},{"type":"heading","level":2,"text":"Infrastructure changes the question"},{"type":"paragraph","text":"At Sukkur, a structure such as the Lansdowne Bridge introduces another relationship: making a reliable crossing for a transport system. Its historical questions concern engineering, labour and connections across a river, not the same settlement processes studied at Harappa. Connecting both on an atlas is useful precisely because it permits comparison without claiming direct continuity."},{"type":"paragraph","text":"A cultural landscape is thus more than a scenic corridor. It is a way to examine how people have occupied, crossed, remembered and altered particular places. The strongest Indus journey may follow one question closely—water access, crossings or settlement evidence—while leaving room for the river to mean something different at the next location."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Cultural Landscapes"],"province":null,"district":null,"relatedDistrictIds":["sindh-larkana","sindh-sukkur"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["unesco-138","major-doam-5119"],"relatedStoryIds":[],"contentType":"landscape","seo":{"title":"The Indus as a cultural landscape, not a single itinerary","description":"River terraces, rural settlement and engineering reveal several Indus landscapes rather than one uninterrupted cultural route.","primaryKeyword":"Indus cultural landscape","socialTitle":"The Indus as a cultural landscape, not a single itinerary","socialDescription":"River terraces, rural settlement and engineering reveal several Indus landscapes rather than one uninterrupted cultural route."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Fluvial landscapes of the Harappan civilization","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3387054/","publisher":"Giosan and colleagues, PNAS","accessDate":"2026-10-22"},{"title":"Introduction to the Beas Research","url":"https://www.harappa.com/beas/chronology","publisher":"Beas Landscape and Settlement Survey","accessDate":"2026-10-22"},{"title":"Lansdowne Bridge","url":"https://doam.gov.pk/public/sites/5119","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"PNAS full indexed text and Beas project introduction read. Approximately 140 words derive from each; remaining framing is original comparison. Lansdowne catalogue used for identity only: its 1887 date is not adopted. No continuous historical route or current visitor itinerary claimed.","editorialReason":"Connect settlement, movement and changing river environments without claiming one continuous culture.","sortOrder":381}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-cholistans-wells-forts-and-traces-of-water','cholistans-wells-forts-and-traces-of-water','review','{"id":"story-cholistans-wells-forts-and-traces-of-water","type":"story","slug":"cholistans-wells-forts-and-traces-of-water","title":"Cholistan’s wells, forts and traces of water","summary":"Wells and storage features make Cholistan’s forts legible, while settlement research warns against reading every mapped mound as simultaneous.","body":[{"type":"paragraph","text":"A fort in Cholistan is easy to photograph as a self-contained object: walls, towers and an expanse of sand. Water changes that composition. A well outside a gateway or a tank beside a fortified enclosure asks how people could remain there, not simply how they defended themselves. The most useful view may therefore include an apparently modest depression or masonry lining as well as the tallest bastion."},{"type":"paragraph","text":"The federal inventory records a well and an external tank at Derawar, and a brick-lined well outside Khairgarh. These features should not be treated as interchangeable ornaments. Their positions raise different questions about access, storage and the relationship between an enclosure and its surroundings. A well is not the same technology as a reservoir, and neither proves that water was continuously available."},{"type":"heading","level":2,"text":"What the map gathers together"},{"type":"paragraph","text":"Cholistan also contains archaeological settlements much earlier than these fort landscapes. Putting both on a regional map can illuminate changing ways of occupying dry country, provided the dates remain visible. A later fort must not become the visual substitute for a prehistoric community merely because its walls survive more dramatically."},{"type":"paragraph","text":"Cameron Petrie and Frank Lynam’s research revisits an especially important problem in the region’s settlement surveys. Sites assigned to the same broad archaeological period were not necessarily occupied at the same moment. Their analysis tests ways of estimating overlap and suggests that a map displaying every recorded settlement together may exaggerate the number simultaneously inhabited. The authors explicitly acknowledge that their models cannot identify exactly which individual sites overlapped and require further testing against field evidence."},{"type":"paragraph","text":"That is a significant qualification, not a reason to discard the surveys. Surface material establishes valuable patterns, but a period lasting centuries is not a single day. Several nearby sites might represent successive occupations rather than a densely populated neighbourhood at one moment."},{"type":"heading","level":2,"text":"Reading a water feature carefully"},{"type":"paragraph","text":"A useful record of a well would distinguish its visible construction from its inferred age. Is the lining original, repaired or replaced? Does the inventory describe a functioning source or a surviving structure? Is the associated fort securely dated, and does that date necessarily apply to the well? These are separate questions; a compelling photograph cannot answer them all."},{"type":"paragraph","text":"Likewise, an ancient channel trace is evidence to investigate, not permission to draw a permanently flowing river through every period. Water history requires sediment, chronology and landscape study alongside the positions of sites. The absence of a visible channel today should invite enquiry without encouraging a romantic story of a single lost river explaining everything."},{"type":"paragraph","text":"Cholistan becomes richer when forts and water are read at several scales: the doorway and well, the enclosure and surrounding activity, the wider distribution of settlements. Such a view replaces the empty-desert backdrop with a landscape of practical decisions, while keeping the limits of the surviving evidence in sight."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Archaeology","Punjab","Cultural Landscapes"],"province":"Punjab","district":null,"relatedDistrictIds":["punjab-bahawalpur","punjab-rahim-yar-khan"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6959","major-doam-6978"],"relatedStoryIds":[],"contentType":"landscape","seo":{"title":"Cholistan’s wells, forts and traces of water","description":"Wells and storage features make Cholistan’s forts legible, while settlement research warns against reading every mapped mound as simultaneous.","primaryKeyword":"Cholistan water heritage landscape","socialTitle":"Cholistan’s wells, forts and traces of water","socialDescription":"Wells and storage features make Cholistan’s forts legible, while settlement research warns against reading every mapped mound as simultaneous."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Derawar Fort","url":"https://doam.gov.pk/public/sites/6959","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Khairgarh Fort","url":"https://doam.gov.pk/public/sites/6978","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Revisiting Settlement Contemporaneity and Exploring Stability and Instability","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7665820/","publisher":"Cameron Petrie and Frank Lynam, Journal of Field Archaeology","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Official fort entries checked in saved catalogue; only short water-feature identification used from underlying Mughal inventory. Petrie/Lynam indexed full article read, approximately 170 derived words. Models are not treated as a census or proven movement of any named group.","editorialReason":"Examine the spatial relationship of infrastructure and survival with documented mapping.","sortOrder":382}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-ravi-and-lahores-changing-edges','the-ravi-and-lahores-changing-edges','review','{"id":"story-the-ravi-and-lahores-changing-edges","type":"story","slug":"the-ravi-and-lahores-changing-edges","title":"The Ravi and Lahore’s changing edges","summary":"Shahdara’s tombs and present river planning show why Lahore’s historic edge must be read as a changing relationship with the Ravi.","body":[{"type":"paragraph","text":"The Ravi is often treated as the line beyond which Lahore ends. For heritage, it is more productive to ask how the city’s edge has changed and how important places were related across it. Shahdara’s tombs are not incidental monuments outside an urban centre. Their gardens, approaches and exposure to water place them within a larger landscape history."},{"type":"paragraph","text":"A map of individual buildings can hide that relationship. Jahangir’s Tomb and Nur Jahan’s Tomb appear as separate pins, yet questions of drainage, access and surrounding development do not stop at the boundary of either monument. The heritage setting includes the spaces between a protected building and the river."},{"type":"heading","level":2,"text":"Gardens were also working landscapes"},{"type":"paragraph","text":"James Wescoat’s discussion of water and work in Mughal landscapes encourages attention to the practical systems behind garden imagery. His account includes flood protection, noting the Alamgiri embankment at Lahore in the seventeenth century. The point is not that every river problem had a durable imperial solution. It is that gardens and monuments participated in hydraulic work and environmental uncertainty, rather than existing only as formal designs."},{"type":"paragraph","text":"This provides a useful corrective to a perfectly symmetrical garden plan. The plan records an intended order; water supply and drainage make that order possible in a particular place. A channel may have an aesthetic role and a practical one, while a surrounding floodplain belongs to a different scale of water movement."},{"type":"heading","level":2,"text":"The edge remains unsettled"},{"type":"paragraph","text":"A 2022 study of the Shahdara complex examines flooding, drainage and changes around the tombs. It draws attention to the surrounding mixture of settlement, infrastructure and floodplain, rather than discussing the monuments solely as isolated works of art. Its reported flood history is a reminder that damage can involve garden levels and enclosing walls as well as decorated chambers."},{"type":"paragraph","text":"A more recent environmental assessment for Ravi river-training works includes an archaeological map locating the Shahdara monuments in relation to the proposed corridor. That document is evidence of how heritage is represented within contemporary planning; it is not proof that every proposed intervention has been carried out or that its effects are settled."},{"type":"paragraph","text":"The two kinds of document answer different questions. A site study can identify conservation concerns. A project assessment can show proposed works and the features considered in planning. Neither should be collapsed into a simple claim that the river has been permanently controlled."},{"type":"heading","level":2,"text":"Looking beyond the façade"},{"type":"paragraph","text":"For an attentive visitor, the useful exercise is to look outward as well as inward. How is the garden approached? Where does the enclosure meet roads or neighbouring uses? Which parts of the river relationship can actually be seen, and which require historic maps or research?"},{"type":"paragraph","text":"Lahore’s changing edge is not a story of a picturesque river disappearing from a fixed city. It is a relationship among monuments, water, land and successive decisions. Keeping those elements together allows the Ravi to remain part of heritage interpretation without turning uncertain environmental history into a decorative backdrop."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Punjab","Cultural Landscapes"],"province":"Punjab","district":"Lahore","relatedDistrictIds":["punjab-lahore"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6479","major-doam-6472"],"relatedStoryIds":[],"contentType":"landscape","seo":{"title":"The Ravi and Lahore’s changing edges","description":"Shahdara’s tombs and present river planning show why Lahore’s historic edge must be read as a changing relationship with the Ravi.","primaryKeyword":"Ravi Lahore heritage landscape","socialTitle":"The Ravi and Lahore’s changing edges","socialDescription":"Shahdara’s tombs and present river planning show why Lahore’s historic edge must be read as a changing relationship with the Ravi."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Urban Generosity: Strategies for Rejuvenation of Historic Site—Mughal Tombs of Shahdara","url":"https://ojs.plhr.org.pk/journal/article/download/290/209/414","publisher":"Pakistan Languages and Humanities Review","accessDate":"2026-10-22"},{"title":"EIA of River Training Works and Flood Control Infrastructure of River Ravi","url":"https://epd.punjab.gov.pk/system/files/2026%20EPA%2001-EIA%20of%20RTW%20%26%20FCI%20Railway%20Bridge%20to%20SL-04%20%281%29.pdf","publisher":"Punjab Environment Protection Department / RUDA","accessDate":"2026-10-22"},{"title":"Water and Work in Mughal Gardens and Landscapes","url":"https://www.sciencedirect.com/org/science/article/pii/S2666627822000032","publisher":"James Wescoat","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Read indexed relevant text of research paper and EIA archaeological map, not all EIA appendices. Present planning document does not verify project completion or safety. Flood list and depth figures intentionally omitted. Approximately 100–130 words per scholarly source and 60 EIA-derived words.","editorialReason":"Distinguish historical river relationships from today’s engineered banks.","sortOrder":383}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-chenab-crossings-and-places-of-stopping','chenab-crossings-and-places-of-stopping','review','{"id":"story-chenab-crossings-and-places-of-stopping","type":"story","slug":"chenab-crossings-and-places-of-stopping","title":"Chenab crossings and places of stopping","summary":"A mail station and a residence near the Chenab suggest different forms of stopping, movement and dependence on a river crossing.","body":[{"type":"paragraph","text":"A crossing is more than a point where a road meets water. It involves approaches, waiting, information and places where people can stop. Around Wazirabad and the Chenab, surviving structures allow these functions to be considered separately. A building associated with communication does not tell the same story as a residence, even when both belong to a wider landscape of movement."},{"type":"paragraph","text":"The federal heritage catalogue identifies a Dak Chowki near Wazirabad’s railway junction and the Grand Trunk route. Its description records an arched masonry structure with losses to the upper fabric. The identification as a mail station provides a starting point, but the entry’s attribution contains a chronological inconsistency. It should not be converted into a confident founding date."},{"type":"heading","level":2,"text":"A stop is not automatically a caravanserai"},{"type":"paragraph","text":"The distinction matters because familiar route language can quickly fill gaps in evidence. An arched structure is not sufficient proof of stables, lodging, a particular postal system or a named ruler’s visit. Each proposed function needs support from the building’s arrangement or documentary record. At the Dak Chowki, the useful question is what the surviving spaces could accommodate and what further evidence underpins the catalogue name."},{"type":"paragraph","text":"This approach does not make the building less interesting. It changes attention from an attractive but uncertain anecdote to the relationship between architecture and communication. A small structure may carry a major historical question without having to become a miniature palace or a complete roadside inn."},{"type":"heading","level":2,"text":"Residence and route"},{"type":"paragraph","text":"The residence associated with Ranjit Singh on the eastern side of the Chenab offers a different kind of stopping place. Its association is residential rather than a general facility for travellers. Comparing the two sites helps separate movement through a region from occupation within it. A person staying beside a river and a messenger passing through a network have different requirements, even if their journeys share a road."},{"type":"paragraph","text":"The river landscape also includes smaller waterways. The Federal Flood Commission identifies Palkhu’s connection with the Chenab around Wazirabad and relates it to the Grand Trunk crossing and Khanki. This is a useful reminder that a crossing belongs to a drainage network, not only to the main channel represented by a bold line on a map."},{"type":"heading","level":2,"text":"What a historical route requires"},{"type":"paragraph","text":"To reconstruct a route at a particular date, one would need to align several kinds of evidence: the position of the crossing, the approach roads, the functions of nearby structures and their periods of use. Mere proximity cannot establish that all operated together. Nor can a present road prove that its alignment has remained unchanged."},{"type":"paragraph","text":"These sites reward a slower form of discovery. Instead of asking only which ruler built what, ask what kind of pause each place represents and how it relates to movement. The Chenab then becomes part of the historical explanation, not simply the scenic view beside it."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Punjab","Cultural Landscapes"],"province":"Punjab","district":null,"relatedDistrictIds":["punjab-wazirabad"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-10112","major-doam-10106"],"relatedStoryIds":[],"contentType":"landscape","seo":{"title":"Chenab crossings and places of stopping","description":"A mail station and a residence near the Chenab suggest different forms of stopping, movement and dependence on a river crossing.","primaryKeyword":"Chenab heritage crossings","socialTitle":"Chenab crossings and places of stopping","socialDescription":"A mail station and a residence near the Chenab suggest different forms of stopping, movement and dependence on a river crossing."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Dak Chowki","url":"https://doam.gov.pk/public/sites/10106","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Ranjit Singh Summer Residence","url":"https://doam.gov.pk/public/sites/10112","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Salient features and flood limits of nullahs","url":"https://ffc.gov.pk/salient-feature-flood-limits-of-nullahs/","publisher":"Federal Flood Commission","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Catalogue 10106 contains internally impossible 1560s/Sher Shah attribution; omitted and flagged. No stable remains, horses, founder or construction date asserted. Residence already used370: only brief riverbank association repeated. FFC official tributary entry consulted; no live risk advice.","editorialReason":"Use documented roadside and riverside structures without inventing a continuous ancient route.","sortOrder":384}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-salt-range-viewed-in-section','the-salt-range-viewed-in-section','review','{"id":"story-the-salt-range-viewed-in-section","type":"story","slug":"the-salt-range-viewed-in-section","title":"The Salt Range viewed in section","summary":"Geology, hilltop architecture and water give the Salt Range several distinct timescales that should not be compressed into one ancient landscape.","body":[{"type":"paragraph","text":"Seen in section, the Salt Range is a place where different kinds of time become visible together. Rocks belong to geological histories; a ridge acquires its present form through uplift and erosion; buildings occupy selected positions within that terrain. Calling the whole view ancient conceals the distinctions between those processes."},{"type":"paragraph","text":"The Geological Society’s account explains the range through the continuing collision of the Indian plate with Asia. Sedimentary layers have been folded and uplifted, while salt at depth has helped layers detach and move relative to the underlying crust. This is not a claim that the hills and every rock within them are the same age."},{"type":"heading","level":2,"text":"Layers before landmarks"},{"type":"paragraph","text":"A 2026 United States Geological Survey data release addresses age constraints on the Salt Range Formation using samples from named localities. Its existence is a reminder that even a familiar geological label is subject to investigation. The date of a formation, the timing of mountain building and the age of a temple are not interchangeable measurements."},{"type":"paragraph","text":"For heritage interpretation, this matters because stone is not simply a neutral pedestal. Terrain influences where an approach is possible and what can be seen from a site. Yet a dramatic hilltop position does not by itself explain why a particular building was founded there. Geological context can frame the question without replacing historical evidence."},{"type":"heading","level":2,"text":"Buildings occupy particular terrain"},{"type":"paragraph","text":"The federal catalogue places Nandana’s remains within a constrained hill setting and records several kinds of surviving structures. At Katas Raj, the ensemble includes temples, water and later buildings. These are different relationships with land: an elevated position and approach in one case, a group organised partly around a pool in the other. Neither can stand for every settlement or religious site in the range."},{"type":"paragraph","text":"Malot offers another architectural focus within this regional comparison. Connecting it with Nandana and Katas on an atlas should invite a study of distinct sites, not imply a single construction campaign or identical religious history. Their shared landscape is a reason to compare them, not permission to erase their differences."},{"type":"heading","level":2,"text":"Three scales of looking"},{"type":"paragraph","text":"A useful first scale is the wider landform: ridge, slope, valley and water. The second is the site’s placement within it: approach, enclosure, orientation and relationship to nearby habitation. The third is the material detail of a particular wall or carved element. Moving between these scales helps avoid mistaking a close-up of stone for an explanation of the whole landscape."},{"type":"paragraph","text":"It also suggests what a photograph cannot establish. Similar-looking stone need not come from the same quarry; a nearby cliff does not prove a building’s material was extracted there. Such connections require identification and evidence."},{"type":"paragraph","text":"The Salt Range is compelling precisely because its histories do not fit one clock. Reading the landscape in section allows geological depth, architectural decisions and present settlement to coexist without turning them into an undifferentiated story of antiquity."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Punjab","Cultural Landscapes"],"province":"Punjab","district":null,"relatedDistrictIds":["punjab-chakwal","punjab-jhelum"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6535","major-doam-8267","major-doam-6750"],"relatedStoryIds":[],"contentType":"landscape","seo":{"title":"The Salt Range viewed in section","description":"Geology, hilltop architecture and water give the Salt Range several distinct timescales that should not be compressed into one ancient landscape.","primaryKeyword":"Salt Range terrain heritage","socialTitle":"The Salt Range viewed in section","socialDescription":"Geology, hilltop architecture and water give the Salt Range several distinct timescales that should not be compressed into one ancient landscape."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"The Salt Range, Pakistan","url":"https://www.geolsoc.org.uk/science-and-policy/plate-tectonic-stories/the-salt-range/","publisher":"Geological Society of London","accessDate":"2026-10-22"},{"title":"Data to determine new age constraints on the Ediacaran Salt Range Formation of Pakistan","url":"https://www.usgs.gov/data/data-determine-new-age-constraints-ediacaran-salt-range-formation-pakistan","publisher":"United States Geological Survey","accessDate":"2026-10-22"},{"title":"Nandana Fort","url":"https://doam.gov.pk/public/sites/8267","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Katas Raj","url":"https://doam.gov.pk/public/sites/6750","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Geological Society explanatory text read; 2026 USGS dataset description indexed. Avoid numeric age conflict between older society text and newer Ediacaran investigation. Nandana erroneous Chingez1021 claim and Katas blanket ancient haveli dates rejected. Approx150 geological derived words; monument features under100combined.","editorialReason":"Explain how ridges, passes and resources shape distinct sites across periods.","sortOrder":385}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-kallar-kahar-lake-garden-memory-and-a-stone-platform','kallar-kahar-lake-garden-memory-and-a-stone-platform','review','{"id":"story-kallar-kahar-lake-garden-memory-and-a-stone-platform","type":"story","slug":"kallar-kahar-lake-garden-memory-and-a-stone-platform","title":"Kallar Kahar: lake, garden memory and a stone platform","summary":"Babur’s account of lake and garden can be read beside Takht-i-Babri without assuming that every surviving stone is unchanged from his visit.","body":[{"type":"paragraph","text":"Kallar Kahar brings together a lake, the memory of a garden and a small stone platform associated with Babur. Their proximity makes a persuasive scene, but each offers a different kind of evidence. A memoir records an experience and a claim of garden-making; a surviving structure has its own material history; later accounts explain how the place has been remembered."},{"type":"paragraph","text":"Keeping these forms of evidence distinct allows the setting to remain evocative without requiring every element to have survived unchanged since the sixteenth century."},{"type":"heading","level":2,"text":"A lake in the memoir"},{"type":"paragraph","text":"In Annette Beveridge’s translation of the Baburnama, the entry for February 1519 describes Kalda-kahar as enclosed by the Jud mountains. Babur notes a lake gathering runoff, a meadow and a spring on the western hillside. He also refers to a garden he made there, Bagh-i-Safa. The account connects pleasure in a place with specific features of water and terrain rather than offering only a general compliment to scenery."},{"type":"paragraph","text":"The passage is especially useful because it distinguishes the spring, lake and meadow. They are not a single decorative water feature. They belong to a landscape in which different sources and spaces could shape the attraction of a garden site."},{"type":"heading","level":2,"text":"A platform and its later life"},{"type":"paragraph","text":"The federal catalogue describes Takht-i-Babri as a stone platform with tapering sides and notes renovation and a commemorative inscription associating it with Babur. That record supports discussion of a remembered royal connection; it does not by itself establish that every visible stone belongs to one original construction event."},{"type":"paragraph","text":"The Punjab Small Industries Corporation’s Chakwal publication also presents the platform and Bagh-e-Safa within the district’s heritage. Its narrative illustrates the continuing importance of the association. More detailed stories about exactly what Babur did on the platform require their own evidence and should not be substituted for what his memoir actually says."},{"type":"heading","level":2,"text":"Reading the setting together"},{"type":"paragraph","text":"The most revealing comparison is therefore between text and terrain. Which relationships in the memoir can still be understood in the wider setting? Where are later structures, repairs or altered uses visible? Which features are remembered through a name even when their original extent is uncertain?"},{"type":"paragraph","text":"These questions are different from trying to stage a precise scene from Babur’s day. A garden remembered over centuries can accumulate new meanings, while the surrounding town and access routes change. Survival need not mean stasis, and restoration should be documented as part of the place’s history rather than made invisible."},{"type":"paragraph","text":"For an archive, a photograph of the platform benefits from a caption identifying its association and recorded repair history. A broader lake view benefits from a date and viewpoint. Together with the memoir, those records create a layered account of Kallar Kahar: water observed, a garden claimed, a platform commemorated and a landscape continuing beyond the moment of a royal visit."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Punjab","Cultural Landscapes"],"province":"Punjab","district":"Chakwal","relatedDistrictIds":["punjab-chakwal"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6836"],"relatedStoryIds":[],"contentType":"landscape","seo":{"title":"Kallar Kahar: lake, garden memory and a stone platform","description":"Babur’s account of lake and garden can be read beside Takht-i-Babri without assuming that every surviving stone is unchanged from his visit.","primaryKeyword":"Kallar Kahar cultural landscape","socialTitle":"Kallar Kahar: lake, garden memory and a stone platform","socialDescription":"Babur’s account of lake and garden can be read beside Takht-i-Babri without assuming that every surviving stone is unchanged from his visit."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"The Babur-nama in English, volume2, page381","url":"https://uzbekliterature.uz/sites/default/files/baburnama_2.pdf","publisher":"Babur; translated by Annette Beveridge","accessDate":"2026-10-22"},{"title":"Takht-i-Babri","url":"https://doam.gov.pk/public/sites/6836","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Crafts and Craftsmen of Punjab: Chakwal","url":"https://www.psic.gop.pk/Download%28psic%29/Crafts-of-Chakwal-1.pdf","publisher":"Punjab Small Industries Corporation","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Beveridge translated passage p381 indexed and read; no quotations. DOAM platform description saved official catalogue. PSIC later narrative treated as commemoration rather than independent proof of meditation/army speeches. Approximately150words memoir-derived,80catalogue,40PSIC.","editorialReason":"Connect documented built evidence with landscape while qualifying later narratives.","sortOrder":386}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-pothohar-plateau-between-village-and-route','the-pothohar-plateau-between-village-and-route','review','{"id":"story-the-pothohar-plateau-between-village-and-route","type":"story","slug":"the-pothohar-plateau-between-village-and-route","title":"The Pothohar plateau between village and route","summary":"Forts, settlement traces and a pass show how Pothohar can be read between local occupation and movement across a wider plateau.","body":[{"type":"paragraph","text":"Pothohar is often introduced as a landscape between larger destinations. That description can make its villages and smaller remains seem like intervals on somebody else’s journey. A more useful approach begins with occupation: places where people lived, worked, gathered and controlled access, as well as routes through which they moved."},{"type":"paragraph","text":"The plateau does not present one uniform historical surface. Different kinds of evidence—settlement mounds, forts, religious buildings and road remains—belong to different periods and levels of preservation. Their proximity is worth investigating, but it cannot by itself make them part of a single system."},{"type":"heading","level":2,"text":"Enclosure and surrounding settlement"},{"type":"paragraph","text":"At Sangni, the federal inventory records a compact fort with corner bastions and a defined entrance. Dhan Gali is described as a ruined enclosure built in small brick and mortar, with a tentative Mughal attribution. These records supply useful architectural observations while leaving important questions open. A fort’s outline alone cannot identify all the people who used it or establish the extent of its authority."},{"type":"paragraph","text":"The difference between a fort and the wider place around it is equally important. Walls concentrate attention, while less conspicuous occupation can disappear from a visitor’s mental map. A comprehensive account would ask about nearby settlement evidence and later uses, rather than treating everything outside the enclosure as empty background."},{"type":"heading","level":2,"text":"A route has a material history"},{"type":"paragraph","text":"The catalogue’s record for the Margalla Pass and Grand Trunk route introduces movement at another scale. It describes surviving road fabric and discusses historical associations. Such an entry should not be read as proof that every famous traveller used the exact surviving alignment. Roads can be repaired, widened, diverted and renamed; their history is rarely a single line maintained without change."},{"type":"paragraph","text":"Putting a pass and a fort on the same map therefore creates a research question, not an automatic answer. Were their periods of use contemporary? What other approaches existed? Did the fort actually control movement along that route, or is the connection only a modern visual impression?"},{"type":"heading","level":2,"text":"The landscape of recording"},{"type":"paragraph","text":"The Urban Unit’s Rawalpindi Division heritage report describes a planning method combining field visits, survey forms, digital recording and consultation. It also recognises that conditions have changed since earlier archaeological surveys. The inventory is consequently a record of investigation as well as a catalogue of places: its coverage depends on where researchers looked and when they recorded it."},{"type":"paragraph","text":"This is particularly relevant to modest sites. A ruined wall or spread of pottery may receive less attention than an intact monument, despite its value for understanding settlement. Absence from a convenient visitor list does not establish absence of history."},{"type":"paragraph","text":"Pothohar can thus be explored through two linked questions: how were particular places occupied, and how were they connected? Moving between village, enclosure and route makes the plateau a subject in its own right, without turning its many histories into a generic gateway between better-known regions."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Punjab","Cultural Landscapes"],"province":"Punjab","district":null,"relatedDistrictIds":["punjab-rawalpindi"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6922","major-doam-6923","major-doam-6684"],"relatedStoryIds":[],"contentType":"landscape","seo":{"title":"The Pothohar plateau between village and route","description":"Forts, settlement traces and a pass show how Pothohar can be read between local occupation and movement across a wider plateau.","primaryKeyword":"Pothohar cultural landscape","socialTitle":"The Pothohar plateau between village and route","socialDescription":"Forts, settlement traces and a pass show how Pothohar can be read between local occupation and movement across a wider plateau."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Archaeology and Cultural Heritage Report: Rawalpindi Division","url":"https://urbanunit.gov.pk/Download/publications/Files/20/2024/Archaeology%20Sector%20Plan%20Rawalpindi.pdf","publisher":"The Urban Unit, Punjab","accessDate":"2026-10-22"},{"title":"Sangni Fort","url":"https://doam.gov.pk/public/sites/6922","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Dhan Gali Fort","url":"https://doam.gov.pk/public/sites/6923","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Margalla Pass, GT Road","url":"https://doam.gov.pk/public/sites/6684","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"UrbanUnit indexed methodological section read; no unverified continuous-city antiquity claim repeated. Sangni/DhanGali official inventory descriptions collectivelyunder130 words from shared2010survey. Margalla entry attribution remains qualified; no claimnamedancientrulerusedexactroad.","editorialReason":"Read dispersed structures as evidence of varied use, not an invented single kingdom.","sortOrder":387}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-sulaiman-foothills-as-an-archaeological-borderland','the-sulaiman-foothills-as-an-archaeological-borderland','review','{"id":"story-the-sulaiman-foothills-as-an-archaeological-borderland","type":"story","slug":"the-sulaiman-foothills-as-an-archaeological-borderland","title":"The Sulaiman foothills as an archaeological borderland","summary":"A small recorded settlement on the Sulaiman foothills illustrates why borderland archaeology needs precise chronology and attention to local terrain.","body":[{"type":"paragraph","text":"An archaeological borderland is not necessarily a thin strip between two self-contained cultures. Along the Sulaiman foothills, the more useful questions concern relationships among slopes, passages and adjoining plains. A modern provincial boundary can help locate a record, but it cannot define the full range of movement or interaction in an earlier period."},{"type":"paragraph","text":"The area also demonstrates why small archaeological sites deserve attention alongside prominent sacred places. Their physical modesty can conceal the importance of the questions they raise about settlement, material use and the history of survey."},{"type":"heading","level":2,"text":"A recorded site at Khalath"},{"type":"paragraph","text":"The federal catalogue describes Khalath as a small ruined settlement with a partly visible stone wall, a platform, ceramics and stone-working material. It links the record to a 2019 study by Zakirullah Jan and colleagues of sites along the Koh-e-Suleiman foothills in Dera Ghazi Khan. The study’s introduction identifies its focus as the late Neolithic settlements documented within a wider survey that also recorded other periods."},{"type":"paragraph","text":"The catalogue’s dating fields require care. Its broad numerical chronology does not sit comfortably with all the material labels in the description. Rather than selecting whichever date sounds more impressive, the responsible reading separates the observed remains from the chronological interpretation and refers the discrepancy back to the original research."},{"type":"heading","level":2,"text":"What surface evidence can tell us"},{"type":"paragraph","text":"The description nevertheless contains meaningful distinctions. A built wall is evidence of construction; ceramics may help identify activities or periods; stone tools and cores raise questions about manufacture and use. Those materials should not be merged into a single imagined household scene unless their association has been demonstrated."},{"type":"paragraph","text":"For example, finds visible across a site may come from more than one occupation or from disturbed deposits. A precise account needs to know where material was recovered and whether it came from a surface survey or an excavated context. These are not technical distractions: they determine what can be said about the people who used the place."},{"type":"heading","level":2,"text":"Different histories in one foothill region"},{"type":"paragraph","text":"The shrine of Sakhi Sarwar belongs to a very different historical and social context. Its presence in the same regional atlas should broaden the range of questions, not imply a direct continuity from the prehistoric settlement. Archaeological remains and a sacred place can share a landscape while requiring different kinds of evidence and different forms of respectful engagement."},{"type":"paragraph","text":"This distinction also prevents the region from becoming merely a passage between better-known centres. A borderland has places of residence, devotion and work, not just movement through it. Their histories cannot be reconstructed from a line joining distant cities."},{"type":"paragraph","text":"The Sulaiman foothills therefore reward a deliberately local scale of discovery. Begin with a named site and what has actually been recorded there; then consider its terrain and possible connections. Such an approach preserves the significance of the region while leaving genuine chronological and interpretive uncertainties open to further research."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Archaeology","Punjab","Cultural Landscapes"],"province":"Punjab","district":null,"relatedDistrictIds":["punjab-taunsa","punjab-dera-ghazi-khan"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-9504","major-doam-10103"],"relatedStoryIds":[],"contentType":"landscape","seo":{"title":"The Sulaiman foothills as an archaeological borderland","description":"A small recorded settlement on the Sulaiman foothills illustrates why borderland archaeology needs precise chronology and attention to local terrain.","primaryKeyword":"Sulaiman foothills archaeology landscape","socialTitle":"The Sulaiman foothills as an archaeological borderland","socialDescription":"A small recorded settlement on the Sulaiman foothills illustrates why borderland archaeology needs precise chronology and attention to local terrain."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Late Neolithic Period Sites Along Koh-e-Suleiman in Dera Ghazi Khan: Recent Discoveries","url":"https://iris.unive.it/retrieve/8b3f9ad1-e02a-4af2-a47f-719f202863e6/20-19-PB.pdf","publisher":"Zakirullah Jan and colleagues, Journal of Asian Civilizations","accessDate":"2026-10-22"},{"title":"Khalath","url":"https://doam.gov.pk/public/sites/9504","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Sakhi Sarwar Shrine","url":"https://doam.gov.pk/public/sites/10103","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"2019 paper introduction available through indexed text; fullPDF403, therefore no claimfullclose-read. Khalath catalogue descriptive observationsused; blanket8000–5600BCEfield rejected as conflicts with KotDijian materialdescription. SakhiSarwaridentityonly; inconsistenthagiographicdatesnotadopted. Narrowevidencepiece,pendingfullpaperreview.","editorialReason":"Connect topography and surveyed remains without treating the foothills as an empty barrier.","sortOrder":388}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-maklis-scale-walking-a-funerary-landscape','maklis-scale-walking-a-funerary-landscape','review','{"id":"story-maklis-scale-walking-a-funerary-landscape","type":"story","slug":"maklis-scale-walking-a-funerary-landscape","title":"Makli’s scale: walking a funerary landscape","summary":"Makli’s extent is best understood through relationships among tombs, terrain, living attachments and conservation needs—not by counting monuments alone.","body":[{"type":"paragraph","text":"Makli is not one tomb enlarged to monumental scale. It is a funerary landscape in which individual structures, groups, open ground and changes in terrain must be understood together. The first challenge for a visitor is therefore not to identify every monument, but to recognise that the spaces between them are part of the place."},{"type":"paragraph","text":"UNESCO’s recognition concerns an ensemble extending across a substantial necropolis near Thatta. A close view of one carved surface can reveal exceptional workmanship, yet it cannot explain the organisation or significance of the whole. Both scales are necessary: the detail that invites attention and the wider setting that gives it relationships."},{"type":"heading","level":2,"text":"Distance changes interpretation"},{"type":"paragraph","text":"From a single viewpoint, monuments can appear to belong to one continuous composition. Moving through a landscape reveals differences in enclosure, approach, size and grouping. Those differences should not automatically be translated into a simple hierarchy of wealth or a chronological sequence. Such interpretations require records of the particular monuments."},{"type":"paragraph","text":"An attentive approach is to compare relationships: whether a structure stands within a group, how its entrance addresses surrounding space, and what parts of its setting remain legible. This is a method of looking, not a proposed walking route. Current access, safe paths and conservation restrictions need to be checked with the site authorities."},{"type":"heading","level":2,"text":"The necropolis is not socially empty"},{"type":"paragraph","text":"The Sindh Directorate of Antiquities describes its We Connect Makli initiative as a project linking communities, government bodies and other custodians around heritage protection and disaster preparedness. Implemented between March 2021 and October 2022, it included objectives for emergency response, communication and risk planning. The project account explicitly recognises religious attachments to the site."},{"type":"paragraph","text":"That perspective changes the meaning of an apparently quiet landscape. A funerary site can remain important to living communities without functioning like a conventional residential neighbourhood. Conservation must consequently consider relationships and responsibilities as well as the physical condition of stone or brick."},{"type":"heading","level":2,"text":"Water moves across the whole site"},{"type":"paragraph","text":"Conservation reporting submitted to UNESCO following the 2022 rains discusses drainage and the effects of water within Makli’s terrain. Such concerns cannot be solved by looking at each monument as an isolated object. Water follows levels and pathways that cross the boundaries of individual structures, making the broader landscape part of the conservation problem."},{"type":"paragraph","text":"A photograph that excludes the ground around a tomb may therefore omit evidence relevant to its condition. Conversely, a distant panorama may conceal vulnerable surfaces. Good documentation needs both context and detail, dated carefully enough to support comparison over time."},{"type":"paragraph","text":"Makli’s scale becomes meaningful when it changes how we look: outward from an inscription or carving to a group of monuments, then to terrain and living attachments. The result is more than an impressive count of tombs. It is a recognition that heritage here is an ensemble of material, space and continuing human concern."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Conservation","Sindh","Cultural Landscapes"],"province":"Sindh","district":"Thatta","relatedDistrictIds":["sindh-thatta"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["unesco-143"],"relatedStoryIds":[],"contentType":"landscape","seo":{"title":"Makli’s scale: walking a funerary landscape","description":"Makli’s extent is best understood through relationships among tombs, terrain, living attachments and conservation needs—not by counting monuments alone.","primaryKeyword":"Makli cultural landscape","socialTitle":"Makli’s scale: walking a funerary landscape","socialDescription":"Makli’s extent is best understood through relationships among tombs, terrain, living attachments and conservation needs—not by counting monuments alone."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Historical Monuments at Makli, Thatta","url":"https://whc.unesco.org/en/list/143/","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"We Connect Makli Project","url":"https://antiquities.sindhculture.gov.pk/weconnectmakliproject/","publisher":"Directorate General of Antiquities, Government of Sindh","accessDate":"2026-10-22"},{"title":"State Party conservation report for Makli","url":"https://whc.unesco.org/document/204957","publisher":"Pakistan, submitted to UNESCO","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"UNESCOpropertysourcebriefidentityonly(previous341used130words). Sindhprojectpagefullreadapprox150words. StatePartyreportindexedsectionsaboutdrainageand2022rainread; full18MBreaderfailed, notclaimallread. No suggestedwalkroute,currentconditionsoraccessguarantee.","editorialReason":"Focus on spatial extent and conservation rather than repeat tomb-by-tomb biographies.","sortOrder":389}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-indus-delta-and-the-changing-idea-of-a-port','the-indus-delta-and-the-changing-idea-of-a-port','review','{"id":"story-the-indus-delta-and-the-changing-idea-of-a-port","type":"story","slug":"the-indus-delta-and-the-changing-idea-of-a-port","title":"The Indus delta and the changing idea of a port","summary":"Excavation at Banbhore shows why identifying a historic port requires more than matching a ruined city to today’s shoreline.","body":[{"type":"paragraph","text":"A ruined city beside a creek does not explain its former harbour at a glance. The coastline may have changed, channels may have shifted, and later buildings may cover earlier activity. Banbhore is particularly valuable because its excavations show how an apparently simple question—where was the port?—can remain open even when a settlement’s wider maritime importance is clear."},{"type":"paragraph","text":"The archaeological project places Banbhore on the northern bank of Gharo Creek, well inland from the present shoreline. Its account includes a fortified area and extensive remains outside it. This broader setting matters: a port is not only a gate or quay, but a relationship among water access, settlement and activities on land."},{"type":"heading","level":2,"text":"Names are hypotheses too"},{"type":"paragraph","text":"The Pakistani-Italian research team discusses Banbhore’s proposed identification with places named in historical texts, including Daybul or Debal. The authors acknowledge continuing debate. Similarity of location and evidence of trade are important, but neither automatically settles the relationship between an excavated site and every ancient place-name associated with it."},{"type":"paragraph","text":"Keeping that distinction visible avoids a circular argument in which a name is used to prove the interpretation that originally produced the name. Archaeological evidence and written accounts can illuminate one another without being forced into premature agreement."},{"type":"heading","level":2,"text":"Excavation can revise a persuasive feature"},{"type":"paragraph","text":"Eveha’s report on the French mission’s 2015 work offers a concrete example. A wall previously considered in connection with a possible harbour location was re-examined. The excavators interpreted it instead as two phases of masonry associated with a small building and reinforcement along a change in slope. They concluded that the original port location remained uncertain."},{"type":"paragraph","text":"The same campaign recorded alternating alluvial and sandy deposits, with traces of relatively short occupations in some levels. These observations linked settlement activity with changing water conditions. The report also distinguished earlier occupation from the construction and alteration of the visible fortification. A standing wall therefore cannot be assumed to represent the beginning of the place."},{"type":"heading","level":2,"text":"A port is a relationship, not a silhouette"},{"type":"paragraph","text":"For a reader, these findings suggest a different way of looking at the delta. Instead of searching only for a recognisable harbour shape, ask which evidence supports a relationship with water: deposits, structures, artefacts and the changing levels at which people occupied the ground. Each contributes something different."},{"type":"paragraph","text":"The distinction is especially useful when modern photographs show dry ground where an account discusses river activity. The mismatch is not necessarily an error; it may be the historical question. Yet explaining it requires dated evidence, not a general assumption that every coastal ruin was abandoned because the sea withdrew."},{"type":"paragraph","text":"Banbhore’s value lies partly in this capacity to revise expectations. Its port history becomes more interesting when uncertainty is retained: a city whose connections can be investigated, a delta whose form has changed, and an excavation record that shows how interpretations improve when earlier assumptions are tested."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Sindh","Cultural Landscapes"],"province":"Sindh","district":null,"relatedDistrictIds":["sindh-thatta"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5512"],"relatedStoryIds":[],"contentType":"landscape","seo":{"title":"The Indus delta and the changing idea of a port","description":"Excavation at Banbhore shows why identifying a historic port requires more than matching a ruined city to today’s shoreline.","primaryKeyword":"Indus delta historic ports","socialTitle":"The Indus delta and the changing idea of a port","socialDescription":"Excavation at Banbhore shows why identifying a historic port requires more than matching a ruined city to today’s shoreline."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Banbhore: Pakistani-Italian Excavations and Research","url":"https://easaa.org/wp-content/uploads/2023/01/Felici-et-al-8.pdf","publisher":"Anna Candida Felici and colleagues","accessDate":"2026-10-22"},{"title":"Banbhore archaeological project","url":"https://www.centroscavitorino.it/en/siti-di-scavo/banbhore-2/","publisher":"Centro Ricerche Archeologiche e Scavi di Torino","accessDate":"2026-10-22"},{"title":"Banbhore—2015","url":"https://eveha-international.com/?p=4705&lang=en","publisher":"Eveha International / archaeological mission","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Eveha2015fulltextread; approximately170derivedwords. FelicietalindexedintroductionandCRASTdescriptionread,combined~140. Debal/Barbarikonnotassertedsettled; portpositionexplicitlyunresolvedin2015report. No2026submergeddiscoveryclaimused.","editorialReason":"Explain shifting water and archaeological interpretation without presenting reconstructed shorelines as certain.","sortOrder":390}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-thar-settlement-around-scarce-water','thar-settlement-around-scarce-water','review','{"id":"story-thar-settlement-around-scarce-water","type":"story","slug":"thar-settlement-around-scarce-water","title":"Thar: settlement around scarce water","summary":"Water storage, groundwater differences and seasonal work give Thar a more precise history than the familiar image of an empty desert.","body":[{"type":"paragraph","text":"Thar’s settlement history cannot be separated from the practical work of finding and storing water. Yet water scarcity is not a complete description of the region. The important differences include where rain can be collected, where groundwater is usable and how access changes through the year. A single desert photograph reveals very little of that variation."},{"type":"paragraph","text":"The Pakistan Council of Research in Water Resources distinguishes rainfall storage from groundwater development in its dryland work. Its accounts discuss collecting runoff in depressions and underground storage, while its Thar research identifies mostly saline groundwater alongside scattered freshwater pockets. These are different resources requiring different kinds of knowledge and infrastructure."},{"type":"heading","level":2,"text":"A source is not a system"},{"type":"paragraph","text":"A well marked on a map tells us that a structure exists; it does not establish the quality, reliability or accessibility of its water. A storage pond likewise needs a catchment, maintenance and arrangements for use. Thinking in systems rather than isolated objects brings the surrounding terrain and human work into the picture."},{"type":"paragraph","text":"PCRWR’s 2018–19 report describes geophysical exploration intended to locate freshwater pockets in Thar, alongside work on rainwater harvesting and saline agriculture. The report is valuable because it records investigation, not a claim that all villages face the same conditions or that one intervention solved the region’s needs."},{"type":"paragraph","text":"At the council’s Mithi field station, the institutional description distinguishes rainwater ponds, a tubewell and experimental cultivation. It also notes features such as silt traps and water-level gauges. These details show why a body of stored water is more than a hole in the ground: the management of sediment and the monitoring of supply are part of its operation."},{"type":"heading","level":2,"text":"Heritage beyond the picturesque well"},{"type":"paragraph","text":"For a cultural archive, the question is not only which water structure is old. It is also how people maintain, share and adapt it. Those practices require testimony from the people involved, with dates and consent. They should not be invented from a general account of desert life or assigned uniformly to every community."},{"type":"paragraph","text":"Gori Temple and Naukot Fort provide prominent heritage anchors in the wider Thar region, but their presence does not explain the water arrangements of nearby settlements. Connecting them with a landscape article should encourage broader attention rather than imply that the same water system served every place across centuries."},{"type":"heading","level":2,"text":"Looking seasonally"},{"type":"paragraph","text":"A photograph taken after rain and one taken in a dry period can describe very different conditions at the same location. Recording the date is therefore essential. The visible amount of water is not a stable attribute comparable to the height of a wall."},{"type":"paragraph","text":"Thar becomes more legible when the landscape is read through this combination of place, season and work. Scarcity remains a real concern, but it need not erase the specificity of settlement or reduce its inhabitants to an anonymous story of endurance. Water history is also a history of decisions, knowledge and changing possibilities."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Sindh","Cultural Landscapes"],"province":"Sindh","district":null,"relatedDistrictIds":["sindh-tharparkar"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5499","major-doam-5504"],"relatedStoryIds":[],"contentType":"landscape","seo":{"title":"Thar: settlement around scarce water","description":"Water storage, groundwater differences and seasonal work give Thar a more precise history than the familiar image of an empty desert.","primaryKeyword":"Thar water cultural landscape","socialTitle":"Thar: settlement around scarce water","socialDescription":"Water storage, groundwater differences and seasonal work give Thar a more precise history than the familiar image of an empty desert."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Rainwater harvesting","url":"https://www.pcrwr.gov.pk/rainwater-harvesting/","publisher":"Pakistan Council of Research in Water Resources","accessDate":"2026-10-22"},{"title":"Annual Report2018–19, Thar groundwater project","url":"https://www.pcrwr.gov.pk/wp-content/uploads/2020/Annual-Reports/Annual-Report-2018-19.pdf","publisher":"Pakistan Council of Research in Water Resources","accessDate":"2026-10-22"},{"title":"Tandojam research and Mithi field station","url":"https://www.pcrwr.gov.pk/tandojam/","publisher":"Pakistan Council of Research in Water Resources","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Primaryinstitutionaldescriptionsread; specificTharannualreportsectionindexed. GenericdrylandpageincludesCholistan,notalltermsassignedexclusivelyThar. Historicalpopulation/rainfallstatisticsnotpresentedcurrent. Eachsourceunder150derivedwords. Nohealth/waterpotabilityrecommendation.","editorialReason":"Investigate documented settlement strategies without romanticising environmental hardship.","sortOrder":391}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-manchar-as-a-lived-waterscape','manchar-as-a-lived-waterscape','review','{"id":"story-manchar-as-a-lived-waterscape","type":"story","slug":"manchar-as-a-lived-waterscape","title":"Manchar as a lived waterscape","summary":"Manchar’s boats and shoreline settlements belong to a changing relationship between water quality, livelihoods and home.","body":[{"type":"paragraph","text":"A boat on Manchar can be a striking photograph, but it is not simply a decorative expression of lake culture. Water has supported work, movement and dwelling. When its quality and availability change, the consequences extend beyond scenery to the possibilities of remaining in a place."},{"type":"paragraph","text":"The Pakistan Council of Research in Water Resources describes Manchar as a lived lake with households occupying boat-based homes and livelihoods dependent on its waters. Its environmental assessment links reduced inflows and wastewater inputs with deteriorating conditions and declining fish catches. That account places the lake’s ecology and its social life in the same frame."},{"type":"heading","level":2,"text":"Home and livelihood are connected"},{"type":"paragraph","text":"An image of a boat-home may invite admiration for construction or adaptation. Those interests are legitimate, but they should not make hardship picturesque. A household’s choice to remain, move or change its work cannot be inferred from the appearance of a vessel. Nor should every person associated with the lake be represented as living in the same way."},{"type":"paragraph","text":"The World Bank’s fisheries assessment discusses Manchar through the effects of reduced freshwater inflows, pollution and declining fishing opportunities. It also considers the additional burdens associated with obtaining domestic water and the movement of fishing families in search of livelihoods. Its figures belong to the period of that report, not to an automatically updated census of the lake today."},{"type":"paragraph","text":"This historical distinction matters for an archive. A record of a household at one date cannot stand indefinitely for a community whose circumstances may have changed. Documentation should make room for movement and adaptation, rather than requiring people to preserve a familiar visual identity for visitors."},{"type":"heading","level":2,"text":"A waterscape extends upstream"},{"type":"paragraph","text":"PCRWR’s 2022 monitoring report discusses the Main Nara Valley Drain in relation to Manchar’s water-quality concerns. This directs attention beyond the immediate shoreline. The condition of a lake can depend on flows and decisions originating elsewhere, even when their consequences are experienced locally."},{"type":"paragraph","text":"For heritage interpretation, that means the boundary of the meaningful landscape is not necessarily the edge of the water in a photograph. Channels, drainage infrastructure and upstream uses may be part of the explanation. A cultural account that ignores them risks treating environmental change as an unexplained misfortune."},{"type":"heading","level":2,"text":"Recording without turning people into exhibits"},{"type":"paragraph","text":"A responsible photographic or oral-history project would identify when and where a record was made and ask participants how they wish their work and homes to be described. It would distinguish an individual account from a claim about everyone on the lake. It would also avoid presenting access to domestic spaces as a visitor entitlement."},{"type":"paragraph","text":"Manchar’s heritage is therefore not an image to preserve unchanged. It is a continuing relationship among water, knowledge, livelihood and home. Understanding that relationship requires attention to environmental evidence and to the people whose lives cannot be reduced to the beauty of a boat against a horizon."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Sindh","Cultural Landscapes"],"province":"Sindh","district":"Dadu","relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"landscape","seo":{"title":"Manchar as a lived waterscape","description":"Manchar’s boats and shoreline settlements belong to a changing relationship between water quality, livelihoods and home.","primaryKeyword":"Manchar lake cultural landscape","socialTitle":"Manchar as a lived waterscape","socialDescription":"Manchar’s boats and shoreline settlements belong to a changing relationship between water quality, livelihoods and home."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Environmental assessment of Manchar Lake","url":"https://www.pcrwr.gov.pk/water-quality/","publisher":"Pakistan Council of Research in Water Resources","accessDate":"2026-10-22"},{"title":"Revitalizing Pakistan’s Fisheries: Options for Sustainable Development","url":"https://documents1.worldbank.org/curated/en/122481529566117025/pdf/Revitalizing-Pakistan-s-Fisheries-Options-for-Sustainable-Development.pdf","publisher":"World Bank","accessDate":"2026-10-22"},{"title":"Monitoring of Persistent Organic Pollutants in Hydrosphere of Pakistan2022","url":"https://pcrwr.gov.pk/wp-content/uploads/2023/02/Monitoring-of-Persistent-Organic-Pollutants-in-Hydrosphere-of-Pakistan-2022.pdf","publisher":"Pakistan Council of Research in Water Resources","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"PCRWRMancharsectionandWorldBankBox8read;2022reportrelevantindexedparagraphread. Historicalcountsnotrecastas2026census. Noindividualtestimonyinvented,nostatementwatercurrentlysafer,medicaladviceorfieldvisitclaimed. Eachsourceunder150derivedwords.","editorialReason":"Require community and environmental sources and avoid treating a living livelihood as a vanished tradition.","sortOrder":392}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-sukkur-crossing-as-a-landscape-of-engineering','the-sukkur-crossing-as-a-landscape-of-engineering','review','{"id":"story-the-sukkur-crossing-as-a-landscape-of-engineering","type":"story","slug":"the-sukkur-crossing-as-a-landscape-of-engineering","title":"The Sukkur crossing as a landscape of engineering","summary":"Rail bridges, a barrage and an older urban landmark reveal different ways engineering and settlement have related to the Indus at Sukkur.","body":[{"type":"paragraph","text":"At Sukkur, the river is crossed, regulated and overlooked. These are different relationships, embodied in different structures. A railway bridge carries movement across water; a barrage regulates flows into a wider system; an urban landmark can orient a view without controlling the river at all. Reading them together makes an engineering landscape more than a collection of impressive silhouettes."},{"type":"paragraph","text":"The Lansdowne Bridge is a particularly strong starting point because its construction has a photographic record. Cambridge University Library’s digitised album documents work on the Sukkur crossing in the 1880s, culminating in the bridge’s completion in 1889. The sequence makes construction visible as a process rather than presenting the finished span as if it had simply appeared."},{"type":"heading","level":2,"text":"The photograph before the monument"},{"type":"paragraph","text":"A construction photograph can reveal temporary arrangements that disappear from later views. It also has limits: the camera’s position and the purpose of the album determine what is included. An image celebrating engineering may give less information about labour, supply chains or disruption than about the structure itself."},{"type":"paragraph","text":"For an archive, comparing dated stages is therefore more useful than using an old photograph merely to prove age. Which parts of the work were complete? What remained temporary? Which information comes from the caption and which is actually visible? Those distinctions help turn visual fascination into historical understanding."},{"type":"heading","level":2,"text":"Crossing and distributing water"},{"type":"paragraph","text":"Sukkur Barrage introduces another scale of infrastructure. The Sindh Irrigation Department records its operation from 1932 and identifies the canal network taking water from it. The structure’s significance consequently extends far beyond the immediate riverfront. It belongs to a managed landscape of channels and agricultural distribution, not simply a line across the Indus."},{"type":"paragraph","text":"The government’s rehabilitation assessment also records changes after commissioning. Excessive silt entering the right-bank canals prompted model investigations and subsequent alterations, including closure of some bays and river-training works. This history shows engineering as observation and adjustment, not a finished solution whose performance remained unchanged after inauguration."},{"type":"heading","level":2,"text":"The city is not only infrastructure"},{"type":"paragraph","text":"Mir Masum’s Minar and associated tombs belong to an older urban history. Their presence in the same landscape prevents the crossing from becoming the sole explanation of Sukkur. A place can acquire new infrastructural roles while retaining earlier forms of memory and orientation."},{"type":"paragraph","text":"The comparison should not imply that the minar, bridge and barrage formed one coordinated plan. Their dates, purposes and settings differ. What connects them for a present reader is the opportunity to examine successive ways of relating a city to a river."},{"type":"paragraph","text":"A careful landscape account thus moves between the span, the water system and the urban setting. It asks who and what could move, where water was directed, and how later changes altered earlier arrangements. Sukkur’s engineering heritage becomes most compelling when its structures are understood as parts of evolving systems rather than isolated feats frozen at the moment of completion."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Sindh","Cultural Landscapes"],"province":"Sindh","district":"Sukkur","relatedDistrictIds":["sindh-sukkur"],"provinceRegionIds":["sindh"],"relatedHeritageIds":["major-doam-5119","major-doam-5135"],"relatedStoryIds":[],"contentType":"landscape","seo":{"title":"The Sukkur crossing as a landscape of engineering","description":"Rail bridges, a barrage and an older urban landmark reveal different ways engineering and settlement have related to the Indus at Sukkur.","primaryKeyword":"Sukkur river engineering heritage","socialTitle":"The Sukkur crossing as a landscape of engineering","socialDescription":"Rail bridges, a barrage and an older urban landmark reveal different ways engineering and settlement have related to the Indus at Sukkur."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Digitisation of Sukkur Bridge photograph album","url":"https://specialcollections-blog.lib.cam.ac.uk/?p=16383","publisher":"Cambridge University Library","accessDate":"2026-10-22"},{"title":"Sukkur Barrage Left Bank Region","url":"https://irrigation.sindh.gov.pk/public/SukkurLeftBankRegion","publisher":"Sindh Irrigation Department","accessDate":"2026-10-22"},{"title":"Sukkur Barrage Rehabilitation and Modernization: environmental assessment","url":"https://documents.worldbank.org/curated/en/356891516200660593/pdf/SFG3992-EA-P162117-Box405323B-PUBLIC-Disclosed-1-17-2018.pdf","publisher":"Government of Sindh Irrigation Department","accessDate":"2026-10-22"},{"title":"Mir Masum’s Minar and Tomb","url":"https://doam.gov.pk/public/sites/5135","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Cambridgealbumalready342~85words; new~90withinsharedbudget. Officialbarragepageincorrectinauguratingpersonnotrepeated.1938modelstudyfromprojectassessmentindexedread; noengineeringcapacityadvice. MirMasumidentityonly,notbiographyalreadycoveredelsewhere.","editorialReason":"Link bridge, banks and urban visibility without duplicating the bridge’s technical profile.","sortOrder":393}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-swats-terraces-and-archaeological-visibility','swats-terraces-and-archaeological-visibility','review','{"id":"story-swats-terraces-and-archaeological-visibility","type":"story","slug":"swats-terraces-and-archaeological-visibility","title":"Swat’s terraces and archaeological visibility","summary":"Barikot’s slopes and terraces reveal why what archaeology can see depends on reuse, erosion and where excavation takes place.","body":[{"type":"paragraph","text":"A terrace in an archaeological landscape is not automatically a field, and a hilltop is not a single-period monument. At Barikot in Swat, slopes, platforms and successive buildings show how the visibility of the past depends on reuse as well as survival. The most conspicuous remains may occupy a surface created for an earlier purpose."},{"type":"paragraph","text":"Luca Maria Olivieri’s study of Barikot’s Shahi landscape describes a Hindu temple built on a monumental terrace previously associated with a Buddhist sacred area. The important point is not simply that one religious phase followed another. The material setting itself was reused and altered, creating relationships that only careful excavation can distinguish."},{"type":"heading","level":2,"text":"Height is not a date"},{"type":"paragraph","text":"It is tempting to read an elevated structure as the oldest or most important element of a site. Archaeology does not permit that shortcut. A high platform can be a later intervention, while earlier remains survive beneath or beside it. Equally, material found lower on a slope may have moved from above rather than marking an undisturbed occupation."},{"type":"paragraph","text":"Ca’ Foscari’s account of work at Barikot distinguishes excavation in the lower town from investigation of the acropolis. It describes complex stratigraphy on the steep slope and notes earlier material incorporated into later fills. That distinction helps explain why an artefact’s age is not necessarily the date of the deposit in which it is recovered."},{"type":"heading","level":2,"text":"Architecture connects levels"},{"type":"paragraph","text":"Elisa Iori’s research on Buddhist buildings at Barikot examines the relationship between lower open courts and raised, formerly roofed platforms. Steps connected spaces with different arrangements and uses. The elevation was therefore part of architectural organisation, not just a response to scenery."},{"type":"paragraph","text":"Such evidence encourages a more precise way of looking at a ruin. Rather than imagining an entire lost building from one wall, begin with the relationships that survive: a threshold, a stair, a court and the level to which it leads. These can support interpretations of movement even when roofs and upper walls are gone."},{"type":"heading","level":2,"text":"Excavation shapes what becomes visible"},{"type":"paragraph","text":"An archaeological plan is also a record of where work has taken place. Unexcavated ground should not be interpreted as empty ancient space, while an exposed area may bring together remains from several phases for study. The viewer needs a phased explanation to understand which features actually belonged together."},{"type":"paragraph","text":"This is especially important in a landscape as visually powerful as Swat. The green valley and prominent hills can make the setting seem immediately comprehensible, while the chronology remains complex. A scenic panorama is a useful introduction, not a substitute for the excavation record."},{"type":"paragraph","text":"Barikot’s terraces consequently offer more than attractive vantage points. They show how people built upon earlier surfaces and how researchers separate those interventions. Reading the site through levels, connections and documented phases makes its visible remains richer without pretending that the whole past is already exposed to view."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Archaeology","Khyber Pakhtunkhwa","Cultural Landscapes"],"province":"Khyber Pakhtunkhwa","district":"Swat","relatedDistrictIds":["khyber-pakhtunkhwa-swat"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-doam-3304","major-bazira"],"relatedStoryIds":[],"contentType":"landscape","seo":{"title":"Swat’s terraces and archaeological visibility","description":"Barikot’s slopes and terraces reveal why what archaeology can see depends on reuse, erosion and where excavation takes place.","primaryKeyword":"Swat archaeological landscape","socialTitle":"Swat’s terraces and archaeological visibility","socialDescription":"Barikot’s slopes and terraces reveal why what archaeology can see depends on reuse, erosion and where excavation takes place."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Temples of Swat: The Shahi archaeological landscape of Barikot","url":"https://iris.unive.it/handle/10278/5011041","publisher":"Luca Maria Olivieri / Ca’ Foscari University","accessDate":"2026-10-22"},{"title":"Excavations: archaeology at Ca’ Foscari","url":"https://www.unive.it/pag/44639/","publisher":"Ca’ Foscari University","accessDate":"2026-10-22"},{"title":"An Urban Approach to the Archaeology of Buddhism in Gandhara: The Case of Barikot","url":"https://www.tandfonline.com/doi/full/10.1080/02666030.2023.2231671","publisher":"Elisa Iori, South Asian Studies","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Universityextendedabstractandprojectdescriptionread;Ioriindexedbuilt-environmentpassageread. Eachsourceapprox100–140derivedwords. NoallSwatterracesagriculturalclaim; lowercity/acropolissequenceskeptdistinct; nofieldvisit.","editorialReason":"Explain why settlement and monuments occupy different landforms and how survey finds them.","sortOrder":394}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-peshawar-valley-as-a-network-of-places','the-peshawar-valley-as-a-network-of-places','review','{"id":"story-the-peshawar-valley-as-a-network-of-places","type":"story","slug":"the-peshawar-valley-as-a-network-of-places","title":"The Peshawar valley as a network of places","summary":"Monastery, town and river-junction settlement offer different perspectives on the Peshawar valley’s interconnected archaeological landscape.","body":[{"type":"paragraph","text":"The Peshawar valley becomes more intelligible when its heritage is read as different kinds of places rather than a sequence of interchangeable Buddhist ruins. A monastery, a fortified town and a settlement near a river junction had distinct settings and functions. Their relationships are the subject of investigation, not something a line on a tourist map can establish by itself."},{"type":"paragraph","text":"The World Heritage property of Takht-i-Bahi and Sahr-i-Bahlol offers a useful starting point because it deliberately brings two components together. The monastic remains occupy hills; the neighbouring town remains lie in the plain. Their shared recognition does not erase the difference between a religious complex and an urban settlement."},{"type":"heading","level":2,"text":"Complementary places, different evidence"},{"type":"paragraph","text":"UNESCO’s account describes Takht-i-Bahi through its courts, stupas, monastic spaces and passages, while Sahr-i-Bahlol is represented by the remains of a fortified town. It also notes the contrast in their present survival: urban occupation has affected the town’s archaeological remains, whereas the hilltop complex retains a more immediately legible arrangement."},{"type":"paragraph","text":"This contrast matters for public understanding. A site that looks more complete is not necessarily the only one with a substantial history. Visibility depends on later occupation, conservation and the kinds of structures originally built. The less photogenic component may be essential to understanding the wider landscape."},{"type":"heading","level":2,"text":"A settlement at a junction"},{"type":"paragraph","text":"The Cambridge and Peshawar universities’ research project at Bala Hisar, Charsadda, places the mound near the meeting of the Swat and Kabul rivers and within wider communication routes. Here the geographical question differs from that of a hilltop monastery: how did a settlement relate to converging waterways and movement through adjoining regions?"},{"type":"paragraph","text":"This is the Bala Hisar at Charsadda, not the similarly named fort in Peshawar city. Keeping the locations distinct is essential when linking records, photographs or historical references. Familiar names can otherwise produce convincing but false connections."},{"type":"paragraph","text":"Durham University’s exhibition records collaborative fieldwork at Charsadda in the 1990s, while the Cambridge project describes a later research collaboration. The sequence is a reminder that understanding a site develops through successive investigations. An old excavation does not close every question about its history."},{"type":"heading","level":2,"text":"What makes a network visible?"},{"type":"paragraph","text":"Shared architectural features can suggest comparison, but demonstrating a network requires more: chronology, material distributions, inscriptions or evidence of movement. Two sites need not have been occupied at the same time simply because both appear under a broad label such as Gandhara."},{"type":"paragraph","text":"For discovery, the practical benefit is to ask a different question at each place. How were spaces organised at the monastery? What survives of the town? What made the river-junction location significant? Following those questions preserves the character of each site while allowing the valley to emerge as a connected landscape—one composed of varied communities and changing relationships rather than a single repeated monument type."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Gandhara","Khyber Pakhtunkhwa","Cultural Landscapes"],"province":"Khyber Pakhtunkhwa","district":null,"relatedDistrictIds":["khyber-pakhtunkhwa-mardan","khyber-pakhtunkhwa-charsadda"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["unesco-140","major-doam-2160"],"relatedStoryIds":[],"contentType":"landscape","seo":{"title":"The Peshawar valley as a network of places","description":"Monastery, town and river-junction settlement offer different perspectives on the Peshawar valley’s interconnected archaeological landscape.","primaryKeyword":"Peshawar valley heritage landscape","socialTitle":"The Peshawar valley as a network of places","socialDescription":"Monastery, town and river-junction settlement offer different perspectives on the Peshawar valley’s interconnected archaeological landscape."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Buddhist Ruins of Takht-i-Bahi and Neighbouring City Remains at Sahr-i-Bahlol","url":"https://whc.unesco.org/en/list/140/","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Investigating ancient Pushkalavati: introduction","url":"https://www.arch.cam.ac.uk/research/projects/archived-projects/investigating-ancient-pushkalavati/introduction","publisher":"University of Cambridge / University of Peshawar","accessDate":"2026-10-22"},{"title":"Bala Hisar of Charsadda exhibition","url":"https://dur.ac.uk/research/institutes-and-centres/ethics-cultural-heritage/unescochair/exhibitions/","publisher":"Durham University","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"UNESCOOUVandCambridgeprojectintroductionread,Durhamexhibitionmetadataonly. UNESCO~140words;Cambridge~90. Do not confuseCharsaddaBalaHisarwithPeshawarfort; noallGandharahomogeneousreligionorpreciserouteasserted.","editorialReason":"Move beyond a city-centred narrative while respecting distinct modern districts.","sortOrder":395}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-chitrals-seasonal-knowledge-and-local-horizons','chitrals-seasonal-knowledge-and-local-horizons','review','{"id":"story-chitrals-seasonal-knowledge-and-local-horizons","type":"story","slug":"chitrals-seasonal-knowledge-and-local-horizons","title":"Chitral’s seasonal knowledge and local horizons","summary":"Suri Jagek shows how seasonal knowledge can depend on particular horizons, social learning and the decisions a community makes about transmission.","body":[{"type":"paragraph","text":"A mountain horizon can be more than a view. For a knowledge system based on observing celestial positions in relation to local terrain, the shape of that horizon is part of the reference. Suri Jagek, the Kalasha practice described in UNESCO’s safeguarding record, makes this connection between observation and place particularly clear."},{"type":"paragraph","text":"The practice should not be presented as the calendar of everyone in Chitral. It belongs to a particular community and set of traditions within a linguistically and culturally varied region. That specificity is essential to understanding it, not a detail to be removed for a simpler regional story."},{"type":"heading","level":2,"text":"Observation belongs to a setting"},{"type":"paragraph","text":"UNESCO describes Suri Jagek through observations of the sun, moon, stars and shadows in relation to local topography. These observations inform seasonal activities and the timing of important social and religious occasions. Knowledge of the surrounding land is therefore integral to the practice, rather than scenery added around an abstract astronomical system."},{"type":"paragraph","text":"The description also identifies oral forms—including stories, songs and proverbs—as means of transmission. Learning is not represented solely as memorising a table of dates. It involves ways of explaining and recalling relationships within a community."},{"type":"heading","level":2,"text":"A calendar is also social"},{"type":"paragraph","text":"This connection suggests why documenting only a calculation would be incomplete. Who learns, how observations are discussed and how occasions are coordinated are part of the cultural significance. Those details require accounts from knowledgeable practitioners; they cannot be reconstructed from a landscape photograph or a short institutional summary."},{"type":"paragraph","text":"Nor should a public article turn the practice into an exotic forecasting trick. An explanation of cultural knowledge is different from an instruction for predicting weather or planning a journey. The purpose here is to understand a relationship with the environment, not to replace current weather information with an untested interpretation."},{"type":"heading","level":2,"text":"Safeguarding is an ongoing process"},{"type":"paragraph","text":"Suri Jagek was inscribed on UNESCO’s Urgent Safeguarding List in 2018. UNESCO’s reporting record also identifies a subsequent state report submitted in 2023 and examined in 2024. These dates distinguish recognition from later monitoring; inscription is not proof that transmission is secure or that every proposed safeguarding activity has been completed."},{"type":"paragraph","text":"The underlying description discusses pressure on transmission while noting adaptation. That combination matters. A living practice need not remain unchanged to be meaningful, but changes should be described through the people involved rather than judged against an imagined frozen past."},{"type":"heading","level":2,"text":"The horizon as part of heritage"},{"type":"paragraph","text":"For an archive, a useful record would connect a place and a dated explanation with appropriate permission, while respecting any limits practitioners place on sharing knowledge. It would avoid offering a generic mountain image as if it documented a specific observation point."},{"type":"paragraph","text":"Chitral’s seasonal knowledge becomes most compelling at this human scale: a particular horizon, a learned way of attending to it and a community deciding how that knowledge continues. The landscape matters because it is understood, not merely because it is beautiful."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Khyber Pakhtunkhwa","Cultural Landscapes"],"province":"Khyber Pakhtunkhwa","district":"Lower Chitral","relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"landscape","seo":{"title":"Chitral’s seasonal knowledge and local horizons","description":"Suri Jagek shows how seasonal knowledge can depend on particular horizons, social learning and the decisions a community makes about transmission.","primaryKeyword":"Chitral seasonal landscape knowledge","socialTitle":"Chitral’s seasonal knowledge and local horizons","socialDescription":"Suri Jagek shows how seasonal knowledge can depend on particular horizons, social learning and the decisions a community makes about transmission."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Suri Jagek, nomination file01381","url":"https://ich.unesco.org/en/USL/suri-jagek-observing-the-sun-traditional-meteorological-and-astronomical-practice-based-on-the-observation-of-the-sun-moon-and-stars-in-reference-to-the-local-topography-01381","publisher":"UNESCO Intangible Cultural Heritage","accessDate":"2026-10-22"},{"title":"Pakistan periodic reporting: Suri Jagek","url":"https://ich.unesco.org/en/state/pakistan-PK?info=periodic-reporting","publisher":"UNESCO Intangible Cultural Heritage","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"UNESCOelementdescriptionindexedread; reportingmetadataread,notfull2023reportorvideo. Approximately180words deriveelementdescription,40reportmetadata; restoriginalinterpretiveframework. Noformula/calendarpredictionorpracticalweatheradvice. ExplicitlyKalashanotallChitral.","editorialReason":"Explore the role of terrain in a documented knowledge system, distinct from a general festival article.","sortOrder":396}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-khyber-passage-and-the-problem-of-the-timeless-gateway','the-khyber-passage-and-the-problem-of-the-timeless-gateway','review','{"id":"story-the-khyber-passage-and-the-problem-of-the-timeless-gateway","type":"story","slug":"the-khyber-passage-and-the-problem-of-the-timeless-gateway","title":"The Khyber passage and the problem of the timeless gateway","summary":"The Khyber’s archaeology and railway history challenge the idea of a passage that has worked in the same way throughout time.","body":[{"type":"paragraph","text":"Calling the Khyber a timeless gateway gives a strong first impression and a weak historical explanation. A mountain passage can remain geographically recognisable while its routes, technologies and political conditions change profoundly. The people who live around it are not merely spectators to movement by others."},{"type":"paragraph","text":"The contrast between an archaeological monument and a twentieth-century railway makes those changes visible. Both belong to the Khyber landscape, but they cannot be treated as evidence for one continuous, unaltered corridor."},{"type":"heading","level":2,"text":"A sacred structure within the passage"},{"type":"paragraph","text":"The federal catalogue records Saphola Stupa at Zarai, between Ali Masjid and Landi Kotal. Its description places the stone remains on a rocky edge and identifies a tiered base beneath the ruined upper structure. This is evidence of a particular monument and its setting, not a complete account of everyone who travelled through the pass."},{"type":"paragraph","text":"A stupa should not become a convenient label for an entire route. Its construction, use and relationship to nearby settlement require their own evidence. The fact that a later road passes within the same landscape does not establish that it follows the exact path of earlier movement."},{"type":"heading","level":2,"text":"A railway required decisions"},{"type":"paragraph","text":"The contemporary Railway Gazette account of the Khyber Railway’s opening records the long history of planning and the decision to proceed with a broad-gauge extension through the pass in the twentieth century. A railway was not simply a modern surface laid over an inevitable ancient line. It required a particular alignment and substantial works suited to its technology."},{"type":"paragraph","text":"Abhilash Medhi’s research asks how construction also changed relationships of authority. His study’s abstract emphasises negotiations between the colonial government and populations around the Khyber, and the ways infrastructure became entangled with local hierarchies. This shifts attention from engineering alone to the conditions under which a route could be built and operated."},{"type":"heading","level":2,"text":"Passage is not the same as openness"},{"type":"paragraph","text":"The gateway metaphor can imply that movement was always easy or available to everyone. Historical routes instead raise questions about permission, cost, control and purpose. A railway intended for strategic movement, a road used for commerce and a path connecting local places need not serve the same people in the same way."},{"type":"paragraph","text":"Those distinctions also matter when reading photographs. A dramatic tunnel or a line climbing a hillside records infrastructure; it does not explain all the negotiations, labour and restrictions that made it possible. Captions should identify the date and system rather than imply an eternal view of frontier life."},{"type":"paragraph","text":"The Khyber is more interesting when its continuity is treated as a question. What remained geographically useful, and what changed in the organisation of movement? Keeping archaeology, local occupation and railway history distinct allows connections to emerge without reducing the passage to a stage on which history repeatedly performed the same scene."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Khyber Pakhtunkhwa","Cultural Landscapes"],"province":"Khyber Pakhtunkhwa","district":"Khyber","relatedDistrictIds":["khyber-pakhtunkhwa-khyber"],"provinceRegionIds":["khyber-pakhtunkhwa"],"relatedHeritageIds":["major-doam-3447"],"relatedStoryIds":[],"contentType":"landscape","seo":{"title":"The Khyber passage and the problem of the timeless gateway","description":"The Khyber’s archaeology and railway history challenge the idea of a passage that has worked in the same way throughout time.","primaryKeyword":"Khyber Pass heritage interpretation","socialTitle":"The Khyber passage and the problem of the timeless gateway","socialDescription":"The Khyber’s archaeology and railway history challenge the idea of a passage that has worked in the same way throughout time."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Infrastructural Contingencies and Contingent Sovereignties on the Indo–Afghan Frontier","url":"https://www.cambridge.org/core/journals/modern-asian-studies/article/abs/infrastructural-contingencies-and-contingent-sovereignties-on-the-indoafghan-frontier/79933E0210E5CF2D440FA682ED970F55","publisher":"Abhilash Medhi, Modern Asian Studies","accessDate":"2026-10-22"},{"title":"Opening of the Khyber Railway,1925","url":"https://irfca.org/docs/history/railway-gazette-khyber-railway-1925.html","publisher":"Railway Gazette, reproduced by IRFCA","accessDate":"2026-10-22"},{"title":"Saphola Stupa","url":"https://doam.gov.pk/public/sites/3447","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Medhiabstractread,notpaywalledarticle; RailwayGazetteindexedopeningpassageread,full403. DOAMinventoryread. Nooperatorschedule/currentaccessclaim. Derivedwordsroughly100Medhi,65Gazette,70DOAM.","editorialReason":"Investigate dated route evidence rather than reuse an unchanging gateway metaphor.","sortOrder":397}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-kachi-plain-the-landscape-around-early-villages','kachi-plain-the-landscape-around-early-villages','review','{"id":"story-kachi-plain-the-landscape-around-early-villages","type":"story","slug":"kachi-plain-the-landscape-around-early-villages","title":"Kachi plain: the landscape around early villages","summary":"Mehrgarh and Nausharo place early settlement in the Kachi landscape, while new dating evidence requires care with familiar foundation claims.","body":[{"type":"paragraph","text":"The Kachi plain is important to the study of early villages because it contains evidence of settlement, cultivation and changing material practices over long periods. Yet its significance should not depend on repeating the oldest possible date. Mehrgarh remains a major archaeological reference point even when new research revises the chronology used to interpret it."},{"type":"paragraph","text":"Reading the landscape around early villages means asking how occupation related to terrain and resources, while keeping separate the dates of particular deposits, structures and burial grounds. A large site name can encompass evidence that was not created all at once."},{"type":"heading","level":2,"text":"What the new dates actually measure"},{"type":"paragraph","text":"A 2025 study by Benjamin Mutin and colleagues analysed human tooth enamel from twenty-three Neolithic burials at Mehrgarh. Its modelling places the beginning of the sampled aceramic cemetery around 5200–4900 BCE and estimates a duration of several centuries. These results challenge substantially earlier chronologies commonly repeated for the site."},{"type":"paragraph","text":"The distinction between measurement and interpretation is important. The dated evidence comes from burials. The authors use it within a broader argument about settlement and the emergence of farming, but the cemetery’s modelled start should not be presented without explanation as a direct measurement of every occupation deposit across Mehrgarh."},{"type":"paragraph","text":"This does not diminish the research. It clarifies why the study matters: better chronological evidence changes the relationships that can be proposed among communities and material traditions. Archaeology gains explanatory power through revision, not through preserving a familiar superlative."},{"type":"heading","level":2,"text":"A plain with more than one settlement"},{"type":"paragraph","text":"Nausharo provides another archaeological anchor in the Kachi landscape. The federal catalogue records settlement remains and material including ceramics, figurines and seals. These categories support questions about occupation and connections, but they do not make Nausharo a simple continuation of every earlier practice at Mehrgarh."},{"type":"paragraph","text":"The sites must be compared through documented sequences. Similar forms can be meaningful only when their contexts and dates are understood. A regional map helps locate the comparison; it cannot supply the chronological links by itself."},{"type":"heading","level":2,"text":"From village image to archaeological evidence"},{"type":"paragraph","text":"The phrase early village can evoke a complete scene of houses, fields and daily routines. Excavation usually provides a more uneven record. Walls, storage features, botanical remains, animal remains and burials each answer different questions. Their survival and recovery determine how much can be reconstructed."},{"type":"paragraph","text":"A landscape interpretation should therefore avoid treating the modern appearance of the plain as a transparent view of prehistoric conditions. Water availability, sedimentation and land use require their own investigation. Nor should farming be represented as a single invention that instantly transformed every nearby community in the same way."},{"type":"paragraph","text":"Kachi’s importance lies in the possibility of asking these questions together. Mehrgarh’s revised dating and Nausharo’s distinct evidence encourage a regional history grounded in particular observations. The result is more informative than a race for antiquity: a landscape in which the history of early settlement remains both substantial and open to better explanation."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Balochistan","Cultural Landscapes"],"province":"Balochistan","district":"Kachhi","relatedDistrictIds":["balochistan-kachhi"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["curated-mehrgarh","major-doam-8927"],"relatedStoryIds":[],"contentType":"landscape","seo":{"title":"Kachi plain: the landscape around early villages","description":"Mehrgarh and Nausharo place early settlement in the Kachi landscape, while new dating evidence requires care with familiar foundation claims.","primaryKeyword":"Kachi plain early settlement","socialTitle":"Kachi plain: the landscape around early villages","socialDescription":"Mehrgarh and Nausharo place early settlement in the Kachi landscape, while new dating evidence requires care with familiar foundation claims."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"New radiocarbon dates of human tooth enamel reveal a late appearance of farming life in the Indus Valley","url":"https://www.nature.com/articles/s41598-025-92621-5","publisher":"Benjamin Mutin and colleagues, Scientific Reports2025","accessDate":"2026-10-22"},{"title":"Archaeological Site of Mehrgarh","url":"https://whc.unesco.org/en/tentativelists/1876/","publisher":"UNESCO World Heritage Centre / Pakistan nomination","accessDate":"2026-10-22"},{"title":"Nausharo","url":"https://doam.gov.pk/public/sites/8927","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"2025paperabstract,results,discussionindexedread; claimcarefullylimitedcemeterymodelnotunqualifiedwholesitefoundation. OlderUNESCOchronologycontextnotadopted. Nausharocatalogueperiodmixnotrepeated; identity/materialtypesonly. Paperderivedportionapprox180words.","editorialReason":"Connect resources and settlement evidence without reducing complex change to climate alone.","sortOrder":398}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-makrans-inland-routes-and-coastal-horizons','makrans-inland-routes-and-coastal-horizons','review','{"id":"story-makrans-inland-routes-and-coastal-horizons","type":"story","slug":"makrans-inland-routes-and-coastal-horizons","title":"Makran’s inland routes and coastal horizons","summary":"Makran’s settlement evidence connects inland valleys and coastal possibilities without proving a single continuous maritime route.","body":[{"type":"paragraph","text":"Makran is often imagined as a coastline with an inland margin. Archaeology suggests a more productive starting point: valleys, settlements and possible maritime connections that need to be investigated together. An inland site need not be isolated from exchange, and a site near the coast is not automatically a harbour."},{"type":"paragraph","text":"Shahi Tump in the Kech landscape and Sutkagen-Dor farther west provide different points of reference. They should not be presented as two interchangeable stops on a single ancient shipping route. Their material evidence, dates and settings require separate attention before a connection can be proposed."},{"type":"heading","level":2,"text":"A research question shaped an expedition"},{"type":"paragraph","text":"Writing for Penn Museum in 1968, George Dales explained that his early Makran investigations were motivated by questions about contacts between South Asia and the Near East. Accounts of seafaring and evidence from Mesopotamia helped frame the search. This is valuable testimony about how archaeological research began, but an expedition’s objective is not the same thing as its final proof."},{"type":"paragraph","text":"His article on Harappan outposts likewise treats the identification of Sutkagen-Dor as part of an argument about possible western contacts. The careful word is possible. A settlement’s participation in a wider material world does not by itself reveal the exact route by which every object or idea travelled."},{"type":"heading","level":2,"text":"The archive behind the route line"},{"type":"paragraph","text":"Penn Museum’s finding aid for the Dales papers lists field notes, maps, plans, artefact lists and pottery drawings from the Makran work. It includes separate records associated with Sutkagen-Dor and Sotka Koh. That range of material shows why a drawn route is only a synthesis: its strength depends on underlying observations that can be checked and compared."},{"type":"paragraph","text":"The finding aid is not a substitute for inspecting those records. It establishes where research evidence survives and what kinds of documentation may be available. Detailed claims about a particular trench or object still require the relevant report or archive item."},{"type":"heading","level":2,"text":"Inland resources and coastal horizons"},{"type":"paragraph","text":"For an atlas reader, the useful distinction is between a demonstrated connection and a plausible corridor. Material similarities can suggest interaction; the location of valleys and coastlines can suggest ways movement might have occurred. Neither alone determines whether exchange was direct, passed through intermediaries or changed across periods."},{"type":"paragraph","text":"The same caution applies to modern distances from the sea. Reconstructing an earlier shoreline requires geological evidence rather than an assumption that the coast has remained fixed or moved uniformly. A present map supplies the starting geography, not the completed ancient landscape."},{"type":"paragraph","text":"Makran’s interest consequently extends beyond the search for ports. Inland settlements deserve attention as places of occupation and production, while coastal evidence opens questions about wider horizons. Keeping both in view allows the region to be understood as more than a transit strip between distant centres, without replacing genuine uncertainty with a confidently drawn but unproven ancient route."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Archaeology","Balochistan","Cultural Landscapes"],"province":"Balochistan","district":null,"relatedDistrictIds":["balochistan-kech","balochistan-gwadar"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["major-doam-10398","major-doam-8639"],"relatedStoryIds":[],"contentType":"landscape","seo":{"title":"Makran’s inland routes and coastal horizons","description":"Makran’s settlement evidence connects inland valleys and coastal possibilities without proving a single continuous maritime route.","primaryKeyword":"Makran routes cultural landscape","socialTitle":"Makran’s inland routes and coastal horizons","socialDescription":"Makran’s settlement evidence connects inland valleys and coastal possibilities without proving a single continuous maritime route."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"The South Asia Section","url":"https://www.penn.museum/sites/expedition/the-south-asia-section/","publisher":"George F. Dales, Penn Museum,1968","accessDate":"2026-10-22"},{"title":"George F. Dales Papers: Makran Coast records","url":"https://findingaids.library.upenn.edu/records/UPENN_MUSEUM_PU-MU.1066","publisher":"Penn Museum Archives","accessDate":"2026-10-22"},{"title":"Harappan Outposts on the Makran Coast","url":"https://www.cambridge.org/core/journals/antiquity/article/abs/harappan-outposts-on-the-makran-coast/069AC7E4AC889080FD3BBB98A859552A","publisher":"George F. Dales, Antiquity","accessDate":"2026-10-22"},{"title":"Shahi Tump","url":"https://doam.gov.pk/public/sites/10398","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"Sutkagen-Dor","url":"https://doam.gov.pk/public/sites/8639","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Dales1968firstpersonaccountandPennfindingaidread;Antiquityextractonly. Archivecontentsnotpersonallyinspected. DOAMsiteidentityonlyalready352. AvoidrepeatingArScAnpagebudget. NoassertionSutkagenDorportlocationorcontinuousrouteproved.","editorialReason":"Test connections through material evidence rather than draw speculative caravan paths.","sortOrder":399}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-khojak-a-pass-transformed-by-a-tunnel','khojak-a-pass-transformed-by-a-tunnel','review','{"id":"story-khojak-a-pass-transformed-by-a-tunnel","type":"story","slug":"khojak-a-pass-transformed-by-a-tunnel","title":"Khojak: a pass transformed by a tunnel","summary":"Khojak’s tunnel changed how a mountain barrier was crossed, while archival photographs preserve a different view of the engineering project.","body":[{"type":"paragraph","text":"A pass and a tunnel solve the problem of crossing a mountain in different ways. At Khojak, the railway did not simply improve a path over the ridge; it established a new relationship between the line’s approaches, the rock through which it passed and the settlements connected by it. The tunnel is best understood as part of that system rather than as a length record."},{"type":"paragraph","text":"The federal catalogue places it on the Quetta–Chaman railway between Shelabagh and Sanzala and records completion in 1891. At roughly 3.9 kilometres, it is a substantial engineering work, but its historical significance is not dependent on whether it occupies a particular place in a changing list of longest tunnels."},{"type":"heading","level":2,"text":"Crossing beneath the barrier"},{"type":"paragraph","text":"The distinction between a road over a pass and a railway through a tunnel concerns more than distance. A railway requires an alignment suited to its operating conditions, together with approaches and supporting infrastructure. The tunnel entrance is therefore only the most visible part of a larger decision about movement through the landscape."},{"type":"paragraph","text":"The historical account reproduced by the Indian Railways Fan Club Association discusses the project in relation to the Chaman extension. Read alongside the catalogue, it places the tunnel within a particular late nineteenth-century railway undertaking. It should not be used to imply that the line crossed into Afghanistan or that every earlier proposal was completed."},{"type":"heading","level":2,"text":"An entrance in the photographic record"},{"type":"paragraph","text":"The British Library holds a photograph catalogued as the entrance to the Khojak tunnel, attributed to Frederick Bremner and dated to the 1890s. Its collection context is also recorded: it survives within the Jones collection rather than as an anonymous illustration detached from provenance."},{"type":"paragraph","text":"A separate reproduced Bremner image is identified as construction work on the Shelabagh side in 1889. Together, the records indicate that the project was photographed during and after construction. Their catalogue dates and descriptions are evidence, although close visual comparison requires examination of the images themselves."},{"type":"heading","level":2,"text":"What the engineering view leaves open"},{"type":"paragraph","text":"Such photographs can help document changing fabric, but they cannot provide a complete social history. The organisation of labour, working conditions and supply arrangements require records beyond an entrance view. Dramatic stories attached to the tunnel should likewise be checked against contemporary evidence before being repeated as fact."},{"type":"paragraph","text":"The same distinction applies to present-day discovery. Historical railway significance is not a statement about current train services, permission to enter railway property or safe access to a tunnel. Those are separate, time-sensitive questions."},{"type":"paragraph","text":"Khojak rewards attention to the relationship between visible and hidden infrastructure. The portal gives the railway an architectural face, while the passage through the mountain and its approaches explain the transformation. Reading the tunnel through dated records and its wider alignment makes it a specific historical project, not merely a picturesque opening in a hillside."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Balochistan","Cultural Landscapes"],"province":"Balochistan","district":"Killa Abdullah","relatedDistrictIds":["balochistan-chaman"],"provinceRegionIds":["balochistan"],"relatedHeritageIds":["major-doam-10388"],"relatedStoryIds":[],"contentType":"landscape","seo":{"title":"Khojak: a pass transformed by a tunnel","description":"Khojak’s tunnel changed how a mountain barrier was crossed, while archival photographs preserve a different view of the engineering project.","primaryKeyword":"Khojak railway landscape","socialTitle":"Khojak: a pass transformed by a tunnel","socialDescription":"Khojak’s tunnel changed how a mountain barrier was crossed, while archival photographs preserve a different view of the engineering project."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Khojak Tunnel","url":"https://doam.gov.pk/public/sites/10388","publisher":"Department of Archaeology and Museums","accessDate":"2026-10-22"},{"title":"The entrance to the Khojak tunnel, Photo578/4(88)","url":"https://searcharchives.bl.uk/catalog/041-003114962","publisher":"British Library","accessDate":"2026-10-22"},{"title":"Khojak tunnel construction,1889","url":"https://irfca.org/gallery/Heritage/Khojak/khojak_tunnel_boring_1889.jpg.html","publisher":"Frederick Bremner photograph, reproduced by IRFCA","accessDate":"2026-10-22"},{"title":"Khojak Tunnel historical account","url":"https://irfca.org/articles/khojak-tunnel.html","publisher":"Indian Railways Fan Club Association","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"BLcataloguemetadataprimaryread;photographnotvisuallyinspected. DOAMmiscellaneoussourceweak,detailslimitedroute1891completion~3.9kmcorroboratedIRFCA. Noengineering-suicidelegend,deathcounts,oldlongestrankingorcurrenttrainoperationasserted. Primaryevidencelimitrequireseditorreview.","editorialReason":"Study infrastructure’s spatial consequences separately from the tunnel’s construction history.","sortOrder":400}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-baltistans-irrigation-channels-as-cultural-infrastructure','baltistans-irrigation-channels-as-cultural-infrastructure','review','{"id":"story-baltistans-irrigation-channels-as-cultural-infrastructure","type":"story","slug":"baltistans-irrigation-channels-as-cultural-infrastructure","title":"Baltistan’s irrigation channels as cultural infrastructure","summary":"Baltistan’s irrigation channels are cultural infrastructure: physical works sustained through water-sharing arrangements, maintenance and changing relationships with outside agencies.","body":[{"type":"paragraph","text":"In a mountain landscape, a line of water can explain a settlement more clearly than a monumental façade. A channel connects a source to cultivated ground, but its continued operation also depends on decisions about maintenance and use. Baltistan’s irrigation systems deserve attention as cultural infrastructure: they join physical construction to the organisation of everyday life."},{"type":"heading","level":2,"text":"Following water also means following responsibilities"},{"type":"paragraph","text":"Joe Hill’s 2014 research examines farmer-managed irrigation in Thurgu, Baltistan, alongside a separate case in Kargil. It describes systems that use gravity to carry river, spring or meltwater toward fields. Some include storage that holds water overnight for later use. These arrangements respond to particular sources and terrain; they are not one uniform design across the mountains."},{"type":"paragraph","text":"The paper treats users’ work as more than clearing a channel. Maintenance, distribution, resource management and relationships with outside agencies all form part of the system. Water infrastructure is therefore both a material network and a set of practical responsibilities."},{"type":"paragraph","text":"This perspective changes what a landscape photograph can show. A visible channel may indicate where water travels, but not who repairs it, how turns are arranged or what happens during a shortage. Those questions require local evidence. The presence of a wall or sluice does not reveal the rules attached to it."},{"type":"heading","level":2,"text":"Continuity without freezing the past"},{"type":"paragraph","text":"Hill compares early twentieth-century revenue records with later practices. The comparison identifies change as well as continuity. External improvement projects can affect institutions indirectly even when they appear to concern physical works alone. A new structure does not enter an empty social landscape."},{"type":"paragraph","text":"A Rural Support Programmes Network collection of mountain adaptation practices offers another way into the subject. Its irrigation examples connect open channels with local management and recurring upkeep. The collection describes particular practices, not a prescription that every village must follow the same arrangements."},{"type":"paragraph","text":"Calling these systems heritage should not imply that users ought to preserve every old material or procedure unchanged. Their purpose includes sustaining cultivation. People may seek safer, more reliable or less demanding infrastructure, and those choices belong within the history rather than outside it."},{"type":"heading","level":2,"text":"Reading a working landscape carefully"},{"type":"paragraph","text":"For a future field account, a useful starting point would be a jointly explained section of channel: where the water comes from, which land it serves and who is responsible for that stretch. Different users might describe the same system differently. Those differences should be recorded rather than smoothed into a single story of timeless communal harmony."},{"type":"paragraph","text":"An archive should also resist assigning an ancient date simply because a channel looks old. Recutting, repair and replacement can make an operating system difficult to date from appearance. Documents and local accounts may illuminate parts of its history without establishing its origin."},{"type":"paragraph","text":"Baltistan’s irrigated landscapes show that heritage can reside in recurring work as well as surviving fabric. The significant relationship is between water, terrain and people who keep a system functioning. Recognising that relationship makes the cultivated ground intelligible without turning it into a picturesque backdrop."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Cultural Landscapes","Gilgit-Baltistan"],"province":"Gilgit-Baltistan","district":null,"relatedDistrictIds":[],"provinceRegionIds":["gilgit-baltistan"],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"landscape","seo":{"title":"Baltistan’s irrigation channels as cultural infrastructure","description":"Baltistan’s irrigation channels are cultural infrastructure: physical works sustained through water-sharing arrangements, maintenance and changing relationships with outside agencies.","primaryKeyword":"Baltistan irrigation heritage","socialTitle":"Baltistan’s irrigation channels as cultural infrastructure","socialDescription":"Baltistan’s irrigation channels are cultural infrastructure: physical works sustained through water-sharing arrangements, maintenance and changing relationships with outside agencies."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Farmer-managed irrigation systems in Baltistan and Kargil","url":"https://ladakhstudies.org/wp-content/uploads/2018/03/ls31.pdf","publisher":"Joe Hill / Ladakh Studies","accessDate":"2026-10-22","section":"2014, pages 4–23"},{"title":"Local Indigenous Adaptation Practices in Mountain Areas of Pakistan","url":"https://www.rspn.org/wp-content/uploads/2020/01/Case-Studies-on-Local-Indigenous-Practices.pdf","publisher":"Rural Support Programmes Network","accessDate":"2026-10-22","section":"Irrigation practices chapter"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. Remove plan link8244 Zaipur Shikari and districtAstore: official site is not Baltistan. No substitute Place or guessed district introduced. Hill spells village Thurgu; paper abstract and selected system passages close-read, approximately170 derived words. RSPN selected chapter approximately90. No engineering advice, universal custom, antiquity date or claim of every channel sacred. Comparative Kargil case kept explicitly outside Baltistan.","editorialReason":"Explain documented channels, labour and maintenance with community evidence still required.","sortOrder":401}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-hunzas-fort-and-the-settlement-below-it','hunzas-fort-and-the-settlement-below-it','review','{"id":"story-hunzas-fort-and-the-settlement-below-it","type":"story","slug":"hunzas-fort-and-the-settlement-below-it","title":"Hunza’s fort and the settlement below it","summary":"The settlement beneath Baltit Fort asks different conservation questions from the monument itself: housing, services, livelihoods and the effects of visitors.","body":[{"type":"paragraph","text":"The view of Baltit Fort from Karimabad can encourage a simple reading: a celebrated monument above, an attractive settlement below. Conservation becomes more complicated when the lower part of that image is understood as somewhere people live and work. A house, a lane and a shop have requirements that are not identical to those of a museum or landmark."},{"type":"heading","level":2,"text":"A settlement is not a foreground"},{"type":"paragraph","text":"The Aga Khan Trust for Culture’s account of work in Hunza describes concern about abandonment of older settlement areas and construction spreading into cultivated land. Its programme connected building conservation with improvements such as services and paving. The aim was not merely to improve the view towards the fort."},{"type":"paragraph","text":"This historical project account suggests a practical distinction. Repairing a roof and maintaining a usable home may protect heritage more effectively than preserving an exterior while everyday life becomes difficult inside. A visitor sees a façade briefly; residents encounter its performance through seasons and daily routines."},{"type":"paragraph","text":"That does not mean any change is automatically beneficial. It means that assessing a change requires asking whose needs it meets. Decisions about access, sanitation or circulation have consequences that cannot be judged solely from a before-and-after photograph."},{"type":"heading","level":2,"text":"Benefits need to be examined"},{"type":"paragraph","text":"A 2013 Freie Universität Berlin evaluation considers the relationship between built-environment preservation and community development in Gilgit-Baltistan. Its Karimabad discussion connects tourism with shops, handicraft production and marketing. It also records the vulnerability of visitor-related activity to wider disruption. Conservation and tourism are related, but their relationship is not a guarantee of steadily rising income."},{"type":"paragraph","text":"The evaluation describes organisations and businesses responding to demand, including efforts associated with handicrafts. These are observations from a particular period. They should not be repackaged as current employment totals or proof that every household benefited equally."},{"type":"paragraph","text":"For an archive, the important question is distribution. A business near a visitor route, a household elsewhere in the settlement and a person making goods for sale may experience the same conservation programme differently. A successful monument project does not settle all three accounts in advance."},{"type":"heading","level":2,"text":"Looking beyond the silhouette"},{"type":"paragraph","text":"The UNESCO Tentative List identifies Baltit as a fort property. That recognition is useful context, but a monument description is not a complete social history of the surrounding settlement. Nor does tentative listing mean inscription on the World Heritage List."},{"type":"paragraph","text":"A future neighbourhood account could follow one lane through its uses rather than treating it as a photographic approach. Where do residents need access? Which spaces are shared? Which buildings remain homes? These are proposed lines of enquiry, not claims made from an aerial image or a brief visit."},{"type":"paragraph","text":"Understanding Karimabad this way need not diminish the fort. It places the landmark within the relationships that make conservation consequential. The richer story is not simply that an impressive building survives above Hunza. It is that preserving a prominent monument raises continuing questions about the settlement beneath it and the people whose lives do not stop when visitors leave."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Gilgit-Baltistan","Cultural Landscapes"],"province":"Gilgit-Baltistan","district":"Hunza","relatedDistrictIds":["gilgit-baltistan-hunza"],"provinceRegionIds":["gilgit-baltistan"],"relatedHeritageIds":["curated-baltit"],"relatedStoryIds":[],"contentType":"landscape","seo":{"title":"Hunza’s fort and the settlement below it","description":"The settlement beneath Baltit Fort asks different conservation questions from the monument itself: housing, services, livelihoods and the effects of visitors.","primaryKeyword":"Hunza fort settlement landscape","socialTitle":"Hunza’s fort and the settlement below it","socialDescription":"The settlement beneath Baltit Fort asks different conservation questions from the monument itself: housing, services, livelihoods and the effects of visitors."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Preservation of Built Environment and Its Impacts on Community Development in Gilgit-Baltistan","url":"https://www.geo.fu-berlin.de/geog/fachrichtungen/anthrogeog/zelf/_media_/download/Berlin_Geographical_Papers/BGP_42_Preservation-of-built-environment.pdf","publisher":"Hermann Kreutzmann / Freie Universität Berlin","accessDate":"2026-10-22","section":"Berlin Geographical Papers 42, 2013"},{"title":"Steering the Transformation of the Physical Environment in Hunza","url":"https://static.the.akdn/53832/1641873948-2005_hcsp_hunza.pdf","publisher":"Aga Khan Trust for Culture","accessDate":"2026-10-22","section":"2005 report"},{"title":"Baltit Fort","url":"https://whc.unesco.org/en/tentativelists/1882/","publisher":"UNESCO World Heritage Centre / Department of Archaeology and Museums","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. Distinct from355 fort authority/architecture: focuses village services and distribution of conservation outcomes. BGP42 full reader size limitation; indexed Karimabad evaluation passages close-read; no claim entire report read. BGP42 approximately135 derived words; AKTC2005 approximately65 (prior355 approximately110); TL only identity approximately15 (prior355 approximately85). Evaluation observations dated2013, not current tourism performance or access.","editorialReason":"Study the relation of elite architecture and ordinary settlement without duplicating the fort profile.","sortOrder":402}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-rock-art-corridors-of-the-upper-indus','rock-art-corridors-of-the-upper-indus','review','{"id":"story-rock-art-corridors-of-the-upper-indus","type":"story","slug":"rock-art-corridors-of-the-upper-indus","title":"Rock-art corridors of the upper Indus","summary":"Upper Indus rock art records many acts of marking across a landscape. Inscriptions and images illuminate movement without making every maker a foreign traveller.","body":[{"type":"paragraph","text":"Rock art beside the upper Indus can make movement visible without drawing a complete route on a map. Images and inscriptions occur at particular surfaces, but their makers did not all leave the same kind of evidence. Some recorded names or religious acts; others left marks whose circumstances remain uncertain. A corridor is therefore a useful way to think about connections, not a single explanation for everything engraved along it."},{"type":"heading","level":2,"text":"Many kinds of encounter"},{"type":"paragraph","text":"Jason Neelis’s research presentation places inscriptions and rock art within networks of movement through the upper Indus region. It distinguishes major routes from smaller connecting paths and considers both local inhabitants and people passing through. This avoids the familiar shortcut in which every unusual image becomes the work of a distant traveller."},{"type":"paragraph","text":"The written evidence includes several scripts and languages. Identifying a script can help frame a question about chronology or communication, but it does not automatically identify the birthplace of its writer. Someone could use a learned language without having travelled from the place most associated with it."},{"type":"paragraph","text":"Images require a similar caution. A stupa drawing, an animal and an inscription on neighbouring rock may belong to different moments. Physical proximity invites comparison; it does not establish that all were made by one group or as a single composition."},{"type":"heading","level":2,"text":"Reading is an argument"},{"type":"paragraph","text":"Thomas Höllmann’s study of Chinese inscriptions illustrates the interpretive work involved. His discussion of a Haldeikish inscription proceeds from photographs and considers readings of names, titles and a reference to Wei. The name of a dynasty is not enough by itself to provide an uncontested date, because more than one historical polity used that designation."},{"type":"paragraph","text":"This is a useful model for an archive caption. It should separate what can be seen, what a specialist reads and what that reading may imply. A proposed identification can be interesting without being presented as certainty. Translation should not erase the difficulty of the original evidence."},{"type":"heading","level":2,"text":"Sites, not an undifferentiated gallery"},{"type":"paragraph","text":"The official catalogue records locations including Hodar, Thalpan and the Sor Das group in Rondu. Keeping these names and geographic relationships distinct helps readers understand the distribution of evidence. Combining their images into a single decorative montage would conceal the individual surfaces and settings that make them informative."},{"type":"paragraph","text":"The history of research also deserves precision. Karl Jettmar’s introduction acknowledges earlier knowledge of rock carvings before the systematic investigations begun in 1979. A modern research project should not be described as discovering a landscape that local people and earlier observers already knew."},{"type":"paragraph","text":"For public interpretation, the strongest invitation is to look closely without intervening. Marks should not be traced, wetted or altered to make a photograph clearer. More importantly, the archive should preserve uncertainty in its language. Upper Indus rock art is compelling because it records many encounters across time; reducing those encounters to one effortless Silk Road story would make the evidence less, not more, remarkable."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Rock Art","Gilgit-Baltistan","Cultural Landscapes"],"province":"Gilgit-Baltistan","district":null,"relatedDistrictIds":["gilgit-baltistan-diamir","gilgit-baltistan-rondu"],"provinceRegionIds":["gilgit-baltistan"],"relatedHeritageIds":["major-doam-8249","major-doam-8278","major-doam-7811"],"relatedStoryIds":[],"contentType":"landscape","seo":{"title":"Rock-art corridors of the upper Indus","description":"Upper Indus rock art records many acts of marking across a landscape. Inscriptions and images illuminate movement without making every maker a foreign traveller.","primaryKeyword":"Upper Indus rock art landscape","socialTitle":"Rock-art corridors of the upper Indus","socialDescription":"Upper Indus rock art records many acts of marking across a landscape. Inscriptions and images illuminate movement without making every maker a foreign traveller."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Upper Indus rock art and inscriptions story map","url":"https://storymaps.arcgis.com/stories/d5018abb97d34ac7ba3a3a84d0267e72","publisher":"Jason Neelis","accessDate":"2026-10-22","section":"2023; updated 2024"},{"title":"Chinese rock inscriptions in the Indus valley","url":"https://en.unesco.org/silkroad/sites/default/files/knowledge-bank-article/chinese_rock_inscriptions_in_the_indus_valley.pdf","publisher":"Thomas O. Höllmann / UNESCO Silk Roads knowledge bank","accessDate":"2026-10-22"},{"title":"Introduction to Antiquities of Northern Pakistan","url":"https://archiv.ub.uni-heidelberg.de/propylaeumdok/6493/1/Jettmar_Introduction_1989.pdf","publisher":"Karl Jettmar / Heidelberg University repository","accessDate":"2026-10-22","section":"1989"},{"title":"Hodar","url":"https://doam.gov.pk/public/sites/8249","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Thalpan","url":"https://doam.gov.pk/public/sites/8278","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Sor Das Group of Rock Carvings, Rondu","url":"https://doam.gov.pk/public/sites/7811","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. Neelis storymap reader empty, detailed indexed author text read; approximately145 derived words. Höllmann selected opening inscription analysis read, approximately85; avoid definitive date/ethnicity. Jettmar historical introduction approximately30. DOAM IDs geographic anchors only; no chronology adopted from generic catalogue motif claims. No visitor access/safety assurance, tracing or touching instruction.","editorialReason":"Connect movement and recorded sites without assigning every engraving to travellers.","sortOrder":403}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-neelum-valley-sacred-remains-and-a-river-corridor','neelum-valley-sacred-remains-and-a-river-corridor','review','{"id":"story-neelum-valley-sacred-remains-and-a-river-corridor","type":"story","slug":"neelum-valley-sacred-remains-and-a-river-corridor","title":"Neelum valley: sacred remains and a river corridor","summary":"Around Sharda, temple, fort and river setting invite a layered reading of Neelum’s landscape without turning sacred tradition into a fixed architectural chronology.","body":[{"type":"paragraph","text":"At Sharda, the meeting of watercourses helps explain why a small area can hold several kinds of significance. A temple, a fort and the surrounding settlement should not be read as one monument with one date. They belong to different histories, even where the same landscape brings them into view together."},{"type":"heading","level":2,"text":"A sacred place and its surviving fabric"},{"type":"paragraph","text":"The Department of Archaeology and Museums places Sharda Temple near the Neelum and Madhumati watercourses. Its record describes a raised stone structure and architectural details including trefoil forms. Such features give an account something material to discuss: position, construction and the organisation of the surviving building."},{"type":"paragraph","text":"They do not, on their own, settle every question about origin. Architectural dates proposed for Sharda should be distinguished from the age of traditions associated with the sacred place. A story preserved in literature or devotion may be important without providing a construction inscription for the masonry now visible."},{"type":"paragraph","text":"Published studies of the temple bring architectural description into conversation with its religious associations. Their value is greatest when those forms of evidence remain identifiable. An archive should not turn every statement about learning or pilgrimage into proof of an excavated university campus, nor use the absence of a particular surviving feature as proof that no earlier activity occurred."},{"type":"heading","level":2,"text":"A different structure beside the corridor"},{"type":"paragraph","text":"The official record treats Sharda Fort separately and associates it with the nineteenth-century Dogra period. It describes a construction using stone, timber and earth in the river-confluence setting. The fort’s purpose and fabric therefore need their own explanation rather than being appended to the temple as if both formed a single ancient complex."},{"type":"paragraph","text":"Putting these structures on one map can be helpful. Giving them the same date or significance would not be. The relationship is spatial: different activities have occupied a strategically and culturally meaningful setting over time. Whether particular routes or institutions connected them requires evidence beyond proximity."},{"type":"heading","level":2,"text":"A river is more than scenery"},{"type":"paragraph","text":"Water offers a way to organise a careful reading without inventing a journey. The temple’s position, the fort’s setting and the routes available through a valley can be considered in relation to terrain. That approach does not require claiming that every historical traveller followed the same path or stopped at the same place."},{"type":"paragraph","text":"A future field account should distinguish an observed present-day crossing from a documented older one. It should also record local names with their speakers and spellings, rather than assume that one transliteration captures every usage. These are practical safeguards against letting a smooth narrative outrun its evidence."},{"type":"paragraph","text":"Sharda’s significance does not depend on removing uncertainty. Sacred associations, architectural remains and later military construction can each be meaningful on their own terms. Reading them together produces a layered Neelum landscape, provided the layers remain visible. Current access, permissions and travel conditions are separate matters and should be checked independently of any historical account."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Azad Kashmir","Cultural Landscapes"],"province":"Azad Jammu and Kashmir","district":"Neelum","relatedDistrictIds":["azad-kashmir-neelum"],"provinceRegionIds":["azad-kashmir"],"relatedHeritageIds":["major-doam-6633","major-doam-6666"],"relatedStoryIds":[],"contentType":"landscape","seo":{"title":"Neelum valley: sacred remains and a river corridor","description":"Around Sharda, temple, fort and river setting invite a layered reading of Neelum’s landscape without turning sacred tradition into a fixed architectural chronology.","primaryKeyword":"Neelum cultural landscape","socialTitle":"Neelum valley: sacred remains and a river corridor","socialDescription":"Around Sharda, temple, fort and river setting invite a layered reading of Neelum’s landscape without turning sacred tradition into a fixed architectural chronology."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Sharda Temple","url":"https://doam.gov.pk/public/sites/6633","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Sharda Fort","url":"https://doam.gov.pk/public/sites/6666","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Sharda Temple: an ancient archaeological site","url":"https://jac.qau.edu.pk/index.php/jac/article/download/124/93/190","publisher":"Journal of Asian Civilizations, Quaid-i-Azam University","accessDate":"2026-10-22","section":"2019 article; selected indexed architectural discussion"},{"title":"History, Architecture and Tourism Prospects of the Sharda Temple in Neelum Valley, Pakistan: An Appraisal","url":"https://grrjournal.com/article/history-architecture-and-tourism-prospects-of-the-sharda-temple-in-neelum-valley-pakistan-an-appraisal","publisher":"Global Regional Review","accessDate":"2026-10-22","section":"2022"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. JAC full PDF403, selected indexed architectural passages only. GRR article indexed findings read; not proof of ancient university or Buddhist monastery. DOAM2020survey shares title across records; limited architectural/topographic facts approximately100 combined here; earlier358 budget should be checked before publication if expanded. No definitive7c construction, current accessibility or pilgrimage permission claim. Interpretive uncertainty is central.","editorialReason":"Keep architecture, landscape and attributed traditions distinct in a sensitive regional setting.","sortOrder":404}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-the-margalla-foothills-before-the-planned-capital','the-margalla-foothills-before-the-planned-capital','review','{"id":"story-the-margalla-foothills-before-the-planned-capital","type":"story","slug":"the-margalla-foothills-before-the-planned-capital","title":"The Margalla foothills before the planned capital","summary":"Routes, caves and excavated structures in the Margalla foothills reveal histories that precede Islamabad’s modern plan and cross its administrative boundary.","body":[{"type":"paragraph","text":"The modern plan of Islamabad can make the surrounding foothills appear to be its natural frame. Their history is not confined to that role. Routes, shelters and archaeological remains belong to landscapes that existed before the capital’s streets and sectors. Understanding them requires looking across the present boundary between Islamabad and neighbouring Rawalpindi rather than treating that line as an ancient division."},{"type":"heading","level":2,"text":"A pass belongs to a wider route"},{"type":"paragraph","text":"The official heritage catalogue records remains of the Grand Trunk Road at Margalla Pass. The relevant record is geographically associated with Rawalpindi, not simply absorbed into Islamabad because the capital is nearby. This distinction matters for both mapping and interpretation."},{"type":"paragraph","text":"A road fragment can help establish the material presence of a route, but it cannot demonstrate every historical journey later associated with that corridor. Road surfaces change, alignments shift and repairs accumulate. Describing a recorded stretch is more precise than assigning all movement through the hills to one unchanged ancient road."},{"type":"heading","level":2,"text":"Shelter, water and uncertain chronology"},{"type":"paragraph","text":"Shah Allah Ditta’s caves and spring provide another kind of evidence. Their combination encourages questions about shelter and water, but the official record should not be stretched into a detailed account of named occupants or uninterrupted use. Popular age claims need stronger support than their repetition in visitor descriptions."},{"type":"paragraph","text":"An archive can be useful while leaving those questions open. It can identify the place and explain which features are recorded, then distinguish material description from religious attribution or local tradition. That separation protects the significance of the site from dependence on a dramatic but poorly supported date."},{"type":"heading","level":2,"text":"Excavation changes the questions"},{"type":"paragraph","text":"Ban Faqiran offers a different evidential situation. A report in Pakistan Archaeology describes excavations carried out between August 2015 and February 2016, investigating a stupa and a mosque. Their presence within the investigated area does not make them contemporary or parts of one original institution."},{"type":"paragraph","text":"The stupa’s surviving masonry and architectural components provide evidence that can be studied through excavation and recording. The official catalogue also notes losses to its upper structure. A reconstruction of the complete monument would therefore be an interpretation, not simply a photograph of what survives."},{"type":"paragraph","text":"These distinctions help explain why a landscape history cannot be assembled by lining up attractive sites and assigning them one era. Excavated relationships, standing fabric, documentary references and attributed traditions have different strengths. Each can contribute without being made to answer questions beyond its scope."},{"type":"heading","level":2,"text":"Before the capital, not outside its story"},{"type":"paragraph","text":"The point is not to describe an ancient Islamabad. That would project a modern city backwards onto places with their own histories. Instead, the foothills show how the capital now sits beside and within older patterns of movement and occupation."},{"type":"paragraph","text":"A regional map can make those relationships visible while retaining accurate district assignments. The road, caves and stupa do not become interchangeable attractions. Together they invite a more attentive view of the Margallas: a terrain carrying several histories, not merely a scenic edge to a planned city."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Islamabad","Cultural Landscapes"],"province":null,"district":null,"relatedDistrictIds":["punjab-rawalpindi","islamabad-islamabad"],"provinceRegionIds":["punjab","islamabad"],"relatedHeritageIds":["major-doam-6684","major-doam-6344","major-doam-6315"],"relatedStoryIds":[],"contentType":"landscape","seo":{"title":"The Margalla foothills before the planned capital","description":"Routes, caves and excavated structures in the Margalla foothills reveal histories that precede Islamabad’s modern plan and cross its administrative boundary.","primaryKeyword":"Margalla historic landscape","socialTitle":"The Margalla foothills before the planned capital","socialDescription":"Routes, caves and excavated structures in the Margalla foothills reveal histories that precede Islamabad’s modern plan and cross its administrative boundary."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Grand Trunk Road Remains, Margalla Pass","url":"https://doam.gov.pk/public/sites/6684","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Shah Allah Ditta Caves","url":"https://doam.gov.pk/public/sites/6344","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Ban Faqiran Stupa","url":"https://doam.gov.pk/public/sites/6315","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22"},{"title":"Pakistan Archaeology: report on excavations at Ban Faqiran","url":"https://iris.unive.it/retrieve/e4239ddd-bd16-7180-e053-3705fe0a3322/Archaeology%20New%202019%20%20%2025-06-2020.pdf","publisher":"Department of Archaeology and Museums, Pakistan","accessDate":"2026-10-22","section":"2019 volume; excavation report"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Review draft. Retain cross-boundary relations Rawalpindi+Islamabad because article explicitly regional. Primary excavation report indexed selected passages, not entire volume. Avoid conflicting stupa dimensions between report/catalogue, exact ancient dating for Shah Allah Ditta, generic Buddhist meditation claim, or all remains contemporary. Approximate allocations: excavation130, DOAM6684 60 (prior386~40), DOAM6344 50 (prior359~90), DOAM6315 30. No visitor access instructions.","editorialReason":"Relate route, shelter and archaeological sites across the capital boundary without overriding their actual geographic assignments.","sortOrder":405}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-world-heritage-is-not-the-same-as-the-tentative-list','world-heritage-is-not-the-same-as-the-tentative-list','review','{"id":"story-world-heritage-is-not-the-same-as-the-tentative-list","type":"story","slug":"world-heritage-is-not-the-same-as-the-tentative-list","title":"World Heritage is not the same as the Tentative List","summary":"How a national proposal differs from an inscription, and why precise labels matter when exploring Pakistan’s heritage.","body":[{"type":"paragraph","text":"A place can deserve serious attention without being inscribed on the World Heritage List. Confusion begins when the words UNESCO, nominated and listed are used as though they describe one status. They do not. A useful heritage guide should tell readers which process a place has reached, not reward it with the most impressive available label."},{"type":"paragraph","text":"UNESCO describes a Tentative List as a State Party’s inventory of places it may consider for nomination. The national submission is therefore a proposal about potential international significance. Publication on UNESCO’s website makes that proposal accessible; it does not turn its argument into a decision to inscribe the place on the World Heritage List."},{"type":"heading","level":2,"text":"Reading the status before the story"},{"type":"paragraph","text":"For a reader, the first practical distinction is between the name of a place and the name of its designation. A historic mosque may have a familiar local name, a national protection category and an entry in an international process. These labels answer different questions. A photograph of the building cannot establish any of them. Nor can a travel article that repeats an undated claim of recognition."},{"type":"paragraph","text":"The World Heritage Centre explains that a nominated property must already appear on its State Party’s Tentative List. It also notes that an inscribed property is removed from that tentative inventory. Those two statements show why the lists should not be added together as if every entry were an existing World Heritage property. They describe different stages, not interchangeable collections."},{"type":"paragraph","text":"Consider a hypothetical guide with two cards. One says World Heritage, with an inscription year and an official property reference. The other says Tentative List, with a submission date and a link to the proposal. The second card is not a lesser invitation to learn. It is a more precise account of the evidence available. Replacing both labels with UNESCO site would remove useful information."},{"type":"heading","level":2,"text":"Recognition is not the whole value"},{"type":"paragraph","text":"The same discipline applies when an older article is updated. A writer should check the present official entry rather than carry its previous status forward automatically. The date of that check belongs with the reference. If the status changes, the explanation should change without rewriting the monument’s entire history as a recent discovery."},{"type":"paragraph","text":"For Virsapur, accurate status is a way of respecting both the institution and the place. International recognition can be important, but a site’s architectural, archaeological or community significance does not begin only when an international committee considers it. Clear labels allow curiosity to extend beyond the internationally recognised shortlist."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Heritage Practice"],"province":null,"district":null,"relatedDistrictIds":["punjab-bahawalpur","punjab-jhelum"],"provinceRegionIds":["punjab"],"relatedHeritageIds":["major-doam-6959","unesco-586"],"relatedStoryIds":[],"contentType":"heritage-concept","seo":{"title":"World Heritage is not the same as the Tentative List","description":"How a national proposal differs from an inscription, and why precise labels matter when exploring Pakistan’s heritage.","primaryKeyword":"UNESCO World Heritage tentative list difference","socialTitle":"World Heritage is not the same as the Tentative List","socialDescription":"How a national proposal differs from an inscription, and why precise labels matter when exploring Pakistan’s heritage."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Tentative Lists","url":"https://whc.unesco.org/en/tentativelists/","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Operational Guidelines","url":"https://whc.unesco.org/en/guidelines/","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Explain formal status precisely and prevent the promotion of nominations into inscriptions.","sortOrder":406}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-one-property-many-components-understanding-serial-heritage','one-property-many-components-understanding-serial-heritage','review','{"id":"story-one-property-many-components-understanding-serial-heritage","type":"story","slug":"one-property-many-components-understanding-serial-heritage","title":"One property, many components: understanding serial heritage","summary":"Taxila shows why one recognised heritage property can contain several distinct places without becoming several separate inscriptions.","body":[{"type":"paragraph","text":"A map invites us to count dots. Heritage recognition sometimes asks us to understand relationships instead. One World Heritage property may contain distinct component places, each with its own name, location and history. Treating every component as a separate inscription exaggerates the count. Collapsing them into one anonymous point conceals the landscape that makes the property meaningful."},{"type":"paragraph","text":"Taxila offers a particularly useful example. UNESCO describes it as a serial site encompassing several settlement remains, religious complexes and other archaeological places. Saraikala, Bhir, Sirkap and Sirsukh are named separately in the account of urban development. Buddhist monasteries contribute other kinds of evidence. The recognised property is not simply a single ruin called Taxila that can stand in for every location associated with that name."},{"type":"heading","level":2,"text":"Two levels of description"},{"type":"paragraph","text":"A property-level record explains the shared argument for significance. A component-level record tells us which part we are looking at. Neither level replaces the other. A photograph of one monastery can illustrate that monastery within the property, but it should not quietly imply that it shows every component. A coordinate for one settlement cannot be used as the precise position of all the others."},{"type":"paragraph","text":"Imagine an atlas that opens a parent record first, then offers a list of its constituent places. That structure lets a reader move from the collective story to a specific location without inventing additional international designations. It also gives the interface a sensible way to handle photographs: a caption can name the depicted component while retaining the parent property’s official reference."},{"type":"paragraph","text":"Historical differences remain important within the grouping. The sites need not be treated as one simultaneous city, nor should their physical separation be disguised by a continuous shape on a map. UNESCO’s Taxila account presents different settlement histories and varied religious remains. A responsible summary preserves those differences instead of making every feature part of one imagined moment."},{"type":"heading","level":2,"text":"Why the distinction helps visitors and researchers"},{"type":"paragraph","text":"For visitors, a component name helps make sense of a signboard, a museum label or a separate entrance. For researchers, it helps connect a photograph or excavation report to the right location. For editors, it prevents an appealing but inaccurate shortcut: attaching the parent title to any nearby ruin without checking the documented relationship."},{"type":"paragraph","text":"The simplest test is to ask two questions. What is the recognised property, and which part is this record actually describing? If an article answers only one, it may still be useful, but it should not pretend to answer both. A well-designed atlas can make the relationship visible without turning a complex landscape into either a misleading total or an unreadable catalogue."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Heritage Practice"],"province":null,"district":null,"relatedDistrictIds":["khyber-pakhtunkhwa-haripur","punjab-rawalpindi"],"provinceRegionIds":["khyber-pakhtunkhwa","punjab"],"relatedHeritageIds":["unesco-139"],"relatedStoryIds":[],"contentType":"heritage-concept","seo":{"title":"One property, many components: understanding serial heritage","description":"Taxila shows why one recognised heritage property can contain several distinct places without becoming several separate inscriptions.","primaryKeyword":"serial World Heritage components","socialTitle":"One property, many components: understanding serial heritage","socialDescription":"Taxila shows why one recognised heritage property can contain several distinct places without becoming several separate inscriptions."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Taxila","url":"https://whc.unesco.org/en/list/139/","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Operational Guidelines","url":"https://whc.unesco.org/en/guidelines/","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Explain a data and heritage concept through Taxila without adding duplicate properties.","sortOrder":407}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-tangible-and-intangible-heritage-connected-not-interchangeable','tangible-and-intangible-heritage-connected-not-interchangeable','review','{"id":"story-tangible-and-intangible-heritage-connected-not-interchangeable","type":"story","slug":"tangible-and-intangible-heritage-connected-not-interchangeable","title":"Tangible and intangible heritage: connected, not interchangeable","summary":"Buildings, objects, skills and performances belong to connected histories, but they require different forms of description and care.","body":[{"type":"paragraph","text":"A musical instrument can be held in a collection. The knowledge required to make and play it cannot be understood simply by measuring the object. This is a useful starting point for distinguishing tangible and intangible heritage. The distinction concerns what is being described and sustained; it does not divide culture into two unrelated worlds."},{"type":"paragraph","text":"The 2003 UNESCO Convention identifies practices, expressions, knowledge and skills recognised by communities as forms of intangible cultural heritage. It also acknowledges associated instruments, objects and spaces. The relationship is therefore present in the definition itself. A building may provide a setting for a practice, and an object may be essential to it, without either being identical to the living knowledge involved."},{"type":"heading","level":2,"text":"Different questions, connected evidence"},{"type":"paragraph","text":"Consider a hypothetical embroidered textile. An object study might document its fibres, stitches, dimensions, condition and ownership history. A study of living practice would ask who teaches the technique, how terms are used, how work is valued and how makers decide to continue or change it. These enquiries can inform one another, but an answer to one is not automatically evidence for the other."},{"type":"paragraph","text":"A historic example in a display case does not establish that a technique is still practised in exactly the same way. Equally, a contemporary maker’s variation does not make the work culturally meaningless because it differs from a museum specimen. A guide that presents only an unchanged ancestral pattern may miss experimentation, changes in materials or the maker’s own account of what matters."},{"type":"paragraph","text":"UNESCO’s discussion of safeguarding distinguishes supporting transmission from freezing practice into a fixed form. It emphasises the recognition and involvement of the communities concerned. In editorial terms, this means that a published photograph of a performance is not a substitute for asking practitioners how they describe it or what conditions apply to its documentation."},{"type":"heading","level":2,"text":"Choosing the right kind of care"},{"type":"paragraph","text":"The practical implications differ. A damaged object may need a conservator’s examination. A threatened skill may need time, income, teaching opportunities or access to materials. A building repair could support a gathering, but it cannot by itself guarantee that the knowledge shared there will continue. These are illustrative possibilities, not a universal programme for every tradition."},{"type":"paragraph","text":"When Virsapur links an object, a place and a story, the links should make those relationships easier to explore. They should not imply that ownership of an object confers authority over a community’s practice. Nor should a place description speak for everyone who uses it. The strongest account allows the material evidence and the people involved to remain distinct, connected and open to further understanding."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Heritage Practice"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"heritage-concept","seo":{"title":"Tangible and intangible heritage: connected, not interchangeable","description":"Buildings, objects, skills and performances belong to connected histories, but they require different forms of description and care.","primaryKeyword":"tangible intangible heritage difference","socialTitle":"Tangible and intangible heritage: connected, not interchangeable","socialDescription":"Buildings, objects, skills and performances belong to connected histories, but they require different forms of description and care."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Convention for the Safeguarding of the Intangible Cultural Heritage","url":"https://ich.unesco.org/convention","publisher":"UNESCO Intangible Cultural Heritage","accessDate":"2026-10-22","section":"Article 2"},{"title":"Safeguarding without freezing","url":"https://ich.unesco.org/en/safeguarding-00012","publisher":"UNESCO Intangible Cultural Heritage","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Clarify the distinction without separating living communities from their buildings and objects.","sortOrder":408}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-what-authenticity-means-beyond-original-bricks','what-authenticity-means-beyond-original-bricks','review','{"id":"story-what-authenticity-means-beyond-original-bricks","type":"story","slug":"what-authenticity-means-beyond-original-bricks","title":"What authenticity means beyond original bricks","summary":"Authenticity asks whether heritage claims are credible within their cultural context, not merely how old a building’s visible bricks appear.","body":[{"type":"paragraph","text":"The word authentic can sound reassuring while telling us very little. Applied casually to a building, it may mean old, attractive, untouched or simply unlike its surroundings. Heritage assessment asks a more demanding question: what values are being claimed, and how credibly can the available evidence express them? Age is relevant, but age alone does not answer that question."},{"type":"paragraph","text":"The Nara Document on Authenticity, developed in 1994, argues against judging every cultural context by one fixed test. It relates authenticity to credible information about heritage values and recognises several possible kinds of evidence, including materials, design, use, techniques and setting. Its importance lies partly in widening the enquiry beyond a visual count of surviving old surfaces."},{"type":"heading","level":2,"text":"A claim needs an explanation"},{"type":"paragraph","text":"Imagine a visitor comparing two hypothetical timber buildings. One retains older structural members but has lost its documented use and surroundings. Another includes replacement timber installed through an established maintenance practice. A photograph cannot settle which claims about either building are credible. The comparison needs records of change, knowledge of the practices involved and clarity about the values under discussion."},{"type":"paragraph","text":"This does not mean that any replacement can be called authentic. It means that the reasoning must be visible. Who identified the earlier form? Which evidence supports the proposed date? What was renewed, and why? Are surviving surfaces being mistaken for original construction, or later work being concealed? These questions are more useful than applying a positive label to an entire structure without qualification."},{"type":"paragraph","text":"The distinction also matters in writing. A sentence about authentic Mughal decoration may combine a date, a style, a material judgement and an attribution of workmanship. Each part may require different evidence. If a conservation report identifies later repairs, an editorial account should not erase them just because the restored room looks coherent in a photograph."},{"type":"heading","level":2,"text":"Beyond the untouched ideal"},{"type":"paragraph","text":"An inhabited place accumulates changes. Describing those changes accurately can make its history richer rather than less impressive. The challenge is not to celebrate every alteration or condemn every repair. It is to explain which features carry significance and how their history can be understood without confusing evidence with preference."},{"type":"paragraph","text":"For a reader, authenticity is therefore best approached as a reasoned assessment rather than a decorative adjective. Look for specific claims, named evidence and a clear account of interventions. A careful article may be less absolute than a promotional caption, but it gives you something more valuable: an explanation that can be questioned, compared and improved as research develops."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Conservation","Heritage Practice"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"heritage-concept","seo":{"title":"What authenticity means beyond original bricks","description":"Authenticity asks whether heritage claims are credible within their cultural context, not merely how old a building’s visible bricks appear.","primaryKeyword":"heritage authenticity meaning","socialTitle":"What authenticity means beyond original bricks","socialDescription":"Authenticity asks whether heritage claims are credible within their cultural context, not merely how old a building’s visible bricks appear."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Nara Document on Authenticity","url":"https://whc.unesco.org/archive/nara94.htm","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22","section":"Paragraphs 9–13"},{"title":"Authenticity","url":"https://whc.unesco.org/en/faq/187","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Explain a nuanced institutional concept without claiming that authenticity has one universal test.","sortOrder":409}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-integrity-asking-whether-enough-survives-to-convey-meaning','integrity-asking-whether-enough-survives-to-convey-meaning','review','{"id":"story-integrity-asking-whether-enough-survives-to-convey-meaning","type":"story","slug":"integrity-asking-whether-enough-survives-to-convey-meaning","title":"Integrity: asking whether enough survives to convey meaning","summary":"Integrity concerns the survival and relationships needed to express a place’s significance; it is not a synonym for untouched or perfectly preserved.","body":[{"type":"paragraph","text":"A monument may retain a striking facade while losing the relationships that explain it. Conversely, a ruin can retain enough evidence to communicate an important history without looking complete. Integrity helps describe this problem. It directs attention to the survival, extent and condition of the elements needed to convey a place’s significance rather than asking only whether the most photogenic building remains standing."},{"type":"paragraph","text":"UNESCO’s discussion of integrity distinguishes the presence of necessary elements from their condition and exposure to threats. The enquiry is therefore both spatial and material. Does the identified property contain the features required to explain its significance? Are those features sufficiently intact, and what processes may undermine them? A boundary and a condition report answer different parts of the same enquiry."},{"type":"heading","level":2,"text":"Enough of what, for which story?"},{"type":"paragraph","text":"Consider an imaginary water-powered workshop. If the significance being explained concerns a production system, preserving a machine but removing its water channel may leave a serious gap. If the claim concerns the design of a particular machine, the assessment may focus differently. The example shows why integrity cannot be judged without first stating what the place is significant for."},{"type":"paragraph","text":"The question is not whether every trace of every period survives. Archaeological places are often fragmentary. What matters is whether the surviving evidence can support the particular argument being made. A glossy reconstruction cannot automatically repair a loss of evidence, just as weathered masonry does not automatically mean that all meaningful relationships have been destroyed."},{"type":"paragraph","text":"UNESCO’s Taxila account illustrates why threats may extend beyond the immediate appearance of a ruin. Its integrity discussion identifies environmental pressures and activities in the surrounding valley as relevant to the property. The lesson for a general reader is not to diagnose those pressures from a photograph. It is to recognise that assessment needs a broader field of evidence than a single well-framed image."},{"type":"heading","level":2,"text":"Different from authenticity"},{"type":"paragraph","text":"Integrity and authenticity can overlap in discussion, but they ask different questions. A surviving feature may be credibly documented while the wider system to which it belonged is severely reduced. Another place may retain a broad arrangement but contain poorly explained replacement work. An account should describe those conditions separately rather than compress them into the vague claim that a site is well preserved."},{"type":"paragraph","text":"For Virsapur, a useful integrity description should identify the relevant elements, explain the scale of the property and cite the assessment being summarised. It should not become an unsupported condition score. Readers gain more from knowing what survives and why it matters than from receiving an unexplained badge of completeness."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Heritage Practice"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"heritage-concept","seo":{"title":"Integrity: asking whether enough survives to convey meaning","description":"Integrity concerns the survival and relationships needed to express a place’s significance; it is not a synonym for untouched or perfectly preserved.","primaryKeyword":"heritage integrity meaning","socialTitle":"Integrity: asking whether enough survives to convey meaning","socialDescription":"Integrity concerns the survival and relationships needed to express a place’s significance; it is not a synonym for untouched or perfectly preserved."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Integrity: discussion of wholeness and intactness","url":"https://whc.unesco.org/document/140656","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"},{"title":"Taxila","url":"https://whc.unesco.org/en/list/139/","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22","section":"Integrity section"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Distinguish integrity from authenticity with bounded illustrative cases.","sortOrder":410}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-why-the-setting-of-a-monument-matters','why-the-setting-of-a-monument-matters','review','{"id":"story-why-the-setting-of-a-monument-matters","type":"story","slug":"why-the-setting-of-a-monument-matters","title":"Why the setting of a monument matters","summary":"A monument’s setting includes meaningful spatial, social and environmental relationships, not just the empty space surrounding its walls.","body":[{"type":"paragraph","text":"A building does not explain itself only through its walls. The approach to a gateway, the slope beneath a fort, the water beside a garden and the activities around a shrine can all affect how a place is understood. Setting is the term used to investigate such relationships. It should not be confused with a requirement that everything nearby must look old."},{"type":"paragraph","text":"The 2005 ICOMOS Xi’an Declaration describes setting as the surrounding environment that contributes to a heritage place’s significance and character. Its account extends beyond views to social practices, uses, knowledge and interactions with the natural environment. This gives editors a more precise task than describing a monument as standing in beautiful surroundings."},{"type":"heading","level":2,"text":"Relationships rather than scenery"},{"type":"paragraph","text":"Imagine a caravanserai whose entrance faces a documented historic road. The road’s alignment may help explain the building’s orientation and function. A nearby patch of vacant land may be visually prominent but have a different relationship to its significance. Both deserve investigation; neither should be treated as important or irrelevant simply because it appears in the same photograph."},{"type":"paragraph","text":"The enquiry also has a temporal dimension. A river may have changed course, an approach may have been redirected, or a market may have developed around an older entrance. An article can explain those changes without presenting today’s view as an unchanged survival. Historical maps, photographs and accounts may show relationships that are no longer immediately visible on the ground."},{"type":"paragraph","text":"The Xi’an Declaration calls for several kinds of evidence, including records, descriptions, community perspectives and analysis of views. In practical writing, this encourages an account that separates a measured sightline from a remembered route or a customary association. The sources can be brought into conversation without being made to prove identical things."},{"type":"heading","level":2,"text":"Why a map boundary is not the whole explanation"},{"type":"paragraph","text":"A buffer line on a map can be an important planning tool, but readers still need to know what it is intended to protect. A line alone cannot explain why a hillside, approach or activity matters. Nor should an editorial diagram be mistaken for an official legal boundary. The diagram’s source, date and purpose should be stated."},{"type":"paragraph","text":"For a visitor, attention to setting changes the act of looking. Instead of isolating the monument from everything around it, ask how it is reached, what it faces and which relationships remain legible. This is not permission to enter private land or obstruct daily use. It is an invitation to recognise that heritage significance often resides in connections, and that those connections require evidence as carefully considered as the building itself."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Heritage Practice"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"heritage-concept","seo":{"title":"Why the setting of a monument matters","description":"A monument’s setting includes meaningful spatial, social and environmental relationships, not just the empty space surrounding its walls.","primaryKeyword":"heritage setting significance","socialTitle":"Why the setting of a monument matters","socialDescription":"A monument’s setting includes meaningful spatial, social and environmental relationships, not just the empty space surrounding its walls."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Xi’an Declaration on the Conservation of the Setting of Heritage Structures, Sites and Areas","url":"https://www.icomos.org/images/DOCUMENTS/Charters/xian-declaration.pdf","publisher":"International Council on Monuments and Sites","accessDate":"2026-10-22","section":"Articles 1–4"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Explain visual, spatial and functional relationships rather than only a buffer on a map.","sortOrder":411}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-a-heritage-designation-is-not-a-visitor-access-guarantee','a-heritage-designation-is-not-a-visitor-access-guarantee','review','{"id":"story-a-heritage-designation-is-not-a-visitor-access-guarantee","type":"story","slug":"a-heritage-designation-is-not-a-visitor-access-guarantee","title":"A heritage designation is not a visitor-access guarantee","summary":"Recognition tells us why a place matters, but it does not confirm ownership, opening hours, safe access or permission to photograph.","body":[{"type":"paragraph","text":"Finding an official heritage designation can make a place easier to understand. It does not, by itself, tell you whether you may enter it tomorrow. Recognition, ownership, management, physical safety and visitor arrangements are separate questions. A responsible guide should keep them separate, especially when a map makes a remote or unfamiliar place appear only a short journey away."},{"type":"paragraph","text":"The World Heritage Convention acknowledges the sovereignty of states and the property rights provided by national legislation. Its international framework is not a transfer of every recognised site into UNESCO ownership. Likewise, an entry on a Tentative List records a national proposal for possible nomination, not a new public-access arrangement."},{"type":"heading","level":2,"text":"What an entry can and cannot tell you"},{"type":"paragraph","text":"A designation may establish a formal status and direct you to an authoritative description. A management body may provide current visitor information. A photograph may show what a site looked like when it was taken. None of these sources automatically answers the questions addressed by the others. A decade-old photograph of an open doorway is not evidence that the doorway is presently accessible."},{"type":"paragraph","text":"Consider a hypothetical historic house that is privately occupied. Its inclusion in an architectural survey could be entirely appropriate while entry remains subject to the occupant’s permission. An archaeological site might have a recognised boundary but no maintained visitor route. A functioning religious place may welcome some activities while asking visitors to avoid others. These examples illustrate the distinctions; they are not access claims about particular places in Pakistan."},{"type":"paragraph","text":"A map coordinate needs similar caution. It identifies a location, not a safe approach, an approved parking area or an entrance. A point may represent the centre of an archaeological property rather than the gate a visitor should use. Navigation instructions deserve their own verification instead of being inferred from the existence of a marker."},{"type":"heading","level":2,"text":"Asking the useful questions"},{"type":"paragraph","text":"Before a visit, seek current information from the responsible local authority, manager or community contact. Ask about opening arrangements, permissions, restrictions and conditions relevant to your visit. If no dependable answer is available, uncertainty should remain visible. A heritage platform should not replace missing information with reassuring language merely to keep an itinerary attractive."},{"type":"paragraph","text":"The same restraint applies to photographs and recordings. Being allowed to enter does not settle every question about documenting people, ceremonies or interiors. These require attention to the specific setting and applicable rules. This article is an editorial distinction, not legal advice. Its central point is simple: recognition explains significance; access must be established through a separate, current and appropriate enquiry."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Heritage Practice"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"heritage-concept","seo":{"title":"A heritage designation is not a visitor-access guarantee","description":"Recognition tells us why a place matters, but it does not confirm ownership, opening hours, safe access or permission to photograph.","primaryKeyword":"heritage designation access","socialTitle":"A heritage designation is not a visitor-access guarantee","socialDescription":"Recognition tells us why a place matters, but it does not confirm ownership, opening hours, safe access or permission to photograph."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"World Heritage Convention","url":"https://whc.unesco.org/en/conventiontext/","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22","section":"Article 6"},{"title":"Tentative Lists","url":"https://whc.unesco.org/en/tentativelists/","publisher":"UNESCO World Heritage Centre","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Separate recognition, ownership, safety and opening arrangements without legal advice.","sortOrder":412}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-conservation-restoration-and-reconstruction','conservation-restoration-and-reconstruction','review','{"id":"story-conservation-restoration-and-reconstruction","type":"story","slug":"conservation-restoration-and-reconstruction","title":"Conservation, restoration and reconstruction","summary":"Conservation, restoration and reconstruction describe different kinds of work. Naming them accurately helps readers understand what has changed and why.","body":[{"type":"paragraph","text":"A newly repaired surface can hide an important question: what kind of intervention took place? Heritage writing often uses conservation, restoration and reconstruction as interchangeable words for making an old building look better. That shortcut obscures the work itself. The terms describe different relationships to surviving evidence, earlier form and newly introduced material."},{"type":"paragraph","text":"The Australia ICOMOS Burra Charter treats conservation as the broader work of caring for a place so that its cultural significance is retained. Within that framework, restoration returns existing fabric towards a known earlier state without introducing new material, while reconstruction involves introducing material to recover such a state. These are the charter’s distinctions, not a claim that every institution uses identical terminology in every context."},{"type":"heading","level":2,"text":"Name the intervention, not the effect"},{"type":"paragraph","text":"Imagine a damaged architectural fragment. Carefully stabilising its surviving material is different from reassembling separated original pieces. Making a missing section from new material raises another set of questions. The finished result may look coherent in each case, but the appearance does not reveal which process occurred. A useful project account should explain that process explicitly."},{"type":"paragraph","text":"Evidence matters particularly when an earlier form is being recovered. A photograph, measured drawing, surviving joint or written description may support one part of a proposal without establishing every detail. Where evidence ends, a confident-looking new surface does not make the uncertainty disappear. The Burra Charter’s discussion of restoration and reconstruction insists on sufficient evidence for the earlier state being presented."},{"type":"paragraph","text":"For an editor, this suggests specific questions. What remained before work began? Which elements were retained, moved, repaired or newly made? What records informed the decisions? Who carried out and documented the intervention? An article that answers these questions is more informative than one that simply celebrates a building as restored to its former glory."},{"type":"heading","level":2,"text":"Change should remain intelligible"},{"type":"paragraph","text":"Documentation allows later readers and specialists to distinguish historical fabric from subsequent treatment. It can also make changes in interpretation visible. A reconstruction based on one set of records may need to be reconsidered when further evidence emerges. Treating the result as an unquestionable original would prevent that conversation rather than strengthen the site’s history."},{"type":"paragraph","text":"This vocabulary is not a guide to carrying out repairs yourself. Materials and structures require appropriate specialist assessment, and an apparently minor intervention can affect evidence that is difficult to recover. The public value of accurate language is different: it helps visitors understand what they are seeing, recognise the decisions involved and appreciate conservation as a reasoned practice rather than a cosmetic before-and-after transformation."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Conservation","Heritage Practice"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"heritage-concept","seo":{"title":"Conservation, restoration and reconstruction","description":"Conservation, restoration and reconstruction describe different kinds of work. Naming them accurately helps readers understand what has changed and why.","primaryKeyword":"conservation restoration reconstruction difference","socialTitle":"Conservation, restoration and reconstruction","socialDescription":"Conservation, restoration and reconstruction describe different kinds of work. Naming them accurately helps readers understand what has changed and why."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"The Burra Charter, 2013","url":"https://australia.icomos.org/wp-content/uploads/The-Burra-Charter-2013-Adopted-31.10.2013.pdf","publisher":"Australia ICOMOS","accessDate":"2026-10-22","section":"Definitions and Articles 18–20"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Explain distinct interventions and the evidence needed to describe them accurately.","sortOrder":413}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-provenance-and-provenience-two-histories-of-an-object','provenance-and-provenience-two-histories-of-an-object','review','{"id":"story-provenance-and-provenience-two-histories-of-an-object","type":"story","slug":"provenance-and-provenience-two-histories-of-an-object","title":"Provenance and provenience: two histories of an object","summary":"An object’s ownership history and its archaeological find context answer different questions. Losing either can limit what a museum or reader can responsibly claim.","body":[{"type":"paragraph","text":"Two similar-looking words can lead to different histories of the same object. Provenance commonly refers to a history of ownership and movement between people or collections. Provenience, in archaeological usage, identifies the precise place where an object was found. Neither is a decorative addition to a museum record. Each can change the questions that the object is able to answer."},{"type":"paragraph","text":"The Metropolitan Museum of Art describes provenance research as an investigation of the journeys of works in its care. The Archaeological Institute of America distinguishes an artefact’s precise find location from its wider context and associations. These enquiries may overlap, but a documented purchase does not automatically recover a lost excavation record."},{"type":"heading","level":2,"text":"An object can have an incomplete biography"},{"type":"paragraph","text":"Suppose a vessel has a sequence of sale receipts covering the last hundred years, but no reliable account of where it was excavated. The receipts may help establish its modern movement. They cannot reveal which layer it came from, whether other objects were found beside it or how it related to a building. Those archaeological questions remain unresolved rather than being answered by the existence of a collector’s name."},{"type":"paragraph","text":"The reverse situation also matters. An excavation record may establish a find context, while later transfers remain poorly documented. Keeping the two kinds of information distinct prevents a well-recorded beginning from being used to conceal an uncertain later history. A gap is something to investigate, not necessarily proof of one particular explanation."},{"type":"paragraph","text":"The Met’s 2025 provenance discussion offers a concrete example through a Canosan head-vase. Its researchers describe both a recorded tomb discovery and subsequent dispersal, while noting gaps in the available history. The value of that account lies not only in the names it recovers, but also in its refusal to treat incomplete documentation as a seamless chain."},{"type":"heading","level":2,"text":"Reading the label carefully"},{"type":"paragraph","text":"On a collection page, look for differences between findspot, attributed production place, former owner and acquisition method. These fields may sound geographically precise while describing very different evidence. Made in a region is not the same claim as excavated at a named site. Acquired in a city does not establish either one."},{"type":"paragraph","text":"For Virsapur’s object stories, a good biography should identify which parts are documented and which are inferred. It should avoid turning a museum’s present location into the object’s original identity, or a stylistic attribution into an excavated fact. Such care does not reduce the object’s interest. It reveals that historical knowledge depends on records and relationships as much as on the survival of the object itself."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Archaeology","Heritage Practice"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"heritage-concept","seo":{"title":"Provenance and provenience: two histories of an object","description":"An object’s ownership history and its archaeological find context answer different questions. Losing either can limit what a museum or reader can responsibly claim.","primaryKeyword":"provenance provenience difference","socialTitle":"Provenance and provenience: two histories of an object","socialDescription":"An object’s ownership history and its archaeological find context answer different questions. Losing either can limit what a museum or reader can responsibly claim."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Provenance Research at The Met","url":"https://www.metmuseum.org/pt/research-centers/provenance-research","publisher":"Metropolitan Museum of Art","accessDate":"2026-10-22"},{"title":"Archaeological Tourism Guidelines: Archaeology 101","url":"https://www.archaeological.org/pdfs/AIATourismGuidelines.pdf","publisher":"Archaeological Institute of America","accessDate":"2026-10-22"},{"title":"Marking International Provenance Research Day at The Met","url":"https://www.metmuseum.org/pt/perspectives/international-provenance-research-day-2025","publisher":"Metropolitan Museum of Art","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Separate ownership history from archaeological find context through identified examples.","sortOrder":414}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-whose-heritage-participation-without-a-single-community-voice','whose-heritage-participation-without-a-single-community-voice','review','{"id":"story-whose-heritage-participation-without-a-single-community-voice","type":"story","slug":"whose-heritage-participation-without-a-single-community-voice","title":"Whose heritage? Participation without a single community voice","summary":"Meaningful heritage participation makes room for differing interests, consent and decisions, rather than assuming one invited voice represents everyone.","body":[{"type":"paragraph","text":"A heritage project may describe itself as community-led after holding a public meeting or interviewing a respected local figure. Those actions can be useful, but they do not by themselves establish who shaped the project’s decisions. Participation is a relationship over time: people need opportunities to influence what is recorded, how it is presented and what happens to the results."},{"type":"paragraph","text":"UNESCO’s intangible-heritage framework gives communities, groups and practitioners a central role in identifying and safeguarding their heritage. Its ethical principles also emphasise continuing informed consent and attention to the interests of those who maintain living practices. These principles offer a starting point for asking more precise questions than whether a consultation took place."},{"type":"heading","level":2,"text":"There may be more than one answer"},{"type":"paragraph","text":"Consider a hypothetical neighbourhood project about a historic market. Shopkeepers, residents, workers, property owners and visitors may value different aspects of the place. Some may welcome publicity; others may worry about disruption or unwanted exposure. The example does not assume inevitable conflict. It shows why a single spokesperson’s approval should not automatically be presented as agreement on behalf of everyone."},{"type":"paragraph","text":"An editor can make the boundaries of participation visible. Who was invited? Who could not attend? Which languages were used? Did participants see the account before it was published? These questions are not a substitute for local judgement, but they help distinguish a collaborative process from one that extracts information and returns only a polished story."},{"type":"paragraph","text":"Consent also concerns the form of publication. Agreeing to speak in an interview is not necessarily agreement to every future use of the recording. A transcript, translated quotation, photograph and promotional video can expose a person in different ways. A responsible project explains those proposed uses and provides a practicable way to raise concerns or correct an error."},{"type":"heading","level":2,"text":"Participation should affect the result"},{"type":"paragraph","text":"The strongest test is whether the process changes decisions. If participants identify a sensitive location, challenge a caption or ask for a recording to remain restricted, does the project have a way to respond? An invitation to speak carries little weight if every substantial editorial choice has already been closed."},{"type":"paragraph","text":"For Virsapur, acknowledging different voices should improve precision rather than produce an artificial claim of consensus. An account can identify the people consulted, distinguish their perspectives and state the limits of the work. Community participation does not require every person to tell the same story. It requires a respectful process in which the story’s subjects have meaningful agency, and in which disagreement or a decision not to participate is not silently edited away."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Heritage Practice"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"heritage-concept","seo":{"title":"Whose heritage? Participation without a single community voice","description":"Meaningful heritage participation makes room for differing interests, consent and decisions, rather than assuming one invited voice represents everyone.","primaryKeyword":"community heritage participation","socialTitle":"Whose heritage? Participation without a single community voice","socialDescription":"Meaningful heritage participation makes room for differing interests, consent and decisions, rather than assuming one invited voice represents everyone."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Involvement of communities, groups and individuals","url":"https://ich.unesco.org/en/involvement-of-communities-00033","publisher":"UNESCO Intangible Cultural Heritage","accessDate":"2026-10-22"},{"title":"Ethics and Intangible Cultural Heritage","url":"https://ich.unesco.org/en/ethics-and-ich-00866","publisher":"UNESCO Intangible Cultural Heritage","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Discuss representation and differing interests without assuming one spokesperson represents everyone.","sortOrder":415}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-heritage-value-is-not-a-popularity-contest','heritage-value-is-not-a-popularity-contest','review','{"id":"story-heritage-value-is-not-a-popularity-contest","type":"story","slug":"heritage-value-is-not-a-popularity-contest","title":"Heritage value is not a popularity contest","summary":"Fame and visitor numbers cannot replace an explanation of significance. A modest place may preserve evidence or memories absent from celebrated monuments.","body":[{"type":"paragraph","text":"A small structure at the edge of a town may receive less attention than a monumental gateway. That difference in visibility tells us something about publicity, access and visual appeal. It does not, on its own, establish the relative heritage significance of the two places. A popularity ranking answers a different question from a reasoned assessment of why something matters."},{"type":"paragraph","text":"Historic England’s Conservation Principles groups heritage values into evidential, historical, aesthetic and communal categories. This is a framework developed in a particular institutional context, not a ready-made legal test for Pakistan. Its usefulness here is conceptual: it reminds a reader that there is more than one way for a place to be significant."},{"type":"heading","level":2,"text":"Evidence may be unobtrusive"},{"type":"paragraph","text":"A hypothetical workshop could retain marks of a production method that is poorly documented elsewhere. Its facade might be plain, and it might not have a famous patron. An assessment would still need to ask what evidence survives, how securely it can be interpreted and whether comparable examples remain. None of those questions can be answered by counting how often the building appears on social media."},{"type":"paragraph","text":"A place can also be important through associations and collective experience. A meeting room, school or neighbourhood gathering space may hold meanings that are not obvious to a visitor. Such associations require documentation and careful attribution. Saying that a community values a place is stronger when the account identifies whose experiences were considered and how they were recorded."},{"type":"paragraph","text":"Visual qualities are not irrelevant. Scale, workmanship, spatial arrangement and sensory experience can contribute substantially to significance. The problem arises when visual appeal becomes the only criterion, or when dramatic photography conceals a lack of historical evidence. An unattractive current condition does not erase every value; a beautiful view does not establish every claim."},{"type":"heading","level":2,"text":"From ranking to explanation"},{"type":"paragraph","text":"An atlas can make this distinction practical by describing the reason for including a place. Is it an important surviving example, a source of archaeological evidence, a documented association, a continuing place of meaning, or several of these together? Clear answers let readers compare different kinds of significance without pretending that they can all be reduced to one score."},{"type":"paragraph","text":"This also changes how gaps are understood. Limited online information may reflect uneven research or digitisation rather than an absence of importance. At the same time, a claim of neglected significance should not become an excuse to invent a history. The next step is evidence gathering, not automatic promotion."},{"type":"paragraph","text":"Heritage discovery becomes richer when it moves beyond a shortlist of famous sights. The aim is not to reverse the ranking and declare every obscure place superior. It is to replace unsupported ranking with a transparent explanation of value, allowing modest structures and difficult histories to be considered on the strength of what they can actually tell us."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Heritage Practice"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"heritage-concept","seo":{"title":"Heritage value is not a popularity contest","description":"Fame and visitor numbers cannot replace an explanation of significance. A modest place may preserve evidence or memories absent from celebrated monuments.","primaryKeyword":"heritage significance assessment","socialTitle":"Heritage value is not a popularity contest","socialDescription":"Fame and visitor numbers cannot replace an explanation of significance. A modest place may preserve evidence or memories absent from celebrated monuments."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Conservation Principles, Policies and Guidance","url":"https://historicengland.org.uk/advice/constructive-conservation/conservation-principles/","publisher":"Historic England","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Explain multiple forms of significance and why a small site may matter.","sortOrder":416}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-what-responsible-heritage-tourism-should-not-promise','what-responsible-heritage-tourism-should-not-promise','review','{"id":"story-what-responsible-heritage-tourism-should-not-promise","type":"story","slug":"what-responsible-heritage-tourism-should-not-promise","title":"What responsible heritage tourism should not promise","summary":"Responsible tourism requires evidence about access, impacts and benefits. An appealing heritage itinerary should not promise more than it can demonstrate.","body":[{"type":"paragraph","text":"A heritage journey can create opportunities to learn, support local livelihoods and encounter places with care. None of those outcomes is guaranteed simply because the itinerary uses the word responsible. The description needs to explain what is being done, who is involved and how claims about benefits or reduced harm are supported."},{"type":"paragraph","text":"The 2022 ICOMOS International Charter for Cultural Heritage Tourism places conservation, participatory governance, interpretation and community resilience within the same framework. Its principles are not an endorsement of a particular tour. They offer questions against which tourism practices can be examined, including how impacts are monitored and whose rights and interests shape management."},{"type":"heading","level":2,"text":"Promises that deserve scrutiny"},{"type":"paragraph","text":"Exclusive access is one example. A tour organiser may legitimately arrange a visit with a responsible manager, but an advertisement should not imply permission that has not been secured. Nor should restricted access be treated as an obstacle to overcome for a better photograph. Some limits may be essential to safety, conservation, privacy or religious practice."},{"type":"paragraph","text":"Claims of community benefit need similar precision. Paying a local guide is a concrete action. Declaring that a visit supports the entire community is a much larger claim. A reader should be able to distinguish a documented payment, a partnership, a donation and a general aspiration. These are not interchangeable descriptions of the same transaction."},{"type":"paragraph","text":"Conservation language can also become vague. A visitor fee may contribute to a management budget, but that does not prove that a particular journey directly restores a monument. If an organiser claims a contribution to a project, it should explain the arrangement and identify the recipient rather than rely on a photograph of repair work."},{"type":"heading","level":2,"text":"Learning is part of the experience"},{"type":"paragraph","text":"Good interpretation can acknowledge uncertainty. A guide need not turn every tradition into a verified historical event or every building phase into a simple royal story. Explaining why an attribution is disputed can make the visit more interesting. It also respects the difference between a local account, an inscription and a later interpretation."},{"type":"paragraph","text":"For travellers, practical restraint matters alongside enthusiasm. Follow the arrangements communicated by the responsible hosts, avoid interfering with ordinary use and ask before recording people or sensitive activities. These are general editorial principles, not a substitute for site-specific advice or applicable rules."},{"type":"paragraph","text":"A credible heritage offer should leave room for change: a site may close, conditions may alter, or a community may decline participation. A responsible description makes such limits understandable instead of promising that everything will always be available. The best test is not how many ethical adjectives appear in the brochure, but whether the actual arrangements remain accountable to the place and the people who live with it."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Heritage Practice"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"heritage-concept","seo":{"title":"What responsible heritage tourism should not promise","description":"Responsible tourism requires evidence about access, impacts and benefits. An appealing heritage itinerary should not promise more than it can demonstrate.","primaryKeyword":"responsible heritage tourism Pakistan","socialTitle":"What responsible heritage tourism should not promise","socialDescription":"Responsible tourism requires evidence about access, impacts and benefits. An appealing heritage itinerary should not promise more than it can demonstrate."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"ICOMOS International Charter for Cultural Heritage Tourism, 2022","url":"https://admin.icomos.org/wp-content/uploads/2023/01/International-Cultural-Heritage-Tourism-Charter_EN_ES.pdf","publisher":"ICOMOS","accessDate":"2026-10-22","section":"Principles 1–7"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Set evidence-based expectations for access, conservation and community impact without selling an itinerary.","sortOrder":417}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-a-source-is-not-automatically-a-licence','a-source-is-not-automatically-a-licence','review','{"id":"story-a-source-is-not-automatically-a-licence","type":"story","slug":"a-source-is-not-automatically-a-licence","title":"A source is not automatically a licence","summary":"Crediting a photograph identifies its source; permission to reuse it requires a separate rights check and compliance with the applicable terms.","body":[{"type":"paragraph","text":"A heritage photograph may be easy to find and difficult to reuse responsibly. It can appear on a museum website, in a government catalogue or on a public social-media account without offering a licence for another organisation’s publication. A source link tells readers where the image was found. It does not, by itself, establish permission to copy it."},{"type":"paragraph","text":"The distinction is especially important when a photograph documents a historic building. The building’s age and the photograph’s rights are different questions. A modern image of an ancient object should not automatically be treated as an ancient image. Likewise, a public institution’s role as custodian does not mean that every photograph on its website carries identical reuse terms."},{"type":"heading","level":2,"text":"Read the terms attached to the actual file"},{"type":"paragraph","text":"Creative Commons provides several licences with different conditions. Its guidance distinguishes attribution, sharing adaptations under specified terms, non-commercial restrictions and limits on distributing adaptations. Seeing a CC label is therefore only the beginning of the check. The exact licence and version need to be identified, together with the person or organisation making the rights statement."},{"type":"paragraph","text":"For example, the CC BY 4.0 deed permits sharing and adaptation under its stated terms, including credit, a licence link and an indication of changes. It also warns that the licence may not supply every permission required for a proposed use. This article does not resolve privacy, personality rights or other legal issues for any particular photograph; those may require separate advice."},{"type":"paragraph","text":"An editorial record should keep the creator’s name, the original file page, the selected licence and the date of verification. It should also record changes such as resizing or cropping. A downloaded filename alone is a poor rights record because it can become separated from the page that explained the conditions."},{"type":"heading","level":2,"text":"Availability is not clearance"},{"type":"paragraph","text":"Consider an image copied into a research folder while a writer investigates a site. Its presence there means it was available for reference, not that it passed a publication check. If the rights remain unknown, the publishing system should preserve that uncertainty rather than infer approval from the file’s existence."},{"type":"paragraph","text":"The same applies to a credit that says only image courtesy of the internet. It neither identifies a creator nor explains the basis for reuse. A properly credited but unlicensed copy can still present a problem; a licensed image with missing required credit can also fail its conditions."},{"type":"paragraph","text":"For a cultural platform, a restrained no-image treatment is preferable to an undocumented assumption. Rights work is not separate from the institution’s respect for culture. It recognises photographers and other creators as participants whose labour deserves the same care that the platform gives to the subjects they depict."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Heritage Practice"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"heritage-concept","seo":{"title":"A source is not automatically a licence","description":"Crediting a photograph identifies its source; permission to reuse it requires a separate rights check and compliance with the applicable terms.","primaryKeyword":"heritage image rights source credit","socialTitle":"A source is not automatically a licence","socialDescription":"Crediting a photograph identifies its source; permission to reuse it requires a separate rights check and compliance with the applicable terms."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Creative Commons Licenses","url":"https://creativecommons.org/share-your-work/use-remix/cc-licenses/","publisher":"Creative Commons","accessDate":"2026-10-22"},{"title":"Considerations for licensors and licensees","url":"https://creativecommons.org/share-your-work/licensing-considerations/version4/","publisher":"Creative Commons","accessDate":"2026-10-22"},{"title":"CC BY 4.0 deed","url":"https://creativecommons.org/licenses/by/4.0/","publisher":"Creative Commons","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"General editorial literacy, not jurisdiction-specific legal advice. Human legal/rights review required before publication. No claim that a source citation alone grants permission.","editorialReason":"Explain attribution and permission as separate editorial checks; require legal review for specific licensing advice.","sortOrder":418}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-why-an-atlas-sometimes-leaves-a-place-unmapped','why-an-atlas-sometimes-leaves-a-place-unmapped','review','{"id":"story-why-an-atlas-sometimes-leaves-a-place-unmapped","type":"story","slug":"why-an-atlas-sometimes-leaves-a-place-unmapped","title":"Why an atlas sometimes leaves a place unmapped","summary":"An empty map position can be more honest than a precise-looking guess. Coordinates need provenance, context and an account of uncertainty.","body":[{"type":"paragraph","text":"An atlas can know that a heritage place exists without knowing exactly where to put its marker. A catalogue may identify a village, describe a nearby landmark or repeat an old coordinate that conflicts with the written location. In that situation, filling the gap with a convenient point can make the map look complete while making its information less trustworthy."},{"type":"paragraph","text":"GBIF’s Georeferencing Best Practices was developed for biodiversity records, not as a heritage-site designation standard. Its distinction between coordinate precision and location uncertainty is nevertheless useful for any reader of mapped records. More decimal places do not automatically mean better evidence. A coarse original measurement can acquire many digits when its format is converted."},{"type":"heading","level":2,"text":"The point should describe the place"},{"type":"paragraph","text":"Imagine a catalogue that places a ruin somewhere within a large district but gives no verified site coordinate. The district’s centre is a coordinate for an administrative area, not for that ruin. Assigning it to the heritage record would turn a known broad association into an unsupported exact location. A visitor might then mistake the marker for an entrance or navigable destination."},{"type":"paragraph","text":"A location also needs context. Does a coordinate represent a building, the centre of a large archaeological property, a survey observation or a visitor facility? Two different points can both be legitimate if they describe different features. Without that explanation, an apparent disagreement can be impossible to interpret."},{"type":"paragraph","text":"The GBIF guidance stresses the importance of retaining source information and considering locality descriptions alongside coordinates. Applied cautiously to a heritage atlas, this suggests an audit trail: record where the point came from, what it represents and why it was accepted or withheld. A later correction should improve that record rather than erase the reason for the earlier uncertainty."},{"type":"heading","level":2,"text":"Listing without pretending to locate"},{"type":"paragraph","text":"A platform can still make an unresolved place discoverable. It can provide a textual record, its documented district relationship and an explanation that precise mapping awaits verification. This is different from declaring the place unimportant or absent. It separates a question about identity from a question about spatial evidence."},{"type":"paragraph","text":"There may also be reasons not to publish an exact location even when it is known. Those require an explicit policy and responsible review, not an invented coordinate that quietly disguises the decision. The public record should communicate the limitation appropriately without exposing sensitive information."},{"type":"paragraph","text":"An honest atlas therefore contains both mapped knowledge and visible limits. Its quality is not measured only by the number of dots. It also depends on whether each dot can be defended, whether corrections remain traceable and whether the interface resists presenting uncertainty as an unwarranted promise of precision."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Heritage Practice"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"heritage-concept","seo":{"title":"Why an atlas sometimes leaves a place unmapped","description":"An empty map position can be more honest than a precise-looking guess. Coordinates need provenance, context and an account of uncertainty.","primaryKeyword":"heritage mapping uncertainty","socialTitle":"Why an atlas sometimes leaves a place unmapped","socialDescription":"An empty map position can be more honest than a precise-looking guess. Coordinates need provenance, context and an account of uncertainty."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Georeferencing Best Practices","url":"https://docs.gbif.org/georeferencing-best-practices/1.0/en/index.en.html","publisher":"GBIF Secretariat","accessDate":"2026-10-22","section":"Coordinate precision and uncertainty"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Explain coordinate uncertainty and why empty coverage should be honest rather than filled with a centroid.","sortOrder":419}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('stories','story-how-to-read-a-heritage-articles-references','how-to-read-a-heritage-articles-references','review','{"id":"story-how-to-read-a-heritage-articles-references","type":"story","slug":"how-to-read-a-heritage-articles-references","title":"How to read a heritage article’s references","summary":"References become useful when readers connect each source to a specific claim and distinguish observation, interpretation and repeated assertion.","body":[{"type":"paragraph","text":"A long list of references can make an article look authoritative without making its claims easy to check. The useful question is not simply whether sources are present. It is which source supports which statement, how that source acquired its information and what remains an interpretation. Reading references actively turns them from a decorative ending into a route through the evidence."},{"type":"paragraph","text":"The Library of Congress’s teaching guidance encourages attention to a source’s creator, purpose, audience and context. It also distinguishes observations from inferences. Those habits work well for heritage writing, where a photograph, a historical account, a survey and an institutional summary may all appear in the same bibliography while doing different kinds of work."},{"type":"heading","level":2,"text":"Match the claim to the evidence"},{"type":"paragraph","text":"If an article gives a construction date, look for the source of that date. An inscription may supply a specific statement; a later historian may interpret it; a modern catalogue may summarise the interpretation. The final date can be well supported, but the path matters. A link to the catalogue should not be described as though the writer personally examined the inscription."},{"type":"paragraph","text":"A photograph can establish visible features at a particular moment, assuming its identity and date are reliable. It cannot alone establish who built the structure or why a repair was undertaken. Conversely, a written record may describe a feature that no longer survives. Neither kind of evidence is automatically superior for every question."},{"type":"paragraph","text":"Repeated claims deserve special care. Five websites may trace back to the same unsupported paragraph. Counting them as five independent confirmations makes the evidence appear stronger than it is. A useful reference trail leads towards the underlying record or argument rather than circling between pages that repeat one another."},{"type":"heading","level":2,"text":"Uncertainty should be readable"},{"type":"paragraph","text":"Words such as attributed, probably and traditionally associated with should not be dismissed as weakness. Used carefully, they tell the reader what kind of confidence a source permits. The problem is not qualification but inconsistency: an uncertain attribution in the reference should not become an unquestioned fact in the headline."},{"type":"paragraph","text":"A reader can test an article by choosing one important sentence and following its citation. Does the linked page actually address the claim? Is it a primary record, an interpretation or a general introduction? Does the article preserve the source’s limits? If the link is too broad, the writer may need to add a page number, section or more specific reference."},{"type":"paragraph","text":"This approach does not require everyone to become a specialist before enjoying heritage stories. It makes curiosity more productive. Good references allow readers to continue the enquiry, recognise disagreement and understand why a careful account may change when new evidence becomes available."}],"primaryCategoryId":"archive-category-cultural-landscapes-historic-places","categoryIds":["archive-category-cultural-landscapes-historic-places"],"tags":["Heritage Practice"],"province":null,"district":null,"relatedDistrictIds":[],"provinceRegionIds":[],"relatedHeritageIds":[],"relatedStoryIds":[],"contentType":"heritage-concept","seo":{"title":"How to read a heritage article’s references","description":"References become useful when readers connect each source to a specific claim and distinguish observation, interpretation and repeated assertion.","primaryKeyword":"heritage source literacy","socialTitle":"How to read a heritage article’s references","socialDescription":"References become useful when readers connect each source to a specific claim and distinguish observation, interpretation and repeated assertion."},"featuredImage":null,"imageStatus":"no-cleared-image","references":[{"title":"Primary Sources and Research Part II: Sourcing and Contextualizing to Strengthen Analysis","url":"https://blogs.loc.gov/teachers/2014/03/primary-sources-and-research-part-ii-sourcing-and-contextualizing-to-strengthen-analysis/","publisher":"Library of Congress","accessDate":"2026-10-22"},{"title":"Using Claim, Evidence, and Reasoning with Primary Source Analysis","url":"https://blogs.loc.gov/teachers/2022/05/using-claim-evidence-and-reasoning-cer-with-primary-source-analysis/","publisher":"Library of Congress","accessDate":"2026-10-22"}],"aiAssisted":true,"editorialReviewRequired":true,"status":"review","featured":false,"internalNotes":"Research-based AI-assisted review draft. Examples described as hypothetical are editorial illustrations, not claims about a named site. Human subject review and citation verification required before publication.","editorialReason":"Teach readers to distinguish primary evidence, interpretation, institutional summaries and unsourced repetition.","sortOrder":420}'::jsonb) on conflict(collection,id) do nothing;
