insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-7658','gurdwara-panja-sahib','published','{"id":"major-doam-7658","mapDisplay":"featured","slug":"gurdwara-panja-sahib","status":"published","title":"Gurdwara Panja Sahib","shortTitle":"Gurdwara Panja Sahib","summary":"A Sikh shrine at Hasan Abdal associated with Guru Nanak and the sacred handprint tradition. Its monumental complex is an important centre of pilgrimage.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Major heritage site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/7658","verifiedDate":"2026-10-17","sourceTitle":"Gurdwara Panja Sahib (Hasan Abdal, Attock)","sourceRegion":"Punjab","sourceDistrict":"Attock","sourcePublication":"Survey and Documentation of Archaeological Sites and Monuments in District Attock ","selectionReason":"Major Sikh sacred architecture in previously unmapped Attock.","components":[{"id":"major-doam-7658-point","name":"Gurdwara Panja Sahib","latitude":33.820796009,"longitude":72.689693372,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/7658","coordinateNote":"Official catalogue site coordinate retained exactly at its published precision; not independently resurveyed. Current geographic contexts must be derived from protected polygons, not the historical source district label.","regionId":"punjab","districtId":"punjab-attock","regionIds":["punjab"],"districtIds":["punjab-attock"],"spatialMatches":[{"regionId":"punjab","districtId":"punjab-attock"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,"sor