insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-10358','attock-khurd-railway-station','published','{"id":"major-doam-10358","mapDisplay":"featured","slug":"attock-khurd-railway-station","status":"published","title":"Attock Khurd Railway Station","shortTitle":"Attock Khurd Railway Station","summary":"A stone-built colonial railway station beside the Indus crossing. The station represents the railway infrastructure that connected Punjab and the north-west.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Monument","designationType":"none","designationName":"Major heritage site","legalStatus":null,"legalStatusNote":"Catalogue legal-status field incorrectly cites Karachi/Sindh legislation for an Attock monument; not adopted. Conflicting construction-year wording omitted.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/10358","verifiedDate":"2026-10-17","sourceTitle":"Attock Khurd Railway Station","sourceRegion":"Punjab","sourceDistrict":"Attock","sourcePublication":"Attock Khurd Railway Station","selectionReason":"Adds transport and industrial-era heritage rather than another religious monument.","components":[{"id":"major-doam-10358-point","name":"Attock Khurd Railway Station","latitude":33.873517222,"longitude":72.240775944,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/10358","coordinateNote":"Official catalogue site coordinate retained exactly at its published precision; not independently resurveyed. Current geographic contexts must be derived from protected polygons, not the historical source district label.","regionId":"punjab","districtId":"punjab-attock","regionIds":["punjab"],"districtIds":["punjab-attock"],"spatialMatches":[{"regionId":"punjab","districtId":"punjab-attock"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeho