insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6418','sargana-mosque','published','{"id":"major-doam-6418","mapDisplay":"featured","slug":"sargana-mosque","status":"published","title":"Sargana Mosque","shortTitle":"Sargana Mosque","summary":"A three-domed mosque in the Mailsi area, with a larger central dome and an arched prayer chamber. Green glazed tiles and Persian inscriptions ornament its facade.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Major heritage site","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6418","verifiedDate":"2026-10-17","sourceTitle":"Ruined Mosque (Village Sargana)","sourceRegion":"Punjab","sourceDistrict":"Vehari","sourcePublication":"Archaeological Sites and Historical Monuments Protected Under the Antiquities Act, 1975","selectionReason":"Architecturally documented mosque in Vehari, preferred over poorly supported legendary attributions.","components":[{"id":"major-doam-6418-point","name":"Sargana Mosque","latitude":29.928755667,"longitude":72.193663444,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6418","coordinateNote":"Official catalogue site coordinate retained exactly at its published precision; not independently resurveyed. Current geographic contexts must be derived from protected polygons, not the historical source district label.","regionId":"punjab","districtId":"punjab-vehari","regionIds":["punjab"],"districtIds":["punjab-vehari"],"spatialMatches":[{"regionId":"punjab","districtId":"punjab-vehari"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholder