insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6178','daira-din-panah-shrine','published','{"id":"major-doam-6178","mapDisplay":"featured","slug":"daira-din-panah-shrine","status":"published","title":"Daira Din Panah Shrine","shortTitle":"Daira Din Panah Shrine","summary":"An octagonal tomb with corner minarets and a large dome, accompanied by a three-domed mosque. The ensemble illustrates the region’s historic funerary building tradition.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Major heritage site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6178","verifiedDate":"2026-10-17","sourceTitle":"Daira Din Panah","sourceRegion":"Punjab","sourceDistrict":"Muzaffargarh","sourcePublication":"The Monuments and Ancient Sites in the Surveyed Districts of Punjab","selectionReason":"Newly configured Kot Addu coverage derived from exact catalogue coordinates.","components":[{"id":"major-doam-6178-point","name":"Daira Din Panah Shrine","latitude":30.570833333,"longitude":70.933333333,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6178","coordinateNote":"Official catalogue site coordinate retained exactly at its published precision; not independently resurveyed. Current geographic contexts must be derived from protected polygons, not the historical source district label.","regionId":"punjab","districtId":"punjab-kot-addu","regionIds":["punjab"],"districtIds":["punjab-kot-addu"],"spatialMatches":[{"regionId":"punjab","districtId":"punjab-kot-addu"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured