insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6373','historic-murree-brewery-ruins','published','{"id":"major-doam-6373","mapDisplay":"featured","slug":"historic-murree-brewery-ruins","status":"published","title":"Historic Murree Brewery Ruins","shortTitle":"Historic Murree Brewery Ruins","summary":"The remains of a colonial brewery comprise stone-built buildings with arched openings. The complex represents industrial heritage in the Murree hills, rather than the present-day Rawalpindi brewery.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Monument","designationType":"none","designationName":"Major heritage site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6373","verifiedDate":"2026-10-17","sourceTitle":"Murree Brewery","sourceRegion":"Punjab","sourceDistrict":"Rawalpindi","sourcePublication":"Archaeological Remains of Islamabad Capital Territory and Rawalpindi District","selectionReason":"Adds industrial archaeology in the newly configured Murree district.","components":[{"id":"major-doam-6373-point","name":"Historic Murree Brewery Ruins","latitude":33.88249,"longitude":73.35937,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6373","coordinateNote":"Official catalogue site coordinate retained exactly at its published precision; not independently resurveyed. Current geographic contexts must be derived from protected polygons, not the historical source district label.","regionId":"punjab","districtId":"punjab-murree","regionIds":["punjab"],"districtIds":["punjab-murree"],"spatialMatches":[{"regionId":"punjab","districtId":"punjab-murree"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,"sortOrder":7373,"detailsPageStatus":"future","researchNote":"Explicitly distinguish abandoned Murree-hills complex from operating Rawalpindi brewery.","provinceRegionIds":["punjab"],"districtIds":["punjab-murree"],"spatialAssignment":{"method":"point-in-polygon","geometryDataset":"Virsapur authoritative ADM2 runtime geometry","reviewedAt":"2026-10-22"}}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6825','turab-baoli','published','{"id":"major-doam-6825","mapDisplay":"featured","slug":"turab-baoli","status":"published","title":"Turab Baoli","shortTitle":"Turab Baoli","summary":"A stepped well associated with a caravanserai, built in small bricks and lime mortar. Pointed arches and surviving entrance structures record the site’s role in historic travel and water supply.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Monument","designationType":"none","designationName":"Major heritage site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6825","verifiedDate":"2026-10-17","sourceTitle":"Turab Baoli","sourceRegion":"Punjab","sourceDistrict":"Chakwal","sourcePublication":"Survey and Documentation of Archaeological Sites and Monuments in Tehsil Talagang, District Chakwal, Punjab, Pakistan: An Analytical and Comparative Study","selectionReason":"Documented transport-water heritage in newly configured Talagang.","components":[{"id":"major-doam-6825-point","name":"Turab Baoli","latitude":33.056488026,"longitude":71.935722475,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6825","coordinateNote":"Official catalogue site coordinate retained exactly at its published precision; not independently resurveyed. Current geographic contexts must be derived from protected polygons, not the historical source district label.","regionId":"punjab","districtId":"punjab-talagang","regionIds":["punjab"],"districtIds":["punjab-talagang"],"spatialMatches":[{"regionId":"punjab","districtId":"punjab-talagang"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage