insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-10106','wazirabad-dak-chowki','published','{"id":"major-doam-10106","mapDisplay":"featured","slug":"wazirabad-dak-chowki","status":"published","title":"Wazirabad Dak Chowki","shortTitle":"Wazirabad Dak Chowki","summary":"The remains of a historic mail station beside the Grand Trunk Road corridor. Arched openings and surviving brick turrets preserve a building associated with communication and travel.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Monument","designationType":"none","designationName":"Major heritage site","legalStatus":"Protected by The Punjab Special Premises (Preservation), Ordinance, 1985","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/10106","verifiedDate":"2026-10-17","sourceTitle":"Dak Chowki of Sher Shah Suris period","sourceRegion":"Punjab","sourceDistrict":"Gujranwala","sourcePublication":"Asian Historical Architecture","selectionReason":"Rare postal infrastructure in newly configured Wazirabad; source’s contradictory 1560s attribution omitted.","components":[{"id":"major-doam-10106-point","name":"Wazirabad Dak Chowki","latitude":32.442951,"longitude":74.11097,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/10106","coordinateNote":"Official catalogue site coordinate retained exactly at its published precision; not independently resurveyed. Current geographic contexts must be derived from protected polygons, not the historical source district label.","regionId":"punjab","districtId":"punjab-wazirabad","regionIds":["punjab"],"districtIds":["punjab-wazirabad"],"spatialMatches":[{"regionId":"punjab","districtId":"punjab-wazirabad"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,"sortOrder":11106,"detailsPageStatus":"future","researchNote":"Catalogue says 1560s during Sher Shah Suri; contradiction excluded from public summary.","provinceRegionIds":["punjab"],"districtIds":["punjab-wazirabad"],"spatialAssignment":{"method":"point-in-polygon","geometryDataset":"Virsapur authoritative ADM2 runtime geometry","reviewedAt":"2026-10-22"}}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-4915','old-city-of-badin','published','{"id":"major-doam-4915","mapDisplay":"featured","slug":"old-city-of-badin","status":"published","title":"Old City of Badin","shortTitle":"Old City of Badin","summary":"The remains of old Badin preserve traces of a historic town now interwoven with later buildings. The archaeological site records the changing urban landscape of lower Sindh.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/4915","verifiedDate":"2026-10-17","sourceTitle":"Ruins of the Old City of Badin","sourceRegion":"Sindh","sourceDistrict":"Badin","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Representative historic settlement in an initially unrepresented southern district.","components":[{"id":"major-doam-4915-point","name":"Old City of Badin","latitude":24.646661111,"longitude":68.836072222,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/4915","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-badin","regionIds":["sindh"],"districtIds":["sindh-badin"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-badin"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,"sortOrder":20