insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-9983','roopa-mari','published','{"id":"major-doam-9983","mapDisplay":"featured","slug":"roopa-mari","status":"published","title":"Roopa Mari","shortTitle":"Roopa Mari","summary":"Roopa Mari is a ruined settlement mound with brick debris and traces of a mosque. Nearby memorials connect the landscape with local traditions about Dodo and Chanesar; those traditions are distinct from the surviving archaeological evidence.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/9983","verifiedDate":"2026-10-17","sourceTitle":"Roopa Mari","sourceRegion":"Sindh","sourceDistrict":"Badin","sourcePublication":"Documentation of the Heritage Sites and Monuments of Sindh","selectionReason":"Adds lower-Sindh settlement archaeology without presenting legendary attribution as established history.","components":[{"id":"major-doam-9983-point","name":"Roopa Mari","latitude":24.35916,"longitude":68.84558,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/9983","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-badin","regionIds":["sindh"],"districtIds":["sindh-badin"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-badin"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,"sortOrder":2001,"detailsPageStatus":"available","provinceRegionIds":["sindh"],"districtIds":["sindh-badin"],"spatialAssignment":{"method":"point-in-polygon","geometryDataset":"Virsapur authoritative ADM2 runtime geometry","reviewedAt":"2026-10-22"}}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-4957','khudabad-jamia-mosque','published','{"id":"major-doam-4957","mapDisplay":"featured","slug":"khudabad-jamia-mosque","status":"published","title":"Khudabad Jamia Mosque","shortTitle":"Khudabad Jamia Mosque","summary":"The monumental mosque at old Khudabad is a major surviving work of Kalhora architecture. Its entrance and prayer halls preserve elaborate Sindhi tile decoration and substantial brick construction.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/4957","verifiedDate":"2026-10-17","sourceTitle":"Jamia Mosque Khudabad","sourceRegion":"Sindh","sourceDistrict":"Dadu","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Major architectural monument in the historic Kalhora capital landscape.","components":[{"id":"major-doam-4957-point","name":"Khudabad Jamia Mosque","latitude":26.646869444,"longitude":67.739716667,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/4957","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-dadu","regionIds":["sindh"],"districtIds":["sindh-dadu"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-dadu"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,