insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-10380','tomb-of-mian-yar-muhammad-kalhoro','published','{"id":"major-doam-10380","mapDisplay":"featured","slug":"tomb-of-mian-yar-muhammad-kalhoro","status":"published","title":"Tomb of Mian Yar Muhammad Kalhoro","shortTitle":"Tomb of Mian Yar Muhammad Kalhoro","summary":"This domed mausoleum at Khudabad commemorates Mian Yar Muhammad Kalhoro. Its raised platform, tiled facade and gallery beneath the dome illustrate the ambition of early Kalhora funerary architecture.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Tomb / Funerary Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/10380","verifiedDate":"2026-10-17","sourceTitle":"Mian Yar Muhammad Kalhoro Tomb","sourceRegion":"Sindh","sourceDistrict":"Dadu","sourcePublication":"Miscellaneous","selectionReason":"Important dynastic monument; disputed precise builder is deliberately not asserted.","components":[{"id":"major-doam-10380-point","name":"Tomb of Mian Yar Muhammad Kalhoro","latitude":26.645513889,"longitude":67.714436111,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/10380","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-dadu","regionIds":["sindh"],"districtIds":["sindh-dadu"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-dadu"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,"so