insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6039','mazar-e-quaid','published','{"id":"major-doam-6039","mapDisplay":"featured","slug":"mazar-e-quaid","status":"published","title":"Mazar-e-Quaid","shortTitle":"Mazar-e-Quaid","summary":"The white-marble mausoleum of Muhammad Ali Jinnah is a national memorial in Karachi. Its monumental arches, raised platform and domed composition distinguish it from the city’s older colonial buildings.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Monument","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Protected by Quaid-i-Azam`s Mazar (Protection and Maintenance) Ordinance, 1971","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6039","verifiedDate":"2026-10-17","sourceTitle":"Mazar-e-Quaid-e-Azam","sourceRegion":"Sindh","sourceDistrict":"Karachi","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Nationally significant twentieth-century memorial and distinct East Karachi coverage.","components":[{"id":"major-doam-6039-point","name":"Mazar-e-Quaid","latitude":24.874736111,"longitude":67.039841667,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6039","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-east-karachi","regionIds":["sindh"],"districtIds":["sindh-east-karachi"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-east-karachi"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemp