insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6591','vijnot-jo-daro','published','{"id":"major-doam-6591","mapDisplay":"featured","slug":"vijnot-jo-daro","status":"published","title":"Vijnot Jo Daro","shortTitle":"Vijnot Jo Daro","summary":"Vijnot Jo Daro is an extensive archaeological mound complex in the Deharki area. Pottery, brick fragments and charcoal documented in the official survey preserve evidence of an earlier settlement whose chronology remains cautiously attributed.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6591","verifiedDate":"2026-10-17","sourceTitle":"Vijnot Jo Daro","sourceRegion":"Sindh","sourceDistrict":"Ghotki","sourcePublication":"Survey and Documentation of Archaeological Sites and Monuments (1995-2001)","selectionReason":"Representative upper-Sindh archaeological landscape; avoids turning tentative dating into certainty.","components":[{"id":"major-doam-6591-point","name":"Vijnot Jo Daro","latitude":28.036388889,"longitude":69.844444444,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6591","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-ghotki","regionIds":["sindh"],"districtIds":["sindh-ghotki"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-ghotki"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":