insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5700','mukhi-mahal','published','{"id":"major-doam-5700","mapDisplay":"featured","slug":"mukhi-mahal","status":"published","title":"Mukhi Mahal","shortTitle":"Mukhi Mahal","summary":"Mukhi Mahal is a substantial early-twentieth-century stone residence in Hyderabad. Its two-storey composition and central domed feature preserve an important example of the city’s historic domestic architecture.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Urban Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5700","verifiedDate":"2026-10-17","sourceTitle":"Mukhi Mahal, Fort Incline","sourceRegion":"Sindh","sourceDistrict":"Hyderabad","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Adds urban domestic architecture to Hyderabad rather than another generic mound.","components":[{"id":"major-doam-5700-point","name":"Mukhi Mahal","latitude":25.386327778,"longitude":68.370819444,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5700","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-hyderabad","regionIds":["sindh"],"districtIds":["sindh-hyderabad"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-hyderabad"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,"sortOrder":2007,"detailsPageStatus":"available","provinceRegionIds":["sindh"],"districtIds":["sindh-hyderabad"],"spatialAssignment":{"method":"point-in-polygon","geometryDataset":"Virsapur authoritative ADM2 runtime geometry","reviewedAt":"2026-10-22"}}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5712','pucca-qila-fortifications','published','{"id":"major-doam-5712","mapDisplay":"featured","slug":"pucca-qila-fortifications","status":"published","title":"Pucca Qila Fortifications","shortTitle":"Pucca Qila Fortifications","summary":"The surviving walls of Hyderabad’s Pucca Qila retain distinctive ornamental battlements. They form part of the city’s Kalhora and Talpur-period fortified landscape.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Fortification","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5712","verifiedDate":"2026-10-17","sourceTitle":"Pucca Fort Boundary Wall","sourceRegion":"Sindh","sourceDistrict":"Hyderabad","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Representative city fortification, grouped as one place rather than separate gate and wall pins.","components":[{"id":"major-doam-5712-point","name":"Pucca Qila Fortifications","latitude":25.386316667,"longitude":68.373555556,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5712","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-hyderabad","regionIds":["sindh"],"districtIds":["sindh-hyderabad"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-hyderabad"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"image