insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5659','tomb-of-ghulam-shah-kalhoro','published','{"id":"major-doam-5659","mapDisplay":"featured","slug":"tomb-of-ghulam-shah-kalhoro","status":"published","title":"Tomb of Ghulam Shah Kalhoro","shortTitle":"Tomb of Ghulam Shah Kalhoro","summary":"This Hyderabad mausoleum commemorates Ghulam Shah Kalhoro. Built on a raised platform, its brick structure combines a large dome and corner minarets with painted and tiled decoration.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Tomb / Funerary Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5659","verifiedDate":"2026-10-17","sourceTitle":"Tomb of Ghulam Shah Kalhoro","sourceRegion":"Sindh","sourceDistrict":"Hyderabad","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Major dynastic funerary monument with documented architectural fabric.","components":[{"id":"major-doam-5659-point","name":"Tomb of Ghulam Shah Kalhoro","latitude":25.414144444,"longitude":68.362908333,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5659","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-hyderabad","regionIds":["sindh"],"districtIds":["sindh-hyderabad"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-hyderabad"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderI