insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-4365','victoria-clock-tower-jacobabad','published','{"id":"major-doam-4365","mapDisplay":"featured","slug":"victoria-clock-tower-jacobabad","status":"published","title":"Victoria Clock Tower, Jacobabad","shortTitle":"Victoria Clock Tower, Jacobabad","summary":"Jacobabad’s Victoria Clock Tower is a colonial-period civic landmark constructed in brick and lime. Its arched rooms and internal stair express the layered design of a public clock-tower building.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Urban Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/4365","verifiedDate":"2026-10-17","sourceTitle":"Victoria Clock Tower","sourceRegion":"Sindh","sourceDistrict":"Jacobabad","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Representative civic architecture in a previously unrepresented district; avoids disputed attribution.","components":[{"id":"major-doam-4365-point","name":"Victoria Clock Tower, Jacobabad","latitude":28.284069444,"longitude":68.437833333,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/4365","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-jacobabad","regionIds":["sindh"],"districtIds":["sindh-jacobabad"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-jacobabad"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","