insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-4362','grave-of-john-jacob','published','{"id":"major-doam-4362","mapDisplay":"featured","slug":"grave-of-john-jacob","status":"published","title":"Grave of John Jacob","shortTitle":"Grave of John Jacob","summary":"The marble grave of John Jacob survives within a walled burial enclosure in Jacobabad. It is a material reminder of the city’s colonial-era history.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Tomb / Funerary Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/4362","verifiedDate":"2026-10-17","sourceTitle":"Grave of John Jacob","sourceRegion":"Sindh","sourceDistrict":"Jacobabad","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Historically named memorial complements the district’s civic tower without duplicating it.","components":[{"id":"major-doam-4362-point","name":"Grave of John Jacob","latitude":28.286825,"longitude":68.428894444,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/4362","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-jacobabad","regionIds":["sindh"],"districtIds":["sindh-jacobabad"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-jacobabad"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,"sortOrder":2011,"detailsPageStatus":"available","province