insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5179','shrine-of-lal-shahbaz-qalandar','published','{"id":"major-doam-5179","mapDisplay":"featured","slug":"shrine-of-lal-shahbaz-qalandar","status":"published","title":"Shrine of Lal Shahbaz Qalandar","shortTitle":"Shrine of Lal Shahbaz Qalandar","summary":"The shrine of Lal Shahbaz Qalandar is a major sacred monument in Sehwan. Its mausoleum anchors a historic urban religious precinct whose fabric has developed through successive periods.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5179","verifiedDate":"2026-10-17","sourceTitle":"Shrine of Lal Shahbaz Qalandar","sourceRegion":"Sindh","sourceDistrict":"Jamshoro","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Nationally significant built sacred heritage, not a separate intangible-practice record.","components":[{"id":"major-doam-5179-point","name":"Shrine of Lal Shahbaz Qalandar","latitude":26.428363889,"longitude":67.862277778,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5179","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-jamshoro","regionIds":["sindh"],"districtIds":["sindh-jamshoro"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-jamshoro"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageT