insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5180','sehwan-fort','published','{"id":"major-doam-5180","mapDisplay":"featured","slug":"sehwan-fort","status":"published","title":"Sehwan Fort","shortTitle":"Sehwan Fort","summary":"The raised remains of Sehwan Fort preserve masonry from successive building phases. Pottery and brick fragments across the mound document the long occupation of this fortified site.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Fortification","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5180","verifiedDate":"2026-10-17","sourceTitle":"Fort at Sehwan","sourceRegion":"Sindh","sourceDistrict":"Jamshoro","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Adds archaeological fortification distinct from the existing Ranikot record and shrine.","components":[{"id":"major-doam-5180-point","name":"Sehwan Fort","latitude":26.433255556,"longitude":67.86125,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5180","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-jamshoro","regionIds":["sindh"],"districtIds":["sindh-jamshoro"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-jamshoro"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,"sortOrder":2013,"detailsPageStatus":"availabl