insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-10062','ghaibi-khan-chandio-graveyard','published','{"id":"major-doam-10062","mapDisplay":"featured","slug":"ghaibi-khan-chandio-graveyard","status":"published","title":"Ghaibi Khan Chandio Graveyard","shortTitle":"Ghaibi Khan Chandio Graveyard","summary":"The necropolis near Ghaibi Dero contains a substantial group of tombs associated with Ghaibi Khan Chandio and later burials. Its surviving and ruined structures document a long funerary tradition in western Sindh.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Tomb / Funerary Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/10062","verifiedDate":"2026-10-17","sourceTitle":"Ghaibi Khan Husnani Chandio Graveyard (Rankoon)","sourceRegion":"Sindh","sourceDistrict":"Qambar Shahdadkot","sourcePublication":"Documentation of the Heritage Sites and Monuments of Sindh","selectionReason":"Representative necropolis in underrepresented Kambar Shahdad Kot, kept as a single place rather than individual tomb records.","components":[{"id":"major-doam-10062-point","name":"Ghaibi Khan Chandio Graveyard","latitude":27.629772,"longitude":67.617099,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/10062","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-kambar-shahdad-kot","regionIds":["sindh"],"districtIds":["sindh-kambar-shahdad-kot"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-kambar-shahdad-kot"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,"sortOrder":2014,"detailsPageStatus":"available","provinceRegionIds":["sindh"],"districtIds":["sindh-kambar-shahdad-kot"],"spatialAssignment":{"method":"point-in-polygon","geometryDataset":"Virsapur authoritative ADM2 runtime geometry","reviewedAt":"2026-10-22"}}'::jsonb) on conflict(collection,id) do nothing;
insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-9528','thul-of-dribh-chandio','published','{"id":"major-doam-9528","mapDisplay":"featured","slug":"thul-of-dribh-chandio","status":"published","title":"Thul of Dribh Chandio","shortTitle":"Thul of Dribh Chandio","summary":"The Thul of Dribh Chandio is a historic tower in the Miro Khan area. The official archaeological inventory associates it with the Talpur-period landscape of Sindh.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Monument","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/9528","verifiedDate":"2026-10-17","sourceTitle":"Thul of Dribh Chandio","sourceRegion":"Sindh","sourceDistrict":"Qambar Shahdadkot","sourcePublication":"Archaeological Sites and Monuments of Larkana and Qambar Shahdad Kot Districts","selectionReason":"Distinct tower type broadens representation beyond the selected necropolis.","components":[{"id":"major-doam-9528-point","name":"Thul of Dribh Chandio","latitude":27.7,"longitude":68.086111111,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/9528","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-kambar-shahdad-kot","regionIds":["sindh"],"districtIds":["sindh-kambar-shahdad-kot"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-kambar-shahdad-kot"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,"sortOrder":2015