insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6852','thul-of-jamro','published','{"id":"major-doam-6852","mapDisplay":"featured","slug":"thul-of-jamro","status":"published","title":"Thul of Jamro","shortTitle":"Thul of Jamro","summary":"This ruined tower near Kashmore retains brick construction and traces of a staircase. The official survey records it as a Talpur-period structure.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Monument","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6852","verifiedDate":"2026-10-17","sourceTitle":"Thul of Jamro","sourceRegion":"Sindh","sourceDistrict":"Jacobabad","sourcePublication":"Survey and Documentation of Archaeological Sites and Monuments (1995-2001)","selectionReason":"Representative Kashmore monument; legacy Jacobabad source label is retained only as provenance.","components":[{"id":"major-doam-6852-point","name":"Thul of Jamro","latitude":28.444444444,"longitude":69.577777778,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6852","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-kashmore","regionIds":["sindh"],"districtIds":["sindh-kashmore"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-kashmore"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,"sortOrder":2016,"detailsPageStatus":"available","provinceRegionIds":["sindh"],"districtIds":["