insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5185','shrine-of-sachal-sarmast','published','{"id":"major-doam-5185","mapDisplay":"featured","slug":"shrine-of-sachal-sarmast","status":"published","title":"Shrine of Sachal Sarmast","shortTitle":"Shrine of Sachal Sarmast","summary":"The mausoleum of Sachal Sarmast is a brick-built shrine in Khairpur district. Its corner minarets and enclosed burial chamber form a distinctive monument associated with the poet-saint.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5185","verifiedDate":"2026-10-17","sourceTitle":"Shrine of Hazrat Sachal Sarmast","sourceRegion":"Sindh","sourceDistrict":"Khairpur","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Major built sacred monument separate from Kot Diji’s fortification.","components":[{"id":"major-doam-5185-point","name":"Shrine of Sachal Sarmast","latitude":27.305583333,"longitude":68.512752778,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5185","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-khairpur","regionIds":["sindh"],"districtIds":["sindh-khairpur"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-khairpur"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,"sortOrder":2017,