insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-4869','tomb-of-shah-baharo','published','{"id":"major-doam-4869","mapDisplay":"featured","slug":"tomb-of-shah-baharo","status":"published","title":"Tomb of Shah Baharo","shortTitle":"Tomb of Shah Baharo","summary":"Shah Baharo’s mausoleum is a prominent Kalhora-period funerary monument in Larkana. Its raised octagonal form, domed roof and tiled decoration distinguish the brick structure.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Tomb / Funerary Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/4869","verifiedDate":"2026-10-17","sourceTitle":"Tomb of Shah Baharo","sourceRegion":"Sindh","sourceDistrict":"Larkana","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Adds Larkana’s historic architecture beyond the existing Moenjodaro property.","components":[{"id":"major-doam-4869-point","name":"Tomb of Shah Baharo","latitude":27.558719444,"longitude":68.223663889,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/4869","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-larkana","regionIds":["sindh"],"districtIds":["sindh-larkana"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-larkana"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,"sortO