insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6011','lakho-shaikh-graveyard','published','{"id":"major-doam-6011","mapDisplay":"featured","slug":"lakho-shaikh-graveyard","status":"published","title":"Lakho Shaikh Graveyard","shortTitle":"Lakho Shaikh Graveyard","summary":"The Lakho Shaikh burial ground preserves historic tombs associated with Baloch communities near Karachi. Its carved funerary tradition belongs to a wider group of monuments across southern Sindh and neighbouring Balochistan.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Tomb / Funerary Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6011","verifiedDate":"2026-10-17","sourceTitle":"Lakho Shaikh (Baloch Graveyard)","sourceRegion":"Sindh","sourceDistrict":"Karachi","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Distinct necropolis from Chaukhandi; the separate catalogue tomb entry is not added again.","components":[{"id":"major-doam-6011-point","name":"Lakho Shaikh Graveyard","latitude":24.946575,"longitude":67.250358333,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6011","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-malir-karachi","regionIds":["sindh"],"districtIds":["sindh-malir-karachi"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-malir-karachi"}],"assignmentStatus":"spatially-deri