insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-4892','hala-monuments','published','{"id":"major-doam-4892","mapDisplay":"featured","slug":"hala-monuments","status":"published","title":"Hala Monuments","shortTitle":"Hala Monuments","summary":"This historic burial ground near Hala includes carved graves, a tomb and a mosque. The official inventory associates the ensemble with the early nineteenth century.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Tomb / Funerary Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/4892","verifiedDate":"2026-10-17","sourceTitle":"Hala Monuments","sourceRegion":"Sindh","sourceDistrict":"Matiari","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Grouped funerary ensemble broadens Matiari’s built heritage beyond the existing Bhittai shrine.","components":[{"id":"major-doam-4892-point","name":"Hala Monuments","latitude":25.83005,"longitude":68.400752778,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/4892","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-matiari","regionIds":["sindh"],"districtIds":["sindh-matiari"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-matiari"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,"sortOrder":2021,"detailsPageStat