insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5231','chottori-tombs','published','{"id":"major-doam-5231","mapDisplay":"featured","slug":"chottori-tombs","status":"published","title":"Chottori Tombs","shortTitle":"Chottori Tombs","summary":"The Chottori cemetery contains tombs of Talpur figures associated with the Kalhora period. Its ensemble of burial monuments and a mosque records the region’s dynastic and funerary history.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Tomb / Funerary Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5231","verifiedDate":"2026-10-17","sourceTitle":"Chottori Tombs","sourceRegion":"Sindh","sourceDistrict":"Mirpur Khas","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Major Mirpur Khas ensemble; constituent Talpur tombs are not ingested as separate places.","components":[{"id":"major-doam-5231-point","name":"Chottori Tombs","latitude":25.657175,"longitude":69.076352778,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5231","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-mirpur-khas","regionIds":["sindh"],"districtIds":["sindh-mirpur-khas"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-mirpur-khas"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":fals