insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6870','kot-sirini','published','{"id":"major-doam-6870","mapDisplay":"featured","slug":"kot-sirini","status":"published","title":"Kot Sirini","shortTitle":"Kot Sirini","summary":"Kot Sirini is a rectangular historic fort in the Moro area with corner watchtowers. The official survey describes Talpur-period fortifications and later occupation inside its courtyard.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Fortification","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6870","verifiedDate":"2026-10-17","sourceTitle":"Kot Sirini","sourceRegion":"Sindh","sourceDistrict":"Naushahro Feroze","sourcePublication":"Survey and Documentation of Archaeological Sites and Monuments (1995-2001)","selectionReason":"Representative fortification in a previously unrepresented district; uncertain antiquities chronology is omitted.","components":[{"id":"major-doam-6870-point","name":"Kot Sirini","latitude":26.75,"longitude":68.036388889,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6870","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-naushahro-feroze","regionIds":["sindh"],"districtIds":["sindh-naushahro-feroze"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-naushahro-feroze"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,"sortOrder":2023,"detailsPageStatus"