insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6950','baba-saroop-daas-temple','published','{"id":"major-doam-6950","mapDisplay":"featured","slug":"baba-saroop-daas-temple","status":"published","title":"Baba Saroop Daas Temple","shortTitle":"Baba Saroop Daas Temple","summary":"The temple of Baba Saroop Daas at Halani is a multi-storey brick complex with a domed feature and an enclosing wall. It is a surviving example of Sindh’s Hindu sacred architecture.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6950","verifiedDate":"2026-10-17","sourceTitle":"Temple Baba Saroop Daas","sourceRegion":"Sindh","sourceDistrict":"Naushahro Feroze","sourcePublication":"Survey and Documentation of Archaeological Sites and Monuments (1995-2001)","selectionReason":"Adds architectural and religious diversity to Naushahro Feroze.","components":[{"id":"major-doam-6950-point","name":"Baba Saroop Daas Temple","latitude":27.090555556,"longitude":68.322777778,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6950","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-naushahro-feroze","regionIds":["sindh"],"districtIds":["sindh-naushahro-feroze"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-naushahro-feroze"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,"sor