insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5267','brahmanabad-mansurah','published','{"id":"major-doam-5267","mapDisplay":"featured","slug":"brahmanabad-mansurah","status":"published","title":"Brahmanabad–Mansurah","shortTitle":"Brahmanabad–Mansurah","summary":"The extensive remains of Mansurah preserve a fortified early Islamic city in Sindh. Archaeological structures include a major mosque and substantial stretches of the former defences.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5267","verifiedDate":"2026-10-17","sourceTitle":"Brahmanabad (Mansurah)","sourceRegion":"Sindh","sourceDistrict":"Sanghar","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Nationally significant urban archaeology, selected instead of nearby constituent mound records.","components":[{"id":"major-doam-5267-point","name":"Brahmanabad–Mansurah","latitude":25.880527778,"longitude":68.775997222,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5267","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-sanghar","regionIds":["sindh"],"districtIds":["sindh-sanghar"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-sanghar"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":f