insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6464','chanhudaro','published','{"id":"major-doam-6464","mapDisplay":"featured","slug":"chanhudaro","status":"published","title":"Chanhudaro","shortTitle":"Chanhudaro","summary":"Chanhudaro is an Indus-period settlement whose excavations revealed brick houses, drainage and varied craft objects. Its surviving mounds are an important archaeological record of settlement and production in Sindh.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6464","verifiedDate":"2026-10-17","sourceTitle":"Chanhu Jo Daro","sourceRegion":"Sindh","sourceDistrict":"Shaheed Benazirabad","sourcePublication":"Nawab Shah: The Lost Glory","selectionReason":"Nationally significant Indus archaeology beyond Moenjodaro.","components":[{"id":"major-doam-6464-point","name":"Chanhudaro","latitude":26.170833333,"longitude":68.330555556,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6464","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-shaheed-benazir-abad","regionIds":["sindh"],"districtIds":["sindh-shaheed-benazir-abad"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-shaheed-benazir-abad"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,"sortOrder":2026,"detailsPageStatus":"available","provinceRegionIds":["sindh