insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5094','thul-mir-rukan','published','{"id":"major-doam-5094","mapDisplay":"featured","slug":"thul-mir-rukan","status":"published","title":"Thul Mir Rukan","shortTitle":"Thul Mir Rukan","summary":"Thul Mir Rukan is a tall cylindrical brick monument rising from a square base. Often interpreted as a Buddhist stupa, its precise early history remains uncertain.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5094","verifiedDate":"2026-10-17","sourceTitle":"Thulh Mir Rukan","sourceRegion":"Sindh","sourceDistrict":"Shaheed Benazirabad","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Distinct monument type in Shaheed Benazir Abad; retains uncertainty rather than adopting legendary history.","components":[{"id":"major-doam-5094-point","name":"Thul Mir Rukan","latitude":26.454569444,"longitude":68.106627778,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5094","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-shaheed-benazir-abad","regionIds":["sindh"],"districtIds":["sindh-shaheed-benazir-abad"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-shaheed-benazir-abad"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,"sortOrder":202