insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5095','tomb-of-mian-noor-muhammad-kalhoro','published','{"id":"major-doam-5095","mapDisplay":"featured","slug":"tomb-of-mian-noor-muhammad-kalhoro","status":"published","title":"Tomb of Mian Noor Muhammad Kalhoro","shortTitle":"Tomb of Mian Noor Muhammad Kalhoro","summary":"This Kalhora mausoleum stands on a raised platform within an enclosure. Its tiled facade, corner kiosks and domed chamber preserve elaborate geometric and floral decoration.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Tomb / Funerary Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5095","verifiedDate":"2026-10-17","sourceTitle":"Tomb of Mian Noor Mohammad Kalhoro","sourceRegion":"Sindh","sourceDistrict":"Shaheed Benazirabad","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Major dynastic monument complementary to the district’s Indus and Buddhist archaeology.","components":[{"id":"major-doam-5095-point","name":"Tomb of Mian Noor Muhammad Kalhoro","latitude":26.550033333,"longitude":68.064325,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5095","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-shaheed-benazir-abad","regionIds":["sindh"],"districtIds":["sindh-shaheed-benazir-abad"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-shaheed-benazir-abad"}],"assignmentStatus":"spatially-deriv