insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5426','dargah-haji-faqirullah-shah-alvi','published','{"id":"major-doam-5426","mapDisplay":"featured","slug":"dargah-haji-faqirullah-shah-alvi","status":"published","title":"Dargah Haji Faqirullah Shah Alvi","shortTitle":"Dargah Haji Faqirullah Shah Alvi","summary":"This Shikarpur shrine combines brick and stone masonry with a domed roof and wooden gateway. The official inventory dates the present shrine building to the early twentieth century.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5426","verifiedDate":"2026-10-17","sourceTitle":"Dargah Haji Faqirullah Shah Alvi","sourceRegion":"Sindh","sourceDistrict":"Shikarpur","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Distinct sacred architecture complements Shikarpur’s civic landmark.","components":[{"id":"major-doam-5426-point","name":"Dargah Haji Faqirullah Shah Alvi","latitude":27.954322222,"longitude":68.637536111,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5426","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-shikarpur","regionIds":["sindh"],"districtIds":["sindh-shikarpur"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-shikarpur"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary