insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5858','frere-hall','published','{"id":"major-doam-5858","mapDisplay":"featured","slug":"frere-hall","status":"published","title":"Frere Hall","shortTitle":"Frere Hall","summary":"Frere Hall is a landmark of nineteenth-century Karachi, distinguished by Gothic forms and yellow limestone. Its towers, arcades and upper hall express the city’s colonial civic architecture.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Urban Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5858","verifiedDate":"2026-10-17","sourceTitle":"Frere Hall","sourceRegion":"Sindh","sourceDistrict":"Karachi","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Nationally recognisable civic landmark, selectively representing Karachi’s large built-heritage inventory.","components":[{"id":"major-doam-5858-point","name":"Frere Hall","latitude":24.847463889,"longitude":67.032877778,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5858","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-south-karachi","regionIds":["sindh"],"districtIds":["sindh-south-karachi"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-south-karachi"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false