insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5846','empress-market','published','{"id":"major-doam-5846","mapDisplay":"featured","slug":"empress-market","status":"published","title":"Empress Market","shortTitle":"Empress Market","summary":"Empress Market is a late-nineteenth-century public market in Karachi. Its purpose-built galleries preserve the architectural setting of a major commercial landmark.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Urban Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5846","verifiedDate":"2026-10-17","sourceTitle":"Empress Market","sourceRegion":"Sindh","sourceDistrict":"Karachi","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Material commercial heritage complements civic and sacred records.","components":[{"id":"major-doam-5846-point","name":"Empress Market","latitude":24.862422222,"longitude":67.029341667,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5846","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-south-karachi","regionIds":["sindh"],"districtIds":["sindh-south-karachi"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-south-karachi"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,"sortOrder":2032,"detailsPageStatus":"available","provinceRegionIds":["sindh"],"dist