insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6234','sindh-madrassatul-islam','published','{"id":"major-doam-6234","mapDisplay":"featured","slug":"sindh-madrassatul-islam","status":"published","title":"Sindh Madrassatul Islam","shortTitle":"Sindh Madrassatul Islam","summary":"Established in 1885 by Hassan Ali Effendi, Sindh Madrassatul Islam is an important historic educational institution in Karachi. Muhammad Ali Jinnah studied here, giving the campus a particular place in Pakistan’s national history.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Urban Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6234","verifiedDate":"2026-10-17","sourceTitle":"Sindh Madrassatul Islam","sourceRegion":"Sindh","sourceDistrict":"Karachi","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"National educational heritage, distinct from the existing Mohatta Palace record.","components":[{"id":"major-doam-6234-point","name":"Sindh Madrassatul Islam","latitude":24.851080556,"longitude":67.004052778,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6234","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-south-karachi","regionIds":["sindh"],"districtIds":["sindh-south-karachi"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-south-karachi"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderIm