insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-7187','manjeera-raja-mound','published','{"id":"major-doam-7187","mapDisplay":"featured","slug":"manjeera-raja-mound","status":"published","title":"Manjeera Raja Mound","shortTitle":"Manjeera Raja Mound","summary":"The Manjeera Raja archaeological mound retains a well and traces of earlier occupation near Sheikh Ismail village. An official catalogue based on university research associates the site with Sindh’s Buddhist-period archaeology.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/7187","verifiedDate":"2026-10-17","sourceTitle":"Mound of Manjeera Raja","sourceRegion":"Sindh","sourceDistrict":"Thatta","sourcePublication":"Early History of Sindh with special reference to Buddhism","selectionReason":"Representative archaeological evidence in the configured Sujawal district; legacy Thatta label is research metadata only.","components":[{"id":"major-doam-7187-point","name":"Manjeera Raja Mound","latitude":24.954167083,"longitude":68.231904389,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/7187","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-sujawal","regionIds":["sindh"],"districtIds":["sindh-sujawal"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-sujawal"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemp