insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5135','mir-masums-minaret-and-tomb','published','{"id":"major-doam-5135","mapDisplay":"featured","slug":"mir-masums-minaret-and-tomb","status":"published","title":"Mir Masum’s Minaret and Tomb","shortTitle":"Mir Masum’s Minaret and Tomb","summary":"Mir Masum’s tall brick minaret and family tombs form a major Mughal-period monument in Sukkur. The complex combines an internal staircase, domed summit and inscribed funerary canopies.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Monument","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5135","verifiedDate":"2026-10-17","sourceTitle":"Mir Masum`s Minar and Tomb","sourceRegion":"Sindh","sourceDistrict":"Sukkur","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Major nationally recognisable architectural ensemble in a previously unrepresented district.","components":[{"id":"major-doam-5135-point","name":"Mir Masum’s Minaret and Tomb","latitude":27.694630556,"longitude":68.866563889,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5135","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-sukkur","regionIds":["sindh"],"districtIds":["sindh-sukkur"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-sukkur"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeh