insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5119','lansdowne-bridge','published','{"id":"major-doam-5119","mapDisplay":"featured","slug":"lansdowne-bridge","status":"published","title":"Lansdowne Bridge","shortTitle":"Lansdowne Bridge","summary":"The historic Lansdowne Bridge spans part of the Indus crossing at Sukkur and Rohri. Its monumental structure represents the expansion of transport engineering during the colonial period.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Monument","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5119","verifiedDate":"2026-10-17","sourceTitle":"Lansdown Bridge","sourceRegion":"Sindh","sourceDistrict":"Sukkur","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Adds important industrial and transport heritage without introducing a one-off category.","components":[{"id":"major-doam-5119-point","name":"Lansdowne Bridge","latitude":27.692238889,"longitude":68.888041667,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5119","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-sukkur","regionIds":["sindh"],"districtIds":["sindh-sukkur"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-sukkur"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,"sortOrder":2036,"detailsPageStatus":"available","provinc