insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5139','bilawal-mari-ruins','published','{"id":"major-doam-5139","mapDisplay":"featured","slug":"bilawal-mari-ruins","status":"published","title":"Bilawal Mari Ruins","shortTitle":"Bilawal Mari Ruins","summary":"The ruins at Bilawal Mari include traces of a mosque, a well and other historic structures. The official inventory records the site as part of the Talpur-period landscape near Jhando Mari.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5139","verifiedDate":"2026-10-17","sourceTitle":"Ruins Bilawal Mari at Jhando Mari","sourceRegion":"Sindh","sourceDistrict":"Tando Allah Yar","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Representative tangible archaeology in Tando Allahyar, without importing a broad town coordinate.","components":[{"id":"major-doam-5139-point","name":"Bilawal Mari Ruins","latitude":25.682705556,"longitude":68.877772222,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5139","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-tando-allahyar","regionIds":["sindh"],"districtIds":["sindh-tando-allahyar"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-tando-allahyar"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,