insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-10373','shiv-temple-umerkot','published','{"id":"major-doam-10373","mapDisplay":"featured","slug":"shiv-temple-umerkot","status":"published","title":"Shiv Temple, Umerkot","shortTitle":"Shiv Temple, Umerkot","summary":"The Shiv temple near Umerkot is an active Hindu sacred complex centred on a Shiva lingam. Its courtyards and temple buildings reflect repeated repair and expansion rather than a securely established single ancient construction date.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/10373","verifiedDate":"2026-10-17","sourceTitle":"Shiv Temple Umerkot","sourceRegion":"Sindh","sourceDistrict":"Umerkot","sourcePublication":"Miscellaneous","selectionReason":"Major built Hindu shrine; excludes unsupported claims of a 5,000-year-old structure.","components":[{"id":"major-doam-10373-point","name":"Shiv Temple, Umerkot","latitude":25.416027778,"longitude":69.776305556,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/10373","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-umer-kot","regionIds":["sindh"],"districtIds":["sindh-umer-kot"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-umer-kot"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,"sortOrder":2039,"detailsPageStatus":"ava