insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6031','mangho-pir-shrine','published','{"id":"major-doam-6031","mapDisplay":"featured","slug":"mangho-pir-shrine","status":"published","title":"Mangho Pir Shrine","shortTitle":"Mangho Pir Shrine","summary":"The shrine of Sakhi Sultan Mangho Pir includes his tomb, a burial ground and mosques. The complex is a significant historic sacred site in western Karachi.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6031","verifiedDate":"2026-10-17","sourceTitle":"Mazar of Mangho Pir","sourceRegion":"Sindh","sourceDistrict":"Karachi","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Adds documented built heritage in West Karachi.","components":[{"id":"major-doam-6031-point","name":"Mangho Pir Shrine","latitude":24.979286111,"longitude":67.034127778,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6031","coordinateNote":"Exact numeric coordinate transcribed from the public DOAM catalogue. Display contexts must be derived from protected ADM2 geometry, not the legacy source district label.","regionId":"sindh","districtId":"sindh-west-karachi","regionIds":["sindh"],"districtIds":["sindh-west-karachi"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-west-karachi"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,"sortOrder":2040,"detailsPageStatus":"available","provinceRegionIds":["sindh"],"districtIds":["sindh-we