insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-664','st-lukes-church-abbottabad','published','{"id":"major-doam-664","mapDisplay":"featured","slug":"st-lukes-church-abbottabad","status":"published","title":"St Luke''s Church, Abbottabad","shortTitle":"St Luke''s Church, Abbottabad","summary":"Dressed-stone walls and pointed arches distinguish this British-period church in Abbottabad. It represents the city''s colonial-era Christian architectural heritage.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/664","verifiedDate":"2026-10-17","sourceTitle":"ST. Luke`s Church","sourceRegion":"Khyber Pakhtunkhwa","sourceDistrict":"Abbottabad","sourcePublication":"Archaeological Survey in Hazara Division, District Abbottabad (Campaign 2008-09)","selectionReason":"Adds a well-documented historic church and an underrepresented Hazara district.","components":[{"id":"major-doam-664-point","name":"St Luke''s Church, Abbottabad","latitude":34.1498,"longitude":73.2134,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/664","coordinateNote":"Coordinate transcribed without relocation from the public DOAM catalogue. Administrative contexts are derived from the protected geometry, not the source district label.","regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-abbottabad","regionIds":["khyber-pakhtunkhwa"],"districtIds":["khyber-pakhtunkhwa-abbottabad"],"spatialMatches":[{"regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-abbottabad"}],"assignmentStatus":"spatially-derived"}],"image":null,"plac