insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-623','st-matthews-church-nathia-gali','published','{"id":"major-doam-623","mapDisplay":"featured","slug":"st-matthews-church-nathia-gali","status":"published","title":"St Matthew''s Church, Nathia Gali","shortTitle":"St Matthew''s Church, Nathia Gali","summary":"This church at Nathia Gali is recorded by the national heritage catalogue as a memorial to Colonel Hope Waddle Kelsal. Its surviving building forms part of the hill station''s architectural history.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/623","verifiedDate":"2026-10-17","sourceTitle":"St. Mathews Church (Nathiagali)","sourceRegion":"Khyber Pakhtunkhwa","sourceDistrict":"Abbottabad","sourcePublication":"Archaeological Survey of District Abbottabad 2006-07:A Preliminary Report","selectionReason":"Distinct hill-station ecclesiastical architecture, not another archaeological mound.","components":[{"id":"major-doam-623-point","name":"St Matthew''s Church, Nathia Gali","latitude":34.071531,"longitude":73.351636306,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/623","coordinateNote":"Coordinate transcribed without relocation from the public DOAM catalogue. Administrative contexts are derived from the protected geometry, not the source district label.","regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-abbottabad","regionIds":["khyber-pakhtunkhwa"],"districtIds":["khyber-pakhtunkhwa-abbottabad"],"spatialMatches":[{"regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-a