insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-3579','mughal-mosque-khar','published','{"id":"major-doam-3579","mapDisplay":"featured","slug":"mughal-mosque-khar","status":"published","title":"Mughal Mosque, Khar","shortTitle":"Mughal Mosque, Khar","summary":"The historic prayer sanctuary at Khar retains an arched frontage. Later additions recorded by the national catalogue distinguish the surviving core from the expanded mosque.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/3579","verifiedDate":"2026-10-17","sourceTitle":"Mughal Mosque Khar","sourceRegion":"Khyber Pakhtunkhwa","sourceDistrict":"Bajaur Agency","sourcePublication":"The Archaeological Explorations in Bajaur Agency","selectionReason":"Representative historic mosque in Bajaur; conservative attribution follows the catalogue.","components":[{"id":"major-doam-3579-point","name":"Mughal Mosque, Khar","latitude":34.755278861,"longitude":71.500371778,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/3579","coordinateNote":"Coordinate transcribed without relocation from the public DOAM catalogue. Administrative contexts are derived from the protected geometry, not the source district label.","regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-bajaur","regionIds":["khyber-pakhtunkhwa"],"districtIds":["khyber-pakhtunkhwa-bajaur"],"spatialMatches":[{"regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-bajaur"}],"assignmentStatus":"spatially-derived"}],"image":null,"placeholderImage":true,"imageTemporary":false,"featured":