insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-3184','akra-archaeological-mounds','published','{"id":"major-doam-3184","mapDisplay":"featured","slug":"akra-archaeological-mounds","status":"published","title":"Akra Archaeological Mounds","shortTitle":"Akra Archaeological Mounds","summary":"The mounds at Akra preserve evidence of a long-lived settlement in the Bannu basin. Pottery, sculpture fragments and coins recorded here connect the site with successive ancient and medieval occupations.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/3184","verifiedDate":"2026-10-17","sourceTitle":"Akra (Akara) Mound","sourceRegion":"Khyber Pakhtunkhwa","sourceDistrict":"Bannu","sourcePublication":"Archaeological Sites In the Bannu Basin","selectionReason":"Major long-duration archaeological landscape in an otherwise unrepresented basin.","components":[{"id":"major-doam-3184-point","name":"Akra Archaeological Mounds","latitude":32.877222222,"longitude":70.635611111,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/3184","coordinateNote":"Coordinate transcribed without relocation from the public DOAM catalogue. Administrative contexts are derived from the protected geometry, not the source district label.","regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-bannu","regionIds":["khyber-pakhtunkhwa"],"districtIds":["khyber-pakhtunkhwa-bannu"],"spatialMatches":[{"regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-bannu"}],"assignmentStatus":"spatia