insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-4977','gagra-fort','published','{"id":"major-doam-4977","mapDisplay":"featured","slug":"gagra-fort","status":"published","title":"Gagra Fort","shortTitle":"Gagra Fort","summary":"Gagra Fort preserves a fortified building associated with the former Swat state. Its watchtowers combine masonry with iron structural elements, illustrating a comparatively recent phase of regional defensive architecture.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Fortification","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/4977","verifiedDate":"2026-10-17","sourceTitle":"Gagra Fort","sourceRegion":"Khyber Pakhtunkhwa","sourceDistrict":"Buner","sourcePublication":"The Archaeological Explorations in Buner (1991-92 and 1992-93)","selectionReason":"Adds Buner''s Swat-state built heritage rather than importing the conflicting Ranigat coordinate.","components":[{"id":"major-doam-4977-point","name":"Gagra Fort","latitude":34.4735135,"longitude":72.538155056,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/4977","coordinateNote":"Coordinate transcribed without relocation from the public DOAM catalogue. Administrative contexts are derived from the protected geometry, not the source district label.","regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-buner","regionIds":["khyber-pakhtunkhwa"],"districtIds":["khyber-pakhtunkhwa-buner"],"spatialMatches":[{"regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-buner"}],"assignmentStatus":"spatially-derived"}],"image":null,"placeholderImage":true,"imageTemporary":false,"featur