insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-2160','bala-hisar-mound-charsadda','published','{"id":"major-doam-2160","mapDisplay":"featured","slug":"bala-hisar-mound-charsadda","status":"published","title":"Bala Hisar Mound, Charsadda","shortTitle":"Bala Hisar Mound, Charsadda","summary":"Excavations at this mound revealed a long sequence of occupation associated with ancient Pushkalavati. It is an important source for understanding settlement and urban life in Gandhara.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/2160","verifiedDate":"2026-10-17","sourceTitle":"Bala Hisar Mound","sourceRegion":"Khyber Pakhtunkhwa","sourceDistrict":"Charsadda","sourcePublication":"Archaeological Sites and Historical Monuments Protected Under the Antiquities Act, 1975","selectionReason":"Nationally significant urban archaeology; distinct from Peshawar''s Bala Hisar Fort.","components":[{"id":"major-doam-2160-point","name":"Bala Hisar Mound, Charsadda","latitude":34.206282333,"longitude":71.828915972,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/2160","coordinateNote":"Coordinate transcribed without relocation from the public DOAM catalogue. Administrative contexts are derived from the protected geometry, not the source district label.","regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-charsadda","regionIds":["khyber-pakhtunkhwa"],"districtIds":["khyber-pakhtunkhwa-charsadda"],"spatialMatches":[{"regionId":"khyber-pakhtunkhwa","districtId":"khyber-p