insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-1236','shahi-masjid-chitral','published','{"id":"major-doam-1236","mapDisplay":"featured","slug":"shahi-masjid-chitral","status":"published","title":"Shahi Masjid, Chitral","shortTitle":"Shahi Masjid, Chitral","summary":"Chitral''s Shahi Masjid combines a prayer hall with surrounding cloisters. The national catalogue associates the mosque and its tomb of Shuja-ul-Mulk with the Kator period.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/1236","verifiedDate":"2026-10-17","sourceTitle":"Shahi Masjid","sourceRegion":"Khyber Pakhtunkhwa","sourceDistrict":"Chitral","sourcePublication":"Archaeological Survey of District Chitral, 2004","selectionReason":"Adds Chitral''s courtly religious architecture with a site-specific official point.","components":[{"id":"major-doam-1236-point","name":"Shahi Masjid, Chitral","latitude":35.840196639,"longitude":71.819744583,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/1236","coordinateNote":"Coordinate transcribed without relocation from the public DOAM catalogue. Administrative contexts are derived from the protected geometry, not the source district label.","regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-chitral-lower","regionIds":["khyber-pakhtunkhwa"],"districtIds":["khyber-pakhtunkhwa-chitral-lower"],"spatialMatches":[{"regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-chitral-lower"}],"assignmentStatus":"spatially-derived"}],"image":null,"placeholderImage":true,"imageTemporary":false,