insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-1238','mustuj-fort','published','{"id":"major-doam-1238","mapDisplay":"featured","slug":"mustuj-fort","status":"published","title":"Mustuj Fort","shortTitle":"Mustuj Fort","summary":"Mustuj Fort is a surviving fortified complex associated with the Kator period of Chitral. The official catalogue records an occupied and preserved enclosure, making it a tangible link with the valley''s political history.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Fortification","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/1238","verifiedDate":"2026-10-17","sourceTitle":"Mustuj Fort","sourceRegion":"Khyber Pakhtunkhwa","sourceDistrict":"Chitral","sourcePublication":"Archaeological Survey of District Chitral, 2004","selectionReason":"Extends northern KP representation through a distinct historic fort.","components":[{"id":"major-doam-1238-point","name":"Mustuj Fort","latitude":36.2848,"longitude":72.5242,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/1238","coordinateNote":"Coordinate transcribed without relocation from the public DOAM catalogue. Administrative contexts are derived from the protected geometry, not the source district label.","regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-chitral-upper","regionIds":["khyber-pakhtunkhwa"],"districtIds":["khyber-pakhtunkhwa-chitral-upper"],"spatialMatches":[{"regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-chitral-upper"}],"assignmentStatus":"spatially-derived"}],"image":null,"placeholderImage":true,"imageTemporary":false,"featured":false,"sortOrder