insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-1012','bilot-sharif-temples','published','{"id":"major-doam-1012","mapDisplay":"featured","slug":"bilot-sharif-temples","status":"published","title":"Bilot Sharif Temples","shortTitle":"Bilot Sharif Temples","summary":"A fortified enclosure at Bilot Sharif contains a group of dressed-stone Hindu temples. The surviving temples and defensive walls illustrate the region''s religious and architectural heritage.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/1012","verifiedDate":"2026-10-17","sourceTitle":"Bilot Sharif Temples","sourceRegion":"Khyber Pakhtunkhwa","sourceDistrict":"Dera Ismail Khan","sourcePublication":"Archaeological Explorations In the Gomal Valley, Pakistan 2003","selectionReason":"Important stone temple ensemble; one Place for the group, not a record per temple.","components":[{"id":"major-doam-1012-point","name":"Bilot Sharif Temples","latitude":32.2395,"longitude":71.15324,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/1012","coordinateNote":"Coordinate transcribed without relocation from the public DOAM catalogue. Administrative contexts are derived from the protected geometry, not the source district label.","regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-d-i-khan","regionIds":["khyber-pakhtunkhwa"],"districtIds":["khyber-pakhtunkhwa-d-i-khan"],"spatialMatches":[{"regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-d-i-khan"}],"assignmentStatus":"spatially-deriv