insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-3108','raisan-stupa','published','{"id":"major-doam-3108","mapDisplay":"featured","slug":"raisan-stupa","status":"published","title":"Raisan Stupa","shortTitle":"Raisan Stupa","summary":"The national catalogue identifies a Buddhist archaeological site at Raisan with a visible square stupa structure. It provides a documented point of entry into Hangu''s Buddhist heritage.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/3108","verifiedDate":"2026-10-17","sourceTitle":"Raisan Stupa","sourceRegion":"Khyber Pakhtunkhwa","sourceDistrict":"Hangu","sourcePublication":"Preliminary Report On the Survey of Kohat And Hangu Districts, 2004","selectionReason":"Representative standing archaeological structure in an unrepresented district.","components":[{"id":"major-doam-3108-point","name":"Raisan Stupa","latitude":33.5731,"longitude":71.17775,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/3108","coordinateNote":"Coordinate transcribed without relocation from the public DOAM catalogue. Administrative contexts are derived from the protected geometry, not the source district label.","regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-hangu","regionIds":["khyber-pakhtunkhwa"],"districtIds":["khyber-pakhtunkhwa-hangu"],"spatialMatches":[{"regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-hangu"}],"assignmentStatus":"spatially-derived"}],"image":null,"placeholderImage":true,"imageTemporary":false,"featured":false,"sortOrder":33108,"detailsPa