insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-3447','saphola-stupa','published','{"id":"major-doam-3447","mapDisplay":"featured","slug":"saphola-stupa","status":"published","title":"Saphola Stupa","shortTitle":"Saphola Stupa","summary":"A ruined Buddhist stupa rises from a tiered stone base along the Khyber Pass. Its surviving masonry is evidence of religious activity on this historic route.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/3447","verifiedDate":"2026-10-17","sourceTitle":"Saphola Stupa","sourceRegion":"Khyber Pakhtunkhwa","sourceDistrict":"Khyber Agency","sourcePublication":"Preliminary Report on  Survey of Heritage Sites and Monuments along the Grand Trunk Road  from Peshawar to Lahore","selectionReason":"Connects the Khyber route with Buddhist architectural heritage.","components":[{"id":"major-doam-3447-point","name":"Saphola Stupa","latitude":34.074518,"longitude":71.208453,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/3447","coordinateNote":"Coordinate transcribed without relocation from the public DOAM catalogue. Administrative contexts are derived from the protected geometry, not the source district label.","regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-khyber","regionIds":["khyber-pakhtunkhwa"],"districtIds":["khyber-pakhtunkhwa-khyber"],"spatialMatches":[{"regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-khyber"}],"assignmentStatus":"spatially-derived"}],"image":null,"placeholderImage":true,"imageTemporary":false,"featured":false,"sortO