insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-1297','chakdara-fort','published','{"id":"major-doam-1297","mapDisplay":"featured","slug":"chakdara-fort","status":"published","title":"Chakdara Fort","shortTitle":"Chakdara Fort","summary":"Chakdara Fort is recorded as a British-period fort built over the remains of an earlier defensive site. Its layered history connects the Lower Dir landscape with successive military occupations.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Fortification","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/1297","verifiedDate":"2026-10-17","sourceTitle":"Chakdara Fort","sourceRegion":"Khyber Pakhtunkhwa","sourceDistrict":"Lower Dir","sourcePublication":"A Survey of Lower Dir, Khyber Pakhtunkhwa (former North West Frontier Province), Pakistan (2005)","selectionReason":"Distinct defensive monument; catalogue''s internally inconsistent early date and builder are deliberately omitted.","components":[{"id":"major-doam-1297-point","name":"Chakdara Fort","latitude":34.6468,"longitude":72.0287,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/1297","coordinateNote":"Coordinate transcribed without relocation from the public DOAM catalogue. Administrative contexts are derived from the protected geometry, not the source district label.","regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-lower-dir","regionIds":["khyber-pakhtunkhwa"],"districtIds":["khyber-pakhtunkhwa-lower-dir"],"spatialMatches":[{"regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-lower-dir"}],"assignmentStatus":"spatially-derived"}],"image":null,"pla