insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-1941','jatgram-manri','published','{"id":"major-doam-1941","mapDisplay":"featured","slug":"jatgram-manri","status":"published","title":"Jatgram Manri","shortTitle":"Jatgram Manri","summary":"Stupa remains and substantial stone walls survive at Jatgram Manri. The official catalogue records occupation spanning Kushan and Hindu Shahi periods, illustrating the archaeological depth of the Dir valleys.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/1941","verifiedDate":"2026-10-17","sourceTitle":"Jatgram Manri","sourceRegion":"Khyber Pakhtunkhwa","sourceDistrict":"Upper Dir","sourcePublication":"Archaeological Survey of Tehsil Wari, Upper Dir District (Campaign 2006-07)","selectionReason":"Documented Buddhist remains and long occupation in underrepresented Upper Dir.","components":[{"id":"major-doam-1941-point","name":"Jatgram Manri","latitude":35.023433333,"longitude":72.051816667,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/1941","coordinateNote":"Coordinate transcribed without relocation from the public DOAM catalogue. Administrative contexts are derived from the protected geometry, not the source district label.","regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-upper-dir","regionIds":["khyber-pakhtunkhwa"],"districtIds":["khyber-pakhtunkhwa-upper-dir"],"spatialMatches":[{"regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-upper-dir"}],"assignmentStatus":"spatially-derived"}],"image":null,"placeholderImage":true,"imageT