insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-4712','alingar-rock-inscription','published','{"id":"major-doam-4712","mapDisplay":"featured","slug":"alingar-rock-inscription","status":"published","title":"Alingar Rock Inscription","shortTitle":"Alingar Rock Inscription","summary":"An inscription in Sharada script and nearby animal carvings survive on rocks at Alingar. Ruined structures around them place this epigraphic heritage within a wider archaeological landscape.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Monument","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/4712","verifiedDate":"2026-10-17","sourceTitle":"Alingar Rock Inscription","sourceRegion":"Khyber Pakhtunkhwa","sourceDistrict":"Mohmand Agency","sourcePublication":"Archaeological Exploration in the Mohmand Agency","selectionReason":"Adds inscription and rock-art heritage in Mohmand instead of another generic mound.","components":[{"id":"major-doam-4712-point","name":"Alingar Rock Inscription","latitude":34.648592111,"longitude":71.511602167,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/4712","coordinateNote":"Coordinate transcribed without relocation from the public DOAM catalogue. Administrative contexts are derived from the protected geometry, not the source district label.","regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-mohmand","regionIds":["khyber-pakhtunkhwa"],"districtIds":["khyber-pakhtunkhwa-mohmand"],"spatialMatches":[{"regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-mohmand"}],"assignmentStatus":"spatially-derived"}],"image":null,"placeho