insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-3210','sher-kela-dherai','published','{"id":"major-doam-3210","mapDisplay":"featured","slug":"sher-kela-dherai","status":"published","title":"Sher Kela Dherai","shortTitle":"Sher Kela Dherai","summary":"This archaeological mound beside the Gambila river preserves evidence of settlement in the Lakki Marwat area. Surface finds recorded by the national catalogue indicate Kushan and early Islamic activity.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/3210","verifiedDate":"2026-10-17","sourceTitle":"Sher Kela Dherai","sourceRegion":"Khyber Pakhtunkhwa","sourceDistrict":"Lakki Marwat","sourcePublication":"Archaeological Sites In the Bannu Basin","selectionReason":"Representative settlement archaeology in an otherwise uncovered district.","components":[{"id":"major-doam-3210-point","name":"Sher Kela Dherai","latitude":32.762630778,"longitude":70.719326778,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/3210","coordinateNote":"Coordinate transcribed without relocation from the public DOAM catalogue. Administrative contexts are derived from the protected geometry, not the source district label.","regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-lakki-marwat","regionIds":["khyber-pakhtunkhwa"],"districtIds":["khyber-pakhtunkhwa-lakki-marwat"],"spatialMatches":[{"regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-lakki-marwat"}],"assignmentStatus":"spatially-derived"}],"image":null,"placeholderImage":true,"imageTemporary":false,"