insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-995','fort-of-the-nawab-of-tank','published','{"id":"major-doam-995","mapDisplay":"featured","slug":"fort-of-the-nawab-of-tank","status":"published","title":"Fort of the Nawab of Tank","shortTitle":"Fort of the Nawab of Tank","summary":"A gateway and pillared verandah survive from the fort of the Nawab of Tank. These brick-built remnants recall a larger fortified complex damaged by flooding.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Fortification","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/995","verifiedDate":"2026-10-17","sourceTitle":"Fort of the Nawab of Tank","sourceRegion":"Khyber Pakhtunkhwa","sourceDistrict":"Tank","sourcePublication":"Archaeological Explorations in the Gomal Valley: The third Phase 2004-District Tank","selectionReason":"Distinct historic gateway and southern KP representation; uncertain builder omitted.","components":[{"id":"major-doam-995-point","name":"Fort of the Nawab of Tank","latitude":32.213398972,"longitude":70.385487278,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/995","coordinateNote":"Coordinate transcribed without relocation from the public DOAM catalogue. Administrative contexts are derived from the protected geometry, not the source district label.","regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-tank","regionIds":["khyber-pakhtunkhwa"],"districtIds":["khyber-pakhtunkhwa-tank"],"spatialMatches":[{"regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-tank"}],"assignmentStatus":"spatially-derived"}],"image":null,"placeholderImage":true,"im