insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-10334','dargai-fort','published','{"id":"major-doam-10334","mapDisplay":"featured","slug":"dargai-fort","status":"published","title":"Dargai Fort","shortTitle":"Dargai Fort","summary":"Dargai Fort is a brick-built military structure with high defensive walls and firing openings. The national catalogue places its construction in the late nineteenth century, within the history of British campaigns around Malakand.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Fortification","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/10334","verifiedDate":"2026-10-17","sourceTitle":"Dargai Fort","sourceRegion":"Khyber Pakhtunkhwa","sourceDistrict":"Malakand","sourcePublication":"Miscellaneous","selectionReason":"Architectural and regional military history in Malakand.","components":[{"id":"major-doam-10334-point","name":"Dargai Fort","latitude":34.507103694,"longitude":71.89849775,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/10334","coordinateNote":"Coordinate transcribed without relocation from the public DOAM catalogue. Administrative contexts are derived from the protected geometry, not the source district label.","regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-malakand","regionIds":["khyber-pakhtunkhwa"],"districtIds":["khyber-pakhtunkhwa-malakand"],"spatialMatches":[{"regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-malakand"}],"assignmentStatus":"spatially-derived"}],"image":null,"placeholderImage":true,"imageTemporary":false,"featured":false,"sortOrder":40334,"detailsPageStatus":"future",