insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-1799','mughal-mosque-at-kaka-sahib','published','{"id":"major-doam-1799","mapDisplay":"featured","slug":"mughal-mosque-at-kaka-sahib","status":"published","title":"Mughal Mosque at Kaka Sahib","shortTitle":"Mughal Mosque at Kaka Sahib","summary":"The historic prayer chamber at Kaka Sahib survives within a mosque expanded in later times. Its original frontage and the newer verandah make the building''s successive phases legible.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/1799","verifiedDate":"2026-10-17","sourceTitle":"Mughal Mosque at Kaka Sahib","sourceRegion":"Khyber Pakhtunkhwa","sourceDistrict":"Nowshera","sourcePublication":"The Archaeological Explorations in District Nowshera","selectionReason":"Representative mosque architecture in Nowshera with a site-specific official coordinate.","components":[{"id":"major-doam-1799-point","name":"Mughal Mosque at Kaka Sahib","latitude":33.93885575,"longitude":72.036015,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/1799","coordinateNote":"Coordinate transcribed without relocation from the public DOAM catalogue. Administrative contexts are derived from the protected geometry, not the source district label.","regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-nowshera","regionIds":["khyber-pakhtunkhwa"],"districtIds":["khyber-pakhtunkhwa-nowshera"],"spatialMatches":[{"regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-nowshera"}],"assignmentStatus":"spatially-derived"}],"image":n