insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-10332','wooden-mosque-kalam','published','{"id":"major-doam-10332","mapDisplay":"featured","slug":"wooden-mosque-kalam","status":"published","title":"Wooden Mosque, Kalam","shortTitle":"Wooden Mosque, Kalam","summary":"Kalam''s wooden mosque is constructed with deodar timber and decorated with floral and geometric carving. Its two-storey form represents the distinctive timber-building traditions of the upper Swat valley.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/10332","verifiedDate":"2026-10-17","sourceTitle":"Wooden Mosque (Kalam)","sourceRegion":"Khyber Pakhtunkhwa","sourceDistrict":"Swat","sourcePublication":"Fruit of labour: 250-year-old mosque stands tall among Kalam`s stunning views","selectionReason":"Broadens Swat beyond Buddhist archaeology with material architectural heritage.","components":[{"id":"major-doam-10332-point","name":"Wooden Mosque, Kalam","latitude":35.489079944,"longitude":72.579031667,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/10332","coordinateNote":"Coordinate transcribed without relocation from the public DOAM catalogue. Administrative contexts are derived from the protected geometry, not the source district label.","regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-swat","regionIds":["khyber-pakhtunkhwa"],"districtIds":["khyber-pakhtunkhwa-swat"],"spatialMatches":[{"regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-swat"}],"assignmentStatus":"spatially-derived"}],"image":null,"placehol