insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-2280','hund-fort','published','{"id":"major-doam-2280","mapDisplay":"featured","slug":"hund-fort","status":"published","title":"Hund Fort","shortTitle":"Hund Fort","summary":"Fortification walls and regularly spaced bastions survive at Hund. The national catalogue attributes this defensive enclosure to the Mughal period, within a settlement subsequently occupied by later residents.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Fortification","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Protected by The Khyber Pakhtunkhwa Antiquities Act, 2016","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/2280","verifiedDate":"2026-10-17","sourceTitle":"Hund Fort","sourceRegion":"Khyber Pakhtunkhwa","sourceDistrict":"Swabi","sourcePublication":"Archaeological Survey of District Swabi (Campaign 2005-06)","selectionReason":"Historic Indus-crossing settlement fortifications in Swabi.","components":[{"id":"major-doam-2280-point","name":"Hund Fort","latitude":34.016017,"longitude":72.431786,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/2280","coordinateNote":"Coordinate transcribed without relocation from the public DOAM catalogue. Administrative contexts are derived from the protected geometry, not the source district label.","regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-swabi","regionIds":["khyber-pakhtunkhwa"],"districtIds":["khyber-pakhtunkhwa-swabi"],"spatialMatches":[{"regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-swabi"}],"assignmentStatus":"spatially-derived"}],"image":null,"placeholderImage":true,"imageTemporary":false,"featured":false,"sortOrder