insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-4549','peshawar-museum','published','{"id":"major-doam-4549","mapDisplay":"featured","slug":"peshawar-museum","status":"published","title":"Peshawar Museum","shortTitle":"Peshawar Museum","summary":"Peshawar Museum houses important Gandharan sculpture alongside collections reflecting later regional history. The museum''s early-twentieth-century building is itself part of the city''s institutional heritage.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Museum / Collection","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/4549","verifiedDate":"2026-10-17","sourceTitle":"Peshawar Museum","sourceRegion":"Khyber Pakhtunkhwa","sourceDistrict":"Peshawar","sourcePublication":"Peshawar: Historic City of the Frontier","selectionReason":"Balances the regional inventory with a nationally important museum collection.","components":[{"id":"major-doam-4549-point","name":"Peshawar Museum","latitude":34.0079,"longitude":71.558,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/4549","coordinateNote":"Coordinate transcribed without relocation from the public DOAM catalogue. Administrative contexts are derived from the protected geometry, not the source district label.","regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-peshawar","regionIds":["khyber-pakhtunkhwa"],"districtIds":["khyber-pakhtunkhwa-peshawar"],"spatialMatches":[{"regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-peshawar"}],"assignmentStatus":"spatially-derived"}],"image":null,"placeholderImage":true,"imageTemporary":false,"featured":false,"sor