insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-3093','sheikh-allah-dad-and-sheikh-karim-dad-tombs','published','{"id":"major-doam-3093","mapDisplay":"featured","slug":"sheikh-allah-dad-and-sheikh-karim-dad-tombs","status":"published","title":"Sheikh Allah Dad and Sheikh Karim Dad Tombs","shortTitle":"Sheikh Allah Dad and Sheikh Karim Dad Tombs","summary":"These square-plan tombs preserve decorated interiors associated by the national catalogue with the Mughal period. Their fresco work adds a funerary and painted-architecture dimension to the area''s heritage.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Tomb / Funerary Heritage","designationType":"none","designationName":"Major Heritage Site","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/3093","verifiedDate":"2026-10-17","sourceTitle":"Sheikh Allah Dad and Sheikh Karim Dad Tombs","sourceRegion":"Khyber Pakhtunkhwa","sourceDistrict":"Kohat","sourcePublication":"Preliminary Report On the Survey of Kohat And Hangu Districts, 2004","selectionReason":"Adds a documented tomb ensemble with precise catalogue coordinates; public geography remains polygon-derived.","components":[{"id":"major-doam-3093-point","name":"Sheikh Allah Dad and Sheikh Karim Dad Tombs","latitude":33.636547583,"longitude":71.879134167,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/3093","coordinateNote":"Coordinate transcribed without relocation from the public DOAM catalogue. Administrative contexts are derived from the protected geometry, not the source district label.","regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-kohat","regionIds":["khyber-pakhtunkhwa"],"districtIds":["khyber-pakhtun