insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-8030','mudoori-fort-yasin','published','{"id":"major-doam-8030","mapDisplay":"featured","slug":"mudoori-fort-yasin","status":"published","title":"Mudoori Fort, Yasin","shortTitle":"Mudoori Fort, Yasin","summary":"The fort site at Sandi in Yasin is associated with nineteenth-century conflict in the valley. It preserves a tangible location for the region’s political and military history.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Fortification","designationType":"none","designationName":"Major heritage site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/8030","verifiedDate":"2026-10-17","sourceTitle":"Mudoori Fort Sandi Yasin","sourceRegion":"Gilgit-Baltistan","sourceDistrict":"Ghizer","sourcePublication":"Built Heritage of Gilgit Baltistan by Baltistan Culture and Development Foundation","selectionReason":"Underrepresented Gupis-Yasin; disputed casualty and date details omitted.","legalStatus":"Not Protected","legalStatusNote":"Attributed catalogue statement, not an independent assessment of current law.","components":[{"id":"major-doam-8030-point","name":"Mudoori Fort, Yasin","latitude":36.418844344,"longitude":73.370561609,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/8030","coordinateNote":"Official site catalogue coordinate retained at published precision, not independently field-surveyed. Geographic contexts derive from protected ADM2 geometry; historical district labels are metadata only.","regionId":"gilgit-baltistan","districtId":"gilgit-baltistan-gupis-yasin","regionIds":["gilgit-baltistan"],"districtIds":["gilgit-baltistan-gupis-yasin"],"spatialMatches":[{"regionId":"gilgit-baltistan","districtId":"gilgit-baltistan-gupis-yasin"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","pla