insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-8245','tarishing-safro-shikar','published','{"id":"major-doam-8245","mapDisplay":"featured","slug":"tarishing-safro-shikar","status":"published","title":"Tarishing Safro Shikar","shortTitle":"Tarishing Safro Shikar","summary":"The surviving lower level of a traditional watchtower at Tarishing combines stone and timber construction. The original tower contained storage, residential and lookout levels.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Fortification","designationType":"none","designationName":"Major heritage site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/8245","verifiedDate":"2026-10-17","sourceTitle":"Tarishing Safro Shikar","sourceRegion":"Gilgit-Baltistan","sourceDistrict":"Astore","sourcePublication":"Tourism, Sports, Culture, Archaeology & Museum Department Gilgit-Baltistan","selectionReason":"Astore watchtower and regional building technique.","legalStatus":"Not Protected","legalStatusNote":"Attributed catalogue statement, not an independent assessment of current law.","components":[{"id":"major-doam-8245-point","name":"Tarishing Safro Shikar","latitude":35.357030131,"longitude":74.862033688,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/8245","coordinateNote":"Official site catalogue coordinate retained at published precision, not independently field-surveyed. Geographic contexts derive from protected ADM2 geometry; historical district labels are metadata only.","regionId":"gilgit-baltistan","districtId":"gilgit-baltistan-astore","regionIds":["gilgit-baltistan"],"districtIds":["gilgit-baltistan-astore"],"spatialMatches":[{"regionId":"gilgit-baltistan","districtId":"gilgit-baltistan-astore"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemp