insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-8244','zaipur-shikari-water-channel-pillar','published','{"id":"major-doam-8244","mapDisplay":"featured","slug":"zaipur-shikari-water-channel-pillar","status":"published","title":"Zaipur Shikari Water-Channel Pillar","shortTitle":"Zaipur Shikari Water-Channel Pillar","summary":"A tapering stone pillar survives from a structure that supported wooden water channels between hillsides. Its layered masonry records an unusual piece of historic water-supply infrastructure.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Monument","designationType":"none","designationName":"Major heritage site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/8244","verifiedDate":"2026-10-17","sourceTitle":"Zaipur Shikari","sourceRegion":"Gilgit-Baltistan","sourceDistrict":"Astore","sourcePublication":"Tourism, Sports, Culture, Archaeology & Museum Department Gilgit-Baltistan","selectionReason":"Astore engineering heritage; not mislabelled as a defensive tower.","legalStatus":"Not Protected","legalStatusNote":"Attributed catalogue statement, not an independent assessment of current law.","components":[{"id":"major-doam-8244-point","name":"Zaipur Shikari Water-Channel Pillar","latitude":35.319964227,"longitude":74.776179602,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/8244","coordinateNote":"Official site catalogue coordinate retained at published precision, not independently field-surveyed. Geographic contexts derive from protected ADM2 geometry; historical district labels are metadata only.","regionId":"gilgit-baltistan","districtId":"gilgit-baltistan-astore","regionIds":["gilgit-baltistan"],"districtIds":["gilgit-baltistan-astore"],"spatialMatches":[{"regionId":"gilgit-baltistan","districtId":"gilgit-baltistan-astore"}],"assignmen