insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-8292','ishal-rock-art','published','{"id":"major-doam-8292","mapDisplay":"featured","slug":"ishal-rock-art","status":"published","title":"Ishal Rock Art","shortTitle":"Ishal Rock Art","summary":"Rock carvings and Brahmi inscriptions at Ishal include animals, hunters and symbolic forms. The documented group is part of the archaeological record of the Darel valley.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Major heritage site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/8292","verifiedDate":"2026-10-17","sourceTitle":"Ishal","sourceRegion":"Gilgit-Baltistan","sourceDistrict":"Diamir","sourcePublication":"Archaeological Survey of Gilgit-Baltistan by Baltistan Culture and Development Foundation","selectionReason":"Underrepresented Darel archaeological landscape.","legalStatus":"Not Protected","legalStatusNote":"Attributed catalogue statement, not an independent assessment of current law.","components":[{"id":"major-doam-8292-point","name":"Ishal Rock Art","latitude":35.791684046,"longitude":73.693902782,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/8292","coordinateNote":"Official site catalogue coordinate retained at published precision, not independently field-surveyed. Geographic contexts derive from protected ADM2 geometry; historical district labels are metadata only.","regionId":"gilgit-baltistan","districtId":"gilgit-baltistan-darel","regionIds":["gilgit-baltistan"],"districtIds":["gilgit-baltistan-darel"],"spatialMatches":[{"regionId":"gilgit-baltistan","districtId":"gilgit-baltistan-darel"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,"sortOrder":48292