insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-7664','danyor-rock-inscription','published','{"id":"major-doam-7664","mapDisplay":"featured","slug":"danyor-rock-inscription","status":"published","title":"Danyor Rock Inscription","shortTitle":"Danyor Rock Inscription","summary":"A large rock at Danyor preserves royal inscriptions in a late Brahmi script associated with the development of Sharada. It is an important epigraphic monument in the Gilgit landscape.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Major heritage site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/7664","verifiedDate":"2026-10-17","sourceTitle":"Danyor Rock Inscription","sourceRegion":"Gilgit-Baltistan","sourceDistrict":"Gilgit","sourcePublication":"Pak-German Archaeological Mission to the Northern Areas of the Heidelberg Academy for the Humanities and Sciences","selectionReason":"Gilgit epigraphy; contradictory legal-status fields not treated as proof of protection.","legalStatus":null,"legalStatusNote":"Catalogue legal-status fields are inconsistent with the description or jurisdiction; no legal designation asserted.","components":[{"id":"major-doam-7664-point","name":"Danyor Rock Inscription","latitude":35.916962067,"longitude":74.373127439,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/7664","coordinateNote":"Official site catalogue coordinate retained at published precision, not independently field-surveyed. Geographic contexts derive from protected ADM2 geometry; historical district labels are metadata only.","regionId":"gilgit-baltistan","districtId":"gilgit-baltistan-gilgit","regionIds":["gilgit-baltistan"],"districtIds":["gilgit-baltistan-gilgit"],"spatialMatches":[{"regionId":"gilgit-baltistan","districtId":"gilgit-