insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-7638','kargah-buddha','published','{"id":"major-doam-7638","mapDisplay":"featured","slug":"kargah-buddha","status":"published","title":"Kargah Buddha","shortTitle":"Kargah Buddha","summary":"A standing Buddha is carved in relief into the cliff face at Kargah near Gilgit. The monument is a significant surviving expression of the region’s Buddhist heritage.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Major heritage site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/7638","verifiedDate":"2026-10-17","sourceTitle":"Kargah Buddha","sourceRegion":"Gilgit-Baltistan","sourceDistrict":"Gilgit","sourcePublication":"Pak-German Archaeological Mission to the Northern Areas of the Heidelberg Academy for the Humanities and Sciences","selectionReason":"Major Buddhist sculpture; current regional authority supplies a defensible site coordinate.","legalStatus":"Not Protected","legalStatusNote":"Attributed catalogue statement, not an independent assessment of current law.","components":[{"id":"major-doam-7638-point","name":"Kargah Buddha","latitude":35.91150862,"longitude":74.26275851,"coordinateStatus":"verified-official","coordinateSource":"https://e-tourism.visitgilgitbaltistan.gov.pk/tourist-destinations/kargahbuddha","coordinateNote":"Exact site coordinate supplied by the current GB tourism/archaeology authority. DOAM point35.882001287,74.463564096 rejected as conflicting; no estimated relocation.","regionId":"gilgit-baltistan","districtId":"gilgit-baltistan-gilgit","regionIds":["gilgit-baltistan"],"districtIds":["gilgit-baltistan-gilgit"],"spatialMatches":[{"regionId":"gilgit-baltistan","districtId":"gilgit-baltistan-gilgit"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholde