insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6734','bagh-fort','published','{"id":"major-doam-6734","mapDisplay":"featured","slug":"bagh-fort","status":"published","title":"Bagh Fort","shortTitle":"Bagh Fort","summary":"Also known as Gulab Singh ka Qila, this fort stands in the Bagh valley beside the Malwani stream. The official catalogue associates it with the Dogra period.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Fortification","designationType":"none","designationName":"Major heritage site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6734","verifiedDate":"2026-10-17","sourceTitle":"Bagh Fort","sourceRegion":"Azad Jammu and Kashmir","sourceDistrict":"Bagh","sourcePublication":"History and Archaeology: Azad Jammu and Kashmir","selectionReason":"Previously unmapped Bagh; official protected-monument identity.","legalStatus":"Protected by Azad Jammu & Kashmir Preservation and Protection of Antiquities Act, 1986","legalStatusNote":"Attributed catalogue statement, not an independent assessment of current law.","components":[{"id":"major-doam-6734-point","name":"Bagh Fort","latitude":33.99391664,"longitude":73.768890958,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6734","coordinateNote":"Official site catalogue coordinate retained at published precision, not independently field-surveyed. Geographic contexts derive from protected ADM2 geometry; historical district labels are metadata only.","regionId":"azad-kashmir","districtId":"azad-kashmir-bagh","regionIds":["azad-kashmir"],"districtIds":["azad-kashmir-bagh"],"spatialMatches":[{"regionId":"azad-kashmir","districtId":"azad-kashmir-bagh"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":false,"featured":false,"sortOrder":46734,"detailsPageStatu