insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6470','samadhi-of-maharaja-ranjit-singh','published','{"id":"major-doam-6470","slug":"samadhi-of-maharaja-ranjit-singh","status":"published","title":"Samadhi of Maharaja Ranjit Singh","shortTitle":"Samadhi of Maharaja Ranjit Singh","summary":"A domed memorial beside Lahore Fort commemorating Maharaja Ranjit Singh. Carved stone, painted decoration and mirrorwork distinguish its commemorative architecture.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Tomb / Funerary Heritage","designationType":"none","designationName":"Major heritage site","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"Catalogue transcription only; not an independent review of current statutory protection.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6470","verifiedDate":"2026-10-22","sourceTitle":"Samadh of Ranjit Singh","sourceRegion":"Punjab","sourceDistrict":"Lahore","sourcePublication":"Archaeological Sites and Historical Monuments Protected Under the Antiquities Act, 1975","selectionReason":"Adds a distinct funerary monument and its documented architectural treatment.","components":[{"id":"major-doam-6470-point","name":"Samadh of Ranjit Singh","latitude":31.5893,"longitude":74.3113,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6470","coordinateNote":"Exact DOAM catalogue site coordinate at published precision; DMS consistency, identity context and protected-polygon checks performed. Not independently field surveyed. Historical district metadata is not used as a spatial override.","regionId":"punjab","districtId":"punjab-lahore","regionIds":["punjab"],"districtIds":["punjab-lahore"],"spatialMatches":[{"regionId":"punjab","districtId":"punjab-lahore"}],"assignmentStatus":"spatially-derived"}],"ima