insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6472','tomb-of-nur-jahan','published','{"id":"major-doam-6472","slug":"tomb-of-nur-jahan","status":"published","title":"Tomb of Nur Jahan","shortTitle":"Tomb of Nur Jahan","summary":"A Mughal mausoleum at Shahdara associated with Nur Jahan and her daughter Ladli Begum. Its low, platform-based composition contrasts with nearby monumental tomb towers.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Tomb / Funerary Heritage","designationType":"none","designationName":"Major heritage site","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"Catalogue transcription only; not an independent review of current statutory protection.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6472","verifiedDate":"2026-10-22","sourceTitle":"Tomb of Nur Jahan","sourceRegion":"Punjab","sourceDistrict":"Lahore","sourcePublication":"Archaeological Sites and Historical Monuments Protected Under the Antiquities Act, 1975","selectionReason":"Adds a distinct funerary monument and its documented architectural treatment.","components":[{"id":"major-doam-6472-point","name":"Tomb of Nur Jahan","latitude":31.6209,"longitude":74.2947,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6472","coordinateNote":"Exact DOAM catalogue site coordinate at published precision; DMS consistency, identity context and protected-polygon checks performed. Not independently field surveyed. Historical district metadata is not used as a spatial override.","regionId":"punjab","districtId":"punjab-lahore","regionIds":["punjab"],"districtIds":["punjab-lahore"],"spatialMatches":[{"regionId":"punjab","districtId":"punjab-lahore"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":fa