insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6513','dai-angas-tomb-and-gulabi-bagh-gateway','published','{"id":"major-doam-6513","slug":"dai-angas-tomb-and-gulabi-bagh-gateway","status":"published","title":"Dai Anga’s Tomb and Gulabi Bagh Gateway","shortTitle":"Dai Anga’s Tomb and Gulabi Bagh Gateway","summary":"A domed brick mausoleum and decorated garden gateway form a historic ensemble beside Lahore’s old Grand Trunk Road. Tile mosaic and calligraphy distinguish the surviving structures.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Tomb / Funerary Heritage","designationType":"none","designationName":"Major heritage site","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"Catalogue transcription only; not an independent review of current statutory protection.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6513","verifiedDate":"2026-10-22","sourceTitle":"Dai Anga`s Tomb","sourceRegion":"Punjab","sourceDistrict":"Lahore","sourcePublication":"Archaeological Sites and Historical Monuments Protected Under the Antiquities Act, 1975","selectionReason":"Adds a distinct funerary monument and its documented architectural treatment.","components":[{"id":"major-doam-6513-point","name":"Dai Anga`s Tomb","latitude":31.578611111,"longitude":74.363888889,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6513","coordinateNote":"Exact DOAM catalogue site coordinate at published precision; DMS consistency, identity context and protected-polygon checks performed. Not independently field surveyed. Historical district metadata is not used as a spatial override.","regionId":"punjab","districtId":"punjab-lahore","regionIds":["punjab"],"districtIds":["punjab-lahore"],"spatialMatches":[{"regionId":"punjab","districtId":"punjab-lahore"}],"assig