insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-9986','old-police-station-seerani','published','{"id":"major-doam-9986","slug":"old-police-station-seerani","status":"published","title":"Old Police Station, Seerani","shortTitle":"Old Police Station, Seerani","aliases":["Old Police Station Seerani"],"summary":"The old police station at Seerani is a colonial-period administrative building recorded by the Sindh heritage survey. It preserves a material link with the development of local public institutions in lower Sindh.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Urban Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/9986","verifiedDate":"2026-10-22","sourceTitle":"Old Police Station Seerani","sourceRegion":"Sindh","sourceDistrict":"Badin","sourcePublication":"Documentation of the Heritage Sites and Monuments of Sindh","selectionReason":"Distinct public-service architecture outside the already selected Badin settlement sites.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-9986-point","name":"Old Police Station, Seerani","latitude":24.498251,"longitude":68.791624,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/9986","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-badin","regionIds":["sindh"],"districtIds":["sindh-badin"],"spatialMatches":[{"regionId":"sindh","districtI