insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-9988','luari-sharif-shrine-complex','published','{"id":"major-doam-9988","slug":"luari-sharif-shrine-complex","status":"published","title":"Luari Sharif Shrine Complex","shortTitle":"Luari Sharif Shrine Complex","aliases":["Luari Sharif Dargah"],"summary":"Luari Sharif is a walled shrine complex with a wooden entrance gate and an adjoining historic burial ground. The documented ensemble includes carved graves and archaeological material, linking sacred architecture with a longer history of occupation.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/9988","verifiedDate":"2026-10-22","sourceTitle":"Luari Sharif Dargah","sourceRegion":"Sindh","sourceDistrict":"Badin","sourcePublication":"Documentation of the Heritage Sites and Monuments of Sindh","selectionReason":"Substantial named sacred ensemble in lower Sindh; no claim about present opening arrangements.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-9988-point","name":"Luari Sharif Shrine Complex","latitude":24.56181,"longitude":68.901835,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/9988","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-badin","regionIds":["sindh"],"districtIds":["sindh-badin"],"spatialMatches":[{"regionI