insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-10013','talhar-old-bridge','published','{"id":"major-doam-10013","slug":"talhar-old-bridge","status":"published","title":"Talhar Old Bridge","shortTitle":"Talhar Old Bridge","aliases":["Talhar Old Pull/Bridge"],"summary":"The old bridge north of Talhar preserves a series of brick-and-stone arches built to carry a drainage channel. Its surviving masonry records colonial-period water infrastructure, distinct from the newer crossing nearby.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Monument","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/10013","verifiedDate":"2026-10-22","sourceTitle":"Talhar Old Pull/Bridge","sourceRegion":"Sindh","sourceDistrict":"Badin","sourcePublication":"Documentation of the Heritage Sites and Monuments of Sindh","selectionReason":"Material water-engineering heritage rather than another repeated religious monument.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-10013-point","name":"Talhar Old Bridge","latitude":24.8929,"longitude":68.82296,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/10013","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-badin","regionIds":["sindh"],"districtIds":["sindh-badin"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-badin"}],"assignmentStatus":"spatially-derived"}