insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-10023','peeru-lashari-railway-station','published','{"id":"major-doam-10023","slug":"peeru-lashari-railway-station","status":"published","title":"Peeru Lashari Railway Station","shortTitle":"Peeru Lashari Railway Station","aliases":["Peeru Lashari Railwaay Station"],"summary":"The brick railway station at Peeru Lashari is a surviving colonial-period transport building north of Badin. It records the railway infrastructure that once connected settlements across the lower Indus plain.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Monument","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/10023","verifiedDate":"2026-10-22","sourceTitle":"Peeru Lashari Railwaay Station","sourceRegion":"Sindh","sourceDistrict":"Badin","sourcePublication":"Documentation of the Heritage Sites and Monuments of Sindh","selectionReason":"Distinct historic transport site with a published site-specific survey coordinate.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-10023-point","name":"Peeru Lashari Railway Station","latitude":24.767648,"longitude":68.816143,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/10023","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-badin","regionIds":["sindh"],"districtIds":["sindh-badin"],"spatialMatches":[{"regionId":"sindh","d