insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-4922','johi-shiva-temple','published','{"id":"major-doam-4922","slug":"johi-shiva-temple","status":"published","title":"Johi Shiva Temple","shortTitle":"Johi Shiva Temple","aliases":["Jo-hi-Jo Qubbi at Johi"],"summary":"Johi’s former Shiva temple survives within later residential development. Its unusual historic form records the town’s Hindu architectural heritage, although the original sacred interior has been altered.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/4922","verifiedDate":"2026-10-22","sourceTitle":"Jo-hi-Jo Qubbi at Johi","sourceRegion":"Sindh","sourceDistrict":"Dadu","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Distinct built temple in Dadu; precise founding year is not asserted.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-4922-point","name":"Johi Shiva Temple","latitude":26.689358333,"longitude":67.611097222,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/4922","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-dadu","regionIds":["sindh"],"districtIds":["sindh-dadu"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-dadu"}],"assignmentStatus":"spatially-derived"}],"image":null,"ima