insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-10058','hairo-khan-thul','published','{"id":"major-doam-10058","slug":"hairo-khan-thul","status":"published","title":"Hairo Khan Thul","shortTitle":"Hairo Khan Thul","aliases":[],"summary":"The thul near Hairo Khan is a brick monument associated with Buddhist archaeology. Its surviving fabric includes arched openings, a stairway and traces of a circular structure above the base.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/10058","verifiedDate":"2026-10-22","sourceTitle":"Hairo Khan Thul","sourceRegion":"Sindh","sourceDistrict":"Dadu","sourcePublication":"Documentation of the Heritage Sites and Monuments of Sindh","selectionReason":"Documented Buddhist monument; implausible catalogue height and width are deliberately excluded.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-10058-point","name":"Hairo Khan Thul","latitude":26.830115,"longitude":67.468663,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/10058","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-dadu","regionIds":["sindh"],"districtIds":["sindh-dadu"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-dadu"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"ima