insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-10076','mazar-bhurgri-thul','published','{"id":"major-doam-10076","slug":"mazar-bhurgri-thul","status":"published","title":"Mazar Bhurgri Thul","shortTitle":"Mazar Bhurgri Thul","aliases":["Thul Mazar Bhurgri"],"summary":"The Mazar Bhurgri thul preserves a raised brick mass with moulded brick fragments and pottery around it. The survey identifies the monument with Sindh’s Buddhist archaeological tradition while recording substantial erosion.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/10076","verifiedDate":"2026-10-22","sourceTitle":"Thul Mazar Bhurgri","sourceRegion":"Sindh","sourceDistrict":"Dadu","sourcePublication":"Documentation of the Heritage Sites and Monuments of Sindh","selectionReason":"Distinct surveyed thul with material evidence, separate from Hairo Khan and Mir Rukan.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-10076-point","name":"Mazar Bhurgri Thul","latitude":26.902297,"longitude":67.44935,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/10076","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-dadu","regionIds":["sindh"],"districtIds":["sindh-dadu"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-dadu"}],"assignmentStatus":"spatially-derive