insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-10083','dada-budhal-shah-complex','published','{"id":"major-doam-10083","slug":"dada-budhal-shah-complex","status":"published","title":"Dada Budhal Shah Complex","shortTitle":"Dada Budhal Shah Complex","aliases":[],"summary":"At Borirri, the Dada Budhal Shah complex brings together a brick mausoleum, a mosque and a burial enclosure. Its architectural forms recall Kalhora and Talpur traditions, but the survey does not establish a firm historical date.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Tomb / Funerary Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/10083","verifiedDate":"2026-10-22","sourceTitle":"Dada Budhal Shah Complex","sourceRegion":"Sindh","sourceDistrict":"Dadu","sourcePublication":"Documentation of the Heritage Sites and Monuments of Sindh","selectionReason":"Named funerary ensemble, with uncertainty about chronology made explicit.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-10083-point","name":"Dada Budhal Shah Complex","latitude":27.003934,"longitude":67.767727,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/10083","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-dadu","regionIds":["sindh"],"districtIds":["sindh-dadu"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-dadu"}],"assignmentStatus":"sp