insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6593','jamia-masjid-al-farooque-rati','published','{"id":"major-doam-6593","slug":"jamia-masjid-al-farooque-rati","status":"published","title":"Jamia Masjid Al Farooque, Rati","shortTitle":"Jamia Masjid Al Farooque, Rati","aliases":["Jamia Masjid Al Farooque I"],"summary":"This mosque at Rati has a square prayer hall, a domed roof and corner minarets. Brick construction, lime plaster and a glazed finial contribute to its distinctive historic architectural form.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6593","verifiedDate":"2026-10-22","sourceTitle":"Jamia Masjid Al Farooque I","sourceRegion":"Sindh","sourceDistrict":"Ghotki","sourcePublication":"Survey and Documentation of Archaeological Sites and Monuments (1995-2001)","selectionReason":"Specific architectural record in Ghotki, not a generic village point or duplicate Al Farooque II.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-6593-point","name":"Jamia Masjid Al Farooque, Rati","latitude":28.073055556,"longitude":69.786666667,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6593","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-ghotki","regionIds":["sindh"],"districtIds":["sindh-ghotki"],"spatialMatches":[{"regionId"