insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6803','loi-saiban-jamia-mosque','published','{"id":"major-doam-6803","slug":"loi-saiban-jamia-mosque","status":"published","title":"Loi Saiban Jamia Mosque","shortTitle":"Loi Saiban Jamia Mosque","aliases":["Loi Saiban Jamia Mosque of Ghotki"],"summary":"Loi Saiban mosque in Ghotki has a five-part prayer hall covered by five domes. Its arched entrances, ventilators and lotus-shaped finials preserve a carefully articulated historic facade and roofline.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6803","verifiedDate":"2026-10-22","sourceTitle":"Loi Saiban Jamia Mosque of Ghotki","sourceRegion":"Sindh","sourceDistrict":"Ghotki","sourcePublication":"Survey and Documentation of Archaeological Sites and Monuments (1995-2001)","selectionReason":"Substantial named urban mosque with clearly documented form.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-6803-point","name":"Loi Saiban Jamia Mosque","latitude":28.000833333,"longitude":69.322777778,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6803","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-ghotki","regionIds":["sindh"],"districtIds":["sindh-ghotki"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-ghotki"}],"assignm