insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6804','jamia-mosque-khanpur-khan-garh','published','{"id":"major-doam-6804","slug":"jamia-mosque-khanpur-khan-garh","status":"published","title":"Jamia Mosque, Khanpur Khan Garh","shortTitle":"Jamia Mosque, Khanpur Khan Garh","aliases":["Jamia Mosque of Khanpur Khan Garh"],"summary":"The mosque at Khanpur Khan Garh combines a brick prayer hall with timber roof supports and a courtyard. Painted floral and geometric ornament, inscriptions and carved wooden elements distinguish its interior.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6804","verifiedDate":"2026-10-22","sourceTitle":"Jamia Mosque of Khanpur Khan Garh","sourceRegion":"Sindh","sourceDistrict":"Ghotki","sourcePublication":"Survey and Documentation of Archaeological Sites and Monuments (1995-2001)","selectionReason":"Distinct architectural use of timber and painting, complementing rather than repeating Ghotki domed masonry sites.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-6804-point","name":"Jamia Mosque, Khanpur Khan Garh","latitude":27.866666667,"longitude":69.431111111,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6804","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-ghotki","regionIds":["sindh"],"distri