insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5675','katcha-qila-hyderabad','published','{"id":"major-doam-5675","slug":"katcha-qila-hyderabad","status":"published","title":"Katcha Qila, Hyderabad","shortTitle":"Katcha Qila, Hyderabad","aliases":["Katcha Qila"],"summary":"Hyderabad’s Katcha Qila is a Kalhora-period fort built with earthen walls over a brick foundation. Bastions and a substantial enclosure surround a precinct containing sacred monuments.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Fortification","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5675","verifiedDate":"2026-10-22","sourceTitle":"Katcha Qila","sourceRegion":"Sindh","sourceDistrict":"Hyderabad","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Separate fortification from existing Pucca Qila; shrine components remain grouped within the enclosure.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-5675-point","name":"Katcha Qila, Hyderabad","latitude":25.378969444,"longitude":68.363475,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5675","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-hyderabad","regionIds":["sindh"],"districtIds":["sindh-hyderabad"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-hyderabad"}],"assignmentStatus":"spatiall