insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5708','navel-rai-market-clock-tower','published','{"id":"major-doam-5708","slug":"navel-rai-market-clock-tower","status":"published","title":"Navel Rai Market Clock Tower","shortTitle":"Navel Rai Market Clock Tower","aliases":["Navel Rai Market Clock Tower Market Area"],"summary":"The clock tower at Navel Rai Market is a brick civic landmark of colonial Hyderabad. Its integration with the market illustrates how public timekeeping and commercial architecture shared an urban setting.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Urban Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5708","verifiedDate":"2026-10-22","sourceTitle":"Navel Rai Market Clock Tower Market Area","sourceRegion":"Sindh","sourceDistrict":"Hyderabad","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Distinct market and civic-clock ensemble, not separate tower and market pins.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-5708-point","name":"Navel Rai Market Clock Tower","latitude":25.399802778,"longitude":68.369019444,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5708","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-hyderabad","regionIds":["sindh"],"districtIds":["sindh-hyderabad"],"s