insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5726','training-college-for-men-hyderabad','published','{"id":"major-doam-5726","slug":"training-college-for-men-hyderabad","status":"published","title":"Training College for Men, Hyderabad","shortTitle":"Training College for Men, Hyderabad","aliases":["Training College for Men Tilak Incline"],"summary":"This historic teacher-training college is a two-storey brick building with broad corridors, arched windows and large halls. Its architecture represents the development of educational institutions in nineteenth-century Hyderabad.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Urban Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5726","verifiedDate":"2026-10-22","sourceTitle":"Training College for Men Tilak Incline","sourceRegion":"Sindh","sourceDistrict":"Hyderabad","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Historic educational building with described fabric; not a modern campus umbrella.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-5726-point","name":"Training College for Men, Hyderabad","latitude":25.389058333,"longitude":68.368155556,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5726","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-hyderabad",