insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5729','talpur-palace-hyderabad','published','{"id":"major-doam-5729","slug":"talpur-palace-hyderabad","status":"published","title":"Talpur Palace, Hyderabad","shortTitle":"Talpur Palace, Hyderabad","aliases":["Talpur`s Palace"],"summary":"The Talpur palace in Hyderabad combines a large residence with attached buildings and verandas. A tall central hall, brick masonry and timber roof elements define the surviving domestic complex.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Urban Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5729","verifiedDate":"2026-10-22","sourceTitle":"Talpur`s Palace","sourceRegion":"Sindh","sourceDistrict":"Hyderabad","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Separate palace from Khairpur and Kot Diji ensembles; one record for connected buildings.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-5729-point","name":"Talpur Palace, Hyderabad","latitude":25.369463889,"longitude":68.337394444,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5729","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-hyderabad","regionIds":["sindh"],"districtIds":["sindh-hyderabad"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-hyderabad"}],"