insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6828','kot-mirpur-buro','published','{"id":"major-doam-6828","slug":"kot-mirpur-buro","status":"published","title":"Kot Mirpur Buro","shortTitle":"Kot Mirpur Buro","aliases":[],"summary":"Kot Mirpur Buro preserves parts of a square Talpur-period fort. Surviving bastions and earthen construction retain evidence of an enclosure originally articulated by towers at its corners and along its walls.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Fortification","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6828","verifiedDate":"2026-10-22","sourceTitle":"Kot Mirpur Buro","sourceRegion":"Sindh","sourceDistrict":"Jacobabad","sourcePublication":"Survey and Documentation of Archaeological Sites and Monuments (1995-2001)","selectionReason":"Distinct Jacobabad fort beyond prior civic tower and colonial burial record.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-6828-point","name":"Kot Mirpur Buro","latitude":28.175,"longitude":68.713888889,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6828","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-jacobabad","regionIds":["sindh"],"districtIds":["sindh-jacobabad"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-jacobabad"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","plac