insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6842','udi-sharif-mosque','published','{"id":"major-doam-6842","slug":"udi-sharif-mosque","status":"published","title":"Udi Sharif Mosque","shortTitle":"Udi Sharif Mosque","aliases":["Udi Shareef Mosque"],"summary":"Udi Sharif mosque preserves a prayer hall with timber doors, minarets and painted ornament. Quranic and Persian inscriptions accompany geometric designs across the historic interior.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6842","verifiedDate":"2026-10-22","sourceTitle":"Udi Shareef Mosque","sourceRegion":"Sindh","sourceDistrict":"Jacobabad","sourcePublication":"Survey and Documentation of Archaeological Sites and Monuments (1995-2001)","selectionReason":"Named architectural site with material detail and exact official point.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-6842-point","name":"Udi Sharif Mosque","latitude":28.202777778,"longitude":68.8,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6842","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-jacobabad","regionIds":["sindh"],"districtIds":["sindh-jacobabad"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-jacobabad"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","pl