insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6844','bahadurpur-jamia-mosque','published','{"id":"major-doam-6844","slug":"bahadurpur-jamia-mosque","status":"published","title":"Bahadurpur Jamia Mosque","shortTitle":"Bahadurpur Jamia Mosque","aliases":["Jamia Mosque Bahadur Pur"],"summary":"Bahadurpur’s mosque combines a prayer hall, veranda and courtyard with three domes. Decorative arches, finials and painted floral and geometric patterns enrich its brick-and-plaster construction.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6844","verifiedDate":"2026-10-22","sourceTitle":"Jamia Mosque Bahadur Pur","sourceRegion":"Sindh","sourceDistrict":"Jacobabad","sourcePublication":"Survey and Documentation of Archaeological Sites and Monuments (1995-2001)","selectionReason":"Distinct large mosque ensemble; tentative dynastic attribution is omitted.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-6844-point","name":"Bahadurpur Jamia Mosque","latitude":28.316666667,"longitude":68.591666667,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6844","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-jacobabad","regionIds":["sindh"],"districtIds":["sindh-jacobabad"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-jacobabad"}],"assi