insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5167','loni-kot-remains','published','{"id":"major-doam-5167","slug":"loni-kot-remains","status":"published","title":"Loni Kot Remains","shortTitle":"Loni Kot Remains","aliases":["Remains of Kot at Loni  Kot"],"summary":"The remains at Loni Kot include thick earthen walls and exposed timber elements. The ruined enclosure records a regional construction tradition, while its precise early date remains uncertain.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Fortification","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5167","verifiedDate":"2026-10-22","sourceTitle":"Remains of Kot at Loni  Kot","sourceRegion":"Sindh","sourceDistrict":"Jamshoro","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Separate earthen fortification, not an extra component of Ranikot.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-5167-point","name":"Loni Kot Remains","latitude":25.315597222,"longitude":68.163341667,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5167","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-jamshoro","regionIds":["sindh"],"districtIds":["sindh-jamshoro"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-jamshoro"}],"assignmentStatus":"spatially-derived"}],"image":null,