insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5181','bukharia-mosque','published','{"id":"major-doam-5181","slug":"bukharia-mosque","status":"published","title":"Bukharia Mosque","shortTitle":"Bukharia Mosque","aliases":["Bukharia Mosque at Syed Murad Ali"],"summary":"The Bukharia mosque has three domes and a line of minarets above its prayer hall. A taller central entrance arch and lower side entrances give the facade a balanced composition.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5181","verifiedDate":"2026-10-22","sourceTitle":"Bukharia Mosque at Syed Murad Ali","sourceRegion":"Sindh","sourceDistrict":"Jamshoro","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Distinct early-twentieth-century sacred architecture at Sehwan.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-5181-point","name":"Bukharia Mosque","latitude":26.517936111,"longitude":67.714169444,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5181","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-jamshoro","regionIds":["sindh"],"districtIds":["sindh-jamshoro"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-jamshoro"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt