insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-9565','mian-shahal-muhammad-tomb','published','{"id":"major-doam-9565","slug":"mian-shahal-muhammad-tomb","status":"published","title":"Mian Shahal Muhammad Tomb","shortTitle":"Mian Shahal Muhammad Tomb","aliases":[],"summary":"This mausoleum in Qambar taluka is identified by the regional archaeological survey with Mian Shahal Muhammad and the Kalhora period. It forms part of the district’s documented historic funerary landscape.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Tomb / Funerary Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/9565","verifiedDate":"2026-10-22","sourceTitle":"Mian Shahal Muhammad Tomb","sourceRegion":"Sindh","sourceDistrict":"Qambar Shahdadkot","sourcePublication":"Archaeological Sites and Monuments of Larkana and Qambar Shahdad Kot Districts","selectionReason":"Named dynastic memorial distinct from the existing Ghaibi Khan graveyard.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-9565-point","name":"Mian Shahal Muhammad Tomb","latitude":27.605555556,"longitude":68.083333333,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/9565","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-kambar-shahdad-kot","regionIds":["sindh"],"districtIds":["sindh-kambar-shahdad-kot"],"spatialMatches":[{"regionId":"sindh","dist