insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6854','thul-of-touj-pull','published','{"id":"major-doam-6854","slug":"thul-of-touj-pull","status":"published","title":"Thul of Touj Pull","shortTitle":"Thul of Touj Pull","aliases":[],"summary":"The ruined thul at Touj Pull preserves brick construction, an enclosing wall and a stair on its western side. The archaeological inventory associates the rectangular structure with the Talpur period.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Monument","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6854","verifiedDate":"2026-10-22","sourceTitle":"Thul of Touj Pull","sourceRegion":"Sindh","sourceDistrict":"Jacobabad","sourcePublication":"Survey and Documentation of Archaeological Sites and Monuments (1995-2001)","selectionReason":"Distinct tower in Kashmore, separate from the existing Jamro thul.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-6854-point","name":"Thul of Touj Pull","latitude":28.383333333,"longitude":69.213888889,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6854","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-kashmore","regionIds":["sindh"],"districtIds":["sindh-kashmore"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-kashmore"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","plac