insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6933','channi-munu-mal-temple','published','{"id":"major-doam-6933","slug":"channi-munu-mal-temple","status":"published","title":"Channi Munu Mal Temple","shortTitle":"Channi Munu Mal Temple","aliases":["Temple in Channi Muu Maal"],"summary":"This temple at Channi Munu Mal joins a sanctuary hall to a canopied entrance space. Lotus ornament and a domed canopy preserve distinctive elements of historic Hindu temple architecture.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6933","verifiedDate":"2026-10-22","sourceTitle":"Temple in Channi Muu Maal","sourceRegion":"Sindh","sourceDistrict":"Naushahro Feroze","sourcePublication":"Survey and Documentation of Archaeological Sites and Monuments (1995-2001)","selectionReason":"Distinct temple complex, separate from the existing Halani shrine.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-6933-point","name":"Channi Munu Mal Temple","latitude":26.860555556,"longitude":68.268888889,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6933","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-naushahro-feroze","regionIds":["sindh"],"districtIds":["sindh-naushahro-feroze"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-naushahro-feroze"