insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6930','darya-khan-marri-temple','published','{"id":"major-doam-6930","slug":"darya-khan-marri-temple","status":"published","title":"Darya Khan Marri Temple","shortTitle":"Darya Khan Marri Temple","aliases":["Temple in Durria Khan Marri"],"summary":"The temple in Darya Khan Marri’s bazaar has a square sanctuary, a domed roof and coloured glazed tiles. Accommodation buildings around it reflect the relationship between worship and pilgrimage hospitality.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6930","verifiedDate":"2026-10-22","sourceTitle":"Temple in Durria Khan Marri","sourceRegion":"Sindh","sourceDistrict":"Naushahro Feroze","sourcePublication":"Survey and Documentation of Archaeological Sites and Monuments (1995-2001)","selectionReason":"Specific sacred ensemble; nearby Taija Bai pavilion and tower are not independently split.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-6930-point","name":"Darya Khan Marri Temple","latitude":26.682538932,"longitude":68.287299482,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6930","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-naushahro-feroze","regionIds":["sindh"],"districtIds":["sindh-naushahro-feroze"],"spatialMatches":[{"re