insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6963','kotri-kabir-jamia-mosque','published','{"id":"major-doam-6963","slug":"kotri-kabir-jamia-mosque","status":"published","title":"Kotri Kabir Jamia Mosque","shortTitle":"Kotri Kabir Jamia Mosque","aliases":["Jamia mosque Kotri Kabir"],"summary":"Kotri Kabir’s Jamia mosque is a brick structure with three eastern entrances, three domes and an open courtyard. The official inventory relates its architectural fabric to the Talpur period.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6963","verifiedDate":"2026-10-22","sourceTitle":"Jamia mosque Kotri Kabir","sourceRegion":"Sindh","sourceDistrict":"Naushahro Feroze","sourcePublication":"Survey and Documentation of Archaeological Sites and Monuments (1995-2001)","selectionReason":"Distinct named mosque; alternate Kotri Kabir mosque entry requires identity comparison before any further addition.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-6963-point","name":"Kotri Kabir Jamia Mosque","latitude":27.144722222,"longitude":68.377222222,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6963","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-naushahro-feroze","regionIds":["sindh"],"districtIds":["sindh-naushahro-feroze"],"spatialMatche