insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-7172','depar-ghanghro-stupa','published','{"id":"major-doam-7172","slug":"depar-ghanghro-stupa","status":"published","title":"Depar Ghanghro Stupa","shortTitle":"Depar Ghanghro Stupa","aliases":[],"summary":"At Depar Ghanghro near Jhol, an archaeological mound preserves the remains of a stupa built with both fired and unfired bricks. The official record identifies it with Sindh’s Buddhist-period archaeology.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/7172","verifiedDate":"2026-10-22","sourceTitle":"Depar Ghanghro Stupa","sourceRegion":"Sindh","sourceDistrict":"Sanghar","sourcePublication":"Early History of Sindh with special reference to Buddhism","selectionReason":"Distinct Buddhist site outside the existing Mansurah city ensemble.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-7172-point","name":"Depar Ghanghro Stupa","latitude":25.880555556,"longitude":68.777777778,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/7172","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-sanghar","regionIds":["sindh"],"districtIds":["sindh-sanghar"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-sanghar"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","p