insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6461','dalail-dero-fort','published','{"id":"major-doam-6461","slug":"dalail-dero-fort","status":"published","title":"Dalail Dero Fort","shortTitle":"Dalail Dero Fort","aliases":[],"summary":"Dalail Dero preserves a roughly circular fort with bastions and a projecting gateway complex. Brick and earthen construction, a pointed entrance arch and guard chambers record its defensive organisation.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Fortification","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6461","verifiedDate":"2026-10-22","sourceTitle":"Dalail Dero Fort","sourceRegion":"Sindh","sourceDistrict":"Shaheed Benazirabad","sourcePublication":"Nawab Shah: The Lost Glory","selectionReason":"Distinct fortified settlement; uncertain precise construction date omitted.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-6461-point","name":"Dalail Dero Fort","latitude":26.174444444,"longitude":68.296388889,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6461","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-shaheed-benazir-abad","regionIds":["sindh"],"districtIds":["sindh-shaheed-benazir-abad"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-shaheed-benazir-abad"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","pla