insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6566','sakhi-jam-datar-shrine','published','{"id":"major-doam-6566","slug":"sakhi-jam-datar-shrine","status":"published","title":"Sakhi Jam Datar Shrine","shortTitle":"Sakhi Jam Datar Shrine","aliases":["Sakhi Jam Datar Asgher Ali Shrine"],"summary":"The shrine at Jam Sahib contains a tall, square-plan brick mausoleum. The archaeological inventory associates the monument with the Talpur period, while its construction also shows later materials and repairs.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6566","verifiedDate":"2026-10-22","sourceTitle":"Sakhi Jam Datar Asgher Ali Shrine","sourceRegion":"Sindh","sourceDistrict":"Shaheed Benazirabad","sourcePublication":"Nawab Shah: The Lost Glory","selectionReason":"Distinct named sacred monument in Shaheed Benazir Abad.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-6566-point","name":"Sakhi Jam Datar Shrine","latitude":26.293055556,"longitude":68.502777778,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6566","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-shaheed-benazir-abad","regionIds":["sindh"],"districtIds":["sindh-shaheed-benazir-abad"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-shaheed-benazir-abad"}],"a