insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6988','merewether-pavilion-shikarpur','published','{"id":"major-doam-6988","slug":"merewether-pavilion-shikarpur","status":"published","title":"Merewether Pavilion, Shikarpur","shortTitle":"Merewether Pavilion, Shikarpur","aliases":["Mere Whether Pavillion"],"summary":"The pavilion at Shikarpur’s Shahi Bagh features timber arches, screened openings and a domed upper element. It records the historic architectural setting of the town’s public garden.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Monument","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6988","verifiedDate":"2026-10-22","sourceTitle":"Mere Whether Pavillion","sourceRegion":"Sindh","sourceDistrict":"Shikarpur","sourcePublication":"Survey and Documentation of Archaeological Sites and Monuments (1995-2001)","selectionReason":"Garden pavilion distinct from Karachi’s similarly named clock tower.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-6988-point","name":"Merewether Pavilion, Shikarpur","latitude":27.933333333,"longitude":68.644722222,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6988","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-shikarpur","regionIds":["sindh"],"districtIds":["sindh-shikarpur"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-shikar