insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6396','wazir-mansion','published','{"id":"major-doam-6396","slug":"wazir-mansion","status":"published","title":"Wazir Mansion","shortTitle":"Wazir Mansion","aliases":["Wazir Mansion (Birth Place of Quaid-i-Azam)"],"summary":"Wazir Mansion is the historic Karachi house associated with Muhammad Ali Jinnah’s birthplace. Arched openings and a continuous timber balcony distinguish the stone residence, which has undergone later structural work.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Urban Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6396","verifiedDate":"2026-10-22","sourceTitle":"Wazir Mansion (Birth Place of Quaid-i-Azam)","sourceRegion":"Sindh","sourceDistrict":"Karachi","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Nationally significant historic residence distinct from Mazar-e-Quaid.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-6396-point","name":"Wazir Mansion","latitude":24.8509,"longitude":66.997430556,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6396","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-south-karachi","regionIds":["sindh"],"districtIds":["sindh-south-karachi"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-south-