insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6073','parsi-dar-e-meher-karachi','published','{"id":"major-doam-6073","slug":"parsi-dar-e-meher-karachi","status":"published","title":"Parsi Dar-e-Meher, Karachi","shortTitle":"Parsi Dar-e-Meher, Karachi","aliases":["Parsi Dar-e-Meher"],"summary":"This two-storey stone building serves a Parsi place of worship and community gathering. Its documented fabric is part of the material heritage of Karachi’s Zoroastrian community.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6073","verifiedDate":"2026-10-22","sourceTitle":"Parsi Dar-e-Meher","sourceRegion":"Sindh","sourceDistrict":"Karachi","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Religious and community architectural diversity, not a claim of public visitor access.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-6073-point","name":"Parsi Dar-e-Meher, Karachi","latitude":24.860508333,"longitude":67.0297,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6073","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-south-karachi","regionIds":["sindh"],"districtIds":["sindh-south-karachi"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-south-karachi"}],"assignme