insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5136','sukkur-clock-tower','published','{"id":"major-doam-5136","slug":"sukkur-clock-tower","status":"published","title":"Sukkur Clock Tower","shortTitle":"Sukkur Clock Tower","aliases":["Sukkar Clock Tower"],"summary":"Sukkur’s clock tower is an octagonal brick landmark with balconies, tilework and a small dome. A winding internal stair connects the levels of this twentieth-century civic monument.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Monument","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5136","verifiedDate":"2026-10-22","sourceTitle":"Sukkar Clock Tower","sourceRegion":"Sindh","sourceDistrict":"Sukkur","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Distinct named clock tower outside the existing Mir Masum minaret ensemble.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-5136-point","name":"Sukkur Clock Tower","latitude":27.69445,"longitude":68.880822222,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5136","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-sukkur","regionIds":["sindh"],"districtIds":["sindh-sukkur"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-sukkur"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","pla