insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5101','bukkur-fort','published','{"id":"major-doam-5101","slug":"bukkur-fort","status":"published","title":"Bukkur Fort","shortTitle":"Bukkur Fort","aliases":["Bakhar Fort"],"summary":"Bukkur Fort occupies an island in the Indus between Sukkur and Rohri. Surviving perimeter walls and bastions record the island’s defensive use, amid archaeological debris from its long occupation.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Fortification","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5101","verifiedDate":"2026-10-22","sourceTitle":"Bakhar Fort","sourceRegion":"Sindh","sourceDistrict":"Sukkur","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Whole island fort, separate from the nearby bridge and sacred islands.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-5101-point","name":"Bukkur Fort","latitude":27.696536111,"longitude":68.887477778,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5101","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-sukkur","regionIds":["sindh"],"districtIds":["sindh-sukkur"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-sukkur"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"imageTemporary":fa