insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5146','kirarh-ji-mosque','published','{"id":"major-doam-5146","slug":"kirarh-ji-mosque","status":"published","title":"Kirarh Ji Mosque","shortTitle":"Kirarh Ji Mosque","aliases":["Kirarh Ji Masjid (Kiraiji Masjid)"],"summary":"Kirarh Ji mosque at Nasarpur retains a prayer hall and courtyard, with tiled octagonal drums marking its former domes. Kashi tilework and plaster ornament preserve important elements of the historic interior.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5146","verifiedDate":"2026-10-22","sourceTitle":"Kirarh Ji Masjid (Kiraiji Masjid)","sourceRegion":"Sindh","sourceDistrict":"Tando Allah Yar","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Distinct Nasarpur mosque; locally attributed chronology is not presented as proven.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-5146-point","name":"Kirarh Ji Mosque","latitude":25.515272222,"longitude":68.617197222,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5146","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-tando-allahyar","regionIds":["sindh"],"districtIds":["sindh-tando-allahyar"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-