insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-9801','mai-khairi-mosque','published','{"id":"major-doam-9801","slug":"mai-khairi-mosque","status":"published","title":"Mai Khairi Mosque","shortTitle":"Mai Khairi Mosque","aliases":["Mai Khairi-Ji-Masjid"],"summary":"Mai Khairi mosque at Nasarpur is a modest brick prayer hall with an adjoining courtyard. Its decorative tiled floor and mihrab panels preserve a characteristic use of Kashi ceramics in Sindhi sacred architecture.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/9801","verifiedDate":"2026-10-22","sourceTitle":"Mai Khairi-Ji-Masjid","sourceRegion":"Sindh","sourceDistrict":"Hyderabad","sourcePublication":"Archaeological Sites and Historical Monuments Protected Under the Antiquities Act, 1975","selectionReason":"Distinct named mosque about 900 metres from Kirarh Ji; not a duplicate of that record.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-9801-point","name":"Mai Khairi Mosque","latitude":25.522417889,"longitude":68.612598556,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/9801","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-tando-allahyar","regionIds":["sindh"],"districtIds":["sindh-tando-allahyar"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-tand