insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-10000','morio-leghari-archaeological-site','published','{"id":"major-doam-10000","slug":"morio-leghari-archaeological-site","status":"published","title":"Morio Leghari Archaeological Site","shortTitle":"Morio Leghari Archaeological Site","aliases":["Morio Leghari"],"summary":"Morio Leghari is a low settlement mound with scattered pottery and traces of structures. The survey identifies the recorded material with the Islamic period, while noting damage to the surviving archaeological surface.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/10000","verifiedDate":"2026-10-22","sourceTitle":"Morio Leghari","sourceRegion":"Sindh","sourceDistrict":"Badin","sourcePublication":"Documentation of the Heritage Sites and Monuments of Sindh","selectionReason":"A site-specific recent survey point in the configured Tando Muhammad Khan polygon, not a relocated stupa or district centroid.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-10000-point","name":"Morio Leghari Archaeological Site","latitude":24.831311,"longitude":68.721339,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/10000","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-tando-muhammad-khan","regionIds":["sindh"],"districtIds":