insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5508','akbar-birthplace-memorial','published','{"id":"major-doam-5508","slug":"akbar-birthplace-memorial","status":"published","title":"Akbar Birthplace Memorial","shortTitle":"Akbar Birthplace Memorial","aliases":["Memorial of Birth Place of Akbar"],"summary":"This pavilion at Umerkot commemorates the birthplace of the Mughal emperor Akbar. The memorial itself is a later structure, distinct from the sixteenth-century event with which the site is associated.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Monument","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5508","verifiedDate":"2026-10-22","sourceTitle":"Memorial of Birth Place of Akbar","sourceRegion":"Sindh","sourceDistrict":"Umerkot","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Distinct memorial outside the existing Umerkot fort and Shiv temple.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-5508-point","name":"Akbar Birthplace Memorial","latitude":25.376841667,"longitude":69.732511111,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5508","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-umer-kot","regionIds":["sindh"],"districtIds":["sindh-umer-kot"],"spatialMatches":[{"regionId":"sindh","districtId":"sind