insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5623','dabgir-mosque','published','{"id":"major-doam-5623","slug":"dabgir-mosque","status":"published","title":"Dabgir Mosque","shortTitle":"Dabgir Mosque","aliases":[],"summary":"Dabgir mosque in Thatta preserves a three-bay brick prayer hall with a larger central dome. Surviving coloured tilework and a finely carved stone mihrab distinguish its historic architectural fabric.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5623","verifiedDate":"2026-10-22","sourceTitle":"Dabgir Mosque","sourceRegion":"Sindh","sourceDistrict":"Thatta","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Separate urban mosque outside the Makli necropolis and Shah Jahan Mosque property.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-5623-point","name":"Dabgir Mosque","latitude":24.738802778,"longitude":67.930941667,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5623","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-thatta","regionIds":["sindh"],"districtIds":["sindh-thatta"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-thatta"}],"assignmentStatus":"spatially-derived"}],"image":null,"imageAlt":"","placeholderImage":true,"im