insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5626','nawab-amir-khan-mosque','published','{"id":"major-doam-5626","slug":"nawab-amir-khan-mosque","status":"published","title":"Nawab Amir Khan Mosque","shortTitle":"Nawab Amir Khan Mosque","aliases":["Nawab Amir Khan`s Mosque"],"summary":"Nawab Amir Khan mosque is a small, square-plan brick structure in Thatta with a domed prayer chamber. Its documented Mughal-period form survives in a different location from the Shah Jahan Mosque.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5626","verifiedDate":"2026-10-22","sourceTitle":"Nawab Amir Khan`s Mosque","sourceRegion":"Sindh","sourceDistrict":"Thatta","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Distinct official inventory site; no splitting of the Shah Jahan ensemble.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-5626-point","name":"Nawab Amir Khan Mosque","latitude":24.747808333,"longitude":67.926744444,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5626","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-thatta","regionIds":["sindh"],"districtIds":["sindh-thatta"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-thatta"}],"assignmentStatus":"spat