insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5616','pir-patho-mosque-and-tower','published','{"id":"major-doam-5616","slug":"pir-patho-mosque-and-tower","status":"published","title":"Pir Patho Mosque and Tower","shortTitle":"Pir Patho Mosque and Tower","aliases":["Muhammad Bin Qasim Mosque at Pir Patho","Pir Patho Tower"],"summary":"The historic mosque at Pir Patho has connected domed halls and arched openings. A nearby brick tower forms part of the same monument group; its original function and precise date remain uncertain.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5616","verifiedDate":"2026-10-22","sourceTitle":"Muhammad Bin Qasim Mosque at Pir Patho","sourceRegion":"Sindh","sourceDistrict":"Thatta","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Grouped mosque and tower, combining DOAM 5616 and 5618 without repeating legendary attribution to Muhammad bin Qasim.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-5616-point","name":"Pir Patho Mosque and Tower","latitude":24.554952778,"longitude":67.884297222,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5616","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-thatta","regionIds":["sindh"],"districtIds":