insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5517','kot-raja-manjera-gujjo','published','{"id":"major-doam-5517","slug":"kot-raja-manjera-gujjo","status":"published","title":"Kot Raja Manjera, Gujjo","shortTitle":"Kot Raja Manjera, Gujjo","aliases":["Kafir Kot Gujjo"],"summary":"The archaeological site at Gujjo has yielded pottery and stone-working material attributed to more than one period. Published surveys discuss both prehistoric settlement and later Buddhist remains within the same site.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5517","verifiedDate":"2026-10-22","sourceTitle":"Kafir Kot Gujjo","sourceRegion":"Sindh","sourceDistrict":"Thatta","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"One multi-period archaeological place, not separate prehistoric and stupa records.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-5517-point","name":"Kot Raja Manjera, Gujjo","latitude":24.729111111,"longitude":67.751786111,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5517","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-thatta","regionIds":["sindh"],"districtIds":["sindh-thatta"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-thatta"}],"assi