insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-5604','jam-bijar-fort','published','{"id":"major-doam-5604","slug":"jam-bijar-fort","status":"published","title":"Jam Bijar Fort","shortTitle":"Jam Bijar Fort","aliases":["Jam Bijar Fort Mirpur Sakro"],"summary":"The Jam Bijar site near Mirpur Sakro consists of a raised, irregular platform with stone-faced retaining walls and bastions. A smaller platform within the enclosure is traditionally associated with an open court.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Fortification","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/5604","verifiedDate":"2026-10-22","sourceTitle":"Jam Bijar Fort Mirpur Sakro","sourceRegion":"Sindh","sourceDistrict":"Thatta","sourcePublication":"Inventory of Cultural Property in the Province of Sindh, Pakistan, 2015","selectionReason":"Distinct surveyed fortification platform, not a constituent of Banbhore.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-5604-point","name":"Jam Bijar Fort","latitude":24.771505556,"longitude":67.680483333,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/5604","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"sindh","districtId":"sindh-thatta","regionIds":["sindh"],"districtIds":["sindh-thatta"],"spatialMatches":[{"regionId":"sindh","districtId":"sindh-thatta"}],"assignmentStatus":"spatially-derived"}],"imag