insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-3561','ade-sahib-mosque-mujahideen','published','{"id":"major-doam-3561","slug":"ade-sahib-mosque-mujahideen","status":"published","title":"Ade Sahib Mosque, Mujahideen","shortTitle":"Ade Sahib Mosque, Mujahideen","summary":"A stone-and-mud mosque with two halls and a substantial timber-pillared roof illustrates the region''s wooden religious architecture.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Heritage place","legalStatus":"Not Protected","legalStatusNote":"As recorded in the cited DOAM catalogue; not an independent review of current legislation.","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/3561","verifiedDate":"2026-10-22","sourceTitle":"Ade Sahib Mosque (Mujahideen)","sourceRegion":"Khyber Pakhtunkhwa","sourceDistrict":"Bajaur Agency","sourcePublication":"The Archaeological Explorations in Bajaur Agency","selectionReason":"Distinct documented sacred heritage with a substantive inventory description and a source point passing coordinate, duplicate and location screens; expands listed discovery without adding default-map prominence.","components":[{"id":"major-doam-3561-point","name":"Ade Sahib Mosque, Mujahideen","latitude":34.726903178,"longitude":71.238801816,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/3561","coordinateNote":"DOAM public catalogue site point transcribed unchanged on 2026-10-22; raw DMS screened for valid ranges and non-whole-minute precision. Protected geometry yields khyber-pakhtunkhwa-bajaur.","regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtunkhwa-bajaur","regionIds":["khyber-pakhtunkhwa"],"districtIds":["khyber-pakhtunkhwa-bajaur"],"spatialMatches":[{"regionId":"khyber-pakhtunkhwa","districtId":"khyber-pakhtu