insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-9660','samungli-mound-no-2','published','{"id":"major-doam-9660","slug":"samungli-mound-no-2","status":"published","title":"Samungli Mound No. 2","shortTitle":"Samungli Mound No. 2","summary":"A low archaeological mound at Samungli preserves part of the Quetta valley’s settlement record. The federal inventory describes surviving pottery and a mound near the village, distinguishing it from the valley’s other numbered archaeological sites.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Heritage site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/9660","sourceTitle":"Mound No. 2 village Samungli west side of Airport).","sourceRegion":"Balochistan","sourceDistrict":"Quetta","sourcePublication":"Archaeological Sites and Historical Monuments Protected Under the Antiquities Act, 1975","verifiedDate":"2026-10-22","sourceNote":"Official catalogue identity and published point reviewed. Historical district attribution is retained as source metadata; current map context is derived from unchanged runtime boundaries. Access and visitor facilities have not been confirmed.","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"Attributed catalogue statement; not an independent assessment of current legal protection.","components":[{"id":"major-doam-9660-point","name":"Samungli Mound No. 2","latitude":30.220253396,"longitude":66.974553143,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/9660","coordinateNote":"Exact decimal coordinate from the official catalogue; DMS consistency checked. This is source verification, not a field survey.","regionId":"balochistan","districtId":"balochistan-quetta","regionIds":["balochistan"],"districtI