insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-9661','killi-gul-muhammad-mound-no-1','published','{"id":"major-doam-9661","slug":"killi-gul-muhammad-mound-no-1","status":"published","title":"Killi Gul Muhammad Mound No. 1","shortTitle":"Killi Gul Muhammad Mound No. 1","summary":"The mound catalogued near Killi Gul Muhammad preserves pottery-bearing archaeological deposits beneath and beside a later graveyard. It belongs to the Quetta valley’s early settlement landscape. Conflicting chronological statements in the inventory require specialist review before assigning a precise date.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Heritage site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/9661","sourceTitle":"Mound No. 1 near village Killi Gul Muhammad","sourceRegion":"Balochistan","sourceDistrict":"Quetta","sourcePublication":"Archaeological Sites and Historical Monuments Protected Under the Antiquities Act, 1975","verifiedDate":"2026-10-22","sourceNote":"Official catalogue identity and published point reviewed. Historical district attribution is retained as source metadata; current map context is derived from unchanged runtime boundaries. Access and visitor facilities have not been confirmed.","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"Attributed catalogue statement; not an independent assessment of current legal protection.","components":[{"id":"major-doam-9661-point","name":"Killi Gul Muhammad Mound No. 1","latitude":30.244482311,"longitude":66.980517898,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/9661","coordinateNote":"Exact decimal coordinate from the official catalogue; DMS consistency checked. This is source verification, not a field surve