insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-9669','sheikh-manda-mound-no-10','published','{"id":"major-doam-9669","slug":"sheikh-manda-mound-no-10","status":"published","title":"Sheikh Manda Mound No. 10","shortTitle":"Sheikh Manda Mound No. 10","summary":"An archaeological mound near Sheikh Manda lies within the Quetta valley’s network of early settlements. The federal inventory records surviving structural traces and pottery, giving the site value beyond its modest appearance in the modern landscape.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Heritage site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/9669","sourceTitle":"Mound No. 10 (Village Shbaikh Manda)","sourceRegion":"Balochistan","sourceDistrict":"Quetta","sourcePublication":"Archaeological Sites and Historical Monuments Protected Under the Antiquities Act, 1975","verifiedDate":"2026-10-22","sourceNote":"Official catalogue identity and published point reviewed. Historical district attribution is retained as source metadata; current map context is derived from unchanged runtime boundaries. Access and visitor facilities have not been confirmed.","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"Attributed catalogue statement; not an independent assessment of current legal protection.","components":[{"id":"major-doam-9669-point","name":"Sheikh Manda Mound No. 10","latitude":30.229175028,"longitude":66.951182361,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/9669","coordinateNote":"Exact decimal coordinate from the official catalogue; DMS consistency checked. This is source verification, not a field survey.","regionId":"balochistan","districtId":"balochistan-quetta","regionIds":["balochistan"