insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-9664','kuchlak-mound-no-7','published','{"id":"major-doam-9664","slug":"kuchlak-mound-no-7","status":"published","title":"Kuchlak Mound No. 7","shortTitle":"Kuchlak Mound No. 7","summary":"A settlement mound at Kuchlak is documented beside the historic Quetta–Chaman corridor. Its raised archaeological deposits and recorded pottery preserve evidence of occupation in a valley shaped by movement between upland routes.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Heritage site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/9664","sourceTitle":"Mound No.7 (Kachlak, Chaman Road)","sourceRegion":"Balochistan","sourceDistrict":"Quetta","sourcePublication":"Archaeological Sites and Historical Monuments Protected Under the Antiquities Act, 1975","verifiedDate":"2026-10-22","sourceNote":"Official catalogue identity and published point reviewed. Historical district attribution is retained as source metadata; current map context is derived from unchanged runtime boundaries. Access and visitor facilities have not been confirmed.","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"Attributed catalogue statement; not an independent assessment of current legal protection.","components":[{"id":"major-doam-9664-point","name":"Kuchlak Mound No. 7","latitude":30.355755415,"longitude":66.969895113,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/9664","coordinateNote":"Exact decimal coordinate from the official catalogue; DMS consistency checked. This is source verification, not a field survey.","regionId":"balochistan","districtId":"balochistan-quetta","regionIds":["balochistan"],"districtIds":["balochistan-quetta"],"spatialMatches