insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-9670','nauhisar-mound-no-11','published','{"id":"major-doam-9670","slug":"nauhisar-mound-no-11","status":"published","title":"Nauhisar Mound No. 11","shortTitle":"Nauhisar Mound No. 11","summary":"A small archaeological mound near Nauhisar preserves pottery-bearing deposits within the Quetta valley. The officially recorded site contributes to the regional settlement inventory without implying that its occupation sequence has been fully established.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Heritage site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/9670","sourceTitle":"Mound No. 11 (Village Nauhisar)","sourceRegion":"Balochistan","sourceDistrict":"Quetta","sourcePublication":"Archaeological Sites and Historical Monuments Protected Under the Antiquities Act, 1975","verifiedDate":"2026-10-22","sourceNote":"Official catalogue identity and published point reviewed. Historical district attribution is retained as source metadata; current map context is derived from unchanged runtime boundaries. Access and visitor facilities have not been confirmed.","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"Attributed catalogue statement; not an independent assessment of current legal protection.","components":[{"id":"major-doam-9670-point","name":"Nauhisar Mound No. 11","latitude":30.259261834,"longitude":66.887716931,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/9670","coordinateNote":"Exact decimal coordinate from the official catalogue; DMS consistency checked. This is source verification, not a field survey.","regionId":"balochistan","districtId":"balochistan-quetta","regionIds":["balochistan"],"districtIds":["ba