insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-9658','harian-haider-zai-mound','published','{"id":"major-doam-9658","slug":"harian-haider-zai-mound","status":"published","title":"Harian Haider Zai Mound","shortTitle":"Harian Haider Zai Mound","summary":"A broad prehistoric mound near Harian Haider Zai contains evidence of settlement recorded through pottery and stone tools. The inventory connects this landscape with archaeological investigations around Loralai; the mound is retained as a distinct surveyed location.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Heritage site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/9658","sourceTitle":"Pre-historic Mound (Near Harian Haider Zai)","sourceRegion":"Balochistan","sourceDistrict":"Loralai","sourcePublication":"Archaeological Sites and Historical Monuments Protected Under the Antiquities Act, 1975","verifiedDate":"2026-10-22","sourceNote":"Official catalogue identity and published point reviewed. Historical district attribution is retained as source metadata; current map context is derived from unchanged runtime boundaries. Access and visitor facilities have not been confirmed.","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"Attributed catalogue statement; not an independent assessment of current legal protection.","components":[{"id":"major-doam-9658-point","name":"Harian Haider Zai Mound","latitude":30.380310116,"longitude":68.526873581,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/9658","coordinateNote":"Exact decimal coordinate from the official catalogue; DMS consistency checked. This is source verification, not a field survey.","regionId":"balochistan","districtId":"balochistan-loralai","regionId