insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-9663','shahi-khan-mound-no-6','published','{"id":"major-doam-9663","slug":"shahi-khan-mound-no-6","status":"published","title":"Shahi Khan Mound No. 6","shortTitle":"Shahi Khan Mound No. 6","summary":"The archaeological mound near Shahi Khan and Pir Ballo preserves pottery-bearing settlement deposits along the Sariab corridor. Later graves form part of its recorded surface, showing how an older settlement location acquired subsequent uses.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Heritage site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/9663","sourceTitle":"Mound No. 6 (Shahi Khan near Pir Ballo).","sourceRegion":"Balochistan","sourceDistrict":"Quetta","sourcePublication":"Archaeological Sites and Historical Monuments Protected Under the Antiquities Act, 1975","verifiedDate":"2026-10-22","sourceNote":"Official catalogue identity and published point reviewed. Historical district attribution is retained as source metadata; current map context is derived from unchanged runtime boundaries. Access and visitor facilities have not been confirmed.","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"Attributed catalogue statement; not an independent assessment of current legal protection.","components":[{"id":"major-doam-9663-point","name":"Shahi Khan Mound No. 6","latitude":30.172891173,"longitude":66.991809839,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/9663","coordinateNote":"Exact decimal coordinate from the official catalogue; DMS consistency checked. This is source verification, not a field survey.","regionId":"balochistan","districtId":"balochistan-quetta","regionIds":["balochistan"],"districtIds":["b