insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-9666','samali-mound-no-8','published','{"id":"major-doam-9666","slug":"samali-mound-no-8","status":"published","title":"Samali Mound No. 8","shortTitle":"Samali Mound No. 8","summary":"A prominent mound at Samali forms part of the officially catalogued archaeological landscape north of Quetta. Its rounded profile and surviving deposits offer a tangible location for studying the valley’s settlement history.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Heritage site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/9666","sourceTitle":"Mound No. 8 (Village Samali)","sourceRegion":"Balochistan","sourceDistrict":"Quetta","sourcePublication":"Archaeological Sites and Historical Monuments Protected Under the Antiquities Act, 1975","verifiedDate":"2026-10-22","sourceNote":"Official catalogue identity and published point reviewed. Historical district attribution is retained as source metadata; current map context is derived from unchanged runtime boundaries. Access and visitor facilities have not been confirmed.","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"Attributed catalogue statement; not an independent assessment of current legal protection.","components":[{"id":"major-doam-9666-point","name":"Samali Mound No. 8","latitude":30.320934271,"longitude":66.934174645,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/9666","coordinateNote":"Exact decimal coordinate from the official catalogue; DMS consistency checked. This is source verification, not a field survey.","regionId":"balochistan","districtId":"balochistan-quetta","regionIds":["balochistan"],"districtIds":["balochistan-quetta"],"spatialMatches":[{"regionId":