insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-9667','mehtar-zai-mound-no-9','published','{"id":"major-doam-9667","slug":"mehtar-zai-mound-no-9","status":"published","title":"Mehtar Zai Mound No. 9","shortTitle":"Mehtar Zai Mound No. 9","summary":"An archaeological mound at Mehtar Zai preserves evidence of an earlier settlement beneath later uses of the site. The federal description records its incorporation into a military redoubt, illustrating the reuse of raised archaeological ground.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Heritage site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/9667","sourceTitle":"Mound No. 9 (Village Mehtar Zai)","sourceRegion":"Balochistan","sourceDistrict":"Quetta","sourcePublication":"Archaeological Sites and Historical Monuments Protected Under the Antiquities Act, 1975","verifiedDate":"2026-10-22","sourceNote":"Official catalogue identity and published point reviewed. Historical district attribution is retained as source metadata; current map context is derived from unchanged runtime boundaries. Access and visitor facilities have not been confirmed.","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"Attributed catalogue statement; not an independent assessment of current legal protection.","components":[{"id":"major-doam-9667-point","name":"Mehtar Zai Mound No. 9","latitude":30.326395493,"longitude":67.106514491,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/9667","coordinateNote":"Exact decimal coordinate from the official catalogue; DMS consistency checked. This is source verification, not a field survey.","regionId":"balochistan","districtId":"balochistan-quetta","regionIds":["balochistan"],"districtIds":["balochi