insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-9681','ibn-e-haroon-tomb-bela','published','{"id":"major-doam-9681","slug":"ibn-e-haroon-tomb-bela","status":"published","title":"Ibn-e-Haroon Tomb, Bela","shortTitle":"Ibn-e-Haroon Tomb, Bela","summary":"A substantial square brick tomb stands on Bela’s outskirts. Catalogued under the name Ibn-e-Haroon, the structure represents the town’s historic funerary architecture. The record identifies the monument without treating uncertain personal associations as established biography.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Heritage site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/9681","sourceTitle":"Ibn-e-Haroon`s Tomb at Bela","sourceRegion":"Balochistan","sourceDistrict":"Las Bela","sourcePublication":"Archaeological Sites and Historical Monuments Protected Under the Antiquities Act, 1975","verifiedDate":"2026-10-22","sourceNote":"Official catalogue identity and published point reviewed. Historical district attribution is retained as source metadata; current map context is derived from unchanged runtime boundaries. Access and visitor facilities have not been confirmed.","legalStatus":"Protected by The Antiquity Act 1975 (As amended in 1992)","legalStatusNote":"Attributed catalogue statement; not an independent assessment of current legal protection.","components":[{"id":"major-doam-9681-point","name":"Ibn-e-Haroon Tomb, Bela","latitude":26.232439723,"longitude":66.315488814,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/9681","coordinateNote":"Exact decimal coordinate from the official catalogue; DMS consistency checked. This is source verification, not a field survey.","regionId":"balochistan","districtId":"balochistan-lasbela","regionIds":["baloc