insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-10399','robert-sandeman-tomb-bela','published','{"id":"major-doam-10399","slug":"robert-sandeman-tomb-bela","status":"published","title":"Robert Sandeman Tomb, Bela","shortTitle":"Robert Sandeman Tomb, Bela","summary":"A marble funerary monument in Sandeman Park at Bela commemorates the colonial administrator Robert Sandeman. Its architectural and commemorative setting provides a material record of British-period authority in the region.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Historic Monument","designationType":"none","designationName":"Heritage site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/10399","sourceTitle":"Sir Robert Sandeman`s Tomb","sourceRegion":"Balochistan","sourceDistrict":"Las Bela","sourcePublication":"Miscellaneous","verifiedDate":"2026-10-22","sourceNote":"Official catalogue identity and published point reviewed. Historical district attribution is retained as source metadata; current map context is derived from unchanged runtime boundaries. Access and visitor facilities have not been confirmed.","legalStatus":"Not Protected","legalStatusNote":"Attributed catalogue statement; not an independent assessment of current legal protection.","components":[{"id":"major-doam-10399-point","name":"Robert Sandeman Tomb, Bela","latitude":26.223645283,"longitude":66.316863848,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/10399","coordinateNote":"Exact decimal coordinate from the official catalogue; DMS consistency checked. This is source verification, not a field survey.","regionId":"balochistan","districtId":"balochistan-lasbela","regionIds":["balochistan"],"districtIds":["balochistan-lasbela"],"spatialMatches":[{"regionId":"balochistan","districtId":"balochistan-lasbela"}],"assignmentStatus":"spa