insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-10403','zoroastrian-graveyard-quetta','published','{"id":"major-doam-10403","slug":"zoroastrian-graveyard-quetta","status":"published","title":"Zoroastrian Graveyard, Quetta","shortTitle":"Zoroastrian Graveyard, Quetta","summary":"A walled Zoroastrian graveyard in Quetta contains brick and marble funerary monuments with inscriptions in several languages. The cemetery is a surviving record of the city’s religious communities and their commemorative traditions.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Heritage site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/10403","sourceTitle":"Zoroastrians Graveyard Quetta","sourceRegion":"Balochistan","sourceDistrict":"Quetta","sourcePublication":"Miscellaneous","verifiedDate":"2026-10-22","sourceNote":"Official catalogue identity and published point reviewed. Historical district attribution is retained as source metadata; current map context is derived from unchanged runtime boundaries. Access and visitor facilities have not been confirmed.","legalStatus":"Not Protected","legalStatusNote":"Attributed catalogue statement; not an independent assessment of current legal protection.","components":[{"id":"major-doam-10403-point","name":"Zoroastrian Graveyard, Quetta","latitude":30.214173983,"longitude":66.99482083,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/10403","coordinateNote":"Exact decimal coordinate from the official catalogue; DMS consistency checked. This is source verification, not a field survey.","regionId":"balochistan","districtId":"balochistan-quetta","regionIds":["balochistan"],"districtIds":["balochistan-quetta"],"spatialMatches":[{"regionId":"balochistan","districtId":"balochistan-quetta"}],"as