insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-8423','saindak-fort','published','{"id":"major-doam-8423","slug":"saindak-fort","status":"published","title":"Saindak Fort","shortTitle":"Saindak Fort","summary":"A courtyard fort near Saindak uses earthen walls strengthened with straw. The official catalogue dates its construction to 1912 and records a deteriorated condition. Its surviving fabric documents frontier infrastructure in western Balochistan.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Fortification","designationType":"none","designationName":"Heritage site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/8423","sourceTitle":"Saindak Fort","sourceRegion":"Balochistan","sourceDistrict":"Chagai","sourcePublication":"Ancient Balochistan: The Glimpses of the Glorious Cultural Heritage","verifiedDate":"2026-10-22","sourceNote":"Official catalogue identity and published point reviewed. Historical district attribution is retained as source metadata; current map context is derived from unchanged runtime boundaries. Access and visitor facilities have not been confirmed.","legalStatus":"Not Protected","legalStatusNote":"Attributed catalogue statement; not an independent assessment of current legal protection.","components":[{"id":"major-doam-8423-point","name":"Saindak Fort","latitude":29.241888132,"longitude":61.604721317,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/8423","coordinateNote":"Exact decimal coordinate from the official catalogue; DMS consistency checked. This is source verification, not a field survey.","regionId":"balochistan","districtId":"balochistan-chagai","regionIds":["balochistan"],"districtIds":["balochistan-chagai"],"spatialMatches":[{"regionId":"balochistan","districtId":"balochistan-chagai"}],"assignmentStatus":"spatially-derived"}],"m