insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-8718','bit-fortress','published','{"id":"major-doam-8718","slug":"bit-fortress","status":"published","title":"Bit Fortress","shortTitle":"Bit Fortress","summary":"The remains of a fortress occupy a terrace above Bit village near the Gish Kaur. The surveyed enclosure preserves a local defensive site within the Kech landscape; its precise construction history remains uncertain.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Fortification","designationType":"none","designationName":"Heritage site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/8718","sourceTitle":"Bit Fortress","sourceRegion":"Balochistan","sourceDistrict":"Turbat","sourcePublication":"Cartography of Ancient Settlements in Central Southern Pakistani Makran: New Data","verifiedDate":"2026-10-22","sourceNote":"Official catalogue identity and published point reviewed. Historical district attribution is retained as source metadata; current map context is derived from unchanged runtime boundaries. Access and visitor facilities have not been confirmed.","legalStatus":"Not Protected","legalStatusNote":"Attributed catalogue statement; not an independent assessment of current legal protection.","components":[{"id":"major-doam-8718-point","name":"Bit Fortress","latitude":26.107530774,"longitude":63.492713553,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/8718","coordinateNote":"Exact decimal coordinate from the official catalogue; DMS consistency checked. This is source verification, not a field survey.","regionId":"balochistan","districtId":"balochistan-kech","regionIds":["balochistan"],"districtIds":["balochistan-kech"],"spatialMatches":[{"regionId":"balochistan","districtId":"balochistan-kech"}],"assignmentStatus":"spatially-derived"}],"mapDisplay":"listed","