insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-9183','chogaanekand-fort-turbat','published','{"id":"major-doam-9183","slug":"chogaanekand-fort-turbat","status":"published","title":"Chogaanekand Fort, Turbat","shortTitle":"Chogaanekand Fort, Turbat","summary":"An earthen fort at Chogaanekand near Turbat represents the fortified compounds of historic Makran. Its recorded mud-brick construction contributes to the regional architectural inventory, although its exact foundation date is not established.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Fortification","designationType":"none","designationName":"Heritage site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/9183","sourceTitle":"Turbat Chogaanekand Fort","sourceRegion":"Balochistan","sourceDistrict":"Turbat","sourcePublication":"Forts of Balochistan (Communication)","verifiedDate":"2026-10-22","sourceNote":"Official catalogue identity and published point reviewed. Historical district attribution is retained as source metadata; current map context is derived from unchanged runtime boundaries. Access and visitor facilities have not been confirmed.","legalStatus":"Not Protected","legalStatusNote":"Attributed catalogue statement; not an independent assessment of current legal protection.","components":[{"id":"major-doam-9183-point","name":"Chogaanekand Fort, Turbat","latitude":26.016049574,"longitude":63.01424022,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/9183","coordinateNote":"Exact decimal coordinate from the official catalogue; DMS consistency checked. This is source verification, not a field survey.","regionId":"balochistan","districtId":"balochistan-kech","regionIds":["balochistan"],"districtIds":["balochistan-kech"],"spatialMatches":[{"regionId":"balochistan","districtId":"balochistan-kech"}],"assignm