insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-10400','baba-khatawara-ashram-gandhawa','published','{"id":"major-doam-10400","slug":"baba-khatawara-ashram-gandhawa","status":"published","title":"Baba Khatawara Ashram, Gandhawa","shortTitle":"Baba Khatawara Ashram, Gandhawa","summary":"A Hindu ashram in Gandhawa’s old bazaar includes a temple, assembly space and residential rooms. Surviving decorative details and the arrangement of the compound preserve evidence of the town’s historic religious and community life.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Heritage site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/10400","sourceTitle":"Baba Khatawara Ashram","sourceRegion":"Balochistan","sourceDistrict":"Jhal Magsi","sourcePublication":"Miscellaneous","verifiedDate":"2026-10-22","sourceNote":"Official catalogue identity and published point reviewed. Historical district attribution is retained as source metadata; current map context is derived from unchanged runtime boundaries. Access and visitor facilities have not been confirmed.","legalStatus":"Not Protected","legalStatusNote":"Attributed catalogue statement; not an independent assessment of current legal protection.","components":[{"id":"major-doam-10400-point","name":"Baba Khatawara Ashram, Gandhawa","latitude":28.614494,"longitude":67.483705,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/10400","coordinateNote":"Exact decimal coordinate from the official catalogue; DMS consistency checked. This is source verification, not a field survey.","regionId":"balochistan","districtId":"balochistan-jhal-magsi","regionIds":["balochistan"],"districtIds":["balochistan-jhal-magsi"],"spatialMatches":[{"regionId":"balochistan","districtId":"balochistan-jhal