insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6258','mohrian-rock-shelter','published','{"id":"major-doam-6258","slug":"mohrian-rock-shelter","status":"published","title":"Mohrian Rock Shelter","shortTitle":"Mohrian Rock Shelter","aliases":["Rock Shelter (Mohrian)"],"summary":"The rock shelter at Mohrian has an engraved bird on one supporting boulder and pottery fragments recorded nearby. The cultural markings distinguish it from an unmodified natural shelter, but their precise date remains uncertain.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Archaeological Site","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6258","verifiedDate":"2026-10-22","sourceTitle":"Rock Shelter (Mohrian)","sourceRegion":"Islamabad","sourceDistrict":"Islamabad","sourcePublication":"Archaeological Survey of Islamabad Capital Territory, 2016 Survey Data on Ancient Sites","selectionReason":"Explicit recorded cultural modification; avoids claiming an unsupported Stone Age date.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-6258-point","name":"Mohrian Rock Shelter","latitude":33.675833333,"longitude":73.194166667,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6258","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"islamabad","districtId":"islamabad-islamabad","regionIds":["islamabad"],"districtIds":["islamabad-islamabad"],"spatialMatc