insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6265','kuri-jamia-mosque','published','{"id":"major-doam-6265","slug":"kuri-jamia-mosque","status":"published","title":"Kuri Jamia Mosque","shortTitle":"Kuri Jamia Mosque","aliases":["Jamia Mosque, Kuri"],"summary":"Kuri’s historic Jamia mosque has a brick prayer hall, a veranda and courtyard. A central dome rises above the hall, while later restoration and paint have altered parts of its surface decoration.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6265","verifiedDate":"2026-10-22","sourceTitle":"Jamia Mosque, Kuri","sourceRegion":"Islamabad","sourceDistrict":"Islamabad","sourcePublication":"Survey and Documentation of Archaeological Sites and Monuments (1995-2001)","selectionReason":"Distinct mosque from the existing Kuri Baradari.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-6265-point","name":"Kuri Jamia Mosque","latitude":33.679722222,"longitude":73.180277778,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6265","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"islamabad","districtId":"islamabad-islamabad","regionIds":["islamabad"],"districtIds":["islamabad-islamabad"],"spatialMatches":[{"regionId":"islamabad","districtId":"islamabad-islamabad"}],"assignmentStatus":"spatially-derived"}],"ima