insert into public.cms_records(collection,id,slug,status,data) values('heritagePlaces','major-doam-6341','bari-imam-bethak-nikka-tumair','published','{"id":"major-doam-6341","slug":"bari-imam-bethak-nikka-tumair","status":"published","title":"Bari Imam Bethak, Nikka Tumair","shortTitle":"Bari Imam Bethak, Nikka Tumair","aliases":["Zinda Wali Bethak or Bari Imam Bethak"],"summary":"This small shrine at Nikka Tumair is traditionally identified as a resting place associated with Bari Imam. It is a separate built sacred site from the main Bari Imam shrine in Islamabad.","recordType":"place","heritageDomain":"cultural-tangible","heritageCategory":"Sacred Heritage","designationType":"none","designationName":"Heritage Site","sourceAuthority":"Department of Archaeology & Museums, Government of Pakistan","sourceUrl":"https://doam.gov.pk/public/sites/6341","verifiedDate":"2026-10-22","sourceTitle":"Zinda Wali Bethak or Bari Imam Bethak","sourceRegion":"Islamabad","sourceDistrict":"Islamabad","sourcePublication":"Archaeological Remains and Monuments of Islamabad Capital Territory and District Rawalpindi","selectionReason":"Specific secondary shrine, with traditional association clearly identified rather than treated as proven biography.","legalStatus":null,"legalStatusNote":"The catalogue legal-status value is retained in the research snapshot only; no independent claim about current statutory protection is made.","components":[{"id":"major-doam-6341-point","name":"Bari Imam Bethak, Nikka Tumair","latitude":33.711666667,"longitude":73.3275,"coordinateStatus":"verified-official","coordinateSource":"https://doam.gov.pk/public/sites/6341","coordinateNote":"Exact published DOAM coordinate checked against the live source on 2026-10-22. Valid DMS and protected ADM2 assignment checked. No centroid substitution or manual relocation. This is desk verification of an official survey point, not a field GPS survey.","regionId":"islamabad","districtId":"islamabad-islamabad","regionIds":["is